CatQuestVoicePack = CatQuestVoicePack or {}
CatQuestVoicePack.quests = {
    [2] = { d = 17.0, v = "human-male#114", n = { x = 184 }, c = { x = { { 0.00, "Могучий гиппогриф Острокоготь был убит, и коготь этой свирепой твари – свидетельство вашей победы." }, { 7.58, "Сенани Громосерд на заставе Расщеплённого Древа несомненно пожелает увидеть этот трофей – доказательство ваших деяний." } } }, t = { d = 32.5, g = 1, v = "tauren-female", n = { m = 302, f = 303 }, c = { m = { { 0.00, "Очень впечатляет... коготь Острокогтя непросто добыть! Тебе везёт в охоте!" }, { 7.24, "Острый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Дерева." }, { 16.82, "Несомненно, скоро разойдётся весть, что именно ты прикончил чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!" } }, f = { { 0.00, "Очень впечатляет... коготь Острокогтя непросто добыть! Тебе везёт в охоте!" }, { 7.24, "Острый Удар давно донимал батраков с лесозаготовок, когда они пытались добраться сюда, на заставу Расщеплённого Дерева." }, { 16.82, "Несомненно, скоро разойдётся весть, что именно ты прикончила чудовище, и множество песен в твою честь будет распеваться у костров и на лесопильнях по всему Ясеневому лесу!" } } } } },
    [5] = { d = 20.1, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Я прячусь в этом призрачном городе несколько недель и не ел ничего, кроме трав и кореньев!" }, { 6.35, "Страшно хочется нормальной еды, и я за неё хорошо заплачу. Устрой мне пир, и не пожалеешь." }, { 13.10, "Говорят, что шеф-повар Груаль в таверне \"Алый ворон\" делает превосходные тёмные пирожки с крабами..." } } }, t = { d = 4.3, v = "human-male", n = { x = 44 }, c = { x = { { 0.00, "Значит, тебе нужны пирожки с крабами? Что ж, могу испечь..." } } } } },
    [6] = { d = 23.2, g = 1, v = "human-male", n = { m = 267, f = 267 }, c = { m = { { 0.00, "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам." }, { 6.70, "Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом." }, { 12.78, "Принесёшь мне голову этого негодяя – получишь награду!" }, { 16.89, "Но будь осторожен. Гаррик собрал разбойничью шайку. До него непросто будет добраться." } }, f = { { 0.00, "Гаррик Тихокрад – головорез, который уже много недель не даёт покоя нашим крестьянам и торговцам." }, { 6.70, "Недавно его видели у лачуги возле виноградников, что к востоку от аббатства, за мостом." }, { 12.78, "Принесёшь мне голову этого негодяя – получишь награду!" }, { 16.89, "Но будь осторожна. Гаррик собрал разбойничью шайку. До него непросто будет добраться." } } }, t = { d = 6.4, g = 1, v = "human-male", n = { m = 70, f = 72 }, c = { m = { { 0.00, "Ха! Ты его прикончил! Ты оказал большую услугу Элвину и заслуживаешь хорошей награды!" } }, f = { { 0.00, "Ха! Ты его прикончила! Ты оказала большую услугу Элвину и заслуживаешь хорошей награды!" } } } } },
    [7] = { d = 16.1, v = "human-male", n = { x = 186 }, c = { x = { { 0.00, "Первое твоё задание, – это зачистка. Северные леса наводнили кобольды." }, { 5.17, "Ступай туда и уничтожь столько кобольдов-вредителей, сколько сможешь." }, { 9.99, "Сократи их число, чтобы в один прекрасный день мы смогли вытеснить их из Североземья." } } }, t = { d = 12.6, v = "human-male", n = { x = 140 }, c = { x = { { 0.00, "Славная работа. Эти кобольды – воры и трусы, но когда их много, они становятся опасны. А людям Штормграда лишняя угроза не нужна." }, { 9.24, "Примите мою благодарность за хорошую работу." } } } } },
    [8] = { d = 39.0, g = 1, v = "scourge-male#83", n = { m = 389, f = 389 }, c = { m = { { 0.00, "Эй, приятель! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками!" }, { 8.31, "У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там. Неважно, какая у неё там фамилия!" }, { 18.87, "Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире." }, { 27.24, "Ты и сам сможешь там отдохнуть, если захочешь. По крайней мере, ты должен туда заглянуть..." }, { 34.93, "ну а за доставку письма я тебе хорошенько заплачу." } }, f = { { 0.00, "Эй, подруга! Сделай одолжение для парня, который более чем достаточно бился с безмозглыми зомби и пауками!" }, { 8.27, "У меня тут есть письмецо, которое нужно доставить в Брилл... хозяйке таверны Ренни-как-её-там. Неважно, какая у неё там фамилия!" }, { 18.83, "Да и в любом случае, Брилл – это славное уютное местечко, полное жертв чумы, пытающихся как-то выжить в этом мире." }, { 27.20, "Ты и сама сможешь там отдохнуть, если захочешь. По крайней мере, ты должна туда заглянуть..." }, { 34.58, "ну а за доставку письма я тебе хорошенько заплачу." } } }, t = { d = 44.5, v = "scourge-female#80", n = { x = 355 }, c = { x = { { 0.00, "Ого! Письмо? Отличная новость! Я давно жду весточки от моей старушки-матери из Могильника. Она настоящая святая – моя мать. Как она там поживает..." }, { 14.94, "Что? Слишком фальшивлю? Не купился?" }, { 18.95, "Ну так отстань... тебе абсолютно не обязательно знать, от кого это письмо. Давай, давай, иди отсюда!" }, { 30.08, "Возвращайся, когда будет что потратить... бродяга." }, { 34.60, "И вообще, приходи сюда отдохнуть, когда устанешь от своих многодневных приключений или другой подобной глупости." } } } } },
    [9] = { d = 29.3, v = "human-male", n = { x = 328 }, c = { x = { { 0.00, "Взгляните, во что превратилось это место! Когда-то эти земли населяли честные крестьяне. Но проклятые воры выжили отсюда всех." }, { 8.71, "Только не меня! Однако угодья захватили големы – дозорные полей." }, { 13.47, "Если вы готовы поработать, я попросил бы вас пойти и убить двадцать таких големов." }, { 19.27, "Возвращайтесь за оплатой, когда всё будет сделано." }, { 22.89, "Когда расправитесь с теми, что обитают на моём поле, зачистите поля и моих соседей тоже." } } }, t = { d = 8.3, v = "human-male", n = { x = 94 }, c = { x = { { 0.00, "Отличная работа, дружище. Вы полностью отработали свою плату. Кто знает, может быть, Западный Край снова расцветёт." } } } } },
    [11] = { d = 33.3, v = "human-male", n = { x = 393 }, c = { x = { { 0.00, "На границах Элвиннского леса появились гноллы – звероподобные твари, которым попросту нечего делать в этих краях." }, { 7.78, "К югу от сторожевой башни была замечена большая группа этих существ: их слишком много, чтобы мы сумели с ними справиться." }, { 16.10, "Хуже того: на востоке, у Озера Каменных Столбов, тоже обнаружили гноллов." }, { 21.40, "Армия Штормграда будет благодарна любому, кто поможет справиться с этой угрозой." }, { 26.96, "В доказательство своей победы принеси мне раскрашенные нарукавные повязки гноллов." } } }, t = { d = 4.8, v = "human-male", n = { x = 50 }, c = { x = { { 0.00, "О, вижу, ты слов на ветер не бросаешь! Прими нашу благодарность." } } } } },
    [12] = { d = 41.6, v = "human-male", n = { x = 478 }, c = { x = { { 0.00, "У народного ополчения есть лишь одна цель: защитить земли Западного Края и вернуть в них мир." }, { 6.48, "К сожалению, приходится это делать путём кровопролития." }, { 10.61, "Один из моих разведчиков сообщил о группе звероловов из Братства Справедливости, наводящих на местных жителей ужас и панику." }, { 19.35, "У меня есть сообщения, что звероловов Братства замечали около Рудника Янго к северо-западу отсюда, а также неподалёку от фермы Мольсена и тыквенной фермы Хмуроброва." }, { 30.66, "Если ты хочешь присоединиться к ополчению, убей пятнадцать звероловов и пятнадцать контрабандистов из Братства Справедливости, а затем возвращайся ко мне." } } }, t = { d = 8.0, v = "human-male", n = { x = 93 }, c = { x = { { 0.00, "Отличная работа. Мой разведчик был свидетелем твои доблестных деяний. Пока что с тобой очень приятно иметь дело." } } } } },
    [13] = { d = 32.0, g = 1, v = "human-male", n = { m = 362, f = 363 }, c = { m = { { 0.00, "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона." }, { 8.87, "Народное ополчение не потерпит этого. Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света." }, { 17.20, "Золотой карьер находится неподалёку от побережья, к западу от башни." }, { 21.89, "В качестве следующего этапа твоего обучения я хочу, чтобы ты убил пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости." } }, f = { { 0.00, "Шайка злобных погромщиков из Братства Справедливости разбойничает близ Прииска на Золотом Берегу, Луноречья и усадьбы Алекстона." }, { 8.87, "Народное ополчение не потерпит этого. Разберись с этим немедленно, и пусть весь Западный Край узнает о силе Света." }, { 17.20, "Золотой карьер находится неподалёку от побережья, к западу от башни." }, { 21.89, "В качестве следующего этапа твоего обучения я хочу, чтобы ты убила пятнадцать погромщиков и пятнадцать мошенников из Братства Справедливости." } } }, t = { d = 6.3, v = "human-male", n = { x = 73 }, c = { x = { { 0.00, "Ваша значимость для народного ополчения была подкреплена вашими смелыми действиями." } } } } },
    [14] = { d = 24.4, v = "human-male", n = { x = 288 }, c = { x = { { 0.00, "Некоторые члены Братства Справедливости от нас ускользнули." }, { 4.13, "Один из моих разведчиков, которому я очень доверяю, сообщает, что члены этого братства грабят и разоряют деревни вплоть до Южного Западного Края." }, { 14.20, "Мы считаем, что они скрываются в Холмах Разбойничьих Кинжалов, замышляя новые бесчинства." }, { 20.49, "Убей этих негодяев от имени народного ополчения." } } }, t = { d = 22.1, v = "human-male", n = { x = 256 }, c = { x = { { 0.00, "Я покинул разорённые земли Лордерона, вернувшись на свою родину... и застал её в столь же ужасном состоянии." }, { 7.41, "Но для Западного Края ещё есть надежда. Проявленная тобой доблесть доказала, что ты с честью служишь нашему делу." }, { 15.34, "С огромной гордостью я принимаю тебя в ряды народного ополчения. Да воссияет над тобой Свет!" } } } } },
    [15] = { d = 22.7, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Мои разведчики доносят, что в эти края проникло гораздо больше кобольдов, чем мы рассчитывали." }, { 6.54, "Группа кобольдов-рабочих разбила лагерь близ Рудника Горного Эха к северу отсюда." }, { 12.61, "Отправляйся к шахте и уничтожь их. Насколько нам известно, кобольдов там много..." }, { 18.13, "Убей-ка десяток, посмотри, сколько ещё осталось, и доложи мне." } } }, t = { d = 14.0, g = 1, v = "human-male", n = { m = 158, f = 159 }, c = { m = { { 0.00, "Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведёт. Вот, это твоя награда." }, { 7.06, "Когда будешь готов, приходи ко мне. Буду рад, если ты согласишься предпринять ещё одну вылазку..." } }, f = { { 0.00, "Меня тревожат сообщения о кобольдах на нашем руднике. К добру это не приведёт. Вот, это твоя награда." }, { 7.06, "Когда будешь готова, приходи ко мне. Буду рад, если ты согласишься предпринять ещё одну вылазку..." } } } } },
    [18] = { d = 17.2, v = "human-male", n = { x = 194 }, c = { x = { { 0.00, "Тут возле Североземья недавно новая воровская шайка завелась. Зовут себя Братством Справедливости. Видели их за рекой, на востоке." }, { 9.48, "Не знаю, что у них на уме, но наверняка ничего хорошего! Принеси мне их банданы, и в награду получишь оружие." } } }, t = { d = 7.5, g = 1, v = "human-male", n = { m = 63, f = 64 }, c = { m = { { 0.00, "Ага, вижу, ты вернулся не с пустыми руками. Армия Штормграда ценит твою помощь." } }, f = { { 0.00, "Ага, вижу, ты вернулась не с пустыми руками. Армия Штормграда ценит твою помощь." } } } } },
    [19] = { d = 15.7, v = "human-male", n = { x = 182 }, c = { x = { { 0.00, "Вестники и отступники из клана Чёрной горы постоянно устраивают засады на дороге между городом и крепостью Каменной Стражи." }, { 8.63, "Их предводитель – орк по имени Тарил'зун. Он уже натворил достаточно дел. Принеси мне его голову!" } } }, t = { d = 8.7, v = "human-male", n = { x = 88 }, c = { x = { { 0.00, "Тарил'зун был жестоким и коварным орком. Ты молодчина – я знаю, справиться с ним было нелегко. Вот твоя награда." } } } } },
    [20] = { d = 34.3, v = "human-male", n = { x = 385 }, c = { x = { { 0.00, "К нам явились орки Чёрной Горы из Пылающих степей и захватили крепость Каменной стражи." }, { 6.11, "Они грабят области к северу от Озёр, и жители тех земель бежали в город, набились в него, словно сельди в бочку." }, { 14.17, "Помоги Приозерью избавиться от этой угрозы. Перебей орков Чёрной Горы и принеси в доказательство десять иззубренных топоров." }, { 23.92, "Хотя орки теснят нас с севера, до нас доходили вести об их появлении и в юго-восточной части Красногорья." }, { 31.16, "Если встретишь их – убивай без колебаний." } } }, t = { d = 4.3, v = "human-male", n = { x = 44 }, c = { x = { { 0.00, "Что ж, чем меньше орков, тем лучше. Большое тебе спасибо." } } } } },
    [21] = { d = 19.4, v = "human-male", n = { x = 226 }, c = { x = { { 0.00, "Данные твоей предыдущей разведки подтвердились – на Руднике Горного Эха необходимо провести зачистку." }, { 7.14, "Возвращайся на рудник и помоги очистить его от кобольдов." }, { 11.62, "Время дорого. Чем дольше кобольды безнаказанно пробудут в руднике, тем сильнее они закрепятся в Североземье." } } }, t = { d = 13.2, g = 1, v = "human-male", n = { m = 154, f = 155 }, c = { m = { { 0.00, "Ты снова заслужил мою похвалу и благодарность армии Штормграда." }, { 4.37, "В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения." } }, f = { { 0.00, "Ты снова заслужила мою похвалу и благодарность армии Штормграда." }, { 4.58, "В руднике ещё достаточно кобольдов, но я отправлю других новобранцев бороться с ними. Для тебя имеются другие поручения." } } } } },
    [22] = { d = 14.3, v = "human-female#47", n = { x = 155 }, c = { x = { { 0.00, "Лук очищен. Чеснок раздавлен. Розмарин измельчён. Основа выпечена. Укроп нарезан. Соус вымешан до гладкости." }, { 7.99, "Всё, что мне ещё нужно для моего знаменитого пирога – это восемь кусков печени жутеклыка!" } } }, t = { d = 14.1, g = 1, v = "human-female#47", n = { x = 159 }, c = { m = { { 0.00, "Замечательные куски! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды." }, { 8.63, "Не допускаешь же ты мысли, что герой вроде тебя останется без угощения, а?" } }, f = { { 0.00, "Замечательные куски! Большое тебе спасибо! Мы с фермером Сальденом устроим сегодня настоящий праздник. А это – для тебя, за труды." }, { 8.63, "Не допускаешь же ты мысли, что героиня вроде тебя останется без угощения, а?" } } } } },
    [23] = { d = 23.1, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Вот лапа могучего медведя Топтыжня – ваш трофей этого этапа охоты. На лапе есть маленький знак – месяц. Смысл этого знака покрыт тайной." }, { 10.74, "Эту лапу надо отнести Сенани Громовое Сердце на заставу Расщеплённого Древа, чтобы доказать, что вы одолели могучую тварь, тем самым завершив этот этап охоты." } } }, t = { d = 30.6, g = 1, v = "tauren-female", n = { x = 282 }, c = { m = { { 0.00, "О, лапа Топтыжня! Твои навыки меня впечатлили, герой. Говорят, он многих убил." }, { 7.39, "Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу." }, { 15.73, "Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях." }, { 22.95, "Убить такую тварь – истинное испытание воли и решимости. Твои предки гордились бы тобой!" } }, f = { { 0.00, "О, лапа Топтыжня! Твои навыки меня впечатлили, героиня. Говорят, он многих убил." }, { 7.57, "Месяц на его лапе ясно говорит о том, что его обучали ночные эльфы, которые рыщут по Ясеневому лесу." }, { 15.91, "Топтыжень был одним из самых могучих медведей, которых только можно сыскать в этих краях." }, { 23.13, "Убить такую тварь – истинное испытание воли и решимости. Твои предки гордились бы тобой!" } } } } },
    [24] = { d = 19.7, v = "human-male#114", n = { x = 210 }, c = { x = { { 0.00, "Некогда стремительный Тенумбра лежит у ваших ног. Вы победили." }, { 4.90, "Голова убитого ночного саблезуба – достойный трофей этой схватки в ходе охоты." }, { 10.83, "Сенани Громосерд на заставе Расщеплённого Древа захочет увидеть ваш трофей и наградить вас за этот этап охоты." } } }, t = { d = 27.8, v = "tauren-female", n = { x = 274 }, c = { x = { { 0.00, "Победа в Ашенвальской охоте! Отлично! Голова Тенумбры, вне всякого сомнения, – достойный трофей столь впечатляющей схватки." }, { 10.45, "Дикий нрав Тенумбры был хорошо известен на заставе." }, { 14.75, "Из-за этого чудовища любое путешествие от Зорамского взморья на запад, особенно пешком, было рискованным." }, { 23.53, "Благодаря тебе этой угрозы больше не существует." } } } } },
    [25] = { d = 33.4, g = 1, v = "orc-male", n = { m = 377, f = 378 }, c = { m = { { 0.00, "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?" }, { 6.81, "Сообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на всё, что только подойдёт поближе..." }, { 17.20, "то есть, на всё, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса. Ну, готов принести пользу?" } }, f = { { 0.00, "Если хочешь принести пользу, то почему бы тебе не разобраться с ситуацией у Туннеля Когтя?" }, { 6.81, "Сообщение между Ясеневым лесом и Каменным Когтем замерло из-за того, что из озера лезет всякая дрянь и нападает на всё, что только подойдёт поближе..." }, { 17.20, "то есть, на всё, что на дороге. Но куда лучше простой разборки с элементалями воды будет вот что – разведай-ка беседку на озере Мистраль – ту, с которой открывается отличный вид на соседний форт Альянса. Ну, готова принести пользу?" } } }, t = { d = 25.1, v = "orc-male", n = { x = 280 }, c = { x = { { 0.00, "Да я слышал, как что-то пролетело по озеру подобно пыльной буре Степей." }, { 5.17, "По звуку мы сможем найти пригодный наблюдательный пункт, чтобы присматривать за нашими друзьями из Альянса." }, { 12.77, "Да, только если будем сидеть тихо..." }, { 15.65, "Похоже, от тебя тут больше толку не будет – сообщение между здешними местами и Каменным Когтем налажено. Возьми вот это – заслужил." } } } } },
    [26] = { d = 30.0, g = 1, v = "nightelf-male#59", n = { m = 362, f = 362 }, c = { m = { { 0.00, "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитым защитником природы." }, { 7.20, "Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий." }, { 15.68, "Об аспекте, который даёт тебе власть над водой." }, { 18.89, "Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." } }, f = { { 0.00, "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитой защитницей природы." }, { 7.16, "Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий." }, { 15.64, "Об аспекте, который даёт тебе власть над водой." }, { 18.85, "Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." } } }, t = { d = 32.1, v = "nightelf-male#54", n = { x = 382 }, c = { x = { { 0.00, "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик." }, { 4.67, "В нём ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением..." }, { 13.78, "Но прежде чем овладеть этой способностью, её надо заслужить." }, { 18.29, "Тебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды." }, { 25.21, "Второе – испытание твоей решимости познать аспекты самого облика. Готовься – время испытания пришло." } } } } },
    [27] = { d = 43.0, g = 1, v = "tauren-male#67", n = { m = 365, f = 365 }, c = { m = { { 0.00, "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитым защитником природы." }, { 10.16, "Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий." }, { 22.02, "Об аспекте, который даёт тебе власть над водой." }, { 26.49, "Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." } }, f = { { 0.00, "Я с удовольствием наблюдал за твоими успехами. Ты непременно станешь знаменитой защитницей природы." }, { 10.17, "Пришла пора тебе узнать побольше об одном из многих аспектов животных, способность обращаться в которых даровал нам Кенарий." }, { 22.16, "Об аспекте, который даёт тебе власть над водой." }, { 26.63, "Для этого тебе следует отправиться в селение Ночная Гавань на Лунной поляне и поговорить там с Дендритом Блеском Звёзд из Круга Кенария. Он будет твоим наставником." } } }, t = { d = 32.1, v = "nightelf-male#54", n = { x = 382 }, c = { x = { { 0.00, "Мой поклон юному друиду. Пришла пора тебе познать наш водный облик." }, { 4.67, "В нём ты сможешь свободно и сколько угодно перемещаться в воде. Этот аспект будет для тебя полезным инструментом и благословением..." }, { 13.78, "Но прежде чем овладеть этой способностью, её надо заслужить." }, { 18.29, "Тебе предстоит пройти два испытания. Первое – испытание твоей способности работать под тяжестью воды." }, { 25.21, "Второе – испытание твоей решимости познать аспекты самого облика. Готовься – время испытания пришло." } } } } },
    [28] = { d = 35.4, v = "nightelf-male#54", n = { x = 423 }, c = { x = { { 0.00, "Вот твоё первое испытание – исследуй глубины озера Элуны и найди безделушку святилища." }, { 6.04, "Она быстро разрушается, так что не медля отнеси её к святилищу Ремулоса." }, { 10.96, "Используй эту безделушку в святилище, а затем поговори там с Таджарри – это одна из самых доверенных хранительниц Лунной поляны." }, { 20.02, "На всё испытание тебе даётся ограниченное количество времени, и возможно, тебе придётся соревноваться с другими друидами, которые тоже ищут безделушки." }, { 30.15, "Быстрота ума и ловкость тела помогут тебе добиться успеха. Удачи тебе." } } }, t = { d = 27.1, g = 1, v = "nightelf-female#52", n = { m = 321, f = 322 }, c = { m = { { 0.00, "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг." }, { 6.68, "Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище." }, { 14.40, "Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело." }, { 22.52, "Использовав здесь безделушку, ты отдал дань уважения этому месту." } }, f = { { 0.00, "Что же, сдаётся мне, ещё один друид успешно прошёл Испытание Озера! Хвалю тебя, мой юный друг." }, { 6.68, "Как я уже сказала, моё имя Таджарри. Мой долг и привилегия – оберегать Лунную поляны и, в особенности, это святилище." }, { 14.40, "Хранитель Ремул наставляет Круг Кенария в деле сохранения природы и равновесия, а его святилище – мощный вклад в это дело." }, { 22.52, "Использовав здесь безделушку, ты отдала дань уважения этому месту." } } } } },
