    [30] = { d = 32.3, v = "nightelf-female#52", n = { x = 403 }, c = { x = { { 0.00, "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва." }, { 5.44, "Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва." }, { 16.02, "Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика." }, { 21.37, "Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить." }, { 28.67, "Сделав это, отнеси подвеску Дендриту Блеску Звёзд." } } }, t = { d = 27.7, g = 1, v = "nightelf-male#54", n = { m = 323, f = 323 }, c = { m = { { 0.00, "Ты прошёл испытание Морского Льва. Прими мои поздравления." }, { 4.55, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 13.74, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 21.36, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } }, f = { { 0.00, "Ты прошла испытание Морского Льва. Прими мои поздравления." }, { 4.50, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 13.69, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 21.31, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } } } } },
    [31] = { d = 27.0, g = 1, v = "nightelf-male#54", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 7.34, "Теперь возвращайся к своему наставнику, Тюраку Руническому Тотэму в Громовой Утёс." }, { 13.05, "Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки." }, { 17.57, "Он завершит твоё обучение, благодаря которому ты станешь единым с водой." }, { 23.00, "Доброго тебе пути, юный друид. Мы ещё встретимся." } }, f = { { 0.00, "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 7.22, "Теперь возвращайся к своему наставнику, Тюраку Руническому Тотэму в Громовой Утёс." }, { 12.94, "Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки." }, { 17.52, "Он завершит твоё обучение, благодаря которому ты станешь единой с водой." }, { 22.84, "Доброго тебе пути, юный друид. Мы ещё встретимся." } } }, t = { d = 32.3, g = 1, v = "tauren-male#67", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Великолепно. Твои предки могут гордиться твоими успехами! Ты готов прининять водный облик, и я с радостью научу тебя этому." }, { 13.44, "Прими также эту вещицу в знак признания твоих успехов в двух испытаниях." }, { 20.63, "Надеюсь, тебе будет приятно присоединить её к своему снаряжению защитника Природы и хранителя равновесия." } }, f = { { 0.00, "Великолепно. Твои предки могут гордиться твоими успехами! Ты готова прининять водный облик, и я с радостью научу тебя этому." }, { 13.55, "Прими также эту вещицу в знак признания твоих успехов в двух испытаниях." }, { 20.74, "Надеюсь, тебе будет приятно присоединить её к своему снаряжению защитника Природы и хранителя равновесия." } } } } },
    [33] = { d = 19.4, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Ненавижу этих мерзких лесных волков! Но я бы не прочь полакомиться бифштексами из волчатины..." }, { 6.33, "Принеси мне жёсткой волчатины, и в обмен я предложу тебе что-нибудь полезное." }, { 11.93, "Убей несколько лесных волков и молодых волков, что водятся в североземских лесах, и принеси мне их мясо." } } }, t = { d = 8.9, g = 1, v = "human-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Ну, ты на славу постарался! Прямо не терпится поджарить волчатинки..." }, { 5.08, "У меня есть кое-что интересное для тебя – выбирай!" } }, f = { { 0.00, "Ну, ты на славу постаралась! Прямо не терпится поджарить волчатинки..." }, { 5.04, "У меня есть кое-что интересное для тебя – выбирай!" } } } } },
    [34] = { d = 26.8, v = "human-female#47", n = { x = 316 }, c = { x = { { 0.00, "Мой сад снова разграблен и вытоптан. И я знаю, кто это сделал! Это проклятый вепрь, которого маршал Маррис прозвал Грубобрюхом." }, { 8.78, "Теперь мне долго не удастся посадить нарциссы. Они загублены! И во всём виноват мерзкий кабан. Положи конец этому паразиту!" }, { 16.87, "Принеси мне его клык, и я с удовольствием вознагражу тебя." }, { 20.76, "Говорят, он пасётся в полях на юго-западе от Озёр, но порой заходит и сюда, в мой сад." } } }, t = { d = 8.8, g = 1, v = "human-female#47", n = { m = 107, f = 108 }, c = { m = { { 0.00, "Наконец-то моему саду ничего не грозит! Спасибо тебе, ты оказал мне большую услугу." }, { 5.51, "Теперь мой сад расцветёт с небывалой пышностью!" } }, f = { { 0.00, "Наконец-то моему саду ничего не грозит! Спасибо тебе, ты оказала мне большую услугу." }, { 5.52, "Теперь мой сад расцветёт с небывалой пышностью!" } } } } },
    [35] = { d = 17.8, v = "human-male", n = { x = 206 }, c = { x = { { 0.00, "Если ты думаешь, что слухи о мурлоках могут оказаться правдой, отправляйся к восточному мосту Элвиннского леса и поговори со стражником Томасом." }, { 10.07, "Он уже неделю несёт стражу у моста и должен знать, что там происходит на самом деле. Принеси мне его отчёт." } } }, t = { d = 12.7, v = "human-male", n = { x = 141 }, c = { x = { { 0.00, "Да, это правда: мурлоки поселились в реках и на их берегах в западной части леса." }, { 5.66, "Мы не знаем, почему они пришли сюда, но их следует остерегаться: они агрессивны и довольно умны." } } } } },
    [36] = { d = 24.4, v = "human-female", n = { x = 280 }, c = { x = { { 0.00, "Никогда я не думала, что наступит день, когда я покину ферму. Но поля кишат разбойниками, и для нас теперь тут слишком опасно." }, { 8.67, "Как только фермер Хмуробров починит повозку, мы отправимся в путь." }, { 13.57, "Может быть, ты окажешь мне услугу?" }, { 15.79, "Я напишу рецепт похлёбки Западного Края, а ты отнесёшь его Сальме Сальден вон на ту ферму – она сразу за развилкой дороги." } } }, t = { d = 17.4, v = "human-female#47", n = { x = 206 }, c = { x = { { 0.00, "Эта Верна всегда была такой милой девушкой." }, { 2.97, "Нам будет её не хватать здесь, в Западном Крае, но, только между нами, в душе она – городская жительница, и Штормград – местечко как раз для неё." }, { 12.41, "Ладно, хватит сплетничать! Начнём же готовить похлёбку Западного Края!" } } } } },
    [37] = { d = 20.3, v = "human-male", n = { x = 230 }, c = { x = { { 0.00, "Несколько дней назад мы отправили на обследование берегов реки двух наших стражей, Рольфа и Малакаи; ни один из них до сих пор не вернулся." }, { 9.63, "Чтобы составить полный отчёт, мне нужно выяснить, что с ними случилось." }, { 14.92, "Отправляйся на север вдоль реки и разыщи стражей... или хотя бы их останки." } } }, t = { d = 7.1, v = "human-male", n = { x = 82 }, c = { x = { { 0.00, "Хотя на трупе мало что осталось, рядом с ним оказался медальон с надписью \"Камень пехотинца Малакаи\"." } } } } },
    [38] = { d = 11.6, v = "human-female#47", n = { x = 129 }, c = { x = { { 0.00, "Помоги мне сварить похлёбку Западного Края! Мне нужны для неё следующие ингредиенты:" }, { 5.72, "Три куска жилистого мяса стервятника Три рыла жутеклыка Три глаза мурлока Три окры" } } }, t = { d = 16.6, v = "human-female#47", n = { x = 204 }, c = { x = { { 0.00, "Окра отлично загустит бульон! А теперь мы просто добавим жилистого мяса стервятника, несколько глаз мурлока и эти вкуснейшие рыла кровоклыка." }, { 9.55, "И вот всё готово! За оказанную помощь, я предлагаю тебе отведать первую порцию похлёбки Западного Края." } } } } },
    [39] = { d = 15.4, v = "human-male", n = { x = 171 }, c = { x = { { 0.00, "Нужно сообщить маршалу Дугхану о смерти Малакаи и Рольфа. Наши войска на востоке Элвиннского леса не смогут справиться с мурлоками." }, { 9.51, "Я знаю, лишних солдат у нас нет, но, может, Дугхан пришлёт хоть какую-то помощь..." } } }, t = { d = 15.6, v = "human-male", n = { x = 173 }, c = { x = { { 0.00, "Да, вести невесёлые... Людей у нас и так немного, а теперь, когда мурлоки прикончили Рольфа и Малакаи, будет и вовсе несладко." }, { 8.85, "Если положение не изменится к лучшему, боюсь, к концу недели бои будут идти уже в Златоземье..." } } } } },
    [40] = { d = 26.1, v = "human-male", n = { x = 299 }, c = { x = { { 0.00, "В Элвиннском лесу появилась новая напасть." }, { 2.91, "Мурлоки поднялись вверх по рекам в восточной части леса, они распугивают рыбу и нападают на мирных жителей." }, { 10.77, "Я предупреждал маршала Дугхана, но его больше беспокоит нашествие гноллов и бандитов. Мурлоков он вообще не принимает в расчёт." }, { 19.86, "Я прошу тебя, поговори с Дугханом и постарайся убедить его послать отряд на восток!" } } }, t = { d = 19.0, v = "human-male", n = { x = 213 }, c = { x = { { 0.00, "Да, верно, я говорил с Реми. Поверь, я очень высоко ценю его как торговца, но все отчёты о появлении мурлоков на востоке крайне недостоверны." }, { 10.03, "Я понимаю твою тревогу, но пока не будут получены надёжные сведения о мурлоках, никаких войск на восток я посылать не стану." } } } } },
    [45] = { d = 15.7, v = "human-male#114", n = { x = 166 }, c = { x = { { 0.00, "При осмотре местности были обнаружены запутанные следы, ведущие на восток вдоль берега Озера Каменных Столбов." }, { 8.42, "В отдалении видно поселение мурлоков." }, { 11.61, "Возможно, именно здесь и окончил свой путь Рольф..." } } }, t = { d = 5.7, v = "human-male#114", n = { x = 59 }, c = { x = { { 0.00, "На шее трупа вы находите медальон с надписью \"Пехотинец Рольф Хартфорд\"." } } } } },
    [46] = { d = 20.7, v = "human-male", n = { x = 234 }, c = { x = { { 0.00, "Армия Штормграда назначила награду за мурлоков – скрытней и добытчиков." }, { 5.35, "Убей их и принеси мне их плавники: армия хорошо за это заплатит." }, { 10.10, "Мурлоки построили селение на Озере Каменных Столбов – это к северу отсюда; ещё одно селение расположено на юге – там, где русло реки разделяется надвое." } } }, t = { d = 14.4, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Что у нас тут? Плавники? Отлично! Маршал Дугхан обеспокоен мурлоками, поселившимися на востоке леса." }, { 7.05, "Он будет рад узнать, что ситуация под контролем." }, { 10.85, "Твоя помощь в этом деле была просто неоценимой." } } } } },
    [47] = { d = 17.6, v = "human-male", n = { x = 194 }, c = { x = { { 0.00, "Кобольды в этих местах иногда носят с собой Золотую пыль. Достань мне этой пыли, и я дам за неё лучшую цену в городе! Лучшую цену в городе!" }, { 9.98, "Кобольдов можно найти на юге, на руднике Подземных глубин, или на северо-востоке, рядом с Яшмовой шахтой." } } }, t = { d = 9.8, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Благодарю за пыль. Вот твои деньги... А вот и маленький подарочек от моих друзей. Возможно, он тебе пригодится... Да, пригодится." } } } } },
    [52] = { d = 11.6, v = "human-male", n = { x = 137 }, c = { x = { { 0.00, "Приветствую. Чем дальше от Златоземья, тем агрессивнее становятся дикие звери: на Лесопилку Восточной долины постоянно нападают волки и медведи. Хочешь нам помочь?" } } }, t = { d = 11.1, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Я так тебе благодарен!.. Похоже, в этом лесу поселилось что-то, что гонит зверей прямо на нас." }, { 6.95, "Что бы там ни было, хотел бы я, чтобы оно не покидало леса..." } } } } },
    [54] = { d = 21.7, g = 1, v = "human-male", n = { x = 246 }, c = { m = { { 0.00, "Ты – герой, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса." }, { 8.97, "Если ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье." }, { 16.73, "Златоземье находится на южном тракте, за пограничными воротами." } }, f = { { 0.00, "Ты – героиня, чья верность интересам Североземья ни для кого не является тайной. Теперь тебе поручается защита Элвиннского леса." }, { 9.22, "Если ты принимаешь это поручение, то вот бумаги, которые я подготовил для отправки маршалу Дугхану в Златоземье." }, { 16.97, "Златоземье находится на южном тракте, за пограничными воротами." } } }, t = { d = 22.7, g = 1, v = "human-male", n = { m = 255, f = 257 }, c = { m = { { 0.00, "Что же, тут говорится, что ты был назначен полномочным представителем маршалов Штормграда. Прими мои поздравления." }, { 8.18, "И удачи тебе... Охранять Элвинн - это непростая работа." }, { 11.96, "Да ещё когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки!" }, { 18.91, "В наши мрачные времена политика - дело тёмное..." } }, f = { { 0.00, "Что же, тут говорится, что ты была назначена полномочным представителем маршалов Штормграда. Прими мои поздравления." }, { 8.44, "И удачи тебе... Охранять Элвинн - это непростая работа." }, { 12.21, "Да ещё когда большая часть армии занимается непонятно чем по приказу какого-то аристократишки!" }, { 19.17, "В наши мрачные времена политика - дело тёмное..." } } } } },
    [55] = { d = 24.9, g = 1, v = "human-male", c = { m = { { 0.00, "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма." }, { 7.01, "Пора положить конец его бесчинствам в наших землях…" }, { 10.83, "Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию." }, { 16.88, "Убей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, герой Сумеречного леса." } }, f = { { 0.00, "Морбент Скверн прячется в своём доме на вершине холма на востоке, рядом с кладбищем Вороньего холма." }, { 7.01, "Пора положить конец его бесчинствам в наших землях…" }, { 10.83, "Примени против него Проклятье Морбента, оно обратит в прах всю его защитную магию." }, { 16.88, "Убей его. Убей негодяя и избавь нас от его гнусных козней. Стань орудием возмездия, героиня Сумеречного леса." } } }, t = { d = 20.8, g = 1, v = "human-male", c = { m = { { 0.00, "Морбент Скверн убит. Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему." }, { 10.57, "Ты совершил невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу." }, { 16.52, "Ступай. Быть может, судьба вновь приведёт тебя ко мне..." } }, f = { { 0.00, "Морбент Скверн убит. Тёмные всадники по-прежнему топчут наши земли, но всё же мы одержали победу, хотя и неполную. Я надеялся на это вопреки всему." }, { 10.57, "Ты совершила невозможное, и легенды о тебе будут ходить во всему Сумеречному лесу." }, { 16.72, "Ступай. Быть может, судьба вновь приведёт тебя ко мне..." } } } } },
    [56] = { d = 21.7, g = 1, v = "human-female#47", n = { m = 244, f = 245 }, c = { m = { { 0.00, "Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья." }, { 5.03, "Солдаты Штормграда оставили свои посты, предоставив нас самим себе." }, { 9.78, "Если ты готов на подвиги, помоги нам!" }, { 12.27, "Отправляйся в Застывшие сады на юге от Темнолесья и убей восемь скелетов-воинов и восемь магов-скелетов. Мы должны дать отпор нежити!" } }, f = { { 0.00, "Я – командир Ночного дозора, и мой долг – охранять покой жителей Темнолесья." }, { 5.03, "Солдаты Штормграда оставили свои посты, предоставив нас самим себе." }, { 9.78, "Если ты готова на подвиги, помоги нам!" }, { 12.41, "Отправляйся в Застывшие сады на юге от Темнолесья и убей восемь скелетов-воинов и восемь магов-скелетов. Мы должны дать отпор нежити!" } } }, t = { d = 5.1, v = "human-female#47", n = { x = 62 }, c = { x = { { 0.00, "Великолепно. За верную службу народу Темнолесья тебе полагается награда." } } } } },
    [57] = { d = 21.0, v = "human-female#47", n = { x = 239 }, c = { x = { { 0.00, "Я получила сведения о появлении нежити в наших лесах!" }, { 3.45, "Если ты не боишься, отправляйся на кладбище Вороньего холма и убей пятнадцать скелетов-губителей и пятнадцать ужасных скелетов." }, { 12.13, "Также говорят, что скелеты появились и к югу от Темнолесья, на Безмятежном кладбище. Мы должны изгнать нежить из Сумеречного леса!" } } }, t = { d = 5.6, g = 1, v = "human-female#47", n = { m = 66, f = 67 }, c = { m = { { 0.00, "Народ Темнолесья благодарит тебя. Ты доказал свою преданность Ночному дозору." } }, f = { { 0.00, "Народ Темнолесья благодарит тебя. Ты доказала свою преданность Ночному дозору." } } } } },
    [58] = { d = 17.2, v = "human-female#47", n = { x = 213 }, c = { x = { { 0.00, "Обстановка на Вороньем холме не улучшилась. Безопасность Темнолесья – в твоих руках." }, { 5.53, "У нас не хватает стражей для обеспечения безопасности города." }, { 9.45, "Придётся тебе снова отправиться на Вороний холм и уничтожить двадцать распространителей чумы в восточном мавзолее." } } }, t = { d = 13.0, v = "human-female#47", n = { x = 117 }, c = { x = { { 0.00, "Я благодарю тебя, от лица народа Темнолесья и от себя, как главы Ночного дозора, за храбрость и преданность общему делу. Да озарит Свет твой путь!" } } } } },
    [59] = { d = 28.5, v = "human-male", n = { x = 334 }, c = { x = { { 0.00, "Твои хитроумие и доблесть должны быть вознаграждены. Я приготовил для тебя знак: он пригодится для какой-нибудь части доспехов." }, { 8.90, "Отнеси его Саре Тимберлейн на Лесопилку Восточной долины: она изготовит для тебя броню, или что там тебе будет нужно." }, { 16.98, "Мне хотелось бы надеяться, что новые доспехи помогут тебе, в защите Элвиннского леса от врагов." }, { 23.81, "Лесозаготовки находятся к востоку от сторожевого поста Томаса." } } }, t = { d = 9.9, g = 1, v = "human-female#45", n = { x = 100 }, c = { m = { { 0.00, "Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен." }, { 5.55, "Желаю удачи, герой! Надеюсь, новый доспех тебе пригодится." } }, f = { { 0.00, "Ага, вот и знак! Благодарю. Можешь выбрать любой доспех, какой тебе нужен." }, { 5.55, "Желаю удачи, героиня! Надеюсь, новый доспех тебе пригодится." } } } } },
    [60] = { d = 31.8, g = 1, v = "human-male", n = { m = 354, f = 359 }, c = { m = { { 0.00, "Приветствую тебя, добрый путник! Не найдётся ли у тебя свободной минутки?" }, { 5.49, "Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь?" }, { 12.85, "Я вот и думаю: может, ты мне поможешь?" }, { 15.97, "Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке..." }, { 27.35, "Может, прогуляешься туда и раздобудешь для меня свечи?" } }, f = { { 0.00, "Приветствую тебя, прекрасная госпожа! Не найдётся ли у тебя свободной минутки?" }, { 5.80, "Мы с братом держим аптеку в Штормграде; так вот, мне тут понадобились большие свечи. Воск нужен, понимаешь?" }, { 13.17, "Я вот и думаю: может, ты мне поможешь?" }, { 16.28, "Свечи можно достать у кобольдов, а кобольдов, по слухам, в Элвиннских рудниках видимо-невидимо: и в руднике Подземных глубин к югу отсюда, и в Яшмовой шахте на востоке..." }, { 27.67, "Может, прогуляешься туда и раздобудешь для меня свечи?" } } }, t = { d = 4.9, v = "human-male", n = { x = 51 }, c = { x = { { 0.00, "Ну что, пришлось попотеть? Спасибо за свечи! А вот и твоя награда..." } } } } },
    [61] = { d = 19.5, v = "human-male", n = { x = 218 }, c = { x = { { 0.00, "В Штормграде мой брат Морган ждёт посылки со свечами." }, { 3.78, "У меня нет времени съездить туда самому, но если ты окажешь нам эту услугу, Морган хорошо тебе заплатит." }, { 11.43, "Вот, я тут упаковал свечи. А Моргана найти несложно, он работает в Торговом квартале Штормграда, в аптеке Песта." } } }, t = { d = 10.7, v = "human-male", n = { x = 123 }, c = { x = { { 0.00, "Вот плата за услугу... Кстати, можешь тут пока осмотреться: уверен, у нас наверняка найдётся какое-нибудь зелье или безделушка, которые тебе пригодятся..." } } } } },
    [62] = { d = 22.7, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Рудник в Североземье – не единственная головная боль." }, { 3.59, "До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды." }, { 10.63, "Нужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчёта." }, { 17.25, "Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур." } } }, t = { d = 12.1, v = "human-male", n = { x = 137 }, c = { x = { { 0.00, "Скверные вести. И что дальше? Может, драконы?! Похоже, придётся усилить охрану рудника. Спасибо тебе. И подожди, не уходи..." }, { 8.18, "возможно, у меня найдётся для тебя ещё одно задание." } } } } },
    [63] = { d = 36.0, v = "tauren-female#71", n = { x = 365 }, c = { x = { { 0.00, "На побережье Серебряного Бора, к западу от Гробницы, находится святилище, осквернённое чумой." }, { 7.27, "Духи перестали разговаривать с нашим народом, и тебе предстоит победить воплощение воды и очистить купель." }, { 15.96, "Возьми браслеты элементалей и остатки зелья Брин и помести их в жаровню." }, { 22.26, "Этот ритуал позволит призвать чистого духа, с которым можно будет поговорить." }, { 28.67, "Принеси мне доказательство того, что моё задание выполнено, и в награду я дам тебе тотэм." } } }, t = { d = 13.7, v = "tauren-female#71", n = { x = 143 }, c = { x = { { 0.00, "Вы помещаете браслеты в жаровню и выливаете в огонь оставшиеся капли зелья Брин." }, { 6.40, "Пламя потрескивает, а вы начинаете проговаривать простые слова, которым вас обучила Ислен..." } } } } },
    [64] = { d = 29.8, v = "human-male", n = { x = 340 }, c = { x = { { 0.00, "Это было ужасно! Верна разбудила меня, когда услышала гвалт в поле. Поля были полны хулиганья." }, { 6.50, "Мы бежали в спешке, и я забыл взять с собой карманные часы." }, { 10.51, "Папаша Верны подарил мне эти часы в день нашей с ней свадьбы, и мне прямо нехорошо от мысли, что ими могли завладеть те воры." }, { 18.96, "Я оставил часы в доме, в платяном шкафу. Ищи тыквенную ферму к западу отсюда – ты её не пропустишь." }, { 25.77, "Если вернёшь мне мои часы, я буду очень признателен!" } } }, t = { d = 11.8, g = 1, v = "human-male", n = { m = 130, f = 129 }, c = { m = { { 0.00, "Мои часы! Благодарю тебя, любезный господин!" }, { 3.57, "Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности." } }, f = { { 0.00, "Мои часы! Благодарю тебя, любезная госпожа!" }, { 3.55, "Мы всего лишь бедные фермеры, потерявшие свою землю, но прошу тебя, прими эту награду в знак нашей признательности." } } } } },
    [65] = { d = 28.6, g = 1, v = "human-male", n = { m = 333, f = 335 }, c = { m = { { 0.00, "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости." }, { 7.97, "Мне нужно, чтобы ты проник в эту бандитскую шайку. Нам нужно узнать, кто её главарь, и где они прячутся." }, { 15.11, "В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан." }, { 20.87, "Отправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай." } }, f = { { 0.00, "Группа негодяев, ответственных за то, что честные люди покидают Западный Край, зовёт себя Братством Справедливости." }, { 7.97, "Мне нужно, чтобы ты проникла в эту бандитскую шайку. Нам нужно узнать, кто её главарь, и где они прячутся." }, { 15.16, "В деревне Приозерье, в таверне, обитает некий Вилли, который мне кое-чем обязан." }, { 20.92, "Отправляйся в деревню Приозерье, что расположена в Красногорье, к востоку от Элвиннского леса, и всё разузнай." } } }, t = { d = 4.4, v = "human-male#50", n = { x = 47 }, c = { x = { { 0.00, "Так значит, тебя послал Камнегрив? Что ж, я перед ним в долгу." } } } } },
    [66] = { d = 27.2, v = "human-female#45", n = { x = 314 }, c = { x = { { 0.00, "Вчера ночью меня охватил беспричинный ужас. Я почувствовала, что моя внучка Алисса оказалась в страшной опасности." }, { 7.72, "Я разложила карты... и со стола на меня взглянула Смерть." }, { 11.96, "Погрузившись в длительный и тяжкий транс, я сумела разгадать эту тёмную тайну. Мне открылось имя: Сталван." }, { 19.56, "Отыщи клерка в городской Ратуше и постарайся побольше разузнать об этом Сталване. Я опасаюсь за всех нас." } } }, t = { d = 2.6, v = "human-male", n = { x = 23 }, c = { x = { { 0.00, "А, так тебя послала мадам Ева..." } } } } },
    [67] = { d = 24.1, v = "human-male", n = { x = 237 }, c = { x = { { 0.00, "Сталван, значит? Дай-ка погляжу в журнал." }, { 3.77, "Сталван... Сталван... Ну-ка... А, вот он! У меня есть запись о некоем господине Сталване Мистмантле." }, { 12.18, "Последний адрес – Лунореченская школа. Но это было так давно!" }, { 16.74, "Окажи любезность, дай знать, если выяснишь что-либо об этом типе. Записи должны содержаться в порядке." } } }, t = { d = 3.0, v = "human-male", n = { x = 32 }, c = { x = { { 0.00, "Старый сундук со скрипом открывается..." } } } } },
    [68] = { d = 4.5, v = "human-male#114", n = { x = 49 }, c = { x = { { 0.00, "Вы находите в старом сундуке пыльное неотосланное письмо." } } }, t = { d = 9.7, v = "human-male", n = { x = 105 }, c = { x = { { 0.00, "Занятно. Значит, этот тип всё же побывал в Луноречье. Странно, что письмо так и не доставили." }, { 6.52, "Тем не менее я обновлю записи в журнале." } } } } },
    [69] = { d = 14.9, v = "human-male", n = { x = 172 }, c = { x = { { 0.00, "Боже мой! Сразу и не заметил. В журнале, точно под первым адресом Сталвана, написан ещё один адрес, частично вычеркнутый." }, { 8.45, "Похоже, он направлялся в таверну \"Гордость льва\" в Златоземье. Можешь поискать сведения там." } } }, t = { d = 2.4, v = "human-male", n = { x = 18 }, c = { x = { { 0.00, "Сталван? Знакомое имя." } } } } },
    [70] = { d = 29.0, v = "human-male", n = { x = 316 }, c = { x = { { 0.00, "Имя Сталван мне знакомо. А, вспомнил." }, { 3.22, "Много лет назад ненастной ночью в трактир явился гонец, искавший убежища от непогоды." }, { 9.24, "Около полуночи этот человек, бледный от страха, сбежал вниз по лестнице в пижаме и исчез." }, { 15.86, "Второпях он оставил письма в сундуке на втором этаже. За ними он так и не вернулся. Осталось одно, от этого Сталвана." }, { 24.05, "Адресовано оно в район каналов Штормграда. Можешь прочитать." } } }, t = { d = 3.9, v = "human-male#50", n = { x = 41 }, c = { x = { { 0.00, "А ты не робкого десятка, раз решился доставить это." } } } } },
    [71] = { d = 10.1, v = "human-male#114", n = { x = 102 }, c = { x = { { 0.00, "Теперь, когда вы нашли оба медальона, отнесите их к мосту и отдайте стражнику Томасу: он должен узнать о смерти обоих стражей." } } }, t = { d = 6.5, v = "human-male", n = { x = 74 }, c = { x = { { 0.00, "Увы, мои худшие опасения подтвердились. Мурлоки – это угроза, с которой придётся считаться..." } } } } },
    [72] = { d = 26.7, v = "human-male#50", n = { x = 321 }, c = { x = { { 0.00, "Мой отец был сторожем в этом поместье задолго до меня. Ему-то и пришлось вытирать кровь после того убийства. Но это к делу не относится." }, { 9.40, "Последние деньги треста Кременника давно иссякли. А теперь и последние семейные ценности отправляются прямиком на аукцион." }, { 17.62, "Проклятые сборщики налогов!.. Пожалуй, если ты хочешь узнать побольше, можешь порыться в этом барахле. Кто знает, что тебе попадётся." } } }, t = { d = 2.8, v = "human-male#50", n = { x = 30 }, c = { x = { { 0.00, "Вы медленно снимаете крышку с ящика..." } } } } },
    [74] = { d = 16.9, v = "human-male#114", n = { x = 175 }, c = { x = { { 0.00, "Внутри ящика вы находите много разных вещей: пыльные фамильные ценности, портрет, несколько охотничьих трофеев и старые книги." }, { 9.90, "Уже на самом дне, под глиняной вазой, вам попадается страница, вырванная из дневника." } } }, t = { d = 9.9, v = "human-male", n = { x = 102 }, c = { x = { { 0.00, "Я едва разбираю буквы, но почерк напоминает мне о..." }, { 4.25, "Да, я видел что-то подобное до того, как моё зрение окончательно испортилось." } } } } },
    [75] = { d = 27.3, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Когда я только приехал сюда, в сундуке на втором этаже лежала кипа пергаментов." }, { 5.43, "Как-то раз я их просмотрел, но потом зрение стало не то, и я махнул на них рукой." }, { 11.52, "Окажи любезность слепому старику, поищи в сундуке наверху что-нибудь, что сможет помочь тебе разузнать о Сталване." }, { 19.39, "Мне кажется, там была выцветшая страница с интересными записями. Принеси её мне, и я помогу тебе по мере сил." } } }, t = { d = 1.1, v = "human-male", n = { x = 6 }, c = { x = { { 0.00, "Это она!" } } } } },
    [76] = { d = 22.7, v = "human-male", n = { x = 258 }, c = { x = { { 0.00, "Благодаря тебе мы знаем, что рудник Подземных глубин заполонили кобольды." }, { 5.18, "Но нам нужен разведчик, чтобы выяснить, что творится в Яшмовой шахте." }, { 10.35, "Отправляйся туда и доложи мне, если обнаружишь кобольдов." }, { 14.43, "Иди на восток по дороге, пока не доберёшься до Башни Азоры, оттуда поверни на север, и у подножия гор отыщешь шахту." } } }, t = { d = 10.9, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Кобольды в Яшмовой шахте? Так это правда? Проклятье! Дела идут всё хуже и хуже!" }, { 5.95, "Конечно, я благодарен тебе за информацию, но лучше бы мы ошибались..." } } } } },
    [78] = { d = 16.6, v = "human-male", n = { x = 189 }, c = { x = { { 0.00, "Я знаю, кто мог бы тебе помочь. Когда я служил в страже Штормграда, мы порой пропускали по стаканчику в темнолесской таверне \"Алый ворон\"." }, { 9.43, "Её хозяин Смиттс всегда был знатоком преданий. Покажи ему эту страницу, посмотрим, что он скажет." } } }, t = { d = 2.9, v = "human-male#50", n = { x = 29 }, c = { x = { { 0.00, "Клянусь Светом! Я узнаю этот почерк!" } } } } },
    [79] = { d = 28.6, v = "human-male#50", n = { x = 351 }, c = { x = { { 0.00, "Я много лет следил за легендами, ходящими об этом Сталване." }, { 4.08, "Когда несколько лет назад нескольких заезжих аристократов нашли мёртвыми, мы с Хаггардом решили расследовать это дело." }, { 12.05, "Я отыскал несколько заляпанных грязью страниц, но мы так и не нашли связи между ними и этим лесным сумасшедшим." }, { 19.46, "Найденные тобой улики подтверждают его вину. Немедленно отнеси эту страницу командиру Чернодрев и расскажи ей о добытых сведениях!" } } }, t = { d = 3.6, g = 1, v = "human-female#47", n = { m = 32, f = 33 }, c = { m = { { 0.00, "Надо же, ты оказался настоящим сыщиком, герой." } }, f = { { 0.00, "Надо же, ты оказалась настоящим сыщиком, героиня." } } } } },
    [80] = { d = 19.3, v = "human-female#47", n = { x = 233 }, c = { x = { { 0.00, "Я давно присматриваюсь к этому Сталвану. Но если эта страница написана той же самой рукой, то его вина несомненно доказана." }, { 8.51, "За долгие годы службы клерк Далтри стал настоящим экспертом по различению почерков." }, { 14.12, "Покажи ему эту страницу, проверь, совпадает ли почерк с росписью в журнале." } } }, t = { d = 5.0, v = "human-male", n = { x = 56 }, c = { x = { { 0.00, "Несомненно! Почерк на этой странице совпадает с подписью в журнале." } } } } },
    [83] = { d = 21.0, v = "human-female#45", n = { x = 242 }, c = { x = { { 0.00, "В Североземье Братство Справедливости носит маски из холстины; в Элвиннском лесу они предпочитают лён, который мог бы принести мне гораздо большую пользу... и прибыль." }, { 11.68, "Принеси мне красные повязки, а я сделаю из них кое-что полезное для тебя." }, { 17.07, "Лагеря братства разбросаны по всему Элвиннскому лесу." } } }, t = { d = 4.2, v = "human-female#45", n = { x = 45 }, c = { x = { { 0.00, "Отличные повязки, даром что ткань грубовата... Вот, держи!" } } } } },
    [84] = { d = 6.1, v = "human-female", n = { x = 66 }, c = { x = { { 0.00, "Вот, держи. Отдай этот пирог Билли, да не забудь сказать, что я желаю ему подавиться!" } } }, t = { d = 5.0, v = "child-male", n = { x = 53 }, c = { x = { { 0.00, "М-м, вкуснятина! Пирог что надо!" }, { 2.53, "Похоже, ко мне возвращается память..." } } } } },
    [85] = { d = 18.3, v = "human-female", n = { x = 210 }, c = { x = { { 0.00, "Я потеряла ожерелье. Сдаётся мне, его стащил этот беспризорник Билли Маклур!" }, { 5.28, "Вечно он шастает по виноградникам, как крыса какая-то! Если решишь его искать, то сходи на виноградники, это к востоку отсюда." }, { 14.27, "Пожалуйста, разыщи моё ожерелье, порадуй старуху-вдову!" } } }, t = { d = 14.2, v = "child-male", n = { x = 174 }, c = { x = { { 0.00, "Чего-чего она там потеряла? Какое такое ожерелье? Не брал я его, даже в глаза не видел, и вообще я не вор какой-нибудь!" }, { 7.59, "Может, я и знаю, кто мог это сделать... Вот только вспоминать на голодный желудок сложно, в голове мутится." } } } } },
    [86] = { d = 17.6, v = "child-male", n = { x = 227 }, c = { x = { { 0.00, "Может, если бы я получил пирог, то смог бы вспомнить, у кого сейчас это твоё ожерелье. Кстати..." }, { 5.53, "Говорят, у тётушки Бернис получаются отличные пироги со свининой." }, { 9.82, "Я вот что думаю: принеси ей кабаньего мяса – около ферм кабанов ошивается видимо-невидимо – и попроси испечь для тебя пирог." } } }, t = { d = 7.5, v = "human-female", n = { x = 86 }, c = { x = { { 0.00, "Хоть мясо и жестковато, его можно потушить на медленном огне и приготовить отличную начинку для пирога!" } } } } },
    [87] = { d = 21.4, v = "child-male", n = { x = 272 }, c = { x = { { 0.00, "Я играл около рудника Подземных глубин и, похоже, уронил... М-м... В смысле, я там видел ожерелье этой самой дамы." }, { 6.62, "Представления не имею, как оно туда попало; я тут ни при чём!" }, { 10.65, "В общем, короче, я видел, как здоровенный кобольд с золотыми зубами схватил ожерелье и скрылся в руднике." }, { 16.95, "Если отыщешь этого кобольда, найдёшь и ожерелье, точно тебе говорю!" } } }, t = { d = 13.6, v = "human-female", n = { x = 152 }, c = { x = { { 0.00, "Моё ожерелье! Оно нашлось! О, дорогуша, спасибо, спасибо!" }, { 4.15, "Вот, держи. Это принадлежало моему мужу; \"счастливая вещица\" – он всегда так говорил." }, { 9.72, "Если бы только он взял это с собой в последний поход!.." } } } } },
    [88] = { d = 36.0, v = "human-female#47", n = { x = 430 }, c = { x = { { 0.00, "У семейства Бреквеллов имеется свинья. Не простая, а призовая, по кличке – ты только представь себе! – Принцесса." }, { 7.37, "И эта громадная гора сала то и дело пробирается на мой огород! Чтобы пожирать мои овощи!" }, { 13.74, "Так вот, прежде чем эта скотина доберётся до полей... словом, Принцесса должна умереть!" }, { 19.40, "Принеси мне её ошейник в доказательство того, что это свершилось, а взамен получишь кое-что полезное." }, { 26.36, "Принцессу держат на тыквенной ферме Бреквеллов: это к востоку от фермы Маклуров." }, { 31.58, "Разберись с ней прежде, чем она проголодается и вернётся сюда!" } } }, t = { d = 12.6, v = "human-female#47", n = { x = 140 }, c = { x = { { 0.00, "Счастье-то какое! Эта хавронья была такой громадной, что в один присест сожрала бы весь наш урожай! Я так тебе благодарна!" }, { 8.57, "Взгляни: что-нибудь из этого тебе, надеюсь, подойдёт?" } } } } },
    [89] = { d = 25.4, v = "human-male", n = { x = 285 }, c = { x = { { 0.00, "Из-за последнего нашествия орков нам пришлось переплавить весь металл на пули, мечи и доспехи." }, { 6.59, "Мы посылали в Штормград за новыми поставками, но отряд гноллов Красногорья разграбил обоз и сбежал в холмы за Приозерьем." }, { 15.24, "Нам не хватает материалов на ремонт моста." }, { 18.25, "Если ты принесёшь мне пять железных пик и пять железных клепок, я прикажу тебя наградить. За дело!" } } }, t = { d = 6.1, v = "human-male", n = { x = 69 }, c = { x = { { 0.00, "Отличная работа. Мы можем продолжить восстановление моста. Ещё немного, и закончим." } } } } },
    [90] = { d = 26.4, v = "human-male", n = { x = 304 }, c = { x = { { 0.00, "Моё коронное блюдо – пряные котлеты из волчатины!" }, { 3.43, "Разумеется, я могу тебе их пожарить, но для этого мне понадобятся кое-какие продукты. Раздобудь десять постных волчьих боков." }, { 12.11, "В лесу волков полно, и добыть мясо будет несложно." }, { 15.64, "Кстати, тебе ещё повезло – буквально на днях мне пришёл очередной груз травяных приправ Штормграда, так что от тебя мне понадобится только сама волчатина." } } }, t = { d = 5.8, v = "human-male", n = { x = 68 }, c = { x = { { 0.00, "Отличная работа! Наслаждайся вкуснятиной – приправленной котлетой из волчатины!" } } } } },
    [91] = { d = 31.2, v = "human-male", n = { x = 342 }, c = { x = { { 0.00, "В восточных предгорьях нашего края обосновался враг Штормграда." }, { 4.32, "С помощью тайной магии этот негодяй по имени Моргант сеет ужас и страдания в нашем городе и окрестностях." }, { 12.57, "Он прибрал под свою руку гноллов из стаи Темношкуров, и они исполняют его повеления." }, { 19.48, "Согласно Закону Озёр, пособничество врагу королевства карается смертью. Гноллов следует уничтожить!" }, { 26.83, "Принеси мне десять подвесок Темношкуров и получишь награду." } } }, t = { d = 11.0, v = "human-male", n = { x = 132 }, c = { x = { { 0.00, "Суд Озёр благодарит тебя за помощь правосудию." }, { 3.27, "Помогая претворить в жизнь законы Королевства, ты способствуешь установлению справедливости в наших землях." } } } } },
    [92] = { d = 26.5, v = "human-female#47", n = { x = 324 }, c = { x = { { 0.00, "Я бы с радостью сделала для тебя гуляш по-красногорски, но есть небольшое затруднение." }, { 5.80, "Во время недавнего вторжения орков мне пришлось кормить целый отряд солдат Штормграда, и все кладовые опустели..." }, { 13.21, "Хотя если ты снабдишь меня всеми необходимыми продуктами, я уж расстараюсь!" }, { 18.64, "Принеси мне пять кусков жёсткого мяса кондора, пять рыл больших жутевепрей и пять порций хрустящего паучьего мяса." } } }, t = { d = 5.8, v = "human-female#47", n = { x = 66 }, c = { x = { { 0.00, "Молодец. И какие отличные куски! А вот и моё коронное блюдо – гуляш по-красногорски." } } } } },
    [93] = { d = 25.0, v = "human-male", n = { x = 286 }, c = { x = { { 0.00, "Открою тебе тайну: тёмные пирожки с \"крабами\" делаются из паучьих лапок!" }, { 4.95, "Понимаю, эта новость может быть для тебя неприятной, но пирожки получаются вкусные и ароматные – отличная закуска!" }, { 12.78, "Принеси мне липкие паучьи лапки, и я испеку для тебя пирожочки." }, { 17.67, "Говорят, что лучшие лапки у ядовитых кругопрядов. Они плетут паутины на севере, между холмами и рекой." } } }, t = { d = 16.8, v = "human-male", n = { x = 186 }, c = { x = { { 0.00, "О, отличные лапки! Дай-ка я замариную их особым составом, – не подсматривай! – потом хорошенько подрумяню на сковородке…" }, { 8.53, "И хотя тёмные пирожки с крабами – моё коронное блюдо и рецептом я делиться не готов, вот тебе рецепт блюда не хуже." } } } } },
    [94] = { d = 36.8, v = "human-male", n = { x = 419 }, c = { x = { { 0.00, "Мой соперник Моргант – волшебник, наделённый великой силой, но лишённый сердечной доброты." }, { 6.22, "Он обосновался в башне Илгалара, что в Красногорье. Я нашёл способ следить за ним при помощи Ока Азоры." }, { 13.79, "Однако Око не даёт возможности проникнуть в его мысли. Для такого дела мне потребуется помощь." }, { 20.68, "Если ты согласишься помогать мне, возьми амулет Азоры и отнеси его к башне Илгалара." }, { 26.56, "Амулет нужно положить под статую льва рядом с башней." }, { 30.59, "Если это будет сделано, то с помощью силы Азоры я смогу проникнуть в замыслы Морганта." } } }, t = { d = 20.5, g = 1, v = "human-male", n = { m = 226, f = 226 }, c = { m = { { 0.00, "Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита:" }, { 7.17, "Прими мою благодарность, юный путник. Отныне ты сможешь говорить со мной посредством этого амулета." }, { 14.13, "После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание." } }, f = { { 0.00, "Вы кладёте амулет Азоры в углубление, и он словно бы врастает в камень. Вы слышите голос Теокрита:" }, { 7.17, "Прими мою благодарность, юная путница. Отныне ты сможешь говорить со мной посредством этого амулета." }, { 14.18, "После того как я проникну в мысли моего соперника, у меня будет для тебя новое задание." } } } } },
    [95] = { d = 36.3, v = "human-male", n = { x = 409 }, c = { x = { { 0.00, "Раньше я работал на одной из ферм на юго-востоке..." }, { 3.37, "а потом тёмные всадники спустились с перевала Мёртвого Ветра и перебили всю мою семью, пока я был в отлучке!" }, { 11.19, "Вернувшись, я увидел неподалёку от амбара неясную фигуру человека, который что-то закапывал." }, { 17.63, "Он успел сбежать от меня, а задерживаться я не мог, потому что преследовал тёмных всадников." }, { 24.19, "Так я и не узнал, что там спрятано." }, { 27.02, "Если ты можешь выяснить, что закопал в землю этот незнакомец, я буду очень признателен. Поищи возле старого пня, рядом с амбаром." } } }, t = { d = 7.9, v = "human-male", n = { x = 89 }, c = { x = { { 0.00, "Вы находите кучу торопливо накиданной земли. Похоже, кто-то хотел что-то спрятать... а времени у него не хватало." } } } } },
    [96] = { d = 16.9, v = "elemental-water", n = { x = 113 }, c = { x = { { 0.00, "Возьми осколок. Возьми его и даруй жизнь." }, { 4.43, "Даруй жизнь и пойми. Пойми, что вода – это жизнь... А порча – конец жизни." }, { 13.25, "Оберегай и даруй жизнь силой воды." } } }, t = { d = 37.4, v = "tauren-female#71", n = { x = 369 }, c = { x = { { 0.00, "А вот и доказательство твоих свершений, как я и просила." }, { 4.85, "Я рада, что могу первой поздравить тебя с успехом и вручить тебе этот... Тотэм воды." }, { 11.77, "Пусть он служит тебе верой и правдой. Удачи!" }, { 15.92, "Следующее испытание ожидает тебя нескоро, поэтому учись хорошенько." }, { 21.35, "Чистая вода не только вдыхает новую жизнь в раненых, но может также оказывать и другие эффекты." }, { 28.77, "Когда найдёшь время, поговори с наставником шаманов. Может быть, у него найдутся для тебя новые заклинания." } } } } },
    [97] = { d = 6.6, v = "human-male", n = { x = 78 }, c = { x = { { 0.00, "Немедленно сообщи командиру Чернодрев, что почерки совпадают! Её подозрения подтвердились!" } } }, t = { d = 2.5, v = "human-female#47", n = { x = 24 }, c = { x = { { 0.00, "Я так и знала! Отличная работа!" } } } } },
    [99] = { d = 55.7, v = "scourge-male#82", n = { x = 501 }, c = { x = { { 0.00, "По мере того, как растёт моё понимание магии Аругала, растёт и моё презрение к этому злосчастному глупцу." }, { 9.57, "Я уже почти закончил исследование его так называемого \"лекарственного зелья\"." }, { 16.91, "У меня будет полная информация, когда я узнаю, какие чары служат причиной странностей, происходящих в деревне Погребальных Костров." }, { 28.74, "Днём живущие там крестьяне выглядят по-человечески. Но когда солнце заходит, деревенский люд превращается в воргенов Лунного Гнева." }, { 40.88, "Мне нужно извлечь энергию из заколдованных кандалов, надетых на крестьян Аругалом." }, { 48.52, "Принеси мне шесть заколдованных кандалов из деревни Погребальных Костров." } } }, t = { d = 14.7, v = "scourge-male#82", n = { x = 123 }, c = { x = { { 0.00, "Твоя настойчивость весьма похвальна." }, { 3.36, "С помощью информации, которую ты помог мне собрать, Аругал падёт, и вся его безрассудная магия развеется. Браво." } } } } },
    [100] = { d = 14.3, v = "human-male#114", n = { x = 150 }, c = { x = { { 0.00, "Отзвучали последние слова заклятья, и вас ослепляет вспышка света." }, { 4.98, "Звуки капель, падающих на пламя, стихают, и вас переполняет радость: ведь осквернённые духи вокруг вас уничтожены." } } }, t = { d = 12.0, v = "elemental-water", n = { x = 87 }, c = { x = { { 0.00, "Спасибо тебе. Спасибо шаманам." }, { 3.59, "Порча отступает, но жизнь продолжает увядать. Пусть шаманы охраняют жизнь." } } } } },
    [101] = { d = 28.2, g = 1, v = "human-female#45", n = { m = 309, f = 309 }, c = { m = { { 0.00, "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите." }, { 5.69, "Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем." }, { 11.57, "Если ты желаешь оградить себя от неё, благородный герой, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда." }, { 21.56, "Тогда я создам тотэм Кары, который будет наносить урон тем, кто попытается напасть на тебя." } }, f = { { 0.00, "По лесу расползается тление и порча, и все мы вынуждены позаботиться о самозащите." }, { 5.69, "Ветер несёт мне вести о великой опасности, поджидающей тебя в ближайшем будущем." }, { 11.57, "Если ты желаешь оградить себя от неё, благородная героиня, принеси мне десять клыков вурдалаков, десять пальцев скелетов и пять фиалов паучьего яда." }, { 21.69, "Тогда я создам тотэм Кары, который будет наносить урон тем, кто попытается напасть на тебя." } } }, t = { d = 21.4, g = 1, v = "human-female#45", n = { m = 242, f = 243 }, c = { m = { { 0.00, "Ты поступил мудро. Этот тотэм Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами." }, { 7.02, "Если тебе будет что-то угрожать, возьми тотэм в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасный герой." }, { 15.68, "Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений." } }, f = { { 0.00, "Ты поступила мудро. Этот тотэм Кары защитит тебя от зла, таящегося по всему Азероту и за его пределами." }, { 7.14, "Если тебе будет что-то угрожать, возьми тотэм в руку – и его магическая аура защитит тебя. Не теряй мужества, прекрасная героиня." }, { 15.88, "Тебе оно понадобится, ибо я чувствую – грядёт немало кровопролитных сражений." } } } } },
    [102] = { d = 34.7, v = "human-male#50", n = { x = 395 }, c = { x = { { 0.00, "Штормград отвернулся от нас. Злобный ветер несчастий носится по равнинам Западного Края." }, { 6.07, "Это была моя родина, и я не отвернусь от местных жителей, решивших остаться здесь. Мы, бывшие фермеры, намерены постоять за себя." }, { 15.65, "Твоё задание, если ты за него возьмёшься, будет состоять в том, чтобы патрулировать луга Западного Края." }, { 22.62, "Выследи и убей мерзких гноллов, которые, похоже, действуют заодно с ворами из Мёртвых копей." }, { 29.39, "Принеси мне восемь лап гноллов, и я вознагражу тебя за проявленное мужество." } } }, t = { d = 16.5, v = "human-male#50", n = { x = 199 }, c = { x = { { 0.00, "Хорошая работа. Если на стороне народного ополчения будут такие смельчаки, как ты, Западный Край сможет когда-нибудь вновь стать процветающей житницей, какой был когда-то." }, { 11.57, "Пожалуйста, прими эту награду в знак признательности за твои усилия." } } } } },
    [103] = { d = 33.3, v = "human-male", n = { x = 391 }, c = { x = { { 0.00, "Ночь, когда погибла семья смотрителя маяка, была ужасной." }, { 4.12, "Я беспомощно наблюдал за происходившим, поскольку сам Старый Мрачноглаз вёл нападавших." }, { 10.16, "Но что случилось, то случилось, и теперь жизнь моряков, плавающих по Великому морю и близко подходящих к опасным прибрежным рифам – моя забота." }, { 19.89, "Поддерживать огонь маяка оказалось некому, и эта обязанность легла на мои плечи." }, { 25.65, "Помогите мне поддержать огонь факела – принесите пять фляг масла, собрав их с сельскохозяйственных големов." } } }, t = { d = 21.0, g = 1, v = "human-male", n = { x = 220 }, c = { m = { { 0.00, "Хвала тебе, смелый герой. Рифы побережья Западного Края будут освещены благодаря твоим трудам." }, { 6.66, "Множество жизней будет спасено, пока горит факел." }, { 10.51, "Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." } }, f = { { 0.00, "Хвала тебе, смелый героиня. Рифы побережья Западного Края будут освещены благодаря твоим трудам." }, { 7.99, "Множество жизней будет спасено, пока горит факел." }, { 11.84, "Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." } } } } },
    [104] = { d = 35.1, v = "human-male", n = { x = 401 }, c = { x = { { 0.00, "Когда моя жизнь оборвалась на скалах, я и понятия не имел, что уготовано мне на том свете." }, { 6.21, "Маяк той ночью не светил, поскольку Старый Мрачноглаз перепугал семью смотрителя, и они убежали." }, { 12.94, "Потом они вернулись и вновь зажгли пламя, но Мрачноглаз заставил более слабых духом мурлоков атаковать маяк вместе с ним." }, { 21.49, "Во второй раз семье смотрителя не повезло, и вся она погибла у меня на глазах." }, { 27.16, "Убейте Старого Мрачноглаза, если увидите его на берегу, принесите мне одну из его чешуй, и я вознагражу вас." } } }, t = { d = 19.2, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Итак, это злобное чудовище, Мрачноглаз, мертво. Хорошая работа." }, { 4.40, "Вы своими руками прервали одну жизнь, но, возможно, тем самым спасли множество других." }, { 10.36, "Великое море, само по себе исполненное угрозы, станет этой ночью чуточку безопаснее благодаря вашему героическому деянию." } } } } },
    [106] = { d = 21.8, v = "human-female", n = { x = 247 }, c = { x = { { 0.00, "За что мне это наказание? Моё сердце отдано Томми Джо Стоунфилду, я жить без него не могу, но наши родители – заклятые враги!" }, { 8.49, "Я не только встретиться – даже взглянуть на него не могу!" }, { 12.76, "Пожалуйста, отнеси Томми Джо это письмо." }, { 15.43, "Он обычно бывает у реки к западу от фермы Стоунфилдов, а сама ферма – тоже к западу отсюда..." } } }, t = { d = 4.6, v = "human-male", n = { x = 45 }, c = { x = { { 0.00, "Я больше не могу жить в разлуке с ней! Я должен увидеть её!" } } } } },
    [107] = { d = 13.6, v = "human-female#45", n = { x = 155 }, c = { x = { { 0.00, "Бьюсь об заклад, у Вильяма Песта найдётся зелье, которое поможет соединить наших юных влюблённых!" }, { 7.08, "Вот, держи: отнесёшь эту записку Вильяму. Найдёшь его в Златоземье, в таверне \"Гордость льва\"." } } }, t = { d = 13.2, v = "human-male", n = { x = 141 }, c = { x = { { 0.00, "У меня просто сердце разрывается, как подумаю об этих бедных детках, Мейбелл и Томми Джо. Ах, молодость... Весна... Любовь..." }, { 8.63, "Думаю, я смогу им чем-нибудь помочь. Погоди-ка, дай подумать..." } } } } },
    [109] = { d = 23.6, g = 1, v = "human-male", n = { x = 249 }, c = { m = { { 0.00, "Похоже, герой, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву." }, { 9.07, "Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает." }, { 16.48, "Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края." } }, f = { { 0.00, "Похоже, героиня, тебе довелось побывать не в одном бою... Думаю, тебе стоит явиться с докладом к Гриану Камнегриву." }, { 7.80, "Он возглавляет ополчение, защищающее фермерские земли Западного Края. Думаю, твоя помощь ему не помешает." }, { 15.21, "Обычно его можно найти в башне, что на Сторожевом холме, у дороги, в самом сердце Западного Края." } } }, t = { d = 16.9, v = "human-male", n = { x = 189 }, c = { x = { { 0.00, "А, так это мой друг тебя сюда отправил? С его стороны это большая любезность." }, { 5.65, "Что ж... Монархия Штормграда больше не поддерживает нас. Остаётся полагаться на ополчение." }, { 11.82, "Если ты хочешь сражаться за свободу вместе с нами, я буду рад этому." } } } } },
    [111] = { d = 11.2, v = "human-male", n = { x = 119 }, c = { x = { { 0.00, "Прошу тебя, поговори с моей бабулей. Если кто и может сделать так, чтобы мы с Мейбелл были вместе, так это она." }, { 7.91, "Бабуля сейчас дома – это к востоку отсюда..." } } }, t = { d = 10.7, v = "human-female#45", n = { x = 119 }, c = { x = { { 0.00, "Пока наши семьи враждуют, у Томми Джо и Мейбелл вряд ли есть шансы; но, может, мы дадим им возможность хоть немного побыть вместе. Хм... Что бы придумать..." } } } } },
    [112] = { d = 27.0, v = "human-male", n = { x = 310 }, c = { x = { { 0.00, "Да, я могу приготовить для Мэйбелл напиток невидимости, чтобы она могла убежать с Виноградников Маклура к своему Томми Джо." }, { 8.59, "Но для этого мне нужен хрустальный фукус." }, { 11.78, "Эти водоросли растут в океане, и мурлокам иногда удаётся добыть их." }, { 16.52, "Может, у тех, что живут на берегах Хрустального Озера, найдётся нужный компонент." }, { 22.02, "А озеро найти просто: нужно только пойти на восток от Златоземья." } } }, t = { d = 8.2, v = "human-male", n = { x = 75 }, c = { x = { { 0.00, "Ага, вот и фукус! Отлично, просто отлично! А теперь погоди минутку: сейчас напиток будет готов." } } } } },
    [114] = { d = 8.6, v = "human-male", n = { x = 98 }, c = { x = { { 0.00, "Отнеси этот напиток невидимости юной Мэйбелл. Его действия хватит на то, чтобы девушка успела встретиться с Томми Джо." } } }, t = { d = 18.5, v = "human-female", n = { x = 205 }, c = { x = { { 0.00, "Мне так стыдно, что приходится обманывать свою семью... Но я не могу отказаться от Томми!" }, { 6.39, "Благодарю тебя. Как только подвернётся случай, я выпью этот напиток и найду способ пробраться к моему любимому." }, { 14.35, "А в дополнение к словам благодарности прими вот это." } } } } },
    [115] = { d = 26.8, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Орки из клана Чёрной Горы позвали на помощь чародеев, а те принесли с собой источники тёмной силы – полуночные сферы." }, { 8.02, "Чародеи наносят чувствительные удары по защитникам Красногорья, и мы должны как можно скорее лишить их столь мощного оружия." }, { 16.91, "Добудь для меня полуночные сферы. Ты найдёшь их у чародеев Чёрной Горы." }, { 21.98, "Я придумаю, как избавиться от Сфер, чтобы мир стал лучше и чище!" } } }, t = { d = 4.7, v = "human-male", n = { x = 52 }, c = { x = { { 0.00, "Благодарю тебя. Я немедленно прикажу уничтожить эту мерзость." } } } } },
    [116] = { d = 26.1, v = "human-male", n = { x = 305 }, c = { x = { { 0.00, "У меня возникло небольшое затруднение. Ещё немного, и все бутылки опустеют, а поставок алкоголя давно не было. Проклятые орки. Не хочешь подзаработать?" }, { 10.97, "Принеси мне бочонок громоварского светлого от Мрачнобуха Громовара из Западного Края, бочонок \"Мерло\" из Штормграда, бутылку самогона из Темнолесья и бурдюк со сладким ромом из Златоземья, и я тебя непременно награжу." } } }, t = { d = 11.8, v = "human-male", n = { x = 142 }, c = { x = { { 0.00, "Отличная работа! Я представляю, сколько дорог тебе пришлось исходить, чтобы принести мне такое количество первосортных напитков." }, { 8.84, "Завсегдатаи трактира будут счастливы!" } } } } },
    [118] = { d = 16.3, v = "human-male#50", n = { x = 186 }, c = { x = { { 0.00, "Я потратил так много железа на доспехи и оружие для стражников Штормграда, что теперь его не хватает даже на подковы для лошадей!" }, { 8.96, "Отнеси эту записку кузнецу Аргусу в Златоземье, я хочу попросить его прислать мне партию подков." } } }, t = { d = 2.9, v = "human-male#50", n = { x = 31 }, c = { x = { { 0.00, "Так старому Вернеру нужны подковы, да?!" } } } } },
    [119] = { d = 14.3, v = "human-male#50", n = { x = 154 }, c = { x = { { 0.00, "Ладно, так и быть, пошлю ему пятьдесят подков…" }, { 3.61, "Вот они, уже упакованы, осталось только доставить! Передай Вернеру, что с ним приятно иметь дело." }, { 10.10, "Пусть не забудет прочитать записку, прикреплённую к ящику!" } } }, t = { d = 9.8, g = 1, v = "human-male#50", n = { m = 96, f = 98 }, c = { m = { { 0.00, "Спасибо, ты здорово мне помог." }, { 2.44, "Что это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф! Ладно, спасибо за помощь." } }, f = { { 0.00, "Спасибо, ты здорово мне помогла." }, { 2.62, "Что это? Аргус приложил к ящику записку... Что?! Аргус хочет ПЛАТЫ? Пф! Ладно, спасибо за помощь." } } } } },
    [120] = { d = 19.8, g = 1, v = "human-male", n = { x = 218 }, c = { m = { { 0.00, "Тяжёлые настали времена, герой. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять." }, { 8.18, "Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану." }, { 14.56, "И поскорее возвращайся с вестями – неважно, добрыми или злыми. Спеши!" } }, f = { { 0.00, "Тяжёлые настали времена, героиня. Город в непрерывной осаде. Если из Штормграда не пришлют подкрепление, нам не выстоять." }, { 8.42, "Я доверяю тебе важнейшее письмо. Отнеси его в Штормград генералу Маркусу Джонатану." }, { 14.80, "И поскорее возвращайся с вестями – неважно, добрыми или злыми. Спеши!" } } }, t = { d = 18.8, g = 1, v = "human-male", n = { x = 208 }, c = { m = { { 0.00, "Вольно, герой." }, { 1.45, "Чиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королём и объясню ему ситуацию." }, { 9.55, "Заверьте доброго судью, что он получит подержку армии Штормграда. Я вышлю подкрепления, как только получу приказ Его Величества." } }, f = { { 0.00, "Вольно, героиня." }, { 1.56, "Чиновник Соломон – благородный человек. Его слова много для меня значат. Я поговорю с королём и объясню ему ситуацию." }, { 9.65, "Заверьте доброго судью, что он получит подержку армии Штормграда. Я вышлю подкрепления, как только получу приказ Его Величества." } } } } },
    [121] = { d = 7.6, g = 1, v = "human-male", n = { m = 76, f = 78 }, c = { m = { { 0.00, "Пока я жду ответа от короля, хочу, чтобы ты отнёс это письмо мировому судье Соломону. Свободен, герой!" } }, f = { { 0.00, "Пока я жду ответа от короля, хочу, чтобы ты отнесла это письмо мировому судье Соломону. Свободна, героиня!" } } }, t = { d = 14.4, g = 1, v = "human-male", n = { x = 155 }, c = { m = { { 0.00, "Благодарю тебя, герой. В знак признательности Озёр и Штормграда прими эти деньги." }, { 6.06, "Хотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны." } }, f = { { 0.00, "Благодарю тебя, героиня. В знак признательности Озёр и Штормграда прими эти деньги." }, { 6.14, "Хотя, признаться, смысл этого письма туманен. Что-то неладно в нашем королевстве. Боюсь, это не конец, а начало войны." } } } } },
    [122] = { d = 24.2, v = "human-male#50", n = { x = 277 }, c = { x = { { 0.00, "В обмен на подковы Аргус из Златоземья просит брюшную чешую чёрных дракончиков." }, { 5.46, "Если ты добудешь мне шесть лоскутов чешуи, я смогу расплатиться с Аргусом... И для тебя что-нибудь сделаю." }, { 12.91, "Чёрных дракончиков можно отыскать к югу от Озёр, но им не сидится на одном месте." }, { 18.50, "Проще всего высматривать их, направляясь по другим делам, и охотиться по случаю." } } }, t = { d = 3.6, v = "human-male#50", n = { x = 39 }, c = { x = { { 0.00, "Спасибо! Теперь я смогу расплатиться с Аргусом..." } } } } },
    [123] = { d = 29.5, v = "human-male#114", n = { x = 308 }, c = { x = { { 0.00, "На этом листке – расписание поставок золота из рудников в Элвиннском лесу." }, { 5.59, "Поставки расписаны по дням и часам, а в качестве получателя указан некий \"Вымогатель\"." }, { 12.49, "Судя по всему, Вымогатель обосновался неподалёку от тыквенного поля Бреквеллов в восточной части Элвиннского леса." }, { 21.73, "Похоже, это важные сведения. Было бы неплохо сообщить их маршалу Дугхану: он сейчас в Златоземье." } } }, t = { d = 10.2, v = "human-male", n = { x = 116 }, c = { x = { { 0.00, "Хм... Я слышал об этом \"Собирателе\", вот только не знаю, на кого он работает." }, { 4.97, "Должен тебя поблагодарить: расписание поможет нам разгадать эту тайну..." } } } } },
    [124] = { d = 15.8, v = "human-male#50", n = { x = 187 }, c = { x = { { 0.00, "Будто нам одних орков мало! А теперь вдоль хребта рядом с моими стойлами шастают громилы и мистики гноллов и при случае воруют лошадей…" }, { 9.51, "Если ты сможешь избавить меня от этих проходимцев, мы с лошадьми будем весьма признательны." } } }, t = { d = 2.1, v = "human-male#50", n = { x = 21 }, c = { x = { { 0.00, "Благодарю тебя за помощь!" } } } } },
    [125] = { d = 23.4, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Мне не помешала бы помощь. Наш город в осаде, и достать припасы и оборудование всё труднее." }, { 6.44, "Мои инструменты везли из Златоземья в фургоне, но мост был уничтожен." }, { 11.25, "Мы перегрузили их в лодку, но тут орки пробили её снарядом из катапульты! И вот невезенье, ящик опустился на самое дно озера." }, { 20.34, "Достань его, и я щедро вознагражу тебя." } } }, t = { d = 5.0, v = "human-male", n = { x = 55 }, c = { x = { { 0.00, "Отличная работа! Я уж и не надеялся вновь увидеть свои инструменты." } } } } },
    [126] = { d = 24.2, v = "human-male#50", n = { x = 265 }, c = { x = { { 0.00, "Гноллы по-прежнему здесь. Я слышу, как они завывают, охотясь в холмах над Приозерьем." }, { 5.77, "И один из них воет громче других – это Изувой, их вождь." }, { 10.82, "Стоит его прикончить, и вся стая разбежится! Убей его и принеси в доказательство отрубленную лапу." }, { 17.87, "Соблюдай осторожность, этот гнолл заслуженно возглавляет целую стаю. Он совсем не прост..." } } }, t = { d = 10.3, v = "human-male#50", n = { x = 125 }, c = { x = { { 0.00, "И снова благодарю тебя за помощь. Штормград еле-еле справляется с орками, у них не хватает солдат, чтобы защищать Красногорье от напастей вроде гноллов." } } } } },
    [127] = { d = 16.7, g = 1, v = "human-male", n = { m = 181, f = 182 }, c = { m = { { 0.00, "Застывшее озеро славится пятнистой рыбой-луной. На неё всегда есть спрос... А мой запас подходит к концу!" }, { 7.58, "Принеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты сам не умеешь удить, то... Попытайся отнять рыбу у мурлоков!" } }, f = { { 0.00, "Застывшее озеро славится пятнистой рыбой-луной. На неё всегда есть спрос... А мой запас подходит к концу!" }, { 7.58, "Принеси мне штук десять рыбин, и я хорошо за них заплачу. Если ты сама не умеешь удить, то... Попытайся отнять рыбу у мурлоков!" } } }, t = { d = 3.6, v = "human-male", n = { x = 38 }, c = { x = { { 0.00, "Иметь с тобой дело – одно удовольствие, дружище!" } } } } },
    [128] = { d = 29.0, v = "human-male", n = { x = 326 }, c = { x = { { 0.00, "Мы должны уничтожить клан Чёрной Горы. Враг вторгся в наши земли. Эти горы по праву принадлежат королю Штормграда." }, { 7.98, "До нас дошли сведения, что главы всех видов войск клана называются воителями." }, { 13.36, "Их можно отыскать в северном лагере, к западу от дороги, ведущей в Пылающие степи." }, { 19.23, "Мировой судья Соломон распорядился перебить этих гнусных тварей." }, { 23.86, "Убей пятнадцать воителей из клана Чёрной Горы и возвращайся ко мне." } } }, t = { d = 7.5, g = 1, v = "human-male", n = { m = 76, f = 78 }, c = { m = { { 0.00, "Вижу, ты доблестно сражался с кланом Чёрной Горы, герой. Ты оказал нашему городу неоценимую услугу." } }, f = { { 0.00, "Вижу, ты доблестно сражалась с кланом Чёрной Горы, героиня. Ты оказала нашему городу неоценимую услугу." } } } } },
    [129] = { d = 20.9, v = "human-female", n = { x = 242 }, c = { x = { { 0.00, "Можешь оказать мне услугу? Я приготовила обед для стражника Паркера, но он ушёл на дежурство..." }, { 6.28, "Он-то может постоять за себя, но простой горожанке вроде меня не стоит соваться в те края." }, { 12.71, "Если ты отнесёшь ему обед, я бесплатно тебя накормлю! Паркер патрулирует участок дороги, ведущей в Сумеречный лес." } } }, t = { d = 7.8, v = "human-male", n = { x = 80 }, c = { x = { { 0.00, "Спасибо, вкусно и сытно покушать я люблю. Хранить Приозерье от нападений орков и гноллов нелегко!" } } } } },
    [130] = { d = 16.4, v = "human-male", n = { x = 176 }, c = { x = { { 0.00, "Если ты всё равно идёшь к Дарси, не отнесёшь ли ей от меня цветы?" }, { 4.55, "Букетик можно приобрести у травницы в Приозерье, в западной части города." }, { 9.98, "Только когда будешь покупать цветы…" }, { 12.85, "не говори травнице Марти, от кого они и кому..." } } }, t = { d = 14.4, g = 1, v = "human-female#47", n = { m = 164, f = 165 }, c = { m = { { 0.00, "Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашёл возлюбленную?" }, { 5.37, "Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена." } }, f = { { 0.00, "Тебе нужен букет цветов? Ты вроде бы у нас недавно... уже нашла возлюбленного?" }, { 5.42, "Понимаю, мне не следует совать нос не в своё дело, но приятно видеть витающую в воздухе любовь... особенно в такие опасные времена." } } } } },
    [131] = { d = 4.4, v = "human-female#47", n = { x = 47 }, c = { x = { { 0.00, "Вот и букет. Я выбрала для тебя нарциссы. Мои любимые цветы!" } } }, t = { d = 20.4, g = 1, v = "human-female", n = { m = 220, f = 222 }, c = { m = { { 0.00, "Какая прелесть! Надо поскорее поставить их в воду!" }, { 3.73, "Но... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не сказал, для кого они?" }, { 12.11, "Иначе не удивлюсь, если она их отравила." }, { 15.24, "Нет-нет, ты ни в чём не виноват. Большое спасибо! А вот и твой обед." } }, f = { { 0.00, "Какая прелесть! Надо поскорее поставить их в воду!" }, { 3.73, "Но... это любимые цветы Марти. Неужели Паркер послал тебя за букетом к этой ревнивой мегере? Ты ведь не сказала, для кого они?" }, { 12.13, "Иначе не удивлюсь, если она их отравила." }, { 15.27, "Нет-нет, ты ни в чём не виновата. Большое спасибо! А вот и твой обед." } } } } },
    [132] = { d = 20.8, v = "human-male#50", n = { x = 247 }, c = { x = { { 0.00, "То, о чём я хочу вам рассказать, может стоить мне жизни. Бандиты из Братства Справедливости замышляют что-то крупномасштабное." }, { 8.37, "Последнее, что я слышал, – что они действуют заодно со всякими гноллами, кобольдами и даже гоблинами." }, { 15.27, "Отнеси эту записку Камнегриву. В ней разъясняется всё, что я знаю на эту тему." } } }, t = { d = 8.9, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Эх!.. Надо было сгноить этого мошенника, когда у меня был шанс. Но эта информация действительно очень важна. Хорошая работа." } } } } },
    [133] = { d = 32.0, v = "human-male", n = { x = 362 }, c = { x = { { 0.00, "Я живу вдали от города, никто меня не защищает, и даже странно, как это меня до сих пор не сожрали вурдалаки и мертвяки!" }, { 8.39, "Только вчера несколько костеглодов ломились ко мне в дом!.." }, { 12.76, "Я хочу сделать особую фигурку – что-то вроде пугала для этой нежити. Для этого мне понадобится несколько рёбер вурдалаков." }, { 21.27, "Их можно добыть, убивая плотоядов, костеглодов, мозгоедов, гнилую нежить и распространителей чумы." }, { 28.40, "Принеси мне рёбра, и я дам тебе несколько монет." } } }, t = { d = 3.0, v = "human-male", n = { x = 29 }, c = { x = { { 0.00, "О, спасибо. Это наверняка сработает!" } } } } },
    [134] = { d = 23.5, v = "human-male", n = { x = 259 }, c = { x = { { 0.00, "Несколько недель назад я собирал травы вдали от дома, и на меня напал отряд огров!" }, { 5.82, "Я сбежал, бросив свой ящик с ценными инструментами и травами." }, { 10.39, "Прогнав меня, они вернулись к своему кургану в южной части Сумеречного леса. Думаю, они оставили мой ящик неподалёку от кургана." }, { 19.66, "Прошу тебя, верни мне ящик, без него я как без рук." } } }, t = { d = 8.6, v = "human-male", n = { x = 88 }, c = { x = { { 0.00, "Хвала Нек... то есть ТЕБЕ! Ты более чем заслуживаешь награды." }, { 4.57, "Ага! Как я счастлив! Впереди много радостных ночей!" } } } } },
    [135] = { d = 27.2, v = "human-male", n = { x = 316 }, c = { x = { { 0.00, "Интересно, что имел в виду Вилли, когда упомянул о Каменщиках. Оговорился или проговорился?" }, { 6.43, "Могут ли разбойники из Братства Справедливости быть связаны с Каменщиками?" }, { 11.67, "Только один человек должен знать наверняка: Матиас Шоу, глава ШРУ." }, { 16.39, "Покажите ему записку Вилли и посмотрите, сможет ли он пролить свет на эту тайну." }, { 21.89, "Если вам не сразу удастся найти Шоу, поищите в Казармах в Старом городе." } } }, t = { d = 4.7, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Это дело может оказаться сложнее, чем полагает Камнегрив." } } } } },
    [136] = { d = 35.6, v = "human-male#114", n = { x = 369 }, c = { x = { { 0.00, "Если ты читаешь это – значится, старина капитан Сандерс уже покоится на дне." }, { 5.73, "Так что моё сокровище теперь может стать твоим, главное – следуй подсказкам." }, { 11.91, "Сначала найди мой сундучок. Его, должно быть, уже наполовину песком занесло, а находится он на западном побережье Западного Края рядом с обломками корабля." }, { 23.89, "Обломков-то там много, но ржавый якорь на берегу – только один. Найди этот якорь, и ты найдёшь мой сундучок." }, { 32.41, "Загляни внутрь за следующей подсказкой." } } }, t = { d = 14.2, v = "human-male#114", n = { x = 145 }, c = { x = { { 0.00, "Сундучок медленно, со скрипом, открывается. Кажется, ничего в нём нет, кроме песка и воды. Постойте-ка!" }, { 7.97, "Проворно выползает маленький крабик, а в клешнях у него – следующая подсказка!" } } } } },
    [138] = { d = 18.1, v = "human-male#114", n = { x = 185 }, c = { x = { { 0.00, "Ключ к поиску сокровища таков: \"Отличная работа, приятель! Теперь тебе идти на восток. На восток в холмы, на восток к дороге." }, { 9.50, "Ищи на обочине дороги развалины старого очага. Там найдёшь старую бочку, в которой и будет следующий ключ\"." } } }, t = { d = 3.6, g = 1, v = "human-male#114", n = { m = 34, f = 35 }, c = { m = { { 0.00, "Отличная работа, охотник за сокровищами!" } }, f = { { 0.00, "Отличная работа, охотница за сокровищами!" } } } } },
    [139] = { d = 23.2, v = "human-male#114", n = { x = 243 }, c = { x = { { 0.00, "Обыскивая бочку, вы обнаруживаете ещё один кусок пергамента. На нём написано: \"А теперь от этой бочки поверни к северу." }, { 9.11, "Прямо, как ворон летит, иди, пока не наткнёшься на пустой кувшин рядом с одинокой ветряной мельницей на прибрежных утёсах." }, { 18.54, "Осмотри кувшин внимательно – может, и найдёшь то, что ищешь\"." } } }, t = { d = 4.3, g = 1, v = "human-male#114", n = { m = 38, f = 42 }, c = { m = { { 0.00, "Ты на пути к главному призу, искатель сокровищ!" } }, f = { { 0.00, "Ты на пути к главному призу, искательница сокровищ!" } } } } },
    [140] = { d = 33.2, g = 1, v = "human-male#114", n = { m = 344, f = 345 }, c = { m = { { 0.00, "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса." }, { 7.60, "Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашёл мой старый кувшин из-под виски, значит, ты близко подобрался к сокровищу!" }, { 20.83, "Иди от бутылки на запад и спустись к берегу. Доберёшься до воды – не останавливайся!" }, { 27.21, "Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!" } }, f = { { 0.00, "Конечно же, глубоко внутри старого кувшина лежит ещё одна подсказка к поиску сокровища Сандерса." }, { 7.60, "Чернила кое-где расплылись, а бумага отдаёт виски, но кое-что вам удалось разобрать: \"Раз уж ты нашла мой старый кувшин из-под виски, значит, ты близко подобралась к сокровищу!" }, { 21.11, "Иди от бутылки на запад и спустись к берегу. Доберёшься до воды – не останавливайся!" }, { 27.48, "Плыви, пока не найдёшь остров, где и находится мой сундук с сокровищем!" } } }, t = { d = 9.9, v = "human-male#114", n = { x = 103 }, c = { x = { { 0.00, "Петли на крышке старого сундука заржавели, но поддаются. Вы с усилием открываете сундук и забираете сокровище. Поздравляем!" } } } } },
    [141] = { d = 32.0, v = "human-male", n = { x = 375 }, c = { x = { { 0.00, "Гильдию каменщиков возглавлял человек по имени Эдвин ван Клиф." }, { 4.40, "Именно он занимался восстановлением Штормграда после разорения его орками во время Первой войны." }, { 11.12, "Должно быть, ван Клиф и его люди остались недовольны тем, как с ними обошёлся король, когда восстановление города было завершено." }, { 19.95, "Это могло бы объяснить пару вещей." }, { 22.75, "Я тут расписал всё более подробно для вашего начальства в Западном Крае. Сразу же отправляйтесь туда и передайте ему документ!" } } }, t = { d = 15.1, v = "human-male", n = { x = 174 }, c = { x = { { 0.00, "Эдвин ван Клиф... Мне хорошо известно это имя." }, { 3.47, "Обидно думать, что этот трудолюбивый и талантливый человек мог превратиться в такого мерзавца." }, { 9.90, "Мне понадобятся дополнительные доказательства, чтобы я поверил в это." } } } } },
    [142] = { d = 23.7, g = 1, v = "human-male", n = { x = 271 }, c = { m = { { 0.00, "Нам нужно выяснить местонахождение Убежища Братства Справедливости." }, { 4.80, "путник, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости." }, { 15.34, "Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено." } }, f = { { 0.00, "Нам нужно выяснить местонахождение Убежища Братства Справедливости." }, { 4.80, "путница, мой разведчик сообщает, что на дороге между Луноречьем, Прииском на Золотом Берегу и Рудником Янго видели вестника из Братства Справедливости." }, { 15.13, "Я хочу, чтобы вы его поймали. Если он окажет сопротивление, убейте его и принесите мне то, что будет у него найдено." } } }, t = { d = 30.7, v = "human-male", n = { x = 357 }, c = { x = { { 0.00, "Вот явное доказательство того, что ими верховодит ван Клиф. Теперь всё, что нам нужно узнать, – это где прячутся бандиты братства." }, { 9.27, "Нам тут немного повезло, пока вас не было. Мы поймали вора, пытавшегося украсть повозку Сальдена." }, { 16.03, "Он пообещал навести нас на убежище бандитов в обмен на жизнь." }, { 20.29, "Я прошу вас защитить его, чтобы предатель братства мог указать, где находится убежище." }, { 26.22, "Возвращайтесь ко мне, когда выясните местонахождение убежища." } } } } },
    [143] = { d = 32.1, v = "human-male", n = { x = 365 }, c = { x = { { 0.00, "Что-то странное происходит в армии Штормграда, подкрепления всё нет и нет. К сожалению, мы не можем позволить себе ждать." }, { 8.48, "Нельзя же сидеть сложа руки и не пытаться позвать соседей на помощь, пока доблестные воины Приозерья погибают один за другим." }, { 18.03, "Говорят, в Западном Крае создано народное ополчение." }, { 22.02, "Отнеси мою просьбу о помощи его предводителю, Гриану Камнегриву." }, { 26.39, "Может быть, его люди помогут нам продержаться до подхода королевских отрядов." } } }, t = { d = 4.1, g = 1, v = "human-male", n = { m = 44, f = 46 }, c = { m = { { 0.00, "Добрый вестник, ты хорошо послужил своему господину." } }, f = { { 0.00, "Добрая вестница, ты хорошо послужила своему господину." } } } } },
    [144] = { d = 25.2, g = 1, v = "human-male", n = { x = 280 }, c = { m = { { 0.00, "Меня очень огорчило письмо мирового судьи Соломона." }, { 3.53, "К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас." }, { 9.92, "Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы." }, { 16.53, "Отнеси мой ответ в Красногорье, герой, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов." } }, f = { { 0.00, "Меня очень огорчило письмо мирового судьи Соломона." }, { 3.53, "К сожалению, он не ведает о войне, начавшейся в Западном Крае, иначе не ждал бы помощи от нас." }, { 9.92, "Нам самим без ополчения не обойтись, потому что Штормград бросил нас на произвол судьбы." }, { 16.53, "Отнеси мой ответ в Красногорье, героиня, и передай своему хозяину, что я скорблю всем сердцем о гибели отважных бойцов." } } }, t = { d = 22.6, g = 1, v = "human-male", n = { m = 255, f = 256 }, c = { m = { { 0.00, "Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими." }, { 6.47, "Что же отвлекает армию Штормграда от защиты её собственных земель? Впрочем, зря я об этом говорю вслух." }, { 13.87, "Вот, вестник. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься." } }, f = { { 0.00, "Что сказать, вести недобрые. Я и не подозревал, что у Камнегрива трудности, схожие с нашими." }, { 6.47, "Что же отвлекает армию Штормграда от защиты её собственных земель? Впрочем, зря я об этом говорю вслух." }, { 13.87, "Вот, вестница. Прими эти монеты в знак благодарности за верную службу городу. Быть может, скоро ты мне снова понадобишься." } } } } },
    [145] = { d = 22.0, v = "human-male", n = { x = 257 }, c = { x = { { 0.00, "И снова мне нужна твоя помощь. Я написал письмо лорду Чернодреву, прося его прислать нам на помощь обученных бойцов Ночного дозора на защиту Озёр." }, { 10.18, "Надо как можно скорее доставить моё послание. Действуй осторожно." }, { 14.69, "Лорд Чернодрев – мэр города Темнолесья, расположенного в сердце Сумеречного леса. Не сходи с дороги." } } }, t = { d = 4.3, v = "human-male", n = { x = 43 }, c = { x = { { 0.00, "Благодарю за проделанный путь. Вести и верно важные." } } } } },
    [146] = { d = 28.6, v = "human-male", n = { x = 311 }, c = { x = { { 0.00, "Не знай я мирового судью Соломона лично, решил бы, что он сошёл с ума." }, { 4.83, "Послать в Приозерье Ночной дозор, потому что Штормград отказал в помощи?" }, { 9.72, "Мы и создали его, когда земли наводнила нечистая магия, а Штормград бросил нас на произвол судьбы." }, { 17.89, "Если я пошлю в Приозерье Ночной дозор, то наш город падёт, едва лишь Дозор доберётся до края леса." }, { 25.09, "Отнеси мой ответ своему господину в Приозерье." } } }, t = { d = 21.0, g = 1, v = "human-male", n = { x = 226 }, c = { m = { { 0.00, "Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так?" }, { 9.98, "О, я забыл отблагодарить тебя за услуги, герой. Прими вот эту плату. А теперь извини меня." }, { 16.31, "Что-то творится в Штормграде, и я должен докопаться до сути." } }, f = { { 0.00, "Во имя Света! Армия Штормграда отступила из Западного Края. И Дозор не сможет защищать Темнолесье? Здесь таится предательство. Как же так?" }, { 9.98, "О, я забыл отблагодарить тебя за услуги, героиня. Прими вот эту плату. А теперь извини меня." }, { 16.52, "Что-то творится в Штормграде, и я должен докопаться до сути." } } } } },
    [147] = { d = 24.4, v = "human-male", n = { x = 287 }, c = { x = { { 0.00, "Если Вымогатель забирает золото с наших рудников, значит, он обворовывает королевство!" }, { 5.91, "Он должен предстать перед судом – а мне понадобится то кольцо, которое упоминалось в записке." }, { 12.25, "Возможно, оно поможет нам узнать, на кого работает этот Вымогатель..." }, { 17.25, "Здесь написано, что Вымогатель скрывается на тыквенном поле Бреквеллов. Попробуй поискать его там." } } }, t = { d = 29.4, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "Так тебе удалось его найти? Отлично, просто прекрасно! Больше он ничего не будет \"вымогать\" на Элвиннских шахтах!" }, { 8.18, "А это кольцо... О, очень интересно! Это кольцо древнего братства Каменщиков Штормграда." }, { 15.26, "С чего бы это мелкому воришке носить кольцо гильдии? И как вышло, что Братство Справедливости добывает золото на наших рудниках?" }, { 24.57, "Непростые вопросы, верно? Надеюсь, когда-нибудь мы узнаем ответ." } } } } },
    [148] = { d = 22.1, g = 1, v = "human-male", n = { m = 238, f = 240 }, c = { m = { { 0.00, "Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели." }, { 10.87, "Не мог бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос?" }, { 16.19, "Её можно приобрести у мадам Евы, которая живёт на центральной площади города." } }, f = { { 0.00, "Как же быть несчастному старику?.. Мне нужно привезти кое-что из Темнолесья, но деревня так далеко, а я стар и слаб... Мне не добраться до цели." }, { 10.87, "Не могла бы ты отправиться в Темнолесье и привезти мне нить из призрачных волос?" }, { 16.31, "Её можно приобрести у мадам Евы, которая живёт на центральной площади города." } } }, t = { d = 9.5, v = "human-female#45", n = { x = 106 }, c = { x = { { 0.00, "А, так тебе нужна нить из призрачных волос? Боюсь, мои запасы иссякли, но я могу сделать ещё..." }, { 6.42, "Если ты принесёшь мне призрачные волосы." } } } } },
    [149] = { d = 22.8, g = 1, v = "human-female#45", n = { m = 261, f = 261 }, c = { m = { { 0.00, "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри." }, { 6.98, "Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы." }, { 11.89, "Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити." }, { 18.27, "Будь осторожен, рядом с домом бродит множество тёмных тварей." } }, f = { { 0.00, "На старой ферме, в холмах к югу от Темнолесья, живёт несчастное привидение по имени Слепая Мэри." }, { 6.98, "Возьми этот призрачный гребень и попроси Слепую Мэри расчесать волосы." }, { 11.89, "Потом принеси гребень обратно, и я сниму с него призрачные волосы, необходимые для нити." }, { 18.27, "Будь осторожна, рядом с домом бродит множество тёмных тварей." } } }, t = { d = 14.7, v = "scourge-female", n = { x = 127 }, c = { x = { { 0.00, "Что это? Гребень? Какая прелесть! И он спокойно скользит по моим волосам, хотя они давно сбились в ужасный слипшийся колтун." }, { 11.26, "Ах, мне бы в зеркало посмотреться..." } } } } },
    [150] = { d = 19.0, v = "human-male", n = { x = 214 }, c = { x = { { 0.00, "Мурлоки начинают нас беспокоить. Всё больше мурлокских рыбаков селится вдоль побережья Озера Безмолвия и вовсю ловит рыбу!" }, { 8.53, "Надо изгнать их, пока они не опустошили всё озеро!" }, { 12.54, "Убей побольше мурлоков! Принеси мне восемь их плавников, и я найду, чем тебе отплатить..." } } }, t = { d = 10.9, v = "human-male", n = { x = 104 }, c = { x = { { 0.00, "Молодец. Надеюсь, тебе не слишком солоно пришлось." }, { 3.91, "Странно, что они ушли так далеко от моря. Хотелось бы знать, отчего они сбежали..." } } } } },
    [151] = { d = 35.2, g = 1, v = "human-female", n = { m = 416, f = 417 }, c = { m = { { 0.00, "Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений..." }, { 6.81, "Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге." }, { 13.24, "Я была бы вам очень благодарна, сэр, если бы вы могли принести ей несколько горстей овса с окрестных полей." }, { 20.79, "Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях." }, { 30.49, "К юго-западу отсюда расположено несколько фермерских хозяйств." } }, f = { { 0.00, "Бедная старая Савраска! Несчастная лошадка так устала от непосильного труда и бесчисленных лишений..." }, { 6.81, "Я её покормила перед тем, как уехать с фермы, но мы не ожидали, что повозка сломается по дороге." }, { 13.24, "Я была бы вам очень благодарна, леди, если бы вы могли принести ей несколько горстей овса с окрестных полей." }, { 20.87, "Уверена, что вы найдёте овёс на любой ферме в Западном Крае, если только сумеете увернуться от этих ужасных машин, которые буйствуют на полях." }, { 30.58, "К юго-западу отсюда расположено несколько фермерских хозяйств." } } }, t = { d = 5.1, v = "human-female", n = { x = 59 }, c = { x = { { 0.00, "Огромное тебе спасибо! Бедная старая Савраска будет просто счастлива!" } } } } },
    [152] = { d = 28.0, g = 1, v = "human-male", n = { m = 308, f = 309 }, c = { m = { { 0.00, "Ты, должно быть, видел все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово." }, { 7.31, "Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности." }, { 15.51, "На сегодняшний день мурлоки являются большой проблемой..." }, { 19.64, "Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя." } }, f = { { 0.00, "Ты, должно быть, видела все эти обломки кораблей вдоль побережья. Великое море и в самом деле очень сурово." }, { 7.41, "Береговую линию Западного Края нужно держать чистой, чтобы моряки, если приплывут к нашим берегам, были в безопасности." }, { 15.61, "На сегодняшний день мурлоки являются большой проблемой..." }, { 19.74, "Разберись с ними – убей семь волноловов, семь воинов, семь оракулов и семь береговиков, – и награда будет ждать тебя." } } }, t = { d = 8.6, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Хорошая работа. У тебя отличные боевые навыки! Благодаря тебе побережье Западного Края стало более безопасным местом." } } } } },
    [153] = { d = 20.5, v = "human-male", n = { x = 229 }, c = { x = { { 0.00, "В Братстве Справедливости идёт постоянная кипучая деятельность. Я уже долго слежу за их передвижениями." }, { 7.15, "Между прочим, я заметил, что многих бандитов можно опознать по красным кожаным банданам." }, { 13.65, "Принесите мне пятнадцать таких бандан, и я позабочусь о том, чтобы вы получили вознаграждение." } } }, t = { d = 6.6, v = "human-male", n = { x = 75 }, c = { x = { { 0.00, "Хорошая работа. Пожалуйста, примите один из этих предметов в качестве оплаты за ваши труды." } } } } },
    [154] = { d = 10.0, v = "scourge-female", n = { x = 76 }, c = { x = { { 0.00, "НЕТ!!!" }, { 0.89, "Убери его, убери от меня этот гребень!" }, { 4.84, "Я чудовище, меня больше никто не назовёт прекрасной!" } } }, t = { d = 10.0, v = "human-female#45", n = { x = 112 }, c = { x = { { 0.00, "Ну, из этого выйдет целая катушка нити из призрачных волос, да ещё и останется несколько прядей." }, { 6.67, "Прими эти монеты в уплату за лишние пряди." } } } } },
    [155] = { d = 30.5, g = 1, v = "human-male", n = { m = 329, f = 329 }, c = { m = { { 0.00, "Так Камнегрив считает, что такой слабый герой сможет меня защитить? А ведь придётся. Возьми-ка с собой пару-тройку друзей." }, { 8.82, "Ты же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе." }, { 17.63, "Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить." }, { 24.43, "Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти." } }, f = { { 0.00, "Так Камнегрив считает, что такая слабая героиня сможет меня защитить? А ведь придётся. Возьми-ка с собой пару-тройку друзей." }, { 9.56, "Ты же знаешь, что делать, да? Ты прикрываешь мою спину, а я веду тебя к убежищу Братства Справедливости. Держись ко мне поближе." }, { 18.37, "Бандиты братства охотятся за моей головой. Если нас увидят вместе, они попытаются меня убить." }, { 25.18, "Дай мне знать, когда ты и друзья, которых ты соберёшь, будут готовы идти." } } }, t = { d = 5.9, g = 1, v = "human-male", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Великолепно, сэр путник! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!" } }, f = { { 0.00, "Великолепно, леди путница! Теперь, когда мы знаем, где прячется ван Клиф, – он наш!" } } } } },
    [156] = { d = 25.5, v = "human-male#50", n = { x = 301 }, c = { x = { { 0.00, "Если ты принесёшь мне несколько цветков гнили, я сделаю для тебя сок зомби." }, { 5.45, "Цветки гнили растут в самых странных местах. Например, в черепах ужасных скелетов и скелетов-губителей... хотя я лично туда не заглядывал!" }, { 14.96, "Кладбище Вороньего холма и Безмятежное кладбище кишмя кишат этими скелетами. Заодно ты и нас от них избавишь." }, { 22.37, "Темнолесье будет тебе весьма признательно." } } }, t = { d = 20.7, g = 1, v = "human-male#50", n = { m = 249, f = 250 }, c = { m = { { 0.00, "Отлично, ты сумел добыть цветки гнили." }, { 2.68, "А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов." }, { 9.53, "Ночной дозор охраняет покой Темнолесья, и им нелегко приходится." }, { 13.83, "Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех." } }, f = { { 0.00, "Отлично, ты сумела добыть цветки гнили." }, { 2.62, "А я расскажу Альтее Чернодрев из Ночного дозора, что тебе удалось уничтожить несколько скелетов." }, { 9.47, "Ночной дозор охраняет покой Темнолесья, и им нелегко приходится." }, { 13.77, "Разумеется, вести о добровольцах, помогающих остановить нашествие нечисти, будут отрадой для всех." } } } } },
    [157] = { d = 9.7, v = "human-female#45", n = { x = 103 }, c = { x = { { 0.00, "Вот тебе нитки. Им можно найти тысячи способов применения – от связывания злых духов до зашивания жизни в бездушные предметы." } } }, t = { d = 8.2, g = 1, v = "human-male", n = { x = 82 }, c = { m = { { 0.00, "Великолепно! Она прекрасно подойдёт…" }, { 3.05, "Вот, дражайший путник, прими это в уплату за благороднейший поступок." } }, f = { { 0.00, "Великолепно! Она прекрасно подойдёт…" }, { 3.05, "Вот, дражайший путница, прими это в уплату за благороднейший поступок." } } } } },
    [158] = { d = 15.3, v = "human-male", n = { x = 175 }, c = { x = { { 0.00, "Мне нужна бутылка особого напитка – сока зомби." }, { 3.30, "У хозяина темнолесской таверны \"Алый ворон\" Смиттса наверняка найдётся лишняя бутылочка." }, { 9.68, "Торопись. Ночи стоят холодные, и мне не терпится снова наполнить жилы огнём." } } }, t = { d = 6.7, v = "human-male#50", n = { x = 76 }, c = { x = { { 0.00, "Значит, тебе нужен сок зомби? Хм... это довольно крепкий напиток, обычно его у меня не заказывают." } } } } },
    [159] = { d = 6.2, g = 1, v = "human-male#50", n = { m = 63, f = 63 }, c = { m = { { 0.00, "А вот и сок зомби…" }, { 1.65, "Будь с ним осторожен. Он такой крепкий, что мёртвого поднимет!" } }, f = { { 0.00, "А вот и сок зомби…" }, { 1.65, "Будь с ним осторожна. Он такой крепкий, что мёртвого поднимет!" } } }, t = { d = 9.4, v = "human-male", n = { x = 101 }, c = { x = { { 0.00, "Тысяча благодарностей. Твоя глу... то есть твоя доброта согрела сердце старика!" }, { 5.75, "Вот, друг, прими это в знак моей благодарности." } } } } },
    [160] = { d = 14.4, g = 1, v = "human-male", n = { m = 152, f = 153 }, c = { m = { { 0.00, "Отнеси эту записку Элло Чернодреву, мэру Темнолесья." }, { 4.09, "Мы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня сделал..." }, { 9.82, "не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!" } }, f = { { 0.00, "Отнеси эту записку Элло Чернодреву, мэру Темнолесья." }, { 4.09, "Мы с ним старые друзья... И когда он прочитает это и узнает, что ты для меня сделала..." }, { 9.87, "не сомневаюсь, он будет счастлив не меньше меня! Ха-ха-ха!!!" } } }, t = { d = 7.0, v = "human-male", n = { x = 73 }, c = { x = { { 0.00, "Элло рассматривает письмо..." }, { 2.19, "Что это за язык? Похоже, какой-то древний... Не могу его прочитать." } } } } },
    [161] = { d = 26.7, v = "dwarf-male", n = { x = 311 }, c = { x = { { 0.00, "Если мои подозрения верны, то это взрывчатый порошок." }, { 3.74, "Его следует показать специалистам, чтобы выяснить, с чем именно мы имеем дело." }, { 9.04, "Ашлана Камнехмыла направили в полк, охраняющий Дун Модр и мост Тандола. Путь предстоит нелёгкий и опасный." }, { 16.69, "Пройди через врата Альгаза, по дороге, ведущей через Болотину, и отыщи Камнехмыла в Дун Модре." }, { 23.15, "Советую не сходить с дороги и не задерживаться." } } }, t = { d = 3.1, v = "dwarf-male", n = { x = 32 }, c = { x = { { 0.00, "Да, старина Плотина не зря беспокоится." } } } } },
    [163] = { d = 20.6, v = "human-female#45", n = { x = 232 }, c = { x = { { 0.00, "Что-то неладно на Вороньем холме. Калор клянётся, что он заметил кого-то – или что-то – в одном из домов." }, { 7.07, "Две ночи подряд он видел крадущиеся тени, а на третью – свет в одном из окон." }, { 12.54, "Если тебя и в самом деле беспокоит безопасность Темнолесья, выясни, что за чудовище скрывается на Вороньем холме." } } }, t = { d = 12.1, v = "human-male", n = { x = 132 }, c = { x = { { 0.00, "Нет! Прошу, не убивай меня! Это всего лишь я... Трясунчик! Они повсюду... Мне не скрыться! Чудовища на Вороньем холме? Н-н-нет..." }, { 8.46, "не может быть. Всего лишь безвредный Трясунчик." } } } } },
    [164] = { d = 15.1, v = "human-female#45", n = { x = 172 }, c = { x = { { 0.00, "Ты знаешь Свена? Вот кто настоящий служитель Света! Он и его последователи стоят лагерем в северо-западной части Сумеречного леса." }, { 9.32, "Увы, их так мало, что некого отправить за припасами в город. Не поможешь ли ты ему?" } } }, t = { d = 7.4, v = "human-male", n = { x = 83 }, c = { x = { { 0.00, "Припасы нам очень пригодятся. Семья Кэрвинов не оставляет нас без помощи. Вот, прими награду за труды." } } } } },
    [165] = { d = 15.9, v = "human-female#45", n = { x = 185 }, c = { x = { { 0.00, "Одно время в город частенько приходил старик и покупал припасы, но в последнее время я его не видела." }, { 6.82, "Он живёт в хижине рядом с кладбищем Вороньего холма, если я верно запомнила. Не навестишь ли ты его? Вдруг с ним что-то случилось?" } } }, t = { d = 13.2, v = "human-male", n = { x = 139 }, c = { x = { { 0.00, "Илана Карвин? Хе-хе, да, разумеется, Карвин." }, { 3.40, "Нет, со мной всё в порядке, но мне трудновато ходить в город. Дороги нынче опасные, а я не молодею." }, { 10.26, "Может, ты окажешь старику пару услуг?" } } } } },
    [166] = { d = 19.7, v = "human-male", n = { x = 234 }, c = { x = { { 0.00, "Осталось одно, последнее задание. Эдвин ван Клиф должен умереть." }, { 4.51, "Хотя меня печалит сам факт вынесения человеку смертного приговора, для всего народа Западного Края будет гораздо лучше, если ван Клиф упокоится навечно." }, { 14.98, "Принесите мне голову этого негодяя, когда с ним будет покончено." } } }, t = { d = 18.6, v = "human-male", n = { x = 221 }, c = { x = { { 0.00, "Вы проявили удивительную храбрость. Народное ополчение благодарит вас за службу народу Западного Края." }, { 7.19, "Смерть Эдвина ван Клифа станет началом конца для Братства Справедливости." }, { 12.33, "Надеюсь, недалёк тот прекрасный день, когда мир вновь снизойдёт на эту честную землю." } } } } },
    [167] = { d = 29.0, v = "dwarf-male", n = { x = 334 }, c = { x = { { 0.00, "Мы находились в обширных шахтах Западного Края, скрытых глубоко под землями Луноречья." }, { 6.00, "Понятия не имею, откуда явились эти мерзкие вороватые вонючки. Так или иначе – туннель обрушился на нас." }, { 13.05, "Мне удалось выбраться, но остальные... о них я ничего не знаю." }, { 17.52, "Вдруг тебе повезёт больше, чем мне? Я ищу своего брата. Он всегда носил значок Лиги Исследователей." }, { 24.36, "Если ты не найдёшь брата, постарайся найти хотя бы его значок." } } }, t = { d = 8.7, v = "dwarf-male", n = { x = 100 }, c = { x = { { 0.00, "Мои подозрения оправдались. Бедный мой брат... Что ж, благодарю. Определённость лучше загадок, даже если она лишает надежды." } } } } },
    [168] = { d = 19.2, v = "dwarf-male", n = { x = 224 }, c = { x = { { 0.00, "Многие из моих друзей погибли в тот роковой день, когда обрушился штрек." }, { 5.06, "Если тебя как-нибудь занесёт в ту шахту в Луноречье, пожалуйста, постарайся добыть что-то, что поможет их опознать." }, { 12.84, "А если найдёшь их карточки Союза шахтёров, принеси их мне, я отправлю их семьям погибших." } } }, t = { d = 9.3, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Спасибо тебе. Твоя помощь в посмертном успокоении жертв этой чудовищной трагедии была неоценимой. Их семьи будут тебе признательны." } } } } },
    [169] = { d = 32.9, v = "human-male#114", n = { x = 357 }, c = { x = { { 0.00, "Розыск! Гат'Илзогг, вождь клана Чёрной Горы, разыскивается за нападение на крепость Каменной Стражи и набеги на окрестности Приозерья." }, { 10.74, "Гат'Илзогг крайне опасен. По последним сведениям, он находится в недавно захваченной крепости и замышляет новые преступления против Королевства." }, { 21.77, "Нашествие орков должно быть остановлено любой ценой." }, { 25.67, "Храбрец, доставивший голову Гат'Илзогга мировому судье Соломону, будет щедро вознаграждён." } } }, t = { d = 13.1, v = "human-male", n = { x = 149 }, c = { x = { { 0.00, "Великолепная работа! Гат'Илзогг вёл своих громил в бой, и они убивали ни в чём не повинных людей. Мы отомстили ему." }, { 8.00, "Это первый шаг на пути возвращения крепости королевству Штормграда!" } } } } },
    [170] = { d = 36.1, g = 1, v = "dwarf-male", n = { m = 392, f = 392 }, c = { m = { { 0.00, "Надеюсь, ты оказался здесь не случайно, герой." }, { 3.16, "Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес." }, { 9.28, "Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались." }, { 15.42, "Говорят, их полно в горах на юго-востоке и возле замёрзшего озера." }, { 20.30, "Так ведь и это ещё не всё! Недавно они напали на наш лагерь на западе и разгромили его!" }, { 26.63, "Нам и так воинов не хватает, а тут ещё эти гады... Послушай, приятель, может, ты нам поможешь?" }, { 32.94, "Боюсь, иначе нам троггов не одолеть..." } }, f = { { 0.00, "Надеюсь, ты оказалась здесь не случайно, героиня." }, { 3.46, "Не буду лукавить: после недавнего нападения троггов для нас любая помощь – дар небес." }, { 9.58, "Я слышал, что эти мерзавцы теперь повсюду лезут – ну и до Холодной долины тоже добрались." }, { 15.72, "Говорят, их полно в горах на юго-востоке и возле замёрзшего озера." }, { 20.60, "Так ведь и это ещё не всё! Недавно они напали на наш лагерь на западе и разгромили его!" }, { 26.93, "Нам и так воинов не хватает, а тут ещё эти гады... Послушай, подруга, может, ты нам поможешь?" }, { 33.19, "Боюсь, иначе нам троггов не одолеть..." } } }, t = { d = 15.1, v = "dwarf-male", n = { x = 164 }, c = { x = { { 0.00, "Если повсюду происходит то же, что и здесь, у нас, то, клянусь бородой Магни, нас ждёт большая беда!" }, { 6.86, "Остаётся надеяться, что король и Совет придумают, что делать с этими проклятыми троггами, иначе нам конец." } } } } },
    [172] = { d = 28.9, v = "orc-female#57", c = { x = { { 0.00, "Ты хочешь помочь сиротам? Да благословят тебя боги! Твоя помощь во время Детской недели будет очень кстати!" }, { 8.06, "Вот, возьми эту свистульку. Действовать она будет недолго – до конца Детской недели." }, { 14.00, "Свистни в неё – и появится сирота, за которым ты обещаешь присматривать. Свистни ещё раз – ребёнок уйдёт." }, { 21.65, "Прошу тебя, пользуйся свистулькой почаще, не забывай своего подопечного! Для детей это так важно..." } } }, t = { d = 23.1, g = 1, v = "child-male", n = { m = 288, f = 292 }, c = { m = { { 0.00, "Заг-заг! Меня зовут Грент. Ты теперь мой опекун, да? Ты ищешь приключений, совсем как мои мама с папой!" }, { 6.88, "Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться!" }, { 12.75, "А мы теперь будем всё делать вместе?" }, { 14.93, "Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старший брат. Вот здорово!" } }, f = { { 0.00, "Заг-заг! Меня зовут Грент. Ты теперь моя опекунша, да? Ты ищешь приключений, совсем как мои мама с папой!" }, { 6.49, "Наша попечительница говорит, что они с честью погибли в бою! Я так рад с тобой познакомиться!" }, { 12.37, "А мы теперь будем всё делать вместе?" }, { 14.55, "Мне столько всего хочется сделать, а попечительница говорила, ты мне в эту неделю будешь всё равно как старшая сестра. Вот здорово!" } } } } },
    [173] = { d = 33.5, g = 1, v = "human-male", n = { m = 377, f = 378 }, c = { m = { { 0.00, "На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом." }, { 5.69, "Благодаря нашим усилиям народ Темнолесья живёт в безопасности." }, { 10.23, "Ты считаешь, что достоин вступить в наши ряды?" }, { 13.77, "Когда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина." }, { 21.37, "Если ты хочешь показать, на что способен, то слова тебе не помощники." }, { 26.60, "Выступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду." } }, f = { { 0.00, "На Сумеречный лес наступают силы тьмы, и цель мастера Кэрвина – борьба с этим злом." }, { 5.69, "Благодаря нашим усилиям народ Темнолесья живёт в безопасности." }, { 10.23, "Ты считаешь, что достойна вступить в наши ряды?" }, { 13.85, "Когда-то я был таким же, как ты. Меня раздражало самодовольство Дозора, и я стал соратником мастера Кэрвина." }, { 21.44, "Если ты хочешь показать, на что способна, то слова тебе не помощники." }, { 26.52, "Выступи против воргенов-тенеткачей Ночной Погибели в Светлой роще – светлой, ха! – и Гниющем саду." } } }, t = { d = 21.7, v = "human-male", n = { x = 249 }, c = { x = { { 0.00, "Твои успехи впечатляют. Похоже, ты на многое способен. Пожалуй, твоим талантам следует найти более достойное применение." }, { 8.74, "Впрочем, вот что интересно... Воргены появились словно из ниоткуда." }, { 13.34, "Но, с другой стороны, в наши границы вторглось такое количество странных существ, что это не самая большая проблема." } } } } },
    [174] = { d = 21.3, v = "human-male", n = { x = 245 }, c = { x = { { 0.00, "Один мой друг, гном по имени Ког, обещал мне помочь создать устройство, которое позволит изучать звёзды." }, { 7.30, "Уверен, что есть и иные объяснения творящемуся в лесу, чем магическое вмешательство." }, { 13.43, "Принеси мне бронзовую трубку, изготовленную искусным инженером. Согласно чертежам Кога, это шаг номер один." } } }, t = { d = 3.4, v = "human-male", n = { x = 36 }, c = { x = { { 0.00, "Великолепно! Первый шаг мы сделали успешно!" } } } } },
    [175] = { d = 19.9, v = "human-male", n = { x = 230 }, c = { x = { { 0.00, "Согласно чертежам Кога, мне нужно отыскать способ отражать свет." }, { 4.50, "Помнится, есть у нас одна особа по имени Мэри, которая вечно таскает с собой зеркальце." }, { 10.59, "Может быть, ты отыщешь её и она одолжит нам свою отражающую поверхность?" }, { 15.75, "Кажется, она когда-то жила в южной части Сумеречного леса." } } }, t = { d = 4.1, v = "scourge-female", n = { x = 33 }, c = { x = { { 0.00, "Всё верно, у меня некогда было зеркальце." } } } } },
    [176] = { d = 25.1, v = "human-male#114", n = { x = 266 }, c = { x = { { 0.00, "Разыскивается: Дробитель" }, { 2.36, "В юго-западной части Элвиннского леса поселился могучий гнолл по прозванию Дробитель." }, { 8.99, "Несмотря на все усилия, поймать его так и не удалось." }, { 13.35, "Армия Штормграда назначила за этого гнолла щедрую награду." }, { 17.83, "Чтобы получить её, необходимо представить маршалу Дугхану доказательства смерти Дробителя." } } }, t = { d = 13.2, v = "human-male", n = { x = 139 }, c = { x = { { 0.00, "Ха! Отличная работа! А я уже было думал, что никому не под силу совладать с этим чудовищем!" }, { 6.59, "Вот твоя награда, а с ней прими и мою благодарность: этот гнолл у нас уже вот где сидел!" } } } } },
    [177] = { d = 24.6, v = "scourge-female", n = { x = 223 }, c = { x = { { 0.00, "Зеркальце было одним из моих главных сокровищ... но потом со мной случилось несчастье." }, { 7.58, "После этого я зашвырнула стекляшку за амбар. Одно время там бродил Невменяемый Вурдалак. Может быть, он утащил моё зеркальце." }, { 18.83, "Говорят, что теперь эта тварь живёт на Безмятежном кладбище." } } }, t = { d = 4.7, v = "human-male", n = { x = 52 }, c = { x = { { 0.00, "Шедеврально! Это непременно сработает. Я глубоко признателен!" } } } } },
    [178] = { d = 31.5, v = "human-male#114", n = { x = 319 }, c = { x = { { 0.00, "*До вас доносится бесплотный голос...*" }, { 3.08, "Не пугайся. Я Теокрит, верховный маг башни Азоры в Элвиннском лесу." }, { 8.43, "При помощи этой подвески гноллы из стаи Темношкуров общаются со своим повелителем Моргантом." }, { 16.08, "Я потратил много времени на то, чтобы тоже научиться вещать через эти подвески." }, { 22.23, "Если ты слышишь моё сообщение, значит заклинание сработало." }, { 27.31, "Принеси мне эту подвеску, и я щедро вознагражу тебя." } } }, t = { d = 27.8, v = "human-male", n = { x = 323 }, c = { x = { { 0.00, "Благодарю тебя. Я передал это сообщение через подвески Темношкуров несколько недель назад и полагал, что заклинание не сработало." }, { 9.06, "Оказывается, в конечном итоге оно достигло по меньшей мере некоторых из них." }, { 14.68, "Хочется верить, что рано или поздно я научусь посылать таким образом боевые заклинания и обездвиживать тех гноллов, которые носят эти подвески." }, { 24.96, "К сожалению, до этого ещё очень далеко." } } } } },
    [179] = { d = 30.4, v = "dwarf-male", n = { x = 330 }, c = { x = { { 0.00, "Ну-ка, ну-ка, что тут у нас?.. Холодновато в наших краях, верно? Готов спорить, у тебя всё время мёрзнут руки. Ну, угадал?" }, { 8.53, "Я скажу, что тебе нужно: пара хороших тёплых перчаток. Ну да, душа у меня добрая, так что замёрзнуть я тебе не дам. Только вот есть одно условие." }, { 18.69, "Принеси мне волчьего мяса – и мы, считай, в расчёте. Справедливо, как думаешь?" }, { 23.84, "Мне – мясо, а уж я-то позабочусь о том, чтобы у тебя пальцы больше не мёрзли. Ну, что скажешь?" } } }, t = { d = 11.7, v = "dwarf-male", n = { x = 106 }, c = { x = { { 0.00, "О! Прекрасно! Волчье мясо – это то, что надо!.. Не беспокойся, свою часть сделки я выполню честно." }, { 8.43, "Вот, посмотри, что из этого тебе подойдёт." } } } } },
    [180] = { d = 24.3, v = "human-male#114", n = { x = 264 }, c = { x = { { 0.00, "Разыскивается: лейтенант Фангор" }, { 2.85, "Глава гнолльской стаи Темношкуров, соратник Морганта, врага Города и Королевства." }, { 9.13, "По приказу чиновника Соломона подлый предатель Штормграда приговаривается к смерти." }, { 15.41, "Тот, кто приведёт приговор в исполнение, должен в доказательство принести лапу Фангора мировому судье Соломону." } } }, t = { d = 9.6, g = 1, v = "human-male", n = { m = 107, f = 107 }, c = { m = { { 0.00, "Значит, злобный лейтенант Фангор мёртв? Прекрасно. Ты удивительно храбрый герой. Городской совет Приозерья благодарит тебя за помощь." } }, f = { { 0.00, "Значит, злобный лейтенант Фангор мёртв? Прекрасно. Ты удивительно храбрая героиня." }, { 5.66, "Городской совет Приозерья благодарит тебя за помощь." } } } } },
    [181] = { d = 21.5, v = "human-male", n = { x = 245 }, c = { x = { { 0.00, "Для завершения работы не хватает только одного предмета. Согласно чертежам Кога, нам нужна линза." }, { 6.89, "Единственную подходящую линзу в наших краях будет нелегко достать." }, { 11.80, "В кургане на юге Сумеречного леса живёт огр по имени Ззарк'Вул." }, { 16.30, "Если сможешь, принеси мне его монокль, и я использую его вместо линзы!" } } }, t = { d = 7.0, v = "human-male", n = { x = 79 }, c = { x = { { 0.00, "Наконец-то! Устройство для изучения звёзд готово! Спасибо тебе. Я могу продолжить исследования..." } } } } },
    [182] = { d = 34.3, v = "dwarf-male", n = { x = 383 }, c = { x = { { 0.00, "Нас с моим братом Сениром отправили в Дун Морог, чтобы разведать, действительно ли там объявились тролли, и насколько серьёзна эта угроза." }, { 9.44, "Совету хватает хлопот с троггами, лишние проблемы им ни к чему." }, { 14.92, "Насколько я видел, тролли здесь не слишком хорошо закрепились; в основном они живут в южной пещере." }, { 21.68, "Как по мне, тут и армия не нужна: несколько крепких бойцов вполне управятся." }, { 27.29, "Может, и ты решишь поучаствовать в этом деле? Не за так, конечно: у меня есть что тебе предложить." } } }, t = { d = 16.2, v = "dwarf-male", n = { x = 163 }, c = { x = { { 0.00, "Проклятые тролли! Да не озарит их Извечный Свет! Шумно дышит; немного успокаивается." }, { 7.32, "Эти негодяи ввалились ко мне ночью и украли мои записи! У меня хватило ума не доверять этому негодному подмастерь..." } } } } },
    [183] = { d = 27.8, v = "dwarf-male", n = { x = 313 }, c = { x = { { 0.00, "Нет ничего лучше охоты на диких вепрей, верно?" }, { 3.57, "Правда, здесь, в Холодной долине, их расплодилось столько, что весь интерес пропадает." }, { 9.43, "Их и загонять не надо – они злые, как демоны, и сами бросаются прямо на охотника." }, { 14.77, "Я бы даже сказал, что этих злобных свиней так много, что и охотиться-то стало опасно..." }, { 20.98, "Короче говоря, я буду благодарен, если ты поможешь мне прикончить хотя бы нескольких кабанов." } } }, t = { d = 8.1, v = "dwarf-male", n = { x = 77 }, c = { x = { { 0.00, "Отлично, просто отлично! Теперь я могу спокойно отдох... М-м... Заняться охотой. Благодарю за помощь." } } } } },
    [184] = { d = 39.6, v = "human-male#114", n = { x = 408 }, c = { x = { { 0.00, "Вот бумага, дающая право на расширение фермерских владений в Западном Крае." }, { 5.81, "Она подписана Теодором Хмуробровом и его женой, Верной Хмуробров. На обороте документа торопливо нацарапаны слова:" }, { 15.15, "\"Мы нажали на Хмуроброва и получили от него нужную бумагу. Если тебе захочется заполучить один из участков, она тебе пригодится." }, { 25.44, "С Хмуробровами проблем не предвидится: я видел, как они покидают Западный Край, у них как раз телега сломалась.\"" }, { 34.32, "Наверное, Хмуробровы были бы рады получить этот документ назад..." } } }, t = { d = 19.3, v = "human-male", n = { x = 219 }, c = { x = { { 0.00, "Ты представить не можешь, как мы тебе благодарны!" }, { 3.45, "Конечно, сейчас в этих краях приличным людям не место, но, может, времена переменятся, и тогда нам нужно будет предъявить эту бумагу на право владения землёй." }, { 14.45, "Конечно, многого я предложить не могу, но возьми хотя бы вот это..." } } } } },
    [199] = { d = 3.6, v = "human-male#114", n = { x = 38 }, c = { x = { { 0.00, "Вы берёте образец странно пахнущего порошка." } } }, t = { d = 2.9, v = "dwarf-male", n = { x = 30 }, c = { x = { { 0.00, "Это тревожная находка, мягко говоря!" } } } } },
    [214] = { d = 35.5, v = "human-female#45", n = { x = 420 }, c = { x = { { 0.00, "Не секрет, что красные банданы являются отличительным знаком бандитов из Братства Справедливости." }, { 6.66, "Но мы узнали, что материал, из которого они изготовлены, указывает на ранг члена братства." }, { 13.12, "Я рассказываю вам об этом, потому что хочу, чтобы вы устранили как можно больше бандитов высокого ранга." }, { 20.18, "Обладающих наивысшим рангом, без сомнения, можно найти в тайном убежище ван Клифа." }, { 25.87, "Когда справитесь с заданием, принесите мне десять красных шёлковых бандан в доказательство их смерти – и будете вознаграждены. Желаю удачи." } } }, t = { d = 11.2, g = 1, v = "human-female#45", n = { x = 122 }, c = { m = { { 0.00, "Отличная работа путник! От имени народного ополчения я благодарю вас за ваши усилия." }, { 5.83, "Вскоре с помощью таких смельчаков, как вы, мы вернём эту землю её народу." } }, f = { { 0.00, "Отличная работа путница! От имени народного ополчения я благодарю вас за ваши усилия." }, { 5.94, "Вскоре с помощью таких смельчаков, как вы, мы вернём эту землю её народу." } } } } },
    [216] = { d = 34.1, v = "orc-male", n = { x = 390 }, c = { x = { { 0.00, "Эти фурболги Колючего Меха мешают нашему продвижению!" }, { 3.86, "Деревня Колючего Меха, что лежит на востоке, преграждает нам путь к заставе Расщеплённого Древа." }, { 10.70, "Это на дороге, что идёт в обход деревни Астранаар." }, { 14.29, "Если мы не будем её контролировать, Альянс получит дополнительный путь для вторжения. Мы должны заткнуть эту дыру!" }, { 22.71, "Иди в деревню Колючего Меха да устрой фурболгам прореживание." }, { 27.15, "Выполнишь задачу – получишь награду, но важнее будет то, что ты выполнишь свой долг перед Ордой!" } } }, t = { d = 21.0, g = 1, v = "orc-male", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Отлично, герой, отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса." }, { 12.01, "Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом!" }, { 16.65, "Ты заслужил свою награду, герой! Честь и слава тебе!" } }, f = { { 0.00, "Отлично, героиня, отлично! Я буду продолжать посылать отряды истреблять этих фурболгов, но по крайней мере я могу рассчитывать, что ещё одна дорога расчищена от сил Альянса." }, { 12.08, "Теперь завоевание Ясеневого леса Ордой пойдёт полным ходом!" }, { 16.72, "Ты заслужила свою награду, герой! Честь и слава тебе!" } } } } },
    [217] = { d = 28.4, g = 1, v = "dwarf-male", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг." }, { 8.13, "Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят." }, { 14.50, "Если ты уверен в своих силах, можешь возглавить операцию по ликвидации Громага и его громил." }, { 20.89, "Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю." } }, f = { { 0.00, "Наши разведчики обнаружили предводителя троггов. Похоже, этих тварей привёл к озеру Лок Модан их вождь по имени Громаг." }, { 8.13, "Его хорошо охраняют. Два элитных стража, Скрежетун и Буян, ни на шаг от него не отходят." }, { 14.50, "Если ты уверена в своих силах, можешь возглавить операцию по ликвидации Громага и его громил." }, { 20.92, "Если нам удастся прикончить вождя троггов, то появится шанс загнать проклятых тварей обратно под землю." } } }, t = { d = 8.3, g = 1, v = "dwarf-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Превосходно! Ты вернул надежду Лок Модану. Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель." } }, f = { { 0.00, "Превосходно! Ты вернула надежду Лок Модану. Громаг мёртв, и у нас появилась надежда изгнать троггов из наших земель." } } } } },
    [218] = { d = 20.3, v = "dwarf-male", n = { x = 214 }, c = { x = { { 0.00, "Мои записи! Они уволокли в свою мерзкую пещеру мои записи! Здоровенный громила, весь разрисованный с головы до ног..." }, { 9.36, "Жаль, я не смог разглядеть его получше!" }, { 12.52, "Послушай, тебе ведь уже приходилось иметь дело с троллями? Может, ты сумеешь вернуть мои драгоценные записи?.." } } }, t = { d = 24.2, v = "dwarf-male", n = { x = 244 }, c = { x = { { 0.00, "Великолепно! Словами не передать, как я благодарен! Мои записи, наконец-то!.." }, { 6.74, "Да к тому же, похоже, троллей Холодной долины удалось-таки обуздать, так что больше беспокоиться не о чем." }, { 15.72, "Кстати, послушай: я скоро закончу своё донесение – так, может, ты поработаешь курьером и доставишь его моему братцу Сениру?" } } } } },
    [219] = { d = 22.2, v = "human-male", n = { x = 244 }, c = { x = { { 0.00, "Наконец-то, сторонники Альянса! Помогите... Пожалуйста..." }, { 4.12, "Последнее, что я помню – как орки окружили наш отряд. Меня ударили по затылку, и в глазах потемнело." }, { 10.87, "А теперь я пленник в этой пещере. Спасите меня, я тяжело ранен." }, { 15.71, "Мне понадобится помощь, чтобы добраться до города... Пожалуйста... Вы моя последняя надежда..." } } }, t = { d = 14.7, g = 1, v = "human-male", n = { m = 149, f = 150 }, c = { m = { { 0.00, "Ты отлично послужил Королевству, герой. Благодарю тебя за помощь капралу Кеешану." }, { 7.19, "Одному ему не удалось бы сбежать от орков Чёрной Горы. Подобная храбрость заслуживает великой награды." } }, f = { { 0.00, "Ты отлично послужила Королевству, героиня. Благодарю тебя за помощь капралу Кеешану." }, { 5.85, "Одному ему не удалось бы сбежать от орков Чёрной Горы. Подобная храбрость заслуживает великой награды." } } } } },
    [220] = { d = 13.3, v = "orc-female", n = { x = 146 }, c = { x = { { 0.00, "Прежде чем дать тебе в награду следующий тотэм, Ислен поручит тебе ещё одно задание." }, { 5.86, "Для этого понадобится фиал с водой, который я дал тебе." }, { 10.04, "Ступай, поговори с ней. Мы ещё встретимся." } } }, t = { d = 30.7, v = "tauren-female#71", n = { x = 290 }, c = { x = { { 0.00, "А, фиал с водой, созданной и благословлённой Брин и добытой тобой, ни больше ни меньше." }, { 8.43, "Жидкость в этом фиале необходима для создания сапты, но годится и для других целей." }, { 15.38, "При помощи этой сапты ты сможешь разглядеть водных духов в святилище в Серебряном бору, к югу от Подгорода." }, { 23.79, "Что же до оставшихся капель... о них я расскажу тебе потом. Не боишься долгого пути?" } } } } },
    [221] = { d = 24.2, g = 1, v = "human-male", n = { m = 264, f = 265 }, c = { m = { { 0.00, "Может, ты заметил крупных воргенов, бродящих по лесу в компании тенеткачей?" }, { 5.22, "Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы." }, { 11.84, "Странствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города." }, { 18.17, "Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться. Будь осторожен." } }, f = { { 0.00, "Может, ты заметила крупных воргенов, бродящих по лесу в компании тенеткачей?" }, { 5.32, "Судя по всему, большую часть воргенских сил и составляют эти самые вестники Тьмы." }, { 11.95, "Странствуя по лесу, я узнал, что они захватили и Гниющий сад на юго-западе от города." }, { 18.27, "Эти воргены сильнее тех, с которыми тебе уже пришлось столкнуться. Будь осторожна." } } }, t = { d = 22.7, g = 1, v = "human-male", n = { m = 246, f = 247 }, c = { m = { { 0.00, "Ты достойно выступил против вестников Тьмы. Но, похоже, ряды их нескончаемы. На место убитых становятся всё новые и новые воргены." }, { 9.36, "Что за злая сила притягивает их сюда? Зачем они явились терзать наш несчастный город..." }, { 15.71, "Я возлагаю надежду на мастера Кэрвина. Не сомневаюсь, он разберётся с этой проблемой." } }, f = { { 0.00, "Ты достойно выступила против вестников Тьмы. Но, похоже, ряды их нескончаемы." }, { 5.91, "На место убитых становятся всё новые и новые воргены." }, { 10.04, "Что за злая сила притягивает их сюда? Зачем они явились терзать наш несчастный город..." }, { 16.39, "Я возлагаю надежду на мастера Кэрвина. Не сомневаюсь, он разберётся с этой проблемой." } } } } },
    [224] = { d = 30.6, g = 1, v = "dwarf-male", n = { m = 354, f = 358 }, c = { m = { { 0.00, "Мы должны защитить озеро Лок! Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности." }, { 8.41, "Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов!" }, { 16.42, "Нам нужна твоя помощь, отважный искатель приключений. Ступай и устрани нависшую над нами угрозу." }, { 23.13, "Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся." } }, f = { { 0.00, "Мы должны защитить озеро Лок! Множество королевских солдат проливает кровь в далёких землях, а наш родной край в опасности." }, { 8.41, "Трогги полезли изо всех щелей! Нашествие троггов грозит безопасности Стальгорна. Пора истребить мерзких мутантов!" }, { 16.42, "Нам нужна твоя помощь, отважная искательница приключений. Ступай и устрани нависшую над нами угрозу." }, { 23.25, "Убей десять троггов из племени Камнедробов и десять разведчиков из племени Камнедробов и возвращайся." } } }, t = { d = 24.2, g = 1, v = "dwarf-male", n = { m = 268, f = 270 }, c = { m = { { 0.00, "Молодчина! Ты проявил немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужил королю Магни." }, { 10.19, "Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание." }, { 18.37, "Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне." } }, f = { { 0.00, "Молодчина! Ты проявила немалое мужество на поле боя. Побольше таких, как ты, и мы победим троггов. Ты славно послужила королю Магни." }, { 10.24, "Если тебе по нраву такие свершения, поговори с горным пехотинцем Булыжным Карьером. Капитан дал ему непростое задание." }, { 18.42, "Уверен, ему понадобится помощь. Поговори с Булыжным Карьером, он сейчас в башне." } } } } },
    [226] = { d = 28.9, v = "human-male", n = { x = 325 }, c = { x = { { 0.00, "Нас со Свеном ждут трудные времена, учитывая, что на востоке поселился Некромант." }, { 5.70, "Мы здесь совсем одни, приходится самим добывать себе еду." }, { 9.79, "Такое впечатление, что всякий раз, как я возвращаюсь в лагерь, неся добычу, за мной увязывываются лютые волки." }, { 17.38, "Что и говорить, жить здесь опасно!" }, { 20.28, "Но если ты избавишь нас хотя бы от части волков, нам станет полегче. Они живут на севере и на востоке отсюда, возле реки." } } }, t = { d = 16.5, g = 1, v = "human-male", n = { m = 179, f = 180 }, c = { m = { { 0.00, "О, хорошо. Ты здорово проредил волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном." }, { 9.10, "Вот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию." } }, f = { { 0.00, "О, хорошо. Ты здорово проредила волчью стаю, и если хищники перестанут нас преследовать, мы сможем заняться Морбентом Скверном." }, { 9.26, "Вот, возьми в награду взрывпакеты. Их делают в городе, и Свену недавно выделили целую партию." } } } } },
    [230] = { d = 11.8, v = "human-male#114", n = { x = 121 }, c = { x = { { 0.00, "Порывшись в груде земли, вы находите небольшую книгу, перепачканную грязью." }, { 6.05, "На ней нет заглавия, зато в ней содержатся сведения, необходимые Свену." } } }, t = { d = 14.8, v = "human-male", n = { x = 145 }, c = { x = { { 0.00, "Свен прочитывает несколько страниц и захлопывает книгу." }, { 4.25, "Этот таинственный незнакомец – свидетель смерти моей семьи! У меня столько вопросов к этому человеку... Узнать бы, кто он!" } } } } },
    [233] = { d = 16.5, g = 1, v = "dwarf-male", n = { m = 176, f = 178 }, c = { m = { { 0.00, "Не думаю, что ты горишь желанием мне помочь, парень, но у меня тут целая куча писем, а времени на доставку нет." }, { 8.01, "Это всё для Талина Остроглаза. Его лагерь – у замёрзшего озера, к западу отсюда." }, { 13.65, "Ну что, может, доставишь ему почту?" } }, f = { { 0.00, "Не думаю, что ты горишь желанием мне помочь, красотка, но у меня тут целая куча писем, а времени на доставку нет." }, { 8.13, "Это всё для Талина Остроглаза. Его лагерь – у замёрзшего озера, к западу отсюда." }, { 13.77, "Ну что, может, доставишь ему почту?" } } }, t = { d = 12.2, v = "dwarf-male", n = { x = 126 }, c = { x = { { 0.00, "Благодарю тебя, я уже давно ждал этих писем..." }, { 3.47, "Конечно, они не все для меня. Вот это, скажем, для Грелина Белоборода. Он тут неподалёку живёт, может, зайдёшь к нему?" } } } } },
    [234] = { d = 9.8, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Если мне память не изменяет, лагерь Грелина находится дальше по дороге, на юго-восток отсюда." }, { 6.51, "Не сомневаюсь, он будет рад этому посланию." } } }, t = { d = 16.9, v = "dwarf-male", n = { x = 180 }, c = { x = { { 0.00, "Как здорово! Я уже давно не получал весточки из Стальгорна. Письма моей матушки всегда согревают мне душу." }, { 8.77, "Кстати, и тебе не помешало бы почитать что-нибудь дельное. Вон, возьми любое руководство, которых у нас тут навалом." } } } } },
    [235] = { d = 31.4, v = "orc-male", n = { x = 333 }, c = { x = { { 0.00, "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!" }, { 4.72, "Орде удалось закрепиться в землях к северу от Степей." }, { 8.60, "И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды!" }, { 15.86, "Те, кто жаждет подвигов, могут отправиться туда." }, { 19.31, "Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей." }, { 27.38, "Она ждёт желающих принять участие в большой охоте!" } } }, t = { d = 34.0, g = 1, v = "tauren-female", n = { x = 307 }, c = { m = { { 0.00, "Добро пожаловать на новое пограничье." }, { 2.96, "Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя." }, { 13.10, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 21.28, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 26.33, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } }, f = { { 0.00, "Добро пожаловать на новое пограничье." }, { 2.96, "Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя." }, { 13.49, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 21.66, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 26.72, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } } } } },
    [237] = { d = 27.3, g = 1, v = "dwarf-male", n = { x = 305 }, c = { m = { { 0.00, "Горный пехотинец Кремневик превозносит тебя до небес, герой. Поэтому я хочу доверить тебе очень важное задание." }, { 7.68, "Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны." }, { 13.91, "Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов." }, { 21.98, "Это поможет нам выиграть время. Когда выполнишь задание, возвращайся." } }, f = { { 0.00, "Горный пехотинец Кремневик превозносит тебя до небес, героиня. Поэтому я хочу доверить тебе очень важное задание." }, { 7.82, "Мы не должны ослаблять натиск на троггов, пока наши братья-дворфы не вернутся с войны." }, { 14.05, "Отправляйся в южные холмы и убей десять головоломов из племени Камнедробов и десять ясновидцев из племени Камнедробов." }, { 22.11, "Это поможет нам выиграть время. Когда выполнишь задание, возвращайся." } } }, t = { d = 29.9, g = 1, v = "dwarf-male", n = { m = 338, f = 339 }, c = { m = { { 0.00, "Ты прекрасно справился с заданием, герой! Сам король может гордиться тобой." }, { 5.44, "К сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса." }, { 11.53, "Вести о потерях наполняют горечью моё сердце... Так пусть же эти жертвы будут не напрасны!" }, { 17.76, "Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу." }, { 22.88, "Поговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужен нам как никогда." } }, f = { { 0.00, "Ты прекрасно справилась с заданием, героиня! Сам король может гордиться тобой." }, { 5.75, "К сожалению, обещанное подкрепление так и не подошло. Фронт обагрен кровью воинов Альянса." }, { 11.84, "Вести о потерях наполняют горечью моё сердце... Так пусть же эти жертвы будут не напрасны!" }, { 18.07, "Мы должны с честью выдержать невзгоды и вернуть Альянсу былую славу." }, { 23.19, "Поговори с горным пехотинцем Стеноломом, он даст тебе новое задание. Ты нужна нам как никогда." } } } } },
    [239] = { d = 31.1, v = "human-male", n = { x = 359 }, c = { x = { { 0.00, "Гарнизон западной границы докладывает об усилении активности гноллов и грабителей." }, { 5.70, "Они просят, чтобы мы прислали подкрепление из Штормграда... Но у нас не хватает людей!" }, { 12.00, "Твоя помощь не была бы лишней. Поговори с заместителем судьи Рейнером: он сейчас находится в гарнизоне у Западного ручья. Рейнер скажет тебе, что делать." }, { 22.91, "Гарнизон расположен к западу отсюда: иди по дороге, а потом, когда перейдёшь через речушку по мосту, сверни направо." } } }, t = { d = 12.5, v = "human-male", n = { x = 134 }, c = { x = { { 0.00, "Тебя что, маршал Дугхан сюда послал? Ну... Ты, конечно, не солдат, но маршалу я доверяю." }, { 6.22, "У нас тут сложилась, скажем так, напряжённая ситуация. Надеюсь, ты сумеешь нам помочь." } } } } },
    [240] = { d = 2.9, v = "human-male", n = { x = 28 }, c = { x = { { 0.00, "А вот и пирожки с \"крабами\" а-ля Груал!" } } }, t = { d = 4.9, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Ага! Спасибо. Как раз то, что нужно. А вот и твоя плата за услугу!" } } } } },
    [244] = { d = 26.2, g = 1, v = "human-male", n = { x = 291 }, c = { m = { { 0.00, "Привет тебе, герой. Мне приказано охранять этот участок дороги." }, { 4.47, "Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов." }, { 10.35, "В Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону." }, { 17.36, "Уверен, он заплатит тебе за принесённые вести." }, { 20.90, "Фелдон обычно обходит территорию к югу от моста по дороге в Приозерье." } }, f = { { 0.00, "Привет тебе, героиня. Мне приказано охранять этот участок дороги." }, { 4.61, "Хотя сейчас здесь безопасно, к северу и к востоку отсюда я видел лагеря гноллов." }, { 10.50, "В Приозерье должны узнать о том, что гноллы собирают армию! Сообщи об этом заместителю судьи Фелдону." }, { 17.51, "Уверен, он заплатит тебе за принесённые вести." }, { 21.05, "Фелдон обычно обходит территорию к югу от моста по дороге в Приозерье." } } }, t = { d = 20.3, v = "human-male", n = { x = 223 }, c = { x = { { 0.00, "К Элвиннскому лесу подбираются гноллы Красногорья? Похоже, скоро они доберутся и до наших земель." }, { 7.39, "И тогда не только Приозерье окажется в осаде!" }, { 11.04, "Возьми плату за вести, хоть они и скверные. И время сейчас неподходящее, ведь мы ничего не сможем противопоставить новой угрозе." } } } } },
    [245] = { d = 27.8, g = 1, v = "human-male", n = { m = 302, f = 303 }, c = { m = { { 0.00, "Привет тебе, герой. Наверное, ты видел пауков на западной границе?" }, { 4.65, "Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья." }, { 12.02, "Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться." }, { 17.65, "Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов." }, { 24.55, "Мой тебе совет: остерегайся их яда." } }, f = { { 0.00, "Привет тебе, героиня. Наверное, ты видела пауков на западной границе?" }, { 4.77, "Эти восьминогие чудища нам не по зубам, а командир не может отпустить солдат так далеко от Темнолесья." }, { 12.14, "Мне неловко просить тебя о помощи, но, кажется, тебе удалось бы с ними разобраться." }, { 17.77, "Не могу обещать тебе большую награду, но одарю, чем смогу, если ты поможешь извести этих гадов." }, { 24.67, "Мой тебе совет: остерегайся их яда." } } }, t = { d = 12.6, v = "human-male", n = { x = 137 }, c = { x = { { 0.00, "А! Ты вернулся. И на первый взгляд – в целости и сохранности. Разумеется, Ночной дозор весьма тебе признателен." }, { 7.62, "Я обещал вознаградить тебя, и обещание своё выполняю. Держи." } } } } },
    [246] = { d = 22.8, v = "human-male", n = { x = 253 }, c = { x = { { 0.00, "У нас нет лишних людей, но с гноллами, о которых ты говоришь, надо что-то делать." }, { 5.91, "Поищи их в южной части Красногорья." }, { 8.41, "Убей, кого сможешь, и сообщи мне об их общем числе и степени угрозы, которую они представляют для города." }, { 15.52, "Гноллы стоят лагерем вдоль южной дороги." }, { 18.75, "Сделай это ради армии Штормграда, и получишь награду." } } }, t = { d = 27.4, g = 1, v = "human-male", n = { m = 302, f = 303 }, c = { m = { { 0.00, "Заместитель судьи Фелдон слушает ваш отчёт." }, { 3.50, "Значит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения." }, { 12.62, "Что ж, мы благодарим тебя за помощь." }, { 15.49, "Если ты ещё не беседовал с маршалом Маррисом и мировым судьёй Соломоном, непременно обратись к ним." }, { 22.20, "Дела у нас идут всё хуже; не сомневаюсь, эти двое найдут тебе работу." } }, f = { { 0.00, "Заместитель судьи Фелдон слушает ваш отчёт." }, { 3.50, "Значит, там собралось немало гноллов, и, судя по всему, они весьма сильны. Должно быть, тебе нелегко было собрать эти сведения." }, { 12.62, "Что ж, мы благодарим тебя за помощь." }, { 15.49, "Если ты ещё не беседовала с маршалом Маррисом и мировым судьёй Соломоном, непременно обратись к ним." }, { 22.36, "Дела у нас идут всё хуже; не сомневаюсь, эти двое найдут тебе работу." } } } } },
    [248] = { d = 26.4, v = "human-male", n = { x = 298 }, c = { x = { { 0.00, "Я наблюдал за башней Илгалара и понял, что Моргант враждует с орками крепости Каменной Стражи." }, { 6.62, "Не знаю, что за этим кроется, но ты можешь помочь мне приоткрыть завесу тайны." }, { 12.38, "Возьми ещё один амулет Азоры и отнеси его на вершину уцелевшей башни рядом с крепостью." }, { 18.83, "Отыщи подходящее место для амулета и спрячь его там. Для этой цели прекрасно подойдёт сундук или кувшин." } } }, t = { d = 8.5, v = "human-male", n = { x = 101 }, c = { x = { { 0.00, "Это подходящий сосуд для амулета Азоры. Он позволит Теокриту проникнуть в помыслы обитателей крепости Каменной Стражи." } } } } },
    [249] = { d = 29.4, g = 1, v = "human-male", n = { m = 316, f = 316 }, c = { m = { { 0.00, "Ценой долгих усилий я раскрыл планы Морганта." }, { 3.59, "Он ищет Косу Элуны... и быть может, уже отыскал её!" }, { 7.06, "Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь." }, { 14.21, "Я не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты должен войти в башню Илгалара и бросить ему вызов." }, { 23.97, "Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет." } }, f = { { 0.00, "Ценой долгих усилий я раскрыл планы Морганта." }, { 3.59, "Он ищет Косу Элуны... и быть может, уже отыскал её!" }, { 7.06, "Коли так, то скоро Красногорье, а следом и всё королевство Штормграда почувствует его тёмную мощь." }, { 14.21, "Я не готов выступить против Морганта, но, боюсь, терять время нельзя. Ты должна войти в башню Илгалара и бросить ему вызов." }, { 23.03, "Одолей злодея, принеси мне его подвеску Тени, и королевство тебя не забудет." } } }, t = { d = 20.1, g = 1, v = "human-male", n = { m = 225, f = 226 }, c = { m = { { 0.00, "Ты сделал великое дело. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности." }, { 7.14, "Смиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена." }, { 14.03, "Вместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях." } }, f = { { 0.00, "Ты сделала великое дело. Чернокнижник Моргант повержен, и Штормград избавлен от великой опасности." }, { 7.21, "Смиренно прошу принять эту награду. Я пожелал бы тебе мира, выпади нам жить в мирные времена." }, { 14.10, "Вместо этого желаю удачи в ожидающих тебя испытаниях и победы в предстоящих боях." } } } } },
    [250] = { d = 30.9, g = 1, v = "dwarf-male", n = { m = 351, f = 351 }, c = { m = { { 0.00, "Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра!" }, { 8.37, "Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба." }, { 12.92, "Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора." }, { 19.22, "Потому-то ты мне и нужен. Я заметил сапёров из клана Чёрного железа неподалёку от восточной части дамбы." }, { 27.22, "Разведай обстановку и возвращайся с уликами." } }, f = { { 0.00, "Хвала небесам, что хоть кого-то волнует наша дамба. Будто мало нам разрушенного моста Тандола и разграбленного Дун Модра!" }, { 8.37, "Не сомневаюсь, следующей целью Чёрного Железа станет именно Дамба." }, { 12.92, "Большую часть охраны отослали биться за Альянс, в том числе моего старшего инспектора." }, { 19.22, "Потому-то ты мне и нужна. Я заметил сапёров из клана Чёрного железа неподалёку от восточной части дамбы." }, { 26.38, "Разведай обстановку и возвращайся с уликами." } } }, t = { d = 4.4, v = "dwarf-male", n = { x = 52 }, c = { x = { { 0.00, "В подозрительной бочке содержится странно пахнущий порошок." } } } } },
    [251] = { d = 10.0, v = "human-male", n = { x = 112 }, c = { x = { { 0.00, "Отнесите записку Шире Фон-Инди. Он знает множество языков и не чужд древним искусствам – если кто и может перевести это послание, то это он." } } }, t = { d = 2.9, v = "human-male", n = { x = 31 }, c = { x = { { 0.00, "Шира принимается за перевод записки..." } } } } },
    [252] = { d = 15.4, v = "human-male", n = { x = 165 }, c = { x = { { 0.00, "О небо! Если то, о чём сказано в этой записке – правда, то Аберкромби сделал нечто... невообразимое." }, { 7.10, "Отнеси-ка переведённую записку Элло." }, { 10.23, "И поторопись, поскольку я боюсь, что это чудовище уже ковыляет к городу..." } } }, t = { d = 14.1, g = 1, v = "human-male", n = { m = 153, f = 156 }, c = { m = { { 0.00, "Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд." }, { 5.66, "Хотя ты помогал Аберкромби по доброте душевной, именно ты обрёк наш город на гибель. Элло погружается в раздумья..." } }, f = { { 0.00, "Элло читает письмо... и бледнеет на глазах. Затем он поднимает на вас взгляд." }, { 5.66, "Хотя ты помогала Аберкромби по доброте душевной, именно ты обрекла наш город на гибель. Элло погружается в раздумья..." } } } } },
    [253] = { d = 39.3, v = "human-male", n = { x = 453 }, c = { x = { { 0.00, "Бальзамировщиком в наших краях давно пугают детей." }, { 3.54, "Когда-то он был добрым алхимиком, но смерть любимой жены Элизы лишила его рассудка." }, { 9.34, "Чтобы вернуть её к жизни, он прибег к тёмной магии и даже вложил в грудь мёртвой супруги собственное сердце." }, { 17.22, "Это оживило Элизу... но её сразило проклятие – она возжелала человеческой плоти, и Бальзамировщику пришлось закопать её обратно." }, { 26.34, "Всё его могущество заключено в сердце. Отыщи могилу Элизы, извлеки из неё сердце и принеси его мне, пока оно бьётся." }, { 34.46, "Если тебе удастся выполнить это, то сила Бальзамировщика иссякнет." } } }, t = { d = 12.9, v = "human-male", n = { x = 147 }, c = { x = { { 0.00, "Получилось! Магия этого сердца защитит нас от зла Бальзамировщика и послужит могущественным талисманом Темнолесью." }, { 8.46, "Ты совершил подвиг во имя нашего народа. Мы тебя не забудем." } } } } },
    [255] = { d = 32.5, g = 1, v = "dwarf-male", n = { x = 341 }, c = { m = { { 0.00, "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться!" }, { 9.07, "И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности." }, { 17.22, "Похоже, у меня нет выбора. Придётся искать наёмников." }, { 21.27, "Как насчёт тебя? На первый взгляд ты подходишь, герой. На северном берегу озера разбила лагерь группа огров." }, { 28.72, "Может быть, ты избавишь наш город от опасности?" } }, f = { { 0.00, "Пройдёт два месяца, прежде чем из Стальгорна к нам на подмогу направят горстку солдат, да ещё два месяца они будут до нас добираться!" }, { 9.07, "И мало того, что наш город остался без защиты, но раскоп и дамба – дамба! – тоже в опасности." }, { 17.22, "Похоже, у меня нет выбора. Придётся искать наёмников." }, { 21.27, "Как насчёт тебя? На первый взгляд ты подходишь, героиня. На северном берегу озера разбила лагерь группа огров." }, { 28.95, "Может быть, ты избавишь наш город от опасности?" } } }, t = { d = 9.9, v = "dwarf-male", n = { x = 116 }, c = { x = { { 0.00, "Прекрасные новости! Я и народ Телсамара глубоко признательны тебе." }, { 4.53, "Ведь если нам удастся разобраться с ограми, мы сможем заняться троггами." } } } } },
    [256] = { d = 29.4, v = "human-male#114", n = { x = 297 }, c = { x = { { 0.00, "По приказу магистрата Телсамара:" }, { 2.99, "Чок-сул, обвиняемый в организации нападений на город Телсамар, Каменную дамбу и раскоп, приговаривается к смерти любым из возможных способов." }, { 14.10, "Вознаграждение получит тот, кто предоставит в Магистрат доказательства смерти Чок-сула." }, { 21.32, "В последний раз обвиняемого видели в лагере огров в северо-восточной части озера Лок Модан." } } }, t = { d = 17.4, g = 1, v = "dwarf-male", n = { m = 165, f = 166 }, c = { m = { { 0.00, "Ой! Что это? И зачем ты притащил её…" }, { 3.16, "Боги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов!" }, { 9.33, "Что ж, награда и благодарность от имени всего народа Телсамара достаются тебе по праву!" } }, f = { { 0.00, "Ой! Что это? И зачем ты притащила её…" }, { 2.86, "Боги!.. Это она? Ну, разрази меня гром, неужели это голова проклятого огра? Вот это улов!" }, { 9.03, "Что ж, награда и благодарность от имени всего народа Телсамара достаются тебе по праву!" } } } } },
    [257] = { d = 30.6, v = "human-male", n = { x = 350 }, c = { x = { { 0.00, "Думаешь тягаться с Дэрилом Смелым? Не советую! Разумеется, отговаривать тебя я не буду." }, { 6.07, "Вот испытание, которое тебе явно не по силам. Не огорчайся, если ничего не выйдет." }, { 12.20, "Неподалёку от озера Лок Модан свила гнёзда стая канюков. Почему бы не подстрелить несколько тварей?" }, { 19.14, "Знаешь что, если ты справишься с моим заданием за пятнадцать минут, я отдам тебе свой лук или ружьё. *Он с презрением осматривает вас.* Всё равно тебе нечего терять." } } }, t = { d = 25.7, v = "human-male", n = { x = 272 }, c = { x = { { 0.00, "Что? Получилось?!" }, { 1.62, "Послушай добрый совет, пусть успех не кружит тебе голову. Я хочу сказать, любой безусый паренёк с луком справился бы с такими..." }, { 10.37, "небольшими существами. Надеюсь, тебе не слишком нравится убивать канюков, м-м-м? Не хотелось бы, чтобы они стали исчезающим видом." }, { 19.74, "Что ж, э-э-э... Пусть не говорят, что Дерил Смелый не держит своё слово." } } } } },
    [258] = { d = 32.6, g = 1, v = "human-male", n = { m = 348, f = 348 }, c = { m = { { 0.00, "путник Батькович, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко." }, { 8.53, "А вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее." }, { 16.55, "На сей раз даю тебе двенадцать минут." }, { 19.38, "Не расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься!" }, { 26.76, "Я не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад..." } }, f = { { 0.00, "путница Батьковна, да? Вижу, ты лопаешься от гордости за выполненное задание, а? Я же говорил, что это легко." }, { 7.95, "А вот попробуй поохотиться на кабанов. Верь мне, это тебе не поросята из Холодной долины, с ними надо поосторожнее." }, { 15.96, "На сей раз даю тебе двенадцать минут." }, { 18.79, "Не расстраивайся, если ничего не выйдет. Я тебе рубаху с собственного плеча отдам, если ты справишься!" }, { 26.17, "Я не рассказывал, как получил свой знаменитый шрам? Нет? Это было два года назад..." } } }, t = { d = 21.3, g = 1, v = "human-male", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трёпку, да?" }, { 5.47, "Не беспокойся, я никому не расскажу о твоём поражении. Тебе и без досужих болтунов тяжело." }, { 12.08, "О! Ты умудрился убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребёнок смог бы... Обещание? Какое ещё обещание?" } }, f = { { 0.00, "Похоже, тебе несладко пришлось. Видно, кабаны задали тебе изрядную трёпку, да?" }, { 5.47, "Не беспокойся, я никому не расскажу о твоём поражении. Тебе и без досужих болтунов тяжело." }, { 12.08, "О! Ты умудрилась убить кабанов? Я... что ж... хочу сказать, ничего удивительного! Любой ребёнок смог бы... Обещание? Какое ещё обещание?" } } } } },
    [262] = { d = 23.5, g = 1, v = "human-male", n = { m = 250, f = 251 }, c = { m = { { 0.00, "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!" }, { 5.36, "Прошу тебя, помоги мне. Ты не раз творил настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны!" }, { 13.15, "Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме." }, { 18.32, "Может быть, кто-то в городе опознает её, и мы выясним имя владельца?" } }, f = { { 0.00, "Я должен узнать, кто таился в тени в ту ночь, когда была убита моя семья!" }, { 5.36, "Прошу тебя, помоги мне. Ты не раз творила настоящие чудеса. Выясни, кто это был. Мне нужно узнать его тайны!" }, { 13.25, "Я рассказал тебе всё, что мог, но возьми эту книгу, обнаруженную на ферме." }, { 18.42, "Может быть, кто-то в городе опознает её, и мы выясним имя владельца?" } } }, t = { d = 15.2, v = "human-female#45", n = { x = 164 }, c = { x = { { 0.00, "Хмм... Кто-то совсем недавно держал эту книгу в руках. Этот человек одержим жаждой мести." }, { 6.13, "Но увы, следы на ней, по крайней мере следы первого владельца, едва различимы." }, { 11.84, "Я могу сказать одно: он не из Темнолесья." } } } } },
    [263] = { d = 30.0, g = 1, v = "dwarf-male", n = { m = 320, f = 322 }, c = { m = { { 0.00, "Горные пехотинцы уверяют, что ты силён и отважен. Нам нужен путник вроде тебя. Мы никак не можем справиться с троггами." }, { 8.19, "Всех бойцов отозвали на фронт, и мы остались без защиты." }, { 12.05, "Но раз среди нас появился закалённый в боях герой, то может быть, нам удастся выстоять." }, { 18.27, "Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов." }, { 24.34, "Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов." } }, f = { { 0.00, "Горные пехотинцы уверяют, что ты сильна и отважна. Нам нужна путница вроде тебя. Мы никак не можем справиться с троггами." }, { 8.30, "Всех бойцов отозвали на фронт, и мы остались без защиты." }, { 12.17, "Но раз среди нас появилась закалённая в боях героиня, то может быть, нам удастся выстоять." }, { 18.73, "Убей десять шаманов из племени Камнедробов и десять костегрызов из племени Камнедробов." }, { 24.80, "Посмотрим, не преувеличены ли слухи о твоей доблести, о Гроза троггов." } } }, t = { d = 16.6, g = 1, v = "dwarf-male", n = { m = 196, f = 198 }, c = { m = { { 0.00, "Я сразу понял, что Стальгорн будет тобой гордиться. Ты славно послужил королю Магни." }, { 5.82, "Теперь, доказав, что ты верный защитник Королевства, можешь поговорить с капитаном." }, { 11.38, "Может быть, он посвятит тебя в наши более насущные проблемы. Хвала тебе." } }, f = { { 0.00, "Я сразу понял, что Стальгорн будет тобой гордиться. Ты славно послужила королю Магни." }, { 5.82, "Теперь, доказав, что ты верная защитница Королевства, можешь поговорить с капитаном." }, { 11.41, "Может быть, он посвятит тебя в наши более насущные проблемы. Хвала тебе." } } } } },
    [264] = { d = 45.5, v = "scourge-female", n = { x = 358 }, c = { x = { { 0.00, "Гад такой! Бросил меня ради своего клятого похода! Понимаете ли, \"Свет превыше всего, ибо он единственная наша защита от нежити!\"" }, { 13.93, "А как же дети?! А я?! Много ночей я терпеливо ждала его... я всегда была второй после его чёртового долга!" }, { 25.02, "И посмотрите, теперь на плоды борьбы за \"справедливость\"! Он мёртв, а на меня обрушилось всё то, чему он пытался помешать!" }, { 35.90, "Возьмите этот хлам и положите на его могилу в Гробнице. Мне не нужен больше этот мусор... и он сам тоже!" } } }, t = { d = 30.6, v = "scourge-female", n = { x = 277 }, c = { x = { { 0.00, "Вы кладёте дешёвую безделушку на могилу, и драгоценный камень в ней заметно тускнеет." }, { 8.06, "Когда вы поднимаетесь, чтобы уйти, вы смотрите на подвеску – она лежит, тусклая и мёртвая, в руках вырезанного на надгробной плите изображения." }, { 20.50, "Ваши мысли прерывает порыв холодного ветра, пронёсшегося по Гробнице. На мгновение всё вокруг вас замирает." } } } } },
    [265] = { d = 15.5, v = "human-female#45", n = { x = 174 }, c = { x = { { 0.00, "Вот твоя книга, желаю удачи в расследовании. Если ты расспросишь других горожан, они могут рассказать тебе что-нибудь ценное." }, { 8.81, "Я же скажу одно: хотя автор этой книги не из нашего города, тетрадь для неё он купил здесь." } } }, t = { d = 12.1, v = "human-male", n = { x = 135 }, c = { x = { { 0.00, "Ах, да. Я продал эту тетрадь одному сомнительному типу." }, { 3.91, "Он не представился, но явно нервничал, дёргался, то и дело оглядывался через плечо. Надеюсь, что смог тебе помочь..." } } } } },
    [266] = { d = 12.6, v = "human-male", n = { x = 138 }, c = { x = { { 0.00, "Вот твоя книга, желаю удачи в расследовании." }, { 3.54, "Советую заглянуть в таверну. Если человек, о котором ты говоришь, останавливался у нас в городе, скорее всего его кто-то видел." } } }, t = { d = 23.6, v = "human-male#50", n = { x = 268 }, c = { x = { { 0.00, "Ах да, эту книгу я помню. Её владелец снимал комнату на несколько дней и вечерами засиживался в баре, всё писал." }, { 7.85, "Город он покинул в спешке, бормоча под нос, что его преследует... что-то." }, { 12.61, "В последний раз я видел его на дороге, ведущей на запад. Кажется, он собирался искать новое укрытие." }, { 19.63, "Первое, что ему встретится на западе, – это Вороний холм..." } } } } },
    [267] = { d = 32.1, g = 1, v = "dwarf-male", n = { m = 351, f = 352 }, c = { m = { { 0.00, "герой, не знаю, слышал ли ты о новой угрозе, нависшей над землями дворфов." }, { 5.10, "Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов." }, { 10.47, "Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов." }, { 17.53, "И всё же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан." }, { 26.59, "Принеси в доказательство своих свершений восемь каменных зубов троггов." } }, f = { { 0.00, "героиня, не знаю, слышала ли ты о новой угрозе, нависшей над землями дворфов." }, { 5.33, "Внутренние войска отправили на фронт, на охране осталась лишь горстка воинов." }, { 10.69, "Мой полк приставлен к Вратам, и я не могу отойти от них, поскольку мы опасаемся вторжения врагов." }, { 17.75, "И всё же необходимо усилить натиск на троггов, заселивших холмы. Если это задание тебе по плечу, проведи вылазку в их стан." }, { 26.81, "Принеси в доказательство своих свершений восемь каменных зубов троггов." } } }, t = { d = 10.8, g = 1, v = "dwarf-male", n = { m = 106, f = 107 }, c = { m = { { 0.00, "Отличная работа. Ты оказал всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!" } }, f = { { 0.00, "Отличная работа. Ты оказала всем дворфам великую услугу, защищая наши земли. Сам король Магни Бронзобород может гордиться тобой!" } } } } },
    [268] = { d = 26.9, v = "human-male", n = { x = 300 }, c = { x = { { 0.00, "Я лишь наполовину успел закончить книгу, найденную тобой. Мне пришлось оставить её на ферме Свена во время поспешного бегства…" }, { 9.26, "Вот. Отнеси Свену все мои записи. Здесь подробно рассказывается о случившемся на ферме." }, { 16.30, "Хотя единственным моим сокровищем в последние несколько недель были только эти записи, я охотно расстанусь с ними, лишь бы не вставать на пути Свена!" } } }, t = { d = 13.3, v = "human-male", n = { x = 153 }, c = { x = { { 0.00, "Записи многое проясняют. Теперь мне ясно, что следует искать тёмных всадников!" }, { 5.58, "Я встречал их в Сумеречном лесу и видел, как они говорят с чародеем Морбентом Скверном у Покинутой усадьбы." } } } } },
    [269] = { d = 27.4, v = "human-male", n = { x = 308 }, c = { x = { { 0.00, "Отправляйся в Штормград и поговори с епископом Фартингом в Соборе Света." }, { 4.89, "Отдай ему записи Трясунчика и сообщи, что собираешься бросить вызов Морбенту Скверну." }, { 11.22, "Хоть Штормград и бросил Темнолесье на произвол судьбы, Фартинг – добрая душа и мудрый человек. Он поможет тебе спасти нас." }, { 20.14, "Тебя ждёт много опасностей... Однако поспеши. С каждым часом в Сумеречном лесу сгущается тьма." } } }, t = { d = 29.7, v = "human-male", n = { x = 341 }, c = { x = { { 0.00, "Епископ изучает записи..." }, { 2.27, "Зло нашло лазейку в и без того обложенный со всех сторон Сумеречный лес. Хвала Свету, что отыскался герой вроде тебя." }, { 10.79, "Но прежде чем смело двинуться навстречу испытаниям, тебе следует хорошо подготовиться..." }, { 16.76, "Некромант Морбент Скверн всегда был необычайно силён, а чтобы стать неуязвимым, наложил на себя могучие чары." }, { 24.39, "Тебе не одолеть его без оружия, способного пробиться сквозь эти преграды." } } } } },
    [270] = { d = 40.8, v = "human-male", n = { x = 482 }, c = { x = { { 0.00, "Много лет назад Третья флотилия Кул-Тираса затонула у берегов Болотины, огромной топи к северу от дворфийского королевства Стальгорна." }, { 9.30, "Одно из судов было нагружено светлой сталью." }, { 12.77, "Этот металл представляет для нас большую ценность, поскольку изготовленное из него оружие и доспехи разят врагов силой святой истины." }, { 22.07, "Если вы собираетесь противостоять Морбенту Скверну, вам именно такое оружие и понадобится." }, { 28.73, "Отправляйтесь в Гавань Менетилов и переговорите с моим коллегой-дворфом по имени Глорин Стальной Лоб." }, { 35.74, "Если утерянный груз ещё можно найти – он сообразит, где нужно искать." } } }, t = { d = 24.1, g = 1, v = "dwarf-male", n = { m = 263, f = 265 }, c = { m = { { 0.00, "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких." }, { 6.70, "Ты проделал длинный путь, братишка. Если тебе сильно повезёт, ты можешь найти то, что ищешь." }, { 13.21, "А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь." } }, f = { { 0.00, "Светлая сталь – и впрямь драгоценный металл, но всё говорит за то, что задание у тебя не из лёгких." }, { 6.70, "Ты проделала длинный путь, сестрёнка. Если тебе сильно повезёт, ты можешь найти то, что ищешь." }, { 13.47, "А если раздобудешь металл – я знаю, кто сможет выковать подходящее оружие против того некроманта в Сумеречном лесу, о котором ты говоришь." } } } } },
    [271] = { d = 34.6, v = "bloodelf-female", n = { x = 394 }, c = { x = { { 0.00, "Не хочешь отплатить Его Смелости? Вынуждена признать, что Дэрил в самом деле многое умеет." }, { 6.60, "Год назад весь Приют странников охотился на огромного медведя, но ни одному смельчаку не посчастливилось его одолеть." }, { 14.79, "Тогда Дэрил решил выступить против зверя сам. Разумеется, он ничего не добился, да ещё и получил этот уродливый шрам над глазом." }, { 24.04, "Убей медведя, и не сомневаюсь, что даже Дэрил ненадолго лишится дара речи." }, { 29.60, "Старину Черношкура можно отыскать в логове в холмах над Телсамаром." } } }, t = { d = 18.4, v = "human-male", n = { x = 184 }, c = { x = { { 0.00, "Э... что это? Судя по всему, медвежья голова." }, { 3.70, "Он невольно проводит пальцем по старому шраму." }, { 7.39, "Что ж, интересная добыча. Не тот ли самый медведь..." }, { 11.18, "Он умолкает и начинает заметно дрожать." }, { 14.39, "О, скорее убери её! Убери отсюда эту страшную штуку!" } } } } },
    [272] = { d = 32.3, v = "nightelf-female#52", n = { x = 403 }, c = { x = { { 0.00, "Вот твоё второе испытание – тебе понадобятся две половинки подвески Морского Льва." }, { 5.44, "Одна половинка черпает мощь из ловкости аспекта морского льва, скользящего в бездне вод, вторая черпает силу из невероятной выносливости аспекта морского льва." }, { 16.02, "Друидов привлекают обе эти черты, олицетворяющие аспект их водного облика." }, { 21.37, "Поговори с жителями Лунной поляны, чтобы узнать, где могут находиться эти половинки, и принеси их, чтобы соединить." }, { 28.67, "Сделав это, отнеси подвеску Дендриту Блеску Звёзд." } } }, t = { d = 27.4, g = 1, v = "nightelf-male#54", n = { m = 323, f = 323 }, c = { m = { { 0.00, "Ты прошёл испытание Морского Льва. Прими мои поздравления." }, { 4.33, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 13.29, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 20.92, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } }, f = { { 0.00, "Ты прошла испытание Морского Льва. Прими мои поздравления." }, { 4.44, "Каждый шаг на пути обретения этой подвески должен был показать тебе, насколько важны ловкость и выносливость в перемещениях под водой." }, { 13.40, "Одно не существует без другого, и эти качества нельзя обрести без желания принять аспект морского льва." }, { 21.03, "Запомни хорошенько этот урок и полагайся на него, когда научишься принимать водный облик." } } } } },
    [273] = { d = 21.4, v = "dwarf-male", n = { x = 229 }, c = { x = { { 0.00, "Ещё не поздно, ты можешь поискать Хальдора." }, { 3.00, "Вряд ли он ушёл далеко; Миран и Сайан – крепкие ребята, но под грузом бочек ходят не слишком быстро." }, { 10.73, "Они пошли к раскопу обычной дорогой – на юг от города, вдоль берега озера." }, { 16.19, "Найти их будет несложно, если они ещё не добрались до места назначения." } } }, t = { d = 15.3, v = "dwarf-male", n = { x = 172 }, c = { x = { { 0.00, "Хм, жалкой засаде Чёрного Железа не помешать мне доставить товар!" }, { 4.76, "Но Сайан... Никогда бы не подумал, что он сторонник этих предателей. Я с ним почти год работаю... должно быть, что-то упустил. Ладно, подумаю об этом позже." } } } } },
    [274] = { d = 28.0, v = "dwarf-male", n = { x = 329 }, c = { x = { { 0.00, "Это не простой взрывчатый порошок. Только взгляни на эти крошечные серебристые кристаллы. А характерный запах!" }, { 7.61, "Ясно, как день – это сефорий. Сам по себе он безобиден, но, намокнув, может взорвать весь Стальгорн!" }, { 14.69, "Химическую реакцию можно нейтрализовать, смешав четыре компонента: паучий яд, толчёный кристалл Могроша, слезу кроколиска и нейтрализующий коллоид." }, { 24.74, "Расскажи об этом Плотине, пока не поздно!" } } }, t = { d = 4.1, v = "dwarf-male", n = { x = 36 }, c = { x = { { 0.00, "Нейтрализующий коллоид? Для сефория? О небо!" } } } } },
    [275] = { d = 21.9, v = "tauren-male", n = { x = 204 }, c = { x = { { 0.00, "Болотину лихорадит, и я не знаю почему. Трясинные ползуны набирают силу. Это болезненные, гнойные нарывы на теле земли!" }, { 11.07, "И чтобы исцелить её, нужно загнать трясинных ползунов обратно в болота, откуда они вылезли." }, { 18.70, "Ползуны водятся у водоёмов в Болотине." } } }, t = { d = 8.9, v = "tauren-male", n = { x = 82 }, c = { x = { { 0.00, "Скоро раны на теле земли затянутся, и лихорадка спадёт. Я благодарю тебя и вручаю небольшой подарок..." } } } } },
    [276] = { d = 32.9, v = "tauren-male", n = { x = 320 }, c = { x = { { 0.00, "Многие годы гноллы из стаи Мохошкуров мирно жили в Болотине, но теперь их поголовье увеличилось." }, { 7.52, "Они вытаптывают наши прекрасные луга и вырубают лес на дрова!" }, { 12.86, "Чтобы спасти природу нашего края, придётся истребить часть гноллов." }, { 18.71, "Убей пятнадцать гноллов из стаи Мохошкуров и десять полукровок из стаи Мохошкуров." }, { 25.20, "Они водятся на юге, возле дворфийских Врат Альгаза. Когда справишься с заданием, вернись ко мне." } } }, t = { d = 12.5, g = 1, v = "tauren-male", n = { x = 116 }, c = { m = { { 0.00, "Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату..." }, { 6.67, "но твой подвиг, герой, заставил меня задуматься. Спасибо тебе!" } }, f = { { 0.00, "Теперь наши земли спасены! Признаться, раньше я с недоверием относился к вашему брату..." }, { 6.67, "но твой подвиг, героиня, заставил меня задуматься. Спасибо тебе!" } } } } },
    [277] = { d = 20.3, v = "tauren-male", n = { x = 201 }, c = { x = { { 0.00, "Гноллы из стаи Мохошкуров вырубают деревья Болотины и жгут древесину, греясь у костров. Я этого не потерплю!" }, { 9.05, "Отбери у гноллов их кремни, которыми они высекают огонь." }, { 13.64, "Кремни есть у всего клана, кроме мелких гноллов и полукровок из стаи Мохошкуров." } } }, t = { d = 11.9, v = "tauren-male", n = { x = 99 }, c = { x = { { 0.00, "Спасибо. Я раскрошу их в порошок и выброшу в море, и их уже никогда не используют для того, чтобы жечь живую древесную плоть." } } } } },
    [278] = { d = 31.8, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Немедленно принимайся за сбор материалов для нейтрализации взрывчатки. Паучий яд ты найдёшь у пауков у озера Лок Модан." }, { 8.29, "Слезу кроколиска можно отыскать там же. А вот заполучить кристалл Могроша будет нелегко." }, { 14.39, "Такие кристаллы добывают огры, живущие к северо-востоку отсюда, но и у огров они водятся нечасто." }, { 22.75, "Мы должны разминировать творение Чёрного Железа! Как только соберёшь все материалы, сразу же возвращайся, и я подготовлю состав." } } }, t = { d = 1.3, v = "dwarf-male", n = { x = 9 }, c = { x = { { 0.00, "Наконец-то!" } } } } },
    [279] = { d = 41.5, v = "human-male", n = { x = 476 }, c = { x = { { 0.00, "Мурлоки выходят из морских глубин и строят свои поселения на побережье." }, { 5.00, "Они нападают на наших рыбаков и торговцев, и это уже переходит всякие границы. Их надо остановить." }, { 12.18, "Один из этих мурлоков, Жрун, придумал устраивать засады на наших купцов на дорогах." }, { 18.07, "На мурлоков из племени Синежабрых нет никакой управы." }, { 21.68, "Творят, что хотят, а потом прячутся в ближайших поселениях, и всё – их уже не достать." }, { 27.54, "Наши торговцы в опасности, и мы готовы хорошо заплатить тому, кто возьмётся их защищать." }, { 34.01, "Жрун промышляет в речном заливе к северу отсюда. Принеси мне его голову, а заодно перебей его сородичей." } } }, t = { d = 6.4, g = 1, v = "human-male", n = { m = 63, f = 64 }, c = { m = { { 0.00, "Отлично!" }, { 1.15, "Вот твои деньги, ты честно их заработал, выполнив все обязательства." } }, f = { { 0.00, "Отлично!" }, { 1.15, "Вот твои деньги, ты честно их заработала, выполнив все обязательства." } } } } },
    [280] = { d = 30.2, v = "dwarf-male", n = { x = 320 }, c = { x = { { 0.00, "Я только сегодня видел мятежников Чёрного Железа, которые тащили к Дамбе большую бочку." }, { 5.97, "И рядом со мной не было ни одного горного пехотинца, поэтому никто их не остановил!" }, { 11.72, "Боюсь, они заложили сефорий у основания Дамбы, и она того и гляди взлетит на воздух! Дай-ка я смешаю все компоненты." }, { 21.99, "Вот, у меня получилась нейтрализующая смесь." }, { 25.42, "Скорее, возьми смесь и залей её в бочку, пока не поздно. Торопись!" } } }, t = { d = 5.2, v = "dwarf-male", n = { x = 59 }, c = { x = { { 0.00, "Вы вливаете нейтрализующую смесь, и из бочки доносится слабое шипение." } } } } },
    [281] = { d = 27.9, v = "human-male", n = { x = 321 }, c = { x = { { 0.00, "Не так давно мурлоки напали на торговый корабль \"Слепая принцесса\"." }, { 4.50, "Корабль удалось спасти, но эти подлые твари растащили почти весь груз, в том числе и одну очень ценную вещь, статуэтку Теренаса Менетила." }, { 13.87, "Её надо вернуть во что бы то ни стало." }, { 16.91, "Обыщи поселение мурлоков на побережье. Ищи сундуки, ящики, бочки – всё, что может быть связано с украденным грузом." }, { 24.71, "Найди статуэтку Менетила и верни её мне." } } }, t = { d = 20.0, v = "human-male", n = { x = 228 }, c = { x = { { 0.00, "Сундук отсырел, он весь исцарапан – это явно следы от когтей. Вы открываете сундук. Внутри – размокшая гнилая солома." }, { 8.07, "Можно предположить, что здесь спрятана некая ценная вещь, требующая бережного обращения. Вы разгребаете солому..." }, { 16.18, "...и находите несколько бутылок из красного стекла." } } } } },
    [282] = { d = 38.2, v = "dwarf-male", n = { x = 431 }, c = { x = { { 0.00, "Я собирался послать своего ученика к брату Сениру с отчётом, но парень он не слишком надёжный, а мне нужен кто-то, на кого действительно можно положиться." }, { 10.49, "Ну, то есть, конечно, если ты не будешь возражать." }, { 14.25, "Хм-м. Чтобы добраться до Караноса, тебе придётся пройти по тоннелю." }, { 19.15, "Перед тем как зайти в тоннель, заскочи к горному пехотинцу Талосу и поговори с ним – в тоннеле полным-полно троггов." }, { 27.27, "Сначала тебе нужно вернуться по дороге к Старой Наковальне, а потом направиться на восток." }, { 33.36, "Рядом с тоннелем Талос и стоит – найти его будет несложно." } } }, t = { d = 11.3, v = "dwarf-male", n = { x = 122 }, c = { x = { { 0.00, "Хм. Ну что ж, если Белобород послал тебя в Дун Морог по важному делу, то не мне тебя останавливать, верно?" }, { 7.42, "С другой стороны, пару советов-то я могу тебе дать..." } } } } },
    [283] = { d = 2.1, v = "human-male#114", n = { x = 18 }, c = { x = { { 0.00, "Бочка негромко шипит." } } }, t = { d = 17.6, g = 1, v = "dwarf-male", n = { m = 194, f = 196 }, c = { m = { { 0.00, "Огромное спасибо! Ты спас Каменную дамбу." }, { 2.98, "Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение." }, { 9.43, "Королевство и Альянс гордятся тобой, отважный герой!" }, { 13.40, "Дамба снова в безопасности... по крайней мере, пока..." } }, f = { { 0.00, "Огромное спасибо! Ты спасла Каменную дамбу." }, { 3.15, "Без твоей помощи террористы Чёрного Железа непременно разрушили бы это знаменитое сооружение." }, { 9.61, "Королевство и Альянс гордятся тобой, отважная героиня!" }, { 13.79, "Дамба снова в безопасности... по крайней мере, пока..." } } } } },
    [284] = { d = 14.0, v = "human-male#114", n = { x = 144 }, c = { x = { { 0.00, "Вы обыскиваете всё поселение мурлоков в этом районе, но статуэтки Менетила здесь нет." }, { 6.94, "Может быть, стоит проверить ближайшие несколько жилищ к северу и северо-востоку отсюда?" } } }, t = { d = 10.3, v = "human-male#114", n = { x = 96 }, c = { x = { { 0.00, "Эту бочку, похоже, никто не трогал. Вы открываете её..." }, { 4.57, "Запах валит вас с ног. Сыр слегка заплесневел, но он вполне съедобен!" } } } } },
    [285] = { d = 14.5, v = "human-male#114", n = { x = 140 }, c = { x = { { 0.00, "Вы обыскиваете ещё несколько жилищ мурлоков. Вот досада – опять ничего!" }, { 5.94, "...Но вы уверены, что всё получится." }, { 8.95, "Статуэтка Менетила наверняка где-то здесь, в одном из жилищ к северу." } } }, t = { d = 4.2, v = "human-male#114", n = { x = 41 }, c = { x = { { 0.00, "Бочка наполовину утоплена в грязи и мокрой траве..." } } } } },
    [286] = { d = 22.1, v = "human-male#114", n = { x = 230 }, c = { x = { { 0.00, "Вы достаёте бочку из грязи, открываете её и видите серебряную статуэтку, укрытую соломой." }, { 6.93, "Фигурка изображает юного длинноволосого паладина с воздетым над головою молотом." }, { 13.58, "Это, должно быть, и есть статуэтка Менетилова! Теперь вам надо вернуть её Карлу Борану в Гавань Менетилов." } } }, t = { d = 20.8, g = 1, v = "human-male", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз." }, { 6.50, "Ты сослужил нам хорошую службу и получишь обещанную награду." }, { 11.00, "Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время." } }, f = { { 0.00, "Капитан \"Слепой принцессы\" будет очень доволен, когда узнает, что мы сумели вернуть ценный груз." }, { 6.50, "Ты сослужила нам хорошую службу и получишь обещанную награду." }, { 11.10, "Радостно сознавать, что в этом мире ещё есть надёжные люди, на которых можно положиться, и особенно – в такое тяжёлое и неспокойное время." } } } } },
    [287] = { d = 36.4, v = "dwarf-male", n = { x = 401 }, c = { x = { { 0.00, "Я не успеваю с донесением, и твоя помощь, мне бы пригодилась." }, { 4.31, "Я сумел узнать, где засели тролли, но их там было столько, что я побоялся лезть туда." }, { 10.54, "Вот что мне нужно... Спустись в пещеру, порыскай там, прибей пару-другую троллей и возвращайся ко мне." }, { 19.02, "Отправляйся из Караноса по северной дороге." }, { 22.12, "Когда перейдёшь через мост, следуй на запад по замёрзшей реке, пока не доберёшься до Заледеневшего озера." }, { 29.30, "На западном берегу обнаружишь Посёлок Пивоваров. Форт Мерзлогривов находится к юго-западу от него." } } }, t = { d = 19.9, v = "dwarf-male", n = { x = 206 }, c = { x = { { 0.00, "А! Я так и думал, что тебе будет несложно найти это место, ведь мои указания были предельно чётки... Дай-ка мне закончить донесение." }, { 9.36, "Он приносит бумагу и что-то быстро на ней пишет." }, { 13.17, "Вот! Ха-ха, теперь это совсем забавно... Думаю, ты не откажешься помочь мне ещё разок?" } } } } },
    [288] = { d = 31.2, v = "human-male#50", n = { x = 356 }, c = { x = { { 0.00, "Когда-то я был первым помощником на \"Владычице\", линейном корабле кул-тирасской Третьей флотилии. Обречённой флотилии..." }, { 8.47, "Во время последнего плавания на нас напали красные драконы. А ими правили орки!" }, { 14.28, "У нас не было ни единого шанса спастись от драконьего огня, и все корабли были сожжены и потоплены у побережья. Я один уцелел в этом кошмаре." }, { 24.21, "Ох, как же раскалывается голова! Погоди, сейчас я выпью чего-нибудь, немного приду в себя и продолжу." } } }, t = { d = 4.4, v = "human-male#50", n = { x = 47 }, c = { x = { { 0.00, "Вот! И голова не болит, и язык развязался. Спасибо, приятель!" } } } } },
    [289] = { d = 38.6, v = "human-male#50", n = { x = 438 }, c = { x = { { 0.00, "*Приободрившись, Фитсиммонс продолжает рассказывать...*" }, { 3.72, "Я единственный уцелевший из всех матросов злополучной Кул-Тирасской Третьей флотилии, погибшей у северного побережья." }, { 13.83, "И хотя я последний из команды, чьё сердце бьётся и кто ещё дышит, я не единственный, кто ещё бродит по земле!" }, { 21.18, "На одном из наших кораблей хранилось великое, ужасное сокровище, и его потусторонняя зловещая сила держит души моих собратьев и не даёт им покинуть гниющие остовы кораблей." }, { 33.19, "Если ты сможешь их освободить, тогда, может быть, они избавятся от проклятия." } } }, t = { d = 4.6, v = "human-male#50", n = { x = 54 }, c = { x = { { 0.00, "Багодарю тебя. И прими благодарность моих несчастных собратьев." } } } } },
    [290] = { d = 33.1, v = "human-male#50", n = { x = 387 }, c = { x = { { 0.00, "Чтобы избавиться от проклятия и освободить моих верных товарищей, нужно найти и очистить эту... проклятую штуковину..." }, { 7.60, "спрятанную на моём корабле! Не знаю, что это такое, знаю только, что эта штука хранится в корабельном сейфе, а ключ от сейфа – у капитана Халиндора." }, { 17.84, "Старина капитан снится мне до сих пор. Я знаю, он сейчас на \"Отважном\" – нашем несчастном корабле." }, { 24.24, "Постарайся добыть ключ от сейфа, открой его и возьми эту вещь." }, { 28.82, "Потом отнеси её в город и отдай жрецу Глорину Стальному Лбу." } } }, t = { d = 4.0, v = "human-male#50", n = { x = 44 }, c = { x = { { 0.00, "Ключ насквозь проржавел, но замок открылся без труда." } } } } },
    [291] = { d = 34.1, g = 1, v = "dwarf-male", n = { m = 380, f = 382 }, c = { m = { { 0.00, "Замечательно! Отнеси моё донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием." }, { 8.32, "Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд." }, { 13.18, "Что? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы." }, { 24.36, "Кстати, будь добр, не говори о том, как ты мне помогал." }, { 28.20, "Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица." } }, f = { { 0.00, "Замечательно! Отнеси моё донесение сенатору Бэрину Краснокамню. Он мрачный тип, постарайся не заразиться от него унынием." }, { 8.32, "Ты найдёшь его в Стальгорне, в палате, где король Магни вершит суд." }, { 13.18, "Что? Не знаешь дороги в Стальгорн? От Караноса возьми к северу, перейди мост, затем иди по восточной дороге – там по обе стороны штандарты – и вверх по склону горы." }, { 24.36, "Кстати, будь добра, не говори о том, как ты мне помогала." }, { 28.26, "Понимаешь, я не хочу, чтобы подумали, будто я тут не тружусь в поте лица." } } }, t = { d = 18.6, v = "dwarf-male", n = { x = 191 }, c = { x = { { 0.00, "Он быстро просматривает донесение." }, { 2.80, "По приказу КОРОЛЯ!? Магни совсем спятил! И ещё этот проклятый Белобород... Значит, взял дела в свои руки?" }, { 10.89, "Сенат этому не обрадуется, вовсе не обрадуется." }, { 14.53, "Что, ты ещё здесь? Иди отсюда, пока я охрану не вызвал!" } } } } },
    [292] = { d = 23.0, v = "human-male#114", n = { x = 223 }, c = { x = { { 0.00, "Внутри сундука лежит тёмный шар, источающий зловещее свечение." }, { 4.77, "Это и есть то сокровище, о котором говорил Фитсиммонс: проклятое Око Палета." }, { 11.02, "Отнесите проклятое Око Палета дворфийскому жрецу Глорину Стальному Лбу в Гавань Менетилов. Попросите его снять проклятие с Ока." } } }, t = { d = 21.1, g = 1, v = "dwarf-male", n = { m = 221, f = 221 }, c = { m = { { 0.00, "Око Палета? Поразительно! Хмм... с ним явно что-то не так. Говоришь, ты нашёл его среди обломков судна? Это многое объясняет!" }, { 8.26, "Но как же Око попало на корабль Третьей флотилии?.." }, { 12.14, "Неудивительно, что этот Фитсиммонс так перепугался. Проклятое Око Палета кого угодно выбьет из колеи." } }, f = { { 0.00, "Око Палета? Поразительно! Хмм... с ним явно что-то не так. Говоришь, ты нашла его среди обломков судна? Это многое объясняет!" }, { 9.23, "Но как же Око попало на корабль Третьей флотилии?.." }, { 13.12, "Неудивительно, что этот Фитсиммонс так перепугался. Проклятое Око Палета кого угодно выбьет из колеи." } } } } },
    [293] = { d = 19.4, v = "dwarf-male", n = { x = 228 }, c = { x = { { 0.00, "Я не могу снять проклятие с Ока Палета. Это людское творение, и поэтому тебе следует направиться в Штормград." }, { 7.40, "Найди того, кто сумеет тебе помочь. Обратись к архиепископу Бенедикту." }, { 12.19, "Он главный в Соборе Света Штормграда, и сможет дать тебе наставления. Надеюсь, у тебя всё получится." } } }, t = { d = 18.3, v = "human-male#170", n = { x = 214 }, c = { x = { { 0.00, "Это Око Палета. Определённо, оно видело много скорбей и печалей..." }, { 4.60, "может быть, стало свидетелем некоей ужасной, поистине ужасной трагедии." }, { 9.60, "Сейчас я очищу его, ибо Очи созданы для того, чтобы сиять ярким светом, и их сила становится опасной, если они запятнаны порчей." } } } } },
    [294] = { d = 27.1, v = "dwarf-male", n = { x = 309 }, c = { x = { { 0.00, "Придётся признать, что положение отчаянное. Когда мы раскопали эти кости, ящеры немедленно атаковали нас." }, { 7.15, "Многие из братьев были разорваны на месте, а я, Меррин и бедолага геолог оказались в ловушке здесь, наверху." }, { 14.96, "Помоги очистить Болотину от ящеров. Крапчатые ящеры и крапчатые крикуны водятся к западу от этого утёса." }, { 22.13, "Убей по десять тварей каждого вида. Это будет началом моей мести." } } }, t = { d = 10.6, v = "dwarf-male", n = { x = 111 }, c = { x = { { 0.00, "Я понимаю, что убийство – грязная и опасная работа." }, { 3.50, "Но если бы я не поклялся остаться рядом с геологом и Меррин, я бы и сам отправился с тобой." } } } } },
    [295] = { d = 9.8, v = "dwarf-male", n = { x = 109 }, c = { x = { { 0.00, "Пора нанести им сокрушительный удар. Внизу бродят стаи крапчатых смертехватов и крапчатых острозубов." }, { 6.99, "Убей по десять гадов каждого вида!" } } }, t = { d = 3.1, g = 1, v = "dwarf-male", n = { m = 30, f = 32 }, c = { m = { { 0.00, "Ты не представляешь, как ты мне помог!" } }, f = { { 0.00, "Ты не представляешь, как ты мне помогла!" } } } } },
    [296] = { d = 32.0, v = "dwarf-male", n = { x = 372 }, c = { x = { { 0.00, "Пока тебя не было, я заметил, что среди этих тварей есть один выдающийся экземпляр." }, { 5.75, "Он крупнее остальных и отличается особой свирепостью." }, { 9.55, "Могу поклясться, что он – их вожак, это он привёл их сюда и подначил разорить шахту." }, { 15.49, "Сослужи мне последнюю службу. Зарлозуба надо предать правосудию." }, { 19.89, "А если принять во внимание тяжесть его преступлений, правосудие здесь может быть только одно: смерть на месте!" }, { 27.46, "Убей его и в доказательство принеси мне один из его когтей." } } }, t = { d = 20.8, g = 1, v = "dwarf-male", n = { m = 239, f = 241 }, c = { m = { { 0.00, "Спасибо. Мы не забудем того, что ты сделал для нас." }, { 3.54, "Сколько ни в чём не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах." }, { 11.53, "Но ты отомстил за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни." } }, f = { { 0.00, "Спасибо. Мы не забудем того, что ты сделала для нас." }, { 3.62, "Сколько ни в чём не повинных дворфов полегло в этой злосчастной шахте – а ведь они просто трудились на своих местах." }, { 11.62, "Но ты отомстила за наших безвинно погибших братьев, и теперь ящеры дважды подумают, прежде чем нападать на владения короля Магни." } } } } },
    [297] = { d = 26.7, v = "dwarf-male", n = { x = 312 }, c = { x = { { 0.00, "Незадолго до появления в раскопе троггов мы обнаружили множество странных резных идолов." }, { 6.04, "Изучить их мы не успели, потому что вскоре после этого трогги вытеснили нас из развалин!" }, { 12.09, "А идолы оказывают на этих тварей странное воздействие – превращают их в берсерков!" }, { 18.07, "Отбей идолов у троггов и принеси мне – я хочу их изучить. Идолов ты найдёшь у троггов – а их в раскопе более чем достаточно." } } }, t = { d = 11.4, g = 1, v = "dwarf-male", n = { m = 121, f = 123 }, c = { m = { { 0.00, "Ты добыл их! Хвалю!" }, { 1.74, "И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадал. Я буду с интересом следить за твоей судьбой... Ты подаёшь надежды." } }, f = { { 0.00, "Ты добыла их! Хвалю!" }, { 1.87, "И хотя там полно троггов-берсерков, ты, кажется, не сильно пострадала. Я буду с интересом следить за твоей судьбой... Ты подаёшь надежды." } } } } },
    [298] = { d = 17.6, v = "dwarf-male", n = { x = 173 }, c = { x = { { 0.00, "Мне нужно отправить в Телсамар отчёт о ходе работ и запрос на получение нового груза пороха! Вот мой отчёт." }, { 8.92, "Отнеси его Джерну Шлеморогу, он наш представитель в Телсамаре." }, { 14.31, "Задание не сложное, но достаточно важное." } } }, t = { d = 18.4, v = "dwarf-male", n = { x = 205 }, c = { x = { { 0.00, "Ха! У Железняка проблемы с троггами. Интересно, порох ему нужен для продолжения раскопок или для войны с этими тварями..." }, { 8.52, "Так или иначе, он будет потрачен не зря!" }, { 11.71, "Но вот что странно, несколько недель назад я послал ему немало пороха. Интересно, куда он делся." } } } } },
    [299] = { d = 43.2, g = 1, v = "dwarf-male", n = { m = 474, f = 475 }, c = { m = { { 0.00, "Перед самым вторжением я обнаружил табличку с письменами, именуемую скрижалью Гоаз." }, { 6.70, "Несколько кусков отломилось, и в четырёх местах текст обрывается." }, { 11.19, "Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\"." }, { 15.92, "Боюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты молод и полон сил." }, { 23.99, "Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру." }, { 30.87, "Ищи среди древних артефактов или там, где почва разрыхлена." }, { 35.00, "Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!" } }, f = { { 0.00, "Перед самым вторжением я обнаружил табличку с письменами, именуемую скрижалью Гоаз." }, { 6.70, "Несколько кусков отломилось, и в четырёх местах текст обрывается." }, { 11.19, "Там говорится о некоем \"замысле богов\" и о \"проклятом пророчестве\"." }, { 15.92, "Боюсь, у нас мало времени. Я уже слишком стар, чтобы сражаться с этими тварями в раскопе. Но ты молода и полна сил." }, { 24.13, "Обыщи раскоп и найди четыре недостающих фрагмента скрижали – Адос, Модр, Голм и Неру." }, { 31.01, "Ищи среди древних артефактов или там, где почва разрыхлена." }, { 35.14, "Найди эти фрагменты и принеси их сюда, и, быть может, тогда я сумею расшифровать письмена и разгадать эту тайну!" } } }, t = { d = 16.8, g = 1, v = "dwarf-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудился. Будем надеяться, теперь я сумею расшифровать письмена титанов." }, { 8.20, "Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землёй\". Похоже, грядут грандиозные перемены." } }, f = { { 0.00, "Итак, скрижаль Гоаз восстановлена! Ты хорошо потрудилась. Будем надеяться, теперь я сумею расшифровать письмена титанов." }, { 8.13, "Я уже разбираю новые слова! Э... тут написано: \"Древние боги... томятся в цепях под землёй\". Похоже, грядут грандиозные перемены." } } } } },
    [301] = { d = 27.9, v = "dwarf-male", n = { x = 325 }, c = { x = { { 0.00, "Мы не можем выдать Сталекруту новую партию взрывчатого порошка без одобрения Стальгорна." }, { 6.15, "Тебе придётся отнести его отчёт в штаб-квартиру Лиги Исследователей." }, { 11.26, "Вот он. Отдай его геологу Грозовой Вершине, да не забудь сразу отскочить в сторону. Грозовая Вершина – горячая голова." }, { 19.28, "Его совсем не порадуют новости о медленном продвижении работ." }, { 23.94, "Грозовую Вершину можно найти в Зале исследователей." } } }, t = { d = 12.1, v = "dwarf-male", n = { x = 110 }, c = { x = { { 0.00, "Проклятый Железняк! Я послал ему целый воз пороха ещё неделю назад, но он не потрудился упомянуть об этом в отчёте. Так... куда делся порох?!?" } } } } },
    [302] = { d = 26.6, g = 1, v = "dwarf-male", n = { m = 292, f = 293 }, c = { m = { { 0.00, "Если Сталекруту нужен порох, то, именем короля Магни, он его получит!" }, { 4.83, "Я уже отправил вестника в Телсамар с соответствующим приказом Джерну Шлеморогу." }, { 11.40, "Он подготовит груз пороха и прочих припасов для Сталекрута." }, { 15.97, "И ещё одно: я хочу, чтобы ты лично проследил за доставкой груза." }, { 20.37, "Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба." } }, f = { { 0.00, "Если Сталекруту нужен порох, то, именем короля Магни, он его получит!" }, { 4.83, "Я уже отправил вестника в Телсамар с соответствующим приказом Джерну Шлеморогу." }, { 11.40, "Он подготовит груз пороха и прочих припасов для Сталекрута." }, { 15.97, "И ещё одно: я хочу, чтобы ты лично проследила за доставкой груза." }, { 20.54, "Последний груз не добрался до адресата, поэтому держи ушки на макушке и смотри в оба." } } }, t = { d = 16.9, g = 1, v = "dwarf-male", n = { m = 186, f = 187 }, c = { m = { { 0.00, "Что? Грозовая Вершина хочет, чтобы ты лично проследил за доставкой груза к Железняку?" }, { 6.26, "Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли." }, { 12.77, "Вы чуть-чуть разминулись, я отправил их совсем недавно." } }, f = { { 0.00, "Что? Грозовая Вершина хочет, чтобы ты лично проследила за доставкой груза к Железняку?" }, { 6.27, "Я... думаю, это неплохая идея, но беда в том, что Хальдар и носильщики, Миран и Сайан, уже вышли." }, { 12.78, "Вы чуть-чуть разминулись, я отправил их совсем недавно." } } } } },
    [303] = { d = 37.2, v = "dwarf-male", n = { x = 419 }, c = { x = { { 0.00, "Война свирепствует повсюду: и в наших краях, и в чужих землях тоже." }, { 4.55, "Пока наши могучие воины не щадят своих жизней, сражаясь во имя Альянса вдали от дома, на наших собственных землях бесчинствуют дворфы Чёрного Железа." }, { 14.98, "Они разрушили один из мостов Тандола, потом пал и Дун Модр." }, { 19.54, "Тебе нужно собрать добровольцев и сдержать натиск врагов." }, { 23.45, "Если сумеешь убить десять дворфов Чёрного Железа, пять проходчиков, пять саботажников и пять подрывников, тогда, может быть, мы и продержимся до подхода подкрепления. И поторопись! У нас мало времени." } } }, t = { d = 18.2, g = 1, v = "dwarf-male", n = { m = 203, f = 205 }, c = { m = { { 0.00, "Ты всё сделал как надо, герой. Ты доказал свою доблесть и преданность королю Магни, за что тебе честь и хвала!" }, { 7.53, "Боевой дух Чёрного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда..." }, { 14.32, "если этот треклятый резерв всё-таки подойдёт..." } }, f = { { 0.00, "Ты всё сделала как надо, героиня. Ты доказала свою доблесть и преданность королю Магни, за что тебе честь и хвала!" }, { 7.82, "Боевой дух Чёрного Железа подорван, и у нас появилась возможность выгнать их с нашей земли навсегда..." }, { 14.61, "если этот треклятый резерв всё-таки подойдёт..." } } } } },
    [305] = { d = 33.9, v = "dwarf-male", n = { x = 382 }, c = { x = { { 0.00, "Знаешь... как-то мне неспокойно на сердце." }, { 3.19, "Моя благоверная Меррин работает в изыскательской группе на раскопе Вельгара. Писала мне каждую неделю весь прошлый месяц." }, { 11.51, "А теперь вдруг пропала. Уже две недели ни слуху, ни духу. Наверняка что-то случилось!" }, { 18.34, "Длинная Коса обещал, что, если я вскорости не получу никаких известий, он пришлёт мне разведчика, который проверит, что стало с экспедицией." }, { 27.86, "Как я понимаю, ты и есть этот разведчик. Разыщи Меррин на раскопе к востоку отсюда!" } } }, t = { d = 2.5, g = 1, v = "dwarf-female#33", n = { m = 20, f = 20 }, c = { m = { { 0.00, "Слава богам, ты нас нашёл!" } }, f = { { 0.00, "Слава богам, ты нас нашла!" } } } } },
    [306] = { d = 41.0, v = "dwarf-female#33", n = { x = 453 }, c = { x = { { 0.00, "Это было ужасно! Мы обнаружили несколько очень редких артефактов." }, { 4.71, "Пока мы занимались раскопками, нам всё чаще и чаще начали попадаться огромные кости." }, { 10.95, "Всё случилось внезапно. На нас напали крапчатые ящеры, их было значительно больше, чем нас." }, { 17.33, "Почти все наши погибли в неравной схватке." }, { 20.66, "Остались только мы трое. Ормер – он такой храбрый, настоящий герой, – спас меня и проспектора, он прикрывал нас, пока мы бежали в укрытие." }, { 29.97, "А теперь мы в ловушке, и вся наша работа пропала!" }, { 33.76, "Вот, отнеси эту записку моему дорогому Таррелу. Я ему всё написала подробно. Он разберётся." } } }, t = { d = 13.5, v = "dwarf-male", n = { x = 157 }, c = { x = { { 0.00, "Какая ужасная новость! Это счастье, что уцелели хотя бы трое. Когда же закончится эта череда злоключений?!" }, { 7.26, "Когда же наконец подданные короля Магни забудут, что значит жить в постоянном страхе?!" } } } } },
    [307] = { d = 31.8, v = "dwarf-male", n = { x = 374 }, c = { x = { { 0.00, "Рудник у Серебряного ручейка давно выработан." }, { 3.15, "Лига рудокопов превратила его в склад, но теперь туда забрались кобольды и наложили свои грязные лапы на дворфийские инструменты!" }, { 12.48, "Рано или поздно мы искореним этих паразитов, но Лига хочет спасти оборудование, пока в шахту не спустились воины и не разнесли всё к демонам." }, { 22.13, "Задача твоя не из простых – помощники тебе не помешают." }, { 26.21, "Оборудование находится в ящиках лиги Рудокопов, разбросанных по всему руднику." } } }, t = { d = 8.6, v = "dwarf-male", n = { x = 96 }, c = { x = { { 0.00, "Там много кобольдов? Жду не дождусь приказа очистить от них рудник. Как подумаю, что они там хозяйничают, аж киплю весь!" } } } } },
    [309] = { d = 13.7, v = "dwarf-male", n = { x = 141 }, c = { x = { { 0.00, "Что ж, в путь?" }, { 1.42, "Для начала надо доставить Железняку порох. Вес немалый, а здесь небезопасно – кто знает, что ещё замышляют дворфы Чёрного Железа. С тобой мне будет куда спокойнее." } } }, t = { d = 22.0, v = "dwarf-male", n = { x = 255 }, c = { x = { { 0.00, "О, слава Свету, вот мой порох. Но новости и верно тревожные." }, { 4.25, "Только подумать, что находятся сторонники Чёрного Железа, способные снабдить их первосортными материалами для выполнения гнусных замыслов." }, { 14.08, "Но над этим пусть поломает голову кто-нибудь другой и не сегодня. А я найду этому пороху отличное применение." } } } } },
    [310] = { d = 31.3, v = "dwarf-female", n = { x = 346 }, c = { x = { { 0.00, "Не могу не признать, эти Громовары делают славные напитки. Но они должны понять, что не только у них это хорошо получается!" }, { 8.44, "Может, ты поможешь преподать им урок..." }, { 11.50, "Вот, возьми-ка этот бочонок жгучего пива Ячменоваров." }, { 15.32, "Проберись в подвал \"Громоварки\" в Караносе и подмени один бочонок их громового эля." }, { 21.07, "И посмотрим, не скажут ли их заказчики, что моё пиво лучше, чем Громоваров!" }, { 27.14, "Если бочонки охраняются, тебе придётся отвлечь стражу..." } } }, t = { d = 7.4, v = "dwarf-female", n = { x = 84 }, c = { x = { { 0.00, "Вы быстро ставите бочонок жгучего пива Ячменоваров, что дала вам Марлетта, среди бочек громового эля." } } } } },
    [311] = { d = 13.9, v = "human-male#114", n = { x = 119 }, c = { x = { { 0.00, "Подсунув бочонок жгучего пива Марлетты в подвал в подвал \"Громоварки\" в Караносе, вы хватаете бочонок громового эля в качестве доказательства..." } } }, t = { d = 13.5, v = "dwarf-female", n = { x = 153 }, c = { x = { { 0.00, "Неплохо! Тебе, небось, нелегко было проскользнуть мимо их охраны?" }, { 4.85, "Да всё равно – прими мою благодарность, и если когда-нибудь тебе понадобится крепкое пивко с огоньком, вспомни Ячменевцев!" } } } } },
    [312] = { d = 29.9, v = "dwarf-male", n = { x = 339 }, c = { x = { { 0.00, "У меня был месячный запас вяленой солонины на зиму. Я запер его в ларь, чтобы медведи не добрались." }, { 6.74, "Но пока я охотился на оленей, этот изверг, Старый Ледобород, уволок мой мясной ларь! Он не смог, однако, взломать ториевый замок." }, { 15.54, "Но я же с голоду помру, если не верну своё мясо!" }, { 19.25, "Ты вроде посильнее меня будешь. Может, сумеешь вернуть мой запас?" }, { 23.78, "Нога моя совсем плоха – мне не суметь быстро забраться в пещеру и утащить оттуда ларь." } } }, t = { d = 7.1, v = "dwarf-male", n = { x = 79 }, c = { x = { { 0.00, "Какая же ты добрая душа! Благодаря твоей отваге я не подохну с голоду, когда начнутся зимние бури." } } } } },
    [313] = { d = 29.8, g = 1, v = "dwarf-male", n = { m = 340, f = 340 }, c = { m = { { 0.00, "Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы!" }, { 6.36, "К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь покаказать мне, на что ты способен?" }, { 14.16, "Ладно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее." }, { 19.01, "Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса?" }, { 24.91, "Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!" } }, f = { { 0.00, "Управлять осадным орудием не каждому по плечу. Тут нужна железная хватка и стальные нервы!" }, { 6.36, "К счастью, у меня есть и то, и другое! А у тебя? Кишка-то не тонка? Хочешь покаказать мне, на что ты способна?" }, { 14.07, "Ладно... Я хочу сделать свою машинку, Троллеукладчика, малость поудобнее." }, { 18.92, "Не добудешь ли ты мне охапку грив вендиго из Серой берлоги, что к западу от Караноса?" }, { 24.83, "Эти гривы будут прекрасной прокладкой для кабины Троллеукладчика!" } } }, t = { d = 7.7, g = 1, v = "dwarf-male", n = { x = 70 }, c = { m = { { 0.00, "О, эти гривы мне очень пригодятся! Ты крепкий орешек, герой, бьюсь об заклад, я о тебе ещё услышу!" } }, f = { { 0.00, "О, эти гривы мне очень пригодятся! Ты крепкий орешек, героиня, бьюсь об заклад, я о тебе ещё услышу!" } } } } },
    [314] = { d = 30.3, v = "dwarf-female#34", n = { x = 360 }, c = { x = { { 0.00, "Мы услышали шум среди ночи. Поутру не досчитались в отаре двух баранов." }, { 5.50, "Эта подлая тварь Вагаш покушается на наше единственное добро!" }, { 9.60, "Поскольку большая часть армии короля Магни сражается в дальних краях за дело Альянса, некому приструнить этого Вагаша." }, { 17.71, "Может, тебе достанет отваги найти эту тварь и прикончить? Принеси мне его клык, и я тебя награжу." }, { 24.08, "Вагаш рыщет как раз вон над тем выгоном, но предупреждаю: это смертельно опасная тварюга." } } }, t = { d = 12.2, v = "dwarf-female#34", n = { x = 145 }, c = { x = { { 0.00, "Отлично! Верон будет так рад этой доброй вести! Убить Вагаша – дело непростое." }, { 5.14, "Сдаётся мне, настанет день – и ты будешь сражаться вместе с воинами короля Магни на передовой Альянса!" } } } } },
    [315] = { d = 38.9, v = "dwarf-male", n = { x = 444 }, c = { x = { { 0.00, "Я тут по делу, а дело моё – создать самый лучший портер! Я знаю, я смогу – пивоварение у меня в крови." }, { 6.80, "Просто надо составить правильный рецепт..." }, { 10.01, "Тролльское племя Мерзлогривов высоко в восточных холмах выращивает одну травку, звездолист называется." }, { 17.77, "Они используют её в странных ритуалах своего племени. Нам, дворфам, она не особо нужна, но у неё неповторимый вкус..." }, { 25.65, "И я хочу поэкспериментировать с ней при варении пива!" }, { 29.69, "Добудь мне немного звездолиста – его можно \"отнять\" у ясновидцев племени Мерзлогривов или стянуть из тролльских корзинок с травами." } } }, t = { d = 9.7, v = "dwarf-male", n = { x = 102 }, c = { x = { { 0.00, "Великолепно! Прямо не терпится испробовать эту травку в одном из моих рецептов. Думаю, вот в этом она особенно хорошо пойдёт..." } } } } },
    [317] = { d = 27.4, v = "dwarf-male", n = { x = 316 }, c = { x = { { 0.00, "Я веду подготовку к выполнению боевого задания Осадной бригады." }, { 4.32, "Дело будет долгим, и мне нужно укомплектовать мой паровик провизией на месяц." }, { 9.70, "Так что пока ребята из Стальной Решётки работают с моим танком, не отправишься ли ты на охоту?" }, { 16.50, "Мне нужен мех, чтобы сделать кровать, и кабанина для еды. Кабаны – на мясо, медведи – на мех..." }, { 22.70, "Этих животных можно найти в снежных полях к югу от Серого логова." } } }, t = { d = 4.7, g = 1, v = "dwarf-male", n = { m = 48, f = 49 }, c = { m = { { 0.00, "Клянусь бородой Магни, ты славно поохотился! Спасибо тебе." } }, f = { { 0.00, "Клянусь бородой Магни, ты славно поохотилась! Спасибо тебе." } } } } },
    [318] = { d = 34.9, v = "dwarf-male", n = { x = 402 }, c = { x = { { 0.00, "Регольд Ячменовар не боится экспериментировать со своим варевом. Продукт эксперимента порой хорош на вкус, а порой нет, а иногда..." }, { 8.98, "самого крепкого дворфа уложит в стельку." }, { 12.29, "Редгольд живёт в Посёлке Пивоваров, к западу от Караноса, и один из его напитков, \"Вечное сияние\", – как раз то, что мне надо. Он согреет меня в пути." }, { 22.46, "И... этот благословенный напиток горит так, что я могу залить его в топку паровика – и будет такой силовой импульс!" }, { 30.00, "Эта тактическая уловка помогала мне выбираться из многих переделок." } } }, t = { d = 3.6, v = "dwarf-male", n = { x = 34 }, c = { x = { { 0.00, "Толступузу нужно \"Вечное сияние\"? Ну, ладно." } } } } },
    [319] = { d = 27.1, g = 1, v = "dwarf-male", n = { m = 309, f = 312 }, c = { m = { { 0.00, "У меня есть бочонок \"Вечного сияния\", но... не мог бы ты оказать мне услугу?" }, { 5.06, "Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко..." }, { 13.95, "Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взял это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение." } }, f = { { 0.00, "У меня есть бочонок \"Вечного сияния\", но... не могла бы ты оказать мне услугу?" }, { 5.09, "Посёлку Пивоваров не помешала бы помощь в борьбе против дикого зверья, что бродит вокруг. Иногда они подходят слишком близко..." }, { 13.98, "Мы не боимся этих медведей, кошек и кабанов – ни один уважающий себя дворф не станет их бояться, – но если бы ты взяла это зверьё на себя, у нас было бы больше времени на ремесло и пивоварение." } } }, t = { d = 6.2, v = "dwarf-male", n = { x = 70 }, c = { x = { { 0.00, "Спасибо тебе. Славно будет заняться ремеслом без этого рыка да хрюканья за околицей!" } } } } },
    [320] = { d = 4.2, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Вот твоя бочка \"Вечного сияния\". И спасибо тебе за охоту." } } }, t = { d = 4.6, v = "dwarf-male", n = { x = 44 }, c = { x = { { 0.00, "Ух ты! Пожалуй, открою-ка я его прямо сейчас да попробую..." } } } } },
    [321] = { d = 38.5, v = "dwarf-male", n = { x = 448 }, c = { x = { { 0.00, "Эти обломки погибших кораблей – останки Кул-Тирасской Третьей флотилии, сожжённой и потопленной красными драконами во время последней Великой войны." }, { 10.63, "Флотилия вышла из Лордерона, и с ней шёл эльфийский боевой корабль – \"Орлик\"." }, { 16.15, "Он вёз груз светлостали и присоединился к Третьей флотилии, ища покровительства и защиты." }, { 22.30, "По иронии судьбы, он был потоплен теми же драконами, от которых пытался спастись..." }, { 28.23, "Ладно, краткий исторический экскурс будем считать завершённым. \"Орлик\" затонул к югу от Гавани Менетилов." }, { 35.29, "Если найдёшь светлосталь, принеси её мне." } } }, t = { d = 22.1, v = "dwarf-male", n = { x = 255 }, c = { x = { { 0.00, "Сундук весь размок, его обшивка сломана. На стенках внутри и снаружи видны глубокие следы когтей..." }, { 6.70, "как будто в нём шарились мурлоки и унесли все сокровища." }, { 11.05, "Но в самом дальнем углу завалялся один-единственный слиток светлостали. К несчастью, этого мало." }, { 17.65, "Для того чтобы выковать достойное оружие, вам нужно больше." } } } } },
    [322] = { d = 21.0, g = 1, v = "dwarf-male", n = { m = 234, f = 234 }, c = { m = { { 0.00, "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор." }, { 6.68, "Металл, который ты нашёл, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю." }, { 13.07, "Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!" } }, f = { { 0.00, "В Квартале Дворфов Штормграда есть оружейник, мастер по светлостали. Зовут его Гриманд Элмор." }, { 6.68, "Металл, который ты нашла, я упакую в сундук. Отнеси его Гриманду и расскажи ему свою историю." }, { 13.68, "Я уверен, он не откажет тебе в помощи и изготовит оружие – оружие, которого убоится сам Морбент Скверн!" } } }, t = { d = 21.5, v = "dwarf-male", n = { x = 240 }, c = { x = { { 0.00, "Да, занятный рассказ. И светлосталь! Я уже много лет не работал с этим материалом. Для меня это будет великая честь." }, { 8.53, "А когда всё закончится, ты непременно зайди ко мне и расскажи о своей битве с некромантом." }, { 15.02, "Но не будем опережать события. Первым делом -оружие, которым ты сокрушишь Морбента Скверна..." } } } } },
    [323] = { d = 19.6, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Морбент Скверн – могущественный некромант и союзник тёмных всадников." }, { 4.83, "Я не могу послать тебя на битву с ним, не испытав прежде твою силу." }, { 9.92, "Храбрость твою я не подвергаю сомнению, но если ты в самом деле хочешь выступить против некроманта, сразись сначала с его приспешниками." } } }, t = { d = 8.1, v = "human-male", n = { x = 94 }, c = { x = { { 0.00, "Без сомнения, в бою тебе нет равных. Благодаря твоей решимости мы сможем положить конец деяниям Морбента Скверна!" } } } } },
    [324] = { d = 14.2, v = "human-male#114", n = { x = 150 }, c = { x = { { 0.00, "Вы забрали слиток светлостали из отсыревшего сундука, но похоже, что остальные слитки растащили мурлоки." }, { 8.18, "Найдите мурлоков-налётчиков у остова \"Орлика\" и отберите у них светлосталь." } } }, t = { d = 5.5, v = "dwarf-male", n = { x = 42 }, c = { x = { { 0.00, "Ага, вот и материал! Ну что, пора бы пустить его в дело, а?" } } } } },
    [325] = { d = 6.6, g = 1, v = "dwarf-male", n = { x = 66 }, c = { m = { { 0.00, "Вот оружие против твоего врага. путник, иди и сражайся. Удачи тебе, возвращайся со славой!" } }, f = { { 0.00, "Вот оружие против твоего врага. путница, иди и сражайся. Удачи тебе, возвращайся со славой!" } } }, t = { d = 6.9, v = "human-male", n = { x = 70 }, c = { x = { { 0.00, "О, это именно то, что сразит Морбента Скверна! Отлично!" }, { 4.08, "Готовься. Скверн теперь – не жилец." } } } } },
    [332] = { d = 18.9, v = "human-male", n = { x = 218 }, c = { x = { { 0.00, "Если тебя интересует вино, так лучшее вино в Штормграде продаёт семейство Галлина!" }, { 5.88, "Это недалеко – в Торговом квартале, неподалёку от городских каналов." }, { 10.66, "Возьми этот талон, отнеси его моей сестре Сюзетте и получишь бутылку нашего знаменитого \"Пино нуар\". Не пожалеешь!" } } }, t = { d = 10.3, g = 1, v = "human-female#111", n = { m = 116, f = 117 }, c = { m = { { 0.00, "Вы знакомы с Ренато? В таком случае - только для вас, мсье... Бутылка нашего особого \"Пино нуар\"!" }, { 6.24, "Такого вы не попробуете больше нигде во всём Азероте!" } }, f = { { 0.00, "Вы знакомы с Ренато? В таком случае - только для вас, мадам... Бутылка нашего особого \"Пино нуар\"!" }, { 6.31, "Такого вы не попробуете больше нигде во всём Азероте!" } } } } },
    [333] = { d = 24.3, v = "human-male", n = { x = 275 }, c = { x = { { 0.00, "Кажется, мы уже встречались. Наверное, насчёт покупки брони и походной одежды. Кстати, ожидается суровая зима..." }, { 8.05, "А сегодня меня постигло настоящее огорчение: раскупили всю вязаную одежду. Мне нужна ещё одна партия от нашего поставщика." }, { 16.97, "Если ты отнесёшь это послание Реме Шнайдер в ателье \"Канал\", моя признательность будет весьма велика." } } }, t = { d = 22.0, v = "human-female", n = { x = 257 }, c = { x = { { 0.00, "Говорят, бизнес Харлана пошёл в гору. Хорошие новости, хотя…" }, { 4.25, "хотелось бы мне знать, для чего вдруг понадобилось столько брони. Неужели где-то поблизости скоро случится война?" }, { 11.75, "Благородные господа ничего не говорят нам об этом!" }, { 15.37, "Ну что ж, спасибо тебе за помощь. Вот твоя плата, и я надеюсь, что с заказом Харлана всё хорошо." } } } } },
    [334] = { d = 29.0, g = 1, v = "human-female", n = { x = 330 }, c = { m = { { 0.00, "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы." }, { 8.19, "Конечно, герой вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать..." }, { 17.49, "Прошу вас! Отнесите моему сыну его швейные принадлежности!" }, { 21.62, "Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов." } }, f = { { 0.00, "Мой сын Турман – ученик в суконной лавке Ларсона в квартале магов. Он сегодня торопился, а потому забыл иголки и ножницы." }, { 8.19, "Конечно, героиня вроде вас едва ли станет заниматься такой ерундой, но, понимаете, без своих инструментов Турман не сможет работать..." }, { 17.70, "Прошу вас! Отнесите моему сыну его швейные принадлежности!" }, { 21.83, "Лавка Ларсона – один из двух магазинов одежды в Квартале магов, и стоит она прямо рядом с Башней магов." } } }, t = { d = 11.7, v = "child-male", n = { x = 143 }, c = { x = { { 0.00, "Ох, блин покровный! А я так надеялся, что забытые инструменты помогут мне увильнуть от работы." }, { 5.69, "А теперь всё-таки придётся помочь Ларсону с шитьём..." }, { 9.24, "Ну, ладно: делу – время, потехе – час..." } } } } },
    [335] = { d = 30.5, v = "human-male#50", n = { x = 371 }, c = { x = { { 0.00, "Лорд Вишлок наделал немалого переполоху среди Благородных домов." }, { 4.41, "Он прознал о наших делах и теперь собирается добиться полного расследования." }, { 9.60, "У меня есть план, согласно которому можно занять Вишлока другим делом, но понадобится твоя помощь." }, { 16.57, "Есть один цветочек под названием \"слеза Тиллоа\", он растёт в садах Сталвана поблизости от Темнолесья." }, { 23.29, "Ещё мне понадобится мускусный корень, который можно найти только у подножия Каменной дамбы в Болотине." } } }, t = { d = 2.6, v = "human-male#50", n = { x = 25 }, c = { x = { { 0.00, "Отлично! Это ровно то, что нужно!" } } } } },
    [336] = { d = 34.4, v = "human-male#50", n = { x = 413 }, c = { x = { { 0.00, "У лорда Вишлока, как у всех людей, есть свои маленькие слабости. Например, он совсем не дурак выпить. Удивительное лицемерие!" }, { 8.36, "Старый ханжа целыми днями сражается с заведениями вроде нашего, а ночи напролёт проводит наверху, да ещё и не платит по счёту." }, { 16.91, "Ну, посмотрим, как ему понравится придуманный мной специально для него напиток: портер \"Чёрный Коготь\"! С ног сбивает – точно тебе говорю!" }, { 26.17, "Отнеси ему это пойло и посмотри, придётся ли оно лорду по вкусу. Старый хмырь наверняка шатается вокруг Зала просителей." } } }, t = { d = 7.3, v = "human-male", n = { x = 80 }, c = { x = { { 0.00, "Спасибо за чудесный портер! Вот, возьми пару монет. А теперь иди прочь и не мешай мне дегустировать!" } } } } },
    [337] = { d = 19.3, v = "human-male#114", n = { x = 198 }, c = { x = { { 0.00, "Хотя обложка книги исцарапана и заляпана грязью, на корешке всё ещё можно прочитать заглавие – \"История Штормграда\"." }, { 8.84, "Открыв её, вы видите на первой странице печать библиотеки Штормграда." }, { 14.52, "Похоже, кто-то взял почитать эту книгу, да так и не вернул..." } } }, t = { d = 19.7, v = "human-male", n = { x = 211 }, c = { x = { { 0.00, "О небо! Этой книги не видели на полках со времён восстановления Штормграда." }, { 6.33, "Конечно, её придётся реставрировать, она в плохом состоянии, но я с радостью помещу её в нашу коллекцию редких книг." }, { 14.70, "Благодарю вас, господин. Прошу, примите плату за возвращение книги!" } } } } },
    [343] = { d = 31.4, v = "human-male", n = { x = 368 }, c = { x = { { 0.00, "Я готовлю важную лекцию по стойкости духа и хотел бы освежить в памяти несколько мест из важной работы в области металлургии, \"Как закалялось железо\"." }, { 10.28, "Копия этой книги должна быть в Королевской библиотеке Крепости Штормграда. Не могли бы вы заказать её для меня? Да осенит вас благодать Света!" }, { 20.39, "Королевская библиотека очень велика, но старший библиотекарь, Милтон Сноп, знает каталог как свои пять пальцев." }, { 28.13, "Поговорите с ним, он принесёт для вас книгу." } } }, t = { d = 11.1, v = "human-male", n = { x = 127 }, c = { x = { { 0.00, "Металлургия? Да, конечно, у нас много книг по данной отрасли знаний, и мы будем рады помочь брату Кристофу в подготовке лекции! Какая же книга его интересует?" } } } } },
    [344] = { d = 35.7, v = "human-male", n = { x = 384 }, c = { x = { { 0.00, "\"Как закалялось железо\"? Конечно, я знаю такую книгу." }, { 3.56, "Отличная книга, лет двадцать назад написанная дворфом-горняком Маргульфом Благгоном." }, { 9.57, "Он много времени провёл в горах Каз Модана, добывая руду. Отличный парень!" }, { 15.15, "Но о чём это я? Ах, да... \"Как закалялось железо\"! Боюсь, что книга отправилась в Аббатство Североземья." }, { 23.94, "Хранитель тамошней библиотеки, брат Пакстон, хотел сделать с неё копию для своей коллекции." }, { 30.61, "Уж сколько тому месяцев минуло... Интересно, почему он её задерживает." } } }, t = { d = 10.8, v = "human-male", n = { x = 120 }, c = { x = { { 0.00, "Коллега Шиф потерял свою книгу? Мда, неловко вышло..." }, { 3.64, "Книга действительно у меня, но я не закончил её переписывать, так что мне пока что нужен оригинал!" } } } } },
    [345] = { d = 33.2, v = "human-male", n = { x = 373 }, c = { x = { { 0.00, "Я как раз собирался закончить свою работу над копией \"Как закалялось железо\", но..." }, { 5.77, "Я пользуюсь только чернилами своего собственного изготовления. Они не текут, не выцветают и очень быстро сохнут." }, { 13.65, "Увы, высыхают они тоже слишком быстро! Последняя моя бутылка чернил никуда не годится, а я ещё не успел закончить работу…" }, { 22.41, "и сделать ещё чернил я не могу!" }, { 25.17, "Для изготовления чернил мне нужна ретбанская руда из Красногорья. Штейгер Ослоу из Озёр – мой верный поставщик…" } } }, t = { d = 13.9, g = 1, v = "human-male", n = { m = 144, f = 145 }, c = { m = { { 0.00, "Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков." }, { 9.97, "Если тебе сдалась ретбанская руда, добудь её сам!" } }, f = { { 0.00, "Чего тебе надо? Ты, может, не замечаешь, но мы здесь немного заняты – и укрепления строим, и Приозерье латаем после нападения орков." }, { 9.97, "Если тебе сдалась ретбанская руда, добудь её сама!" } } } } },
    [346] = { d = 10.8, v = "human-male", n = { x = 124 }, c = { x = { { 0.00, "Я закончил перепись и могу вернуть оригинал \"Как закалялось железо\"." }, { 4.60, "Спасибо за помощь, и передай, пожалуйста, Милтону мои извинения за долгую задержку." } } }, t = { d = 4.6, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Это она! Спасибо! Да пребудет над тобой вечный сияющий Свет!" } } } } },
    [347] = { d = 37.9, v = "human-male", n = { x = 440 }, c = { x = { { 0.00, "Ретбанская руда получила своё название по имени первооткрывателя, Барта Ретбана." }, { 5.50, "Выплавленный металл мягче железа, но руда имеет приятный тёмный цвет, и многие переписчики используют её для изготовления чернил." }, { 14.57, "Добыть руду можно в пещерах Ретбана к северу отсюда." }, { 18.52, "К сожалению, постоянные нападения орков отвлекают нас от добычи руды, и запасы наши иссякли. Скажу тебе ещё вот что..." }, { 26.54, "Красногорские гноллы недавно поселились в пещерах Ретбана, и их работяги как раз добывают там руду." }, { 33.81, "Так что если тебе нужна руда... ты знаешь, как добыть её." } } }, t = { d = 9.2, v = "human-male", n = { x = 104 }, c = { x = { { 0.00, "О, благодарю! Я наконец-то смогу приготовить чернила и закончить свою работу над копией \"Как закалялось железо\"! Благодарю тебя!" } } } } },
    [350] = { d = 35.6, v = "human-male", n = { x = 418 }, c = { x = { { 0.00, "Марзон наверняка поддерживает контакт с Братством Справедливости, и у него есть выход на Лесковара..." }, { 7.19, "Теперь, когда ван Клиф и Тредд погибли, Лесковара будет нелегко посадить на скамью подсудимых, потому что без их показаний твоё свидетельство ничего не будет значить; стоит также принять во внимание благородное происхождение и хорошие связи Лесковара." }, { 24.18, "Ему, в сущности, наплевать на закон." }, { 26.94, "Тебе понадобится помощь. Я, увы, оказать её не могу, но знаю того, кто может нам помочь. Найди Триаса в Торговом квартале." } } }, t = { d = 18.1, v = "human-male#50", n = { x = 201 }, c = { x = { { 0.00, "Опять Шоу?! Совести у него нет!.." }, { 2.63, "Братство Справедливости, говорите? Да вы просто мешок с хорошими новостями! Скажите ещё, что Смертокрыл воскрес и напал на город..." }, { 11.59, "Ну, ладно, выкладывайте всё по порядку. И не пропускайте ни единой детали. Я хочу знать всё." } } } } },
    [353] = { d = 32.1, v = "dwarf-male", n = { x = 380 }, c = { x = { { 0.00, "Грозовая Вершина – уважаемый клан дворфов, известный своими изысканными и утончёнными вкусами." }, { 6.39, "Неудивительно, что Грингер Грозовая Вершина, горный пехотинец Стальгорна, обратился ко мне, когда ему понадобилось оружие." }, { 15.13, "Заказ выполнен, но Грингер служит далеко отсюда, в Лок Модане. Если вы собираетесь на север, не возьмётесь ли доставить груз?" }, { 24.05, "По моим последним данным, горный пехотинец Грозовая Вершина остановился в северной сторожевой башне в Лок Модане." } } }, t = { d = 15.6, v = "dwarf-male", n = { x = 166 }, c = { x = { { 0.00, "Ага! Так Гриманд всё-таки закончил мой топор! Мне уже не терпится опробовать его на троггах и кобольдах!" }, { 8.34, "Благодарю. Эта посылка проделала такой долгий путь... Вот, примите это в благодарность за ваши услуги." } } } } },
    [354] = { d = 41.0, v = "scourge-male#82", n = { x = 355 }, c = { x = { { 0.00, "Семья Агамондов была самой преуспевающей в Тирисфальских лесах. Я работал на их мельницах... ещё до чумы." }, { 9.88, "Когда Плеть явилась в первый раз, Агамонды укрепили свой дом и уговорили всех работников остаться и помогать им держать оборону." }, { 21.47, "А мы были дураками, но дураками преданными..." }, { 25.86, "Из-за гордыни Агамондов мы стали нежитью, а сами они служат Плети!" }, { 32.34, "Сослужи Отрёкшимся службу – убей Агамондов, ставших жертвами Чумы, и принеси мне их останки." } } }, t = { d = 22.4, g = 1, v = "scourge-male#82", n = { m = 190, f = 192 }, c = { m = { { 0.00, "Месть сладка, не правда ли? Ты заметил хоть какие-то признаки свободной воли в Агамондах, когда убивал их? Надеюсь, что да." }, { 11.03, "Надеюсь, они почувствовали страх, прежде чем упокоились навсегда." }, { 17.41, "Конечно, глупо на это надеяться, но тем не менее." } }, f = { { 0.00, "Месть сладка, не правда ли? Ты заметила хоть какие-то признаки свободной воли в Агамондах, когда убивала их? Надеюсь, что да." }, { 11.12, "Надеюсь, они почувствовали страх, прежде чем упокоились навсегда." }, { 17.50, "Конечно, глупо на это надеяться, но тем не менее." } } } } },
    [355] = { d = 26.6, g = 1, v = "scourge-male#82", n = { m = 230, f = 233 }, c = { m = { { 0.00, "Ты принёс мне останки Агамондов и утолил мою жажду мести." }, { 5.37, "Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся." }, { 16.16, "Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично." } }, f = { { 0.00, "Ты принесла мне останки Агамондов и утолила мою жажду мести." }, { 5.54, "Но мельницы этой проклятой семейки всё ещё представляют собой угрозу не только для меня, но и для всех Отрёкшихся." }, { 16.34, "Я рассказал мировому судье Севрену о твоих действиях против Агамондов, и он хочет поговорить с тобой лично." } } }, t = { d = 12.7, v = "scourge-male#82", n = { x = 107 }, c = { x = { { 0.00, "Коулман хорошо отзывался о тебе, и рассказал о твоём успешном походе на мельницы Агамондов." }, { 8.94, "Отрёкшимся ещё раз нужна твоя помощь..." } } } } },
    [356] = { d = 43.5, v = "scourge-female", n = { x = 378 }, c = { x = { { 0.00, "Защитники Бастиона, охраняющие Тирисфаль со стороны Чумных земель, постоянно начеку, но порой Плеть проскальзывает мимо них." }, { 11.51, "Наш успех на Бастионе зависит от битвы на один фронт: мы не можем допустить атаки с тыла и уж конечно не можем лишить наших защитников линии поставки припасов." }, { 26.13, "Помоги Бастиону. Отправляйся на восток и убей любого приспешника Плети, которого встретишь." }, { 35.98, "Особое внимание обрати на ферму Балнира на востоке – там настоящее гнездо Плети." } } }, t = { d = 14.3, v = "scourge-female", n = { x = 122 }, c = { x = { { 0.00, "Очень хорошо. Благодаря вашим усилиям Плеть ещё долго не осмелится сунуться сюда." }, { 8.19, "Я отправлю лестный отзыв моему начальнику, исполнителю Зуганду." } } } } },
    [357] = { d = 47.7, v = "scourge-male#82", n = { x = 405 }, c = { x = { { 0.00, "На острове посреди озера Ясноводного, что к северу отсюда, обитает лич." }, { 6.49, "Сам он - свободный Отрёкшийся, но считает, что мы, да и вся остальная нежить, до сих пор находимся под контролем Плети, и велел своим прислужникам атаковать любого, кто приблизится." }, { 23.17, "Но раз он Отрёкшийся, он понадобится Королеве. А если он ещё и специалист в некромантии, то его умения нам... весьма пригодятся." }, { 35.99, "Чтобы понять, кто он и что умеет, мне нужно заглянуть в его книгу заклинаний. Прокрадись в его лагерь, достань её, и принеси мне." } } }, t = { d = 48.0, g = 1, v = "scourge-male#82", n = { m = 380, f = 381 }, c = { m = { { 0.00, "Прекрасно. Я изучу эту книгу и узнаю многое об этом личе. Ты сослужил королеве добрую службу." }, { 11.15, "Бетор открывает книгу и внимательно смотрит на её сияющие страницы…" }, { 17.85, "Невероятно! Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею!" }, { 26.15, "Гюнтер и при жизни был искусным некромантом. До нашествия Плети мы были добрыми товарищами и братьями по оружию." }, { 37.31, "Судя по книге, после смерти он достиг ещё большего могущества." }, { 43.49, "Его искусство могло бы нам очень пригодиться." } }, f = { { 0.00, "Прекрасно. Я изучу эту книгу и узнаю многое об этом личе. Ты сослужила королеве добрую службу." }, { 9.85, "Бетор открывает книгу и внимательно смотрит на её сияющие страницы…" }, { 16.55, "Невероятно! Добытая тобой книга принадлежит не кому иному, как Гюнтеру Чародею!" }, { 24.85, "Гюнтер и при жизни был искусным некромантом. До нашествия Плети мы были добрыми товарищами и братьями по оружию." }, { 36.00, "Судя по книге, после смерти он достиг ещё большего могущества." }, { 42.17, "Его искусство могло бы нам очень пригодиться." } } } } },
    [358] = { d = 45.3, v = "scourge-male#82", n = { x = 404 }, c = { x = { { 0.00, "Братские могилы к юго-востоку от фермы Гаррена были вырыты, чтобы справиться с..." }, { 7.33, "внушительным количеством смертей в Тирисфале после прихода Чумы." }, { 13.63, "Тела в этих могилах ещё не превратились в нежить, но теперь Плеть подослала гноллов-Гнилошкуров, чтобы они воровали из могил трупы и пополняли ими ряды их армии. Это недопустимо!" }, { 29.98, "У тебя будет два задания: перебить гноллов-Гнилошкуров возле братских могил и фермы Гаррена, а также отобрать у них бальзамирующую лимфу, поддерживающую в них жизнь." } } }, t = { d = 36.8, g = 1, v = "scourge-male#82", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Отличная работа! Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись." }, { 10.83, "Что же касается жидкости, которую ты собрал с рабов Гнилошкуров, её изучат наши аптекари." }, { 18.97, "Возможно, они откроют какой-то секрет, который поможет нам в войне." }, { 25.55, "Словом, ты отлично справился. Но война продолжается, и у тебя будет ещё много шансов проявить себя перед Отрёкшимися." } }, f = { { 0.00, "Отличная работа! Если силы Плети решили, что могут направлять этих мертвецов на нас, то они жестоко ошиблись." }, { 10.83, "Что же касается жидкости, которую ты собрала с рабов Гнилошкуров, её изучат наши аптекари." }, { 19.12, "Возможно, они откроют какой-то секрет, который поможет нам в войне." }, { 25.71, "Словом, ты отлично справилась. Но война продолжается, и у тебя будет ещё много шансов проявить себя перед Отрёкшимися." } } } } },
    [359] = { d = 35.9, v = "scourge-male#82", n = { x = 305 }, c = { x = { { 0.00, "Мне нужен свежий отчёт с восточной базы наших стражей смерти." }, { 6.06, "Я хочу знать, не проникли ли новые силы Плети за Бастион, в Тирисфаль." }, { 12.44, "На границе с Чумными землями нужно постоянно смотреть в оба! Нельзя, чтобы Плеть устроила здесь ещё одну крепость." }, { 23.19, "Иди по дороге на юг, а на развилке сверни на восток, к базе." }, { 28.78, "Поговори со стражем смерти Линнеей, у неё есть вся нужная мне информация." } } }, t = { d = 18.3, v = "scourge-female", n = { x = 149 }, c = { x = { { 0.00, "Севрену нужен отчёт? Ну что же, защитники Бастиона сдерживают силы Плети, но часть из них всё же проникает время от времени." }, { 12.53, "Плеть видели к востоку от нашей базы, возле Усадьбы Балнира." } } } } },
    [360] = { d = 19.5, v = "scourge-female", n = { x = 171 }, c = { x = { { 0.00, "Теперь возвращайся к мировому судье Севрену с той информацией, что я дала вам. Он очень ждёт её, так что поспеши." }, { 10.40, "А если встретишь по пути приспешников Плети – немедленно убей их! Нечего им шастать по нашим землям." } } }, t = { d = 17.1, v = "scourge-male#82", n = { x = 134 }, c = { x = { { 0.00, "Неприятно слышать, что Плеть просачивается через Бастион. Король-лич и его слуги не собираются сдаваться." }, { 10.11, "Но и мы не уступим. Мы не позволим ему захватить нас снова!" } } } } },
    [361] = { d = 10.7, v = "human-male#114", n = { x = 108 }, c = { x = { { 0.00, "Это письмо, написанное Турманом, старшим сыном Грегора Агамонда." }, { 4.98, "Оно адресовано Иветте Фартинг, но, похоже, так до неё и не добралось..." } } }, t = { d = 44.8, v = "scourge-female#80", n = { x = 371 }, c = { x = { { 0.00, "О... мой бедный Тармен! Я ведь просила его уйти с этих мельниц со мной и моим отцом, но его преданность семье оказалась сильнее..." }, { 11.51, "Так я и знала! Я знала, что Брэнд желает ему зла! Будь прокляты эти Чума и Плеть! Лицо Иветты смягчается." }, { 23.35, "Но стенания – удел слабых. Я Отрёкшаяся, у меня есть свои цели, и любовь не входит в их число." }, { 31.32, "Спасибо за то, что принесли мне письмо от некогда любимого человека, теперь я хотя бы знаю, что с ним сталось." }, { 41.04, "Но та жизнь для меня окончена. Навсегда." } } } } },
    [362] = { d = 48.3, v = "scourge-male#82", n = { x = 416 }, c = { x = { { 0.00, "Девлин Агамонд был младшим из двух сыновей в семье, и более непохожих братьев найти было невозможно." }, { 9.29, "Турман был высоким и учтивым, а его младший брат – слабым и острым на язык." }, { 16.54, "Когда мельницы Агамондов пали во время нашествия Чумы, я не удивился, услышав, что Девлин погиб одним из первых." }, { 26.91, "На дороге, ведущей к мельницам Агамондов, до сих пор можно услышать его безумное бормотание." }, { 35.67, "Я собираю останки Агамондов, и для полной коллекции мне не хватает лишь бедного Девлина." }, { 43.85, "Найди его, уничтожь и принеси мне его кости." } } }, t = { d = 24.3, v = "scourge-male#82", n = { x = 206 }, c = { x = { { 0.00, "Спасибо. Кости Девлина станут отличным украшением для моего плаща." }, { 6.43, "Если что-то может согреть моё холодное сердце, то это мысль о том, что Агамондов больше нет." }, { 14.92, "Они предали меня и мою семью, когда пришла Чума – а теперь я клянусь, что растопчу их кости ногами!" } } } } },
    [363] = { d = 26.3, g = 1, v = "scourge-male#83", n = { m = 265, f = 268 }, c = { m = { { 0.00, "Ты вовремя пришёл в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи." }, { 11.69, "Меня зовут Мордо, я смотритель склепа Могильника. А ты больше не раб Короля-лича." }, { 18.14, "Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать." } }, f = { { 0.00, "Ты вовремя пришла в себя. Мы собирались уже швырнуть тебя в огонь вместе с остальными, но, похоже, тебе посчастливилось избежать этой участи." }, { 10.55, "Меня зовут Мордо, я смотритель склепа Могильника. А ты больше не рабыня Короля-лича." }, { 17.26, "Поговори с жрецом Тьмы Сарвисом в часовне у подножья холма, он расскажет тебе о том, что тебе нужно знать." } } }, t = { d = 40.5, v = "scourge-male#82", n = { x = 345 }, c = { x = { { 0.00, "А, ещё один живой мертвец! Должно быть, это настоящий шок – очнуться в склепе, в котором тебя встречает лишь холод... и Мордо." }, { 12.39, "Я всё это читаю по твоему лицу. Позволь мне объяснить тебе наше... эээ... положение." }, { 20.16, "Нас освободила из-под контроля Короля-лича наша новая предводительница, Леди Сильвана." }, { 28.09, "Тёмная Госпожа руководит нами в войне против ненавистной армии Плети и цепляющихся за эту землю людей, преследующих нас, словно ищейки." } } } } },
    [364] = { d = 33.6, v = "scourge-male#82", n = { x = 302 }, c = { x = { { 0.00, "Мы, Отрёкшиеся, ведём войну против армии Плети, ведомой Королём-личом: против поднятых некромантией войск нежити, против злобных зверей севера и истерзанных призраков." }, { 15.45, "Северную часть деревни оккупировали безмозглые твари Плети, их нужно уничтожить." }, { 22.81, "Сокруши их, не давая пощады, пусть они и были прежде нашими братьями и сёстрами. Падшие – всего лишь рабы Короля-лича." } } }, t = { d = 18.2, v = "scourge-male#82", n = { x = 158 }, c = { x = { { 0.00, "Жаль, что нельзя привлечь Плеть на нашу сторону, её несметные полчища пришлись бы как нельзя кстати в предстоящих битвах." }, { 11.22, "Но так как договориться с ними нельзя, нам остаётся лишь уничтожить их." } } } } },
    [365] = { d = 32.5, g = 1, v = "scourge-male", n = { m = 323, f = 323 }, c = { m = { { 0.00, "Кто это тут? Новенький, да ещё и герой? Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся." }, { 10.58, "К западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу." }, { 17.23, "К тому же Алый орден постоянно ходит дозором возле своей башни." }, { 22.14, "Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв." }, { 28.10, "Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл." } }, f = { { 0.00, "Кто это тут? Новенькая, да ещё и героиня? Если хочешь проявить себя перед Тёмной Госпожой, придётся следовать обычаям Отрёкшихся." }, { 9.85, "К западу отсюда есть ферма. Люди растекаются по этой земле, как плесень по трупу." }, { 16.50, "К тому же Алый орден постоянно ходит дозором возле своей башни." }, { 21.40, "Преподай этим ничтожествам урок и укради у них десять их драгоценных тыкв." }, { 27.37, "Как наберёшь десяток, отнеси их аптекарю Юхану в Брилл." } } }, t = { d = 10.3, g = 1, v = "scourge-male#82", n = { m = 80, f = 83 }, c = { m = { { 0.00, "Ты хорошо справился с заданием, герой, и тем самым доказал, что достоин примкнуть к армии Тёмной Госпожи." } }, f = { { 0.00, "Ты хорошо справилась с заданием, героиня, и тем самым доказала, что достойна примкнуть к армии Тёмной Госпожи." } } } } },
    [366] = { d = 47.0, v = "scourge-male#82", n = { x = 380 }, c = { x = { { 0.00, "Давным-давно Гюнтер, я и Тул Коготь Ворона, который стал теперь некромантом Плети, дружили и состояли в Кирин-Торе – сообществе магов Даларана." }, { 13.14, "Мы с Гюнтером оба пали жертвами Чумы, но я полагал, что он так и сгинул в небытие или встал под знамёна Короля-лича. Я рад, что он остался свободным." }, { 29.38, "Мы должны привлечь его на свою сторону." }, { 33.19, "Я наложил на эту книгу заклинание, которое докажет ему, что я тоже свободен от Короля-лича." }, { 41.62, "Надеюсь, что, убедившись в этом, он станет одним из нас." } } }, t = { d = 19.0, g = 1, v = "scourge-male#82", n = { m = 140, f = 141 }, c = { m = { { 0.00, "Моя книга?! Так это ты украл её!" }, { 3.65, "Но... что это за новые чары на ней... Бетор? Он в Лордероне?" }, { 9.18, "Если он всё ещё \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича..." } }, f = { { 0.00, "Моя книга?! Так это ты украла её!" }, { 4.30, "Но... что это за новые чары на ней... Бетор? Он в Лордероне?" }, { 9.82, "Если он всё ещё \"жив\", то, может быть, ему тоже удалось вырваться из холодных объятий Короля-лича..." } } } } },
    [367] = { d = 41.4, v = "scourge-male#82", n = { x = 361 }, c = { x = { { 0.00, "Леди Сильвана обратилась к Королевскому фармацевтическому обществу." }, { 6.14, "Тёмная Госпожа считает, что при помощи наших знаний и новейшей магии мы сумеем найти ключ к свержению Артаса." }, { 16.20, "Она хочет, чтобы мы вывели новую чуму – смертоноснее любой болезни Азерота, чтобы она уничтожила всю армию Артаса." }, { 26.97, "В своих изысканиях я обнаружил, что для этого потребуется кровь животных." }, { 33.69, "Принеси мне пять склянок крови пса тьмы, чтобы я мог провести эксперимент." } } }, t = { d = 4.8, v = "scourge-male#82", n = { x = 40 }, c = { x = { { 0.00, "Вы хорошо справились. Благодарю вас за старания." } } } } },
    [368] = { d = 33.1, g = 1, v = "scourge-male#82", n = { m = 291, f = 292 }, c = { m = { { 0.00, "Пока ты собирал для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты." }, { 13.11, "Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее." }, { 22.33, "Мне потребуется пять чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу." } }, f = { { 0.00, "Пока ты собирала для меня образцы, я провёл исследования и обнаружил, что для должного распространения этой болезни потребуются и другие реагенты." }, { 13.22, "Отравить какую-нибудь одну жалкую жертву – это ерунда, а вот отравить весь мир будет куда сложнее." }, { 22.44, "Мне потребуется пять чешуек мурлоков из племени Злобного Плавника. Их можно найти на берегу к северу или к западу." } } }, t = { d = 5.3, v = "scourge-male#82", n = { x = 43 }, c = { x = { { 0.00, "Отличная чешуя. Именно то, что мне нужно для микстуры." } } } } },
    [369] = { d = 43.0, v = "scourge-male#82", n = { x = 389 }, c = { x = { { 0.00, "Пока вы были заняты сборами, я обнаружил в одном из своих фолиантов старинный текст, в котором сказано, что древняя чума унесла тысячи невинных жизней." }, { 13.59, "Позже открыли, что возбудитель болезни сохранился благодаря яду ночных кругопрядов." }, { 21.63, "Принесите мне немного яда злобных ночных кругопрядов, чтобы я мог закончить эксперимент." }, { 29.83, "Хочу посмотреть, как среагирует ядовитый элемент с моим новым составом." }, { 36.39, "Говорят, что этих пауков можно найти в Восточных Тирисфальских лесах." } } }, t = { d = 13.4, v = "scourge-male#82", n = { x = 115 }, c = { x = { { 0.00, "Да, этот яд великолепно подойдёт! Я уже добавил всё остальное в мой состав и вскипятил его." }, { 8.44, "Наконец-то я испытаю эту смертельно опасную смесь!" } } } } },
    [370] = { d = 24.3, v = "scourge-male", n = { x = 252 }, c = { x = { { 0.00, "В документах палача Аррена содержится информация, нужная нам для того, чтобы истребить всех людей в наших землях." }, { 8.28, "Судя по этим данным, Алый орден прислал в заброшенную башню на юго-западе от Брилла капитана Перрина с людьми." }, { 17.60, "Убей Перрина, трёх ревнителей и трёх миссионеров, а потом доложи мне о своём успехе." } } }, t = { d = 9.5, g = 1, v = "scourge-male", n = { x = 80 }, c = { m = { { 0.00, "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, герой." } }, f = { { 0.00, "Тёмная Госпожа, без сомнения, обрадуется смерти капитана Перрина. Вы хорошо исполнили свой долг, героиня." } } } } },
    [371] = { d = 26.7, v = "scourge-male", n = { x = 256 }, c = { x = { { 0.00, "У нас до сих пор война, а Алый орден набирает силу." }, { 4.32, "В отчёте палача Аррена сказано, что его участники под предводительством капитана Вакона совершают набеги из разрушенной башни в юго-восточном Тирисфале, близ фермы Балнира." }, { 19.60, "Убей Вакона и пять келейников из Алого ордена – это должно нанести ордену сокрушающий удар!" } } }, t = { d = 8.3, v = "scourge-male", n = { x = 91 }, c = { x = { { 0.00, "Смерть капитана Вакона значительно замедлит продвижение Алого ордена по Тирисфалю. Но есть и другие угрозы." } } } } },
    [372] = { d = 22.1, v = "scourge-male", n = { x = 229 }, c = { x = { { 0.00, "Алый орден совершает набеги из своей разрушенной башни в северном Тирисфале, за могилой Фаола." }, { 7.82, "Согласно нашей информации, отвечает за эти набеги жестокий капитан Мелраш." }, { 13.87, "Я даю вам особенное и очень важное задание – убить Мелраша и двух его телохранителей во имя Тёмной Госпожи." } } }, t = { d = 14.4, g = 1, v = "scourge-male", n = { x = 142 }, c = { m = { { 0.00, "Вы отлично справились, герой. Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса." }, { 11.00, "У меня хорошие предчувствия на ваш счёт." } }, f = { { 0.00, "Вы отлично справились, героиня. Чем больше на стороне Отрёкшихся таких безжалостных бойцов, как вы, тем ближе наша победа и свержение Артаса." }, { 10.29, "У меня хорошие предчувствия на ваш счёт." } } } } },
    [373] = { d = 19.2, v = "human-male#114", n = { x = 202 }, c = { x = { { 0.00, "Обыскав труп Эдвина ван Клифа, вы находите, среди прочих предметов, неотправленное письмо." }, { 7.04, "Адрес таков: \"Баросу Алекстону, главному архитектору Штормграда, в Ратуша на Соборной Площади\"." }, { 14.39, "Оно кажется написанным совсем недавно, и печать ещё свежая…" } } }, t = { d = 33.3, v = "human-male", n = { x = 372 }, c = { x = { { 0.00, "Эдвин ван Клиф, говорите? Я бы скорее ждал письма от своей покойной бабушки... Так это вы его убили?" }, { 7.00, "Извините, конечно, но я сильно удивлён. В молодые годы он был просто непревзойдённым бойцом." }, { 13.43, "Ну, дайте-ка взглянуть, что он мне там написал после стольких лет... Барос рассматривает письмо." }, { 20.28, "Эх, Эдвин… годы не изменили тебя ни на каплю. Всё такой же идеалист и романтик. Представляете, ему было всё равно, кому мстить." }, { 29.05, "Месть попросту поглотила его. Но, кажется, я его понимаю…" } } } } },
    [374] = { d = 35.6, g = 1, v = "scourge-male", n = { x = 365 }, c = { m = { { 0.00, "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими." }, { 9.32, "Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли." }, { 18.54, "Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден." }, { 25.20, "Помоги нам истребить их, герой. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже." } }, f = { { 0.00, "Палач Зуганд сказал, что тебе уже приходилось убивать членов Алого ордена. Тирисфальские леса так и кишат ими." }, { 9.32, "Вариматрас, подручный Тёмной Госпожи, лично следит за тем, чтобы это азеротское отребье – раса людей – было стёрто с лица земли." }, { 18.54, "Здесь, в Тирисфальских лесах, обосновалась особо неприятная группа людей – Алый орден." }, { 25.20, "Помоги нам истребить их, героиня. Принеси мне десять алых перстней в доказательство твоей верности Вариматрасу и Тёмной Госпоже." } } }, t = { d = 6.0, g = 1, v = "scourge-male", n = { x = 56 }, c = { m = { { 0.00, "Вариматас будет гордиться тобой. Ты отлично служишь своим лидерам, герой." } }, f = { { 0.00, "Вариматас будет гордиться тобой. Ты отлично служишь своим лидерам, героиня." } } } } },
    [375] = { d = 38.4, v = "scourge-female#80", n = { x = 341 }, c = { x = { { 0.00, "Так холодно... Чума Нежити расползается по моим венам, как клубок ледяных змей, и скоро я впаду в беспамятство." }, { 9.26, "Но никакой злой рок не помешает мне нести службу нашей Тёмной Госпоже." }, { 16.51, "Когда прозвучал зов, я шила мешки для павших солдат великой армии Сильваны." }, { 23.22, "Теперь мои руки дрожат от холода. Если ты принесёшь мне пять шкурок сумеречницы и грубую нить, я сошью себе одеяло." }, { 33.34, "Помоги мне, чтобы я могла и дальше служить нашему делу." } } }, t = { d = 7.8, v = "scourge-female#80", n = { x = 69 }, c = { x = { { 0.00, "Спасибо за заботу. Надеюсь, когда-нибудь слух о твоей храбрости дойдёт и до Сильваны..." } } } } },
    [376] = { d = 48.0, g = 1, v = "scourge-female#80", n = { m = 446, f = 447 }, c = { m = { { 0.00, "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться." }, { 12.56, "Похоже, и ты будешь записан к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю." }, { 22.56, "В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь." }, { 32.02, "У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех." }, { 41.82, "К югу отсюда волков-падальщиков и летучих мышей предостаточно." } }, f = { { 0.00, "В мои обязанности входит присмотр за нашими ранеными воинами, пошив доспехов и одежды и любая помощь жрецу Тьмы Сарвису, какая может потребоваться." }, { 12.86, "Похоже, и ты будешь записана к нему на службу... он поручит тебе охоту на безмозглых тварей Плети, насколько я его знаю." }, { 22.99, "В общем, если ты хочешь остаться в целости и сохранности – а я не сомневаюсь, что это так – может, я смогу помочь." }, { 32.45, "У меня заканчиваются запасы лап и крыльев, и если ты принесёшь мне немного, я найду для тебя какой-нибудь доспех." }, { 42.25, "К югу отсюда волков-падальщиков и летучих мышей предостаточно." } } }, t = { d = 10.1, v = "scourge-female#80", n = { x = 83 }, c = { x = { { 0.00, "Спасибо. Держи этот доспех." }, { 3.19, "Надеюсь, тебе он послужит лучше, чем тому бедолаге, что носил его последним…" } } } } },
    [377] = { d = 32.5, v = "human-male", n = { x = 385 }, c = { x = { { 0.00, "Мало того, что столица бросила Темнолесье на произвол судьбы, теперь Благородные дома плюнули на решение городского совета Темнолесья и заточили Декстрена Варда в тюрьму Штормграда – вместо того, чтобы обезглавить злодея по приказу лорда Чернодрева." }, { 17.22, "Вард продавал тела с кладбища Морбенту Скверну. Подобное преступление карается смертью." }, { 23.31, "И всё же Штормград объявил Варда своим пленником." }, { 27.16, "Убей Варда в тюрьме Штормграда, принеси мне его руку, и я тебя вознагражу." } } }, t = { d = 24.4, g = 1, v = "human-male", n = { m = 286, f = 288 }, c = { m = { { 0.00, "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества?" }, { 6.22, "Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой!" }, { 10.60, "Ты не только утешил семьи покойных, ты преподал наглядный урок продажным бюрократам из Благородных домов." }, { 17.99, "Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании." } }, f = { { 0.00, "Так значит, Декстрен Вард наконец-то расплатился за свои преступления против человечества?" }, { 6.22, "Чем меньше швали, тем лучше, я так считаю. Хвала тебе, друг мой!" }, { 10.60, "Ты не только утешила семьи покойных, ты преподала наглядный урок продажным бюрократам из Благородных домов." }, { 18.12, "Штормград должен прислушиваться к нашему голосу, или мы восстанем против его тирании." } } } } },
    [378] = { d = 38.1, g = 1, v = "dwarf-male", n = { m = 415, f = 416 }, c = { m = { { 0.00, "Ты доказал свою преданность королю Магни, герой. И ты, так же как я, ненавидишь мерзавцев Чёрного Железа всем сердцем." }, { 9.21, "Я бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой." }, { 15.31, "Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола." }, { 23.37, "А это значит, что Кам виноват в гибели брата Длинной Косы." }, { 27.83, "Пока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его. Ради Грима! Принеси мне его голову!" } }, f = { { 0.00, "Ты доказала свою преданность королю Магни, героиня. И ты, так же как я, ненавидишь мерзавцев Чёрного Железа всем сердцем." }, { 8.64, "Я бы сам взялся за эту работу, но я дал слово чести и должен быть рядом с Длинной Косой." }, { 14.74, "Рогго говорит, что у него есть доподлинные доказательства: это Кам Гневливый организовал нападение на мост Тандола." }, { 22.80, "А это значит, что Кам виноват в гибели брата Длинной Косы." }, { 27.26, "Пока что Кама Гневливого держат в тюрьме Штормграда. Но такие, как он, не достойны того, чтобы жить. Убей его. Ради Грима! Принеси мне его голову!" } } }, t = { d = 28.8, g = 1, v = "dwarf-male", n = { x = 333 }, c = { m = { { 0.00, "Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо." }, { 6.98, "С этими негодяями из клана Чёрного Железа только так и надо. Отлично потрудился, герой." }, { 12.94, "Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами." }, { 21.79, "Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщён." } }, f = { { 0.00, "Стало быть, Кам Гневливый на собственной шкуре узнал, каково это – принять мучительную смерть? Хорошо." }, { 6.98, "С этими негодяями из клана Чёрного Железа только так и надо. Отлично потрудился, героиня." }, { 13.15, "Жертвы атаки на мост Тандола – это не первые и не последние невинные жертвы в нашем мире, объятом смятением и раздираемым войнами." }, { 22.00, "Но теперь семьи погибших хотя бы утешатся тем, что предатель наказан. Брат Длиннокоса отомщён." } } } } },
    [380] = { d = 36.5, v = "scourge-male", n = { x = 388 }, c = { x = { { 0.00, "Одна из наших самых серьёзных проблем – это добыча природных ресурсов, необходимых для выживания." }, { 7.13, "Золота было очень мало даже во времена расцвета Альянса." }, { 11.72, "К северо-западу отсюда есть золотой рудник, но он весь кишит пауками." }, { 16.76, "Нам нужно золото из рудника, но мы не можем его добывать, пока там везде бегают эти членистоногие твари." }, { 24.62, "У меня не так много рабочих рук для этой задачи, так что придётся действовать постепенно." }, { 31.68, "Отправляйся туда – может быть, ты сможешь чем-то помочь нам." } } }, t = { d = 19.2, g = 1, v = "scourge-male", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Ну что же, для начала неплохо. Очистка всей территории займёт несколько недель или даже месяцев." }, { 7.23, "А после этого, нам придётся пойти туда с факелами, чтобы сжечь паутину." }, { 12.82, "Ты отлично справился, я уверен, что подыщу для тебя ещё какую-нибудь работёнку." } }, f = { { 0.00, "Ну что же, для начала неплохо. Очистка всей территории займёт несколько недель или даже месяцев." }, { 7.23, "А после этого, нам придётся пойти туда с факелами, чтобы сжечь паутину." }, { 12.82, "Ты отлично справилась, я уверен, что подыщу для тебя ещё какую-нибудь работёнку." } } } } },
    [381] = { d = 44.9, g = 1, v = "scourge-male", n = { m = 458, f = 458 }, c = { m = { { 0.00, "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям." }, { 10.57, "Теперь мы можем позаботится и о других делах." }, { 14.38, "Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда." }, { 22.21, "Алый орден – достойная презрения организация, ведущая охоту на нас." }, { 27.21, "Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар!" }, { 39.44, "Будь осторожен, нечестивое рвение делает их опасными противниками." } }, f = { { 0.00, "Тебе будет приятно узнать, что у нас, кажется, наметился неплохой прогресс на руднике, не в последнюю очередь благодаря твоим усилиям." }, { 10.65, "Теперь мы можем позаботится и о других делах." }, { 14.46, "Мои разведчики доложили, что подразделение Алого ордена разбивает лагерь к юго-востоку отсюда." }, { 22.29, "Алый орден – достойная презрения организация, ведущая охоту на нас." }, { 27.29, "Они не успокоятся, пока не истребят всю нежить, независимо от того, принадлежит ли эта нежить к армии Плети или нет. Мы должны первыми нанести удар!" }, { 38.43, "Будь осторожна, нечестивое рвение делает их опасными противниками." } } }, t = { d = 12.7, v = "scourge-male", n = { x = 115 }, c = { x = { { 0.00, "Если б только они послушались доводов разума, а? Может быть, мы могли бы уговорить их всё серьёзно обсудить... Как же! Идиоты, ослеплённые светом..." } } } } },
    [382] = { d = 30.5, v = "scourge-male", n = { x = 329 }, c = { x = { { 0.00, "В сообщениях от моего начальства в Брилле упоминается, что агент Алого ордена направляется из их монастыря к Могильнику." }, { 8.87, "Судя по этим сообщениям, гонец несёт важную информацию." }, { 13.12, "Я не знаю подробностей, но что бы у него ни оказалось, мы должны это перехватить!" }, { 19.51, "А ты, наиболее квалифицированная особа, которую я могу послать на это задание." }, { 25.32, "Найди гонца и принеси мне информацию, которую тебе удастся найти." } } }, t = { d = 31.0, g = 1, v = "scourge-male", n = { m = 270, f = 270 }, c = { m = { { 0.00, "Хмм... Ну-ка, посмотрим, что ты там нашёл..." }, { 3.21, "Аррен пробегает глазами документы, принесённые вами." }, { 7.42, "Новости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы..." }, { 14.89, "\"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чём мы не знали бы... А это ещё что?" }, { 23.72, "Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать." } }, f = { { 0.00, "Хмм... Ну-ка, посмотрим, что ты там нашла..." }, { 3.31, "Аррен пробегает глазами документы, принесённые вами." }, { 7.51, "Новости об их успехах в борьбе с нами... Ценности не имеют. Донесения разведки... Новые приказы..." }, { 14.98, "\"Продолжайте организацию лагеря около разрушенного города...\" Ничего такого, о чём мы не знали бы... А это ещё что?" }, { 23.82, "Карта местонахождения некоторых полевых командиров и агентов! Это можно будет использовать." } } } } },
    [383] = { d = 38.9, g = 1, v = "scourge-male", n = { m = 417, f = 419 }, c = { m = { { 0.00, "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл." }, { 4.83, "Обладая этой информацией, он сможет нанести решающий удар по Алому ордену." }, { 10.33, "Ты сильно помог нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа." }, { 22.63, "Иди по дороге из Могильника на север. Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток." }, { 30.76, "Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\"." } }, f = { { 0.00, "Вот это нужно отнести моему начальнику, палачу Зуганду, в Брилл." }, { 4.83, "Обладая этой информацией, он сможет нанести решающий удар по Алому ордену." }, { 10.33, "Ты сильно помогла нам здесь, в Могильнике, но мне нужно, чтобы кто-то доставил эти сведения Зуганду, и я уверен, что у него для тебя найдётся более серьёзная работа." }, { 22.71, "Иди по дороге из Могильника на север. Вскоре после того, как дойдёшь до Тирисфаля, наткнёшься на перекрёсток." }, { 30.84, "Сверни на восток и продолжай идти в том же направлении. По дороге как раз и будет поместье \"Остывший очаг\"." } } }, t = { d = 19.8, g = 1, v = "scourge-male", n = { m = 188, f = 189 }, c = { m = { { 0.00, "О, прекрасно! Ты отлично потрудился, добывая эту информацию. Хмм... Имена офицеров в Тирисфальских лесах…" }, { 10.00, "Представь, какой удар мы можем нанести по боевому духу этих фанатиков, если убъём всех их лидеров одним стремительным ударом." } }, f = { { 0.00, "О, прекрасно! Ты отлично потрудилась, добывая эту информацию. Хмм... Имена офицеров в Тирисфальских лесах…" }, { 7.99, "Представь, какой удар мы можем нанести по боевому духу этих фанатиков, если убъём всех их лидеров одним стремительным ударом." } } } } },
    [384] = { d = 28.9, v = "dwarf-male", n = { x = 340 }, c = { x = { { 0.00, "Завсегдатаи моей таверны больше всего любят кабаньи рёбрышки в пиве!" }, { 4.72, "Беда в том, что местный охотник, который снабжал меня кабанятиной, теперь завербован в королевскую армию, чтобы помочь Альянсу." }, { 13.76, "Может, ты мне поможешь? Если принесёшь мне шесть рёбер скального вепря и \"Болтливое пиво\" вон из той таверны, я открою тебе фамильный рецепт моих знаменитых рёбрышек в пиве, не говоря уж о дармовой порции! Вся соль – в пиве!" } } }, t = { d = 10.3, v = "dwarf-male", n = { x = 107 }, c = { x = { { 0.00, "Сварено пиво, разлито по кружкам," }, { 3.26, "Эй, не деритесь, друзья и подружки! Каждому выделим по половине Вкуснейшей порции рёбрышек в пиве!" } } } } },
    [385] = { d = 34.8, v = "dwarf-male", n = { x = 386 }, c = { x = { { 0.00, "Многие охотники приезжают к озеру Лок Модан поохотиться на знаменитых кроков." }, { 6.33, "Всегда находятся торговцы, скупающие кроколисковые шкуры на одежду или доспехи, а есть и любители кроколискового мяса." }, { 14.89, "Мы тоже зарабатываем на этом, но не слишком много, потому что кроколисков не так просто одолеть, и к тому же они поселились на островах посреди озера Лок." }, { 26.31, "Но если хочешь отправиться на охоту, я не стану тебя отговаривать. Это действительно незабываемо. Я и сам в своё время..." } } }, t = { d = 4.4, g = 1, v = "dwarf-male", n = { m = 47, f = 48 }, c = { m = { { 0.00, "Ты отлично поохотился. За хорошую работу и платят хорошо!" } }, f = { { 0.00, "Ты отлично поохотилась. За хорошую работу и платят хорошо!" } } } } },
    [386] = { d = 34.0, v = "human-male", n = { x = 399 }, c = { x = { { 0.00, "Таргорр Ужасный служил под началом Гат'Илзогга старшим палачом и даже среди жестоких орков отличался особой кровожадностью." }, { 8.65, "По его прихоти отважных бойцов Королевства подвергали страшным пыткам." }, { 13.38, "Его взяли в плен и поместили в тюрьму Штормграда, приговорив к смертной казни. Но происходит что-то странное." }, { 20.78, "Один из знатных людей запретил его казнить. Уверен, дело нечисто." }, { 26.10, "Положи конец Таргорру Ужасному. Отправляйся в тюрьму и обезглавь его, пока мы не пали жертвой предательства." } } }, t = { d = 14.9, v = "human-male", n = { x = 173 }, c = { x = { { 0.00, "Наконец-то Таргорр Ужасный получил по заслугам. Я рад, что злодей угодил в лапы Смерти. Молодец." }, { 6.74, "Иной раз подлинное правосудие можно отыскать лишь за стенами залов суда, вдали от замутнённого взора политиканов." } } } } },
    [387] = { d = 26.4, v = "human-male", n = { x = 302 }, c = { x = { { 0.00, "Бунт должен быть подавлен! И ты мне в этом поможешь. Если станет известно, что в тюрьме случился бунт, я потеряю работу." }, { 8.30, "Это исключительная подлость! Самое важное сейчас – немедленно взять тюрьму под контроль. Ради безопасности Штормграда." }, { 16.98, "Наказание за бунт в тюрьме – смертная казнь." }, { 19.99, "Убей несколько этих отщепенцев, это даст урок всем остальным, и ситуация войдёт в норму." } } }, t = { d = 10.3, g = 1, v = "human-male", n = { m = 115, f = 117 }, c = { m = { { 0.00, "Ты отлично проявил себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработал, и я тебе очень благодарен." } }, f = { { 0.00, "Ты отлично проявила себя в тюрьме. Эта проблема куда сложнее, чем выглядит на первый взгляд, но ты отлично поработала, и я тебе очень благодарен." } } } } },
    [388] = { d = 34.4, v = "human-female#47", n = { x = 389 }, c = { x = { { 0.00, "Кровь моя стынет в жилах от ужасного горя... Мой внук Мак…" }, { 4.04, "он был такой чудесный мальчик. Всего четырнадцать лет. Когда армия ушла на фронт, он счёл, что должен защитить город." }, { 12.05, "Он был охранником в тюрьме, куда прибыла партия заключённых из Братства Справедливости." }, { 17.70, "Мак наказал некоторых заключённых за порчу шерстяного одеяла, из которого они изготовили головные повязки, знаки их банды. За это он получил нож в спину." }, { 28.36, "Я хочу мести. Принесите мне десять этих проклятых шерстяных бандан. Они цвета крови..." } } }, t = { d = 13.9, v = "human-female#47", n = { x = 157 }, c = { x = { { 0.00, "Значит, из-за этих жалких тряпиц они убили моего Мака... Ужасная, нелепая смерть!.." }, { 5.76, "Увы, мне не дано изменить прошлое. Но я благодарна вам, за то что вам удалось воздать по заслугам убийцам моего внука." } } } } },
    [389] = { d = 32.3, v = "human-male", n = { x = 377 }, c = { x = { { 0.00, "Ван Клиф и я были членами гильдии каменщиков. Это мы восстанавливали Штормград после войны." }, { 6.80, "Когда мы закончили работу, вельможи отказались платить нам за неё." }, { 11.20, "Руководителям гильдии предложили места на государственной службе, но ван Клиф отказался, потому что превыше всего ценил интересы гильдии." }, { 20.78, "Он поднял мятеж и покинул город, поклявшись отомстить." }, { 24.92, "Его лейтенант, Базиль Тредд, много знает о планах своего командира. Базиль содержится в плену в тюрьме." } } }, t = { d = 17.6, v = "human-male", n = { x = 188 }, c = { x = { { 0.00, "Чего, во имя Света, тебе надо? Не видишь, тут и без тебя проблем хватает?" }, { 5.40, "Базиль Тредд?! Какое тебе дело до этого мерзавца? Или ты – из его поганых кровавых соратничков?" }, { 12.03, "Не будь у меня тут все камеры заняты, я бы тебя точно засунул в одну из них!" } } } } },
    [391] = { d = 20.9, v = "human-male", n = { x = 228 }, c = { x = { { 0.00, "Скажу тебе сразу: я тебе ни капли не доверяю. Но в нынешней ситуации это не особо важно." }, { 6.56, "Что от тебя требуется: иди и поговори с Треддом. Если ты и вправду на нашей стороне, убей его и принеси мне его голову." }, { 14.89, "А если ты на их стороне и не вернёшься вовремя, то будешь долго, долго гнить заживо…" } } }, t = { d = 22.4, v = "human-male", n = { x = 245 }, c = { x = { { 0.00, "Без Тредда бунтовщики станут куда более управляемыми. Посмотрим..." }, { 4.95, "Должен сказать, я уже через полчаса решил, что больше тебя не увижу…" }, { 10.00, "но, надо признать, я в тебе ошибся." }, { 12.69, "Думаю, тебе не удалось из него ничего вытянуть..." }, { 16.08, "А вот я знаю пару вещей насчёт деятельности Тредда, которые тебя могут заинтересовать." } } } } },
    [392] = { d = 31.1, v = "human-male", n = { x = 352 }, c = { x = { { 0.00, "Во время первого года заключения Тредда никто его не навещал." }, { 4.31, "Мне казалось, что братство отказалось от него, поскольку он стал бесполезен." }, { 9.93, "Но пару месяцев назад его стали постоянно навещать – раз, два в неделю. Посетитель был весьма странный. Такой тихий тип." }, { 18.19, "У меня возникли подозрения, но все его документы были в полном порядке." }, { 23.54, "Согласно документам, звали его Мелик; вот его описание. Не думаю, что он ещё когда-нибудь придёт к Тредду." } } }, t = { d = 18.8, v = "human-male", n = { x = 213 }, c = { x = { { 0.00, "Мелик? Нет, это имя мне незнакомо и даже ни на какие мысли не наводит. Это может быть кто угодно!" }, { 6.87, "Бывший каменщик, один из членов Братства Справедливости..." }, { 10.81, "Хотя если он тесно связан с ними, как предполагает Телуотер, кто-нибудь может опознать его. Мне нужно подумать." } } } } },
    [393] = { d = 25.6, v = "human-male", n = { x = 278 }, c = { x = { { 0.00, "Знаете ли, мне так ничего и не пришло в голову." }, { 3.22, "Зато я придумал, кто может нам помочь; если так и случится, я буду гордиться собой, но не стоит на это закладываться." }, { 11.41, "Матиас Шоу из ШРУ – его можно найти в казармах Старого города." }, { 15.70, "Шоу знает все уголки и закоулки этого города, всю его подноготную и тайные делишки." }, { 21.97, "Если кто-то и знает, о ком речь, то только он." } } }, t = { d = 31.8, v = "human-male", n = { x = 361 }, c = { x = { { 0.00, "Что это? Да, думаю, что знаю этого человека, но его зовут вовсе не Мелик." }, { 4.98, "Наёмные убийцы носят много масок, зовутся множеством имён и забывают их, как только они становятся не нужны." }, { 12.57, "Этот человек также известен под именем Марзон; вероятно, это его очередной псевдоним." }, { 18.78, "В общем, он – наёмный убийца, и я о нём довольно много знаю." }, { 23.24, "Марзон сейчас работает на Грегора Лесковара – человека с репутацией, дурной даже для коррумпированного лорда Штормграда." } } } } },
    [394] = { d = 26.9, v = "human-male#50", n = { x = 308 }, c = { x = { { 0.00, "Найдите Шоу в Старом городе. Дайте ему знать, что с Лесковаром покончено, и о вашей причастности к заговору лордов против города." }, { 8.62, "Я думаю, он будет рад, что среди горожан Штормграда есть ещё герои." }, { 13.50, "Думаю, он отправит вас на встречу с принцем или другим лордом. Не позволяйте им запудрить вам мозги." }, { 20.23, "Власть имущие думают, что могут творить в городе что угодно, но пока они не всесильны." } } }, t = { d = 21.8, g = 1, v = "human-male", n = { m = 227, f = 229 }, c = { m = { { 0.00, "Значит, мёртв? Ты скор на расправу. Не хотел бы я стать твоим врагом." }, { 5.28, "Смеётся и кладёт руку вам на плечо." }, { 8.12, "Не прими за осуждение. Я же глава наёмных убийц, как я могу осуждать тебя за чистое убийство?" }, { 14.72, "По правде сказать, ты оказал людям Штормграда огромную услугу, и я благодарю тебя за это." } }, f = { { 0.00, "Значит, мёртв? Ты скора на расправу. Не хотел бы я стать твоим врагом." }, { 5.68, "Смеётся и кладёт руку вам на плечо." }, { 8.52, "Не прими за осуждение. Я же глава наёмных убийц, как я могу осуждать тебя за чистое убийство?" }, { 15.12, "По правде сказать, ты оказала людям Штормграда огромную услугу, и я благодарю тебя за это." } } } } },
    [395] = { d = 30.5, v = "human-male", n = { x = 326 }, c = { x = { { 0.00, "Ах, да... Пока тебя не было, приходил Алекстон, хотел с тобой поговорить. Должно быть, это касалось Братства Справедливости." }, { 8.67, "Позволь дать тебе совет: на твоём месте я бы по первой просьбе рассказал обо всём произошедшем в подробностях." }, { 16.37, "Но при этом упомяни, что Лесковара сразила именно твоя рука. Можешь мне верить – я на таких вещах собаку съел." }, { 25.58, "А что касается Триаса... ну, не говори о нём. Никогда. Если сможешь." } } }, t = { d = 16.0, v = "human-male", n = { x = 171 }, c = { x = { { 0.00, "Приятно тебя видеть снова. Мне довелось услышать о недавней кончине лорда Грегора Лесковара." }, { 6.91, "Значит, твоя миссия оказалась успешной. Я щедро награжу тебя за спасение и меня, и многих прочих от мести ван Клифа." } } } } },
    [396] = { d = 21.6, v = "human-male", c = { x = { { 0.00, "Я готовлю донесение для короля. Надеюсь, ты сумеешь преподнести его величеству всё в лучшем виде." }, { 6.77, "Не переживай так, король обязательно оценит твоё благородное служение народу Штормграда и достойно наградит тебя." }, { 15.12, "Срок твоей аудиенции близок, так что поторопись, чтобы не опоздать в Крепость Штормграда." } } }, t = { d = 15.1, g = 1, v = "human-female#45", n = { x = 168 }, c = { m = { { 0.00, "Я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей. Этого мы должны избежать." }, { 10.49, "Возьмите этот жетон в знак королевской благосклонности, герой." } }, f = { { 0.00, "Я щедро награжу вас за службу Штормграду. Если ван Клиф преуспел в своих махинациях, то у нас ещё будет немало трудностей. Этого мы должны избежать." }, { 10.49, "Возьмите этот жетон в знак королевской благосклонности, героиня." } } } } },
    [397] = { d = 15.2, g = 1, v = "human-male#50", n = { m = 179, f = 181 }, c = { m = { { 0.00, "Я слышал, что Лорд Вишлок в восторге от напитка." }, { 3.55, "Ты нам здорово помог. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех." }, { 9.92, "За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой." } }, f = { { 0.00, "Я слышал, что Лорд Вишлок в восторге от напитка." }, { 3.55, "Ты нам здорово помогла. Теперь чернокнижники Штормграда смогут заниматься своим делом без помех." }, { 9.93, "За свою службу ты получишь достойный подарок. Поговори с Згги, моим слугой." } } }, t = { d = 9.5, g = 1, v = "human-male", n = { x = 82 }, c = { m = { { 0.00, "Хозяин дал подарок для путник. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина." } }, f = { { 0.00, "Хозяин дал подарок для путница. Згги хотел бы оставить его себе, но Згги знает, что будет, если предать хозяина." } } } } },
    [398] = { d = 31.4, v = "human-male#114", n = { x = 320 }, c = { x = { { 0.00, "Разыскивается: Червеглаз!" }, { 2.47, "Ужасное даже по меркам гноллов чудовище – Червеглаз – приговорён к смерти за его преступления против Отрёкшихся." }, { 11.79, "Этот гнусный злодей воровал трупы для армии Короля-лича. Червеглаза видели близ Фермы Гаррена, к северу от Брилла." }, { 21.10, "Город Брилл предлагает награду всякому, кто сумеет прикончить негодяя и предъявить палачу Зуганду его лапу. Милосердие – удел слабых." } } }, t = { d = 12.5, v = "scourge-male", n = { x = 134 }, c = { x = { { 0.00, "Наконец-то Червеглаз получил по заслугам. Пусть твой поступок запомнится всем, кто захочет навредить нашему народу!" }, { 8.72, "Благодарю тебя от имени всего города Брилла." } } } } },
    [399] = { d = 34.5, v = "human-male", n = { x = 387 }, c = { x = { { 0.00, "С тех пор как я мальчишкой работал на ферме в Западном Крае, прошла целая вечность." }, { 5.79, "Говорят, нельзя вернуться в прошлое – и это верно." }, { 9.17, "Дважды верно, если говорить обо мне – ведь мой родной дом был разграблен ворами и сожжён." }, { 15.68, "Я спросил у отца о судьбе некоторых моих вещей, например, о моём первом компасе." }, { 21.35, "Отец не мог его захватить при бегстве, но сказал, что компас спрятан где-то на ферме." }, { 27.73, "Усадьба Алекстона расположена к западу от Сторожевого холма. Может быть, ты найдёшь мой компас?" } } }, t = { d = 16.5, v = "human-male", n = { x = 187 }, c = { x = { { 0.00, "Благодарю вас! Совершенно бесполезная вещь, не считая воспоминаний..." }, { 4.74, "Нет слов, как я благодарен за то, что принесли мне этот предмет; вам, конечно, трудно понять цену памяти о Западном Крае." }, { 13.20, "Возьмите это в знак моей признательности..." } } } } },
    [400] = { d = 39.3, v = "dwarf-male", n = { x = 461 }, c = { x = { { 0.00, "Белдин Сталежар владеет местной ремонтной мастерской, и он лучший техник по осадным машинам! Но своего инструмента он не жалеет." }, { 8.82, "Могу побиться об заклад, его тангенциальные вращатели выходят из строя быстрее, чем мы успеваем поставлять ему новые!" }, { 17.33, "Мы только что выполнили его очередной заказ. Если ты его доставишь, я уверен, мастер заплатит тебе за труды." }, { 25.07, "Ты сможешь найти Сталежара к северо-востоку от Караноса." }, { 29.06, "Кстати, это излюбленное местечко ветеранов-водителей осадных машин, так что держи ухо востро, когда там будешь, – вдруг какая работёнка подвернётся." } } }, t = { d = 18.1, g = 1, v = "dwarf-male", n = { m = 206, f = 210 }, c = { m = { { 0.00, "У тебя мои инструменты? Отлично, парень, отлично!" }, { 3.81, "Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца." }, { 12.78, "Славно, что ты принёс мне эти инструменты. Вот, возьми эти деньги; спасибо!" } }, f = { { 0.00, "У тебя мои инструменты? Отлично, девчушка, отлично!" }, { 3.55, "Я только что сломал последний зубчатый храповик, и мне нужен другой, чтобы закончить ремонт осадной машины для пилота Камнекожца." }, { 12.53, "Славно, что ты принесла мне эти инструменты. Вот, возьми эти деньги; спасибо!" } } } } },
    [401] = { d = 6.3, v = "human-male", n = { x = 72 }, c = { x = { { 0.00, "Я почти закончил работу над переводом записки. Она будет готова через несколько минут." } } }, t = { d = 7.1, v = "human-male", n = { x = 77 }, c = { x = { { 0.00, "Ну вот. Готово…" }, { 1.47, "Вокруг воцаряется душная тишина, словно на лес опустился тёмный тяжёлый полог..." } } } } },
    [404] = { d = 21.6, v = "scourge-male", n = { x = 231 }, c = { x = { { 0.00, "Плеть проникла в Тирисфальские леса и заполонила всю местность к западу от Брилла, возле старого моста." }, { 8.04, "Отправляйся туда и загони этих гниющих мертвецов обратно в землю, откуда они вылезли." }, { 14.40, "Разбросай их кости и принеси их гнилые когти – за них ты получишь награду от стражей смерти." } } }, t = { d = 6.4, v = "scourge-male", n = { x = 66 }, c = { x = { { 0.00, "Отличная работа. Жаль, я не видел, как ты расправляешься с этими гнусными тварями!" } } } } },
    [405] = { d = 46.1, g = 1, v = "scourge-male#82", n = { x = 361 }, c = { m = { { 0.00, "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, как раз подходишь для этого." }, { 18.28, "Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия." }, { 24.71, "Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича. Это очень опасное дело." }, { 35.02, "Приготовься как следует, герой. Не подведи нас." }, { 39.74, "Бетора можно найти в квартале Магов Подгорода." } }, f = { { 0.00, "Бетор Ледострел, высокопоставленный и могущественный маг из Подгорода, что к югу отсюда, приказал мне прислать ему того, кто готов бороться с Плетью. Ты, как раз подходишь для этого." }, { 19.90, "Отнеси эти приказы Бетору, а он расскажет, в чём состоит твоя миссия." }, { 26.33, "Деталей я не знаю, могу сказать лишь то, что речь пойдёт о вербовке заблудшего лича. Это очень опасное дело." }, { 36.64, "Приготовься как следует, героиня. Не подведи нас." }, { 41.57, "Бетора можно найти в квартале Магов Подгорода." } } }, t = { d = 15.7, v = "scourge-male#82", n = { x = 128 }, c = { x = { { 0.00, "А, так тебя прислал мировой судья Севрен. Тогда да, дело у нас с тобой очень важное." }, { 8.16, "Уверен, Севрен выбрал того, кто справится с моим заданием, но… ладно, посмотрим." } } } } },
    [407] = { d = 41.7, v = "scourge-male#82", n = { x = 366 }, c = { x = { { 0.00, "Безвредные тыковки, да? Это только так кажется." }, { 4.41, "Если мы хотим победить силы Артаса на севере и нашествие людей на юге, нам нужно извлечь всю пользу из нашего дара нежития." }, { 15.87, "Чуть-чуть смекалки, и простая тыква превратится в шпиона Тёмной Госпожи." }, { 22.47, "С помощью моей последней формулы эта тыква станет лакомым блюдом." }, { 28.85, "Вот недавно мы поймали ещё одного ревнителя из Алого ордена, сейчас он сидит в погребе таверны \"Петля Висельника\". Иди, отнеси ему эту тыкву." } } }, t = { d = 4.4, v = "human-male", n = { x = 48 }, c = { x = { { 0.00, "Благословенный Свет! Наконец-то еда! Сладенькая тыквочка..." } } } } },
    [408] = { d = 40.8, g = 1, v = "scourge-male#82", n = { m = 351, f = 351 }, c = { m = { { 0.00, "Мельницы Агамондов превратились в крепость Плети." }, { 4.68, "Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом." }, { 18.21, "С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас." }, { 27.48, "Ты не должен допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков." }, { 36.26, "А заодно принеси мне череп капитана Даргола." } }, f = { { 0.00, "Мельницы Агамондов превратились в крепость Плети." }, { 4.68, "Самая важная точка – это семейная усыпальница Агамондов, где устроил штаб их местный лидер, скелет, которого называют капитаном Дарголом." }, { 18.09, "С помощью некромантии он поднял предков рода Агамондов и собирается использовать их против нас." }, { 27.35, "Ты не должна допустить этого. Отправляйся в склеп Агамондов и убей их неупокоенных предков." }, { 36.14, "А заодно принеси мне череп капитана Даргола." } } }, t = { d = 19.3, v = "scourge-male#82", n = { x = 150 }, c = { x = { { 0.00, "Твои действия нанесли Плети ощутимый удар! И твоя победа не будет забыта ни Отрёкшимися, ни врагами." }, { 11.20, "Продолжай бороться вместе с нами, и когда-нибудь мы изгоним Короля-лича из Азерота!" } } } } },
    [409] = { d = 39.8, g = 1, v = "scourge-male#82", n = { m = 342, f = 342 }, c = { m = { { 0.00, "Ты говоришь, что неподвластен воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают." }, { 9.96, "Но прежде чем я поверю тебе,ты должен доказать то, что являешься врагом Плети." }, { 17.57, "На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара." }, { 28.54, "Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится. Убей её, и я поверю, что ты – враг Короля-лича." } }, f = { { 0.00, "Ты говоришь, что неподвластна воле Короля-лича, и чары, которые Бетор наложил на мою книгу, это подтверждают." }, { 9.98, "Но прежде чем я поверю тебе,ты должна доказать то, что являешься врагом Плети." }, { 17.59, "На южном берегу этого острова находится старый окровавленный алтарь, которым пользуется адепт Плети – Лилит Нефара." }, { 28.56, "Возьми из этого ящика манящую свечу, зажги её на алтаре, и Лилит пробудится. Убей её, и я поверю, что ты – враг Короля-лича." } } }, t = { d = 21.2, v = "scourge-male#82", n = { x = 174 }, c = { x = { { 0.00, "Невероятно! Ты убил Лилит Нефару и тем самым доказал, что являешься врагом Плети!" }, { 8.61, "Я думал, что я – единственный из нежити, обладающий свободой воли, но теперь вижу, что есть и другие, кто не поддался влиянию Короля-лича." } } } } },
    [411] = { d = 12.0, v = "scourge-male#82", n = { x = 107 }, c = { x = { { 0.00, "Отнеси этот самоцвет Пустоты моему старому товарищу Бетору. С его помощью мы сможем общаться, а мне очень многое надо ему сказать." } } }, t = { d = 10.6, g = 1, v = "scourge-male#82", n = { m = 90, f = 91 }, c = { m = { { 0.00, "Ты убедил его присоединиться к нам! Это огромная радость для всех Отрёкшихся. Я доложу об этом Тёмной Госпоже." } }, f = { { 0.00, "Ты убедила его присоединиться к нам! Это огромная радость для всех Отрёкшихся. Я доложу об этом Тёмной Госпоже." } } } } },
    [412] = { d = 36.3, v = "gnome-male", n = { x = 440 }, c = { x = { { 0.00, "При дальнейшем анализе гномреганской ситуации оказалось, что нам не только не удалось извести троггов, но мы случайно превратили большую часть представителей нашей расы в ужасающих, безмозглых, злобных лепрогномов!" }, { 14.62, "Мы с Оззи намерены направить в обратную сторону ужасный эффект лепры при помощи нашего последнего изобретения – перенаправлятора." }, { 23.35, "Эта машина почти закончена, но нам чрезвычайно нужны зубцы рестабилизации и гиромеханические шестерни." }, { 30.43, "Добудь их у лепрогномов, которые обитают около Гномрегана, и принеси нам!" } } }, t = { d = 20.4, v = "gnome-male", n = { x = 234 }, c = { x = { { 0.00, "Эти гиромеханические шестерни и зубцы рестабилизации прекрасно подходят к чертежу Оззи для устройства Перенаправления." }, { 9.01, "Как только я залью гидросмазку во внутренние клапаны сгорания, подкручу кривохраповик и повышу вязкость электрогуммигеля, раса гномов будет возрождена." } } } } },
    [413] = { d = 27.9, v = "dwarf-male", n = { x = 292 }, c = { x = { { 0.00, "Хотелось бы мне, чтобы мой братец Велларт попробовал свежего \"Мерцающего портера\"." }, { 5.50, "Он горный пехотинец, их расквартировали в южной сторожевой башне, одной из двух на границе с озером Лок Модан." }, { 15.51, "Может, он и не такой пивовар, как остальные Ячменовары, но своё пиво он любит, и я знаю, что это тоже ему понравится." }, { 23.86, "Не отнесёшь ему вот этот бочонок \"Мерцающего портера\"?" } } }, t = { d = 9.1, v = "dwarf-male", n = { x = 92 }, c = { x = { { 0.00, "Горный пехотинец Ячменовар пробует \"Мерцающий портер\"..." }, { 4.09, "Ох-х. Аж искры из глаз! Кажется, я даже в темноте видеть могу!" } } } } },
    [414] = { d = 35.6, v = "dwarf-male", n = { x = 381 }, c = { x = { { 0.00, "Я бы и ещё отхлебнул \"Мерцающего портера\" с пивоварни моего братца – забористое же пойло!" }, { 5.94, "Но я хочу, чтобы мой приятель-пехотинец попробовал его." }, { 9.72, "Зовут парня Кэдрелл, и он обычно патрулирует дорогу через Телсамар в озере Лок Модан." }, { 16.98, "Чтобы добраться до Телсамара, иди на юго-восток через туннель, затем на развилке возьми на северо-восток." }, { 25.55, "И по той дороге иди прямо до Телсамара." }, { 28.89, "Отдай горному пехотинцу Кэдреллу этот бочонок \"Мерцающего портера\", и посмотрим, что он скажет!" } } }, t = { d = 10.4, v = "dwarf-male", n = { x = 99 }, c = { x = { { 0.00, "Ну-с, попробуем..." }, { 1.55, "Клянусь бородой Магни! Аж голова кругом пошла! И в теле лёгкость необыкновенная. Сейчас полечу, как птичка!" } } } } },
    [415] = { d = 18.7, g = 1, v = "dwarf-male", n = { m = 208, f = 210 }, c = { m = { { 0.00, "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя." }, { 5.02, "Он хочет поговорить с тобой про своё новое пиво... Сказал вроде, что ты ему помог." }, { 10.57, "Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо." }, { 15.94, "Может, тебя дармовая выпивка ждёт..." } }, f = { { 0.00, "Регольд Ячменовар, что живёт в Посёлке Пивоваров, спрашивал про тебя." }, { 5.02, "Он хочет поговорить с тобой про своё новое пиво... Сказал вроде, что ты ему помогла." }, { 10.54, "Можешь самолично вернуться в Посёлок Пивоваров и спросить, что ему надо." }, { 15.91, "Может, тебя дармовая выпивка ждёт..." } } }, t = { d = 14.1, g = 1, v = "dwarf-male", n = { m = 146, f = 148 }, c = { m = { { 0.00, "путник! Помнишь тот звездолист, что ты принёс мне?" }, { 3.58, "Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!" }, { 11.34, "Вот, попробуй и скажи, как пошло..." } }, f = { { 0.00, "путница! Помнишь тот звездолист, что ты принесла мне?" }, { 3.81, "Ну так я его использовал в новых рецептах, над которыми работал, и в одном случае вышло просто великолепно!" }, { 11.57, "Вот, попробуй и скажи, как пошло..." } } } } },
    [416] = { d = 25.0, v = "dwarf-male", n = { x = 293 }, c = { x = { { 0.00, "К западу отсюда началось настоящее нашествие." }, { 3.06, "Эти крысы, кобольды-туннельщики, обосновались в предгорьях, устроили там свои логовища и оскверняют нашу прекрасную землю!" }, { 11.63, "Их необходимо истребить. Перебей их как можно больше, принеси в доказательство уши и получишь награду." }, { 18.99, "Кобольды-туннельщиков поселились к западу от Телсамара вдоль горных склонов." } } }, t = { d = 7.2, v = "dwarf-male", n = { x = 79 }, c = { x = { { 0.00, "Фу! Когда я просил принести уши, я не подозревал, что они так дурно пахнут! Прими награду. Молодчина." } } } } },
    [417] = { d = 25.2, v = "human-male#114", n = { x = 261 }, c = { x = { { 0.00, "Хилдельв пишет в своём журнале, что подвергся нападению Паршивого Когтя, \"огромного медведя-ледолапа\"." }, { 7.66, "Он отогнал тварь, но та успела страшно изранить его." }, { 12.18, "Судя по состоянию трупа Хилдельва, Паршивый Коготь, видимо, вернулся и добил его." }, { 18.73, "В журнале Хилдельв записал своё последнее пожелание: \"Отомстить Паршивому Когтю.\"" } } }, t = { d = 12.5, v = "dwarf-male", n = { x = 139 }, c = { x = { { 0.00, "Злая весть. Хилдельв был хорошим другом. Жаль, что не довелось мне с тобой пойти на этого Паршивого Когтя!" }, { 7.69, "Спасибо тебе. Пилоты Осадной бригады Стальгорна тебя не забудут." } } } } },
    [418] = { d = 28.2, g = 1, v = "dwarf-female#95", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Едоки в Телсамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят." }, { 7.72, "Мы славимся кровяными колбасками... Но ты ведь их ещё не пробовал? Нет?" }, { 12.02, "Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение." }, { 19.01, "Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты." }, { 24.06, "Добудь всё это, а уж Видра сготовит всё в лучшем виде!" } }, f = { { 0.00, "Едоки в Телсамаре не переводятся – ещё бы, детей полным-полно, после трудового дня работники ужинать хотят." }, { 7.72, "Мы славимся кровяными колбасками... Но ты ведь их ещё не пробовала? Нет?" }, { 12.44, "Что же, у нас принято отрабатывать еду, и не думаю, что за красивые глазки тебе сделают исключение." }, { 19.43, "Мне понадобится медвежатина, кишки кабана на оболочки и паучья лимфа для остроты." }, { 24.48, "Добудь всё это, а уж Видра сготовит всё в лучшем виде!" } } }, t = { d = 14.0, v = "dwarf-female#95", n = { x = 169 }, c = { x = { { 0.00, "Поверь, со стороны готовка выглядит куда сложнее, чем на деле, но..." }, { 4.47, "Хоть я и не встречала никого, кому бы захотелось научиться делать колбаски, но на всякий случай рецептик я тебе всё же дам. Бери! Ешь, пока рот свеж!" } } } } },
    [419] = { d = 33.6, v = "dwarf-male", n = { x = 381 }, c = { x = { { 0.00, "Мой друг и напарник, пилот Осадного орудия Мори Хилдельв, пропал в этих холмах." }, { 5.38, "Мы искали там редкую руду, необходимую для высококачественного пороха, и во время поисков мы загнали его танк на крутой холм и он сломался!" }, { 15.44, "Хилдельв, по-прежнему уверенный, что руда в тех горах есть, оставил меня охранять наши танки, а сам пошёл дальше пешком." }, { 23.93, "Прошло уже несколько дней, а я слышал ночью какой-то звериный вой в холмах. Мори – парень-кремень, но мне тревожно. Прошу тебя, найди его." } } }, t = { d = 22.1, v = "dwarf-male", n = { x = 260 }, c = { x = { { 0.00, "Перед вами труп дворфа – изуродованный, застывший и сильно обглоданный горными хищниками." }, { 6.20, "В руке он сжимает записную книжку с грубо нацарапанными записями Мори Хилдельва." }, { 11.80, "Труп одет во всё ещё превосходно сохранившийся жилет бригадира." }, { 16.62, "Эта мрачная сцена показывает, где встретил свой конец пилот Осадной машины." } } } } },
    [420] = { d = 30.4, v = "dwarf-male", n = { x = 343 }, c = { x = { { 0.00, "Трогги, поселившиеся в тоннелях, крайне враждебны: они без раздумий нападают на любого, кто только осмелится туда сунуться." }, { 8.30, "С другой стороны, что-то мне подсказывает, что у тебя хватит сил и умения, чтобы с ними справиться." }, { 15.40, "Если тебе хочется побеседовать с Сениром, то его можно отыскать в Караносе." }, { 20.73, "А добраться туда и вовсе просто: пройдёшь весь тоннель насквозь, а дальше шагай себе по дороге до самого до города Караноса." } } }, t = { d = 32.4, v = "dwarf-male", n = { x = 343 }, c = { x = { { 0.00, "А что это у нас тут такое? О, донесение от моего братца! Хм-м..." }, { 5.40, "Говорил я ему, нечего поминать королевское имя всуе, да только станет он меня слушать!" }, { 11.31, "С другой стороны, кое-кому в Совете не мешает попортить кровь. Ха!" }, { 16.59, "Как бы то ни было, думаю, мне нужно и своё донесение отправить в Стальгорн. Как-то запоздал я с этим делом. Всё этот проклятый холод!" }, { 25.97, "Слушай, если тебе это интересно, у меня скоро может найтись для тебя кое-какая работёнка..." } } } } },
    [421] = { d = 46.1, v = "scourge-male#82", n = { x = 403 }, c = { x = { { 0.00, "Леди Сильвана поручила Вариматрасу завоевать земли людей и дворфов к югу." }, { 7.12, "Но этот идиот Аругал – даларанский шарлатан, а ныне проклятая тварь из крепости Тёмного Клыка – позволил своей бездумной магии нанести ущерб стратегической цитадели Серебряного бора." }, { 23.77, "Мне нужен кто-то, искушённый в воинском деле, чтобы разрубить узел, завязанный Аругалом." }, { 31.91, "Убейте пять белоголовов Лунной Ярости и докажите, что вы – тот, кого я ищу." }, { 38.85, "Этих мерзких зверей легко можно встретить у самой дороги, внизу под холмом." } } }, t = { d = 14.5, g = 1, v = "scourge-male#82", n = { x = 121 }, c = { m = { { 0.00, "Вы сослужили мне хорошую службу, герой." }, { 3.67, "Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала." } }, f = { { 0.00, "Вы сослужили мне хорошую службу, героиня." }, { 3.85, "Для меня очевидно, что вы будете достойным помощником – я готовлюсь избавить Серебряный бор от проклятья Аругала." } } } } },
    [422] = { d = 51.1, v = "scourge-male#82", n = { x = 450 }, c = { x = { { 0.00, "Для меня загадка, каким образом Аругал вообще был принят в Кирин Тор." }, { 6.31, "Его знания касательно применения заклинаний были просто мыльным пузырём." }, { 13.52, "Сейчас важно точно выяснить, какую магию применил Аругал, чтобы я мог использовать её против него и обеспечить владычество Тёмной Госпожи в Серебряном бору." }, { 28.03, "Вначале Аругал останавливался на пшеничной ферме, что к северу от моста." }, { 34.74, "Один из стражей смерти сообщил о том, что видел какие-то книги с заклинаниями, но не сумел их заполучить." }, { 44.54, "Добудьте для меня ту из этих книг, которая называется \"Зелье Аругала\"." } } }, t = { d = 14.2, g = 1, v = "scourge-male#82", n = { x = 117 }, c = { m = { { 0.00, "Да, это именно та книга, которую я искал, герой." }, { 4.45, "Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся." } }, f = { { 0.00, "Да, это именно та книга, которую я искал, героиня." }, { 4.52, "Если ваша приверженность делу Тёмной Госпожи не ослабела, вас ждёт неплохое будущее среди Отрёкшихся." } } } } },
    [423] = { d = 53.4, v = "scourge-male#82", n = { x = 477 }, c = { x = { { 0.00, "Изучив деятельность Аругала я понял, что мои наихудшие подозрения верны." }, { 6.64, "Старый хрыч был недостоин даже ночные горшки выносить в Даларане, не говоря уж о том, чтобы представлять Кирин Тор в самый трудный час. Идиоты!" }, { 21.08, "Для усиления своей никудышной магии Аругал использовал заколдованные предметы. В первую очередь я должен изучить эти предметы." }, { 32.49, "Отправляйтесь в путь и убивайте обжор Лунной Ярости и тёмных духов Лунной Ярости, пока не наберёте достаточного для моих исследований количества их заколдованных наручей." }, { 47.92, "Эти злобные создания обитают к северу и к востоку отсюда." } } }, t = { d = 20.0, g = 1, v = "scourge-male#82", n = { x = 168 }, c = { m = { { 0.00, "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала." }, { 8.19, "Вероятно, мне следовало поручить вам добыть больше наручей." }, { 14.16, "Тем не менее, вы отменно проявили себя, собирая эти, герой." } }, f = { { 0.00, "Надеюсь, что смогу выжать достаточно энергии из столь ограниченного количества материала." }, { 8.19, "Вероятно, мне следовало поручить вам добыть больше наручей." }, { 14.16, "Тем не менее, вы отменно проявили себя, собирая эти, героиня." } } } } },
    [424] = { d = 47.9, v = "scourge-male#82", n = { x = 403 }, c = { x = { { 0.00, "Мне потребуется больше времени на раскрытие тёмных тайн чар Аругала,чем я думал." }, { 10.07, "Но тем временем мне нужно, чтобы вы помогли разрешить одну небольшую проблему, которую обнаружили наши разведчики." }, { 20.61, "Похоже, Аругал распространил свою магию на Серебряный рудник, находящийся в холмах к юго-востоку отсюда." }, { 30.40, "Этот рудник стал бы ценным ресурсом для Вариматраса." }, { 35.83, "Я хочу, чтобы вы снесли голову с плеч поражённому скверной старшине рудника Мрачнону Белёсому. После его смерти рудник будет нашим." } } }, t = { d = 12.4, v = "scourge-male#82", n = { x = 113 }, c = { x = { { 0.00, "Великолепно. Рудник обеспечит нас отменными ресурсами для наших сил по мере нашего продвижения по Серебряному бору и далее по Азероту." } } } } },
    [425] = { d = 50.4, v = "scourge-female", n = { x = 450 }, c = { x = { { 0.00, "Нам с моим братом Квинном было поручено провести рекогносцировку в Серебряном бору и отчитаться перед верховным палачом Хадриком." }, { 11.60, "Но далеко продвинуться мы не сумели: когда мы проходили через эту ферму, нас атаковал вурдалак Ивар Нечистый." }, { 21.92, "Нам удалось уйти от Ивара, но он успел как следует приложить Квинна." }, { 28.27, "Мой брат поправляется от зелья, что вы ему дали, но Ивар может вернуться раньше, чем Квинн совсем встанет на ноги." }, { 38.98, "Убейте Ивара, чтобы Квинн мог спокойно поправляться. Обычно Ивар торчит в том амбаре – поджидает, когда я утрачу бдительность." } } }, t = { d = 10.7, v = "scourge-female", n = { x = 92 }, c = { x = { { 0.00, "О, спасибо. Я очень благодарна вам." }, { 3.68, "Я упомяну ваше имя в отчёте, который направлю своему вышестоящему начальству." } } } } },
    [426] = { d = 34.8, v = "scourge-male", n = { x = 375 }, c = { x = { { 0.00, "Плеть пытается основать базу на мельницах Агамондов. Если им это удастся, они продолжат свои нападения в Тирисфале." }, { 8.81, "Поступил приказ уничтожить всю Плеть на мельницах." }, { 12.99, "Отправляйся туда и собери зазубренные рёбра костетрясов-солдат и костеголовых солдат, а также почерневшие черепа мрачнооких скелетов-заклинателей." }, { 24.15, "Чтобы добраться до мельниц, иди по дороге на запад." }, { 28.39, "После того как перейдёшь мост, поверни на север, и скоро увидишь ветряные мельницы." } } }, t = { d = 11.0, v = "scourge-male", n = { x = 110 }, c = { x = { { 0.00, "Твои старания не прошли даром! Я не буду благодарить тебя за исполнение долга, но стражи смерти Тирисфаля навсегда запомнят твоё имя!" } } } } },
    [427] = { d = 36.5, g = 1, v = "scourge-male", n = { m = 383, f = 383 }, c = { m = { { 0.00, "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом." }, { 7.81, "Теперь мы знаем расположение всех их баз в Тирисфальских лесах." }, { 12.98, "Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью." }, { 19.29, "Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом." }, { 26.04, "Докажи мне, что способен служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена." } }, f = { { 0.00, "Документы, которые прислал палач Аррен, приблизят переломный момент в нашей битве с мерзким Алым орденом." }, { 7.81, "Теперь мы знаем расположение всех их баз в Тирисфальских лесах." }, { 12.98, "Но у стражей смерти есть заботы и поважнее: армия Короля-лича растёт с каждой ночью." }, { 19.29, "Нам нужен кто-то такой \"инициативный\", как ты, чтобы навсегда покончить с Алым орденом." }, { 26.04, "Докажи мне, что способна служить Тёмной Госпоже: отправляйся на запад, к башне за фермой Соллидена, и убей десять воинов из Алого ордена." } } }, t = { d = 5.2, g = 1, v = "scourge-male", n = { x = 46 }, c = { m = { { 0.00, "Замечательно, герой. Ваши боевые умения не вызывают сомнений." } }, f = { { 0.00, "Замечательно, героиня. Ваши боевые умения не вызывают сомнений." } } } } },
    [428] = { d = 28.7, v = "scourge-male", n = { x = 303 }, c = { x = { { 0.00, "Пару недель назад двое наших стражей смерти – Ран и Квинн Йорик, ушли на разведывательное задание в северный Серебряный бор." }, { 9.22, "С тех пор от них не было никаких известий." }, { 12.72, "Они могли стать жертвами Плети, но даже если это так, мне нужно подтверждение. Найдите этих стражей смерти." }, { 21.09, "Их первой целью была разведка на полях в северной части Серебряного бора. Начните свои поиски там." } } }, t = { d = 4.9, v = "scourge-female", n = { x = 37 }, c = { x = { { 0.00, "Вы нашли нас! Ещё чуть-чуть – и было бы уже поздно..." } } } } },
    [429] = { d = 39.1, v = "scourge-female", n = { x = 341 }, c = { x = { { 0.00, "Моего брата Квинна серьёзно ранил вурдалак Ивар Нечистый. Боюсь, без алхимической помощи он теперь не исцелится." }, { 11.11, "Я мало что понимаю в лекарском искусстве, но знаю, что наши аптекари умеют варить целительные зелья из обесцвеченных сердец воргов." }, { 23.25, "Добудь такие сердца и отнеси их аптекарю Ренферрелу в гробницу к югу отсюда. Потом возвращайся с зельем." }, { 32.93, "Множество воргов водится на пути к Саду Мальдена, что к востоку." } } }, t = { d = 28.3, v = "scourge-male#82", n = { x = 241 }, c = { x = { { 0.00, "Ренферрел берёт у вас сердца." }, { 3.12, "Меня тревожит известие о том, что наши стражи смерти потерпели неудачу в своей миссии." }, { 11.20, "Будем надеяться, что таких неудач будет немного." }, { 15.96, "Я сейчас дам зелье, но вот вам рецепт – если стражам смерти понадобится дальнейшая помощь, быть может, вы сами сможете им её оказать." } } } } },
    [430] = { d = 12.2, v = "scourge-male#82", n = { x = 102 }, c = { x = { { 0.00, "Вот зелье, которое должно помочь Квинну Йорику поправиться." }, { 5.91, "А теперь, простите, мне нужно продолжить одно очень важное дело..." } } }, t = { d = 10.4, v = "scourge-male", n = { x = 77 }, c = { x = { { 0.00, "Квинн выпивает зелье." }, { 2.33, "Да, я чувствую его действие. Вскоре я снова смогу передвигаться. Вы оказали мне большую услугу." } } } } },
    [432] = { d = 31.8, v = "dwarf-male", n = { x = 331 }, c = { x = { { 0.00, "Эти проклятые Светом трогги перевернули всё моё рабочее место! Ты только глянь, ещё одну бочку пороха разворотили!" }, { 8.22, "Ох, прямо руки чешутся спуститься к ним да головы поотрывать! Всех бы поубивал!" }, { 14.02, "Но здоровье не позволяет, да ещё это потрясение и злость... Они ничего мне не оставили!" }, { 20.28, "Я бы сам их перебил, да рука уже не так тверда! Иди в карьер и перебей грязных тварей! Я заплачу!" }, { 28.83, "Ты только задай им шороху, перебей их!" } } }, t = { d = 7.5, v = "dwarf-male", n = { x = 73 }, c = { x = { { 0.00, "Ох, на душе полегчало..." }, { 2.27, "Но я не успокоюсь, пока все трогги не будут уничтожены! Все до единого!" } } } } },
    [433] = { d = 34.3, v = "dwarf-male", n = { x = 379 }, c = { x = { { 0.00, "Будучи членом Сената и Лиги Исследователей, я взял на себя заботу об искоренении троггской заразы, наводнившей наши земли." }, { 9.60, "Они ни за что ни про что разнесли карьер Гол'Болар." }, { 13.58, "Чем глубже мы копаем, тем больше их лезет наружу, уничтожая наше оборудование и выгоняя горняков из шахт." }, { 20.84, "У нас нет выбора, кроме как истребить их как можно больше, отстроиться заново и вернуться к работе." }, { 28.09, "Если вы поможете мне разобраться с троггами, я с радостью возмещу вам затраты времени." } } }, t = { d = 18.2, v = "dwarf-male", n = { x = 210 }, c = { x = { { 0.00, "Это только начало. Надеюсь, мы сможем воспользоваться преимуществом, и выделим небольшой контингент горных пехотинцев для защиты этого района." }, { 10.54, "Тогда мы сможем начать восстановление инфраструктуры и вернуть горняков к работе. Спасибо тебе за помощь." } } } } },
    [434] = { d = 34.4, g = 1, v = "gnome-male", n = { m = 406, f = 407 }, c = { m = { { 0.00, "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем." }, { 8.83, "Пока ты собирал для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром." }, { 16.28, "Я даже подкинул ему пару ложных слухов." }, { 19.43, "Лесковар отпустит свою охрану и будет дожидаться Марзона в саду." }, { 23.81, "Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом." } }, f = { { 0.00, "Сейчас я переодену своего робота-шпиона, и он отправится на аудиенцию к Лесковару. Гвардия пропустит его без особых проблем." }, { 8.83, "Пока ты собирала для меня материалы, я дал Марзону идейку, которую он непременно захочет обсудить с Лесковаром." }, { 16.42, "Я даже подкинул ему пару ложных слухов." }, { 19.56, "Лесковар отпустит свою охрану и будет дожидаться Марзона в саду." }, { 23.94, "Начинай действовать, как только они заведут разговор о Братстве Справедливости. Убей обоих до возвращения гвардейцев! После этого поговори с Триасом." } } }, t = { d = 16.4, g = 1, v = "human-male#50", n = { x = 185 }, c = { m = { { 0.00, "Сделано? Отлично. путник, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу." }, { 7.20, "С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса." }, { 13.63, "Постарайтесь ни во что не вляпаться." } }, f = { { 0.00, "Сделано? Отлично. путница, благодарю вас за посильное участие. Вы оказали Штормовому Оплоту не одну услугу." }, { 7.26, "С вашего позволения, я буду приглядывать за вами: вы можете славно послужить делу Альянса." }, { 13.69, "Постарайтесь ни во что не вляпаться." } } } } },
    [435] = { d = 32.9, v = "scourge-male", n = { x = 332 }, c = { x = { { 0.00, "Волки там, снаружи, никуда не уйдут, и они злобно смотрят на меня каждый раз, когда я выхожу из двери." }, { 7.64, "Должно быть, они невероятно голодны, раз смогли счесть меня пищей." }, { 13.05, "Я должен доложиться своей коллеге, стражу смерти Ран Йорик. Но чтобы добраться до Ран, мне нужна помощь против этих волков." }, { 22.54, "Пожалуйста, проводите меня! Волков здесь очень много, так что наши шансы будут выше, если у вас есть готовые помочь друзья..." } } }, t = { d = 13.3, v = "scourge-female", n = { x = 111 }, c = { x = { { 0.00, "Спасибо за помощь. Я боялась, что Эрланда погубили опасности Серебряного бора." }, { 7.86, "Но я вижу, что благодаря вашей помощи этого не произошло." } } } } },
    [436] = { d = 36.3, v = "dwarf-male", n = { x = 419 }, c = { x = { { 0.00, "Геолог Сталекрут возглавляет раскопки в древних руинах к востоку от озера." }, { 5.20, "В последнее время дело продвигается медленно – и это учитывая, сколько мы послали туда припасов!" }, { 12.02, "Сталекрут – надёжный, честный дворф, который прежде всего болеет за результат, потому-то я и думаю, что кто-то решил ему помешать." }, { 21.15, "Отправляйся к раскопкам Сталекрута и обратись к Магмару Рудоколу." }, { 25.67, "Он ведёт отчётность по раскопкам и сможет объяснить, чем вызвана задержка." }, { 31.18, "Чтобы отыскать раскопки, обогни озеро с юга и направляйся на восток." } } }, t = { d = 11.2, v = "dwarf-male", n = { x = 124 }, c = { x = { { 0.00, "Значит, Джерн хочет узнать, чем вызвана задержка?" }, { 3.77, "Железняк как раз пишет подробный отчёт о своих последних достижениях, но я буду краток. Дело в троггах!!!" } } } } },
    [437] = { d = 43.7, v = "scourge-male", n = { x = 435 }, c = { x = { { 0.00, "Первые отчёты наших разведчиков в Серебряном бору говорят о том, что Гнилошкуры устроили базу на заброшенном поле к северу отсюда – на Мёртвом поле." }, { 11.85, "Мы посылали против них небольшие группы, но им каждый раз помогала банши Плеть Ночи, которая своей магией обращала наших воинов в бегство. Мы хотим уничтожить Плеть Ночи." }, { 24.72, "Отправляйтесь на Мёртвое поле и атакуйте Гнилошкуров. Убивайте их до тех пор, пока не покажется Плеть Ночи, а затем убейте и её." }, { 37.19, "Сущность банши обратится в прах. Принесите мне этот прах в доказательство её смерти." } } }, t = { d = 18.0, v = "scourge-male", n = { x = 198 }, c = { x = { { 0.00, "Я слышал о вашем успешном набеге на гноллов-гнилошкуров, а эта сущность является доказательством смерти банши Плеть ночи." }, { 9.38, "Сегодня Король-лич потерял ещё одного прислужника. Вы становитесь ещё более ценным союзником в глазах Отрёкшихся." } } } } },
    [438] = { d = 22.5, v = "scourge-male", n = { x = 244 }, c = { x = { { 0.00, "Мы обнаружили ещё одно место, где угнездилась Плеть: это старая переправа." }, { 5.67, "Переправа находится к востоку от Гробницы, и её патрулируют многочисленные гноллы-гнилошкуры и различная нежить." }, { 14.38, "Полагаю, Плеть захватила это место неспроста. Отправляйтесь к старой переправе и выясните, в чём там дело." } } }, t = { d = 15.7, v = "scourge-male", n = { x = 164 }, c = { x = { { 0.00, "В лодке находится куча спелёнутых мёртвых тел." }, { 3.54, "А если смотреть на восток через озеро Лордамер, то напротив видна пристань на острове Фенриса." }, { 10.96, "Должно быть, разгадку этой тайны стоит искать на острове." } } } } },
    [439] = { d = 15.5, v = "human-male#114", n = { x = 155 }, c = { x = { { 0.00, "Из кучи трупов торчит обнажённая рука. Это рука женщины – тронутая чумой, но относительно свежая." }, { 8.02, "На пальце надето кольцо. Вы снимаете кольцо и, осмотрев его, обнаруживаете гравировку: \"Делии\"." } } }, t = { d = 15.8, v = "scourge-male", n = { x = 163 }, c = { x = { { 0.00, "Говорите, это кольцо было надето на палец недавно погибшей женщины?" }, { 5.46, "Видимо, тело было поднято из общей могилы в Тирисфале, не иначе." }, { 10.35, "Должно быть, гноллы-гнилошкуры таскают эти трупы на остров Фенриса!" } } } } },
    [440] = { d = 28.8, v = "scourge-male", n = { x = 292 }, c = { x = { { 0.00, "Если хотите найти мужа или возлюбленного Делии – того, кто подарил ей кольцо... поговорите с мировым судьёй Севреном в Брилле." }, { 9.91, "У него должны быть записи о недавних смертях и, если повезёт, он сможет выяснить, кто такая Делия." }, { 17.60, "Но я бы на это не рассчитывал. Тот, кто подарил ей кольцо, вероятно, уже мёртв." }, { 23.40, "Или, если он стал нежитью, то, возможно, ему больше нет дела до Делии." } } }, t = { d = 28.6, v = "scourge-male#82", n = { x = 240 }, c = { x = { { 0.00, "Некая Делия жила в Брилле не так давно." }, { 3.59, "Она была похоронена в общей могиле, но, если верить вашим словам, её тело, должно быть, похитили гноллы из стаи Гнилошкуров и утащили в Серебряный бор." }, { 17.54, "Стая Гнилошкуров, как и вся Плеть, должна быть уничтожена. Я верю, что ты предпримешь к этому надлежащие шаги." } } } } },
    [441] = { d = 19.8, v = "scourge-male#82", n = { x = 169 }, c = { x = { { 0.00, "У Делии был муж по имени Роли, проживающий ныне в Подгороде." }, { 5.61, "Если кольцо действительно принадлежало Делии, которая жила здесь, в Брилле, то Роли узнает его." }, { 14.74, "Найти Роли вы можете в Торговом квартале Подгорода." } } }, t = { d = 23.9, v = "scourge-male", n = { x = 233 }, c = { x = { { 0.00, "Да, это вещица моей жены. Её постигла та же участь, что и всех, кому не удалось пережить эти суровые времена." }, { 8.79, "Меня не трогает её смерть, как не трогает и ваш рассказ о похищении её тела." }, { 14.89, "Подобные чувства давно остыли во мне. Но желание всё ещё клокочет в моём мёртвом сердце. Желание отомстить." } } } } },
    [442] = { d = 24.2, g = 1, v = "scourge-male", n = { m = 245, f = 249 }, c = { m = { { 0.00, "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса." }, { 7.15, "Ты снова должен добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова!" }, { 14.27, "Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача. Ты должен выйти победителем!" } }, f = { { 0.00, "А теперь настало время для нападения на оплот силы Плети в Серебряном бору: остров Фенриса." }, { 7.15, "Ты снова должна добраться до острова и уничтожить Тула Когтя Ворона. Мне нужна его голова!" }, { 14.98, "Я посылаю тебя на смертельно опасное задание, но выполнить его – жизненно важная задача. Ты должна выйти победительницей!" } } }, t = { d = 19.9, v = "scourge-male", n = { x = 208 }, c = { x = { { 0.00, "Смерть Тула Когтя Ворона – значимое событие." }, { 3.18, "Ренферрел рассказывает, что потоки энергии, которые вы высвободили при уничтожении Тула, ощущались аж до Гробницы." }, { 12.85, "Твои действия получили большой резонанс у Отрёкшихся. Твоя ценность в наших глазах растёт." } } } } },
    [443] = { d = 30.8, v = "scourge-male", n = { x = 320 }, c = { x = { { 0.00, "Прежде чем мы совершим нападение на остров Фенриса, мы должны понять, кто стоит за Гнилошкурами." }, { 7.22, "Наши аптекари считают, что их особенности связаны со странной жидкостью, текущей по их жилам." }, { 15.87, "Отправляйся на остров Фенриса, к востоку от старой переправы, и собери лимфу гноллов-гнилошкуров, которых вы там встретите." }, { 25.02, "Образцы нужны аптекарю Ренферрелу, который стоит неподалёку от Гробницы." } } }, t = { d = 12.5, v = "scourge-male#82", n = { x = 108 }, c = { x = { { 0.00, "Отлично. Эта лимфа поможет нам понять природу гноллов-гнилошкуров, а также сможет показать нам, в чём их слабость... ...если она у них есть..." } } } } },
    [444] = { d = 41.5, g = 1, v = "scourge-male#82", n = { m = 360, f = 362 }, c = { m = { { 0.00, "Я выпарил лимфу, которую ты принёс мне, и разложил её на основные компоненты." }, { 7.10, "Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией." }, { 19.34, "Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород." }, { 27.88, "Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров." }, { 36.03, "Иди же. Бетора ты найдёшь в Квартале Магов Подгорода." } }, f = { { 0.00, "Я выпарил лимфу, которую ты принесла мне, и разложил её на основные компоненты." }, { 7.46, "Мои выводы ещё не окончательные, но я определил, что для изготовления этой лимфы пользовались как чернокнижием, так и некромантией." }, { 19.70, "Пока я продолжу её изучение, я прошу тебя отнести один образец Бетору Ледострелу в Подгород." }, { 28.23, "Бетор – не фармацевт, но его знание магии может помочь нам раскрыть тайну Гнилошкуров." }, { 36.38, "Иди же. Бетора ты найдёшь в Квартале Магов Подгорода." } } }, t = { d = 16.9, v = "scourge-male#82", n = { x = 151 }, c = { x = { { 0.00, "Эта субстанция наполнена могучими заклинаниями, с некоторыми из которых я не сталкивался вот уже долгое время..." }, { 10.60, "Секундочку – мне придётся воспользоваться проясняющим заклинанием..." } } } } },
    [445] = { d = 46.8, g = 1, v = "scourge-male#82", n = { m = 393, f = 395 }, c = { m = { { 0.00, "Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и сам понял." }, { 9.86, "Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа." }, { 29.39, "Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору." }, { 38.52, "Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад." } }, f = { { 0.00, "Время – это непозволительная роскошь для тех, кто служит леди Сильване. Ты это, конечно, уже и сама поняла." }, { 10.05, "Я состою в Королевском фармацевтическом обществе и в мои обязанности входит обмен знаниями с коллегами, чтобы однажды нашими совместными усилиями появилась новая чума, которую так желает получить Тёмная Госпожа." }, { 31.27, "Отнеси эти находки аптекарю Ренферрелу – его можно найти в Гробнице, это поселение в Серебряном бору." }, { 40.41, "Если идти из Брилла – то на юг, а если из Подгорода – на юго-запад." } } }, t = { d = 35.9, g = 1, v = "scourge-male#82", n = { x = 287 }, c = { m = { { 0.00, "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований!" }, { 6.95, "Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов." }, { 18.93, "Кстати, надо бы поскорей отправить те образцы в Некрополь..." }, { 24.57, "Ах, простите. Задержитесь в Серебряном бору чуть подольше, такой герой, как вы, всегда нам пригодится." } }, f = { { 0.00, "А, как хорошо, что аптекарь Юхан прислал мне результаты своих исследований!" }, { 6.95, "Здесь, в Серебряном бору, происходит столько всего, что я совсем забыл про материалы из Лордерона и с Тирисфальских лесов." }, { 18.93, "Кстати, надо бы поскорей отправить те образцы в Некрополь..." }, { 24.57, "Ах, простите. Задержитесь в Серебряном бору чуть подольше, такой героиня, как вы, всегда нам пригодится." } } } } },
    [446] = { d = 47.5, v = "scourge-male#82", n = { x = 411 }, c = { x = { { 0.00, "Эта лимфа была создана моим давним коллегой, Тулом Когтем Ворона." }, { 6.10, "До великой войны он был молодым и многообещающим магом, но когда вошёл в силу Король-лич, Тул предал своих братьев и перешёл на сторону Плети." }, { 19.34, "Я и не думал, что он всё ещё жив, и уж тем более – что он возглавляет набеги Гнилошкуров на нас!" }, { 28.45, "Я знаю многие из его заклинаний и могу помочь сварить зелье для того, чтобы им противостоять." }, { 37.03, "Отнеси этот свиток обратно к аптекарю Ренферрелу. Там содержатся заклятья, необходимые для изготовления зелья." } } }, t = { d = 22.2, v = "scourge-male#82", n = { x = 202 }, c = { x = { { 0.00, "Этот свиток весь пронизан могущественной магией. Я никогда не использовал таких сил в зельях..." }, { 8.57, "это будет сильнодействующая микстура, и она должна сослужить тебе хорошую службу, если ты решишься атаковать Тула в его крепости на острове Фенриса." } } } } },
    [447] = { d = 45.6, v = "scourge-male#82", n = { x = 400 }, c = { x = { { 0.00, "Силы Артаса неисчислимы. Но с Новой чумой мы могли бы раз и навсегда покончить как с армией Плети, так и с людьми." }, { 11.54, "Мои исследования показали, что паучья кровь в соединении с токсином, извлечённом из сердца бешеного медведя, даёт смертельно опасный эликсир." }, { 24.24, "Собери необходимые субстанции с пауков из Струящейся Тьмы к северо-западу отсюда и с медведей, бродящих по Серебряному бору." }, { 35.42, "Принеси реагенты в Подгород мастеру-аптекарю Фаранеллу из Королевского фармацевтического общества." } } }, t = { d = 13.4, v = "scourge-male", n = { x = 147 }, c = { x = { { 0.00, "Аптекарь Ренферрел правильно сделал, что послал вас ко мне. Эти образцы действительно будут весьма полезны." }, { 7.98, "Я немедленно начну изучить их отравляющие и инфицирующие свойства." } } } } },
    [448] = { d = 14.4, v = "scourge-male#82", n = { x = 126 }, c = { x = { { 0.00, "Прежде чем вы нападёте на остров Фенриса, доложитесь верховному палачу Хадрику." }, { 7.36, "У него может быть дополнительная информация о том, что вам понадобится." } } }, t = { d = 16.7, v = "scourge-male", n = { x = 179 }, c = { x = { { 0.00, "Если то, что говорит Бетор, – правда, то Тул Коготь Ворона представляет собой силу, с которой нужно разобраться, причём разобраться срочно." }, { 10.38, "В качестве помощи можете подобрать себе что-нибудь из нашего здешнего арсенала..." } } } } },
    [449] = { d = 18.1, v = "scourge-female", n = { x = 165 }, c = { x = { { 0.00, "Хотя раны Квинна заживают, я хотела бы доставить наш отчёт верховному палачу Хадрику как можно скорее." }, { 9.30, "В нём содержится информация, которая жизненно важна для захвата Серебряного бора Отрёкшимися." } } }, t = { d = 18.4, v = "scourge-male", n = { x = 202 }, c = { x = { { 0.00, "Я не ожидал ни такого количества Плети, с каким мы столкнулись в Серебряном бору, ни проблем, которые возникли перед стражами смерти в ходе разведывательной операции." }, { 12.45, "Ваша помощь нашим стражам смерти просто неоценима. Вы заслуживаете похвалы." } } } } },
    [450] = { d = 39.7, v = "scourge-male", n = { x = 424 }, c = { x = { { 0.00, "Вы можете ещё послужить Королевскому фармацевтическому обществу." }, { 5.19, "Когда Аругал навёл на лес свою никчёмную магию, он наложил проклятие на одного из наших самых многообещающих сотрудников, аптекаря Берарда." }, { 16.23, "Ставший безвольным слугой Аругала, теперь Берард для нас бесполезен. Но его находки могут быть ценными." }, { 23.87, "Он изучал древнюю чуму, давным-давно погубившую всякую жизнь в озере Лордамер." }, { 30.08, "Раздобудьте записи Берарда из его кабинета в таверне деревни Погребальных Костров и принесите аптекарю Ренферрелу." } } }, t = { d = 11.4, v = "scourge-male#82", n = { x = 101 }, c = { x = { { 0.00, "Записи аптекаря Берарда! В смелости вам не откажешь. Теперь давайте посмотрим, чем занимался Берард прежде, чем сошёл с ума..." } } } } },
    [451] = { d = 48.8, v = "scourge-male#82", n = { x = 425 }, c = { x = { { 0.00, "Согласно записям Берарда, мох озёрных тихоходов и озёрных ползунов может оказаться полезным для решения нашей задачи по изготовлению новой отравы." }, { 14.61, "Эти твари обитают на островах на озере Лордамер на востоке." }, { 20.57, "Он также упоминает об очень редкой субстанции – твёрдой опухоли, обнаруженной им у мурлока из племени Злобного Плавника." }, { 31.37, "Очевидно, эта опухоль столь редка, что Берарду удалось раздобыть лишь одну." }, { 38.75, "Соберите образцы моха, а также редкую твёрдую опухоль и отнесите их мастеру-аптекарю Фаранеллу в Подгород." } } }, t = { d = 28.1, g = 1, v = "scourge-male", n = { x = 301 }, c = { m = { { 0.00, "Потеря Берарда – серьёзный удар для Королевского фармацевтического общества." }, { 5.69, "Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Тёмной Госпожи." }, { 16.52, "Мы находимся на пороге чего-то великого путник." }, { 20.18, "Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества." } }, f = { { 0.00, "Потеря Берарда – серьёзный удар для Королевского фармацевтического общества." }, { 5.69, "Но благодаря вашим стараниям и усердным исследованиям аптекаря Ренферрела разработки Берарда по-прежнему будут полезны делу Тёмной Госпожи." }, { 16.52, "Мы находимся на пороге чего-то великого путница." }, { 20.28, "Если бы вы не были столь искусны в военном деле, я пригласил бы вас вступить в члены нашего Общества." } } } } },
    [452] = { d = 49.0, v = "scourge-female", n = { x = 423 }, c = { x = { { 0.00, "Вы очень вовремя добрались сюда!" }, { 3.47, "Совет деревни Погребальных Костров вернётся в любой момент. Аругалу же есть чем заняться в крепости." }, { 13.53, "Он использует совет как марионеток, чтобы держать лишённых разума и воли приспешников в деревне под своим полным контролем." }, { 24.46, "Но я уверена, что без руководства совета деревни Погребальных Костров сыновья Аругала взбунтовались бы против своего хозяина." }, { 37.33, "Я не могу справиться со всем в этим в одиночку. Мне нужна ваша помощь. Вместе мы сможем погубить совет, на благо леди Сильваны." } } }, t = { d = 20.4, v = "scourge-female", n = { x = 189 }, c = { x = { { 0.00, "Вы бились достойно настоящего последователя Тёмной Госпожи." }, { 5.47, "Теперь, когда члены Совета мертвы, может быть, мы сможем восстановить контроль над этой деревней раз и навсегда и выбить Аругала из крепости Тёмного Клыка. Честь имею!" } } } } },
    [453] = { d = 8.6, v = "human-male#50", n = { x = 95 }, c = { x = { { 0.00, "Удачи. Надеюсь, ты найдёшь этого парня, причём живым." }, { 3.98, "Сбежав за пределы Темнолесья, он мог пасть жертвой диких зверей." } } }, t = { d = 10.6, v = "human-male", n = { x = 112 }, c = { x = { { 0.00, "Трясунчик вздыхает..." }, { 1.74, "Да, автор этой книги – я. Сумел-таки отыскать меня?" }, { 5.49, "Но если ты прочитаешь мои записи, то узнаешь только половину истории!" } } } } },
    [454] = { d = 17.9, v = "dwarf-male", n = { x = 198 }, c = { x = { { 0.00, "До этого... случая мы всё время таскали туда-сюда бочки с порохом." }, { 4.90, "Теперь придётся поделить работу: Миран понесёт часть бочек, а я присмотрю за остальными." }, { 11.39, "Мне не хочется отпускать Мирана одного. Когда он соберётся в путь, проводи, пожалуйста, его." } } }, t = { d = 17.7, g = 1, v = "dwarf-male", n = { x = 186 }, c = { m = { { 0.00, "Добрый день, герой." }, { 1.80, "Ты проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа." }, { 10.80, "Я почти готов, осталось только кое-что проверить. Когда ты соберёшься в путь, скажи мне об этом." } }, f = { { 0.00, "Добрый день, героиня." }, { 1.92, "Ты проводишь меня до раскопа? Отлично... После случая с Сайаном и его компанией я не знаю, чего и ждать от клана Чёрного Железа." }, { 10.92, "Я почти готов, осталось только кое-что проверить. Когда ты соберёшься в путь, скажи мне об этом." } } } } },
    [455] = { d = 42.6, v = "dwarf-male", n = { x = 458 }, c = { x = { { 0.00, "Орки из клана Драконьей Пасти бесчинствуют по всей Болотине. А сейчас они двинулись на Дун Альгаз!" }, { 6.83, "Нельзя допустить, чтобы они здесь закрепились, иначе Лок Модан будет отрезан от Гавани Менетилов, нашего порта и крепости в Болотине." }, { 16.38, "Попытайся прорваться сквозь Дун Альгаз в Болотине и убей столько орков, сколько сумеешь! Чем больше, тем лучше!" }, { 24.69, "Об исполнении доложишь Валстагу Сталезубу в Гавани Менетилов." }, { 30.55, "Найти Менетилов несложно: пройдёшь через Дун Альгаз, потом – по дороге на север, а на развилке свернёшь на запад." }, { 39.24, "Мы очень надеемся на тебя. Не подведи нас." } } }, t = { d = 21.5, v = "dwarf-male", n = { x = 240 }, c = { x = { { 0.00, "Да, нехорошие новости!" }, { 1.97, "Как я понимаю, орки Драконьей Пасти всерьёз вознамерились двинуться на Альгаз." }, { 7.39, "Обычно они сидят у себя на холмах и никуда не суются. Что их сподвигло идти на Альгаз? Для меня это загадка..." }, { 15.22, "Спасибо. Может быть, нам понадобится твоя помощь, когда мы пойдём разбираться с орками." } } } } },
    [456] = { d = 34.6, g = 1, v = "nightelf-male#54", n = { m = 358, f = 358 }, c = { m = { { 0.00, "Мои приветствия. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия." }, { 8.42, "Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают." }, { 16.74, "К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить." }, { 26.57, "Юный герой, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия." } }, f = { { 0.00, "Мои приветствия. Я – Опекун Илталайн. Здесь, в Тенистой долине, я слежу за поддержанием природного равновесия." }, { 8.42, "Весенние дожди в этом году были очень сильными, и от этого одни лесные существа благоденствуют, а другие страдают." }, { 16.74, "К несчастью, ночные саблезубы и щетинистые вепри слишком расплодились. Тенистая долина не может их прокормить." }, { 26.57, "Юная героиня, помоги нам – сократи численность вепрей и саблезубов ради сохранения природного равновесия." } } }, t = { d = 2.6, g = 1, v = "nightelf-male#54", n = { m = 24, f = 25 }, c = { m = { { 0.00, "Ты хорошо исполнил свой долг." } }, f = { { 0.00, "Ты хорошо исполнила свой долг." } } } } },
    [457] = { d = 27.5, v = "nightelf-male#54", n = { x = 321 }, c = { x = { { 0.00, "Сокращение численности молодых особей, обитающих в Тенистой долине – это неплохо для начала, однако нужно выполнить ещё некоторую работу." }, { 9.78, "Лесные ресурсы истощатся слишком быстро, если не решить эту проблему." }, { 14.62, "Охота на диких зверей – это зло, необходимое для блага всех тех, кто обитает в этих землях." }, { 20.85, "Отправляйся в лес и убивай облезлых ночных саблезубов и щетинистых вепрей ради равновесия." } } }, t = { d = 9.4, g = 1, v = "nightelf-male#54", n = { x = 103 }, c = { m = { { 0.00, "Твои дела доказывают твою преданность природе. Поверь, герой, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее." } }, f = { { 0.00, "Твои дела доказывают твою преданность природе." }, { 3.23, "Поверь, героиня, несмотря на твою юность уже заметно, что тебя ждёт блестящее будущее." } } } } },
    [458] = { d = 28.6, g = 1, v = "nightelf-male#55", n = { x = 322 }, c = { m = { { 0.00, "Какая отрада, что ты здесь, герой. Шёпот лесных духов донёс до моего слуха странные вести." }, { 6.50, "Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора." }, { 14.60, "Что-то определённо не так, если она вновь появилась в этих землях." }, { 19.40, "Найди Тариндреллу и узнай, что привело её в наши рощи." }, { 23.00, "Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила." } }, f = { { 0.00, "Какая отрада, что ты здесь, героиня. Шёпот лесных духов донёс до моего слуха странные вести." }, { 6.68, "Таинственная защитница леса, Тариндрелла, вернулась в Тенистую долину. Много лет эту дриаду не видели в лесах Калимдора." }, { 14.77, "Что-то определённо не так, если она вновь появилась в этих землях." }, { 19.58, "Найди Тариндреллу и узнай, что привело её в наши рощи." }, { 23.18, "Кто-то из Стражей сообщил о том, что её видели к юго-западу от Альдрассила." } } }, t = { d = 15.8, g = 1, v = "human-female", n = { m = 182, f = 182 }, c = { m = { { 0.00, "Я вижу, тебе удалось найти меня, юный ночной эльф! Друид Мелитар мудро поступил, отправив тебя сюда." }, { 6.94, "Тебе ещё многому нужно научиться. Я так понимаю, ваш народ любит книги. Можешь взять одну из них, чтобы углубить свои познания." } }, f = { { 0.00, "Я вижу, тебе удалось найти меня, юная ночной эльф! Друид Мелитар мудро поступил, отправив тебя сюда." }, { 6.77, "Тебе ещё многому нужно научиться. Я так понимаю, ваш народ любит книги. Можешь взять одну из них, чтобы углубить свои познания." } } } } },
    [459] = { d = 30.3, v = "human-female", n = { x = 356 }, c = { x = { { 0.00, "Непонятное зло затаилось в лесу Тельдрассила. Взгляни на холмы, где некогда обитали мирные фурболги." }, { 7.43, "Они покинули свои дома и объединились в племя Кривой Сосны." }, { 11.67, "Лишь порча, вызванная зловещим мхом Скверны, могла быть причиной подобного изменения." }, { 17.48, "Грелли и греллиды кишат в округе, представляя собой угрозу для жителей Тенистой долины." }, { 23.72, "Напади на этих бесов, и узнай, действительно ли они подпали под чары зловещего мха Скверны." } } }, t = { d = 27.5, g = 1, v = "human-female", n = { x = 289 }, c = { m = { { 0.00, "Твоё служение обитателям Тенистой долины достойно награды." }, { 4.29, "Однако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь." }, { 16.38, "герой, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печётся о благополучии леса." } }, f = { { 0.00, "Твоё служение обитателям Тенистой долины достойно награды." }, { 4.29, "Однако мои опасения подтвердились. Если даже грелли попали под влияние мха Скверны, то можно вообразить, что случилось с фурболгами племени Кривой Сосны, некогда жившими здесь." }, { 16.39, "героиня, если будешь в Доланааре, отыщи мудрого друида Атридаса Медвежью Шкуру. Он, как и мы, печётся о благополучии леса." } } } } },
    [460] = { d = 43.6, v = "scourge-male", n = { x = 452 }, c = { x = { { 0.00, "На вид ты не похож на гнилошкура. Это хорошо. А то я уже потерял надежду..." }, { 6.81, "Меня зовут Аларик, когда-то я был доверенным слугой и телохранителем Тула." }, { 12.47, "Он использовал свою магию для \"защиты\" меня от Чумы Нежити, но вместо этого его заклинание повергло меня в нежитие – состояние, из которого я не могу уйти." }, { 23.49, "А после создания этих проклятых гнилошкурых гноллов Туле обезглавил меня... и отдал гноллам мою голову в качестве игрушки!" }, { 32.88, "Пожалуйста, воссоедини меня с телом." }, { 35.86, "Я уверен, что гноллы закопали его в Крепости Фенриса, возле стойл, в ничем не примечательной могиле." } } }, t = { d = 8.5, v = "scourge-male", n = { x = 67 }, c = { x = { { 0.00, "Спасибо. Я опасался, что гноллы изуродовали моё тело. Приятно узнать, что это не так." } } } } },
    [461] = { d = 26.6, v = "scourge-male", n = { x = 274 }, c = { x = { { 0.00, "Я знаю об одной тайной нише в крепости, где хранится дорогой сердцу Тула и его давних коллег предмет." }, { 7.65, "В ней также лежит нечто, что вы можете счесть полезным для себя. Возьмите меня туда!" }, { 14.36, "Углубление в стене находится в юго-западной башне крепости, позади пыльной полки." }, { 20.76, "Возьмите моё тело, а сапоги оставьте здесь. Они мне всё равно не по ноге..." } } }, t = { d = 21.9, v = "scourge-male", n = { x = 211 }, c = { x = { { 0.00, "Вот мы и на месте, здесь открыто. Оставь меня здесь." }, { 4.01, "Лучшие дни своей жизни я провёл в этой крепости, и мысль об упокоении в этих стенах умиротворяет меня." }, { 11.99, "Хорошенько закрой нишу – я не хочу, чтобы эти гнилошкуры нашли меня." }, { 17.41, "Ах, да, и возьми вот это. Ты это заслуживаешь." } } } } },
    [463] = { d = 38.4, g = 1, v = "human-male#50", n = { m = 445, f = 446 }, c = { m = { { 0.00, "Ты ведь слышал рассказы о Зелёном Страже? Я даже подозреваю, что ты и разыскать его хочешь." }, { 6.14, "Если так, то скажу тебе, что это чистое безумие!" }, { 9.46, "Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим." }, { 15.94, "Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями." }, { 24.67, "Оставь-ка свои денежки мне – покойникам они всё равно не нужны." }, { 28.93, "Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое..." }, { 34.93, "Ты ведь не хочешь, чтобы бедняга потом мучился?" } }, f = { { 0.00, "Ты ведь слышала рассказы о Зелёном Страже? Я даже подозреваю, что ты и разыскать его хочешь." }, { 6.09, "Если так, то скажу тебе, что это чистое безумие!" }, { 9.41, "Впрочем, не мне тебя отговаривать: хочешь найти верную смерть – пожалуйста, милости просим." }, { 15.89, "Он живёт на болотах, к востоку от развилки на дороге, ведущей в Дун Модр. Рыщет там на пару с кроколисками... и прочими тварями." }, { 24.62, "Оставь-ка свои денежки мне – покойникам они всё равно не нужны." }, { 28.88, "Да и Зелёный Дядя может обломать зуб о твои золотые, когда будет перекусывать тебя надвое..." }, { 34.88, "Ты ведь не хочешь, чтобы бедняга потом мучился?" } } }, t = { d = 24.0, g = 1, v = "tauren-male", n = { m = 221, f = 221 }, c = { m = { { 0.00, "Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришёл с добрым умыслом..." }, { 8.56, "Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль." }, { 15.70, "А теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их." } }, f = { { 0.00, "Что это за букашка ко мне пожаловала? Корни и папоротники говорят, что ты пришла с добрым умыслом..." }, { 7.72, "Меня по-разному называют, но не на всякое имя я откликаюсь. Зови меня Ретиль." }, { 14.86, "А теперь внемли... Здешние земли уже давно страдают от множества недугов, и я поручу тебе исцелить их." } } } } },
    [464] = { d = 32.3, v = "dwarf-male", n = { x = 372 }, c = { x = { { 0.00, "К концу Второй войны клан орков Драконьей Пасти потерял власть над красными драконами и был почти уничтожен." }, { 7.56, "Драконы припомнили им всё, гнали бывших хозяев аж до самого Грим Батола." }, { 12.64, "Затем орки скрылись в горах к востоку от раскопа Вельгара." }, { 16.91, "Отсидевшись в горах, они вновь набрали силу и теперь разбили лагерь к северо-востоку от Менетила." }, { 24.41, "Напади на этот лагерь, внеси панику в ряды орков. В доказательство содеянного принеси мне боевые знамёна клана." } } }, t = { d = 30.9, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Отличная работа. Ныне клан Драконьей Пасти уж не тот, что в былые времена, когда оркам служили драконы." }, { 6.94, "Но всё равно они опасные противники." }, { 9.83, "Кланом Драконьей Пасти руководит Нек'рош, сын Некросса – бывшего главы клана." }, { 14.93, "Некросс владел могущественными заклинаниями, с помощью которых он управлял красными драконами. Но когда его силы иссякли... ну, ты уже знаешь эту историю." }, { 25.62, "Некросс погиб, а его сын поклялся отомстить драконам, убившим его отца." } } } } },
    [466] = { d = 37.5, v = "dwarf-male", n = { x = 422 }, c = { x = { { 0.00, "Я слышал о редком виде руды – огневите. Его добывают в Болотине, в пещере к северо-западу от Врат Альгаза." }, { 7.13, "Огневит очень неустойчив – чуть что, сразу взрывается." }, { 10.84, "Однако я уверен, что если правильно его выплавить, то можно делать из него мощнейшие снаряды для пушек!" }, { 18.31, "Раздобудь для меня огневитовую руду, а я пока поищу добровольца, который согласится принять участие в опытах." }, { 26.92, "Ах да, чтобы добыть руду, тебе нужны познания в горном деле. Если у тебя нет необходимых знаний, то..." }, { 33.74, "отправь в шахту кого-нибудь из знакомых рудокопов!" } } }, t = { d = 12.6, v = "dwarf-male", n = { x = 145 }, c = { x = { { 0.00, "Как раз столько, сколько нужно для экспериментов! Молодец, я в тебя верил! Тут же отправлю материал на изучение." }, { 7.58, "Надеюсь, что мой доброволец хотя бы до первых результатов доживёт!" } } } } },
    [467] = { d = 25.1, v = "dwarf-male", n = { x = 277 }, c = { x = { { 0.00, "Пилот Камнекожиц любит свою осадную машину, как и все пилоты осадных машин!" }, { 5.15, "И он всегда рад найти новый способ повысить огневую мощь своих орудий." }, { 10.29, "До него дошли слухи о редкой руде, и он ищет кого-нибудь, кто добудет её." }, { 15.15, "И если тебе уже не терпится взяться за это дело, то найди Камнекожица в посёлке Сталежара в Дун Мороге и спроси, чего он хочет." } } }, t = { d = 7.1, g = 1, v = "dwarf-male", n = { m = 72, f = 72 }, c = { m = { { 0.00, "Привет. Ты тут по моему делу, да? Приятно видеть, как молодой герой рвётся на поиски приключений!" } }, f = { { 0.00, "Привет. Ты тут по моему делу, да? Приятно видеть, как молодая героиня рвётся на поиски приключений!" } } } } },
    [468] = { d = 18.7, v = "dwarf-male", n = { x = 219 }, c = { x = { { 0.00, "Горный пехотинец Рокхар ищет добровольцев для похода через Дун Альгаз в Болотину!" }, { 6.09, "Если желаете омыть сапоги в болотной жиже и снискать приключений на свою голову – поговорите со Скальным Панцирником в Дун Альгаз." }, { 14.75, "Это к северу отсюда, по дороге за сторожевой башней." } } }, t = { d = 13.6, g = 1, v = "dwarf-male", n = { x = 143 }, c = { m = { { 0.00, "герой, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично!" }, { 5.97, "Надеюсь, у тебя есть всё необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже..." } }, f = { { 0.00, "героиня, ни больше, ни меньше! Желаешь отправиться с нами в разведку? Отлично!" }, { 5.61, "Надеюсь, у тебя есть всё необходимое снаряжение, потому что эта \"разведка\" может обернуться и кое-чем похуже..." } } } } },
    [469] = { d = 29.5, g = 1, v = "dwarf-male", n = { m = 323, f = 330 }, c = { m = { { 0.00, "Привет тебе, странник!" }, { 2.01, "Не лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!" }, { 12.31, "Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана." }, { 21.87, "Я бы и сам отнёс их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза." } }, f = { { 0.00, "Привет тебе, путешественница!" }, { 2.42, "Не лежит ли твой путь в сторону Менетила? Если нет, то знай, что там можно передохнуть, сделать покупки и пропустить пару пинт. Прелестный городок!" }, { 12.72, "Ну а если ты как раз туда и направляешься, то я бы хотел передать с оказией стопку кроколисковых шкур для кожевника Джеймса Халлорана." }, { 22.28, "Я бы и сам отнёс их, но дома последнее время то свара, то скандал. Не хочу попадаться жене на глаза." } } }, t = { d = 15.7, v = "human-male", n = { x = 170 }, c = { x = { { 0.00, "Хмм, да это же от Эйнара, да? Не вижу его уж который день, а шкуры присылает исправно." }, { 5.97, "Опять поцапался со своей благоверной, к бабке не ходи!" }, { 10.11, "Надо бы подослать жену к Сиде – поговорить, чтобы та не выживала мужа из дому..." } } } } },
    [470] = { d = 31.9, g = 1, v = "dwarf-female#34", n = { m = 360, f = 361 }, c = { m = { { 0.00, "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась..." }, { 11.76, "Я бросила в одного из них сумку, но он взял и засосал её! Мне едва хватило времени, чтобы сбежать. А в сумке-то мои вещи!" }, { 20.10, "Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые!" }, { 24.52, "Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что согласился помочь!" } }, f = { { 0.00, "Каждую неделю я хожу к Гробнице Железноборода, и в этот раз всё было как всегда, но вдруг на меня напали омерзительные хлюпающие слизнюки! Я так растерялась..." }, { 11.76, "Я бросила в одного из них сумку, но он взял и засосал её! Мне едва хватило времени, чтобы сбежать. А в сумке-то мои вещи!" }, { 20.10, "Я даже не знаю, какой из этих гадов её сожрал – они все одинаковые!" }, { 24.52, "Гробница Железноборода находится к северо-востоку отсюда, возле Дун Модра. Спасибо, что согласилась помочь!" } } }, t = { d = 16.3, v = "dwarf-female#34", n = { x = 182 }, c = { x = { { 0.00, "Спасибо большущее! Я-то боялась, что её больше не вернуть!" }, { 4.68, "Она вытряхивает из склизкой сумки содержимое и собирает мелочь в кучку." }, { 9.76, "Хм, чего-то я здесь самого нужного и не вижу... посмотри, может, тебе что-нибудь отсюда пригодится." } } } } },
    [471] = { d = 33.2, v = "human-male", n = { x = 379 }, c = { x = { { 0.00, "Недавно я отправил помощника на болото за шкурами гигантских болотных кроколисков." }, { 5.75, "Он не вернулся обратно, и я отправился на поиски... Скажем так: зрелище было не для слабонервных." }, { 12.86, "Лекарь говорит, что мальчик выживет, и слава богу, но у меня-то работа стоит!" }, { 18.53, "Если у тебя есть желание поохотиться на кроколисков, я препятствовать не стану – особенно после того, что они сделали с моим помощником." }, { 27.81, "Кроколиски водятся на побережье к северу отсюда, за поселением мурлоков." } } }, t = { d = 17.6, v = "human-male", n = { x = 188 }, c = { x = { { 0.00, "Хмм... не думаю, что ты захочешь наняться ко мне в помощники, так ведь?" }, { 5.05, "Хе-хе-хе! Да шучу я. Староват ты для этого, да и заметно, что у тебя на роду совсем другое написано." }, { 12.03, "Благодарю тебя за помощь. Шкуры отменные – как раз подойдут мне для работы!" } } } } },
    [472] = { d = 35.5, g = 1, v = "dwarf-male", n = { x = 376 }, c = { m = { { 0.00, "Дворфы Чёрного Железа захватили Дун Модр!" }, { 3.85, "Я тяжело ранен, герой. Почти все мои однополчане погибли!" }, { 8.22, "Подонки из клана Чёрного Железа набросились на нас, не успели мы оправиться после взрыва." }, { 14.79, "Наш командир, Длинная Коса, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание..." }, { 23.52, "Очнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длинная Коса тоже спасся!" }, { 32.23, "Иди в Дун Модр и отыщи его, путник!" } }, f = { { 0.00, "Дворфы Чёрного Железа захватили Дун Модр!" }, { 3.85, "Я тяжело ранен, героиня. Почти все мои однополчане погибли!" }, { 8.47, "Подонки из клана Чёрного Железа набросились на нас, не успели мы оправиться после взрыва." }, { 15.04, "Наш командир, Длинная Коса, протрубил сигнал к отступлению. Во время бегства мне в спину попал топорик. Я потерял сознание..." }, { 23.77, "Очнулся уже в Менетиле, но меня волнует судьба остальных солдат. Надежда умирает последней... Может быть, Длинная Коса тоже спасся!" }, { 32.48, "Иди в Дун Модр и отыщи его, путница!" } } }, t = { d = 29.8, g = 1, v = "dwarf-male", n = { x = 301 }, c = { m = { { 0.00, "Какие новости из Менетила принёс нам добрый герой? Так-так-так, значит, тебя зовут путник. Приятно познакомиться." }, { 8.10, "Что ж, весть добрая. Слава Свету, что молодой Харло выжил." }, { 13.20, "Ранение у него было очень тяжёлое, и нам пришлось отправить его в город на единственном уцелевшем скакуне." }, { 20.88, "Однако в целом ситуация безнадёжная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания." } }, f = { { 0.00, "Какие новости из Менетила принёс нам добрый героиня? Так-так-так, значит, тебя зовут путница. Приятно познакомиться." }, { 8.23, "Что ж, весть добрая. Слава Свету, что молодой Харло выжил." }, { 13.33, "Ранение у него было очень тяжёлое, и нам пришлось отправить его в город на единственном уцелевшем скакуне." }, { 21.01, "Однако в целом ситуация безнадёжная: Дун Модр пал, а от нашего славного полка остались лишь воспоминания." } } } } },
    [473] = { d = 16.5, g = 1, v = "dwarf-male", n = { x = 177 }, c = { m = { { 0.00, "путник. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза." }, { 6.27, "Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков." }, { 13.64, "Он сейчас в крепости, в зале Войны." } }, f = { { 0.00, "путница. Орки из клана Драконьей Пасти совсем озверели. Им уже мало одного Альгаза." }, { 6.36, "Капитан Крепкий Кулак просил направлять к нему всех, кто готов оказать нам содействие в войне против орков." }, { 13.73, "Он сейчас в крепости, в зале Войны." } } }, t = { d = 14.3, g = 1, v = "dwarf-male", n = { m = 126, f = 126 }, c = { m = { { 0.00, "путник. Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – достойный герой. Нам такие нужны." }, { 9.33, "И у меня уже есть для тебя поручение." } }, f = { { 0.00, "путница. Валстаг вкратце рассказал мне о твоих победах над орками Драконьей Пасти в Дун Альгазе. Ты – достойная героиня. Нам такие нужны." }, { 11.35, "И у меня уже есть для тебя поручение." } } } } },
    [475] = { d = 30.3, v = "nightelf-male#55", n = { x = 339 }, c = { x = { { 0.00, "Ветер тревоги веет над лесом." }, { 2.43, "Гэролас Талветрен служит Великим смотрителем за спящими друидами-воронами в обители Бен'этиль." }, { 9.99, "Его долг – обеспечивать их безопасность, дабы их уговор с Изерой оставался в силе." }, { 15.85, "Но вести от Гэроласа что-то задерживаются, и я начинаю волноваться." }, { 20.50, "Отправляйся на восток в Деревню Звёздного Ветра – мне нужен отчёт Гэроласа, дабы я был спокоен, узнав, что мои братья и сёстры спят спокойно." } } }, t = { d = 5.9, v = "nightelf-male", n = { x = 65 }, c = { x = { { 0.00, "Хвала лесным духам, ты здесь! Я знал, что Атридас забеспокоится и пришлёт помощь." } } } } },
    [476] = { d = 34.8, g = 1, v = "nightelf-male", n = { m = 387, f = 387 }, c = { m = { { 0.00, "Племя Кривой Сосны поражено порчей!" }, { 2.97, "Эти некогда мирные фурболги обратились против покровителей леса." }, { 7.43, "Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра." }, { 14.70, "Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны." }, { 19.97, "Я слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придётся сделать тебе, юный герой." }, { 27.25, "Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!" } }, f = { { 0.00, "Племя Кривой Сосны поражено порчей!" }, { 2.97, "Эти некогда мирные фурболги обратились против покровителей леса." }, { 7.43, "Они подстерегли меня в засаде, когда я выходил из обители Бен'этиль и разграбили Деревню Звёздного Ветра." }, { 14.70, "Их вождь, Урсал Изверг, затмевает их разум при помощи мха Скверны." }, { 19.97, "Я слишком изранен, чтобы донести до Атридаса эти страшные вести. Теперь это придётся сделать тебе, юная героиня." }, { 27.75, "Остаётся только надеяться, что безумные фурболги Кривой Сосны ещё не уничтожили Бен'этиль!" } } }, t = { d = 3.3, v = "nightelf-male#55", n = { x = 37 }, c = { x = { { 0.00, "Клянусь звёздами! Воистину тревожные вести!" } } } } },
    [477] = { d = 43.1, v = "scourge-male", n = { x = 463 }, c = { x = { { 0.00, "Как вы, должно быть, знаете, в деревне Янтарная Мельница окопалась враждебная группа людей." }, { 6.76, "Она держится там в основном за счёт поддержки, которую они получают от волшебников Даларана." }, { 13.92, "Я не знаю, что они замышляют, но сам по себе интерес, проявленный ими к захолустной деревушке вроде Янтарной Мельницы, показывает, что она имеет немаленькое значение." }, { 27.42, "Они отправляют повозкой из Хилсбрада сундуки." }, { 30.86, "Многое из привезённого складируется в небольшом лагере к северу от деревни Погребальных Костров." }, { 38.10, "Раздобудьте содержимое одного такого сундука и принесите мне." } } }, t = { d = 24.8, v = "scourge-male", n = { x = 261 }, c = { x = { { 0.00, "*С любопытством открыв крышку ящика, вы находите в нём множество тщательно упакованных предметов." }, { 8.54, "На самом верху лежит связка пожелтевших от времени карт, на которых, судя по всему, изображено Серебряный бор и другие области западного Лордерона." }, { 19.57, "Под картами обнаруживается подвеска таинственно-волшебного вида.*" } } } } },
    [478] = { d = 6.1, v = "human-male#114", n = { x = 58 }, c = { x = { { 0.00, "*Вы быстро вытаскиваете подвеску из сундука и кладёте крышку на место.*" } } }, t = { d = 16.9, v = "scourge-male", n = { x = 173 }, c = { x = { { 0.00, "Карты и эта... эта подвеска? Интересно." }, { 3.21, "Очевидно, что волшебники Даларана почему-то интересуются Янтарной мельницей, но их цель по-прежнему остаётся неизвестной." }, { 12.61, "Может быть, Далар сможет выяснить, что они там ищут." } } } } },
    [479] = { d = 23.8, v = "scourge-male", n = { x = 252 }, c = { x = { { 0.00, "Далар пытается выяснить, каков источник магической силы этих волшебников. А пока что нам нужно замедлить их прогресс любым путём..." }, { 9.89, "Маги, окудники и заступники, несомненно, носят такие подвески. Добудьте их." }, { 15.82, "Чтобы добраться до Янтарной Мельницы, идите на юг по главной дороге, а на развилке сверните на восток." } } }, t = { d = 14.8, v = "scourge-male", n = { x = 159 }, c = { x = { { 0.00, "Далар выяснил, что несмотря на замедление, процесс плетения чар зашёл уже далеко." }, { 6.48, "Некий очень могущественный волшебник направляет магическую энергию. Его нужно как можно скорее остановить." } } } } },
    [480] = { d = 25.8, v = "scourge-male", n = { x = 277 }, c = { x = { { 0.00, "Верховный маг огромной силы отвечает за реактивацию энергетического узла." }, { 5.59, "Они уже далеко зашли, так что единственный способ их остановить – это убить его." }, { 11.42, "Это будет тяжело – безусловно, его защищают многочисленные маги и охранники." }, { 17.42, "Вам надо пойти и разобраться с ним, быстро. Когда он будет мёртв, принесите мне его посох. Идите немедленно." } } }, t = { d = 23.6, v = "scourge-male", n = { x = 262 }, c = { x = { { 0.00, "Магия волшебников рассеивается, и энергетические узлы вновь засыпают." }, { 5.16, "Ваши усилия оказались плодотворными, и мы сумели нанести нашим врагам и могучим волшебникам Даларана серьёзный удар." }, { 14.31, "Однако нужно не терять бдительности – ведь источник энергии находится совсем близко... Нужно разрабатывать планы на будущее." } } } } },
    [481] = { d = 8.3, v = "scourge-male", n = { x = 88 }, c = { x = { { 0.00, "Отнесите подвеску Далару Ткачу Рассвета – может быть, он сможет пролить какой-то свет на планы волшебников." } } }, t = { d = 35.3, v = "scourge-male#82", n = { x = 303 }, c = { x = { { 0.00, "Интересно – похоже, новые махинации Кирин-Тора. Это могущественный артефакт." }, { 7.70, "Такие часто использовали могучие волшебники Кирин-Тора для передачи магической энергии." }, { 16.22, "То, что они так много таких вещиц доставляют в Янтарную Мельницу, указывает на то, что затевается что-то серьёзное." }, { 27.06, "Посмотрим, сумею ли я проникнуть сквозь защиту и поточнее разузнать об их намерениях." } } } } },
    [482] = { d = 50.6, v = "scourge-male#82", n = { x = 444 }, c = { x = { { 0.00, "Конечно! Как же я мог забыть?" }, { 3.46, "Янтарная Мельница была одним из мест, отмеченных магами Кирин Тора, и примечательна тем, что на территории деревни находится спящий энергетический узел." }, { 17.30, "Волшебники, должно быть, планируют реактивировать узел и использовать его энергию для какой-то более серьёзной цели." }, { 28.22, "Мы не можем позволить этому случиться..." }, { 32.21, "Чтобы активировать энергии этого места, понадобится много сил, и мы можем осложнить им задачу, стащив у волшебников подвески." }, { 43.84, "Передайте эту информацию Алистеру, он спланирует дальнейшие действия." } } }, t = { d = 17.2, v = "scourge-male", n = { x = 172 }, c = { x = { { 0.00, "Вы принесли тревожные вести. Если Далар прав – а у меня нет оснований думать иначе – мы должны действовать быстро." }, { 9.50, "Мне нужно выработать совместно с ним план нашей атаки. А тем временем нужно замедлить их прогресс." } } } } },
    [483] = { d = 34.6, v = "nightelf-male#55", n = { x = 390 }, c = { x = { { 0.00, "Захватчиков Кривой Сосны видели в обители Бен'этиль на западе, они крушили там всё подряд." }, { 6.53, "Спящие друиды никогда не смогут выйти из Изумрудного Сна – они даже не понимают, в какую западню угодили, – если мы только им не поможем." }, { 15.65, "Тонкий ритуал спячки нельзя нарушить без реликвий Пробуждения." }, { 20.23, "Отправляйся в обитель и найди талисман Когтя Ворона, Чёрное перо, Небесный сапфир и руну Размещения." }, { 28.29, "Друиды хранят их в священных ларцах. Принеси их мне, и я подготовлю ритуал пробуждения." } } }, t = { d = 4.9, g = 1, v = "nightelf-male#55", n = { m = 45, f = 45 }, c = { m = { { 0.00, "Тебе удалось это сделать, юный герой! Славно! И как раз вовремя." } }, f = { { 0.00, "Тебе удалось это сделать, юная героиня! Славно! И как раз вовремя." } } } } },
    [484] = { d = 30.2, g = 1, v = "human-male", n = { m = 338, f = 340 }, c = { m = { { 0.00, "Ты, наверное, слышал обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему миру!" }, { 8.61, "Уже встречался с Эйнаром? Он – один из охотников, приносящих мне шкуры." }, { 13.85, "В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков." }, { 20.98, "Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур. Молодые кроколиски обитают в водах прямо за городом." } }, f = { { 0.00, "Ты, наверное, слышала обо мне. Я Джеймс Халлоран, кожевник. Выделанные мною кроколисковые шкуры расходятся по всему миру!" }, { 8.79, "Уже встречалась с Эйнаром? Он – один из охотников, приносящих мне шкуры." }, { 14.11, "В последнее время у меня осталось мало мягких шкур, а их можно снять только с молодых кроколисков." }, { 21.24, "Учитывая обстоятельства, я готов заплатить высокую цену за стопку шкур. Молодые кроколиски обитают в водах прямо за городом." } } }, t = { d = 11.0, v = "human-male", n = { x = 122 }, c = { x = { { 0.00, "Отлично, превосходно! Прекрасные шкуры! Надо немедленно замочить их..." }, { 4.83, "но перед этим я хотел бы попросить тебя ещё об одной услуге. Думаю, ты справишься." } } } } },
    [486] = { d = 31.4, v = "nightelf-male#55", n = { x = 370 }, c = { x = { { 0.00, "Настало время спасти друидов-воронов. Если сейчас мы потерпим неудачу, их сон станет вечным." }, { 6.60, "Я подготовлю реликвии Пробуждения и совершу обряд." }, { 10.01, "Но чтобы у меня всё получилось, тварь, виновная в их злоключениях, должна быть уничтожена. Только тогда ритуал может быть выполнен." }, { 19.26, "Это Урсал Изверг разрушил дело наших братьев, и теперь он должен заплатить за свои злодеяния ради их освобождения." }, { 26.85, "Отправляйся в Лагерь у Кривой Сосны на юго-западе и убей его." } } }, t = { d = 17.7, g = 1, v = "nightelf-male#55", n = { m = 191, f = 192 }, c = { m = { { 0.00, "Ты проявил себя как весьма достойный и способный герой." }, { 3.65, "путник, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире." }, { 10.93, "Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия." } }, f = { { 0.00, "Ты проявила себя как весьма достойная и способная героиня." }, { 3.96, "путница, следующий путём чести столь же неустанно, как ты, обязательно обретёт великую славу в этом мире." }, { 11.41, "Да будут благосклонны к тебе лесные духи всюду, куда бы ни завели тебя твои странствия." } } } } },
    [487] = { d = 35.5, g = 1, v = "nightelf-female#51", n = { x = 405 }, c = { m = { { 0.00, "Дорогу в Дарнасс нужно охранять. Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны." }, { 12.08, "Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения." }, { 17.08, "Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам." }, { 22.73, "Возьмись же за оружие во имя священного леса, герой. Их логово находится где-то под этим наблюдательным пунктом." }, { 30.52, "Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне." } }, f = { { 0.00, "Дорогу в Дарнасс нужно охранять. Путники, направляющиеся из Доланаара в Дарнасс, рассказывают о варварских нападениях поражённых порчей фурболгов из племени Кривой Сосны." }, { 12.08, "Каждый день из Дарнасса и в Дарнасс поступают грузы и важные сообщения." }, { 17.08, "Мы не можем допустить, чтобы шайка этих мерзостных тварей угрожала путникам." }, { 22.73, "Возьмись же за оружие во имя священного леса, героиня. Их логово находится где-то под этим наблюдательным пунктом." }, { 30.69, "Убей шесть душителей из племени Кривой Сосны и возвращайся ко мне." } } }, t = { d = 10.0, g = 1, v = "nightelf-female#51", n = { m = 99, f = 100 }, c = { m = { { 0.00, "Ты славно послужил доброму народу Доланаара и Дарнаса, отважный герой. От имени всех часовых Тельдрассила воздаю тебе хвалу." } }, f = { { 0.00, "Ты славно послужила доброму народу Доланаара и Дарнаса, отважная героиня. От имени всех часовых Тельдрассила воздаю тебе хвалу." } } } } },
    [488] = { d = 32.0, g = 1, v = "human-male", n = { m = 334, f = 337 }, c = { m = { { 0.00, "Вижу, ты работёнку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивному юнцу... вроде тебя." }, { 9.19, "Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесёшь." }, { 17.32, "Мне часто бывают нужны определённые... ингредиенты." }, { 20.88, "Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника." }, { 28.25, "И пусть это всё останется между нами, герой." } }, f = { { 0.00, "Вижу, ты работёнку ищешь? Хе-хе, ни дня не проходит без того, чтобы я не поручил какое-нибудь дельце наивной девчушке... вроде тебя." }, { 9.43, "Видишь ли, я могу осчастливить тебя такими вещицами, что тебе и не снились. Но за это ты кое-что мне принесёшь." }, { 17.56, "Мне часто бывают нужны определённые... ингредиенты." }, { 21.12, "Принеси три клыка ночного саблезуба, три пера островной совы и три мотка паутины чащобного тенётника." }, { 28.49, "И пусть это всё останется между нами, героиня." } } }, t = { d = 16.6, g = 1, v = "human-male", n = { x = 172 }, c = { m = { { 0.00, "Ха-ха! Хорошая работёнка!" }, { 2.34, "Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать герой? Я даже мечтать об этом не мог!" }, { 9.79, "Но раз уж так вышло... Наш милый мир полон неожиданностей. Обманули дурака на четыре кулака!" } }, f = { { 0.00, "Ха-ха! Хорошая работёнка!" }, { 2.34, "Кто бы мог подумать, что на меня, Зенна Грязное Копыто, будет работать героиня? Я даже мечтать об этом не мог!" }, { 9.94, "Но раз уж так вышло... Наш милый мир полон неожиданностей. Обманули дурака на четыре кулака!" } } } } },
    [489] = { d = 34.5, g = 1, v = "nightelf-female#51", n = { m = 382, f = 384 }, c = { m = { { 0.00, "Совет Леса узнал, что ты помог Зенну Грязному Копыту! Этот сатир – враг леса!" }, { 5.87, "И ты, как герой, должен бы понимать, что оскверняешь лес, убивая созданий Природы!" }, { 11.83, "Ты должен искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу!" }, { 18.11, "Преподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зелёный дым." }, { 27.91, "Скорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое." } }, f = { { 0.00, "Совет Леса узнал, что ты помогла Зенну Грязному Копыту! Этот сатир – враг леса!" }, { 5.43, "И ты, как героиня, должна бы понимать, что оскверняешь лес, убивая созданий Природы!" }, { 11.50, "Ты должна искупить свою вину перед Советом, если хочешь оставаться другом Тельдрассилу!" }, { 17.85, "Преподай Грязному Копыту урок – и заслужишь прощение. Есть такие шишки Скверны – это семена, падающие с деревьев. Они испускают зелёный дым." }, { 27.65, "Скорми несколько штук Грязному Копыту. Он подумает, что ему предлагают что-то вкусненькое." } } }, t = { d = 4.4, v = "human-male", n = { x = 43 }, c = { x = { { 0.00, "Ну что ты за лапочка! Я знал, что ты мне ещё пригодишься!" } } } } },
    [490] = { d = 32.0, v = "nightelf-female", n = { x = 368 }, c = { x = { { 0.00, "По приказу часовых я назначаю награду за головы фурболгов из племени Кривой Сосны. Это враги леса." }, { 6.91, "Скверна лишила их рассудка, и теперь они угрожают нашему народу и лесным жителям." }, { 12.99, "Мы отблагодарим всякого, кто защитит Тельдрассил от этой напасти. Только принеси их клыки в качестве доказательства." }, { 21.33, "Больше всего фурболгов собралось в лощине Бен'этиль на западе от Доланаара и с южной стороны от дороги, а также в деревне Звёздного Ветра на востоке." } } } },
    [491] = { d = 32.5, v = "scourge-male", n = { x = 347 }, c = { x = { { 0.00, "Туле как-то рассказывал мне, что давным-давно он вместе с двумя товарищами создал магический жезл, сплетя его из трёх принадлежащих им ученических жезлов." }, { 11.22, "Он был символом их дружбы, и, хотя Тул презрел её, с жезлом он расстаться не мог и не желал отдавать его другим." }, { 19.55, "Поэтому он выкрал жезл и спрятал его в крепости Фенриса." }, { 24.26, "Здесь. Отнесите жезл Бетору Ледострелу, одному из прежних друзей Тула. Я уверен, он будет рад его получить." } } }, t = { d = 31.5, v = "scourge-male#82", n = { x = 253 }, c = { x = { { 0.00, "... Что это?! У Туле был наш Сплетённый жезл? Я думал, он пропал, когда наша дружба пошла прахом, и Туле примкнул к Королю-личу!" }, { 12.53, "Должно быть, он не обращался к силе жезла, потому что если бы он сделал это, я бы почувствовал." }, { 21.24, "И хорошо, что Тул не использовал жезл..." }, { 25.09, "Это удивительная находка. Я признателен за неё, и вознагражу тебя." } } } } },
    [492] = { d = 33.6, v = "scourge-male#82", n = { x = 296 }, c = { x = { { 0.00, "Страж смерти сообщил, что недавно был захвачен ещё один дворф-горный пехотинец." }, { 7.32, "Стражи смерти обычно сажают пленных в погреб таверны \"Петля Висельника\", где им оказывается \"достойный приём\"." }, { 17.56, "Почему бы вам не пойти и не угостить пленника специальным напитком, который я приготовил?" }, { 25.87, "В нём есть небольшая примесь того, что Тёмная Госпожа готовит для всего Азерота." } } }, t = { d = 6.4, v = "dwarf-male", n = { x = 68 }, c = { x = { { 0.00, "Ах, наконец-то питьё! Хоть это и не \"Болтливое пиво\", но я рад хоть чем-то промочить горло." } } } } },
    [493] = { d = 50.7, v = "scourge-male#82", n = { x = 462 }, c = { x = { { 0.00, "Тёмная Госпожа давит на Королевское фармацевтическое общество, чтобы оно поскорее разработало Новую чуму." }, { 9.70, "Мы упорно трудимся и добились значительного прогресса." }, { 14.85, "Мы уверены, что успех был бы достигнут значительно быстрее, если бы мы могли распространять информацию среди членов общества." }, { 26.54, "Поэтому я хотел бы, чтобы вы доставили мои последние находки аптекарю Лидону в Мельницу Таррен – небольшой городок, расположенный в предгорьях Хилсбрада. Путь туда неблизкий." }, { 42.38, "Направляйтесь на юг и держитесь поближе к дорогам. Строго следуйте дорожным указателям!" } } }, t = { d = 8.1, v = "scourge-male", n = { x = 88 }, c = { x = { { 0.00, "А, отлично. Я в высшей степени уважаю аптекаря Ренферрела. Сгораю от нетерпения начать изучение его работы." } } } } },
    [494] = { d = 37.1, g = 1, v = "scourge-female", n = { x = 326 }, c = { m = { { 0.00, "Молчи и слушай, герой." }, { 2.57, "Меня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия." }, { 10.72, "А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен." }, { 18.37, "Скажи, что страж смерти Леш передала следующие слова: \"Крик ворона на западе манит.\"" }, { 26.22, "Ступай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной скоростью!" } }, f = { { 0.00, "Молчи и слушай, героиня." }, { 2.73, "Меня направили сюда для наблюдением за городом Хилсбрадом. У меня разведывательная миссия." }, { 10.88, "А тебе необходимо срочно отнести вести верховному палачу Дарталии в Мельницу Таррен." }, { 18.53, "Скажи, что страж смерти Леш передала следующие слова: \"Крик ворона на западе манит.\"" }, { 26.38, "Ступай по дороге на восток и обращай внимание на знаки. Торопись! Ступай в Мельницу Таррен со всей возможной скоростью!" } } }, t = { d = 14.7, v = "scourge-female", n = { x = 120 }, c = { x = { { 0.00, "Крик ворона на западе манит?" }, { 3.05, "Отличные новости! Пора напасть на Хилсбрад. Мы сможем воплотить наш план уничтожения жизни. Вариматас будет доволен." } } } } },
    [496] = { d = 36.7, v = "scourge-male", n = { x = 391 }, c = { x = { { 0.00, "Ах, ещё один мерзкий день на мельнице Таррен. От этого чистого воздуха у меня сразу портится настроение." }, { 8.16, "Чем скорее мы заразим здешних людей, тем лучше." }, { 11.79, "Я провожу исследования различных смертоносных веществ, чтобы использовать их в моих составах, но собрать все времени не хватило." }, { 21.72, "Если ты хочешь принести пользу, добудь для меня следующее: десять языков серых медведей и очень редкую и труднодоступную лимфу паука-охотника." }, { 32.02, "Медведи и пауки-охотники живут рядом с мельницей Таррен." } } }, t = { d = 9.7, g = 1, v = "scourge-male", n = { m = 87, f = 88 }, c = { m = { { 0.00, "Отличные компоненты. Что ж, ты умудрился внести хоть немного радости в мой тоскливый день. Благодарю тебя." } }, f = { { 0.00, "Отличные компоненты. Что ж, ты умудрилась внести хоть немного радости в мой тоскливый день. Благодарю тебя." } } } } },
    [498] = { d = 32.9, v = "orc-male#60", n = { x = 359 }, c = { x = { { 0.00, "Вождь послал нас с ребятами, чтобы добыть кое-что из Дарнхольда и разведать, что представляет собой так называемый Синдикат." }, { 9.13, "Мы пошли к Дарнхольду, поглядели, что к чему, тут на нас и напал большой отряд людей." }, { 14.91, "Мы бились изо всех сил, но они сильно превосходили нас числом." }, { 19.42, "В конце концов нескольких из нас взяли в плен, но мне удалось сбежать." }, { 24.63, "Дарнхольд находится на юго-востоке отсюда, по ту сторону реки. Там держат Друлла и Тог'тара, освободи их." } } }, t = { d = 21.3, v = "orc-male#60", n = { x = 232 }, c = { x = { { 0.00, "Значит, люди собирались поработить наших воинов? Мы ещё им покажем!" }, { 5.19, "Похоже, они захватили Гол'дира, нашего вождя, и держат его в другом месте. Его тоже необходимо отыскать и спасти. Впрочем, пока неизвестно, где он…" }, { 15.65, "Когда у нас появится хоть какая-то зацепка, я немедленно скажу об этом тебе." } } } } },
    [499] = { d = 26.9, v = "scourge-male", n = { x = 280 }, c = { x = { { 0.00, "Мне понадобится совсем немного времени для создания того, что я хочу наречь эликсиром Страдания." }, { 7.54, "Вот, готово! Ах, ничто не доставляет столько радости в этих проклятых холмах, как принесение страдания в мир." }, { 15.80, "Посмотрим, достигнут ли желанный эффект." }, { 19.61, "Дай попробовать моему помощнику Ампи то, что Тёмная Госпожа готовит людям и созданиям Плети." } } }, t = { d = 1.0, v = "human-male#114", n = { x = 4 }, c = { x = { { 0.00, "Квак!" } } } } },
    [501] = { d = 33.0, v = "scourge-male", n = { x = 350 }, c = { x = { { 0.00, "О... Луга Хилсбрада полны цветов, воздух свеж и приятен. Меня от этого просто тошнит!" }, { 6.29, "Я смотрю в мутное окно и мечтаю о наступлении дня, когда Новая чума принесёт в мир заслуженную смерть!" }, { 14.30, "Но как бы мне ни хотелось сидеть и мечтать – прежде всего приказы Тёмной Госпожи. Помоги мне!" }, { 21.32, "В результате исследований я обнаружил, что из крови горного льва можно создать великолепный напиток смерти." }, { 29.37, "Принеси мне немного крови, и мы повеселимся." } } }, t = { d = 1.7, v = "scourge-male", n = { x = 14 }, c = { x = { { 0.00, "Отличная работа." } } } } },
    [502] = { d = 30.8, v = "scourge-male", n = { x = 317 }, c = { x = { { 0.00, "Ах, ничто так не радует, как запах свежей крови в предгорьях!" }, { 4.92, "Смешаем капелюшку этого и щепотку того, и пойдёт веселье! Из этой крови я сделаю эликсир Боли." }, { 12.55, "Если мои вычисления верны, то этот состав порадует леди Сильвану. Надо его испытать." }, { 19.27, "Отнеси этот эликсир на самую северную ферму Хилсбрадских полей, что на юго-западе." }, { 25.45, "Посмотрим, как моё \"угощение\" понравится собачке фермера Рея, Стэнли." } } }, t = { d = 5.2, v = "human-male#114", n = { x = 54 }, c = { x = { { 0.00, "Вы наливаете немного эликсира в ладонь и протягиваете её Стэнли." } } } } },
    [509] = { d = 36.0, v = "scourge-male", n = { x = 357 }, c = { x = { { 0.00, "Новый день, новый эликсир. Если бы я тут командовал, я бы позволил Плети и жалким людишкам сцепиться между собой." }, { 9.19, "Им и так нравится убивать друг друга." }, { 12.39, "Увы, Тёмная Госпожа хочет ускорить процесс, так почему бы не скрасить унылые дни распространением смерти и болезней по стране." }, { 22.21, "Вот мой план: иди-ка ты во Владение Нетандера на юге от мельницы Таррен и на востоке от реки и Южнобережья." }, { 31.04, "Принеси мне шесть цветков Грязного Рыла для нового эликсира." } } }, t = { d = 7.0, v = "scourge-male", n = { x = 74 }, c = { x = { { 0.00, "А, отвратительная вонь цветков Грязного Рыла. Хоть для чего-то эти грязные гноллы годятся." } } } } },
    [513] = { d = 30.3, g = 1, v = "scourge-male", n = { m = 319, f = 321 }, c = { m = { { 0.00, "Я уже решил, что ещё один день пройдёт без капли радости, но тут ты принёс мне цветки Грязного Рыла." }, { 7.88, "Для начала я смешаю их и сделаю отличный состав. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода." }, { 16.81, "Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнётся!" }, { 23.20, "Вот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу." } }, f = { { 0.00, "Я уже решил, что ещё один день пройдёт без капли радости, но тут ты принесла мне цветки Грязного Рыла." }, { 7.96, "Для начала я смешаю их и сделаю отличный состав. Потом нам понадобится помощь мастера-аптекаря Фаранелла из Подгорода." }, { 16.89, "Он должен добавить туда коллоид разложения и тогда-то самое веселье и начнётся!" }, { 23.28, "Вот возьми этот состав Грязного Рыла и немедленно отнеси его мастеру-аптекарю Фаранеллу." } } }, t = { d = 25.0, g = 1, v = "scourge-male", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Тебя послал аптекарь Лидон? Что ж ты сразу не сказал!" }, { 4.38, "Невзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников." }, { 11.76, "Он прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли." }, { 20.71, "Тёмная Госпожа порадуется наступлению новой чумы." } }, f = { { 0.00, "Тебя послал аптекарь Лидон? Что ж ты сразу не сказала!" }, { 4.49, "Невзирая на угрюмый нрав, аптекарь Лидон – один из наших самых преданных и умелых сотрудников." }, { 11.87, "Он прислал состав Грязного Рыла, какой умница! Я знаю, что замышляет наш друг из Хилсбрада. И мне нравится ход его мысли." }, { 20.82, "Тёмная Госпожа порадуется наступлению новой чумы." } } } } },
    [515] = { d = 36.0, v = "scourge-male", n = { x = 374 }, c = { x = { { 0.00, "Состав Грязного Рыла? Гениально! Почему мне не пришло это в голову?" }, { 5.41, "Пожалуй, я добавлю свой коллоид разложения в эту хитрую смесь." }, { 10.43, "Чтобы активировать отраву в смеси, Лидону понадобится крепкое зелье тролльей крови, немного чешуи наги из клана Пронзающего Гребня и глаза мурлоков из клана Рваный Плавник с южного берега Хилсбрада." }, { 26.34, "Когда ты принесёшь ему все составляющие, он мигом всё сделает. Ох, как мне не терпится узнать о результатах его эксперимента!" } } }, t = { d = 10.8, v = "scourge-male", n = { x = 112 }, c = { x = { { 0.00, "У меня даже голова закружилась от возбуждения! Какой эксперимент! Ты мне очень помог." }, { 6.45, "Мы будем сеять болезнь и смерть по всем этим землям!" } } } } },
    [516] = { d = 39.4, v = "scourge-male", n = { x = 423 }, c = { x = { { 0.00, "Я получил сообщение, что группа нежити спряталась и готовит атаку против нас." }, { 5.66, "Вооружённые этой информацией, мы можем повернуть всё другой стороной и напасть первыми, подавив их планы в самом зародыше." }, { 15.16, "К сожалению, моя информация весьма обрывочная. Говорят, они скрываются в месте, называемом Погибель Берена." }, { 22.98, "Точное местонахождение неизвестно, но, похоже, это пещера где-то в холмах, недалеко от участка, занятого даларанскими волшебниками." }, { 33.77, "Я доверяю вашей изобретательности. Отыщите их и нанесите им поражение." } } }, t = { d = 12.8, v = "scourge-male", n = { x = 129 }, c = { x = { { 0.00, "Если наши разведчики и агенты продолжат предоставлять столь же ценную информацию, как эта, мы в мгновение ока очистим наши земли от армии Плети Короля-лича." } } } } },
    [517] = { d = 26.6, v = "scourge-male", n = { x = 274 }, c = { x = { { 0.00, "Пришло время испытать новый эликсир. Но зачем же тратить хорошую, очень заразную болезнь на простых лягушек и собак?" }, { 8.70, "Давай устроим настоящее веселье во имя леди Сильваны." }, { 13.21, "Ступай в Дун Гарок. Знаешь, это казармы, где вечно шныряют эти дворфики. Укради у них бочонок землекопского крепкого." }, { 22.74, "Получив эту бочку, я устрою весёлую вечеринку!" } } }, t = { d = 4.0, v = "scourge-male", n = { x = 34 }, c = { x = { { 0.00, "Наконец-то! Теперь мы готовы действовать!" } } } } },
    [524] = { d = 31.9, v = "scourge-male", n = { x = 341 }, c = { x = { { 0.00, "За соседней дверью стражи смерти держат нескольких заложников-фермеров." }, { 5.47, "Верховный палач Дарталия подозревает, что среди них скрывается один из военных-стратегов." }, { 12.25, "Очевидно, его нашли мёртвым в Чумных землях. Дарталия всегда заботится обо мне и решила передать пленников мне в руки." }, { 21.48, "Пора устроить этим фермерам вечеринку. Ох, повеселимся!" }, { 26.02, "Поставь гниющий бочонок на ковёр у них в комнате. Чумной напиток для всех!" } } }, t = { d = 3.7, v = "scourge-male", n = { x = 37 }, c = { x = { { 0.00, "Вы ставите гниющий бочонок на пыльный ковёр." } } } } },
    [526] = { d = 12.6, g = 1, v = "dwarf-male", n = { m = 143, f = 143 }, c = { m = { { 0.00, "Ты нашёл только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее." }, { 6.69, "Вернись и поищи ещё слитки. Думается, их растащили мурлоки, разграбившие корабль." } }, f = { { 0.00, "Ты нашла только один слиток светлостали – этого не хватит, чтобы выковать что-нибудь стоящее." }, { 6.60, "Вернись и поищи ещё слитки. Думается, их растащили мурлоки, разграбившие корабль." } } }, t = { d = 5.2, g = 1, v = "dwarf-male", n = { m = 57, f = 57 }, c = { m = { { 0.00, "А, ты нашёл их! Теперь давай эту светосталь скуем в что-нибудь полезное?" } }, f = { { 0.00, "А, ты нашла их! Теперь давай эту светосталь скуем в что-нибудь полезное?" } } } } },
    [527] = { d = 43.1, g = 1, v = "scourge-female", n = { x = 350 }, c = { m = { { 0.00, "Когда говоришь со мной, стой по стойке \"смирно\", герой." }, { 5.18, "Я нахожусь под прямым командованием Вариматраса." }, { 9.63, "Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы." }, { 18.68, "По нашим сведениям город Хилсбрад очень уязвим. Твоё первое задание – прервать снабжение едой и прочим." }, { 28.32, "Отправляйся на запад. Устрой налёт на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца." } }, f = { { 0.00, "Когда говоришь со мной, стой по стойке \"смирно\", героиня." }, { 5.26, "Я нахожусь под прямым командованием Вариматраса." }, { 9.72, "Наша задача – сдерживать распространение людей, покуда аптекари работают над составом новой чумы." }, { 18.76, "По нашим сведениям город Хилсбрад очень уязвим. Твоё первое задание – прервать снабжение едой и прочим." }, { 28.40, "Отправляйся на запад. Устрой налёт на самые северные фермы Хилсбрадских полей. И казни землевладельцев, фермеров Рея и Гетца." } } }, t = { d = 10.4, g = 1, v = "scourge-female", n = { m = 68, f = 70 }, c = { m = { { 0.00, "Вольно, герой. Вижу, ты вернулся из боя. Мне доложили, что ты хорошо показал себя в Хилсбраде." } }, f = { { 0.00, "Вольно, героиня. Вижу, ты вернулась из боя. Мне доложили, что ты хорошо показала себя в Хилсбраде." } } } } },
    [528] = { d = 34.9, g = 1, v = "scourge-female", n = { m = 303, f = 303 }, c = { m = { { 0.00, "Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно." }, { 7.84, "Наши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели." }, { 19.87, "Покажи им, как они заблуждаются. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян." }, { 29.36, "Рази их направо и налево во имя Тёмной Госпожи. Свободен!" } }, f = { { 0.00, "Слухи о нападении на северные фермы вызвали панику среди населения. Великолепно." }, { 7.84, "Наши стражи смерти докладывают о крестьянах южного Хилсбрада, бегущих в поля. Эти глупцы надеются укрыться в садах, избежав гибели." }, { 19.85, "Покажи им, как они заблуждаются. Возвращайся в Хилсбрадские поля и отыщи там трусливых крестьян." }, { 29.34, "Рази их направо и налево во имя Тёмной Госпожи. Свободна!" } } }, t = { d = 7.5, v = "scourge-female", n = { x = 66 }, c = { x = { { 0.00, "Смерть всё крепче сжимает костлявую руку на горле Хилсбрада. Битва идёт хорошо." } } } } },
    [529] = { d = 28.2, v = "scourge-female", n = { x = 260 }, c = { x = { { 0.00, "Люди Хилсбрада оказывают нам неожиданное сопротивление. Кажется, проблема в кузнеце, снабжающем горожан оружием. Необходимо прервать цепь снабжения." }, { 13.53, "Убей кузнеца Верринтана вместе с учениками и возвращайся с партией железа." }, { 20.41, "Нам оно пригодится, когда мы одержим победу над Хилсбрадом и нападём на Южнобережье." } } }, t = { d = 6.6, g = 1, v = "scourge-female", n = { x = 44 }, c = { m = { { 0.00, "Задание выполнено, герой. И, надо сказать, выполнено на славу." } }, f = { { 0.00, "Задание выполнено, героиня. И, надо сказать, выполнено на славу." } } } } },
    [530] = { d = 24.8, v = "scourge-male", n = { x = 251 }, c = { x = { { 0.00, "Когда-то Валдред был моим лучшим другом, а потом убил мою жену. Горевать я уже не способен, но до сих пор жажду мести." }, { 8.71, "Если ты убьёшь Валдреда и принесёшь мне его проклятые руки, я тебя награжу." }, { 14.76, "По последним слухам, он был у Стены Седогрива в южном Серебряном бору. Небось, пытается сбежать в королевство Гильнеас." } } }, t = { d = 23.4, v = "scourge-male", n = { x = 216 }, c = { x = { { 0.00, "А, хорошо. Этими руками была убита моя жена, Делия. С тех пор я думал только о мести, и вот ты стал моим оружием." }, { 10.92, "Возьми кольцо, которое вернул мне ранее. Делия так давно умерла, что я не нуждаюсь в этой безделушке." }, { 18.42, "Лучше я оставлю себе эти руки в память о предательстве друга." } } } } },
    [531] = { d = 13.1, v = "human-male", n = { x = 136 }, c = { x = { { 0.00, "Ради всего святого! Не приноси в Приют такое... это негигиенично, неприлично, не... не... негигиенично!" }, { 7.78, "Скорее убери её отсюда! Никому здесь не нужны твои страхолюдные трофеи!" } } }, t = { d = 13.3, g = 1, v = "bloodelf-female", n = { m = 150, f = 153 }, c = { m = { { 0.00, "Спасибо, что помог мне выполнить мой маленький план." }, { 3.57, "Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужил." } }, f = { { 0.00, "Спасибо, что помогла мне выполнить мой маленький план." }, { 3.81, "Я много месяцев жаждала проучить этого надутого самовлюблённого мальчишку, а теперь нам это удалось! Вот, возьми, ты это заслужила." } } } } },
    [532] = { d = 44.4, v = "scourge-female", n = { x = 369 }, c = { x = { { 0.00, "В Хилсбраде царит паника. Думаю, он скоро падёт." }, { 4.49, "Но мы не должны ослаблять натиск, пока последние человеческие отродья не изжиты из этих холмов навеки." }, { 14.07, "Невзирая на колоссальные потери, люди держатся вокруг своих вождей и не кладут оружия." }, { 21.85, "Мы должны уничтожить их главу, чиновника Бернсайда, и весь городской совет." }, { 28.73, "Заодно уничтожь и их главный документ, Хилсбрадское официальное объявление." }, { 37.63, "И раз уж на то пошло, укради и городскую книгу регистрации." } } }, t = { d = 7.4, g = 1, v = "scourge-female", n = { x = 58 }, c = { m = { { 0.00, "Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, герой." } }, f = { { 0.00, "Вести о твоих победах в Хилсбраде быстро разносятся. Отличная работа, героиня." } } } } },
    [536] = { d = 27.0, v = "human-male#50", n = { x = 300 }, c = { x = { { 0.00, "Меня перевели в Южнобережье из городской стражи Штормграда. Непонятно, как тут вообще люди живут..." }, { 6.43, "А как воняет со стороны пристани и днём и ночью!" }, { 10.13, "Да ещё старый Редпат на мою голову... Он хочет, чтобы я занялся мурлоками. Ха!" }, { 16.11, "Я едва могу заставить себя подойти к этим рыбам-переросткам на Западном побережье." }, { 22.22, "Если ты разберёшься с ними вместо меня, я буду очень признателен." } } }, t = { d = 13.4, v = "human-male#50", n = { x = 157 }, c = { x = { { 0.00, "Надеюсь, этого хватит, чтобы убедить Крассена, что я – ха!" }, { 3.79, "– выполняю его приказы и избавляю Южнобережье от страшной и ужасной угрозы, жутких мурлоков!" }, { 10.07, "Нет ничего страшнее ярости рыбы-переростка!" } } } } },
    [538] = { d = 37.7, v = "human-male", n = { x = 433 }, c = { x = { { 0.00, "Доброго дня вам. Если вы не против долгого путешествия, то у меня для вас найдётся задание, которое поможет пополнить библиотеку Штормграда." }, { 9.96, "Вместе со старым королевством Альтерака во время войны погибла и огромнейшая библиотека." }, { 16.15, "Жаль, что город разрушен, но вдвойне жаль, что пропал бесценный кладезь знаний! Мы должны восстановить всё, что можем." }, { 24.66, "Южнобережье – ближайший к руинам Альтерака город. Отправляйтесь туда и поговорите с Хранителем мудрости Диббсом." }, { 33.03, "Он направит вас к руинам, может быть, там вы сумеете найти книги..." } } }, t = { d = 20.5, v = "human-male", c = { x = { { 0.00, "Да, конечно, я помню Милтона. Такой типичный книжный червь, будь он здоров..." }, { 5.54, "И он совершенно прав. Руины Альтерака по-прежнему полны драгоценных документов, которые находятся под угрозой исчезновения!" }, { 14.56, "Теперь-то в Альтераке обитают огры, а их совершенно не волнуют памятники культуры..." } } } } },
    [539] = { d = 40.7, v = "scourge-female", n = { x = 341 }, c = { x = { { 0.00, "Согласно регистрационной книге Хилсбрада, Лазуритовый рудник находится в руках Альянса." }, { 7.94, "Более того, львиную долю руды, идущей на вооружение Альянса, добывают именно там." }, { 15.67, "Хотя мы нанесли решительный удар по городу Хилсбраду, Альянс изо всех сил защищает свой рудник." }, { 24.68, "Рудник расположен на юге от Хилсбрада. Ступай туда и убей штейгера, человека по имени Бондс. Убей и его горняков. Альянс надолго запомнит этот урок." } } }, t = { d = 9.8, v = "scourge-female", n = { x = 87 }, c = { x = { { 0.00, "Тёмная Госпожа будет рада услышать, что у неё появился новый рудник, который поможет вооружить её бойцов." } } } } },
    [540] = { d = 31.2, v = "human-male", c = { x = { { 0.00, "Мерзкие огры поселились в руинах Альтерака, и мне дурно при мысли, что они делают с драгоценными книгами из библиотеки. Спаси всё, что можно!" }, { 10.14, "Ступай в руины Альтерака и поищи там манускрипты, украденные ограми. Собери всё, что сможешь и принеси мне." }, { 17.57, "Больше всего меня интересует одна книга – \"Рука Гри'лека\"." }, { 21.43, "В ней содержится древняя мудрость троллей, о которой я жажду узнать, а последняя копия этой книги находилась именно в руинах Альтерака." } } }, t = { d = 5.5, v = "human-male", c = { x = { { 0.00, "А, вот они! Великолепно! Я немедленно примусь за изучение \"Руки Гри'лека\"." } } } } },
    [541] = { d = 42.6, g = 1, v = "scourge-female", n = { x = 375 }, c = { m = { { 0.00, "Дворфы пришли на помощь людям? Проклятые мелкие твари!" }, { 5.35, "Что ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев." }, { 16.69, "Мы отлично знаем, где скрывается их цитадель в этих краях." }, { 22.38, "Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовётся Дун Гарок." }, { 32.58, "Последняя цель этой битвы – осадить Дун Гарок, герой. Глава дворфов, капитан Железная Гора, должен умереть." } }, f = { { 0.00, "Дворфы пришли на помощь людям? Проклятые мелкие твари!" }, { 5.35, "Что ж, испытаем силу так называемого Альянса. Посмотрим, решатся ли эти недорослики помогать людям, когда почувствуют наш гнев." }, { 16.69, "Мы отлично знаем, где скрывается их цитадель в этих краях." }, { 22.38, "Они построили свои казармы в юго-восточной части Хилсбрада, рядом со стеной Торадина. Это местечко зовётся Дун Гарок." }, { 32.58, "Последняя цель этой битвы – осадить Дун Гарок, героиня. Глава дворфов, капитан Железная Гора, должен умереть." } } }, t = { d = 5.3, v = "scourge-female", n = { x = 45 }, c = { x = { { 0.00, "Твои подвиги на поле битвы достойны высочайшей хвалы." } } } } },
    [546] = { d = 35.5, v = "scourge-male", n = { x = 351 }, c = { x = { { 0.00, "Я слышал, что Дарталия призвала тебя в строй, чтобы выступить против людей Хилсбрада. Как я завидую…" }, { 7.85, "Пока ты там развлекаешься – убиваешь людей, грабишь города, запугиваешь невинных – я торчу здесь, на страже мельницы Таррен." }, { 18.79, "Может, ты смилостивишься над старым стражем смерти?" }, { 22.71, "Видишь, я собираю коллекцию человеческих черепов, а тебе предстоит убить немало смертных." }, { 29.47, "Набери в ходе битвы тридцать черепов, принеси мне, и я тебе хорошо заплачу." } } }, t = { d = 5.8, v = "scourge-male", n = { x = 53 }, c = { x = { { 0.00, "Превосходные черепа! И какие красивые! Вот тебе обещанная плата!" } } } } },
    [547] = { d = 35.4, v = "scourge-male", n = { x = 353 }, c = { x = { { 0.00, "Верховный палач Дарталия послала меня наблюдать за Дун Гароком издалека. Я разбил лагерь подальше от дворфов." }, { 9.77, "Но пришло утро, мне нужно было вскипятить воду, и я пошёл за дровами." }, { 15.31, "Вернувшись, я обнаружил, что мои вещи пропали." }, { 19.14, "Очевидно, ко мне заглянули дворфийские разведчики из Дун Гарока и украли их. Мне нужен мой меч!" }, { 26.33, "Если ты сможешь вернуть его, я буду очень признателен. Там так много дворфов... будет нелегко понять, кто же из них вор." } } }, t = { d = 7.4, g = 1, v = "scourge-male", n = { m = 71, f = 71 }, c = { m = { { 0.00, "Ты нашёл его!" }, { 1.64, "Ах, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!" } }, f = { { 0.00, "Ты нашла его!" }, { 1.73, "Ах, как приятно чувствовать в руке знакомую рукоять. Премного благодарен!" } } } } },
    [549] = { d = 26.8, v = "human-male#114", n = { x = 289 }, c = { x = { { 0.00, "По приказу леди Сильваны все члены организации, именуемой Синдикат, приговариваются к смертной казни. Всех пленных казнят." }, { 9.34, "В настоящий момент организация собирает силы в руинах крепости Дарнхольд на юго-востоке от мельницы Таррен." }, { 17.89, "Всем, предоставившим доказательства своих подвигов верховному палачу Дарталии, будет дарована щедрая награда." } } }, t = { d = 8.1, g = 1, v = "scourge-female", n = { x = 65 }, c = { m = { { 0.00, "Великолепно, герой. Такими темпами мы мигом очистим эти земли от синдикатской швали." } }, f = { { 0.00, "Великолепно, героиня. Такими темпами мы мигом очистим эти земли от синдикатской швали." } } } } },
    [567] = { d = 46.2, v = "human-male#114", n = { x = 462 }, c = { x = { { 0.00, "Внимание: вооружены и очень опасны!" }, { 3.92, "Следующие люди из Хилсбрада объявлены вне закона, и верховный палач Дарталия предлагает награду за их головы:" }, { 12.76, "Клерк Гораций Белоконь. Разыскивается за убийство стража смерти Томма." }, { 18.68, "Горожанин Вилкс. Разыскивается за убийство аптекаря Эли." }, { 23.56, "Шахтёр Хакетт. Разыскивается за убийство стража смерти Фрая." }, { 28.71, "Фермерша Калаба. Разыскивается за нападение из засады на караван с припасами из Подгорода." }, { 36.07, "Все перечисленные преступники скрываются, и найти их нелегко. Награда будет выдана при предъявлении доказательств их смерти." } } }, t = { d = 4.4, g = 1, v = "scourge-female", n = { x = 29 }, c = { m = { { 0.00, "Да ты неплохой охотник за головами, герой." } }, f = { { 0.00, "Да ты неплохой охотник за головами, героиня." } } } } },
    [583] = { d = 29.5, g = 1, v = "dwarf-male", n = { x = 329 }, c = { m = { { 0.00, "Добро пожаловать в Тернистую долину!" }, { 2.96, "Быть может, ты не знаешь об этом, но этот дворф – единственный и неповторимый Хеминг Эрнестуэй, прославленный герой Альянса и великий охотник на крупную дичь." }, { 13.46, "Он не слишком жалует гостей, но на твою долю, кажется, выпало немало приключений, герой?" }, { 19.75, "Хеминг и сам многое повидал – может, вы с ним найдёте общий язык." }, { 24.46, "Ступай, поговори с ним. Вдруг он научит тебя охотничьим хитростям." } }, f = { { 0.00, "Добро пожаловать в Тернистую долину!" }, { 2.96, "Быть может, ты не знаешь об этом, но этот дворф – единственный и неповторимый Хеминг Эрнестуэй, прославленный герой Альянса и великий охотник на крупную дичь." }, { 13.46, "Он не слишком жалует гостей, но на твою долю, кажется, выпало немало приключений, героиня?" }, { 19.86, "Хеминг и сам многое повидал – может, вы с ним найдёте общий язык." }, { 24.56, "Ступай, поговори с ним. Вдруг он научит тебя охотничьим хитростям." } } }, t = { d = 30.3, g = 1, v = "dwarf-male", n = { x = 332 }, c = { m = { { 0.00, "Приятно познакомиться. Давно в наши края не забредал герой. Я здесь с одной-единственной целью – поймать крупного и хитрого зверя." }, { 8.82, "Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте? Впрочем, сначала покажи, на что способен." }, { 17.59, "Я научу тебя охотиться на ящеров. Ажек – на тигров. А сэр Эрлгедин – мастер выслеживать пантер." }, { 25.06, "Покажи нам своё искусство, и сможешь принять участие в большой охоте." } }, f = { { 0.00, "Приятно познакомиться. Давно в наши края не забредал героиня. Я здесь с одной-единственной целью – поймать крупного и хитрого зверя." }, { 9.04, "Раз ты, так сказать, личность героическая, может, захочешь принять участие в охоте? Впрочем, сначала покажи, на что способен." }, { 17.82, "Я научу тебя охотиться на ящеров. Ажек – на тигров. А сэр Эрлгедин – мастер выслеживать пантер." }, { 25.29, "Покажи нам своё искусство, и сможешь принять участие в большой охоте." } } } } },
    [590] = { d = 12.5, g = 1, v = "scourge-male#83", n = { m = 111, f = 111 }, c = { m = { { 0.00, "Что? ЧТО?!" }, { 1.28, "Денег хочешь? Не должен я тебе никаких денег." }, { 5.09, "Письмо? Какое письмо? Может, ещё и подерёмся? Ну, приятель, давай! Вот ещё, деньги я должен..." } }, f = { { 0.00, "Что? ЧТО?!" }, { 1.28, "Денег хочешь? Не должен я тебе никаких денег." }, { 5.09, "Письмо? Какое письмо? Может, ещё и подерёмся? Ну, подружка, давай! Вот ещё, деньги я должен..." } } }, t = { d = 16.4, g = 1, v = "scourge-male#83", n = { m = 163, f = 164 }, c = { m = { { 0.00, "Невероятно! Какое мастерство!" }, { 2.65, "А я-то думал, ты будешь лёгкой добычей. Да, хорошенько ты меня отделал." }, { 8.33, "Вот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать." } }, f = { { 0.00, "Невероятно! Какое мастерство!" }, { 2.65, "А я-то думал, ты будешь лёгкой добычей. Да, хорошенько ты меня отделала." }, { 8.41, "Вот обещанные деньги... правда, не столько, сколько я сказал сначала, но должен же я был немного приврать." } } } } },
    [637] = { d = 19.7, v = "human-male#114", n = { x = 210 }, c = { x = { { 0.00, "Промокший и потрёпанный конверт разваливается в руках, и в ладонях остаётся письмо на нескольких страницах." }, { 8.20, "Каждая буковка выведена с удивительной аккуратностью." }, { 12.58, "Письмо адресовано некой миссис Саре Баллу из Стальгорна. Оно начинается: \"Дорогая Сара...\"" } } }, t = { d = 8.1, g = 1, v = "dwarf-female#33", n = { m = 80, f = 81 }, c = { m = { { 0.00, "Неужели ты видел моего Салли подо льдом? Прошу, скажи, что это не так!" }, { 5.28, "Дай-ка я прочитаю, что он написал..." } }, f = { { 0.00, "Неужели ты видела моего Салли подо льдом? Прошу, скажи, что это не так!" }, { 5.33, "Дай-ка я прочитаю, что он написал..." } } } } },
    [647] = { d = 28.9, v = "dwarf-male", n = { x = 316 }, c = { x = { { 0.00, "Ох, и хлебнул я вчера самогона! Знай Длиннокос, что я отрубился на посту, он оторвал бы мне голову." }, { 7.13, "Башка раскалывается, жуть. И в ушах гремит, будто осадные орудия вокруг грохочут." }, { 13.03, "Ой-ой, а времени сколько! Я обещал мастеру-пивовару Бочкопузу из Южнобережья вернуть должок своим самогоном." }, { 20.86, "А осталось до истечения срока действия долга всего пятнадцать минут! Отнеси ему самогон, будь другом! И поскорее!" } } }, t = { d = 11.1, v = "dwarf-male", n = { x = 127 }, c = { x = { { 0.00, "Ах, ничто не греет так, как глоток самогона Туманника Маккрила! А я-то думал, что этот паразит опять просрочит платёж." }, { 7.98, "Спасибо, дружище! Огромное тебе спасибо!" } } } } },
    [683] = { d = 20.8, g = 1, v = "dwarf-female#33", n = { m = 233, f = 230 }, c = { m = { { 0.00, "У меня есть к вам маленькая просьба." }, { 2.85, "Возьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода." }, { 10.59, "Это небольшой труд для такого, как ты, славного героя." }, { 14.67, "Мне в моём горе сейчас трудно будет предстать перед королём. Ты понимаешь меня." } }, f = { { 0.00, "У меня есть к вам маленькая просьба." }, { 2.85, "Возьмите прошение, которое я написала на имя нашего великого государя стальгорнского, короля Магни Бронзоборода." }, { 10.59, "Это небольшой труд для такой, как ты, славной девы." }, { 15.06, "Мне в моём горе сейчас трудно будет предстать перед королём. Ты понимаешь меня." } } }, t = { d = 2.9, v = "dwarf-male#177", n = { x = 28 }, c = { x = { { 0.00, "Подожите минутку, я прочту письмо..." } } } } },
    [686] = { d = 37.3, g = 1, v = "dwarf-male#177", n = { x = 419 }, c = { m = { { 0.00, "Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа." }, { 9.10, "Гибель её мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе." }, { 16.81, "Мне не под силу вернуть её супруга из Круговерти Пустоты, но я могу хотя бы почтить его память." }, { 23.60, "Я намерен заказать главному каменотёсу Стальгорна Мраморщику памятник в честь Салли Баллу." }, { 31.13, "Отправляйтесь к нему сейчас же и передайте мои слова, герой. Вы будете моим вестником." } }, f = { { 0.00, "Вряд ли добрые дворфские вдовы вроде госпожи Баллу понимают, что нам приходится терпеть тяготы войны ради высшего блага нашего народа." }, { 9.10, "Гибель её мужа, как и гибель всех дворфов, что сражаются за дело Альянса, тяжким бременем лежит на моей душе." }, { 16.81, "Мне не под силу вернуть её супруга из Круговерти Пустоты, но я могу хотя бы почтить его память." }, { 23.60, "Я намерен заказать главному каменотёсу Стальгорна Мраморщику памятник в честь Салли Баллу." }, { 31.13, "Отправляйтесь к нему сейчас же и передайте мои слова, героиня. Вы будете моим вестником." } } }, t = { d = 7.0, v = "dwarf-male", n = { x = 75 }, c = { x = { { 0.00, "Значит, вас послал лично король Магни Бронзобород?" }, { 3.83, "Подумать только! Стало быть, дело важное!" } } } } },
    [729] = { d = 38.9, v = "dwarf-female#33", n = { x = 447 }, c = { x = { { 0.00, "Мне была оказана большая честь, когда мастер Седоус назначил меня работать под руководством великого геолога Сомнамбулера." }, { 8.51, "В академии в Стальгорне все знают о грандиозных открытиях Сомнамбулера." }, { 13.77, "Но геолог довольно... ммм... рассеян... порой кажется, что он не от мира сего." }, { 19.12, "Мы обнаружили признаки некогда крупного поселения. Из-под земли выскочили ужасные големы и заполонили весь раскоп." }, { 27.09, "Но Сомнамбулер, казалось, так ничего и не заметил. Я побежала обратно в Аубердин за помощью." }, { 33.79, "Прошу тебя, отправляйся на юг и посмотри, всё ли в порядке с геологом!" } } }, t = { d = 36.1, g = 1, v = "dwarf-male", n = { m = 372, f = 373 }, c = { m = { { 0.00, "Это ты, Холли? Мне нужна помощь, надо подолбить этот камень." }, { 4.11, "Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу." }, { 8.97, "Ой, да ты не Холли! Вряд ли ты видел мою щётку для камня..." }, { 13.60, "А, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл. Куда же делась Холли?" }, { 22.29, "Так много нужно сделать! И где ж эта таинственная окаменелость... и моя щётка... и Холли..." }, { 28.40, "И ты кто будешь... правда, это неважно, если ты хочешь помочь." }, { 33.00, "Дай знать, когда сможешь начать поиски." } }, f = { { 0.00, "Это ты, Холли? Мне нужна помощь, надо подолбить этот камень." }, { 4.11, "Передай-ка мне мою щётку для камня – мне кажется, я тут что-то вижу." }, { 8.97, "Ой, да ты не Холли! Вряд ли ты видела мою щётку для камня..." }, { 13.31, "А, забудь об этом! Я обещал Лиге, что отошлю им ту таинственную окаменелость, что я нашёл. Куда же делась Холли?" }, { 22.00, "Так много нужно сделать! И где ж эта таинственная окаменелость... и моя щётка... и Холли..." }, { 28.11, "И ты кто будешь... правда, это неважно, если ты хочешь помочь." }, { 32.71, "Дай знать, когда сможешь начать поиски." } } } } },
    [730] = { d = 33.6, g = 1, v = "dwarf-male", n = { m = 383, f = 383 }, c = { m = { { 0.00, "Приятно видеть! герой, интересующийся великими археологическими чудесами нашего мира!" }, { 6.24, "Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать." }, { 13.86, "Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора." }, { 20.10, "Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега. От них уже несколько недель ни слова." }, { 28.01, "Отправляйся в Аубердин и узнай, где они предположительно могут находиться." } }, f = { { 0.00, "Приятно видеть! героиня, интересующаяся великими археологическими чудесами нашего мира!" }, { 6.44, "Часто наши друзья из Альянса считают нашу работу чем-то вроде развлечения. Многие просто отказываются понимать." }, { 14.06, "Великая, могущественная сила угрожает всему Азероту – от Лордерона до Калимдора." }, { 20.30, "Меня очень беспокоит судьба группы, которую я отправил на Тёмные берега. От них уже несколько недель ни слова." }, { 28.21, "Отправляйся в Аубердин и узнай, где они предположительно могут находиться." } } }, t = { d = 4.4, v = "dwarf-female#33", n = { x = 47 }, c = { x = { { 0.00, "Как же здорово, что главный археолог Седой Ус прислал вас..." } } } } },
    [731] = { d = 32.1, g = 1, v = "dwarf-male", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Итак, Холли... А, да, верно, ты же не Холли. А где Холли?" }, { 4.65, "Ай, ладно, это к делу не относится. Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость!" }, { 12.90, "Мы должны найти эту окаменелость. Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь." }, { 20.13, "Дай мне знать, когда будешь готов, и начнём поиски этой щётки... ну, то есть окаменелости!" }, { 26.18, "Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны. Так что, готов?" } }, f = { { 0.00, "Итак, Холли... А, да, верно, ты же не Холли. А где Холли?" }, { 4.65, "Ай, ладно, это к делу не относится. Мы должны найти эту щётку для камня... то есть я имею в виду таинственную окаменелость!" }, { 12.90, "Мы должны найти эту окаменелость. Лига исследователей в Дарнассе захочет узнать, чем я тут занимаюсь." }, { 20.13, "Дай мне знать, когда будешь готова, и начнём поиски этой щётки... ну, то есть окаменелости!" }, { 26.35, "Мы найдём какой-нибудь документ, чтобы в Лиге остались довольны. Так что, готова?" } } }, t = { d = 13.2, v = "dwarf-female#33", n = { x = 146 }, c = { x = { { 0.00, "Слава звёздам, геолог Сомнамбулер в безопасности! Я же говорила тебе, какой он рассеянный." }, { 6.81, "Не могу поверить, что он твёрдо хочет остаться там, где рядом повсюду рыщут жуткие твари!" } } } } },
    [741] = { d = 15.9, v = "dwarf-female#33", n = { x = 188 }, c = { x = { { 0.00, "Так геолог хочет отослать эту таинственную окаменелость Лиге исследователей в Дарнасс?" }, { 5.93, "Мне не хотелось бы уезжать с Тёмных берегов без него." }, { 9.98, "Вот, отвезите эту таинственную окаменелость главному археологу Седоусу в Дарнасс." } } }, t = { d = 4.5, v = "dwarf-male", n = { x = 50 }, c = { x = { { 0.00, "Ух ты! Только геолог Сомнамбулер мог сделать такое открытие!" } } } } },
    [742] = { d = 37.5, v = "tauren-male", n = { x = 333 }, c = { x = { { 0.00, "Внимание, молодые герои! Вас ждут дикие чащи Ясеневого леса!" }, { 6.53, "Орде удалось закрепиться в землях к северу от Степей." }, { 10.68, "И два наших форпоста – застава Расщеплённого Древа и застава Зорамского взморья – бьются во славу Орды!" }, { 20.98, "Те, кто жаждет подвигов, могут отправиться туда." }, { 24.86, "Запомните: Сенани Громосерд находится на заставе Расщеплённого Древа, к северу от Степей." }, { 33.20, "Она ждёт желающих принять участие в большой охоте!" } } }, t = { d = 34.0, g = 1, v = "tauren-female", n = { x = 307 }, c = { m = { { 0.00, "Добро пожаловать на новое пограничье." }, { 2.96, "Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя." }, { 13.10, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 21.28, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 26.33, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } }, f = { { 0.00, "Добро пожаловать на новое пограничье." }, { 2.96, "Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя." }, { 13.49, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 21.66, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 26.72, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } } } } },
    [743] = { d = 31.0, g = 1, v = "tauren-male", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Спасибо, что выбрал время поговорить со мной. Я Руул, воин и учитель." }, { 6.33, "Пришло время пройти испытания и покинуть Мулгор." }, { 10.59, "Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке." }, { 19.05, "Они гнездятся вдоль гребня гор в стороне от дороги." }, { 23.57, "Эти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе." } }, f = { { 0.00, "Спасибо, что выбрала время поговорить со мной. Я Руул, воин и учитель." }, { 5.92, "Пришло время пройти испытания и покинуть Мулгор." }, { 10.18, "Если ты хочешь проверить свою силу, вызови на бой гарпий Неистовства Ветра, живущих на юго-востоке." }, { 18.64, "Они гнездятся вдоль гребня гор в стороне от дороги." }, { 23.16, "Эти гарпии – вечные враги тауренов Мулгора. По схватке с ними мы будем судить о твоей силе." } } }, t = { d = 5.4, g = 1, v = "tauren-male", n = { m = 53, f = 54 }, c = { m = { { 0.00, "Молодец. Похоже, ты готов двинуться дальше. Попутного тебе ветра!" } }, f = { { 0.00, "Молодец. Похоже, ты готова двинуться дальше. Попутного тебе ветра!" } } } } },
    [744] = { d = 40.0, v = "tauren-male#68", n = { x = 404 }, c = { x = { { 0.00, "Вскоре мой брат предстанет перед вождём Кровавым Копытом, и мне выпала большая честь сделать для него головной убор." }, { 9.30, "Мне хотелось бы попросить тебя об одолжении – надо сделать одно дело, пока я буду красить эти кожаные полоски." }, { 17.71, "Я просто не успею добыть достаточное количество перьев – так не поможешь ли ты мне в этом?" }, { 24.95, "Перья нужной величины можно найти у гарпий, что живут далеко на севере и северо-западе от Громового Утёса." }, { 33.18, "Мне нужно всего-то шесть лазурных и шесть бронзовых перьев, чтобы закончить работу." } } }, t = { d = 12.2, v = "tauren-male#68", n = { x = 120 }, c = { x = { { 0.00, "Спасибо за помощь." }, { 1.97, "Моё участие в церемонии в честь моего брата почти закончено. От меня требуется только подарить ему этот убор и быть свидетелем." } } } } },
    [745] = { d = 45.7, v = "tauren-male#67", n = { x = 381 }, c = { x = { { 0.00, "Нашей земле причиняют боль раздоры её обитателей. Я надеюсь, что тебе не суждено видеть столько войн, сколько выпало мне." }, { 11.72, "И всё же я вынужден просить тебя вступить в бой." }, { 16.18, "Благодаря этому ты поймёшь, что малая угроза, если не искоренить её, со временем разрастается." }, { 25.85, "Гноллы-бледногривы поселились на юге от нашей деревни и в пещере на западе." }, { 33.38, "Они не обращают внимания на наши попытки договориться и без жалости убивают животных Мулгора. Слова бессильны остановить их." } } }, t = { d = 23.3, v = "tauren-male#67", n = { x = 192 }, c = { x = { { 0.00, "Хорошо, что ты отнёсся к моему заданию со всей серьёзностью. Очень важно уважать землю и её обитателей." }, { 9.94, "Жизнь и смерть – это вечный цикл... Необходимость. Одно не может существовать без другого." }, { 18.57, "Обдумай это хорошенько и никогда не забывай." } } } } },
    [746] = { d = 35.2, v = "tauren-male#67", n = { x = 288 }, c = { x = { { 0.00, "К северо-западу отсюда дворфы готовятся к раскопкам." }, { 5.08, "Они думают, что тайны скрыты глубоко в земле, и это правда, но у неё надо учиться, а не осквернять бесконечными ямами." }, { 16.73, "Собери инструменты дворфов, уничтожь их и принеси мне." }, { 22.43, "Ломать инструменты можно в кузнице, которая есть в Громовом Утёсе, но подойдёт любая, даже та, что находится в дворфийском лагере." } } }, t = { d = 13.4, v = "tauren-male#67", n = { x = 108 }, c = { x = { { 0.00, "Спасибо. Звери Мулгора успокоятся. И, если будет на то воля духов, дворфы познают, что бурение земли – не лучший путь к обретению знаний." } } } } },
    [747] = { d = 46.0, g = 1, v = "tauren-male", n = { m = 471, f = 472 }, c = { m = { { 0.00, "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем." }, { 8.24, "Возможно, вскоре тебя позовут в Громовой Утёс." }, { 11.75, "Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достоин этой чести." }, { 21.09, "На плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы." }, { 31.93, "Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды." }, { 38.92, "Покажи, на что ты способен, – поохоться на равнинных долгоногов и принеси мяса в деревню." } }, f = { { 0.00, "Ты выглядишь весьма многообещающе, и тебе будет предоставлена возможность проявить себя перед племенем." }, { 8.24, "Возможно, вскоре тебя позовут в Громовой Утёс." }, { 11.75, "Но прежде чем это случится, тебе придётся доказать моему отцу, вождю Соколиному Ветру, что ты достойна этой чести." }, { 20.97, "На плато Красного Облака предметом особой гордости является охотничье мастерство. Таурены охотятся ради выживания и для забавы." }, { 31.81, "Сейчас в племени кончается запас мяса, кроме того, нам нужны перья для украшения одежды." }, { 38.80, "Покажи, на что ты способна, – поохоться на равнинных долгоногов и принеси мяса в деревню." } } }, t = { d = 5.8, v = "tauren-male", n = { x = 58 }, c = { x = { { 0.00, "Таурены Нараче благодарят тебя. Я уверен, ты достигнешь больших высот." } } } } },
    [748] = { d = 27.3, v = "tauren-male#68", n = { x = 276 }, c = { x = { { 0.00, "Гоблины и их прислужники отравили наши священные колодцы! Это недопустимо." }, { 6.65, "Для очищения колодцев придётся создать тотэмы, а ты пойдёшь с ними к колодцам и проведёшь очищающие ритуалы." }, { 15.47, "Начнём мы с колодца Заиндевевшего Копыта. Земля сама поможет нам. Принеси мне лапы койотов и когти взрослых долгоногов. Эти звери живут на юго-западе." } } }, t = { d = 5.3, v = "tauren-male#68", n = { x = 53 }, c = { x = { { 0.00, "Молодец. Я вплету силу принесённых тобой вещей в тотэм Очищения." } } } } },
    [749] = { d = 38.0, v = "tauren-male", n = { x = 391 }, c = { x = { { 0.00, "Несколько дней назад мы наткнулись на охраняемый караван Торговой компании, следовавший вдоль северного берега озера Каменного Быка." }, { 10.49, "В предыдущей битве мы потеряли двоих, поэтому на сей раз мы напали без промедления и уничтожили караван." }, { 19.09, "Мы бросили их ящики с припасами, полагая, что наши факелы уничтожат всё ценное, но учитывая, что возле сожжённых телег видели мародёров Торговой компании, похоже, мы ошиблись." }, { 32.97, "Быть может, ты сходишь к каравану и посмотришь, что в ящиках?" } } }, t = { d = 14.7, v = "tauren-male", n = { x = 155 }, c = { x = { { 0.00, "Все стороны ящика опечатаны знаками рудникового отдела Торговой Компании." }, { 5.92, "Сбоку прикреплены пометки, что содержимое должно быть обработано на одном из центральных заводов компании." } } } } },
    [750] = { d = 29.1, v = "tauren-male", n = { x = 294 }, c = { x = { { 0.00, "Любой искушённый в охоте таурен понимает, что её смысл не заключается в убийстве любой подвернувшейся добычи." }, { 9.29, "Живущие на равнине звери обеспечивают нас всем необходимым для выживания." }, { 15.06, "Ты произведёшь впечатление на старейшин, если принесёшь им несколько шкур горных пум – они у нас очень высоко ценятся!" }, { 24.65, "Нашим детям нужна одежда, да и шатры пора подлатать." } } }, t = { d = 10.0, v = "tauren-male", n = { x = 94 }, c = { x = { { 0.00, "Таурены из Нараче благодарят тебя за твои дары. Твоё охотничье искусство будет высоко цениться в Громовом Утёсе." } } } } },
    [751] = { d = 21.0, v = "human-male#114", n = { x = 225 }, c = { x = { { 0.00, "Приоткрыв крышку, вы видите плотно упакованную руду и минералы – новое свидетельство деятельности Торговой компании в Мулгоре." }, { 9.58, "Поверх руды и минералов лежит пачка бумаг." }, { 12.99, "Со стороны восточных предгорий доносятся звуки работы и к небу поднимается дым от больших костров." } } }, t = { d = 11.8, v = "tauren-male", n = { x = 123 }, c = { x = { { 0.00, "Похоже, Торговая Компания в самом деле замыслила лишить нас всех природных ресурсов." }, { 6.66, "Хорошо знать это наверняка, пожалуй, пришло время действовать." } } } } },
    [752] = { d = 30.8, v = "tauren-male#67", n = { x = 250 }, c = { x = { { 0.00, "Все члены племени живут вместе в мире и гармонии." }, { 5.07, "Мы преданы друг другу и отвечаем друг за друга. Я обращаюсь к тебе со скромной просьбой." }, { 14.02, "Моя матушка сегодня отправилась за водой к источнику к юго-востоку от Нараче. С тех пор прошло довольно много времени." }, { 25.24, "Не поищешь ли ты её, пока я занимаюсь делами племени?" } } }, t = { d = 17.9, g = 1, v = "tauren-female", n = { m = 165, f = 166 }, c = { m = { { 0.00, "Ты проделал такой путь, только чтобы оказать услугу старушке? Да, похоже, ты чтишь традиции нашего народа." }, { 8.58, "Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу." } }, f = { { 0.00, "Ты проделала такой путь, только чтобы оказать услугу старушке? Да, похоже, ты чтишь традиции нашего народа." }, { 9.57, "Вот, возьми себе одно из этих учебных пособий – из него ты узнаешь, как ещё можно помочь сообществу." } } } } },
    [753] = { d = 32.9, g = 1, v = "tauren-female", n = { m = 302, f = 302 }, c = { m = { { 0.00, "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше." }, { 7.06, "Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени." }, { 14.82, "Думаю, ты достойный герой. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче." }, { 24.69, "Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин." } }, f = { { 0.00, "В своей жизни я прошла немало дорог, и мои старые ноги уже не так быстры, как раньше." }, { 7.06, "Я ещё могу принести пользу своему племени – просто иногда мне требуется чуть больше времени." }, { 14.82, "Думаю, ты достойная героиня. Набери-ка кувшин воды из колодца и отнеси его моему сыну, вождю Лагеря Нараче." }, { 24.82, "Помни, иногда выполнение даже самых скромных просьб может помочь заслужить уважение старейшин." } } }, t = { d = 25.4, g = 1, v = "tauren-male#67", n = { m = 212, f = 214 }, c = { m = { { 0.00, "Ты принёс мне этот кувшин по просьбе Великой матери Соколиный Ветер." }, { 7.17, "Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе." } }, f = { { 0.00, "Ты принесла мне этот кувшин по просьбе Великой матери Соколиный Ветер." }, { 7.26, "Твоя готовность помочь другим и желание обеспечить тауренов Лагеря Нараче всем необходимым вселяет в меня уверенность, что придёт день, когда мы будем гордиться тобой в Громовом Утёсе." } } } } },
    [754] = { d = 21.6, v = "tauren-male#68", n = { x = 215 }, c = { x = { { 0.00, "Я создал тотэм для очищения колодца Заиндевевшего Копыта. Отнеси его туда и произведи ритуал очищения." }, { 7.89, "Колодец находится на юго-востоке, и его охраняют мерзкие гоблины!" }, { 13.21, "Дело непростое, но кому-то придётся его сделать, иначе мы не сможем брать там воду. Удачи тебе." } } }, t = { d = 12.2, g = 1, v = "tauren-male#68", n = { m = 119, f = 120 }, c = { m = { { 0.00, "До меня только что дошли вести о твоём деянии – звери уже спешат к колодцу на водопой." }, { 6.86, "Ты оказал большую услугу нашему краю. И всему народу тауренов." } }, f = { { 0.00, "До меня только что дошли вести о твоём деянии – звери уже спешат к колодцу на водопой." }, { 6.86, "Ты оказала большую услугу нашему краю. И всему народу тауренов." } } } } },
    [755] = { d = 43.4, g = 1, v = "tauren-male#67", n = { m = 343, f = 343 }, c = { m = { { 0.00, "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны." }, { 12.37, "Не сомневаюсь, придёт день, и тебя, герой, назовут одним из величайших." }, { 19.43, "Но сначала ты должен пройти три обряда Матери-Земли." }, { 24.87, "Первым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер." }, { 37.16, "Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче." } }, f = { { 0.00, "Твоя готовность выполнить скромную просьбу таурена из Нараче и твоё желание обрести новые знания весьма похвальны." }, { 12.37, "Не сомневаюсь, придёт день, и тебя, героиня, назовут одной из величайших." }, { 19.64, "Но сначала ты должна пройти три обряда Матери-Земли." }, { 25.00, "Первым испытанием будет Обряд Силы. Отправляйся к провидцу Серой Пасти и скажи ему, что тебя прислал вождь Соколиный Ветер." }, { 37.39, "Обиталище провидца сокрыто в холмах к югу от Лагеря Нараче." } } }, t = { d = 8.2, v = "tauren-male#68", n = { x = 85 }, c = { x = { { 0.00, "Тебя прислал вождь Соколиный Ветер? Обряды Матери-Земли гораздо сложнее, чем кажутся на первый взгляд..." } } } } },
    [756] = { d = 18.8, v = "tauren-male#68", n = { x = 195 }, c = { x = { { 0.00, "Для создания Тотэма очищения колодца Громового Рога тебе понадобятся когти хищников мулгорских равнин." }, { 8.02, "Придётся тебе убить несколько охотников прерий и пум плоскогорья и принести мне их когти." }, { 15.34, "Живут эти звери на востоке и на западе." } } }, t = { d = 18.3, v = "tauren-male#68", n = { x = 192 }, c = { x = { { 0.00, "Спасибо. Чтобы создать следующий очищающий тотэм, тебе придётся постичь, в чём разница между убийством ради пропитания и бессмысленной жестокостью." }, { 11.61, "Гоблинам же не дано понять разницу между захватом земли и жизнью в гармонии с ней." } } } } },
    [757] = { d = 38.5, g = 1, v = "tauren-male#68", n = { m = 396, f = 396 }, c = { m = { { 0.00, "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса." }, { 8.39, "Сначала ты должен пройти обряд Силы. Чтобы выдержать это испытание, ты должен доказать свою храбрость, убивая врагов племени." }, { 18.53, "Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени." }, { 25.19, "Они нападают на наших охотников и грабят деревню по ночам." }, { 30.21, "Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства." } }, f = { { 0.00, "Обряды Матери-Земли проходит каждый юный таурен, чтобы заслужить уважение старейшин Громового Утёса." }, { 8.39, "Сначала ты должна пройти обряд Силы. Чтобы выдержать это испытание, ты должна доказать свою храбрость, убивая врагов племени." }, { 18.52, "Воины клана Вздыбленная Щетина из Ежевичной лощины вторгаются в земли нашего племени." }, { 25.18, "Они нападают на наших охотников и грабят деревню по ночам." }, { 30.20, "Покажи свою доблесть, убив негодяев, и принеси вождю Лагеря Нараче их пояса в качестве доказательства." } } }, t = { d = 6.7, g = 1, v = "tauren-male#67", n = { m = 52, f = 52 }, c = { m = { { 0.00, "Ты прошёл первый из обрядов Матери-Земли. Племя гордится тобой!" } }, f = { { 0.00, "Ты прошла первый из обрядов Матери-Земли. Племя гордится тобой!" } } } } },
    [758] = { d = 17.1, v = "tauren-male#68", n = { x = 175 }, c = { x = { { 0.00, "Тотэм готов. Тебе остаётся лишь провести ритуал очищения." }, { 4.86, "Ступай к колодцу Громового Рога на севере от деревни и проведи ритуал с помощью тотэма очищения. После этого возвращайся ко мне. И да пребудут с тобой духи." } } }, t = { d = 11.8, v = "tauren-male#68", n = { x = 120 }, c = { x = { { 0.00, "Предки клана Громового Рога явились ко мне во сне и восхваляли тебя за очищение их колодца." }, { 7.39, "Они просили передать тебе это в знак признательности…" } } } } },
    [759] = { d = 21.4, v = "tauren-male#68", n = { x = 224 }, c = { x = { { 0.00, "Тебе осталось очистить лишь один колодец, названный в часть племени Буйногривых." }, { 6.01, "Для этого тебе понадобятся зубы лютого хищника, могучего волка прерий. Ступай на север, убей его и возвращайся." }, { 15.08, "Могучие волки прерий водятся неподалёку от славного города Громового Утёса." } } }, t = { d = 10.2, v = "tauren-male#68", n = { x = 88 }, c = { x = { { 0.00, "Замечательно. Увы, нашей земле приходится приносить в жертву своих детей, и я исполняюсь печали и гордости." } } } } },
    [760] = { d = 26.6, g = 1, v = "tauren-male#68", n = { m = 264, f = 265 }, c = { m = { { 0.00, "Духи говорят, что ты успешно очистил колодцы Заиндевевшего Копыта и Громового Рога, юный герой." }, { 7.36, "Тотэм Буйногривых готов, и ты можешь приступить к выполнению последнего задания." }, { 13.91, "Колодец Буйногривых расположен на севере от Громового Утёса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой." } }, f = { { 0.00, "Духи говорят, что ты успешно очистила колодцы Заиндевевшего Копыта и Громового Рога, юная героиня." }, { 7.54, "Тотэм Буйногривых готов, и ты можешь приступить к выполнению последнего задания." }, { 14.10, "Колодец Буйногривых расположен на севере от Громового Утёса. Проведи ритуал! Избавь нашу землю от гоблинского яда! Пусть вода вновь станет чистой." } } }, t = { d = 17.3, g = 1, v = "tauren-male#68", n = { m = 154, f = 155 }, c = { m = { { 0.00, "Ты справился! Наши колодцы снова чисты, а земля исцелена. Деревня Кровавого Копыта признательна тебе." }, { 10.45, "Пусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек." } }, f = { { 0.00, "Ты справилась! Наши колодцы снова чисты, а земля исцелена. Деревня Кровавого Копыта признательна тебе." }, { 9.11, "Пусть ветер шепчет о твоих подвигах сотни лет, а воды Мулгора остаются чистыми навек." } } } } },
    [761] = { d = 36.8, v = "tauren-male", n = { x = 336 }, c = { x = { { 0.00, "Перепелятники – хитрые птицы. Их нелегко найти и убить." }, { 4.68, "Связка перьев перепелятника – всё равно что медаль для охотника, говорящая о его уме и решимости." }, { 13.35, "Если ты хочешь взяться за это задание, ступай на равнины и убей нескольких перепелятников." }, { 21.47, "Принеси мне их перья, и прославь свой клан этой победой." }, { 26.62, "Перепелятники живут по всему Мулгору, но заметить их могут лишь очень зоркие глаза, а догнать – лишь резвые копыта." } } }, t = { d = 12.1, g = 1, v = "tauren-male", n = { m = 100, f = 101 }, c = { m = { { 0.00, "Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показал, на что способен. Хорошо, что ты живёшь у нас в деревне." } }, f = { { 0.00, "Я знаю, набрать достаточно перьев было нелегко. Но тем самым ты показала, на что способна." }, { 7.88, "Хорошо, что ты живёшь у нас в деревне." } } } } },
    [763] = { d = 52.5, g = 1, v = "tauren-male#67", n = { m = 406, f = 406 }, c = { m = { { 0.00, "Чтобы продолжить прохождение обрядов Матери-Земли, ты должен пройти ещё два испытания. Тебе бы не помешало поднабраться опыта." }, { 12.36, "Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна." }, { 22.03, "Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса." }, { 31.62, "Отнеси этот тотэм Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии." }, { 40.97, "Следуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!" } }, f = { { 0.00, "Чтобы продолжить прохождение обрядов Матери-Земли, ты должна пройти ещё два испытания. Тебе бы не помешало поднабраться опыта." }, { 12.52, "Отправляйся в Деревню Кровавого Копыта и найди вождя Бейна Кровавого Копыта, сына Кэрна." }, { 22.19, "Там ты сможешь продолжить свои тренировки и завоевать расположение старейшин Громового Утёса." }, { 31.77, "Отнеси этот тотэм Бейну. Он узнает мою руку в этой резьбе и поможет тебе в твоём путешествии." }, { 41.13, "Следуй по дороге из Лагеря Нараче, да поспеши. И не уходи далеко от дороги – заблудишься!" } } }, t = { d = 13.5, g = 1, v = "tauren-male#67", n = { x = 83 }, c = { m = { { 0.00, "О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты герой особой породы!" } }, f = { { 0.00, "О, весточка от моего старого друга, вождя Соколиного Ветра! Смотри-ка, он пишет мне, что ты героиня особой породы!" } } } } },
    [764] = { d = 33.4, v = "tauren-male", n = { x = 325 }, c = { x = { { 0.00, "Теперь понятно, почему в Мулгоре появилось много сотрудников и оборудования Торговой компании. Эти гоблины..." }, { 9.17, "Компания слишком быстро растёт, не жди добра. Как говорят, гоблинам палец в рот не клади." }, { 17.08, "Маленькие жадины. К несчастью для их деловых операций, таурены не согласны терпеть их присутствие в своих землях." }, { 25.92, "Ступай в их рудник на северо-востоке от разграбленного каравана и преподай им урок." } } }, t = { d = 16.0, v = "tauren-male", n = { x = 168 }, c = { x = { { 0.00, "Думаю, такой намёк невозможно не понять, а?" }, { 3.34, "Торговая Компания не будет впредь так легко относиться к тауренам или заносчиво полагать, будто мы без лишних слов позволим похищать наши полезные ископаемые." } } } } },
    [765] = { d = 40.1, g = 1, v = "tauren-male", n = { m = 392, f = 393 }, c = { m = { { 0.00, "Согласно документам, которые ты отыскал в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить." }, { 15.48, "Мне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы." }, { 26.21, "Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана." }, { 34.34, "Принеси мне его планшет, посмотрим, нет ли в нём чего полезного." } }, f = { { 0.00, "Согласно документам, которые ты отыскала в караване, Торговая компания разработала несколько планов, как изгнать нас из наших земель, чтобы они могли беспрепятственно их разграбить." }, { 15.82, "Мне тошно слышать, на какую низость они готовы пойти ради достижения цели. Я хочу уничтожить того, кто разработал эти планы." }, { 26.55, "Его зовут бригадир Шумовик, он сейчас в руднике Торговой компании на востоке от разграбленного каравана." }, { 34.67, "Принеси мне его планшет, посмотрим, нет ли в нём чего полезного." } } }, t = { d = 16.3, v = "tauren-male", n = { x = 159 }, c = { x = { { 0.00, "Ярость немного отступила при вести о гибели злодея Шумовика." }, { 4.76, "Я пороюсь в его личных вещах, посмотрю, нет ли там дополнительных сведений о ближайших планах Торговой Компании. Спасибо за помощь." } } } } },
    [766] = { d = 38.4, v = "tauren-male#68", n = { x = 406 }, c = { x = { { 0.00, "Дедушка рассказывал мне истории о столкновениях с долгоногом Маззраначем." }, { 5.69, "О его красных, как у демона, глазах, острых, как бритва, когтях и ядовитых укусах." }, { 12.24, "И вот ирония судьбы – он встретился мне во время странствий по равнинам и здорово укусил меня за плечо." }, { 20.04, "Мой дед ничуть не преувеличил, описывая это жуткое создание." }, { 24.69, "Теперь мне нужны редкие части животных, чтобы вылечить воспалённую рану: сердце койота, бедро пумы, чешуя равнинного долгонога и потроха перепелятника. Торопись, время не ждёт." } } }, t = { d = 22.9, v = "tauren-male#68", n = { x = 218 }, c = { x = { { 0.00, "А, спасибо. Из этих компонентов я сделаю лекарство, которое остановит распространение инфекции и излечит меня. Я обязан тебе жизнью." }, { 12.52, "Но пронзительный крик Маззранача и блеск его безжалостного клюва мне никогда не забыть…" }, { 19.52, "Будь осторожен во время своих странствий." } } } } },
    [767] = { d = 26.7, v = "tauren-male#67", n = { x = 227 }, c = { x = { { 0.00, "Обряд прозрения, один из обрядов Матери-Земли, поможет тебе завоевать уважение старейшин Громового Утёса." }, { 10.42, "Наш народ твёрдо усвоил, что кормящая нас земля – священна." }, { 16.11, "Чтобы принять участие в этом ритуальном прозрении, поговори с духовным вождём деревни, Зарельманом Две Луны." } } }, t = { d = 11.0, g = 1, v = "tauren-male#67", n = { x = 81 }, c = { m = { { 0.00, "Я предчувствовал, что ты придёшь ко мне, герой. Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли." } }, f = { { 0.00, "Я предчувствовал, что ты придёшь ко мне, героиня. Я всегда узнаю тех, кто пытается пройти обряды Матери-Земли." } } } } },
    [768] = { d = 27.6, g = 1, v = "tauren-male", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Привет тебе, юноша. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться." }, { 10.04, "Да принесёшь ты честь своему клану!" }, { 13.29, "Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса." }, { 21.24, "Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью." } }, f = { { 0.00, "Привет тебе, девица. У тебя так горят глаза, что готов поспорить – тебе не терпится вернуться на равнины и поохотиться." }, { 10.14, "Да принесёшь ты честь своему клану!" }, { 13.40, "Я работаю со шкурами животных – шью из них одежду и доспехи для народа Громового Утёса." }, { 21.34, "Если принесёшь мне добытые на охоте шкуры, я что-нибудь и для тебя сошью." } } }, t = { d = 7.7, v = "tauren-male", n = { x = 63 }, c = { x = { { 0.00, "Ах, какая кожа! Из неё выйдут отличные товары. Вот. Возьми в знак благодарности..." } } } } },
    [769] = { d = 22.7, v = "tauren-male", n = { x = 198 }, c = { x = { { 0.00, "Эти кодо из Мулгора – твари крепкие и упрямые, а мы такие качества уважаем." }, { 7.08, "Если ты дока в кожевничестве и хочешь научиться делать сумки из шкуры кодо, то принеси мне необходимые для моего дела припасы." }, { 18.99, "И тогда я поделюсь с тобой своими знаниями." } } }, t = { d = 9.8, v = "tauren-male", n = { x = 92 }, c = { x = { { 0.00, "Добро. Спасибо. Моё сердце распирает от гордости, когда я вижу молодёжь, взыскующую мастерства в кожевничестве!" } } } } },
    [770] = { d = 18.1, v = "human-male#114", n = { x = 192 }, c = { x = { { 0.00, "На потрёпанной шкуре Призрачного Воя по-прежнему виден след от ужасной раны, полученной во время сражений волка с Пылающим Легионом." }, { 10.38, "Может быть, следует рассказать кому-нибудь в Деревне Кровавого Копыта о кончине Призрачного Воя..." } } }, t = { d = 32.3, g = 1, v = "tauren-male", n = { m = 299, f = 300 }, c = { m = { { 0.00, "Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты вырос в моих глазах, юный герой." }, { 8.40, "Оказывается, ты превосходный охотник!" }, { 11.77, "Позволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие." }, { 22.94, "Пусть оно не знает промаха и дарует тебе славу." }, { 27.06, "Будем надеяться, что дух Призрачного Воя упокоился с миром." } }, f = { { 0.00, "Глазам своим стариковским не верю! Тебе удалось одолеть Призрачного Воя? Ты выросла в моих глазах, юная героиня." }, { 8.68, "Оказывается, ты превосходная охотница!" }, { 12.03, "Позволь предложить тебе кое-что. Мне уже не выйти на тропу охоты, но я почту за честь, если ты примешь моё оружие." }, { 23.20, "Пусть оно не знает промаха и дарует тебе славу." }, { 27.32, "Будем надеяться, что дух Призрачного Воя упокоился с миром." } } } } },
    [771] = { d = 42.7, v = "tauren-male#67", n = { x = 347 }, c = { x = { { 0.00, "Чтобы пройти обряд Прозрения, тебе придётся собрать некоторые реагенты для создания воды Провидцев." }, { 10.20, "Мне понадобятся камни, которых полно вокруг источников Мулгора." }, { 16.46, "Я смешаю их с янтарным семенем, что роняют могучие деревья нашей земли." }, { 23.76, "В этих реагентах содержится магия, и если сварить их и выпить отвар перед костром племени, тебе явится видение." }, { 35.46, "Следуй за ним, и оно приведёт тебя к следующему этапу священного обряда." } } }, t = { d = 12.9, g = 1, v = "tauren-male#67", n = { m = 109, f = 110 }, c = { m = { { 0.00, "Вижу, ты научился собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев." } }, f = { { 0.00, "Вижу, ты научилась собирать дань с нашей священной земли. Мне понадобится совсем немного времени, чтобы приготовить воду Провидцев." } } } } },
    [772] = { d = 19.1, v = "tauren-male#67", n = { x = 154 }, c = { x = { { 0.00, "Я вручаю тебе воду Провидцев." }, { 3.27, "Выпей её перед костром племени. Когда священные воды вольются в тебя, из огня навстречу тебе шагнёт видение." }, { 14.02, "После этого следуй за ним навстречу своей судьбе..." } } }, t = { d = 4.4, g = 1, v = "tauren-male#68", n = { m = 36, f = 36 }, c = { m = { { 0.00, "Не бойся. Ты успешно прошёл Обряд прозрения." } }, f = { { 0.00, "Не бойся. Ты успешно прошла Обряд прозрения." } } } } },
    [773] = { d = 27.4, g = 1, v = "tauren-male#68", n = { m = 263, f = 263 }, c = { m = { { 0.00, "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости." }, { 7.27, "Ты уже прошёл Обряд прозрения, и духи Красных скал благословят тебя силой предков." }, { 13.60, "Лишь те, кто испили воды Провидцев, могут обрести это благословение." }, { 19.24, "Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков." } }, f = { { 0.00, "Чтобы завоевать признание старейшин Громового Утёса, тебе следует пройти Обряд мудрости." }, { 7.27, "Ты уже прошла Обряд прозрения, и духи Красных скал благословят тебя силой предков." }, { 13.42, "Лишь те, кто испили воды Провидцев, могут обрести это благословение." }, { 19.06, "Ступай на восток от Громового Утёса, к Красным скалам, и отыщи там дух предков." } } }, t = { d = 27.7, g = 1, v = "tauren-male", n = { m = 242, f = 243 }, c = { m = { { 0.00, "Ты приложил много стараний, чтобы пройти обряды Матери-Земли." }, { 5.29, "Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс." }, { 13.11, "Итак, я передаю тебе почётную обязанность хранить его от бед." }, { 18.82, "Ты прошёл Обряд мудрости, юный герой. Отныне ты можешь с гордостью войти в Громовой Утёс." } }, f = { { 0.00, "Ты приложила много стараний, чтобы пройти обряды Матери-Земли." }, { 5.32, "Мы, духи предков – память о могучих тауренах, отдавшие жизни за великий город Громовой Утёс." }, { 13.14, "Итак, я передаю тебе почётную обязанность хранить его от бед." }, { 18.85, "Ты прошла Обряд мудрости, юная героиня. Отныне ты можешь с гордостью войти в Громовой Утёс." } } } } },
    [775] = { d = 21.7, g = 1, v = "tauren-male", n = { m = 209, f = 209 }, c = { m = { { 0.00, "Отныне тебя будут почитать в стенах нашего великого города. Прошедший обряды Матери-Земли заслуживает такой чести." }, { 10.39, "Выполни последнее задание, отыщи благородного вождя Кэрна Кровавого Копыта, живущего на вершине высочайшего плато в Громовом Утёсе." } }, f = { { 0.00, "Отныне тебя будут почитать в стенах нашего великого города. Прошедшая обряды Матери-Земли заслуживает такой чести." }, { 9.26, "Выполни последнее задание, отыщи благородного вождя Кэрна Кровавого Копыта, живущего на вершине высочайшего плато в Громовом Утёсе." } } }, t = { d = 5.3, g = 1, v = "named/3057", n = { x = 48 }, c = { m = { { 0.00, "Привет тебе, юный герой. Вижу, тебе удалось отыскать дорогу ко мне." } }, f = { { 0.00, "Привет тебе, юный героиня. Вижу, тебе удалось отыскать дорогу ко мне." } } } } },
    [776] = { d = 24.8, g = 1, v = "named/3057", n = { m = 273, f = 274 }, c = { m = { { 0.00, "Ты прошёл обряды Матери-Земли и заслужил достойное место среди жителей Громового Утёса." }, { 6.30, "Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу." }, { 13.35, "Мы охотники. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея." }, { 19.09, "Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи." } }, f = { { 0.00, "Ты прошла обряды Матери-Земли и заслужила достойное место среди жителей Громового Утёса." }, { 6.36, "Чтобы сохранить это таким трудом заработанное место, тебе придётся и дальше служить своему народу." }, { 13.41, "Мы охотники. Внизу, в Мулгоре, есть могучий кодо по имени Арра'чея." }, { 19.16, "Выследи и убей его, проявив своё искусство охотника, и принеси мне рог Арра'чеи." } } }, t = { d = 8.2, g = 1, v = "named/3057", n = { m = 88, f = 89 }, c = { m = { { 0.00, "Отлично! Добрая охота." }, { 1.91, "Я пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо. Ты оказал своему народу услугу." } }, f = { { 0.00, "Отлично! Добрая охота." }, { 1.91, "Я пошлю отряд за тушей кодо, чтобы забрать шкуру и мясо. Ты оказала своему народу услугу." } } } } },
    [780] = { d = 24.4, v = "tauren-male", n = { x = 239 }, c = { x = { { 0.00, "Боевые вепри из Ежевичной лощины, что к востоку отсюда, вторгаются в охотничьи угодья нашего племени." }, { 8.79, "Их натаскивают свинобразы из племени Дыбогривов, наши заклятые враги." }, { 14.60, "Пойди и покажи гнусным тварям, кто хозяин в этих землях! Мы сварим из их боков и рыл славную похлёбку для наших детишек!" } } }, t = { d = 11.2, v = "tauren-male", n = { x = 98 }, c = { x = { { 0.00, "Прекрасно! Мы сварим отличную похлёбку, а для проклятых дыбогривов потеря нескольких боевых вепрей послужит уроком." } } } } },
    [781] = { d = 16.2, v = "human-male#114", n = { x = 146 }, c = { x = { { 0.00, "Внимательно изучив карту, вы понимаете, что перед вами не что иное, как план нападения клана Дыбогривов на Лагерь Нараче." }, { 11.46, "Вождь Соколиный Ветер непременно должен об этом узнать!" } } }, t = { d = 19.4, g = 1, v = "tauren-male#67", n = { m = 149, f = 151 }, c = { m = { { 0.00, "Это действительно тревожные вести! Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение. Ты спас жизни многих тауренов." } }, f = { { 0.00, "Это действительно тревожные вести! Но с этой информацией мы сможем призвать наших братьев из Деревни Кровавого Копыта, чтобы остановить нападение. Ты спасла жизни многих тауренов." } } } } },
    [783] = { d = 34.9, g = 1, v = "human-male", n = { m = 383, f = 385 }, c = { m = { { 0.00, "Надеюсь, ты готов к подвигам, герой, поскольку для тебя есть дело здесь, в Североземье." }, { 6.34, "И я имею в виду не мирные сельские заботы." }, { 9.92, "Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится." }, { 19.63, "И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких." }, { 25.47, "Если ты готов откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной." } }, f = { { 0.00, "Надеюсь, ты готова к подвигам, героиня, поскольку для тебя есть дело здесь, в Североземье." }, { 6.52, "И я имею в виду не мирные сельские заботы." }, { 10.10, "Стража Штормграда с трудом поддерживает здесь мир: слишком многие из нас находятся в дальних краях, а тревожных вестей меньше не становится." }, { 19.81, "И потому мы надеемся на помощь всех, кто готов защитить свой дом и своих близких." }, { 25.64, "Если ты готова откликнуться на призыв, то поговори с моим командиром, маршалом Макбрайдом. Он здесь, в аббатстве у меня за спиной." } } }, t = { d = 23.6, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Отлично. Ещё один доброволец. В эти дни у нас много таких, как ты. Надеюсь, нам хватит бойцов." }, { 6.79, "Землям людей угрожают внешние враги, потому большая часть наших сил направлена к рубежам." }, { 12.92, "И из-за этого бандитские шайки вольготно чувствуют себя в наших землях." }, { 18.71, "Нам приходится воевать на много фронтов... Готовьтся к долгой войне." } } } } },
    [784] = { d = 36.2, v = "orc-male#60", n = { x = 410 }, c = { x = { { 0.00, "Люди из Кул-Тираса, ведомые адмиралом Праудмуром, вторглись в Дуротар, нарушив договор, который вождь заключил с Джайной Праудмур несколько лет назад, чтобы одолеть Архимонда." }, { 12.45, "Вторжение людей удалось отбить, крепость Тирагард пала." }, { 16.44, "Но не так давно подкрепление под командой лейтенанта Бенедикта вновь захватило эту крепость. Нашей родине снова грозит опасность!" }, { 26.43, "Эти люди совершенно не чтут договоров!" }, { 29.58, "Покажи свою доблесть. Отправляйся на юг, в крепость Тирагард, и уничтожь непрошеных гостей." } } }, t = { d = 9.0, g = 1, v = "orc-male#60", n = { x = 96 }, c = { m = { { 0.00, "Твоя отвага скоро станет известна всем, герой! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара." } }, f = { { 0.00, "Твоя отвага скоро станет известна всем, героиня! Вести о твоей победе в крепости Тирагард, наверное, уже достигли Оргриммара." } } } } },
    [785] = { d = 40.2, v = "human-male#114", n = { x = 405 }, c = { x = { { 0.00, "Тралл – весьма мудрый и благородный лидер. Его навыки дипломата могут сравниться лишь с его отвагой на поле брани." }, { 9.27, "Тролли из племени Чёрного Копья оказались бесценными союзниками для всего орочьего рода." }, { 16.12, "И мы, из верности и чести, заключили с ними договор о взаимной обороне." }, { 22.43, "И вот вождь приказал удостовериться, что нашим друзьям в деревне Сен'джин ничто не угрожает." }, { 29.46, "Один из их самых опытных разведчиков, Лар Ночной Клык, охраняет их западные пределы." }, { 36.41, "Разыщи Лара и спроси, не нужна ли ему помощь." } } } },
    [786] = { d = 34.4, g = 1, v = "troll-male#78", n = { m = 368, f = 369 }, c = { m = { { 0.00, "Говори потише, герой! Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара." }, { 8.31, "Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!" }, { 21.33, "Нельзя допустить, чтобы они это сделали! Достаточно ли ты храбр, чтобы напасть на Утёс Колкара и уничтожить их планы?" }, { 29.70, "Я заметил, что они хранятся у трёх лидеров кентавров." } }, f = { { 0.00, "Говори потише, героиня! Кентавры из племени Колкар совсем близко, вон там, к западу от Утёса Колкара." }, { 8.68, "Прошлой ночью, когда они отправились в набег, мне удалось пробраться в их лагерь, и там я обнаружил, что эти грязные твари замышляют нанести тройной удар по позициям троллей и орков Дуротара!" }, { 21.70, "Нельзя допустить, чтобы они это сделали! Достаточно ли ты храбра, чтобы напасть на Утёс Колкара и уничтожить их планы?" }, { 30.04, "Я заметил, что они хранятся у трёх лидеров кентавров." } } }, t = { d = 18.4, g = 1, v = "troll-male#78", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть." }, { 4.84, "Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь." }, { 10.69, "А кровопролитий в эти смутные времена и без того хватает." }, { 15.00, "Ты хорошо послужил своему народу, герой." } }, f = { { 0.00, "Конечно, если кентавры осмелятся напасть на нас, Орда сумеет их одолеть." }, { 4.84, "Но, предотвратив нападение, мы избавили наших могучих воинов от возможных потерь." }, { 10.69, "А кровопролитий в эти смутные времена и без того хватает." }, { 15.00, "Ты хорошо послужила своему народу, героиня." } } } } },
    [787] = { d = 32.0, g = 1, v = "orc-male#60", n = { x = 342 }, c = { m = { { 0.00, "Тром'ка, герой! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов." }, { 6.94, "Орда уже не такая, как раньше. Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти." }, { 16.96, "Во время изгнания я попал в плен к людям, но вождь меня спас." }, { 21.23, "Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся." }, { 28.94, "Горнек скажет тебе, что делать дальше." } }, f = { { 0.00, "Тром'ка, героиня! Меня зовут Эйтригг. Тралл поручил мне следить за обучением рекрутов." }, { 6.36, "Орда уже не такая, как раньше. Некогда я оставил её: мне не нравилось растущее влияние прихвостней Пылающего Легиона, которые рвались к власти." }, { 16.38, "Во время изгнания я попал в плен к людям, но вождь меня спас." }, { 20.65, "Он поделился со мной своей мечтой о Новой Орде, свободной от влияния демонов. Я выслушал его – и вернулся." }, { 28.36, "Горнек скажет тебе, что делать дальше." } } }, t = { d = 16.4, v = "orc-male#60", n = { x = 178 }, c = { x = { { 0.00, "Ещё один из новобранцев Эйтригга, хм? В каком плачевном положении мы оказались, если это лучшее, что может произвести Орда. Неважно." }, { 10.06, "К тому времени, когда мы решим, что вы готовы покинуть Долину, вы будете гордиться собой." } } } } },
    [788] = { d = 18.3, g = 1, v = "orc-male#60", n = { m = 198, f = 200 }, c = { m = { { 0.00, "Вот тебе первое поручение, чтобы ты набрался опыта и показал себя." }, { 4.66, "Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему." }, { 12.50, "Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда." } }, f = { { 0.00, "Вот тебе первое поручение, чтобы ты набралась опыта и показала себя." }, { 4.69, "Конечно, можно было бы отправить тебя в Степи охотиться на кодо, но нам лишние покойники ни к чему." }, { 12.53, "Пожалуй, тебе стоит начать с пятнистых вепрей, которые обитают к северу отсюда." } } }, t = { d = 17.8, g = 1, v = "orc-male#60", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Ну что ж, неплохо. Но не задирай носа: грядут бои с куда более серьёзными врагами." }, { 6.13, "Однако ты показал себя достойным бойцом." }, { 9.16, "В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает." } }, f = { { 0.00, "Ну что ж, неплохо. Но не задирай носа: грядут бои с куда более серьёзными врагами." }, { 6.13, "Однако ты показала себя достойным бойцом." }, { 9.21, "В следующем испытании тебе придётся встретиться с более опасным противником, так что дополнительная защита не помешает." } } } } },
    [789] = { d = 29.6, v = "orc-male#60", n = { x = 305 }, c = { x = { { 0.00, "Ядовитое жало скорпиона губит всех – и могучих воинов, и неопытных новичков." }, { 5.34, "К северо-западу отсюда водится множество этих членистоногих. Принеси мне десять их хвостов, чтобы доказать свою воинскую доблесть." }, { 14.80, "Из яда жал скорпионов можно изготовить противоядие. Мы всегда держим его под рукой, специально для неосторожных юнцов вроде тебя..." }, { 26.86, "Но тебе-то оно не понадобится, а?" } } }, t = { d = 19.0, g = 1, v = "orc-male#60", n = { m = 209, f = 210 }, c = { m = { { 0.00, "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним!" }, { 6.94, "В бою победа или поражение зависят от многого." }, { 10.56, "Ну что ж! Я научил тебя всему, чему мог. Ты оказался хорошим учеником. Я буду с интересом следить за твоей карьерой." } }, f = { { 0.00, "Запомни раз и навсегда: любой противник, будь он мал или велик, может оказаться для тебя последним!" }, { 6.94, "В бою победа или поражение зависят от многого." }, { 10.56, "Ну что ж! Я научил тебя всему, чему мог. Ты оказалась хорошим учеником. Я буду с интересом следить за твоей карьерой." } } } } },
    [790] = { d = 35.3, g = 1, v = "troll-male", n = { x = 291 }, c = { m = { { 0.00, "герой! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный." }, { 12.55, "Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу." }, { 20.32, "А вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида!" }, { 31.60, "Я сражался с ним на плато, к югу отсюда..." } }, f = { { 0.00, "героиня! А я уж думаю, помру тут, никто и не узнает... Я охотился в долине на скорпидов, и попался мне один, особенно злобный." }, { 11.99, "Я бросился на него и сумел разрубить ему клешню, когда та собиралась укоротить мне ногу." }, { 19.76, "А вот жало застигло меня врасплох. Оно вонзилось мне в грудь, хлынула кровь... Прошу тебя, смой с меня позор! Убей этого скорпида!" }, { 31.02, "Я сражался с ним на плато, к югу отсюда..." } } }, t = { d = 16.7, v = "troll-male", n = { x = 155 }, c = { x = { { 0.00, "Да, убить его мне не удалось, но ранил я его серьёзно. Пожалуй, мне есть чем гордиться." }, { 7.18, "И это единственное, что утешает меня перед смертью. Как подумаю, как мало я сделал в жизни, такая злость берёт!" } } } } },
    [791] = { d = 37.8, v = "orc-male#60", n = { x = 393 }, c = { x = { { 0.00, "Старость сделала меня бесполезным в бою. Теперь я служу Орде иным путём." }, { 5.92, "Я сижу здесь, на вышине, и смотрю, не появятся ли враги." }, { 9.81, "Но по мере того, как наши силы растут, мне всё реже и реже приходится трубить в сигнальный рог." }, { 16.67, "А чтобы проводить время с пользой, я изготовляю разные вещи для молодых сильных воинов, которые защищают теперь нашу родину." }, { 25.39, "Я могу сделать тебе сумку для пожитков." }, { 28.27, "Если такая вещь будет для тебя полезна, принеси мне отрез холста – эта ткань в ходу у людей и кентавров." } } }, t = { d = 8.7, v = "orc-male#60", n = { x = 92 }, c = { x = { { 0.00, "Отлично! Такая сумка пригодится любому хорошему бойцу." }, { 4.35, "Я отдаю честь твоей силе и решимости умереть во имя Орды!" } } } } },
    [792] = { d = 31.5, g = 1, v = "orc-female", n = { x = 339 }, c = { m = { { 0.00, "Что ж, герой, надеюсь, у нас ты многому научишься." }, { 3.86, "Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно!" }, { 10.44, "В долине Испытаний обосновался клан Пылающего Клинка." }, { 14.14, "Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос." }, { 21.77, "Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне." } }, f = { { 0.00, "Что ж, героиня, надеюсь, у нас ты многому научишься." }, { 4.08, "Меня послали сюда, чтобы я стала твоей наставницей, но оказывается, здесь не всё ладно!" }, { 10.66, "В долине Испытаний обосновался клан Пылающего Клинка." }, { 14.36, "Эти твари скрываются в пещере на северо-востоке, и их злобные фамильяры выбираются оттуда и сеют хаос." }, { 21.98, "Итак, вот твоё первое задание в борьбе с Пылающим Клинком: перебей их столько, сколько сумеешь, и, если выживешь, возвращайся ко мне." } } }, t = { d = 11.0, v = "orc-female", n = { x = 116 }, c = { x = { { 0.00, "Молодец!" }, { 1.24, "Да, злобные фамильяры для злодеев из Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предрекает великие события!" } } } } },
    [794] = { d = 33.1, v = "orc-female", n = { x = 373 }, c = { x = { { 0.00, "С помощью ворожбы я узнала, что в глубине грота Пылающего Клинка находится мощный магический предмет." }, { 7.13, "Его стерегут звери и чёрная магия." }, { 10.08, "Этот предмет – медальон Пылающего Клинка. Твоя очередная задача – найти его и отнять у ковена." }, { 16.66, "Но берегись: медальон может оказаться в руках одного из членов ковена, и этот чернокнижник будет куда могущественнее, чем фамильяры, с которыми тебе уже доводилось встречаться!" }, { 29.30, "Ступай. Грот находится к северо-западу отсюда." } } }, t = { d = 16.7, v = "orc-female", n = { x = 176 }, c = { x = { { 0.00, "Он у тебя! Молодец!" }, { 2.06, "Теперь у нас есть возможность вытеснить приспешников Пылающего Клинка из Долины Испытаний." }, { 8.64, "Но, боюсь, этот грот – не единственный их оплот в наших землях." }, { 13.37, "Так что эта встреча с ними была не последней." } } } } },
    [804] = { d = 18.9, g = 1, v = "troll-male", n = { m = 177, f = 178 }, c = { m = { { 0.00, "То, что ты сделал ради меня, заставило меня воспрянуть духом. Я ещё повоюю!" }, { 6.58, "Но пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь." } }, f = { { 0.00, "То, что ты сделала ради меня, заставило меня воспрянуть духом. Я ещё повоюю!" }, { 6.44, "Но пока что мне не добраться до Логова без посторонней помощи. Прошу тебя, сходи в Логово, расскажи Горнеку, что я здесь. Может, он сумеет мне помочь." } } }, t = { d = 26.6, v = "orc-male#60", n = { x = 300 }, c = { x = { { 0.00, "Судя по твоему описанию, этим скорпионом был не кто иной, как Саркот! Неудивительно, что Хана'зуа с ним не справился." }, { 8.14, "Не тревожься о нём, помощь уже в пути." }, { 11.24, "Однако, нужно сказать, я тебя зауважал. Неужели тебе действительно удалось одолеть Саркота?" }, { 17.75, "Это немалый подвиг, тебе есть чем гордиться. А твоя готовность сражаться по просьбе незнакомца тем более делает тебе честь." } } } } },
    [805] = { d = 40.7, v = "orc-female", n = { x = 414 }, c = { x = { { 0.00, "Твои испытания в борьбе с Пылающим Клинком подошли к концу... по крайней мере тут, в нашей Долине." }, { 6.49, "Но я прошу тебя отнести известие о том, что ты теперь знаешь." }, { 11.16, "Ступай в тролльскую деревню Сен'джин, отыщи там мастера Гадрина. Отправляйся на восток, на развилке поверни направо." }, { 22.14, "Расскажи Гадрину о чернокнижниках из клана Пылающего Клинка и о том, что они уже проникли в долину Испытаний." }, { 30.01, "Узнай, не видно ли их в Сен'джине." }, { 32.88, "Ступай, и не медли в пути! Боюсь, появление Пылающего Клинка в долине – это только первая ласточка..." } } }, t = { d = 21.4, v = "troll-male#77", n = { x = 200 }, c = { x = { { 0.00, "Хм... Как это всё не вовремя! Нет, у нас в Сен'джине Пылающего Клинка пока не видно, однако на побережье, на островах Эхо, обосновалось иное зло." }, { 12.80, "Орки – друзья троллей Чёрного Копья. Верные друзья. Мы хотели бы помочь оркам, но... сейчас нам самим нужна помощь!" } } } } },
    [806] = { d = 33.2, v = "orc-male", n = { x = 377 }, c = { x = { { 0.00, "Нельзя допустить, чтобы Пылающий Клинок закрепился в Дуротаре!" }, { 4.59, "Нужно уничтожить этих чернокнижников, прежде чем распространяемое ими зло расползётся по нашей земле!" }, { 12.10, "Я провёл расследование и выяснил, что один из чернокнижников из клана Пылающего Клинка, гоблин по имени Пшикс Черношквал, обосновался на Громовом хребте к северо-западу отсюда." }, { 24.39, "Там он и его приспешники сеют хаос!" }, { 27.57, "Найди Пшикса, убей его и принеси мне его коготь в качестве доказательства." } } }, t = { d = 8.9, g = 1, v = "orc-male", n = { m = 92, f = 93 }, c = { m = { { 0.00, "Ага! Ты его убил!" }, { 1.74, "Твой клан может гордиться тобой. Благодаря тебе в Дуротаре стало одним приспешником зла меньше." } }, f = { { 0.00, "Ага! Ты его убила!" }, { 1.78, "Твой клан может гордиться тобой. Благодаря тебе в Дуротаре стало одним приспешником зла меньше." } } } } },
    [808] = { d = 39.7, v = "troll-male#77", n = { x = 402 }, c = { x = { { 0.00, "Я слышу голос моего брата, Миншины. Он взывает ко мне из снов." }, { 5.39, "Его захватил в плен Залазан, чернокнижник с островов Эха на востоке. И теперь Миншина мёртв." }, { 12.61, "Но смерть не принесла ему свободы! Залазан заточил дух Миншины внутри его собственного черепа." }, { 20.31, "В снах я вижу его рядом с другими черепами, в магическом кругу на самом большом из островов Эха." }, { 28.53, "Пока его душа находится в этом месте, она обречена не вечные страдания." }, { 33.76, "Прошу тебя, отыщи этот круг и похить череп Миншины. Принеси его мне. Освободи его!" } } }, t = { d = 5.4, v = "troll-male#77", n = { x = 61 }, c = { x = { { 0.00, "Спасибо! Тебе удалось спасти Миншину! Дух моего брата избавлен от рабства!" } } } } },
    [809] = { d = 40.8, v = "orc-male", n = { x = 472 }, c = { x = { { 0.00, "Со времён последней великой войны, когда Пылающий Легион потерпел поражение, я ищу источники демонической порчи, что воздействует на общество орков." }, { 10.51, "И принесённый тобой ошейник подтверждает мои опасения!" }, { 14.88, "Он принадлежит Пылающему Клинку, культу, объединённому вокруг предмета, который наделён демонической силой." }, { 22.31, "Этот предмет называется Демоново Семя, и находится он в Степях, на вершине Багрового Тумана. Его необходимо уничтожить!" }, { 31.00, "Отправляйся на Дальнюю заставу на границе Степей, к западу, и поговори с моим помощником, Ак'Зелотом." }, { 37.95, "Он скажет тебе, что делать дальше." } } }, t = { d = 12.0, v = "orc-male", n = { x = 110 }, c = { x = { { 0.00, "Вот как? Ниру хочет, чтобы Демоново семя было уничтожено? Странно…" }, { 6.50, "Что ж, хорошо. Если такова его воля, я расскажу тебе, как уничтожить семя." } } } } },
    [812] = { d = 30.5, v = "troll-male", n = { x = 285 }, c = { x = { { 0.00, "А... Ты как нельзя вовремя! Надеюсь на твоё проворство." }, { 5.24, "Я сражался с несколькими ядохвостами, и один из них смог меня ужалить. Я чувствую, как слабею с каждой секундой..." }, { 14.26, "Боюсь, мне осталось не больше часа. Мне срочно нужна твоя помощь!" }, { 20.15, "Коргхан из Оргриммара умеет изготовлять противоядие. Найди его... Быстрее! Долго мне не протянуть. Ищи его в расселине Теней." } } }, t = { d = 30.3, v = "troll-male", n = { x = 283 }, c = { x = { { 0.00, "Ты спас мне жизнь! Спасибо тебе." }, { 3.39, "Прошу тебя, возьми эту вещь. Денег за неё не выручишь, но, надеюсь, она пригодится тебе в странствиях." }, { 11.76, "Судя по тому, что ты говоришь, мне она пригодится нескоро." }, { 16.44, "Кор'гхан подвергнет меня ещё множеству своих ритуалов, пока я не сумею показать, на что способен." }, { 24.38, "Снова охотиться на вепрей, собирать хвосты скорпидов... вздыхает" } } } } },
    [815] = { d = 32.7, v = "orc-male", n = { x = 345 }, c = { x = { { 0.00, "Ба! А я и позабыл, что надо готовить завтрак." }, { 3.65, "Слушай, сбегай-ка, раздобудь мне по-быстрому несколько яиц кнутохвостов, как минимум три штуки." }, { 10.82, "Имей в виду, кровопалые кнутохвосты – твари свирепые и вполне могут убить, защищая свою кладку." }, { 19.32, "Иногда они зарывают яйца слишком глубоко, чтобы их можно было беспрепятственно раздобыть, но если ты отправишься на острова Эха, к юго-востоку от деревни Сен'джин, там эти яйца лежат повсюду." } } }, t = { d = 10.5, v = "orc-male", n = { x = 97 }, c = { x = { { 0.00, "Ну, может, ты и слабак но уж ловкости и проворства тебе не занимать!" }, { 6.12, "На вот, возьми за труды и проваливай. Мне готовить надо!" } } } } },
    [816] = { d = 40.4, v = "orc-female#57", n = { x = 441 }, c = { x = { { 0.00, "Прошу тебя, может, хоть ты сумеешь мне помочь?" }, { 3.31, "Мой сын, Крон, несколько дней тому назад отправился на охоту и до сих пор не вернулся!" }, { 9.59, "Он ушёл на запад, в Степи, охотиться на кроколисков у реки Строптивой. Я опасаюсь худшего…" }, { 16.32, "Крон могуч, но гордость и упрямство всегда доводили его до беды." }, { 21.03, "Я попросила его не охотиться на кроколисков, потому что они злобны и коварны! А он рассвирепел и хлопнул дверью." }, { 29.44, "Если не сумеешь отыскать его – узнай хотя бы, что с ним случилось..." }, { 34.07, "даже если тебе придётся заглянуть в брюхо каждому кроколиску на берегах Строптивой!" } } }, t = { d = 23.1, v = "orc-female#57", n = { x = 240 }, c = { x = { { 0.00, "Ох, сыночек... милый мой сыночек…" }, { 2.91, "Что ж, я не знала судьбы своего сына и потому терзалась понапрасну. Теперь же я хоть смогу его оплакать…" }, { 10.63, "Спасибо тебе. Прошу тебя, возьми этот плащ. Я-то собиралась подарить его Крону, когда он вернётся с добычей..." }, { 18.32, "А теперь, зная, что он погиб, я даже не смогу смотреть на него." } } } } },
    [817] = { d = 28.5, v = "troll-male#78", n = { x = 317 }, c = { x = { { 0.00, "У нас в большом ходу шкуры дуротарского тигра. Чего только из них не делают! И одеяла, и доспехи, и шатры." }, { 7.18, "Вот почему мы охотимся на этих животных, но не истребляем их." }, { 11.76, "В общем, пришла пора в очередной раз сократить поголовье. Наши потребности растут, и запасов не хватает. Мне нужны новые шкуры." }, { 20.80, "Принеси мне четыре шкуры дуротарских тигров, и получишь награду. Эти кошки водятся на островах к югу отсюда." } } }, t = { d = 10.2, v = "troll-male#78", n = { x = 109 }, c = { x = { { 0.00, "Молодец! Благодаря твоей помощи наш народ не останется без доспехов и не будет страдать от холода, когда наступит зима. Спасибо тебе." } } } } },
    [818] = { d = 43.0, g = 1, v = "troll-male", n = { m = 390, f = 391 }, c = { m = { { 0.00, "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо." }, { 6.16, "И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда." }, { 15.52, "И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков." }, { 21.93, "Что? Ты достоин? Ну да, конечно... Это ты так думаешь." }, { 26.59, "Мне нужны кое-какие компоненты. Сумеешь ли ты их добыть?" }, { 31.60, "Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда. Вот принеси мне их, потом поговорим." } }, f = { { 0.00, "Да, глаза меня порой подводят, но всё же пока я вижу достаточно отчётливо." }, { 6.16, "И всё чаще приходится прибегать к помощи алхимии, чтобы творить заклинания, которые прежде давались мне без труда." }, { 15.52, "И я не беру учеников. Нет нынче достойных ни среди троллей, ни среди орков." }, { 21.93, "Что? Ты достойна? Ну да, конечно... Это ты так думаешь." }, { 26.58, "Мне нужны кое-какие компоненты. Сумеешь ли ты их добыть?" }, { 31.58, "Мне нужны невредимые глаза макрур и слизь крабов, которые водятся к югу отсюда. Вот принеси мне их, потом поговорим." } } }, t = { d = 3.1, v = "troll-male", n = { x = 23 }, c = { x = { { 0.00, "Отличная работа! Ты молодец!" } } } } },
    [819] = { d = 10.3, v = "human-male#114", n = { x = 89 }, c = { x = { { 0.00, "Маленькая табличка на торце одной из бочек гласит: \"Чэнь Буйный Портер –" }, { 5.93, "Да будет ваш дух горяч, а кружка – полной.\"" } } }, t = { d = 15.6, g = 1, v = "orc-male", n = { m = 157, f = 159 }, c = { m = { { 0.00, "Ну, я…" }, { 1.06, "Это был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром." }, { 7.85, "Я не видел его и не слышал о нём с незапамятных времён. Спасибо, что ты принёс мне этот бочонок." } }, f = { { 0.00, "Ну, я…" }, { 1.06, "Это был один из бочонков Чэня Буйного Портера. Давным-давно он путешествовал вместе с Рексаром." }, { 7.85, "Я не видел его и не слышал о нём с незапамятных времён. Спасибо, что ты принесла мне этот бочонок." } } } } },
    [821] = { d = 28.7, v = "orc-male", n = { x = 284 }, c = { x = { { 0.00, "Хочешь попробовать напиток, придуманный Чэнем? Ах, до чего же хорош! Чэнь передал рецепт моему наставнику, ну а он – мне." }, { 9.30, "Только для него понадобится несколько компонентов. Но он того стоит!" }, { 14.40, "Принеси мне пять клыков равнинного льва, пять почек долгонога и один рог рокочущей ящерицы. Из них выйдет прекрасный портер." }, { 24.97, "Все эти составляющие нетрудно отыскать в Степях." } } }, t = { d = 14.9, v = "orc-male", n = { x = 146 }, c = { x = { { 0.00, "Ха-ха... Вот уж не думал, что снова сварю этот напиток!" }, { 4.79, "Прямо ностальгия охватила. Сразу вспомнилось, как я наварил троггского пойла. Спасибо. От воспоминаний даже на душе посветлело." } } } } },
    [822] = { d = 26.7, v = "orc-male", n = { x = 266 }, c = { x = { { 0.00, "Отличный напиток, а?" }, { 2.19, "Я научился у Чэня ещё одному рецепту. Хочешь узнать? Много времени он не отнимает, а в жизни пригодится." }, { 9.97, "Принеси мне пять грозовых желёз любых грозошкуров, один слюнную железу грозового змея от больших грозовых змеев и печень кодо от любого из кодо Степей." }, { 21.87, "Вставляет – не то слово. Это эль трогга, о котором я уже говорил." } } }, t = { d = 9.0, v = "orc-male", n = { x = 88 }, c = { x = { { 0.00, "Ха-ха! Я знал, что ты не откажешься от этого напитка. Приходи, я ещё тебе сварю. Главное – приноси всё необходимое." } } } } },
    [823] = { d = 33.8, g = 1, v = "troll-male#77", n = { m = 381, f = 382 }, c = { m = { { 0.00, "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе." }, { 7.51, "Однако принесённые тобой вести об Пылающем Клинке сулят неприятности всем." }, { 12.94, "В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок." }, { 21.91, "Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнал в долине Испытаний. Ему нужно это знать." }, { 30.48, "Колючий Холм находится к северу отсюда." } }, f = { { 0.00, "У нас, в деревне Сен'джин, конечно, есть свои проблемы, и твоя помощь нам бы не помешала. Так что спасибо тебе." }, { 7.51, "Однако принесённые тобой вести об Пылающем Клинке сулят неприятности всем." }, { 12.94, "В Колючем Холме есть один орк, Оргнил Душегрыз, в обязанности которого входит охранять Дуротар от таких напастей, как Пылающий Клинок." }, { 21.91, "Ступай к Оргнилу и расскажи ему о нашем положении и о том, что ты узнала в долине Испытаний. Ему нужно это знать." }, { 29.84, "Колючий Холм находится к северу отсюда." } } }, t = { d = 4.9, v = "orc-male", n = { x = 49 }, c = { x = { { 0.00, "Да? Тебе есть, о чём доложить? Ну так рассказывай, чего ты ждёшь?!" } } } } },
    [824] = { d = 30.9, v = "orc-male", n = { x = 315 }, c = { x = { { 0.00, "Служители Земли – сообщество шаманов, посвятивших себя изучению и охране Стихий." }, { 7.24, "Они забыли о безумных древних богах, древних легендах и преданиях больше, чем большинство учёных вообще знало." }, { 15.45, "Повезло тебе, что я знаю кое-кого из Служителей Земли тут, в Ясеневом лесу." }, { 20.80, "Иди в форт Зорам'гар на Зорамское взморье и покажи Дже'неу Санкри свою находку. Если кто и поймёт, что это за шар, так это он." } } }, t = { d = 34.9, v = "troll-male", n = { x = 329 }, c = { x = { { 0.00, "Этот шар... волнует он меня. Многие из наиболее могучих элементалей черпают силу и энергию при помощи таких устройств." }, { 9.54, "Найти такую штуку неповреждённой – одно дело, а вот настолько осквернённой – совсем другое." }, { 18.59, "Я прослежу, чтобы этот шар как следует изучили Служители Земли. Возможно, мы сумеем положить конец такому осквернению Стихий." }, { 28.72, "Прошу – прими это в награду за то, что принёс нам этот шар для изучения." } } } } },
    [825] = { d = 30.5, v = "orc-male#60", n = { x = 350 }, c = { x = { { 0.00, "Один из моих лучших разведчиков принёс сообщение, что обломки кораблей Праудмура всё ещё плавают около побережья Дуротара, к востоку от крепости Тирагард." }, { 11.01, "Ни для кого не секрет, что люди, будучи в союзе с этими маленькими уродцами, гномами, неплохо овладели механикой." }, { 18.84, "Нам нужно знать всё о нашем предполагаемом противнике! К тому же, эти знания пригодятся и нашему народу." }, { 26.46, "Сплавай к обломкам, и добудь мне инструменты Альянса." } } }, t = { d = 9.2, g = 1, v = "orc-male#60", n = { m = 100, f = 101 }, c = { m = { { 0.00, "Ты успешно выполнил поручение, герой. Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном." } }, f = { { 0.00, "Ты успешно выполнила поручение, героиня. Я позабочусь о том, чтобы эти инструменты отправились в Оргриммар с ближайшим караваном." } } } } },
    [826] = { d = 29.8, v = "troll-male#77", n = { x = 333 }, c = { x = { { 0.00, "Знахарь Залазан живёт на островах Эха на востоке. Эти острова мы когда-то называли родиной…" }, { 7.08, "А теперь он оттуда посылает троллей на материк, досаждая нашему народу и переманивая на свою сторону всё новых приспешников. Его нужно остановить!" }, { 17.43, "Уничтожь Залазана и его слуг – бывших троллей из племени Чёрного Копья, ныне потерянных для нас!" }, { 24.53, "Принеси мне его голову – и я буду знать, что владычеству зла пришёл конец." } } }, t = { d = 16.8, v = "troll-male#77", n = { x = 192 }, c = { x = { { 0.00, "Залазана больше нет, наше племя снова может спать спокойно!" }, { 4.47, "Спасибо. Племя Чёрного Копья многим тебе обязано." }, { 7.95, "Если тебя мучает какой-нибудь недуг, обратись к моему помощнику, Бом'бею, который находится позади меня. Он силён в магии вуду…" } } } } },
    [827] = { d = 34.3, g = 1, v = "orc-male", n = { x = 381 }, c = { m = { { 0.00, "путник! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа." }, { 6.66, "Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками." }, { 13.91, "Я подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами." }, { 20.24, "Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников." }, { 26.01, "Ступай к скале Черепа и отбери у фанатиков, которых там найдёшь, их ошейники. Принеси их мне, и я раскрою их тайну!" } }, f = { { 0.00, "путница! Пылающий Клинок захватил пещеру к востоку от Оргриммара, известную как скала Черепа." }, { 6.66, "Сектанты совершают там свои гнусные обряды и сжигают собственную плоть обжигающими ошейниками." }, { 13.91, "Я подозреваю, что, нося эти ошейники, фанатики вступают в резонанс с демоническими силами." }, { 20.24, "Но чтобы в этом убедиться, мне необходимо изучить несколько таких ошейников." }, { 26.01, "Ступай к скале Черепа и отбери у фанатиков, которых там найдёшь, их ошейники. Принеси их мне, и я раскрою их тайну!" } } }, t = { d = 6.3, v = "orc-male", n = { x = 61 }, c = { x = { { 0.00, "Отлично! В этих ошейниках и таится секрет Пылающего Клинка. И я его раскрою!" } } } } },
    [828] = { d = 37.4, v = "orc-male", n = { x = 392 }, c = { x = { { 0.00, "Один из наших шаманов, Маргоз, многое знает о клане Пылающего Клинка." }, { 4.95, "Как-то он рассказывал о пещере, которая называется скала Черепа, в горах у самого Оргриммара." }, { 11.61, "Там окопалась большая шайка сектантов из клана Пылающего Клинка." }, { 16.71, "Прежде чем отправиться к скале Черепа, поговори с Маргозом. Он мудр, и к его советам стоит прислушиваться." }, { 25.22, "Ты найдёшь его на северо-востоке, между побережьем и Сухой лощиной." }, { 30.28, "Следуй его советам, но, что бы он ни сказал, я прошу тебя – уничтожь этих сектантов!" } } }, t = { d = 12.9, g = 1, v = "orc-male", n = { x = 132 }, c = { m = { { 0.00, "Здравствуй. До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре. Ты – многообещающая герой." }, { 7.91, "Не сворачивай с этого пути, и великое будущее будет ждать тебя!" } }, f = { { 0.00, "Здравствуй. До меня дошли слухи о твоём появлении и о твоих подвигах в Дуротаре. Ты – многообещающая героиня." }, { 8.03, "Не сворачивай с этого пути, и великое будущее будет ждать тебя!" } } } } },
    [829] = { d = 39.9, v = "orc-male", n = { x = 456 }, c = { x = { { 0.00, "Принесённые тобой обжигающие ошейники – это мощные инструменты демонов. И распознать их происхождение мне, как шаману, не под силу." }, { 9.17, "Нужно, чтобы на них взглянул чернокнижник." }, { 12.48, "Отнеси один обжигающий ошейник Нииру Огненному Клинку." }, { 16.57, "Он искусный чернокнижник, но утверждает, что использует свою силу лишь затем, чтобы вредить демонам, а ещё говорит, что его оккультные исследования идут на пользу Орде." }, { 28.39, "Правда это или нет, а его помощь нам ещё может понадобиться в борьбе с последователями демонов в Дуротаре." }, { 36.10, "Нииру можно найти в Оргриммаре, в Расселине Теней." } } }, t = { d = 8.3, v = "orc-male", n = { x = 80 }, c = { x = { { 0.00, "О! Откуда у тебя это? Тебя прислал ко мне славный Маргоз из Колючего Холма, верно? Ну-ка, дай взглянуть..." } } } } },
    [830] = { d = 18.0, v = "human-male#114", n = { x = 187 }, c = { x = { { 0.00, "Вы открываете потрёпанный и выгоревший конверт и обнаруживаете документ официального вида. На нём – печать адмирала Праудмура." }, { 10.09, "Похоже, это что-то важное. Может быть, Га'току, командиру Колючего Холма, эта информация пригодится..." } } }, t = { d = 5.3, v = "orc-male#60", n = { x = 57 }, c = { x = { { 0.00, "Ничего хорошего это не предвещает... Очень хорошо, что ты принёс это мне." } } } } },
    [831] = { d = 38.7, v = "orc-male#60", n = { x = 444 }, c = { x = { { 0.00, "Людям верить нельзя. Мы сражались плечом к плечу с ними, но в глубине души знали, что рано или поздно они нас предадут." }, { 8.53, "Адмирал Праудмур был убит, но этого оказалось недостаточно, чтобы остановить предательство." }, { 14.92, "Этот подлый человечишка успел изложить свои планы на бумаге, прежде чем встретил заслуженную смерть." }, { 22.35, "Его наследие не пропадёт даже со смертью Бенедикта. Кто знает, когда следующая волна людей Праудмура обрушится на наши берега?" }, { 31.57, "Эти приказы нужно немедленно доставить в Оргриммар, Назгрелу! Ты найдёшь его в зале приёмов Тралла." } } }, t = { d = 14.5, g = 1, v = "orc-male", n = { m = 145, f = 146 }, c = { m = { { 0.00, "О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости. Ты достойно послужил Орде, герой." }, { 8.91, "А теперь извини, мне нужно немедленно поговорить об этом с Траллом!" } }, f = { { 0.00, "О, сколько раз я умолял вождя не доверять людям! Однако тут речь не о личной гордости." }, { 6.48, "Ты достойно послужила Орде, героиня." }, { 9.36, "А теперь извини, мне нужно немедленно поговорить об этом с Траллом!" } } } } },
    [832] = { d = 28.7, v = "human-male#114", n = { x = 240 }, c = { x = { { 0.00, "Слова из амулета плавно перетекают в ваш разум. Газз'уз! Газз'уз, докладывай!" }, { 6.46, "О том, что ты нашёл в Скале Черепа, уже стало известно. Готовься к нападению!" }, { 12.69, "Говори, Газз'уз! Говори, или я позабочусь о том, чтобы о твоём присутствии стало известно Нииру Огненному Клинку, а уж он-то тебя не пощадит!" }, { 23.86, "С Нииру тебе лучше не связываться... Газз'уз, ты меня слышишь?" } } }, t = { d = 35.4, g = 1, v = "orc-male", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Нииру разглядывает Око Пылающей Тени." }, { 3.38, "Любопытно. Так ты говоришь, голос упоминал моё имя?" }, { 7.38, "Я, конечно, известен как непримиримый враг противников нашего вождя, но всё же странно, что голос назвал именно меня." }, { 15.52, "Тем более странно, что название секты, у членов которой ты нашёл этот амулет, так похоже на мою фамилию." }, { 23.27, "Надо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение." }, { 29.68, "Спасибо, что сообщил мне об этом. Ты оказал своему народу серьёзную услугу." } }, f = { { 0.00, "Нииру разглядывает Око Пылающей Тени." }, { 3.38, "Любопытно. Так ты говоришь, голос упоминал моё имя?" }, { 7.38, "Я, конечно, известен как непримиримый враг противников нашего вождя, но всё же странно, что голос назвал именно меня." }, { 15.52, "Тем более странно, что название секты, у членов которой ты нашла этот амулет, так похоже на мою фамилию." }, { 23.14, "Надо изучить эту подвеску. Изучить и поразмыслить над тем, что значит это сообщение." }, { 29.55, "Спасибо, что сообщила мне об этом. Ты оказала своему народу серьёзную услугу." } } } } },
    [833] = { d = 40.7, g = 1, v = "tauren-male#67", n = { x = 331 }, c = { m = { { 0.00, "Лишь самых доблестных тауренов хоронят в Красных скалах, на нашем священном кладбище." }, { 8.34, "Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей." }, { 21.92, "Похоже, теперь на эту священную землю пала тень." }, { 26.53, "Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их." }, { 36.61, "Против них поможет только сила, герой." } }, f = { { 0.00, "Лишь самых доблестных тауренов хоронят в Красных скалах, на нашем священном кладбище." }, { 8.34, "Эта честь выпадает лишь величайшим воинам, основавшим и защищавшим Громовой Утёс, и тем, кто отдал свои жизни на благо племени и вождей." }, { 21.80, "Похоже, теперь на эту священную землю пала тень." }, { 26.41, "Могилы оскверняет отряд злоумышленников из племени Дыбогривов, а я слишком стар, чтобы отогнать их." }, { 36.49, "Против них поможет только сила, героиня." } } }, t = { d = 11.8, g = 1, v = "tauren-male#67", n = { m = 90, f = 91 }, c = { m = { { 0.00, "Молодец. Ты проучил племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места." } }, f = { { 0.00, "Молодец. Ты проучила племя Дыбогривов. Теперь они дважды подумают, прежде чем осквернять святые для нас места." } } } } },
    [834] = { d = 35.0, v = "goblin-male", n = { x = 388 }, c = { x = { { 0.00, "Я – Резлак, один из ребят Газлоу. Шеф послал меня на помощь оркам в Дуротаре. Всё бы хорошо, если бы не проблемы с караванами." }, { 8.51, "Точнее, с охраной караванов. Как ты думаешь, можно ли работать, когда караваны всё время грабят?" }, { 15.45, "Последний караван – они мне клялись, что он-то уж точно дойдёт! – перехватили гарпии Пыльного Ветра в... как же его... Каньоне Колючего Ветра!" }, { 25.11, "А мне этот груз позарез нужен, я без него как без рук!" }, { 29.03, "Ступай по большому каньону на юг, там будет расселина, идущая с запада на восток..." } } }, t = { d = 9.6, v = "goblin-male", n = { x = 104 }, c = { x = { { 0.00, "О, то что надо! Наши припасы! Замечательно." }, { 3.05, "Я смогу снова взяться за работу, как только найду кого-нибудь, кто донесёт мне эти мешки." } } } } },
    [835] = { d = 30.8, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "Газлоу мне как-то сказал: \"Резлак, запомни одну вещь: если хочешь, чтобы что-то было сделано хорошо, сделай это сам\"." }, { 8.30, "Мы не можем и дальше терять караваны. Я вынужден взять дело в собственные руки." }, { 13.80, "Сухая лощина находится в восточной части Каньона Колючего Ветра. Если перебить всех тамошних гарпий, дороги станут безопасными." }, { 23.00, "Разумеется, Газлоу учил меня и другому: \"За соответствующую плату тебе сделают что угодно\". Ну что, возьмёшься?" } } }, t = { d = 25.9, v = "goblin-male", n = { x = 293 }, c = { x = { { 0.00, "Ну всё, теперь нашим караванам больше ничто не угрожает! Наконец-то я вздохну свободно." }, { 5.98, "Твоя помощь пришлась как нельзя вовремя: со следующим караваном мне должны прислать партию занятных безделушек!" }, { 14.13, "Ты, своё дело знаешь. Обратись к моему шефу в Кабестане. У него наверняка найдётся для тебя работёнка." }, { 21.50, "Ах да, не беспокойся, разумеется, я тебе заплачу за труды!" } } } } },
    [837] = { d = 33.9, v = "orc-male#60", n = { x = 382 }, c = { x = { { 0.00, "Когда мы поселились здесь, свинобразы Иглогривых владели большей частью этих земель и оказались сущей напастью!" }, { 8.59, "Большую их часть нам мало-помалу удалось вытеснить, но в некоторых районах они окопались прочно." }, { 15.67, "Однако, с нас довольно! Ради нашей безопасности мы не можем больше терпеть присутствие Иглогривых в наших землях." }, { 23.61, "Их лагеря – к западу отсюда. Они часто прячутся в зарослях колючек." }, { 28.25, "Сегодня мы вытесним их из Дуротара – а завтра, глядишь, и из всего Калимдора!" } } }, t = { d = 14.2, v = "orc-male#60", n = { x = 165 }, c = { x = { { 0.00, "Я расскажу всем, что Иглогривы прогнаны со своих обжитых мест, и что их жилища надо сжечь." }, { 6.37, "Теперь, когда племя Иглогривых изгнано из Дуротара, границы нашей новой родины станут значительно безопаснее." } } } } },
    [840] = { d = 17.0, g = 1, v = "orc-male", n = { m = 179, f = 181 }, c = { m = { { 0.00, "Хм, слабаком тебя не назовёшь…" }, { 2.76, "Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс." }, { 12.30, "Передай Каргалу это письмо о найме – возможно, он его подпишет." } }, f = { { 0.00, "Хм, слабенькой тебя не назовёшь…" }, { 2.68, "Послушай, моему приятелю Каргалу нужны новобранцы для службы в Степях. Ты ведь хочешь принести пользу Орде? Ну вот, это твой шанс." }, { 12.21, "Передай Каргалу это письмо о найме – возможно, он его подпишет." } } }, t = { d = 14.2, v = "orc-male#60", n = { x = 130 }, c = { x = { { 0.00, "А, так тебя Такрин прислал? Он отличный разведчик, не знаю даже, что бы я без него делал…" }, { 8.19, "Письмо-то я подпишу, но на самом деле воины нам нужны не здесь, а в Перекрёстке." } } } } },
    [842] = { d = 22.2, g = 1, v = "orc-male#60", n = { m = 242, f = 242 }, c = { m = { { 0.00, "Отнеси это подписанное письмо о найме в Перекрёсток." }, { 4.07, "Там всем заправляет – Сергра Чёрный Шип, лопни её шкура!" }, { 8.11, "Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое." }, { 14.57, "Тралл уверен, что она замечательная, но мне что-то так не кажется. Так что разбирайся сам, парень..." } }, f = { { 0.00, "Отнеси это подписанное письмо о найме в Перекрёсток." }, { 4.07, "Там всем заправляет – Сергра Чёрный Шип, лопни её шкура!" }, { 8.11, "Противная шаманка, заговорит тебя до посинения, прежде чем даст сделать что-нибудь толковое." }, { 14.57, "Тралл уверен, что она замечательная, но мне что-то так не кажется. Так что разбирайся сама, детка..." } } }, t = { d = 27.1, v = "orc-female", n = { x = 275 }, c = { x = { { 0.00, "Ладно. Не хочешь есть свой хлеб в Орде даром? Что ж, дел у нас предостаточно. Просто слушай внимательно и делай, что тебе скажут." }, { 11.00, "Имей в виду, я по глазам вижу, что у тебя на уме. Наглости я не спущу!" }, { 15.97, "Тралл самолично заявил, что в Орде женщины во всём будут наравне с вами, мужиками." }, { 21.80, "Только попробуй проявить ко мне неуважение – узнаешь, почём фунт лиха!" } } } } },
    [843] = { d = 39.5, v = "tauren-male", n = { x = 370 }, c = { x = { { 0.00, "Ныне я брожу по дорогам родного края в одиночестве." }, { 4.32, "Дворфы Бейл Модана не чтят моих границ." }, { 8.43, "Они постоянно устраивают взрывы, после которых остаются огромные ямы, а шумные механизмы разрывают мои холмы." }, { 17.97, "Земли, некогда приютившие и питавшие моё племя, захвачены вредоносными дворфами." }, { 24.70, "Все попытки решить дело миром провалились. Пришло время для решительных действий." }, { 31.45, "Выгони дворфов из раскопа в Бейл Модане и принеси мне записи Хазгорма, их главаря." } } }, t = { d = 18.1, v = "tauren-male", n = { x = 172 }, c = { x = { { 0.00, "Хазгорм заслужил свою судьбу. Мне нисколько его не жаль. Он явился в наши края незванным." }, { 7.39, "Быть может, его смерть послужит предостережением тем, кто пытается нарушить наш покой." }, { 14.66, "Дай-ка я изучу записи этого дворфа..." } } } } },
    [844] = { d = 14.8, v = "orc-female", n = { x = 164 }, c = { x = { { 0.00, "Первое задание будет совсем простым." }, { 2.99, "Равнинные долгоноги, живущие к востоку отсюда, разоряют наши продовольственные склады – просто сил уже нет!" }, { 10.73, "Перебей несколько долгоногов и принеси мне их клювы." } } }, t = { d = 12.0, v = "orc-female", n = { x = 135 }, c = { x = { { 0.00, "Хорошо. Долгоногов перебили, и нам будет проще доставлять продовольствие." }, { 5.11, "Надеюсь, и ты кое-чему научился, потому что следующая дичь не такая смирная, как долгоноги..." } } } } },
    [845] = { d = 24.2, v = "orc-female", n = { x = 262 }, c = { x = { { 0.00, "Хотя жевры – не самые страшные звери в Степях, они посильнее равнинных долгоногов." }, { 5.78, "Не беспокойся, в своё время тебе и покрупнее дичь достанется, но пока тебе ещё надо малость поточить зубки." }, { 13.77, "Поохоться на жевр на севере и на юге и собери их копыта." }, { 18.15, "Принеси их мне, и, быть может, в следующий раз мы дадим тебе задание посерьёзнее." } } }, t = { d = 14.1, v = "orc-female", n = { x = 141 }, c = { x = { { 0.00, "Неплохо. У жевр сильные ноги. Одного меткого удара достаточно, чтобы отшвырнуть таурена в сторону!" }, { 8.46, "Похоже, в тебе тоже силы хватает. Ну что, готов пройти настоящее испытание?" } } } } },
    [846] = { d = 39.8, v = "tauren-male", n = { x = 381 }, c = { x = { { 0.00, "Очевидно, что шахтёры не могут обойтись без взрывчатки и шумных землеройных машин." }, { 6.52, "Мы думаем, что скоро туда направят нового старшину." }, { 10.86, "Пусть проклятые дворфы отведают собственного угощения." }, { 15.19, "Согласно схемам, если смешать нитроглицерин с древесной сердцевиной и натриевой селитрой, получится взрывной заряд." }, { 26.64, "Все компоненты есть у ружейников, солдат и офицеров из Крепости." }, { 32.54, "Собери всё необходимое и принеси мне. Я создам заряд, который дворфы не скоро забудут!" } } }, t = { d = 7.7, g = 1, v = "tauren-male", n = { x = 64 }, c = { m = { { 0.00, "Вижу, ты зря времени не терял, герой." }, { 3.35, "Очень скоро дворфов ожидает неприятный сюрприз!" } }, f = { { 0.00, "Вижу, ты зря времени не терял, героиня." }, { 3.47, "Очень скоро дворфов ожидает неприятный сюрприз!" } } } } },
    [848] = { d = 25.6, v = "scourge-male", n = { x = 242 }, c = { x = { { 0.00, "Оазисы Степей таят в себе тайну. В их водах разлита энергия жизни, питающая и укрепляющая растения и животных. И меняющая их." }, { 12.13, "Неподалёку от этих оазисов растёт вид грибов, чьи споры мы, аптекари Лордерона, используем при создании снадобий." }, { 20.93, "Принеси мне эти споры – и благодарность наша будет велика." } } }, t = { d = 10.6, v = "scourge-male", n = { x = 91 }, c = { x = { { 0.00, "Ах, да. Прекрасный материал. Действенный." }, { 4.35, "Я из Отрёкшихся, а мы исполняем свои обещания. Вот твоё вознаграждение." } } } } },
    [849] = { d = 37.0, v = "tauren-male", n = { x = 343 }, c = { x = { { 0.00, "Изучив схемы Хазгорма, можно без труда создать взрывчатку. Ну вот, готово." }, { 6.22, "А теперь, я дам тебе особое задание. Возьми взрывчатку и подорви летающую машину в Бейл Модане." }, { 15.48, "Эта машина не просто играет ключевую роль в снабжении раскопок, она служит и для военных целей." }, { 23.72, "И что ещё важнее – она воплощение мощи дворфов и оскорбление памяти моего племени." }, { 30.48, "Выполни это задание, и я буду гордиться тобой! Ну и награду ты тоже получишь." } } }, t = { d = 12.0, v = "tauren-male", n = { x = 106 }, c = { x = { { 0.00, "Отличная работа. В Громовом Утёсе тебя будут чтить как защитника священных земель тауренов и поборника исчезнувшего племени." } } } } },
    [850] = { d = 33.9, v = "orc-male#60", n = { x = 383 }, c = { x = { { 0.00, "Сотни лет кентавры вставали на пути тауренов. В последнее время клан Колкар начал всерьёз грозить безопасности Степей." }, { 8.39, "Раньше им мешала побеждать их собственная неорганизованность, но недавно среди них появились новые вожди." }, { 15.90, "Они создали из своих сородичей войско." }, { 19.05, "Чтобы сохранить наши земли, мы должны убить вождей кентавров." }, { 23.76, "Принеси мне голову Барака Кодобоя. Он живёт в лагере неподалёку от Забытых прудов на севере." }, { 30.67, "Когда одержишь над ним верх, возвращайся." } } }, t = { d = 13.1, v = "orc-male#60", n = { x = 141 }, c = { x = { { 0.00, "Молодец. Кентавры – примитивные и грубые создания, но некоторым из них была дарована мудрость и умение вести в бой. Они-то опаснее прочих." }, { 9.92, "Барак таким и был. Хорошо, что он мёртв." } } } } },
    [851] = { d = 30.4, v = "orc-male#60", n = { x = 342 }, c = { x = { { 0.00, "Кентавр Верог Дервиш бродит по Пустошам, и найти его будет нелегко." }, { 4.75, "Живёт же он в командном шатре кентавров, в Застывшем оазисе на юго-востоке. Быть может, удастся заманить его туда." }, { 13.08, "Отправляйся в Застывший оазис и напади на кентавров рядом с командным шатром." }, { 18.45, "Это опасно, но если убить достаточно кентавров, кто-нибудь поднимет тревогу и явится Верог." }, { 25.25, "Принеси мне его голову, и я помещу её рядом с головой Барака Кодобоя." } } }, t = { d = 14.9, g = 1, v = "orc-male#60", n = { m = 171, f = 172 }, c = { m = { { 0.00, "Замечательно. Видно, ты взбаламутил кентавров – стражи заметили необычную активность неподалёку от Застывшего оазиса. Наверное, это твоя работа." }, { 10.30, "Можешь гордиться своим подвигом. Ты необыкновенно отважен." } }, f = { { 0.00, "Замечательно. Видно, ты взбаламутила кентавров – стражи заметили необычную активность неподалёку от Застывшего оазиса. Наверное, это твоя работа." }, { 10.37, "Можешь гордиться своим подвигом. Ты необыкновенно отважна." } } } } },
    [852] = { d = 23.7, g = 1, v = "orc-male#60", n = { m = 255, f = 257 }, c = { m = { { 0.00, "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жёсток и хитёр." }, { 6.51, "Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам." }, { 13.43, "Итак, убей его. Принеси мне его голову, как принёс головы Барака и Верога." }, { 19.02, "Он управляет своим народом из Цветущего оазиса на юге." } }, f = { { 0.00, "Хэрзул Кровавая Отметина – глава кентаврского клана Колкар в Степях. Он свиреп, жёсток и хитёр." }, { 6.51, "Одолев его, ты нанесёшь серьёзный урон всем Колкар, а значит, они станут меньше угрожать нам." }, { 13.43, "Итак, убей его. Принеси мне его голову, как принесла головы Барака и Верога." }, { 19.15, "Он управляет своим народом из Цветущего оазиса на юге." } } }, t = { d = 13.1, g = 1, v = "orc-male#60", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Хвала тебе. Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они всё равно свирепые противники." }, { 9.32, "Одержав над ними верх, ты доказал свою доблесть." } }, f = { { 0.00, "Хвала тебе. Хотя кентаврам не хватает дисциплины, чтобы обрушить свою ярость на врагов, как орки, они всё равно свирепые противники." }, { 9.32, "Одержав над ними верх, ты доказала свою доблесть." } } } } },
    [853] = { d = 37.3, v = "scourge-male", n = { x = 395 }, c = { x = { { 0.00, "Я сделал эмульсию из принесённых тобой спор, и теперь мне нужно доставить её моей коллеге, аптекарю Заме." }, { 7.75, "Если ты отнесёшь ей мою посылку, она предложит тебе на выбор что-нибудь из своего запаса алхимических товаров." }, { 16.37, "Она живёт в Прудах Видений, пещере, расположенной ниже обиталища шаманов Громового Утёса." }, { 23.07, "Путь к этой пещере хорошо скрыт, но начинается он на Вершине духов." }, { 28.91, "Поспеши. Эмульсия хранится не очень долго, потому надо вскрыть и использовать её до того, как она испортится." } } }, t = { d = 15.7, g = 1, v = "scourge-female", n = { x = 128 }, c = { m = { { 0.00, "А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо." }, { 8.24, "Эмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, герой." } }, f = { { 0.00, "А, споры, которые Хелбрим собрал в Степях. Он заручился твоей помощью при сборе? Хорошо." }, { 8.24, "Эмульсия не успела испортиться, видать, ты время зря не тратил. Молодец, героиня." } } } } },
    [854] = { d = 30.8, g = 1, v = "tauren-male#68", n = { m = 298, f = 299 }, c = { m = { { 0.00, "Я знал, что ты придёшь, юный герой. Хотя, пожалуй, ты уже не так юн." }, { 5.90, "Думаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения." }, { 13.40, "Ступай в Перекрёсток. Наша судьба тесно связана с судьбой орков, а им нужна помощь." }, { 19.84, "Иди по дороге на восток, а потом сверни на север, к Перекрёстку." }, { 24.76, "Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли." } }, f = { { 0.00, "Я знал, что ты придёшь, юная героиня. Хотя, пожалуй, ты уже не так юна." }, { 5.87, "Думаю, тебе пора двинуться вглубь этих земель. Я чую, что тебе предстоят великие свершения." }, { 13.37, "Ступай в Перекрёсток. Наша судьба тесно связана с судьбой орков, а им нужна помощь." }, { 19.81, "Иди по дороге на восток, а потом сверни на север, к Перекрёстку." }, { 24.74, "Отыщи Торка в стенах города, ибо с ним пребывает благословение Матери-Земли." } } }, t = { d = 6.2, v = "orc-male#60", n = { x = 70 }, c = { x = { { 0.00, "Я рад, что нам на помощь прибыли союзники из самого Громового Утёса. Добро пожаловать!" } } } } },
    [855] = { d = 18.8, v = "orc-male#60", n = { x = 203 }, c = { x = { { 0.00, "Клан Колкар угрожает завоеваниям Орды в Степях. Мы должны сократить численность их войск." }, { 6.92, "В связи с этим у меня есть для тебя задание." }, { 10.29, "Отправляйся в земли Колкар, перебей их воинов и принеси мне их наручи. Возвращайся с трофеями, и Орда тебя наградит." } } }, t = { d = 17.8, v = "orc-male#60", n = { x = 185 }, c = { x = { { 0.00, "Неплохо. Уверен, тебе удалось вселить страх в выживших кентавров." }, { 5.77, "Если Колкар не полные идиоты, теперь они успокоятся и прекратят наступление." }, { 11.51, "К сожалению, вряд ли им на это хватит ума. Что весьма плохо. Плохо для них, разумеется." } } } } },
    [857] = { d = 37.8, v = "dwarf-male", n = { x = 393 }, c = { x = { { 0.00, "Она была у меня в руках! В этих самых руках! И я хочу вернуть её! Вернуть, говорю!" }, { 5.95, "Её откопали эти грязные землекопы... и как она была прекрасна. Её назвали слеза Лун. Первое серьёзное открытие в Бейл Модане." }, { 16.42, "Она должна достаться мне! Мне, говорю!" }, { 19.52, "Генерал Двукосса позавидовал силе, которую она мне давала, и запер её в Крепости. Сказал, что эта вещь проклята. Дурак!" }, { 27.95, "Её хотели заполучить и другие, мне пришлось их остановить. А этот ублюдок Двукосса прогнал меня." }, { 34.81, "А я хочу её вернуть. Вернуть, говорю!" } } }, t = { d = 3.5, v = "dwarf-male", n = { x = 36 }, c = { x = { { 0.00, "Наконец-то сила снова со мной! Со мной, говорю!" } } } } },
    [858] = { d = 28.0, v = "goblin-male", n = { x = 316 }, c = { x = { { 0.00, "Тебя случайно не Пароклапан прислал? У меня проблемы. Я запрыгнул внутрь, не подумав, что для запуска резака нужен ключ." }, { 8.30, "Один из операторов спросил меня, всё ли в порядке, и я впал в панику!" }, { 13.08, "Вместо того чтобы сказать, что я потерял ключ, я заявил, что резак неисправен." }, { 18.85, "Надо поскорее выбираться отсюда! Поднимись в комнату управления на вышке, у бригадира должен быть ключ от резака. Выручи меня!" } } }, t = { d = 24.2, v = "goblin-male", n = { x = 253 }, c = { x = { { 0.00, "Ага, похоже, ключ подходит. Ну-ка, знаю ли я, как управлять этой штуковиной…" }, { 5.60, "Хм... Управление вращением... Этот рычаг отвечает за скорость и равновесие... Управление манипулятором. Ну и ну!" }, { 15.03, "Поверить не могу, что Торговая Компания создала устройство, которое настолько лучше нашего. Надо доставить этот резак в Кабестан!" } } } } },
    [860] = { d = 36.7, v = "tauren-male#68", n = { x = 372 }, c = { x = { { 0.00, "Ежели хочешь вступить на путь охотника, то тогда тебе надо идти в Степи. Тамошние твари упрямы и яростны." }, { 8.26, "Охотясь там, ты многому научишься, и дух твой окрепнет." }, { 13.27, "Поговори с Сергрой Чёрный Шип. Она будет первой твоей наставницей в Степях." }, { 19.47, "Сергра сейчас в Перекрёстке. Чтобы туда добраться, иди на восток от Деревни Кровавого Копыта прямиком в Степи, затем на развилке сверни на север." }, { 30.44, "И по дороге держи ухо востро – Степи весьма опасны для неопытных и беспечных." } } }, t = { d = 21.2, v = "orc-female", n = { x = 222 }, c = { x = { { 0.00, "Хочешь охотиться в Степях?" }, { 2.29, "Глаза у тебя горячие и молодые. Они ещё не окосели от выслеживания добычи на тутошних пыльных равнинах." }, { 9.91, "Но ты не бойся. Мы закалим твоё тело и дух! И растолкуем, что охота – не просто выслеживание и добыча." }, { 17.51, "Готовься. Твой путь начинается прямо сейчас." } } } } },
    [861] = { d = 39.2, g = 1, v = "tauren-male", n = { m = 371, f = 369 }, c = { m = { { 0.00, "Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий…" }, { 6.06, "Странствий и охоты. Ведь охота – первая доблесть таурена." }, { 11.73, "Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги." }, { 20.25, "Он живёт в Громовом Утёсе, на вершине Охотников." }, { 24.29, "Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья." }, { 30.41, "Эти звери сильны и хитры – подходящая добыча для молодого героя, избравшего путь охотника." } }, f = { { 0.00, "Вижу, ты любишь путешествовать. Когда-то и меня обуревала жажда странствий…" }, { 6.06, "Странствий и охоты. Ведь охота – первая доблесть таурена." }, { 11.73, "Если ты в самом деле желаешь избрать путь охотника, Мелор Каменное Копыто поможет тебе сделать первые шаги." }, { 20.25, "Он живёт в Громовом Утёсе, на вершине Охотников." }, { 24.29, "Чтобы показать свою решимость и умения, принеси ему когти хищника плоскогорья." }, { 30.41, "Эти звери сильны и хитры – подходящая добыча для молодой героини, избравшей путь охотника." } } }, t = { d = 25.8, v = "tauren-male#68", n = { x = 231 }, c = { x = { { 0.00, "Скорн Белое Облако – мудрый таурен. Он посвятил охоте много лет, и хотя уже слаб телом, дух его по-прежнему бодр. Мы высоко чтим его." }, { 12.28, "Если тебя и правда прислал Скорн, то он разглядел в тебе будущего охотника. Добыть же эти когти было непросто, я знаю." }, { 21.69, "Быть может, тебе пора вступить на избранный путь." } } } } },
    [862] = { d = 29.0, g = 1, v = "orc-male#60", n = { x = 308 }, c = { m = { { 0.00, "Должно быть, герою вроде тебя в Степях голодно. Я вот постоянно хочу есть." }, { 5.52, "Знаешь, приготовлю-ка я тебе отличную похлёбку. Для этого мне понадобится несколько пещерных крыс." }, { 12.83, "Похоже, эти грязные дворфы в Бейл Модане увлечены празднованием." }, { 17.30, "Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс." }, { 23.51, "Тебе не стать закалённым бойцом, пока не набьёшь руку на крысах! Ха-ха!" } }, f = { { 0.00, "Должно быть, героине вроде тебя в Степях голодно. Я вот постоянно хочу есть." }, { 5.69, "Знаешь, приготовлю-ка я тебе отличную похлёбку. Для этого мне понадобится несколько пещерных крыс." }, { 12.99, "Похоже, эти грязные дворфы в Бейл Модане увлечены празднованием." }, { 17.46, "Так что ступай в Бейл Модан, это на юге, и принеси мне несколько пещерных крыс." }, { 23.68, "Тебе не стать закалённым бойцом, пока не набьёшь руку на крысах! Ха-ха!" } } }, t = { d = 16.5, v = "orc-male#60", n = { x = 177 }, c = { x = { { 0.00, "Обычно я не ем этих грызунов, пока они такие... такие... свежие. Им надо полежать несколько недель, чтобы мяско стало с душком. Но ты, похоже, голоден." }, { 10.52, "Дай-ка я сварю тебе похлёбку из пещерных крыс. Ну вот, готово. Кушай на здоровье!" } } } } },
    [863] = { d = 8.1, v = "goblin-male", n = { x = 86 }, c = { x = { { 0.00, "Полагаю, я буду учиться по ходу дела... Вряд ли это так сложно. Тут пара кнопок, там рычаг-другой. Ну что, поехали?" } } }, t = { d = 14.2, v = "goblin-male", n = { x = 145 }, c = { x = { { 0.00, "Надеюсь, нам удастся найти что-нибудь ценное в этом поломанном образце крошшера... Время на исходе!" }, { 6.75, "Я отправлю спасательную экспедицию на помощь к Визлкранку. А, вот тебе за труды." } } } } },
    [865] = { d = 25.9, v = "goblin-male", n = { x = 268 }, c = { x = { { 0.00, "Ящеры Степей умнее, чем прочие. Мне кажется, весь ум в рогах!" }, { 5.07, "Если так, эти рога можно стереть в порошок и сделать из них \"умный напиток\". Я мог бы продавать его за баснословные деньги!!!" }, { 14.05, "Ты можешь мне помочь. Принеси мне целые рога ящерочешуйчатых смертехватов." }, { 19.29, "Они живут в южной части Степей и на севере, рядом с границей Ясеневого леса." } } }, t = { d = 6.6, v = "goblin-male", n = { x = 67 }, c = { x = { { 0.00, "Здорово, тебе удалось их добыть! Остаётся стереть рога в порошок, смешать с вином и..." } } } } },
    [866] = { d = 28.0, v = "goblin-male", n = { x = 310 }, c = { x = { { 0.00, "Таких трав, как в Степях, нет нигде." }, { 2.46, "Свойства у них по большей части те же, но вода оазисов оказывает на них особое влияние, и они всё же отличаются от подобных им, хоть и не сильно." }, { 12.87, "Я хочу выяснить, в чём же состоит разница... и нельзя ли ей воспользоваться!" }, { 18.37, "Если ты владеешь искусством травничества, собери для меня образцы корней растений Степей, и я сравню их с травами из других регионов." } } }, t = { d = 17.4, g = 1, v = "goblin-male", n = { m = 188, f = 188 }, c = { m = { { 0.00, "Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства..." }, { 9.61, "И не беспокойся – ты узнаешь об этом первым. Потому что в таком случае мне понадобится много корней!" } }, f = { { 0.00, "Да-да, замечательно! Из этих корней я выращу травы и смогу изучить их. Надеюсь отыскать в них новые свойства. Скрытые ценные свойства..." }, { 9.61, "И не беспокойся – ты узнаешь об этом первой. Потому что в таком случае мне понадобится много корней!" } } } } },
    [867] = { d = 30.6, v = "orc-male", n = { x = 342 }, c = { x = { { 0.00, "Нет сил терпеть нападения на наши караваны со съестными припасами." }, { 4.85, "Пора сократить число проклятых гарпий, перерезав горло десятку-другому." }, { 10.22, "Я пробрался к их гнёздам и выяснил, кто есть кто. Начать надо с низов, а потом постепенно пробиваться наверх." }, { 18.26, "Для начала займись гарпиями и разбойницами из стаи Зачарованного Крыла, поселившимися на северо-западе, и принеси мне восемь когтей Зачарованного Крыла. Будет уже неплохо..." } } }, t = { d = 9.6, v = "orc-male", n = { x = 100 }, c = { x = { { 0.00, "Прекрасные когти. Чудные. Отличная работа. Надеюсь, в ближайшем будущем мне снова доведётся полюбоваться на твою работу." } } } } },
    [868] = { d = 31.9, v = "troll-male#78", n = { x = 376 }, c = { x = { { 0.00, "Эй. Меня отправили в Перекрёсток присматривать за этими землями и сообщать начальству в Оргриммаре, что тут творится." }, { 8.18, "В частности, мне велено наблюдать за насекомовидными тварями на юге в Полях Великанов." }, { 13.92, "Нам о них почти ничего не известно, а я хотел бы узнать о них побольше. Кажется, они умнее обычных животных." }, { 21.62, "Возьми вспарывающий коготь и принеси несколько яиц этих тварей из их курганов, но будь осторожнее: они нападут на тебя, если заметят, что ты творишь." } } }, t = { d = 3.3, v = "troll-male#78", n = { x = 36 }, c = { x = { { 0.00, "Порадовал ты меня. Молодец. Вот твоя награда..." } } } } },
    [869] = { d = 28.6, v = "orc-male", n = { x = 291 }, c = { x = { { 0.00, "Недавно из сторожевой башни был похищен груз серебра. Он предназначался в уплату стражам Перекрёстка, и его необходимо вернуть." }, { 9.23, "Самое странное... одного из воров мы поймали с поличным. И... это оказался ящер! Немыслимо!" }, { 17.50, "Не знаю, зачем ящерам серебро. Мне всё равно: главное, чтобы у нас не воровали. Пусть сдохнут!" }, { 24.51, "Отправляйся на охоту в Степи. Принеси мне их головы!" } } }, t = { d = 5.1, g = 1, v = "orc-male", n = { x = 48 }, c = { m = { { 0.00, "Тебе удалось избавить нас от ящеров! Спасибо. Ты – достойный герой." } }, f = { { 0.00, "Тебе удалось избавить нас от ящеров! Спасибо. Ты – достойный героиня." } } } } },
    [870] = { d = 41.2, v = "tauren-male", n = { x = 415 }, c = { x = { { 0.00, "Давным-давно Степи были цветущим садом, полным жизни." }, { 4.59, "Но этих земель коснулась карающая десница войны и катаклизма, обратив их в высохшую пустыню." }, { 11.93, "Это наполняет моё сердце грустью, но так уж получилось." }, { 16.74, "Впрочем, в последние годы в Степях образовалось несколько новых оазисов, а в них появилась жизнь." }, { 24.24, "Мы, друиды, чувствуем, что из глубины к поверхности рвётся какая-то сила." }, { 30.31, "Мы должны обнаружить её источник. Отправляйся к Забытым прудам, к северу от Перекрёстка." }, { 37.17, "Отыщи в воде источник силы и возвращайся сюда." } } }, t = { d = 16.1, v = "tauren-male", n = { x = 144 }, c = { x = { { 0.00, "Там есть расселина, из которой выходят пузырьки газа? Странно. Может быть, это и есть ответ на наши вопросы, но уверенности нет." }, { 11.23, "Впрочем, хоть какая-то зацепка. Спасибо, что нашёл её." } } } } },
    [871] = { d = 34.0, v = "orc-male#60", n = { x = 377 }, c = { x = { { 0.00, "Все свинобразы – наши враги. Просто одни из них причиняют нам больше неприятностей, чем другие." }, { 7.02, "Клан Иглогривых в последнее время нередко нападает на наши караваны из Дуротара, и терпеть это нет больше сил." }, { 14.77, "Мои разведчики ищут главарей, но тем временем чем больший урон мы нанесём эти свиньям, тем лучше." }, { 22.51, "Ступай на северо-восток, по направлению к Дуротару. Ты легко отыщешь их логова среди огромных колючих побегов, исходящих из земли. Отыщи их и убей, кого сможешь." } } }, t = { d = 5.8, v = "orc-male#60", n = { x = 66 }, c = { x = { { 0.00, "Отличная работа. Мерзавцы-иглоривы наконец-то научатся считаться с мощью Орды." } } } } },
    [872] = { d = 30.4, v = "orc-male#60", n = { x = 349 }, c = { x = { { 0.00, "Один из разведчиков своими глазами видел нападение на караван из Дуротара. Естественно, виноваты свинобразы из племени Иглогривых." }, { 9.24, "Возглавляет нападения Криниг Грознорыл. Его видели на северо-востоке отсюда, южнее дороги на Дуротар. Пока Криниг жив, покоя не будет." }, { 18.88, "Но чтобы окончательно прекратить разбой, надо как следует унизить мерзких иглогривов." }, { 24.90, "Убей Кринига Грознорыла и его приспешников и принеси мне его клык." } } }, t = { d = 7.3, v = "orc-male#60", n = { x = 82 }, c = { x = { { 0.00, "Молодец. Криниг мёртв, и число нападений на караваны сократится. Твой народ должен гордиться тобой." } } } } },
    [873] = { d = 36.8, g = 1, v = "tauren-female", n = { m = 328, f = 329 }, c = { m = { { 0.00, "Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость." }, { 7.02, "Народ побережья страшится его, ибо он поглотил многих из их числа." }, { 12.85, "Но я не боюсь его. Я благодарен провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник." }, { 23.13, "Если ты готов, плыви на поиски Иши Авака, Рока Глубин." }, { 29.04, "Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе." } }, f = { { 0.00, "Великий Иша Авак – повелитель этих вод. Велика его сила, несокрушима гордость." }, { 7.02, "Народ побережья страшится его, ибо он поглотил многих из их числа." }, { 12.85, "Но я не боюсь его. Я благодарен провидению за то, что он есть. Бросить ему вызов – высокая честь, ибо он достойный противник." }, { 23.13, "Если ты готова, плыви на поиски Иши Авака, Рока Глубин." }, { 28.48, "Его дух содержится в сердце, и услышав, как оно бьётся, можно узнать многое о своей судьбе." } } }, t = { d = 10.1, v = "tauren-female", n = { x = 93 }, c = { x = { { 0.00, "Теперь вы с Иши Аваком едины. Его дух живёт в тебе. Он таится в твоих глазах…" }, { 6.51, "Глазах, которые однажды научатся видеть." } } } } },
    [874] = { d = 35.1, g = 1, v = "tauren-male#67", n = { m = 269, f = 270 }, c = { m = { { 0.00, "Ты поохотился на многих зверей Степей. Дух твой твёрд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его. И даже море." }, { 18.21, "Найди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя." }, { 28.11, "Ищи её с осторожностью, потому что побережье Степей захвачено людьми." } }, f = { { 0.00, "Ты поохотилась на многих зверей Степей. Дух твой твёрд. Но охотник должен быть готов ко всему, его не смутит никакой путь. Горы и болота не испугают его. И даже море." }, { 16.54, "Найди мою сестру, Марен. Она охотится на огромных водных тварей на побережье и многому научит тебя." }, { 26.44, "Ищи её с осторожностью, потому что побережье Степей захвачено людьми." } } }, t = { d = 15.4, g = 1, v = "tauren-female", n = { m = 136, f = 137 }, c = { m = { { 0.00, "Тебя прислал мой брат? Должно быть, ты произвёл на него впечатление. А если тебя зауважал Джорн, то и я буду уважать." }, { 10.83, "Желаешь ли ты сделать следующий шаг на пути охотника?" } }, f = { { 0.00, "Тебя прислал мой брат? Должно быть, ты произвела на него впечатление. А если тебя зауважал Джорн, то и я буду уважать." }, { 10.09, "Желаешь ли ты сделать следующий шаг на пути охотника?" } } } } },
    [875] = { d = 33.1, g = 1, v = "orc-male", n = { m = 355, f = 356 }, c = { m = { { 0.00, "Ха-ха-ха. Ещё захотелось? Отлично, приятно слышать." }, { 5.04, "На сей раз я хочу, чтобы ты убил несколько лейтенантов гарпий в Сухих холмах." }, { 10.43, "Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам." }, { 18.80, "Неприятные твари, да ещё и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству." }, { 27.31, "И пусть подыхают долго и мучительно. Это научит их не связываться с Ордой." } }, f = { { 0.00, "Ха-ха-ха. Ещё захотелось? Отлично, приятно слышать." }, { 5.04, "На сей раз я хочу, чтобы ты убила несколько лейтенантов гарпий в Сухих холмах." }, { 10.56, "Лейтенантами бывают только душегубки из стаи Зачарованного Крыла. Их можно отличить от других по характерным кольцам." }, { 18.92, "Неприятные твари, да ещё и приспешников их там полно. Убей шестерых и нанеси мощный удар по этому бабьему царству." }, { 27.44, "И пусть подыхают долго и мучительно. Это научит их не связываться с Ордой." } } }, t = { d = 5.6, v = "orc-male", n = { x = 55 }, c = { x = { { 0.00, "Прекрасная работа. Думаю, ты достигнешь высокого положения в Орде." } } } } },
    [876] = { d = 33.2, g = 1, v = "orc-male", n = { m = 373, f = 374 }, c = { m = { { 0.00, "Ты так хорошо справился с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение." }, { 7.27, "Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар." }, { 14.32, "Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры." }, { 20.92, "Перережь ей горло и принеси мне её голову. Я хочу прибить её на переднюю телегу следующего каравана..." }, { 27.91, "Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас." } }, f = { { 0.00, "Ты так хорошо справилась с лейтенантами и приспешниками, что я хочу дать тебе ещё одно поручение." }, { 7.30, "Серена Кровавое Перо – сестра гарпии по имени Кровавое Перо, которую давным-давно прикончил Рексар." }, { 14.35, "Очевидно, что нападения на обозы Орды обусловлены желанием отомстить за смерть сестры." }, { 20.95, "Перережь ей горло и принеси мне её голову. Я хочу прибить её на переднюю телегу следующего каравана..." }, { 27.94, "Пусть проклятые гарпии задумаются, прежде чем снова нападать на нас." } } }, t = { d = 16.5, v = "orc-male", n = { x = 164 }, c = { x = { { 0.00, "ХА! Молодец! Отличная работа... Я не был уверен, что ты справишься с заданием, но, оказывается, ты головорез, каких поискать." }, { 10.23, "Ещё раз спасибо за избавление от нашествия гарпий. Вот награда, используй её с умом." } } } } },
    [877] = { d = 30.8, v = "tauren-male", n = { x = 286 }, c = { x = { { 0.00, "Быть может, и в других оазисах Степей есть расселины вроде той, что тебе удалось обнаружить в Забытых прудах?" }, { 8.65, "Коли так, скорее всего именно эти расселины – источник жизни оазисов. Надо проверить." }, { 16.35, "Вот, возьми эти семена. Сейчас они мёртвые и бесплодные. Отнеси их в Застывший оазис на юго-востоке." }, { 25.77, "Если там есть расселина, помести в неё семена... и понаблюдай." } } }, t = { d = 16.0, v = "tauren-male", n = { x = 143 }, c = { x = { { 0.00, "Удивительное открытие! Я дал тебе иссохшие, мёртвые семена. Значит, то, что таится в этих оазисах, создаёт жизнь из ничего!" }, { 11.71, "Необходимо исследовать это явление повнимательнее..." } } } } },
    [878] = { d = 57.4, v = "named/3430", n = { x = 358 }, c = { x = { { 0.00, "Отомсти моим врагам. *фыркает* Помоги Кривозубу и Иглогривым, ослабив племя Дыбогривов." }, { 10.60, "Оба племени духовно связаны с землёй и её мощью. *фыркает* Она дарует нам силу, необходимую для всего... и прежде всего – для войны." }, { 29.57, "Если ты в самом деле хочешь узнать, кто причинил Торку и Орде так много страданий, помоги Кривозубу!" }, { 41.81, "Напади на духовных вождей Дыбогривов на севере; подорви их мощь, чтобы Иглогривые одолели своих соперников и покорили Степи." } } }, t = { d = 44.2, g = 1, v = "named/3430", n = { x = 268 }, c = { m = { { 0.00, "Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, герой." }, { 14.03, "Но нет, радости нет места. фыркает" }, { 18.99, "Ты помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него." }, { 30.87, "Его забыли, оставили гнить в клетке!" }, { 35.63, "Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!" } }, f = { { 0.00, "Да-да... Меня должна переполнять радость, фыркает ведь племя Дыбогривов испытало ту же боль, что и мой народ, героиня." }, { 14.11, "Но нет, радости нет места. фыркает" }, { 19.07, "Ты помогаешь своим, и они чтят тебя. Кривозуб помогает своим – и что же? Они отвернулись от него." }, { 30.95, "Его забыли, оставили гнить в клетке!" }, { 35.71, "Я помогал им даже из-за решётки, но никто не пришёл мне на помощь!" } } } } },
    [879] = { d = 66.7, g = 1, v = "named/3430", n = { x = 386 }, c = { m = { { 0.00, "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, герой." }, { 11.26, "*фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир..." }, { 27.81, "*фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*" }, { 40.46, "Имена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей." }, { 49.36, "Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин." }, { 61.63, "Убей их, герой, как они убили меня." } }, f = { { 0.00, "Из Лабиринтов вышли трое моих соплеменников, чтобы возглавить набеги на Орду, героиня." }, { 10.56, "*фыркает* Они отличаются жестокостью и хитростью, и если одолеть их, то в Перекрёстке и в большей части Степей воцарится мир..." }, { 27.11, "*фыркает* по крайней мере, племя Иглогривых не будет на вас нападать. *фыркает*" }, { 39.76, "Имена этих главарей – Нак, Куз и Лок Оркобой. Они укрылись на юге Степей." }, { 48.66, "Один из них заклинатель, другой следопыт, а главный из них – тот, кого называют Оркобоем – *фыркает* воин." }, { 60.93, "Убей их, героиня, как они убили меня." } } }, t = { d = 23.3, g = 1, v = "named/3430", n = { x = 139 }, c = { m = { { 0.00, "Дело сделано. Кривозуб считает, уж лучше так." }, { 5.66, "фыркает Надо было убедиться фыркает, что я мёртв, а не бросать меня здесь, во всеми забытой клетке." }, { 18.35, "Тебе осталось лишь одно дело, герой." } }, f = { { 0.00, "Дело сделано. Кривозуб считает, уж лучше так." }, { 5.66, "фыркает Надо было убедиться фыркает, что я мёртв, а не бросать меня здесь, во всеми забытой клетке." }, { 18.35, "Тебе осталось лишь одно дело, героиня." } } } } },
    [880] = { d = 26.9, v = "tauren-male", n = { x = 264 }, c = { x = { { 0.00, "Ты рассказываешь невероятные вещи. Источник свойств этих оазисов явно сторонний. Или, быть может, вообще потустороннй." }, { 10.43, "Я хочу узнать, какое влияние расселины оказывают на зверей, приходящий на водопой." }, { 17.29, "Убей несколько оазисных хрустогрызов в Цветущем и Застывшем оазисах. Принеси мне их панцири, и я их пристально изучу." } } }, t = { d = 19.2, v = "tauren-male", n = { x = 175 }, c = { x = { { 0.00, "Спасибо. Изучая обитателей различных мест, узнаешь немало о самих местах. Посмотрим, о чём нам поведают панцири." }, { 10.70, "Прошу тебя, прими благодарность за помощь... Быть может, эти монеты тебе не помешают. Мне они уже не нужны." } } } } },
    [881] = { d = 42.5, v = "orc-female", n = { x = 450 }, c = { x = { { 0.00, "Ичияки, Белый Туман на языке тауренов, король кошачьих саванны." }, { 4.90, "Он подкрадывается к жертвам так незаметно, что его уподобили белому туману, стелящемуся над землёй." }, { 11.83, "Убивает он одним ударом – жертва не успевает ни испугаться, ни ощутить боли." }, { 18.00, "Таурены говорят, что он воплощает собой милосердие и смерть." }, { 22.86, "Ты узнаешь это на своём опыте, потому что я отправляю тебя охотиться на Ичияки." }, { 28.49, "Его логово располагается на северо-востоке от Перекрёстка, среди костей огромного кодо." }, { 35.01, "Ступай. Добравшись до логова, протруби в этот рог. Протруби в рог, и он явится на зов." } } }, t = { d = 18.6, g = 1, v = "orc-female", n = { x = 191 }, c = { m = { { 0.00, "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой." }, { 8.41, "Он научит тебя обретать силу в хитрости, а честь в милосердии." }, { 13.20, "Перед тобой долгий путь, герой. Хочется верить, что ты далеко пойдёшь." } }, f = { { 0.00, "Тебе удалось одолеть Ичияки, и хотя ему больше не суждено охотиться в саванне, дух его отныне пребудет с тобой." }, { 8.41, "Он научит тебя обретать силу в хитрости, а честь в милосердии." }, { 13.20, "Перед тобой долгий путь, героиня. Хочется верить, что ты далеко пойдёшь." } } } } },
    [882] = { d = 54.1, g = 1, v = "tauren-male#67", n = { m = 401, f = 402 }, c = { m = { { 0.00, "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия." }, { 13.05, "Охота – его страсть. Он убивает потому, что сам убийца по природе." }, { 20.26, "Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала." }, { 35.56, "Начинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мёртвому дереву на северо-западе от Кабестана." }, { 46.76, "Ишамухал почует тушу и явится на её запах. Будь готов к его появлению." } }, f = { { 0.00, "Ишамухал, или Копьезуб, – самый страшный из всех яркочешуйчатых ящеров Степей. Он охотится не ради еды и не для удовольствия." }, { 14.42, "Охота – его страсть. Он убивает потому, что сам убийца по природе." }, { 21.64, "Именно о его природе тебе и предстоит узнать многое, ибо твой путь теперь поведёт тебя по когтистым следам Ишамухала." }, { 35.52, "Начинай охоту. Убей его излюбленную добычу – жевру – и принеси его тушу к мёртвому дереву на северо-западе от Кабестана." }, { 46.73, "Ишамухал почует тушу и явится на её запах. Будь готова к его появлению." } } }, t = { d = 17.0, v = "tauren-male#67", n = { x = 136 }, c = { x = { { 0.00, "Клык – всего лишь символ, но символ очень важных вещей." }, { 5.70, "Теперь в тебе есть сила Ишамухала. Пользуйся ей, но соблюдай умеренность. Отныне это твоя ноша. И это великая честь." } } } } },
    [883] = { d = 3.8, v = "human-male#114", n = { x = 38 }, c = { x = { { 0.00, "Копыто Лакота'мани – символ силы великого кодо." } } }, t = { d = 24.7, v = "tauren-male#67", n = { x = 193 }, c = { x = { { 0.00, "Лакота'мани на нашем языке означает \"Землекрушитель\", ибо шаги его громоподобны." }, { 7.80, "Теперь он пребывает с тобой, к тебе перешло всё его мужество. Отныне ты не побоишься встретиться с любой опасностью." }, { 19.34, "Верь в себя. Верь в себя, Землекрушитель." } } } } },
    [884] = { d = 3.7, v = "human-male#114", n = { x = 36 }, c = { x = { { 0.00, "При касании от хвоста Оватанки летят искры." } } }, t = { d = 30.4, g = 1, v = "tauren-male#67", n = { m = 253, f = 254 }, c = { m = { { 0.00, "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру." }, { 12.28, "Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой." }, { 22.82, "Ныне её неутомимость передалась тебе. Теперь ты не отстал бы от Оватанки." } }, f = { { 0.00, "Имя рокочущей ящерицы Оватанки на языке тауренов означает \"синяя молния\", ведь о её стремительности не стоит судить по размеру." }, { 12.07, "Говорят, что Оватанку некогда поразила молния, и, напитавшись гневом небес, она стала воистину неутомимой." }, { 22.61, "Ныне её неутомимость передалась тебе. Теперь ты не отстала бы от Оватанки." } } } } },
    [885] = { d = 3.2, v = "human-male#114", n = { x = 28 }, c = { x = { { 0.00, "Пера Ваште Пауни больно касаться." } } }, t = { d = 55.4, g = 1, v = "tauren-male#67", n = { m = 424, f = 427 }, c = { m = { { 0.00, "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок." }, { 10.46, "Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу." }, { 23.62, "Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой." }, { 33.68, "Внутренние терзания же – следствие сожалений." }, { 38.32, "Впрочем, я вижу, что ты справился с этими искушениями и познал, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу. Ты многое познал." } }, f = { { 0.00, "Грозовой змей нечасто встречается в Степях, и его смерть может означать большую удачу или тяжкий рок." }, { 10.46, "Но смерть Ваште Пауни, что на языке тауренов означает \"кусающий дух\", не значит ни то, ни другое... Или оба сразу." }, { 21.39, "Боль, испытанная тобой во время охоты на это существо, знакома всем, кто достигает величия великой ценой." }, { 31.45, "Внутренние терзания же – следствие сожалений." }, { 36.08, "Впрочем, я вижу, что ты справилась с этими искушениями и познала, что сожаления обращаются в мудрость и лишь через страдания можно обрести силу. Ты многое познала." } } } } },
    [886] = { d = 38.7, v = "tauren-male", n = { x = 365 }, c = { x = { { 0.00, "Друиды Громового Утёса ощущают странную силу, просачивающуюся в Степи к, востоку от Мулгора." }, { 8.31, "Мы отправили найти источник этой силы Тонгу Рунического Тотэма, но, похоже, ему нужна помощь." }, { 16.06, "Отправляйся в Степи и поговори с Тонгой. Он будет в Перекрёстке. Иди туда по дороге на восток от Деревни Кровавого Копыта." }, { 26.64, "Как попадёшь в Степи, сверни на развилке на север. И продолжай идти, пока не упрёшься в Перекрёсток." }, { 34.71, "С дороги не сходи, ибо Степи – край суровый." } } }, t = { d = 17.3, g = 1, v = "tauren-male", n = { x = 148 }, c = { m = { { 0.00, "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юный герой. Ибо тайну Степей мне в одиночку не раскрыть." }, { 10.77, "Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос." } }, f = { { 0.00, "Мои собратья в Громовом Утёсе мудро поступили, прислав тебя сюда, юный героиня. Ибо тайну Степей мне в одиночку не раскрыть." }, { 11.76, "Будем надеяться, что с твоей помощью мы найдём ответ на наш вопрос." } } } } },
    [887] = { d = 28.4, v = "named/3391", n = { x = 337 }, c = { x = { { 0.00, "Жаль, что вице-адмиралу Греззлику не удалось добиться безопасности в наших водах для торговых кораблей." }, { 7.03, "В торговый флот вложено столько денег, что я просто зверею, когда пираты как нечего делать нападают на мои корабли и похищают товары!" }, { 16.42, "Говорят, что флибустьеры Южных морей разбили лагерь к югу отсюда." }, { 20.84, "Они мне как бельмо на глазу, и если ими не хочет заняться Греззлик, может быть, ты поможешь избавиться от них?" } } }, t = { d = 12.2, v = "named/3391", n = { x = 143 }, c = { x = { { 0.00, "Молодец, малыш. Побольше таких подвигов, и у меня станет одной проблемой меньше." }, { 5.30, "Хочется верить, что они решат перенести свой лагерь." }, { 9.19, "Остаётся одно – вернуть украденные товары!" } } } } },
    [888] = { d = 28.0, v = "named/3391", n = { x = 312 }, c = { x = { { 0.00, "Хоть я и хотел бы вернуть все товары, думаю, это невозможно. Но некоторые из них мне очень нужны!" }, { 6.92, "Как видишь, моя обсерватория почти готова, но ей не хватает двух малых линз." }, { 12.03, "Первая из них прибыла с караваном из Дуротара, но вторую везли на корабле, который ограбили пираты." }, { 18.99, "Кроме того, до меня так и не дошла партия сапог от Дриззлика из Пиратской бухты!" }, { 25.04, "Ступай в пиратский лагерь и поищи их." } } }, t = { d = 11.4, v = "named/3391", n = { x = 132 }, c = { x = { { 0.00, "Я так рад, что вернул своё добро! Спасибо за помощь. Знаешь, мне пригодились бы помощники вроде тебя." }, { 6.86, "Если понадобится работа, не забывай, что Газлоу неплохо платит!" } } } } },
    [890] = { d = 20.0, v = "named/3391", n = { x = 231 }, c = { x = { { 0.00, "Я уже сто лет жду последнего заказа из Пиратской бухты!" }, { 3.85, "Наверняка его перехватили флибустьеры, но на всякий случай сходи в порт и спроси у Дыбоволоса, вдруг товары без моего ведома отнесли на склад?" }, { 13.85, "Вот, отнеси мою учётную книжку Головокружилкинсу, пусть сверит со своими записями." } } }, t = { d = 13.3, v = "goblin-male", n = { x = 138 }, c = { x = { { 0.00, "А, так тебя прислал Газлоу? Минутку, дай-ка я загляну в свои записи, надо убедиться, что я не отправил товар Газлоу куда-то не туда." }, { 9.43, "Небось, он ждёт поставку сапог от Дриззлика..." } } } } },
    [891] = { d = 32.5, v = "bloodelf-male", n = { x = 377 }, c = { x = { { 0.00, "Вот и ещё один мой корабль захватили рьяные людишки из крепости Северной стражи!" }, { 6.00, "Пора разобраться с этими мерзавцами. Их паранойя перешла все мыслимые границы." }, { 11.44, "Эти безрассудные любители спускать курок стреляют во всё, что движется." }, { 16.81, "Отправляйся на юг вдоль Торгового побережья, найди их крепость и брось вызов их силе." }, { 22.83, "Принести в доказательство собственных подвигов медали их солдат." }, { 27.29, "И во имя моего флота, убей капитана Гордостанную и её рьяных канониров!" } } }, t = { d = 9.4, v = "bloodelf-male", n = { x = 103 }, c = { x = { { 0.00, "Ах, какая жалость, праведные пушки Альянса умолкли. Ты получишь награду за помощь." }, { 6.14, "Как бы теперь выручить тела наших погибших..." } } } } },
    [892] = { d = 17.9, v = "goblin-male", n = { x = 190 }, c = { x = { { 0.00, "У меня в записях всё в порядке. Ступай к Газулу и скажи, что ему не повезло." }, { 5.25, "Не удивлюсь, если его товары прибрали к рукам пираты." }, { 9.34, "Я ничем не могу ему помочь. А, да... Скажи, что у меня есть для него кое-что из Нижней шахты, пусть приходит и забирает." } } }, t = { d = 15.6, v = "named/3391", n = { x = 173 }, c = { x = { { 0.00, "Вот непруха... Наверняка это корсары... Дыбоволос тут ни при чём, я уверен, он не стал бы так меня обманывать." }, { 7.38, "В конце концов, он получает деньги за доставку." }, { 10.93, "Похоже, мне придётся вернуть себе кое-какие товары. Что скажешь?" } } } } },
    [893] = { d = 24.7, v = "orc-male", n = { x = 279 }, c = { x = { { 0.00, "Хотя говорят, что у свинобразов племени Иглогривых за Полями Великанов нет искусных кузнецов, они научились делать серьёзное оружие." }, { 9.47, "Мне хотелось бы получить несколько образцов, чтобы изучить их технику работы." }, { 15.32, "Если ты стремишься к подвигам во славу Орды, добудь для меня их оружие. Мне понадобятся кинжал, жезл и щит. Этого вполне хватит!" } } }, t = { d = 15.9, v = "orc-male", n = { x = 171 }, c = { x = { { 0.00, "Прекрасные, прекрасные образцы." }, { 2.60, "Свинобразы куда более умелый народ, чем мне казалось." }, { 6.74, "Вот, возьми это и убирайся. Мне надо получше изучить это оружие. Похоже, мы недооценивали врага, а такие ошибки недопустимы." } } } } },
    [894] = { d = 34.8, v = "goblin-male", n = { x = 401 }, c = { x = { { 0.00, "Торговая Компания устроила к северу отсюда, в юго-западной части Нефтяного болота, небольшой исследовательский центр." }, { 8.10, "Я не очень хорошо представляю, чем они занимаются, но до меня дошли сведения, что они проводят эксперименты со штукой под названием \"самофланж\"." }, { 18.36, "Что ещё за самофланж? Как бы то ни было, я хочу исследовать его, а значит, мне надо его заполучить." }, { 25.60, "Мне удалось достать копию их руководства пользователя. Почитай его, там наверняка написано, как вытащить самофланж из терминала." } } }, t = { d = 19.1, v = "goblin-male", n = { x = 221 }, c = { x = { { 0.00, "На панели управления в беспорядке разбросаны кнопки, рычаги и мигающие лампочки." }, { 5.75, "Судя по маленькому индикатору, устройство работает в оптимальном режиме, а контрольные клапаны один-три открыты." }, { 13.51, "В нижнем правом углу панели управления имеется небольшая замочная скважина." } } } } },
    [895] = { d = 20.4, v = "human-male#114", n = { x = 216 }, c = { x = { { 0.00, "РОЗЫСК!" }, { 0.96, "Разыскивается Барон Дольноберег, капитан \"Безрассудной\"." }, { 5.53, "Капитан Дольноберег из Гильнеаса водит корабли корсаров Южного моря. Он разыскивается по обвинению в пиратских нападениях." }, { 14.83, "Предоставленные останки должны быть пригодны для опознания! - Газул." } } }, t = { d = 19.5, v = "named/3391", n = { x = 224 }, c = { x = { { 0.00, "А! Вот какое у тебя дело. Знаешь, я однажды видел \"Безрассудную\" в открытом море. Впечатляющий корабль. Или судно?" }, { 7.57, "Эти моряки так придираются к словам!" }, { 10.46, "В общем, она так скользила по водной глади, что дух захватывало. Я рад, что её проклятый капитан перестанет тревожить мои корабли." } } } } },
    [896] = { d = 29.7, v = "goblin-male", n = { x = 348 }, c = { x = { { 0.00, "Хозяин причала в таком оживлённом порту, как Кабестан, держит руку на пульсе происходящего." }, { 6.34, "Я в курсе всего товарообмена между нашим городом и Пиратской бухтой." }, { 11.52, "Последние слухи касаются Каменного карьера, принадлежащего Торговой Компании, что на северо-востоке от Нефтяного болота." }, { 19.95, "Один из шахтёров нашёл изумруд размером с твой кулак." }, { 23.75, "Я знаю несколько покупателей на такой товар и готов поделиться с тобой комиссией." } } }, t = { d = 16.1, v = "goblin-male", n = { x = 177 }, c = { x = { { 0.00, "Только посмотри, какой он огромный! Теперь мы разбогатеем!" }, { 4.19, "Ну-ка, судя по расценкам на драгоценные камни, я могу прикинуть твою долю... Пятьдесят процентов, будь спок!" }, { 11.93, "Посчитаем... Да, примерно так. С тобой приятно иметь дело." } } } } },
    [897] = { d = 7.2, v = "human-male#114", n = { x = 73 }, c = { x = { { 0.00, "Это странное, похожее на насекомое существо выглядит так, будто попало в Степи случайно." } } }, t = { d = 27.0, g = 1, v = "tauren-male#67", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Я ничего не могу сказать о природе этого существа, так как его дух ушёл. Как ты уже догадался, оно не из Степей." }, { 11.95, "Я боюсь, что это может предвещать мрачное будущее нашему народу..." }, { 18.72, "Но сейчас приготовься, давай надеяться, что время раскроет тайну этого существа." } }, f = { { 0.00, "Я ничего не могу сказать о природе этого существа, так как его дух ушёл. Как ты уже догадалась, оно не из Степей." }, { 12.00, "Я боюсь, что это может предвещать мрачное будущее нашему народу..." }, { 18.77, "Но сейчас приготовься, давай надеяться, что время раскроет тайну этого существа." } } } } },
    [898] = { d = 35.7, v = "bloodelf-male", n = { x = 404 }, c = { x = { { 0.00, "Наконец-то! Кто-то пришёл мне на помощь!" }, { 3.27, "Поверить не могу, что тебе удалось пройти мимо стражей. Фанатики из Терамора совсем спятили." }, { 9.61, "Они потопили наш корабль и меня, единственного выжившего, взяли в плен. Меня назвали врагом и угрозой безопасности Альянса." }, { 18.41, "Я! Угроза великому и могучему Альянсу? Я был матросом на грузовом судне, возившем самогон из Кабестана в Пиратскую бухту." }, { 27.24, "Довольно болтать. Ты ведь поможешь мне вернуться в Кабестан? Скажи, когда решишь тронуться в путь, и мы совершим побег." } } }, t = { d = 8.3, g = 1, v = "bloodelf-male", n = { m = 91, f = 92 }, c = { m = { { 0.00, "Подумать только, мы полагали, что Огненный Цветок давно погиб!" }, { 4.65, "Ты заслужил уважение всех Тало'данских каперов." } }, f = { { 0.00, "Подумать только, мы полагали, что Огненный Цветок давно погиб!" }, { 4.65, "Ты заслужила уважение всех Тало'данских каперов." } } } } },
    [899] = { d = 31.8, g = 1, v = "orc-male#60", n = { m = 337, f = 339 }, c = { m = { { 0.00, "Быть может, тебе знакома мука неопределённости, а может, и нет." }, { 4.28, "Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ." }, { 10.60, "Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть." }, { 17.06, "Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо. Ты, герой, мог бы мне помочь." }, { 24.79, "Убей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах." } }, f = { { 0.00, "Быть может, тебе знакома мука неопределённости, а может, и нет." }, { 4.28, "Но знай: каждый день я стою здесь от восхода до заката и выискиваю взглядом этих чудовищ." }, { 10.60, "Я убил всех людей-свиней, которые попались мне на пути, но так и не смог утолить ненависть." }, { 17.06, "Быть может, мне стоило идти не на север к Перекрёстку, а в Таурахо. Ты, героиня, могла бы мне помочь." }, { 24.42, "Убей их. Убей как можно больше тварей. Принеси мне их клыки, и мы вместе попируем на их могилах." } } }, t = { d = 13.2, g = 1, v = "orc-male#60", n = { x = 135 }, c = { m = { { 0.00, "герой, ты отнёсся к моему заданию серьёзно, спасибо тебе за это." }, { 4.85, "Хотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я." } }, f = { { 0.00, "героиня, ты отнёсся к моему заданию серьёзно, спасибо тебе за это." }, { 4.85, "Хотя жажда мести не утолена, я могу хотя бы улыбаться при мысли о том, что и иглогривы испытали ту же боль, что и я." } } } } },
    [900] = { d = 10.6, v = "human-male#114", n = { x = 113 }, c = { x = { { 0.00, "В настоящий момент открыты три контрольных клапана." }, { 3.91, "Суда по надписям на панели управления, их надо закрыть, прежде чем выключать прибор." } } }, t = { d = 15.8, v = "human-male#114", n = { x = 166 }, c = { x = { { 0.00, "Лампочки, относящиеся к трём управляющим клапанам, медленно гаснут." }, { 5.38, "Зелёный огонёк становится жёлтым, и теперь можно повернуть рычаг, выключающий прибор. Клапаны закрыты, и терминал можно отключить." } } } } },
    [901] = { d = 11.2, v = "human-male#114", n = { x = 117 }, c = { x = { { 0.00, "Прибор выключен, и вы можете открыть панель управления и достать самофланж из терминала." }, { 6.69, "Всё бы хорошо, но чтобы отпереть терминал, нужен ключ." } } }, t = { d = 10.5, v = "human-male#114", n = { x = 115 }, c = { x = { { 0.00, "Повернув ключ в замке, вы открываете панель управления. В верхней части терминала гаснет красная лампочка. Теперь он полностью обесточен." } } } } },
    [902] = { d = 20.4, v = "human-male#114", n = { x = 219 }, c = { x = { { 0.00, "Под панелью управления оказывается мешанина проводов, ламп и прочих загадочных механических объектов – кажется, большая часть там вообще не нужна." }, { 10.84, "Отодвинув их в сторону и сунув руку поглубже, вы находите самофланж. Одного рывка хватает, чтобы вытащить его из паза." } } }, t = { d = 13.6, v = "goblin-male", n = { x = 147 }, c = { x = { { 0.00, "Это... Э... Любопытно... Да. Я пошлю его в Союз ремонтников Нижней шахты." }, { 4.61, "Не сомневаюсь, что эту штуку исследуют и поймут, для чего она нужна." }, { 9.77, "Впрочем, сначала надо самому посмотреть что к чему..." } } } } },
    [903] = { d = 21.0, v = "orc-female", n = { x = 234 }, c = { x = { { 0.00, "Пришло время поохотиться на тех, кто может постоять за себя. Хищники саванны, живущие в Степях – сильные звери." }, { 7.69, "Сильные, могучие, хитрые и опасные. Их можно найти в высокой траве на юго-западе от Перекрёстка." }, { 14.95, "Соблюдай осторожность, иначе можешь неожиданно превратиться из охотника в дичь." } } }, t = { d = 11.1, v = "orc-female", n = { x = 121 }, c = { x = { { 0.00, "А, вижу, ты времени даром не терял, а прятался в траве, выслеживая хищников." }, { 5.38, "Как ты думаешь, пришло ли время встретиться лицом к лицу с сильнейшим из них?" } } } } },
    [905] = { d = 21.6, v = "orc-female", n = { x = 239 }, c = { x = { { 0.00, "Что ж, теперь твоя задача усложняется. Сначала тебе надо победить свою добычу, а потом отыскать её логово." }, { 7.71, "Я предлагаю поохотиться на яркочешуйчатых ящеров, живущих на юге. Убей их и забери перья." }, { 14.20, "Отнеси перья в их гнёзда на юго-западе от Застывшего оазиса. Покажи их сородичам, что ты не боишься!" } } }, t = { d = 17.7, g = 1, v = "orc-female", n = { m = 183, f = 187 }, c = { m = { { 0.00, "Значит, ты побывал возле гнёзд и поместил в них перья? На это требуется немало мужества." }, { 6.50, "Ты чувствуешь, что стал сильнее? Выглядишь ты куда крепче, чем в тот миг, когда явился сюда в первый раз." }, { 13.76, "Думаю, Степи сыграли в этом свою роль." } }, f = { { 0.00, "Значит, ты побывала возле гнёзд и поместила в них перья? На это требуется немало мужества." }, { 7.31, "Ты чувствуешь, что стала сильнее? Выглядишь ты куда крепче, чем в тот миг, когда явилась сюда в первый раз." }, { 14.59, "Думаю, Степи сыграли в этом свою роль." } } } } },
    [906] = { d = 49.8, g = 1, v = "named/3430", n = { x = 276 }, c = { m = { { 0.00, "Отнеси голову Лока Торку на Перекрёсток, герой." }, { 5.84, "*фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах." }, { 24.45, "Но я не сомневаюсь, что он наградит тебя за совершённый подвиг. *фыркает*" }, { 34.73, "Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай." } }, f = { { 0.00, "Отнеси голову Лока Торку на Перекрёсток, героиня." }, { 7.39, "*фыркает* Он-то без слов должен знать, что случилось с моим племенем; ха, он ни за что не поверит, что Кривозуб помог в *фыркает* таких вещах." }, { 24.21, "Но я не сомневаюсь, что он наградит тебя за совершённый подвиг. *фыркает*" }, { 34.49, "Пока я сижу в этой клетке, я и дальше буду благословлять тебя силой Агамаггана. Пока же прощай." } } }, t = { d = 22.0, v = "orc-male#60", n = { x = 239 }, c = { x = { { 0.00, "Тебе удалось найти главаря племени Иглогривых и собственноручно убить его? Поразительно." }, { 6.52, "У меня нет слов, но это не значит, что я не благодарен тебе. Жители Перекрёстка должны уважать твою силу." }, { 14.85, "Должен признать, я считал, что возглавляет налёты на наши обозы другой свинобраз. Ещё раз спасибо." } } } } },
    [907] = { d = 29.5, v = "tauren-male#67", n = { x = 244 }, c = { x = { { 0.00, "Пришло время выступить против рокочущих ящериц. Они столь огромны, что земля дрожит под их шагами." }, { 9.71, "Сражаясь с ними, соблюдай осторожность: один неверный шаг – и они стопчут тебя." }, { 17.64, "Ящерицы живут в южной части Степей. Их называют грозорылами, грозошкурами и громоголовами. Возвращайся ко мне с победой." } } }, t = { d = 10.9, v = "tauren-male#67", n = { x = 88 }, c = { x = { { 0.00, "Я рад, что ты принёс доказательство своего торжества. И особенно здорово, что у тебя все кости остались целы." } } } } },
    [913] = { d = 19.7, g = 1, v = "tauren-male#67", n = { m = 156, f = 157 }, c = { m = { { 0.00, "Грозовой змей – лютый зверь. И всё же ты уже готов бросить ему вызов." }, { 6.66, "Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты." }, { 14.12, "Выполни моё задание, и твоё обучение подойдёт к концу." } }, f = { { 0.00, "Грозовой змей – лютый зверь. И всё же ты уже готова бросить ему вызов." }, { 6.93, "Ступай, отыщи его и принеси мне крылья в доказательство успешной охоты." }, { 14.39, "Выполни моё задание, и твоё обучение подойдёт к концу." } } }, t = { d = 25.6, g = 1, v = "tauren-male#67", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Тебе есть чем гордиться, ведь ты одолел всех врагов, явив силу, мужество и честь." }, { 8.38, "Не останавливайся, следуй дальше по своему пути. Более того, жизнь настоящего охотника – постоянная борьба." }, { 18.55, "Ступай же с высоко поднятой головой по избранному тобой пути. Пора." } }, f = { { 0.00, "Тебе есть чем гордиться, ведь ты одолела всех врагов, явив силу, мужество и честь." }, { 8.43, "Не останавливайся, следуй дальше по своему пути. Более того, жизнь настоящего охотника – постоянная борьба." }, { 18.62, "Ступай же с высоко поднятой головой по избранному тобой пути. Пора." } } } } },
    [914] = { d = 39.5, v = "tauren-female", n = { x = 383 }, c = { x = { { 0.00, "Друиды в Пещерах Стенаний, Друиды Клыка поражены порчей." }, { 4.46, "Когда-то они были частью ордена друидов давшего обет исцелить Степи, но теперь они хотят перекроить эти земли в соответствии со своими извращёнными мечтаниями." }, { 17.83, "У Друидов Клыка четыре предводителя и каждый обладает Камнем Сновидения. Даже теперь их лица преследуют меня в кошмарах." }, { 28.42, "Убей предводителей друидов, принеси мне их камни и в Степях снова воцарится мир." }, { 35.31, "Иди, и разыщи их укрытия в Пещерах Стенаний." } } }, t = { d = 16.5, g = 1, v = "tauren-female", n = { m = 148, f = 152 }, c = { m = { { 0.00, "Ты сделал это. Ты убил друидов Клыка, теперь мои сны свободны от их присутствия." }, { 6.90, "Ты спас Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утёса и от имени этой земли." } }, f = { { 0.00, "Ты сделала это. Ты убила друидов Клыка, теперь мои сны свободны от их присутствия." }, { 7.20, "Ты спасла Степи, и я благодарю тебя от своего имени, от имени друидов Громового Утёса и от имени этой земли." } } } } },
    [916] = { d = 36.9, v = "nightelf-male#55", n = { x = 439 }, c = { x = { { 0.00, "Я пришёл в Тенистую долину, чтобы наблюдать за чащобными тенётниками, обитающими в Паучьем логове." }, { 6.46, "Они – родичи более мелких разновидностей пауков. Полагаю, что Древо Жизни оказало на них сильное воздействие..." }, { 13.72, "Я хотел бы получить несколько вещей, чтобы изучить их и подтвердить свои догадки." }, { 19.65, "Для начала мне понадобится немного их яда." }, { 22.86, "Добудь ядовитые железы у пауков-тенётников в Паучьем логове и вокруг него, к северу отсюда." }, { 28.99, "После этого я смогу изучить эти образцы и понять, есть ли у этого яда сходство с ядом их более мелких сородичей." } } }, t = { d = 12.9, v = "nightelf-male#55", n = { x = 152 }, c = { x = { { 0.00, "Благодарю тебя. Когда я вернусь в Дарнас, я первым же делом сравню образцы яда из этих желёз с ядами других пауков." }, { 7.80, "Полагаю, что некоторые свойства яда связаны с ростом нового Древа Жизни." } } } } },
    [917] = { d = 33.0, v = "nightelf-male#55", n = { x = 378 }, c = { x = { { 0.00, "Теперь, когда у меня есть паучий яд, мне хотелось бы получить для изучения живой образец." }, { 6.10, "Не волнуйся, я не могу просить тебя поймать гигантского паука живьём." }, { 10.91, "Да и мне самому вряд ли удалось бы справиться с таким \"образцом\"!" }, { 15.64, "Но если ты принесёшь яйцо, из которого ещё не вылупился паучок, то получить образец будет куда легче, не говоря уж о том, чтобы содержать." }, { 25.26, "В глубинах Паучьего логова должно быть гнездо. Прошу тебя, найди его, возьми оттуда яйцо паука и принеси мне." } } }, t = { d = 13.3, v = "nightelf-male#55", n = { x = 152 }, c = { x = { { 0.00, "О, отлично. Я отправлю яйцо и яд в Дарнас, а потом и сам вернусь туда, когда мои изыскания здесь будут завершены." }, { 7.72, "Я многого ожидаю от этих образцов. Твоя помощь оказалась поистине бесценной." } } } } },
    [918] = { d = 29.4, g = 1, v = "nightelf-male#59", n = { m = 342, f = 344 }, c = { m = { { 0.00, "Древесники Тельдрассила – духи Природы." }, { 2.70, "Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе." }, { 9.83, "Потому меня очень тревожит, что древесники становятся такими озлобленными." }, { 15.10, "Мне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников." }, { 24.16, "Не мог бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?" } }, f = { { 0.00, "Древесники Тельдрассила – духи Природы." }, { 2.70, "Они в какой-то мере отражают естественный порядок жизни растений и животных на нашем великом древе." }, { 9.83, "Потому меня очень тревожит, что древесники становятся такими озлобленными." }, { 15.10, "Мне кажется, что дело в почве. Я разными методами выращивал растения, и мне хотелось бы испытать эти способы на саженцах древесников." }, { 24.16, "Не могла бы ты собрать для меня этих саженцев вокруг озера Аль'Амет?" } } }, t = { d = 14.1, g = 1, v = "nightelf-male#59", n = { m = 157, f = 158 }, c = { m = { { 0.00, "Ты их добыл. Славно!" }, { 1.90, "Я посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных." }, { 10.96, "Может, позже ты ещё увидишь результаты!" } }, f = { { 0.00, "Ты их добыла. Славно!" }, { 1.94, "Я посажу их в специально подготовленную почву. Уверен, что ростки потянутся вверх и вырастут в древесников, гораздо более послушных." }, { 10.99, "Может, позже ты ещё увидишь результаты!" } } } } },
    [919] = { d = 22.1, v = "nightelf-male#59", n = { x = 258 }, c = { x = { { 0.00, "Вокруг вод озера Аль'Амет прорастают маленькие древесники." }, { 4.08, "Боюсь, им уже не помочь, нам придётся выдернуть их из земли прежде, чем они станут слишком большими и начнут приносить беды." }, { 13.01, "Когда будешь бродить вокруг озера, выдергивай каждый росток древесника, что попадётся тебе по дороге. Помоги очистить нашу землю!" } } }, t = { d = 13.1, v = "nightelf-male#59", n = { x = 148 }, c = { x = { { 0.00, "Как много! Они распространяются с ужасающей скоростью. Надеюсь, мне удастся разгадать, что же за порча поразила их." }, { 8.29, "Благодарю за помощь. Этот край благодаря твоим усилиям стал чище." } } } } },
    [920] = { d = 13.6, g = 1, v = "nightelf-male#55", n = { x = 146 }, c = { m = { { 0.00, "Ты путник, не так ли? До меня доходили слухи, что тебя искал Тенарон." }, { 4.61, "Ты отыщешь его в самой верхней комнате на вершине Альдрассила." }, { 9.22, "Хоть мы и живём долго, не стоит заставлять Тенарона ждать." } }, f = { { 0.00, "Ты путница, не так ли? До меня доходили слухи, что тебя искал Тенарон." }, { 4.65, "Ты отыщешь его в самой верхней комнате на вершине Альдрассила." }, { 9.27, "Хоть мы и живём долго, не стоит заставлять Тенарона ждать." } } }, t = { d = 8.0, v = "nightelf-male#54", n = { x = 88 }, c = { x = { { 0.00, "А. Я думал, что ты быстрее откликнешься на мой призыв. У меня есть важное задание, которое я хочу поручить тебе." } } } } },
    [921] = { d = 35.7, v = "nightelf-male#54", n = { x = 406 }, c = { x = { { 0.00, "Пришло время тебе отправиться на поиски своей судьбы." }, { 3.75, "Но чтобы подготовиться к встрече с миром за пределами наших зачарованных лесов, тебе нужно больше узнать о нашей недавней истории." }, { 13.09, "Многое изменилось для нашего народа со времён битвы за гору Хиджал." }, { 17.91, "Нордрассил ныне – лишь бледная тень того, чем он некогда был, его сила ушла на то, чтобы одолеть Архимонда и отбросить прочь Пылающий Легион..." }, { 27.85, "Тебе нужно исполнить важное поручение. Принеси мне воды из лунного колодца к северу от Альдрассила." } } }, t = { d = 17.2, v = "nightelf-male#54", n = { x = 208 }, c = { x = { { 0.00, "Тебе уже довелось услышать первую часть истории о последствиях битвы за гору Хиджал, однако ещё многое нужно рассказать, и выполнение задания, данного мной тебе, будет продолжаться на протяжении всего твоего путешествия через Тельдрассил в Дарнас." } } } } },
    [922] = { d = 34.5, g = 1, v = "nightelf-male#59", n = { m = 394, f = 398 }, c = { m = { { 0.00, "Не мог бы ты доставить один из тех ростков, что ты принёс мне, моему другу, Релиану Зелёному Костру? Он друид из Дарнасса." }, { 8.35, "Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками." }, { 13.83, "У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом." }, { 19.94, "Благодарю тебя. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов." }, { 26.82, "Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять." } }, f = { { 0.00, "Не могла бы ты доставить один из тех ростков, что ты принесла мне, моему другу, Релиану Зелёному Костру? Он друид из Дарнасса." }, { 8.69, "Когда мы в последний раз общались, он проявил интерес к моей работе с древесниками." }, { 14.17, "У него самого кое-какие идеи есть, и он будет очень рад поработать с таким образцом." }, { 20.28, "Благодарю тебя. Твоя помощь просто неоценима. Надеюсь, что однажды ты увидишь плоды моих трудов." }, { 27.16, "Релиана обычно можно найти на какой-нибудь из дорожек анклава Кенария в Дарнассе, он любит там гулять." } } }, t = { d = 29.2, v = "nightelf-male#55", n = { x = 340 }, c = { x = { { 0.00, "А, росток древесника? Я хотел попытаться сам вырастить древесника, чтобы помочь Деналану в его изысканиях." }, { 7.58, "К сожалению, я выяснил, что множество древесников поражено порчей, и ростки таких существ также наследуют её от родителей. И не в моих силах это исправить." }, { 18.23, "У Деналана великий талант работать со всем, что растёт. Если кто и найдёт исцеление для будущих древесников, то это он." }, { 26.23, "Возможно, он – наша последняя надежда." } } } } },
    [923] = { d = 28.2, v = "nightelf-male#55", n = { x = 335 }, c = { x = { { 0.00, "Древесники становятся всё более злобными. Мы пытаемся найти источник этой беды, но пока..." }, { 5.95, "чтобы уберечь Тельдрассил, нам приходится уничтожать древесников, которым уже не поможешь." }, { 12.07, "Те, что бродят вокруг Родникового озера на севере, поражены порчей сильнее всего. Их надо уничтожить!" }, { 19.31, "Уничтожь всех древесников, которых там найдёшь, и собери растущие на них мшистые опухоли. Принеси их мне, чтобы я мог их сжечь." } } }, t = { d = 12.1, v = "nightelf-male#55", n = { x = 136 }, c = { x = { { 0.00, "Хорошая работа! Эти опухоли - симптом болезни древесников. Они наполнены ядом, от которого мы должны очистить наши новые земли." }, { 8.97, "Я уничтожу эти опухоли. Благодарю тебя." } } } } },
    [924] = { d = 34.7, v = "orc-male", n = { x = 383 }, c = { x = { { 0.00, "Демоново семя – страшное оружие Пылающего Легиона. Оно хранится в пещере на Вершине Багрового Тумана, над демоническим алтарём Огня." }, { 9.72, "Я подготовил камни силы, которые разорвут связь Семени с Легионом." }, { 14.68, "Возьми камень со стола и возложи его на алтарь Огня на Вершине Багрового Тумана." }, { 20.37, "Отправляйся на запад, а на развилке сверни на север. Вершина окажется по левую руку от тебя." }, { 27.08, "Безопаснее всего подниматься по северному склону." }, { 31.01, "Торопись: сила камня постепенно иссякает." } } }, t = { d = 30.7, v = "orc-male", n = { x = 317 }, c = { x = { { 0.00, "Твоя цель достигнута. Тебе удалось уничтожить Демоново семя, как велел Ниру. Но это ещё не конец…" }, { 7.17, "После уничтожения Демонова семени по всему астралу пошли волны небывалой силы. Их почувствовала не только я." }, { 15.00, "Об этом узнают те, чью игрушку мы сломали…" }, { 18.44, "Впрочем, невзирая на грядущие испытания, я хочу вручить тебе кое-что. Ниру велел дать это в уплату и поблагодарить тебя. Итак, я благодарю тебя." } } } } },
    [927] = { d = 15.9, v = "human-male#114", n = { x = 163 }, c = { x = { { 0.00, "Сердце Черномшеца Злосмрадного поросло тёмным маслянистым мхом." }, { 4.97, "Понять, что это сердце, можно лишь по тому, что оно медленно и ритмично пульсирует... Даже сейчас." }, { 12.79, "Возможно, это заинтересует Деналана." } } }, t = { d = 13.9, g = 1, v = "nightelf-male#59", n = { m = 147, f = 149 }, c = { m = { { 0.00, "...Это ещё что такое? Сердце древесника? Оно всё поросло вонючим мхом!" }, { 5.10, "Хорошо, что ты принёс его мне. Я исследую это сердце и, если удача повернётся ко мне лицом, выясню, что это за мох на нём." } }, f = { { 0.00, "...Это ещё что такое? Сердце древесника? Оно всё поросло вонючим мхом!" }, { 5.10, "Хорошо, что ты принесла его мне. Я исследую это сердце и, если удача повернётся ко мне лицом, выясню, что это за мох на нём." } } } } },
    [928] = { d = 35.7, g = 1, v = "nightelf-male#54", n = { m = 389, f = 391 }, c = { m = { { 0.00, "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждёт тебя." }, { 9.60, "Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнёс его Коритрасу." }, { 16.01, "Ты найдёшь Коритраса у лунного колодца в Доланааре." }, { 19.61, "Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками." }, { 28.86, "И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа." } }, f = { { 0.00, "Я мог бы поведать тебе ещё многое о лунных колодцах и о Тельдрассиле, однако тебе пора в путь. Коритрас Лунный Гнев ждёт тебя." }, { 9.60, "Я перелил воду из фиала, принесённого тобой, в этот сосуд, чтобы ты отнесла его Коритрасу." }, { 16.59, "Ты найдёшь Коритраса у лунного колодца в Доланааре." }, { 20.18, "Иди из Тенистой долины по дороге, что на юге от Альдрассила, а когда она свернёт на запад, следуй по пути, мощенному булыжниками." }, { 29.44, "И советую тебе не сходить с дороги, – в последнее время в лесу появились опасные существа." } } }, t = { d = 12.5, v = "nightelf-male#54", n = { x = 131 }, c = { x = { { 0.00, "А, понятно. Тебя послал Тенарон. Ну что ж, похоже, нам о многом нужно поговорить, многое сделать – но времени мало." }, { 8.55, "Думаю, лучше не медлить и приступить к делу сейчас же." } } } } },
    [929] = { d = 35.3, v = "nightelf-male#54", n = { x = 407 }, c = { x = { { 0.00, "Сначала позволь поведать тебе, какая стоит перед тобой задача." }, { 4.49, "Друиды Дарнасса пользуются водой из лунных колодцев Тельдрассила, и временами их колодцы надо пополнять." }, { 11.69, "При помощи этих специально изготовленных фиалов ты сможешь набирать воду из лунных колодцев." }, { 18.37, "Отнеси этот сосуд к лунному колодцу у деревни Звёздного Ветра на востоке и набери из него немного воды, а затем возвращайся ко мне." }, { 27.56, "Когда ты выполнишь это задание, я продолжу свой рассказ с момента, на котором его прервал Тенарон..." } } }, t = { d = 19.2, v = "nightelf-male#54", n = { x = 219 }, c = { x = { { 0.00, "После битвы за гору Хиджал мы не знали, что делать дальше." }, { 4.11, "Нордрассил дымился, опалённый огнём, и наше бессмертие – сама сущность нашего бытия! – было утрачено." }, { 11.19, "Именно в эту пору испытаний Предатель вырвался из заточения и исчез Шан'до Ярость Бури. Настали тёмные времена." } } } } },
    [930] = { d = 9.3, v = "human-male#114", n = { x = 96 }, c = { x = { { 0.00, "Под ветками этого светящегося растения висит большой круглый плод." }, { 5.46, "Вы уверены, что Деналану захочется его изучить." } } }, t = { d = 19.5, g = 1, v = "nightelf-male#59", n = { m = 222, f = 222 }, c = { m = { { 0.00, "Ты нашёл его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота!" }, { 8.31, "И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила." }, { 14.49, "Спасибо тебе. Теперь извини, мне нужно попристальнее его поизучать..." } }, f = { { 0.00, "Ты нашла его на Тельдрассиле? Как интересно... Такой необычный плод. Может, семена занесло издалека? Может, даже из Азерота!" }, { 8.23, "И что-то в нём есть такое... похоже, на него как-то странно повлияли почвы Тельдрассила." }, { 14.42, "Спасибо тебе. Теперь извини, мне нужно попристальнее его поизучать..." } } } } },
    [931] = { d = 12.8, v = "human-male#114", n = { x = 133 }, c = { x = { { 0.00, "Росток этого дерева мерцает в сумраке леса, распространяя вокруг себя изменчивое, пульсирующее свечение." }, { 8.41, "Наверное. Деналана интересует именно такой образец." } } }, t = { d = 20.8, g = 1, v = "nightelf-male#59", n = { m = 232, f = 232 }, c = { m = { { 0.00, "Где ты это нашёл? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад!" }, { 7.96, "Удивительно, как он попал в Тельдрассил. Да ещё вырос до такой величины!" }, { 13.28, "Спасибо тебе. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком..." } }, f = { { 0.00, "Где ты это нашла? Я не видел таких растений с тех пор, как жил на Болоте Печали. А это было много десятилетий назад!" }, { 8.01, "Удивительно, как он попал в Тельдрассил. Да ещё вырос до такой величины!" }, { 13.33, "Спасибо тебе. Прости мою немногословность, но мне не терпится провести кое-какие опыты с этим ростком..." } } } } },
    [932] = { d = 29.4, v = "nightelf-male#54", n = { x = 305 }, c = { x = { { 0.00, "Должен предупредить тебя, что это должно остаться только между нами." }, { 4.63, "Сатиры и так уже причиняют нам немало неприятностей, а этот уж слишком близко к нашему дому рыщет." }, { 12.36, "Его зовут лорд Меленас. Он живёт по соседству, в Пещере Бесов, где собрал шайку греллей-воинов." }, { 20.66, "Его сердце чернее ночи, а замыслы – омерзительны." }, { 24.38, "Найди его в пещере, прямо к северу отсюда, и принеси мне его голову!" } } }, t = { d = 9.2, v = "nightelf-male#54", n = { x = 84 }, c = { x = { { 0.00, "Теперь, когда лорд Меленас упокоился навек, я могу заняться и другими делами. Прими мою благодарность." } } } } },
    [933] = { d = 21.1, v = "nightelf-male#54", n = { x = 241 }, c = { x = { { 0.00, "К юго-востоку от входа в Дарнасс, на берегу Арлитириэнских прудов есть ещё один лунный колодец." }, { 7.03, "Стражам трудно наблюдать за этими местами из-за всё учащающихся нападений и всё большей злобности фурболгов из племени Кривой Сосны." }, { 16.59, "Будь начеку во время поисков колодца и держи оружие наготове." } } }, t = { d = 28.9, v = "nightelf-male#54", n = { x = 326 }, c = { x = { { 0.00, "Шан'до Ярость Бури так и не вернулся, и новостей про него до сих пор не поступало. Друиды были в смятении." }, { 7.24, "После пропажи Малфуриона верховный Фэндрал Олений Шлем взял на себя руководство друидами, убедив Круг Древних на Тёмных берегах, что нашему народу пора снова заполучить былую мощь и бессмертие." }, { 20.79, "С одобрения Круга Олений Шлем и самые могучие друиды вырастили Тельдрассил, новое Древо Жизни." } } } } },
    [934] = { d = 33.9, v = "nightelf-male#54", n = { x = 390 }, c = { x = { { 0.00, "Но не всё было ладно с Тельдрассилом." }, { 2.64, "Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие." }, { 10.77, "Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила." }, { 17.09, "Однако, пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула." }, { 25.36, "Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне." } } }, t = { d = 32.2, v = "nightelf-male#54", n = { x = 389 }, c = { x = { { 0.00, "Находиться в присутствии Древа-оракула... это всё равно что увидеть воплощённую мудрость. Позволь мне продолжить..." }, { 8.10, "Тельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена." }, { 17.12, "Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности." }, { 22.96, "Алекстраза также отказала Оленьему Шлему, а без её благословения рост Тельдрассила стал непредсказуем, и в нём обнаружились изъяны..." } } } } },
    [935] = { d = 29.0, g = 1, v = "nightelf-male#54", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном." }, { 7.12, "Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников." }, { 14.20, "Могу только надеяться, что верховный друид быстро найдёт то, что ищет." }, { 18.90, "Я наполню все принесённые тобой фиалы, чтобы ты доставил их в Дарнасс." }, { 24.00, "Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов." } }, f = { { 0.00, "Без благословения Алекстразы Хранительницы Жизни и Ноздорму Хозяина Времени Тельдрассил вырос с изъяном." }, { 7.12, "Странные твари лезут из-под его корней, и бешеные фурболги нападают на проходящих мимо путников." }, { 14.20, "Могу только надеяться, что верховный друид быстро найдёт то, что ищет." }, { 18.90, "Я наполню все принесённые тобой фиалы, чтобы ты доставила их в Дарнасс." }, { 24.17, "Отнеси их к Фэндралу Оленьему Шлему, ты найдёшь его в роще друидов." } } }, t = { d = 22.9, v = "named/3516", n = { x = 247 }, c = { x = { { 0.00, "О, да, это та вода, о которой я просил. Тенарон и Коритрас улучили минутку передать её..." }, { 6.07, "хотя гонца, может, и не самого надёжного выбрали... хм-м." }, { 10.21, "Однако теперь я могу вернуться к работе. Бремя бед Тельдрассила тяжким гнётом лежит на моих плечах." }, { 17.16, "Но скоро я избавлюсь от этого ярма." }, { 20.02, "Вот, возьми. Может, тебе пригодится." } } } } },
    [937] = { d = 26.5, v = "nightelf-female#52", n = { x = 316 }, c = { x = { { 0.00, "Меня отправили сюда с небольшим отрядом Часовых для защиты древа-оракула от гарпий, что устроили себе гнёзда по всей поляне." }, { 8.39, "Мы стараемся потихоньку вытеснить их отсюда." }, { 11.56, "Когда древо-оракул попыталось послать гонца в Дарнасс, на него напала стая гарпий и растерзала." }, { 18.23, "Если ты считаешь, что это задание тебе по плечу, иди к их гнездовью и принеси их пояса в доказательство своего подвига." } } }, t = { d = 22.4, g = 1, v = "nightelf-female#52", n = { m = 264, f = 267 }, c = { m = { { 0.00, "Ты столького достиг за такое короткое время!" }, { 3.11, "Это очень впечатляет Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе..." }, { 9.34, "но я понимаю, что тебя ждут великие дела." }, { 12.38, "Я заметила, что Древо-оракул только что сбросило кусок коры." }, { 16.37, "Несомненно, оно хочет, чтобы ты выполнил какое-то поручение для него. Поговори с ним." } }, f = { { 0.00, "Ты столького достигла за такое короткое время!" }, { 2.96, "Это очень впечатляет Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе..." }, { 9.18, "но я понимаю, что тебя ждут великие дела." }, { 12.22, "Я заметила, что Древо-оракул только что сбросило кусок коры." }, { 16.22, "Несомненно, оно хочет, чтобы ты выполнила какое-то поручение для него. Поговори с ним." } } } } },
    [938] = { d = 22.5, v = "human-male#114", n = { x = 227 }, c = { x = { { 0.00, "Мех самки саблезуба имеет характерный серый цвет, сливающийся с фоном окружающего леса." }, { 6.72, "Вы видите, что она сильно пострадала: глубокие рваные раны видны на её спине и брюхе." }, { 13.80, "Она смотрит на вас, и в её голубых глазах читается глубокая мудрость. Похоже, она хочет следовать за вами." } } }, t = { d = 15.3, v = "nightelf-female#52", n = { x = 178 }, c = { x = { { 0.00, "О, благодарю тебя! Я так боялась, что уж больше не увижу мою Туманну, скорбела всем сердцем о её гибели, о том, что навек разлучилась с моей верной спутницей..." }, { 10.66, "Я в неоплатном долгу перед тобой! Прими мою вечную благодарность." } } } } },
    [940] = { d = 26.8, v = "nightelf-female#52", n = { x = 326 }, c = { x = { { 0.00, "Шум леса донёс до меня весть о твоих подвигах." }, { 3.00, "Когда я ощутила, что гарпии покинули свои гнездовья, великий покой распространился по лесу и его обитатели снова ощутили себя в безопасности." }, { 12.45, "Я боялась посылать очередное сообщение верховному друиду, но теперь я знаю, что ты доставишь его ему в целости и сохранности." }, { 21.10, "Передай ему письмо и знай, что лес будет охранять тебя по дороге в каменные джунгли." } } }, t = { d = 25.4, g = 1, v = "named/3516", n = { m = 288, f = 289 }, c = { m = { { 0.00, "Я-то думал, почему Древо-оракул так долго не связывается со мной..." }, { 4.44, "Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная." }, { 11.68, "Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие." }, { 18.54, "Тем не менее, ты славно справился с заданием Древа-оракула, и за усердие тебе положена награда." } }, f = { { 0.00, "Я-то думал, почему Древо-оракул так долго не связывается со мной..." }, { 4.44, "Сдаётся мне, что как только мы решаем одну проблему, немедленно возникает другая, ещё более сложная." }, { 11.68, "Боюсь, мне никогда не закончить мои труды с Тельдрассилом и мы так и не вернём себе бессмертие." }, { 18.54, "Тем не менее, ты славно справилась с заданием Древа-оракула, и за усердие тебе положена награда." } } } } },
    [941] = { d = 13.6, v = "nightelf-male#59", n = { x = 155 }, c = { x = { { 0.00, "Я удалил этот смрадный мох с сердца, но оно всё ещё остаётся запятнанным..." }, { 5.45, "Попытайся посадить его в мою кадку. Она наполнена плодородной землёй, которая может очистить и исцелить это сердце." } } }, t = { d = 13.2, v = "nightelf-male#59", n = { x = 149 }, c = { x = { { 0.00, "Вы сажаете сердце в кадку, и оно быстро в неё зарывается!" }, { 4.31, "Через несколько секунд оно снова выкапывается из земли – уже очищенное. Оно тихонько пульсирует... и вам хочется взять его в руки." } } } } },
    [942] = { d = 40.1, v = "dwarf-male", n = { x = 454 }, c = { x = { { 0.00, "Эта окаменелость поразительно похожа на другую, которую я однажды видел в Стальгорне." }, { 5.97, "Геолог по имени Бутылопуз приносил её на ежегодную конференцию Лиги Исследователей." }, { 11.82, "Он был уверен, что в этой окаменелости скрыта мощь, которую можно каким-то образом высвободить." }, { 18.74, "Последнее, что я слышал, что Бутылопуз обосновался в таверне \"Большая вода\" и ждёт, чтобы его сопроводили к раскопу Вельгара." }, { 27.13, "Найдите его и покажите ему окаменелость, найденную Сомнамбулером. Может быть, он сумеет раскрыть секреты прошлого." }, { 36.13, "Корабль в Менетилов отходит из Аубердина." } } }, t = { d = 8.5, v = "dwarf-male", n = { x = 89 }, c = { x = { { 0.00, "О боги! Так вы говорите, эта вещь происходит из далёких земель Калимдора? Поразительно! Просто поразительно!" } } } } },
    [943] = { d = 31.0, v = "dwarf-male", n = { x = 353 }, c = { x = { { 0.00, "Геолог Вельгар, который сейчас находится на раскопе в Болотине, держит окаменелость у себя." }, { 6.25, "Когда я обнаружил камень Релу, то был уверен, что это ключ к тайне окаменелости." }, { 12.16, "Пока я шёл по дороге к Вельгару, на меня напали ящеры, и реликвия пропала." }, { 17.19, "Не знаю, какая из крапчатых тварей проглотила её, но если вам удастся её вернуть, я смогу высвободить силу этих артефактов." }, { 25.95, "Принесите мне и камень Релу, и окаменелость, хранящуюся у Вельгара." } } }, t = { d = 8.4, v = "dwarf-male", n = { x = 92 }, c = { x = { { 0.00, "Великолепно!" }, { 1.44, "Теперь посмотрим, смогу ли я использовать камень, чтобы распознать силы, скрытые в окаменелостях." } } } } },
    [944] = { d = 39.3, v = "tauren-male", n = { x = 385 }, c = { x = { { 0.00, "Очень странно, что наги появились здесь, на Тёмных берегах. Но ещё страннее – клан Сумеречного Молота." }, { 7.91, "Они поклоняются старым, очень старым богам этой земли. Богам, давным-давно низвергнутым." }, { 15.26, "Меч Властителя, что к югу отсюда, – место, где пал один из этих древних богов." }, { 21.63, "Пойди туда и поищи других культистов Сумеречного Молота." }, { 26.49, "Возьми этот фиал виденья. Используй его для создания гадальной чаши, когда разведаешь всё у Меча Властителя." }, { 35.81, "Посредством этой чаши поговори со мной." } } }, t = { d = 20.1, g = 1, v = "tauren-male", n = { m = 185, f = 186 }, c = { m = { { 0.00, "Так ты обнаружил клан Сумеречного Молота у Меча Властителя? Плохо." }, { 5.59, "Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества." }, { 14.38, "Должно быть, клан Сумеречного Молота пытается найти его силу." } }, f = { { 0.00, "Так ты обнаружила клан Сумеречного Молота у Меча Властителя? Плохо." }, { 6.20, "Древний бог, пронзённый мечом, давно мёртв, но это не значит, что исчезли и остатки его могущества." }, { 14.99, "Должно быть, клан Сумеречного Молота пытается найти его силу." } } } } },
    [945] = { d = 20.9, v = "human-female", n = { x = 227 }, c = { x = { { 0.00, "Помогите!" }, { 1.12, "Я бродила у Меча Властителя, как вдруг меня окружили эти жуткие культисты. Счастье, что я умею отлично прятаться!!!" }, { 9.41, "Можете помочь мне отсюда выбраться? И ещё, мне нужно будет сообщить моей сестре Тересиль, что я в порядке." }, { 16.65, "Она в Ясеневом лесу, к югу отсюда, у святилища Эссины." } } }, t = { d = 16.3, v = "human-female", n = { x = 182 }, c = { x = { { 0.00, "Моя сестра была – где? Терилун любит бродить по всяким местам, но всё-таки!" }, { 5.12, "Это же очень далеко, да и Меч Властителя – вовсе не безопасное место..." }, { 10.04, "Ну, спасибо вам. С вашей стороны было очень любезно сообщить мне, что с ней всё в порядке." } } } } },
    [947] = { d = 34.1, v = "nightelf-male#54", n = { x = 393 }, c = { x = { { 0.00, "Я тут составляю одно зелье, для которого нужны редкие грибы, растущие в одной-единственной пещере." }, { 6.76, "Пещера эта находится за водопадом Скалистый, к востоку и чуть севернее в горах." }, { 12.46, "Я бы и сам туда пошёл, но в Роще Древних мне порекомендовали держаться подальше от того места." }, { 18.97, "Наши почтенные союзники чувствуют, что в этой пещере таится какое-то незнакомое зло." }, { 25.20, "Прошу вас, соберите для меня эти грибы. А в процессе заодно приглядитесь: может быть, вы сможете подтвердить опасения Дерев." } } }, t = { d = 15.9, v = "nightelf-male#54", n = { x = 169 }, c = { x = { { 0.00, "Большое вам спасибо. Это отличные экземпляры!" }, { 3.97, "Кстати, когда вы были у водопада Скалистый, заметили ли что-нибудь, что могло подтвердить опасения Дерев?" }, { 11.55, "Дерева мудры, но я надеялся, что на сей раз они ошибаются." } } } } },
    [948] = { d = 22.9, v = "nightelf-male#54", n = { x = 227 }, c = { x = { { 0.00, "Ону, Древо Мудрости из Рощи Древних, знает о вашем путешествии к Скалистому водопаду и хочет поговорить с вами." }, { 9.13, "Роща расположена к югу отсюда, у подножья гор." }, { 13.08, "Дерева терпеливы и мудры. Но если Ону ищет вашего совета касательно того, что вы видели у водопадов, то, боюсь, дело срочное." } } }, t = { d = 6.2, g = 1, v = "tauren-male", n = { x = 39 }, c = { m = { { 0.00, "путник. Ты здесь. Хорошо." }, { 2.80, "Нам есть... что обсудить. Тебе и мне." } }, f = { { 0.00, "путница. Ты здесь. Хорошо." }, { 2.62, "Нам есть... что обсудить. Тебе и мне." } } } } },
    [949] = { d = 22.3, v = "tauren-male", n = { x = 214 }, c = { x = { { 0.00, "Что замышляет клан Сумеречного Молота у Меча Властителя, неизвестно. Но наверняка что-то недоброе" }, { 8.08, "Обыщите их лагерь у Меча Властителя... Ищите то, что может помочь нам понять их намерения." }, { 16.09, "Ведь мы должны узнать об их целях раньше, чем они выработают план действий." } } }, t = { d = 5.6, v = "tauren-male", n = { x = 57 }, c = { x = { { 0.00, "Книга написана от руки на древнем языке и прекрасно иллюстрирована." } } } } },
    [950] = { d = 24.1, v = "human-male#114", n = { x = 254 }, c = { x = { { 0.00, "Вглядываясь в сумеречный фолиант, можно сойти с ума." }, { 4.03, "Буквы начинают плыть и плясать перед глазами даже после мельком брошенного взгляда, и некогда прекрасный орнамент принимает гротескные формы." }, { 15.05, "Вырвать одну страницу с безумными каракулями – вот и всё, что вам удаётся сделать, пока вы не потеряли сознание." } } }, t = { d = 18.2, v = "tauren-male", n = { x = 181 }, c = { x = { { 0.00, "Неизученная первобытная магия окружает этот пергамент с письменами. Я чувствую, что над ним потрудились древние силы." }, { 9.64, "Будем надеяться, мы сумеем раскрыть цель деятельности клана Сумеречного Молота на Тёмном Берегу." } } } } },
    [951] = { d = 47.0, g = 1, v = "tauren-male", n = { m = 444, f = 445 }, c = { m = { { 0.00, "Пергамент, который ты обнаружил близ Меча Властителя, – страница древнего текста... написанная эльфами!" }, { 9.36, "Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев." }, { 26.42, "Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии." }, { 37.43, "Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов." } }, f = { { 0.00, "Пергамент, который ты обнаружила близ Меча Властителя, – страница древнего текста... написанная эльфами!" }, { 7.95, "Она отягощена проклятиями и загрязнена порчей клана Сумеречного Молота, но похоже, что служители культа используют древнюю эльфийскую магию для того, чтобы вернуть в наш мир своих древних хозяев." }, { 23.56, "Направляйся к руинам Матистры, расположенным к северо-востоку отсюда, и поищи в траве и средь разбитых камней древние реликвии." }, { 34.57, "Изучая их, мы сможем выяснить, каким образом в клане Сумеречного Молота намерены использовать магию эльфов." } } }, t = { d = 23.3, v = "tauren-male", n = { x = 221 }, c = { x = { { 0.00, "Благодарю тебя. Эти реликвии относятся к поре расцвета Матистры." }, { 6.10, "Этот некогда могучий оплот эльфов давно разрушен, но остатки магии ещё попадаются в руинах." }, { 13.35, "Будем надеяться, что нам удастся раскрыть тайны этого места раньше, чем это сделают наши враги. Будь настороже." } } } } },
    [952] = { d = 27.1, v = "named/3516", n = { x = 306 }, c = { x = { { 0.00, "Если уж у тебя нашлось время передать письмо для Древа-оракула, то, мне кажется, для тебя не составит труда отнести донесение в Рощу Древних на Тёмный Берег, прямо к югу от Аубердина." }, { 12.70, "Ты наверняка сможешь свободно добраться туда на гиппогрифе, я уверен, что ты сумеешь это сделать. Отнеси это Ону, Древу Мудрости." }, { 21.48, "Он ждёт от меня вести, точно так же, как я ждал вести с Поляны Оракула." } } }, t = { d = 12.2, v = "tauren-male", n = { x = 110 }, c = { x = { { 0.00, "А. Спасибо. Тем не менее, это странно. Верховный друид всегда так торопится. Лес знает, что всему своё время. Шан'до Ярость Бури это понимал." } } } } },
    [953] = { d = 35.2, v = "nightelf-female#52", n = { x = 433 }, c = { x = { { 0.00, "К востоку отсюда находятся руины Амет'Арана." }, { 2.78, "Сейчас их населяют неупокоенные духи высокорожденных, некогда живших в его стенах, но когда-то Амет'Аран был местом, где слуги Азшары свободно практиковались в своей могучей магии." }, { 15.15, "Меня послали исследовать эти руины, и я наткнулась на две большие таблички, на которых была неразборчиво начертана история Амет'Арана и его падения." }, { 24.85, "Пока я пыталась прочесть руны, на меня напали призраки, и я сбежала." }, { 29.51, "Пожалуйста, если можете, отправляйтесь в руины и расшифруйте таблички вместо меня." } } }, t = { d = 22.6, v = "nightelf-female#52", n = { x = 265 }, c = { x = { { 0.00, "У нас очень немного записей, относящихся ко времени Войны Древних, а особенно – к периоду разрушения Источника Вечности." }, { 7.86, "Что неудивительно, если вспомнить о том, какие ужасные события и катаклизмы тогда происходили." }, { 14.44, "Спасибо вам. С вашей помощью моя работа здесь окончена, и я смогу представить Кругу Древних полный доклад." } } } } },
    [954] = { d = 36.8, v = "nightelf-male#54", n = { x = 415 }, c = { x = { { 0.00, "Руины Башал'Арана, расположенные к востоку отсюда, населены демоническими служителями зла." }, { 6.83, "Злые духи и сатиры, обосновавшиеся там, питаются магическими энергиями Башал'Арана, и силы их растут от постоянной подпитки энергией." }, { 16.99, "Но при этом я заметил, что к одному святилищу они не приближаются." }, { 21.63, "На западной стороне руин, на вершине небольшого утёса, распространяется странное синее свечение..." }, { 28.41, "Там и должно быть объяснение нежеланию демонов приближаться к этому месту." }, { 33.98, "Я хотел бы, чтобы вы его исследовали." } } }, t = { d = 32.7, g = 1, v = "nightelf-male", n = { x = 358 }, c = { m = { { 0.00, "Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная герой?" }, { 7.90, "На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение..." }, { 21.99, "Но, прошу вас, пусть мой грубый язык не заставит вас уйти." }, { 26.02, "Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания." } }, f = { { 0.00, "Ахх... Кому ж моя скромная персона обязана столь лестной для меня встречей с такой личностью, как вы, любезная героиня?" }, { 7.74, "На самом деле, не желая обижать моих гостеприимных хозяев – греллей и сатиров – это многое говорит о моих нынешних компаньонах, раз уж ваше присутствие может быть расценено как улучшение..." }, { 22.03, "Но, прошу вас, пусть мой грубый язык не заставит вас уйти." }, { 26.06, "Очень уж много лет, а то и десятилетий, прошло с тех пор, как у меня была приличная компания." } } } } },
    [955] = { d = 34.2, g = 1, v = "nightelf-male", n = { m = 395, f = 397 }, c = { m = { { 0.00, "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения." }, { 7.88, "Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук." }, { 17.55, "Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помог мне найти то, что держит меня здесь." }, { 27.60, "Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след." } }, f = { { 0.00, "Если бы я решил поведать тебе о своей жизни, не сомневаюсь, что повествование превзошло бы пределы твоего терпения." }, { 7.88, "Скажем так: в моей долгой жизни было много страданий, и существование в этом призрачном обличье, быть может, самая ужасная из моих мук." }, { 17.55, "Хотя мои слова могут показаться лицемерием, я уверяю тебя, что был бы невероятно благодарен, если бы ты помогла мне найти то, что держит меня здесь." }, { 27.42, "Некая печать связывает меня, и, изучая серьги злых духов и греллей, я могу напасть на её след." } } }, t = { d = 18.1, v = "nightelf-male", n = { x = 180 }, c = { x = { { 0.00, "И правда... Грелли Башал'Арана не владеют тем, что я ищу... Однако недавно они были в контакте с этим. Недавно..." }, { 9.39, "Я имею в виду по меркам твоего времени, не моего. Для меня \"недавно\" простирается глубоко в прошлое, почти что в другую эру..." } } } } },
    [956] = { d = 25.8, v = "nightelf-male", n = { x = 288 }, c = { x = { { 0.00, "Если грелли вступали в тесный контакт с той силой, что запечатывает мою вечную тюрьму, то, подозреваю, я знаю, в чём дело." }, { 8.33, "Несомнено эта печать находится во владении сатира, предводительствующего ими." }, { 14.03, "Я убеждён, что моя догадка верна. Она наверняка у одного из сатиров." }, { 19.27, "Если ты сможешь её добыть, то ты почти откроешь дверь моей темницы. Мне не сдержать слёз..." } } }, t = { d = 13.2, v = "nightelf-male", n = { x = 152 }, c = { x = { { 0.00, "Мне трудно поверить, что вещь, которую я сейчас держу в руках, так долго держала меня самого... Не будем тратить времени." }, { 8.26, "Когда печать будет уничтожена, я снова вольно смогу бродить по лесам." } } } } },
    [957] = { d = 18.5, v = "nightelf-male", n = { x = 219 }, c = { x = { { 0.00, "Эта печать, заточившая меня, некогда была изготовлена руками одного из самых могущественных высокорожденных." }, { 7.46, "В Амет'Аране – точно таких же руинах к югу отсюда – до сих пор горит древний синий огонь." }, { 13.33, "В этом огне печать может быть уничтожена. Будь осторожнее в тех руинах..." } } }, t = { d = 29.3, v = "nightelf-male", n = { x = 335 }, c = { x = { { 0.00, "Я свободен! Я могу собственными глазами видеть, какие изменения произошли с нашим миром... Я узнаю только отдельные фрагменты." }, { 9.55, "Подумать только, что когда я в последний раз гулял на свободе, ещё существовал Источник и высокорожденные держали совет с Азшарой, нашей любимой королевой." }, { 20.28, "Я чувствую, что мой тюремщик, мой бывший хозяин, Атрикус, ещё жив... Моё осознание безнадёжности вскоре сменится мыслями о мести." } } } } },
    [958] = { d = 35.4, g = 1, v = "nightelf-male#54", n = { x = 404 }, c = { m = { { 0.00, "герой. Вот задание, которое я вам поручаю." }, { 3.67, "Видели ли вы руины Амет'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда." }, { 11.07, "Когда-то Амет'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершённому их жалкими подражателями." }, { 21.47, "Мне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления." }, { 30.62, "Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить." } }, f = { { 0.00, "героиня. Вот задание, которое я вам поручаю." }, { 3.87, "Видели ли вы руины Амет'Арана? Если нет – их можно найти на востоке от главной дороги, несколько к югу отсюда." }, { 11.27, "Когда-то Амет'Аран служил домом для многих могущественных высокорожденных, а теперь это – памятник разрушению, совершённому их жалкими подражателями." }, { 21.67, "Мне говорили часовые, что духи высокорожденных по-прежнему обитают там и что они используют свои древние магические приспособления." }, { 30.82, "Эти реликвии нужно конфисковать, чтобы мы могли их уничтожить." } } }, t = { d = 15.1, v = "nightelf-male#54", n = { x = 177 }, c = { x = { { 0.00, "Хотя это, безусловно, лишь игра моего воображения, я чувствую себя так, будто бы ощущаю в этих реликвиях ядовитое дыхание магии высокорожденных." }, { 9.86, "Я их уничтожу, чтобы давно уснувшее зло больше никогда не пробудилось." } } } } },
    [959] = { d = 37.6, v = "goblin-male", n = { x = 379 }, c = { x = { { 0.00, "Ой!" }, { 1.29, "Как видишь, у меня сегодня приключилась неприятность! Утром из Пиратской бухты пришла поставка. И какая!" }, { 8.44, "Никогда не видел столько ящиков. Я хотел побыстрее закончить, поэтому поднимал больше, чем следовало." }, { 15.53, "В конце концов всё рухнуло на землю." }, { 18.44, "Не успел я оглянуться, как эта тварь, Безумный Магглиш, схватил бутылку портвейна девяносто девять-летней выдержки и бросился наутёк." }, { 29.33, "Я гнался за ним до самых Пещер Стенаний, но внутрь я не ходок." }, { 34.17, "Может, тебе хватит пороху, чтобы найти его?" } } }, t = { d = 8.1, v = "goblin-male", n = { x = 92 }, c = { x = { { 0.00, "Великолепно! И ведь меня едва не уволили! Теперь надо поскорее отнести подарок Газлоу. Спасибо. Отличная работа!" } } } } },
    [962] = { d = 44.0, v = "scourge-female", n = { x = 389 }, c = { x = { { 0.00, "Королевское фармацевтическое общество из великого Подгорода Лордерона направило меня сюда с очень необычной целью." }, { 10.45, "Возможно, вы сумеете помочь мне, а, стало быть, и Тёмной Госпоже в трудах на благо Отрёкшихся." }, { 19.24, "Не так давно я изучала редкий образец флоры под названием змеецвет." }, { 25.58, "Я уверена, что в большом количестве это растение таит в себе великие возможности." }, { 32.99, "Увы, змеецвет можно найти только в самых тёмных закоулках Пещер Стенаний, опасной системе подземелий в Степях." } } }, t = { d = 5.0, v = "scourge-female", n = { x = 43 }, c = { x = { { 0.00, "Ах, замечательные экземпляры! Вы хорошо поработали." } } } } },
    [963] = { d = 31.4, v = "nightelf-male#59", n = { x = 347 }, c = { x = { { 0.00, "После битв за Источник Вечности я узнал, что Амет'Аран разрушен, жители его погибли – в том числе и моя возлюбленная Анайя." }, { 9.54, "Я никогда не думал, что и через тысячи лет воспоминания об Анайе будут тревожить мои сны." }, { 15.75, "Бродя в помрачении рассудка по лесам на Тёмном Берегу, я очутился в руинах Амет'Арана..." }, { 21.64, "где и увидел неупокоенный дух моей любимой." }, { 25.10, "Её нужно освободить, но у меня просто рука не поднимается. Нужно уничтожить её призрак." } } }, t = { d = 14.3, v = "nightelf-male#59", n = { x = 160 }, c = { x = { { 0.00, "Благодарю тебя. Может быть, было бы лучше... если бы я сам это сделал." }, { 4.74, "Но даже после прошедших тысячелетий у меня нет сил поднять руку на свою возлюбленную." }, { 10.99, "Пожалуйста, оставь меня наедине с моим горем..." } } } } },
    [965] = { d = 31.7, g = 1, v = "nightelf-female#52", n = { m = 367, f = 369 }, c = { m = { { 0.00, "Привет тебе, юный герой. Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда." }, { 7.59, "С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда." }, { 17.41, "Но он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью." }, { 24.37, "Я была бы тебе очень благодарна, если бы ты смог найти его и удостовериться, что с ним всё в порядке." } }, f = { { 0.00, "Привет тебе, юная героиня. Меня зовут Элисса Звёздный Ветер, и моя задача – защищать Аубердин от всякого вреда." }, { 7.72, "С этой целью я послала Балтула Удар Тени вести наблюдение за странными событиями, происходящими близ башни Алталакса к северо-востоку отсюда." }, { 17.53, "Но он уже давно должен был вернуться. Боюсь, что он столкнулся в лесу с какой-то непредвиденной опасностью." }, { 24.49, "Я была бы тебе очень благодарна, если бы ты смогла найти его и удостовериться, что с ним всё в порядке." } } }, t = { d = 7.8, v = "nightelf-male#55", n = { x = 87 }, c = { x = { { 0.00, "Тебя прислала Элисса? Это хорошо. У меня есть для неё тревожные вести, но не было возможности передать их ей." } } } } },
    [966] = { d = 38.4, v = "nightelf-male#55", n = { x = 441 }, c = { x = { { 0.00, "Группа чернокнижников обосновалась вокруг и внутри башни." }, { 3.91, "Я хотел было вернуться в Аубердин и доложить Элиссе раньше, но побоялся, что могу что-то пропустить, пока буду отсутствовать." }, { 12.77, "Делгрен подозревал, что подобная компания может собираться у башни, но не знал, зачем." }, { 19.03, "Несколько обрывков свитков пергамента, которые носят с собой чернокнижники, попали в мои руки, но мне нужно знать больше, чтобы разгадать эту головоломку." }, { 29.48, "Однако я предостерегаю вас от попытки вторгнуться в саму башню: чернокнижники, засевшие там, гораздо сильнее!" } } }, t = { d = 23.9, v = "nightelf-male#55", n = { x = 279 }, c = { x = { { 0.00, "Большое спасибо. Это должно пролить некоторый свет на то, чем занимается это сборище чернокнижников..." }, { 7.16, "Хмм... Клан Тёмной Нити... Никогда раньше не слышал о такой группе." }, { 11.51, "Пока у нас нет никаких сведений об их истории, практически невозможно сказать, в чём могут заключаться их планы." }, { 19.40, "Больше нельзя тянуть. Нужно немедленно предупредить Делгрена." } } } } },
    [967] = { d = 28.2, v = "nightelf-male#55", n = { x = 319 }, c = { x = { { 0.00, "Мой хозяин, Делгрен Очиститель – паладин, любезно предоставивший свою помощь в защите наших лесов от сил демонов и нежити." }, { 8.81, "Он многое поведал мне о Божественном Свете и воинском искусстве." }, { 13.57, "Делгрен должен немедленно узнать о деятельности клана." }, { 17.97, "Вы найдёте его далеко на юге отсюда, на Заставе Мейстры в Ясеневом лесу." }, { 22.96, "Поторопитесь – я боюсь, что угроза клана Тёмной Нити растёт с каждым часом." } } }, t = { d = 31.3, g = 1, v = "human-male", n = { m = 354, f = 355 }, c = { m = { { 0.00, "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простого посланца, не так ли?" }, { 6.70, "Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки. Посмотрим, что он там пишет..." }, { 15.27, "Да, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их." }, { 23.02, "Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников." } }, f = { { 0.00, "Если позволите, я вам скажу: слишком уж вы хорошо экипированы для простой посланницы, не так ли?" }, { 6.77, "Предполагаю, Балтул хотел быть уверенным, что его письмо действительно попадёт мне в руки. Посмотрим, что он там пишет..." }, { 15.34, "Да, это тревожные новости. Когда обнаруживаются силы демонов или нежити, я помогаю часовым уничтожить их." }, { 23.09, "Вначале мне были непривычны манеры ночных эльфов, но постепенно я стал в высшей степени уважать их как союзников." } } } } },
    [968] = { d = 39.4, v = "human-male#114", n = { x = 411 }, c = { x = { { 0.00, "Хотя книга ужасно истрёпана и исцарапана, её название на обложке всё же можно разобрать: \"Подземные Силы\"." }, { 8.59, "В книге перечисляются непроизносимые имена со зловещими титулами, способами почитания и предпочтительными жертвоприношениями..." }, { 18.42, "И среди этих жертвоприношений числятся живые разумные создания." }, { 23.61, "На внутренней стороне обложки написано: \"Руны и Жребии Костохвата, Заброшенный грот, Стальгорн. Владелец: Геррик Костохват\"." }, { 33.59, "Если Костохват торгует подобными книгами, может быть, он выкупит эту?" } } }, t = { d = 30.2, g = 1, v = "dwarf-male", n = { m = 321, f = 324 }, c = { m = { { 0.00, "А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдёт его и полезным тоже..." }, { 7.01, "Но эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице!" }, { 13.70, "Хм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его друг? Да, должно быть, так." }, { 20.67, "У вас в глазах такой же огонь горит!" }, { 23.60, "Ну, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?" } }, f = { { 0.00, "А, экземпляр \"Подземных сил\". Интересный текст, да уж. А кое-кто найдёт его и полезным тоже..." }, { 7.01, "Но эта книга в ужасном состоянии. И поглядите-ка! Заметки на полях – почти на каждой странице!" }, { 13.70, "Хм... Я помню этот экземпляр. Я продал его Болгару в прошлом году. Вы его... его подруга? Да, должно быть, так." }, { 20.87, "У вас в глазах такой же огонь горит!" }, { 23.80, "Ну, по определению, друг Болгара – мой друг. А мы должны поддерживать близких людей, правда?" } } } } },
    [970] = { d = 26.4, v = "human-male", n = { x = 276 }, c = { x = { { 0.00, "Письмо Балтула приводит меня в ужас. Этот клан Тёмной Нити – сущее бельмо у меня на глазу, и его надо устранить!" }, { 7.77, "Мне приходилось иметь дело с мерзавцами из Тёмной Нити к северо-востоку отсюда в Ордиль-Аране." }, { 16.03, "У одного из них есть самоцвет Души, в котором, как я думаю, заключается секрет силы клана." }, { 22.59, "Принеси его мне, а уж я сумею разгадать его тайну." } } }, t = { d = 6.8, v = "human-male", n = { x = 75 }, c = { x = { { 0.00, "Хмм, этот самоцвет Души наполнен какой-то тёмной магией. Давай-ка посмотрим, что в нём таится..." } } } } },
    [971] = { d = 36.4, v = "dwarf-male", n = { x = 394 }, c = { x = { { 0.00, "Насколько вам известно, я собираю знания. Древние знания. Могучие знания." }, { 5.07, "Знания, что отворяют пути, знания, что могут пробудить Тех-Что-Спят." }, { 10.13, "Ходят слухи о старинном манускрипте Лоргалиса, будто бы он покоится в Непроглядной Пучине Ясеневого леса." }, { 17.39, "Некогда там жили эльфы, но они давно уже мертвы. Эльфы эти обладали великим знанием, до того как их город превратился в руины." }, { 26.45, "Найдите манускрипт в Непроглядной Пучине Сделайте это, и я не забуду вашей услуги. Даже после... скончания дней." } } }, t = { d = 20.8, v = "dwarf-male", n = { x = 238 }, c = { x = { { 0.00, "Вы нашли манускрипт! Что за радостный день!" }, { 3.12, "Мы сделаем с него копии и распространим, и древнее знание Лоргалиса станет достоянием наших братьев и сестёр!" }, { 11.09, "Вы даже не понимаете, какую услугу нам оказали." }, { 14.36, "Но я надеюсь, что этот дар покажет вам всю глубину нашей признательности нашим союзникам." } } } } },
    [973] = { d = 20.2, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Илкруд Магтрулл. Да, я знаю о нём." }, { 2.72, "Это могучий орочий чернокнижник, который поселился в Святилище Огненной Расщелины, месте великого зла на юго-западе Ясеневого леса." }, { 12.09, "Доныне он был не более чем досадной помехой, потому я и не трогал его, но, похоже, пришла пора с ним разобраться." } } }, t = { d = 9.9, g = 1, v = "human-male", n = { m = 110, f = 112 }, c = { m = { { 0.00, "Сегодня ты сделал большое дело. Гордись – ты сразил могущественного чернокнижника." }, { 5.96, "А теперь посмотрим, что сказано в записях Илкруда." } }, f = { { 0.00, "Сегодня ты сделала большое дело. Гордись – ты сразила могущественного чернокнижника." }, { 6.10, "А теперь посмотрим, что сказано в записях Илкруда." } } } } },
    [976] = { d = 25.0, v = "human-male", n = { x = 280 }, c = { x = { { 0.00, "Делгрен попросил меня доставить письма и припасы часовому Звёздный Ветер в Аубердин, но мне очень не хочется ехать в одиночку." }, { 8.84, "В лесу опасные враги, а я не хочу, чтобы эти припасы и информация попали не в те руки." }, { 15.14, "Если ты с остальными согласитесь охранять меня, то я смогу уехать прямо сейчас." }, { 20.75, "Под вашей защитой я точно доставлю всё это в Аубердин." } } }, t = { d = 13.2, g = 1, v = "human-male", n = { m = 144, f = 145 }, c = { m = { { 0.00, "Ты сегодня славно поработал, герой. То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес." }, { 9.33, "Прими это вместе с моей сердечной благодарностью." } }, f = { { 0.00, "Ты сегодня славно поработала, героиня." }, { 2.69, "То, что мы отослали в Аубердин, срочно необходимо для отражения тёмной угрозы, наводнившей лес." }, { 9.48, "Прими это вместе с моей сердечной благодарностью." } } } } },
    [981] = { d = 14.0, v = "nightelf-male#55", n = { x = 168 }, c = { x = { { 0.00, "За всю проделанную вами работу вы заслужили хорошую награду." }, { 4.17, "Возвращайтесь к Делгрену и скажите ему, что Атрикус Нарассин лежит, сражённый вашей рукой, а клан Тёмной Нити сокрушён, и остатки его рассеяны." } } }, t = { d = 13.3, v = "human-male", c = { x = { { 0.00, "Я знал, что вы возьмётесь за это задание." }, { 3.37, "Я чувствую, вас ждут великие дела и что вам суждено исцелить многие недуги, что терзают наши земли." }, { 10.31, "Примите моё благословение, и этот дар." } } } } },
    [982] = { d = 35.0, g = 1, v = "dwarf-male#99", n = { m = 418, f = 419 }, c = { m = { { 0.00, "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\"." }, { 8.62, "Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина." }, { 17.83, "Теперь корабли лежат на дне океана, став добычей мурлоков" }, { 22.09, "Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках." }, { 29.28, "Я хотел бы, чтобы ты добыл их для нас; это много значило бы для членов команды." } }, f = { { 0.00, "У побережья Тёмного Берега, к северу от нас, есть остатки двух потерпевших крушение кораблей – \"Серебряной Зари\" и \"Туманной Пелены\"." }, { 8.62, "Некоторое время назад моряки обоих кораблей не поладили с отвратительными мурлоками, когда плыли по безбрежному морю в сторону Аубердина." }, { 17.83, "Теперь корабли лежат на дне океана, став добычей мурлоков" }, { 22.09, "Оба капитана погибли в ту ночь, и их судовые журналы и ценные вещи по-прежнему лежат там, в денежных ящиках." }, { 29.28, "Я хотел бы, чтобы ты добыла их для нас; это много значило бы для членов команды." } } }, t = { d = 18.4, g = 1, v = "dwarf-male#99", n = { m = 215, f = 217 }, c = { m = { { 0.00, "Вы оказали нам огромную услугу, юноша. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход." }, { 7.81, "Что же касается вас, прошу вас принять это." }, { 10.78, "Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости." } }, f = { { 0.00, "Вы оказали нам огромную услугу, девушка. Мы позаботимся о том, чтобы за этими личными вещами был надлежащий уход." }, { 8.03, "Что же касается вас, прошу вас принять это." }, { 11.01, "Это самое маленькое, чем я могу отблагодарить за смелость, проявленную ради восстановления справедливости." } } } } },
    [983] = { d = 39.4, v = "goblin-male", n = { x = 412 }, c = { x = { { 0.00, "Слушай! Помоги мне с моим последним изобретением, Жужжалкой. С её помощью можно общаться на расстоянии!" }, { 7.53, "Может быть, ты уже видел их – такие ящики с рычагами. С ними одна проблема – за ними нужен постоянный уход." }, { 15.83, "У каждой из них есть своя проблема, но я нашёл хитрое решение." }, { 20.22, "Я поместил все машины в районе обитания существ, части которых нужны для починки каждой конкретной машины." }, { 27.73, "Сейчас неисправна Жужжалка восемьсот двадцать семь. Она находится чуть южнее Аубердина, совсем рядом с ним." }, { 35.19, "Чтобы её починить, нужно шесть ножек краба. Я заплачу..." } } }, t = { d = 28.7, g = 1, v = "goblin-male", n = { m = 302, f = 303 }, c = { m = { { 0.00, "Когда вы кладёте ножки крабов в приёмник машины, то слышите, как шестерни начинают их перемалывать." }, { 6.78, "По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли своё место." }, { 12.44, "Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины." }, { 18.40, "\"Алло! Уфф... Алло! Ты её починил! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить ещё одну машинку?\"" } }, f = { { 0.00, "Когда вы кладёте ножки крабов в приёмник машины, то слышите, как шестерни начинают их перемалывать." }, { 6.78, "По нескольким хлопающим звукам вы решаете, что ножки краба уже нашли своё место." }, { 12.44, "Вскоре машина начинает жужжать, и вы слышите голосок, едва доносящийся из машины." }, { 18.40, "\"Алло! Уфф... Алло! Ты её починила! Кстати, это Бацбах. Спасибо большое... Эй, не откажешься починить ещё одну машинку?\"" } } } } },
    [984] = { d = 30.6, v = "nightelf-male#54", n = { x = 356 }, c = { x = { { 0.00, "Некоторые из моих собратьев спаслись от порабощённых порчей фурболгов в Тельдрассиле, а я пообещал остановить злодеяния, пока кровь не полилась рекой..." }, { 10.47, "или не произошло чего-то ещё хуже." }, { 13.42, "Я уже вижу признаки присутствия скверны на Тёмных берегах, но она ещё не так распространилась." }, { 19.75, "Я думаю, было бы логично продолжить исследования фурболгов." }, { 23.88, "Может быть, ты найдёшь один из их лагерей, а затем вернёшься ко мне, если увидишь следы порчи?" } } }, t = { d = 10.4, v = "nightelf-male#54", n = { x = 116 }, c = { x = { { 0.00, "Это и вправду ужасные новости." }, { 2.79, "Поскольку фурболги находятся так близко к Аубердину, нам придётся приготовиться к неизбежному. Спасибо вам." } } } } },
    [985] = { d = 37.2, v = "nightelf-male#54", n = { x = 389 }, c = { x = { { 0.00, "Вы уже поднаторели в разведке на вражеских территориях. Но способны ли вы не только следить за врагами, но и биться с ними?" }, { 8.85, "Не все искатели приключений предпочитают честную битву лицом к лицу искусству скрытности и уклонения." }, { 18.17, "Если вы считаете, что готовы к сражению, то наибольшую угрозу нашему народу представляют сейчас фурболги в лагере к югу от Аубердина." }, { 28.19, "Вы найдёте там фурболгов Чернолесья. Убейте восемь следопытов и пять заклинателей ветра, а потом возвращайтесь сюда, ко мне." } } }, t = { d = 16.7, v = "nightelf-male#54", n = { x = 197 }, c = { x = { { 0.00, "Смойте кровь с ваших доспехов, и не мучайтесь из-за содеянного. Вместо этого вознесите благодарность судьбе." }, { 7.42, "Вы уменьшили угрозу нашему народу здесь, в Аубердине, даже если весь Тёмный Берег пока ещё находится в опасности из-за Мха Скверны." } } } } },
    [986] = { d = 38.7, v = "nightelf-male#54", n = { x = 451 }, c = { x = { { 0.00, "Ваше мастерство уже один раз сослужило мне хорошую службу в сложной ситуации." }, { 5.42, "Могу ли я вновь возложить на вас задачу помочь Мрачнокогтю и его хозяину Волкору?" }, { 11.21, "Я могу сделать для вас волшебный плащ, который позволит вам беспрепятственно ходить вблизи враждебных существ Тёмного Берега, пока вы будете искать Волкора." }, { 22.32, "Для изготовления плаща, чтобы хватило материала, мне нужно пять прекрасных шкур лунопарда, снятых со взрослых самцов или матриархов." }, { 31.47, "Этих кошек можно найти около Петляющей реки, к югу отсюда, или ещё дальше на юг, близ Ясеневого леса." } } }, t = { d = 24.4, v = "nightelf-male#54", n = { x = 282 }, c = { x = { { 0.00, "Эти шкуры отлично подойдут. Я немедленно приступаю к работе над плащом." }, { 5.26, "Дайте мне немного времени, а затем возвращайтесь." }, { 8.89, "Да, ещё кое-что: после того как вы задействуете чары, наложенные на плащ, вы будете ограничены в своём взаимодействии с другими лицами." }, { 17.97, "Если сможете, ограничьтесь только разговорами. Всё, что сверх этого, может развеять чары." } } } } },
    [990] = { d = 19.7, v = "nightelf-female#52", n = { x = 228 }, c = { x = { { 0.00, "Моя госпожа – Раэна Волкопас – ожидает тебя в городе Астранаар, что в Ясеневом лесу." }, { 5.88, "Возможно, с твоей помощью мы сможем хотя бы немного ослабить порчу, пустившую здесь корни." }, { 12.32, "Отправляйся отсюда на юг и держись дороги – ты легко найдёшь путь, если будешь держаться этого направления." } } }, t = { d = 19.6, g = 1, v = "nightelf-female#52", n = { x = 214 }, c = { m = { { 0.00, "А, герой с Тёмного Берега. Хорошо, что Селарин прислала тебя так быстро. Прости, что тебе пришлось так спешить." }, { 7.25, "Но с твоей помощью мы, возможно, сможем исправить положение." }, { 11.24, "Я бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь." } }, f = { { 0.00, "А, героиня с Тёмного Берега. Хорошо, что Селарин прислала тебя так быстро. Прости, что тебе пришлось так спешить." }, { 8.21, "Но с твоей помощью мы, возможно, сможем исправить положение." }, { 12.21, "Я бы начала с разговоров с другими жителями Астранаара. Многим наверняка понадобится твоя помощь." } } } } },
    [991] = { d = 34.2, v = "nightelf-female#52", n = { x = 411 }, c = { x = { { 0.00, "Один мой старый друг тоже помогает часовым здесь, в Ясеневом лесу, но он ещё не вернулся." }, { 6.35, "Он думает отыскать один предмет, который, по его мнению, ослабит нападения фурболгов на наш народ – это жезл, сделанный ныне покойным злым волшебником." }, { 16.44, "Прежде чем уйти, он упомянул, что будет искать драгоценный камень для жезла." }, { 21.78, "Он также говорил, что камень может находиться в святилище на озере Фалатим у подножия западных гор." }, { 28.17, "Камень хранился там до того, как святилище было разрушено. Найди моего друга, пожалуйста." } } }, t = { d = 12.4, v = "nightelf-male", n = { x = 143 }, c = { x = { { 0.00, "Покрытое ранами тело Терониса лежит на острове. По какой-то непонятной причине мурлоки бросили его здесь." }, { 7.56, "Глубокие резаные раны явно оставлены оружием и когтями мурлоков." } } } } },
    [993] = { d = 34.0, g = 1, v = "nightelf-male#54", n = { m = 373, f = 374 }, c = { m = { { 0.00, "Плащ готов. Пришло время найти Волкора. Я могу только надеяться, что мы успеем." }, { 6.42, "Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять." }, { 12.37, "Сам решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя." }, { 18.99, "Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги." }, { 27.17, "Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину." } }, f = { { 0.00, "Плащ готов. Пришло время найти Волкора. Я могу только надеяться, что мы успеем." }, { 6.42, "Магия, скрытая в плаще, если её пробудить, продержится недолго: может быть, минут пять." }, { 12.37, "Сама решай, когда использовать: я бы предложил подождать, пока не найдёшь Мрачнокогтя." }, { 18.53, "Если то, что он сказал мне – правда, ты найдёшь его хозяина в пещере к югу отсюда. Мрачнокоготь будет ждать тебя у дороги." }, { 26.71, "Помаши ему, когда увидишь, чтобы привлечь его внимание, и он укажет тебе путь к своему хозяину." } } }, t = { d = 16.0, v = "nightelf-male#55", n = { x = 169 }, c = { x = { { 0.00, "Чудесно! Терентис прислал мне помощь!" }, { 3.20, "О, посмотри-ка, ещё и плащ... кашляет Ох... Больно. Спасибо." }, { 7.37, "Фурболги ранили меня, прежде чем я сумел от них улизнуть. Дай мне ещё минутку, и я буду в состоянии разговаривать дальше." } } } } },
    [994] = { d = 19.7, v = "nightelf-male#55", n = { x = 227 }, c = { x = { { 0.00, "Ладно, силой так силой. Давайте убираться отсюда, как только вы будете готовы." }, { 5.38, "Мы пробьёмся к дороге – Мрачнокоготь должен всё ещё ждать. А там мы уже сможем разделиться." }, { 11.90, "Терентис сразу же захочет услышать ваш рассказ, поэтому вы направитесь в Аубердин, когда мы отсюда выберемся." } } }, t = { d = 13.0, g = 1, v = "nightelf-male#54", n = { m = 139, f = 139 }, c = { m = { { 0.00, "путник! Рад видеть вас живым и здоровым." }, { 3.42, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } }, f = { { 0.00, "путница! Рад видеть вас живой и здоровой." }, { 3.17, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } } } } },
    [995] = { d = 17.2, v = "nightelf-male#55", n = { x = 198 }, c = { x = { { 0.00, "Ну, ладно... Если вы уверены, попробуем выскользнуть отсюда. Мы уйдём, как только вы будете готовы." }, { 6.90, "Не забудьте после бегства отсюда вернуться к Терентису в Аубердин." }, { 11.41, "А я туда отправлюсь сам по себе, потому что, вероятно, буду двигаться быстрее вас." } } }, t = { d = 13.2, g = 1, v = "nightelf-male#54", n = { x = 139 }, c = { m = { { 0.00, "путник! Рад видеть вас живым и здоровым." }, { 3.48, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } }, f = { { 0.00, "путница! Рад видеть вас живым и здоровым." }, { 3.03, "Ваша помощь Волкору вселила в меня веру, что мы сможем преодолеть трудности, с которыми сталкиваемся на Тёмном Берегу и за его пределами." } } } } },
    [997] = { d = 24.9, g = 1, v = "nightelf-female#51", n = { m = 276, f = 278 }, c = { m = { { 0.00, "Так ты идёшь на юг? К озеру Аль'Амет? Если да, то не выполнишь ли ты одну мою просьбу..." }, { 6.29, "Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты." }, { 15.59, "Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что." }, { 22.05, "Не мог бы ты отнести ему эту землю?" } }, f = { { 0.00, "Так ты идёшь на юг? К озеру Аль'Амет? Если да, то не выполнишь ли ты одну мою просьбу..." }, { 6.29, "Мой собрат Деналан стоит лагерем у восточной оконечности озера, где изучает жизнь растений Тельдрассила и проводит свои эксперименты." }, { 15.59, "Ему нужна редкая земля из Дарнасса, но её доставили в Доланаар с опозданием – только что." }, { 22.05, "Не могла бы ты отнести ему эту землю?" } } }, t = { d = 10.6, g = 1, v = "nightelf-male#59", n = { m = 106, f = 106 }, c = { m = { { 0.00, "Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она ещё свежая..." }, { 5.16, "Спасибо тебе за доставку. Ты – герой, не жалеющий времени на благие дела!" } }, f = { { 0.00, "Наконец-то! Я уже давно жду эту редкую землю. Надеюсь, она ещё свежая..." }, { 5.16, "Спасибо тебе за доставку. Ты – героиня, не жалеющая времени на благие дела!" } } } } },
    [1001] = { d = 36.8, v = "human-male#114", n = { x = 334 }, c = { x = { { 0.00, "Тоненький голосок пробивается откуда-то из глубины машины." }, { 4.66, "\"Бацбах у аппарата! Следующая Жужжалка находится к северу от Аубердина, прямо на берегу." }, { 12.49, "Итак, номер той Жужжалки – четыреста одиннадцать, и для её починки нужно три глаза крепкозуба." }, { 19.67, "Эти твари водятся недалеко от берега! Крепкозубы Тёмного Берега... *И-ик!* Извини..." }, { 26.85, "Как и в прошлый раз, когда поместишь в Жужжалку то, что нужно, она выдаст тебе награду. *И-ик!* Что? Не, со мной всё в порядке!\"" } } }, t = { d = 28.5, g = 1, v = "human-male#114", n = { m = 270, f = 271 }, c = { m = { { 0.00, "Жужжалка оживает вскоре после того, как вы помещаете в неё глаза крепкозуба. После коротких помех вы слышите знакомый голосок." }, { 10.24, "\"Вино из крабов лучше всего...\" И-ик!" }, { 13.20, "\"Что? О, ты уже её починил! Ух, какой ты бысшшштрый. Так шшшо, согласишшшься почшшшинить ешшше одну?\"" }, { 21.23, "Вы уверены, что слышите, как жидкость льётся в ёмкость, а затем – звучные глотки." } }, f = { { 0.00, "Жужжалка оживает вскоре после того, как вы помещаете в неё глаза крепкозуба. После коротких помех вы слышите знакомый голосок." }, { 10.24, "\"Вино из крабов лучше всего...\" И-ик!" }, { 13.20, "\"Что? О, ты уже её починила! Ух, какая ты бысшшштрая. Так шшшо, согласишшшься почшшшинить ешшше одну?\"" }, { 22.06, "Вы уверены, что слышите, как жидкость льётся в ёмкость, а затем – звучные глотки." } } } } },
    [1002] = { d = 31.2, v = "human-male#114", n = { x = 293 }, c = { x = { { 0.00, "Жужжалка издаёт треск статических помех, и вы слышите голос Бацбаха." }, { 5.79, "\"Шшшледуюшшшая жужшшшалка – номер триста двадцать три. Она к шшшеверу от Аубердина, но... а хде жшшше эль? Шшшо?" }, { 14.21, "О, она шшштоит на дороге, так шшшо ты легко её найдешшшь около мосшшшт\"." }, { 20.22, "Бацбах что-то неразборчиво бормочет, а потом вы слышите отчётливый звук глотка." }, { 26.77, "\"В эту нужшшшно положшшшить клыки лунопардов... шшшесть\"." } } }, t = { d = 19.3, g = 1, v = "human-male#114", n = { m = 186, f = 187 }, c = { m = { { 0.00, "Неожидано Жужжалка начинает работать, и вы отчётливо слышите, как клыки перемалываются внутри машины в муку." }, { 8.85, "\"Так шшшо, ты это шшшделал! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?\"" } }, f = { { 0.00, "Неожидано Жужжалка начинает работать, и вы отчётливо слышите, как клыки перемалываются внутри машины в муку." }, { 8.85, "\"Так шшшо, ты это шшшделала! Отлишшшные новосшшшти... И шшшо жшшше... ты не уходишшшь? А! Можшшшет, хочешшшь ешшше поработать?\"" } } } } },
    [1003] = { d = 46.1, v = "human-male#114", n = { x = 434 }, c = { x = { { 0.00, "Сквозь булькающий шум и звуки капающей жидкости, исходящие от машины, вы слышите неверный голос Бацбаха." }, { 8.55, "\"Шшшледуюшший далеко на юг по доррроге. Найти должно быть нетрудно... шшшразу рядом на обочшшине... возле огражшшдения." }, { 17.56, "Думаю, я шшпрятал его в каких-то кусшшштах... Кусшшшты... Хи-хи..." }, { 22.66, "Да, Жужжшшалка пятьсот двадцать пять снимет сшшшедые шшшкальпы с этттих сшшшедых колючешшшшерстныхх медведей." }, { 32.74, "Божшшшежшшш мой, шшшто за пойло. Гнусшшшные... Хи-хи-хи...\"" }, { 37.33, "Вы слышите звуки жадных глотков, и машина выключается. Затем, совершенно неожиданно, вновь оживает. \"Четыре!\"" } } }, t = { d = 38.5, v = "goblin-male", n = { x = 449 }, c = { x = { { 0.00, "Так ты шшшшо, положшшил шшшкальпы внутрь? Хорошшшо... Шо?" }, { 3.89, "Агга, я шшшоображшшаю, шшшо могу разшшшговаривать шшш тобой и безшшш материалов в машшшине." }, { 10.82, "Но я пррравду грил, когда шшшказшшшал, шшшо они шшшломались!" }, { 15.41, "Шшшмотри, кроме шшшредшшштв коммунимакации эти жужжшшшалки ешшшё варят и дишшштиллируют отличшшшное питьё." }, { 22.89, "Просшшшти зшшша обман, но Ночшшшные эльфы не одобряют торррговли моими напитками в сшшшвоих городах." }, { 29.82, "Я оставлю нечшшшто осшшшобенное в этом яшшшике, шшшобы показать мою благодарносшшшть за твои усшшшилия. Насшшшлаждайся!" } } } } },
    [1007] = { d = 35.3, v = "nightelf-male#59", n = { x = 395 }, c = { x = { { 0.00, "Я хотел бы дать тебе поручение." }, { 2.51, "Я на своей маленькой лодочке плыл над затопленными руинами Зорама, когда на меня напали наги, выныривая из воды и вцепляясь в меня когтями!" }, { 12.20, "Я убежал, унеся с собой всё, что смог, и чего хватило лишь вот на этот жалкий лагерь." }, { 18.43, "Но когда я добрался до берега и побежал... я потерял одну дорогую мне вещь." }, { 23.90, "Прошу тебя, найди место засады – это на побережье к северу – и отыщи древнюю статуэтку." }, { 29.77, "Именно из-за неё я отважился подвергнуть себя опасностям Зорамского взморья." } } }, t = { d = 9.8, g = 1, v = "nightelf-male#59", n = { m = 106, f = 106 }, c = { m = { { 0.00, "Ты её нашёл! Спасибо тебе!" }, { 2.30, "Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них." } }, f = { { 0.00, "Ты её нашла! Спасибо тебе!" }, { 2.31, "Древний город Зорам хранит неисчислимые тайны, и эта статуэтка может послужить ключом ко многим из них." } } } } },
    [1008] = { d = 29.9, v = "nightelf-female#52", n = { x = 355 }, c = { x = { { 0.00, "По нашему северо-западному побережью, известному как Зорамское взморье, расползается зло." }, { 6.26, "Там покоятся руины злосчастного города Зорам, разрушенного при Расколе и поглощённого морем." }, { 12.35, "Для ночных эльфов он был утрачен на много веков. Утрачен и почти забыт." }, { 17.43, "Теперь туда вернулись наги, и мы не знаем, почему." }, { 20.81, "Но причина не так важна – мы должны перебить этих тварей и загнать их обратно в глубины!" }, { 26.96, "Возвращайся, когда выполнишь поручение." } } }, t = { d = 17.7, v = "nightelf-female#52", n = { x = 201 }, c = { x = { { 0.00, "Отлично. Твои деяния против наг на Зорамском взморье достойны похвалы." }, { 5.13, "Я знаю, что задание выполнить было нелегко, ибо сила и коварство наг прекрасно известны ночным эльфам." }, { 11.93, "Мы это знаем, ибо у нас одна история." }, { 14.84, "Но эту историю я вспоминать не желаю." } } } } },
    [1009] = { d = 29.9, v = "nightelf-male#59", n = { x = 342 }, c = { x = { { 0.00, "Боюсь, тайна этой древней статуэтки так и останется нераскрытой, если не нати ключа к этому древнему замку." }, { 7.74, "Этим ключом является кольцо – кольцо Зорама. Оно принадлежало правителям этого города до того, как волны Раскола поглотили его." }, { 16.77, "Долгие годы кольцо считалось утраченным, пока наги недавно не нашли его." }, { 22.13, "Их предводительница, Руузель, живёт на острове на северной окраине Зорама. Прошу тебя, добудь мне это кольцо!" } } }, t = { d = 9.6, g = 1, v = "nightelf-male#59", n = { m = 94, f = 97 }, c = { m = { { 0.00, "Ты добыл кольцо! Спасибо тебе. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты делал сегодня." } }, f = { { 0.00, "Ты добыла кольцо! Спасибо тебе. Прошу, возьми вот это в награду и знай, что я никогда не забуду того, что ты сделала сегодня." } } } } },
    [1010] = { d = 31.4, v = "nightelf-male#54", n = { x = 356 }, c = { x = { { 0.00, "Есть одна травка, что росла некогда в древних руинах Убежища Батрана на севере." }, { 5.61, "Звалась эта травка Батранов волос и славилась тем, что лечила болезни души." }, { 11.29, "В этой деревне болеет ребёнок, и сдаётся мне, что это болезнь не телесная." }, { 16.29, "Не сходишь ли ты в Убежище Батрана и не поищешь ли Батранов волос? Мне он может понадобиться, чтобы вылечить ребёнка." }, { 24.71, "Убежище Батрана лежит к северу от заставы Мейстры и прямо к югу от границы с Тёмным Берегом." } } }, t = { d = 15.5, g = 1, v = "nightelf-male#54", n = { m = 153, f = 155 }, c = { m = { { 0.00, "Ах, ты принёс эту травку! Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал." }, { 7.62, "И... В Убежище Батрана – Отрёкшиеся? Очень тревожная весть. Поистине, очень тревожная..." } }, f = { { 0.00, "Ах, ты принесла эту травку! Теперь я сварю лекарство для ребёнка, и будем молиться, чтобы отвар подействовал." }, { 7.98, "И... В Убежище Батрана – Отрёкшиеся? Очень тревожная весть. Поистине, очень тревожная..." } } } } },
    [1011] = { d = 29.6, v = "nightelf-male#54", n = { x = 335 }, c = { x = { { 0.00, "Отрёкшиеся, нежить из Орды, проникли в Ясеневый лес, и рыщут среди развалин и курганов." }, { 6.01, "Мы уверены, что их цель – распространить чуму по землям ночных эльфов. Мы должны убедиться в этом!" }, { 13.01, "Отрёкшиеся разбили лагерь к югу отсюда, рядом с Обителью Дор'Данил, где они готовят яды и заразу и разливают их по бутылкам." }, { 21.65, "Проложи себе путь в этот лагерь и укради бутыль с заразой. Принеси её сюда. Я исследую её и узнаю, для чего она." } } }, t = { d = 7.5, v = "nightelf-male#54", n = { x = 79 }, c = { x = { { 0.00, "Очень хорошо. Теперь, когда я проанализирую содержимое бутыли, станут понятны цели Отрёкшихся!" } } } } },
    [1013] = { d = 26.1, v = "scourge-male", n = { x = 281 }, c = { x = { { 0.00, "В крепости Тёмного Клыка хранится книга – книга Ура, я хочу видеть её в своей коллекции." }, { 6.40, "Ур был великим магом Даларана до того, как оказался в рядах Плети, и его труды по иным мирам представляют большой интерес... для некоторых Отрёкшихся." }, { 17.61, "Отправляйся в крепость Тёмного Клыка и найди книгу. Принеси мне её, и я сообщу о твоих заслугах Тёмной Госпоже." } } }, t = { d = 26.7, v = "scourge-male", n = { x = 281 }, c = { x = { { 0.00, "Прекрасно. Эта книга будет прекрасным дополнением моей коллекции трудов Ура." }, { 5.62, "Знания его были велики, однако ограниченность его сознания не давало ему обрести настоящую силу." }, { 12.83, "Именно поэтому он не смог противостоять Плети." }, { 16.82, "Мы, Отрёкшиеся, не можем позволить себе роскошь быть слабыми – ведь тогда нам не выжить..." }, { 23.75, "И уж тем более не обрести власть." } } } } },
    [1014] = { d = 39.7, v = "scourge-male#82", n = { x = 339 }, c = { x = { { 0.00, "Аругал по-прежнему сидит в крепости Тёмного Клыка." }, { 4.79, "Мы не можем считать Серебряный бор стратегическим оплотом Тёмной Госпожи до тех пор, пока Аругал жив." }, { 14.50, "Я позабочусь о том, чтобы искоренить его магию. Но сделать так, чтобы Аругал встретил заслуженную смерть – это я оставляю вам." }, { 26.04, "Отправляйтесь в крепость Тёмного Клыка и положите конец скверным деяниям Аругала раз и навсегда." }, { 35.89, "И принесите мне голову этого злодея!" } } }, t = { d = 12.8, v = "scourge-male#82", n = { x = 117 }, c = { x = { { 0.00, "Наконец-то Серебряный бор избавлен от злодеяний Аругала. Вы сослужили огромную службу Тёмной Госпоже. Ваша стойкость будет вознаграждена." } } } } },
    [1016] = { d = 32.7, v = "nightelf-female#52", n = { x = 407 }, c = { x = { { 0.00, "Бозьми этот гадальный свиток – он поможет определить создателя этих элементалей." }, { 5.19, "Но тебе понадобится кое-что взять у этих духов для фокусировки магии свитка – их браслеты прекрасно подойдут." }, { 12.66, "Хватит нескольких неповреждённых браслетов с этих существ." }, { 16.59, "Другие для наших целей бесполезны, но зато у торговцев за них можно кое-что выручить, если пожелаешь продать." }, { 23.88, "Как только ты добудешь неповреждённые браслеты, попытайся использовать свиток. Возвращайся ко мне с результатами, и мы продолжим." } } }, t = { d = 27.0, v = "nightelf-female#52", n = { x = 332 }, c = { x = { { 0.00, "Хорошая работа, это даст нам информацию, необходимую для того, чтобы раскрыть преступника." }, { 6.51, "Ты не против помочь нам схватить мага, который наполнил наши пруды порчеными элементалями?" }, { 12.21, "У меня сердце сжимается при виде осквернённого Ясеневого леса и других мест, и я просто сгораю от нетерпения схватить волшебника, который так старается ещё сильнее навредить этому краю. Мы заставим его за всё ответить." } } } } },
    [1017] = { d = 35.0, v = "nightelf-female#52", n = { x = 429 }, c = { x = { { 0.00, "Есть только один маг из нежити в Степях, способный наслать порчу на стольких элементалей воды." }, { 6.30, "И он единственный, кому хватит дури попытаться это сделать." }, { 10.06, "Сарилус Грязнорождённый, наверное, сидит на вершине Вершины Багрового Тумана, да смеётся надо мной." }, { 16.93, "Тебе придётся проникнуть на вражескую территорию и уничтожить этого мерзавца." }, { 22.11, "Мне надоела его бестолковость, и надо показать ему, что бывает с теми, кто донимает часовых." }, { 28.42, "Уничтожь его и принеси мне его голову. Но соблюдай осторожность, Орда может подкараулить тебя." } } }, t = { d = 15.7, v = "nightelf-female#52", n = { x = 168 }, c = { x = { { 0.00, "Теперь эта мерзкая ухмылка навсегда стёрта с его лица. Славное, воистину славное дело." }, { 5.71, "Возьми – это Свет Элуны, испей его, когда будет казаться, что всему конец, и смерть неминуема. Он спасёт тебя по воле Богини." } } } } },
    [1020] = { d = 14.6, v = "nightelf-male#54", n = { x = 166 }, c = { x = { { 0.00, "Я изготовил лекарство, которое, надеюсь, поможет больному ребёнку. Отнеси его в Астранаар отцу ребёнка, Пельтуру Белой Луне." }, { 8.78, "Чтобы добраться до Астранаара, ступай по дороге сначала на юг, потом на восток." } } }, t = { d = 10.2, v = "nightelf-male#54", n = { x = 112 }, c = { x = { { 0.00, "Это от Орендила?" }, { 1.72, "Он славен знанием трав и лекарским искусством. Это лекарство вселяет в меня надежду, которой прежде у меня почти не было..." } } } } },
    [1022] = { d = 31.4, v = "nightelf-female#52", n = { x = 388 }, c = { x = { { 0.00, "Хотя мы затратили много средств и сил на то, чтобы вытеснить остатки демонов из Осквернённого леса на север, успехи наши невелики." }, { 8.66, "Нам удалось не допустить большую часть демонов в Ясеневый лес." }, { 13.08, "На севере, у границы Осквернённого леса, разрушенное святилище Мел'Тандрис захватили загадочные волколюди." }, { 20.30, "Из-за их пронзительных воплей это место называют теперь Воющей Долиной." }, { 24.94, "Фолиант Мел'Тандрис, что хранится в святилище может пролить свет на появление там волколюдей." } } }, t = { d = 20.7, v = "nightelf-female#52", n = { x = 242 }, c = { x = { { 0.00, "Фолиант Мел'Тандрис действует странным образом. События, которые он записывает, события, которые он показывает..." }, { 7.32, "Никто тольком не понимает, почему он делает то, что делает." }, { 11.99, "Тем не менее, понятно, что предмет, который получила жрица Звёздная Песня – эта коса Элуны – требует дальнейшего исследования." } } } } },
    [1023] = { d = 19.7, v = "nightelf-male", n = { x = 205 }, c = { x = { { 0.00, "Осматривая вещи Терониса, вы находите дневник, который всё ещё в неплохом состоянии." }, { 6.21, "Вы берёте дневник и оставляете труп Терониса." }, { 9.73, "Остаётся только найти камень, который искал Теронис. Раэна говорила, что он где-то здесь. Возможно, его забрали мурлоки..." } } }, t = { d = 22.5, v = "nightelf-female#52", n = { x = 258 }, c = { x = { { 0.00, "Это ужасно. Теронис мёртв?!" }, { 2.41, "Мы оплачем его, когда придёт пора, но сейчас надо сосредоточить усилия на другом." }, { 7.72, "Я отправлю часовых за телом Терониса как можно скорее." }, { 11.68, "У тебя дневник Терониса и камень, который он искал. Как думаешь – ты сумеешь завершить его дело?" }, { 18.08, "Моя душа успокоится, если я буду знать, что он не попусту погиб." } } } } },
    [1024] = { d = 35.2, g = 1, v = "nightelf-female#52", n = { m = 423, f = 424 }, c = { m = { { 0.00, "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла." }, { 11.48, "Я бы начала поиск от лунного колодца к востоку от озера Ирис." }, { 15.56, "Когда будешь готов, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя." }, { 23.05, "Дриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди её." }, { 27.64, "Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл." } }, f = { { 0.00, "Тебе придётся провести исследование самостоятельно, но, судя по заметкам Терониса, следующим твоим шагом, похоже, будет поиск остальных фрагментов созданного Дартолом жезла." }, { 11.48, "Я бы начала поиск от лунного колодца к востоку от озера Ирис." }, { 15.56, "Когда будешь готова, ступай по этой дороге и сверни на север у небольшого местечка для отдыха слева от тебя." }, { 23.11, "Дриада Шаэлдрин будет тебе лучшим, чем я, проводником. Найди её." }, { 27.71, "Возьми с собой этот самоцвет – он может понадобиться Шаэлдрин, если она решит помочь тебе восстановить жезл." } } }, t = { d = 5.9, v = "named/3916", n = { x = 66 }, c = { x = { { 0.00, "О, так тебя послала Раэна? Тогда это и правда серьёзное дело. Чем я могу тебе помочь?" } } } } },
    [1025] = { d = 32.8, g = 1, v = "nightelf-female#52", n = { m = 396, f = 396 }, c = { m = { { 0.00, "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу." }, { 10.42, "На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников." }, { 17.47, "Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв." }, { 23.60, "Помоги часовым защитить эти края, отплати этим чудовищам их же монетой." }, { 28.54, "Думаю, их лагерь находится к югу от дороги... будь осторожен." } }, f = { { 0.00, "Если ты желаешь испытать свои умения и заодно помочь жителям Ясеневого леса, я дам тебе ещё одно поручение, прежде чем ты отправишься к лунному колодцу." }, { 10.42, "На дороге, что сворачивает на восток перед рекой Фалфаррен, фурболги в последнее время нападают на путников." }, { 17.47, "Их извращённый разум питается страхом, а кровожадность утоляется кровью невинных жертв." }, { 23.60, "Помоги часовым защитить эти края, отплати этим чудовищам их же монетой." }, { 28.54, "Думаю, их лагерь находится к югу от дороги... будь осторожна." } } }, t = { d = 2.6, v = "nightelf-female#52", n = { x = 24 }, c = { x = { { 0.00, "Славная работа. Спасибо тебе." } } } } },
    [1026] = { d = 35.3, v = "named/3916", n = { x = 418 }, c = { x = { { 0.00, "Хотелось бы мне, чтобы у тебя были более хорошие новости." }, { 4.08, "Раэна права, я знаю о творении Дартола и древнях этих краёв – или знала прежде. Они теперь все осквернены, их природа искажена." }, { 12.84, "Если твоя цель – найти ещё один фрагмент жезла, то тебе придётся найти ключ, чтобы отпереть сундук, в котором он лежит." }, { 20.96, "Деревянный ключ – на одном из древней к северу отсюда, близ Осквернённого леса." }, { 26.04, "Как только добудешь его, ищи небольшую лощинку к западу от дороги близ границы Осквернённого леса..." }, { 32.44, "Сундук должен быть спрятан где-то там." } } }, t = { d = 2.1, v = "named/3916", n = { x = 22 }, c = { x = { { 0.00, "Я рада твоему возвращению." } } } } },
    [1027] = { d = 29.8, v = "named/3916", n = { x = 352 }, c = { x = { { 0.00, "Последний фрагмент жезла был отдан на хранение друидам Дор-Даниля. Я понятия не имею, где они его спрятали." }, { 7.18, "Сожалею, что больше ничем не могу тебе помочь." }, { 10.60, "Могу только сказать, что тебе следует идти по дороге, что ведёт в Степи." }, { 15.22, "Друиды скрывались к востоку от этой дороги, но они тебе уже не помогут – недавно их перебили..." }, { 21.29, "мне не очень хочется об этом думать." }, { 24.03, "Когда найдёшь последний фрагмент, принеси его мне, и я помогу тебе воссоздать жезл." } } }, t = { d = 8.5, g = 1, v = "named/3916", n = { m = 89, f = 89 }, c = { m = { { 0.00, "Ты нашёл последний фрагмент? Тебе очень повезло... И Раэне тоже." }, { 5.12, "Как понимаю, нам надо попытаться собрать его, да?" } }, f = { { 0.00, "Ты нашла последний фрагмент? Тебе очень повезло... И Раэне тоже." }, { 4.97, "Как понимаю, нам надо попытаться собрать его, да?" } } } } },
    [1028] = { d = 32.3, v = "named/3916", n = { x = 384 }, c = { x = { { 0.00, "Вот собранный жезл. Восстановить его было просто... Труднее будет найти святилище, в котором жезл можно будет наполнить силой." }, { 8.64, "Но при твоих целеустремлённости и усердии, после всех твоих достижений тебе не слишком трудно будет его найти." }, { 16.21, "Ступай на юго-восток – там очень мало торных дорог, так что будь осторожнее – и посматривай на север." }, { 22.77, "Святилище скрыто в горах, что окружают эту долину." }, { 26.48, "Как только ты окажешься там, положи жезл в святилище... а остальное сделает магия. Хе-хе." } } }, t = { d = 5.9, v = "named/3916", n = { x = 71 }, c = { x = { { 0.00, "Когда свечение угасает, вы видите в купели святилища заново наполненный чарами жезл." } } } } },
    [1029] = { d = 8.6, v = "named/3916", n = { x = 92 }, c = { x = { { 0.00, "Советую тебе найти Раэну и сказать ей, что жезл воссоздан. Я уверен, она знает, куда тебе направиться дальше. Удачи." } } }, t = { d = 11.8, g = 1, v = "nightelf-female#52", n = { m = 137, f = 138 }, c = { m = { { 0.00, "Ты собрал жезл, который отправил тебя искать Теронис? Это приятно слышать." }, { 5.26, "Теронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели." } }, f = { { 0.00, "Ты собрала жезл, который отправил тебя искать Теронис? Это приятно слышать." }, { 5.25, "Теронис был бы счастлив, узнав, что его задание выполнено даже после его трагической гибели." } } } } },
    [1030] = { d = 35.1, v = "nightelf-female#52", n = { x = 400 }, c = { x = { { 0.00, "Увы, не могу сказать, что у него было на уме." }, { 3.29, "Если он сказал правду о силе жезла, то тогда ты сможешь принимать тот или иной образ. Какой – не знаю." }, { 10.46, "Может, он намеревался использовать его мощь, чтобы подобраться поближе к этим мерзостным фурболгам, но даже не затронутые порчей существа убили бы его, не будь он осторожен." }, { 22.01, "Дартол, превращённый при помощи жезла, должен был бы поговорить с фурболгом, не подпавшим под порчу Мха Скверны." }, { 30.49, "На мой взгляд, надо начать поиски к юго-востоку от озера Мистраль." } } }, t = { d = 34.8, v = "tauren-male", n = { x = 318 }, c = { x = { { 0.00, "Да-да... ты мой сородич, но ты здоровый. Пока ещё чистый." }, { 5.14, "Не знаю, как уж тебе удалось избежать тех злодеяний, что ночные эльфы обрушили на наш народ, но я рад, что больше я не одинок." }, { 15.33, "Нынче порча бежит в жилах наших сородичей, малыш, порча, насланная на нас спесивыми ночными эльфами." }, { 24.66, "Это они с нами такое сделали... Они виноваты в том, что меня изгнали из племени." }, { 31.01, "По ночам я по-прежнему вижу костры в темноте." } } } } },
    [1033] = { d = 35.8, v = "nightelf-male#54", n = { x = 415 }, c = { x = { { 0.00, "Я надеялся, что лекарство Орендила спасёт Релару, но, боюсь, оно лишь немного ослабило болезнь, поселившуюся в теле моей дочери." }, { 8.88, "Мы должны найти более мощное средство!" }, { 11.66, "К счастью, Орендил говорил мне, какие ещё он попытается применить лекарства, если первое не поможет." }, { 18.71, "Слеза Элуны – это такой камень, который можно найти только в одном месте – на острове в озере Ирис к востоку от Астранаара." }, { 26.82, "Орендил сказал, что этот камень снимает порчу... прошу тебя, принеси мне Слезу Элуны, и да покончит она с болезнью моей дочери!" } } }, t = { d = 9.1, g = 1, v = "nightelf-male#54", n = { m = 76, f = 76 }, c = { m = { { 0.00, "О, ты нашёл её! Я опущу Слезу в отвар и буду молиться, чтобы он помог ей. Спасибо тебе! Спасибо тебе!" } }, f = { { 0.00, "О, ты нашла её! Я опущу Слезу в отвар и буду молиться, чтобы он помог ей. Спасибо тебе! Спасибо тебе!" } } } } },
    [1034] = { d = 29.5, v = "nightelf-male#54", n = { x = 298 }, c = { x = { { 0.00, "Слеза Элуны немного облегчила страдания моей дочери. Кошмары стали реже её мучить, хвала богине. Но... лихорадка всё ещё сжигает её." }, { 9.40, "Орендил рассказал мне о морозной пыли, которую находят среди руин Звёздной Пыли. Может, она усмирит лихорадку Релары." }, { 19.60, "Собери немного этой пыли, прошу тебя, и принеси её мне." }, { 23.80, "Руины Звёздной Пыли находятся на юге. Да ускорит твой шаг Элуна!" } } }, t = { d = 10.7, v = "nightelf-male#54", n = { x = 117 }, c = { x = { { 0.00, "Ты принёс пыль! Я сделаю из неё припарки – они должны унять лихорадку Релары." }, { 5.63, "Ещё раз спасибо тебе. Без твоей помощи моё дитя несомненно умерло бы." } } } } },
    [1035] = { d = 30.6, g = 1, v = "nightelf-male#54", n = { m = 333, f = 333 }, c = { m = { { 0.00, "Лихорадка Релары прошла, но она ещё очень слаба. Я не верю, что только время вернёт ей былую силу." }, { 6.69, "Мне кажется, тут нужна мощь лунного камня." }, { 9.95, "Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники." }, { 17.45, "Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты должен отнять лунные камни у Оракула." }, { 27.36, "И, боюсь, для этого тебе придётся его убить." } }, f = { { 0.00, "Лихорадка Релары прошла, но она ещё очень слаба. Я не верю, что только время вернёт ей былую силу." }, { 6.69, "Мне кажется, тут нужна мощь лунного камня." }, { 9.95, "Мы обычно собирали лунный камень у озера Зеркало Небес к юго-востоку отсюда... пока не пришли чащобники." }, { 17.45, "Их предводитель, Чащобный Оракул, собрал все рассыпанные лунные камни и припрятал их. Ты должна отнять лунные камни у Оракула." }, { 26.51, "И, боюсь, для этого тебе придётся его убить." } } }, t = { d = 17.0, g = 1, v = "nightelf-male#54", n = { m = 172, f = 175 }, c = { m = { { 0.00, "О, ты спас мою дочь! Я знаю, что сила лунного камня вернёт моей дочери силы!" }, { 6.65, "Мне никогда не отблагодарить тебя за всё, что ты для меня сделал, но... пожалуйста, возьми вот это." }, { 13.34, "После Релары это самое дорогое, что есть у меня." } }, f = { { 0.00, "О, ты спасла мою дочь! Я знаю, что сила лунного камня вернёт моей дочери силы!" }, { 6.36, "Мне никогда не отблагодарить тебя за всё, что ты для меня сделала, но... пожалуйста, возьми вот это." }, { 13.05, "После Релары это самое дорогое, что есть у меня." } } } } },
    [1037] = { d = 32.5, v = "nightelf-female#52", n = { x = 387 }, c = { x = { { 0.00, "Велинда Песнь Звёзд была моей предшественницей здесь, в Ясеневом лесу." }, { 4.76, "Поначалу казалось, что она держдит под контролем ситуацию в Осквернённом лесу, но понемногу её усилия стали сходить на нет. И однажды она просто исчезла." }, { 15.23, "Меня послали сюда продолжить её труды. Однако, боюсь, я ничего не знаю об этой жрице." }, { 20.95, "Возможно, Тин'тель Танец Клинка, одна из командиров часовых, знает подробности её исчезновения, о которых не знаю я." }, { 29.07, "Наверняка она поймёт значение такой информации." } } }, t = { d = 13.2, v = "nightelf-female#52", n = { x = 162 }, c = { x = { { 0.00, "Велинда Песнь Звёзд? То, что эта жрица пропала некоторое время назад, известно всем." }, { 5.56, "Что касается событий, окружавших её исчезновение... Чтобы поделиться такой информацией, мне нужна веская причина." } } } } },
    [1038] = { d = 28.9, v = "nightelf-female#52", n = { x = 345 }, c = { x = { { 0.00, "Значит, это ты вычитал в фолианте Мел'Тандрис? Думаю, ничего страшного не будет, если ты осмотришь её вещи." }, { 6.83, "Этот ключ позволит тебе отпереть сундук, в котором она держала свои пожитки в казарме часовых." }, { 12.77, "Она вела дневник, и если что-то можно узнать, то только из него." }, { 17.49, "Должна тебе сказать, что часовые считают, что у неё была причина уйти, и ждут её возвращения в любой момент." }, { 24.83, "Эта жрица многими своими делами заслужила наше доверие." } } }, t = { d = 18.1, g = 1, v = "nightelf-female#52", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу." }, { 5.45, "Но я всё равно не могу поверить, что она плохо кончила. Может, нам лучше будет найти её?" }, { 11.66, "Раз уж ты проявил живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой." } }, f = { { 0.00, "Похоже, что исчезновение Велинды – не столь безобидное дело, как казалось поначалу." }, { 5.45, "Но я всё равно не могу поверить, что она плохо кончила. Может, нам лучше будет найти её?" }, { 11.66, "Раз уж ты проявила живой интерес к этому делу, то я была бы рада заручиться твоей поддержкой." } } } } },
    [1039] = { d = 29.9, v = "nightelf-female#52", n = { x = 362 }, c = { x = { { 0.00, "Кабестан – единственный порт в Степях. Скорее всего, Велинда нашла там торговое судно, которое шло в бухту Черноводья в Азероте." }, { 8.41, "Мы ограничили сделки с гоблинами, которые руководят портом, но смотритель пристани наверняка знает, какие пассажиры взошли на борт, а какие сошли на берег." }, { 19.00, "Следуй по дороге на юго-восток через Ясеневый лес, и попадёшь в Степи. Смотри по сторонам, эти края патрулируют солдаты Орды." }, { 27.42, "Но в порту ты будешь в безопасности." } } }, t = { d = 16.0, g = 1, v = "goblin-male", n = { x = 161 }, c = { m = { { 0.00, "герой? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да?" }, { 5.83, "Минуточку, сейчас гляну в своих учётных списках." }, { 9.52, "Через порт проходит куча народу, так что подожди минутку, сделай милость." } }, f = { { 0.00, "героиня? Должен сказать, твоих сородичей тут у нас нечасто увидишь. Кого-то ищешь, да?" }, { 7.03, "Минуточку, сейчас гляну в своих учётных списках." }, { 10.71, "Через порт проходит куча народу, так что подожди минутку, сделай милость." } } } } },
    [1040] = { d = 36.0, v = "goblin-male", n = { x = 401 }, c = { x = { { 0.00, "А, наконец-то, нашёл. Надо было сразу сказать, что она проезжала здесь давно. Посмотрим." }, { 6.47, "Велинда. Оплатила проезд до Пиратской бухты на \"Чёрной Скопе\"." }, { 10.79, "Никаких дополнительных пометок нет – значит, она благополучно добралась до места назначения." }, { 17.58, "Больше ничем я помочь не могу, хотя она спрашивала, какие средства передвижения есть по ту сторону моря, и я упомянул Раззгота, водящего караваны из Пиратской бухты." }, { 28.85, "Быть может, Велинда отправилась с ним." }, { 32.02, "Ну всё, давай, иди. Не весь же день с тобой болтать." } } }, t = { d = 13.4, g = 1, v = "goblin-male", n = { m = 139, f = 141 }, c = { m = { { 0.00, "Да? Не похоже, чтобы ты хотел отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратился. Я угадал?" } }, f = { { 0.00, "Да? Не похоже, чтобы ты хотела отправить какой-нибудь груз, так что ты либо хочешь устроиться подработать в мой караван – а сейчас работы нет, – либо не к тому обратилась. Я угадал?" } } } } },
    [1041] = { d = 31.1, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "Оказывается, я ошибался насчёт тебя, а я это не часто признаю." }, { 4.82, "Оказывается, я помню эту Велинду. Не каждый день жрица ночных эльфов желает отправиться в путь со старым грязным – но превосходным для транспортировки товаров – караваном вроде моего." }, { 17.55, "По пути на север мы разделились, и она направилась в Темнолесье. Тамошний клерк ведёт записи. Может, он знает что полезное." }, { 26.34, "Осторожнее в джунглях, они даже в лучшие времена – опасное место." } } }, t = { d = 16.6, v = "human-male", n = { x = 189 }, c = { x = { { 0.00, "В последние годы случилось много странного, и я стараюсь вести записи про всех чужаков. Никогда не узнаешь, что пригодится..." }, { 8.60, "Хотя когда эти записи оказываются нужны, добра не жди... Нет, про вашу Велинду я не хочу сказать ничего дурного." } } } } },
    [1042] = { d = 30.7, v = "human-male", n = { x = 342 }, c = { x = { { 0.00, "Нет, у меня не сохранилось записей о пребывании Велинды Песни Звёзд в Темнолесье..." }, { 5.80, "Хотя, прошу прощения за прямоту, не могу представить, чтобы жрица ночных эльфов снимала комнату в гостинице, если ты понимаешь, о чём я." }, { 15.60, "А вот о волко-людях я слышал, и не раз. Только недавно Калор явился в город, неся целую связку их голов." }, { 22.89, "Он работает на Кэрвинов. Они охотятся на демонов и прочих чудовищ. Поговори с Джонатаном, он глава их дома." } } }, t = { d = 18.4, v = "human-male#50", n = { x = 218 }, c = { x = { { 0.00, "Тёмные настали времена. Каждая ветвь в лесу нашёптывает дурные вести, зло таится под каждым камнем." }, { 7.06, "И в такую пору незнакомец приходит в мой дом и задаёт вопросы про воргенов..." }, { 11.86, "Прощения за свои подозрения я просить не буду, зато потребую ответить на них. И получу ответ." } } } } },
    [1043] = { d = 30.5, g = 1, v = "human-male#50", n = { m = 357, f = 358 }, c = { m = { { 0.00, "Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты готов избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат." }, { 12.41, "Воргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника." }, { 20.82, "Ступай по своим делам, но если найдёшь что-нибудь важное, расскажи об этом мне." }, { 26.14, "Мы готовы принять любую помощь в нашей войне с силами зла." } }, f = { { 0.00, "Кажется, ты говоришь правду... Я не до конца понимаю твои мотивы, но если ты готова избавить Сумеречный лес хотя бы от небольшой части воргенов, я не буду допытываться. Важен результат." }, { 12.69, "Воргены захватили рудник на юге. Они появились внезапно, но, насколько нам известно, нашествие началось именно с рудника." }, { 21.09, "Ступай по своим делам, но если найдёшь что-нибудь важное, расскажи об этом мне." }, { 26.42, "Мы готовы принять любую помощь в нашей войне с силами зла." } } }, t = { d = 20.0, g = 1, v = "human-male#50", n = { x = 231 }, c = { m = { { 0.00, "Интересные вещи ты рассказываешь, герой." }, { 2.76, "Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить её раз и навсегда, мы делаем всё, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу." }, { 15.69, "Я уже велел Калору уделить этому первоочередное внимание." } }, f = { { 0.00, "Интересные вещи ты рассказываешь, героиня." }, { 2.84, "Хотя семья Карвин не настолько влиятельна, чтобы добраться до корня проблемы и решить её раз и навсегда, мы делаем всё, что в наших силах, чтобы уменьшить число воргенов в Сумеречном лесу." }, { 15.77, "Я уже велел Калору уделить этому первоочередное внимание." } } } } },
    [1044] = { d = 20.8, g = 1, v = "human-male#50", n = { m = 243, f = 244 }, c = { m = { { 0.00, "Мы разберёмся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на неё." }, { 8.55, "Странные вещи творятся в наши времена, и тьма не ведает пощады." }, { 13.24, "Не буду тебя задерживать. Уверен, многие захотят узнать о том, что ты обнаружил в рудниках Сумеречного леса." } }, f = { { 0.00, "Мы разберёмся с воргенами, не беспокойся. Искореним зло, которое твоя подруга невольно принесла в наши леса. Мы не в обиде на неё." }, { 8.55, "Странные вещи творятся в наши времена, и тьма не ведает пощады." }, { 13.24, "Не буду тебя задерживать. Уверен, многие захотят узнать о том, что ты обнаружила в рудниках Сумеречного леса." } } }, t = { d = 22.7, v = "nightelf-female#52", n = { x = 271 }, c = { x = { { 0.00, "Так вот какова судьба Велинды? Верховная жрица огорчится, услышав об этом – они очень дружили до исчезновения Велинды." }, { 7.93, "И всё же Коса Элуны несомненно была дарована Велинде нашей богиней, и очень плохо, что этот священный предмет попал в недобрые руки." }, { 17.08, "Впрочем, это отдельный разговор. Я премного благодарна тебе за твои достижения." } } } } },
    [1045] = { d = 39.3, v = "tauren-male", n = { x = 378 }, c = { x = { { 0.00, "Ночные эльфы стары, как время, но их надменность разрушает их собственный мир. А теперь ещё и наши жизни." }, { 8.06, "Но это уже никак не получится контролировать..." }, { 12.03, "Я много в чём могу обвинять эльфов, но мы всё равно отвечаем за свои деяния." }, { 18.09, "Даже не подвергнувшись порче, мы способны творить великое зло." }, { 23.45, "Рэн Кровавый Клык – такое зло. Жаждущий мощи, алчный... порча только сделала его сильнее." }, { 31.44, "Меня сжигает ненависть к эльфам, но я не хочу зла их детям, так что сами должны обуздать своих." } } }, t = { d = 3.3, v = "tauren-male", n = { x = 24 }, c = { x = { { 0.00, "Славная работа. Спасибо тебе." } } } } },
    [1046] = { d = 8.4, v = "tauren-male", n = { x = 77 }, c = { x = { { 0.00, "Возвращайся в своё племя и поведай им о нашей победе." }, { 4.71, "Покажи им свой трофей и насладись славой..." } } }, t = { d = 24.9, v = "nightelf-female#52", n = { x = 288 }, c = { x = { { 0.00, "Значит, вот он – череп самого лютого фурболга в Ясеневом лесу?" }, { 4.50, "Я более чем довольна твоими способностями. Не знаю даже, как часовым отблагодарить тебя." }, { 10.40, "Надеюсь, в будущем мы снова сможем положиться на тебя, чтобы помочь нашему народу." }, { 16.08, "Я положу этот череп и жезл Дартола на почётное место, чтобы все их увидели." }, { 21.38, "Теронис гордился бы тобой. Ещё раз спасибо тебе." } } } } },
    [1054] = { d = 28.7, v = "nightelf-female#52", n = { x = 346 }, c = { x = { { 0.00, "Прямо к северу от Астранаара живут фурболги Колючего Меха." }, { 3.87, "Мои разведчики доносят, что в последние несколько месяцев они чрезвычайно умножились числом." }, { 10.06, "Если они слишком расплодятся, то могут набраться наглости напасть на Астранаар!" }, { 15.53, "Убей их, сколько сможешь, главное – принеси мне череп их предводителя в знак того, что их усилия напрасны...пока." }, { 23.00, "Я останусь в Астранааре и буду ждать вестей от тебя. Да пребудет с тобой Элуна." } } }, t = { d = 8.3, v = "nightelf-female#52", n = { x = 91 }, c = { x = { { 0.00, "Славная работа." }, { 1.53, "Эти фурболги постоянно угрожают нам. По счастью, теперь они некоторое время будут сидеть тихо." } } } } },
    [1055] = { d = 6.2, v = "human-male#114", n = { x = 62 }, c = { x = { { 0.00, "Воссозданный жезл у вас в руках. Шаэлдрин захочет услышать о ваших успехах." } } }, t = { d = 2.4, v = "named/3916", n = { x = 26 }, c = { x = { { 0.00, "У тебя получилось! Великолепно!" } } } } },
    [1056] = { d = 31.9, g = 1, v = "nightelf-male#54", n = { m = 359, f = 359 }, c = { m = { { 0.00, "Лесные духи говорят мне, что ты отважен и лёгок на подъём." }, { 4.49, "На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя." }, { 9.99, "Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах." }, { 15.85, "Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя." }, { 25.73, "Там ждёт хранитель Албагорм. Выслушай его просьбу, герой. Путешествие будет опасным." } }, f = { { 0.00, "Лесные духи говорят мне, что ты отважна и легка на подъём." }, { 4.46, "На юге, неподалёку от озера Мистраль, находится туннель, именуемый Туннель Когтя." }, { 9.95, "Через этот туннель ты попадёшь в место, называемое Утёс Ветрорезов, в Когтистых горах." }, { 15.82, "Попав туда, иди на юго-запад мимо Скалистого озера, а затем на север, вверх по крутому склону, пока не доберёшься до Пика Каменного Когтя." }, { 25.69, "Там ждёт хранитель Албагорм. Выслушай его просьбу, героиня. Путешествие будет опасным." } } }, t = { d = 4.2, v = "nightelf-male", n = { x = 44 }, c = { x = { { 0.00, "Наконец-то! Вижу, Фальдреас прислушался к духам лесов..." } } } } },
    [1057] = { d = 37.4, v = "nightelf-male", n = { x = 432 }, c = { x = { { 0.00, "Несомненно, будучи защитником лесных духов, можешь догадаться, почему я так встревожен." }, { 6.32, "Чтобы достигнуть этого пика, тебе пришлось пройти через горы, и, конечно же, от глаз твоих не ускользнуло искажение, постигшее эту землю." }, { 15.60, "Алчность привела к уничтожению священных холмов." }, { 19.19, "Обугленная долина на юге сожжена механической армией жадных промышленников." }, { 24.50, "Хуже того, клан Смертельной Ярости, вторгшийся на эти земли, отказывается пропустить нас – а ведь мы могли бы начать восстановление тех краёв! Изгони прочь злобных гарпий!" } } }, t = { d = 9.0, v = "nightelf-male", n = { x = 107 }, c = { x = { { 0.00, "Теперь, когда клан Смертельной Ярости понёс большие потери, вероятно, и начнётся истинная работа по восстановлению этих земель..." } } } } },
    [1058] = { d = 44.3, v = "troll-male", n = { x = 429 }, c = { x = { { 0.00, "Я в восхищении!" }, { 1.74, "Три маленьких клетки для трёх маленьких эльфов. Ну-с, что бы нам сделать с нашими дорогими друзьями-древолюбами?" }, { 10.95, "Что ж, дадим им попробовать... как бы это они сказали... лесной магии!" }, { 16.62, "Мне нужна добрая порция слизи Каменного Когтя. Принеси мне несколько сумеречных усиков этих ужасных кошек." }, { 25.45, "И конечно же, потребуется множество глаз бегового оленя – глаз всегда не хватает!" }, { 32.00, "Да, и ещё, последнее, чуть не забыл: драгоценную чешуйку волшебного дракончика." }, { 38.57, "Живо в Каменный Коготь, чтобы я мог сварить немножко лесной магии!" } } }, t = { d = 10.6, v = "troll-male", n = { x = 104 }, c = { x = { { 0.00, "О, как счастливы будут эти маленькие лесные нимфы! Мы заставим их почувствовать себя как дома при помощи этого особого отвара!" } } } } },
    [1059] = { d = 37.6, v = "nightelf-male", n = { x = 435 }, c = { x = { { 0.00, "Мы одержали победу над кланом Смертельной Ярости. Но они скоро соберут силы и вернутся, если не предпринять решительные действия." }, { 9.26, "Далеко на юге Пустошей находится земля, известная как Тысяча Игл." }, { 13.80, "Если идти на запад Тысячи Игл до тех пор, пока не достигнешь границ густого леса Фералас, то встретишь друида по имени Фалфиндер Хранитель Дорог." }, { 24.31, "Этот сильный и мудрый друид способен призвать великих лесных духов, которые помогут в восстановлении Обугленной долины." }, { 32.86, "Поведай ему о нашей беде! Отправляйся на его поиски немедленно!" } } }, t = { d = 14.2, v = "nightelf-male#54", n = { x = 165 }, c = { x = { { 0.00, "Хранитель Албагорм поступил мудро, прислав тебя со срочным известием." }, { 5.02, "Будем надеяться, что мы успеем призвать помощь, и что эта помощь из великого леса прибудет в Обугленную долину не слишком поздно." } } } } },
    [1060] = { d = 30.2, g = 1, v = "orc-male", n = { m = 312, f = 313 }, c = { m = { { 0.00, "Ты сделал мне много добра. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё." }, { 7.47, "Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе." }, { 14.81, "Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу." }, { 21.69, "Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место." } }, f = { { 0.00, "Ты сделала мне много добра. Можно сказать, ты мой талисман удачи, и я хочу поручить тебе кое-что ещё." }, { 7.49, "Гарпии не всегда жили в Степях, они происходят из гор Каменного Когтя, раскинувшихся на северо-западе." }, { 14.83, "Хоть там и опасно, мне нужно послать письмо старому другу, живущему там, знахарю Джин'Зилу." }, { 21.72, "Он будет рад, узнав о смерти Серены Кровавое Перо, а тебе в тех краях понравится. Занятное место." } } }, t = { d = 21.0, v = "troll-male", n = { x = 193 }, c = { x = { { 0.00, "А, письмо от Дарсока. Давно от него не было вестей." }, { 4.63, "Значит, последняя из Кровавых Перьев мертва? Отличные вести." }, { 9.73, "Я хорошо помню, как мой друг Рокхан пошёл убивать её старшую сестру с этим психом из Мок'Натала." }, { 17.54, "Да, тогда я был молод, как ты сейчас." } } } } },
    [1061] = { d = 33.5, v = "orc-male", n = { x = 361 }, c = { x = { { 0.00, "Духи Когтистых гор разгневаны: гоблины и их приспешники разоряют и выжигают земли." }, { 6.52, "Земля возопила, и те, кто способен слышать – услышали." }, { 10.70, "В Когтистые горы отправилась Сирит Камнеломм, многообещающий шаман Орды." }, { 15.87, "Она сообщает, что гоблины вырубили много леса, и просит о помощи." }, { 20.97, "Отправляйся в Когтистые горы, найди там Сирит. Чтобы туда добраться, ступай от Перекрёстка в Степях по дороге на запад." }, { 29.28, "Сирит стоит лагерем близ Долины Высокого леса." } } }, t = { d = 7.1, g = 1, v = "orc-female", n = { x = 66 }, c = { m = { { 0.00, "А, герой! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!" } }, f = { { 0.00, "А, героиня! Очень кстати. Нам понадобится твоя помощь, чтобы управиться с этими лиходеями!" } } } } },
    [1062] = { d = 34.7, v = "orc-female", n = { x = 394 }, c = { x = { { 0.00, "Торговая Компания, которой управляют гоблины, вторглась в Когтистые горы. Они валят деревья, выжигают большие участки леса." }, { 8.70, "Духи этих земель вне себя от боли и ярости. Мы должны остановить Торговую Компанию!" }, { 15.02, "Отправляйсся на северо-запад, за Долину Высокого леса, к Утёсу Ветрорезов." }, { 20.15, "Ты найдёшь гоблинов и их прислужников за работой – покажи же им, что Орда не позволит разорять Когтистые горы." }, { 28.04, "Поговори с ними на том языке, который они лучше всего понимают... На языке беспощадной силы!" } } }, t = { d = 17.1, v = "orc-female", n = { x = 188 }, c = { x = { { 0.00, "Это подлинно отважное деяние." }, { 2.80, "Вероятно, в конце концов нам понадобится мудрость тауренских старейшин, чтобы успокоить духов Каменного Когтя, но..." }, { 11.23, "Первый шаг в верном направлении сделан – Торговая Компания лишилась работников." } } } } },
    [1063] = { d = 37.2, v = "orc-female", n = { x = 414 }, c = { x = { { 0.00, "Чтобы узнать, как окончательно успокоить духов Когтистых гор, нам нужно посоветоваться со старейшинами тауренов." }, { 8.07, "Я мало знаю о том, кто предводительствует тауренами, но одно имя мне известно: Магата." }, { 14.85, "Я слышала, что она очень стара и много знает. Если кто из тауренов и может оказать нам помощь касательно духов, то это она." }, { 23.81, "Магата живёт в главном городе тауренов Громовом Утёсе, на Вершине Старейшин – это северо-восточная вершина города." }, { 31.97, "Поговори с Магатой и расскажи ей о том, что творится в Когтистых горах." } } }, t = { d = 3.4, v = "named/4046", n = { x = 29 }, c = { x = { { 0.00, "Я приветствую тебя. Ты ищешь совета?" } } } } },
    [1064] = { d = 40.3, v = "named/4046", n = { x = 390 }, c = { x = { { 0.00, "Таурены в сродстве с этой землёй, и мне больно слышать о том, что творится в Каменном Когте." }, { 7.09, "Но я боюсь, что для исцеления этой земли нам прежде придётся справиться с той заразой, что терзает нас самих." }, { 16.09, "Разве не удача, что Отрёкшиеся теперь с нами? Они много знают о заразных болезнях." }, { 22.64, "Я уверена, что они смогут помочь нам и тем укрепят доверие между нашими народами." }, { 29.61, "Поговори с аптекаршей Замой. Она – учёная и представитель Отрёкшихся. Ты найдёшь её у Прудов Видений под Уступом Духов." } } }, t = { d = 18.3, v = "scourge-female", n = { x = 138 }, c = { x = { { 0.00, "Магата прислала о тебе весточку. Хотя сердце моё уже и не бьётся, оно всё же разрывается от горя по духам Каменного Когтя." }, { 13.59, "Отрёкшиеся готовы помочь всем, чем только можно." } } } } },
    [1065] = { d = 54.5, v = "scourge-female", n = { x = 464 }, c = { x = { { 0.00, "Нам придётся прибегнуть к чрезвычайным мерам, чтобы избавить Каменный Коготь от Торговой Компании. Но только без кровопролития." }, { 11.60, "У одного моего коллеги может найтись то, что нам как раз для этого случая и нужно." }, { 19.22, "Его зовут Лидон, он живёт в городе Мельница Таррен в предгорьях Хилсбрада, в далёком краю Лордерон." }, { 29.35, "Чтобы добраться до Хилсбрада, отправляйся на дирижабле в нашу столицу, Подгород." }, { 37.34, "Оттуда иди на север в Тирисфальские леса, что к юго-западу от Серебряного бора, а затем на юг, в Хилсбрад." }, { 47.20, "Найди Лидона и передай ему эту записку. Там написано, что нам от него нужно." } } }, t = { d = 10.4, v = "scourge-male", n = { x = 90 }, c = { x = { { 0.00, "Записка от Замы? Наверняка её сильно прижало, раз пишет в такую даль. Посмотрим..." }, { 7.46, "Замечательно! Я знаю, что ей надо!" } } } } },
    [1066] = { d = 32.9, v = "scourge-male", n = { x = 347 }, c = { x = { { 0.00, "Я создам яд, который остудит пыл Торговой Компании. Они станут слабыми и покорными." }, { 6.18, "Это же решит проблемы Орды в Каменном Когте, да?" }, { 10.15, "Но для создания отравы мне понадобится кровь невинных, а её нелегко найти." }, { 16.09, "К счастью, Синдикат, группа грабителей, насчитывает в своих рядах несколько тёмных магов..." }, { 22.63, "а они собирают кровь невинных для своих нечистых целей." }, { 27.19, "Тёмных магов Синдиката можно найти в крепости Дарнхольд на юго-востоке." } } }, t = { d = 18.4, v = "scourge-male", n = { x = 181 }, c = { x = { { 0.00, "Очень хорошо! Надеюсь, Синдикат не причинил тебе особых проблем?" }, { 5.69, "Как я и говорил, кровь невинных не так уж легко добыть. Нам повезло, что трудную часть работы взяли на себя маги Синдиката." }, { 15.10, "А теперь подожди, я создам мой состав..." } } } } },
    [1067] = { d = 25.0, v = "scourge-male", n = { x = 280 }, c = { x = { { 0.00, "Вот отрава. Если воспользоваться ей против Торговой Компании, результаты должны оказаться весьма благоприятными – возможно, удастся добиться даже распростанения новой заразы." }, { 12.55, "Мне не терпится испытать свою работу в деле!" }, { 16.35, "Впрочем, прежде отнеси её аптекарю Заме. Она должна придумать наиболее эффективный способ использования отравы." } } }, t = { d = 10.5, v = "scourge-female", n = { x = 92 }, c = { x = { { 0.00, "Отрава от аптекаря Лидона? Замечательно. Если я знаю Лидона, она очень хорошо подействует на Торговую Компанию..." } } } } },
    [1068] = { d = 39.0, v = "orc-female", n = { x = 429 }, c = { x = { { 0.00, "Есть связь между духовной магией шаманов и природной магией друидов." }, { 4.82, "Именно поэтому мы, шаманы, можем слышать мольбы духов Каменного Когтя." }, { 9.77, "Я могу разобрать не всё, что они шепчут, однако одно послание - одно видение - было чётким..." }, { 16.36, "В этом видении я узрела на Утёсе Ветрорезов, на северо-западе Долины Высокого леса, две человекоподобные машины, которые валили деревья с невероятной скоростью." }, { 27.51, "Этих металлических тварей нужно остановить!" }, { 30.98, "В явленном мне видении я заметила, что машины эти отмечены странными символами: XT:четыре и XT:девять." } } }, t = { d = 20.9, v = "orc-female", n = { x = 220 }, c = { x = { { 0.00, "Уничтожение машин XT:четыре и XT:девять успокоило многих духов Каменного Когтя." }, { 5.78, "Будем надеяться, что после потери этих машин Торговая Компания покинет эти горы." }, { 12.04, "Ибо если этого не произойдёт, то бедствия, постигшие эти земли, могут оказаться бледной тенью того, что ждёт нас впереди." } } } } },
    [1069] = { d = 31.3, v = "goblin-male", n = { x = 349 }, c = { x = { { 0.00, "В Пиратской бухте фантастический спрос на омлеты из паучьих яиц! Проблема в том... что яиц в Бухте нет. Я чую прибыль!" }, { 8.44, "На Утёсе Ветрорезов и в Сиширском каньоне, в Когтистых горах на северо-западе, живут моховые пауки." }, { 15.35, "Принеси мне их яйца, и я неплохо заплачу!" }, { 18.66, "На Утёсе Ветрорезов паучьи кладки можно найти под оставшимися деревьями." }, { 24.11, "В Сиширском каньоне... хм, если у тебя слабый желудок, можешь собирать яйца только на Утёсе Ветрорезов..." } } }, t = { d = 11.0, v = "goblin-male", n = { x = 111 }, c = { x = { { 0.00, "Ты принёс мне яйца! Спасибо!" }, { 2.36, "Я пошлю их Дыбоволосу, и он переправит мой товар в Пиратскую бухту!" }, { 7.43, "Вот твоя доля. Без тебя мне бы не справиться." } } } } },
    [1070] = { d = 33.9, v = "nightelf-female#52", n = { x = 383 }, c = { x = { { 0.00, "Привет тебе." }, { 1.30, "Судя по виду, ты много путешествуешь. Тебе приходилось бывать в Когтистых горах?" }, { 6.70, "Эта земля опустошена Торговой компанией и прочими врагами ночных эльфов." }, { 11.87, "Недавно часовой Волкопас послала туда мою подругу Келу Копьё Тени, чтобы она узнала, что происходит в тех землях, однако до сих пор от неё нет вестей." }, { 22.76, "Я ещё беспокоюсь и потому, что Альянс отправил вместе с ней гнома-мага... это, несомненно, повод для тревоги." }, { 30.27, "Может быть, ты найдёшь её и пошлёшь весточку мне?" } } }, t = { d = 14.7, v = "nightelf-female#52", n = { x = 170 }, c = { x = { { 0.00, "А, так ты здесь по просьбе Тары из Ясеневого леса... я так скучаю по ней, по моей родине, по друзьям." }, { 6.64, "Должно быть, ей хорошо среди часовых, раз прочие дела передаёт путникам. Я горжусь за неё. Рада познакомиться с тобой." } } } } },
    [1071] = { d = 35.2, v = "gnome-male", n = { x = 405 }, c = { x = { { 0.00, "Понимаешь ли, я состою в Просвещённой Ассамблее Чародейства, Алхимии и Технических Наук, и моя цель... нет, мой ДОЛГ!" }, { 7.75, "– показать ночным эльфам, что единение магии, реактивов и механизмов поможет спасти их леса." }, { 14.32, "Однако это тяжёлая война, а гоблины, похоже, плодятся, словно кролики." }, { 19.59, "У меня даже нет времени воплотить в жизнь свои новые изобретения!" }, { 24.43, "Мне нужно время для планирования и организации." }, { 27.79, "Но для этого мне потребуется твоя помощь – сдерживать натиск гоблинов у Утёса Ветрорезов к востоку отсюда..." } } }, t = { d = 32.8, v = "gnome-male", n = { x = 384 }, c = { x = { { 0.00, "Спасибо тебе за помощь. Да и вернуться тебе удалось как раз вовремя." }, { 5.12, "Кажется, я выработал идеальный план... взрывчатка. Нет, это не сам план, это его часть." }, { 11.19, "Понимаешь ли, я использую сильные взрывчатые вещества – не волнуйся, они далеко не так опасны, как считается – для того, чтобы припугнуть гоблинов." }, { 20.97, "Я смогу как следует нагнать на них страху, разместив в ключевых местах на границах горной местности заряды, однако в ближайшие несколько дней мне может не хватить материалов..." } } } } },
    [1072] = { d = 39.8, v = "gnome-male", n = { x = 420 }, c = { x = { { 0.00, "Устройство, о котором я думаю – моя самая продвинутая версия на сегодняшний день." }, { 5.57, "Но мне нужно особое зелье, чтобы это устройство заработало." }, { 9.69, "Я думаю, нам нужно добыть хороший состав, поскольку эта миссия может стать для тебя последней." }, { 16.51, "А для этого нам нужно мощное взрывчатое вещество: нитромирглицероний." }, { 21.65, "Единственный, кто может создать НГ-пять, это мой старый приятель – Ломак Демонтирс. Поищи его в Городе Механиков." }, { 30.36, "Если уговоришь его сделать для нас немного НГ-пять, то я начну работать над размещением своих устройств." } } }, t = { d = 7.1, v = "gnome-male", n = { x = 58 }, c = { x = { { 0.00, "А-а-а... Тебя послал Гаксим, вот как? А откуда мне знать, что ты не врёшь? Ась? Ась?.." } } } } },
    [1073] = { d = 36.5, v = "gnome-male", n = { x = 407 }, c = { x = { { 0.00, "Ха-ха-ха!.. Тебе нужен нитромирглицероний, чтобы остановить гоблинов, уничтожающих лес?!" }, { 6.26, "Мне всё равно, знаешь ты Гаксима или нет..." }, { 9.19, "я дам тебе этот состав, чтобы посмотреть, как кого-нибудь разнесёт на мелкие кусочки: или тебя, или гоблинов." }, { 16.82, "Но есть проблемка: у меня кончились химикалии." }, { 20.49, "Но вот что я тебе скажу: принесёшь мне нужные зелья, и я прямо сразу же смешаю для тебя составчик." }, { 27.63, "По крайней мере, ты докажешь, что кое-что понимаешь в алхимии, прежде, чем я передам тебе образец своего величайшего творения." } } }, t = { d = 11.0, v = "gnome-male", n = { x = 117 }, c = { x = { { 0.00, "Вот это подойдёт." }, { 1.81, "Не знай я тебя, я бы сказал, что ты кое-что понимаешь в алхимии... Ладненько, ладненько..." }, { 7.54, "в мире есть не только мечи и колдовство, верно?" } } } } },
    [1074] = { d = 13.1, v = "gnome-male", n = { x = 135 }, c = { x = { { 0.00, "Ну вот тебе, держи. Тока поосторожней... это летучая смесь." }, { 4.92, "Если Гаксим тебе и вправду друг, передай ему от меня привет. А если нет – взлетишь на воздух, вот будет тебе потеха." } } }, t = { d = 14.8, v = "gnome-male", n = { x = 156 }, c = { x = { { 0.00, "Дело сделано, и сделано отлично." }, { 2.66, "НГ-пять незаменимый компонент для поджига повозок с динамитом." }, { 7.26, "Что? Да, динамит... целыми повозками. Это идеальный отвлекающий манёвр, я тебе скажу... подожди и увидишь." } } } } },
    [1075] = { d = 37.1, g = 1, v = "gnome-male", n = { m = 406, f = 407 }, c = { m = { { 0.00, "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого?" }, { 7.87, "Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия." }, { 15.94, "Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся НГ-пять." }, { 23.68, "Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен." }, { 29.74, "Ты сможешь отыскать его там в квартале магов. Он человек, так что будь внимателен, не ошибись." } }, f = { { 0.00, "Теперь о том, что касается дистанционных взрывов, входящих в мой план... ах да, я, кажется, ещё не объяснил этого?" }, { 7.87, "Ну так вот, вкратце: задействовав немного магии, я смогу сделать так, чтобы взрыв произошёл почти без твоего участия." }, { 15.94, "Я соберу такое устройство, что тебе останется просто нажать кнопку, а где-то там взорвётся НГ-пять." }, { 23.68, "Но мне нужно заклинание, которое есть у моего друга в Штормграде – его зовут Коллин Маурен." }, { 29.74, "Ты сможешь отыскать его там в квартале магов. Он человек, так что будь внимательна, не ошибись." } } }, t = { d = 6.8, v = "human-male", n = { x = 76 }, c = { x = { { 0.00, "Да, вот то заклинание, которое тебе нужно – оно позволит производить взрывы на расстоянии... хмм." } } } } },
    [1076] = { d = 32.8, v = "human-male", n = { x = 372 }, c = { x = { { 0.00, "А, кажется, я понял. Заклинание послания... полагаю, именно этого эффекта он хочет добиться." }, { 6.61, "Мне нужно создать свиток с запечатлённым на нём заклинанием. Для этого мне нужен прах Пыледемона." }, { 13.68, "Пока я собираю остальные компоненты, почему бы тебе не отправиться в Западный Край и не найти там одно из этих мерзких существ?" }, { 22.55, "Они опасны, но я уверен, что ты со всем справишься, если желаешь участвовать в одном из экспериментов Гаксима. Когда ты вернёшься, я буду здесь." } } }, t = { d = 4.4, v = "human-male", n = { x = 49 }, c = { x = { { 0.00, "Подожди несколько секунд, и нужный тебе свиток будет готов." } } } } },
    [1077] = { d = 12.0, v = "human-male", n = { x = 129 }, c = { x = { { 0.00, "Вот. Это то, что нужно." }, { 2.11, "Когда в следующий раз увидишь Гаксима, передай ему от меня привет. Хотелось бы мне узнать, как закончится эта история. Всего тебе хорошего." } } }, t = { d = 20.0, v = "gnome-male", n = { x = 223 }, c = { x = { { 0.00, "Великолепно! Славная работа." }, { 2.38, "Это заклинание вместе с НГ-пять даст идеальную дистанционную взрывчатку." }, { 7.64, "У нас получится прекрасный отвлекающий манёвр, и ты прокрадёшься и сопрёшь документы и инженерные планы Торговой Компании." }, { 16.43, "Тогда они не смогут вырубать леса так быстро." } } } } },
    [1078] = { d = 39.5, v = "human-male", n = { x = 455 }, c = { x = { { 0.00, "Путешественники постоянно спрашивают меня о Когтистых горах." }, { 4.23, "Похоже, все ищут там приключений, причём самых разных: кому-то нужны виверны, кому-то – элементали, а у кого-то дела с Торговой компанией." }, { 13.95, "В Обугленной долине, прячущейся среди пиков Когтистых гор, некогда обитали особые виды василисков: их чешуя, размолотая в порошок, была прекрасным реактивом для некоторых заклинаний, созданных мною." }, { 27.70, "Если эти василиски ещё живут там, мне надо заполучить хотя бы несколько чешуек." }, { 33.62, "Если не очень торопишься, удели на это немного времени, я хорошо заплачу тебе." } } }, t = { d = 6.5, v = "human-male", n = { x = 67 }, c = { x = { { 0.00, "Великолепно. Спасибо тебе огромное." }, { 2.89, "Может быть, и я когда-нибудь смогу помочь тебе." } } } } },
    [1079] = { d = 29.9, v = "gnome-male", n = { x = 348 }, c = { x = { { 0.00, "Так вот, смотри и слушай внимательно. Все устройства доделаны и готовы к использованию." }, { 6.39, "Возьми эти листы – здесь всё объясняется про детонаторы, взрывчатку и про то, как их разместить." }, { 13.33, "Помни, успех твоей миссии не зависит от того, сколько разрушений ты сможешь причинить." }, { 19.24, "План \"Альфа\" увенчается успехом в том случае, если ты принесёшь технические чертежи Торговой компании, находящиеся на лесопилке к югу от Скалистого Озера." } } }, t = { d = 13.8, v = "gnome-male", n = { x = 159 }, c = { x = { { 0.00, "Просто великолепно! Это сильный удар по Торговой Компании." }, { 4.44, "Мы сможем узнать уязвимые места их машин, а также использовать их разработки для наших собственных целей. Поистине, это великий день." } } } } },
    [1080] = { d = 19.6, g = 1, v = "gnome-male", n = { x = 206 }, c = { m = { { 0.00, "План Бета – почти то же, что и план Альфа. путник." }, { 4.00, "Мы проводим отвлекающий манёвр, а потом похищаем их драгоценные письма." }, { 9.26, "Главное – получить письма... помни это." }, { 12.19, "На листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами..." } }, f = { { 0.00, "План Бета – почти то же, что и план Альфа. путница." }, { 3.88, "Мы проводим отвлекающий манёвр, а потом похищаем их драгоценные письма." }, { 9.14, "Главное – получить письма... помни это." }, { 12.06, "На листках, которые я дал тебе, сказано, где поместить взрывчатку. Не погибни и вернись с добытыми письмами..." } } }, t = { d = 8.9, v = "gnome-male", n = { x = 93 }, c = { x = { { 0.00, "Великолепно! Каэла и часовые будут счастливы. При твоих умениях да моих творениях нас никто и ничто не остановит!" } } } } },
    [1081] = { d = 22.9, v = "nightelf-female#52", n = { x = 272 }, c = { x = { { 0.00, "Я уверена, что Тиранда Шелест Ветра лично хотела бы поблагодарить тебя за участие в этой миссии." }, { 6.67, "Может быть, это и незаметно с первого взгляда, но деяния, совершённые с твоей помощью, способны помочь нам закрепиться в Когтистых горах." }, { 16.06, "Если хочешь и далее помогать нам в борьбе, отправляйся на встречу с Тирандой в храм Луны в Дарнассе." } } }, t = { d = 19.3, g = 1, v = "nightelf-female#173", n = { m = 174, f = 175 }, c = { m = { { 0.00, "Приветствую тебя. Мне доводилось и прежде слышать твоё имя, и я рада видеть, что, не взирая на твою молодость, ты уже избрал свой путь." }, { 11.60, "Ты окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе." } }, f = { { 0.00, "Приветствую тебя. Мне доводилось и прежде слышать твоё имя, и я рада видеть, что, не взирая на твою молодость, ты уже избрала свой путь." }, { 12.50, "Ты окажешь мне великую честь, если примешь это как дар в знак нашего уважения к тебе." } } } } },
    [1082] = { d = 21.4, v = "nightelf-female#52", n = { x = 255 }, c = { x = { { 0.00, "Твоя помощь здесь оказалась поистине бесценной." }, { 3.55, "Часовые Ясеневого леса вознаградят тебя, если ты уведомишь их, что я и Гаксим живы." }, { 9.17, "Скажи им, что мы трудимся над тем, чтобы остановить Торговую компанию и исцелить эти земли." }, { 15.42, "Найди в Астранааре Тару Тенисил, она обрадуется твоему возвращению и хорошим новостям." } } }, t = { d = 10.2, g = 1, v = "nightelf-female#52", n = { m = 113, f = 114 }, c = { m = { { 0.00, "Благодарю тебя. Ты сослужил Стражам хорошую службу." }, { 3.92, "Я рада узнать, что Каэла... и даже Гаксим живы и здоровы. Ты заслуживаешь нашего уважения." } }, f = { { 0.00, "Благодарю тебя. Ты сослужила Стражам хорошую службу." }, { 3.89, "Я рада узнать, что Каэла... и даже Гаксим живы и здоровы. Ты заслуживаешь нашего уважения." } } } } },
    [1083] = { d = 39.5, v = "nightelf-female#52", n = { x = 458 }, c = { x = { { 0.00, "Не могу сказать точно, что Торговая компания сделала с Долиной, однако ясно, что обитающие там существа взяли над ними верх." }, { 8.59, "Представители Торговой компании подожгли лес, они использовали свои убийственные изобретения для того, чтобы как можно сильнее опустошить Долину." }, { 18.69, "Но в невежестве своём они также освободили нечто иное: пылающих духов, элементалей огня, камня и ярости." }, { 27.06, "И этой земле никогда не узреть улыбку Элуны, пока эти существа бродят на свободе." }, { 32.87, "Принеси мне их дымящиеся угли, дабы доказать, что тебе удалось сократить число разъярённых духов." } } }, t = { d = 5.6, v = "nightelf-female#52", n = { x = 63 }, c = { x = { { 0.00, "Останки нашего врага... твоя сила сослужила нам добрую службу. Благодарю тебя." } } } } },
    [1084] = { d = 33.3, v = "nightelf-female#52", n = { x = 393 }, c = { x = { { 0.00, "Мне кажется очевидным, что защитники долины – древни – вели какие-то дела с Торговой компанией, прежде чем их оттеснили прочь." }, { 8.20, "К несчастью, даже эти некогда великие охранители ныне впали в нечестие." }, { 13.33, "Гаксим полагает, что их падение каким-то образом связано с оружием, которое гоблины использовали во время отступления." }, { 21.68, "Я сказала ему, что возьму образец из тела раненого древня и отдам на изучение, чтобы понять, правда ли это." }, { 29.13, "Принеси мне немного шрапнели, чтобы гном мог дать мне ответ..." } } }, t = { d = 10.8, v = "nightelf-female#52", n = { x = 122 }, c = { x = { { 0.00, "Спасибо.Этого должно быть более чем достаточно, чтобы Гаксим выяснил, каким образом скверна пала на древней." }, { 7.87, "Я немедленно передам ему этот образец." } } } } },
    [1085] = { d = 31.5, v = "nightelf-female#52", n = { x = 377 }, c = { x = { { 0.00, "Положение здесь, в Каменном Когте, явно не способствует совместной работе ночного эльфа и гнома." }, { 6.62, "Торговая компания опустошила эти земли, и большая часть моего времени уходит на то, чтобы положить предел уничтожению." }, { 14.72, "Не суди Гаксима преждевременно; он понимает, что нам с ним необходимо трудиться вместе." }, { 20.54, "Если ты хочешь помочь нам, то для начала поговори с Гаксимом." }, { 24.92, "Извини, что пока не могу отослать тебя обратно к Таре с хорошими новостями. Может быть, вскоре..." } } }, t = { d = 31.1, v = "gnome-male", n = { x = 355 }, c = { x = { { 0.00, "Предательская... предательская и опасная, вот какова эта земля." }, { 4.62, "Но я тут для того, чтобы показать ночным эльфам, что ежели призвать на помощь старое доброе инженерное дело и чуточку магии, то так будет вернее." }, { 14.94, "Видишь ли, если убрать магию совсем, то ночным эльфам это никак не поможет – они без неё не могут. И мир без неё не может." }, { 23.11, "А вот если подкрепить магию инженерным делом да алхимией, то так оно будет правильнее. Возможностей просто масса." } } } } },
    [1086] = { d = 42.3, v = "scourge-female", n = { x = 368 }, c = { x = { { 0.00, "Отрава готова. Остаётся только её доставить адресату. И это придётся сделать тебе." }, { 9.05, "У Торговой Компании есть средства доставки сообщений и лёгкого груза от штаб-квартиры до Когтистых гор." }, { 18.71, "Скорее всего, это маленький аэропорт, подходящий не для дирижабля, а для ветролёта." }, { 26.30, "Обыщи все области Когтистых гор, находящиеся под контролем Торговой Компании, и найди этот аэропорт, если он существует. Как найдёшь, помести туда отраву. Положишь – беги оттуда." } } }, t = { d = 36.4, g = 1, v = "scourge-female", n = { m = 293, f = 294 }, c = { m = { { 0.00, "Ты нашёл аэропорт? Молодец! Отличный сюрприз ждал гобинов! Будем надеяться, что яд доберётся до их штаб-квартиры." }, { 12.32, "Ты оказал своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании. Они ещё не того заслуживают." }, { 25.11, "И вот какой мудрости союзникам Отрёкшихся стоит поучиться:" }, { 30.74, "Не бойся тёмных дорог... если они ведут к победе." } }, f = { { 0.00, "Ты нашла аэропорт? Молодец! Отличный сюрприз ждал гобинов! Будем надеяться, что яд доберётся до их штаб-квартиры." }, { 13.33, "Ты оказала своему народу неоценимую услугу, и пусть тебя не мучает совесть из-за отравления Торговой Компании. Они ещё не того заслуживают." }, { 26.01, "И вот какой мудрости союзникам Отрёкшихся стоит поучиться:" }, { 31.64, "Не бойся тёмных дорог... если они ведут к победе." } } } } },
    [1087] = { d = 39.2, v = "bloodelf-female", n = { x = 426 }, c = { x = { { 0.00, "Ты и представить себе не можешь, как я ненавижу эти омерзительные земли!" }, { 6.04, "Отродья Кенария и кальдорайские друиды, обитающие на этом пике, используют свою жалкую силу, чтобы подавить поток магии, даже так далеко на юг от их гнусного обиталища... их драгоценных лесов." }, { 19.33, "Я так хочу вернуться в Джеденар и купаться в потоках магии, но мой господин не позволяет мне вернуться, пока моя работа здесь не будет завершена." }, { 29.73, "Не сомневаюсь, что ты любишь ночных эльфов и их союзников не больше, чем я. Помоги мне, и мы оба внакладе не останемся." } } }, t = { d = 17.1, v = "bloodelf-female", n = { x = 184 }, c = { x = { { 0.00, "Я уже это чувствую... да... прекрасная мощь... струящийся поток." }, { 4.71, "Как же глупы калдораи, что отвергают дары этого мира, не дают магии свободно, словно песня, струиться по жилам." }, { 12.63, "Как же скучна и бесцветна жизнь без этого огненного потока!" } } } } },
    [1088] = { d = 33.8, v = "bloodelf-female", n = { x = 377 }, c = { x = { { 0.00, "Они думали, что могут остановить течение магии. Но они ошиблись." }, { 4.53, "Они думали, что смогут спрятать Хорданиуса – но я заполучу его голову!" }, { 9.74, "Магия даёт мне способность видеть истину. Да... вот он где. Скрещение путей... На вершине великого древа в Ясеневом лесу." }, { 17.81, "Название... Приют в Ночных Лесах. Один из старших сыновей лесного бога." }, { 22.71, "Они унесли его прочь с этого пика прежде, чем я смогла найти его, однако его время на исходе." }, { 29.58, "Принеси мне его голову, и я поделюсь с тобой могуществом." } } }, t = { d = 18.5, v = "bloodelf-female", n = { x = 189 }, c = { x = { { 0.00, "Некогда, давным-давно, я знала Хорданиуса. Он был горд, как и все его сородичи, и ставил себя даже над высокорождёнными." }, { 9.49, "Однако теперь ему трудно так же высоко держать голову, не так ли?" }, { 14.40, "Я обещала тебе награду, и ты её получишь. Слушай меня!" } } } } },
    [1089] = { d = 37.1, v = "bloodelf-female", n = { x = 428 }, c = { x = { { 0.00, "В Пещере Когтей друиды построили Логово Когтя, где хранят множество могущественных предметов." }, { 6.89, "Они продумали сложный план, чтобы не дать этим предметам попасть в чужие руки." }, { 12.72, "К счастью, мне удалось... вытянуть некоторые подробности из одного из них." }, { 18.02, "В маленьком светильнике у входа в пещеру ты найдёшь спрятанный там Ключ Хранителя Врат – с его помощью ты сможешь отворить тайники, расположенные вокруг логова." }, { 29.16, "А предметы из этих тайников помогут тебе открыть сокровищницу, размещённую в одном из центральных помещений." } } }, t = { d = 7.5, v = "bloodelf-female", n = { x = 88 }, c = { x = { { 0.00, "Когда три ключа вошли каждый в своё отверстие, посреди мерцающего сияния появились несколько предметов." } } } } },
    [1090] = { d = 38.1, v = "goblin-male", n = { x = 427 }, c = { x = { { 0.00, "Знаешь, когда-то я был второй по важности персоной во всём этом деле. Всё изменилось, когда главным стал Геренцо." }, { 8.67, "Уволил моего начальника Зиза Физзикса, а меня послал работать в копях. Но Зиз велел мне оставаться здесь и собирать сведения." }, { 17.40, "Его новое начальство хорошо заплатит нам, если мы узнаем, что планирует Геренцо." }, { 23.34, "В любом случае, я точно знаю, что Геренцо приказал добыть как можно больше этой золотисто-зелёной руды." }, { 30.41, "Я могу раздобыть образец, а ты передашь его Зизу. Но пока я этим занимаюсь, следи, не покажется ли стража." } } }, t = { d = 14.5, v = "goblin-male", n = { x = 157 }, c = { x = { { 0.00, "Спасибо. Тут выдалось несколько опасных моментов, да и мы, наверное, были не слишком-то внимательны." }, { 7.32, "Но важно то, что у нас теперь есть образец руды, и мы должны как можно скорее доставить его Зизу." } } } } },
    [1091] = { d = 14.1, v = "gnome-male", n = { x = 158 }, c = { x = { { 0.00, "Отнеси эти письма Каэле. Уверен, что она захочет это узнать. По крайней мере, часовые точно захотят." }, { 7.11, "И обязательно расскажи ей о наших успехах и о том, что мы не добились бы ничего без чуточки магии." } } }, t = { d = 5.6, v = "nightelf-female#52", n = { x = 64 }, c = { x = { { 0.00, "Это действительно интересно." }, { 2.15, "Вы с Гаксимом всё сделали правильно. Благодарю." } } } } },
    [1092] = { d = 34.7, v = "goblin-male", n = { x = 392 }, c = { x = { { 0.00, "Полагаю, мне тоже нужно убираться отсюда. Не пройдёт много времени." }, { 4.71, "как слухи о том, что произошло здесь, распространятся достаточно высоко, и вряд ли меня в следующий раз встретят там с добром да лаской." }, { 14.45, "Мне нужно выбраться наружу и встретиться с Зизом. Надеюсь, он мне подыщет новую работёнку!!!" }, { 21.17, "Я попытаюсь тут слегка подчистить за собой, но тебе придётся доставить образец руды Зизу немедля." }, { 28.08, "Он говорил мне, что разбил свой лагерь где-то за западном склоне Утёса Ветрорезов. Удачи!" } } }, t = { d = 19.0, v = "goblin-male", n = { x = 192 }, c = { x = { { 0.00, "А, я так и знал, что правильно сделал, когда сказал Пузнику остаться." }, { 6.07, "Я уверен, что инженеры в Нижней шахте захотят на это взглянуть." }, { 10.88, "Конечно, я собираюсь прихранить кусочек для себя, но если они чего-то не узнают, то это им и не повредит, верно?" } } } } },
    [1093] = { d = 35.6, v = "goblin-male", n = { x = 401 }, c = { x = { { 0.00, "Ну, Торговая Компания и наломала дров! О чём они только думали? Гоблинская компания нанимает гнома!" }, { 7.30, "К счастью для меня, Пароклапан всегда может узнать гения с первого взгляда. Он нанял меня сразу же, как меня выгнали оттуда!" }, { 16.25, "Мне сказали, что компания строит какие-то огромные лесорубные машины, и Клапан хочет, чтобы я украл для него чертежи." }, { 24.36, "К несчастью, Геренцо – вот ведь злобный гном! – хочет меня убить... может быть, ты вместо меня украдёшь чертежи?" }, { 31.71, "Они должны быть у кого-то из операторов компании." } } }, t = { d = 16.2, v = "goblin-male", n = { x = 164 }, c = { x = { { 0.00, "Эй, это то, что я думаю? Отлично!" }, { 2.97, "Ну-с, посмотрим... и как мне понимать эту ерунду?.. и чем только думают эти гномы?" }, { 9.07, "Удивительно, что они хотя бы колесо сумели соорудить, не говоря уж об этих их обожаемых ветролётах." } } } } },
    [1094] = { d = 25.0, v = "goblin-male", n = { x = 270 }, c = { x = { { 0.00, "В этом конверте – все сведения, которые я смог собрать до того, как меня выпнули за дверь..." }, { 6.17, "Внутренние документы Торговой Компании, кое-какие руководства, технические бумажки..." }, { 12.08, "О, и, конечно, чертежи \"Супер-потрошителя шесть тысяч\"." }, { 16.54, "Паровой Клапан обосновался в Кабестане в Степях. Тебе не доставит труда разыскать его, это такой мелкий зелёный тип." } } }, t = { d = 21.4, v = "goblin-male", n = { x = 234 }, c = { x = { { 0.00, "Физзик, да? Не то, чтоб я ему верил, но, кажется, это правильные сведения." }, { 4.98, "Что б я ни отдал, лишь бы Торговая Компания убралась подальше!" }, { 9.77, "Хотя они притащили с собой кое-какие хорошие машины..." }, { 13.49, "не буду отрицать, что от их изобретений есть польза, когда эти изобретения применяем мы, а не кто-то другой..." } } } } },
    [1095] = { d = 31.0, v = "goblin-male", n = { x = 346 }, c = { x = { { 0.00, "В Нижней шахте было много разговоров про этого гнома, нанятого Торговой Компанией." }, { 5.84, "Торговые олигархи не одобряют, что Раздунк связался с Геренцо." }, { 10.87, "Ридлвокс велел мне позаботиться об этой проблеме, и я не сомневаюсь, что это указание от одного из олигархов." }, { 18.57, "Разумеется, директор мне об этом не говорил. Скажем так, у меня такое подозрение." }, { 24.59, "Как бы то ни было, Геренцо необходимо устранить, и Физзику придётся хорошо поработать." } } }, t = { d = 24.2, v = "goblin-male", n = { x = 275 }, c = { x = { { 0.00, "Убрать Геренцо? Я только за!" }, { 2.41, "Гномы вообще неприятный народ, но, судя по всему, этот Геренцо хуже других." }, { 7.70, "Он был одним из главных инженеров Гномрегана и работал над тайным проектом – каким именно, нам так и не удалось узнать, хоть мы и пытались пробраться в Дун Морог." }, { 18.64, "В докладах говорилось, что этот тайный проект буквально взорвался им в лицо." } } } } },
    [1096] = { d = 38.3, v = "goblin-male", n = { x = 419 }, c = { x = { { 0.00, "Один раз я встречал Геренцо и, скажу тебе, видок у него отвратнее некуда." }, { 5.11, "Такое впечатление, что его плоть гниёт и отпадает, части его тела заменены металлическими деталями и механизмами." }, { 13.34, "К северо-востоку отсюда, высоко над Скалистым озером, вблизи водяного колеса находится пункт, откуда Геренцо наблюдает за всей местностью." }, { 24.40, "Я не смог бы найти дорогу наверх, не говоря уж о том, чтобы справиться с Геренцо... Но тебе, кажется, это вполне под силу." }, { 32.98, "Если ты убьёшь его по моей просьбе, то получишь щедрое вознаграждение!" } } }, t = { d = 30.5, v = "goblin-male", n = { x = 353 }, c = { x = { { 0.00, "Взгляни на эту штуковину... только гном мог с такой управляться." }, { 4.38, "Не понимаю только, зачем отрезать руку и заменять её этой штукой, если можно просто сохранить обе руки и приделать третью! Гномы, я тебе скажу..." }, { 14.55, "Геренцо, по крайней мере, если и не мёртв, то неисправен." }, { 18.51, "Надеюсь, этого доказательства будет достаточно, и Пароклапан даст мне назначение в одну из мастерских Союза ремонтников в Прибамбасске или, может быть, даже в Нижней шахте." } } } } },
    [1097] = { d = 32.0, g = 1, v = "human-male#50", n = { m = 381, f = 381 }, c = { m = { { 0.00, "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север." }, { 8.72, "Ты мне кажешься опытным путешественником..." }, { 11.57, "Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами." }, { 23.92, "Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города." } }, f = { { 0.00, "Дворфу-оружейнику Гриманду Элмору нужна помощь с доставкой ценного груза. Думаю, он хочет отправить посылку домой, на север." }, { 8.72, "Ты мне кажешься опытной путешественницей..." }, { 11.51, "Так что если ты не против взять с собой небольшой груз, то поговори с Гримандом; конечно, тебе и тут можно найти занятие, но мы стараемся поддерживать хорошие отношения с дворфами." }, { 23.86, "Гриманда Элмора можно найти в оружейной лавке в Штормграде, в Квартале Дворфов. Это в северо-восточной части города." } } }, t = { d = 3.3, v = "dwarf-male", n = { x = 35 }, c = { x = { { 0.00, "Ты поможешь мне с доставкой? Замечательно!" } } } } },
    [1098] = { d = 31.4, v = "scourge-male", n = { x = 317 }, c = { x = { { 0.00, "Готовясь к нападению на крепость Тёмного Клыка, мы отправили на разведку двух стражей смерти." }, { 6.99, "Они не возвращаются вот уже много дней, но без их отчёта нам не организовать успешного нападения!" }, { 14.71, "Итак, вот твоё задание. Отправляйся в крепость Тёмного Клыка на юге и найди стражей смерти Адаманта и Винсента." }, { 23.70, "Найди их и помоги им, если сможешь." }, { 26.77, "Это очень опасное и важное задание. Не подведи нас." } } }, t = { d = 17.1, v = "scourge-male", n = { x = 171 }, c = { x = { { 0.00, "Перед вами лежит израненное тело Винсента." }, { 3.91, "Страж смерти Адамант написал отчёт Хадреку... Но что бы ни хотел добавить к его словам Винсент, он унёс это с собой в могилу." }, { 13.39, "В мёртвой руке зажата небольшая безделушка..." } } } } },
    [1103] = { d = 32.3, g = 1, v = "troll-male#77", n = { m = 323, f = 327 }, c = { m = { { 0.00, "Привет, братан! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком шит?" }, { 6.69, "Я тока что прикончил осквернённого духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню." }, { 14.55, "А эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух." }, { 23.02, "Принеси мне сапту воды от Ислен, покажи, что готов к новому заходу, а я уж приготовлю тебе, чё нужно." } }, f = { { 0.00, "Привет, сеструха! Ты тута, чтобы очистить воду и доказать Ислен, что не лыком шита?" }, { 7.58, "Я тока что прикончил осквернённого духа воды и как раз собираюсь сунуть его браслеты и остатки воды в жаровню." }, { 15.45, "А эт што? А-а-а. Тьев понимает, бывает непруха. Что ж, Тьев нехило тебе поможет, если тебе снова нужен чистый водный дух." }, { 23.91, "Принеси мне сапту воды от Ислен, покажи, что готова к новому заходу, а я уж приготовлю тебе, чё нужно." } } }, t = { d = 20.5, g = 1, v = "troll-male#77", n = { x = 220 }, c = { m = { { 0.00, "Хвала тебе, смелый герой. Рифы побережья Западного Края будут освещены благодаря твоим трудам." }, { 7.69, "Множество жизней будет спасено, пока горит факел." }, { 11.50, "Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." } }, f = { { 0.00, "Хвала тебе, смелый героиня. Рифы побережья Западного Края будут освещены благодаря твоим трудам." }, { 6.62, "Множество жизней будет спасено, пока горит факел." }, { 10.42, "Меня постигла бессмысленная смерть на этом самом побережье. Мой долг в иной жизни – следить, чтобы никто не повторил моей судьбы." } } } } },
    [1104] = { d = 31.6, v = "gnome-male", n = { x = 334 }, c = { x = { { 0.00, "Я нарисовал уже столько чертежей нового болида! И все их надо непременно воплотить!!!" }, { 6.19, "Я разрабатываю новое топливо, которое будет гореть жарко-жарко-прежарко!" }, { 11.24, "Пока что у меня не получается, но, кажется, я знаю, что мне может помочь..." }, { 16.52, "У скорпидов с Мерцающей равнины совершенно особый яд, в нём чрезвычайно много солей. Он уникален! Как раз он-то мне и нужен." }, { 26.93, "Принеси мне их яда и поверь: тогда наши болиды просто взлетят!" } } }, t = { d = 12.5, v = "gnome-male", n = { x = 111 }, c = { x = { { 0.00, "Отлично! Этот яд как раз подойдёт! Спасибо!" }, { 3.69, "Теперь надо его вскипятить, добавить скиппер-отомер и нега-катализатор и... Чёрт! Где мои записи?!" } } } } },
    [1105] = { d = 29.8, v = "gnome-male", n = { x = 325 }, c = { x = { { 0.00, "Мой брат составляет новое топливо для болида. Он в этом деле просто гений!" }, { 5.20, "Правда, боюсь, его новое гениальное топливо разъест всю машину..." }, { 9.85, "Поэтому я хочу укрепить топливные баки." }, { 13.30, "Здесь, на равнинах, живут черепахи с очень прочными панцирями." }, { 17.97, "Из них-то я и хочу сделать это покрытие – оно должно выдержать топливо моего брата." }, { 24.08, "Ну как, не желаешь ли взяться за эту работу и принести мне несколько панцирей?" } } }, t = { d = 10.0, v = "gnome-male", n = { x = 96 }, c = { x = { { 0.00, "Панцири! Спасибо!" }, { 1.91, "Ого, да они ещё твёрже, чем я думал! Вот примусь с ними работать – так, поди, целый ящик инструментов погну!" } } } } },
    [1130] = { d = 19.0, v = "tauren-male#67", n = { x = 153 }, c = { x = { { 0.00, "Мелор Каменное Копыто узнал о ваших подвигах и наметил для вас путь." }, { 7.23, "Если вы хотите пройти его, отправляйтесь в Громовой Утёс и поговорите с Мелором. Его можно найти на вершине Охотников." } } }, t = { d = 8.9, g = 1, v = "tauren-male#68", n = { x = 75 }, c = { m = { { 0.00, "Итак, вы пришли... Значит, вы готовы к путешествию через дальние земли?" }, { 5.54, "Раз так, юный герой, то слушайте..." } }, f = { { 0.00, "Итак, вы пришли... Значит, вы готовы к путешествию через дальние земли?" }, { 5.54, "Раз так, юный героиня, то слушайте..." } } } } },
    [1131] = { d = 39.9, v = "tauren-male#68", n = { x = 394 }, c = { x = { { 0.00, "Иногда мы охотимся ради еды. Иногда – ради чести. А иногда мы охотимся для того, чтобы усвоить уроки Матери-Земли." }, { 9.17, "Но охота, на которую я хочу отправить вас, не имеет с этими вещами ничего общего." }, { 15.48, "Вам нужно будет убить существо, не подчиняющееся божественной воле Матери-Земли." }, { 22.13, "Гиена по кличке Сталезуб бродит по Тысяче Игл, к югу от Степей." }, { 27.03, "К этой зверюге прибиваются другие гиены, и вместе они держат всех остальных более мирных животных в страхе." }, { 35.69, "Найдите Сталезуба. Найдите и убейте его." } } }, t = { d = 8.4, v = "tauren-male#68", n = { x = 69 }, c = { x = { { 0.00, "Убив Сталезуба, вы избавили Тысячу Игл от страшной напасти. И это, ваш урок на сегодня." } } } } },
    [1133] = { d = 20.4, v = "bloodelf-female", n = { x = 235 }, c = { x = { { 0.00, "Если вы только что прибыли по морю из Менетила, отправляйтесь прямиком в Астранаар." }, { 5.78, "Уверен, такому преданному члену Альянса будет, чем заняться в городе." }, { 10.55, "Поговорите там с Шиндрелл Огненный Всполох и предложите ей свои услуги." }, { 15.86, "Не стоит говорить ей, кто вас прислал. Шиндрелл меня не знает..." } } }, t = { d = 9.9, v = "nightelf-female#52", n = { x = 106 }, c = { x = { { 0.00, "Вы здесь, чтобы предложить помощь Альянсу? любой помощи. Хотя красота всё ещё живёт в Ясеневом лесу... война добралась и до этих мест." } } } } },
    [1134] = { d = 33.1, v = "nightelf-female#52", n = { x = 402 }, c = { x = { { 0.00, "Между нами и Ордой война не объявлена, однако мир между нами очень хрупок." }, { 4.87, "Мы часто обнаруживаем, что среди нас тайно действуют их агенты." }, { 9.21, "Об одной такой операции мы узнали из скрытых источников в Тераморе." }, { 13.64, "Эти источники утверждают, что орки собирают яд славнокрылов поблизости от Мутного Озера в Когтистых горах, на юге." }, { 21.28, "А потом орочьи убийцы используют этот яд для тайных смертоносных ударов против сил Альянса!" }, { 27.69, "Если это правда, мы обязаны остановить их. Мы должны лишить их источника яда." } } }, t = { d = 23.3, v = "nightelf-female#52", n = { x = 276 }, c = { x = { { 0.00, "Благодарю тебя. Мне не хотелось отправлять тебя убивать этих созданий, которые, возможно, не по своей воле помогали нашим врагам, однако это был мой долг." }, { 10.60, "Быть может, друг мой, твоё сердце оплакивает величавых виверн, которых тебе пришлось убить, однако пусть тебе принесёт утешение то, что твои союзники больше не будут погибать от их яда." } } } } },
    [1135] = { d = 26.9, v = "bloodelf-female", n = { x = 308 }, c = { x = { { 0.00, "Как вы уже знаете, орки часто приручают виверн в качестве ездовых животных." }, { 5.14, "Но мало кто знает о том, что яд виверны порой может быть ценнее самого животного." }, { 10.80, "Так что, если желаете немного поохотиться, то у меня есть для вас работа." }, { 16.24, "В Тысяче Игл – это к западу отсюда – есть место под названием Скальное гнездовье." }, { 21.69, "Там живут виверны, яд которых очень силён и чрезвычайно высоко ценится." } } }, t = { d = 11.6, v = "bloodelf-female", n = { x = 131 }, c = { x = { { 0.00, "О-о-о, некоторые чуть ли не лопаются от яда! Такие обычно собирают с очень юных виверн или с плодовитых самок." }, { 7.71, "Наверное, нелегко вам пришлось в Скальном гнездовье!" } } } } },
    [1138] = { d = 36.1, v = "dwarf-male#100", n = { x = 417 }, c = { x = { { 0.00, "Мне нравятся крабы. Крабы – это деликатесные дары моря! Их можно печь, жарить на гриле, варить, делать из них бульон." }, { 7.87, "Ещё их можно жарить на сковороде, во фритюре и просто жарить." }, { 12.15, "Есть крабовый салат, крабовый суп, краб тушёный, краб перченый, краб лимонный, краб с кнутокорнем, а также стальгорнский крабовый десерт. Вот и... ну, и всё." }, { 22.83, "Я здесь сейчас рыбу ужу, потому охотиться на сочных крабов мне некогда." }, { 27.72, "Можешь извлечь кусочки отличного мяса из рифовых крабов и покрытых илом крабов. Их можно печь, жарить на гриле, варить..." } } }, t = { d = 22.7, v = "dwarf-male#100", n = { x = 234 }, c = { x = { { 0.00, "Да-а-а, эти кусочки отличного крабьего мяса – как раз то, что мне нужно. Спасибо!" }, { 7.10, "Вот, это я обнаружил как-то, когда рыбачил, и мне оно без надобности. Может быть, ты сможешь как-то это использовать?" }, { 15.13, "В деликатесные блюда из крабов это уж точно не положишь." }, { 19.41, "Я ведь уже рассказывал тебе о крабах, правда?" } } } } },
    [1140] = { d = 32.6, g = 1, v = "human-male", n = { m = 375, f = 375 }, c = { m = { { 0.00, "Орочьи письмена немногим лучше детских каракулей." }, { 3.44, "Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов." }, { 12.19, "Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса." }, { 25.50, "Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такой закалённый герой, как ты." } }, f = { { 0.00, "Орочьи письмена немногим лучше детских каракулей." }, { 3.44, "Многие из моих собратьев по ордену кривились, когда я решил изучать их язык, но мне это сильно помогает понимать врагов." }, { 12.19, "Из каракулей Илкруда можно понять, что у Атрикуса ещё оставались два самоцвета души, и они хранились на Ночной поляне и Сатирнааре, занятых сатирами местах на северо-востоке Ясеневого леса." }, { 25.50, "Поосторожнее там, от вида кровавых храмов сатиров содрогнётся даже такая закалённая героиня, как ты." } } }, t = { d = 19.9, v = "human-male", n = { x = 228 }, c = { x = { { 0.00, "Возможно, мы слишком долго терпели сатиров в этом лесу. Я поговорю с Элиссой насчёт этого, когда в другой раз поеду в Аубердин." }, { 9.05, "Тем не менее, раз самоцветы души уничтожены, сила Атрикуса сильно уменьшится." }, { 14.43, "Мы должны воспользоваться этой возможностью и уничтожить его и его культ." } } } } },
    [1141] = { d = 33.5, v = "dwarf-male#100", n = { x = 385 }, c = { x = { { 0.00, "Мне нравится рыбачить. Семья Блумп славится своими рыбаками. Меня зовут Груббер Блумп. Я рыбак." }, { 6.85, "Есть одна рыбка, которую я хотел бы поймать в этих водах – местная разновидность окуня." }, { 12.80, "Я раньше ходил на окуня на лодке, но с тех пор как побережье оккупировали эти противные мурлоки, ни одна лодка в море не выходит. Боюсь, они и окуней всех съедят." }, { 24.08, "Слушай, хочешь помочь мне наловить окуней? Я б тебе от чистого сердца подарил фамильную удочку семьи Блумп! Это очень хорошая удочка!" } } }, t = { d = 23.1, g = 1, v = "dwarf-male#100", n = { m = 265, f = 267 }, c = { m = { { 0.00, "Какие отличные окуни! Большое спасибо за помощь!" }, { 3.75, "Ты как минимум такой же хороший рыбак, как моя драгоценная родственница Граун Блумп." }, { 9.61, "У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить." }, { 16.86, "Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп." } }, f = { { 0.00, "Какие отличные окуни! Большое спасибо за помощь!" }, { 3.75, "Ты как минимум такая же хорошая рыбачка, как моя драгоценная родственница Граун Блумп." }, { 9.78, "У неё, правда, растёт борода и от неё несёт чем-то странным, но это для неё не причина перестать рыбачить." }, { 17.03, "Думаю, ты обладаешь необходимыми качествами, чтобы пользоваться удочкой семьи Блумп." } } } } },
    [1142] = { d = 25.3, v = "nightelf-male", n = { x = 254 }, c = { x = { { 0.00, "Мне недолго осталось жить... о, я так слаб..." }, { 3.28, "Хмурен... храбрый дворф, он отправился... предупредить Фалфиндера... Но прежде, чем я умру..." }, { 10.50, "Пожалуйста, верни моей жене её подвеску... её украл один из этих негодяев..." }, { 15.81, "Подвеска связывает нас... это очень важно... Пожалуйста, верни подвеску моей Трешале... в Дарнасс... И расскажи ей... о моей смерти." } } }, t = { d = 19.1, g = 1, v = "nightelf-female#53", n = { m = 197, f = 198 }, c = { m = { { 0.00, "О нет!" }, { 1.00, "Не может быть! О, я не верю! О, жестокий мир!" }, { 4.54, "Мне предстоит весь век нести в сердце горе... Я не позволю делу Гералата погибнуть вместе с ним!" }, { 11.29, "Благодарю тебя за то, что ты проделал этот опасный путь. Но теперь оставь меня. Я оплачу мужа в одиночестве..." } }, f = { { 0.00, "О нет!" }, { 1.00, "Не может быть! О, я не верю! О, жестокий мир!" }, { 4.54, "Мне предстоит весь век нести в сердце горе... Я не позволю делу Гералата погибнуть вместе с ним!" }, { 11.29, "Благодарю тебя за то, что ты проделала этот опасный путь. Но теперь оставь меня. Я оплачу мужа в одиночестве..." } } } } },
    [1143] = { d = 19.0, v = "nightelf-male#55", c = { x = { { 0.00, "Понятно. Ну если то, о чём ты говоришь, – правда, то сейчас самое время нанести удар." }, { 5.63, "Я уверен, что Атрикус обосновался на самом верху башни." }, { 9.46, "Однако будь начеку, его окружает множество сильных чернокнижников, гораздо более опасных, чем те, с кем тебе доводилось встречаться ранее." } } }, t = { d = 14.9, v = "nightelf-male#55", n = { x = 176 }, c = { x = { { 0.00, "Я надеюсь, что после смерти Атрикуса демонические силы в этом районе отступят." }, { 5.35, "Я не сомневаюсь, что они перегруппируются и вернутся, но тогда мы будем ещё лучше подготовлены, чтобы встретить эту угрозу лицом к лицу." } } } } },
    [1144] = { d = 27.0, v = "goblin-male", n = { x = 292 }, c = { x = { { 0.00, "Наконец-то, помощь пришла!" }, { 2.32, "Ты не представляешь, как долго я уже здесь торчу!" }, { 6.19, "Видишь ли, я предприниматель. Как говорится, всегда ищу выгоду." }, { 10.68, "Вот, прослышал, что Мебок Миззрикс даёт хорошую цену за растущий здесь корень краснолиста." }, { 17.03, "Ну я и подумал, что на этом можно обтяпать неплохие денежки. Как видишь, жестоко ошибался!" }, { 23.62, "Вытащи меня отсюда, я тебе хорошо заплачу!" } } }, t = { d = 5.2, v = "goblin-male", n = { x = 54 }, c = { x = { { 0.00, "Уф... спасибо, дружище! А вот и обещанная награда – за мной не заржавеет!" } } } } },
    [1149] = { d = 41.1, g = 1, v = "tauren-male#68", n = { m = 402, f = 402 }, c = { m = { { 0.00, "Итак, ты нашёл меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь." }, { 11.41, "Личность складывается из многих из многих граней: души, тела и разума." }, { 16.86, "Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться." }, { 25.52, "Если согласишься, я испытаю некоторые присущие тебе качества." }, { 30.69, "Если ты пройдёшь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты." }, { 37.86, "Первое испытание – это испытание веры." } }, f = { { 0.00, "Итак, ты нашла меня – или, возможно, тебя привела сама судьба? Это неважно. Теперь ты здесь, и перед тобой лежит новый путь." }, { 11.39, "Личность складывается из многих из многих граней: души, тела и разума." }, { 16.84, "Некоторые из этих аспектов определяются культурными традициями, о наличии других мы можем только догадываться." }, { 25.50, "Если согласишься, я испытаю некоторые присущие тебе качества." }, { 30.66, "Если ты пройдёшь испытание, то станешь сильнее, если же нет – познаешь всю бездну Пустоты." }, { 37.84, "Первое испытание – это испытание веры." } } }, t = { d = 20.9, g = 1, v = "tauren-male#68", n = { m = 212, f = 215 }, c = { m = { { 0.00, "Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой." }, { 6.47, "Ты поверил в себя, хотя и не был уверен, что выживешь. Твой разум открыт, и твой дух готов встретить всё, что ждёт впереди." }, { 16.21, "Если желаешь, можешь приступить к следующему испытанию." } }, f = { { 0.00, "Истинную силу нашего духа мы можем познать лишь при встрече с непредвиденной бедой." }, { 6.47, "Ты поверила в себя, хотя и не была уверена, что выживешь. Твой разум открыт, и твой дух готов встретить всё, что ждёт впереди." }, { 16.34, "Если желаешь, можешь приступить к следующему испытанию." } } } } },
    [1150] = { d = 40.1, v = "tauren-male#68", n = { x = 412 }, c = { x = { { 0.00, "Хорошо, что ты не теряешь смелости несмотря ни на что. Твоя вера крепка, и теперь настало время испытать твою силу." }, { 9.24, "Сначала тебе надо пройти испытание выносливости. Отправляйся в Логово Легкопёрых – оно к западу от Заставы Вольного Ветра." }, { 18.61, "Проберись в самое сердце логова и уничтожь там все запасы еды." }, { 23.31, "К тому времени местные гарпии будут в ярости, и если ты останешься в живых, с тобой прилетит сразиться их предводительница – Гренка Кровавый Визг." }, { 35.36, "Убей её и принеси мне её коготь, чтобы пройти это испытание." } } }, t = { d = 22.1, g = 1, v = "tauren-male#68", n = { m = 218, f = 220 }, c = { m = { { 0.00, "Гренка была очень сильна даже для такого героя как ты. Сегодня ты можешь по праву гордиться собой." }, { 8.03, "Во время испытания веры ты показал силу своего духа, а сегодня подтвердил, что физически ты готов к битве." }, { 16.19, "Гарпии Лёгкого Пера мертвы, и теперь настало время нового испытания." } }, f = { { 0.00, "Гренка была очень сильна даже для такой героини как ты. Сегодня ты можешь по праву гордиться собой." }, { 8.12, "Во время испытания веры ты показала силу своего духа, а сегодня подтвердила, что физически ты готова к битве." }, { 16.44, "Гарпии Лёгкого Пера мертвы, и теперь настало время нового испытания." } } } } },
    [1151] = { d = 38.5, v = "tauren-male#68", n = { x = 400 }, c = { x = { { 0.00, "Во времена Древних богов элементалей можно было встретить повсюду." }, { 4.97, "Они поклонялись Древним богам, а боги своей силой поддерживали связь духов с этим миром." }, { 11.93, "Когда же Древние боги были изгнаны, элементали тоже покинули этот мир и теперь являются сюда только по зову могущественных магов." }, { 22.08, "Но есть и исключения. Некоторые духи были достаточно сильны для того, чтобы остаться в этом мире, и одного из них зовут Рок'Алим." }, { 32.42, "Для того чтобы испытать свою силу, найди в Тысяче Игл Рок'Алима и убей его." } } }, t = { d = 10.8, v = "tauren-male#68", n = { x = 115 }, c = { x = { { 0.00, "Испытание силы пройдено. Вы показали свою силу и храбрость и теперь готовы к последнему испытанию, после которого эти ритуалы завершатся." } } } } },
    [1152] = { d = 31.1, g = 1, v = "tauren-male#68", n = { m = 315, f = 316 }, c = { m = { { 0.00, "Твои испытания почти закончились, но проверку знаний проводить буду не я." }, { 5.66, "Тебе придётся посетить другие места и усвоить там новые уроки." }, { 10.87, "Если ты готов, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни всё, что он скажет." }, { 20.33, "Брауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь осторожен, ночные эльфы могут помешать тебе." } }, f = { { 0.00, "Твои испытания почти закончились, но проверку знаний проводить буду не я." }, { 5.66, "Тебе придётся посетить другие места и усвоить там новые уроки." }, { 10.87, "Если ты готова, найди Брауга Тусклый Дух – это очень мудрый шаман. Внимательно выслушай его и выполни всё, что он скажет." }, { 20.64, "Брауга можно найти около туннеля, соединяющего Когтистые горы и Ясеневый лес. И будь осторожна, ночные эльфы могут помешать тебе." } } }, t = { d = 32.6, v = "tauren-male#68", n = { x = 322 }, c = { x = { { 0.00, "Гоблины терзают землю, ночные эльфы унижают младшие расы, а дни и ночи тем временем становятся всё холоднее и холоднее." }, { 9.29, "Отрёкшиеся и орки – не единственные, кого нужно винить за конфликты, возникшие на землях Калимдора и Лордерона." }, { 19.17, "Многие разумные расы причинили миру немало боли." }, { 23.07, "Дорн знает об этом, и он отправил вас ко мне, потому что вы тоже способны это понять. Сейчас вы стоите перед Браугом." } } } } },
    [1153] = { d = 37.3, g = 1, v = "orc-male", n = { x = 403 }, c = { m = { { 0.00, "герой, раньше вы часто помогали мне в разных делах." }, { 3.62, "Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью." }, { 9.87, "По закону чести, я должен рассказать вождю обо всём, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи." }, { 19.17, "Недавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл." }, { 26.13, "Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать." }, { 33.45, "А он мне очень нужен для исследования!" } }, f = { { 0.00, "героиня, раньше вы часто помогали мне в разных делах." }, { 3.80, "Пока что вождь доволен моими успехами и просит меня продолжать с новой решимостью." }, { 10.04, "По закону чести, я должен рассказать вождю обо всём, что вы сделали для нас, но вначале я хотел бы снова попросить вас о помощи." }, { 19.35, "Недавно я встречался с путешественниками, которые пришли с юга, из места под названием Тысяча Игл." }, { 26.31, "Там они убили кобольда, у которого при себе был образец необычной руды, но они отказались его продавать." }, { 33.62, "А он мне очень нужен для исследования!" } } }, t = { d = 24.4, g = 1, v = "orc-male", n = { x = 258 }, c = { m = { { 0.00, "Хороший образец. Очень хороший." }, { 2.77, "Вы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо мной нос." }, { 10.40, "Я немедленно начну работать с ней, и если руда окажется достаточно прочной, я изготовлю из неё оружие и отправлю вождю, чтобы он посмотрел на наши успехи. Я не забуду вашей помощи, герой." } }, f = { { 0.00, "Хороший образец. Очень хороший." }, { 2.77, "Вы замечательно справились с заданием, и эти путешественники больше не смогут задирать передо мной нос." }, { 10.40, "Я немедленно начну работать с ней, и если руда окажется достаточно прочной, я изготовлю из неё оружие и отправлю вождю, чтобы он посмотрел на наши успехи." }, { 21.38, "Я не забуду вашей помощи, героиня." } } } } },
    [1154] = { d = 36.9, g = 1, v = "tauren-male#68", n = { m = 364, f = 364 }, c = { m = { { 0.00, "Ты прошёл испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми." }, { 9.10, "Физическую силу испытать легко – то ли дело сила разума!" }, { 13.79, "Ладно, объясню попроще: найди книгу, которую я назову, изучи её и ответь на мой вопрос по её содержимому." }, { 22.34, "Ты спросишь, что за книга? Она называется \"Наследие Аспектов\"." }, { 26.95, "Её можно найти в глубине обители Дор'Данил, это в южном Ясеневом лесу. Книгу охраняют мёртвые друиды и их убийцы." } }, f = { { 0.00, "Ты прошла испытание Дорна и хочешь пройти следующее? Что ж, хорошо. Но все предыдущие испытания были детскими играми." }, { 9.08, "Физическую силу испытать легко – то ли дело сила разума!" }, { 13.77, "Ладно, объясню попроще: найди книгу, которую я назову, изучи её и ответь на мой вопрос по её содержимому." }, { 22.32, "Ты спросишь, что за книга? Она называется \"Наследие Аспектов\"." }, { 26.93, "Её можно найти в глубине обители Дор'Данил, это в южном Ясеневом лесу. Книгу охраняют мёртвые друиды и их убийцы." } } }, t = { d = 15.4, g = 1, v = "tauren-male#68", n = { m = 151, f = 153 }, c = { m = { { 0.00, "Это та самая книга, о которой я говорил. Полагаю, тебе известен ответ на мой вопрос – если только ты не поленился изучить книгу." }, { 10.14, "Как только будешь готов, обратись ко мне, и я задам тебе вопрос." } }, f = { { 0.00, "Это та самая книга, о которой я говорил." }, { 3.09, "Полагаю, тебе известен ответ на мой вопрос – если только ты не поленилась изучить книгу." }, { 10.08, "Как только будешь готова, обратись ко мне, и я задам тебе вопрос." } } } } },
    [1159] = { d = 38.6, g = 1, v = "tauren-male#68", n = { m = 346, f = 347 }, c = { m = { { 0.00, "Отличная работа. Ты прошёл первую часть испытания знаний, но ещё один вопрос остался без ответа. Правда, задавать его буду не я." }, { 11.18, "Поговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей." }, { 21.43, "Он до сих пор стремится к просвещению, но уже по-другому." }, { 26.14, "Он даст тебе задание, и только потом задаст вопрос – но до сих пор ты справлялся хорошо, и, я уверен, трудностей у тебя не возникнет." } }, f = { { 0.00, "Отличная работа. Ты прошла первую часть испытания знаний, но ещё один вопрос остался без ответа. Правда, задавать его буду не я." }, { 12.18, "Поговори с Парквелом Финталласом в Лордероне – до того как пасть жертвой Чумы, он был великим историком среди людей." }, { 22.43, "Он до сих пор стремится к просвещению, но уже по-другому." }, { 27.14, "Он даст тебе задание, и только потом задаст вопрос – но до сих пор ты справлялась хорошо, и, я уверен, трудностей у тебя не возникнет." } } }, t = { d = 22.9, g = 1, v = "scourge-male#83", n = { x = 239 }, c = { m = { { 0.00, "Тебя прислал Брауг? Невероятно. Парквел критически осматривает вас." }, { 5.40, "Справился в Дор'Даниле, прошёл испытание веры и совладал с могущественным элементалем? Ха!" }, { 12.04, "Да ты, наверное, наслушался разговоров в таверне и теперь нагло врёшь мне! Думаешь, что сможешь пройти моё испытание? Ну что ж, хорошо... герой." } }, f = { { 0.00, "Тебя прислал Брауг? Невероятно. Парквел критически осматривает вас." }, { 5.40, "Справился в Дор'Даниле, прошёл испытание веры и совладал с могущественным элементалем? Ха!" }, { 12.04, "Да ты, наверное, наслушался разговоров в таверне и теперь нагло врёшь мне! Думаешь, что сможешь пройти моё испытание? Ну что ж, хорошо... героиня." } } } } },
    [1167] = { d = 11.7, v = "human-male", n = { x = 137 }, c = { x = { { 0.00, "Прежде чем встретиться с Атрикусом, разумно было бы тебе посоветоваться с Балтулом." }, { 5.72, "Не сомневаюсь, что он неусыпно следил за башней и может знать о недавних событиях." } } }, t = { d = 24.2, g = 1, v = "nightelf-male#55", n = { m = 278, f = 279 }, c = { m = { { 0.00, "А, приятно снова свидеться! Тут такие странные вещи творились, так что хорошо, что ты снова тут появился!" }, { 7.37, "Очень странные вещи. Всё казалось как обычно – ну, насколько тут вообще всё может быть обычно – и вдруг на верхнем этаже башни как полыхнёт!" }, { 16.76, "Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что всё это может значить?" } }, f = { { 0.00, "А, приятно снова свидеться! Тут такие странные вещи творились, так что хорошо, что ты снова тут появилась!" }, { 7.51, "Очень странные вещи. Всё казалось как обычно – ну, насколько тут вообще всё может быть обычно – и вдруг на верхнем этаже башни как полыхнёт!" }, { 16.90, "Потом начались вопли. Вопли раскалывали воздух, а в землю порой били молнии. Что всё это может значить?" } } } } },
    [1176] = { d = 28.8, v = "goblin-male", n = { x = 330 }, c = { x = { { 0.00, "На гонках имеет значение абсолютно всё!" }, { 2.85, "Будь то малейшее изменение мощности, небольшое ослабление колец натяжения или уменьшение веса болида – любую мелочь надо принимать в расчёт." }, { 12.91, "Мы используем в своих болидах кости стервятников – они очень крепкие и лёгкие. К тому же их очень легко найти." }, { 20.50, "Уж чего-чего – а стервятников на Мерцающих равнинах хватает." }, { 24.89, "Принеси мне немного костей, и я хорошо заплачу тебе." } } }, t = { d = 4.1, v = "goblin-male", n = { x = 44 }, c = { x = { { 0.00, "Отлично! Моя команда сейчас же начнёт работу! Спасибо." } } } } },
    [1179] = { d = 33.3, v = "dwarf-male", n = { x = 378 }, c = { x = { { 0.00, "Вы когда-нибудь слышали о Мерцающей равнине? Это огромное соляное плато в Калимдоре, южнее каньона Тысяча Игл." }, { 7.60, "Это отличное место для гонок, потому что поверхность там совершенно... ну... равнинная!" }, { 13.63, "Там живёт парочка гномов – мои друзья, они строят новый болид, и говорят, он жуть какой быстрый!" }, { 20.20, "Настолько быстрый, что их пилоты то и дело разбиваются и калечатся..." }, { 25.19, "Они заказали у меня несколько защитных шлемов, но у меня дела, и я не могу их отвезти. Может быть, вы мне поможете?" } } }, t = { d = 7.8, v = "gnome-male", n = { x = 80 }, c = { x = { { 0.00, "Ага! Длиннобородый прислал с вами наши шлемы! Ур-р-а-а-а!!!" }, { 4.33, "Осталось уговорить пилота сесть в наш болид..." } } } } },
    [1195] = { d = 36.7, v = "tauren-male#68", n = { x = 372 }, c = { x = { { 0.00, "Кентавры племени Галак в Тысяче Игл хранят один предмет, сохранившийся ещё со времён сотворения кентавров." }, { 8.69, "Нам бы хотелось его получить, но для этого нужен фиал воды из одного из лунных колодцев ночных эльфов." }, { 16.94, "Чтобы набрать воды, тебе надо сначала добыть один из фиалов дриад, что живут близ Приюта в Ночных Лесах в сердце Ясеневого леса." }, { 27.44, "Лунный колодец есть у западного берега реки Фалфаррен, к югу от главной дороги, у которой ты сможешь наполнить фиал." } } }, t = { d = 8.5, v = "tauren-male#68", n = { x = 83 }, c = { x = { { 0.00, "Хорошо. Это как раз то, что просил Рау. Ты можешь отнести ему фиал? Тебе понравится в Иглах, честное слово!" } } } } },
    [1196] = { d = 20.6, v = "tauren-male#68", n = { x = 193 }, c = { x = { { 0.00, "Отнеси наполненный фиал Рау Скальному Бегуну на Заставу Вольного Ветра на юго-востоке Тысячи Игл." }, { 9.64, "Туда ты можешь добраться на Великом подъёмнике, что возле южного обрыва Степей." }, { 16.02, "Не удивлюсь, если ты и в дальнейшем будешь нам помогать." } } }, t = { d = 16.3, v = "tauren-male#68", n = { x = 176 }, c = { x = { { 0.00, "Хм, да, этот фиал очень пригодится для наших целей." }, { 3.88, "Поскольку дриады и кентавры происходят от одного корня, вода лунных колодцев поможет нам пробить брешь в стене неугасимого огня, что окружает реликвию кентавров." } } } } },
    [1197] = { d = 34.0, g = 1, v = "tauren-male#68", n = { m = 358, f = 360 }, c = { m = { { 0.00, "Водой, которую ты принёс, можно будет затушить пламя, охраняющее реликвию кентавров." }, { 6.48, "Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить." }, { 12.05, "Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда." }, { 17.42, "Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса." }, { 23.06, "Будь осторожен – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность." } }, f = { { 0.00, "Водой, которую ты принесла, можно будет затушить пламя, охраняющее реликвию кентавров." }, { 6.67, "Однако оно погаснет лишь ненадолго, так что тебе придётся поспешить." }, { 12.24, "Утёс Треснувшего Копыта – крепость кентавров – находится к северу отсюда." }, { 17.61, "Огонь горит в оплоте Треснувшего Копыта – самой охраняемой части утёса." }, { 23.25, "Будь осторожна – кентавров из племени Галак очень много, и они вряд ли легко расстанутся с тем, что представляет для них большую ценность." } } }, t = { d = 16.4, v = "tauren-male#68", n = { x = 159 }, c = { x = { { 0.00, "От этого копыта исходит странная энергия... Не сомневаюсь, что при его изучении мы узнаем много нового о кентаврах." }, { 9.31, "Благодарю вас. Я немедленно приступлю к разгадке тайны, которую вы принесли мне." } } } } },
    [1198] = { d = 33.9, v = "nightelf-male#55", n = { x = 397 }, c = { x = { { 0.00, "В нынешние дни много слухов ходит о союзе Сумеречного Молота и наг в Непроглядной Пучине на побережье Ясеневого леса." }, { 8.41, "Я должен собрать как можно больше сведений для Серебряного Рассвета, что бы мы могли понять, где и когда нужна наша помощь." }, { 17.04, "Уже много недель прошло, как я отправил разведчика выяснить, что происходит в Непроглядной Пучине." }, { 23.68, "Страж Талрид из ордена Серебряного Рассвета до сих пор не вернулся." }, { 28.56, "Другие мои разведчики заняты насущными делами. Помоги мне найти Талрида." } } }, t = { d = 9.7, v = "nightelf-male#54", n = { x = 95 }, c = { x = { { 0.00, "Хорошо, что Рассветный дозорный Шедласс прислал вас. В этом испоганенном месте и правда затевается коварный план." } } } } },
    [1199] = { d = 35.7, v = "nightelf-male#54", n = { x = 417 }, c = { x = { { 0.00, "Черпая силу из старинных обрядов, посвящённых Древним Богам Хаоса, Сумеречный Молот пытается вернуть своих тёмных покровителей и распространить смерть и ужас по всему миру." }, { 12.39, "Мы думаем, что Сумеречный Молот в союзе с нагами, и теперь они накапливают силы в Непроглядной Пучине на побережье Ясеневого леса." }, { 21.71, "Что бы ни затевалось в глубинах древнего храма, этим планам нельзя дать осуществиться." }, { 28.08, "Объяви же войну Молоту и вернись с доказательствами своих подвигов! Твои труды будут достойно вознаграждены." } } }, t = { d = 8.5, v = "nightelf-male#54", n = { x = 99 }, c = { x = { { 0.00, "Нет сомнений – в тебе течёт отважная и благородная кровь. Серебряный Рассвет благодарит тебя за содействие силам добра." } } } } },
    [1200] = { d = 32.6, v = "nightelf-male#54", n = { x = 371 }, c = { x = { { 0.00, "Силы оставили меня. Мне необходима твоя помощь!" }, { 3.50, "В давние времена на этом месте был храм Элуны." }, { 6.64, "К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный Лунный колодец." }, { 15.09, "Аку'май, слуга Древнего бога, поднялся из глубин." }, { 18.78, "Сектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы." }, { 28.44, "Убей Келриса и принеси его голову Сельгорму в Дарнасс." } } }, t = { d = 36.2, g = 1, v = "human-male", n = { m = 392, f = 395 }, c = { m = { { 0.00, "Келрис ускользал от нас слишком долго." }, { 3.15, "Кажется, всякий раз, когда в этих землях давало о себе знать зло, Келрис играл в этом какую-то роль." }, { 10.00, "Долгое время мы считали его мёртвым или пропавшим без вести." }, { 14.64, "Теперь всё встало на свои места. Покончив с его правлением, ты спас множество невинных жизней." }, { 21.59, "Свет во имя! Принести жертву прислужнику Древнего Бога ради личной выгоды — это за пределами всякого понимания!" }, { 30.28, "Ты совершил великое деяние. От лица Серебряного Рассвета — честь тебе и слава." } }, f = { { 0.00, "Келрис ускользал от нас слишком долго." }, { 3.15, "Кажется, всякий раз, когда в этих землях давало о себе знать зло, Келрис играл в этом какую-то роль." }, { 10.00, "Долгое время мы считали его мёртвым или пропавшим без вести." }, { 14.64, "Теперь всё встало на свои места. Покончив с его правлением, ты спасла множество невинных жизней." }, { 21.73, "Свет во имя! Принести жертву прислужнику Древнего Бога ради личной выгоды — это за пределами всякого понимания!" }, { 30.42, "Ты совершила великое деяние. От лица Серебряного Рассвета — честь тебе и слава." } } } } },
    [1221] = { d = 33.7, v = "goblin-male", n = { x = 362 }, c = { x = { { 0.00, "Корень синелиста – признанный деликатес в любом уголке мира!" }, { 4.04, "Но растёт он только здесь, в Пустошах, глубоко под землёй в Лабиринтах Иглошкурых." }, { 11.73, "К тому же клубни так сложно найти, если не знать точно где искать!" }, { 16.33, "Поэтому я специально надрессировал этих шмыгуносов, чтобы они находили корни под землёй." }, { 22.43, "Обоняние у них просто невероятное – они чуют корни с пятидесяти шагов!" }, { 27.56, "Задачка, конечно, непростая, но если принесёшь мне корней, я хорошо заплачу." } } }, t = { d = 8.4, v = "goblin-male", n = { x = 89 }, c = { x = { { 0.00, "Прекрасно! О, я загоню их перекупщикам за очень хорошую цену!" }, { 4.67, "Спасибо за работу. Ты вполне надёжный поставщик!" } } } } },
    [1241] = { d = 36.2, v = "human-male", n = { x = 416 }, c = { x = { { 0.00, "Некоторое время назад один из наших дипломатов был отправлен в Терамор для встречи с Джайной Праудмур. Он не вернулся." }, { 8.42, "Я подозреваю, что к этому приложило руку Братство Справедливости, но уверенности у меня пока что нет." }, { 15.45, "Пока что нам удаётся скрывать факт исчезновения дипломата, но так продолжаться не может." }, { 21.87, "Агенты королевской службы рыщут по городам, но я хочу задействовать и свои связи." }, { 27.84, "В Аллее Героев вы найдёте моего старого друга, его зовут Йорген. Передайте ему эту записку и во всём его слушайтесь." } } }, t = { d = 20.5, v = "human-male#50", n = { x = 226 }, c = { x = { { 0.00, "Хм-м... Йорген смотрит на вас, прищурившись." }, { 3.48, "Хорошо. Придётся вам помочь, хоть и не очень-то хочется. Долг есть долг." }, { 8.74, "И запомните одну простую вещь: вы знаете куда больше, чем уместно в вашем случае." }, { 14.19, "Храните наши маленькие секреты и не болтайте по тавернам о том, что обнаружите. Ясно вам?" } } } } },
    [1242] = { d = 21.3, v = "human-male#50", n = { x = 248 }, c = { x = { { 0.00, "Возьмите записку для Иллинга Триаса." }, { 2.55, "Ничего ему не рассказывайте, просто ведите себя вежливо и дождитесь ответа; не волнуйтесь, Триас ответит." }, { 9.86, "Ещё раз напоминаю вам: дело серьёзное, так что держите рот на замке." }, { 14.82, "Триаса вы найдёте в его магазине в Торговом квартале; магазин называется \"Сыры Триаса\". Удачи!" } } }, t = { d = 16.7, v = "human-male#50", n = { x = 185 }, c = { x = { { 0.00, "Извините, письмо мне? О... не так уж часто мне приходится получать что-то, кроме ящиков и бочонков, я ведь занят делом. Ну, давайте посмотрим, что там." }, { 10.34, "Открывая письмо, Эллинг смотрит на вас." }, { 13.27, "Вы выглядите возбуждённо, с вами всё в порядке?" } } } } },
    [1243] = { d = 37.3, v = "human-male#50", n = { x = 428 }, c = { x = { { 0.00, "Йорген, ах ты старый мерзавец... Ну и что со всем этим делать?" }, { 4.46, "Ладно, я разберусь... Да чтоб ему в Круговерть Пустоты угодить раньше времени!" }, { 10.95, "Ну что, займёмся делом? Я задействую все свои контакты, но вам придётся побегать." }, { 16.73, "Отправляйтесь в поселение Темнолесье, которое находится в Сумеречном лесу, и найдите там дозорного Бакуса; он обычно патрулирует северную дорогу за городской стеной." }, { 27.69, "Просто скажите ему, что Братство Справедливости опять зашевелилось, а вы присматриваете за ним по моей просьбе – и он вам поможет, чем сможет." } } }, t = { d = 18.1, v = "human-male", n = { x = 191 }, c = { x = { { 0.00, "Вас послал Триас, да? Другое дело..." }, { 3.10, "Можете гонять чудовищ, сколько вам заблагорассудится." }, { 7.05, "Уверен, что для вас это не составит особого труда, какой бы ужас ни вылез на вас из сумерек..." }, { 13.87, "Так чего же желает мой дорогой друг в этот пасмурный день?" } } } } },
    [1244] = { d = 29.6, v = "human-male", n = { x = 332 }, c = { x = { { 0.00, "Опять братство?! Они вечно что-то вытворяют; даже если они затихли, мы считаем это недвусмысленной угрозой." }, { 7.80, "Кстати, сейчас я вспомнил, что последнюю пару недель их агенты так и кишат вокруг участка Эддла." }, { 14.38, "Это подозрительно – должно быть, назревает какая-то крупная заварушка." }, { 19.49, "Не хотите порыскать там и установить, в чём же дело?" }, { 23.38, "Ферма находится к югу от дороги из Западного Края как раз на входе в Сумеречный лес." } } }, t = { d = 19.6, v = "human-male", n = { x = 224 }, c = { x = { { 0.00, "Вы вернулись, не вляпавшись ни в какие неприятности. Это само по себе достижение, не правда ли?" }, { 6.86, "Ну, покажите, что принесли? Да, очень похоже на официальные документы Братства Справедливости." }, { 13.42, "Но это может быть и подделкой, которую вам подсунули, чтобы одурачить и сбить со следа." } } } } },
    [1245] = { d = 29.1, v = "human-male", n = { x = 297 }, c = { x = { { 0.00, "О-ох, для обычной попытки ввести в заблуждение это слишком сложно. Отнесите этот документ Триасу, пусть поразмыслит над ним." }, { 10.97, "И никому больше об этом не говорите. Кажется, это дело ни мне, ни ему не по плечу. Ну, посмотрим..." }, { 18.06, "И, пожалуйста, никому не говорите, что я вам помог." }, { 21.62, "Если моё начальство поймёт, что я о чём-то узнал и не поделился с ними, они могут меня запросто повесить." } } }, t = { d = 13.3, v = "human-male#50", n = { x = 148 }, c = { x = { { 0.00, "Да-а... весьма интересно. Йорген и Делавей молодцы, что навели меня на это." }, { 5.38, "Кажется, Братство Справедливости всерьёз взялось за воплощение своих планов. Хм, а это что? \"Кулак\"? Знакомое имя..." } } } } },
    [1274] = { d = 20.8, g = 1, v = "child-male", n = { m = 272, f = 274 }, c = { m = { { 0.00, "Простите, сэр. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства." }, { 9.26, "Если вы без лишнего шума проберётесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь." }, { 16.23, "Прошу вас, храните это в тайне, ибо всё это дело большой важности." } }, f = { { 0.00, "Простите, мадам. Епископ Делавей попросил меня разыскать любителя приключений, который мог бы помочь ему, оказав услугу весьма деликатного свойства." }, { 9.48, "Если вы без лишнего шума проберётесь в Крепость Штормграда и обратитесь к епископу, он наверняка примет вашу помощь." }, { 16.45, "Прошу вас, храните это в тайне, ибо всё это дело большой важности." } } }, t = { d = 25.2, v = "human-male", n = { x = 272 }, c = { x = { { 0.00, "Здравствуйте. Я – епископ Делавей." }, { 3.37, "Дайте-ка, я угадаю, почему вы здесь!" }, { 6.03, "Наверняка потому, что откликнулись на просьбу юного Томаса, который предложил вам оказать мне услугу. Он всегда стремится помочь мне." }, { 15.63, "Боюсь, я ещё не успел всё сформулировать, так что простите мне некоторую невнятность изложения..." }, { 22.19, "И, прошу вас, храните всё это в тайне." } } } } },
    [1275] = { d = 33.5, v = "nightelf-male#54", n = { x = 375 }, c = { x = { { 0.00, "Безрассудные эльфы крови попали в западню демонической магии. Разве они не видели, что случилось с нагами и сатирами Калимдора?" }, { 9.07, "Я боюсь, что эльфы крови могут претерпеть такую же трансформацию." }, { 13.54, "Азерот не может позволить себе породить ещё одну расу злобных монстров." }, { 19.30, "Я хотел бы изучить ствол мозга сатиров и нагов, чтобы понять, на что обрекают себя эльфы крови." }, { 25.83, "И сатиров, и нагов вы найдёте в Непроглядной Пучине, на побережье Ясеневого леса. Путь неблизкий." } } }, t = { d = 19.3, g = 1, v = "nightelf-male#54", n = { m = 210, f = 213 }, c = { m = { { 0.00, "Ты проделал долгий путь и, несомненно, столкнулся с множеством опасностей." }, { 5.25, "Твои поступки были бескорыстны. Ради блага всего Азерота ты помогаешь мне в моих исследованиях." }, { 12.16, "Благодарю тебя, за всё, что ты сделал." }, { 15.22, "А теперь, если позволишь… у меня ещё много работы." } }, f = { { 0.00, "Ты проделала долгий путь и, несомненно, столкнулась с множеством опасностей." }, { 5.63, "Твои поступки были бескорыстны. Ради блага всего Азерота ты помогаешь мне в моих исследованиях." }, { 12.53, "Благодарю тебя, за всё, что ты сделала." }, { 15.58, "А теперь, если позволишь… у меня ещё много работы." } } } } },
    [1338] = { d = 37.8, v = "dwarf-male", n = { x = 406 }, c = { x = { { 0.00, "Есть один дворф-бронник, чья работа меня глубоко восхищает. Его зовут Фьюрен Длиннобород, и такого искусника ещё поискать." }, { 10.70, "Мне нужен новый щит, и я хотел бы сделать заказ у него!" }, { 14.90, "Проблема в том... что он живёт далеко на юге, в Квартале Дворфов в Штормграде. В человеческих землях!" }, { 21.55, "Представления не имею, зачем он поселился так далеко от Стальгорна." }, { 26.28, "Должно быть, люди платят немалую мзду, лишь бы удержать его у себя!" }, { 31.32, "Если ты любишь путешествовать и не прочь подзаработать, может, передашь мой заказ Фьюрену?" } } }, t = { d = 15.0, v = "dwarf-male", n = { x = 163 }, c = { x = { { 0.00, "А, заказ от дворфа Грозовой Вершины. Это гордый клан, славный крепкими, сильными дворфами. И их богатством." }, { 8.35, "Большое спасибо. Я сегодня же вечером займусь щитом для горного пехотинца Грозовой Вершины." } } } } },
    [1339] = { d = 18.4, g = 1, v = "dwarf-male", n = { x = 206 }, c = { m = { { 0.00, "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие." }, { 8.11, "Сможет ли герой вроде тебя справиться с его поручением?" }, { 12.13, "Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне." } }, f = { { 0.00, "Я слышал, что горный пехотинец Грозовая Вершина ищет гонца, который совершил бы по его просьбе небольшое путешествие." }, { 8.11, "Сможет ли героиня вроде тебя справиться с его поручением?" }, { 12.51, "Если ты жаждешь приключений, ищи Грозовую Вершину на северной сторожевой башне." } } }, t = { d = 12.1, v = "dwarf-male", n = { x = 139 }, c = { x = { { 0.00, "Верно. У меня есть одно дельце, но самому мне недосуг – не могу покинуть пост. Путь неблизкий, придётся поработать ногами." }, { 8.46, "Зато отличная возможность поискать приключений!" } } } } },
    [1358] = { d = 45.0, v = "scourge-female", n = { x = 381 }, c = { x = { { 0.00, "Мой коллега на Калимдоре, аптекарь Хелбрим, исследует воздействие лордеронских ядов на тамошних зверей." }, { 11.14, "Он наверняка хотел бы иметь препарат из волчьего сердца, что мне прислал Ренферрел." }, { 20.52, "Хелбрим обосновался в Степях, в деревне под названием Перекрёсток." }, { 26.47, "Чтобы до него добраться, вам нужно будет на дирижабле добраться до орочьей столицы Оргриммара, а потом пешком проследовать на юг, в Дуротар." }, { 38.81, "Направляйтесь на запад, в Степи, и вскоре дойдёте до Перекрёстка." } } }, t = { d = 16.6, v = "scourge-male", n = { x = 176 }, c = { x = { { 0.00, "А, очень хорошо. Если первые результаты верны, токсические свойства этих сердец могут серьёзно продвинуть нас в наших представлениях о ядах." }, { 10.55, "Это долгожданная посылка. Ваша награда за неё – совершенно заслуженная." } } } } },
    [1359] = { d = 38.7, v = "scourge-male#82", n = { x = 347 }, c = { x = { { 0.00, "Волчьи сердца, которые вы собрали, обладают качеством, невиданным доселе в подобных образцах." }, { 8.51, "Это сила яда, которая должна быть смертельной даже для тех самых волков, в груди которых бьются эти сердца!" }, { 18.64, "Это просто невероятно, и мы должны продолжить исследование. Я сохранил несколько полученных препаратов." }, { 28.17, "Отнесите их моей коллеге, аптекарю Зинг. Её можно найти в главном представительстве нашего Общества в Подгороде." } } }, t = { d = 18.5, v = "scourge-female", n = { x = 173 }, c = { x = { { 0.00, "Ах да, препараты сердец, о которых говорил Ренферрел. Я хочу поскорее начать экспериментировать с ними..." }, { 9.28, "Обнаружение новых форм ядов всгда вызывает живейший интерес в Королевском фармацевтическом обществе." } } } } },
    [1431] = { d = 30.6, g = 1, v = "orc-male", n = { x = 331 }, c = { m = { { 0.00, "Слушай внимательно, герой. Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное." }, { 8.64, "Мы – народ гордый, и война с людьми истощила даже терпение Тралла." }, { 13.23, "Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми." }, { 23.54, "Если тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город." } }, f = { { 0.00, "Слушай внимательно, героиня. Мне нужно рассказать тебе кое-что, очень важное для нашего народа, но далеко не очевидное." }, { 8.87, "Мы – народ гордый, и война с людьми истощила даже терпение Тралла." }, { 13.47, "Наш вождь мудр и рассудителен, и интересы нашего народа для него превыше всего. В то же время он тонкий дипломат. Он умеет обращаться с людьми." }, { 23.77, "Если тебе это интересно, поговори с Кельдраном. Его лачуга стоит у западного входа в город." } } }, t = { d = 36.0, g = 1, v = "orc-male", n = { x = 370 }, c = { m = { { 0.00, "Патанни, герой! Меня зовут Кельдран, я изучаю магию... и другие тайные искусства." }, { 7.60, "Дело, по поводу которого ты здесь, требует большей тонкости, чем те, которыми тебе приходилось заниматься раньше." }, { 15.60, "Однако это не значит, что ты не можешь нам помочь." }, { 19.49, "Пожалуйста, устраивайся поудобнее. Я расскажу тебе, зачем вождю понадобилась моя... и твоя помощь." }, { 26.70, "Всё начинается со впечатления. Какой себя видит Орда. Какими видят нас наши союзники. И, главное, какими нас видят наши враги." } }, f = { { 0.00, "Патанни, героиня! Меня зовут Кельдран, я изучаю магию... и другие тайные искусства." }, { 7.09, "Дело, по поводу которого ты здесь, требует большей тонкости, чем те, которыми тебе приходилось заниматься раньше." }, { 15.09, "Однако это не значит, что ты не можешь нам помочь." }, { 18.97, "Пожалуйста, устраивайся поудобнее. Я расскажу тебе, зачем вождю понадобилась моя... и твоя помощь." }, { 26.19, "Всё начинается со впечатления. Какой себя видит Орда. Какими видят нас наши союзники. И, главное, какими нас видят наши враги." } } } } },
    [1432] = { d = 34.3, v = "orc-male", n = { x = 368 }, c = { x = { { 0.00, "Альянс всё расширяет свои владения в Калимдоре." }, { 3.41, "Из-за этого может сложиться впечатление, что Орда вступает в союз с Пылающим Легионом. Вождь не может этого допустить." }, { 11.74, "И я, с его благословения, буду отвечать за их изгнание." }, { 16.03, "У меня есть свои агенты в Пустошах, на Заставе Скитающихся Духов – это к северу от большого Кладбища кодо." }, { 24.24, "Ступай на юг от Обугленной долины в Когтистых горах, и увидишь заставу. Когда прибудешь туда, разыщи Такату Стального Клинка." } } }, t = { d = 31.0, g = 1, v = "orc-male#60", n = { x = 335 }, c = { m = { { 0.00, "Приветствую, герой! У тебя есть вести из Оргриммара? Это хорошо." }, { 4.80, "В здешних краях всё провоняло демонами – сильнее, чем кентавровым навозом." }, { 9.93, "Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться." }, { 16.61, "Получается, что мы вроде как помогаем кентаврам." }, { 19.88, "Это мне не по нутру, но всё это на благо Орды, так что я выполняю свой долг перед вождём, даже если ради этого приходится поддерживать чернокнижников." } }, f = { { 0.00, "Приветствую, героиня! У тебя есть вести из Оргриммара? Это хорошо." }, { 5.11, "В здешних краях всё провоняло демонами – сильнее, чем кентавровым навозом." }, { 10.24, "Конелюди вопят, что это их земли, но тут есть силы, с которыми им никак не справиться." }, { 16.92, "Получается, что мы вроде как помогаем кентаврам." }, { 20.19, "Это мне не по нутру, но всё это на благо Орды, так что я выполняю свой долг перед вождём, даже если ради этого приходится поддерживать чернокнижников." } } } } },
    [1442] = { d = 37.5, g = 1, v = "nightelf-male#54", n = { m = 407, f = 406 }, c = { m = { { 0.00, "День добрый. Чем могу помочь идущему путём Света?" }, { 4.70, "Ах да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нём не слышал." }, { 11.16, "Он никогда не казался мне злодеем, поэтому остаётся думать, что его стремление получить самоцвет Кора благородно." }, { 19.32, "Если вам и правда нужен самоцвет, то придётся направиться на северо-запад Ясеневого леса." }, { 25.52, "Там, среди древних развалин, вы обнаружите Непроглядную Пучину." }, { 30.27, "В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, герой." } }, f = { { 0.00, "День добрый. Чем могу помочь идущей путём Света?" }, { 4.42, "Ах да, кузнец Стилвелл... давно не виделись. Я хорошо его помню, хотя давно о нём не слышал." }, { 10.88, "Он никогда не казался мне злодеем, поэтому остаётся думать, что его стремление получить самоцвет Кора благородно." }, { 19.04, "Если вам и правда нужен самоцвет, то придётся направиться на северо-запад Ясеневого леса." }, { 25.24, "Там, среди древних развалин, вы обнаружите Непроглядную Пучину." }, { 30.00, "В их недрах таятся наги, и они до сих пор используют такие самоцветы. Не ходите туда в одиночку, героиня." } } }, t = { d = 25.3, g = 1, v = "nightelf-male#54", n = { x = 277 }, c = { m = { { 0.00, "Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой." }, { 14.01, "Пусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале." }, { 19.77, "Я надеюсь, вы понимаете, что делаете, герой, ибо в руках у вас не игрушка." } }, f = { { 0.00, "Действительно, это тот самый камень, который хочет получить Стилвелл, но, прежде чем я отдам его вам, надо очистить камень от скверны – мерзкие наги наполняют самоцветы силой, но своей, злобной силой." }, { 14.01, "Пусть Стилвелл знает, что мощь камня чиста, и он хорошо послужит в любом ритуале." }, { 19.77, "Я надеюсь, вы понимаете, что делаете, героиня, ибо в руках у вас не игрушка." } } } } },
    [1470] = { d = 42.4, v = "scourge-female#80", n = { x = 368 }, c = { x = { { 0.00, "Приветствую тебя, дитя. Вижу, ты только вступаешь на пути чернокнижия, мощь его не даётся тебе пока." }, { 9.45, "Я чувствую, как велико твоё желание учиться. Да, ты будешь учиться." }, { 15.53, "В невежестве нет силы. Знание – вот залог нашего могущества." }, { 20.75, "Знания позволяют нам контролировать хаотическую магию и тварей Бездны, склоняя их к своей воле." }, { 30.97, "Я покажу тебе, как подчинять себе слугу, но сначала принеси мне три черепа скелетов-костетрясов, бродящих близ покинутой кузницы." } } }, t = { d = 37.0, g = 1, v = "scourge-female#80", n = { m = 348, f = 349 }, c = { m = { { 0.00, "Хотя ты ещё не прошёл испытаний и находишься в самом начале ученичества, ты доказал, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле." }, { 14.25, "Пусть тебя не обманывают его небольшие размеры." }, { 18.46, "Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе." }, { 27.70, "Слушай меня внимательно, потому что повторять я не буду, и тогда придётся всё осваивать самостоятельно." } }, f = { { 0.00, "Хотя ты ещё не прошла испытаний и находишься в самом начале ученичества, ты доказала, что силы у тебя достаточно, чтобы суметь призвать беса и подчинить его своей воле." }, { 14.27, "Пусть тебя не обманывают его небольшие размеры." }, { 18.48, "Физической силы ему не хватает, зато хватит магического могущества и разума, чтобы хорошо служить тебе." }, { 27.72, "Слушай меня внимательно, потому что повторять я не буду, и тогда придётся всё осваивать самостоятельно." } } } } },
    [1471] = { d = 33.9, g = 1, v = "scourge-male#82", n = { m = 282, f = 283 }, c = { m = { { 0.00, "Ты наверняка уже видел круг призыва. Только в его пределы ты можешь вызвать демона Бездны." }, { 8.74, "При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии." }, { 18.06, "Подчинённый демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва." }, { 29.60, "Ты сможешь пользоваться им, когда захочешь." } }, f = { { 0.00, "Ты наверняка уже видела круг призыва. Только в его пределы ты можешь вызвать демона Бездны." }, { 8.77, "При помощи этих рун ты вызовешь его, а потом подчинишь себе силой оружия и магии." }, { 18.08, "Подчинённый демон Бездны будет неразрывно связан с тобой. Выполнив задание, возвращайся ко мне, я научу тебя заклинанию призыва." }, { 29.58, "Ты сможешь пользоваться им, когда захочешь." } } }, t = { d = 16.2, g = 1, v = "scourge-male#82", n = { m = 141, f = 142 }, c = { m = { { 0.00, "Великолепная работа. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны." }, { 8.53, "Ты сможешь обратить силу, которую недавно испытал на себе, против своих врагов." } }, f = { { 0.00, "Великолепная работа. Теперь я научу тебя заклинанию, позволяющему призвать демона Бездны." }, { 8.53, "Ты сможешь обратить силу, которую недавно испытала на себе, против своих врагов." } } } } },
    [1472] = { d = 46.1, v = "scourge-male#82", n = { x = 402 }, c = { x = { { 0.00, "Сайаады – пожиратели душ, разбивающие сердца и вводящие в искушение. Существа, исполненные зла и изощрённой хитрости." }, { 10.78, "Сказания из уст что праведников, что грешников говорят одно: их женщин называют суккубами, а мужчин – инкубами." }, { 21.24, "Просто так их в наш мир не выманишь. Сайаад не сможет устоять перед сердцами добрых и любящих смертных." }, { 30.82, "Когда он явится в Азерот, можно побороть его и подчинить себе." }, { 36.93, "Ступай в храм и поговори с моим помощником Годриком Фарсаном. Он поможет тебе подобрать приманку." } } }, t = { d = 15.9, g = 1, v = "scourge-male#83", n = { x = 159 }, c = { m = { { 0.00, "Тебя прислал Карендин? Говоришь, ты путник?" }, { 3.53, "Не думай, что я просто беспомощный слепец." }, { 6.81, "Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением." } }, f = { { 0.00, "Тебя прислал Карендин? Говоришь, ты путница?" }, { 3.67, "Не думай, что я просто беспомощный слепец." }, { 6.95, "Я вижу истинную суть вещей с недоступной прежде ясностью, и то, что было моим проклятьем, обернулось благословением." } } } } },
    [1473] = { d = 38.2, g = 1, v = "scourge-male#82", n = { m = 327, f = 328 }, c = { m = { { 0.00, "Похоже, ты готов призвать демона Бездны." }, { 4.13, "Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира." }, { 10.58, "Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части." }, { 18.43, "Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре." }, { 26.38, "К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями." } }, f = { { 0.00, "Похоже, ты готова призвать демона Бездны." }, { 4.20, "Эти твари появляются из Круговерти Пустоты, лежащей за пределами мира." }, { 10.66, "Если ты не сможешь подчинить себе вызванного демона, он разорвёт тебя на части." }, { 18.51, "Первого демона Бездны сумел вызвать Эгалин, и это подробно описано в его гримуаре." }, { 26.46, "К сожалению, агент Алого ордена похитил гримуар и спрятал его в башне к западу отсюда. Принеси книгу, и я наделю тебя знаниями." } } }, t = { d = 19.8, v = "scourge-male#82", n = { x = 166 }, c = { x = { { 0.00, "А, великолепно. Вероятно, Перрин не догадывался, какие знания скрывает в себе этот фолиант." }, { 9.36, "Мы больше не допустим хищения книги. Смотри: вот схема заклинания, объясняющая, как следует направлять энергию." } } } } },
    [1474] = { d = 32.5, v = "scourge-male#82", n = { x = 282 }, c = { x = { { 0.00, "При помощи этих сердец наложи заклинание на круг призыва, чтобы открыть дверь в наш мир для суккуба." }, { 9.37, "Твои силы возросли, и они понадобятся тебе, чтобы одолеть демоницу." }, { 15.76, "Остерегайся её чар, даже сила воли может не защитить от них." }, { 21.42, "Если ты победишь, суккуб вернётся в Бездну, а я научу тебя заклинанию, которое позволит тебе вызывать её в любой момент." } } }, t = { d = 24.7, g = 1, v = "scourge-male#82", n = { m = 217, f = 218 }, c = { m = { { 0.00, "И снова ты справился с заданием. Давно мне не встречались чернокнижники с такими задатками." }, { 8.38, "Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям." }, { 18.36, "А теперь я хочу научить тебя заклинанию призва личного суккуба." } }, f = { { 0.00, "И снова ты справилась с заданием. Давно мне не встречались чернокнижники с такими задатками." }, { 8.44, "Не сомневайся, я буду следить за твоими успехами и помогу тебе подготовиться к ожидающим тебя испытаниям." }, { 18.42, "А теперь я хочу научить тебя заклинанию призва личного суккуба." } } } } },
    [1476] = { d = 37.0, v = "scourge-male#83", n = { x = 381 }, c = { x = { { 0.00, "Чтобы поймать суккуба, нужно чистое сердце. Но разве остались среди смертных непорочные сердца?" }, { 7.46, "После долгих поисков и расспросов мне удалось найти только двоих." }, { 12.80, "Первый из них – Далин Искусник. Он посвятил свою жизнь заботе о лордеронских беженцах, которых отказалась принять родня у Стены Седогрива." }, { 24.26, "Вторая – Корма Виллард. Она скорбит об утраченной дружбе и бродит по Болотине в поисках подруги." }, { 31.66, "Принеси их сердца Карендину. Но сначала я покажу тебе твои жертвы." } } }, t = { d = 20.5, v = "scourge-male#82", n = { x = 155 }, c = { x = { { 0.00, "А с виду доброе сердце ничем не отличается от любого другого, да?" }, { 6.50, "Может быть, мы просто... по-другому смотрим на мир. Но эти сердца прекрасно подойдут. Не сомневаюсь, их чистота привлечёт суккуба." } } } } },
    [1478] = { d = 23.1, v = "scourge-male#83", n = { x = 240 }, c = { x = { { 0.00, "А! Я только что получил новости от Карендина Халгара – он хочет поговорить с вами насчёт дальнейшего обучения." }, { 8.54, "Можете гордиться собой! Не каждый день мастер Халгар решает самолично проинструктировать юного чернокнижника." }, { 17.82, "Его можно найти в Квартале Магов Подгорода, возле Храма Проклятых." } } }, t = { d = 14.8, v = "scourge-male#82", n = { x = 128 }, c = { x = { { 0.00, "Хорошо, я вижу, Агерон нашёл вас. Давайте не будем тратить время на болтовню и церемонии, а сразу же перейдём к вашему обучению. Вам ещё очень много надо узнать." } } } } },
    [1483] = { d = 33.2, v = "goblin-male", n = { x = 385 }, c = { x = { { 0.00, "Торговая Компания переманила лучшие гоблинские умы, но порой у нас появляется возможность вернуть своё." }, { 7.54, "Некоторое время назад подразделение Торговой Компании в Когтистых горах приняло на работу Геренцо Терминатрикса – гнома!" }, { 15.93, "Это так ошарашило другого инженера, Зиза Физзикса, что он умолял меня найти ему новую работу в Союзе ремонтников." }, { 23.85, "Я дал ему несколько заданий, но ему может понадобиться помощь." }, { 28.53, "Не навестишь его? Он живёт у западного края Утёса Ветрорезов." } } }, t = { d = 19.9, v = "goblin-male", n = { x = 200 }, c = { x = { { 0.00, "Я думал, что начальство Торговой Компании – настоящие тираны, но потом я познакомился с Пароклапаном, он хуже их всех!" }, { 8.45, "Ха! И всё же это лучше, чем сидеть без работы... Или, хуже того, работать с этим Геренцо." }, { 16.05, "Если ты хочешь мне помочь, дело для тебя найдётся." } } } } },
    [1485] = { d = 31.2, v = "orc-male", n = { x = 355 }, c = { x = { { 0.00, "Чернокнижники, бывшие здесь до нас, внушили Орде недоверие к нам. Нас терпят, но недолюбливают." }, { 6.90, "Однако это не заставило чернокнижников сплотиться. Многие предпочитают жить и заниматься магией в уединении." }, { 14.52, "Я не буду принуждать тебя избрать тот или иной путь, а всего лишь помогу тебе сделать очередной шаг." }, { 22.06, "Но прежде чем я научу тебя искусству призывания, принеси мне шесть голов злолбных фамильяров из той пещеры на северо-востоке." } } }, t = { d = 15.7, v = "orc-male", n = { x = 168 }, c = { x = { { 0.00, "Во время обучения ты научишься вызывать самых разных существ." }, { 4.41, "Все они по-своему полезны, даже если на первый взгляд это не очевидно." }, { 9.88, "Пусть малый рост беса тебя не смущает. Ты уже знаешь, как опасны они бывают." } } } } },
    [1486] = { d = 37.7, v = "tauren-male", n = { x = 377 }, c = { x = { { 0.00, "Пока Наралекс погружался в свои кошмары всё глубже, из-под Степей в Пещеры Стенаний пришли какие-то странные животные." }, { 9.68, "Эти искажённые существа наделены странными, потусторонними силами." }, { 14.88, "В то время как зло в их природе, я уверен, что из их существования можно извлечь некоторую пользу здесь в Калимдоре." }, { 23.93, "Я верю, что из их кожи наши кожевники смастерят что-нибудь стоящее." }, { 30.18, "Если эта задача тебе по вкусу, отправляйся в пещеры и принеси мне немного искажённых шкур." } } }, t = { d = 8.0, g = 1, v = "tauren-male", n = { x = 67 }, c = { m = { { 0.00, "Твои услуги не останутся незамеченными. путник." }, { 4.07, "Спасибо тебе за твою неоценимую помощь." } }, f = { { 0.00, "Твои услуги не останутся незамеченными. путница." }, { 4.55, "Спасибо тебе за твою неоценимую помощь." } } } } },
    [1487] = { d = 34.0, v = "nightelf-female", n = { x = 379 }, c = { x = { { 0.00, "Цели у Наралекса были самые благие." }, { 2.91, "Наш лидер стремился впасть в Изумрудный сон, и вновь превратить эти выжженные земли в тот пышный лес, которым они когда-то являлись. Но что-то пошло не так." }, { 13.84, "Мечта Наралекса превратилась в кошмар, и порченые твари заселили пещеры." }, { 19.21, "В то время как некоторые приспешники Наралекса стремятся пробудить нашего мастера, я забочусь о том, чтобы избавить эти пещеры от заполонивших их тварей." }, { 30.30, "Отправляйся туда. и уничтожь порченое семя." } } }, t = { d = 12.5, v = "nightelf-female", n = { x = 139 }, c = { x = { { 0.00, "Как послушник Наралекса я не могу не отметить твоей храбрости." }, { 4.27, "Твоя помощь – это всего лишь первый шаг в очищении Степей от порчи." }, { 9.20, "Благодарю тебя, и да пребудет тобой удача." } } } } },
    [1489] = { d = 39.1, v = "tauren-male", n = { x = 381 }, c = { x = { { 0.00, "На раковинах, что ты мне принёс, присутствует порча, которой я никогда раньше не видел." }, { 6.96, "Я уверен, что причины её возникновения кроются в воде оазиса, и я уже предчувствую, чем это грозит этим землям." }, { 16.14, "Источник этой порчи в Пещерах Стенаний, но прежде чем отправиться туда, поговори с Хамуулом Руническим Тотэмом, старшим друидом." }, { 26.22, "Я послал ему весточку о том, что творится в Степях. Он мудр и сможет дать тебе дельный совет." }, { 34.76, "Найдёшь его в Громовом Утёсе, на Вершине Старейшин." } } }, t = { d = 11.7, v = "tauren-male", n = { x = 108 }, c = { x = { { 0.00, "Приветствую тебя, добро пожаловать. И лучше бы тебе собрать всю волю в кулак, потому что дело, порученное тебе, будет крайне нелёгким." } } } } },
    [1490] = { d = 38.9, v = "tauren-male", n = { x = 372 }, c = { x = { { 0.00, "Я вошёл в сновидения и увидел там орден друидов, обитающих в Пещерах Стенаний. Когда-то их цели были благородными." }, { 9.66, "Но теперь они отклонились от первоначального пути и стали слугами порчи просачивающейся из Степей." }, { 17.89, "Я уже стар, и мои силы не бесконечны. Я не мог дольше оставаться в сновидениях, хотя и хотел узнать больше об этих друидах." }, { 28.53, "Но Нара молода и сильна духом, и она осталась там, когда я вынужден был уйти." }, { 35.01, "Поговори с ней, ты найдёшь её в дальней палатке." } } }, t = { d = 15.6, g = 1, v = "tauren-female", n = { m = 146, f = 146 }, c = { m = { { 0.00, "Всё верно, я знаю о друидах из Пещер Стенаний. Я видела их исковерканные, покрытые чешуёй лица." }, { 7.91, "Я знаю об их злодеяниях, и самое главное, мне известны их планы. Ты должен остановить их." } }, f = { { 0.00, "Всё верно, я знаю о друидах из Пещер Стенаний. Я видела их исковерканные, покрытые чешуёй лица." }, { 7.91, "Я знаю об их злодеяниях, и самое главное, мне известны их планы. Ты должна остановить их." } } } } },
    [1491] = { d = 36.9, v = "goblin-male", n = { x = 418 }, c = { x = { { 0.00, "Ладно, рога ящеров не подошли. Ничего страшного, с первого раза никому не удаётся разбогатеть." }, { 6.60, "Кроме того, мне удалось придумать кое-что получше!" }, { 10.45, "Существует вещество, именуемое воющей субстанцией, и мне кажется, именно из-за него в Степях такие странные растения и животные." }, { 19.42, "Принеси мне немного субстанции, и я попробую добавить её в напиток!" }, { 24.51, "Насколько я знаю, это вещество накапливается в эктоплазматических существах в Пещерах Стенаний на западе." }, { 31.87, "Убей несколько существ из пещер и собери из них субстанцию." } } }, t = { d = 11.8, v = "goblin-male", n = { x = 124 }, c = { x = { { 0.00, "Здорово, ты принёс её! Не терпится опробовать напиток. Я знаю, он принесёт мне много денег!" }, { 6.75, "Спасибо. Вот тебе деньги, и, разбогатев, я пришлю тебе ещё, клянусь!" } } } } },
    [1492] = { d = 25.2, g = 1, v = "scourge-male", n = { m = 261, f = 263 }, c = { m = { { 0.00, "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света." }, { 6.32, "У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл." }, { 13.05, "Не мог бы ты отнести ящик управляющему пристанью Головокружилкинсу?" }, { 18.16, "А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья." } }, f = { { 0.00, "Мне нужно послать ящик зелий, реактивов и прочего своим партнёрам из Старого Света." }, { 6.32, "У меня нет времени лично относить их в порт Кабестана, а последний караван уже отбыл." }, { 13.05, "Не могла бы ты отнести ящик управляющему пристанью Головокружилкинсу?" }, { 18.26, "А он в свою очередь погрузит его на первый же корабль, идущий в бухту Черноводья." } } }, t = { d = 15.3, g = 1, v = "goblin-male", n = { x = 156 }, c = { m = { { 0.00, "Небольшой ящик. Да, пожалуй, для него найдётся место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно." }, { 9.02, "Надо только записать его в мой регистр. Ну вот, всё готово. Пока, герой." } }, f = { { 0.00, "Небольшой ящик. Да, пожалуй, для него найдётся место на корабле. Он отплывет в ближайший прилив, это достаточно скоро? Великолепно." }, { 9.02, "Надо только записать его в мой регистр." }, { 12.17, "Ну вот, всё готово. Пока, героиня." } } } } },
    [1498] = { d = 30.5, v = "orc-male#60", n = { x = 329 }, c = { x = { { 0.00, "Одна из основных задач воина... защита. Мы – щит Орды, заслоняющий собой наших более слабых братьев." }, { 6.92, "Если ты хочешь вступить в наши ряды, докажи мне, что не струсишь." }, { 11.91, "Ступай в Дуротар, на Громовой хребет, где живут бурешкуры и рокочущие ящерицы. Поохоться на них, докажи, что ты сильнее их!" }, { 21.37, "Выстой против них и принеси мне в доказательство побольше оплавленных чешуек." }, { 27.07, "Как только принесёшь, я возьмусь тебя учить." } } }, t = { d = 18.4, g = 1, v = "orc-male#60", n = { m = 197, f = 197 }, c = { m = { { 0.00, "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкий." }, { 6.24, "А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости." }, { 14.50, "Учись хорошенько. Вскоре тебе предстоит новый урок." } }, f = { { 0.00, "А, вижу, тебе удалось справиться с рокочущими ящерицами, значит, ты крепкая." }, { 5.34, "А теперь я покажу тебе, как можно сделаться почти неуязвимым для противника благодаря толстой шкуре и ловкости." }, { 13.60, "Учись хорошенько. Вскоре тебе предстоит новый урок." } } } } },
    [1499] = { d = 20.7, g = 1, v = "orc-male", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами." }, { 9.16, "Думаю, тебе не помешает набраться опыта, помогая Зурите." }, { 13.21, "Не забудь ей сказать, что ты помогал разобраться с бесами – возможно, у неё найдётся для тебя награда." } }, f = { { 0.00, "Зурита часто посылает таких новичков, как ты, приструнить этих тварей. Тебе уже доводилось сражаться с коварными фамильярами." }, { 9.16, "Думаю, тебе не помешает набраться опыта, помогая Зурите." }, { 13.21, "Не забудь ей сказать, что ты помогала разобраться с бесами – возможно, у неё найдётся для тебя награда." } } }, t = { d = 11.0, v = "orc-female", n = { x = 117 }, c = { x = { { 0.00, "Молодец!" }, { 1.24, "Да, злобные фамильяры для воинов Пылающего Клинка – всего лишь ручные зверушки, однако же твой успех предсказывает тебе великие дела!" } } } } },
    [1501] = { d = 30.2, v = "orc-male", n = { x = 318 }, c = { x = { { 0.00, "Чернокнижников осталось так мало... Мы многим рискуем, но наш риск оправдан!" }, { 5.36, "Если ты хочешь принести пользу Орде и вождю, пора тебе научиться новому заклинанию призыва." }, { 12.24, "Для начала добудь табличку Верги. Чернокнижники из клана Пылающего Клинка похитили её и хранят у себя в логове, под скалой Черепа к востоку от города." }, { 24.84, "После этого я покажу тебе руны, необходимые для призыва демона Бездны." } } }, t = { d = 12.8, v = "orc-male", n = { x = 143 }, c = { x = { { 0.00, "Молодец. Надеюсь, во время твоего визита в логово чернокнижники из клана Пылающего Клинка сильно пострадали?" }, { 7.97, "Они причинили немало вреда вождю, да и нам, чернокнижникам, тоже." } } } } },
    [1502] = { d = 25.1, v = "orc-male#60", n = { x = 284 }, c = { x = { { 0.00, "Воину пристало владеть хорошим оружием. Самое лучшее оружие делает орк по имени Тун'грим Огневзор." }, { 6.92, "Это отшельник, который живёт на вершине холма к востоку от Перекрёстка." }, { 12.18, "Если тебе нужно оружие, воин, отправляйся к Тун'гриму." }, { 16.10, "Чтобы добраться до его жилища, дойди до Перекрёстка и сверни на восток, в сторону холмов. Он разбил лагерь на самой вершине." } } }, t = { d = 15.1, g = 1, v = "orc-male#60", n = { m = 153, f = 154 }, c = { m = { { 0.00, "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу." }, { 6.56, "Например, тебе что-то от меня нужно." }, { 9.46, "И раз ты добрался до моего жилища, то я могу предположить, что именно." } }, f = { { 0.00, "Я так долго глядел на пламя горна, что у меня высохли глаза, но кое-что я по-прежнему вижу." }, { 6.56, "Например, тебе что-то от меня нужно." }, { 9.46, "И раз ты добралась до моего жилища, то я могу предположить, что именно." } } } } },
    [1503] = { d = 32.4, v = "orc-male#60", n = { x = 361 }, c = { x = { { 0.00, "Я дам тебе оружие, но прежде помоги мне. Несколько дней назад с северо-запада на меня напало племя Иглогривых." }, { 7.86, "Биться со мной они побоялись, но зная, какое у меня плохое зрение, одни отвлекли меня своим пофыркиванием, а другие ограбили мой лагерь! Трусы!" }, { 18.22, "Они украли железный сундук, в котором лежали стальные слитки. Если ты сможешь вернуть их, я дам тебе нужное оружие." }, { 26.60, "Найди мой сундук в одном из лагерей иглогривов и принеси мне стальные слитки." } } }, t = { d = 13.5, v = "orc-male#60", n = { x = 147 }, c = { x = { { 0.00, "Вот они! И все мои слиточки на месте, что и неудивительно. Откуда иглогривым знать, что делать с такой отличной сталью." }, { 8.72, "Спасибо. Вот твоя награда. Пусть она служит тебе верой и правдой." } } } } },
    [1504] = { d = 28.0, v = "orc-male", n = { x = 310 }, c = { x = { { 0.00, "Посмотри на табличку Верги. Изображённые на ней знаки понадобятся тебе для призыва." }, { 5.95, "Отнеси это в круг в шатре Нииру Огненного Клинка на другом конце пещеры. Там ты сможешь вызвать демона Бездны." }, { 14.79, "Тебе нужно будет одолеть его любыми физическими и магическими средствами." }, { 20.10, "А после этого возвращайся ко мне со знаками призыва, и я покажу тебе, как подчинить это существо своей воле." } } }, t = { d = 20.1, v = "orc-male", n = { x = 218 }, c = { x = { { 0.00, "Молодец! Я покажу тебе, как вызывать демона Бездны, подобного тому, которого тебе только что пришлось одолеть." }, { 8.13, "Знай, мы на тебя очень рассчитываем, и пока что ты оправдываешь все наши надежды!" }, { 14.30, "Однако пусть успех не кружит тебе голову. Впереди куда более сложные задачи!" } } } } },
    [1505] = { d = 31.2, v = "tauren-male", n = { x = 273 }, c = { x = { { 0.00, "Орда чтит своих воинов, потому что никто не сомневается в их силе. Но истинному величию чуждо самодовольство." }, { 10.22, "Никогда не упускай случая поучиться новому." }, { 14.10, "Отыщи Уззека. Он прошёл через много сражений и теперь обучает молодых воинов боевым приёмам." }, { 23.48, "Он живёт на юге от Дальней заставы, орочьего гарнизона на границе Степей и Дуротара." } } }, t = { d = 3.3, v = "orc-male#60", n = { x = 33 }, c = { x = { { 0.00, "Приветствую тебя. Ты здесь для обучения?" } } } } },
    [1506] = { d = 22.0, g = 1, v = "orc-male", n = { x = 220 }, c = { m = { { 0.00, "Эй, ты! Ты ведь путник, верно?" }, { 2.83, "Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул." }, { 9.79, "Ты найдёшь его среди старших чернокнижников в расселине Теней." }, { 14.55, "Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое." } }, f = { { 0.00, "Эй, ты! Ты ведь путница, верно?" }, { 3.15, "Надеюсь, сейчас у тебя нет никаких срочных дел, потому что тебя немедленно хочет видеть Гарнул." }, { 10.11, "Ты найдёшь его среди старших чернокнижников в расселине Теней." }, { 14.87, "Насколько я знаю Ган'рула, это сулит тебе либо что-то очень хорошее, либо что-то очень плохое." } } }, t = { d = 14.0, v = "orc-male", n = { x = 142 }, c = { x = { { 0.00, "Ага, хорошо. Я опасался, что Офек не сумеет с тобой связаться." }, { 5.47, "Тебе пора продолжить своё обучение на чернокнижника. Все прочие дела пока отложи. Надеюсь, с этим проблем не будет?" } } } } },
    [1507] = { d = 34.2, v = "orc-male", n = { x = 340 }, c = { x = { { 0.00, "Пора тебе научиться новому колдовству. Ты научишься вызывать сайаада, чьи чары порабощают разум." }, { 6.99, "Это существо способно зачаровывать и подчинять себе слабых духом. Но не бойся! Я уверен, тебя ему не одолеть." }, { 15.08, "Чтобы приманить сайаада, нужен предмет, в котором воплощена искренняя любовь и преданность. Тебе нужно найти такую вещь." }, { 25.60, "Где? Ну, потолкуй с Казулом. Чего не знает этот старый чернокнижник, того и знать не стоит." } } }, t = { d = 10.4, g = 1, v = "orc-male", n = { x = 101 }, c = { m = { { 0.00, "Хм... путник. Ты ещё новичок, но я чую в тебе большие способности." }, { 4.84, "У тебя врождённый дар к чернокнижию. Такими вещами не разбрасываются." } }, f = { { 0.00, "Хм... путница. Ты ещё новичок, но я чую в тебе большие способности." }, { 5.12, "У тебя врождённый дар к чернокнижию. Такими вещами не разбрасываются." } } } } },
    [1508] = { d = 25.3, g = 1, v = "orc-male", n = { m = 234, f = 235 }, c = { m = { { 0.00, "Раз Ган'рул отправил тебя ко мне, ты, должно быть, хочешь вызвать суккуба, женщину-сайаад, и ищешь приманку..." }, { 9.47, "Ну, если ты готов довериться слепому поводырю, то слушай. Среди утёсов Оргриммара, к западу от башни ветрокрылов, живёт Занкайя." }, { 19.39, "Она ждёт, когда к ней вернётся близкий друг. Ступай к ней." } }, f = { { 0.00, "Раз Ган'рул отправил тебя ко мне, ты, должно быть, хочешь вызвать суккуба, женщину-сайаад, и ищешь приманку..." }, { 9.47, "Ну, если ты готова довериться слепому поводырю, то слушай. Среди утёсов Оргриммара, к западу от башни ветрокрылов, живёт Занкайя." }, { 20.89, "Она ждёт, когда к ней вернётся близкий друг. Ступай к ней." } } }, t = { d = 9.2, v = "orc-female", n = { x = 97 }, c = { x = { { 0.00, "У тебя есть весточка от Дограна? Он должен был вернуться уже несколько дней тому назад, а о нём до сих пор ни слуху, ни духу..." } } } } },
    [1509] = { d = 33.0, v = "orc-female", n = { x = 352 }, c = { x = { { 0.00, "Моего супруга, Дограна, не так давно отправили служить в Перекрёсток. Это было повышение по службе, он так гордился…" }, { 8.58, "Мне, конечно, было грустно, но ему я этого не показывала. Грустно и тревожно." }, { 14.00, "Степи – не Оргриммар, это опасное место, и я боялась худшего…" }, { 18.64, "Он должен был вернуться неделю назад, а от него до сих пор нет никаких вестей!" }, { 24.64, "Может, ты сходишь в Перекрёсток, разузнаешь о нём? Он служил вместе с Газрогом, и Газрог, наверное, до сих пор там..." } } }, t = { d = 13.0, v = "orc-male", n = { x = 128 }, c = { x = { { 0.00, "Занкайя? Жена Дограна, да?" }, { 2.18, "Слышать-то я о нём слышал, но это не те новости, которые стоит ей передавать." }, { 8.11, "Да нет, не убили его. Но он ранен и сейчас в плену у иглогривов." } } } } },
    [1510] = { d = 30.8, v = "orc-male", n = { x = 336 }, c = { x = { { 0.00, "Он был в Лагере Таурахо, где мы пытались извести иглогривов." }, { 4.32, "Он повёл нескольких рубак на одно из их стойбищ, и там его тяжело ранили. Остальные вернулись и попытались его выручить." }, { 12.98, "Но он был в плохом состоянии, раны загноились, и ребята побоялись его трогать." }, { 18.74, "Они отправили сюда послание, просили троллей из Малака'джина у Когтистых гор прислать целительное зелье." }, { 26.79, "Мы послали за зельем, но гонец пока не вернулся." } } }, t = { d = 17.1, g = 1, v = "troll-male#78", n = { x = 161 }, c = { m = { { 0.00, "путник? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра." }, { 11.00, "Он успел сказать, что приехал за целительным зельем, но больше ничего вразумительного." } }, f = { { 0.00, "путница? Надеюсь, ты не за тем, другим? А то он добрался не очень... благополучно. Общение с гоблинами не довело его до добра." }, { 10.34, "Он успел сказать, что приехал за целительным зельем, но больше ничего вразумительного." } } } } },
    [1511] = { d = 26.7, v = "troll-male#78", n = { x = 271 }, c = { x = { { 0.00, "Я так и думал, что за зельем явится кто-нибудь ещё!" }, { 3.83, "Вот оно, бери. Имей в виду, сразу всё ему не давай, пусть выпьет половину! Этого ему хватит, чтобы передвигаться." }, { 13.61, "А иначе он истечёт кровью. На следующее утро пусть выпьет вторую половину." }, { 19.16, "Отнеси это Логмару в Лагерь Таурахо. Судя по тому, что сказал мне первый гонец, Логмар знает, где Догран." } } }, t = { d = 11.0, v = "orc-male#60", n = { x = 116 }, c = { x = { { 0.00, "О, как нельзя более кстати! А то Догран уже умирает там, в плену." }, { 4.91, "Это нужно доставить ему немедленно. Но большинство моих рубак сейчас на задании..." } } } } },
    [1512] = { d = 21.1, v = "orc-male", n = { x = 213 }, c = { x = { { 0.00, "Занкайя молода и красива. Зачем ей калека? Несправедливо это будет." }, { 5.61, "Оставь меня. Спасибо тебе. Я предпочёл бы умереть в славной битве, а не влачить это жалкое существование." }, { 14.27, "И прошу тебя, не говори об этом моей супруге... Не хочу, чтобы она чувствовала себя виноватой." } } }, t = { d = 11.9, v = "orc-male", n = { x = 124 }, c = { x = { { 0.00, "Ну, если ты говоришь, что этого достаточно, я тебе верю. Дай-ка я её оботру..." }, { 5.34, "Да, вот такая, блестящая и чистенькая, она будет куда соблазнительней для суккуба." } } } } },
    [1513] = { d = 22.8, v = "orc-male", n = { x = 259 }, c = { x = { { 0.00, "Отнеси это к кругу призыва в шатре Нииру. Вызови гнусного суккуба и покажи ему, кто здесь хозяин. Я верю в силу твоей магии." }, { 8.67, "Но всё же будь осторожнее: гордость и самоуверенность погубили немало многообещающих чернокнижников." }, { 16.18, "Когда подчинишь суккуба, верни подвеску мне. Нужно будет сообщить Занкайе о случившемся." } } }, t = { d = 34.4, v = "orc-male", n = { x = 370 }, c = { x = { { 0.00, "Получилось! Впрочем, я ничего другого и не ждал, ведь ты – мой лучший ученик." }, { 5.75, "Теперь я с радостью покажу тебе, как вызывать усмиренного суккуба. Ступай, тебе многому нужно научиться." }, { 13.76, "Я рассчитываю, что к нашей следующей встрече ты уже по-настоящему подчинишь своего суккуба." }, { 20.67, "С печальной историей Дограна и Занкайи разберутся те, кто постарше тебя." }, { 26.22, "Но ты её не забывай: она послужит хорошей защитой от хитростей тёмного демона, который явился к тебе сегодня." } } } } },
    [1515] = { d = 24.0, v = "orc-male#60", n = { x = 249 }, c = { x = { { 0.00, "Ну, раз уж ты здесь и хочешь завершить своё дело, останавливать тебя я не буду." }, { 5.60, "Но своих воинов я с тобой отпустить не смогу, ступай в одиночку." }, { 10.39, "Дограна держат в лагере иглогривов, к северу отсюда. Ищи две хижины, стоящие рядом." }, { 16.14, "Иглогривы его стерегут – если, конечно, его ещё не убили, или он не умер от ран. Удачи тебе!" } } }, t = { d = 12.0, v = "orc-male", n = { x = 116 }, c = { x = { { 0.00, "Тьфу, гадость…" }, { 1.57, "Однако сил у меня прибавляется. Пожалуй, я теперь смогу уковылять отсюда... Однако похоже, что ногу мне придётся отнять. И руку тоже." } } } } },
    [1516] = { d = 33.1, g = 1, v = "troll-male#77", n = { m = 337, f = 339 }, c = { m = { { 0.00, "Что ж, герой, пора! Ты набрался сил, твой дух стоек, как сама Земля." }, { 4.96, "А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости." }, { 10.80, "Стихия земли будет управлять твоей судьбой, станет частью тебя. Готов ли ты? Тебе придётся предстать перед самой Землёй." }, { 19.09, "И тогда ты увидишь многое, что ведомо лишь шаманам." }, { 23.04, "Разыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твоё будущее." } }, f = { { 0.00, "Что ж, героиня, пора! Ты набралась сил, твой дух стоек, как сама Земля." }, { 5.67, "А то, что тобою избран путь шамана – само по себе доказательство твоей мудрости." }, { 11.51, "Стихия земли будет управлять твоей судьбой, станет частью тебя. Готова ли ты? Тебе придётся предстать перед самой Землёй." }, { 20.57, "И тогда ты увидишь многое, что ведомо лишь шаманам." }, { 24.53, "Разыщи на севере ловцов скверны и добудь два их копыта. А потом возвращайся ко мне, и мы обсудим твоё будущее." } } }, t = { d = 25.7, g = 1, v = "troll-male#77", n = { m = 285, f = 286 }, c = { m = { { 0.00, "Великолепно! Твой успех доказывает: ты действительно готов." }, { 4.37, "Среди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твоё терпение." }, { 11.01, "Земля защитит тебя, если ты будешь относиться к ней с должным почтением." }, { 15.98, "Но и Земля, как все прочие стихии, может быть своенравной." }, { 20.35, "Теперь я сделаю для тебя сапту. Прими её – и постигнешь свой путь!" } }, f = { { 0.00, "Великолепно! Твой успех доказывает: ты действительно готова." }, { 4.50, "Среди стихий именно Земля – основа всего сущего. Это твоя сила, твоя выносливость и твоё терпение." }, { 11.14, "Земля защитит тебя, если ты будешь относиться к ней с должным почтением." }, { 16.10, "Но и Земля, как все прочие стихии, может быть своенравной." }, { 20.48, "Теперь я сделаю для тебя сапту. Прими её – и постигнешь свой путь!" } } } } },
    [1517] = { d = 31.6, v = "troll-male#77", n = { x = 361 }, c = { x = { { 0.00, "Сапта – это напиток, который связывает душу со стихией. Сама магия растворена в нём." }, { 5.72, "И сильные духом благодаря ему способны зреть стихии, которых никто более не видит. Твой дух будет связан со стихией сапты." }, { 14.19, "Лишь немногие избранные шаманы знают рецепт этого напитка." }, { 18.74, "Запомни: сапту можно пить лишь в священном месте, и нигде более!" }, { 23.47, "Отыщи Священный Камень к юго-западу отсюда. Он находится в конце Потайной тропы. Выпей там сапту, а дальше... увидишь!" } } }, t = { d = 60.3, g = 1, v = "elemental-earth", n = { m = 405, f = 406 }, c = { m = { { 0.00, "Ах... путник... Земля ликует от того, что ты пришёл сюда." }, { 6.68, "Теперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности." }, { 25.23, "Для прохождения этого обряда довольно было смиренно предстать перед землёй." }, { 33.68, "Но другие обряды потребуют более активных действий.Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий." }, { 48.88, "Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." } }, f = { { 0.00, "Ах... путница... Земля ликует от того, что ты пришла сюда." }, { 6.52, "Теперь ты связана с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности." }, { 25.24, "Для прохождения этого обряда довольно было смиренно предстать перед землёй." }, { 33.69, "Но другие обряды потребуют более активных действий.Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий." }, { 48.89, "Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." } } } } },
    [1518] = { d = 51.0, g = 1, v = "elemental-earth", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались." }, { 13.93, "Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма." }, { 21.47, "Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого." }, { 34.86, "Будь терпелив. Оставайся сильным. И ищи мудрости." }, { 40.79, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } }, f = { { 0.00, "Возьми этот необработанный кварц и отнеси его Канаге заклинателю земли в доказательство того, что мы с тобой встречались." }, { 13.17, "Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма." }, { 20.71, "Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого." }, { 34.10, "Будь терпелива. Оставайся сильной. И ищи мудрости." }, { 40.07, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } } }, t = { d = 24.7, g = 1, v = "troll-male#77", n = { m = 293, f = 294 }, c = { m = { { 0.00, "Великолепно!" }, { 1.30, "Тотэм, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями." }, { 8.02, "Его можно использовать для сосредоточения заклинаний Земли." }, { 12.10, "Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно." }, { 18.04, "Наставники скажут тебе, когда ты будешь готов к новым знаниям. А пока возьми этот тотэм Земли." } }, f = { { 0.00, "Великолепно!" }, { 1.30, "Тотэм, который я создам для тебя, – не просто символ нового статуса. Он обладает тайными возможностями." }, { 8.02, "Его можно использовать для сосредоточения заклинаний Земли." }, { 12.10, "Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно." }, { 18.04, "Наставники скажут тебе, когда ты будешь готова к новым знаниям. А пока возьми этот тотэм Земли." } } } } },
    [1519] = { d = 43.1, g = 1, v = "tauren-female", n = { m = 399, f = 401 }, c = { m = { { 0.00, "Время настало, юный герой. Тело твоё возмужало, а дух закалился, как сама земля. Я вижу, ты обрёл мудрость." }, { 8.94, "Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придётся пройти испытания." }, { 18.90, "Если ты готов, твоему взору откроется то, о чём известно лишь нашему народу." }, { 25.14, "Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах." }, { 35.09, "Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья." } }, f = { { 0.00, "Время настало, юная героиня. Тело твоё возмужало, а дух закалился, как сама земля. Я вижу, ты обрела мудрость." }, { 10.26, "Земля ведёт и хранит наш народ, она говорит с нами, как однажды станет говорить с тобой. Но тебе придётся пройти испытания." }, { 20.23, "Если ты готова, твоему взору откроется то, о чём известно лишь нашему народу." }, { 26.82, "Найди шаманов из племени Дыбогривов в их лощине на востоке и возьми у них мазь, которую они используют в своих ритуалах." }, { 36.77, "Возвращайся ко мне, когда соберёшь достаточно мази для изготовления зелья." } } }, t = { d = 36.3, g = 1, v = "tauren-female", n = { m = 328, f = 330 }, c = { m = { { 0.00, "Отлично. Ты вернулся – а значит, готов к следующему шагу." }, { 5.32, "Стихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твоё терпение." }, { 12.57, "Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя её законам, ты приумножишь мудрость." }, { 23.08, "Никогда не забывай тайны, которые она разделит с тобой." }, { 27.88, "Теперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути." } }, f = { { 0.00, "Отлично. Ты вернулась – а значит, готова к следующему шагу." }, { 5.51, "Стихия земли – это основа всех вещей. Это твоя сила, твоя выносливость и твоё терпение." }, { 12.76, "Мать-Земля защитит тебя, но к ней должно относиться с уважением. Она – основа жизни, и следуя её законам, ты приумножишь мудрость." }, { 23.27, "Никогда не забывай тайны, которые она разделит с тобой." }, { 28.07, "Теперь я приготовлю для тебя сапту земли, который откроет перед тобой новые пути." } } } } },
    [1520] = { d = 37.1, v = "tauren-female", n = { x = 366 }, c = { x = { { 0.00, "Сапта – это напиток, призванный объединить твой дух со стихиями." }, { 5.24, "Сотворённое с помощью магии зелье позволит тем, чьё сознание открыто, видить стихии так, как их никто не видел ранее." }, { 14.73, "Твой дух будет навеки связан со стихией, для которой был создан сапта – и лишь немногим из нашего племени известен секрет его изготовления." }, { 26.02, "Сапта должна быть выпита в только в священном месте и более нигде." }, { 31.80, "Найди шаманское святилище к востоку отсюда и выпей сапту там." } } }, t = { d = 60.4, g = 1, v = "elemental-earth", n = { m = 405, f = 406 }, c = { m = { { 0.00, "Ах... путник... Земля ликует от того, что ты пришёл сюда." }, { 6.68, "Теперь ты связан с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности." }, { 25.23, "Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий." }, { 39.11, "Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий." }, { 47.88, "Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." } }, f = { { 0.00, "Ах... путница... Земля ликует от того, что ты пришла сюда." }, { 6.52, "Теперь ты связана с ней духом и телом, и продолжишь свой путь, зная, что горы суть твоя сила, равнины суть твоё терпение, и весь мир – основа твоей сущности." }, { 25.24, "Для прохождения этого обряда довольно было смиренно предстать перед землёй. Но другие обряды потребуют более активных действий." }, { 40.25, "Они могут оказаться жестоки и непредсказуемы – но такова уж природа стихий." }, { 49.01, "Тебе следует научиться управляться с вечной борьбой противоположностей, лежащей в их основе." } } } } },
    [1521] = { d = 54.7, g = 1, v = "elemental-earth", n = { m = 369, f = 370 }, c = { m = { { 0.00, "Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой." }, { 13.05, "Она создаст для тебя тотэм, и этот камень станет его сердцем." }, { 20.27, "Тебе может показаться, что он мал, но со временем ты поймёшь, что размер не имеет значения." }, { 29.74, "Иногда малое оказывается долговечнее большого." }, { 35.32, "Будь терпелив. Оставайся сильным. И ищи мудрости. Так угодно земле." }, { 43.25, "В конце концов ты станешь единым целым с землёй – чти же её, и она будет чтить тебя." } }, f = { { 0.00, "Возьми этот грубый кварц и отнеси его провидице Воронье Перо в доказательство того, что мы говорили с тобой." }, { 13.05, "Она создаст для тебя тотэм, и этот камень станет его сердцем." }, { 20.27, "Тебе может показаться, что он мал, но со временем ты поймёшь, что размер не имеет значения." }, { 29.74, "Иногда малое оказывается долговечнее большого." }, { 35.32, "Будь терпелива. Оставайся сильной. И ищи мудрости. Так угодно земле." }, { 43.51, "В конце концов ты станешь единым целым с землёй – чти же её, и она будет чтить тебя." } } }, t = { d = 29.2, g = 1, v = "tauren-female", n = { m = 285, f = 286 }, c = { m = { { 0.00, "Прекрасно!" }, { 1.32, "Тотэм, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами." }, { 8.19, "Его можно использовать для сосредоточения заклинаний Земли." }, { 13.15, "Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно." }, { 20.24, "Наставники в Калимдоре скажут тебе, когда ты будешь готов к новым знаниям. А пока возьми этот тотэм Земли..." } }, f = { { 0.00, "Прекрасно!" }, { 1.32, "Тотэм, который я сделаю для тебя – не просто символ. Он обладает тайными свойствами." }, { 8.19, "Его можно использовать для сосредоточения заклинаний Земли." }, { 13.15, "Чем больше мудрости ты обретёшь, тем больше способностей земли станет тебе доступно." }, {