    [1522] = { d = 25.7, g = 1, v = "troll-male#77", n = { m = 266, f = 267 }, c = { m = { { 0.00, "Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Крэналом." }, { 7.52, "Крэнал живёт к северу от Перекрёстка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, готов к этому." }, { 17.37, "Найти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесёт." } }, f = { { 0.00, "Огонь с тобой, дружище! Шо, я смотрю, пути Земли тебе уже знакомы? Значит, пора тебе перетереть с Крэналом." }, { 7.52, "Крэнал живёт к северу от Перекрёстка, в Степях. По части стихий он очень крут, и путям Огня тебя научит на раз... если ты, конечно, готова к этому." }, { 18.51, "Найти его – как нефиг делать, только смотри, слишком далеко не ходи, а не то к эльфам занесёт." } } }, t = { d = 28.5, g = 1, v = "orc-male", n = { m = 296, f = 297 }, c = { m = { { 0.00, "Что, тебя Сеарн прислал, да?" }, { 2.55, "Ну, на Сеарна положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня." }, { 10.25, "Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг..." }, { 19.33, "Однако, имей терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." } }, f = { { 0.00, "Что, тебя Сеарн прислал, да?" }, { 2.55, "Ну, на Сеарна положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня." }, { 9.85, "Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг..." }, { 18.93, "Однако, имей терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." } } } } },
    [1523] = { d = 33.5, g = 1, v = "tauren-male#68", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание!" }, { 6.18, "Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу." }, { 14.84, "Тебе следует овладеть стихией огня – если только ты готов платить за это." }, { 20.80, "Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка." }, { 27.19, "Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" } }, f = { { 0.00, "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание!" }, { 6.18, "Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу." }, { 14.84, "Тебе следует овладеть стихией огня – если только ты готова платить за это." }, { 20.88, "Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка." }, { 27.28, "Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" } } }, t = { d = 28.0, g = 1, v = "orc-male", n = { m = 280, f = 283 }, c = { m = { { 0.00, "Хм, тебя Ксанис прислал ко мне?" }, { 2.43, "Ну что ж, Ксанису всегда можно доверять. Должно быть ты уже готов принять участие в следующей сапе, сапте-огня." }, { 11.29, "Вижу в твоих глазах, огненное желание. Ты попробовал власть на вкус, и теперь, ты готов к большему. Терпение." }, { 18.93, "Помни чему учила тебя Земля. Мощь и разрушение, ты всегда должен знать, когда нужно остановить руку." } }, f = { { 0.00, "Хм, тебя Ксанис прислал ко мне?" }, { 2.43, "Ну что ж, Ксанису всегда можно доверять. Должно быть ты уже готова принять участие в следующей сапе, сапте-огня." }, { 10.69, "Вижу в твоих глазах, огненное желание. Ты попробовала власть на вкус, и теперь, ты готова к большему. Терпение." }, { 18.48, "Помни чему учила тебя Земля. Мощь и разрушение, ты всегда должна знать, когда нужно остановить руку." } } } } },
    [1524] = { d = 36.6, g = 1, v = "orc-male", n = { m = 403, f = 404 }, c = { m = { { 0.00, "У тебя достаточно сил, чтобы управлять тотэмом огня, но это ещё не значит, что ты готов к этому." }, { 7.02, "Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране." }, { 15.72, "Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени." }, { 24.07, "Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь." }, { 28.92, "Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотэм огня." } }, f = { { 0.00, "У тебя достаточно сил, чтобы управлять тотэмом огня, но это ещё не значит, что ты готова к этому." }, { 7.23, "Вдоль реки Строптивой в Дуротаре, у Великого моря, лежит тайная тропа, ведущая к одному из высочайших пиков в нашей стране." }, { 15.93, "Отыщи путь на вершину, и найдёшь одно из наших святилищ, которое оберегает Телф Джулам – святилище Спящего Пламени." }, { 24.29, "Отнеси ему этот факел – это знак, что ты пытаешься приручить огонь." }, { 29.14, "Верни мне этот факел зажжённым от жаровни в святилище, и я позабочусь, чтобы тебе был дан тотэм огня." } } }, t = { d = 29.2, v = "troll-male#77", n = { x = 309 }, c = { x = { { 0.00, "А, я ошибся! Прошу прощения. Я не знал, что у тебя с собой этот факел. Очень рад познакомиться." }, { 7.88, "Сюда забредает немало путешественников, которые ищут клады или охотятся на невиданных зверей, и мне приходится прогонять их из этого святилища, которое кажется пустым." }, { 19.20, "Но мы-то с тобой знаем истину, не так ли?" }, { 22.41, "Это святилище скрывает от несведущих великую тайну. Для нас эта тайна священна!" } } } } },
    [1525] = { d = 40.0, v = "troll-male#77", n = { x = 460 }, c = { x = { { 0.00, "Но ты ведь здесь не затем, чтобы выслушивать лекции по истории, верно? Тебе нужно Неугасимое Пламя и тотэм Огня!" }, { 7.88, "Первый шаг – это создать сапту, чтобы связать тебя со стихией огня." }, { 12.75, "Я могу изготовить тебе сапту, но для этого нужны две вещи." }, { 16.81, "Во-первых – огненная смола, распространённое вещество, которое обычно носят при себе заклинатели Иглогривых в восточных Степях." }, { 25.78, "А вот второй компонент добыть куда сложнее: это мешочек с реактивами, какие носят чернокнижники из клана Пылающего Клинка." }, { 34.11, "Их можно отыскать в пещере над ущельями к северо-востоку от Колючего Холма." } } }, t = { d = 32.5, v = "troll-male#77", n = { x = 368 }, c = { x = { { 0.00, "Это как раз то, что надо." }, { 2.44, "Огонь – это не просто хаос и разрушение. Запомни это хорошенько! Огонь – это ещё и жизнь, и творение!" }, { 9.83, "Всё в мире взаимосвязано подобным же образом." }, { 12.97, "Противоборствующие силы противостоят друг другу, но при этом не могут существовать поодиночке." }, { 19.35, "Они взаимно уничтожаются, но придают друг другу смысл. Помни об этом!" }, { 24.42, "Одновременное использование различных видов магии говорит не только о подлинном искусстве, но и о большой мудрости." } } } } },
    [1526] = { d = 31.4, g = 1, v = "troll-male#77", n = { m = 364, f = 365 }, c = { m = { { 0.00, "Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени!" }, { 5.60, "Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление." }, { 11.34, "Оно не нападёт на тебя, пока ты не будешь готов к этому, однако оно поймёт, что ты его видишь." }, { 17.99, "Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт!" }, { 25.12, "Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел." } }, f = { { 0.00, "Сапта огня готова. Пришло тебе время встретиться лицом к лицу со стихией пламени!" }, { 5.60, "Выпей сапту в святилище и отправляйся на вершину горы, чтобы увидеть там проявление." }, { 11.34, "Оно не нападёт на тебя, пока ты не будешь готова к этому, однако оно поймёт, что ты его видишь." }, { 18.11, "Постарайся поразить его как можно быстрее, ибо чем дольше ты будешь тянуть, тем больше мощи оно наберёт!" }, { 25.25, "Когда одолеешь его, положи оставшиеся от него тлеющие уголья в жаровню и зажги факел." } } }, t = { d = 15.9, v = "troll-male#77", n = { x = 174 }, c = { x = { { 0.00, "Когда вы бросаете уголёк в жаровню, в чаше вспыхивает жаркое белое пламя." }, { 5.53, "Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьётся пламя." }, { 11.83, "Вы опускаете факел в чашу, и он мгновенно вспыхивает." } } } } },
    [1527] = { d = 20.3, v = "human-male#114", n = { x = 211 }, c = { x = { { 0.00, "Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Дуротар. Вас охватывает восторг." }, { 9.40, "Пламя факела рвётся и трепещет на ветру." }, { 12.82, "И вот вы начинаете спускаться обратно по тропе, ведущей в Степи, возвращаясь к Краналу Фиссу." } } }, t = { d = 17.9, v = "orc-male", n = { x = 200 }, c = { x = { { 0.00, "Твой дух пылает ярче любого факела! Тебе есть чем гордиться." }, { 4.74, "Не сходи с избранного пути, и стихии будут повиноваться тебе, а наши собратья станут искать у тебя советов и наставлений." }, { 13.14, "Позволь мне первым поздравить тебя и вручить тебе новый тотэм..." } } } } },
    [1528] = { d = 27.6, g = 1, v = "troll-male#77", n = { m = 301, f = 304 }, c = { m = { { 0.00, "Вода – твоё будущее, дружище. Вижу, ты уже покорил огонь и, кажись, готов поговорить с Ислен." }, { 6.50, "Ислен живёт на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу!" }, { 14.73, "Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готов." }, { 20.52, "Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном." } }, f = { { 0.00, "Вода – твоё будущее, дружище. Вижу, ты уже покорила огонь и, кажись, готова поговорить с Ислен." }, { 6.69, "Ислен живёт на побережье ентих Степей. Топай на юг, вдоль реки Строптивая, не промахнёшься – ищи нехилую акулу!" }, { 14.93, "Ислен – великая повелительница духов, и она научит тебя сути воды... если ты готова." }, { 20.87, "Ты её запростяк найдёшь, только на юг слишком далеко не заходи: Ислен живёт рядом с Кабестаном." } } }, t = { d = 18.6, v = "tauren-female#71", n = { x = 174 }, c = { x = { { 0.00, "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды." }, { 10.24, "Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." } } } } },
    [1529] = { d = 24.0, g = 1, v = "tauren-male#68", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Много воды утекло со времени последнего испытания. Ты проявил немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды." }, { 12.17, "Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." } }, f = { { 0.00, "Много воды утекло со времени последнего испытания. Ты проявила немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды." }, { 12.07, "Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." } } }, t = { d = 18.5, v = "tauren-female#71", n = { x = 174 }, c = { x = { { 0.00, "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды." }, { 10.18, "Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." } } } } },
    [1530] = { d = 31.4, g = 1, v = "tauren-female#71", n = { m = 304, f = 304 }, c = { m = { { 0.00, "Первым делом ты должен понять, что вода означает возрождение." }, { 5.08, "Вода течёт, разрушает и очищает всё сущее. Ты увидишь, что вода – великий целитель, но только чистая вода." }, { 13.74, "Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания." }, { 22.00, "Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На её дом постоянно нападают иглогривы." } }, f = { { 0.00, "Первым делом ты должна понять, что вода означает возрождение." }, { 5.26, "Вода течёт, разрушает и очищает всё сущее. Ты увидишь, что вода – великий целитель, но только чистая вода." }, { 13.91, "Познав, что осквернённая вода разрушает всё кругом, ты поймёшь и то, как вода важна для мироздания." }, { 22.18, "Если же ты хочешь получить сапту воды, отыщи Брин в южной части Степей. На её дом постоянно нападают иглогривы." } } }, t = { d = 31.7, g = 1, v = "orc-female", n = { x = 329 }, c = { m = { { 0.00, "Да?" }, { 1.34, "М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты?" }, { 12.62, "У всех нас свои причины действовать так или иначе." }, { 16.40, "У меня другой вопрос – что заставило простого героя отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?" }, { 27.22, "Готова поспорить, что мы оба знаем ответ на этот вопрос." } }, f = { { 0.00, "Да?" }, { 1.20, "М-м-м, у меня такое чувство, что я заранее знаю твой вопрос: кому взбредёт в голову жить в сердце Степей в ожидании нападения иглогривов и без защиты?" }, { 12.48, "У всех нас свои причины действовать так или иначе." }, { 16.26, "У меня другой вопрос – что заставило простого героини отправиться в сердце Степей разговаривать с женщиной, которую не заботит собственное благополучие?" }, { 27.27, "Готова поспорить, что мы оба знаем ответ на этот вопрос." } } } } },
    [1531] = { d = 31.2, g = 1, v = "troll-male#77", n = { m = 319, f = 320 }, c = { m = { { 0.00, "Ты делаешь успехи, дружище. Я верю, что ты достоин тотэма воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл." }, { 9.82, "Отнесись к ней с уважением, и она расскажет, как получить тотэм." }, { 14.41, "Иди на юг, через Степи, а когда попадёшь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха!" }, { 25.49, "Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится." } }, f = { { 0.00, "Ты делаешь успехи, дружище. Я верю, что ты достойна тотэма воздуха, но сначала надо отыскать Пратту Заклинательницу Туч в Тысяче Игл." }, { 9.89, "Отнесись к ней с уважением, и она расскажет, как получить тотэм." }, { 14.49, "Иди на юг, через Степи, а когда попадёшь в Тысячу Игл, сверни на восток. Пратт прячется в пещере вместе со своим парнем. Ха-ха!" }, { 25.57, "Только не рассказывай ей, что я проболтался тебе об этом, а то она рассердится." } } }, t = { d = 15.4, g = 1, v = "tauren-female#71", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм." }, { 10.88, "Возвращайся, когда будешь готов продолжить обучение." } }, f = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм." }, { 10.88, "Возвращайся, когда будешь готова продолжить обучение." } } } } },
    [1532] = { d = 34.2, g = 1, v = "tauren-male#68", n = { m = 348, f = 347 }, c = { m = { { 0.00, "Все ветра Калимдора спешат к тебе навстречу, и скоро ты займёшь достойное место среди наших самых выдающихся братьев." }, { 9.18, "Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждёт великое будущее." }, { 15.56, "Дух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своём пути." }, { 23.60, "Отправляйся на самый юг Степей, в Тысячу Игл." }, { 27.49, "Там, на востоке, ты найдёшь Пратту Заклинательницу Туч, и она продолжит твоё обучение." } }, f = { { 0.00, "Все ветра Калимдора спешат к тебе навстречу, и скоро ты займёшь достойное место среди наших самых выдающихся сестёр." }, { 8.98, "Я чрезвычайно горжусь твоими успехами и вижу, что тебя ждёт великое будущее." }, { 15.36, "Дух воздуха покорить нелегко, но я верю, что ты сумеешь преодолеть любые препятствия на своём пути." }, { 23.41, "Отправляйся на самый юг Степей, в Тысячу Игл." }, { 27.29, "Там, на востоке, ты найдёшь Пратту Заклинательницу Туч, и она продолжит твоё обучение." } } }, t = { d = 16.7, g = 1, v = "tauren-female#71", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм." }, { 10.10, "Возвращайся, когда будешь готов продолжить обучение." } }, f = { { 0.00, "Сейчас я дам тебе то, что потребуется для концентрации твоих заклинаний и призывания духов воздуха. Возьми этот тотэм." }, { 12.10, "Возвращайся, когда будешь готова продолжить обучение." } } } } },
    [1534] = { d = 30.4, v = "orc-female", n = { x = 347 }, c = { x = { { 0.00, "Возьми этот бурдюк и ступай в густой лес, который ночные эльфы зовут Ясеневым. Он находится далеко на севере от Степей." }, { 8.86, "Добравшись до леса, отправляйся в его западную часть." }, { 12.48, "Возле гряды, отделяющей Когтистые горы от Ясеневого леса, за озером Мистраль, располагается священное место, руины Звёздной Пыли." }, { 21.66, "В центре озера, на островке, есть маленький фонтан. Прежде чем возвращаться к Ислен, принеси мне воду из этого источника." } } }, t = { d = 23.1, v = "orc-female", n = { x = 245 }, c = { x = { { 0.00, "Чудесно. Теперь у меня есть все три пробы воды, и я могу наполнить фиал чистейшей водой, которую только способно найти живое существо." }, { 10.46, "Она понадобится тебе на следующем этапе." }, { 13.63, "Я рада, что среди избравших наш путь есть такие, как ты." }, { 17.60, "Все шаманы гордятся тобой, и я надеюсь вскоре услышать о твоих подвигах." } } } } },
    [1535] = { d = 29.2, v = "orc-female", n = { x = 325 }, c = { x = { { 0.00, "Чтобы обрести понимание и получить от меня сапту, тебе предстоит отыскать чистейшую воду." }, { 6.39, "Принося мне образцы, обращай внимание на окружающий мир – какие существа зависят от этой воды и охраняют её." }, { 13.94, "Как она влияет на леса и пустыни." }, { 16.66, "Ты увидишь, как влага, дающая жизнь сущему, вынуждает различных существ отнимать эту жизнь у других." }, { 24.16, "Начнём с малого: ниже моего домика есть пруд с драгоценной влагой." } } }, t = { d = 25.9, v = "orc-female", n = { x = 292 }, c = { x = { { 0.00, "Я предполагала, что если ты возьмёшься набирать воду, кровопролития не избежать." }, { 5.57, "Жаль, что иглогривы не понимают, что все живые существа связаны между собой, а жадность лишь усиливает боль и страдания их собственного народа." }, { 15.66, "О, сколь многого они достигли бы, забыв о спорах и объединившись." }, { 20.61, "Да, для них это плохо, но для других обитателей Степей – скорее хорошо." } } } } },
    [1536] = { d = 34.8, v = "orc-female", n = { x = 396 }, c = { x = { { 0.00, "Давным-давно мы с несколькими спутниками отправились в предгорья Хилсбрада." }, { 5.36, "Нам пришлось отбиваться от навязчивых людей, поселившихся в тех краях, и в итоге мы оказались в городке, захваченном Отрёкшимися, – Мельнице Таррен." }, { 16.03, "И удивительное дело – в центре города обнаружился маленький источник свежей родниковой воды." }, { 22.51, "Не думаю, что поражённые чумой жители города осознают его ценность – это малый луч света в царстве тьмы." }, { 30.30, "Набери воду из этого источника в этот бурдюк и принеси мне." } } }, t = { d = 15.3, v = "orc-female", n = { x = 150 }, c = { x = { { 0.00, "Хорошо. Ты изо всех сил стараешься выполнить порученные тебе задания и добиваешься успеха." }, { 8.58, "Ещё одна проба воды, и я смогу создать реактив, необходимый для сапты. Ислен будет довольна." } } } } },
    [1578] = { d = 35.6, v = "dwarf-male", n = { x = 400 }, c = { x = { { 0.00, "Горная пехота озера Лок Модан без передышки сражается с троггами!" }, { 4.84, "Им нужен постоянный подвоз новых доспехов и оружия, иначе с троггами не справиться." }, { 10.83, "Мой коллега Торвальд как раз и поехал туда – за тем чтобы у солдат было доброе снаряжение." }, { 17.06, "Так что если бы вы могли изготовить несколько медных топоров и плетёных поясов и доставить их Торвальду, он был бы очень вам благодарен." }, { 26.60, "Он даже может поделиться с вами своими знаниями." }, { 30.29, "Торвальда вы найдёте в южной сторожевой башне озера Лок Модан." } } }, t = { d = 13.1, g = 1, v = "dwarf-male", n = { m = 146, f = 146 }, c = { m = { { 0.00, "Ох, прости! Я и не понял, что ты пришёл помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут!" }, { 8.52, "Вот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся." } }, f = { { 0.00, "Ох, прости! Я и не понял, что ты пришла помочь в деле вооружения наших войск. Изготовленные тобой вещи очень нам помогут!" }, { 8.57, "Вот чертежи кое-каких доспехов. Надеюсь, они тебе пригодятся." } } } } },
    [1579] = { d = 28.2, v = "goblin-male", n = { x = 315 }, c = { x = { { 0.00, "Я прибыл в Аубердин в поисках тишины и покоя." }, { 3.25, "Я хочу заниматься своими изобретениями там, где царит покой, потому что после ночных попоек мне совсем не нравится гомон Стальгорна!" }, { 12.86, "Так что я отправился на корабле в Аубердин... и по дороге слегка перебрал. Я уронил за борт мой ящик с суперразъемами!" }, { 21.29, "Точно не знаю, где я их потерял, но если ты попытаешься выловить их в океане, может, тебе повезёт..." } } }, t = { d = 7.1, g = 1, v = "goblin-male", n = { m = 72, f = 72 }, c = { m = { { 0.00, "Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самый везучий герой на Калимдоре!" } }, f = { { 0.00, "Ах, не могу поверить, что тебе удалось их найти! Должно быть, ты самая везучая героиня на Калимдоре!" } } } } },
    [1580] = { d = 36.5, v = "goblin-male", n = { x = 415 }, c = { x = { { 0.00, "Мы знаем, что тебе везёт, но... насколько сильно везёт?" }, { 3.98, "Однажды ночью я бродил по дорогам Тёмного Берега." }, { 7.51, "Я искал речку или озеро, пригодные для испытания моей самодвижущейся и взрывающейся подсадной утки и, думаю, был слегка пьян..." }, { 16.21, "поскольку потерял сознание и пришёл в себя в Аубердине спустя несколько часов." }, { 21.75, "Мои волосы были опалены, а сумка с электропеллерами исчезла! Должно быть, я уронил её в воду!" }, { 28.53, "Мне нужны эти электропеллеры! Может быть, тебе удастся выловить их из какого-нибудь водоёма на Тёмном Берегу?.." } } }, t = { d = 13.1, g = 1, v = "goblin-male", n = { m = 136, f = 138 }, c = { m = { { 0.00, "Глазам не верю! Ты их нашёл! Ты лучший рыбак на моей памяти!" }, { 4.59, "Спасибо тебе. И вот, возьми это. Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении." } }, f = { { 0.00, "Глазам не верю! Ты их нашла! Ты лучшая рыбачка на моей памяти!" }, { 4.85, "Спасибо тебе. И вот, возьми это. Хотя ты, наверное, в этом и не нуждаешься, оно послужит тебе подспорьем при ужении." } } } } },
    [1581] = { d = 23.2, v = "nightelf-female#51", n = { x = 270 }, c = { x = { { 0.00, "Наша лавочка трав и алхимических снадобий процветает, но мой муж проводит столько времени за изготовлением эликсиров, что почти забыл про личную жизнь! Ты нам не поможешь?" }, { 12.15, "Если ты привезёшь мне партию уже готовых эликсиров, я охотно куплю их у тебя." }, { 17.59, "У меня есть некоторые редкие травы, которые могут оказаться полезными для тебя." } } }, t = { d = 11.9, g = 1, v = "nightelf-female#51", n = { m = 134, f = 135 }, c = { m = { { 0.00, "Прекрасные снадобья! Ты проявил исключительную щепетильность, что очень важно для алхимика!" }, { 6.65, "Вот твои травы, я только-только их собрала. Пусть они тебе пригодятся!" } }, f = { { 0.00, "Прекрасные снадобья! Ты проявила исключительную щепетильность, что очень важно для алхимика!" }, { 6.61, "Вот твои травы, я только-только их собрала. Пусть они тебе пригодятся!" } } } } },
    [1582] = { d = 22.5, v = "nightelf-female#53", n = { x = 262 }, c = { x = { { 0.00, "У нас, жителей Дарнасса, в особенности у ремесленников, работы невпроворот." }, { 5.53, "Молодым искателям приключений неймётся испытать себя во всякой глухомани, так что нам постоянно нужен подвоз материалов." }, { 14.05, "Если ты поможешь мне выполнить заказ на кожаные изделия, я, может, научу тебя более совершенной технике работы с кожей." } } }, t = { d = 12.0, v = "nightelf-female#53", n = { x = 132 }, c = { x = { { 0.00, "Да, славные изделия. У тебя искусные руки и острый глаз. Из тебя может получиться неплохой кожевник." }, { 7.22, "Слушай. Давай-ка я покажу тебе выкройку жилета Лунного сияния." } } } } },
    [1598] = { d = 38.9, g = 1, v = "human-female#47", n = { m = 439, f = 441 }, c = { m = { { 0.00, "Ах, это ты! Тебя зовут путник, верно?" }, { 2.96, "Надеюсь, ты точно уверен, что желаешь стать чернокнижником, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего." }, { 12.20, "Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно силён." }, { 17.55, "В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует?" }, { 25.57, "А потому, что он стянул из аббатства кое-какие важные книги." }, { 29.68, "Одну из них я сама хотела бы иметь. Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках. Принеси её мне." } }, f = { { 0.00, "Ах, это ты! Тебя зовут путница, верно?" }, { 2.92, "Надеюсь, ты точно уверена, что желаешь стать чернокнижницей, поскольку если ты не умеешь постоять за себя, среди нас тебе делать нечего." }, { 12.40, "Я буду тебя обучать, но сначала я должна убедиться, что ты достаточно сильна." }, { 18.33, "В здешнем аббатстве обучался один послушник, который сбежал и вступил в Братство Справедливости. Почему меня это волнует?" }, { 26.35, "А потому, что он стянул из аббатства кое-какие важные книги." }, { 30.46, "Одну из них я сама хотела бы иметь. Братство прячет эту книгу – \"Силы Бездны\" – в своём шатре на виноградниках. Принеси её мне." } } }, t = { d = 20.2, g = 1, v = "human-female#47", n = { m = 242, f = 243 }, c = { m = { { 0.00, "Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг." }, { 11.19, "Ладно, ты отлично потрудился, и я уверена, что ты сумеешь справиться со своим собственным бесом." }, { 17.65, "Пора показать тебе, как его вызывать!" } }, f = { { 0.00, "Замечательно... Мне никогда не удавалось добраться до этой книги, его держали в охраняемом крыле библиотеки, и было бы подозрительно, если бы я стала рыскать вокруг." }, { 11.19, "Ладно, ты отлично потрудилась, и я уверена, что ты сумеешь справиться со своим собственным бесом." }, { 17.61, "Пора показать тебе, как его вызывать!" } } } } },
    [1599] = { d = 43.6, v = "gnome-male", n = { x = 506 }, c = { x = { { 0.00, "Тут все шепчутся о каком-то новом чернокнижнике; наверное, это ты и есть." }, { 5.07, "Должно быть, ты вызываешь кое у кого сильную симпатию, раз меня попросили отвлечься от моих изысканий и посвятить некоторое время занятиям с тобой." }, { 15.24, "Не беспокойся: я не ставлю это тебе в вину." }, { 18.64, "Что ж, самое простое из заклинаний призыва позволяет вызвать беса." }, { 23.26, "Однако, прежде чем я преподам тебе этот урок, мне хотелось бы получить доказательства того, что у тебя достаточно как физической, так и магической силы..." }, { 33.91, "Принеси мне три оберега из перьев." }, { 36.38, "Ты получишь их, если расправишься с новобранцами племени Мерзлогривов в пещере, что к юго-западу отсюда." } } }, t = { d = 40.7, v = "gnome-male", n = { x = 460 }, c = { x = { { 0.00, "Прекрасно, прекрасно! В самом деле, неплохая работа. Возможно, те, кто тебя рекомендовал, и не ошиблись..." }, { 7.34, "Впрочем, это не мне решать. Поживём – увидим." }, { 10.70, "Будем надеяться, что первый же вызванный бес не вырвет тебе сердце и не сожрёт внутренности – думаю, подобное могло бы серьёзно повредить твоей карьере." }, { 21.08, "Пока у меня есть основания полагать, что в качестве чернокнижника ты сумеешь прожить хотя бы несколько месяцев." }, { 29.07, "Кстати, хотел тебе дать тебе совет по поводу бесов." }, { 33.17, "Запомни, размер – ещё не главное: даже самый глупый таурен знает, что бесы наделены весьма сильной магией." } } } } },
    [1618] = { d = 20.8, v = "dwarf-male", n = { x = 239 }, c = { x = { { 0.00, "Не только мы, дворфы, сражаемся денно и нощно – люди, наши союзники, тоже не прохлаждаются!" }, { 6.44, "На Красногорье время от времени устраивают налёты орки Чёрной Горы, а снаряжения туда всегда мало поставляется." }, { 14.18, "Если ты им поможешь, то местный кузнец Вернер Осгуд наверняка научит тебя паре хитростей." } } }, t = { d = 23.0, g = 1, v = "human-male#50", n = { x = 280 }, c = { m = { { 0.00, "Спасибо. Это чрезвычайно мне поможет." }, { 2.66, "Орки Чёрной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск." }, { 16.08, "То, что ты принёс, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить..." } }, f = { { 0.00, "Спасибо. Это чрезвычайно мне поможет." }, { 2.66, "Орки Чёрной Горы нападают со стороны крепости Каменной Стражи, а гноллы Красногорья шныряют в северных предгорьях, и мне постоянно приходится чинить доспехи и делать новое оружие для наших войск." }, { 16.08, "То, что ты принесла, даст мне хоть небольшую передышку. И у меня будет время кое-чему тебя научить..." } } } } },
    [1638] = { d = 19.0, v = "human-female#47", n = { x = 226 }, c = { x = { { 0.00, "Ты в самом деле неплохой воин, но лет тебе мало, и ещё многому придётся научиться." }, { 5.84, "Поговори с Гарри Берлгардом – обычно он сидит в \"Свинье и Свистке\", в Старом городе Штормграда." }, { 11.79, "Гарри опытный боец и неплохой учитель. Он покажет тебе несколько приёмов, глядишь, и подольше проживёшь." } } }, t = { d = 11.0, g = 1, v = "human-male", n = { m = 121, f = 121 }, c = { m = { { 0.00, "О-хо! Выпей со мной. С первого взгляда ты кажешься крепким, посмотрим, что с тобой сделает несколько кружек крепкого пива!!! Или... А, да ты поучиться хочешь?" } }, f = { { 0.00, "О-хо! Выпей со мной. С первого взгляда ты кажешься крепкой, посмотрим, что с тобой сделает несколько кружек крепкого пива!!! Или... А, да ты поучиться хочешь?" } } } } },
    [1639] = { d = 17.2, g = 1, v = "human-male", n = { m = 181, f = 182 }, c = { m = { { 0.00, "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься." }, { 6.11, "Видишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку." }, { 11.76, "Ха, если ты знаком с ним, то догадаешься, что так просто он её не отдаст." } }, f = { { 0.00, "Да, я могу заняться твоим обучением, но сначала хочу взглянуть, на что ты годишься." }, { 6.11, "Видишь, в конце бара стоит выпивка? Бартлби тоже видишь? Добудь эту кружку." }, { 11.76, "Ха, если ты знакома с ним, то догадаешься, что так просто он её не отдаст." } } }, t = { d = 7.0, g = 1, v = "human-male#50", n = { m = 79, f = 79 }, c = { m = { { 0.00, "Эй, красавчик! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь..." } }, f = { { 0.00, "Эй, красавица! Что таким как ты делать в \"Свинье и свистке\"? Осторожнее, неровен час, ноготь сломаешь..." } } } } },
    [1640] = { d = 5.7, g = 1, v = "human-male#50", n = { m = 58, f = 59 }, c = { m = { { 0.00, "Что ты хочешь? Да ты спятил!" }, { 2.52, "Эту кружку ты получишь только через мой труп..." } }, f = { { 0.00, "Что ты хочешь? Да ты спятила!" }, { 2.38, "Эту кружку ты получишь только через мой труп..." } } }, t = { d = 3.3, v = "human-male#50", n = { x = 35 }, c = { x = { { 0.00, "А ты крепче, чем кажешься с первого взгляда." } } } } },
    [1642] = { d = 41.3, v = "human-male#114", n = { x = 425 }, c = { x = { { 0.00, "Во всех своих деяниях паладин должен быть достоин того Света, которому мы служим и который дарует нам силу." }, { 8.49, "Для таких, как мы, стремление к божественности не означает желания стать богами: мы лишь стремимся творить добро." }, { 17.68, "Ныне наступили тяжёлые времена: мы избраны для того, чтобы сражаться со злом и повергнуть его." }, { 25.00, "Однако помни: не борьба со злом отличает нас от прочих жителей Азерота." }, { 30.68, "Сострадание, терпение, отвага и помощь ближним – для паладина всё это значит не меньше, чем искусство воина. Никогда не забывай об этом!" } } }, t = { d = 35.6, v = "human-male", n = { x = 411 }, c = { x = { { 0.00, "И снова рад приветствовать тебя. Как идёт изучение Фолианта Божественности?" }, { 5.59, "Помни: тебе предстоит пройти испытание. Каждого из нас ждёт множество свершений – как в городе, так и в иных землях." }, { 13.54, "Всегда есть люди, нуждающиеся в помощи, сострадании и понимании, всегда есть враждебные твари, которых необходимо уничтожать во благо людей." }, { 23.41, "Докажи, что ты можешь помогать своим ближним – в особенности тем, кому меньше повезло в жизни." }, { 29.81, "Тем самым ты докажешь, что твои помыслы чисты и что ты воистину служишь Свету." } } } } },
    [1643] = { d = 30.1, v = "human-male", n = { x = 334 }, c = { x = { { 0.00, "Итак, твоя задача – найти в Штормграде того, кто нуждается в помощи. Того, кто чист сердцем и помыслами." }, { 7.03, "Возможно, это тот, кто сам помогает другим. Возможно – тот, кто нуждается в наставнике." }, { 13.00, "Как бы то ни было, намерения того, кого ты ищешь, будут благородны, и он во всём будет полагаться на тебя." }, { 20.71, "Ты возвратишься ко мне, когда исполнишь это задание, и мы поговорим о твоём пути – а равно и о том, что значит быть паладином Света." } } }, t = { d = 30.9, g = 1, v = "human-female", n = { m = 341, f = 341 }, c = { m = { { 0.00, "О, привет, дорогой. Что, всё ищешь приключений? Я так рада, что у тебя всё в порядке!" }, { 6.04, "Я? А что я? Ну, с учётом обстоятельств, у меня тоже дела идут неплохо..." }, { 11.71, "Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать?" }, { 20.72, "Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно." }, { 25.84, "Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей..." } }, f = { { 0.00, "О, привет, милашка. Что, всё ищешь приключений? Я так рада, что у тебя всё в порядке!" }, { 6.00, "Я? А что я? Ну, с учётом обстоятельств, у меня тоже дела идут неплохо..." }, { 11.67, "Правда, торговцев у нас тут прибавилось, а пожертвований на сиротский приют стало меньше: зачем отдавать даром то, что можно продать?" }, { 20.68, "Но ничего, мы справимся. Под \"нами\" я имею в виду себя и своего мужа, конечно." }, { 25.80, "Он сейчас в Стальгорне, пытается заручиться помощью тамошних жителей..." } } } } },
    [1644] = { d = 29.6, v = "human-female", n = { x = 336 }, c = { x = { { 0.00, "Да будут благословенны эти несчастные! Многие из них потеряли родных во время набегов нежити..." }, { 6.55, "Мой муж Джон помогает мне доставать ткань, чтобы я могла шить сироткам одежду, но увы, на это у меня не хватает времени, ведь их нужно сначала накормить и дать им кров." }, { 18.22, "Что? Правда? Ты хочешь мне помочь? Благодарение Вечному Свету! Благодарю тебя!" }, { 23.92, "Если бы у меня был лён на одёжки малышам, их жизнь стала бы хоть немного легче..." } } }, t = { d = 19.8, v = "human-female", n = { x = 227 }, c = { x = { { 0.00, "Ах, благодарю, благодарю тебя!" }, { 2.47, "Детишки так рады будут, да и у меня будет побольше времени на них. Надеюсь, теперь Джон сможет возвратиться поскорее." }, { 10.73, "Прими мою искреннюю признательность. Я всегда верила, что в сердцах людей есть место милосердию. Да пребудет с тобой Извечный Свет." } } } } },
    [1646] = { d = 39.3, v = "human-male#114", n = { x = 407 }, c = { x = { { 0.00, "Паладин во всех делах своих должен быть проявлением Света, который есть источник нашей силы." }, { 7.11, "Стремление к божественности для нас не означает стремления стать божеством – мы стремимся к добру во всех деяниях наших." }, { 16.63, "Хотя в эти тяжёлые времена мы призваны сокрушать зло, тебе всегда следует помнить: лишь помогая другим, ты выделяешься среди других обитателей Азерота." }, { 28.18, "Сочувствие, терпение, отвага – все эти достоинства значат для паладина не меньше, чем сила в сражении. Усвой же это и помни всегда." } } }, t = { d = 28.3, g = 1, v = "dwarf-female#33", n = { m = 322, f = 323 }, c = { m = { { 0.00, "С возвращением. Надеюсь, ты нашёл время на прочтение книги?" }, { 4.51, "Тогда ты должен быть готов к испытанию." }, { 7.27, "Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить." }, { 20.13, "Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света." } }, f = { { 0.00, "С возвращением. Надеюсь, ты нашла время на прочтение книги?" }, { 4.41, "Тогда ты должна быть готова к испытанию." }, { 7.26, "Есть задания, которые необходимо сделать по всему нашему городу и на наших землях; акты сострадания и понимания; люди, которые нуждаются в помощи; существа, которых необходимо убить." }, { 20.12, "Доказав что у тебя есть терпение, особенно в помощи людям, которые менее удачливы, ты докажешь, что ты слуга Света." } } } } },
    [1647] = { d = 34.1, v = "dwarf-female#33", n = { x = 388 }, c = { x = { { 0.00, "Твоя задача, найти в Стальгорне кого-нибудь, кто нуждается в помощи. Того, кто чист душой и помыслами." }, { 7.00, "Может быть, того, кто сам помогает другим. Того, кто нуждается в совете." }, { 11.93, "Кто бы то ни был, у него должны быть благородные стремления и он должен полагаться на твою доброту." }, { 19.13, "Сделай это и по выполнении возвращайся ко мне. Тогда мы ещё поговорим о твоём пути и о том, что значит быть паладином Света." }, { 27.83, "Я останусь в храме до твоего возвращения. Моё наставничество нужно и другим паладинам." } } }, t = { d = 21.8, v = "human-male", n = { x = 232 }, c = { x = { { 0.00, "СИРОТСКИЙ ПРИЮТ ШТОРМ... о, простите, я вовсе не хотел кричать на вас, сударь." }, { 5.67, "Меня зовут Джон Тернер. Как поживаете?" }, { 8.83, "Рад, искренне рад слышать, что у вас всё хорошо." }, { 12.20, "А у меня был трудный день, я тоскую по жене, но такова цена, которую приходится платить, чтобы накормить голодные рты и одеть нагих." } } } } },
    [1648] = { d = 33.0, v = "human-male", n = { x = 380 }, c = { x = { { 0.00, "Мы с женой держим в Штормграде сиротский приют, по большей части для детей, потерявших родителей во время нападений Плети в последние десять лет." }, { 10.08, "Я приезжаю в Стальгорн примерно раз в месяц и занимаюсь сбором средств у здешних горожан, а также прошу помощи у различных организаций." }, { 20.03, "Нынешняя поездка была мучительно медленной и не слишком продуктивной." }, { 25.32, "Если бы мне удалось добыть ещё немного льняной ткани для одежды, я бы смог, наконец, отправить посылку домой." } } }, t = { d = 29.7, v = "human-male", n = { x = 313 }, c = { x = { { 0.00, "Это так прекрасно с вашей стороны. Снова большое вам спасибо." }, { 4.73, "Вы благородный человек, что так помогли мне. Не удивительно, что вы избрали путь Света." }, { 10.80, "Хотел бы я, чтобы был какой-либо способ отплатить вам за всё, что вы сделали... что? Это наименьшее что вы могли сделать?" }, { 19.15, "Видите? Это как раз то, о чём я говорю, вы благородны до самого конца." }, { 24.48, "Берегите себя, и да охранит вас Свет в ваших путешествиях." } } } } },
    [1649] = { d = 36.0, v = "human-male#114", n = { x = 383 }, c = { x = { { 0.00, "Отвага и сопутствующие ей достоинства подобны драгоценным металлам." }, { 5.24, "Нужно беречь их, когда находишь, ибо цена их велика, но также необходимо копить и приумножать их." }, { 12.80, "Тогда они образуют крепчайший сплав, зачастую выдерживающий даже самые сильные удары." }, { 19.65, "Твои сила, вера и храбрость должны быть испытаны." }, { 23.42, "Тебе надлежит научиться хранить веру в любых обстоятельствах и понять, что с помощью сил Света ты сможешь преодолеть те препятствия, которые не по силам другим." } } }, t = { d = 30.2, g = 1, v = "human-male", n = { x = 335 }, c = { m = { { 0.00, "Ты просишь испытать твою отвагу? Прекрасно!" }, { 3.30, "Для тебя в городе и в окрестностях найдётся немало заданий. Нам как раз нужен кто-нибудь с твоими способностями." }, { 11.50, "Это испытание не будет лёгким! Оно, как и многое в нашей профессии, может привести к гибели." }, { 17.89, "Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли герой служить правому делу." }, { 26.65, "Чувствуешь ли ты в себе готовность к испытанию?" } }, f = { { 0.00, "Ты просишь испытать твою отвагу? Прекрасно!" }, { 3.30, "Для тебя в городе и в окрестностях найдётся немало заданий. Нам как раз нужен кто-нибудь с твоими способностями." }, { 11.50, "Это испытание не будет лёгким! Оно, как и многое в нашей профессии, может привести к гибели." }, { 17.89, "Церковь всегда готова поддержать своих слуг, но без жертв невозможно определить, достоин ли героиня служить правому делу." }, { 26.53, "Чувствуешь ли ты в себе готовность к испытанию?" } } } } },
    [1650] = { d = 34.0, v = "human-male", n = { x = 376 }, c = { x = { { 0.00, "Отлично! Отсутствие сомнений говорит о твоей готовности к испытаниям. Да будет так!" }, { 6.27, "В самом конце Долгого Берега стоит небольшой домик с окнами на океан. Там живёт чёта Стивеллов." }, { 14.20, "Джордан – великолепный кузнец, и сейчас он собирается в Стальгорн, чтобы навестить дворфов." }, { 20.46, "Но его жена Дафна остаётся дома одна, без защиты..." }, { 24.30, "Донесения говорят, что Братство Справедливости захватило почти весь край. Дафне может понадобиться защита от злодеев. Отправляйся туда." } } }, t = { d = 30.2, v = "human-female#45", n = { x = 345 }, c = { x = { { 0.00, "Здравствуй. Я полагаю, что со всем этим оружием в руках ты хочешь либо захватить мои земли, либо Церковь наконец-то послала мне защитника на время поездки Джордана." }, { 11.75, "Позволь представиться: я – Дафна Стилвелл. Очень приятно!" }, { 16.00, "Твоё прибытие очень кстати: с восхода солнца я уже прикончила с полдюжины этих мерзавцев." }, { 22.14, "До этого они не особо торопились, но сейчас они наверняка заметили тебя, а значит, будут здесь с минуты на минуту..." } } } } },
    [1651] = { d = 22.8, v = "human-female#45", n = { x = 248 }, c = { x = { { 0.00, "Бьюсь об заклад, они скоро вернутся – так что приготовься." }, { 4.27, "В доме есть пистолет, я возьму его и при необходимости помогу тебе, но лучше рассчитывай только на свои силы." }, { 11.95, "Не знаю, сколько их будет, но уверена, что больше, чем в прошлый раз." }, { 16.95, "Моли Свет благословить тебя, потому что…" }, { 19.92, "Слышишь? Они идут! Укроемся за домом!" } } }, t = { d = 15.5, g = 1, v = "human-female#45", n = { x = 172 }, c = { m = { { 0.00, "Мы победили! Благодарю тебя за помощь. Это было просто великолепно!" }, { 4.67, "Я и не думала, что герой может справиться с таким количеством врагов за раз." }, { 10.21, "Твоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня..." } }, f = { { 0.00, "Мы победили! Благодарю тебя за помощь. Это было просто великолепно!" }, { 4.67, "Я и не думала, что героиня может справиться с таким количеством врагов за раз." }, { 10.31, "Твоя выдающаяся храбрость перед лицом превосходящих сил потрясла меня..." } } } } },
    [1652] = { d = 17.4, v = "human-female#45", n = { x = 194 }, c = { x = { { 0.00, "Прошу, возвращайся к Даториану и передай ему, что теперь со мной всё в порядке – благодаря тебе и Церкви." }, { 7.27, "Он пошлёт весть в Стальгорн, чтобы мой Джордан не волновался за меня." }, { 12.38, "Ох, как я соскучилась по своему мужу! Жду не дождусь его возвращения..." } } }, t = { d = 25.0, v = "human-male", n = { x = 264 }, c = { x = { { 0.00, "Вот мы и встретились снова. Я вижу, что дух твой бодр." }, { 3.76, "Дом четы Стивеллов теперь в безопасности, а из твоего рассказа ясно, что ему теперь ещё долго ничего не будет угрожать. Отлично!" }, { 14.48, "Дафна и Джордан немало помогли Церкви. Отправить тебя на их защиту – весьма скромная ответная услуга." }, { 21.69, "Ты получишь награду за проявленную отвагу." } } } } },
    [1653] = { d = 34.4, v = "human-male", n = { x = 399 }, c = { x = { { 0.00, "Вообще я не сомневаюсь, что Джордан захочет лично отблагодарить тебя, и раз уж мне надо сообщить ему, что его жена в безопасности, то, думаю, лучше всего тебя посланником и отправить." }, { 12.79, "Джордан был паладином Света, до того как приверженность отцовскому ремеслу увлекла его на другой путь, – а потому он хорошо знает наш образ жизни и считается одним из самых надёжных наших приверженцев." }, { 26.74, "Он должен ещё быть в Стальгорне – он любит работать днём за воротами, там где с гор тянет холодным воздухом." } } }, t = { d = 36.8, v = "human-male", n = { x = 412 }, c = { x = { { 0.00, "Добрый день. Вижу, ты служишь Свету?" }, { 2.93, "Что это? Тебя послал Даториан?! Моя жена, как она? Я так и знал – стоит уехать, сразу беды нагрянут. Скажи мне, она..." }, { 10.77, "о, хвала Свету. Я так счастлив, что она в безопасности." }, { 14.60, "Это Братство Справедливости было опасным ещё до нынешних своих налётов, но теперь уж королевские советники не смогут этой угрозы отрицать. Что ещё велел передать Даториан?" }, { 26.79, "Именно ты и назначен был оберегать мою жену? Тогда ещё раз прими мою благодарность." }, { 32.64, "Не могу придумать лучшего испытания доблести, чем это." } } } } },
    [1654] = { d = 36.0, g = 1, v = "human-male", n = { x = 399 }, c = { m = { { 0.00, "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар." }, { 4.79, "Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода." }, { 15.40, "Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света." }, { 23.74, "Но тебе придётся добыть необходимые для ковки предметы." }, { 27.70, "Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне. Что скажешь, герой?" } }, f = { { 0.00, "Я хотел бы отблагодарить тебя, если ты согласишься принять этот дар." }, { 4.79, "Пойми меня правильно, всё будет зависеть от того, насколько ты мне поможешь, но я вижу, что от такого сотрудничества обоим нам выйдет большая выгода." }, { 15.40, "Я скую для тебя оружие, достойное твоего деяния, оружие, что станет символом призвания паладина и пути Света." }, { 23.74, "Но тебе придётся добыть необходимые для ковки предметы." }, { 27.70, "Я уже набросал список, так что остаётся только, чтобы некто отважный и искусный принёс их мне. Что скажешь, героиня?" } } }, t = { d = 24.7, g = 1, v = "human-male", n = { m = 275, f = 276 }, c = { m = { { 0.00, "Великолепно! Ты добыл всё необходимое." }, { 3.07, "Теперь я легко изготовлю для тебя великолепное оружие!" }, { 6.92, "Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое. Спасибо тебе." }, { 14.92, "Как же приятно снова держать в руке молот моих отцов..." }, { 18.68, "и самоцвет Кора – я и не думал, что когда-нибудь увижу его собственными глазами!" } }, f = { { 0.00, "Великолепно! Ты добыла всё необходимое." }, { 3.22, "Теперь я легко изготовлю для тебя великолепное оружие!" }, { 7.07, "Я и так собирался когда-нибудь его выковать, просто не было возможности достать всё необходимое. Спасибо тебе." }, { 15.07, "Как же приятно снова