    [1655] = { d = 31.2, g = 1, v = "dwarf-male", n = { m = 326, f = 328 }, c = { m = { { 0.00, "Ох, и испугал ты меня, парень! Не видишь, что я в размышлениях?" }, { 4.63, "Это что ещё? Поставка Джордану... Стальгорн. А, да, я понял, о чём речь." }, { 10.24, "Мо'грошские огры ограбили меня, и нет у меня руды для старого друга. Караван шёл сюда из Болотины и попал в засаду." }, { 18.21, "Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя." }, { 23.49, "Если хочешь найти эту партию руды, то придётся тебе двинуться на север, за озеро Лок. Она где-то там." } }, f = { { 0.00, "Ох, и испугала ты меня, дамочка! Не видишь, что я в размышлениях?" }, { 5.12, "Это что ещё? Поставка Джордану... Стальгорн. А, да, я понял, о чём речь." }, { 10.73, "Мо'грошские огры ограбили меня, и нет у меня руды для старого друга. Караван шёл сюда из Болотины и попал в засаду." }, { 18.70, "Охранник, что уцелел, помер пару дней назад – целитель не поспел вовремя." }, { 23.98, "Если хочешь найти эту партию руды, то придётся тебе двинуться на север, за озеро Лок. Она где-то там." } } }, t = { d = 25.3, g = 1, v = "dwarf-male", n = { x = 248 }, c = { m = { { 0.00, "Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдёшь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести." }, { 10.98, "Но ведь ты тут не за тем, чтобы за меня работу делать, верно?" }, { 15.49, "А сделка есть сделка. Джордан хотел получить свою руду, и он её получит." }, { 20.89, "Передай ему приветик от меня, и доброй тебе дороги, герой." } }, f = { { 0.00, "Ну-ну, надо же! Знал бы я, что ты и правда прямо туда и пойдёшь и навтыкаешь этим ограм, я бы дал тебе целый список, что оттуда принести." }, { 11.02, "Но ведь ты тут не за тем, чтобы за меня работу делать, верно?" }, { 15.53, "А сделка есть сделка. Джордан хотел получить свою руду, и он её получит." }, { 20.93, "Передай ему приветик от меня, и доброй тебе дороги, героиня." } } } } },
    [1656] = { d = 33.6, v = "tauren-female#72", n = { x = 318 }, c = { x = { { 0.00, "Умоляю, помоги мне! У меня ещё есть дело здесь, на плато - я прохожу обряд Силы, - а мой отец требует, чтобы я срочно доставила эти меха в таверну в деревне Кровавого Копыта!" }, { 14.92, "Как же мне выполнить сразу обе задачи - завершить ритуал и отнести меха?! Не отнесёшь ли ты их вместо меня?" }, { 23.52, "Таверна - такое милое и уютное местечко, там есть всё, чего может пожелать притомившийся путник. Даю слово, тебе понравится!" } } }, t = { d = 29.8, v = "tauren-male#132", n = { x = 258 }, c = { x = { { 0.00, "О, а вот и мои меха! Благодарю вас." }, { 4.08, "Вы доставили их даже быстрее, чем я ожидал. Они послужат отличными одеялами для моих постояльцев." }, { 13.11, "Прошу вас, гостите в таверне, сколько пожелаете. Наши двери всегда открыты, и мы рады каждому." }, { 21.48, "Не стоит недооценивать значение полноценного отдыха - особенно если впереди дальняя дорога." } } } } },
    [1665] = { d = 5.3, v = "human-male#50", n = { x = 48 }, c = { x = { { 0.00, "Ладно, бери мою кружку. Стой! Дай-ка я хотя бы допью... Ну вот. Бери." } } }, t = { d = 8.3, v = "human-male", n = { x = 90 }, c = { x = { { 0.00, "А вот и кружка! Да уж, он не хотел с ней расставаться, но ты умеешь настоять на своём. Молодец. Приступим к обучению..." } } } } },
    [1666] = { d = 24.9, g = 1, v = "human-male", n = { m = 279, f = 280 }, c = { m = { { 0.00, "Ты освоил несколько новых приёмов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард." }, { 8.54, "Он живёт в своём поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины." }, { 14.21, "Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия." }, { 19.50, "Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием." } }, f = { { 0.00, "Ты освоила несколько новых приёмов, но без хорошего оружия тебе не обойтись. Думаю, тебе мог бы помочь маршал Хаггард." }, { 8.59, "Он живёт в своём поместье в Элвиннском лесу, возле лесозаготовок Восточной Долины." }, { 14.26, "Он ушёл в отставку, но за время службы собрал недурную коллекцию оружия." }, { 19.55, "Скажи, что тебя прислал я, и если повезёт, он поделится лишним оружием." } } }, t = { d = 8.1, g = 1, v = "human-male", n = { m = 85, f = 86 }, c = { m = { { 0.00, "Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкрался, что я принял тебя за гнолла!" } }, f = { { 0.00, "Кто это? Баргард, это ты? Подойди поближе. Глаза у меня уже не те. Ты так подкралась, что я принял тебя за гнолла!" } } } } },
    [1667] = { d = 35.6, v = "human-male", n = { x = 395 }, c = { x = { { 0.00, "Тебя ведь прислал Баргард? Да, у меня есть запасное оружие, но сначала я хочу дать тебе задание…" }, { 7.04, "Некоторое время назад меня обманул злодей из Братства Справедливости, Джек Мертвозуб." }, { 13.13, "Он пришёл в темноте, одетый в гербовую накидку Штормграда, и я принял его за маршала Дугхана." }, { 19.55, "Джек сказал, что ему нужен мой старый знак маршала, и я, не раздумывая, отдал его..." }, { 25.23, "а потом он захохотал и сбежал, прежде, чем я успел его схватить!" }, { 30.18, "Верни мне мой знак! Джек Мертвозуб наверняка прячет его в лагере на юге." } } }, t = { d = 25.3, v = "human-male", n = { x = 285 }, c = { x = { { 0.00, "Ура, мой знак у тебя! Я боялся, что лишился его навсегда, а шваль из Братства Справедливости получила возможность изображать из себя представителей власти." }, { 10.79, "Тебе же удалось предотвратить невиданный разгул преступности." }, { 15.37, "Вот моё оружие, которое лежит без дела с тех времён, как я был маршалом." }, { 20.44, "Я его регулярно чистил его, и оно в отличной форме, выбирай!" } } } } },
    [1678] = { d = 25.0, g = 1, v = "dwarf-male", n = { m = 272, f = 273 }, c = { m = { { 0.00, "Хорошему воину пристало быть стойким." }, { 2.75, "Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками." }, { 9.66, "Веджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов." }, { 15.74, "Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов." }, { 20.45, "Принеси мне голову Веджрека, и я поверю, что ты не лыком шит." } }, f = { { 0.00, "Хорошему воину пристало быть стойким." }, { 2.75, "Я научу тебя новым приёмам, но прежде докажи, что сможешь справиться с серьёзными противниками." }, { 9.66, "Веджрек – один из самых сильных троллей в наших краях. Ему-то ты и бросишь вызов." }, { 15.74, "Он живёт в хижине в предгорьях, чуть южнее форта Мерзлогривов." }, { 20.45, "Принеси мне голову Веджрека, и я поверю, что ты не лыком шита." } } }, t = { d = 20.9, g = 1, v = "dwarf-male", n = { m = 205, f = 206 }, c = { m = { { 0.00, "Ну и урод же был этот Веджрек, а? Отличная работа! У тебя есть всё, что нужно. А теперь начнём твой урок..." }, { 8.88, "Ты, может, и не знал, но крепкая защита — жизненно важна для герой." }, { 13.39, "Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники" } }, f = { { 0.00, "Ну и урод же был этот Веджрек, а? Отличная работа! У тебя есть всё, что нужно. А теперь начнём твой урок..." }, { 8.88, "Ты, может, и не знала, но крепкая защита — жизненно важна для героиня." }, { 13.54, "Она позволяет ему стоять на ногах там, где другие пали бы, — а именно этого и ждут от тебя твои союзники" } } } } },
    [1679] = { d = 19.1, g = 1, v = "dwarf-male", n = { m = 212, f = 213 }, c = { m = { { 0.00, "Привет тебе, воин! Ты наделён многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдёшь." }, { 10.01, "Марен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним." } }, f = { { 0.00, "Привет тебе, воин! Ты наделена многими талантами, но тебе предстоит многому научиться, и лучше учителя, чем Марен Грозовая Вершина, не найдёшь." }, { 9.91, "Марен в Оружейной, в Палатах Войны Стальгорна. Как только ты решишь сделать очередной шаг на пути воина, поговори с ним." } } }, t = { d = 6.8, v = "dwarf-male", n = { x = 67 }, c = { x = { { 0.00, "А. Я слышал твоё имя от воинов Дун Морога. Надеюсь, ты не всё время проводишь в пивных?" } } } } },
    [1680] = { d = 13.4, g = 1, v = "dwarf-male", n = { m = 147, f = 148 }, c = { m = { { 0.00, "Ты уже освоил несколько приёмов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скуёт тебе оружие по вкусу." }, { 9.40, "Тормус живёт здесь, в Стальгорне, в Великой Кузне." } }, f = { { 0.00, "Ты уже освоила несколько приёмов, пора заняться твоим оружием. Поговори с Тормусом Подземной Кузней. Он скуёт тебе оружие по вкусу." }, { 9.36, "Тормус живёт здесь, в Стальгорне, в Великой Кузне." } } }, t = { d = 14.1, v = "dwarf-male", n = { x = 150 }, c = { x = { { 0.00, "Тебя прислал Марен? Да, я могу сковать тебе превосходное оружие... Но услуга за услугу." }, { 6.82, "Не бойся. Конечно, задание будет опасным, ты можешь погибнуть, но разве не к этому стремятся все воины?" } } } } },
    [1681] = { d = 33.3, v = "dwarf-male", n = { x = 365 }, c = { x = { { 0.00, "У моего наставника, Стурги Сталекрута, была мастерская на юге от озера Хельмова ложа в восточной части Дун Морога." }, { 9.36, "Он был лучшим учителем кузнечного дела." }, { 12.63, "Но однажды ученики принесли ему странную руду." }, { 15.96, "Мастер Сталекрут назвал её мрачной рудой и с радостью с ней работал, но увы, вскоре на них напал отряд дворфов Чёрного Железа. Они поубивали всех!" }, { 26.22, "Ступай в мастерскую Сталекрута, и отомсти за смерть моего учителя. И принеси мне груз мрачной руды." } } }, t = { d = 18.1, g = 1, v = "dwarf-male", n = { m = 197, f = 198 }, c = { m = { { 0.00, "Ты нашёл её! Молодец!" }, { 1.94, "Надеюсь, что в ходе поисков ты убил целую толпу дворфов Чёрного Железа." }, { 6.83, "Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута." }, { 12.16, "Впрочем, спасибо за руду. Я с радостью поработаю с ней и исследую её свойства." } }, f = { { 0.00, "Ты нашла её! Молодец!" }, { 2.22, "Надеюсь, что в ходе поисков ты убила целую толпу дворфов Чёрного Железа." }, { 7.17, "Боюсь, нам придётся столкнуться с ними не только в мастерской Сталекрута." }, { 12.50, "Впрочем, спасибо за руду. Я с радостью поработаю с ней и исследую её свойства." } } } } },
    [1683] = { d = 28.4, v = "nightelf-female#52", n = { x = 332 }, c = { x = { { 0.00, "Прежде чем браться за твоё обучение, я хочу испытать твою храбрость." }, { 4.78, "Сатир Ворлус Подлое Копыто обнаружил один из наших лунных колодцев, тот, что на юго-востоке от обители Бен'этиль." }, { 12.44, "Он плещется в его светлых водах, оскверняя их своим присутствием." }, { 16.81, "Отыщи Ворлуса и убей его. В доказательство принеси мне его рог, и я возьмусь учить тебя." }, { 23.16, "Отыскать дорогу к колодцу очень трудно, но тот, кто ищет, тот всегда найдёт." } } }, t = { d = 13.8, v = "nightelf-female#52", n = { x = 166 }, c = { x = { { 0.00, "Прекрасно сделано. Как приятно знать, что Ворлус побеждён и наш лунный колодец очищен." }, { 5.94, "Приятно видеть юных воинов, стремящихся защитить от порчи наш любимый Тельдрассил. Теперь, давай начнём обучение..." } } } } },
    [1684] = { d = 12.7, v = "nightelf-female#52", n = { x = 144 }, c = { x = { { 0.00, "Приветствую тебя, воин. Ты растёшь над собой, но профессия воина не так проста, как кажется. Тебе нужен хороший учитель." }, { 8.31, "В Дарнассе, на террасе Воинов, живёт Эланария. Поучись у неё." } } }, t = { d = 8.7, v = "nightelf-female#52", n = { x = 104 }, c = { x = { { 0.00, "Приветствую. Говорят, что ты подаёшь надежды. Но надо ещё убедиться есть ли у тебя сила воли, необходимая выбравшему путь воина." } } } } },
    [1685] = { d = 28.7, v = "human-male#50", n = { x = 335 }, c = { x = { { 0.00, "И вот так всегда. Я разыскивал тебя весь день, но так и не смог найти; а сейчас, когда я вовсе этого не ожидал, ты появляешься как из-под земли." }, { 9.96, "Я уже и так слишком много времени потратил на твои поиски, так что буду краток." }, { 15.26, "Наставник Гакин призывает тебя для дополнительных занятий – и, думаю, тебе стоит поторопиться." }, { 21.74, "Ты найдёшь его в подвале таверны \"Забитый ягнёнок\". К слову сказать, не стоит много болтать об этом месте..." } } }, t = { d = 19.4, v = "human-male#50", n = { x = 209 }, c = { x = { { 0.00, "Наконец-то ты здесь. Мне следовало послать за тобой кого-нибудь более расторопного, чем Ремен. Ну, неважно." }, { 8.88, "Когда у тебя было последнее занятие? Слишком давно, слишком..." }, { 12.92, "А ты знаешь, что у плохо обученного чернокнижника мало шансов сохранить голову на плечах?" } } } } },
    [1686] = { d = 35.5, g = 1, v = "nightelf-female#52", n = { m = 423, f = 424 }, c = { m = { { 0.00, "Ты многому научился. Пора создать для тебя настоящее оружие. Оружие воина." }, { 5.37, "Тебе придётся отправиться за ним на Тёмный берег." }, { 8.83, "Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой." }, { 18.10, "Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры." }, { 23.06, "Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза." }, { 30.75, "Победи её, забери у неё медальон и собери со дна ящики с элунитом." } }, f = { { 0.00, "Ты многому научилась. Пора создать для тебя настоящее оружие. Оружие воина." }, { 5.52, "Тебе придётся отправиться за ним на Тёмный берег." }, { 8.97, "Давным-давно один корабль разбился о камни рядом с Аубердинским маяком, и по дну моря рассеялось множество сундуков с элунитовой рудой." }, { 18.24, "Для начала тебе придётся одержать верх над стражем элунита, тенью Элуры." }, { 23.21, "Она была капитаном затонувшего корабля, а после смерти сама обрекла себя на то, чтобы стать последним стражем груза." }, { 30.90, "Победи её, забери у неё медальон и собери со дна ящики с элунитом." } } }, t = { d = 7.7, g = 1, v = "nightelf-female#52", n = { m = 84, f = 85 }, c = { m = { { 0.00, "Браво." }, { 0.96, "Ты дал Тени Элуры так долго ожидаемый мир, и мы используем этот элунит чтобы сделать тебе оружие." } }, f = { { 0.00, "Браво." }, { 0.96, "Ты дала Тени Элуры так долго ожидаемый мир, и мы используем этот элунит чтобы сделать тебе оружие." } } } } },
    [1688] = { d = 43.8, v = "human-male#50", n = { x = 486 }, c = { x = { { 0.00, "У меня была ученица по имени Сурена Каледон. Помню, она стояла как раз там, где сейчас стоишь ты…" }, { 7.27, "Просила меня научить её искусству чернокнижия, а у самой даже капли таланта к этому не было." }, { 13.34, "Хм, зато она была молода и довольно миловидна. Если бы я видел тогда, что это за вероломная дрянь!" }, { 22.02, "Распутная девка сбежала с одним из членов Братства Справедливости по имени Эрлан Драджмур." }, { 28.16, "Об этой потере я нисколько не сожалею, однако колье Кровавого камня, которое я подарил ей, мне всё ещё нужно." }, { 35.77, "Её жизнь для меня больше ничего не значит. Ты найдёшь девку на тыквенной ферме Бреквеллов. Верни мне моё имущество!" } } }, t = { d = 14.8, v = "human-male#50", n = { x = 173 }, c = { x = { { 0.00, "Сурена была талантлива, но не настолько, чтобы овладеть чарами самостоятельно." }, { 5.27, "Печально видеть, как погибают молодые и талантливые, но иногда без этого нельзя." }, { 11.02, "Надеюсь, усилия, вложенные в тебя, прахом не пойдут..." } } } } },
    [1689] = { d = 29.2, g = 1, v = "human-male#50", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Вернув моё колье и обманув Сурену, ты доказал, что не уступаешь ей в таланте." }, { 5.48, "Поэтому я уверен, что тебе не помешает обучение." }, { 8.78, "Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше." }, { 15.43, "Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении." }, { 26.26, "Используй магию колье в кругу призыва." } }, f = { { 0.00, "Вернув моё колье и обманув Сурену, ты доказала, что не уступаешь ей в таланте." }, { 5.53, "Поэтому я уверен, что тебе не помешает обучение." }, { 8.83, "Ты можешь управлять потоками магической энергии, но чернокнижник должен уметь намного больше." }, { 15.48, "Я научу тебя управлять демоном Бездны, но прежде тебе нужно призвать его в круг призыва и покорить, используя любое оружие, которое имеется в твоём распоряжении." }, { 26.30, "Используй магию колье в кругу призыва." } } }, t = { d = 17.4, v = "human-male#50", n = { x = 206 }, c = { x = { { 0.00, "Тебе удалось даже больше, чем я ожидал. На это я и надеялся. Теперь ты можешь научиться управлять покорённым тобой демоном." }, { 8.23, "Он станет твоим помощником в предстоящих испытаниях." }, { 11.78, "Сейчас мне нечему больше учить тебя, но я уверен, что мы с тобой, ещё увидимся..." } } } } },
    [1692] = { d = 12.4, v = "nightelf-female#52", n = { x = 131 }, c = { x = { { 0.00, "Я сложила собранный тобой элунит в сундук. Отнеси его кузнецу Матилю, мы сделаем из него элунитовое оружие." }, { 8.55, "Матиль на юге отсюда, на другой стороне этого здания." } } }, t = { d = 14.0, v = "nightelf-male#59", n = { x = 153 }, c = { x = { { 0.00, "А, элунитовая руда. Работать с этим металлом – одно удовольствие, ведь он благословлён самой богиней Элуной." }, { 7.74, "Выковать элунитовое оружие – великая честь." }, { 11.16, "Подожди, я сейчас примусь за работу..." } } } } },
    [1698] = { d = 10.4, v = "human-male", n = { x = 121 }, c = { x = { { 0.00, "Йорус Ячменовар бросил вызов всем воинам Альянса." }, { 3.52, "Он ждёт в таверне Приозерья, что в Красногорье, и сулит щедрую награду всем, прошедшим испытание." } } }, t = { d = 10.9, v = "dwarf-male", n = { x = 110 }, c = { x = { { 0.00, "Ха! Значит, до тебя дошли вести о моём вызове, а?" }, { 4.17, "Что ж, садись и слушай. Пей и наслаждайся... Может быть, это твоя последняя выпивка в этой жизни." } } } } },
    [1699] = { d = 34.3, g = 1, v = "dwarf-male", n = { m = 392, f = 393 }, c = { m = { { 0.00, "Я называю моё испытание Ретбанским вызовом." }, { 3.37, "Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"…" }, { 13.17, "Вернуться тебе придётся в течение часа. Там полно красногорских гноллов." }, { 18.41, "Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец!" }, { 26.98, "Что скажешь? Пещеры Ретбана находятся в холмах на севере от Озёр. Ты готов принять Ретбанский вызов?" } }, f = { { 0.00, "Я называю моё испытание Ретбанским вызовом." }, { 3.37, "Чтобы пройти его тебе всего-то нужно войти в пещеры Ретбана, дойти до первой развилки и вернуться. Элементарно! Есть, правда, несколько \"но\"…" }, { 13.17, "Вернуться тебе придётся в течение часа. Там полно красногорских гноллов." }, { 18.41, "Перед тем, как тронуться в путь, тебе придётся глотнуть фирменного напитка моей семьи, жгучего пива семейства Ячменевец!" }, { 26.98, "Что скажешь? Пещеры Ретбана находятся в холмах на севере от Озёр. Ты готова принять Ретбанский вызов?" } } }, t = { d = 3.3, g = 1, v = "dwarf-male", n = { m = 27, f = 28 }, c = { m = { { 0.00, "Ты справился! Молодец! Трижды ура путник!" } }, f = { { 0.00, "Ты справилась! Молодец! Трижды ура путница!" } } } } },
    [1700] = { d = 16.4, v = "dwarf-male", n = { x = 185 }, c = { x = { { 0.00, "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Гриманду Элмору." }, { 7.57, "Он живёт здесь, в Квартале Дворфов, в оружейном магазине. Он гордится своим искусством, и совсем не обрадуется моему открытию..." } } }, t = { d = 12.0, v = "dwarf-male", n = { x = 108 }, c = { x = { { 0.00, "Это написал Фьюрен? Как он смёл! Да я его всему сам научил! Яйца курицу не учат! Нахал!" }, { 8.01, "Хм-м-м... Но в этих записях что-то есть... Надо попробовать..." } } } } },
    [1701] = { d = 23.2, v = "dwarf-male", n = { x = 264 }, c = { x = { { 0.00, "Ну вот, я дал тебе отличный щит, но это ещё не всё. Я знаю секрет изготовления очень прочного доспеха." }, { 7.08, "Это нелегко, и мне потребуются редкие материалы, но если тебе не лень за ними поохотиться, доспех получится несравненный." }, { 15.72, "Что скажешь? Если ты не боишься трудностей, я выдам тебе список необходимых материалов и где их искать." } } }, t = { d = 8.8, v = "dwarf-male", n = { x = 99 }, c = { x = { { 0.00, "Тебе удалось добыть всё необходимое? Вот это да! Я опасался, что химеры слопают тебя с потрохами! Что ж, займёмся доспехами..." } } } } },
    [1702] = { d = 26.0, g = 1, v = "dwarf-male", n = { m = 293, f = 294 }, c = { m = { { 0.00, "Да, приняв Ретбанский вызов, ты показал, на что способен. Я своё слово держу. Ты получишь обещанную награду… Только она в Штормграде." }, { 9.46, "Поговори с моим другом, Фьюреном Длиннобородом. Он живёт в Квартале Дворфов." }, { 14.63, "Его щиты славятся во всей округе, а мне он должен услугу." }, { 18.97, "Вот, отнеси Фьюрену этот бочёнок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст." } }, f = { { 0.00, "Да, приняв Ретбанский вызов, ты показала, на что способна. Я своё слово держу. Ты получишь обещанную награду… Только она в Штормграде." }, { 9.45, "Поговори с моим другом, Фьюреном Длиннобородом. Он живёт в Квартале Дворфов." }, { 14.61, "Его щиты славятся во всей округе, а мне он должен услугу." }, { 18.96, "Вот, отнеси Фьюрену этот бочёнок жгучего пива Ячменевца и попроси взамен щит. Он плохого не даст." } } }, t = { d = 11.3, v = "dwarf-male", n = { x = 110 }, c = { x = { { 0.00, "А, жгучее пиво Ячменевца. Отличный напиток! Значит, ты от Йоруса, а?" }, { 5.89, "Конечно я дам тебе щит, да ещё какой! Такого нигде не найти, честное слово!" } } } } },
    [1703] = { d = 13.7, v = "dwarf-male", n = { x = 157 }, c = { x = { { 0.00, "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Матилю." }, { 6.31, "Он живёт довольно далеко, в Дарнассе, но несомненно будет рад, если я поделюсь с ним своими открытиями." } } }, t = { d = 11.9, v = "nightelf-male#59", n = { x = 135 }, c = { x = { { 0.00, "Это интересно, очень интересно. Мой коллега Фьюрен, сделал грандиозное открытие." }, { 5.82, "Спасибо. Это будет честью для меня, применять новые технологии к моим разработкам." } } } } },
    [1704] = { d = 14.0, v = "dwarf-male", n = { x = 161 }, c = { x = { { 0.00, "Работая над твоим доспехом, я делал записи, а теперь хочу отослать их копию кузнецу Клацморту Гайкокруту." }, { 7.30, "Он живёт в Стальгорне, и когда услышит о моём открытии... Он бороду себе выдернет от восторга!" } } }, t = { d = 17.7, v = "gnome-male", n = { x = 195 }, c = { x = { { 0.00, "Ну и ну! Поразительные записи мне прислали! Больше того... Они ошеломляющие и невероятные, я едва на ногах стою от восторга!" }, { 9.45, "Фьюрен совершил прорыв в кузнечном деле! Да-да, самый настоящий прорыв! Мне не терпится испробовать новую технологию!" } } } } },
    [1705] = { d = 31.6, v = "dwarf-male", n = { x = 360 }, c = { x = { { 0.00, "Может, этот Фьюрен и совершил открытие, но мне надо проверить, так ли это. Попробую-ка я сделать такие доспехи." }, { 7.67, "Если ты поможешь добыть все материалы, можешь забрать доспех себе." }, { 12.67, "Мне понадобится горящая кровь и горящий камень." }, { 16.28, "Единственное место, где можно добыть эти материалы – Сумеречный лес." }, { 20.92, "Горящая кровь есть у воргенов из стаи Ночной Погибели из пещеры Роланда, а горящий камень хранит у себя их главарь, Кишкодёр. И не мешкай, во имя Света." } } }, t = { d = 4.5, v = "dwarf-male", n = { x = 48 }, c = { x = { { 0.00, "Недурно! А теперь, прошу прощения, мне тоже надо поработать..." } } } } },
    [1708] = { d = 29.0, g = 1, v = "gnome-male", n = { m = 334, f = 336 }, c = { m = { { 0.00, "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах." }, { 5.14, "Раз ты помог Фьюрену, а он мне, я разрешу тебе забрать их себе!" }, { 9.83, "Чтобы довести работу до конца, мне необходим особый коралл, выжженный." }, { 14.64, "Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине." }, { 19.92, "Принеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, у меня руки чешутся, так хочется взяться за дело." } }, f = { { 0.00, "Я хочу опробовать технологию Фьюрена Длинноборода на собственных доспехах." }, { 5.14, "Раз ты помогла Фьюрену, а он мне, я разрешу тебе забрать их себе!" }, { 10.00, "Чтобы довести работу до конца, мне необходим особый коралл, выжженный." }, { 14.81, "Он растёт лишь в одном месте, вдоль побережья Гавани Менетилов в Болотине." }, { 20.09, "Принеси мне побольше таких кораллов, и я примусь за работу. И поторапливайся, у меня руки чешутся, так хочется взяться за дело." } } }, t = { d = 15.7, g = 1, v = "gnome-male", n = { m = 177, f = 176 }, c = { m = { { 0.00, "Вот, то что нужно! Молодец! А теперь дай-ка я их расплавлю и расплющу." }, { 4.83, "Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!" }, { 10.53, "Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!" } }, f = { { 0.00, "Вот, то что нужно! Умница! А теперь дай-ка я их расплавлю и расплющу." }, { 4.80, "Попробую совместить технологию Фьюрена с моей, и посмотрим что из этого выйдет!" }, { 10.50, "Ну-ну, я предчувствую, что доспехи получатся очень-очень-очень прочные!" } } } } },
    [1710] = { d = 29.4, v = "nightelf-male#59", n = { x = 347 }, c = { x = { { 0.00, "Мой коллега, Фьюрен Долгобород, совершил многообещающее открытие." }, { 4.51, "Я хотел бы испытать его на новых доспехах, мне кажется, результат превзойдёт все ожидания." }, { 10.88, "Не поможешь? Если ты принесёшь мне все необходимые материалы, я и для тебя сделаю такие доспехи." }, { 17.82, "Мне понадобится высохшая на солнце скорлупа яиц виверн Скального Гнездовья из Тысячи Игл. Скорлупу можно найти под их гнёздами." }, { 26.53, "Как наберёшь достаточно, возвращайся." } } }, t = { d = 6.2, v = "nightelf-male#59", n = { x = 63 }, c = { x = { { 0.00, "Ах, спасибо тебе! Это прекрасно подойдёт!" }, { 3.25, "Я начну создавать броню немедленно." } } } } },
    [1715] = { d = 32.9, v = "gnome-male", n = { x = 366 }, c = { x = { { 0.00, "Хмм. В прежние времена все чернокнижники Каз Модан обучались под присмотром мастеров Гномрегана, но теперь, когда все мы вынуждены ютиться в этой крысиной норе под названием Стальгорн и Магни решил не спускать с нас глаз, нам приходится отсылать наших новичков на обучение в Штормград." }, { 21.06, "По счастью, Гакин не растяпа, так что ты всё равно узнаешь всё, что тебе надо, но я просто киплю!" }, { 28.06, "Короче, ты найдёшь Гакина в подвале \"Забитого ягнёнка\" в Штормграде." } } }, t = { d = 16.7, v = "human-male#50", n = { x = 200 }, c = { x = { { 0.00, "Так тебя послал Злобноверт? Нет, пора бы уже этим стальгорнским растяпам как-то разобраться с ситуацией." }, { 6.77, "Штормград не резиновый, и наставников тут сколько есть, и не больше." }, { 11.34, "Если сюда повалит народ, то рано или поздно мы привлечём к себе внимание." } } } } },
    [1716] = { d = 27.5, v = "human-male#50", c = { x = { { 0.00, "Сайаады – пожиратели душ, подавляющие волю и вводящие в искушение. Порождение чистого зла." }, { 6.44, "В легкомысленных историях этих демонов называют суккубами, если речь о женщинах, и инкубами, если это мужчины." }, { 14.19, "Примани демона символом любви, победи его – и он будет тебе служить." }, { 18.95, "Но найти подходящий символ непросто. Поговори с Такаром Провидцем. Ты найдёшь его в калимдорских Степях возле лагеря Таурахо." } } }, t = { d = 11.9, v = "human-male#50", c = { x = { { 0.00, "Как вы добрались? Вы проделали долгий путь, чтобы поговорить со мной. Но не бойтесь: я знаю, зачем Гакин прислал вас." }, { 7.69, "Это было мудро с его стороны, потому что я могу вам помочь." } } } } },
    [1717] = { d = 17.2, g = 1, v = "gnome-male", n = { m = 181, f = 182 }, c = { m = { { 0.00, "путник! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать." }, { 5.90, "Ты давненько уже не проходил очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать." } }, f = { { 0.00, "путница! Не ожидал увидеть тебя в этих краях, но мне велели за тобой приглядывать." }, { 6.06, "Ты давненько уже не проходила очередного обучения, так что тебе следует зайти к Гакину, когда в следующий раз будешь в Штормграде. Он будет тебя ждать." } } }, t = { d = 14.5, v = "human-male#50", n = { x = 165 }, c = { x = { { 0.00, "Хорошо, что кто-то, наконец, поймал тебя. Я уже опасался худшего. В тебя вложено слишком много и было бы жалко тебя потерять." }, { 8.75, "Мы ещё поговорим на эту тему позднее.. Твоя тренировка более важна в данный момент." } } } } },
    [1718] = { d = 48.6, v = "tauren-male#67", n = { x = 395 }, c = { x = { { 0.00, "Ты становишься недурным воином. Пришло время помериться силой с братьями по оружию." }, { 8.58, "Недалеко от побережья Степей, к югу от Кабестана, есть остров. Он называется Островом Битв. Это место встречи воинов. Место встречи и дружеских схваток." }, { 25.20, "Поговори со старшим воином острова, Кланноком Маклеодом." }, { 30.48, "Если он сочтёт тебя достойным дальнейшего обучения, то поможет тебе сделать очередной шаг на пути воина." }, { 40.75, "До Острова Битв можно добраться по песчаной отмели вдоль Торгового побережья." } } }, t = { d = 6.7, v = "human-male#50", n = { x = 77 }, c = { x = { { 0.00, "Привет тебе, воин. Хорошо, что тебе удалось добраться до Острова Битв. Надеюсь, он тебе нравится..." } } } } },
    [1719] = { d = 27.9, v = "human-male#50", n = { x = 327 }, c = { x = { { 0.00, "Если ты хочешь учиться у меня, тебе придётся пройти испытание, Побоище." }, { 4.85, "Через него проходят все молодые воины, вообразившие себя великими. А величие надо доказывать." }, { 11.43, "Для начала пройди сквозь ту толпу и встань на решётку. Это будет знак Пруттику Плоскоголову, что ты готов. Он сразу пошлёт тебе поединщика." }, { 21.08, "Когда ты одолеешь всех, он позовёт Большого Билла. Убей его и вернись ко мне за отведённое время." } } }, t = { d = 6.4, g = 1, v = "human-male#50", n = { m = 67, f = 67 }, c = { m = { { 0.00, "Молодец. Ты прошёл испытание Побоищем!" }, { 3.04, "Ты могучий воин, и учить тебя – великая честь..." } }, f = { { 0.00, "Молодец. Ты прошла испытание Побоищем!" }, { 3.11, "Ты могучий воин, и учить тебя – великая честь..." } } } } },
    [1738] = { d = 31.0, v = "human-male#50", n = { x = 363 }, c = { x = { { 0.00, "Готовясь к твоему приходу, я на скорую руку оглядел весь мир, проник взглядом сквозь пелену времени и нашёл то, что тебе нужно." }, { 8.98, "Во время Войны Древних двое влюблённых вместе пали в битве." }, { 12.98, "Там, где перестали биться их сердца, выросло дерево, известное как сердцедрево – символ их бессмертной любви." }, { 20.50, "Этого должно быть достаточно, чтобы привлечь суккуба." }, { 24.44, "Руины Ордиль-Арана, где растёт сердцедрево, находятся в северо-западной части Ясеневого леса." } } }, t = { d = 13.6, v = "human-male#50", n = { x = 157 }, c = { x = { { 0.00, "Да, сердцедрево нам подойдёт. Дай-ка я немного обработаю древесину..." }, { 4.98, "Такар – настоящий кладезь премудростей; с таким не пропадёшь, правда? Если б я только мог убедить его вернуться к цивилизации..." } } } } },
    [1739] = { d = 22.6, v = "human-male#50", n = { x = 268 }, c = { x = { { 0.00, "С помощью сердцевины сердцедрева ты сможешь открыть портал и призвать суккуба в круг призыва. Круг находится в подвале." }, { 8.23, "Не забывай об осторожности, суккубы подчиняли себе и самых стойких заклинателей." }, { 14.06, "После того как вызовешь демона и вернёшь его обратно в Бездну, возвращайся ко мне и я научу тебя, как обращаться с суккубом." } } }, t = { d = 13.4, v = "human-male#50", n = { x = 157 }, c = { x = { { 0.00, "Неплохо, неплохо... Я не ошибся, когда решил обучать тебя. Твои успехи меня не разочаровывают." }, { 6.56, "Пора научить тебя обращению с только что подчинённым суккубом. Только не забывай про осторожность!" } } } } },
    [1740] = { d = 33.0, v = "human-male#50", n = { x = 399 }, c = { x = { { 0.00, "Когда демоны Легиона попадают в немилость, их души заключают в сферы и раздают магам и чернокнижникам." }, { 7.07, "Многих из них носили на Азероте их слуги. Даже расколотые на части, эти сферы хранят в себе силу демонов, заключённых внутри." }, { 15.37, "Шар Соран'рука был расколот надвое." }, { 17.85, "Одну из частей раздробили на ещё более мелкие фрагменты послушники Сумеречного Молота в Непроглядной Пучине." }, { 25.16, "А другая, большая часть, досталась волшебнику из крепости Тёмного Клыка. Найди их, и я смогу воссоздать этот шар." } } }, t = { d = 23.6, g = 1, v = "human-male#50", n = { m = 277, f = 278 }, c = { m = { { 0.00, "Да... Этот шар не так уж сильно раскололи, и передо мной почти все осколки." }, { 4.96, "Воссоздать их, сделав Соран'рука единым целым, несложно." }, { 9.03, "Я посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона." }, { 13.85, "Ты оказал мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору." } }, f = { { 0.00, "Да... Этот шар не так уж сильно раскололи, и передо мной почти все осколки." }, { 4.96, "Воссоздать их, сделав Соран'рука единым целым, несложно." }, { 9.03, "Я посвятил всю жизнь изучению и восстановлению сфер Пылающего Легиона." }, { 13.85, "Ты оказала мне большую услугу, позволив изучить эти осколки, и я верну их тебе, полностью восстановив, придав им любую форму по твоему выбору." } } } } },
    [1758] = { d = 31.6, v = "human-male#50", n = { x = 379 }, c = { x = { { 0.00, "Простой круг призыва не поможет тебе вызвать на бой охотника скверны." }, { 5.07, "Я и трое моих послушников поможем тебе создать магические круги." }, { 9.86, "Тебе также понадобится фолиант Заговора, который мы давно утратили." }, { 14.29, "Его написала первая группа чернокнижников, умудрившихся вызвать охотника скверны без посторонней помощи." }, { 21.65, "С этим тебе поможет Крому Крепкоруку." }, { 24.14, "Теперь он – главный чернокнижник, и целыми днями он сидит в библиотеке Стальгорна, оберегая древние тексты." } } }, t = { d = 13.1, v = "dwarf-male", n = { x = 140 }, c = { x = { { 0.00, "Фолиант Заговора? Хм-м... Знакомое название. Я его никогда не видел – а уж поверьте, я помню все прочитанные книги. Хм…" }, { 7.95, "А, да! Я видел ссылки на этот фолиант в библиотечных каталогах." } } } } },
    [1778] = { d = 11.4, g = 1, v = "human-male", n = { x = 117 }, c = { m = { { 0.00, "Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, герой." } }, f = { { 0.00, "Я намереваюсь скоро вернуться домой. Надеюсь, у Стефани в Штормграде дела идут хорошо. Не терпится снова увидеться с ней. До следующей встречи, героиня." } } }, t = { d = 23.1, g = 1, v = "dwarf-female#33", n = { m = 238, f = 246 }, c = { m = { { 0.00, "Итак, ты быстро вернулся, а? И чего же ты достиг за это время?" }, { 5.45, "Итак, ты помог достойному делу? Возможно ты уже заслужил уважение граждан Азерота. Скажи мне кому ты помог – и я скажу кто ты…" }, { 14.54, "Удивительно , ты действительно следуешь пути Света." }, { 18.41, "Такая жертва будет обязательно вознаграждена в своё время.." } }, f = { { 0.00, "Итак, ты быстро вернулась, а? И чего же ты достигла за это время?" }, { 4.87, "Итак, ты помогла достойному делу? Возможно ты уже заслужила уважение граждан Азерота." }, { 11.30, "Скажи мне кому ты помогла – и я скажу кто ты…" }, { 14.82, "Удивительно , ты действительно следуешь пути Света." }, { 18.69, "Такая жертва будет обязательно вознаграждена в своё время.." } } } } },
    [1779] = { d = 33.9, g = 1, v = "dwarf-female#33", n = { m = 356, f = 363 }, c = { m = { { 0.00, "Я хочу, чтобы ты взял это. Это называется знак Жизни." }, { 4.08, "Ты показал своё милосердие и терпение, а теперь я хочу, чтобы ты проявил себя не только как воин, но и как целитель." }, { 12.46, "Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа." }, { 18.55, "Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов." }, { 23.55, "Возьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет." } }, f = { { 0.00, "Я хочу, чтобы ты взяла это. Это называется знак Жизни." }, { 4.22, "Ты показала своё милосердие и терпение, а теперь я хочу, чтобы ты проявила себя не только как воин, но и как целительница." }, { 13.62, "Мой супруг Майридон Боевая Кузня недавно вернулся после стычки с дворфами Чёрного Железа." }, { 19.71, "Он едва ноги унёс – сейчас лечит свои раны у одного из наших жрецов." }, { 24.71, "Возьми Символ и поговори с ним. Если ты сумеешь ему помочь, мы вскоре продолжим наш разговор. Да пребудет с тобой Свет." } } }, t = { d = 26.7, g = 1, v = "dwarf-male", n = { x = 298 }, c = { m = { { 0.00, "*кашляет*" }, { 1.02, "Доброго тебе здравия, герой. Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона." }, { 7.47, "Так что сила твоего знака Жизни пока мне не нужна." }, { 11.24, "Значит, моя жёнушка тебя послала потолковать со мной, да? Славно, славно." }, { 16.18, "У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя." } }, f = { { 0.00, "*кашляет*" }, { 1.02, "Доброго тебе здравия, героиня. Не волнуйся о моих ранах, добрый жрец сумеет вылечить Майридона." }, { 7.60, "Так что сила твоего знака Жизни пока мне не нужна." }, { 11.37, "Значит, моя жёнушка тебя послала потолковать со мной, да? Славно, славно." }, { 16.30, "У меня найдётся времечко поговорить с тобой, я расскажу тебе в точности, что произошло с Майридоном и его лучшим другом Нармом, паладином вроде тебя." } } } } },
    [1780] = { d = 18.0, g = 1, v = "human-female", n = { m = 182, f = 183 }, c = { m = { { 0.00, "Я сегодня же отнесу это детям. Ты можешь не тревожиться, герой." }, { 4.16, "Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказал, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается. Доброго пути!" } }, f = { { 0.00, "Я сегодня же отнесу это детям. Ты можешь не тревожиться, героиня." }, { 4.44, "Конечно, такие, как ты, нечасто показываются в городе, но ты без сомнения доказала, что паладины Штормграда никогда не отвернутся от тех, кто в них нуждается. Доброго пути!" } } }, t = { d = 38.2, v = "human-male", n = { x = 429 }, c = { x = { { 0.00, "Ты уже здесь? Однако, странствия заняли у тебя не так много времени, как я полагал." }, { 5.79, "И что же тебе удалось свершить за время, проведённое вдали от Храма? Может быть, тебе довелось сражаться за справедливость?" }, { 14.36, "Или удалось постичь смысл милосердия? Или помочь кому-либо из нуждающихся жителей Азерота? Расскажи мне всё..." }, { 22.37, "Что ж, это производит впечатление. Поверь, это поистине поступки того, кто следует путём Света и ставит благо других выше своего собственного." }, { 33.38, "Рано или поздно такое самопожертвование всегда вознаграждается." } } } } },
    [1781] = { d = 36.5, v = "human-male", n = { x = 416 }, c = { x = { { 0.00, "Прими этот знак Жизни." }, { 1.94, "Тебе удалось обрести милосердие и терпение: пришло время узнать, хватит ли у тебя сил, чтобы воспользоваться одним из величайших даров Света." }, { 12.09, "Мой друг Газин недавно вернулся из Элвиннского леса с острова Героев, где он едва не расстался с жизнью после стычки с магами Братства Справедливости." }, { 22.42, "Сейчас он у алтаря: надеюсь, служителям удастся исцелить его раны." }, { 27.41, "Возьми этот Символ и поговори с Газином. Если сумеешь помочь ему, мы продолжим нашу беседу. Да пребудет с тобой извечный Свет!" } } }, t = { d = 30.3, g = 1, v = "dwarf-male", n = { x = 331 }, c = { m = { { 0.00, "*кашляет*" }, { 1.02, "Я рад встрече с тобой, герой. Не обращай внимания на мои раны: добрые служители Света смогут обо всём позаботиться." }, { 8.95, "Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока." }, { 15.41, "Значит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно." }, { 20.45, "Я тебе расскажу, что случилось со мной и моим другом Хензом." }, { 24.61, "Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти..." } }, f = { { 0.00, "*кашляет*" }, { 1.02, "Я рад встрече с тобой, героиня. Не обращай внимания на мои раны: добрые служители Света смогут обо всём позаботиться." }, { 9.03, "Сила знака Жизни, которого ты держишь в руках, мне без надобности... по крайней мере пока." }, { 15.50, "Значит, Даториан послал тебя поговорить со мной, да? Что ж, это правильно." }, { 20.54, "Я тебе расскажу, что случилось со мной и моим другом Хензом." }, { 24.70, "Если нам повезёт и тебе хватит сил и умения, ты ещё сможешь всех нас спасти..." } } } } },
    [1783] = { d = 34.7, v = "dwarf-male", n = { x = 395 }, c = { x = { { 0.00, "Мы выслеживали дворфов Чёрного Железа, что окопались к югу от озера Хельмово Ложе." }, { 5.69, "Мы знали, что они затевают недоброе, потому мы с Нармом решили подобраться поближе, чтобы посмотреть, как их капитан раздаёт приказы своим воинам." }, { 16.08, "Мы с Нармом воспользовались случаем и пристукнули нескольких, но они оказались крепче, чем мы думали, и набросились на нас толпой." }, { 24.90, "Нарм велел мне бежать за помощью, и вот я здесь." }, { 28.64, "Нарму нужна помощь. И я не успокоюсь, пока он её не получит. Ты ведь поможешь ему?" } } }, t = { d = 30.1, g = 1, v = "dwarf-male", n = { m = 329, f = 332 }, c = { m = { { 0.00, "Не знаю, как мне отблагодарить тебя, брат!" }, { 3.30, "Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни." }, { 8.99, "Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг." }, { 15.02, "Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появился." }, { 22.84, "То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже." } }, f = { { 0.00, "Не знаю, как мне отблагодарить тебя, сестра!" }, { 3.46, "Видать, тебя прислали мне в подмогу Тиза с Майридоном, раз на тебе знак Жизни." }, { 9.15, "Да, это правда, я пал в бою с дворфами Чёрного Железа, пытаясь получить одну из их бумаг." }, { 15.18, "Я довольно долго продержался и дал Майридону уйти, но я почти уже погрузился в Свет, когда ты появилась." }, { 22.42, "То, что тебе хватило мощи воспользоваться знаком, очень многое значит, но мы поговорим об этом позже." } } } } },
    [1784] = { d = 33.4, v = "dwarf-male", n = { x = 385 }, c = { x = { { 0.00, "Прежде чем я пал в бою, мы с Майридоном почти одолели одного из соглядатаев из клана Чёрного Железа возле того небольшого домика." }, { 8.80, "Мы видели, как их капитан раздавал им бумаги с приказами, и хотели убить его и забрать эти бумаги." }, { 15.93, "Кое-кто в совете Стальгорна до сих пор не верит в присутствие дворфов Чёрного Железа в Дун Морог." }, { 22.40, "Захватив одну из этих бумаг, мы не только получим доказательства их вылазок, но и поймём, что они затевают." }, { 30.03, "Добудь один из приказов и отнеси Майридону." } } }, t = { d = 18.4, g = 1, v = "dwarf-male", n = { m = 202, f = 204 }, c = { m = { { 0.00, "Хаха! Тебе удалось! Ты спас Нарма и нашёл доказательство, которое нужно моей жене, чтобы показать его в совете." }, { 7.56, "Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены. Прими снова мою благодарность." } }, f = { { 0.00, "Хаха! Тебе удалось! Ты спасла Нарма и нашла доказательство, которое нужно моей жене, чтобы показать его в совете." }, { 7.82, "Ты просто единственное благословление Света, если я в них хоть что-то понимаю... не считая, конечно, моей жены. Прими снова мою благодарность." } } } } },
    [1785] = { d = 18.4, g = 1, v = "dwarf-male", n = { m = 199, f = 199 }, c = { m = { { 0.00, "Вижу, моя жёнушка прямо пышет гордостью. Я бы на твоём месте поскакал прямо к ней." }, { 5.68, "Сдаётся, она хочет перекинуться с тобой парой слов." }, { 9.54, "Да хранит тебя Свет, славный герой. Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора." } }, f = { { 0.00, "Вижу, моя жёнушка прямо пышет гордостью. Я бы на твоём месте поскакал прямо к ней." }, { 5.68, "Сдаётся, она хочет перекинуться с тобой парой слов." }, { 9.54, "Да хранит тебя Свет, славная героиня. Я буду искать тебя на поле боя против Плети и клана Чёрного Железа, когда придёт пора." } } }, t = { d = 29.5, g = 1, v = "dwarf-female#33", n = { m = 336, f = 338 }, c = { m = { { 0.00, "Сегодня ты оказал большую услугу Стальгорну." }, { 3.09, "Я горда, что ты среди нас, и если ты готов, я хотела бы благословить тебя этим свитком." }, { 9.08, "Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни." }, { 19.13, "Я научу тебя возрождать к жизни твоих соратников." }, { 22.67, "Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна." } }, f = { { 0.00, "Сегодня ты оказала большую услугу Стальгорну." }, { 3.22, "Я горда, что ты среди нас, и если ты готова, я хотела бы благословить тебя этим свитком." }, { 9.42, "Знак Жизни подействовал бы только в руках паладина, готового принять одну из самых великих благостей Света, – силу возвращать умерших к жизни." }, { 19.47, "Я научу тебя возрождать к жизни твоих соратников." }, { 23.01, "Используй это умение мудро, и прими благодарность от меня, моего мужа и всего Стальгорна." } } } } },
    [1786] = { d = 40.7, v = "dwarf-male", n = { x = 467 }, c = { x = { { 0.00, "Мы с Хензом добрались до острова Героев – он находится посреди Озера Каменных Столбов, в северо-восточной части Элвиннского леса." }, { 8.76, "Мы слышали, что Братство Справедливости проникло в наши земли, и должны предоставить доказательства этого вторжения королевским советникам." }, { 18.49, "Мы засекли двоих из этих подонков, когда они просматривали кое-какие документы, и напали на них." }, { 25.07, "Увы, магов было больше, и нас заставили отступить." }, { 28.88, "Хенз прикрывал меня, и мне удалось бежать... проклятый глупец, отвагу проявить решил!.." }, { 35.04, "И вот он там так и остался. Хенз, я имею в виду. Может, ты сумеешь помочь?" } } }, t = { d = 32.6, g = 1, v = "dwarf-male", n = { m = 366, f = 368 }, c = { m = { { 0.00, "Прими мою благодарность, брат." }, { 2.47, "В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин." }, { 7.63, "Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи." }, { 13.93, "Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён..." }, { 22.08, "Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить." }, { 29.47, "Это свидетельство крепости твоей веры..." } }, f = { { 0.00, "Прими мою благодарность, сестра." }, { 2.60, "В твоих руках я вижу знак Жизни – тебя послал Даториан или Газин." }, { 7.76, "Мы с Газином пытались похитить планы Братства Справедливости, но на нас напали их чародеи." }, { 14.05, "Мне удалось продержаться достаточно долго для того, чтобы Газин успел скрыться, но в конце концов я был побеждён..." }, { 22.21, "Но тебе удалось вернуть меня – а далеко не всем дана способность управлять знаком Жизни, можешь мне поверить." }, { 29.60, "Это свидетельство крепости твоей веры..." } } } } },
    [1787] = { d = 33.2, v = "dwarf-male", n = { x = 371 }, c = { x = { { 0.00, "У нас ещё будет время поговорить о Символе. Сейчас важнее заполучить те бумаги, которые мы видели у Братства Справедливости." }, { 8.50, "Если бумаги будут у нас, мы сможем доказать, что братство проникло в Элвиннский лес – а может, и узнать что-нибудь о его планах." }, { 17.56, "Увы, навряд ли я сейчас могу считаться воином. Сможешь ли ты пойти в бой в одиночку?" }, { 23.40, "Сумеешь ли ты добыть то, что нам так необходимо?" }, { 27.23, "Если это тебе удастся, отнеси бумаги Газину и сообщи ему, что со мной всё хорошо." } } }, t = { d = 9.1, v = "dwarf-male", n = { x = 88 }, c = { x = { { 0.00, "Великолепно! Тебе удалось спасти Хенза и выполнить задание. Теперь я знаю: воистину, Свет озаряет твой путь!" } } } } },
    [1788] = { d = 19.9, v = "dwarf-male", n = { x = 232 }, c = { x = { { 0.00, "После того как Даториан ознакомится с этими бумагами, я передам их королевским советникам; однако прежде тебе стоит поговорить с Даторианом." }, { 9.58, "Думаю, он тоже хотел бы поблагодарить тебя." }, { 12.88, "Твоя помощь поистине неоценима. Надеюсь, это не последняя наша встреча. Я горжусь нашей дружбой." } } }, t = { d = 31.8, g = 1, v = "human-male", n = { m = 358, f = 360 }, c = { m = { { 0.00, "Что ж, полагаю, ты можешь гордиться своими свершениями." }, { 4.24, "Скажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделён знак Жизни." }, { 13.34, "Если в твоих силах призвать исцеляющую силу Света, ты достоин того, чтобы принять величайший дар паладинов, – дар воскрешения." }, { 22.33, "Ты сможешь возвращать к жизни павших спутников так же, как вернул к жизни Хенза." }, { 28.26, "Горний Свет озарил тебя, открой же ему душу." } }, f = { { 0.00, "Что ж, полагаю, ты можешь гордиться своими свершениями." }, { 4.24, "Скажу больше: ты можешь также гордиться своими способностями. Далеко не каждый может использовать силу, которой наделён знак Жизни." }, { 13.34, "Если в твоих силах призвать исцеляющую силу Света, ты достойна того, чтобы принять величайший дар паладинов, – дар воскрешения." }, { 22.32, "Ты сможешь возвращать к жизни павших спутников так же, как вернула к жизни Хенза." }, { 28.36, "Горний Свет озарил тебя, открой же ему душу." } } } } },
    [1791] = { d = 28.9, g = 1, v = "human-male#50", n = { m = 341, f = 342 }, c = { m = { { 0.00, "Что ж, ты освоил стойку берсерка, теперь нужно подобрать тебе оружие." }, { 5.07, "Поговори с Бат'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями." }, { 12.73, "Он опытный оружейник и могущественный шаман." }, { 16.19, "Если ты захочешь встретиться с Бат-ра, отправляйся к реке, что течёт вдоль восточного края мельницы Таррен." }, { 23.31, "Иди вдоль неё на север – Бат'ра разбил лагерь рядом с руинами на берегу реки." } }, f = { { 0.00, "Что ж, ты освоила стойку берсерка, теперь нужно подобрать тебе оружие." }, { 5.14, "Поговори с Бат'ра Ветростражем, троллем-отшельником, живущим между Альтеракскими горами и Западными Чумными землями." }, { 12.80, "Он опытный оружейник и могущественный шаман." }, { 16.26, "Если ты захочешь встретиться с Бат-ра, отправляйся к реке, что течёт вдоль восточного края мельницы Таррен." }, { 23.38, "Иди вдоль неё на север – Бат'ра разбил лагерь рядом с руинами на берегу реки." } } }, t = { d = 10.3, g = 1, v = "troll-male#77", n = { m = 107, f = 107 }, c = { m = { { 0.00, "Тебе пришлось проделать долгий путь, юный герой. Как у тебя горят глаза! Тебе ведь нужно мощное оружие?" }, { 7.35, "Я помогу тебе... в обмен на твою помощь." } }, f = { { 0.00, "Тебе пришлось проделать долгий путь, юная героиня. Как у тебя горят глаза! Тебе ведь нужно мощное оружие?" }, { 7.45, "Я помогу тебе... в обмен на твою помощь." } } } } },
    [1795] = { d = 22.9, g = 1, v = "human-male#50", n = { m = 265, f = 266 }, c = { m = { { 0.00, "Если ты готов, давай приступим. Начну с объяснений." }, { 3.81, "Сначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления." }, { 12.53, "Затем ты прочтёшь заклинание из фолианта Заговора, и на зов явится охотник Скверны. Будь осторожен." }, { 19.30, "Охотник Скверны – сильный враг, не теряй головы." } }, f = { { 0.00, "Если ты готова, давай приступим. Начну с объяснений." }, { 3.91, "Сначала мы создадим основной круг призыва. После этого мои послушники создадут больший круг при помощи жезлов направления." }, { 12.63, "Затем ты прочтёшь заклинание из фолианта Заговора, и на зов явится охотник Скверны. Будь осторожна." }, { 19.35, "Охотник Скверны – сильный враг, не теряй головы." } } }, t = { d = 9.8, v = "human-male#50", n = { x = 116 }, c = { x = { { 0.00, "Впечатляюще. Когда я сражался с охотником скверны, то едва выжил." }, { 4.41, "Предчувствую, что ты станешь одним из сильнейших чернокнижников нашей эры." } } } } },
    [1798] = { d = 18.5, v = "human-male#50", n = { x = 218 }, c = { x = { { 0.00, "Пришло время научить тебя вызывать охотника скверны." }, { 3.49, "Здесь у меня нет ни реагентов, ни предметов, необходимых для обучения, так что придётся тебе найти другого учителя – Страхада Фарсана." }, { 12.86, "Он проживает в гоблинском порту Кабестане. Я извещу его о том, что ты появишься." } } }, t = { d = 15.6, g = 1, v = "human-male#50", n = { x = 151 }, c = { m = { { 0.00, "путник? Ах да, конечно. Наше новое чудо. Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни." }, { 7.38, "Впрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой." } }, f = { { 0.00, "путница? Ах да, конечно. Наше новое чудо. Но, боюсь, настоящее чудо вряд ли успеет стать легендой при жизни." }, { 8.93, "Впрочем, неважно – ты здесь для того, чтобы пройти обучение, а не слушать, как я шучу сам с собой." } } } } },
    [1801] = { d = 30.2, v = "human-male#50", n = { x = 364 }, c = { x = { { 0.00, "Простой круг призыва не поможет тебе вызвать на бой охотника Скверны." }, { 4.98, "Я и трое моих послушников поможем тебе создать магические круги." }, { 9.47, "Тебе также понадобится фолиант Заговора, который мы давно утратили." }, { 13.96, "Его написала первая группа чернокнижников, умудрившихся вызвать охотника Скверны без посторонней помощи." }, { 21.40, "С этим тебе поможет Йорах Аннисон. Он работает в Подгороде картографом, но всё равно знает о древних текстах куда больше моего." } } }, t = { d = 18.7, v = "scourge-male#83", n = { x = 196 }, c = { x = { { 0.00, "Картография! Картинки, далёкие от реальности. Они мне не нужны." }, { 5.06, "Книги – повествование, описание! В них и только в них следует искать правду." }, { 10.59, "Я обменял бы все свои карты на одну книгу о возвышении некромантии или сагу о торжестве Тёмной Госпожи." } } } } },
    [1802] = { d = 38.8, v = "dwarf-male", n = { x = 448 }, c = { x = { { 0.00, "Он был утрачен, но есть кое-какие соображения насчёт того, где он может находиться сейчас." }, { 6.61, "С него сделали только одну копию и отнеслись к ней совершенно по-варварски: большая часть книги была вырвана из переплёта." }, { 14.90, "Ходят слухи, что она каким-то образом попала в руки одного кентавра из Тысячи Игл." }, { 20.83, "Остальное было утрачено в прибрежных краях к западу от Южнобережья, откуда книгу должны были переправить морем в Гавань Менетилов. Судно так и не прибыло." }, { 31.64, "А за мои сведения я попрошу одно: когда найдёшь книгу, дай мне заглянуть в неё хотя бы одним глазком." } } }, t = { d = 19.2, v = "dwarf-male", n = { x = 199 }, c = { x = { { 0.00, "С ума сойти! Теперь я один из немногих, что сумел хоть мельком заглянуть в неё." }, { 5.76, "Не терпится повнимательнее изучить этот текст. Какой великий день! Позволь мне ещё раз заглянуть в неё прежде, чем уйдёшь." }, { 15.68, "Уверен, что Страхад охотно пришлёт мне копию." } } } } },
    [1803] = { d = 34.4, v = "scourge-male#83", n = { x = 373 }, c = { x = { { 0.00, "А! Вижу, наши вкусы сходятся. Поиски фолианта Заговора – достойное занятие." }, { 5.49, "Знаешь ли ты, что он некогда хранился в стенах Лордерона? Правда, эти варвары поглумились над ним, вырвали больше половины страниц. Кто мог совершить такую мерзость?" }, { 17.77, "Итак, половина потеряна, хотя говорят, будто она попала в руки кентавров из Тысячи Игл." }, { 24.48, "Остальную часть должны были перевезти в Стальгорн, но она потерялась при перевозке где-то на берегу озера к западу от Южнобережья." } } }, t = { d = 12.6, v = "scourge-male#83", n = { x = 121 }, c = { x = { { 0.00, "Так-так-так! Что это у нас?" }, { 2.51, "Невероятно. Я был уверен, что это невозможно, но вот я держу в руках фолиант Заговора." }, { 9.18, "Позволь мне полистать его, пока ты не ушёл." } } } } },
    [1804] = { d = 32.8, g = 1, v = "dwarf-male", n = { m = 368, f = 368 }, c = { m = { { 0.00, "Как же не хочется его выпускать из рук! Но ты его нашёл и, конечно же, свершишь при его помощи куда более важные дела." }, { 8.12, "Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию." }, { 13.77, "Пока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления." }, { 22.34, "Он-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!" } }, f = { { 0.00, "Как же не хочется его выпускать из рук! Но ты его нашла и, конечно же, свершишь при его помощи куда более важные дела." }, { 8.14, "Только, сделай милость, не забудь сказать Страхаду, что я хочу получить копию." }, { 13.78, "Пока тебя не было, он прислал для тебя письмо. Он пишет, что для призыва духов необходимо достать три жезла направления." }, { 22.35, "Он-то не знает, где их искать, но зато я знаю! Последний раз их использовали орки клана Драконьей Пасти в Болотине. Я бы поискал у их заклинателей!" } } }, t = { d = 10.9, v = "human-male#50", n = { x = 129 }, c = { x = { { 0.00, "Отлично! Фолиант Заговора и три практически нетронутых жезла направления." }, { 5.36, "Забавно выходит. Давно молодые чернокнижники не приручали охотников Скверны." } } } } },
    [1805] = { d = 36.6, g = 1, v = "scourge-male#83", n = { m = 383, f = 384 }, c = { m = { { 0.00, "Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет." }, { 6.89, "Выбор здесь небогат – большинство книг посвящено географии, и я всё до дыр зачитал. Надеюсь, Страхад пришлёт мне копию." }, { 16.83, "Кстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления." }, { 26.14, "В благодарность за то, что ты дал мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине." } }, f = { { 0.00, "Это один из самых интересных текстов, что мне приходилось изучать за последние несколько лет." }, { 6.89, "Выбор здесь небогат – большинство книг посвящено географии, и я всё до дыр зачитал. Надеюсь, Страхад пришлёт мне копию." }, { 16.83, "Кстати, он прислал весточку, пока тебя не было. Чтобы выполнить очередную задачу, тебе понадобится три жезла направления." }, { 26.14, "В благодарность за то, что ты дала мне взглянуть на этот текст, открою тайну: жезлы можно найти у орков клана Драконьей Пасти в Болотине." } } }, t = { d = 10.9, v = "human-male#50", n = { x = 129 }, c = { x = { { 0.00, "Отлично! Фолиант Заговора и три практически нетронутых жезла направления." }, { 5.37, "Забавно выходит. Давно молодые чернокнижники не приручали охотников Скверны." } } } } },
    [1806] = { d = 26.1, g = 1, v = "human-male", n = { m = 284, f = 285 }, c = { m = { { 0.00, "Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займёт." }, { 9.12, "Когда всё будет закончено, ты будешь гораздо лучше подготовлен к защите дела Света, уж за это я ручаюсь." }, { 16.67, "Не утаю, я даже немного завидую твоим деяниям." }, { 19.91, "Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня." } }, f = { { 0.00, "Почему бы нам не пойти прямо в кузню и не начать работу? Я уже ждал тебя и подготовился, так что времени это много не займёт." }, { 9.12, "Когда всё будет закончено, ты будешь гораздо лучше подготовлена к защите дела Света, уж за это я ручаюсь." }, { 16.72, "Не утаю, я даже немного завидую твоим деяниям." }, { 19.96, "Но осознание того, что я по-своему помогу тебе, и немало помогу, всё же радует меня." } } }, t = { d = 19.8, v = "human-male", n = { x = 221 }, c = { x = { { 0.00, "Вот оно. Оружие, достойное защитника Света вроде тебя. Я дал ему имя в честь великого дворфского паладина, моего друга." }, { 8.40, "Его звали Вериган... Бош Вериган. Прошу, прими его в благодарность от меня и моей жены. Мы очень обязаны тебе." }, { 15.90, "Мир станет лучше, если по земле ходят такие, как ты!" } } } } },
    [1818] = { d = 20.0, v = "scourge-male", n = { x = 199 }, c = { x = { { 0.00, "Мне сказали, что у стража смерти Диллинджера есть работа для таких, как ты." }, { 5.71, "Если ты хочешь доказать свою ценность Тёмной Госпоже, немедленно отправляйся к нему." }, { 12.94, "Страж смерти Диллинджер стоит на посту в западном конце Брилла, рядом с кладбищем." } } }, t = { d = 13.5, v = "scourge-male", n = { x = 115 }, c = { x = { { 0.00, "Ты хочешь получить задание? Отлично. У меня есть одно. Довольно важное. Заодно и свою силу нам покажешь..." }, { 10.03, "И решимость защищать дело Отрёкшихся." } } } } },
    [1819] = { d = 39.2, g = 1, v = "scourge-male", n = { m = 391, f = 392 }, c = { m = { { 0.00, "Когда Тирисфальские луга наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению." }, { 8.10, "Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич." }, { 17.05, "Мы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его. Для этого его придётся убить." }, { 28.88, "Воспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы. Сними их и... будь готов!" } }, f = { { 0.00, "Когда Тирисфальские луга наводнили воины Плети, мы поймали одного из них и подвергли пристальному изучению." }, { 8.10, "Он обладал свободной волей и звал себя Улаг Колун. Впрочем, несмотря на свободу воли, его подчинил себе Король-лич." }, { 17.05, "Мы надеялись избавить Улага от чар, но не смогли. Довольно ему томиться в темнице плоти. Освободи его. Для этого его придётся убить." }, { 28.88, "Воспользуйся переключателем в мавзолее к северу отсюда. Это позволит снять с Улага магические путы. Сними их и... будь готова!" } } }, t = { d = 13.7, v = "scourge-male", n = { x = 148 }, c = { x = { { 0.00, "Молодец. Улаг был серьёзным сторонником Плети." }, { 3.80, "Тебе удалось доказать стражам смерти и через них Тёмной Госпоже, что ты опытный и умелый воин и заслуживаешь дальнейшего обучения." } } } } },
    [1820] = { d = 17.7, v = "scourge-male", n = { x = 188 }, c = { x = { { 0.00, "Тебе удалось услужить Тёмной Госпоже, пришло время услужить одному из её подданных." }, { 6.57, "Колману Фартингу нужен воин, который сможет отомстить врагам Отрёкшихся." }, { 12.37, "Коулман сидит в таверне \"Петля висельника\", в восточной части Брилла." } } }, t = { d = 16.7, v = "scourge-male#82", n = { x = 143 }, c = { x = { { 0.00, "Да, это правда. Мне нужна помощь закалённого воина." }, { 4.83, "Средств у меня немного, зато ты послужишь не только мне, но и делу Отрёкшихся. Так что если ты справишься, наградой будет почёт." } } } } },
    [1821] = { d = 35.2, v = "scourge-male#82", n = { x = 303 }, c = { x = { { 0.00, "При жизни я служил семье Агамондов, и именно из-за них и умер!" }, { 5.80, "Поделом им, они стали теперь безмозглыми прислужниками Короля-лича." }, { 12.43, "Мне же хочется лишить их остатков чести." }, { 16.20, "Ступай в Семейную усыпальницу Агамондов и принеси их фамильное оружие: меч, топор, кинжал и палицу." }, { 25.71, "Склеп находится севернее мельниц Агамондов. Его стерегут бойцы Плети и сами неупокоенные Агамонды." } } }, t = { d = 12.3, v = "scourge-male#82", n = { x = 91 }, c = { x = { { 0.00, "А! Вот оно! Итак, проклятые земли Агамондов лишены остатков чести и памяти. Отныне семьи воистину не существует!" } } } } },
    [1823] = { d = 15.1, v = "orc-male#60", n = { x = 163 }, c = { x = { { 0.00, "Ты уже опытный воин, и имя твоё на слуху у многих. Может быть, ты хочешь пройти испытание Руги Тотэма Гнева?" }, { 7.57, "Коли так, отправляйся в Лагерь Таурахо, в Степи." }, { 11.28, "Он ждёт всех воинов, что готовы принять его вызов." } } }, t = { d = 2.4, v = "tauren-male", n = { x = 23 }, c = { x = { { 0.00, "Ты хочешь пройти испытание?" } } } } },
    [1824] = { d = 31.3, v = "tauren-male", n = { x = 301 }, c = { x = { { 0.00, "Чтобы пройти это испытание, тебе придётся отправиться на юг, к Полям Великанов." }, { 6.07, "Там ты встретишь полчища ползучих существ, похожих на насекомых. Они явились в Степи незванными, и мне они совсем не нравятся." }, { 17.41, "Принеси их усики. Главное, чтобы они всё ещё дёргались, поэтому тебе придётся поторопиться." }, { 25.21, "Добудь мне усики за отведённое время, и я сочту, что испытание пройдено." } } }, t = { d = 10.9, g = 1, v = "tauren-male", n = { m = 83, f = 83 }, c = { m = { { 0.00, "Отличная работа! Ты прошёл испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина." } }, f = { { 0.00, "Отличная работа! Ты прошла испытание на Полях Великанов, сделав тем самым ещё один шаг по тропе воина." } } } } },
    [1825] = { d = 20.7, v = "tauren-male", n = { x = 203 }, c = { x = { { 0.00, "Слухи о твоих доблестных подвигах во славу Орды дошли до знаменитого орочьего кузнеца, Тун'грима Огневзора." }, { 9.21, "Он хотел бы сделать для тебя доспехи, но тебе надо как можно скорее с ним встретиться." }, { 16.08, "Тун'грим живёт на востоке от Перекрёстка, что в Степях." } } }, t = { d = 4.5, g = 1, v = "orc-male#60", n = { m = 48, f = 48 }, c = { m = { { 0.00, "Да, ты пришёл. Отлично, нам с тобой многое придётся обсудить." } }, f = { { 0.00, "Да, ты пришла. Отлично, нам с тобой многое придётся обсудить." } } } } },
    [1838] = { d = 29.4, v = "orc-male#60", n = { x = 334 }, c = { x = { { 0.00, "Я наслышан о твоей силе и доблести и хочу сделать для тебя броню, которая охранит тебя в бесчисленных сражениях." }, { 8.23, "Впрочем, создание такой брони – само по себе подвиг. Мне понадобится твоя помощь, а также помощь других кузнецов Орды." }, { 16.70, "Возьми этот список. Я составлял его не одну ночь, напряжённо вглядываясь в пергамент почти незрячими глазами." }, { 24.36, "Принеси мне всё перечисленное, и я создам тебе первую часть доспеха." } } }, t = { d = 4.0, g = 1, v = "orc-male#60", n = { m = 37, f = 39 }, c = { m = { { 0.00, "Ты принёс всё, что я просил. Теперь дело за мной..." } }, f = { { 0.00, "Ты принесла всё, что я просил. Теперь дело за мной..." } } } } },
    [1839] = { d = 15.1, v = "orc-male#60", n = { x = 170 }, c = { x = { { 0.00, "Кузнец-тролль по имени Ула'елек готов выковать для тебя рукавицы жестокости." }, { 5.91, "Он живёт в Дуротаре, в деревне Сен'джин, вместе со своими собратьями из племени Чёрного Копья, и с нетерпением ждёт твоего прихода." } } }, t = { d = 15.4, v = "troll-male#77", n = { x = 166 }, c = { x = { { 0.00, "Привет тебе. Старый Тунгрим предупредил меня о твоём приходе, но умолчи он, я не удивился бы твоему появлению." }, { 8.55, "Духи следят за каждым твоим шагом, юный воин, и они говорят, что от твоей руки пало немало врагов." } } } } },
    [1840] = { d = 13.2, v = "orc-male#60", n = { x = 150 }, c = { x = { { 0.00, "Искусство Орма Каменного Копыта пользуется заслуженным уважением. Он и сделает тебе шлем Жестокости." }, { 7.41, "Его можно найти в Громовом Утёсе, рядом с прудом и центральным тотэмом города." } } }, t = { d = 6.0, v = "tauren-male", n = { x = 56 }, c = { x = { { 0.00, "Привет тебе, воин. Я Орм. Тунгрим сказал, что тебе нужен шлем. Это правда?" } } } } },
    [1841] = { d = 19.7, v = "orc-male#60", n = { x = 205 }, c = { x = { { 0.00, "Говорят, что при жизни Велора Нители была одним из лучших кузнецов Лордерона. Кажется, она и после смерти не лишилась таланта." }, { 9.52, "Поговори с Велорой, она сделает тебе набедренники Жестокости." }, { 14.46, "Велора трудится в Подгороде Лордерона, в торговом квартале." } } }, t = { d = 20.4, v = "scourge-female", n = { x = 159 }, c = { x = { { 0.00, "Тебе нужны набедренники? Отлично!" }, { 3.45, "Хм... Тогда кто из нас будет их делать?" }, { 7.77, "Шутка. Смешно? Я вот не понимаю... Чувство юмора я утратила одновременно с обонянием. Примерно в те времена, как перестала дышать." } } } } },
    [1842] = { d = 34.4, v = "troll-male#77", n = { x = 395 }, c = { x = { { 0.00, "Я могу сделать для тебя пару рукавиц Жестокости, напитав их магической силой. Но прежде тебе придётся добыть эту самую силу." }, { 8.93, "В северо-восточной части Ясеневого леса живут сатиры. Их привлекла туда сила леса." }, { 15.58, "Они питаются его первозданной чистотой, искажая и оскверняя её." }, { 19.98, "Сатиров, вобравших в себя особенно много магии Ясеневого леса можно отличить от других по разбухшим, нераздвоенным копытам." }, { 28.51, "В этих копытах содержится великая сила. Они понадобятся мне для создания рукавиц." } } }, t = { d = 6.1, v = "troll-male#77", n = { x = 68 }, c = { x = { { 0.00, "Ага, вот и они! Сатиры похитили силу Ясеневого леса, а их сила вольётся в моё творение..." } } } } },
    [1844] = { d = 36.6, g = 1, v = "tauren-male", n = { m = 355, f = 356 }, c = { m = { { 0.00, "Я сделаю тебе шлем, но прежде докажи, что достоин его." }, { 4.71, "В северной части Когтистых гор лежит Обугленная долина." }, { 9.04, "Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния. Туда тебе и придётся отправиться." }, { 23.17, "Ступай в Обугленную долину и найди там химеру-матриарха. Избавь её от страданий." }, { 29.46, "Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем." } }, f = { { 0.00, "Я сделаю тебе шлем, но прежде докажи, что достойна его." }, { 5.09, "В северной части Когтистых гор лежит Обугленная долина." }, { 9.42, "Некогда она была цветущей рощей, но теперь от деревьев остался лишь пепел, а все живущие там существа исполнены боли и отчаяния. Туда тебе и придётся отправиться." }, { 23.66, "Ступай в Обугленную долину и найди там химеру-матриарха. Избавь её от страданий." }, { 29.95, "Принеси в доказательство её гибели гальванизированный рог, и я сделаю тебе шлем." } } }, t = { d = 9.7, g = 1, v = "tauren-male", n = { m = 79, f = 80 }, c = { m = { { 0.00, "Что же, задание выполнено. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужил шлем..." } }, f = { { 0.00, "Что же, задание выполнено. Теперь я не сомневаюсь в твоей решимости и храбрости. Ты заслужила шлем..." } } } } },
    [1846] = { d = 27.4, v = "scourge-female", n = { x = 247 }, c = { x = { { 0.00, "Чтобы создать набедренники Жестокости, мне понадобятся прочные берцовые кости. У орков из клана Драконьей Пасти крепкие ноги. Они-то мне и нужны." }, { 13.10, "Но только самые прочные. Непременно проверь их, прежде чем счесть подходящими." }, { 20.16, "Если ты сможешь сломать их голыми руками, значит, они не достаточно прочные." } } }, t = { d = 17.8, g = 1, v = "scourge-female", n = { m = 123, f = 122 }, c = { m = { { 0.00, "Молодец! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались? Опять я пошутила. Ты не смеёшься." }, { 14.03, "Что-то у меня не так с чувством юмора..." } }, f = { { 0.00, "Умница! На вид они крепкие. Пожалуй, подойдут. Орки не возражали? Сильно жаловались? Опять я пошутила. Ты не смеёшься." }, { 12.93, "Что-то у меня не так с чувством юмора..." } } } } },
    [1858] = { d = 22.7, v = "orc-male#60", n = { x = 249 }, c = { x = { { 0.00, "Загляни в сумку Тазана и принеси мне то, что найдёшь внутри. Замок там непростой, так что постарайся раздобыть ключ." }, { 8.44, "На трупе Тазана ключа не было? Значит, он его кому-то отдал... Ах, ну да, конечно. У него был помощник, Гамон." }, { 15.93, "Он пьяница, так что ищи его в тавернах. Возможно, тебе удастся потихоньку утащить у него ключ." } } }, t = { d = 12.6, g = 1, v = "orc-male#60", n = { m = 142, f = 143 }, c = { m = { { 0.00, "Так-так, интересно... Что ж, ты полностью оправдал моё доверие. Отныне можешь считать себя членом клана Изувеченной Длани." }, { 8.34, "И возьми это. Думаю, он тебе очень пригодится в будущем." } }, f = { { 0.00, "Так-так, интересно... Что ж, ты полностью оправдала моё доверие. Отныне можешь считать себя членом клана Изувеченной Длани." }, { 8.38, "И возьми это. Думаю, он тебе очень пригодится в будущем." } } } } },
    [1859] = { d = 22.5, v = "orc-male", n = { x = 241 }, c = { x = { { 0.00, "Говори тише! Ну да, я знаю твоё имя. Мне сказали, чтобы я ждал одного орка, и дали описание твоей внешности." }, { 8.01, "Судя по тому, что о тебе рассказывают, ты неплохо держишься в открытом бою, но можешь прибегнуть и к хитрости, верно?" }, { 16.40, "В общем, сходи в Оргриммар, поговори с Терзоком. У него есть для тебя предложение." } } }, t = { d = 11.7, v = "orc-male#60", n = { x = 121 }, c = { x = { { 0.00, "А, это ты! Очень хорошо, что Каплак сумел тебя перехватить." }, { 4.92, "Нам нужно поговорить кое о чём, не в последнюю очередь – о твоём будущем в Раздробленной Руке." } } } } },
    [1860] = { d = 15.4, v = "human-male", n = { x = 175 }, c = { x = { { 0.00, "У нас, магов, есть одна задача, которая жизненно важня для безопасности Штормграда и Элвиннского леса." }, { 7.35, "Подробности ты можешь узнать у Джиннии Пушки. Она работает в Башне магов, в районе магов в Штормграде. Не мешкай." } } }, t = { d = 12.9, v = "human-female#47", n = { x = 148 }, c = { x = { { 0.00, "Тебя послали мне на подмогу? Хорошо. Приятно видеть, что молодые маги рады внести свой вклад в общее дело…" }, { 7.38, "Какое дело, спросишь ты? Вырастешь – узнаешь. Обязательно узнаешь... со временем." } } } } },
    [1861] = { d = 31.9, v = "human-female#47", n = { x = 388 }, c = { x = { { 0.00, "Этот мир пал жертвой магических войн, в результате которых нарушилось течение магической энергии." }, { 6.59, "Мы попытались просчитать дальнейшие последствия, и многие из нас опасаются худшего!" }, { 12.52, "Но об этом мы поговорим позже. Для начала надо собрать все доступные сведения." }, { 18.01, "Возьми этот сосуд, отправляйся к подножию водопада у Зеркального озера, что на юго-западе от Врат Штормграда, и принеси мне пробу тамошней воды." }, { 27.57, "Я хочу исследовать её на предмет заражения тлетворной магией." } } }, t = { d = 20.0, v = "human-female#47", n = { x = 235 }, c = { x = { { 0.00, "Спасибо. Я исследую магические свойства этой воды." }, { 3.48, "Будем надеяться, что их не окажется, а то, неровен час, окажется, что магия повлияла на всех, кто пил много воды из Зеркального озера." }, { 12.49, "Возьми эту сферу или этот посох в знак моей благодарности за услугу. Пускай они служат тебе верой и правдой." } } } } },
    [1879] = { d = 20.5, g = 1, v = "gnome-male", n = { m = 222, f = 223 }, c = { m = { { 0.00, "путник! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку." }, { 4.65, "У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты готов ей помочь?" }, { 13.46, "Если да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна." } }, f = { { 0.00, "путница! Бинк, моя коллега-гном из Стальгорна, прислала мне весточку." }, { 4.83, "У неё возникла небольшая проблема, а обращаться за помощью ни к кому, кроме мага, она не хочет. Ты готова ей помочь?" }, { 13.03, "Если да, то поговори с ней. Бинк проводит большую часть времени в Зале Тайн в Палатах Магии Стальгорна." } } }, t = { d = 17.3, v = "gnome-female#41", n = { x = 180 }, c = { x = { { 0.00, "О, я вижу в тебе неплохие задатки, да-да! Но чтобы стать хорошим магом, одних задатков мало." }, { 6.10, "А не сликшом хороший маг – плохой маг. А из-за плохих магов и возникают все проблемы!" }, { 13.36, "Ой, кажется, я немного забегаю вперёд. Начнём сначала!" } } } } },
    [1880] = { d = 36.8, v = "gnome-female#41", n = { x = 410 }, c = { x = { { 0.00, "Мы, маги, не просто щёлкаем пальчиками и создаём забавные искорки!" }, { 4.50, "Мы контролируем поток магической энергии, основной ткани мироздания! Для этого требуется осторожность и решимость. И знания... Невероятно много знаний!" }, { 14.99, "Одно из моих устройств, маг-тастический гизмонитор, позволяет собирать и хранить множество знаний! Но увы, он утрачен!" }, { 23.13, "Когда мы бежали из Гномрегана, я оставила его в сундуке в одном из домишек за пределами города. Теперь там кишмя кишат лепрогномы! Прошу тебя, верни мне гизмонитор!\"" } } }, t = { d = 22.1, v = "gnome-female#41", n = { x = 251 }, c = { x = { { 0.00, "О, радость! Создавая гизмонитор, я и не догадывалась, в какую зависимость от него попаду!" }, { 6.60, "Теперь я могу возобновить свои исследования." }, { 9.82, "Спасибо! Вот, смотри. Это мой первый набор магических инструментов. Они не так блестят, как новые, зато проверены временем." }, { 18.13, "Выбирай любой из них – все они могут тебе пригодиться." } } } } },
    [1881] = { d = 13.3, v = "scourge-male#83", n = { x = 145 }, c = { x = { { 0.00, "У Анастасии Хартвелл есть задание, которое тебе как раз по плечу. Поговори с ней. Она живёт в квартале магов в Подгороде." }, { 8.85, "Готовься выполнить первое задание для магов Отрёкшихся." } } }, t = { d = 9.6, g = 1, v = "scourge-female", n = { m = 83, f = 84 }, c = { m = { { 0.00, "Привет тебе. Ты правильно поступил, откликнувшись на мой зов, но ещё правильнее будет меня выслушать..." } }, f = { { 0.00, "Привет тебе. Ты правильно поступила, откликнувшись на мой зов, но ещё правильнее будет меня выслушать..." } } } } },
    [1882] = { d = 35.2, v = "scourge-female", n = { x = 314 }, c = { x = { { 0.00, "Чумные земли – гнусное место, творение Короля-лича. Он отравил землю, осквернил и убил всё живое." }, { 8.45, "Хотя в убийственной силе чумы есть что-то привлекательное, мы, маги Отрёкшихся, считаем её неуправляемой и недопустимой." }, { 19.27, "Для начала надо понять, проникла ли она в Тирисфаль. Отправляйся на ферму Балнира в восточной части Тирисфаля." }, { 29.07, "В саду растут цветы – львиный зев. Собери их и возвращайся." } } }, t = { d = 22.0, v = "scourge-female", n = { x = 170 }, c = { x = { { 0.00, "Отличные цветы. Я отправлю их на изучение нашим аптекарям. Пусть поищут в них скверну Проклятых земель." }, { 10.64, "Молодец. Я предлагаю тебе выбрать награду – сферу или посох. И то, и другое может тебе здорово пригодиться." } } } } },
    [1883] = { d = 18.8, v = "troll-male", n = { x = 178 }, c = { x = { { 0.00, "Ун'Тува, маг деревни Сен'джин, обнаружил изменения в потоках магической энергии Дуротара и просит тебя о помощи." }, { 9.28, "Поговори с ним и сделай всё, что сможешь." }, { 13.00, "Приди к нему на помощь, и со временем тебе откроются великие тайны." } } }, t = { d = 10.6, g = 1, v = "troll-male", n = { m = 84, f = 85 }, c = { m = { { 0.00, "Привет тебе. Хвала тебе, ибо ты ответил на мой зов о помощи. Будем надеяться, что ты справишься с заданием..." } }, f = { { 0.00, "Привет тебе. Хвала тебе, ибо ты ответила на мой зов о помощи. Будем надеяться, что ты справишься с заданием..." } } } } },
    [1884] = { d = 34.9, v = "troll-male", n = { x = 342 }, c = { x = { { 0.00, "Оказывается, нормальное течение магической энергии в Дуротаре нарушил чернокнижник Залазан с островов Эха." }, { 9.49, "Для этого он разместил осквернённые фетиши, груды джуджу, среди домов центрального острова Эха." }, { 17.65, "Из-за этого болеет здешнее зверьё, а чернокнижники и пришельцы из преисподней, таящиеся во тьме, набираются силы." }, { 27.17, "Необходимо уничтожить эти груды джуджу, прежде чем наши земли изменятся до неузнаваемости." } } }, t = { d = 17.9, v = "troll-male", n = { x = 168 }, c = { x = { { 0.00, "Я чувствую, что груды джуджу уничтожены." }, { 3.40, "При удаче все труды Залазана пойдут насмарку и в Дуротаре восстановится нормальное течение магической энергии." }, { 13.57, "Твой подвиг во имя Орды достоин всяческой хвалы!" } } } } },
    [1885] = { d = 25.1, g = 1, v = "scourge-female", n = { x = 213 }, c = { m = { { 0.00, "путник? Вот уж не ожидал вас увидеть после того, как вами заинтересовался сам Каркад. Ничего нельзя сказать наперёд..." }, { 10.68, "В любом случае, вам лучше встретиться с ним, и поскорее." }, { 15.86, "Лучше вам не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него." } }, f = { { 0.00, "путница? Вот уж не ожидал вас увидеть после того, как вами заинтересовался сам Каркад. Ничего нельзя сказать наперёд..." }, { 10.88, "В любом случае, вам лучше встретиться с ним, и поскорее." }, { 16.06, "Лучше вам не знать, что стало с теми несколькими глупцами, которые проигнорировали вызов от него." } } }, t = { d = 10.6, v = "scourge-male#82", n = { x = 92 }, c = { x = { { 0.00, "Хм. Несомненно, вы пришли сюда по первому моему зову, так? Не ожидал ничего иного от перспективного стража смерти." } } } } },
    [1886] = { d = 43.4, v = "scourge-male#82", n = { x = 359 }, c = { x = { { 0.00, "Чтобы вступить в ряды стражей смерти, элитной охраны лорда Вариматраса, тебе придётся сперва доказать свои способности." }, { 11.15, "Не буду лгать: это задание может окончиться твоей гибелью." }, { 17.03, "Мне нужна помощь в нескольких вопросах." }, { 20.68, "Во-первых, принеси мне личные вещи Астора Хадрена – это вестник, путешествующий между Серебряным бором и Подгородом." }, { 33.15, "Как ты это сделаешь - тебе решать." }, { 36.67, "Пока что это всё, что тебе следует знать. Справишься - узнаешь больше." } } }, t = { d = 15.1, v = "scourge-male#82", n = { x = 130 }, c = { x = { { 0.00, "Неплохо. Первая часть испытания пройдена." }, { 3.90, "Надеюсь, Андрон ничего не узнал о твоих действиях, и ты сможешь убедить его, что ты и есть тот вестник, которого он ждёт." } } } } },
    [1898] = { d = 41.7, v = "scourge-male#82", n = { x = 370 }, c = { x = { { 0.00, "Рекомендательное письмо должно убедить Андрона, что ты – тот самый гонец, которого он ждал." }, { 8.29, "Мне приходилось встречаться с Андроном, он не настолько умён, чтобы заподозрить неладное." }, { 16.90, "Лорд Вариматрас подозревает, что Андрон тайно помогает другой группировке, и тебе предстоит выяснить, какой именно." }, { 27.24, "Хорошо бы также получить доказательства." }, { 31.44, "Поговори с Андроном и вытяни из него эти сведения. Его можно найти в лавке неподалёку от Района Фармацевтов." } } }, t = { d = 15.3, v = "scourge-male#83", n = { x = 162 }, c = { x = { { 0.00, "Ах да, я ждал тебя. Полагаю, наши общие знакомые довольны переданными сведениями?" }, { 6.24, "Боюсь, тебя спрашивать без толку, вряд ли тебя обременяют лишними знаниями. К чему доверять гонцу слишком много тайн?" } } } } },
    [1899] = { d = 20.0, v = "scourge-male#83", n = { x = 223 }, c = { x = { { 0.00, "Гроссбух с необходимой твоим нанимателям информацией стоит на книжной полке за моей спиной." }, { 6.87, "Передай его заказчикам вместе с поклоном от меня и сообщи, что, если они оценят полученные сведения и захотят продолжить наше сотрудничество, я предпочёл бы иметь дело с тобой." } } }, t = { d = 13.5, v = "scourge-male#82", n = { x = 115 }, c = { x = { { 0.00, "Ну и ну, я и не рассчитывал вытянуть столько информации из Андрона." }, { 6.24, "Дай-ка я изучу этот гроссбух повнимательнее и дам тебе следующее задание." } } } } },
    [1918] = { d = 31.4, v = "human-male#114", n = { x = 306 }, c = { x = { { 0.00, "Из убитого элементаля выпала ярко светящаяся сфера воды. Содержимое шара в лучшем случае отвратительно." }, { 8.03, "Можно с уверенностью сказать, что то, что заразило воды озера Мистраль, находится в этой сфере." }, { 15.78, "Так сразу и не скажешь, кого может заинтересовать эта находка – возможно, подскажет тот, кто послал вас к этому озеру, а именно Мисток Райльшип с заставы Расщеплённого Древа." } } }, t = { d = 24.9, g = 1, v = "orc-male", n = { m = 269, f = 270 }, c = { m = { { 0.00, "Ты нашёл какой-то грязный шар с водой и решил принести его мне? Я кто, по-твоему – представитель Служителей Земли или что?" }, { 8.94, "Вообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли." }, { 16.06, "В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам." }, { 21.88, "Ты знаешь, кто такие Служители Земли?" } }, f = { { 0.00, "Ты нашла какой-то грязный шар с водой и решила принести его мне? Я кто, по-твоему – представитель Служителей Земли или что?" }, { 8.88, "Вообще-то, у меня появилась кое-какая идея... может, тебе и правда понадобится помощь Служителей Земли." }, { 16.00, "В смысле, если это поможет разрешить ситуацию на озере, то я к твоим услугам." }, { 21.81, "Ты знаешь, кто такие Служители Земли?" } } } } },
    [1919] = { d = 20.6, g = 1, v = "gnome-male", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Ты набираешься знаний и опыта, юный путник." }, { 2.96, "Ты готов приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?" }, { 9.60, "Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда." }, { 14.96, "У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." } }, f = { { 0.00, "Ты набираешься знаний и опыта, юная путница." }, { 3.13, "Ты готова приступить к подлинному обучению и принять участие в непрекращающейся тайной войне?" }, { 9.81, "Если да, поговори с Джиннией Пушкой в Башне магов в квартале магов Штормграда." }, { 15.16, "У неё есть для тебя задание, которое впервые приоткроет окно в невидимый мир." } } }, t = { d = 7.8, v = "human-female#47", n = { x = 91 }, c = { x = { { 0.00, "У меня есть для тебя задание. Да-да, прямо здесь, в квартале магов. Слушай внимательно, не будем терять время даром." } } } } },
    [1920] = { d = 27.7, v = "human-female#47", n = { x = 347 }, c = { x = { { 0.00, "Сообщают о беспорядках в таверне \"Синий отшельник\", что в квартале магов." }, { 4.59, "Там бродят странные невидимые существа, чувствую там образовался провал Маны." }, { 10.00, "Отправляйся туда и поймай этих тварей." }, { 12.62, "Чтобы они стали видимыми, воспользуйся заклятьем Проявления, одолей их и посади в шкатулки-духоловки." }, { 19.19, "Как только наберёшь достаточно этих тварей, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." } } }, t = { d = 12.2, g = 1, v = "human-female#47", n = { m = 127, f = 126 }, c = { m = { { 0.00, "Ну ты молодец! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир." }, { 8.86, "Ты приносишь сообществу магов всё больше пользы." } }, f = { { 0.00, "Ну ты умница! Я займусь изучением этих существ, и при удаче пойму, как они ухитрились пробраться в наш мир." }, { 7.46, "Ты приносишь сообществу магов всё больше пользы." } } } } },
    [1921] = { d = 34.5, v = "human-female#47", n = { x = 417 }, c = { x = { { 0.00, "За верную службу своим собратьям-магам тебе полагается одеяние волшебника." }, { 4.91, "Его вполне может сшить Уинн Ларсон, если ты принесёшь ей всё необходимое." }, { 10.17, "Само одеяние шьётся из льна, который легко найти, но кроме него понадобятся заряженные самоцветы Расселины, а их добывают исключительно в Руднике у Серебряного ручейка у озера Лок Модан." }, { 22.66, "Горняки дворфов не смогли забрать их, и они лежат в ящиках по всему руднику." }, { 28.06, "Набери льна, добудь самоцветы и принеси их Уинн Ларсон в суконную лавку Ларсона в район магов." } } }, t = { d = 9.7, v = "human-female#111", n = { x = 107 }, c = { x = { { 0.00, "Да, превосходный лён. Из него выйдет отличная ряса." }, { 3.85, "А после того, как я разошью её самоцветами, получится настоящее одеяние для мага!" } } } } },
    [1938] = { d = 30.4, v = "human-male", n = { x = 345 }, c = { x = { { 0.00, "Давным-давно в этой башне жили три мага, и один из них поддался искушению и занялся тёмными искусствами." }, { 7.28, "Его уговаривали отказаться от чёрной магии, но тщетно. И он был изгнан." }, { 12.63, "Новое пристанище изгнанного мага – башня Илгалара в Красногорье. Он унёс с собой ценную книгу – Трактат Ура по тёмной магии." }, { 21.41, "Мы, маги Штормграда, хотим вернуть себе эту книгу. Отправляйся в башню Илгалара, найди этот фолиант в библиотеке и принеси мне." } } }, t = { d = 13.5, v = "human-male", n = { x = 146 }, c = { x = { { 0.00, "Я опасался, что Моргант спрятал книгу где-то ещё или же нашёл способ открыть её и прочесть." }, { 6.75, "Хорошо, что он не успел, и что все печати, наложенные на этот трактат, сохранились в целости." } } } } },
    [1939] = { d = 17.4, v = "human-female#47", n = { x = 212 }, c = { x = { { 0.00, "С тобой хочет поговорить верховный колдун Андромат. Он находится на верхнем этаже Башни магов, в квартале магов Штормграда." }, { 8.45, "Обязательно поговори с ним, ведь Андромат – один из самых могущественных магов за пределами Даларана. Его совет стоит десяти других." } } }, t = { d = 5.9, v = "human-male", n = { x = 64 }, c = { x = { { 0.00, "Привет тебе. Рад тебя видеть. Надеюсь, у тебя найдётся время выслушать старика..." } } } } },
    [1940] = { d = 33.7, v = "human-male", n = { x = 400 }, c = { x = { { 0.00, "Пожалуй, следует наградить тебя за безупречную службу. Пора тебе обзавестить одеянием, которое пристало носить магу твоего уровня." }, { 9.00, "Если тебе удастся собрать все необходимые материалы, одеяние у тебя будет." }, { 14.49, "Ступай в Сумеречный лес и убей побольше пауков, падальщиков-отшельников. Набери их паутины, только учти, годится лишь самая лучшая." }, { 23.56, "Набрав достаточно паутины, отнеси её Уинн Ларсон, которой принадлежит магазин \"Суконная лавка Ларсона\" в Квартале Магов. Она сошьёт тебе одеяние." } } }, t = { d = 3.7, v = "human-female#111", n = { x = 41 }, c = { x = { { 0.00, "Неплохая паутина. Я немедленно примусь за работу!" } } } } },
    [1943] = { d = 7.4, v = "scourge-female", n = { x = 64 }, c = { x = { { 0.00, "Магу Дейно нужна твоя помощь. Она живёт в Оргриммаре, в пристанище Темнотёрна." } } }, t = { d = 12.1, v = "troll-female", n = { x = 124 }, c = { x = { { 0.00, "Хорошо, что ты здесь. Я хочу дать тебе довольно сложное задание. Оно жизненно важно для всего сообщества магов." }, { 8.46, "Помоги мне, и маги отплатят тебе сторицей." } } } } },
    [1944] = { d = 33.0, v = "troll-female", n = { x = 375 }, c = { x = { { 0.00, "В восточной части Ясеневого леса раскинулся прославенный город Ксавиан." }, { 5.14, "Учёные всех народов слышали легенды о хранимом в нём древнем знании. Говорят, что воды Ксавиана содержат немало магической энергии. Мне нужна проба воды из Ксавиана." }, { 16.89, "Возьми этот сосуд и ступай туда. Набери воды у подножия самого большого водопада и возвращайся ко мне." }, { 24.21, "Соблюдай осторожность – руины древнего города заполонили сатиры, им не нравится, когда в их дела встревают маги." } } }, t = { d = 10.7, v = "troll-female", n = { x = 109 }, c = { x = { { 0.00, "А, отлично. Надеюсь, сатиры Ксавиана тебе не слишком сильно помешали?" }, { 6.02, "Спасибо. Я немедленно займусь изучением пробы воды из Ксавиана." } } } } },
    [1945] = { d = 24.3, v = "troll-female", n = { x = 263 }, c = { x = { { 0.00, "За верную службу тебе полагается новое одеяние, если ты принесёшь все необходимые материалы." }, { 6.83, "Тебе придётся вернуться в Ясеневый лес за локонами волос Смеющихся сестёр – дриад, бродящих возле Приюта в Ночных Лесах." }, { 16.25, "Добыв их волосы, отнеси их Кил'хале, троллю-портному с Перекрёстка, что в Степях. Он-то и сошьёт тебе одеяние." } } }, t = { d = 15.6, v = "troll-male", n = { x = 141 }, c = { x = { { 0.00, "А, из этих волос выйдет отличное одеяние." }, { 3.37, "Жаль, что приходится убивать Смеющихся сестёр ради добычи волос, впрочем, добровольно они их всё равно не отдали бы. Жаль, но не очень." } } } } },
    [1950] = { d = 25.9, v = "human-male", n = { x = 283 }, c = { x = { { 0.00, "Я помогу тебе с книгой, но сначала окажи мне услугу!" }, { 4.07, "Нужная тебе книга заодно и магический сейф. Он открывается особой фразой, и её-то я и забыл!" }, { 10.59, "Обычно мне напоминает помощник, но он куда-то запропал." }, { 14.78, "Если тебе нужна книга, найди моего помощника! Поспрашивай у зрителей, при удаче кто-то мог его видеть." }, { 21.90, "Притащи его сюда или выбей из него волшебные слова!" } } }, t = { d = 9.6, v = "human-male", n = { x = 99 }, c = { x = { { 0.00, "Ах да, припоминаю…" }, { 1.67, "Я и правда наложил на Джонсона проклятье. Не помню, зачем я это сделал, но так ему и надо, маленькому нахалу!" } } } } },
    [1959] = { d = 19.2, v = "troll-male", n = { x = 193 }, c = { x = { { 0.00, "Маги Подгорода заметили в городе выплеск магической энергии и обратились к чародеями Орды с просьбой выяснить, что же происходит." }, { 10.73, "Подробности тебе расскажет Анастасия Хартвелл. Поговори с ней, она живёт в Квартале Магов Подгорода." } } }, t = { d = 19.1, v = "scourge-female", n = { x = 155 }, c = { x = { { 0.00, "Это правда. В нашем городе произошёл выплеск магической энергии." }, { 7.00, "Мы не поняли, что именно произошло, и даже к добру это или к худу. Не хватает информации…" }, { 15.28, "Что подводит нас к разговору о задании." } } } } },
    [1960] = { d = 38.0, v = "scourge-female", n = { x = 346 }, c = { x = { { 0.00, "В лавке алхимика Алжернона, что в Районе Фармацевтов, происходит что-то странное." }, { 7.30, "Там бродят странные невидимые существа, сотканные из магической энергии." }, { 14.29, "Возьми у меня за спиной шкатулки-духоловки и свиток с нужным заклинанием." }, { 20.96, "Воспользуйся свитком в лавке, подчини этих существ и загони их в шкатулки." }, { 27.77, "Как только наберёшь достаточно, возвращайся ко мне с заполненными шкатулками, пустыми шкатулками и заклинанием." } } }, t = { d = 31.8, v = "scourge-female", n = { x = 273 }, c = { x = { { 0.00, "Отлично. Лучшие умы Подгорода займутся изучением невидимых тварей. Мы выясним, откуда они взялись в нашем городе." }, { 10.35, "Если дело в возникновении провала Маны, потребуется определить, случайно он возник или нет." }, { 18.64, "Если не случайно,а в результате действий враждебных сил, нам придётся готовиться к появлению более серьёзных противников." } } } } },
    [1961] = { d = 41.3, v = "scourge-female", n = { x = 376 }, c = { x = { { 0.00, "Тебе пора обзавестись первым облачением мага. Одеяние – знак твоего особого положения, свидетельство твоего достоинства." }, { 10.85, "Для создания нужного одеяния тебе понадобятся самоцветы маны от даларанских магов из Серебряного бора." }, { 20.20, "Они верят примерно в то же, во что и мы, поэтому убивать их нехорошо, но раз они не могут противостоять нам, значит жизни они не заслуживают." }, { 32.91, "Отнеси камни и несколько кусков льна Джозефу Грегориану в суконную лавку Квартала Магов." } } }, t = { d = 9.8, v = "scourge-male", n = { x = 106 }, c = { x = { { 0.00, "Отличный материал. Оценить качество самоцветов я не могу, но вскоре мы узнаем, подходят ли они для создания одеяний из чароткани..." } } } } },
    [1963] = { d = 26.9, v = "orc-male#60", n = { x = 293 }, c = { x = { { 0.00, "Вождь слишком хитрит и осторожничает. Он не хочет пускать в ход всю мощь Орды. Изувеченная Длань вернёт Орде былую гордость!" }, { 9.16, "Мы тайно копим силы и исподтишка наносим удары неосторожным врагам. Докажи свою доблесть, выполни моё задание!" }, { 17.18, "Тролль по имени Тазан торгует с пиратами близ Кабестана. У него есть нужные мне сведения. Убей его и принеси мне его сумку." } } }, t = { d = 15.2, v = "orc-male#60", n = { x = 158 }, c = { x = { { 0.00, "Хм. Я, конечно, рад слышать, что Тазана больше нет в живых, однако от запертой сумки проку мало. Нам нужно то, что внутри!" }, { 8.74, "Вот и второе задание для того, кто стремится вступить в клан Изувеченной Длани!" } } } } },
    [1978] = { d = 23.1, g = 1, v = "scourge-male#82", n = { m = 195, f = 196 }, c = { m = { { 0.00, "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства." }, { 8.17, "Лорд Вариматрас будет доволен, и раз именно ты совершил это открытие – тебе и сообщать о нём. Ах да, как я мог забыть?" }, { 19.09, "Добро пожаловать в ряды стражей смерти." } }, f = { { 0.00, "Синдикат? Никогда бы не подумал. Низко же пали владыки Альтерака после предательства." }, { 8.17, "Лорд Вариматрас будет доволен, и раз именно ты совершила это открытие – тебе и сообщать о нём. Ах да, как я мог забыть?" }, { 19.18, "Добро пожаловать в ряды стражей смерти." } } }, t = { d = 15.9, v = "human-male", n = { x = 185 }, c = { x = { { 0.00, "Хм, любопытно. Стражи смерти превосходно справились со своими обязанностями." }, { 5.50, "Судя по всему, ты ждёшь благодарности за свои подвиги. Скоро это станет для тебя привычным делом." }, { 12.27, "Стражам смерти не помешают талантливые новички." } } } } },
    [1998] = { d = 40.8, g = 1, v = "scourge-male#82", n = { m = 360, f = 361 }, c = { m = { { 0.00, "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться." }, { 9.50, "Во всём виноват Фенвик Татрас, вождь нежити, поселившейся в Серебряном бору." }, { 16.88, "Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание." }, { 24.25, "Ты не обделён талантами и выполнишь поручение безукоризненно." }, { 30.31, "По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер." } }, f = { { 0.00, "Лорд Вариматрас сообщил мне о грозящей Отрёкшимся опасности, с которой следует немедленно разобраться." }, { 9.50, "Во всём виноват Фенвик Татрас, вождь нежити, поселившейся в Серебряном бору." }, { 16.88, "Я немедленно вспомнил о тебе, и сразу понял, кому следует доверить это задание." }, { 24.25, "Ты не обделена талантами и выполнишь поручение безукоризненно." }, { 30.54, "По последним сведениям от стражей смерти, Татроса видели неподалёку от разрушенной пристани озера Лордамер." } } }, t = { d = 11.5, g = 1, v = "scourge-male#82", n = { m = 95, f = 96 }, c = { m = { { 0.00, "Прекрасно. Ты оказался достойным помощником, а посему настало время продолжить твоё обучение тёмным искусствам." } }, f = { { 0.00, "Прекрасно. Ты оказалась достойным помощником, а посему настало время продолжить твоё обучение тёмным искусствам." } } } } },
    [1999] = { d = 44.1, v = "scourge-male#82", n = { x = 388 }, c = { x = { { 0.00, "Маги братства Кирин-Тора в Янтарной Мельнице хранят важные документы, касающиеся положения дел в Даларане." }, { 9.75, "Эти сведения удалось вытянуть из одного пленника. Лорд Вариматрас поручил стражам смерти добыть эти документы." }, { 20.41, "Честь выполнить это задание выпала тебе. Для задания понадобится кое-какое снаряжение и умение вскрывать замки." }, { 30.84, "Поговори с Эстеллой Джендри, она поставляет нам обмундирование. Попроси у неё набор инструментов, перед тем как отправляться в путь." } } }, t = { d = 15.7, g = 1, v = "scourge-male#82", n = { m = 135, f = 135 }, c = { m = { { 0.00, "Прекрасно. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал." }, { 8.24, "Вижу, я был прав, положившись на тебя. Поверь, мальчик мой, ты далеко пойдёшь." } }, f = { { 0.00, "Прекрасно. Тебе удалось освоить искусство вскрытия замков куда быстрее, чем я ожидал." }, { 8.24, "Вижу, я был прав, положившись на тебя. Поверь, девочка моя, ты далеко пойдёшь." } } } } },
    [2038] = { d = 18.8, v = "gnome-male", n = { x = 222 }, c = { x = { { 0.00, "Мало того, что они вторглись в наши края, эти трогги атаковали меня с ближайшего острова и украли мои инструменты и особую взрывчатку – сорвиголовку Покрышкинса." }, { 10.86, "Без вертолёта и взрывчатки движению не обойтись!" }, { 14.56, "Верни мне инструменты и отыщи сорвиголовку. За Гномреган!" } } }, t = { d = 7.0, g = 1, v = "gnome-male", n = { m = 80, f = 81 }, c = { m = { { 0.00, "Ты оказал движению огромную услугу. Скоро трогги и лепрогномы узнают, что такое воздушная атака!" } }, f = { { 0.00, "Ты оказала движению огромную услугу. Скоро трогги и лепрогномы узнают, что такое воздушная атака!" } } } } },
    [2039] = { d = 19.9, v = "gnome-male", n = { x = 227 }, c = { x = { { 0.00, "Мы потеряли связь с Бинглзом! Он был отправлен в разведывательный полёт над Гномреганом, и уже неделю от него нет никаких известий." }, { 8.98, "Я знаю только то, что он отправился в разведку и потерпел крушение." }, { 14.05, "Последний раз его видели над озером Лок. Возможно, ты сможешь выяснить, что с ним." } } }, t = { d = 11.6, v = "gnome-male", n = { x = 129 }, c = { x = { { 0.00, "Значит, Гноарн сомневается во мне как в разведчике? Интересно, почему..." }, { 4.96, "Ладно, не берите в голову, мне нужна ваша помощь! Нет! Ваша помощь нужна нашему общему делу!" } } } } },
    [2040] = { d = 26.3, v = "gnome-female", n = { x = 311 }, c = { x = { { 0.00, "Гномреган захватили трогги! Ситуация крайне тяжёлая, но, быть может, вы сможете помочь." }, { 6.39, "Глубоко под землёй, в Мёртвых копях, находится действующий гоблинский резак. Найдите его и принесите его источник питания." }, { 14.75, "С его помощью мы сможем обеспечить наши автогиробуроройки достаточной энергией, чтобы пробиться через каменные границы Гномрегана и открыть дорогу армии гномов!" } } }, t = { d = 6.1, v = "gnome-female", n = { x = 70 }, c = { x = { { 0.00, "Хорошая работа. Благодаря вам день освобождения Гномрегана приблизился ещё на шаг!" } } } } },
    [2041] = { d = 17.3, v = "gnome-male", n = { x = 197 }, c = { x = { { 0.00, "Возможно... Возможно, вы поможете нам в битве за Гномреган." }, { 4.58, "В Штормграде вы найдёте командира нашей подземной штурмовой группы, Шони Молшунью. Шони нужна помощь в сооружении автогиробуророек." }, { 13.61, "Вы найдёте её среди дворфов в Штормграде. Удачи." } } }, t = { d = 3.5, v = "gnome-female", n = { x = 39 }, c = { x = { { 0.00, "Вы с известиями от центрального командования?" } } } } },
    [2078] = { d = 18.0, g = 1, v = "gnome-male", n = { m = 201, f = 201 }, c = { m = { { 0.00, "Эй, сухопутное создание, нужно, чтоб ты нашёл моего первого помощника." }, { 5.22, "Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу." }, { 11.76, "Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!" } }, f = { { 0.00, "Эй, сухопутное создание, нужно, чтоб ты нашла моего первого помощника." }, { 5.10, "Берёшь этот ключ, вставляешь ему в башку и ведёшь сюда, чтобы он опять служил своему кэпу." }, { 11.64, "Этим мурлокам и их главарю не шибко понравится, когда ими займётся мой первый помощник!" } } }, t = { d = 12.4, v = "gnome-male", n = { x = 120 }, c = { x = { { 0.00, "Да-а-а... А ты, оказывается, больше, чем желторотая собачья акула, крыса ты сухопутная." }, { 7.35, "Кэп тебя, может, даже пустит палубу драить, если так и дальше пойдёт..." } } } } },
    [2098] = { d = 35.0, v = "gnome-male", n = { x = 401 }, c = { x = { { 0.00, "Жизнь пирата нелегка, сухопутное ты создание. Это не только грабежи да пьянки!" }, { 5.88, "Увы, мой корабль затонул совсем рядом с берегом из-за этих мерзких жесткозубов." }, { 11.80, "Первое, что мне нужно, – это чтоб мой первый помощник был в рабочем состоянии!" }, { 17.35, "Когда меня вынесло на берег, ключ от моего первого помощника сломался от удара о скалы, и его части растащили обитающие на Тёмном Берегу звери." }, { 27.18, "Краем глаза я заметил разъярённых крабов, свирепых лесных долгоходов и мурлоков, обшаривающих останки корабля..." } } }, t = { d = 13.8, g = 1, v = "gnome-male", n = { m = 144, f = 145 }, c = { m = { { 0.00, "Ах ты ж, акула собачья! Тебе удалось всё найти!" }, { 3.64, "Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт!" }, { 10.17, "А кстати, ты не видел моего первого помощника?" } }, f = { { 0.00, "Ах ты ж, акула собачья! Тебе удалось всё найти!" }, { 3.64, "Скоро мой первый помощник будет в полном порядке, и эти звери не знают, что их тогда ждёт!" }, { 10.17, "А кстати, ты не видела моего первого помощника?" } } } } },
    [2118] = { d = 34.5, v = "nightelf-male#59", n = { x = 406 }, c = { x = { { 0.00, "Болезнь расползается по Тёмному Берегу, захватывая сознания и тела всех, до кого добирается." }, { 6.74, "На медведей-осотников она подействовала особенно жестоко." }, { 10.74, "Некогда благородные звери стали инструментами разрушения, бешеными и неистовыми. Возможно, у меня есть средство от этой напасти." }, { 19.97, "Отнеси в лес эту ловушку и положи её на землю." }, { 23.12, "Любой бешеный колючешёрстный медведь, попавший в неё, станет на короткий период времени послушным." }, { 29.74, "В таком состоянии он будет следовать за тобой. Приведи его сюда." } } }, t = { d = 4.6, v = "nightelf-male#59", n = { x = 52 }, c = { x = { { 0.00, "Наша работа только начинается. Вы готовы к следующему заданию?" } } } } },
    [2138] = { d = 26.0, v = "nightelf-male#59", n = { x = 301 }, c = { x = { { 0.00, "Как я и боялся, целительное средство не действует." }, { 3.75, "Меня очень печалит, что я вынужден приговаривать к смерти создания природы, но больных колючешёрстных медведей придётся истребить." }, { 12.95, "Возвращайтесь в лес и уничтожьте двадцать бешеных колючешёрстных медведей." }, { 17.88, "Скорее всего, это не остановит зло, но хотя бы ненадолго замедлит наступление заразы на наш лес и его обитателей." } } }, t = { d = 13.4, v = "nightelf-male#59", n = { x = 146 }, c = { x = { { 0.00, "Вы сослужили большую службу Аубердину, но ваша работа на этом не закончена." }, { 5.61, "Отдохните, а затем возвращайтесь ко мне." }, { 8.76, "...И, укрепитесь духом и разумом для дальнейшего кровопролития." } } } } },
    [2139] = { d = 34.5, g = 1, v = "nightelf-male#59", n = { m = 401, f = 403 }, c = { m = { { 0.00, "За выживание нашего народа и безопасность наших земель мы платим высокую цену." }, { 5.70, "Ты пролил кровь слуг природы, сразил множество больных зверей." }, { 10.02, "Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго." }, { 17.55, "У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать." }, { 23.61, "Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому." }, { 28.75, "В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица. Убей её." } }, f = { { 0.00, "За выживание нашего народа и безопасность наших земель мы платим высокую цену." }, { 5.70, "Ты пролила кровь слуг природы, сразила множество больных зверей." }, { 10.04, "Народ Аубердина в долгу перед тобой, поскольку боль истерзанного леса немного утихла – пусть и ненадолго." }, { 17.56, "У меня есть для тебя последнее задание, но предупреждаю: тебе снова нужно будет убивать." }, { 23.62, "Надеюсь, это последний раз, когда мне приходится побуждать тебя к этому." }, { 28.76, "В пещере к северо-востоку отсюда близ Башал'Арана живёт мать-медведица. Убей её." } } }, t = { d = 26.9, v = "nightelf-male#59", n = { x = 317 }, c = { x = { { 0.00, "Вы с честью и мужеством сражались на благо Аубердина. В наших измученных войной землях смерть и отчаяние стали нормой." }, { 8.07, "Многие уже не пытаются встретить лицом к лицу испытания в нашем новом доме, их выбор – либо скрываться в своих жилищах, либо бежать в более укреплённые и безопасные земли Альянса." }, { 20.34, "Спасибо вам. Может быть, вскоре мы с вами будем плечом к плечу биться против другого врага." } } } } },
    [2158] = { d = 24.4, v = "human-male", n = { x = 269 }, c = { x = { { 0.00, "Каждому путнику рано или поздно нужно отдохнуть и восстановить силы – а для этого нет места лучше, чем таверна \"Гордость льва\"." }, { 8.97, "Там всем заправляет мой лучший друг Фарли. Скажи ему, что ты от меня – может, он даже скидки тебе даст на еду и выпивку." }, { 17.54, "Найти \"Гордость льва\" несложно: нужно просто идти по дороге на юг. Не бойся, с пути не собьёшься!" } } }, t = { d = 12.7, v = "human-male", n = { x = 133 }, c = { x = { { 0.00, "Наш девиз - покой и отдых для всех усталых и продрогших! Прошу, садись у огня, отдохни с дороги." }, { 6.95, "Хочешь - отведай, чем у нас кормят, да и выпить чего-нибудь тебе не помешает..." } } } } },
    [2159] = { d = 25.0, g = 1, v = "nightelf-male#54", n = { m = 262, f = 262 }, c = { m = { { 0.00, "Привет тебе, юный герой. Не окажешь ли ты мне услугу? У меня тут свёрток с травами, который надо доставить в Доланаар." }, { 8.00, "Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться." }, { 14.78, "Не отнесёшь ли ты посылку? Её надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда." } }, f = { { 0.00, "Привет тебе, юная героиня. Не окажешь ли ты мне услугу? У меня тут свёрток с травами, который надо доставить в Доланаар." }, { 8.78, "Но я ещё не закончил кое-какие дела с друидами Тенистой долины и пока что не могу отлучиться." }, { 15.55, "Не отнесёшь ли ты посылку? Её надо доставить Кельдамиру – хозяину таверны в Доланааре. Таверна стоит у дороги к югу отсюда." } } }, t = { d = 29.6, v = "nightelf-male#121", n = { x = 342 }, c = { x = { { 0.00, "Ах да, травы из Тенистой долины! Жаль, что Портанниус сам не смог её доставить - нам с ним много что надо обсудить." }, { 7.77, "Но я всё равно рад получить эту посылку и познакомиться с тобой." }, { 12.57, "Покуда ты здесь - чувствуй себя как дома." }, { 15.33, "Герои должны быть крепки телом и духом, так что если выпадает возможность отдохнуть и подлечиться, надо ей пользоваться!" }, { 23.63, "Забота о теле и духе только приблизит тебя к победе! Так что располагайся поудобнее..." } } } } },
    [2160] = { d = 39.3, v = "gnome-male", n = { x = 451 }, c = { x = { { 0.00, "Похоже, тебе не впервой путешествовать, и трудности в дороге тебя не пугают." }, { 5.20, "Что ж, раз уж ты всё равно собираешься в путь, может, заодно прихватишь и посылочку в Каранос? Её нужно отдать хозяину таверны." }, { 13.98, "Ты ведь собираешь заглянуть в таверну, верно?" }, { 17.16, "После всего, что тебя ожидает в пути – а ожидает тебя много чего, уж можешь мне поверить, – ты наверняка захочешь отдохнуть и перевести дух." }, { 26.81, "Так вот, я тебя и прошу – передай кое-что помощнику хозяина; его зовут Таннок Молот Стужи." }, { 32.87, "Я сам в одиночку до Караноса не доберусь, а патруля горных пехотинцев ещё ждать и ждать..." } } }, t = { d = 20.5, v = "dwarf-male", n = { x = 231 }, c = { x = { { 0.00, "О, гляди-ка, Ручник Ржавозубчик всё-таки прислал припасы!" }, { 3.88, "Я уж начинал беспокоиться: с тех пор, как тут поселились трогги, из Старой Наковальни вести почти и не доходят." }, { 11.81, "Я тебе очень благодарен, просто словами не передать, как. Ты тут располагайся, будь как дома, дорога-то была не из лёгких!" } } } } },
    [2161] = { d = 42.3, g = 1, v = "orc-male", n = { m = 441, f = 447 }, c = { m = { { 0.00, "Извини... Ты не мог бы мне помочь?" }, { 2.71, "У меня тут тяжеленная сумка с припасами. Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари!" }, { 11.37, "Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать." }, { 18.32, "Но оказалось, что припасы им не нужны!" }, { 21.17, "И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут..." }, { 28.96, "Не мог бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – герой! Ты, небось, ничего не боишься..." }, { 37.12, "Отнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!" } }, f = { { 0.00, "Извини... Ты не могла бы мне помочь?" }, { 2.89, "У меня тут тяжеленная сумка с припасами. Я шёл по дороге, на меня нападали и скорпиды, и пауки, и ещё более страшные твари!" }, { 11.55, "Я нёс припасы в долину Испытаний, потому что думал, что они там нужны, а я люблю помогать." }, { 18.50, "Но оказалось, что припасы им не нужны!" }, { 21.35, "И вот мне придётся тащить эти припасы обратно в Колючий Холм, а я так боюсь опасных тварей, обитающих тут..." }, { 29.14, "Не могла бы ты отнести посылку вместо меня? Я ведь простой батрак, а ты-то – героиня! Ты, небось, ничего не боишься..." }, { 37.56, "Отнеси эту сумку хозяину таверны Гроску. Спасибо тебе большое!" } } }, t = { d = 35.4, g = 1, v = "orc-male", n = { x = 356 }, c = { m = { { 0.00, "А, это еда, которую Укор нёс в далину испытаний. Разве она им не нужна?" }, { 5.49, "Что ж, они любят морить голодом вас, героев, во время тренировок. Укрепляет дух, как они говорят!" }, { 12.60, "Спасибо, что вернул еду. Я разложу её обратно по полкам... и вот, позволь мне предложить тебе немного подкрепиться!" }, { 21.74, "И не забудь отдохнуть здесь, в гостинице." }, { 24.75, "Возможно, ты храбрый герой, готовый покорять мир, но если твои силы истощены, ты не сделаешь ничего полезного ни для себя, ни для Орды." } }, f = { { 0.00, "А, это еда, которую Укор нёс в далину испытаний. Разве она им не нужна?" }, { 5.49, "Что ж, они любят морить голодом вас, героев, во время тренировок. Укрепляет дух, как они говорят!" }, { 12.60, "Спасибо, что вернул еду. Я разложу её обратно по полкам... и вот, позволь мне предложить тебе немного подкрепиться!" }, { 21.74, "И не забудь отдохнуть здесь, в гостинице." }, { 24.75, "Возможно, ты храбрый героиня, готовый покорять мир, но если твои силы истощены, ты не сделаешь ничего полезного ни для себя, ни для Орды." } } } } },
    [2178] = { d = 35.5, v = "nightelf-female#53", n = { x = 410 }, c = { x = { { 0.00, "Чувствуете этот восхитительный аромат? Это мой секретный рецепт – свежесваренная похлёбка из долгонога. Настоящий деликатес! Не хотите ли узнать рецепт?" }, { 10.61, "Но прежде, чем я вас научу готовить это блюдо, вы должны доказать мне, что умеете управляться с долгоногами." }, { 18.22, "Нет, я вовсе не жду, что вы пойдёте, приручите себе одного и приедете ко мне на нём верхом!" }, { 24.51, "Но если бы вы могли убить несколько птиц и принести мне их сочного мяса, это, пожалуй, убедило бы меня показать вам, как же готовится похлёбка из долгонога." } } }, t = { d = 4.6, v = "nightelf-female#53", n = { x = 50 }, c = { x = { { 0.00, "Фантастика! Попробуйте сами и скажите, что вы думаете об этом!" } } } } },
    [2205] = { d = 25.4, g = 1, v = "human-female#47", n = { m = 295, f = 295 }, c = { m = { { 0.00, "Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам." }, { 4.99, "Ты выглядишь так, что Матиас может принять тебя за торговца сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником." }, { 13.12, "Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена." }, { 18.07, "К делу! Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий. Не задерживайся!" } }, f = { { 0.00, "Значок? А, это ерунда, рыбка – ничего такого, что было бы тебе не по силам." }, { 4.99, "Ты выглядишь так, что Матиас может принять тебя за торговку сыром. Тебя, детка, вряд ли можно счесть настоящим разбойником." }, { 12.83, "Однако у меня есть для тебя работа, и я хочу, чтобы она была выполнена." }, { 17.78, "К делу! Доставь этот пакет Матиасу: возможно, у него тоже найдётся для тебя пара заданий. Не задерживайся!" } } }, t = { d = 18.3, v = "human-male", n = { x = 206 }, c = { x = { { 0.00, "Итак, тебе удалось меня отыскать. Глядя на тебя, я бы сказал, что для тебя это было серьёзным испытанием как физических сил, так и умственных способностей." }, { 11.01, "Ну что, попросить Рензика показать тебе, где здесь постоялый двор, или ты сразу приступишь к работе?" } } } } },
    [2206] = { d = 33.5, v = "human-male", n = { x = 389 }, c = { x = { { 0.00, "Наши полевые агенты сообщают о серьёзной активности Братства Справедливости к югу от Златоземья." }, { 6.82, "В этих донесениях указывается, что братство захватило лагерь Джерода и теперь использует его как перевалочный пункт для переправки больших партий контрабанды из Красногорья в Западный Край." }, { 20.18, "Мне нужно, чтобы вы проникли в доки и добыли мне расписание поставок. Скорее всего, портовой начальник носит его при себе." }, { 29.01, "...и кстати, если вас обнаружат – вы никогда не слышали о ШРУ..." } } }, t = { d = 23.6, v = "human-male", n = { x = 267 }, c = { x = { { 0.00, "Я потрясён... Потрясён, что Керин наконец-то нашла новобранца, из которого действительно может выйти толк. Возьмите этот клинок." }, { 8.89, "Придёт день, когда ШРУ вновь призовёт вас на службу." }, { 12.58, "Совершенствуйте своё мастерство, пусть глаза ваши будут всегда открыты, а клинок – наточен." }, { 19.26, "Вы не заметите нас, но почувствуете, когда мы будем рядом..." } } } } },
    [2218] = { d = 32.7, v = "dwarf-male", n = { x = 359 }, c = { x = { { 0.00, "Ещё одна заблудшая душа, стало быть, ищет наставничества? Полагаю, ты хочешь найти смысл жизни – смысл твоей жизни." }, { 8.49, "Я тысячу раз видел, как другие герои искали работу." }, { 12.41, "Что же, сегодня тебе повезло. У Хограла найдётся лекарство для твоего недуга." }, { 18.65, "Вот что ты сделаешь: иди по этой дороге до Стальгорна и там зайди в Заброшенный грот." }, { 24.48, "Как окажешься там, найди воровскую гильдию и переговори с Хальфданом Чернобородом. Он укажет тебе путь к спасению." } } }, t = { d = 17.0, g = 1, v = "dwarf-male", n = { m = 192, f = 194 }, c = { m = { { 0.00, "Стало быть, ты считаешь себя настоящим мерзавцем?" }, { 3.47, "Достойным оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?B" }, { 10.45, "Только настоящий прохвост так высоко себя ценит!" }, { 14.12, "Таких мы и ищем! Добро пожаловать!" } }, f = { { 0.00, "Стало быть, ты считаешь себя настоящей мерзавкой?" }, { 3.34, "Достойной оказаться среди немногих избранных ребят Чёрной Бороды – стать офицером Тайного Круга?B" }, { 10.28, "Только настоящая прохвостка так высоко себя ценит!" }, { 14.18, "Таких мы и ищем! Добро пожаловать!" } } } } },
    [2238] = { d = 34.2, g = 1, v = "dwarf-male", n = { m = 392, f = 394 }, c = { m = { { 0.00, "Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит." }, { 7.69, "У Тайного Круга есть свои жизненные ценности. И эти ценности – драгоценности. Просекаешь?" }, { 14.03, "Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить?" }, { 23.34, "Нам надо, чтобы ты переговорил с Онином Макмолотом в Гномрегане и вернулся с ответом. Этот хитрый дворф спрятался среди прокажённых. Так что поосторожнее." } }, f = { { 0.00, "Понимаешь, король выгребает из шахты руду и камни. Таких богатств ни один гном за десять жизней не увидит." }, { 7.69, "У Тайного Круга есть свои жизненные ценности. И эти ценности – драгоценности. Просекаешь?" }, { 14.03, "Теперь сдаётся нам, что королю надо бы поделиться, но так чтобы \"Вонючая Борода\" не знал, что мы берём свою долю, – ты улавливаешь нить?" }, { 23.34, "Нам надо, чтобы ты переговорила с Онином Макмолотом в Гномрегане и вернулась с ответом." }, { 29.18, "Этот хитрый дворф спрятался среди прокажённых. Так что поосторожнее." } } }, t = { d = 3.7, v = "dwarf-male", n = { x = 29 }, c = { x = { { 0.00, "Тсссс! Тише, балда. Нас подслушивают." } } } } },
    [2239] = { d = 35.5, g = 1, v = "dwarf-male", n = { x = 355 }, c = { m = { { 0.00, "Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день." }, { 7.30, "Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться." }, { 29.14, "Всё в этом донесении, герой. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг." } }, f = { { 0.00, "Рудник? Да, видел я, как эти жуткие бронированные паровые танки проходят к этому пункту каждый день." }, { 7.30, "Мои информаторы с востока доносят, что танк выходит из Стальгорна, заходит в карьер Гол'Болар, останавливается на перезаправку в Караносе, а потом орк знает зачем делает большой крюк вокруг Гномрегана, прежде чем вернуться в Стальгорн и разгрузиться." }, { 26.17, "Всё в этом донесении, героиня. Отнеси его Хальфдану, чтобы он смог обдумать следующий шаг." } } }, t = { d = 18.4, g = 1, v = "dwarf-male", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Большой крюк? Клянусь собственной бородой!" }, { 3.36, "Ты постарался на славу. Возьми вот этот кинжал и ступай. Круг призовёт тебя снова, когда будет готов третий шаг." }, { 11.35, "Что такое третий шаг? Да тот, что идёт после второго, а именно – хороший пинок тебе под зад. Хочешь?" } }, f = { { 0.00, "Большой крюк? Клянусь собственной бородой!" }, { 3.36, "Ты постаралась на славу. Возьми вот этот кинжал и ступай. Круг призовёт тебя снова, когда будет готов третий шаг." }, { 11.28, "Что такое третий шаг? Да тот, что идёт после второго, а именно – хороший пинок тебе под зад. Хочешь?" } } } } },
    [2241] = { d = 34.3, v = "nightelf-male#55", n = { x = 379 }, c = { x = { { 0.00, "Говорят, что я обезумел от любви." }, { 2.56, "Да, я всё время думаю о Сиарне. Да, мой дом полон рисунков и картин, с которых на меня смотрит Сиарна." }, { 9.46, "Да, я часто целыми днями крошки в рот не беру, не сплю, не пью, а всё плачу о нашей несбывшейся любви. Что в этом плохого?" }, { 17.92, "И вот теперь она отказывается меня видеть. МЕНЯ!" }, { 21.24, "Я пытался письма ей писать, так она не желает ни с кем разговаривать, если только это не разбойник." }, { 28.27, "Не отнесёшь ли ты ей от меня этот цветок? И не забудь сказать ей, что он от Джаннока." } } }, t = { d = 15.4, g = 1, v = "nightelf-female#52", n = { x = 174 }, c = { m = { { 0.00, "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать!" }, { 6.46, "Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться..." }, { 11.86, "Не хочешь ли подрядиться на одно дельце, герой?" } }, f = { { 0.00, "Если собрать все цветы, что присылает мне этот зануда Джаннок, впору цветочную лавку открывать!" }, { 6.46, "Ладно, как бы там ни было, нынешний посланец Джаннока может мне пригодиться..." }, { 11.86, "Не хочешь ли подрядиться на одно дельце, героиня?" } } } } },
    [2242] = { d = 27.9, v = "nightelf-female#52", n = { x = 334 }, c = { x = { { 0.00, "Нам кажется, что одно существо могло бы помочь нам понять, что происходит с лесами Тельдрассила." }, { 6.28, "Увы, уговорить это существо может оказаться опасным делом." }, { 10.51, "Это сатир. Он скрывается на ветви на опушке Поляны Оракула." }, { 14.51, "Пока всех, кто подходил к этому сатиру - с угрозами или добрым словом, - постигала мрачная судьба." }, { 20.82, "Может, надо подкрасться к нему незаметно?" }, { 23.77, "Узнай, что у Сетира Древнего в сумках, и возвращайся ко мне." } } }, t = { d = 17.7, g = 1, v = "nightelf-female#52", n = { m = 184, f = 185 }, c = { m = { { 0.00, "Дурные вести. Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому." }, { 7.79, "Ты сослужил добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу." } }, f = { { 0.00, "Дурные вести. Похоже, что зараза, охватившая леса и реки Тёмного Берега, начинает расползаться и по нашему дому." }, { 7.79, "Ты сослужила добрую службу, но больше ты уже ничем не поможешь. Прими этот клинок в награду за службу Тельдрассилу." } } } } },
    [2259] = { d = 9.5, v = "nightelf-male#55", n = { x = 85 }, c = { x = { { 0.00, "Не бойся, я не стану посылать тебя к Сиарне. Эрион требует твоего присутствия в Анклаве Кенария. Не медли!" } } }, t = { d = 2.8, g = 1, v = "nightelf-male#55", n = { x = 21 }, c = { m = { { 0.00, "Пора идти дальше, герой, – мир ждёт." } }, f = { { 0.00, "Пора идти дальше, героиня, – мир ждёт." } } } } },
    [2260] = { d = 24.1, v = "nightelf-male#55", n = { x = 284 }, c = { x = { { 0.00, "Весть о ваших деяниях получила широкую огласку. Настолько далеко, что даже разведка Штормграда желает лично побеседовать с вами." }, { 9.01, "Дорога не беспошлинная и небезопасная, но возможность стажироваться в ШРУ – это вам не жук чихнул!" }, { 15.91, "Вас ждёт целый новый мир. Отправляйтесь в Старый город Штормграда и поговорите с Рензиком Ножом в штаб-квартире ШРУ." } } }, t = { d = 10.2, v = "goblin-male", n = { x = 117 }, c = { x = { { 0.00, "Вы откликнулись на призыв ШРУ, и проделали долгий путь от дальних берегов, чтобы вступить в наши ряды." }, { 7.11, "Однако вам многому предстоит научиться." } } } } },
    [2281] = { d = 21.1, v = "goblin-male", n = { x = 243 }, c = { x = { { 0.00, "Посылать тебя в бой равноценно убийству. Рензику не нужны лишние покойники." }, { 5.30, "Но тебе, бояться нечего: для тебя найдётся не такое опасное дело." }, { 10.23, "Отправляйся в Красногорье и поговори там с Люцием – этот тип связан с ШРУ." }, { 15.32, "Он постоянно отирается у пристани в Приозерье вместе с остальными бездельниками." } } }, t = { d = 8.8, v = "dwarf-male", n = { x = 89 }, c = { x = { { 0.00, "Что, не слишком-то у тебя ловкие пальчики, верно? Ну, да не беспокойся: я и не из таких делал отличных разбойников!" } } } } },
    [2282] = { d = 21.3, v = "dwarf-male", n = { x = 237 }, c = { x = { { 0.00, "Я долгие годы обучал молодых воров." }, { 2.48, "В конце концов не всякому плуту от рождения достаётся ловкость и проворство, как у старого Люция." }, { 9.61, "Рядом с дорогой стоит лесопилка Альтера. Я оставил там сундук, а в нём – кое-что важное. Принеси его мне!" }, { 16.74, "Возвращайся с добычей, и получишь Воровской сертификат." } } }, t = { d = 9.5, g = 1, v = "dwarf-male", n = { m = 94, f = 95 }, c = { m = { { 0.00, "Сумел открыть, да? Неплохая работа." }, { 3.15, "Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта." } }, f = { { 0.00, "Сумела открыть, да? Неплохая работа." }, { 2.89, "Теперь если ты погибнешь, то исключительно по глупости, а не от отсутствия опыта." } } } } },
    [2298] = { d = 30.6, v = "dwarf-male", n = { x = 358 }, c = { x = { { 0.00, "И вот собрались мы уже разрабатывать фазу III, когда вломились несколько болванов Магни, стали нести какую-то чушь насчёт воровства и что они арестуют некоторых членов Тайного Круга." }, { 12.58, "Да только поди возьми старика Чёрную Бороду! Разборка пошла нешуточная, и каким-то образом всплыло твоё имя!" }, { 20.47, "Хочешь совет? Бери первого грифона из Стальгорна и дуй в Штормград." }, { 25.09, "Иди в Старый город и там переговори с моим старым приятелем Рензиком Ножом." } } }, t = { d = 3.7, v = "goblin-male", n = { x = 40 }, c = { x = { { 0.00, "Всегда рад видеть в наших рядах ребят Хальфдана!" } } } } },
    [2299] = { d = 11.4, v = "dwarf-male", n = { x = 121 }, c = { x = { { 0.00, "Где тебя носило? Хальфдан всюду тебя искал. Мы уж подумали, что король забил тебя в кандалы." }, { 7.16, "Дуй в Стальгорн как можно быстрее и поговори с Хальфданом!" } } }, t = { d = 2.8, v = "dwarf-male", n = { x = 29 }, c = { x = { { 0.00, "Говори тише, стража может услышать." } } } } },
    [2300] = { d = 8.1, v = "human-female#47", n = { x = 89 }, c = { x = { { 0.00, "Слушай, рыбка, тебя тут Рензик искал." }, { 2.90, "На твоём месте я не заставлял бы его ждать – всё-таки он правая рука Матиаса..." } } }, t = { d = 5.4, v = "goblin-male", n = { x = 61 }, c = { x = { { 0.00, "Как насчёт того, чтобы приступить к работе? Или хочешь сначала вздремнуть?" } } } } },
    [2359] = { d = 29.8, v = "human-female#47", n = { x = 338 }, c = { x = { { 0.00, "Я за этой башней уже не первую неделю наблюдаю." }, { 3.16, "Недавно прошла крупная поставка из Сумеречного леса, а вместе с ней явились эти стражи." }, { 9.40, "Кто такие? Мы можем только гадать. Одно я тебе скажу: это не люди." }, { 14.09, "Как бы то ни было, там был сундук – и, как я полагаю, эта мерзость именно его и охраняет." }, { 19.89, "А ключ от сундука – у того зомби с шипами." }, { 22.99, "Добудь этот ключ, проберись в башню и выясни, что находится в том сундуке. Находку отнесёшь Матиасу." } } }, t = { d = 38.3, v = "human-male", n = { x = 427 }, c = { x = { { 0.00, "Это объясняет присутствие мертвяков из Братства Справедливости, которых вы с Кеарнен видели рядом с башней." }, { 8.68, "Это может объяснить и вовлеченность Торговой Компании в дела Братства Справедливости и эти странные поставки из Сумеречного леса." }, { 18.76, "Как явствует из этой книги, тролли Занзила в Тернистой долине нашли возможность поднимать мёртвых с помощью зелий... выражаясь точнее – ядов." }, { 28.49, "Вы бесполезны для ШРУ, если у вас нет чёткого представления о ядах, особенно когда рецепт того, как поднимать нежить, почти у нас в руках." } } } } },
    [2360] = { d = 35.3, v = "human-male", n = { x = 400 }, c = { x = { { 0.00, "Произошло то, чего я ожидал. Разведотдел ШРУ сообщает, что Братство Справедливости что-то затевает в Западном Крае." }, { 8.27, "Складывается впечатление, что братство захватило покинутую сторожевую башню Альянса к юго-востоку от Сторожевого Холма и использует её как базу для ввоза контрабанды из Красногорья." }, { 21.20, "Отправляйтесь в Западный Край и свяжитесь с посланницей Кеарнен для подробного доклада. Она там прячется, неподалёку от башни." }, { 31.06, "... и кстати, если вас раскроют – вы никогда не слышали о ШРУ..." } } }, t = { d = 7.4, v = "human-female#47", n = { x = 88 }, c = { x = { { 0.00, "Наконец-то Матиас прислал ещё одного агента мне в помощь. Ну, надеюсь, он готов к вороху неприятных новостей." } } } } },
    [2378] = { d = 28.0, g = 1, v = "scourge-male#82", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Ты много сделал для стражей смерти, но пришло время двигаться дальше." }, { 6.42, "У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить." }, { 14.38, "У стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам." }, { 23.14, "Для начала поговори с Шентулом в Оргриммаре." } }, f = { { 0.00, "Ты много сделала для стражей смерти, но пришло время двигаться дальше." }, { 6.59, "У тебя талант к искусству обмана и скрытности, но этот талант ещё следует развить." }, { 14.55, "У стражей смерти есть союзники в Изувеченной Длани. Поищи среди них тех, кто готов помочь нам." }, { 23.31, "Для начала поговори с Шентулом в Оргриммаре." } } }, t = { d = 6.0, v = "troll-male", n = { x = 52 }, c = { x = { { 0.00, "Так вот кого могучие союзники прислали Шентулу... Не впечатляет…" } } } } },
    [2379] = { d = 21.2, v = "troll-male", n = { x = 208 }, c = { x = { { 0.00, "Одной твоей решимости ещё недостаточно, чтобы преодолеть препятствия, которые ждут впереди." }, { 7.72, "Поговори с Зандо'заном, чтобы начать учиться на агента Изувеченной Длани." }, { 14.10, "Лишь овладев навыками незаметности и коварства, ты сможешь сделать следующий шаг." } } }, t = { d = 4.0, v = "troll-male#78", n = { x = 45 }, c = { x = { { 0.00, "Быть может, Зандо'зан ошибся. Зандо'зан просит прощения." } } } } },
    [2380] = { d = 23.9, v = "orc-male", n = { x = 241 }, c = { x = { { 0.00, "Ты, конечно, далеко ещё не специалист по скрытности и всяким уловкам, однако же тебе есть куда расти." }, { 7.26, "По крайней мере, начальство явно обратило на тебя внимание: сам великий Шентул запомнил твоё имя!" }, { 14.57, "Ступай на север – эта дорога ведёт в Оргриммар. Отыщи там в расселине Теней Шентула и поговори с ним." } } }, t = { d = 17.9, v = "troll-male", n = { x = 168 }, c = { x = { { 0.00, "Очень важно, чтобы Изувеченная Длань сохраняла бдительность перед лицом перемен, которые Тралл намеревается ввести в Орде." }, { 10.04, "Числом тут не возьмёшь – для нас главное незаметность и разнообразные уловки!" } } } } },
    [2381] = { d = 35.4, v = "goblin-male", n = { x = 409 }, c = { x = { { 0.00, "Не хочу тебя пугать, но последние пять воров, которым я поручил похитить сокровище Южного моря, не вернулись. Потом их нашли... Частично." }, { 9.70, "В южной части побережья пришвартован пиратский корабль, \"Стрела прилива\". В трюме у него хранится то самое сокровище." }, { 17.74, "На второй палубе устроен пиратский притон, в котором они натаскивают своих воров." }, { 23.78, "Проникни на этот корабль, похить сокровище и принеси его мне." }, { 27.99, "Если тебе надо поднатореть в воровском искусстве, можешь заглянуть в притон, но соблюдай осторожность!" } } }, t = { d = 11.2, v = "goblin-male", n = { x = 120 }, c = { x = { { 0.00, "Немыслимо! Невероятно! Поразительно! Да ты талант. Или же ты самый везучий парень на свете!" }, { 6.65, "Вот твоя доля. Думаю, ты найдёшь ей лучшее применение, чем я." } } } } },
    [2382] = { d = 22.6, g = 1, v = "troll-male#78", n = { m = 208, f = 208 }, c = { m = { { 0.00, "Зандо'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо'зан слишком много болтает." }, { 10.94, "путник! У Зандо'зана есть поручение для тебя!" }, { 14.70, "путник должен отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным. Ступай!" } }, f = { { 0.00, "Зандо'зан это видел! Да, день близок! Смерть Тралла... кинжал в его спине, яд в его кубке... Но Зандо'зан слишком много болтает." }, { 10.94, "путница! У Зандо'зана есть поручение для тебя!" }, { 14.38, "путница должна отправиться в Кабестан, к востоку от Перекрёстка, и поговорить с Рениксом Презренным. Ступай!" } } }, t = { d = 9.9, v = "goblin-male", n = { x = 109 }, c = { x = { { 0.00, "Как, опять? Предыдущие пятеро, кого прислал ко мне этот чокнутый тролль, пошли на корм акулам." }, { 6.52, "Ну что ж, будем надеяться, что тебе повезёт…" } } } } },
    [2383] = { d = 13.9, v = "orc-male#60", n = { x = 150 }, c = { x = { { 0.00, "А! Тебе тут пергамент прислали, пока тебя не было." }, { 3.95, "Прочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить." }, { 10.74, "Он обычно сидит в тени у входа в Логово." } } }, t = { d = 21.7, g = 1, v = "orc-male#60", n = { m = 235, f = 236 }, c = { m = { { 0.00, "А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься." }, { 4.63, "Рад, что тебе удалось добраться сюда невредимым – будем надеяться, что ты переживёшь и грядущие испытания." }, { 12.03, "Наберёшься сил – приходи ко мне. Я сделаю всё, чтобы из тебя получился настоящий воин." }, { 18.44, "Удачи! Возвращайся, когда будешь готов." } }, f = { { 0.00, "А-а, да, это я тебе написал... Я слышал, что ты скоро тут появишься." }, { 4.63, "Рад, что тебе удалось добраться сюда невредимой – будем надеяться, что ты переживёшь и грядущие испытания." }, { 12.00, "Наберёшься сил – приходи ко мне. Я сделаю всё, чтобы из тебя получился настоящий воин." }, { 18.42, "Удачи! Возвращайся, когда будешь готова." } } } } },
    [2438] = { d = 30.5, g = 1, v = "nightelf-male#54", n = { x = 349 }, c = { m = { { 0.00, "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов." }, { 6.39, "Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит." }, { 13.83, "Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра..." }, { 19.11, "Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там." }, { 26.51, "Может, тебе удастся добыть моего ловца снов, герой?" } }, f = { { 0.00, "Некогда Гэролас Талветрен, страж друидов обители Бен'этиль, подарил мне изумрудного ловца снов." }, { 6.39, "Этот могучий амулет способен выкачивать энергию из Изумрудного Сна, принося удачу тому, кто его носит." }, { 13.83, "Увы, мне не удалось забрать его из моего шкафчика в деревне Звёздного Ветра..." }, { 19.11, "Хотя эта деревня некогда была спокойным местом, ныне она поражена порчей фурболгов, что поселились там." }, { 26.51, "Может, тебе удастся добыть моего ловца снов, героиня?" } } }, t = { d = 9.5, v = "nightelf-male#54", n = { x = 111 }, c = { x = { { 0.00, "Мой изумрудный ловец снов очень много для меня значит. Такие подарки лишь немногим дарят." }, { 6.24, "Прими мою благодарность за его возвращение." } } } } },
    [2458] = { d = 41.9, v = "troll-male", n = { x = 393 }, c = { x = { { 0.00, "Торговая Компания... Доводилось тебе слышать про такую?" }, { 4.79, "Мы в течение года пытались внедрить агента в их ряды. Это было непросто, но мы преуспели." }, { 12.51, "Недавно мы получили сведения, что Торговая Компания затевает что-то крупное." }, { 18.67, "Ступай к башне Торговой Компании, которая стоит к северу от Нефтяного болота, и свяжись с нашим тайным агентом, надсмотрщиком Физзулом." }, { 31.70, "Когда найдёшь башню, используй это сигнальное ружьё, потом подойди к Физзулу и покажи ему приветствие Изувеченной Длани." } } }, t = { d = 18.4, v = "dwarf-male", n = { x = 199 }, c = { x = { { 0.00, "Приятно видеть в здешних местах ещё одного агента Изувеченной Длани!" }, { 5.57, "Вот только боюсь, как бы твоих вспышек не заметил кто-то лишний." }, { 10.37, "В следующий раз, когда тебе нужно будет со мной поговорить, дважды свистни в этот свисток, и я пойму, что это свои." } } } } },
    [2459] = { d = 32.1, v = "nightelf-male#54", n = { x = 365 }, c = { x = { { 0.00, "Изумруд... Он пропал! Мой ловец снов повреждён!" }, { 3.39, "К северу от деревни Звёздный Ветер засела шайка мистиков из племени Кривой Сосны." }, { 9.04, "Я слышал, что их вожак, Фероситас Пожиратель Снов, носил ожерелье, которое светится зелёным в ночи." }, { 15.85, "Теперь, глядя на своего ловца снов, я уверен, что это он украл мой изумруд... Он не понимает, что его сила для него бесполезна." }, { 24.80, "Найди этот пропавший драгоценный камень. И раз уж ты здесь, истреби заодно и этих зловредных мистиков." } } }, t = { d = 4.1, v = "nightelf-male#54", n = { x = 44 }, c = { x = { { 0.00, "Теперь я восстановлю своего ловца снов! Спасибо тебе." } } } } },
    [2460] = { d = 15.6, v = "troll-male", n = { x = 129 }, c = { x = { { 0.00, "Теперь, когда ты – разбойник Изувеченной Длани, тебе следует обучиться особому приветствию. Это знак, по которому мы опознаем своих. Смотри и повторяй за мной." } } }, t = { d = 3.9, g = 1, v = "troll-male", n = { m = 30, f = 29 }, c = { m = { { 0.00, "Молодец! Теперь мы можем продолжать." } }, f = { { 0.00, "Умница! Теперь мы можем продолжать." } } } } },
    [2478] = { d = 30.5, g = 1, v = "dwarf-male", n = { m = 334, f = 334 }, c = { m = { { 0.00, "Тебе придётся украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне ещё пригодится." }, { 7.42, "Не забудь: яд ослабил всех в этой башне. Покажи, на что ты способен, неси хаос и разрушение в стены башни." }, { 14.69, "Убей всех – жалости тут нет места!" }, { 17.50, "Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила." }, { 25.41, "Отнеси голову Галливикса и смесь Шентулу в Оргриммар." } }, f = { { 0.00, "Тебе придётся украсть ключ от башни у штейгера Силиксиза. Смотри не потеряй его: он мне ещё пригодится." }, { 7.42, "Не забудь: яд ослабил всех в этой башне. Покажи, на что ты способна, неси хаос и разрушение в стены башни." }, { 14.62, "Убей всех – жалости тут нет места!" }, { 17.43, "Когда внутри останутся лишь кровавые ошмётки, возьми денежный ящик Галливикса и укради из него запас смеси Занзила." }, { 25.34, "Отнеси голову Галливикса и смесь Шентулу в Оргриммар." } } }, t = { d = 22.6, g = 1, v = "troll-male", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену." }, { 8.93, "Да, работа агента Изувеченной Длани опасна." }, { 12.77, "Но ты отлично справился с заданием, герой. Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам." } }, f = { { 0.00, "Бедный Физзул, он был прекрасным агентом, одним из лучших. Увы, мы заплатили за победу высокую цену." }, { 8.93, "Да, работа агента Изувеченной Длани опасна." }, { 12.77, "Но ты отлично справилась с заданием, героиня. Хорошо, что тебе удалось выжить. Ты ведь можешь и дальше служить нам." } } } } },
    [2479] = { d = 15.7, v = "troll-male", n = { x = 138 }, c = { x = { { 0.00, "Отнеси образчик этой смеси Сержу Хинотту на Мельницу Таррен." }, { 5.45, "Если кто сможет тебя исцелить, так это Серж. Он тебя обучит всему, что связано с ядами, – если, конечно, выживешь." } } }, t = { d = 7.3, g = 1, v = "scourge-male#83", n = { m = 66, f = 66 }, c = { m = { { 0.00, "О, герой, какой ты бледненький! А чем это от тебя так мерзко благоухает? Я должен выяснить!" } }, f = { { 0.00, "О, героиня, какая ты бледненькая! А чем это от тебя так мерзко благоухает? Я должен выяснить!" } } } } },
    [2480] = { d = 20.0, v = "scourge-male#83", n = { x = 199 }, c = { x = { { 0.00, "Никогда не видел таких отличных результатов действия яда! Занзил, говоришь? Не слыхал о таком..." }, { 7.75, "Однако пора уже приступать к созданию состава." }, { 11.64, "Итак, я должен вылечить тебя и научить пользоваться этим ядом?" }, { 16.72, "Дай мне пару минут на изучение токсина." } } }, t = { d = 9.6, v = "scourge-male#83", n = { x = 96 }, c = { x = { { 0.00, "Лекарство готово! Выпей это противоядие, и наступление безумия остановится. Впрочем, с запахом ничего не поделаешь." } } } } },
    [2498] = { d = 15.7, v = "nightelf-male#55", n = { x = 188 }, c = { x = { { 0.00, "Я только что получил известие, что Деналан с озера Аль'Амет узнал, что могло послужить причиной возникновения опухоли, поражающей древесников." }, { 9.54, "Пожалуйста, поговори с ним и скажи, что тебя прислал я. Торопись, ему нужна наша помощь." } } }, t = { d = 10.3, g = 1, v = "nightelf-male#59", n = { m = 97, f = 97 }, c = { m = { { 0.00, "Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришёл." }, { 5.76, "Я обнаружил нечто чрезвычайно тревожное!" } }, f = { { 0.00, "Ах, так, значит, Релиан послал тебя мне в помощь. Хорошо, что ты так скоро пришла." }, { 7.07, "Я обнаружил нечто чрезвычайно тревожное!" } } } } },
    [2499] = { d = 34.9, g = 1, v = "nightelf-male#59", n = { m = 370, f = 372 }, c = { m = { { 0.00, "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной." }, { 11.40, "Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал... Она просто гигантская!" }, { 21.89, "Ты и так уже достаточно помог мне в моих трудах, но я попрошу тебя ещё об одной услуге. Найди Дубохмура и сними эту опухоль." }, { 31.97, "Избавь мою землю от источника порчи!" } }, f = { { 0.00, "В пещере на южном берегу озера засел древесник по имени Дубохмур и заражает порчей всех существ, для которых окрестности озера Аль'Амет – дом родной." }, { 10.65, "Я не осмелился подходить к нему близко, но даже издалека хорошо видно: Дубохмур поражён опухолью, какой я в жизни не видывал... Она просто гигантская!" }, { 21.13, "Ты и так уже достаточно помогла мне в моих трудах, но я попрошу тебя ещё об одной услуге. Найди Дубохмура и сними эту опухоль." }, { 29.80, "Избавь мою землю от источника порчи!" } } }, t = { d = 24.0, v = "nightelf-male#59", n = { x = 275 }, c = { x = { { 0.00, "Я так и знал, что ты сумеешь избавить озеро от этой чудовищной твари." }, { 5.15, "Печальная история – Дубохмур некогда был великим вождём своих сородичей... но порча поражает всех подряд – и подлых, и благородных." }, { 14.25, "Величина этой опухоли в дрожь бросает, но я обязан исследовать её, чтобы понять, какая зараза терзает древесников. Прими мою благодарность." } } } } },
    [2518] = { d = 34.6, v = "nightelf-female#51", n = { x = 390 }, c = { x = { { 0.00, "Некогда леди Сатра была дорога Элуне." }, { 2.82, "Эта изящная и чистая душой паучиха ткала серебряные свои нити под светом луны, ловя в свои сети вечерний туман." }, { 10.58, "Его серебристые капли обладали великой целительной силой, их хранили в этом храме." }, { 16.60, "Но недавно Сатру постигло безумие. Теперь и её потомство под угрозой." }, { 22.20, "Найди леди Сатру, и положи конец её страданиям. Она обитает у северных границ Тельдрассила, близ Родникового озера." }, { 30.22, "Возьми её серебристые паутинные железы и принеси их мне." } } }, t = { d = 5.0, v = "nightelf-female#51", n = { x = 55 }, c = { x = { { 0.00, "Лес оплакивает леди Сатру, но это надо было сделать. Благодарю тебя." } } } } },
    [2519] = { d = 15.6, g = 1, v = "nightelf-female#53", n = { x = 163 }, c = { m = { { 0.00, "Одному некогда великому существу из нашего леса нужна помощь, герой." }, { 5.06, "Это трудное дело, но его надо сделать." }, { 8.09, "Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит. Ищи её к юго-востоку отсюда, в Храме Луны." } }, f = { { 0.00, "Одному некогда великому существу из нашего леса нужна помощь, героиня." }, { 5.16, "Это трудное дело, но его надо сделать." }, { 8.20, "Пожалуйста, разыщи нашу жрицу А'моору, она всё тебе объяснит. Ищи её к юго-востоку отсюда, в Храме Луны." } } }, t = { d = 3.2, v = "nightelf-female#51", n = { x = 34 }, c = { x = { { 0.00, "Стало быть, тебя прислала сестра Аквинна?" } } } } },
    [2520] = { d = 23.9, g = 1, v = "nightelf-female#51", n = { m = 272, f = 272 }, c = { m = { { 0.00, "Теперь ты должен закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны." }, { 7.76, "Пусть великая паучиха обретёт покой." }, { 10.62, "Внутри этого храма ты найдёшь центральный фонтан. Там ты оставишь жертвоприношение." }, { 16.49, "Святые воды смоют порчу, что повергла Сатру в безумие." }, { 20.59, "Когда закончишь дело, возвращайся ко мне." } }, f = { { 0.00, "Теперь ты должна закончить дело, порученное тебе. Возьми эти паутинные железы и принеси их в жертву во имя Элуны." }, { 7.87, "Пусть великая паучиха обретёт покой." }, { 10.72, "Внутри этого храма ты найдёшь центральный фонтан. Там ты оставишь жертвоприношение." }, { 16.59, "Святые воды смоют порчу, что повергла Сатру в безумие." }, { 20.70, "Когда закончишь дело, возвращайся ко мне." } } }, t = { d = 9.9, g = 1, v = "nightelf-female#51", n = { m = 106, f = 108 }, c = { m = { { 0.00, "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом." }, { 6.33, "Да примет Элуна ту жертву, что ты принёс ей." } }, f = { { 0.00, "Велика наша скорбь по леди Сатре, но лишь так она может возродиться с обновлённым духом." }, { 6.33, "Да примет Элуна ту жертву, что ты принесла ей." } } } } },
    [2541] = { d = 32.3, v = "nightelf-male", n = { x = 370 }, c = { x = { { 0.00, "Шаман племени Кривой Сосны, который живёт в этих местах, нашёл способ разлучать дух спящего друида с физическим телом." }, { 8.18, "Этот фурболг оживил моё тело и заставил его нападать на любого, кто пытается обследовать обитель Бен'этиль." }, { 16.18, "Теперь мне не выйти из Изумрудного Сна, и я не могу прекратить это!" }, { 21.03, "Помоги мне! У шамана Кривой Сосны есть при себе странный оберег, который он использует во время ритуала, и я хотел бы исследовать его. Прошу тебя, принеси его мне!" } } }, t = { d = 8.9, v = "nightelf-male", n = { x = 94 }, c = { x = { { 0.00, "Прими мою благодарность." }, { 1.94, "Какая странная вещица... Я чувствую злую ауру, которую она излучает. Очень мощное заклятие..." } } } } },
    [2561] = { d = 38.0, v = "nightelf-male", n = { x = 419 }, c = { x = { { 0.00, "Изучив этот оберег, я понял, что надо сделать. Пожалуйста, возьми его и сделай, как я прошу." }, { 6.53, "Тебе придётся собраться с духом и проникнуть в самые глухие закоулки обители Бен'этиль. Там ты найдёшь моё лишённое души тело..." }, { 16.47, "Хотя я и скорблю о том, что мне сейчас придётся поведать тебе, я не вижу другого способа освободиться от власти племени Кривой Сосны." }, { 26.08, "Чтобы я мог сбежать от них, ты должен уничтожить моё физическое тело." }, { 30.81, "Как только это будет сделано, обрати на мой труп силу амулета вуду. После этого возвращайся ко мне." } } }, t = { d = 17.2, g = 1, v = "nightelf-male", n = { m = 187, f = 187 }, c = { m = { { 0.00, "Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе." }, { 4.97, "Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна." }, { 9.63, "Возможно, однажды мы снова встретимся, юный герой. Но пока прими эту награду в знак моей благодарности." } }, f = { { 0.00, "Наконец-то я свободен от власти племени Кривой Сосны! Спасибо тебе." }, { 4.97, "Отныне мой дух обретёт вечный покой в объятиях Изумрудного Сна." }, { 9.63, "Возможно, однажды мы снова встретимся, юная героиня. Но пока прими эту награду в знак моей благодарности." } } } } },
    [2607] = { d = 13.9, v = "human-male", n = { x = 154 }, c = { x = { { 0.00, "Похоже, что информации у вас даже больше, чем я ожидал. Как-то странно всё оборачивается." }, { 6.41, "Лекарство? Хм-м... Спуститесь в подвал и поговорите с Доком Миксиль-Пиксилем – он, вероятно, сможет помочь." } } }, t = { d = 7.2, v = "gnome-male", n = { x = 74 }, c = { x = { { 0.00, "Как раз вовремя! Просто положите сыр на стол и проваливайте. Осборн заплатит вам на выходе." } } } } },
    [2608] = { d = 26.6, g = 1, v = "gnome-male", n = { m = 285, f = 284 }, c = { m = { { 0.00, "Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите ещё хуже." }, { 7.19, "Вы, сударь, будете предсмертной отрыжкой самой смерти. Ха! Слышал, Ноарм? Запиши-ка это!" }, { 13.43, "*Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые..." }, { 22.06, "раз пятьдесят или около того... Ложитесь, и приступим к лечению!" } }, f = { { 0.00, "Ох, вы так выглядите – точь-в-точь мертвец. Поправочка – я видел мертвецов, вы выглядите ещё хуже." }, { 7.19, "Вы, детка, будете предсмертной отрыжкой самой смерти. Ха! Слышал, Ноарм? Запиши-ка это!" }, { 13.39, "*Кашляет.* Хмм, да, чтобы я мог помочь, мне нужно будет взять у вас немного крови. Не беспокойтесь, больно лишь первые..." }, { 22.03, "раз пятьдесят или около того... Ложитесь, и приступим к лечению!" } } }, t = { d = 7.4, v = "gnome-male", n = { x = 86 }, c = { x = { { 0.00, "Позвольте, я минутку посовещаюсь со своими коллегами. Доктор Монтгомери, мистер Ноарм, все на консилиум!" } } } } },
    [2609] = { d = 39.6, v = "gnome-male", n = { x = 447 }, c = { x = { { 0.00, "Однозначно. У вас чтотит." }, { 2.66, "К счастью, от чтотита у меня есть средство." }, { 6.01, "И вот что мне понадобится для его изготовления: букетик простых полевых цветов, одна освинцованная колба, одна бронзовая трубка и последнее – но немаловажное!" }, { 16.72, "– нитка светлого зеленовато-жёлтого шёлка. Старушка Эмма оставила для меня катушку таких ниток в \"Тончайшей пряже\"." }, { 24.44, "Эту лавку можно найти, если идти вдоль каналов." }, { 28.22, "А теперь поспешите, и постарайтесь ни к кому не прикасаться, пока вас не вылечат." }, { 33.64, "Кстати, доктор Монтгомери сказал, что вам нужно душ принять... это его слова, не мои!" } } }, t = { d = 19.2, v = "gnome-male", n = { x = 201 }, c = { x = { { 0.00, "Что я делаю? А на что похоже то, что я делаю? Я продумываю, как вылечить ваш чтотит! И нечего так возмущённо на меня смотреть!" }, { 9.46, "Ещё несколько секунд... Готово! Побрызгайте на себя этим лечебным средством с... эээ..." }, { 15.61, "необыкновенным запахом – и вы в полном порядке!" } } } } },
    [2745] = { d = 37.1, v = "human-male#50", n = { x = 416 }, c = { x = { { 0.00, "Хм-м, интересная история, причём не из тех, на которые можно наплевать." }, { 4.63, "Да, помочь-то я вам могу, но то, что вам нужно будет сделать, это свершить правосудие..." }, { 10.45, "частично незаконным путём, если уж вы хотите довести дело до конца." }, { 15.42, "С Лесковаром и Марзоном нужно разобраться – и быстро. Как думаете, вы на это способны?" }, { 22.06, "Решать вам. Если да, то поскорее отправляйтесь в крепость и найдите там моего старинного друга – гнома по имени Тирион." }, { 30.03, "Он уже пару недель как наблюдает за Лесковаром. Он сможет помочь вам покончить с этим делом." } } }, t = { d = 29.2, v = "gnome-male", c = { x = { { 0.00, "Какого?! Не подкрадывайтесь ко мне вот так! И говорите тише! На кой вы, спрашивается, во имя Теней, так ко мне подкрадываетесь?" }, { 8.65, "Не видите, что ли – я занят, безмозглое вы создание!" }, { 12.52, "Что вы имеете в виду, спрашивая, что я делаю? Жду открытия следующего Тёмного портала, а вы что подумали?" }, { 19.61, "Выкладывайте, с чем пришли, и валите отсюда... пока стражники не заметили, что мы тут вдвоём в кустах прячемся. Мне нужно блюсти репутацию." } } } } },
    [2746] = { d = 36.9, v = "gnome-male", c = { x = { { 0.00, "Триас хочет поторопить события, так? Ладно, мы это сделаем, но сейчас я не готов." }, { 5.58, "И, кстати, сложную часть я беру на себя, а ручки пачкать будете вы, это понятно? Отлично." }, { 11.96, "Значит, мне нужно, чтобы вы мне кое-что принесли, чтобы я смог воплотить в жизнь свой план." }, { 18.14, "У меня есть мысль об отличной маскировке, при помощи которой этот робот-шпион пройдёт мимо стражников." }, { 25.49, "Принесите мне немного шелка и пару яблок." }, { 28.40, "Где достать шёлк – думайте сами, а вот подходящие яблоки есть у Клары в её маленьком хозяйстве сразу за городской чертой." } } }, t = { d = 22.6, v = "gnome-male", c = { x = { { 0.00, "Это отлично подойдёт. Прекрасная работа." }, { 3.11, "Вся остальная амуниция у меня в сумке... Слава Свету, у меня есть приятель-портной, сшивший мне шёлковую сумку." }, { 10.52, "А то мне бы уже некуда было рассовывать свои вещи." }, { 14.30, "Прежде чем мой робот-шпион отправится куда надо, давайте обговорим детали, чтобы вы знали, что вам нужно будет делать." } } } } },
    [2842] = { d = 29.0, v = "goblin-male#110", c = { x = { { 0.00, "Как только Керноби сообщил нам о новой гномьей машине, мы со Скути принялись строить \"Транстелепорт-шесть тысяч\" – лучший способ добраться до Гномрегана." }, { 10.84, "Он уже готов. Если хочешь его испытать, ступай в Пиратскую бухту и поговори со Скути у Гнезда Крыльев Ветра." }, { 18.29, "Из Кабестана туда можно добраться на лодке." }, { 21.74, "Нет, разумеется, ты можешь попробовать добраться до Гномрегана через горы Дун Морог, кишащие дворфами!" } } }, t = { d = 16.3, v = "goblin-male", c = { x = { { 0.00, "Ну, разве она не красавица? Вершина гоблинских транспортных технологий! И десяти раз не взрывалась!" }, { 7.35, "Ты не бойся. Больше она не взорвётся, я там всё отладил. Ну, а если тебе не повезёт, ты хотя бы умрёшь быстро и безболезненно!" } } } } },
    [2843] = { d = 28.1, v = "goblin-male", c = { x = { { 0.00, "Пока импульсный повторитель у тебя с собой, стоит только ступить на площадку, и перенесешься в Гномреган." }, { 7.70, "Может быть, ощущения будут необычные, но ни одно из них не останется навсегда... Теперь." }, { 14.11, "Чуть не забыл самое главное – как вернуться назад. Когда ты решишь уносить ноги, поднимись на площадку транстелепорта в Гномрегане!" }, { 23.47, "А теперь я настрою импульсный повторитель на твой рост и вес." } } }, t = { d = 4.4, v = "goblin-male", c = { x = { { 0.00, "Готово! Когда соберёшься с духом, просто ступи на площадку." } } } } },
    [2904] = { d = 30.6, v = "goblin-male", n = { x = 332 }, c = { x = { { 0.00, "Керноби стонет Э-э... Что случилось?" }, { 3.40, "Последнее, что я помню, это как меня похитили дворфы Чёрного Железа, избили до полусмерти и бросили сюда, к этим омерзительным троггам. Вытащи меня отсюда!" }, { 14.23, "Сделаем так: выведи меня к выходу; если нам удастся выбраться живыми, пойдёшь в Пиратскую бухту и скажешь Скути, что я был в Кабестане и предупредил Оловеня, что дворфы Чёрного Железа тоже как-то связаны с работой над супер-роботом. Идём!" } } }, t = { d = 14.0, g = 1, v = "goblin-male", n = { m = 162, f = 164 }, c = { m = { { 0.00, "Ты достоин награды за то, что вернул Керноби целым и невредимым." }, { 4.41, "Если твой дальнейший путь ведёт в Гномреган, вот это поможет тебе расправиться с никчёмным предателем, Мекжинером Термоштепселем." } }, f = { { 0.00, "Ты достойна награды за то, что вернула Керноби целым и невредимым." }, { 4.72, "Если твой дальнейший путь ведёт в Гномреган, вот это поможет тебе расправиться с никчёмным предателем, Мекжинером Термоштепселем." } } } } },
    [2922] = { d = 41.6, v = "gnome-male", n = { x = 490 }, c = { x = { { 0.00, "Когда пал наш родной город Гномреган, с Техботом, видимо от расстройства, приключилось короткое замыкание. Бедный мой маленький друг!" }, { 9.10, "Он так помогал мне и моим коллегам!" }, { 11.60, "В него встроена куча полезных прибамбасов на все случаи жизни, объём памяти просто огромен, но всё это теперь совершенно бесполезно – его мозг из позитронного стал негатронным!" }, { 23.38, "Все заложенные в него программы теперь работают наоборот. Мой бедный сумасшедший робот теперь бродит по Гномрегану." }, { 31.65, "Может, тебе удастся изловить его и извлечь его ядро памяти. Тогда я смогу разобраться в причинах поломки и, возможно, устраню её." } } }, t = { d = 12.1, v = "gnome-male", n = { x = 130 }, c = { x = { { 0.00, "О, какое счастье! Спасибо! Я немедленно начну разбираться с поломкой!" }, { 5.00, "Бедный мой Техбот! Потерпи, я тебя вылечу." }, { 8.34, "Так, куда же я засунул свой гидропневмогайковёрт..." } } } } },
    [2923] = { d = 25.4, v = "human-male", n = { x = 292 }, c = { x = { { 0.00, "Мехмастер Замыкалец крайне опечален судьбой своего творения – Техбота." }, { 4.81, "Помнится, Техбот был когда-то для гномов весьма полезным инструментом, однако теперь Большая Искра говорит, что он сломан." }, { 13.64, "Очень жаль. Однако, быть может, его ещё возможно починить." }, { 18.11, "Поговори об этом с Мехмастером Замыкальцем в Городе Механиков в Стальгорне. Он будет рад любой помощи." } } }, t = { d = 5.6, v = "gnome-male", n = { x = 56 }, c = { x = { { 0.00, "Да, это правда. Мой Техбот совсем вышел из строя! Ты сможешь мне помочь?" } } } } },
    [2924] = { d = 31.3, v = "gnome-male", n = { x = 381 }, c = { x = { { 0.00, "Базовый элемент – практически универсальный механизм, широко используемый механиками и кузнецами Гномрегана." }, { 7.45, "Однако в спешке покидая город, никто из нас не догадался прихватить запас этих механизмов с собой." }, { 14.04, "Мне просто необходимо пополнить мои запасы!" }, { 17.33, "Пожалуйста, отправляйся в Гномреган и добудь мне побольше таких механизмов." }, { 22.59, "Думаю, их можно найти в подземельях нашего города – обычно они хранятся в контейнерах-экстраполяторах. Умоляю тебя, поторопись!" } } }, t = { d = 8.8, v = "gnome-male", n = { x = 95 }, c = { x = { { 0.00, "Прекрасно! Теперь я могу продолжить свои эксперименты!" }, { 4.21, "Не знаю как благодарить тебя! Ты спас будущее гномьей науки!" } } } } },
    [2925] = { d = 32.0, v = "nightelf-male#59", n = { x = 376 }, c = { x = { { 0.00, "Мой друг, гном Клацморт Гайкокрут из Стальгорна, прислал мне письмо, в котором сообщает, что ему необходима помощь." }, { 7.86, "Ему нужно отправиться в Гномреган, некогда величайший город гномов, который был осквернён, и теперь его населяют лишь безумные гномы и их жуткие изобретения." }, { 18.71, "Я не могу покинуть Дарнасс, но душа моя болит за друга." }, { 22.46, "Если ты сможешь помочь ему вместо меня, благодарности моей не будет предела." }, { 27.98, "Ты найдёшь Клацморта в Городе Механиков в Стальгорне." } } }, t = { d = 7.0, g = 1, v = "gnome-male", n = { x = 58 }, c = { m = { { 0.00, "Да! Да! Мне очень нужна помощь в Гномрегане! И герой вроде тебя как раз подойдёт!" } }, f = { { 0.00, "Да! Да! Мне очень нужна помощь в Гномрегане! И героиня вроде тебя как раз подойдёт!" } } } } },
    [2926] = { d = 35.3, v = "gnome-male", n = { x = 409 }, c = { x = { { 0.00, "С самого дня нашего бегства из города Гноарном думает только о том, как выставить троггов из Гномрегана и очистить город от заражения." }, { 10.52, "У нас с Раззлом есть некоторые идеи на этот счёт, однако похоже, что воплотить их в жизнь сможет только настоящий безумец." }, { 18.70, "Мы ещё не знаем, сработает ли наш замысел – надо всё как следует проверить!" }, { 23.81, "Для этого нам потребуются радиоактивные осадки, оставляемые облучёнными троггами в Гномрегане. Это зелёная светящаяся субстанция." }, { 32.56, "Наполни ею этот фиал и принеси мне!" } } }, t = { d = 15.4, v = "gnome-male", n = { x = 172 }, c = { x = { { 0.00, "Прекрасно! Теперь пришла пора опробовать нашу новую формулу." }, { 4.09, "Если этот метод сработает, я не только смогу вылечить этого несчастного лепрогнома, но и вернуть свою утраченную шевелюру! Ну-ка, отойди в сторонку!" } } } } },
    [2927] = { d = 36.1, g = 1, v = "gnome-male", n = { m = 392, f = 394 }, c = { m = { { 0.00, "Вы ведь не думаете, что я всегда был лысым? Нет, сударь! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане." }, { 8.35, "До тех пор я был единственным кудрявым гномом во всём Азероте." }, { 13.01, "*Гноарн потрясает в воздухе кулаком.*" }, { 15.91, "Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!!" }, { 20.88, "Может, ещё не поздно. Мы ещё можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе." }, { 30.85, "Они со своим партнёром Раззлом как раз пытаются решить эту проблему." } }, f = { { 0.00, "Вы ведь не думаете, что я всегда был лысым? Нет, сударыня! Эту трагическую утрату волос вызвала утечка радиации в Гномрегане." }, { 8.47, "До тех пор я был единственным кудрявым гномом во всём Азероте." }, { 13.13, "*Гноарн потрясает в воздухе кулаком.*" }, { 16.03, "Будь прокляты эти проклятые грязные трогги, будь они все прокляты!!!" }, { 20.99, "Может, ещё не поздно. Мы ещё можем исправить дело – я хочу сказать, спасти город! Поговорите с Оззи Триггервольтом в Караносе." }, { 30.96, "Они со своим партнёром Раззлом как раз пытаются решить эту проблему." } } }, t = { d = 28.2, v = "gnome-male", n = { x = 319 }, c = { x = { { 0.00, "Я думал, что утрата волос нашим выдающимся главой убьёт его, так нет, выжил!" }, { 5.98, "Я стоял рядом с ним, когда тот схватил дозу. И эти замечательные коричневые локоны посыпались на пол прядями! Клочьями!" }, { 14.12, "Ужас произошедшего только усилился, когда у Гроана крыша поехала! Да!" }, { 18.88, "Гроан, не веря глазам своим, коснулся лысой головы, и во взгляде его загорелась месть! И тогда он обрушился на троггов! Оззи ёжится." } } } } },
    [2928] = { d = 32.4, v = "gnome-female", n = { x = 358 }, c = { x = { { 0.00, "Это ужасно. У нас, видно, не хватит запчастей, чтобы собрать всю партию автогиробуророек, которую пора отправить в Дун Морог." }, { 9.79, "Что нам точно нужно – так это детали. И для добычи этих деталей не найти места лучше, чем Гномреган!" }, { 16.71, "Я слышала, что роботы и механизмы, оставшиеся там, бродят по городу как овцы на вольном пастбище." }, { 23.81, "Я хочу от вас, чтобы вы отправились в Гномреган и распотрошили этих роботов на запчасти. Двух дюжин деталей должно хватить." } } }, t = { d = 8.1, v = "gnome-female", n = { x = 76 }, c = { x = { { 0.00, "Это отлично подойдёт. Считайте, что одна автогиробуроройка отремонтирована. Осталось ещё триста девяносто восемь." } } } } },
    [2930] = { d = 39.1, v = "gnome-male", n = { x = 425 }, c = { x = { { 0.00, "Когда мы бежали из Гномрегана, то оставили там столько данных! Жизненно важных данных!" }, { 6.78, "Мне нужны данные с призматической перфокарты чрезвычайно секретного терминала матричного перфографа три тысячи пять-D, что находится в глубинах Гномрегана." }, { 17.32, "Вам нужно добраться до терминала, но сначала надо получить допуск..." }, { 21.92, "а для этого надо добраться до терминалов низшего уровня защиты – моделей -A, -B и -C." }, { 27.33, "А для ЭТОГО вам понадобятся перфокарты допуска, начиная с белой... а все перфокарты остались в городе." }, { 35.92, "Это же катастрофа! Вы можете помочь нам?" } } }, t = { d = 15.0, v = "gnome-male", n = { x = 174 }, c = { x = { { 0.00, "У вас получилось! Вы нашли призматическую перфокарту и восстановили утраченные данные!" }, { 6.05, "Жизненно, критически, безмерно важные данные, без которых мы просто не смогли бы жить!" }, { 12.18, "Вашу услугу гномы запомнят надолго." } } } } },
    [2931] = { d = 32.7, v = "gnome-male", n = { x = 348 }, c = { x = { { 0.00, "Стальгорнский главный механик Чугунотрубз ищет искателей приключений!" }, { 5.79, "Он собирает отряд для проникновения в Гномреган с целью возвращения данных чрезвычайной важности и секретности." }, { 13.72, "Хотя Чугунотрубз и не состоит в Просвещённой ассамблее чарологии, алхимии и инженерных наук, подобно мне, но он гном толковый, и если он считает это дело важным, то, по моим подсчётам, оно с вероятностью восемьдесят четыре процента важное! Шансы хорошие!" } } }, t = { d = 6.9, v = "gnome-male", n = { x = 78 }, c = { x = { { 0.00, "Я готовлю миссию в Гномреган для возвращения важных данных. Если вы пришли помочь, то слушайте!" } } } } },
    [2951] = { d = 33.8, v = "human-male#114", n = { x = 313 }, c = { x = { { 0.00, "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений." }, { 6.24, "Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\"." }, { 12.98, "Ваши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер пять тысяч двести легко справится с этой проблемой!" }, { 23.26, "Опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." } } }, t = { d = 15.6, v = "human-male#114", n = { x = 156 }, c = { x = { { 0.00, "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь." }, { 11.46, "Металлический корпус аппарата скрипит и вибрирует." } } } } },
    [2962] = { d = 32.8, v = "gnome-male", n = { x = 401 }, c = { x = { { 0.00, "Этого образца не только недостаточно для опытов, он ещё и загрязнён." }, { 5.03, "Нам нужно более сильное зелёное свечение. Для наших целей эти трогги явно недостаточно облучены." }, { 11.59, "Вам придётся отправиться в Гномреган и принести некоторое количество радиоактивных образцов прямо с носителей." }, { 19.04, "Я говорю об облучённых слизнюках, шнырюках и ужасниках. Будьте начеку: образцы хранить очень трудно." }, { 25.85, "Возможно, придётся сделать несколько попыток, пока вы не принесёте достаточное количество образцов." } } }, t = { d = 10.8, v = "gnome-male", n = { x = 96 }, c = { x = { { 0.00, "Оззи рассматривает вас. Впечатляюще, у вас не отвалилась ни одна конечность! Ну-с, посмотрим, на что сгодится эта проба!" } } } } },
    [2983] = { d = 30.4, g = 1, v = "orc-male", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Много времени прошло с тех пор, как ты прошёл последнее испытание." }, { 4.70, "Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу!" }, { 11.81, "Стихия огня – твоя, если только ты готов заплатить за это знание." }, { 16.67, "Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка." }, { 22.90, "Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!" } }, f = { { 0.00, "Много времени прошло с тех пор, как ты прошла последнее испытание." }, { 4.58, "Пока тебе хватало терпения в твоих занятиях, однако пришло время обрести новую силу... подлинную силу!" }, { 11.68, "Стихия огня – твоя, если только ты готова заплатить за это знание." }, { 16.74, "Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка." }, { 22.96, "Только осторожнее: если окажешься в землях этих проклятых ночных эльфов, значит, тебя занесло не туда!" } } }, t = { d = 27.0, g = 1, v = "orc-male", n = { m = 288, f = 289 }, c = { m = { { 0.00, "Что, тебя Сварт прислал, да?" }, { 2.39, "Ну, на Сварта положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня." }, { 9.66, "Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг..." }, { 18.74, "Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." } }, f = { { 0.00, "Что, тебя Сварт прислал, да?" }, { 2.39, "Ну, на Сварта положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня." }, { 9.18, "Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг..." }, { 18.26, "Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." } } } } },
    [2984] = { d = 33.5, g = 1, v = "tauren-male#68", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание!" }, { 6.18, "Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу." }, { 14.84, "Тебе следует овладеть стихией огня – если только ты готов платить за это." }, { 20.80, "Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка." }, { 27.19, "Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" } }, f = { { 0.00, "Много времени прошло с тех пор, как тебе пришлось выдержать последнее испытание!" }, { 6.18, "Тебе удалось научиться терпению, но теперь тебе пришло время сделать новый шаг. Пора учиться разрушению и хаосу." }, { 14.84, "Тебе следует овладеть стихией огня – если только ты готова платить за это." }, { 20.88, "Отыщи в Степях Кранала Фисса. Он живёт в небольшой хижине к северу от Перекрёстка." }, { 27.28, "Только осторожнее: если промахнёшься, можешь очутиться в землях ночных эльфов!" } } }, t = { d = 26.8, g = 1, v = "orc-male", n = { m = 286, f = 287 }, c = { m = { { 0.00, "Что, тебя Нарм прислал, да?" }, { 2.27, "Ну, на Нарма положиться можно. Значит, ты уже готов вкусить следующую сапту – сапту огня." }, { 9.39, "Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг..." }, { 18.47, "Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." } }, f = { { 0.00, "Что, тебя Нарм прислал, да?" }, { 2.27, "Ну, на Нарма положиться можно. Значит, ты уже готова вкусить следующую сапту – сапту огня." }, { 9.50, "Да, я уже вижу в твоих глазах огонь стремления к познанию! Тебе довелось вкусить власти, и теперь тебе пора сделать новый шаг..." }, { 18.58, "Но терпение. Помни, чему тебя научила земля. Власть разрушения обрести нетрудно, но следует знать, где остановиться." } } } } },
    [2985] = { d = 20.6, g = 1, v = "orc-male", n = { m = 226, f = 228 }, c = { m = { { 0.00, "Похоже, ты готов к новому испытанию. Ты проявил немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды." }, { 10.26, "Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." } }, f = { { 0.00, "Похоже, ты готова к новому испытанию. Ты проявила немало упорства в учении, и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды." }, { 10.39, "Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." } } }, t = { d = 18.6, v = "tauren-female#71", n = { x = 174 }, c = { x = { { 0.00, "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды." }, { 10.24, "Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." } } } } },
    [2986] = { d = 27.6, g = 1, v = "tauren-male#68", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Много воды утекло со времени последнего испытания. Ты проявил немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды." }, { 12.14, "Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." } }, f = { { 0.00, "Много воды утекло со времени последнего испытания. Ты проявила немало упорства в учении и пришло время сделать новый шаг. Пора тебе узнать о чистоте воды." }, { 13.44, "Отыщи Ислен Заклинательницу Воды. Она живёт в рыбацкой лачуге в Степях, на восточном побережье, к югу от реки Строптивой и Кабестана. Удачи." } } }, t = { d = 18.5, v = "tauren-female#71", n = { x = 174 }, c = { x = { { 0.00, "Ветер следует за тобой, по земле ты шагаешь твёрдо, а дух уже согрет огнём – я бы сказала, что пришло время познать чистоту воды." }, { 10.18, "Путь твой был долог, и сила духа позволит тебе пройти ещё дальше. Но первый шаг делать тебе." } } } } },
    [2996] = { d = 23.0, v = "orc-male", n = { x = 238 }, c = { x = { { 0.00, "Я многому тебя научил, теперь тебе нужен новый наставник. Он живёт в Кабестане, его зовут Страхад." }, { 8.19, "Он человек, но он отнюдь не слаб. Он невелик ростом, но силён!" }, { 12.62, "Ты уже можешь вызывать более могущественных существ, и он научит тебя этому. Ступай к нему." }, { 19.15, "Он живёт в Кабестане, над портом, рядом с башней." } } }, t = { d = 16.3, v = "human-male#50", n = { x = 184 }, c = { x = { { 0.00, "Шумный денёк в Кабестане, не так ли? Обожаю наблюдать за суетой портового города. Столько тайн, столько приключений…" }, { 8.07, "и столько неведения." }, { 9.93, "Это что, ненависть я вижу в твоих глазах? Превосходно. Мы найдём ей достойное применение." } } } } },
    [2997] = { d = 32.2, v = "dwarf-male", n = { x = 329 }, c = { x = { { 0.00, "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, посети Стальгорн и поговори с одной из самых почитаемых наших сестёр – Тизой Кузнебой." }, { 16.76, "Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от тебя." }, { 26.36, "Ты можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии. Удачи тебе." } } }, t = { d = 5.6, v = "dwarf-female#33", n = { x = 61 }, c = { x = { { 0.00, "Привет тебе. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." } } } } },
    [2998] = { d = 27.4, g = 1, v = "human-male", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Приветствую тебя, брат мой. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе." }, { 7.60, "Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать." }, { 15.26, "На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время." }, { 22.75, "Ищи его в Соборе Света: там он проводит большую часть времени." } }, f = { { 0.00, "Приветствую тебя, сестра моя. Даториан Ралл, один из самых влиятельных паладинов Оплота, недавно говорил о тебе." }, { 7.71, "Он считает, что тебе пора пройти некое испытание... Он вообще весьма неплохо о тебе отзывался, надо сказать." }, { 15.37, "На твоём месте я бы отправился в Штормград и поговорил с ним – разумеется, если у тебя найдётся на это время." }, { 22.86, "Ищи его в Соборе Света: там он проводит большую часть времени." } } }, t = { d = 5.9, v = "human-male", n = { x = 61 }, c = { x = { { 0.00, "Как красив Штормград, не правда ли?.." }, { 2.78, "Твой визит в это время более чем уместен." } } } } },
    [2999] = { d = 25.3, v = "dwarf-male", n = { x = 267 }, c = { x = { { 0.00, "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Дун Морога, но когда тебе выпадет свободная минутка, поднимись наверх и поговори с одной из наших самых почитаемых сестёр – Тизой Кузнебой." }, { 15.71, "Она одна из тех, к кому обращаются самые молодые паладины, когда приходит пора им узнать побольше о Свете и том, что от тебя ожидается." } } }, t = { d = 5.6, v = "dwarf-female#33", n = { x = 61 }, c = { x = { { 0.00, "Привет тебе. Надеюсь, Свет укажет тебе истинный путь и сохранит тебя от зла." } } } } },
    [3000] = { d = 26.3, v = "human-male", n = { x = 300 }, c = { x = { { 0.00, "Привет. Я знаю, что ты рук не покладаешь, помогая жителям Азерота, но когда тебе выпадет свободная минутка, вернись в Стальгорн и поговори с Тизой Кузнебой." }, { 10.59, "Она одна из тех, к кому обращаются самые молодые дворфские паладины, когда приходит пора им узнать побольше о Свете и том, что ожидается от всех нас." }, { 21.35, "Ты можешь найти её на верхнем этаже Зала Тайн, что в Палатах Магии." } } }, t = { d = 2.5, v = "dwarf-female#33", n = { x = 27 }, c = { x = { { 0.00, "Приветствую и добро пожаловать." } } } } },
    [3001] = { d = 37.6, v = "scourge-male#82", n = { x = 300 }, c = { x = { { 0.00, "Я многому тебя научил, и теперь тебе нужен новый наставник. Он живёт в Кабестане, его зовут Страхад." }, { 10.09, "Это человек, но отнюдь не слабый. Также у нас нет причин смотреть на него как на потенциального врага..." }, { 21.19, "по крайней мере, пока что. Он обладает силой и заслуживает уважения." }, { 28.04, "Я чувствую в тебе готовность призывать более могущественных существ, и он может обучить тебя этому." } } }, t = { d = 15.3, v = "human-male#50", n = { x = 166 }, c = { x = { { 0.00, "Всегда жизнь в Кабестане, бьёт ключом, не так ли. Ну так, на то он и порт." }, { 5.43, "Столько всяких тайн, столько приключений, столько невежества…" }, { 9.96, "Я вижу ненависть в твоих глазах? Хорошо, мы найдём ей полезное применение." } } } } },
    [3065] = { d = 13.9, v = "orc-male#60", n = { x = 150 }, c = { x = { { 0.00, "А! Тебе тут пергамент прислали, пока тебя не было." }, { 3.95, "Прочитай, когда время будет. Это, кажется, от Франга, наставника воинов. Он хочет с тобой поговорить." }, { 10.74, "Он обычно сидит в тени у входа в Логово." } } }, t = { d = 20.0, g = 1, v = "orc-male#60", n = { m = 227, f = 228 }, c = { m = { { 0.00, "Наша долина – подходящее место, чтобы упражняться в воинских навыках." }, { 4.78, "Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готов продолжать обучение – возвращайся ко мне." }, { 13.04, "Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!" } }, f = { { 0.00, "Наша долина – подходящее место, чтобы упражняться в воинских навыках." }, { 4.78, "Будут вопросы – не стесняйся задавать их кому угодно, а когда решишь, что готова продолжать обучение – возвращайся ко мне." }, { 13.21, "Я ничем не уступаю любому из здешних воинов и охотно обучу тебя всему... хотя и не бесплатно!" } } } } },
    [3082] = { d = 12.1, v = "orc-male#60", n = { x = 123 }, c = { x = { { 0.00, "А! Тебе тут табличку прислали, пока тебя не было." }, { 3.82, "Прочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить." } } }, t = { d = 28.6, g = 1, v = "troll-female#75", n = { m = 304, f = 305 }, c = { m = { { 0.00, "Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники." }, { 7.52, "Не забывай об этом, а Джен'шан не забудет о тебе." }, { 11.20, "Джен'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают." }, { 17.68, "И тебя ждёт большое будущее – помни это!" }, { 21.02, "Будет надо – приходи к Джен'шан. Она тебя научит всему, чему сможет, когда ты будешь готов." } }, f = { { 0.00, "Теперь мы учим их пути охотника, а они учат нас другим вещам. Мы теперь одна раса... почти. Мы давнишние союзники." }, { 7.52, "Не забывай об этом, а Джен'шан не забудет о тебе." }, { 11.20, "Джен'шан научит тебя ремеслу охотника – хорошо научит! Помни: охотника в племени всегда уважают." }, { 17.68, "И тебя ждёт большое будущее – помни это!" }, { 21.02, "Будет надо – приходи к Джен'шан. Она тебя научит всему, чему сможет, когда ты будешь готова." } } } } },
    [3083] = { d = 11.4, v = "orc-male#60", n = { x = 122 }, c = { x = { { 0.00, "А! Тебе тут табличку прислали, пока тебя не было." }, { 3.82, "Прочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить." } } }, t = { d = 24.3, g = 1, v = "orc-male", n = { m = 263, f = 264 }, c = { m = { { 0.00, "Пока не придёт время, ты будешь под моим присмотром. Я покажу тебе основы, как говорится." }, { 6.70, "Когда почувствуешь, что готов — приходи ко мне, и я подумаю, чему научить тебя дальше." }, { 12.96, "А до тех пор — оттачивай свои навыки и держи их наточенными, как бритву." }, { 18.03, "Никогда не знаешь, когда даже самое незначительное умение может спасти тебе жизнь." } }, f = { { 0.00, "Пока не придёт время, ты будешь под моим присмотром. Я покажу тебе основы, как говорится." }, { 6.70, "Когда почувствуешь, что готова — приходи ко мне, и я подумаю, чему научить тебя дальше." }, { 13.06, "А до тех пор — оттачивай свои навыки и держи их наточенными, как бритву." }, { 18.14, "Никогда не знаешь, когда даже самое незначительное умение может спасти тебе жизнь." } } } } },
    [3084] = { d = 11.8, v = "orc-male#60", n = { x = 120 }, c = { x = { { 0.00, "А! Тебе тут табличку прислали, пока тебя не было." }, { 3.82, "Прочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить." } } }, t = { d = 32.9, v = "orc-female", n = { x = 363 }, c = { x = { { 0.00, "Ты, вероятно, уже знаешь, что могущество нам дают стихии. Огонь, земля, вода и воздух – вот наши орудия." }, { 7.37, "Наша сила исходит от духов предков. Мы должны вести наш народ." }, { 11.90, "Для городов и деревень, где мы бываем, мы должны стать тем же, чем стал Тралл для всей Орды." }, { 18.39, "У нас будут просить совета и защиты. Но чтобы этого добиться, тебе потребуется немало трудов." }, { 24.96, "Когда ты почувствуешь, что у тебя накопилось достаточно сил, приходи ко мне, и я научу тебя всему, чему смогу." } } } } },
    [3085] = { d = 11.2, v = "orc-male#60", n = { x = 119 }, c = { x = { { 0.00, "А! Тебе тут табличку прислали, пока тебя не было." }, { 3.82, "Прочитай, когда время будет. Это, кажется, от Кен'джая, наставника жрецов. Он хочет с тобой поговорить." } } }, t = { d = 25.4, g = 1, v = "troll-male#78", n = { m = 276, f = 277 }, c = { m = { { 0.00, "Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе всё лучше и лучше..." }, { 6.16, "В какой-то момент тебе поможет старый Кен'джай! Приходи потолковать с мной, когда будешь готов." }, { 12.71, "И если духи согласятся, мы научим тебя кое-чему ещё... но только если они согласятся!" }, { 20.18, "Ну, ступай, потолкуй со другими здешними жителями. И про меня не забывай." } }, f = { { 0.00, "Почаще пускай в ход полученные знания и увидишь, что духи повинуются тебе всё лучше и лучше..." }, { 6.16, "В какой-то момент тебе поможет старый Кен'джай! Приходи потолковать с мной, когда будешь готова." }, { 12.67, "И если духи согласятся, мы научим тебя кое-чему ещё... но только если они согласятся!" }, { 20.14, "Ну, ступай, потолкуй со другими здешними жителями. И про меня не забывай." } } } } },
    [3086] = { d = 11.8, v = "orc-male#60", n = { x = 117 }, c = { x = { { 0.00, "А! Тебе тут табличку прислали, пока тебя не было." }, { 3.82, "Прочитай, когда время будет. Это, кажется, от Май'ах, наставницы магов. Она хочет с тобой поговорить." } } }, t = { d = 31.2, g = 1, v = "troll-female#73", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Да, скоро ты станешь очень могущественным! И всё это узнают... некоторые – на собственной шкуре!" }, { 6.71, "Но берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча." }, { 14.64, "И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее." }, { 23.95, "Когда решишь, что готов учиться, возвращайся к Май'ах. Она тебя всему научит, не беспокойся!" } }, f = { { 0.00, "Да, скоро ты станешь очень могущественной! И всё это узнают... некоторые – на собственной шкуре!" }, { 6.77, "Но берегись! Бойся не орков, не эльфов и не дворфов. Бояться надо тех, кого не увидишь простым глазом. Магия могуча." }, { 14.70, "И иногда заставляет творить то, чего не хочется. А иногда заставляет считать себя сильнее, чем ты есть. Будь терпеливее. Будь умнее." }, { 24.01, "Когда решишь, что готова учиться, возвращайся к Май'ах. Она тебя всему научит, не беспокойся!" } } } } },
    [3087] = { d = 12.2, v = "orc-male#60", n = { x = 124 }, c = { x = { { 0.00, "А! Тебе тут пергамент прислали, пока тебя не было." }, { 3.95, "Прочитай, когда время будет. Это, кажется, от Джен'шан, наставницы охотников. Она хочет с тобой поговорить." } } }, t = { d = 23.3, v = "troll-female#75", n = { x = 252 }, c = { x = { { 0.00, "Когда мы закончим беседу, поговори с остальными обитателями долины." }, { 4.48, "Они будут просить тебя что-нибудь сделать для них – и каждое такое задание будет для тебя проверкой на прочность." }, { 12.28, "Наберёшься мудрости и опыта – приходи к Джен'шан, она научит тебя новым приёмам и навыкам. Возвращайся к Джен'шан как можно чаще." } } } } },
    [3088] = { d = 11.5, v = "orc-male#60", n = { x = 123 }, c = { x = { { 0.00, "А! Тебе тут пергамент прислали, пока тебя не было." }, { 3.95, "Прочитай, когда время будет. Это, кажется, от Руага, наставника разбойников. Он хочет с тобой поговорить." } } }, t = { d = 24.5, g = 1, v = "orc-male", n = { m = 271, f = 272 }, c = { m = { { 0.00, "Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно." }, { 8.61, "Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу..." }, { 16.72, "за умеренную плату. Возвращайся ко мне, когда решишь, что готов, и мы посмотрим, чему можно тебя научить." } }, f = { { 0.00, "Клан Изувеченной Длани просил меня позаботиться о тебе. Они хотят, чтобы я обучил тебя и сообщал тебе о том, что им нужно." }, { 8.61, "Даже если ты пока не стремишься им помогать – хотя это было бы глупо с твоей стороны, – я обучу тебя всему, чему смогу..." }, { 16.72, "за умеренную плату. Возвращайся ко мне, когда решишь, что готова, и мы посмотрим, чему можно тебя научить." } } } } },
    [3089] = { d = 11.9, v = "orc-male#60", n = { x = 121 }, c = { x = { { 0.00, "А! Тебе тут пергамент прислали, пока тебя не было." }, { 3.95, "Прочитай, когда время будет. Это, кажется, от Шикрик, наставницы шаманов. Она хочет с тобой поговорить." } } }, t = { d = 28.3, g = 1, v = "orc-female", n = { m = 325, f = 326 }, c = { m = { { 0.00, "Ты станешь тем, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку." }, { 7.99, "Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать." }, { 15.51, "Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится." }, { 21.87, "Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готов." } }, f = { { 0.00, "Ты станешь той, через кого говорят предки. Сила стихий будет в твоей власти – достаточно лишь будет протянуть руку." }, { 7.95, "Внести смятение в ряды врагов будет проще простого, а исцелять союзников станет так же просто, как дышать." }, { 15.47, "Помни об этом, когда встретишься с новыми испытаниями. Возвращайся ко мне, если понадобится." }, { 21.83, "Я буду учить тебя новым заклинаниям и наставлю на верный путь, когда ты будешь готова." } } } } },
    [3090] = { d = 17.0, v = "orc-male#60", n = { x = 185 }, c = { x = { { 0.00, "А! Тебе тут пергамент прислали, пока тебя не было." }, { 3.95, "Я лично стараюсь не иметь дела с чернокнижниками, однако ты его всё-таки прочитай, когда время будет." }, { 11.04, "Это, кажется, от твоего нового наставника, Нартока. Он хочет с тобой поговорить." } } }, t = { d = 30.7, v = "orc-male", n = { x = 337 }, c = { x = { { 0.00, "Теперь и ты в наших рядах! Но не обманывайся." }, { 3.34, "Да, ты имеешь доступ к могуществу, которому многие завидуют, но это не означает, что к тебе будут относиться с почтением." }, { 11.75, "Тралл пускает нас в Оргриммар, ведь мы его сородичи – а иначе мы стали бы такими же жалкими, как люди, что держали его в рабстве." }, { 20.67, "И всё же будь осторожен. Да, в твоих руках могущество, но если будешь глуп, – погибнешь." }, { 27.19, "Понадобятся новые заклинания – приходи ко мне." } } } } },
    [3091] = { d = 15.0, v = "tauren-male", n = { x = 138 }, c = { x = { { 0.00, "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя." }, { 7.60, "Думаю, она от наставника воинов Харутта. На твоём месте я бы прочитал её поскорее." } } }, t = { d = 33.4, g = 1, v = "tauren-male", n = { m = 304, f = 305 }, c = { m = { { 0.00, "Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды." }, { 7.24, "Никогда не позволяй гордыне ослепить тебя и заставить думать иначе." }, { 12.92, "Я тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков." }, { 21.87, "Возвращайся ко мне, когда будешь готов, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени!" } }, f = { { 0.00, "Каждый из нас играет свою роль в племени. Каждый из нас должен проходить одни и те же обряды." }, { 7.24, "Никогда не позволяй гордыне ослепить тебя и заставить думать иначе." }, { 12.92, "Я тут обучаю новых воинов, желающих снискать славы в битве и последовать по пути своих предков." }, { 21.87, "Возвращайся ко мне, когда будешь готова, и я научу тебя всему, что умею. Иди, и да пребудет с тобой благословение племени!" } } } } },
    [3092] = { d = 15.0, v = "tauren-male", n = { x = 139 }, c = { x = { { 0.00, "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя." }, { 7.60, "Думаю, она от наставника охотников Ланко. На твоём месте я бы прочитал её поскорее." } } }, t = { d = 27.4, v = "tauren-male", n = { x = 266 }, c = { x = { { 0.00, "А моя задача — подготовить тебя, обучив основам нашего ремесла: как приручать питомца, как метко стрелять из ружья и многим другим навыкам, которые тебе пригодятся." }, { 14.24, "Охотники — важная часть нашей традиции и истории. Помни об этом: ты — неотъемлемая часть племени." }, { 21.77, "Если будешь служить народу с честью, тебя будут уважать и почитать." } } } } },
    [3093] = { d = 14.2, v = "tauren-male", n = { x = 136 }, c = { x = { { 0.00, "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставницы шаманов Милы." }, { 10.67, "На твоём месте я бы прочитал её поскорее." } } }, t = { d = 20.7, g = 1, v = "tauren-female#71", n = { m = 202, f = 202 }, c = { m = { { 0.00, "Мы ещё не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильным... чуть более подготовленным." }, { 9.47, "Твой дух будет пылать подобно Неугасимому пламени." }, { 13.78, "А теперь ступай, испытай себя! Возвращайся, если тебе понадобится моя помощь." } }, f = { { 0.00, "Мы ещё не раз встретимся с тобой, и каждый раз ты будешь уходить от меня чуть более сильной... чуть более подготовленной." }, { 9.42, "Твой дух будет пылать подобно Неугасимому пламени." }, { 13.72, "А теперь ступай, испытай себя! Возвращайся, если тебе понадобится моя помощь." } } } } },
    [3094] = { d = 15.3, v = "tauren-male", n = { x = 137 }, c = { x = { { 0.00, "Привет! Слушай, минуту назад ко мне подошёл посыльный и передал вот эту записку для тебя. Думаю, она от наставника друидов Гарта." }, { 11.81, "На твоём месте я бы прочитал её поскорее." } } }, t = { d = 28.1, g = 1, v = "tauren-male#68", n = { m = 285, f = 286 }, c = { m = { { 0.00, "Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения." }, { 6.70, "Гордыня ослепляет их, но это не твоя забота." }, { 10.09, "Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готов." }, { 18.10, "Приходи ко мне почаще. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя её учению." } }, f = { { 0.00, "Хоть у нас и ночных эльфов есть что-то общее, не стоит ждать от них хорошего отношения." }, { 6.70, "Гордыня ослепляет их, но это не твоя забота." }, { 10.09, "Сосредоточь свой разум на уроках Матери-Земли, а я научу тебя тому, что знаю, когда ты будешь готова." }, { 18.29, "Приходи ко мне почаще. Ты узнаешь, что Мать-Земля дарует величайшие способности тем, кто полностью посвящает себя её учению." } } } } },
    [3095] = { d = 27.0, g = 1, v = "scourge-male#82", n = { m = 212, f = 213 }, c = { m = { { 0.00, "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали." }, { 8.75, "Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника воинов Даннала." }, { 18.33, "Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." } }, f = { { 0.00, "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали." }, { 8.80, "Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника воинов Даннала." }, { 18.38, "Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." } } }, t = { d = 35.0, g = 1, v = "scourge-male", n = { m = 365, f = 373 }, c = { m = { { 0.00, "Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь." }, { 7.60, "Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты был достойным бойцом." }, { 15.24, "А теперь иди и проверь свои боевые навыки. Многое ты поймёшь сам со временем, а кое-что я и вовсе не вправе поведать тебе." }, { 24.41, "Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом." } }, f = { { 0.00, "Я здесь, чтобы обучать тебя по мере того, как ты будешь набираться опыта... приходи как только захочешь." }, { 7.60, "Я беру минимальную плату за уроки и научу тебя всему, чему смогу, чтобы ты была достойной воительницей." }, { 15.66, "А теперь иди и проверь свои боевые навыки. Многое ты поймёшь сама со временем, а кое-что я и вовсе не вправе поведать тебе." }, { 24.85, "Просто знай, что в будущем Сильване потребуются помощники – такие, как ты. Ты станешь главной опорой нашего освобождения. Помни об этом." } } } } },
