    [3099] = { d = 27.3, g = 1, v = "scourge-male#82", n = { m = 226, f = 227 }, c = { m = { { 0.00, "А, вот и ты! Пока ты разбирался с безмозглыми тварями, тебе тут свиток прислали." }, { 8.82, "Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника чернокнижников Максимиллиона." }, { 18.79, "Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." } }, f = { { 0.00, "А, вот и ты! Пока ты разбиралась с безмозглыми тварями, тебе тут свиток прислали." }, { 8.21, "Я думаю, в нём что-то важное, поскольку на нём, похоже, стоит печать наставника чернокнижников Максимиллиона." }, { 18.18, "Я бы на твоём месте потратил время на его изучение, прежде чем пускаться в дальнейший путь." } } }, t = { d = 48.1, v = "scourge-male#82", n = { x = 417 }, c = { x = { { 0.00, "Я говорил, что раб всегда останется рабом, кто бы ни был хозяином. Помнишь?" }, { 6.86, "Мы оба знаем, что именно этот тип контроля – этот самый вид силы – зовёт нас. Мы хотим, чтобы существа служили нам." }, { 17.30, "Мы знаем, что мы более могуществены и заслуживаем большего уважения, чем другие оказывают нам... и теперь мы хотим взять своё." }, { 28.95, "Я буду твоим союзником в этой борьбе – борьбе за нашу собственную свободу. Свободу искать своих собственных союзников." }, { 39.50, "Когда почувствуешь, что время настало, возвращайся ко мне – и я научу тебя всему, что знаю." } } } } },
    [3100] = { d = 19.1, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.95, "Похоже, что на нём стоит печать Ллана, местного наставника воинов." }, { 10.48, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 23.1, v = "human-male#50", n = { x = 276 }, c = { x = { { 0.00, "Разберись в обстановке, изучи местность и возвращайся, как только тебе потребуется обучение. Я тут в любое время дня и ночи." }, { 8.70, "Рыцари Серебряной Длани постарались, чтобы эти места стали почти безопасными, но если ты поговоришь с горожанами, то, думаю, заметишь, что у всех найдутся проблемы, с которыми без помощи воина не разобраться. Удачи!" } } } } },
