    [3103] = { d = 19.3, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.93, "Похоже, что на нём стоит печать Анетты, местной наставницы жрецов." }, { 10.43, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 15.5, v = "human-female#45", n = { x = 178 }, c = { x = { { 0.00, "Как только ты наберёшься опыта, возвращайся ко мне, и я, как сумею, поделюсь с тобой своими знаниями." }, { 6.90, "А пока ступай с милосердием в сердце, и пусть мудрость ведёт тебя. Помни, мир станет лучше, только если мы сами исцелим его." } } } } },
    [3104] = { d = 19.3, v = "human-male", n = { x = 226 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.88, "Похоже, что на нём стоит печать Келдена, местного наставника магов." }, { 10.49, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } }, t = { d = 24.7, g = 1, v = "human-male", n = { m = 268, f = 270 }, c = { m = { { 0.00, "Ха-ха, я знал, что не ошибусь адресом! Значит, ты готов принять свою судьбу?" }, { 5.31, "Готов бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу?" }, { 12.13, "Не скрою, тебя будут не только уважать, но и бояться." }, { 15.84, "Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее." } }, f = { { 0.00, "Ха-ха, я знал, что не ошибусь адресом! Значит, ты готова принять свою судьбу?" }, { 5.36, "Готова бросить вызов богам и любым другим силам, что встанут на твоём пути к знаниям и могуществу?" }, { 12.09, "Не скрою, тебя будут не только уважать, но и бояться." }, { 15.80, "Но знай и то, что я буду ждать тебя здесь, когда тебе понадобится обучение. Приходи ко мне, когда станешь опытнее." } } } } },
    [3105] = { d = 19.2, v = "human-male", n = { x = 225 }, c = { x = { { 0.00, "Меня просили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.66, "Похоже, что на нём печать Друзиллы, одной из наших местных наставниц." }, { 10.48, "На твоём месте я немедленно прочёл бы письмо, прежде чем заниматься какими бы то ни было другими делами здесь, в аббатстве." } } }, t = { d = 27.8, v = "human-female#47", n = { x = 344 }, c = { x = { { 0.00, "Чем могущественнее ты будешь становиться, тем сильнее будет искушение... так что не забывай обуздывать себя." }, { 7.09, "Ладно, скажу тебе прямо: любой, кто занимается тайными искусствами, может пасть." }, { 12.27, "Особенно тот, кто имеет дело с тварями из Круговерти Пустоты. Будь терпелив и благоразумен..." }, { 18.20, "но не давай благоразумию подавлять твои амбиции." }, { 21.59, "Как только ты станешь опытнее, возвращайся ко мне, и я открою тебе тайны нашего мастерства." } } } } },
    [3106] = { d = 14.2, v = "dwarf-male", n = { x = 164 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время." }, { 6.95, "Думаю, руну прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 25.9, v = "dwarf-male", n = { x = 285 }, c = { x = { { 0.00, "Я думаю, ты это уже знаешь, но на всякий случай скажу: в бою дворфы используют магию вместо ружей." }, { 7.36, "Кое-кто из нас чтит Священный Свет – так же, как и некоторые люди, и даже трогги. А вообще, тебе ещё многое предстоит узнать." }, { 15.95, "Я буду учить тебя воинскому мастерству." }, { 18.81, "Если захочешь узнать пару новых приёмов, приходи сюда, и мы посмотрим, что я могу для тебя сделать." } } } } },
    [3107] = { d = 14.4, v = "dwarf-male", n = { x = 169 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время." }, { 6.95, "Думаю, руну прислал Бромос, наставник паладинов. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 34.1, g = 1, v = "dwarf-male", n = { m = 402, f = 402 }, c = { m = { { 0.00, "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту." }, { 7.03, "Мы испытываем огромное уважение к традициям ордена." }, { 10.68, "Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение." }, { 17.00, "Думаю, нам обоим придётся немного поработать вместе." }, { 20.61, "Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело." }, { 29.21, "Негоже отправляться в далёкие странствия неподготовленным, верно?" } }, f = { { 0.00, "Люди многое поведали нам о Священном Свете и о том, как орден паладинов необходим им – и всему Азероту." }, { 7.03, "Мы испытываем огромное уважение к традициям ордена." }, { 10.68, "Поистине поразительно, что один человек, одна жертва может обратить погибель в спасение." }, { 17.00, "Думаю, нам обоим придётся немного поработать вместе." }, { 20.61, "Когда ты решишь, что время пришло, возвращайся ко мне: тебе нужно будет научиться кое-чему новому, прежде чем браться за дело." }, { 29.21, "Негоже отправляться в далёкие странствия неподготовленной, верно?" } } } } },
    [3108] = { d = 14.3, v = "dwarf-male", n = { x = 169 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время." }, { 6.95, "Думаю, руну прислал Торгас, наставник охотников. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 27.8, g = 1, v = "dwarf-male", n = { m = 317, f = 318 }, c = { m = { { 0.00, "Всегда нужно помнить об уважении к тому миру, в котором мы живём." }, { 4.42, "Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна." }, { 14.79, "Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя." }, { 22.25, "Когда ты решишь, что готов, приходи ко мне, и мы займёмся твоим обучением." } }, f = { { 0.00, "Всегда нужно помнить об уважении к тому миру, в котором мы живём." }, { 4.42, "Звери, которые решат сражаться на твоей стороне, сияние клинка, тяжесть брони, пронизывающий холод ветра – без всего этого твоя жизнь будет не полна." }, { 14.79, "Я сделаю всё, что смогу, чтобы познакомить тебя с ремеслом охотника, но знай: самое главное зависит от тебя." }, { 22.25, "Когда ты решишь, что готова, приходи ко мне, и мы займёмся твоим обучением." } } } } },
    [3109] = { d = 14.5, v = "dwarf-male", n = { x = 170 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время." }, { 6.95, "Думаю, руну прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 34.2, g = 1, v = "dwarf-male", n = { m = 396, f = 396 }, c = { m = { { 0.00, "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласен?" }, { 9.27, "Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик..." }, { 16.73, "Понимаешь, о чём я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет." }, { 23.72, "Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится." } }, f = { { 0.00, "Я вот думаю: если ты собираешься шататься по Холодной долине, рано или поздно тебе потребуется усовершенствовать свои навыки, согласна?" }, { 9.21, "Так вот, если тебе это будет нужно, приходи, и я научу тебя тому, что знаю: обманный выпад, хитрый приёмчик..." }, { 16.68, "Понимаешь, о чём я? Эти трюки позволят тебе остаться в живых и заработать несколько звонких монет." }, { 23.67, "Да, и приглядись повнимательнее к гномам: им несладко приходится с тех пор, как Гномреган был... скажем так, захвачен. Думаю, наша помощь им пригодится." } } } } },
    [3110] = { d = 14.3, v = "dwarf-male", n = { x = 168 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время." }, { 6.95, "Думаю, руну прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 23.0, g = 1, v = "dwarf-male", n = { m = 250, f = 252 }, c = { m = { { 0.00, "Я – тот, кто будет заниматься твоим обучением." }, { 3.07, "Когда будешь готов, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов." }, { 13.23, "Свет на твоей стороне, а с ним и весь Стальгорн... Эй, ты что разволновался? Это тебя ни к чему не обязывает... ну, почти ни к чему..." } }, f = { { 0.00, "Я – тот, кто будет заниматься твоим обучением." }, { 3.07, "Когда будешь готова, приходи ко мне: может быть, одно-два новых заклинания помогут тебе быстрее очистить долину от этих отвратительных троггов." }, { 13.19, "Свет на твоей стороне, а с ним и весь Стальгорн... Эй, ты что разволновалась? Это тебя ни к чему не обязывает... ну, почти ни к чему..." } } } } },
    [3112] = { d = 14.7, v = "dwarf-male", n = { x = 171 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время." }, { 7.30, "Думаю, записку прислал Тран, наставник воинов. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 26.3, v = "dwarf-male", n = { x = 287 }, c = { x = { { 0.00, "Да-да, теперь я окончательно понял, чего хотят гномы. И знаешь что?" }, { 4.69, "Даю слово, я сделаю всё возможное, чтобы ты и твои родичи смогли отвоевать свой дом." }, { 11.34, "Да, вот ещё что: когда почувствуешь, что готова к обучению, приходи к старине Трану – я с радостью поделюсь с тобой всем, что знаю." }, { 20.09, "Конечно, не за просто так, но ты можешь не беспокоиться: цена невысока. Ну, до встречи!" } } } } },
    [3113] = { d = 15.1, v = "dwarf-male", n = { x = 177 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время." }, { 7.30, "Думаю, записку прислал Сольм, наставник разбойников. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 33.8, v = "dwarf-male", n = { x = 387 }, c = { x = { { 0.00, "Я стараюсь не привлекать к себе особого внимания, так что если где-то что-то и пропадает, наша репутация от этого не страдает." }, { 8.61, "Если тебе потребуется чему-нибудь подучиться или ещё что, приходи в любое время." }, { 14.48, "Ну, мы ведь с тобой друг друга понимаем? Мы-то знаем, что бывают времена, когда верить можно только семье..." }, { 21.71, "и такие времена сейчас настали, верно? Гномреган... захвачен, и, думаю, это была не последняя беда, которая на нас свалилась..." }, { 30.08, "но мы с тобой всегда прикроем друг другу спину, да?" } } } } },
    [3114] = { d = 16.0, v = "dwarf-male", n = { x = 173 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время." }, { 7.30, "Думаю, записку прислал Маррайк, наставник магов. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 28.2, v = "gnome-male", n = { x = 311 }, c = { x = { { 0.00, "О, да! Тайная магия... Конечно-конечно..." }, { 3.74, "Первое, что тебе следует усвоить, – это очень простой урок: не ищи неприятностей. Поверь, они найдут тебя сами." }, { 11.05, "А если ты сбережёшь несколько монет, то сможешь купить мне кружку эля... или какое-нибудь заклинание для себя." }, { 18.63, "Да, ещё совет: держись подальше от Гномрегана. Пока, думаю, с тебя хватит. Доброго тебе пути!" }, { 24.89, "Захочешь подучиться – приходи в любое время." } } } } },
    [3115] = { d = 20.8, v = "dwarf-male", n = { x = 238 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту записку. Прочти её, когда будет время." }, { 7.30, "Думаю, записку прислал Аламар, наставник чернокнижников. Если представится случай, отыщи его в Старой Наковальне." }, { 15.34, "Да, вот ещё что... будь осторожнее. Таким, как ты, тут не слишком-то доверяют." } } }, t = { d = 29.1, g = 1, v = "gnome-male", n = { m = 307, f = 310 }, c = { m = { { 0.00, "Но всё это не имеет значения. Важно лишь одно — ты узрел свой собственный Святой Свет. Ты понял, откуда приходит истинная сила." }, { 8.57, "Ты осознал, что иметь собственных союзников куда... разумнее. Особенных союзников." }, { 13.97, "Таких, что будут повиноваться до последнего вздоха." }, { 17.85, "И вот тут вступаю я. Я могу обучить тебя основам этих особых сил. Приходи ко мне почаще — и я научу тебя новым заклинаниям." } }, f = { { 0.00, "Но всё это не имеет значения. Важно лишь одно — ты узрела свой собственный Святой Свет. Ты поняла, откуда приходит истинная сила." }, { 8.66, "Ты осознала, что иметь собственных союзников куда... разумнее. Особенных союзников." }, { 14.18, "Таких, что будут повиноваться до последнего вздоха." }, { 18.07, "И вот тут вступаю я. Я могу обучить тебя основам этих особых сил. Приходи ко мне почаще — и я научу тебя новым заклинаниям." } } } } },
    [3116] = { d = 12.4, v = "nightelf-male#54", n = { x = 144 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашей наставницы воинов, Алайссии." }, { 4.96, "Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Алайссии." } } }, t = { d = 36.6, v = "nightelf-female#52", n = { x = 435 }, c = { x = { { 0.00, "Вскоре ты увидишь на ветвях нашего дома представителей других рас – но не поддавайся предубеждению. Они здесь приняты как гости." }, { 8.49, "Они помогут нам, когда смогут помочь. Не все они действуют из альтруизма, однако всем им можно в некоторой степени доверять." }, { 17.12, "Но всё это сейчас не в счёт. Мы должны подумать о тебе и о том, как ты сможешь помочь нашему народу." }, { 23.74, "Я здесь именно ради этого. Я буду учить тебя действовать как воин по мере того, как ты будешь обретать силу." }, { 31.00, "Возвращайся ко мне, когда пожелаешь, – и я сделаю всё возможное, чтобы помочь тебе." } } } } },
    [3117] = { d = 12.6, v = "nightelf-male#54", n = { x = 141 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашей наставницы охотников, Аянны." }, { 5.43, "Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Аянне." } } }, t = { d = 24.8, v = "nightelf-female#51", n = { x = 291 }, c = { x = { { 0.00, "Когда обретёшь достаточно опыта в Тенистой долине, приходи ко мне – я помогу тебе постичь умения охотника и осознать твои собственные возможности." }, { 10.31, "Это опасные времена, и даже умения твоих питомцев нельзя принимать как должное – в мире существуют вещи куда более опасные, нежели ты можешь вообразить." }, { 20.66, "Да хранит тебя Элуна, я буду ждать твоего возвращения." } } } } },
    [3118] = { d = 12.5, v = "nightelf-male#54", n = { x = 146 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашего наставника разбойников, Фрагуна." }, { 5.34, "Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Фрагуну." } } }, t = { d = 32.2, v = "nightelf-male#55", n = { x = 384 }, c = { x = { { 0.00, "Но до тех пор знай, что в эти трудные времена услуги разбойников востребованы гораздо больше, чем обычно." }, { 7.11, "Мирные отношения с другими расами могут рухнуть в любой момент, к тому же ходят слухи о представителях Орды, ищущих, как бы посеять семена ещё большего недоверия. Помни об этом." }, { 19.27, "По мере того как будешь становиться более опытной и обретать силы, приходи сюда, и я позабочусь о твоём обучении." }, { 26.91, "Тебе важно знать, помимо всего прочего, как обращаться с выбранным оружием." } } } } },
    [3119] = { d = 11.9, v = "nightelf-male#54", n = { x = 138 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашей наставницы жрецов, Шанды." }, { 4.88, "Похоже, она хотела бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Шанде." } } }, t = { d = 21.6, v = "nightelf-female#51", n = { x = 251 }, c = { x = { { 0.00, "Пока что не беспокойся о мире за пределами Тельдрассила – ещё успеешь." }, { 4.78, "Иди теперь и поговори с остальными, живущими в Тенистой долине, – они расскажут тебе о том, что тут происходит." }, { 12.07, "Помогай им в том, в чём сможешь, и в любой момент, когда тебе нужно будет обучение, возвращайся сюда, и я научу тебя всему, что знаю сама." } } } } },
    [3120] = { d = 12.2, v = "nightelf-male#54", n = { x = 144 }, c = { x = { { 0.00, "Этот знак был передан мне посланником нашего наставника друидов, Марданта." }, { 4.95, "Похоже, он хотел бы поговорить с тобой, когда у тебя будет время. Изучи знак и отправляйся к Марданту." } } }, t = { d = 23.9, v = "nightelf-male#54", n = { x = 275 }, c = { x = { { 0.00, "Отныне я буду твоим наставником. Мой долг не только научить тебя истолковывать то, что вещают нам духи, но и дать тебе представление о сложностях и тайнах Изумрудного Сна." }, { 12.15, "По мере обучения ты узнаешь больше о нашем сонном трансе." }, { 16.00, "Но пока что приходи ко мне так часто, как сочтёшь нужным, и я обучу тебя всему, следуя традициям ночных эльфов." } } } } },
    [3221] = { d = 15.2, v = "scourge-male", n = { x = 158 }, c = { x = { { 0.00, "Пока вы отсутствовали, помогая нашим стражам смерти, за вами приходил аптекарь Ренферрел." }, { 7.30, "Он не рассказывал мне подробностей, но хотел поговорить с вами о волчьих сердцах, что вы ему передали." } } }, t = { d = 11.7, v = "scourge-male#82", n = { x = 102 }, c = { x = { { 0.00, "О, хорошо, что вы пришли. Касательно тех волчьих сердец, что вы мне ранее принесли – есть один момент, требующий вашего внимания." } } } } },
    [3261] = { d = 11.9, v = "orc-female", n = { x = 138 }, c = { x = { { 0.00, "Вот и закончились наши уроки. Не останавливайся на достигнутом, ступай в Лагерь Таурахо на юге и поговори с Джорном Заклинателем Небес. Он станет твоим новым учителем." } } }, t = { d = 8.6, g = 1, v = "tauren-male#67", n = { m = 63, f = 66 }, c = { m = { { 0.00, "Приветствую тебя, юноша. Ты избрал путь охотника? Замечательно. Начнём с азов." } }, f = { { 0.00, "Приветствую тебя, девушка. Ты избрала путь охотника? Замечательно. Начнём с азов." } } } } },
    [3281] = { d = 21.3, g = 1, v = "orc-male", n = { m = 229, f = 230 }, c = { m = { { 0.00, "Ящеров-то ты убил, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров." }, { 9.82, "Скорее всего они утащили похищенное серебро именно туда." }, { 14.23, "Отправляйся логово мерзких тварей и поищи наше серебро. Как найдёшь – сразу возвращайся ко мне." } }, f = { { 0.00, "Ящеров-то ты убила, но похищенное серебро необходимо вернуть! Говорят, что ящеры гнездятся на юге от Кабестана, в Землях ящеров." }, { 8.90, "Скорее всего они утащили похищенное серебро именно туда." }, { 13.31, "Отправляйся логово мерзких тварей и поищи наше серебро. Как найдёшь – сразу возвращайся ко мне." } } }, t = { d = 19.9, v = "orc-male", n = { x = 209 }, c = { x = { { 0.00, "Ага! Значит, ящеры всё же утащили его в своё логово. Трудно понять, зачем этим тварям серебро." }, { 7.24, "Быть может, в байках об их уме есть зерно правды!" }, { 11.25, "Спасибо. Прими награду за услуги и помни, что стражи перекрёстков получили свою месячную оплату лишь благодаря тебе." } } } } },
    [3301] = { d = 39.1, v = "tauren-male", n = { x = 382 }, c = { x = { { 0.00, "Одна из моих соплеменниц, Муура Рунический Тотэм, отправилась в Серебряный бор на помощь нашим союзникам-нежити." }, { 8.83, "Серебряный бор – больной, вымирающий лес, и Муура надеялась вдохнуть в него новую жизнь." }, { 16.39, "Может быть, необычные обитатели Степей подскажут ей, как лучше выполнить задачу." }, { 22.98, "Возьми образец добытых тобой панцирей и отнеси его Мууре в Серебряный бор. Она остановилась в Гробнице." }, { 32.78, "При удаче, осмотрев панцирь, она придумает, как исцелить это погибающее место." } } }, t = { d = 18.8, v = "tauren-female", n = { x = 183 }, c = { x = { { 0.00, "Что это? Панцирь светится изнутри, словно в нём по-прежнему теплится жизнь. Удивительно! Надо изучить его внимательнее." }, { 10.21, "Спасибо. Быть может, в этом панцире сокрыта тайна исцеления бедной израненной земли Серебряного бора." } } } } },
    [3361] = { d = 46.3, v = "gnome-male", n = { x = 483 }, c = { x = { { 0.00, "Мы изгнали троггов из Гномрегана и уж было собрались праздновать победу, но тут всё пошло наперекосяк!" }, { 7.03, "Только представь: радиация кругом, а гномы – те, кто ещё жив – разбрелись по Дун Морогу..." }, { 14.85, "Я так торопился, что все свои вещи бросил, да и все инструменты в придачу." }, { 19.92, "Вот тролли – те не растерялись: им что радиация, что грибной дождик..." }, { 25.82, "Прибрали всё к рукам: и сундук, и ларец, и даже ведро с винтиками не постеснялись прихватить!" }, { 32.09, "Всё, всё уволокли к себе в лагерь, куда-то к юго-западу от Старой Наковальни..." }, { 37.68, "Путешественник из меня никудышный, так я вот тут подумал: может, ты у них заберёшь мои вещи и вернёшь их мне?" } } }, t = { d = 11.8, v = "gnome-male", n = { x = 121 }, c = { x = { { 0.00, "Ага! Есть! Есть! Тебе удалось найти мои вещи! Я спасён!.." }, { 4.58, "Вот, держи: это, конечно, сущие пустяки, но должен же я тебя хоть чем-то вознаградить за все испытания." } } } } },
    [3364] = { d = 41.7, v = "dwarf-male", n = { x = 466 }, c = { x = { { 0.00, "Я уже давно должен был доставить эту отличнейшую жгучую бражку в Старую Наковальню Дарнану Мехорезу, да только сначала мне нужно было завезти немного Грелину." }, { 10.66, "Боюсь, к тому времени, как я доберусь до Старой Наковальни, остынет бражка-то!" }, { 16.22, "Ты на ногу полегче моего будешь, как я погляжу; вот я и подумал..." }, { 20.57, "эта кружка останется горячей ещё минут пять, а Дарнан вовсе не охлаждённую бражку заказывал, – не пиво, чай!" }, { 27.91, "– так что отправляйся-ка ты в путь. Старая Наковальня – это такое поселение в скалах к северо-востоку отсюда." }, { 36.95, "Благодарю заранее... и вот ещё что: не забудь вернуть мою кружку!" } } }, t = { d = 8.1, v = "dwarf-male#100", n = { x = 87 }, c = { x = { { 0.00, "Отлично! Это именно то, что нужно! Ты погоди пока, эту штуку пить надо, пока не остыла, иначе вкуса того не будет." } } } } },
    [3365] = { d = 15.5, v = "dwarf-male#100", n = { x = 174 }, c = { x = { { 0.00, "Ох, хорошо-то как! Все эти прохладительные напитки – полная ерунда: в морозный денёк нет ничего лучше глотка горячей бражки! Даже на душе теплее становится!" }, { 10.92, "Вот, держи; сделай доброе дело, отнеси эту кружку Нори, ладно?" } } }, t = { d = 20.9, v = "dwarf-male", n = { x = 225 }, c = { x = { { 0.00, "Спасибо! Ты удивишься, если я расскажу тебе, сколько народу забывает сделать самое простое – вернуть назад кружку." }, { 7.81, "А кружки-то, между прочим, на деревьях не растут! Ну, по крайней мере, в наших краях." }, { 14.01, "Тут у меня есть кое-что для тебя. Я так думаю, усердие нужно вознаграждать, верно ведь?" } } } } },
    [3366] = { d = 24.7, v = "human-male#114", c = { x = { { 0.00, "Блестящий осколок ярко-зелёный, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма." }, { 8.51, "Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство." }, { 16.92, "Пожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке." } } } },
    [3369] = { d = 28.1, v = "tauren-female#71", n = { x = 280 }, c = { x = { { 0.00, "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара." }, { 10.05, "Не хочу тревожить тебя, но лучше будет, отдать его кому-то из старших друидов, как только сможешь." }, { 18.01, "Хамуул Рунический Тотэм с Вершины Старейшин, вот кого тебе надо найти. Отправляйся на Громовой Утёс, точнее сказать не могу." } } }, t = { d = 26.8, v = "tauren-male", n = { x = 253 }, c = { x = { { 0.00, "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… Хамуул вглядывается в осколок. Ох... Боги…" }, { 7.63, "Спасибо, что принёс это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться." }, { 18.67, "Запомни, в Изумрудном сне всё не то, чем кажется..." }, { 23.31, "Возможно в будущем мы встретимся вновь." } } } } },
    [3370] = { d = 27.5, v = "tauren-female#71", n = { x = 271 }, c = { x = { { 0.00, "Этот осколок сам по себе большая загадка; Это чистая эссенция Изумрудного Сна. Однако, это осколок не сна, а скорее кошмара." }, { 10.21, "Не хочу тревожить тебя, но лучше будет, отдать его кому-то из старших друидов, как только сможешь." }, { 18.23, "Матренгил Медвежья Лапа из Круга Кенария, вот кого тебе надо найти. Отправляйся в Дарнасс, точнее сказать не могу." } } }, t = { d = 23.3, v = "nightelf-male#59", n = { x = 256 }, c = { x = { { 0.00, "Тебя послала Фалла? Давай-ка, взглянем на этот осколок… Матренгил вглядывается в осколок. Ох... Боги…" }, { 7.09, "Спасибо, что принёс это мне. О таких вещах вслух не говорят, но я всё же предупрежу тебя, есть вещи, с которыми ты можешь не справиться." }, { 16.57, "Запомни, в Изумрудном сне всё не то, чем кажется..." }, { 20.23, "Возможно в будущем мы встретимся вновь." } } } } },
    [3376] = { d = 37.4, g = 1, v = "tauren-female", n = { m = 337, f = 339 }, c = { m = { { 0.00, "путник – я слыхала о тебе. Возможно, именно тебе удастся то, что не удалось другим." }, { 7.00, "Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой." }, { 13.85, "Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами." }, { 25.66, "Я хочу, чтобы ты принёс мне голову их вождя!" }, { 29.64, "Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда." } }, f = { { 0.00, "путница – я слыхала о тебе. Возможно, именно тебе удастся то, что не удалось другим." }, { 7.80, "Мы, таурены, сделали это место своим домом, но это далось нам дорогой ценой." }, { 14.66, "Дыбогривые свинобразы из клана Вздыбленной Щетины под предводительством вождя Остроклыка Терновой Мантии не дают нам покоя своими набегами." }, { 26.47, "Я хочу, чтобы ты принесла мне голову их вождя!" }, { 30.69, "Ты найдёшь его в одной из кустарных хижин в Ежевичной лощине к востоку отсюда." } } }, t = { d = 14.7, g = 1, v = "tauren-female", n = { m = 133, f = 134 }, c = { m = { { 0.00, "Само правосудие сегодня направляло твою руку. Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому!" }, { 11.13, "Ты заслужил эту награду, юный герой." } }, f = { { 0.00, "Само правосудие сегодня направляло твою руку. Да будет твоё деяние предостережением для всех, кто осмелится угрожать нашему дому!" }, { 11.13, "Ты заслужила эту награду, юная героиня." } } } } },
    [3513] = { d = 19.6, v = "human-male#114", n = { x = 196 }, c = { x = { { 0.00, "Свиток официального вида перевязан серебристой лентой. Несомненно, кому-то он был бы весьма интересен, но кому?" }, { 9.04, "На севере, рядом с границей Ясеневого леса, есть застава, и если в свитке идёт речь о ночных эльфах, именно туда его и надо отнести." } } }, t = { d = 2.3, g = 1, v = "orc-male", n = { m = 18, f = 18 }, c = { m = { { 0.00, "Та-ак... И где ты это нашёл?" } }, f = { { 0.00, "Та-ак... И где ты это нашла?" } } } } },
    [3514] = { d = 33.5, v = "orc-male", n = { x = 360 }, c = { x = { { 0.00, "Это послание от коварной дриады Ринтариэль, Хранительницы Ключей Пещеры Когтей на Пике Каменного Когтя." }, { 8.37, "Она уже не встретится с гонцом, у которого ты нашёл этот свиток, хе-хе, но так просто им это не пройдёт." }, { 15.64, "Орда не потерпит такого нахальства." }, { 18.73, "Ступай в Пещеру Когтей. Убей Ринтариэль и покажи это всем." }, { 22.91, "Возьми с собой флаг Орды и установи его в Пещере Когтей у всех на виду." }, { 28.01, "В другой раз они трижды подумают, прежде чем снова соваться в наши земли." } } }, t = { d = 19.2, g = 1, v = "orc-male", n = { m = 200, f = 201 }, c = { m = { { 0.00, "Да ты силён! Это большое дело – лишить Логово Когтя Ринтариэль." }, { 4.96, "Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса." }, { 13.35, "Они подумают дважды, чем прежде чем снова соваться к нам. Спасибо." } }, f = { { 0.00, "Да ты сильна! Это большое дело – лишить Логово Когтя Ринтариэль." }, { 5.76, "Наши противники не сразу оправятся от потери, и в ближайшее время в Степи будет проникать меньше лазутчиков Альянса." }, { 14.14, "Они подумают дважды, чем прежде чем снова соваться к нам. Спасибо." } } } } },
    [3519] = { d = 18.1, v = "nightelf-male#59", n = { x = 192 }, c = { x = { { 0.00, "Ох... меня сильно покусала паучиха по имени Гитьис Зловещая, когда я обследовал паучиную пещеру. Похоже, я серьёзно отравлен. Помоги мне!" }, { 9.61, "Пожалуйста, дай знать Дирании Серебряному Сиянию. Она сможет помочь мне. Спеши... Как голова кружится…" } } }, t = { d = 7.7, v = "nightelf-female#52", n = { x = 80 }, c = { x = { { 0.00, "Ох, какая беда, а я-то думала, что это сегодня Иверрона не видно... Предупреждала же я его насчёт пауков!" } } } } },
    [3521] = { d = 30.6, v = "nightelf-female#52", n = { x = 344 }, c = { x = { { 0.00, "Мы могли бы помочь Иверрону: я знаю противоядие, которое нейтрализует действие яда. Но для него мне нужны некоторые ингредиенты." }, { 8.98, "Мне понадобятся гиацинтовые грибы. Их можно найти под деревьями или добыть у греллей к югу отсюда – похоже, они им по вкусу." }, { 17.24, "Ещё мне нужны лунные лилии, что растут только вокруг прудов." }, { 21.56, "Последний ингредиент добыть сложнее всего. Это лимфа тех самых чащобных тенётников, что отравили Иверрона." } } }, t = { d = 7.5, g = 1, v = "nightelf-female#52", n = { m = 83, f = 84 }, c = { m = { { 0.00, "Хвала Элуне – ты так быстро собрал все ингредиенты!" }, { 3.76, "Подожди минутку, сейчас я приготовлю противоядие." } }, f = { { 0.00, "Хвала Элуне – ты так быстро собрала все ингредиенты!" }, { 3.87, "Подожди минутку, сейчас я приготовлю противоядие." } } } } },
    [3522] = { d = 16.7, v = "nightelf-female#52", n = { x = 202 }, c = { x = { { 0.00, "Противоядие готово. Пожалуйста, проследи, чтобы Иверрон его выпил." }, { 4.66, "И запомни – это важно: противоядие будет обладать своими целебными свойствами в течение пяти минут." }, { 11.11, "Необходимо доставить его до истечения этого времени. Поторопись, во имя Элуны!" } } }, t = { d = 24.4, g = 1, v = "nightelf-male#59", n = { m = 267, f = 268 }, c = { m = { { 0.00, "Что это? Я знал, что Дирания поможет мне! *Иверрон выпивает противоядие.*" }, { 5.26, "Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает." }, { 11.44, "Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя." }, { 17.61, "Что ж, надеюсь, ты расчистил мне дорогу через этот лес, полный мерзостных чащобных тенётников..." } }, f = { { 0.00, "Что это? Я знал, что Дирания поможет мне! *Иверрон выпивает противоядие.*" }, { 5.26, "Я всё время попадаю в переделки, а Дирания постоянно меня из них вытаскивает." }, { 11.44, "Мне стало намного лучше, хотя, пожалуй, я немного посижу тут, пока совсем не приду в себя." }, { 17.61, "Что ж, надеюсь, ты расчистила мне дорогу через этот лес, полный мерзостных чащобных тенётников..." } } } } },
    [3524] = { d = 33.6, v = "nightelf-female#51", n = { x = 391 }, c = { x = { { 0.00, "Громадные морские твари выбрасываются на пески Тёмного Берега и лежат там, пока не умирают." }, { 6.33, "В последнее время останки этих тварей выносит на берег всё чаще и чаще." }, { 11.28, "Меня послали сюда из Храма Луны для расследования ситуации, но наличие мурлоков у береговой линии затрудняет мою задачу." }, { 20.08, "Одни такие останки лежат на юге от Аубердина, совсем рядом, но вокруг очень много злобных мурлоков из клана Серой Мглы." }, { 28.30, "Не могли бы вы сходить туда и принести мне для изучения кости этой твари?" } } }, t = { d = 29.6, v = "nightelf-female#51", n = { x = 351 }, c = { x = { { 0.00, "Я надеюсь, что мурлоки не слишком досаждали вам, пока вы собирали для нас эти кости!" }, { 5.74, "Я непременно следующим же гиппогрифом доставлю их в Дарнасс." }, { 9.92, "Храм Луны снабдил меня некоторыми средствами, которыми я могла бы расплачиваться за помощь; пожалуйста, примите немного денег вместе с нашей благодарностью." }, { 20.94, "Ваш успех побуждает меня предложить вам возможность и дальше оказывать помощь Храму Луны, если вы заинтересованы в этом..." } } } } },
    [3681] = { d = 23.1, g = 1, v = "dwarf-male", n = { x = 258 }, c = { m = { { 0.00, "Я вынужден прервать твоё путешествие, герой." }, { 3.15, "Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения." }, { 9.86, "Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов." }, { 17.69, "Найди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света." } }, f = { { 0.00, "Я вынужден прервать твоё путешествие, героиня." }, { 3.21, "Из Штормграда пришла весть о том, что всех паладинов призывают туда для продолжения обучения." }, { 9.93, "Если бы меня спросили, я бы сказал, что для тебя наступает особое время – время изучения священных Фолиантов." }, { 17.76, "Найди Даториана Ралла в Штормграде. Он обучает паладинов в Соборе Света." } } }, t = { d = 3.2, g = 1, v = "human-male", n = { x = 26 }, c = { m = { { 0.00, "Добро пожаловать в Собор Света, герой." } }, f = { { 0.00, "Добро пожаловать в Собор Света, героиня." } } } } },
    [3741] = { d = 23.5, v = "child-male", n = { x = 270 }, c = { x = { { 0.00, "Моя подруга Хилари потеряла ожелелье, и мы никак не можем отыскать его." }, { 4.23, "Мы весь день сидели на одном и том же месте, удили рыбу, и уже всё кругом обыскали. Наверное, оно упало в воду." }, { 10.86, "Родители не разрешают нам плавать в озере... Мама говорит, что под водой водятся чудовища, но вы ведь их не боитесь, правда? Пожалуйста, достаньте нам ожерелье." } } }, t = { d = 8.1, g = 1, v = "child-female", n = { m = 90, f = 89 }, c = { m = { { 0.00, "Спасибо, что достали мне ожерелье, господин герой... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?" } }, f = { { 0.00, "Спасибо, что достали мне ожерелье, госпожа героиня... Вы очень добры! Моя кошечка тоже хочет сказать \"спасибо\" – верно, Эфси?" } } } } },
    [3765] = { d = 27.7, g = 1, v = "nightelf-male#55", n = { x = 306 }, c = { m = { { 0.00, "Штормград – невероятно суматошный город." }, { 3.03, "Я прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам." }, { 10.83, "Мой брат Гершала на Тёмном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине." }, { 17.71, "Это путешествие будет долгим и насыщенным." }, { 20.72, "Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, герой." } }, f = { { 0.00, "Штормград – невероятно суматошный город." }, { 3.03, "Я прибыл сюда издалека в поисках помощи. Говорят, отважные искатели приключений нередко бродят по этим улицам." }, { 10.83, "Мой брат Гершала на Тёмном Берегу нуждается в помощи. Он обитает в приморском городке Аубердине." }, { 17.71, "Это путешествие будет долгим и насыщенным." }, { 20.72, "Именно по этой причине я и ищу помощи кого-то, обладающего опытом – такого, как вы, героиня." } } }, t = { d = 7.9, v = "nightelf-male#54", n = { x = 86 }, c = { x = { { 0.00, "О, вас прислал мой брат Аргос? Должно быть, вы устали от долгого пути. Но нам очень о многом нужно поговорить." } } } } },
    [3901] = { d = 38.8, g = 1, v = "scourge-male#82", n = { m = 329, f = 331 }, c = { m = { { 0.00, "Ты уже продемонстрировал свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением." }, { 12.44, "Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивался до этого." }, { 24.49, "Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся. Не мешкай! Когда всё будет сделано – возвращайся ко мне." } }, f = { { 0.00, "Ты уже продемонстрировала свой потенциал в обычных обстоятельствах, а теперь давай посмотрим, как ты будешь действовать под давлением." }, { 12.36, "Скелеты-костетрясы – ещё одни безмозглые приспешники Короля-лича – более серьёзные враги, чем зомби, с которыми ты сталкивалась до этого." }, { 26.97, "Я попрошу тебя уменьшить их количество и проявить себя среди Отрёкшихся. Не мешкай! Когда всё будет сделано – возвращайся ко мне." } } }, t = { d = 28.1, g = 1, v = "scourge-male#82", n = { m = 230, f = 233 }, c = { m = { { 0.00, "Отличная работа. Ты показал, что достоин свободы, которая была тебе дана." }, { 6.75, "Многие будут ненавидеть тебя за то, кем ты стал, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся." }, { 20.94, "Вот, возьми это и ступай своей дорогой. Тебя ждут великие дела, герой." } }, f = { { 0.00, "Отличная работа. Ты показала, что достойна свободы, которая была тебе дана." }, { 6.84, "Многие будут ненавидеть тебя за то, кем ты стала, но знай: что бы они ни замышляли против нас, мы свободны, и никто не сможет вновь поработить Отрёкшихся." }, { 21.14, "Вот, возьми это и ступай своей дорогой. Тебя ждут великие дела, героиня." } } } } },
    [3902] = { d = 39.5, v = "scourge-male", n = { x = 401 }, c = { x = { { 0.00, "Эй, ты! Если ищешь, что бы такого сделать полезного, слушай сюда!" }, { 5.21, "Нам нужны свеженькие рекруты, только что из могилы, которых можно направить в Могильник, чтобы они поискали там что-нибудь стоящее из экипировки." }, { 16.86, "Скорее всего, там будут груды ящиков." }, { 19.80, "Мы надеемся, что вскоре поднимутся новые рекруты, а поскольку нам вовсе не надо, чтобы они слонялись тут голыми, надо бы поскорее чем-нибудь поживиться!" }, { 31.25, "А теперь за работу, несчастный ты мешок с костями! Я не собираюсь платить тем, кто еле двигается." } } }, t = { d = 10.3, v = "scourge-male", n = { x = 103 }, c = { x = { { 0.00, "Отличная работа, я так и думал, что ты не совсем бесполезное существо." }, { 5.28, "А это тебе – одна из лучших вещичек среди тех, что мы собрали." } } } } },
    [3903] = { d = 20.1, g = 1, v = "human-male", n = { m = 197, f = 198 }, c = { m = { { 0.00, "Ты показал себя надёжным герой. Да и тяжёлой работы не боишься, не правда ли?" }, { 5.69, "У меня есть подруга, Милли Осворт. У неё какие-то проблемы." }, { 9.89, "Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь." } }, f = { { 0.00, "Ты показала себя надёжной героиня. Да и тяжёлой работы не боишься, не правда ли?" }, { 7.55, "У меня есть подруга, Милли Осворт. У неё какие-то проблемы." }, { 11.75, "Она вместе со своим фургоном находится по другую сторону аббатства, у стойл. Думаю, ей очень пригодится твоя помощь." } } }, t = { d = 17.4, v = "human-female", n = { x = 193 }, c = { x = { { 0.00, "О, заместитель судьи Виллем просил тебя поговорить со мной?" }, { 5.05, "Он отважный человек и всегда готов помочь, но дела не дают ему покинуть Аббатство Североземья, да к тому же, боюсь, нынешняя моя проблема ему не по плечу. Возможно, ты мне поможешь." } } } } },
    [3904] = { d = 29.7, v = "human-female", n = { x = 349 }, c = { x = { { 0.00, "Шайка бандитов, это Братство Справедливости, проникла в Виноградники Североземья во время сбора урожая!" }, { 6.98, "Я сообщила об этом стражникам, и они заверили меня, что разберутся с этим делом, но... я боюсь за виноград!" }, { 14.06, "Если мой урожай не украдут грабители, так наши стражники потопчут!" }, { 18.85, "Прошу тебя, помоги мне! Я собрала большую часть винограда в корзины, но оставила их в виноградниках на юго-востоке." }, { 26.93, "Принеси мне мой виноград, пожалуйста!" } } }, t = { d = 14.0, g = 1, v = "human-female", n = { m = 147, f = 150 }, c = { m = { { 0.00, "Ох, спасибо тебе. Ты спас мой урожай! И, надеюсь, ты показал этим бандитам, что тут им хозяйничать не позволят!" }, { 7.94, "Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!!!" } }, f = { { 0.00, "Ох, спасибо тебе. Ты спасла мой урожай! И, надеюсь, ты показала этим бандитам, что тут им хозяйничать не позволят!" }, { 8.06, "Может, стражи нам тут нынче и не достаёт, но зато у нас есть такие герои, как ты!!!" } } } } },
    [3905] = { d = 20.2, v = "human-female", n = { x = 233 }, c = { x = { { 0.00, "Теперь, когда мой урожай спасён, отнеси это уведомление о поставке винограда брату Нилзу." }, { 6.14, "Он ведает съестными припасами в Североземье, и я уверена, что он обрадуется, узнав, что у него будет свежий виноград." }, { 14.40, "Брата Нилза ты найдёшь в аббатстве, в звоннице – он там любит... дегустировать вино." } } }, t = { d = 20.3, v = "human-male", n = { x = 203 }, c = { x = { { 0.00, "Так, что у нас тут..." }, { 1.80, "Хвала Свету! Виноград Милли спасён!" }, { 4.65, "Когда она сказала мне, что эти бандиты разнесли её виноградники, я чуть не впал в уныние, но моя вера в Свет не дрогнула!" }, { 14.17, "И благодаря твоей отваге теперь у нас есть виноград для вина! Да хранит тебя Свет!" } } } } },
    [3911] = { d = 47.2, v = "scourge-female#80", n = { x = 437 }, c = { x = { { 0.00, "У меня есть работа для тех, кто не боится сунуться в глубины!" }, { 5.70, "Клан Чёрного Железа научился создавать чрезвычайно мощных големов." }, { 11.83, "Исходя из отчётов, присланных нашими шпионами, дворфы используют уникальные источники энергии, чтобы придать своим гоблинам невероятную разрушительную силу." }, { 25.58, "Подумать только, что мы могли бы сделать с нашими поганищами, заполучи мы сущность Стихий, которую они используют..." }, { 36.08, "Можешь перевернуть город вверх дном, но я должна получить эту сущность. Без неё можешь не возвращаться! По усердию и награда." } } }, t = { d = 9.0, v = "scourge-female#80", n = { x = 77 }, c = { x = { { 0.00, "Замечательно! Я немедленно отправлю их курьером в Подгород!" }, { 5.58, "Для вас - оплата, как и было обещано." } } } } },
    [3921] = { d = 30.1, v = "goblin-male", n = { x = 327 }, c = { x = { { 0.00, "Мне кажется, я сломал самофланж. Это плохо, потому что я успел рассказать о нём нескольким коллегам из Нижней шахты, и они очень заинтригованы. Надо починить его!" }, { 11.40, "Отнеси сломанный самофланж Венаки Бенике, который живёт на юге от заставы Мор'шан, лагеря Орды между Степями и Ясеневым лесом." }, { 21.83, "Она очень умная и любопытная. Покажи ей самофланж, и я не сомневаюсь, что она не упустит возможности починить его." } } }, t = { d = 14.2, v = "goblin-female#63", n = { x = 155 }, c = { x = { { 0.00, "Что это? Самофланж, говоришь? Что такое самофланж??" }, { 3.85, "А... Посмотри, как он вибрирует, когда берёшь его в руки. А внутри жужжат сложные шестерёнки. Ух ты!" }, { 10.56, "Мне хочется починить его и узнать, зачем он тебе?" } } } } },
    [3922] = { d = 25.8, v = "goblin-female#63", n = { x = 305 }, c = { x = { { 0.00, "Я готова заняться самофланжем, но для этого мне понадобятся запчасти." }, { 4.73, "У меня кончились семнадцати с половиной миллиметровые заготовки для деталей, а для работы понадобится целая куча." }, { 12.91, "Проще всего их достать у Нефтяного болота на востоке. Торговая Компания обычно хранит их в вёдрах с инструментами." }, { 20.72, "Ступай туда и поищи эти штуковины, а набрав достаточно, возвращайся." } } }, t = { d = 3.8, v = "goblin-female#63", n = { x = 39 }, c = { x = { { 0.00, "О, ты принёс их! Теперь я могу приступить к работе..." } } } } },
    [3923] = { d = 34.6, v = "goblin-female#63", n = { x = 371 }, c = { x = { { 0.00, "Увы, у меня ничего не вышло. Я добавила в самофланж несколько новых индикаторов, чтобы проверить его структурную целостность, и согласно им, структурная целостность на нуле." }, { 12.86, "Я могу добавить пару циферблатов и рычаг-другой, но... Думаю, станет только хуже." }, { 18.64, "Отнеси самофланж Рилли Грязегобу. Он работал на Торговую Компанию, и уж если Рилли не сможет починить эту штуку, то пиши пропало." }, { 29.39, "Он работает в механической мастерской Ногга в Оргриммаре, в Аллее Чести." } } }, t = { d = 11.1, g = 1, v = "goblin-male#65", n = { m = 123, f = 124 }, c = { m = { { 0.00, "Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскал по владениям Торговой Компании в Степях?" }, { 7.41, "Интересно, это говорит о смелости или о глупости?" } }, f = { { 0.00, "Что это? Надо же, самофланж. Откуда он у тебя? Неужели ты рыскала по владениям Торговой Компании в Степях?" }, { 7.32, "Интересно, это говорит о смелости или о глупости?" } } } } },
    [3924] = { d = 25.6, v = "goblin-male#65", n = { x = 306 }, c = { x = { { 0.00, "Думаю, я смогу починить самофланж, но для этого мне понадобится руководство пользователя." }, { 6.04, "В Торговой Компании у меня был соперник, начальник Медноклин." }, { 10.48, "Он ревностно хранил тайны самофланжа и лишь частицы знания доверял самым надёжным своим сторонникам. Я не входил в число избранных..." }, { 19.70, "Начальник Медноклин работает в северо-восточной части Степей, на Каменном карьере." } } }, t = { d = 17.9, v = "goblin-male#65", n = { x = 202 }, c = { x = { { 0.00, "Ты принёс руководство! Мне не терпится узнать, как починить самофланж!" }, { 5.27, "Я говорил с Пароклапаном из Кабестана, и он просил поблагодарить тебя за услуги и вознаградить за них." }, { 12.57, "Я тоже весьма признателен, и если починю-таки эту штуку, сразу тебе сообщу..." } } } } },
    [4021] = { d = 35.6, v = "orc-male#60", n = { x = 383 }, c = { x = { { 0.00, "Орда благодарит тебя за неустанную борьбу с кланом Колкар, но сами кентавры в ярости." }, { 5.86, "Я получил сообщение, что отряд клана Колкар оставил свой дом в Пустошах и прибыл в Степи, движимый местью." }, { 14.44, "Более того, они прямо сейчас подбираются к нам с запада!" }, { 18.71, "Выступи против захватчиков из племени Колкар и положи конец опасности, грозящей Степям." }, { 26.02, "Убивай их, пока не появится их вождь, предводитель Кром'зар. Одолей его и принеси в доказательство кусок его знамени. Не подведи меня." } } }, t = { d = 10.7, g = 1, v = "orc-male#60", n = { m = 104, f = 106 }, c = { m = { { 0.00, "Получилось! Ты победил клан Колкар!" }, { 3.13, "Я непременно сообщу Траллу о твоих подвигах." }, { 6.75, "Можешь гордиться собой, ты – достойный сын Орды." } }, f = { { 0.00, "Получилось! Ты победила клан Колкар!" }, { 3.06, "Я непременно сообщу Траллу о твоих подвигах." }, { 6.67, "Можешь гордиться собой, ты – достойная дочь Орды." } } } } },
    [4161] = { d = 31.4, g = 1, v = "nightelf-male#59", n = { x = 357 }, c = { m = { { 0.00, "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\"." }, { 4.26, "Изучение прошлого – важный шаг на пути героя, так что слушай внимательно всё, что я расскажу тебе." }, { 11.24, "Кальдораи всегда гордились тем, что живут в гармонии с природой." }, { 15.45, "Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей." }, { 21.62, "Это равновесие позволяло нам вершить многое." }, { 25.13, "Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне." } }, f = { { 0.00, "Давным-давно ночные эльфы назывались кальдораями, \"детьми звёзд\"." }, { 4.26, "Изучение прошлого – важный шаг на пути героини, так что слушай внимательно всё, что я расскажу тебе." }, { 11.42, "Кальдораи всегда гордились тем, что живут в гармонии с природой." }, { 15.63, "Это означает, что мы берём у природы только то, что нам необходимо, и воздаём ей сторицей." }, { 21.81, "Это равновесие позволяло нам вершить многое." }, { 25.31, "Ступай же и принеси мне семь маленьких паучьих лапок – не более – и возвращайся ко мне." } } }, t = { d = 9.6, v = "nightelf-male#59", n = { x = 113 }, c = { x = { { 0.00, "Всегда помни то, что я ныне показал тебе." }, { 2.77, "Ты – часть того равновесия, которое ночные эльфы стремятся поддерживать даже в тревожные времена." } } } } },
    [4402] = { d = 28.6, v = "orc-male", n = { x = 291 }, c = { x = { { 0.00, "Ну и жарища у нас в Долине Испытаний! Галгар утирает пот со лба." }, { 4.89, "Были бы у меня плоды кактуса, я бы изготовил свой знаменитый кактусовый десерт!" }, { 10.62, "Ничто не освежает лучше этого восхитительного лакомства." }, { 15.05, "Знаешь что? Принеси-ка мне десяток плодов кактуса, и я приготовлю для тебя несколько порций десерта. Пригодится в путешествиях." }, { 24.05, "Плоды кактуса можно собрать с тех, что растут вокруг." } } }, t = { d = 7.1, v = "orc-male", n = { x = 69 }, c = { x = { { 0.00, "Замечательно! А вот и твой кактусовый десерт, как было обещано. И ещё кое-что в придачу..." } } } } },
    [4495] = { d = 27.4, v = "nightelf-female#52", n = { x = 316 }, c = { x = { { 0.00, "Мой друг по имени Иверрон обычно навещает меня в одно и то же время каждый день." }, { 4.97, "Странно, что сегодня он вообще не пришёл – он задерживается уже на несколько часов." }, { 10.89, "Признаться, я несколько волнуюсь. Иверрон проводит много времени возле пещеры к северу отсюда, и я знаю, насколько там опасно – это ведь логово пауков!" }, { 21.96, "Послушай, если ты вдруг направляешься в ту сторону, то не поищешь ли Иверрона?" } } }, t = { d = 4.6, g = 1, v = "nightelf-male#59", n = { m = 44, f = 45 }, c = { m = { { 0.00, "Я рад, что тебе удалось найти меня. Как ты узнал, что я тут?" } }, f = { { 0.00, "Я рад, что тебе удалось найти меня. Как ты узнала, что я тут?" } } } } },
    [4542] = { d = 30.2, v = "tauren-male", n = { x = 285 }, c = { x = { { 0.00, "Кентавры стали всё чаще нападать на эти земли, и об этом нужно срочно доложить на Заставу Вольного Ветра!" }, { 8.29, "Отправляйтесь туда, найдите дозорного утёсов Долгорога и отдайте ему это письмо. Форт находится к юго-востоку отсюда." }, { 18.85, "Но будьте осторожны: неподалёку есть поселение клана Зловещий Тотэм, и его члены в последнее время ведут себя беспокойно" } } }, t = { d = 17.2, v = "tauren-male#67", n = { x = 133 }, c = { x = { { 0.00, "Опять плохие новости! Эти кентавры зашли слишком далеко! Они напали на один из моих караванов и убили всех погонщиков!" }, { 12.64, "Это неслыханно, они должны за это заплатить!" } } } } },
    [4581] = { d = 22.0, v = "nightelf-female#52", n = { x = 254 }, c = { x = { { 0.00, "Друид Кайнет Штиль прислал мне весточку." }, { 2.67, "Он хотел бы получить отчёт обо всём, что творится у нас на побережье и в лесах вокруг Астранаара." }, { 9.43, "Он опасается, что по Ясеневому лесу расползается порча... Может, он и прав." }, { 14.78, "Вот, отнеси ему мой отчёт. Ты найдёшь его в святилище Лесной Песни, в лесах Ночной Песни к востоку отсюда." } } }, t = { d = 13.3, v = "nightelf-male#54", n = { x = 150 }, c = { x = { { 0.00, "А, отчёт Шиндрелл! Премного благодарен. Шиндрелл – отличный часовой, она отважна и умна." }, { 6.47, "Надо прочесть это донесение и попытаться понять, что за нечисть расползается по Ясеневому лесу." } } } } },
    [4601] = { d = 32.9, v = "human-male#114", n = { x = 313 }, c = { x = { { 0.00, "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\"." }, { 12.56, "Ваши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер пять тысяч двести легко справится с этой проблемой!" }, { 22.67, "Опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." } } }, t = { d = 15.9, v = "human-male#114", n = { x = 156 }, c = { x = { { 0.00, "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь." }, { 11.64, "Металлический корпус аппарата скрипит и вибрирует." } } } } },
    [4602] = { d = 33.4, v = "human-male#114", n = { x = 313 }, c = { x = { { 0.00, "Этот механизм широко применяется гномами для борьбы со всеми видами загрязнений.Небольшая табличка, прикреплённая к устройству, гласит: \"Чистер пять тысяч двести\"." }, { 12.65, "Ваши фамильные драгоценности и просто безделушки покрывает пыль веков? Чистер пять тысяч двести легко справится с этой проблемой!" }, { 22.89, "Опустите в щель приёмника три серебряные монеты и подождите пару минут, пока Чистер пять тысяч двести наводит лоск на ваши украшения." } } }, t = { d = 15.6, v = "human-male#114", n = { x = 156 }, c = { x = { { 0.00, "Вы кладёте покрытый грязью предмет и три серебряные монеты в Чистер пять тысяч двести, и машина начинает работать, с гудением отскребая въевшуюся грязь." }, { 11.46, "Металлический корпус аппарата скрипит и вибрирует." } } } } },
    [4641] = { d = 38.9, g = 1, v = "orc-male", n = { m = 374, f = 375 }, c = { m = { { 0.00, "Ну вот, ты и стал взрослым... достаточно взрослым, чтобы сражаться во имя Орды и во славу вождя. *Калтунк меряет вас взглядом.* Да, ты вполне годишься!" }, { 11.60, "Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного. *Калтунк хохочет.*" }, { 29.53, "Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юный герой. Горнека ты найдёшь в Логове, на западе." } }, f = { { 0.00, "Ну вот, ты и стала взрослой... достаточно взрослой, чтобы сражаться во имя Орды и во славу вождя. *Калтунк меряет вас взглядом.* Да, ты вполне годишься!" }, { 11.60, "Разумеется, тебе уже хочется повстречаться с огромным драконом или каким-нибудь демоном и задушить его голыми руками, но, пожалуй, начать стоит с чего-нибудь... не такого грозного. *Калтунк хохочет.*" }, { 25.32, "Отправляйся к Горнеку, он сумеет подыскать дело, которое будет тебе по плечу, юная героиня. Горнека ты найдёшь в Логове, на западе." } } }, t = { d = 14.4, g = 1, v = "orc-male#60", n = { m = 152, f = 156 }, c = { m = { { 0.00, "Очередной рекрут Калтунка?" }, { 2.31, "Видно, плохи наши дела, если у нас нет никого получше. Ну, ничего." }, { 6.93, "К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравый воитель Орды!" } }, f = { { 0.00, "Очередной рекрут Калтунка?" }, { 2.31, "Видно, плохи наши дела, если у нас нет никого получше. Ну, ничего." }, { 6.93, "К тому времени, как мы решим, что тебе пора покинуть долину, из тебя получится бравая воительница Орды!" } } } } },
    [4681] = { d = 34.1, v = "nightelf-female#51", n = { x = 398 }, c = { x = { { 0.00, "Та тварь на берегу – не единственная на Тёмном Берегу. Вдоль побережья их ещё много, да и в воде тоже." }, { 6.90, "Я хотела бы, чтобы вы исследовали другие известные нам останки." }, { 11.38, "Мне сообщили, что они находятся в воде, непосредственно к западу от Аубердина, возле затонувшего судна." }, { 18.36, "Возвращайтесь ко мне с тем, что вам удастся найти полезного для нас." }, { 23.40, "Кстати, в ваших странствиях вы можете найти и другие подобные останки." }, { 28.21, "Если вы обнаружите что-то, обязательно принесите нам для дальнейших исследований!" } } }, t = { d = 31.8, v = "nightelf-female#51", n = { x = 375 }, c = { x = { { 0.00, "Вы чрезвычайно помогли мне сегодня; теперь у нас есть серьёзные шансы узнать, почему эти твари выбрасываются на отмели Тёмного Берега." }, { 9.29, "Мысль о том, что они бегут сюда из прибрежных вод Тельдрассила, очень беспокоит меня." }, { 15.12, "Если вы наткнётесь на другие останки в ваших странствиях, пожалуйста, дайте мне знать." }, { 20.94, "Наши исследования здесь пока на начальной стадии." }, { 24.63, "От имени Храма Луны примите, пожалуйста, это в качестве благодарности за ваши труды. Благодарю вас!" } } } } },
    [4722] = { d = 22.3, v = "human-male#114", n = { x = 223 }, c = { x = { { 0.00, "Вы наткнулись на останки морской черепахи, некоторое время назад выбросившейся на Тёмный Берег." }, { 7.37, "Плоть её уже объели мурлоки, обосновавшиеся неподалёку от останков." }, { 12.53, "Однако вы можете набрать достаточное количество образцов, которые пригодятся Гвеннид Блай'Леггонд." } } }, t = { d = 15.7, v = "nightelf-female#51", n = { x = 186 }, c = { x = { { 0.00, "Ещё одна находка, которую нам надо изучить. Хорошая работа!" }, { 4.22, "Эти останки будут исследованы должным образом, когда их доставят в Дарнасс." }, { 9.38, "Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." } } } } },
    [4723] = { d = 33.3, v = "human-male#114", n = { x = 346 }, c = { x = { { 0.00, "Останки гигантского крепкозуба – намного больших размеров, чем можно было бы ожидать на Тёмном Берегу, – лежат у побережья Туманного предела." }, { 10.58, "Как это существо очутилось здесь, неизвестно; мурлоки, объедающие тушу, кажутся слишком слабыми и неспособными даже толпой притащить её сюда." }, { 21.85, "В то время как некоторая часть костей уже начисто обглодана, останков ещё достаточно, чтобы набрать образцов для Гвеннид Блай'Леггонд." } } }, t = { d = 15.7, v = "nightelf-female#51", n = { x = 186 }, c = { x = { { 0.00, "Ещё одна находка, которую нам надо изучить. Хорошая работа!" }, { 4.22, "Эти останки будут исследованы должным образом, когда их доставят в Дарнасс." }, { 9.38, "Пожалуйста, примите это скромное вознаграждение за те образцы, которыми вы нас снабжаете." } } } } },
    [4725] = { d = 36.0, v = "human-male#114", n = { x = 357 }, c = { x = { { 0.00, "Ещё одни останки морской черепахи лежат прямо на берегу. К панцирю прикреплена упряжь." }, { 6.76, "Скорее всего, черепаху выгнали на берег неизвестные нам твари; она не выбросилась на берег сама, хотя другие останки и наводят на эту мысль." }, { 17.24, "Теперь останками черепахи завладели мурлоки клана Серой Мглы, питающиеся мертвечиной." }, { 24.22, "Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Может быть, Гвеннид Блай'Леггонд сможет что-то понять?" } } }, t = { d = 28.3, v = "nightelf-female#51", n = { x = 326 }, c = { x = { { 0.00, "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире." }, { 4.28, "Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу." }, { 12.13, "Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега." }, { 20.22, "Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и ещё раз спасибо за вашу помощь." } } } } },
    [4727] = { d = 28.7, v = "human-male#114", n = { x = 269 }, c = { x = { { 0.00, "Скелет морской черепахи лежит на песчаной отмели на севере Тёмного Берега." }, { 5.80, "Мурлоки клана Серой Мглы либо не нашли её тушу, либо по каким-то причинам не рискнули приблизиться к ней." }, { 13.93, "В любом случае, от черепахи осталось достаточно, чтобы взять образцы для Гвеннид Блай'Леггонд, проводящей расследование по поручению Храма Луны." } } }, t = { d = 15.4, v = "nightelf-female#51", n = { x = 181 }, c = { x = { { 0.00, "Интересно, что мурлоков там не было. Мы будем иметь это в виду, когда начнём изучать эти останки!" }, { 6.61, "Благодарю вас за ваши труды; Храм Луны уполномочил меня передать вам эти деньги в качестве компенсации за потраченное время." } } } } },
    [4728] = { d = 29.3, v = "human-male#114", n = { x = 295 }, c = { x = { { 0.00, "Растерзанные останки того, что на вид кажется похожим на гигантское морское млекопитающее, лежат на берегу." }, { 8.37, "Около них валяется тачка и различные инструменты, как будто кто-то раньше уже пытался изучать останки." }, { 16.11, "Хотя мурлоки основательно растащили скелет, останков достаточно, чтобы найти подходящий образец костей для Гвеннид Блай'Леггонд в Аубердине." } } }, t = { d = 24.2, v = "nightelf-female#51", n = { x = 283 }, c = { x = { { 0.00, "О, я уверена, вы обнаружили останки твари, которые уже изучались Лигой Исследователей." }, { 5.98, "Они работают здесь, на Тёмном Берегу, и упоминали, что изучали одну из выбросившихся на берег тварей, пока их не прогнали мурлоки." }, { 14.87, "Похоже, вам удалось добиться успеха там, где и мы, и они потерпели фиаско." }, { 19.84, "Пожалуйста, примите эту скромную плату от имени Храма Луны." } } } } },
    [4730] = { d = 22.4, v = "human-male#114", n = { x = 245 }, c = { x = { { 0.00, "Полуразложившиеся тело твари, похожей на огромное морское млекопитающее, лежит на берегу." }, { 6.95, "Группа мурлоков, более сильных, чем обитающие ближе к Аубердину, обосновалась вокруг погибшего создания." }, { 14.87, "Останков достаточно, чтобы отобрать образцы костей, которые можно отнести Гвеннид Блай'Леггонд." } } }, t = { d = 30.5, v = "nightelf-female#51", n = { x = 357 }, c = { x = { { 0.00, "Кости, которые вы принесли, принадлежат мирным морским млекопитающим, обитающим в водах, окружающих корни Тельдрассила." }, { 8.04, "Им, насколько известно, никогда не было свойственно выбрасываться на берег, как это делают крепкозубы." }, { 14.95, "Хотела бы я знать, почему они так ведут себя. Что ж, может быть, изучение их останков принесёт свои плоды, и мы что-то узнаем." }, { 23.94, "И снова спасибо вам за помощь. Пожалуйста, примите это вознаграждение от имени Храма Луны." } } } } },
    [4731] = { d = 41.0, v = "human-male#114", n = { x = 410 }, c = { x = { { 0.00, "Ещё одни останки морской черепахи лежат у береговой линии. На панцире есть упряжь, которая ещё частично держится." }, { 8.88, "Возможно, несчастная тварь не сама выбросилась на берег (что кажется наиболее вероятным по отношению к другим погибшим тварям), а была пригнана к береговой линии неизвестными существами." }, { 23.05, "Могучие мурлоки клана Серой Мглы сделали остов этой твари своим жилищем." }, { 28.96, "Обследуя упряжь, вы обнаруживаете ящик со странными пометками. Возможно, Гвеннид Блай'Леггонд сумеет что-то разобрать?" } } }, t = { d = 28.3, v = "nightelf-female#51", n = { x = 326 }, c = { x = { { 0.00, "Я слышала о такой сбруе, которую вы нашли на черепашьем панцире." }, { 4.28, "Это, как я понимаю, упряжь нагов – они используют такие как в сражениях, так и для перевозок своих припасов на сушу." }, { 12.13, "Пометки на ящике также сделаны нагами; это объясняет их неожиданное присутствие в северной части Тёмного Берега." }, { 20.22, "Я отошлю этот ящик в Дарнасс вместе с остальными вашими находками. А это – вам, и ещё раз спасибо за вашу помощь." } } } } },
    [4732] = { d = 22.0, v = "human-male#114", n = { x = 236 }, c = { x = { { 0.00, "Вы обнаружили тело морской черепахи, выбросившейся на Тёмный Берег некоторое время назад." }, { 6.82, "Оно почти дочиста объедено мурлоками клана Серой Мглы – теми самыми, что поселились вокруг останков." }, { 14.63, "Однако, похоже, несколько подходящих образцов для Гвиннед Блай'Леггонд вы сможете отобрать." } } }, t = { d = 29.8, v = "nightelf-female#51", n = { x = 350 }, c = { x = { { 0.00, "Так вы нашли и других выбросившихся на берег тварей?" }, { 3.60, "Морские черепахи обычно резвились в водах у подножья Нордрассиля – до его гибели." }, { 9.66, "Однако с рождением Тельдрассила этих созданий становится всё меньше и меньше." }, { 14.89, "Некоторые, как мы уже знаем, оканчивают свою жизнь здесь – непонятно почему." }, { 20.31, "Быть может, ваша помощь поможет нам раскрыть эту тайну." }, { 24.02, "Пожалуйста, примите эти деньги за образцы, предоставленные нам для исследований." } } } } },
    [4733] = { d = 32.8, v = "human-male#114", n = { x = 325 }, c = { x = { { 0.00, "Останки животного, похожего на гигантского крепкозуба, лежат, вынесенные на отмель в скалистой Сумрачной Излучине." }, { 8.79, "Этот крепкозуб в несколько раз больше любого из тех, что обитают в здешних водах." }, { 15.06, "Откуда бы это создание ни приплыло, вряд ли оно родом с Тёмного Берега." }, { 21.48, "Хотя туша животного уже потеряла целостность, останков достаточно, чтобы найти подходящие образцы для Гвеннид Блай'Леггонд." } } }, t = { d = 31.5, v = "nightelf-female#51", n = { x = 362 }, c = { x = { { 0.00, "Габариты этого крепкозуба, о котором вы рассказываете, просто ошеломляют." }, { 5.14, "Даже самые старые крепкозубы в этих водах – и то в несколько раз меньше." }, { 10.03, "В то время как крупные крепкозубы, как известно, обитают близ Тельдрассила, их количество постоянно уменьшается." }, { 17.70, "Интересно, связано ли как-то это с выбрасывающимися на берег тварями?" }, { 22.75, "Мы продолжим анализ костей, которые вы нам принесли, а это вам вознаграждение от имени Храма Луны. Благодарю вас." } } } } },
    [4740] = { d = 36.0, v = "human-male#114", n = { x = 379 }, c = { x = { { 0.00, "Внимание!" }, { 1.28, "Назначена награда за голову мурлока, именуемого \"Глубомрак\"." }, { 5.71, "Эта злобная тварь повинна в смерти как минимум одного часового и подозревается в потоплении как минимум двух грузовых судов в прибрежных водах Тёмного Берега!" }, { 18.46, "Глубомрака в последний раз видели в поселении мурлоков к югу от Аубердина, и, судя по всему, он охраняет хижины своих сородичей." }, { 28.13, "Награда за голову Глубомрака ждёт смельчака у часового Глинды Нал'Шии в Аубердине. Совет Аубердина" } } }, t = { d = 22.3, g = 1, v = "nightelf-female#52", n = { m = 271, f = 272 }, c = { m = { { 0.00, "Что ж, похоже, вы здесь не только затем, чтобы просто узнать!" }, { 3.88, "Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее." }, { 10.26, "Сегодня вы послужили для наших жителей орудием справедливости." }, { 14.30, "И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящего героя народа Аубердина." } }, f = { { 0.00, "Что ж, похоже, вы здесь не только затем, чтобы просто узнать!" }, { 3.88, "Жители Аубердина будут счастливы известию, что сегодня они смогут спать немного спокойнее." }, { 10.26, "Сегодня вы послужили для наших жителей орудием справедливости." }, { 14.30, "И за это я хотела бы предложить вам вот это в качестве награды, подходящей... для настоящей героини народа Аубердина." } } } } },
    [4761] = { d = 33.9, v = "nightelf-male#54", n = { x = 393 }, c = { x = { { 0.00, "При разведке в лагере фурболгов вы обнаружили информацию, которую нужно довести до сведения Тандриса Ветропряда." }, { 7.66, "Он любезно согласился исполнять обязанности старейшины в Аубердине, мудростью своей направляя повседневную жизнь деревни." }, { 17.40, "Прошу вас поделиться с ним вашими находками в деле фурболгов." }, { 22.02, "Я уверен, что у него есть свои идеи по поводу источника наведённой на них порчи." }, { 27.66, "Может быть, вы сможете вместе с ним выработать план восстановления природного равновесия!" } } }, t = { d = 26.2, g = 1, v = "nightelf-male#54", n = { x = 296 }, c = { m = { { 0.00, "Рад нашей встрече, герой. Ваше расследование ситуации с фурболгами как нельзя кстати." }, { 5.56, "Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса." }, { 20.14, "Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена." } }, f = { { 0.00, "Рад нашей встрече, героиня. Ваше расследование ситуации с фурболгами как нельзя кстати." }, { 6.08, "Уже в течение некоторого времени мы имеем дело не только с обитателями здешних лесов, ныне относящихся к нашему присутствию с неприкрытой враждебностью, но и с явной порчей, наведённой на сами леса." }, { 20.64, "Надеюсь, вы сможете протянуть Аубердину руку помощи в эти неспокойные времена." } } } } },
    [4762] = { d = 38.2, v = "nightelf-male#54", n = { x = 425 }, c = { x = { { 0.00, "Воды реки Скалистой исполнились злобы и порчи. Река впадает в Туманный предел, и я боюсь, что скоро беда затронет и Аубердин." }, { 10.40, "Я подозреваю, что в загрязнении повинны фурболги Чернолесья, живущие в верховьях реки, но я также полагаю, что они не являются подлинной причиной этой порчи." }, { 21.62, "Возьмите эту пробирку и отправляйтесь к устью реки, что к северу отсюда." }, { 26.48, "Идите вверх по реке до первого водопада и там возьмите пробу воды. Ориентиром вам послужит высокий мост через реку." }, { 34.45, "Когда возьмёте пробу, вернитесь ко мне в Аубердин." } } }, t = { d = 34.0, v = "nightelf-male#54", n = { x = 399 }, c = { x = { { 0.00, "Я не удивлён тем, насколько сильно отравлена эта вода, но поглядите, какой мерзостной она становится!" }, { 6.96, "Похоже, что нужно действовать как можно скорее, да?" }, { 10.56, "К востоку от нас находится Осквернённый лес; это и есть настоящий источник порчи, я в прошлом такой уже видел." }, { 18.08, "Заранее могу сказать, что ваша проба подтвердит это." }, { 21.73, "Наверное, мы могли бы найти средство для исцеления, но нам понадобится помощь, даже чтобы попытаться это сделать." }, { 29.39, "Когда придёт время, я надеюсь, вы сможете нам её предоставить." } } } } },
    [4763] = { d = 38.5, v = "nightelf-male#54", n = { x = 455 }, c = { x = { { 0.00, "Мы узнали, что источником порчи, наведённой на фурболгов, являются сатиры." }, { 5.10, "Они держат своих жертв в повиновении с помощью талисманов, через которые направляют магию." }, { 11.20, "Если для фурболгов ещё есть шансы на спасение, мы должны выманить сатиров-поработителей и отнять у них талисманы!" }, { 19.41, "Наполни эту чашу из нашего лунного колодца и стащи образцы пищи фурболгов из их северного лагеря." }, { 26.24, "Смешай всё и поставь чашу возле большого костра у реки; любой фурболг, поевший из этой чаши, на некоторое время очистится, что привлечёт внимание сатира... которого нужно убить!" } } }, t = { d = 24.6, g = 1, v = "nightelf-male#54", n = { x = 289 }, c = { m = { { 0.00, "Мы только начали войну за освобождение наших лесов от порабощающих сил Скверны, но сегодняшняя битва выиграна!" }, { 7.64, "путник, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью." }, { 16.10, "То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков." } }, f = { { 0.00, "Мы только начали войну за освобождение наших лесов от порабощающих сил Скверны, но сегодняшняя битва выиграна!" }, { 7.64, "путница, народ Аубердина в огромном и почти неоплатном долгу перед вами. Прошу вас принять это вместе с нашей благодарностью." }, { 16.14, "То, что мы узнали сегодня, может в один прекрасный день навсегда освободить наших друзей-фурболгов от мучительных оков." } } } } },
    [4767] = { d = 51.4, v = "tauren-male", n = { x = 504 }, c = { x = { { 0.00, "Мне велели набрать новых виверн, чтобы выдрессировать их и использовать в качестве ездовых животных." }, { 7.98, "Их поголовье постоянно растёт, и я надеюсь, что когда-нибудь сам смогу стать воздушным всадником." }, { 15.79, "Однако виверны пользуются большим спросом, и нам их постоянно не хватает. Может быть, вы, сможете мне помочь?" }, { 24.79, "Я хочу попросить вас отправиться в Скальное гнездовье и набрать с кладок виверн немного яиц." }, { 32.79, "Отсюда ступайте на северо-запад, держитесь поближе к стене каньона – и увидите дорогу, ведущую наверх." }, { 41.41, "Но будьте очень осторожны: виверны не любят чужаков, а уж за свои кладки они будут готовы разорвать кого угодно." } } }, t = { d = 12.9, g = 1, v = "tauren-male", n = { x = 121 }, c = { m = { { 0.00, "Отлично! Детёныши из этих яиц помогут мне осуществить задуманное!" }, { 5.56, "Возьмите это в знак моей признательности, пусть вам всегда везёт на любой охоте, герой." } }, f = { { 0.00, "Отлично! Детёныши из этих яиц помогут мне осуществить задуманное!" }, { 5.56, "Возьмите это в знак моей признательности, пусть вам всегда везёт на любой охоте, героиня." } } } } },
    [4770] = { d = 41.5, g = 1, v = "tauren-male", n = { x = 392 }, c = { m = { { 0.00, "Пожалуйста, герой, помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица!" }, { 11.95, "Я пришёл сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился." }, { 23.06, "Мне срочно нужно вернуться на заставу Белого Плёса!" }, { 27.10, "Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвёт!" }, { 36.06, "Застава прямо к востоку отсюда... пожалуйста, проводите меня туда!" } }, f = { { 0.00, "Пожалуйста, героиня, помогите мне! Я уже несколько дней прячусь в этом Скальном гнездовье, и за это время не встретил ни одного знакомого лица!" }, { 11.04, "Я пришёл сюда изучать виверн и, похоже, немного переборщил – пришлось спасаться от них бегством, вот тогда-то я и заблудился." }, { 22.14, "Мне срочно нужно вернуться на заставу Белого Плёса!" }, { 26.18, "Мотега не знает, что я потерялся, а когда узнает, что я полез в Скальное гнездовье один, он мне голову оторвёт!" }, { 35.15, "Застава прямо к востоку отсюда... пожалуйста, проводите меня туда!" } } }, t = { d = 30.2, v = "tauren-male", n = { x = 269 }, c = { x = { { 0.00, "Что?! Да если б я знал, что Паока Ходячая Гора полезет в Скальное гнездовье, я бы цепями приковал его к тотэму!" }, { 10.79, "Его отец был против того, чтобы он ехал со мной в Тысячу Игл." }, { 15.66, "Мы собирались изучать различных животных, населяющих эти прекрасные земли." }, { 21.98, "Я очень признателен вам за то, что вы помогли Паоке. Надеюсь, это покроет все ваши затраты." } } } } },
    [4811] = { d = 38.2, v = "nightelf-female#52", n = { x = 472 }, c = { x = { { 0.00, "К востоку отсюда становится всё больше враждебно настроенных лунных совухов." }, { 5.12, "Когда-то их считали милыми и спокойными, почти мистическими созданиями." }, { 9.87, "В то время как кое-кто продолжает почитать их, тревога о безопасности Аубердина вынуждает меня смотреть на вещи более реалистично." }, { 18.95, "Я получила сообщения, что лунных совухов привлекает большой красный кристалл, находящийся в горной гряде на востоке Тёмного Берега." }, { 27.55, "Никто не только не знает, что это за кристалл, но есть ли он на самом деле." }, { 32.33, "Я хочу, чтобы вы установили его местонахождение и доложили мне о том, что обнаружите." } } }, t = { d = 28.5, v = "nightelf-female#52", n = { x = 331 }, c = { x = { { 0.00, "Так значит, кристалл существует? Как интересно... В любом случае, вы хорошо справились с заданием. Отличная работа!" }, { 8.46, "А какова же природа этого кристалла? Это лишь один вопрос в целом море вопросов..." }, { 13.56, "На ум мне приходит и другой: почему лунных совухов тянет к кристаллу? Он безвреден, или же таит в себе зло?" }, { 20.87, "У меня ещё много вопросов, но нам придётся пристально изучить кристалл, чтобы добиться хоть каких-то ответов." } } } } },
    [4812] = { d = 31.2, v = "nightelf-female#52", n = { x = 377 }, c = { x = { { 0.00, "Возьмите этот пустой флакон и наполните его водой из лунного колодца в Аубердине." }, { 5.25, "Её могучая магия должна помочь нам разгадать структуру кристалла." }, { 9.67, "Чтобы это сделать, просто облейте кристалл, а остальное должно произойти само собой." }, { 15.62, "Хотя я не думаю, чтобы вам что-то угрожало, я всё же попрошу вас быть осторожнее." }, { 21.01, "За горами на востоке находится Осквернённый лес, и если этот кристал как-то связан с тем местом (как я подозреваю), он может оказаться очень опасным." } } }, t = { d = 17.0, v = "nightelf-female#52", n = { x = 217 }, c = { x = { { 0.00, "Вы снова добрались до таинственного кристалла." }, { 3.03, "Откупорив флакон с водой лунного колодца, вы аккуратно выливаете его содержимое на верхушку кристалла." }, { 9.76, "Пока вода струится по его граням, вы видете, как непроглядная поверхность кристалла становится прозрачной..." } } } } },
    [4813] = { d = 31.8, v = "human-male#114", n = { x = 336 }, c = { x = { { 0.00, "С помощью воды Лунного колодца выяснилось, что в кристалле заключено несколько мелких фрагментов костей, а также половина челюсти." }, { 9.96, "Кажется, челюсть принадлежала гуманоиду, но точно нельзя сказать, не разбив кристалл, – а это даже для самой мощной магии может оказаться почти непосильной задачей." }, { 22.89, "Задание выполнено, и всё, что вам остаётся, – это вернуться в Аубердин и доложить обо всём часовому Глинде Нал'Шие." } } }, t = { d = 28.3, v = "nightelf-female#52", n = { x = 337 }, c = { x = { { 0.00, "Да, похоже, что, хотя мы и знаем теперь о кристалле больше, в результате возникло множество новых вопросов." }, { 7.32, "Я пойду с добытой вами информацией в совет Аубердина. Может быть, они подскажут, что делать дальше с этим кристаллом." }, { 15.00, "Если вообще есть о чём говорить – пока что угроза слишком далеко на востоке, чтобы принимаеть её всерьёз." }, { 22.34, "Что же касается вас, возьмите это. Считайте это наградой за хорошо проделанную работу." } } } } },
    [4821] = { d = 35.0, v = "tauren-male#68", n = { x = 347 }, c = { x = { { 0.00, "Ходят слухи, что здесь, в Тысяче Игл, появилось яйцо какого-то странного существа." }, { 6.22, "Но те, кто видел его, не смогли подойти достаточно близко и рассмотреть яйцо поподробнее." }, { 13.15, "Его охраняют змеи, да так, словно это яйцо – их собственное!" }, { 18.13, "Я хочу, чтобы вы нашли его и принесли мне для изучения." }, { 22.47, "Говорят, что оно находится в логове змеев, но вообще-то таких гнёзд несколько, они разбросаны вдоль стен каньона к югу и северо-востоку от заставы." } } }, t = { d = 6.9, v = "tauren-male#68", n = { x = 67 }, c = { x = { { 0.00, "Наконец-то я получил это таинственное яйцо... Дайте-ка взглянуть на него... Что... что это?!" } } } } },
    [4841] = { d = 15.8, v = "tauren-male#67", n = { x = 130 }, c = { x = { { 0.00, "Я поручаю вам охоту на этих кентавров." }, { 3.74, "Отомстите им за нас как следует – вырежьте весь их лагерь к северу от Заставы Вольного Ветра. Пусть рука ваша будет тверда!" } } }, t = { d = 3.6, v = "tauren-male#67", n = { x = 30 }, c = { x = { { 0.00, "Примите это в благодарность от меня." } } } } },
    [4865] = { d = 27.1, v = "tauren-male#68", n = { x = 241 }, c = { x = { { 0.00, "Если бы я не видел это собственными глазами, то ни за что бы не поверил! Месть обрушилась на Тысячу Игл! *Хагар утирает лоб.*" }, { 11.78, "Надо действовать быстро! Скорее, иди и поговори с Мотегой Огненной Гривой, он на заставе Белого Плёса, это к северо-западу отсюда, прямо возле дороги. Он подскажет нам, что делать!" } } }, t = { d = 8.9, v = "tauren-male", n = { x = 75 }, c = { x = { { 0.00, "Отмщение! Значит, легенда об Арикаре не врёт! Да, эту проблему следует разрешить немедленно." } } } } },
    [4881] = { d = 18.8, v = "human-male#114", n = { x = 188 }, c = { x = { { 0.00, "Таурен по имени Канати Серое Облако собрался разбить в Тысяче Игл охотничий лагерь." }, { 7.56, "Мы должны убить его и опустошить лагерь, уничтожив всех его сторонников." }, { 13.21, "Собираемся на маленькой заставе к юго-западу от Великого подъёмника." } } }, t = { d = 7.1, v = "tauren-male#67", n = { x = 56 }, c = { x = { { 0.00, "Они хотят меня убить? Пусть приходят, я покажу им, как дерутся таурены!" } } } } },
    [4904] = { d = 25.8, v = "tauren-female#72", n = { x = 256 }, c = { x = { { 0.00, "Арнак хотел жениться на мне, и поэтому похитил меня, когда я отвергла его предложение." }, { 6.68, "Мой брат пытался остановить его, но Арнак оказался сильнее. Он... он убил моего брата и привёл меня сюда. Мой бедный брат..." }, { 16.49, "Не могли бы вы вывести меня с Пика Тёмного Облака? Я хочу назад, к Талье! Она, наверное, с ума сходит от беспокойства." } } }, t = { d = 18.7, v = "tauren-female#71", n = { x = 184 }, c = { x = { { 0.00, "Спасибо. В глубине души я всегда верила, что она найдёт способ вернуться ко мне." }, { 6.36, "Она рассказала мне о вашей храбрости и о том, как вы помогли ей сбежать. Эти вещи принадлежали её брату." }, { 14.64, "Уверена, она бы сама непременно отдала их вам." } } } } },
    [4921] = { d = 31.5, g = 1, v = "orc-male#60", n = { x = 344 }, c = { m = { { 0.00, "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины." }, { 7.99, "Силы были неравны. Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её." }, { 14.85, "Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо мной верх." }, { 20.73, "Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути." }, { 27.71, "Прошу тебя, герой, узнай что-нибудь о моей жене." } }, f = { { 0.00, "Мы бились в маленьком лагере тауренов и разделились в бою – на неё наседали разом три иглогрива Вздыбленной Щетины." }, { 7.99, "Силы были неравны. Я отвлёк на себя очень многих и увидел, что набежали новые враги и одолевают её." }, { 14.85, "Впав в ярость, я бросился на врагов, но они с лёгкостью одержали надо мной верх." }, { 20.73, "Я пришёл в себя и увидел, что таурен-друид ухаживает за мной, – он набрёл на меня на Золотом пути." }, { 27.71, "Прошу тебя, героиня, узнай что-нибудь о моей жене." } } }, t = { d = 2.4, g = 1, v = "orc-male#60", n = { x = 14 }, c = { m = { { 0.00, "Понятно. Спасибо, герой." } }, f = { { 0.00, "Понятно. Спасибо, героиня." } } } } },
    [4966] = { d = 8.1, v = "tauren-male#67", n = { x = 65 }, c = { x = { { 0.00, "Кентавров намного больше, чем я думал. Пожалуйста, помогите мне отбиться от них." } } }, t = { d = 5.8, v = "tauren-male#67", n = { x = 43 }, c = { x = { { 0.00, "Спасибо за помощь. Без тебя я бы ни за что не справился." } } } } },
    [5041] = { d = 24.4, v = "orc-male#60", n = { x = 274 }, c = { x = { { 0.00, "Нападение на караваны лишает нас необходимых припасов." }, { 4.24, "Тебе хватило храбрости выступить против племени Иглогривых, и я вновь попрошу тебя о том же, но на сей раз посматривай, нет ли где украденных у нас припасов?" }, { 15.31, "Может быть, они в лагерях этих тварей, и иглогривы жиреют на чужом добре?" }, { 20.66, "Народ Перекрёстка будет у тебя в неоплатном долгу." } } }, t = { d = 9.7, v = "orc-male#60", n = { x = 107 }, c = { x = { { 0.00, "Ха-ха! Спасибо! Ты нам очень помог. Ты неизменно спасаешь народ Перекрёстка и Орды." }, { 5.82, "Если я могу что-нибудь для тебя сделать, обращайся." } } } } },
    [5052] = { d = 64.4, v = "named/3430", n = { x = 396 }, c = { x = { { 0.00, "Кровь повлияла не только на шипы *фыркает*, но и на другие аспекты земли: среди прочих минералов попадаются кроваво-красные камни." }, { 15.69, "Племя Дыбогривов выкапывает эти осколки и носит с собой как тотэмы *фыркает*, и они дают им силы в бою и помогают творить заклинания. *фыркает* Секреты их магии мне известны." }, { 39.24, "Принеси Кривозубу один кровавый осколок, и ты всё поймёшь. Принеси Кривозубу много осколков, и он благословит тебя." }, { 53.42, "Сильна магия иглогривов, ведь это магия самого Агамаггана! *фыркает*" } } }, t = { d = 56.4, g = 1, v = "named/3430", n = { x = 332 }, c = { m = { { 0.00, "Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, герой." }, { 8.31, "Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана! фыркает" }, { 18.87, "Касание осколка, какое забытое ощущение, герой." }, { 25.00, "Знаешь, каково это – чувствовать себя отрезанным от силы?" }, { 32.26, "Но об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба." }, { 49.63, "Теперь они падут от твоей руки. фыркает" } }, f = { { 0.00, "Да, ты понимаешь. фыркает Мои слова для тебя – не пустой звук, героиня." }, { 10.28, "Быть может, Кривозуб и заключён в клетку, но что клетка для силы Агамаггана! фыркает" }, { 20.84, "Касание осколка, какое забытое ощущение, героиня." }, { 27.43, "Знаешь, каково это – чувствовать себя отрезанным от силы?" }, { 34.69, "Но об этом в другой раз. Я обещал поделиться с тобой сведениями. Я обещал тебе силу Агамаггана. Мой народ отвернулся от Кривозуба." }, { 50.36, "Теперь они падут от твоей руки. фыркает" } } } } },
    [5061] = { d = 26.5, g = 1, v = "nightelf-male#54", n = { m = 303, f = 305 }, c = { m = { { 0.00, "Ты завершил обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 7.51, "Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс." }, { 12.71, "Покажи ему свою подвеску и докажи, что ты готов усвоить его уроки." }, { 17.33, "Он завершит твоё обучение, благодаря которому ты станешь единым с водой." }, { 22.69, "Доброго пути, юный друид. Мы ещё встретимся." } }, f = { { 0.00, "Ты завершила обучение, которое проходят все начинающие друиды прежде, чем они смогут принимать водный облик." }, { 7.52, "Теперь возвращайся к своему наставнику, Матренгилу Медвежьей Лапе в Дарнасс." }, { 12.72, "Покажи ему свою подвеску и докажи, что ты готова усвоить его уроки." }, { 17.38, "Он завершит твоё обучение, благодаря которому ты станешь единой с водой." }, { 22.79, "Доброго пути, дева-друид. Мы ещё встретимся." } } }, t = { d = 18.8, g = 1, v = "nightelf-male#59", n = { m = 214, f = 215 }, c = { m = { { 0.00, "Великолепно. Ты готов принимать водный облик, и я с радостью научу тебя." }, { 5.34, "А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это." }, { 10.69, "Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия." } }, f = { { 0.00, "Великолепно. Ты готова принимать водный облик, и я с радостью научу тебя." }, { 5.48, "А также, в знак признания твоих успехов в двух испытаниях, я даю тебе вот это." }, { 10.83, "Надеюсь, тебе приятно будет присоединить эту вещь к своему снаряжению защитника Природы и хранителя равновесия." } } } } },
    [5062] = { d = 38.3, v = "tauren-male", n = { x = 379 }, c = { x = { { 0.00, "Арикара очень опасна, и мы должны как можно быстрее разделаться с ней." }, { 5.64, "Для того чтобы привлечь это чудовище, тебе нужно будет разжечь священный огонь жизни." }, { 12.78, "Собери немного редкой огненной агавы и отнеси её Магате Зловещий Тотэм. Она живёт в Громовом Утёсе, на Вершине Старейшин." }, { 23.29, "Магата – очень могущественная шаманка, владеющая тайной приготовления зачарованного порошка из огненной агавы." }, { 32.31, "Огненную агаву можно собрать на Кипящем озере, это к востоку отсюда." } } }, t = { d = 17.1, v = "named/4046", n = { x = 117 }, c = { x = { { 0.00, "Прекрасно, вы собрали достаточно огненной агавы." }, { 3.80, "Эта редкая трава растёт лишь в Тысяче Игл, и она поможет мне разбудить священное пламя жизни." }, { 13.13, "Магата начинает зачаровывать огненную агаву." } } } } },
    [5064] = { d = 34.3, v = "tauren-male#67", n = { x = 282 }, c = { x = { { 0.00, "Вы уже помогали нам, поэтому я доверю вам ещё одно важное задание." }, { 6.48, "Клан Зловещий Тотэм явно что-то замышляет: недавно мы видели, как в их поселение приходили какие-то странные путники." }, { 17.76, "Потом нам удалось узнать, что важные записи они хранят в трёх разных сундуках Пика Тёмного Облака." }, { 27.79, "Если вам удастся достать эти документы, я щедро вас вознагражу." } } }, t = { d = 16.6, v = "tauren-male#67", n = { x = 126 }, c = { x = { { 0.00, "Великий тотэм духов! Какие ужасные новости! Я немедленно начну готовиться, кто знает, что нас ждёт..." }, { 10.56, "Вот, как я и обещал, это награда за вашу храбрость и услугу." } } } } },
    [5088] = { d = 33.9, g = 1, v = "named/4046", n = { x = 333 }, c = { m = { { 0.00, "Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл." }, { 6.61, "Сделать это нужно на Пике Тёмного Облака, на отдельной скале, где находится местное кладбище." }, { 14.53, "Я зачаровала порошок так, чтобы он привлёк Арикару." }, { 18.85, "Боюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище." }, { 30.44, "Поспешите, герой, вы можете не успеть!" } }, f = { { 0.00, "Возьмите этот зачарованный порошок и зажгите священный огонь жизни в Тысяче Игл." }, { 6.61, "Сделать это нужно на Пике Тёмного Облака, на отдельной скале, где находится местное кладбище." }, { 14.53, "Я зачаровала порошок так, чтобы он привлёк Арикару." }, { 18.85, "Боюсь, что она охотится за Кэрном Кровавым Копытом – из-за него обычаи тауренов претерпели слишком много изменений, и это могло разозлить чудовище." }, { 30.40, "Поспешите, героиня, вы можете не успеть!" } } }, t = { d = 26.0, v = "tauren-male", n = { x = 231 }, c = { x = { { 0.00, "Ерунда какая-то. Зачем Арикаре охотиться за Кэрном Кровавым Копытом?" }, { 7.04, "Но Магата не может ошибаться, она наша самая могущественная шаманка. Мотега качает головой." }, { 15.32, "В любом случае, вы очень помогли Орде, и деяние ваше не останется незамеченным. Пожалуйста, выберите себе любую награду." } } } } },
    [5147] = { d = 30.9, v = "human-male#114", n = { x = 325 }, c = { x = { { 0.00, "Разыскивается: Арнак Зловещий Тотэм." }, { 3.32, "Арнак приговорён к смертной казни по многочисленным обвинениям в убийствах и похищениях." }, { 10.13, "Достойная награда ждёт того, кто найдёт преступника и приведёт приговор в исполнение." }, { 17.14, "Последний раз Арнака видели на утёсе близ Пика Тёмного Облака." }, { 22.00, "Принесите доказательство его смерти стражу утёса Долгорогу на Заставу Вольного Ветра и получите свою награду." } } }, t = { d = 19.4, v = "tauren-male#67", n = { x = 130 }, c = { x = { { 0.00, "Ха! Что ж, отличные новости! А я уж думал, его никогда не накажут." }, { 8.58, "Держи награду... И большое спасибо. Признаться, меня приводили в ярость сообщения о его бесчинствах!" } } } } },
    [5151] = { d = 26.7, v = "goblin-male", n = { x = 294 }, c = { x = { { 0.00, "На наш караван напали кентавры, и выжить удалось только мне! А самый лучший мой механизм висел на шее могучей пантеры-охранницы!" }, { 9.00, "Даже кентавры дрожали, увидев эту зверюгу!" }, { 12.37, "Вот ключ от её клетки. Они забрали всё, а ключ оставили." }, { 16.36, "Убей пантеру, принеси мне мой гипервместитель, а я хорошо заплачу за него." }, { 22.02, "То, что осталось от нашего каравана, находится к северу отсюда." } } }, t = { d = 7.1, v = "goblin-male", n = { x = 77 }, c = { x = { { 0.00, "Мой гипервместитель! Ну всё, теперь с места не сойду, пока не разберусь, зачем же эта штука нужна..." } } } } },
    [5261] = { d = 16.8, v = "human-male", n = { x = 190 }, c = { x = { { 0.00, "Иган Меховщик ищет охотника на волков." }, { 2.80, "Это добрая новость, поскольку в последнее время в Долине Североземья звери уж чересчур расплодились." }, { 10.05, "Если тебе это интересно, то поговори с Иганом. Он за углом аббатства, если свернуть налево." } } }, t = { d = 6.1, v = "human-male", n = { x = 60 }, c = { x = { { 0.00, "Что? Ищу ли я охотников на волков? Ну да, так и есть. А ты, наверное, ищешь работу?" } } } } },
    [5321] = { d = 36.4, v = "nightelf-male", n = { x = 384 }, c = { x = { { 0.00, "Я шёл к Заставе Мейстры, чтобы встретиться с Лиладрис Лунной Рекой, но решил остановиться здесь и немного вздремнуть." }, { 7.97, "С тех пор как я очнулся от Изумрудного Сна, я всё время такой сонный... Зевает" }, { 14.00, "И я нигде не могу найти свои вещи! Поможешь мне их отыскать?" }, { 18.93, "Я так понимаю, Застава Мейстры находится к югу отсюда, в Ясеневом лесу, у дороги. Я пришёл оттуда..." }, { 26.53, "Да, и вот ещё что: я могу заснуть по дороге, так что если тебе нужно будет меня разбудить, сделай это с помощью моего рога. Он в этом сундуке." } } }, t = { d = 11.6, v = "nightelf-female#51", n = { x = 124 }, c = { x = { { 0.00, "О, я так рада, что Керлониан смог сюда добраться. И я уверена, что найду его спящим где-нибудь поблизости, ведь так?" }, { 8.17, "Спасибо вам за то, что показали ему дорогу." } } } } },
    [5441] = { d = 22.2, g = 1, v = "orc-male", n = { x = 233 }, c = { m = { { 0.00, "Проклятые батраки! Им велено валить лес, но они всё время пытаются отлынивать. Мне нужен кто-то, кто их приструнит." }, { 8.82, "Ты, герой, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум!" }, { 17.58, "Управишься – не забудь вернуть дубинку. Проклятые лентяи..." } }, f = { { 0.00, "Проклятые батраки! Им велено валить лес, но они всё время пытаются отлынивать. Мне нужен кто-то, кто их приструнит." }, { 8.82, "Ты, героиня, мне, пожалуй, годишься. На тебе дубинку – ступай и всыпь этим бездельникам. Хороший тумак заставит их взяться за ум!" }, { 17.89, "Управишься – не забудь вернуть дубинку. Проклятые лентяи..." } } }, t = { d = 6.7, v = "orc-male", n = { x = 71 }, c = { x = { { 0.00, "Отлично, отлично! В следующий раз будут знать, как дрыхнуть на работе! Спасибо за помощь!" } } } } },
    [5481] = { d = 16.5, v = "scourge-male", n = { x = 159 }, c = { x = { { 0.00, "Хозяину надо растения. У нас большие руки, цветы рвать никак. Ты нам помогать, мы тебя не трогать." }, { 7.85, "Нам надо мракоцвет, он растёт тут и у дороги." }, { 12.00, "Ты соберёшь – отнеси хозяину Холланду на кладбище в Брилл." } } }, t = { d = 24.9, v = "named/10665", n = { x = 283 }, c = { x = { { 0.00, "Что это? Мракоцвет?! Зачем он мне сдался?!" }, { 3.10, "Эта тупая гора мяса собирает ромашки и привлекает – сколько, Тёмная Госпожа знает, – к этому делу таких простаков, как ты! Без обид." }, { 12.08, "Ладно, главное, что ты здесь. Я не собираюсь тратить своё время на то, чтобы объяснить этому поганищу элементарные вещи." }, { 20.26, "Так что, может, ты соберёшь для меня этот проклятый погибельник?" } } } } },
    [5482] = { d = 26.1, g = 1, v = "named/10665", n = { m = 301, f = 301 }, c = { m = { { 0.00, "Теперь ты понимаешь, в каком затруднительном положении я нахожусь? Это нечто всё ещё ходит там и собирает не те растения." }, { 8.13, "Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу." }, { 16.30, "Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла." }, { 21.64, "Поторопись – и будь осторожен – в тех местах полно гноллов." } }, f = { { 0.00, "Теперь ты понимаешь, в каком затруднительном положении я нахожусь? Это нечто всё ещё ходит там и собирает не те растения." }, { 8.13, "Я непременно отблагодарю тебя, если ты соберёшь то, что мне нужно. Принеси мне погибельник, и я щедро тебя награжу." }, { 16.30, "Насколько я знаю, его можно найти у братских могил, к северу от кладбища Брилла." }, { 21.64, "Поторопись – и будь осторожна – в тех местах полно гноллов." } } }, t = { d = 14.8, g = 1, v = "named/10665", n = { m = 157, f = 158 }, c = { m = { { 0.00, "А, мой погибельник! Превосходно!" }, { 2.81, "*Младший аптекарь Холланд жадно потирает ладони.*" }, { 6.67, "Он мне очень пригодится. Ты оказал мне, ой, то есть Тёмной Госпоже, большую услугу. Как я и обещал, вот твоя награда." } }, f = { { 0.00, "А, мой погибельник! Превосходно!" }, { 2.81, "*Младший аптекарь Холланд жадно потирает ладони.*" }, { 6.67, "Он мне очень пригодится. Ты оказала мне, ой, то есть Тёмной Госпоже, большую услугу. Как я и обещал, вот твоя награда." } } } } },
    [5541] = { d = 33.7, g = 1, v = "dwarf-male#100", n = { m = 378, f = 380 }, c = { m = { { 0.00, "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню." }, { 4.18, "Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны." }, { 11.14, "Но... Последний ящик с боеприпасами, что я ему послал, пропал по дороге." }, { 15.81, "Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго..." }, { 22.17, "и этот дурак бросил боеприпасы для Громострела!" }, { 26.22, "не мог бы ты найти их и вернуть Громострелу? Он их ждёт, и наверняка у него боеприпасы уже на исходе." } }, f = { { 0.00, "Хегнар Громострел продаёт ружья у дороги в Старую Наковальню." }, { 4.18, "Стрелки и пушкари много упражняются возле его лавки, так что ему всегда нужны снаряды и патроны." }, { 11.14, "Но... Последний ящик с боеприпасами, что я ему послал, пропал по дороге." }, { 15.81, "Мой курьер рассказал мне, что он встал лагерем у Серой берлоги, там на него напали вендиго..." }, { 22.17, "и этот дурак бросил боеприпасы для Громострела!" }, { 26.22, "не могла бы ты найти их и вернуть Громострелу? Он их ждёт, и наверняка у него боеприпасы уже на исходе." } } }, t = { d = 14.1, v = "dwarf-male#99", n = { x = 161 }, c = { x = { { 0.00, "Вот радость-то, ещё боеприпасы! Поставка старины Лослора, наконец, прибыла!" }, { 5.08, "Пусть и поздновато, но, как говаривал мой дедуля, лучше поздно, чем никогда!" }, { 10.49, "Большое тебе спасибо. Покупатели тут заждались!" } } } } },
    [5545] = { d = 27.4, v = "human-female#45", n = { x = 318 }, c = { x = { { 0.00, "У меня большие неприятности. Приближается срок поставки древесины, а я не успеваю её отправить." }, { 6.48, "Самое обидное, что она уже заготовлена – но волки и медведи, расплодившиеся к северу отсюда, не дают моим работникам её забрать" }, { 15.52, "Я уже договорилась с заместителем судьи Рейнером насчёт зверья, но мне нужен кто-нибудь, кто доставит сюда эти дрова." }, { 23.61, "Если ты принесёшь мне восемь вязанок, я всё успею." } } }, t = { d = 12.3, v = "human-female#45", n = { x = 141 }, c = { x = { { 0.00, "Великолепно! Благодаря тебе я сумела выполнить заказ вовремя." }, { 4.36, "Всякий труд должен быть оплачен, так что прошу тебя принять эту плату за беспокойство. Спасибо – и до свидания!" } } } } },
    [5621] = { d = 28.4, g = 1, v = "nightelf-female#51", n = { m = 321, f = 323 }, c = { m = { { 0.00, "Мне нужна твоя помощь. Я должна оставаться здесь, чтобы обучать других, но ты мог бы помочь одной из наших раненых часовых к югу от Доланаара." }, { 9.74, "Её ранили, когда она патрулировала город, и ей нужна наша помощь. Её зовут Шайя." }, { 15.63, "Когда найдёшь её, исцели её раны и укрепи её тело заклятиями. По крайней мере, это защитит её от бед на некоторое время." }, { 23.91, "Когда выполнишь свой долг перед Элуной, возвращайся ко мне." } }, f = { { 0.00, "Мне нужна твоя помощь. Я должна оставаться здесь, чтобы обучать других, но ты могла бы помочь одной из наших раненых часовых к югу от Доланаара." }, { 9.95, "Её ранили, когда она патрулировала город, и ей нужна наша помощь. Её зовут Шайя." }, { 15.84, "Когда найдёшь её, исцели её раны и укрепи её тело заклятиями. По крайней мере, это защитит её от бед на некоторое время." }, { 24.12, "Когда выполнишь свой долг перед Элуной, возвращайся ко мне." } } }, t = { d = 21.8, g = 1, v = "nightelf-female#51", n = { m = 242, f = 244 }, c = { m = { { 0.00, "Ты хорошо послужил Элуне. Я благодарю тебя за это." }, { 3.86, "Пожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты заслужил своё место в наших кругах." }, { 12.53, "Если желаешь, носи его с гордостью, но мы признаём тебя своим в любом обличии." }, { 18.16, "Спасибо, и да благословит тебя великая Элуна." } }, f = { { 0.00, "Ты хорошо послужила Элуне. Я благодарю тебя за это." }, { 3.93, "Пожалуйста, прими это одеяние, как символ моей благодарности. Оно символизирует то, что ты заслужила своё место в наших кругах." }, { 12.57, "Если желаешь, носи его с гордостью, но мы признаём тебя своим в любом обличии." }, { 18.20, "Спасибо, и да благословит тебя великая Элуна." } } } } },
    [5622] = { d = 21.6, g = 1, v = "nightelf-female#51", n = { m = 245, f = 245 }, c = { m = { { 0.00, "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет." }, { 8.68, "Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жреца Элуны." }, { 17.76, "Будь осторожен, и да хранит тебя в пути Элуна!" } }, f = { { 0.00, "Тебе предстоит отправиться в Доланаар, когда завершишь свои дела здесь, в Тенистой долине. Там ты разыщешь Лорну Утренний Свет." }, { 8.68, "Она расскажет тебе больше о пути Элуны, и с её помощью ты получишь своё первое облачение, говорящее о твоём статусе жрицы Элуны." }, { 17.91, "Будь осторожна, и да хранит тебя в пути Элуна!" } } }, t = { d = 9.2, v = "nightelf-female#51", n = { x = 106 }, c = { x = { { 0.00, "Я рада знать, что Шанда послала тебя найти меня. Обучение молодых жрецов, следующих пути Луны приносит мне большое удовольствие." } } } } },
    [5623] = { d = 20.4, g = 1, v = "human-female#45", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Приветствую тебя, юный жрец. Пришло время узнать больше о нашей вере." }, { 4.70, "После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту." }, { 10.61, "Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету." }, { 16.81, "Она готова поделиться с тобой своей мудростью." } }, f = { { 0.00, "Приветствую тебя, юная жрица. Пришло время узнать больше о нашей вере." }, { 4.86, "После того как ты закончишь все дела в Североземье, разыщи в Златоземье жрицу Жозетту." }, { 10.76, "Знания её велики; к тому же она уже слышала о тебе и о твоём стремлении к Истинному Свету." }, { 16.97, "Она готова поделиться с тобой своей мудростью." } } }, t = { d = 7.6, v = "human-female#45", n = { x = 86 }, c = { x = { { 0.00, "Я рада твоему прибытию. У нас есть, что обсудить касательно твоего будущего и твоего пути по дороге Света." } } } } },
    [5624] = { d = 31.3, v = "human-female#45", n = { x = 371 }, c = { x = { { 0.00, "Обычно я подвергаю всех последователей Света небольшому испытанию." }, { 4.59, "Так я выясняю, достойны ли они своего первого облачения – символа того, что церковь их принимает и поддерживает." }, { 12.47, "Но сейчас ситуация немного отличается. Один из жителей Златоземья видел раненого стража на берегу озера к востоку отсюда." }, { 20.80, "Этого стража зовут Робертс. Найди его, исцели его раны, придай ему стойкости и вернись сюда." }, { 27.18, "Если ты справишься, я сочту твоё испытание завершённым." } } }, t = { d = 30.4, g = 1, v = "human-female#45", n = { m = 346, f = 349 }, c = { m = { { 0.00, "Прекрасно. Вылечив стражника ты тем самым помог городу, сделав жизнь в нём безопаснее." }, { 6.01, "Рад видеть что ты уже изучил кое-какие свои способности, и даже умеешь их использовать." }, { 11.93, "Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему..." }, { 19.94, "и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно." } }, f = { { 0.00, "Прекрасно. Вылечив стражника ты тем самым помогла городу, сделав жизнь в нём безопаснее." }, { 6.08, "Рад видеть что ты уже изучила кое-какие свои способности, и даже умеешь их использовать." }, { 12.28, "Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему..." }, { 20.28, "и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно." } } } } },
    [5625] = { d = 30.3, g = 1, v = "dwarf-male", n = { m = 355, f = 355 }, c = { m = { { 0.00, "Как правило, примерно в эту пору послушники вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе." }, { 10.39, "Но, честно говоря, сейчас у меня есть и более важные дела." }, { 14.42, "Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф." }, { 23.12, "Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошёл испытание. Справишься?" } }, f = { { 0.00, "Как правило, примерно в эту пору послушницы вроде тебя проходят испытание, в котором проверяется, достойны ли они носить облачения, говорящие об их статусе." }, { 10.35, "Но, честно говоря, сейчас у меня есть и более важные дела." }, { 14.39, "Горожане Караноса только что сказали мне, что к югу от городских стен они нашли раненого горного пехотинца по имени Дольф." }, { 23.09, "Излечи Дольфа и наложи на него \"Слово Силы: Стойкость\", и я сочту, что ты прошла испытание. Справишься?" } } }, t = { d = 30.7, g = 1, v = "dwarf-male", n = { m = 346, f = 349 }, c = { m = { { 0.00, "Прекрасно. Вылечив стражника ты тем самым помог городу, сделав жизнь в нём безопаснее." }, { 6.60, "Рад видеть что ты уже изучил кое-какие свои способности, и даже умеешь их использовать." }, { 12.59, "Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему..." }, { 20.49, "и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно." } }, f = { { 0.00, "Прекрасно. Вылечив стражника ты тем самым помогла городу, сделав жизнь в нём безопаснее." }, { 6.55, "Рад видеть что ты уже изучила кое-какие свои способности, и даже умеешь их использовать." }, { 12.72, "Если нужна будет тренировка, возвращайся ко мне в любое время. А теперь, возьми это одеяние. Оно несёт нашу эмблему..." }, { 20.62, "и любой, кто взглянет на неё, будет знать о том, что ты принадлежишь к нашему ордену. Ну а не захочешь носить её – твоё дело... Это не обязательно." } } } } },
    [5626] = { d = 27.1, g = 1, v = "dwarf-male", n = { m = 291, f = 291 }, c = { m = { { 0.00, "Эй! путник! У тебя есть свободная минутка?!" }, { 4.04, "Ты давно уже следуешь пути Света, так ведь? Как насчёт того, чтобы сходить к Максану Ковальне в Каранос?" }, { 11.11, "Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойным, он тебе даст твои первые одеяния жреца." }, { 19.33, "Теперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать." } }, f = { { 0.00, "Эй! путница! У тебя есть свободная минутка?!" }, { 3.70, "Ты давно уже следуешь пути Света, так ведь? Как насчёт того, чтобы сходить к Максану Ковальне в Каранос?" }, { 10.78, "Он расскажет тебе побольше о твоей судьбе, а если ты окажешься достойной, он тебе даст твои первые одеяния жрицы." }, { 18.95, "Теперь ступай! Как только закончишь все свои дела здесь, иди в Каранос через туннель – Максан будет тебя ждать." } } }, t = { d = 11.8, g = 1, v = "dwarf-male", n = { m = 105, f = 106 }, c = { m = { { 0.00, "Тебя Брансток послал? Хорошо, хорошо. Ты сделал ещё один шаг навстречу Свету. Но тебе многое ещё надо усилить – силу тела... и силу воли." } }, f = { { 0.00, "Тебя Брансток послал? Хорошо, хорошо. Ты сделала ещё один шаг навстречу Свету. Но тебе многое ещё надо усилить – силу тела... и силу воли." } } } } },
    [5628] = { d = 28.8, g = 1, v = "human-female#45", n = { m = 325, f = 326 }, c = { m = { { 0.00, "Если не ошибаюсь? Рад, что ты уделил мне минутку внимания." }, { 4.03, "Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение!" }, { 9.29, "Если бы мне в молодые годы хватило духу постранствовать по миру..." }, { 14.09, "Тут недавно тебя искала жрица из вашего ордена." }, { 17.34, "Сказала, что тебе спешно надо вернуться в Храм Луны в Дарнасе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоём месте не тянул." } }, f = { { 0.00, "Если не ошибаюсь? Рад, что ты уделила мне минутку внимания." }, { 4.14, "Забраться так далеко от дома, да в такие юные годы, – мне по душе твоё рвение!" }, { 9.40, "Если бы мне в молодые годы хватило духу постранствовать по миру..." }, { 14.20, "Тут недавно тебя искала жрица из вашего ордена." }, { 17.45, "Сказала, что тебе спешно надо вернуться в Храм Луны в Дарнасе и поговорить со жрицей Алатеей – это как-то связано с твоим обучением. Я бы на твоём месте не тянул." } } }, t = { d = 19.7, g = 1, v = "nightelf-female#51", n = { m = 219, f = 221 }, c = { m = { { 0.00, "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.74, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.48, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.98, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.71, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5629] = { d = 25.9, g = 1, v = "nightelf-female#51", n = { m = 273, f = 276 }, c = { m = { { 0.00, "Ещё раз приветствую тебя. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени." }, { 8.53, "Жрица Алатея прислала за тобой. Сдаётся, ты привлёк внимание наших старейшин, и они считают, что ты созрел для более великих дел." }, { 17.38, "Отправляйся в дарнасский Храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна." } }, f = { { 0.00, "Ещё раз приветствую тебя. Я знаю, что ты и так много помогаешь нашему народу, но надо и себе уделить хоть немного времени." }, { 8.53, "Жрица Алатея прислала за тобой. Сдаётся, ты привлекла внимание наших старейшин, и они считают, что ты созрела для более великих дел." }, { 17.62, "Отправляйся в дарнасский Храм Луны и найди там Алатею. Удачи тебе, и да хранит тебя Элуна." } } }, t = { d = 19.2, g = 1, v = "nightelf-female#51", n = { m = 214, f = 216 }, c = { m = { { 0.00, "Хорошо, что ты вернулся. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.45, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.18, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.43, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.16, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5630] = { d = 25.2, g = 1, v = "dwarf-male", n = { m = 294, f = 296 }, c = { m = { { 0.00, "Ну здравствуй, друг. Приятно видеть, что ты так далеко забрался!" }, { 4.47, "Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты слеплен из более крутого теста." }, { 13.19, "Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашёл жрицу Алатею в храме Луны в Дарнассе." }, { 20.42, "Должно быть, это важно так что возвращайся туда как можно скорее." } }, f = { { 0.00, "Ну здравствуй, подруга. Приятно видеть, что ты так далеко забралась!" }, { 4.57, "Без обид, но многие из ваших не слишком хорошо переносят тутошние холода. Славно, что ты слеплена из более крутого теста." }, { 13.14, "Не так давно одна из ваших жриц искала тебя – говорила, чтобы ты нашла жрицу Алатею в храме Луны в Дарнассе." }, { 20.42, "Должно быть, это важно так что возвращайся туда как можно скорее." } } }, t = { d = 19.7, g = 1, v = "nightelf-female#51", n = { m = 219, f = 221 }, c = { m = { { 0.00, "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.74, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.48, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.98, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.71, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5631] = { d = 18.1, g = 1, v = "human-male", n = { m = 197, f = 197 }, c = { m = { { 0.00, "Недавно в наших чертогах побывала одна жрица, и она искала вас, юный герой." }, { 5.36, "Она сказала, что её послали за вами и что вы должны вернуться в Храм Луны в Дарнасе как можно скорее." }, { 12.44, "По прибытии найдите жрицу – она расскажет вам больше. Да пребудет с вами Свет." } }, f = { { 0.00, "Недавно в наших чертогах побывала одна жрица, и она искала вас, юная героиня." }, { 5.32, "Она сказала, что её послали за вами и что вы должны вернуться в Храм Луны в Дарнасе как можно скорее." }, { 12.40, "По прибытии найдите жрицу – она расскажет вам больше. Да пребудет с вами Свет." } } }, t = { d = 19.7, g = 1, v = "nightelf-female#51", n = { m = 219, f = 221 }, c = { m = { { 0.00, "Хорошо, что ты вернулся домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.74, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.48, "Может быть, ты расскажешь мне что-нибудь о том, что ты видел после того, как мы закончим с делами." } }, f = { { 0.00, "Хорошо, что ты вернулась домой. Это всегда радует Тиранду и меня лично, когда кто-то из наших возвращается из дальних странствий." }, { 8.98, "Надеюсь, Элуна благословила твоё путешествие!" }, { 12.71, "Может быть, ты расскажешь мне что-нибудь о том, что ты видела после того, как мы закончим с делами." } } } } },
    [5632] = { d = 24.0, v = "nightelf-female#51", n = { x = 274 }, c = { x = { { 0.00, "Да-да, конечно. Здравствуй. Недавно тут побывала посланница нашего ордена. Она искала тебя." }, { 6.29, "Она мельком упомянула, что в Дарнасе случилось что-то важное и что тебе следует как можно скорее вернуться в Храм Луны." }, { 14.58, "Сразу поговори там со жрицей Алатеей. Наверняка это касается твоих успехов." }, { 20.22, "В общем, возвращайся в Дарнас, как только сможешь." } } } },
    [5633] = { d = 27.3, g = 1, v = "dwarf-female#34", n = { m = 307, f = 311 }, c = { m = { { 0.00, "Добро пожаловать, друг. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом." }, { 7.40, "Пока ты тут странствовал в наших краях, тебя разыскивала здесь жрица из вашего храма." }, { 13.12, "Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны." }, { 17.55, "Прости, большего не скажу, но мне показалось, что дело важное. Когда доберёшься до Храма, поговори со жрицей Алатеей." } }, f = { { 0.00, "Добро пожаловать, подруга. Приятно видеть тебя в наших чертогах. Да пребудет благость с тобой и твоим народом." }, { 7.61, "Пока ты тут странствовала в наших краях, тебя разыскивала здесь жрица из вашего храма." }, { 13.32, "Она сказала, что тебе надо как можно скорее возвращаться в Храм Луны." }, { 17.75, "Прости, большего не скажу, но мне показалось, что дело важное. Когда доберёшься до Храма, поговори со жрицей Алатеей." } } } },
    [5634] = { d = 17.3, g = 1, v = "human-female#45", n = { m = 195, f = 196 }, c = { m = { { 0.00, "Недавно к нам заглянул жрец, которому был нужен ты, герой." }, { 4.05, "Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне." }, { 10.40, "Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит. Да пребудет с тобой Свет." } }, f = { { 0.00, "Недавно к нам заглянул жрец, которому была нужна ты, героиня." }, { 4.12, "Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне." }, { 10.48, "Когда прибудешь туда, отыщи верховного жреца Рохана – он всё объяснит. Да пребудет с тобой Свет." } } }, t = { d = 14.3, v = "human-female#45", n = { x = 168 }, c = { x = { { 0.00, "Твои услуги, оказанные силам Света, неоценимы, а твои деяния – пример блистательной храбрости для всех, кто путешествует в землях, полных опасностей." }, { 10.12, "Прошу, считай этот урок наградой за всё, сделанное тобой." } } } } },
    [5635] = { d = 22.7, g = 1, v = "human-female#45", n = { m = 268, f = 272 }, c = { m = { { 0.00, "Ты привлёк внимание нашего начальства. Тебя просят как можно скорее отправиться в Зал Тайн в Стальгорне." }, { 7.07, "Как я понимаю, вышестоящие считают, что ты уже достаточно показал себя и готов к дальнейшему обучению." }, { 14.10, "Когда доберёшься туда, отыщи верховного жреца Рохана. Он расскажет, что делать дальше. Удачи и да пребудет с тобой Свет." } }, f = { { 0.00, "Ты привлекла внимание нашего начальства. Тебя просят как можно скорее отправиться в Зал Тайн в Стальгорне." }, { 7.01, "Как я понимаю, вышестоящие считают, что ты уже достаточно показала себя и готова к дальнейшему обучению." }, { 14.19, "Когда доберёшься туда, отыщи верховного жреца Рохана. Он расскажет, что делать дальше. Удачи и да пребудет с тобой Свет." } } }, t = { d = 17.9, v = "human-female#45", n = { x = 205 }, c = { x = { { 0.00, "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света." }, { 9.56, "Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." } } } } },
    [5636] = { d = 23.1, g = 1, v = "nightelf-female#51", n = { m = 258, f = 261 }, c = { m = { { 0.00, "Да благословит тебя Элуна, герой. Надеюсь, Свет остаётся с тобой и защищает тебя." }, { 5.94, "Недавно тебя искал один из ваших жрецов." }, { 8.71, "Он сказал, что тебе нужно как можно скорее вернуться в Зал Тайн и поговорить с верховным жрецом Роханом." }, { 15.84, "Похоже, ты отлично себя показал, раз привлёк такое внимание. Не задерживайся здесь, ты нужен своим." } }, f = { { 0.00, "Да благословит тебя Элуна, героиня. Надеюсь, Свет остаётся с тобой и защищает тебя." }, { 5.90, "Недавно тебя искал один из ваших жрецов." }, { 8.68, "Он сказал, что тебе нужно как можно скорее вернуться в Зал Тайн и поговорить с верховным жрецом Роханом." }, { 15.81, "Похоже, ты отлично себя показала, раз привлекла такое внимание. Не задерживайся здесь, ты нужна своим." } } }, t = { d = 17.9, v = "human-female#45", n = { x = 205 }, c = { x = { { 0.00, "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света." }, { 9.56, "Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." } } } } },
    [5637] = { d = 25.1, g = 1, v = "dwarf-male", n = { m = 276, f = 277 }, c = { m = { { 0.00, "Пора тебе отправиться в Штормград. С тобой хочет поговорить верховный жрец Рохан из Зала Тайн." }, { 7.14, "Либо дела очень хороши, либо очень плохи, раз он решил встретиться с тобой лично." }, { 12.78, "Но я подозреваю, что ты отлично себя показал, и то, что он хочет тебя видеть, это добрый знак." }, { 19.51, "Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь." } }, f = { { 0.00, "Пора тебе отправиться в Штормград. С тобой хочет поговорить верховный жрец Рохан из Зала Тайн." }, { 7.14, "Либо дела очень хороши, либо очень плохи, раз он решил встретиться с тобой лично." }, { 12.78, "Но я подозреваю, что ты отлично себя показала, и то, что он хочет тебя видеть, это добрый знак." }, { 19.65, "Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь." } } }, t = { d = 17.9, v = "human-female#45", n = { x = 205 }, c = { x = { { 0.00, "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света." }, { 9.56, "Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." } } } } },
    [5639] = { d = 19.8, g = 1, v = "dwarf-male", n = { x = 224 }, c = { m = { { 0.00, "путник! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки." }, { 9.63, "Не мешкай. Ты найдёшь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!" } }, f = { { 0.00, "путница! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки." }, { 9.72, "Не мешкай. Ты найдёшь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!" } } }, t = { d = 17.9, v = "human-female#45", n = { x = 205 }, c = { x = { { 0.00, "Я рада твоему прибытию. Есть множество вещей, которые нам нужно обсудить, но самая важная – твоё будущее обучение тайному знанию Света." }, { 9.56, "Есть уроки, которые должны выучить все, кто служит Свету. Если ты чувствуешь в себе силы, мы можем начать прямо сейчас." } } } } },
    [5642] = { d = 19.8, v = "scourge-male#83", n = { x = 200 }, c = { x = { { 0.00, "В Оргриммаре происходит нечто важное." }, { 3.31, "Обычно посланцы, которые приезжают сюда за троллями-жрецами, держатся с ленцой. А на этот раз они, похоже, спешили!" }, { 12.65, "Не засиживайся в Громовом Утёсе. Думаю, тебе стоит как можно скорее вернуться на Аллею Духов." } } } },
    [5643] = { d = 23.8, v = "human-female", n = { x = 283 }, c = { x = { { 0.00, "Как и многие из наших жрецов, члены твоего племени проходят обряды инициации." }, { 5.22, "Эти обряды часто наделяют жрецов особыми способностями, которые помогают им выжить." }, { 10.96, "Я чувствую, что тебе пришло время пройти такой обряд. Возвращайся в Аллею Духов в Оргриммаре и поговори с Ур'кьо." }, { 18.66, "То, чему он тебя научит, может оказаться чрезвычайно важным в будущем." } } } },
    [5644] = { d = 32.9, g = 1, v = "scourge-male#83", n = { m = 342, f = 343 }, c = { m = { { 0.00, "Доброго тебе дня. Вижу, ты многому научился, и пришло время вернуться к Эльталисте." }, { 6.17, "Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным." }, { 12.07, "Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом." }, { 16.73, "Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки." }, { 26.57, "Отправляйся в Подгород, поговори с Эльталисте. Она ждёт тебя в Квартале Воинов." } }, f = { { 0.00, "Доброго тебе дня. Вижу, ты многому научилась, и пришло время вернуться к Эльталисте." }, { 6.34, "Есть вещи, рассказать о которых может лишь она, и то лишь самым достойным." }, { 12.23, "Я не скажу, что тебя ждёт – пусть для тебя это будет сюрпризом." }, { 16.89, "Хотя, помнится, когда я был молодым жрецом и только-только понял, что есть истинная сила... божественная сила... Вот это были деньки." }, { 26.73, "Отправляйся в Подгород, поговори с Эльталисте. Она ждёт тебя в Квартале Воинов." } } } },
    [5645] = { d = 22.9, g = 1, v = "human-female#45", n = { m = 266, f = 269 }, c = { m = { { 0.00, "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне." }, { 4.35, "Торопитесь, могучий мой друг, ибо близится срок вашего очередного испытания." }, { 9.53, "Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но моё место здесь. Но да пребудет с вами Свет в пути вашем." }, { 17.81, "Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии." } }, f = { { 0.00, "Ваш верховный жрец Рохан назначает вам аудиенцию в Стальгорне." }, { 4.35, "Торопитесь, могучая моя госпожа, ибо близится срок вашего очередного испытания." }, { 9.75, "Хотя я хотел бы стать свидетелем особых обрядов вашей расы, но моё место здесь. Но да пребудет с вами Свет в пути вашем." }, { 18.03, "Когда вы достигнете города, Рохан будет ждать вас в Палатах Магии." } } } },
    [5646] = { d = 17.8, v = "troll-male#77", n = { x = 206 }, c = { x = { { 0.00, "Эльталисте оказала моему народу большое доверие, посылая ко мне учеников, а теперь я сделаю то же для её племени." }, { 8.09, "Возвращайся в Подгород. Твоя госпожа ждёт тебя в Квартале Воинов, чтобы рассказать ещё больше о твоём народе и его обычаях. Ступай, не медли." } } }, t = { d = 8.3, g = 1, v = "human-female", n = { m = 92, f = 93 }, c = { m = { { 0.00, "Ты вернулся, это хорошо, и даже не слишком поздно – это совсем здорово. У нас есть много вещей, которые надо обсудить." } }, f = { { 0.00, "Ты вернулась, это хорошо, и даже не слишком поздно – это совсем здорово. У нас есть много вещей, которые надо обсудить." } } } } },
    [5647] = { d = 31.2, v = "nightelf-female#51", n = { x = 363 }, c = { x = { { 0.00, "Твоя раса так сильна. Мы гордимся союзом с вами." }, { 3.28, "С каждым закатом ты и твои сородичи не только всё ближе к разгадке вашего истинного происхождения, но и обретаете всё большую уверенность в том, что вы на верном пути во многом." }, { 15.35, "Именно эта уверенность приносит вам победу." }, { 18.74, "Недавно из Стальгорна пришла весть. Тебя просят вернуться и поговорить с верховным жрецом Роханом в Палатах Магии." }, { 26.72, "Не стоит заставлять его ждать. Да направит твой путь Элуна." } } } },
    [5648] = { d = 30.9, g = 1, v = "troll-female", n = { m = 324, f = 326 }, c = { m = { { 0.00, "Что ж, вот ты и готов к своему первому испытанию." }, { 3.52, "К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда." }, { 9.99, "Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас." }, { 18.05, "Её зовут Корджа. Найди её, исцели и дай ей благословение наших предков." }, { 24.50, "Сделай это – ия сочту, что ты подтвердил свою готовность ступить на путь жреца." } }, f = { { 0.00, "Что ж, вот ты и готова к своему первому испытанию." }, { 3.50, "К югу от Колючего Холма, сразу за городской чертой, лежит раненная орчиха из нашего отряда." }, { 9.96, "Она сражалась с остатками прежнего Праудмурова войска, и ей не повезло в бою. Помочь ей может только кто-то из нас." }, { 18.03, "Её зовут Корджа. Найди её, исцели и дай ей благословение наших предков." }, { 24.48, "Сделай это – ия сочту, что ты подтвердила свою готовность ступить на путь жреца." } } }, t = { d = 25.9, g = 1, v = "troll-female", n = { m = 260, f = 264 }, c = { m = { { 0.00, "Молодец... оживил и вылечил Кор'жу... пусть она храбро обороняет и дальше наш город от нападений гадких людей." }, { 8.49, "Я вспоминаю дни битв, где нередко мудрый сметает того, кто полагается на грубую силу." }, { 14.71, "Хорошо сработал. Возьми это одеяние." }, { 17.49, "Может быть, оно пригодится тебе, может быть нет, но ты заслужил её и я рада назвать тебя братом." } }, f = { { 0.00, "Умница... оживила и вылечила Кор'жу... пусть она храбро обороняет и дальше наш город от нападений гадких людей." }, { 9.47, "Я вспоминаю дни битв, где нередко мудрый сметает того, кто полагается на грубую силу." }, { 15.68, "Хорошо сработала. Возьми это одеяние." }, { 18.68, "Может быть, оно пригодится тебе, может быть нет, но ты заслужила её и я рада назвать тебя сестрой." } } } } },
    [5649] = { d = 31.5, g = 1, v = "troll-male#78", n = { m = 326, f = 327 }, c = { m = { { 0.00, "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры." }, { 4.81, "Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи ещё живы." }, { 13.82, "Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне." }, { 19.66, "Ты это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь готов." } }, f = { { 0.00, "Понимаешь, наш народ присоединился к Орде, потому что они к нам добры." }, { 4.81, "Они – преданные друзья, они многому нас научили, внушили нам представление о чести... Но наши старые обычаи ещё живы." }, { 13.82, "Орки не одобряют многие из них, но никто не мешает нам придерживаться их втайне." }, { 19.66, "Ты это знаешь. Вот почему я посылаю тебя в Колючий Холм, к Тай'джин. Она откроет тебе мудрость нашего племени. Ступай к ней, когда будешь готова." } } }, t = { d = 33.1, g = 1, v = "troll-female", n = { x = 371 }, c = { m = { { 0.00, "Аа... ты пришёл к Тай'джин. Это хорошо." }, { 3.09, "Тебе нужно знать, что мы уже не то племя, что присоединилось когда-то к Орде. Сейчас мы гораздо сильнее." }, { 10.38, "Мы сильнее потому, что научились приспосабливаться, Орда многому научила нас." }, { 15.90, "Мы больше не побеждаем врагов, а потом забираем у них силу. Сейчас, мы сначала собираем силы, а потом побеждаем врагов." }, { 24.71, "Разница кажется незначительной, но ты узнаешь и почувствуешь её. Племя рассчитывает, что ты обучишься таким вещам." } }, f = { { 0.00, "Аа... ты пришла к Тай'джин. Это хорошо." }, { 2.96, "Тебе нужно знать, что мы уже не то племя, что присоединилось когда-то к Орде. Сейчас мы гораздо сильнее." }, { 10.26, "Мы сильнее потому, что научились приспосабливаться, Орда многому научила нас." }, { 15.77, "Мы больше не побеждаем врагов, а потом забираем у них силу. Сейчас, мы сначала собираем силы, а потом побеждаем врагов." }, { 24.59, "Разница кажется незначительной, но ты узнаешь и почувствуешь её. Племя рассчитывает, что ты обучишься таким вещам." } } } } },
    [5650] = { d = 50.3, v = "scourge-male#82", n = { x = 426 }, c = { x = { { 0.00, "Мы черпаем силу из тьмы и теней, но ваше дело – не только дело тьмы." }, { 6.10, "Вы поняли, что большая заслуга есть и в изучении искусства лечения. Это мудрый выбор." }, { 13.95, "Но прежде чем познать тьму, вы должны познать и свет, а для этого нужно пройти испытание." }, { 22.51, "К северу от кладбища находится раненый страж смерти по имени Кел – он уже очень долго защищает нас от гноллов, и ему требуется лечение." }, { 35.70, "Но для того чтобы он мог и дальше исполнять свой долг, вы должны также придать ему сил." }, { 43.71, "Используйте для этого свои заклинания, а потом возвращайтесь ко мне." } } }, t = { d = 26.3, g = 1, v = "scourge-male#82", n = { m = 199, f = 199 }, c = { m = { { 0.00, "Ты прошёл мой тест. Молодец." }, { 3.12, "Итак, вскоре ты сможешь погрузить на себя ещё одну ношу, возложить на себя ответственность изучать тёмные энергии, к которым не имеет доступ жрец любой другой расы." }, { 21.06, "Возьми это одеяние как символ! Носи его с гордостью." } }, f = { { 0.00, "Ты прошела мой тест. Умница." }, { 3.60, "Итак, вскоре ты сможешь погрузить на себя ещё одну ношу, возложить на себя ответственность изучать тёмные энергии, к которым не имеет доступ жрец любой другой расы." }, { 18.77, "Возьми это одеяние как символ! Носи его с гордостью." } } } } },
    [5651] = { d = 46.5, v = "scourge-male#82", n = { x = 406 }, c = { x = { { 0.00, "Отрёкшиеся извлекли много уроков из своего опыта и поняли такие вещи, о которых остальные только начинают догадываться." }, { 10.84, "И несмотря на то что наш путь лежит во тьме, скоро вы поймёте, что очень много вещей зависит от неё – так же как и от света." }, { 21.88, "Вы научитесь использовать и то и другое... с должной осторожностью." }, { 27.97, "Но никогда не забывайте того, что нас создали в тлене и бросили гнить, как какие-нибудь отбросы. Тьма – это наш дом." }, { 38.86, "Когда будете готовы узнать больше, разыщите тёмного священника Берила в Брилле." } } }, t = { d = 16.4, g = 1, v = "scourge-male#82", n = { m = 129, f = 130 }, c = { m = { { 0.00, "Наконец-то ты появился. Одной лишь твоё веры недостаточно, чтобы пройти испытания, ожидающие тебя." }, { 10.65, "Нужна настойчивость, да и немного честолюбия не помешает." } }, f = { { 0.00, "Наконец-то ты появилась. Одной лишь твоё веры недостаточно, чтобы пройти испытания, ожидающие тебя." }, { 10.52, "Нужна настойчивость, да и немного честолюбия не помешает." } } } } },
    [5654] = { d = 15.6, v = "troll-female", n = { x = 177 }, c = { x = { { 0.00, "Пора тебе встретиться с Ур'кьо. Ты найдёшь его на аллее Духов, в городе орков. Ступай туда и поговори с ним." }, { 7.46, "Пора тебе познать древнюю мудрость нашего народа. Пора вступить в круг и стать настоящим жрецом нашего племени." } } } },
    [5655] = { d = 18.1, v = "troll-male#77", n = { x = 199 }, c = { x = { { 0.00, "Мне нужно было удостовериться, что ты не уйдёшь слишком далеко от дома." }, { 4.90, "Меня послали за тобой потому, что Ур'кьо, величайший из наших жрецов, желает поговорить с тобой. Ступай туда." }, { 12.97, "Ступай в Аллею Духов в городе орков и поговори с Ур'кьо. Он ждёт тебя." } } } },
    [5656] = { d = 25.9, v = "scourge-male#83", n = { x = 272 }, c = { x = { { 0.00, "Моё нестареющее сердце всегда греет мысль о том, что по миру бродит множество жрецов всех культур." }, { 7.48, "Хорошо знать, что на свете есть сила, не имеющая отношения к тайной магии и вполне доступная нам." }, { 14.69, "Вот почему я сочту за честь указать тебе путь." }, { 18.50, "Уркьо, ваш великий жрец в Оргриммаре, просит тебя прибыть к нему. Ты найдёшь его на аллее Духов." } } } },
    [5657] = { d = 15.5, g = 1, v = "human-female", n = { m = 166, f = 166 }, c = { m = { { 0.00, "Домой! Возвращайся домой, юный герой!" }, { 2.99, "Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути." }, { 10.04, "Ступай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдёшь его там." } }, f = { { 0.00, "Домой! Возвращайся домой, юная героиня!" }, { 3.03, "Твой духовный наставник Ур'кьо просит тебя вернуться к нему и поговорить об избранном тобой пути." }, { 10.08, "Ступай в Аллею Духов в Оргриммаре, великом городе Орды! Ты найдёшь его там." } } } },
    [5660] = { d = 20.9, g = 1, v = "troll-female", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Далеко же ты забрался, герой. Тебя ждут в большом городе под землёй. Твоя госпожа, Эльталисте, велит тебе вернуться." }, { 8.91, "Как и в моём племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту." }, { 16.36, "Лучше лети в Квартал Воинов на самом быстром дирижабле." } }, f = { { 0.00, "Далеко же ты забралась, героиня. Тебя ждут в большом городе под землёй. Твоя госпожа, Эльталисте, велит тебе вернуться." }, { 9.19, "Как и в моём племени, есть вещи, которым тебя может научить лишь она. И не задерживайся попусту." }, { 16.64, "Лучше лети в Квартал Воинов на самом быстром дирижабле." } } }, t = { d = 16.1, g = 1, v = "human-female", n = { m = 169, f = 171 }, c = { m = { { 0.00, "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно." }, { 6.15, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён." } }, f = { { 0.00, "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно." }, { 7.35, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." } } } } },
    [5661] = { d = 26.4, v = "troll-male#77", n = { x = 277 }, c = { x = { { 0.00, "Ты всего лишь гость в деревне Кровавого Копыта, а дом твой далеко. Меня послали сюда искать жрецов из моего племени." }, { 7.84, "С ними хотят говорить вожди. Но и тебе я могу помочь." }, { 12.21, "Говорят, что ваша главная жрица велит всем Отрёкшимся прийти к ней – видно, ей есть что сказать." }, { 19.06, "Ступай, поговори с Эльталисте в Квартале воинов этого вашего города, как его там..." } } }, t = { d = 16.1, g = 1, v = "human-female", n = { m = 169, f = 171 }, c = { m = { { 0.00, "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно." }, { 6.15, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён." } }, f = { { 0.00, "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно." }, { 7.35, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." } } } } },
    [5662] = { d = 23.6, v = "troll-male#77", n = { x = 263 }, c = { x = { { 0.00, "Моё почтение тебе и твоему народу. Обычно я учу лишь своих соплеменников." }, { 5.02, "Тебе же передала знания Эльталисте из города, некогда звавшегося Лордероном." }, { 10.62, "Возвращайся к ней, ведь только она может передать тебе способности, отличающие воинов вашей веры от других." }, { 18.99, "Ступай в Квартал Воинов Подгорода и отыщи там свою госпожу." } } }, t = { d = 16.1, g = 1, v = "human-female", n = { m = 169, f = 171 }, c = { m = { { 0.00, "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно." }, { 6.15, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён." } }, f = { { 0.00, "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно." }, { 7.35, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." } } } } },
    [5663] = { d = 17.8, g = 1, v = "scourge-male#83", n = { m = 186, f = 186 }, c = { m = { { 0.00, "Эльталисте послала вести всем своим жрецам. Нам велено отправить молодёжь в Подгород на обучение." }, { 7.31, "Если ты в самом деле считаешь себя одним из верных, возвращайся туда." }, { 12.89, "Эльталисте живёт в Квартале Воинов в глубинах Подгорода." } }, f = { { 0.00, "Эльталисте послала вести всем своим жрецам. Нам велено отправить молодёжь в Подгород на обучение." }, { 7.31, "Если ты в самом деле считаешь себя одной из верных, возвращайся туда." }, { 12.84, "Эльталисте живёт в Квартале Воинов в глубинах Подгорода." } } }, t = { d = 16.1, g = 1, v = "human-female", n = { m = 169, f = 171 }, c = { m = { { 0.00, "А, хорошо, ещё один прибыл. Время для меня не имеет значения, но для других-то оно ценно." }, { 6.15, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждён." } }, f = { { 0.00, "А, хорошо, ещё одна прибыла. Время для меня не имеет значения, но для других-то оно ценно." }, { 7.35, "Много вещей предстоит тебе изучить, а мне предстоит тебя многому научить. Так что давай, учись. Учись, и будешь вознаграждена." } } } } },
    [5673] = { d = 25.8, v = "human-female#45", n = { x = 298 }, c = { x = { { 0.00, "Знай, что здесь ты можешь в любое время обратиться к любому наставнику." }, { 4.94, "Впрочем, есть знания, которые мы не можем тебе предоставить. Среди них – учение вашей богини Элуны." }, { 11.69, "Верным своим приверженцам она даёт особые способности, и, если я не ошибаюсь, тебе пора вернуться домой, в Храм Луны, и пройти испытание." }, { 21.31, "Так что как сможешь – возвращайся и поговори со жрицей Алатеей." } } }, t = { d = 17.1, v = "nightelf-female#51", n = { x = 205 }, c = { x = { { 0.00, "Элуна благословляет тебя за столь быстрое возвращение. Важное дело ожидает тебя и важные дела ждут твоего решения." }, { 7.88, "Когда отдохнёшь от своего путешествия повидай меня снова. Тогда мы обсудим, как именно мы начнём... точнее продолжим, твою тренировку!" } } } } },
    [5674] = { d = 22.1, g = 1, v = "nightelf-female#51", n = { m = 260, f = 262 }, c = { m = { { 0.00, "Настал славный день. Ты достиг возраста, когда наши жрецы изучают те способности, которые свойственны только ночным эльфам." }, { 8.58, "Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела." }, { 15.56, "Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны." } }, f = { { 0.00, "Настал славный день. Ты достигла возраста, когда наши жрицы изучают те способности, которые свойственны только ночным эльфам." }, { 8.65, "Тебе следует вернуться в Храм Луны и поговорить со жрицей Алатеей, как только закончишь тут свои дела." }, { 15.63, "Она испытает тебя, убедится в твоей готовности и лишь потом научит тебя Благодати Элуны." } } } },
    [5675] = { d = 20.2, g = 1, v = "dwarf-male", n = { m = 231, f = 234 }, c = { m = { { 0.00, "Не тяни время, друг. Пора тебе возвращаться домой в Дарнасс. Жрица Алатея велит возвращаться на обучение." }, { 7.17, "Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди." }, { 14.60, "Алатея в своём письме говорит, что будет ждать тебя в храме Луны. Удачи." } }, f = { { 0.00, "Не тяни время, подруга. Пора тебе возвращаться домой в Дарнасс. Жрица Алатея велит возвращаться на обучение." }, { 7.53, "Похоже, тебя решили допустить к испытаниям вроде тех, что проходят служители Света. Так что как сможешь – иди." }, { 14.96, "Алатея в своём письме говорит, что будет ждать тебя в храме Луны. Удачи." } } } },
    [5677] = { d = 26.0, v = "dwarf-male", n = { x = 308 }, c = { x = { { 0.00, "Мне бы хотелось показать тебе кое-какие из наших особых методик обучения, которые направят тебя по пути Света, но меня опередили." }, { 8.86, "Тебе нужно вернуться в Штормград... Прямо сейчас. Поверь мне, так будет лучше." }, { 14.02, "Когда ты встретишься с Верховной жрицей Лореной из Собора Света, ты поймёшь, о чём я говорю." }, { 20.24, "Для вашей расы настало время подумать о будущем и выбрать свой собственный путь." } } }, t = { d = 27.8, v = "human-female#45", n = { x = 313 }, c = { x = { { 0.00, "Ах, у вас сейчас чудесное время. Я начал задаваться вопросом, все ли мои посланники были успешными." }, { 6.87, "Я рад видеть, что это так, иначе я готов поспорить, что вы всё ещё были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа." }, { 17.88, "Вы готовы? Я имею в виду готовы к дальнейшим тренировкам." }, { 21.91, "Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." } } } } },
    [5678] = { d = 27.8, v = "nightelf-female#51", n = { x = 311 }, c = { x = { { 0.00, "Тебе пора возвращаться в Штормград. Старшие иерархи призывают тебя продолжить тренировки." }, { 6.15, "Жаль, что мне пришлось разыскивать тебя, но я делаю это во имя союза между нашими расами." }, { 13.30, "Буду говорить откровенно, тайная магия не внушает мне никакого доверия, хоть по благословлению богов, хоть без них..." }, { 21.64, "Ты понимаешь, о чём я говорю? Вернись в Собор Света. Верховная жрица Лорена ждёт тебя." } } }, t = { d = 27.8, v = "human-female#45", n = { x = 313 }, c = { x = { { 0.00, "Ах, у вас сейчас чудесное время. Я начал задаваться вопросом, все ли мои посланники были успешными." }, { 6.87, "Я рад видеть, что это так, иначе я готов поспорить, что вы всё ещё были бы в мире, узнавая больше обо всех угрозах, которые существуют против нашего народа." }, { 17.88, "Вы готовы? Я имею в виду готовы к дальнейшим тренировкам." }, { 21.91, "Ваша сила растёт быстрее, и я чувствую, что вы готовы больше узнать о нашей вере." } } } } },
    [5713] = { d = 34.5, v = "nightelf-female", n = { x = 384 }, c = { x = { { 0.00, "Я направлялась в Аубердин с важным донесением, когда меня атаковал фурболг Марош и его следопыты." }, { 7.45, "Во время атаки я получила отравление, так что еле держусь. Я могу изготовить противоядие, но это займёт некоторое время." }, { 16.28, "Хотела попросить вас защитить меня, пока я не приму противоядие. Я подсоблю вам своим луком, как смогу." }, { 23.91, "Если мы выживем, то смогу доставить донесение в Аубердин, а вас попрошу поговорить с Онейей на Заставе Мейстры и проинформировать её о случившемся." } } }, t = { d = 14.5, g = 1, v = "nightelf-female#52", n = { x = 162 }, c = { m = { { 0.00, "Вы принесли долгожданное известие, герой. Приятно слышать, что Айнаша жива и здорова благодаря вам." }, { 6.61, "Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь." } }, f = { { 0.00, "Вы принесли долгожданное известие, героиня. Приятно слышать, что Айнаша жива и здорова благодаря вам." }, { 7.20, "Смею надеяться, вы примете эту награду за вашу доблесть. Пусть Элуна заботится о вас и освещает ваш путь." } } } } },
    [5722] = { d = 40.1, v = "tauren-male", n = { x = 392 }, c = { x = { { 0.00, "В Огненной пропасти Магату интересуют не только трогги." }, { 4.34, "До неё дошли слухи, что один из её слуг, некий Маур Зловещий Тотэм, будучи в пропасти, нашёл нечто особенное, но выбраться оттуда ему не удалось." }, { 16.62, "Она хочет, чтобы кто-нибудь нашёл тело Маура – если оно ещё цело – и выяснил, что же он такое нашёл, пытаясь вести переговоры с троггами." }, { 27.53, "Если найдёшь что-нибудь интересное, принеси это Магате, и она наверняка не поскупится на награду." }, { 35.49, "Да, пропасть ищи в самых тёмных закоулках Оргриммара." } } }, t = { d = 21.8, v = "tauren-male", n = { x = 216 }, c = { x = { { 0.00, "Тело выглядит так, будто Маура жестоко били дубинками или кулаками, но большая часть одежды и снаряжения на месте." }, { 8.93, "Похоже, троггам не сильно были нужны его пожитки." }, { 13.16, "Вы начинаете осматривать тело в поисках любых предметов, которые могли бы заинтересовать Магату." } } } } },
    [5723] = { d = 37.9, v = "tauren-male", n = { x = 384 }, c = { x = { { 0.00, "Назойливые твари, известные как трогги, вдруг полезли из заполненных лавой туннелей под Оргриммаром." }, { 8.00, "Магата по своей доброте душевной хотела договориться с этими тварями, но они набросились на её переговорщиков и перебили их." }, { 17.80, "Но такого обращения с тауренами она допустить не может, так что теперь для неё эти твари – враги Орды." }, { 26.79, "Она просит тебя разделаться с этими троггами, прежде чем они начнут угрожать Орде из-под земли." }, { 34.17, "Найди Огненную пропасть и уничтожь их всех!" } } }, t = { d = 18.2, v = "tauren-male", n = { x = 172 }, c = { x = { { 0.00, "Я рад, что ты серьёзно отнёсся к просьбе Магаты. Спасибо тебе." }, { 4.97, "Теперь, когда троггов поубавилось, они уже не полезут так нагло на поверхность!" }, { 12.10, "Может, в будущем мы сумеем узнать, откуда взялись эти твари, и что им надо." } } } } },
    [5724] = { d = 26.3, v = "tauren-male", n = { x = 249 }, c = { x = { { 0.00, "Под телом погибшего таурена вы находите сумку." }, { 3.73, "Убитый до сих пор крепко держит её – видимо, он пытался уберечь её во время нападения троггов." }, { 12.22, "Высвободив сумку из его крепкой хватки, вы закидываете её себе на плечо и готовитесь возвращаться наружу из туннелей, чтобы отправиться к Рахауро в Громовой Утёс." } } }, t = { d = 13.0, v = "tauren-male", n = { x = 117 }, c = { x = { { 0.00, "Прекрасно. Благодарю тебя." }, { 2.32, "Магата сказала мне, что если ты найдёшь её сородича, то я должен отдать тебе вот это. Прошу, прими в знак благодарности." } } } } },
    [5725] = { d = 27.7, v = "human-male", n = { x = 326 }, c = { x = { { 0.00, "Тебе хорошо известно, что в Легионе принято всячески одаривать идейных последователей." }, { 5.93, "Некоторым из этих даров лучше бы оказаться в руках у Тёмной Госпожи, чем у... простецов." }, { 12.33, "Например, в пещерах под Оргриммаром скрывается секта Совета Теней, известная как \"Огненный Клинок\"." }, { 19.04, "Госпожа сообщила, что они получили две могущественные книги заклинаний – она хотела бы \"позаимствовать\" их. Выполни её волю." } } }, t = { d = 18.5, g = 1, v = "human-male", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Молодец, герой. Ты оказал Тёмной Госпоже хорошую услугу. Её подданным пригодятся твои упорство и честолюбие." }, { 7.60, "Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети." } }, f = { { 0.00, "Молодец, героиня. Ты оказала Тёмной Госпоже хорошую услугу. Её подданным пригодятся твои упорство и честолюбие." }, { 7.83, "Заходи ко мне в будущем. Быть может, я отправлю тебя на новые подвиги, которые помогут Тёмной Госпоже свергнуть Короля-лича и освободить рабов Плети." } } } } },
    [5726] = { d = 42.6, g = 1, v = "orc-male", n = { m = 476, f = 480 }, c = { m = { { 0.00, "Чего я не потерплю, так это предательства среди своих." }, { 3.84, "Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее." }, { 17.69, "Но ты, юный искатель приключений, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду..." }, { 25.50, "можешь обнаружить настоящего главу заговора!" }, { 29.17, "Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне." } }, f = { { 0.00, "Чего я не потерплю, так это предательства среди своих." }, { 3.84, "Однако было бы глупо действовать напролом и сразу арестовать единственного известного мне предателя – это не очистит наши земли от порчи, наоборот, зараза расползётся ещё сильнее." }, { 17.69, "Но ты, юная искательница приключений, можешь проникнуть туда, куда моим агентам ходу нет. Ты можешь узнать правду..." }, { 25.85, "можешь обнаружить настоящего главу заговора!" }, { 29.53, "Если у тебя достаточно отваги, отправляйся к скале Черепа к востоку от Оргриммара, сорви с одного из чернокнижников клана Пылающего Клинка лейтенантский знак отличия и принеси его мне." } } }, t = { d = 37.0, v = "orc-male", n = { x = 403 }, c = { x = { { 0.00, "Молодец! Слава духам! Быть может, именно ты – тот, кому суждено избавить меня от самых серьёзных моих опасений!" }, { 8.57, "Ну кто бы мог подумать, что столь юное существо, как ты, сумеет достойно защитить наше дело?" }, { 15.14, "Ты мне напоминаешь меня самого в молодости..." }, { 18.22, "Я позабочусь о том, чтобы тебя достойно вознаградили за труды – если мы оба переживём грядущую бурю." }, { 26.07, "Ладно, сейчас не время рассыпаться в похвалах. То, что тебе уже удалось совершить, – пустяки в сравнении с тем, что ещё предстоит... Но начало положено хорошее." } } } } },
    [5727] = { d = 38.8, g = 1, v = "orc-male", n = { m = 420, f = 418 }, c = { m = { { 0.00, "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий." }, { 5.43, "В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю." }, { 10.81, "Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка..." }, { 18.48, "Однако не торопись вступать с ним в бой. Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам." }, { 27.04, "Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одного из своих. А потом возвращайся ко мне." } }, f = { { 0.00, "Ну-ка, посмотрим, стоил ли принесённый тобой знак отличия таких усилий." }, { 5.43, "В городе живёт чернокнижник, который уверен, будто я ему полностью доверяю." }, { 10.81, "Он и не подозревает, что мне известно о его предательстве. На самом деле он – предводитель Пылающего Клинка..." }, { 18.48, "Однако не торопись вступать с ним в бой. Он нам ещё нужен, мы можем использовать его, чтобы навредить нашим врагам." }, { 27.04, "Отнеси ему этот знак отличия в расселину Теней в Оргриммаре, поговори с ним и проверь, примет ли он тебя за одну из своих. А потом возвращайся ко мне." } } }, t = { d = 22.9, g = 1, v = "orc-male", n = { x = 242 }, c = { m = { { 0.00, "Великолепно, герой! Просто великолепно!" }, { 3.31, "Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам." }, { 8.72, "Возможно, это поможет нам уничтожить Совет Теней раз и навсегда." }, { 13.69, "Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь." } }, f = { { 0.00, "Великолепно, героиня! Просто великолепно!" }, { 3.38, "Твоё сегодняшнее деяние – всего лишь первый шаг к куда более серьёзным делам." }, { 8.79, "Возможно, это поможет нам уничтожить Совет Теней раз и навсегда." }, { 13.76, "Перескажи мне всё, что он говорил, и смотри, не упусти ни слова: какой-нибудь пустяк может оказаться важнее, чем ты думаешь." } } } } },
    [5728] = { d = 34.3, g = 1, v = "orc-male", n = { m = 376, f = 375 }, c = { m = { { 0.00, "Хм, предводители клана Огненного Клинка... Это серьёзно. Если Нииру ими дорожит, значит, именно их и нужно ликвидировать." }, { 8.36, "Этот сатир... Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить." }, { 15.85, "Возвращайся в расселину Теней и проникни в Огненную пропасть. Разыщи этих предводителей клана Огненного Клинка и убей их." }, { 25.43, "Но будь осторожен, чтобы Нииру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя одним из братьев по оружию." } }, f = { { 0.00, "Хм, предводители клана Огненного Клинка... Это серьёзно. Если Нииру ими дорожит, значит, именно их и нужно ликвидировать." }, { 8.36, "Этот сатир... Баззалан, и тот, второй, которого упоминал Нииру, – он кто, чернокнижник? – их следует убить." }, { 15.85, "Возвращайся в расселину Теней и проникни в Огненную пропасть. Разыщи этих предводителей клана Огненного Клинка и убей их." }, { 25.43, "Но будь осторожна, чтобы Нииру не узнал, что это твоих рук дело. Пусть по-прежнему считает тебя одной из сестёр по оружию." } } }, t = { d = 22.4, v = "orc-male", n = { x = 246 }, c = { x = { { 0.00, "Я рад, что ты вернулся. Преданные мне агенты уже сообщили, что в пещерах под Оргриммаром воцарился хаос – теперь, когда их предводители убиты." }, { 9.97, "Мне даже докладывали, что Ниру более чем взбудоражен. Похоже, мы пробили брешь в его броне." }, { 16.46, "Не могу не признать, что меня это радует... Пусть небольшая, но всё же победа." } } } } },
    [5729] = { d = 33.8, v = "orc-male", n = { x = 368 }, c = { x = { { 0.00, "Думаю, теперь тебе следует попытаться войти в число приближённых Нииру." }, { 5.12, "Если он действительно так взбудоражен, как мне доносят, мы убьём сразу двух зайцев." }, { 11.03, "Во-первых, тебе, возможно, удастся разузнать побольше о Совете или, по крайней мере, о Пылающем Клинке, и, во-вторых, он, возможно, начнёт доверять тебе настолько, что попросит ему помогать." }, { 24.10, "Ему сейчас отчаянно не хватает помощников." }, { 27.57, "Возвращайся в Расселину и поговори с ним, но не особо навязывайся." } } }, t = { d = 29.6, g = 1, v = "orc-male", n = { x = 276 }, c = { m = { { 0.00, "Ну в чём дело?! Ах, это ты, герой... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всём виноват." }, { 7.55, "Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами." }, { 14.56, "Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь." } }, f = { { 0.00, "Ну в чём дело?! Ах, это ты, героиня... Прошу прощения. Я зол, как бешеный кодо... Но, возможно, я сам во всём виноват." }, { 9.45, "Отправляя путешественников в Огненную пропасть, я должен был предвидеть, что это чревато проблемами." }, { 16.46, "Похоже, что Баззалана и Жергоша застиг врасплох кто-то из Тралловых доброхотов. Они оба убиты. Как это невовремя! Но тут уж ничего не поделаешь." } } } } },
    [5730] = { d = 30.8, g = 1, v = "orc-male", n = { m = 340, f = 340 }, c = { m = { { 0.00, "Теперь ты один из моих лейтенантов! Готовься, герой. Скоро я призову тебя." }, { 5.70, "Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать." }, { 14.44, "Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти." }, { 20.26, "А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы." }, { 27.70, "Возвращайся ко мне как можно скорее." } }, f = { { 0.00, "Теперь ты одна из моих лейтенантов! Готовься, героиня. Скоро я призову тебя." }, { 5.71, "Можно считать, что с Огненным Клинком я зря потратил время, но это не значит, что другие планы Совета Теней должны пострадать." }, { 14.45, "Я сделаю всё, что смогу, чтобы свести к минимуму потери здесь, в Огненной пропасти." }, { 20.27, "А пока что распоряжусь, чтобы мои агенты в Степях и Ясеневом лесу начали выполнять наши последние замыслы." }, { 27.71, "Возвращайся ко мне как можно скорее." } } }, t = { d = 17.1, v = "orc-male", n = { x = 180 }, c = { x = { { 0.00, "Ясеневый лес? Хм. Впервые слышу о присутствии Совета или Пылающего Клинка в Ясеневом лесу. Я поручу своим агентам это проверить. А ты молодец." }, { 11.10, "Пока отдыхай, занимайся другими делами. Скоро я призову тебя снова. Лок-тар Огар!" } } } } },
    [5761] = { d = 36.8, v = "orc-male", n = { x = 401 }, c = { x = { { 0.00, "Главная задача, которую поручил мне наш великий вождь, – это извести тех тварей, которые повинны в том, что в великий город нашего владыки проникают демоны." }, { 10.65, "Клан Пылающего Клинка – главная, но не единственная угроза." }, { 14.87, "Есть ещё и Огненный Клинок, клан, который обосновался в Огненной пропасти и втайне смущает умы простых представителей Орды." }, { 23.90, "Чтобы их остановить, нужно убить их предводителя, стража Скверны по имени Тарагаман Ненасытный." }, { 31.74, "Убей его. Я уверен, Вождь будет рад получить его сердце..." } } }, t = { d = 18.1, g = 1, v = "orc-male", n = { x = 164 }, c = { m = { { 0.00, "Ага! Тебе это удалось! Тралл, конечно, будет в восторге." }, { 4.89, "Я позабочусь о том, чтобы это сердце попало по назначению." }, { 9.36, "Ну, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоём успехе. Спасибо за помощь, герой." } }, f = { { 0.00, "Ага! Тебе это удалось! Тралл, конечно, будет в восторге." }, { 4.89, "Я позабочусь о том, чтобы это сердце попало по назначению." }, { 9.36, "Ну, а ты можешь отпраздновать свою победу. Я сообщу Траллу о твоём успехе. Спасибо за помощь, героиня." } } } } },
    [5805] = { d = 29.4, v = "human-male#114", n = { x = 327 }, c = { x = { { 0.00, "Добро пожаловать в \"World of Warcraft\"!" }, { 2.79, "В знак особой благодарности за приобретение коллекционного издания \"World of Warcraft\" примите этот подарочный сертификат и передайте Мериссе Стилвелл в долине Североземья." }, { 15.44, "Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе." }, { 23.98, "Ещё раз благодарим вас и желаем приятного пребывания в \"World of Warcraft\"!" } } }, t = { d = 5.9, v = "human-female", n = { x = 67 }, c = { x = { { 0.00, "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" } } } } },
