    [5844] = { d = 29.8, v = "human-male#114", n = { x = 332 }, c = { x = { { 0.00, ".Добро пожаловать в World of Warcraft!" }, { 2.78, "В знак особой благодарности за приобретение коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Ворну Небесному Провидцу в лагере Нараче." }, { 15.94, "Вы получите подарок – маленького спутника, который будет сопровождать вас на пути к приключениям и славе." }, { 24.48, "Ещё раз благодарим вас и желаем приятного пребывания в World of Warcraft" } } }, t = { d = 7.1, v = "tauren-male#68", n = { x = 67 }, c = { x = { { 0.00, "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" } } } } },
    [5847] = { d = 28.8, v = "human-male#114", n = { x = 322 }, c = { x = { { 0.00, "Добро пожаловать в World of Warcraft!" }, { 2.75, "В качестве особой благодарности за покупку коллекционного издания World of Warcraft примите этот подарочный сертификат и передайте его Клэр Вилловер в Могильник." }, { 14.64, "Вас ждёт подарок – маленький спутник, который будет сопровождать вас на пути к приключениям и славе." }, { 22.66, "Ещё раз благодарим вас и желаем приятного времяпрепровождения в World of Warcraft!" } } }, t = { d = 7.5, v = "scourge-female#80", n = { x = 67 }, c = { x = { { 0.00, "Ну, теперь приветствую тебя в мире Азерота. Иди вперёд, к славе, наградам и почестям!" } } } } },
    [5881] = { d = 37.2, v = "tauren-male", n = { x = 342 }, c = { x = { { 0.00, "Орда не даёт нам растерять силы, и это правильно! С самой Великой Войны мы здесь, в Калимдоре, живём неплохо." }, { 9.73, "Я прошу тебя оказать мне услугу: один парень по имени Гриш Выносливый Гонец охраняет Великий подъёмник в западных пустошах." }, { 20.45, "Передай ему это письмо: там говорится, что один из солдат запаса скоро придёт ему на смену, чтобы он мог навестить свою семью." }, { 31.46, "Гриш недавно просил об этом, и он будет рад услышать эти новости." } } }, t = { d = 10.6, v = "tauren-male", n = { x = 97 }, c = { x = { { 0.00, "Это хорошие новости; я слишком долго сижу здесь, охраняя этот кусок дерева. Теперь я смогу побыть со своими родными... Ура!" } } } } },
    [5921] = { d = 38.6, g = 1, v = "nightelf-male#59", n = { m = 444, f = 449 }, c = { m = { { 0.00, "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны." }, { 12.62, "Теперь, когда ты встал на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну." }, { 21.09, "Пользуйся им, когда тебе нужно знание или уединение Лунной поляны." }, { 26.06, "Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, юный друид." } }, f = { { 0.00, "На священной земле Лунной поляны рады всем друидам, невзирая на последние разногласия в Круге Кенария между верховным друидом Оленьим Шлемом и хранителем Ремулом – стражем Лунной поляны." }, { 12.36, "Теперь, когда ты встала на путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну." }, { 20.86, "Пользуйся им, когда тебе нужно знание или уединение Лунной поляны." }, { 25.82, "Вот первый урок: отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, по которому ты ныне следуешь. Удачи тебе, юная дева-друид." } } }, t = { d = 26.9, v = "nightelf-male#54", n = { x = 301 }, c = { x = { { 0.00, "\"Да будет так, отец Кенарий. Да будет так.\"" }, { 3.51, "Дендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы." }, { 10.90, "\"Первое обличье, которое тебе следует освоить, - это обличье медведя." }, { 15.59, "Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути - это твоя забота! И так отныне будет всегда.\"" } } } } },
    [5922] = { d = 52.6, v = "tauren-male#67", n = { x = 437 }, c = { x = { { 0.00, "На священной земле Лунной поляны рады всем друидам – и тауренам, и эльфам." }, { 7.27, "Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами." }, { 17.27, "Теперь, когда ты знаешь путь друида-медведя, я научу тебя заклинанию, которое позволит тебе переноситься в Лунную поляну." }, { 28.88, "Пользуйся им всегда, когда тебе нужно знание или уединение Лунной поляны." }, { 36.56, "Вот первый урок – отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид." } } }, t = { d = 27.0, v = "nightelf-male#54", n = { x = 83 }, c = { x = { { 0.00, "Да будет так, отец Кенарий. Да будет так." }, { 3.49, "Дендрит делает быстрый незаметный жест в воздухе у себя над головой. Его окутывает тонкая аура силы." }, { 10.88, "Первое обличье, которое тебе следует освоить, – это обличье медведя." }, { 15.43, "Я направлю тебя на путь понимания этого аспекта бытия друида, но уж усвоить знания и усовершенствоваться на этом пути – это твоя забота! И так отныне будет всегда." } } } } },
    [5923] = { d = 29.2, v = "nightelf-male#54", n = { x = 345 }, c = { x = { { 0.00, "Не уделишь мне минутку внимания?.." }, { 2.70, "Дошло до меня, что Матренгил Медвежья Лапа желает побеседовать с тобой." }, { 7.63, "Сдаётся, твоё друидическое обучение выходит на следующую ступень, и он лично берётся тебя обучать." }, { 14.38, "Матренгил непосредственный помощник самого верховного друида, он один из самых мудрых и благородных друидов Тельдрассила." }, { 22.92, "Он живёт в анклаве Кенария в Дарнассе, на втором уровне дерева Фэндрала Оленьего Шлема." } } }, t = { d = 29.7, g = 1, v = "nightelf-male#59", n = { m = 334, f = 338 }, c = { m = { { 0.00, "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир." }, { 6.18, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 13.71, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 19.31, "Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя." }, { 25.37, "Так ты познаешь, что такое сила тела и духа. Готовься!" } }, f = { { 0.00, "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир." }, { 6.57, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 14.10, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 19.70, "Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя." }, { 25.72, "Так ты познаешь, что такое сила тела и духа. Готовься!" } } } } },
    [5924] = { d = 30.4, v = "nightelf-male#59", n = { x = 358 }, c = { x = { { 0.00, "Не уделишь мне минутку внимания?.." }, { 2.41, "До моего сведения дошло, что Матренгил Медвежья Лапа желает пообщаться с вами." }, { 7.80, "Похоже, ваше обучение искусству друида переходит на новую ступень, и он лично будет учить вас." }, { 14.27, "Матренгил – правая рука самого верховного друида и один из самых мудрых и благородных друидов, каких только можно встретить в Тельдрассиле." }, { 24.08, "Он обитает в анклаве Кенария в Дарнассе, на втором ярусе дерева Фэндрала Оленьего Шлема." } } }, t = { d = 29.7, g = 1, v = "nightelf-male#59", n = { m = 334, f = 338 }, c = { m = { { 0.00, "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир." }, { 6.18, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 13.71, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 19.31, "Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя." }, { 25.37, "Так ты познаешь, что такое сила тела и духа. Готовься!" } }, f = { { 0.00, "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир." }, { 6.57, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 14.10, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 19.70, "Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя." }, { 25.72, "Так ты познаешь, что такое сила тела и духа. Готовься!" } } } } },
