    [5927] = { d = 29.3, g = 1, v = "orc-female#124", n = { m = 320, f = 323 }, c = { m = { { 0.00, "Извини, друг…" }, { 1.50, "Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида." }, { 10.83, "Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида." }, { 16.86, "Он известен как мудрый и терпеливый наставник. Ты у него многому научишься." }, { 22.72, "Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." } }, f = { { 0.00, "Извини, подруга…" }, { 1.78, "Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида." }, { 11.11, "Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида." }, { 17.13, "Он известен как мудрый и терпеливый наставник. Ты у него многому научишься." }, { 23.00, "Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." } } }, t = { d = 41.1, g = 1, v = "tauren-male#67", n = { m = 334, f = 338 }, c = { m = { { 0.00, "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир." }, { 8.82, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 18.74, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 26.57, "Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя." }, { 35.44, "Так ты познаешь, что такое сила тела и духа. Готовься!" } }, f = { { 0.00, "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир." }, { 9.17, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 19.08, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 26.92, "Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству