    [5928] = { d = 34.3, v = "tauren-female#71", n = { x = 327 }, c = { x = { { 0.00, "Прости меня, друг мой…" }, { 2.10, "Мне стало известно, что Тюрак Рунический Тотэм желает поговорить с тобой. Похоже, что тебе предстоит продолжать обучение на друида." }, { 14.31, "Тюрак собирается обучать тебя лично! А ведь он – один из помощников верховного друида." }, { 21.14, "Он известен как мудрый и терпеливый наставник. Ты у него многому научишься." }, { 27.51, "Ты найдёшь его в Громовом Утёсе, в главном шатре Круга Кенария на Вершине Старейшин." } } }, t = { d = 41.1, g = 1, v = "tauren-male#67", n = { m = 334, f = 338 }, c = { m = { { 0.00, "Я рад, что ты нашёл сюда дорогу, юный друид. Пришло тебе время вступить в большой мир." }, { 8.82, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 18.74, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 26.57, "Чтобы сделать первый шаг в этот мир, ты должен обучиться искусству превращения в медведя." }, { 35.44, "Так ты познаешь, что такое сила тела и духа. Готовься!" } }, f = { { 0.00, "Я рад, что ты нашла сюда дорогу, юная дева-друид. Пришло тебе время вступить в большой мир." }, { 9.17, "В сердце каждого из детей Кенария звучит зов природы. Животные и растения – наши друзья и наша забота." }, { 19.08, "Мы сознательно посвящаем наши жизни сохранению равновесия ради их и нашего блага." }, { 26.92, "Чтобы сделать первый шаг в этот мир, ты должна обучиться искусству превращения в медведя." }, { 35.38, "Так ты познаешь, что такое сила тела и духа. Готовься!" } } } } },
    [5929] = { d = 37.5, g = 1, v = "nightelf-male#54", n = { m = 446, f = 447 }, c = { m = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя." }, { 8.25, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 15.69, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 22.29, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 28.85, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоил его уроки." } }, f = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя." }, { 8.25, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 15.69, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 22.29, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 28.85, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоила его уроки." } } }, t = { d = 26.9, v = "nightelf-male#54", n = { x = 311 }, c = { x = { { 0.00, "Дендрит делает ещё один неприметный жест над головой при вашем приближении." }, { 4.89, "Его снова окутывает аура силы, и он еле заметно улыбается." }, { 9.34, "\"Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи." }, { 14.41, "Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное." }, { 20.38, "Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя.\"" } } } } },
    [5930] = { d = 37.5, g = 1, v = "nightelf-male#54", n = { m = 446, f = 447 }, c = { m = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя." }, { 8.25, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 15.69, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 22.29, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 28.85, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоил его уроки." } }, f = { { 0.00, "В северо-западной части Лунной поляны обитает мудрое и благородное существо, которые мы называем духом Великого Медведя." }, { 8.25, "Для всех друидов он является наставником и учителем, который даёт начала понимания истинной природы медведя." }, { 15.69, "Всем друидам в определённый момент требуется мудрость этого существа, и ты не исключение." }, { 22.29, "Отправляйся же прямо сейчас к духу Великого Медведя и познай всё, чему он захочет тебя научить." }, { 28.85, "Когда он будет доволен тобой, возвращайся ко мне в Ночную Гавань. Тогда и посмотрим, действительно ли ты усвоила его уроки." } } }, t = { d = 26.9, v = "nightelf-male#54", n = { x = 311 }, c = { x = { { 0.00, "Дендрит делает ещё один неприметный жест над головой при вашем приближении." }, { 4.89, "Его снова окутывает аура силы, и он еле заметно улыбается." }, { 9.34, "Я чую мудрость в тебе, дитя, которой не было во время нашей первой встречи." }, { 14.41, "Во взгляде твоём сила и осознанное стремление, хотя ещё и не столь оформленное." }, { 20.38, "Ныне ты научишься сосредотачивать свою силу и привлекать к твоим трудам сущность медведя." } } } } },
    [5931] = { d = 32.8, v = "nightelf-male#54", n = { x = 347 }, c = { x = { { 0.00, "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне." }, { 8.81, "Матренгил Медвежья Лапа живёт в истинном равновесии с природой, хотя и обитает опасно близко к тому месту, где это равновесие пошатнулось." }, { 20.70, "Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия." }, { 30.14, "Ступай же, дитя. Мы ещё встретимся." } } }, t = { d = 30.8, v = "nightelf-male#59", n = { x = 361 }, c = { x = { { 0.00, "С возвращением. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя..." }, { 11.35, "немного сбивает с толку, но впечатляет. То же было и со мной." }, { 15.96, "Дух Великого Медведя был частью Азерота с самого его возникновения." }, { 20.56, "Мы полагаемся на его мудрость и могущество в достижении наших целей." }, { 25.17, "Теперь пришла пора тебе пройти первое своё испытание на этом пути. Слушай же..." } } } } },
    [5932] = { d = 27.8, v = "nightelf-male#54", n = { x = 316 }, c = { x = { { 0.00, "Пришла пора нашим дорогам разойтись, дитя моё, ибо для продолжения обучения тебе надо вернуться к тому, кто прислал тебя ко мне." }, { 8.81, "Хотя таурены недавно вступили на путь Кенария, Тюрак Рунический Тотэм живёт в равновесии с природой." }, { 15.64, "Слушай его наставления, и скоро ты окончательно усвоишь свои первые уроки, определяющие твою роль защитника равновесия." }, { 25.07, "Ступай же, дитя. Мы ещё встретимся." } } }, t = { d = 49.6, v = "tauren-male#67", n = { x = 381 }, c = { x = { { 0.00, "С возвращением. Я чувствую, что твоя первая встреча с духом Великого Медведя сказалась на тебе так же, как и на прочих друидах, когда они впервые ступают на путь медведя..." }, { 19.72, "немного сбивает с толку, но впечатляет. То же было и со мной." }, { 26.06, "Дух Великого Медведя был частью Азерота с самого его возникновения." }, { 32.74, "Мы, Таурены, внимательно прослушиваемся его мудрости и могуществу в достижении наших целей." }, { 41.67, "Теперь пришла пора тебе пройти первое своё испытание на этом пути. Слушай же..." } } } } },
    [6001] = { d = 33.0, g = 1, v = "nightelf-male#59", n = { m = 391, f = 393 }, c = { m = { { 0.00, "Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха." }, { 8.73, "Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария." }, { 15.92, "Лунокоготь таит в себе силу, которой ты, как один из друидов-медведей, должен овладеть." }, { 22.21, "Ты заслужил право пользоваться этой лунной пылью Кенария..." }, { 26.20, "теперь покажи мне, что также заслужил право обладать силами тела и духа, необходимыми друиду!" } }, f = { { 0.00, "Прямо к востоку от Аубердина находятся пещеры лунных совухов. В той, что ближе всего к Аубердину, находится камень лунного совуха." }, { 8.73, "Лунокоготь, страж камня, появится перед тобой только тогда, когда ты воспользуешься лунной пылью Кенария." }, { 15.92, "Лунокоготь таит в себе силу, которой ты, как одна из друидов-медведей, должен овладеть." }, { 22.08, "Ты заслужила право пользоваться этой лунной пылью Кенария..." }, { 26.22, "теперь покажи мне, что также заслужила право обладать силами тела и духа, необходимыми друиду!" } } }, t = { d = 17.1, g = 1, v = "nightelf-male#59", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 3.82, "Я чую учение Духа Великого Медведя в тебе и вижу, что ты перенял мощь Лунокогтя." }, { 9.84, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } }, f = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 3.82, "Я чую учение Духа Великого Медведя в тебе и вижу, что ты переняла мощь Лунокогтя." }, { 9.73, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } } } } },
    [6002] = { d = 50.0, g = 1, v = "tauren-male#67", n = { m = 405, f = 407 }, c = { m = { { 0.00, "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха." }, { 9.70, "Лунные совухи – звери особые, в здешних краях они не живут." }, { 15.35, "Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария." }, { 25.01, "Лунокоготь таит в себе силу, который ты должен овладеть, как один из друидов-медведей." }, { 33.67, "Ты заслужил право пользоваться этой лунной пылью Кенария..." }, { 39.23, "теперь покажи мне, что также заслужил право обладать силой тела и духа, необходимыми друиду!" } }, f = { { 0.00, "Прямо к западу от Таурахо в Степях – там, где они переходят в Мулгор – находится камень Лунного совуха." }, { 9.70, "Лунные совухи – звери особые, в здешних краях они не живут." }, { 15.35, "Лунокоготь, страж камня, появится перед тобой только когда ты воспользуешься лунной пылью Кенария." }, { 25.01, "Лунокоготь таит в себе силу, который ты должна овладеть, как одна из друидов-медведей." }, { 33.84, "Ты заслужила право пользоваться этой лунной пылью Кенария..." }, { 39.58, "теперь покажи мне, что также заслужила право обладать силой тела и духа, необходимыми друиду!" } } }, t = { d = 24.6, g = 1, v = "tauren-male#67", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 5.68, "Я чую учение Духа Великого Медведя в тебе, и вижу, что ты перенял мощь Лунокогтя." }, { 14.58, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } }, f = { { 0.00, "Это твой первый большой шаг на пути к великим свершениям." }, { 5.68, "Я чую учение Духа Великого Медведя в тебе, и вижу, что ты переняла мощь Лунокогтя." }, { 13.96, "Более ничего не препятствует тебе... позволь же ныне поведать тебе, что значит быть друидом-медведем!" } } } } },
    [6061] = { d = 36.2, v = "tauren-male", n = { x = 348 }, c = { x = { { 0.00, "Для нас, тауренов, важно следовать традициям предков, сражаясь с могучими зверями." }, { 7.08, "Одолевая их, мы вбираем в себя их дух, делаясь всё ближе Матери-Земле." }, { 13.51, "Приручив же зверя и сделав его своим помощником, мы делаем ещё один шаг навстречу природе." }, { 21.34, "В конце концов ты сможешь выбрать зверя себе по вкусу. Но сначала всему приходится учиться, и этому тоже." }, { 29.62, "Для начала возьми этот хлыст приручения; ступай, приручи равнинного долгонога." } } }, t = { d = 6.3, g = 1, v = "tauren-male", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Я уже знаю, мать-земля сказала мне, что ты справился со своей задачей." } }, f = { { 0.00, "Я уже знаю, мать-земля сказала мне, что ты справилась со своей задачей." } } } } },
    [6062] = { d = 32.9, g = 1, v = "orc-male", n = { m = 370, f = 371 }, c = { m = { { 0.00, "Умение подчинять природу своей воле – великое искусство." }, { 4.03, "Ты охотник, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу." }, { 11.94, "Обрести власть над животным – дело не простое, тут требуется решимость." }, { 17.34, "Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря." }, { 23.86, "Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне." } }, f = { { 0.00, "Умение подчинять природу своей воле – великое искусство." }, { 4.03, "Ты охотница, и тебе следует научиться использовать силу и мощь, свойственную любому избранному тобой существу." }, { 12.23, "Обрести власть над животным – дело не простое, тут требуется решимость." }, { 17.63, "Для начала возьми вот этот хлыст приручения и укроти с его помощью лютого пятнистого вепря." }, { 24.15, "Они водятся поблизости от Колючего Холма. Попробуй поучаствовать в битве вместе с вепрем, а потом возвращайся ко мне." } } }, t = { d = 4.6, v = "orc-male", n = { x = 47 }, c = { x = { { 0.00, "Молодец! Думаю, тебе уже можно поручить задачу посложнее..." } } } } },
    [6063] = { d = 34.7, g = 1, v = "nightelf-male#54", n = { m = 411, f = 411 }, c = { m = { { 0.00, "Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям." }, { 8.97, "Её следует почитать как нечто, без чего само твоё существование было бы невозможным." }, { 14.99, "Ты должен доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника." }, { 23.87, "Первым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенётника." }, { 30.64, "Приручи его и поупражняйся в своём охотничьем искусстве." } }, f = { { 0.00, "Охотнику важно помнить о том, какая перед ним стоит ответственность. Природа – не та сила, которую можно подчинить своим прихотям." }, { 8.97, "Её следует почитать как нечто, без чего само твоё существование было бы невозможным." }, { 14.99, "Ты должна доказать, что понимаешь это, прежде чем получишь способность превращать любое животное в своего верного спутника." }, { 23.80, "Первым делом возьми этот хлыст приручения. С его помощью ты сумеешь приручить чащобного тенётника." }, { 30.57, "Приручи его и поупражняйся в своём охотничьем искусстве." } } }, t = { d = 3.4, g = 1, v = "nightelf-male#54", n = { m = 36, f = 37 }, c = { m = { { 0.00, "Превосходно! Ты довольно способный ученик." } }, f = { { 0.00, "Превосходно! Ты довольно способная ученица." } } } } },
    [6064] = { d = 32.8, g = 1, v = "dwarf-male", n = { m = 380, f = 381 }, c = { m = { { 0.00, "Привет, парень! Стало быть, хочешь узнать, как завести себе питомца?" }, { 5.07, "Что же, начнём. Когда доходит до охоты, нет ничего важнее снаряжения, но о моём новом шрапнельном самостреле мы поболтаем в другой раз." }, { 14.30, "А пока займёмся тем, что, так интересует тебя в данный момент – питомцем!" }, { 19.47, "Тебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу." }, { 26.16, "Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его." } }, f = { { 0.00, "Привет, подруга! Стало быть, хочешь узнать, как завести себе питомца?" }, { 4.97, "Что же, начнём. Когда доходит до охоты, нет ничего важнее снаряжения, но о моём новом шрапнельном самостреле мы поболтаем в другой раз." }, { 14.20, "А пока займёмся тем, что, так интересует тебя в данный момент – питомцем!" }, { 19.36, "Тебе лучше всего попытаться приручить нескольких существ и посмотреть, кто тебе больше по сердцу." }, { 26.06, "Итак, найди большого скального вепря, а затем используй хлыст приручения, чтобы приручить его." } } }, t = { d = 3.9, v = "dwarf-male", n = { x = 33 }, c = { x = { { 0.00, "Я знаю, знаю, ты думаешь – ну а дальше то что, а?" } } } } },
