    [6081] = { d = 21.7, v = "orc-male", n = { x = 244 }, c = { x = { { 0.00, "Теперь ты умеешь приручать зверей, но тебе ещё осталось узнать, как их обучать." }, { 5.91, "Ступай в Оргриммар. Там тебе нужно будет поговорить с одним из самых прославленных наших охотников, Ормаком Лютострелом." }, { 14.44, "Он покажет тебе, как обучать своего нового питомца. Ты найдёшь Ормака возле Зала Отважных. Удачи!" } } }, t = { d = 22.2, g = 1, v = "orc-male#60", n = { m = 242, f = 243 }, c = { m = { { 0.00, "А, молодой охотник! Да, я поделюсь с тобой навыками и знаниями, необходимыми для того, чтобы обучать и дрессировать питомца." }, { 9.32, "Ты сможешь не только обучать своего питомца новым способностям, но также научишься кормить его и даже оживлять, если он погибнет в бою." }, { 19.09, "А теперь ступай. Мы поговорим позднее." } }, f = { { 0.00, "А, молодая охотница! Да, я поделюсь с тобой навыками и знаниями, необходимыми для того, чтобы обучать и дрессировать питомца." }, { 8.72, "Ты сможешь не только обучать своего питомца новым способностям, но также научишься кормить его и даже оживлять, если он погибнет в бою." }, { 18.49, "А теперь ступай. Мы поговорим позднее." } } } } },
    [6082] = { d = 31.6, g = 1, v = "orc-male", n = { m = 361, f = 361 }, c = { m = { { 0.00, "Последнее животное, которое тебе придётся приручить, – это бронескорп. Тебе придётся частенько с ними сражаться." }, { 7.76, "Но ты, будучи охотником, должен уметь повелевать и такими существами." }, { 13.02, "Когда ты вернёшься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору." }, { 20.01, "Выбранный тобой зверь будет набираться опыта и становиться сильнее." }, { 24.82, "А ещё я покажу тебе, как призывать его и отпускать на волю, когда в нём не будет надобности." } }, f = { { 0.00, "Последнее животное, которое тебе придётся приручить, – это бронескорп. Тебе придётся частенько с ними сражаться." }, { 7.76, "Но ты, будучи охотницей, должна уметь повелевать и такими существами." }, { 12.91, "Когда ты вернёшься, я обучу тебя всему, что потребуется, чтобы приручить животное по твоему выбору." }, { 19.91, "Выбранный тобой зверь будет набираться опыта и становиться сильнее." }, { 24.72, "А ещё я покажу тебе, как призывать его и отпускать на волю, когда в нём не будет надобности." } } }, t = { d = 21.4, g = 1, v = "orc-male", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Теперь, ты знаешь всё, чему я мог тебя обучить. Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца." }, { 9.68, "Вот, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле." }, { 16.61, "Можешь гордиться своим новым умением, ты заслужил эти знания!" } }, f = { { 0.00, "Теперь, ты знаешь всё, чему я мог тебя обучить. Пора тебе воспользоваться полученными знаниями и выбрать себе собственного питомца." }, { 9.68, "Вот, я даю тебе способность приручать зверя, а также призывать и отсылать его по собственной воле." }, { 16.61, "Можешь гордиться своим новым умением, ты заслужила эти знания!" } } } } },
    [6083] = { d = 31.0, v = "orc-male", n = { x = 354 }, c = { x = { { 0.00, "Разумеется, питомец даёт тебе большое преимущество в бою. Подчиняя себе живое существо, ты добавляешь его силу к своей." }, { 8.42, "Он становится как бы продолжением тебя." }, { 11.64, "Следующее задание потребует от тебя обратиться от земли к морю." }, { 16.29, "Приливный краб, которого тебе нужно будет приручить, обитает в прибрежных водах, близ деревни Сен'джин и островов Эха." }, { 24.53, "Воспользуйся хлыстом приручения, чтобы усмирить зверя, а потом потренируй свои навыки." } } }, t = { d = 2.5, v = "orc-male", n = { x = 22 }, c = { x = { { 0.00, "Ты быстро учишься! Молодец." } } } } },
    [6084] = { d = 31.1, v = "dwarf-male", n = { x = 352 }, c = { x = { { 0.00, "Эти скальные вепри такие здоровенные – может, тебе хочется кого поизящнее? Ладушки, у меня есть кое-кто на примете." }, { 7.82, "К югу и востоку отсюда ты найдёшь больших белых кошек, называемых снежными леопардами." }, { 13.79, "Они чем-то напоминают элегантную винтовку – такие же красивые и такие же смертоносные." }, { 20.30, "Они гораздо проворнее и быстрее укрощённого тобой вепря." }, { 24.92, "На, держи этот хлыст приручения. Посмотрим, придётся ли тебе по душе снежный леопард." } } }, t = { d = 8.4, g = 1, v = "dwarf-male", n = { m = 96, f = 96 }, c = { m = { { 0.00, "Когда я почувствую, что ты всё изучил, я дам тебе способность самому выбирать себе любого зверя, которого ты захочешь." } }, f = { { 0.00, "Когда я почувствую, что ты всё изучила, я дам тебе способность самой выбирать себе любого зверя, которого ты захочешь." } } } } },
    [6085] = { d = 34.4, v = "dwarf-male", n = { x = 405 }, c = { x = { { 0.00, "Возможно, тебе понравится животное, обладающее чем-то большим, чем просто грубая сила." }, { 5.85, "Медведи-ледолапы – замечательные спутники для охотников-новичков, вроде тебя. Их можно найти к востоку от Караноса." }, { 13.75, "Вот тебе хлыст приручения, попытайся приручить это животное и посмотри, как он тебе придётся!" }, { 20.61, "Когда ты вернёшься, я научу тебя, как приручать животных. Твой питомец будет вместе с тобой разделять опасности и получать опыт." }, { 29.27, "Я также научу тебя призывать и отпускать животное по своему желанию." } } }, t = { d = 13.7, v = "dwarf-male", n = { x = 147 }, c = { x = { { 0.00, "Вот и ты. Теперь я дам тебе навыки, позволяющие приручать, звать и прогонять любимца. Используй их на своё усмотрение." }, { 9.22, "Найди себе хорошего, лояльного спутника, и наслаждайся охотой!" } } } } },
    [6086] = { d = 27.1, g = 1, v = "dwarf-male", n = { m = 309, f = 310 }, c = { m = { { 0.00, "Ты умеешь приручать зверей, но ведь надо ещё научиться тренировать своего питомца." }, { 6.12, "Иди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специлистов в обучении зверей – Белией Громовым Гранитом." }, { 14.81, "Она покажет тебе, как обучать питомца. Так что отправляйся в путь, парень!" }, { 20.14, "Белия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи." } }, f = { { 0.00, "Ты умеешь приручать зверей, но ведь надо ещё научиться тренировать своего питомца." }, { 6.12, "Иди в Палаты Войны в Стальгорне и поговори там с одним из наших лучших специлистов в обучении зверей – Белией Громовым Гранитом." }, { 14.81, "Она покажет тебе, как обучать питомца. Так что отправляйся в путь, подруга!" }, { 20.35, "Белия по характеру дружелюбна, у тебя не будет проблем в нахождении с ней общего языка. Удачи." } } }, t = { d = 13.4, v = "dwarf-female#34", n = { x = 154 }, c = { x = { { 0.00, "Новый рекрут? В своё время ты станешь неплохим охотником, да-да." }, { 4.58, "Я могу тебя научить тому, что ты хочешь. Животных приручать? Да всё, что угодно." }, { 9.76, "Но за всё это придётся заплатить звонкой монетой." } } } } },
    [6087] = { d = 38.3, v = "tauren-male", n = { x = 363 }, c = { x = { { 0.00, "Твой дух полон огня, охотник, и ты с радостью встречаешь новые испытания." }, { 7.16, "Следующее задание – приручить волка, известного как охотник прерий." }, { 12.34, "Он быстр и бесстрашен, и чтобы сделать его своим спутником, тебе придётся воспитать в себе эти качества." }, { 20.96, "Во время боя ты поймёшь, как вы будете сражаться бок о бок." }, { 25.76, "Ведь вы с питомцем должны действовать очень слаженно, как единый организм." }, { 31.85, "Вот хлыст приручения. Подчини себе охотника прерий, потренируйся." } } }, t = { d = 5.0, g = 1, v = "tauren-male", n = { m = 42, f = 43 }, c = { m = { { 0.00, "Да... Мать-Земля верит, что ты готов к следующему уроку." } }, f = { { 0.00, "Да... Мать-Земля верит, что ты готова к следующему уроку." } } } } },
    [6088] = { d = 40.6, v = "tauren-male", n = { x = 370 }, c = { x = { { 0.00, "Последним твоим заданием станет приручение жителя неба." }, { 4.42, "Перепелятник – непростой противник, но зато отличный союзник – атакует он внезапно и пугает врагов." }, { 13.85, "По воле Матери-Земли, по возвращении с победой, я наделю тебя искусством приручать любого зверя и делать его своим спутником; твоему питомцу придётся встретиться с теми же испытаниями, что и тебе, и вместе с тобой набираться опыта." }, { 35.19, "Я покажу тебе, как подзывать и отсылать его по собственной воле." } } }, t = { d = 24.6, g = 1, v = "tauren-male", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Ты изучил всё, чему я могу тебя научить. Пусть благословения Матери-Земли направляют тебя при выборе своего любимца." }, { 9.59, "Вот. Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтёшь нужным." }, { 19.10, "Используй свои новые способности с гордостью и уважай Мать-Землю." } }, f = { { 0.00, "Ты изучила всё, чему я могу тебя научить. Пусть благословения Матери-Земли направляют тебя при выборе своего любимца." }, { 9.39, "Вот. Теперь я дам тебе силу приручать животных, а также отпускать их на волю, когда ты сочтёшь нужным." }, { 18.90, "Используй свои новые способности с гордостью и уважай Мать-Землю." } } } } },
    [6089] = { d = 40.2, v = "tauren-male", n = { x = 387 }, c = { x = { { 0.00, "Теперь ты знаешь, как приручать питомца, но тебе надо научиться ещё и обучать его." }, { 6.81, "Отправляйся в Громовой Утёс. Там тебе нужно будет поговорить с одним из наших самых уважаемых охотников, Хольтом Громовым Рогом." }, { 19.54, "Если он сочтёт тебя достойным знаний, то объяснит тебе, как обучать твоего нового питомца." }, { 27.01, "Хольт одолел многих могущественных и страшных зверей Азерота и сам повелевает сильными существами." }, { 34.63, "Его связь с Матерью-Землёй сильна, и он многому может научить. Удачи." } } }, t = { d = 22.7, g = 1, v = "tauren-male#68", n = { x = 208 }, c = { m = { { 0.00, "А, юный герой. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца." }, { 8.40, "Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падёт в бою." }, { 17.84, "Ступай, Мать-Земля ещё сведёт наши пути. Поговорим позже." } }, f = { { 0.00, "А, юный героиня. Да, я могу наделить тебя знаниями, как обучать и направлять твоего питомца." }, { 7.65, "Ты не только сможешь научить его новым способностям, но также сможешь кормить его и даже оживлять, если он падёт в бою." }, { 17.08, "Ступай, Мать-Земля ещё сведёт наши пути. Поговорим позже." } } } } },
    [6101] = { d = 34.2, v = "nightelf-male#54", n = { x = 405 }, c = { x = { { 0.00, "Природа изменчива, но на неё вполне можно положиться." }, { 3.69, "Она предсказуема в том, что никогда не остаётся одной и той же, она всегда меняется." }, { 9.82, "Поручения, которые я тебе дам, помогут тебе увидеть и оценить различных существ, которые впоследствии смогут стать твоими спутниками." }, { 19.22, "Возьми этот хлыст приручения и приручи ночного саблезуба-охотника, которого ты найдёшь к югу отсюда." }, { 26.13, "Поупражняйся в своём охотничьем искусстве. Таким образом ты начнёшь понимать сходства и различия творений природы." } } }, t = { d = 4.6, v = "nightelf-male#54", n = { x = 53 }, c = { x = { { 0.00, "Вижу в тебе обязательность и понимание всего, чему я научил тебя." } } } } },
    [6102] = { d = 39.5, v = "nightelf-male#54", n = { x = 450 }, c = { x = { { 0.00, "Тебе удалось приручить двух детей земли, и теперь тебе предстоит подружиться с обитателем неба." }, { 6.44, "При помощи этого хлыста приручи совиного визгуна, которую найдёшь к западу отсюда." }, { 12.52, "Испытай своё искусство, взяв в спутники эту могучую сову." }, { 16.89, "Когда вернёшься, я наделю тебя знаниями, которые понадобятся тебе для приручения любого животного, которого ты выберешь себе в спутники." }, { 26.23, "Твой спутник встретит лицом к лицу те же опасности, что и ты, и вместе с тобой будет набираться опыта." }, { 33.18, "Я также научу тебя, как призывать и отпускать по желанию твоего питомца." } } }, t = { d = 32.6, g = 1, v = "nightelf-male#54", n = { m = 367, f = 368 }, c = { m = { { 0.00, "Теперь ты знаешь всё, чему я мог тебя обучить. Могу ли дать тебе ещё один совет?" }, { 5.44, "Хорошенько подумай прежде, чем выбрать первого питомца." }, { 9.20, "Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса?" }, { 14.63, "Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе." }, { 20.47, "Что же. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно." }, { 28.14, "Гордись своими новыми умениями – ты их честно заслужил." } }, f = { { 0.00, "Теперь ты знаешь всё, чему я мог тебя обучить. Могу ли дать тебе ещё один совет?" }, { 5.44, "Хорошенько подумай прежде, чем выбрать первого питомца." }, { 9.20, "Будет ли это существо, что ходит по земле, плавает в воде или рассекает небеса?" }, { 14.63, "Кем бы оно ни было, твой питомец, вне всякого сомнения, долго пробудет при тебе." }, { 20.47, "Что же. Ныне я дам тебе умение приручать животное, а так же призывать и отпускать его, когда тебе будет нужно." }, { 28.14, "Гордись своими новыми умениями – ты их честно заслужила." } } } } },
    [6103] = { d = 30.8, v = "nightelf-male#54", n = { x = 341 }, c = { x = { { 0.00, "Теперь ты знаешь, как приручать питомца, но тебе надо научиться ещё и обучать его." }, { 6.11, "Отправляйся в Дарнасс. Там тебе нужно будет поговорить с одной из наших самых уважаемых охотниц, Иокастой." }, { 14.05, "Она объяснит тебе, как обучать твоего нового питомца, так что поторопись." }, { 19.47, "Хотя Иокаста и сурова, ей всегда приятно наблюдать за развитием способностей очередного охотника." }, { 26.80, "Держись с ней почтительно, и она воздаст добром. Удачи." } } }, t = { d = 22.8, g = 1, v = "nightelf-female#52", n = { x = 267 }, c = { m = { { 0.00, "Новоиспечённый герой?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем." }, { 7.40, "Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке." }, { 16.43, "Запомни: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже ещё поговорим." } }, f = { { 0.00, "Новоиспечённый героиня?. Что же, я могу дать тебе знания, необходимые для обучения и управления твоим питомцем." }, { 7.24, "Ты сможешь обучать своего питомца не только новым способностям, но научишься его кормить и возрождать, если он погибнет в схватке." }, { 16.27, "Запомни: всегда уважай равновесие и почитай природу. Теперь ступай. Попозже ещё поговорим." } } } } },
    [6121] = { d = 29.7, g = 1, v = "nightelf-male#59", n = { m = 349, f = 350 }, c = { m = { { 0.00, "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 5.80, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 12.52, "Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 21.67, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } }, f = { { 0.00, "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 5.91, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 12.62, "Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 21.77, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } } }, t = { d = 25.1, g = 1, v = "nightelf-male#54", n = { m = 261, f = 261 }, c = { m = { { 0.00, "Привет тебе друид, я вижу ты готов получить знания излечения ядов." }, { 5.32, "Видишь ли, мы столкнулись с определёнными трудностями около Аубердина в Тёмных берегах, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы." }, { 17.75, "Мы запросили Лунную Поляну о помощи... и надеюсь, ты, тот, кого мы ждали!" } }, f = { { 0.00, "Привет тебе друид, я вижу ты готова получить знания излечения ядов." }, { 6.21, "Видишь ли, мы столкнулись с определёнными трудностями около Аубердина в Тёмных берегах, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы." }, { 19.91, "Мы запросили Лунную Поляну о помощи... и надеюсь, ты, та, кого мы ждали!" } } } } },
    [6122] = { d = 33.7, v = "nightelf-male#54", n = { x = 391 }, c = { x = { { 0.00, "Водопад Скалистый на Тёмном Берегу – основной источник питьевой воды для всего региона, но теперь я подозреваю, что именно оттуда распространяется отрава, поражающей местную фауну – особенно оленей." }, { 13.40, "Возьми эту пробирку, чтобы отобрать немного воды из устья пещеры. Осторожнее – в пещере у водопада ныне поселилась опасная нага." }, { 23.30, "Как только наберёшь воды, доставь её Аландариан Песне Ночи в Аубердин." }, { 28.18, "Именно она просила нашей помощи, и ты поможешь ей разобраться с этой заразой." } } }, t = { d = 22.1, g = 1, v = "nightelf-female#53", n = { m = 247, f = 249 }, c = { m = { { 0.00, "Во имя Элуны, эта вода просто отвратительна! Не удивительно, что олени больны." }, { 5.68, "Что-то загрязняет эту воду, а она загрязняет все источники в Тёмных берегах! Река? Нет, не думаю…" }, { 12.67, "Что-ж эта вода, что ты принёс, поможет нам сделать лекарство!" }, { 16.82, "И пока я работаю над ним – ты поможешь мне достать необходимые компоненты." } }, f = { { 0.00, "Во имя Элуны, эта вода просто отвратительна! Не удивительно, что олени больны." }, { 5.68, "Что-то загрязняет эту воду, а она загрязняет все источники в Тёмных берегах! Река? Нет, не думаю…" }, { 12.67, "Что-ж эта вода, что ты принесла, поможет нам сделать лекарство!" }, { 17.04, "И пока я работаю над ним – ты поможешь мне достать необходимые компоненты." } } } } },
    [6123] = { d = 33.0, g = 1, v = "nightelf-female#53", n = { m = 387, f = 388 }, c = { m = { { 0.00, "Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится землекорень." }, { 7.93, "Травники знают, где его искать, так что, если нам не повезло и вы не травник, придётся найти кого-то, кто сможет помочь." }, { 16.38, "Для усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно." }, { 24.97, "В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны." } }, f = { { 0.00, "Основой целительной мази для оленей послужит вода. Для придания ей целительных свойств мне понадобится землекорень." }, { 7.93, "Травники знают, где его искать, так что, если нам не повезло и вы не травница, придётся найти кого-то, кто сможет помочь." }, { 16.39, "Для усиления воздействия мне нужны лунные грибы. Найти их довольно легко: в пещерах, прямо на восток отсюда, их полным-полно." }, { 24.98, "В этих пещерах обитают лунные совухи; в последнее время они стали очень раздражительны, так что будьте осторожны." } } }, t = { d = 31.6, v = "nightelf-female#53", n = { x = 375 }, c = { x = { { 0.00, "Отлично, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось." }, { 8.75, "Изготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия." }, { 18.98, "Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!" }, { 28.25, "А теперь позвольте мне приступить к работе!" } } } } },
    [6124] = { d = 37.3, v = "nightelf-female#53", n = { x = 431 }, c = { x = { { 0.00, "Мази, изготовленной из реактивов, которые вы принесли мне, хватит на десять доз." }, { 5.51, "Пока я работаю здесь, в деревне, пытаясь изготовить побольше этой мази, я хотел бы, чтобы вы помогли нам начать исцеление." }, { 13.78, "По всему Тёмному Берегу встречаются больные олени. Используйте мазь для исцеления их недуга." }, { 20.51, "Я уверен, что Дендрит Звёздная Вспышка из Лунной Поляны захочет поговорить с вами, когда вы закончите." }, { 27.47, "Пожалуйста, передайте благодарность жителей Аубердина Кругу Кенария... и позвольте мне поблагодарить вас лично за вашу помощь!" } } }, t = { d = 33.5, g = 1, v = "nightelf-male#54", n = { m = 385, f = 385 }, c = { m = { { 0.00, "Вы хорошо сделали, что позаботились о больных оленях Тёмных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю." }, { 9.61, "В Дарнассе есть те, кто признаёт наличие угрозы... и те, кто упорно игнорирует её всё усиливающиеся признаки." }, { 16.95, "Я надеюсь, что вы, – один из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам." }, { 23.70, "Как бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы." } }, f = { { 0.00, "Вы хорошо сделали, что позаботились о больных оленях Тёмных берегов; это невольные жертвы порчи и осквернения, расползающихся по всему краю." }, { 9.61, "В Дарнассе есть те, кто признаёт наличие угрозы... и те, кто упорно игнорирует её всё усиливающиеся признаки." }, { 16.95, "Я надеюсь, что вы, – одна из тех, кто не собирается надевать шоры и будет смотреть в лицо фактам." }, { 23.80, "Как бы там ни было, вы доказали, что являетесь другом природы и Круга Кенария, и я прошу вас принять это в качестве знака нашей дружбы." } } } } },
    [6125] = { d = 27.2, g = 1, v = "nightelf-male#54", n = { m = 309, f = 311 }, c = { m = { { 0.00, "Ты познал, что значит исцелять от действия яда без помощи духов." }, { 4.40, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 11.95, "Тебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнасс." }, { 16.04, "Теперь, когда его ученик усвоил данный ему урок, он несомненно научит тебя новому могучему заклинанию." }, { 23.45, "До свидания, юный друид. Мы ещё встретимся." } }, f = { { 0.00, "Ты познала, что значит исцелять от действия яда без помощи духов." }, { 4.47, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 12.02, "Тебе следует вернуться к Матренгилу Медвежьей Лапе в Дарнасс." }, { 16.11, "Теперь, когда его ученица усвоила данный ей урок, он несомненно научит тебя новому могучему заклинанию." }, { 23.59, "До свидания, юный друид. Мы ещё встретимся." } } }, t = { d = 29.9, g = 1, v = "nightelf-male#59", n = { m = 346, f = 348 }, c = { m = { { 0.00, "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинул нас, и, должен признаться, был изумлён, узнав о ситуации в Аубердине." }, { 9.92, "Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие." }, { 18.18, "Ты благородно поступил в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами." }, { 27.03, "Используй её во благо... во благо." } }, f = { { 0.00, "С возвращением. Я следил за твоими успехами с тех самых пор, как ты покинула нас, и, должен признаться, был изумлён, узнав о ситуации в Аубердине." }, { 10.01, "Это требует дальнейшего расследования, ибо появление такого яда в окружающей среде чрезвычайно нарушает равновесие." }, { 18.28, "Ты благородно поступила в трудной ситуации. И я не вижу лучшего поощрения, чем даровать тебе в награду постоянную власть над ядами." }, { 27.28, "Используй её во благо... во благо." } } } } },
    [6126] = { d = 43.5, g = 1, v = "tauren-male#67", n = { m = 349, f = 351 }, c = { m = { { 0.00, "Теперь, ты готов узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 8.09, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 17.61, "Однако мы должны быть уверены, что ты усвоил этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 30.37, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } }, f = { { 0.00, "Теперь, ты готова узнать о ядах и о той власти, которой мы, друиды, над ними обладаем." }, { 8.39, "Кенарий даровал нам способность изгонять из тела даже самый мерзостный яд при помощи простых чар." }, { 17.92, "Однако мы должны быть уверены, что ты усвоила этот важный урок, посему тебе придётся испытать на себе силу действия яда в полной мере." }, { 32.35, "Отправляйся в Лунную поляну и поговори с Дендритом Блеском Звёзд – он ждёт твоего прибытия, чтобы начать обучение." } } }, t = { d = 22.3, g = 1, v = "nightelf-male#54", n = { m = 256, f = 256 }, c = { m = { { 0.00, "Привет тебе друид, я вижу ты готов получить знания излечения ядов." }, { 5.00, "Видишь ли, мы столкнулись с определёнными трудностями около Перекрёстка в Степях, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы." }, { 17.12, "Мы запросили Лунную Поляну о помощи...и надеюсь, ты, тот, кого мы ждали!" } }, f = { { 0.00, "Привет тебе друид, я вижу ты готова получить знания излечения ядов." }, { 5.17, "Видишь ли, мы столкнулись с определёнными трудностями около Перекрёстка в Степях, там распоясались животные, которые сеют своим ядом направо и налево, и нет на них никакой управы." }, { 17.38, "Мы запросили Лунную Поляну о помощи...и надеюсь, ты, та, кого мы ждали!" } } } } },
    [6127] = { d = 34.3, v = "nightelf-male#54", n = { x = 407 }, c = { x = { { 0.00, "Вершина Багрового Тумана, что к северо-западу от Перекрёстка – самый вероятный источник распространения этой отравы." }, { 7.97, "На его вершине находятся озёра воды, влияющие на перемены погоды." }, { 12.49, "Подозреваю, что вода сейчас заражена демонопоклонниками из клана Пылающего Клинка." }, { 18.50, "Возьми этот пробоотборник и набери воды из озера у самой вершины. Наполнив, доставь его Тонге Руническому Тотэму в Перекрёсток." }, { 27.29, "Именно он и просил нашей помощи, и ты будешь работать вместе с ним над искоренением этой заразы." } } }, t = { d = 29.3, v = "tauren-male", n = { x = 278 }, c = { x = { { 0.00, "Во имя отцов-основателей, эта вода просто отвратительна! Неудивительно что газели больны." }, { 7.96, "Что-то загрязняет воду и превращает в руины экосистему северных Степей. Больные газели замечены на север по дороге отсюда." }, { 18.51, "Пока мы не выявим источник заразы, у нас будет много работы здесь." }, { 24.16, "А эта вода поможет нам найти причину заразы, в этом я уверен..." } } } } },
    [6128] = { d = 37.8, g = 1, v = "tauren-male", n = { m = 354, f = 355 }, c = { m = { { 0.00, "Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится землекорень." }, { 8.79, "Травники знают, где его отыскать, так что если нам не повезло, и ты – не травник, придётся попросить кого-то о помощи." }, { 19.80, "Для силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей." }, { 28.90, "Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне." } }, f = { { 0.00, "Основой целебной мази для газелей послужит вода. Для придания ей целебных свойств мне понадобится землекорень." }, { 8.79, "Травники знают, где его отыскать, так что если нам не повезло, и ты – не травница, придётся попросить кого-то о помощи." }, { 19.94, "Для силы воздействия мне нужны рога кодо – осколки и куски не подойдут. Кодо живут в северной части Степей." }, { 29.03, "Убей несколько зверюг, заодно и природное равновесие восстановится. Отпили у них рога и принеси мне." } } }, t = { d = 35.8, v = "tauren-male", n = { x = 375 }, c = { x = { { 0.00, "Отлично, вы принесли так много, что должно хватить на несколько больших доз мази – по крайней мере чтобы исцеление началось." }, { 10.10, "Изготовление средств против ядов иногда бывает весьма сложным, поскольку каждый из них требует конкретного антидота для нейтрализации воздействия." }, { 21.31, "Здорово было бы уметь в любой момент снимать отравление, не беспокоясь о конкретных ингредиентах, которые должен содержать антидот!" }, { 32.02, "А теперь позвольте мне приступить к работе!" } } } } },
    [6129] = { d = 38.7, g = 1, v = "tauren-male", n = { m = 380, f = 382 }, c = { m = { { 0.00, "Мне удалось сделать десять доз целебной мази." }, { 3.55, "Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты помог нам лечить бедных зверей." }, { 12.48, "По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази." }, { 19.88, "Я уверен, что Дендрит Блеск Звёзд на Лунной Поляне захочет поговорить с тобой, когда ты закончишь." }, { 29.21, "Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!" } }, f = { { 0.00, "Мне удалось сделать десять доз целебной мази." }, { 3.55, "Пока я работаю здесь, в деревне, пытаясь изготовить побольше, я хотел бы, чтобы ты помогла нам лечить бедных зверей." }, { 12.63, "По всей северной части Степей бродят больные газели. Исцели их недуг при помощи этой мази." }, { 20.03, "Я уверен, что Дендрит Блеск Звёзд на Лунной Поляне захочет поговорить с тобой, когда ты закончишь." }, { 29.36, "Пожалуйста, передай нашу благодарность Кругу Кенария... и позволь мне поблагодарить тебя лично за неоценимую помощь!" } } }, t = { d = 21.0, g = 1, v = "nightelf-male#54", n = { m = 238, f = 241 }, c = { m = { { 0.00, "Ты поступил хорошо с больными газелями Степей, ведь они невинные жертвы заразы, что распростёрлась над этим и другими континентами." }, { 8.96, "Ты сделал ещё один шаг по пути Кенария. Старейшины в Громовом Утёсе будут рады услышать весть о тебе." }, { 16.35, "Ты, как наш друг и друг Круга, достоин награды. Возьми же её." } }, f = { { 0.00, "Ты поступила хорошо с больными газелями Степей, ведь они невинные жертвы заразы, что распростёрлась над этим и другими континентами." }, { 9.04, "Ты сделала ещё один шаг по пути Кенария. Старейшины в Громовом Утёсе будут рады услышать весть о тебе." }, { 16.42, "Ты, как наш друг и друг Круга, достойна награды. Возьми же её." } } } } },
    [6130] = { d = 27.9, g = 1, v = "nightelf-male#54", n = { m = 314, f = 316 }, c = { m = { { 0.00, "Ты познал, что значит исцелять от действия яда без помощи духов." }, { 4.49, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 12.17, "Тебе следует вернуться к Тюраку Руническому Тотэму в Громовой Утёс." }, { 16.75, "Теперь, когда его ученик усвоил данный ему урок, он несомненно научит тебя новому могучему заклинанию." }, { 24.13, "До свидания, юный друид. Мы ещё встретимся." } }, f = { { 0.00, "Ты познала, что значит исцелять от действия яда без помощи духов." }, { 4.50, "Помни же, что приходится претерпевать другим в борьбе против отравы, и прими свою новую власть над ядами." }, { 12.19, "Тебе следует вернуться к Тюраку Руническому Тотэму в Громовой Утёс." }, { 16.77, "Теперь, когда его ученица усвоила данный ей урок, он несомненно научит тебя новому могучему заклинанию." }, { 24.26, "До свидания, юный друид. Мы ещё встретимся." } } }, t = { d = 32.0, v = "tauren-male#67", n = { x = 268 }, c = { x = { { 0.00, "С возвращением... я следил за твоим прогрессом... но сейчас, знаешь ли, я больше обеспокоен ситуацией вокруг Перекрёстка." }, { 11.26, "Эта ситуация требует твоего вмешательства." }, { 15.86, "Но! Проявленное тобой усердие не останется без вознаграждения." }, { 21.85, "Пока же я не могу найти лучшего пути, чем вознаградить тебя властью над ядами. Используй её достойно" } } } } },
    [6181] = { d = 38.5, v = "human-male", n = { x = 443 }, c = { x = { { 0.00, "Хотя мы не получаем серьёзной помощи напрямую из Штормграда, у меня в городе есть знакомый, снабжающий нас доспехами." }, { 8.29, "Зовут его Озрик Штранг. Его магазин, \"Ограниченная неуязвимость\", находится в Старом городе." }, { 14.94, "Наши запасы доспехов заканчиваются, и я должен связаться с Озриком, чтобы попросить ещё. Можете ли вы передать ему эту записку?" }, { 24.17, "Быстрее всего добраться до Штормграда можно с помощью Тора, нашего укротителя грифонов. Он находится прямо у подножия этого холма." }, { 33.28, "Приходите к нему с моей запиской, а затем летите на грифоне в Штормград." } } }, t = { d = 7.4, v = "human-male", n = { x = 83 }, c = { x = { { 0.00, "Вам нужно доставить эту записку в Штормград? Это не проблема, вы можете взять одного из моих грифонов!" } } } } },
    [6261] = { d = 27.7, v = "human-male#116", n = { x = 321 }, c = { x = { { 0.00, "Я сложил в этот ящик всё, о чём просил Льюис. Можете отвезти ему ящик?" }, { 5.23, "С Тором в Западном Крае вы уже общались – значит, сможете нанять грифона, чтобы туда вернуться." }, { 11.51, "Наш укротитель грифонов – Дунгар Долгопив, он находится в Торговом квартале." }, { 16.96, "Поговорите с Дунгаром и доставьте этот ящик Льюису как можно скорее." }, { 21.63, "Мы не хотим, чтобы нашим воинам в Западном Крае пришлось сражаться без новых доспехов!" } } }, t = { d = 11.7, v = "human-male", n = { x = 130 }, c = { x = { { 0.00, "Нужно доставить сундук в Западный Край, да? А вы там бывали прежде? Если да, то никаких проблем, друг мой." }, { 7.33, "У меня есть множество грифонов, обученных этому маршруту!" } } } } },
    [6281] = { d = 20.1, v = "human-male", n = { x = 227 }, c = { x = { { 0.00, "За небольшую плату вы можете нанять грифона для полёта в Штормград, чтобы доставить записку Льюиса Озрику. Более быстрого пути нет." }, { 9.44, "Если для вас это приемлемо, поговорите со мной снова, когда будете готовы лететь." }, { 15.09, "Я, конечно, возьму с вас немного денег, но поверьте, оно того стоит!" } } }, t = { d = 16.6, v = "human-male#116", n = { x = 188 }, c = { x = { { 0.00, "А, записка от интенданта Льюиса! Я не удивлён, что ему понадобилась дополнительная экипировка." }, { 6.59, "Сторожевой Холм далеко, и в Штормграде едва помнят о нём." }, { 10.90, "Что ж, спасибо вам. Вот немного денег на покрытие ваших транспортных расходов." } } } } },
    [6282] = { d = 28.9, v = "tauren-male", n = { x = 277 }, c = { x = { { 0.00, "Таурен горд тем, что защищает эти земли." }, { 3.29, "Несомненно, ты понимаешь, почему я обеспокоен тем, что здесь, в Каменном Когте, обитает множество гарпий." }, { 12.66, "Клан Смертельной Ярости – вот откуда берутся всё новые и новые гарпии в Калимдоре." }, { 18.95, "Они посягают на жизнь всех и каждого, не давая слабым даже уйти отсюда!" }, { 24.89, "Мне нужна твоя помощь в уничтожении гарпий!" } } }, t = { d = 14.4, v = "tauren-male", n = { x = 127 }, c = { x = { { 0.00, "Замечательные новости! Поведай мне вновь, как тебе удалось вселить ужас в холодные сердца злобных гарпий." }, { 10.54, "Клан Смертельной Ярости понёс серьёзный урон!" } } } } },
    [6283] = { d = 29.4, v = "tauren-male", n = { x = 300 }, c = { x = { { 0.00, "Уменьшить число гарпий из стаи Кровавой Ярости – этого недостаточно." }, { 5.30, "Единственное, чем можно извести эту заразу – это убить их предводительницу, Потрошительницу!" }, { 12.66, "Средь этих мерзостных существ она почти королева. Убей её, и гарпий станет меньше." }, { 19.47, "Возвращайся в Обугленную долину, и ты найдёшь её у западных холмов. Её не так-то легко уничтожить, но награда будет велика." } } }, t = { d = 27.9, v = "tauren-male", n = { x = 264 }, c = { x = { { 0.00, "Я уже чувствую, как гнев покидает меня. Что мне теперь делать?" }, { 4.94, "Знание о том, что зло бродило поблизости от моих земель, заставляло мои мысли течь быстро, пусть и безмолвно." }, { 14.30, "Быть может, это и к лучшему... быть может, теперь я смогу обратить свои мысли в сторону добра, как и положено таурену." }, { 23.76, "Прошу тебя, прими это в награду за твои труды." } } } } },
    [6284] = { d = 29.0, v = "human-male#114", n = { x = 297 }, c = { x = { { 0.00, "Предупреждение: дорога отсюда на запад, в Сиширский каньон, опасна." }, { 6.11, "Бесселет и её восьминогие отпрыски превратили этот каньон в своё логово, заплетённое паутиной." }, { 13.93, "Маггран Связующий Землю из Приюта у Солнечного Камня назначил награду за Бесселет." }, { 20.18, "Убей её и принеси доказательство её смерти Магграну – получишь награду за устранение этой восьминогой угрозы." } } }, t = { d = 26.6, v = "tauren-male", n = { x = 254 }, c = { x = { { 0.00, "Добрая охота! Бесселет издавна была угрозой для этих земель... и я не буду по ней тосковать." }, { 7.81, "Возьми эту награду в знак того, что тебе удалось защитить наш лес." }, { 13.80, "Маггран потирает рану, нанесённую Бесселет." }, { 17.64, "Быть может, теперь больше народа будет приходить в Приют у Солнечного Камня, не боясь того, что крадётся во мраке." } } } } },
    [6285] = { d = 33.1, v = "human-male", n = { x = 376 }, c = { x = { { 0.00, "Укротителем грифонов в Западном Крае работает Тор. Если вы с ним уже знакомы, то можете на одном из моих грифонов к нему долететь." }, { 9.36, "Полезная для вас информация: грифоны обучены так, что до столицы могут долететь всегда, а к укротителям, расположенным в других местах, полетят, только если вы там уже бывали." }, { 21.56, "Вы ведь уже были у Тора, так что просто поговорите со мной ещё раз, когда будете готовы лететь в Западный Край." }, { 29.25, "А там уже отнесёте ящик Озрика интенданту Льюису." } } }, t = { d = 19.7, g = 1, v = "human-male", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Отлично, вы привезли доспехи! Мы распределим их между теми, кому они срочно необходимы." }, { 6.43, "Спасибо вам, сэр путник. Вы нам очень помогли." }, { 9.69, "А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто прилетать к нам и предлагать свою помощь Сторожевому холму!" } }, f = { { 0.00, "Отлично, вы привезли доспехи! Мы распределим их между теми, кому они срочно необходимы." }, { 6.43, "Спасибо вам, леди путница. Вы нам очень помогли." }, { 9.90, "А теперь, когда вы знакомы и с нашими грифонами, я надеюсь, вы будете часто прилетать к нам и предлагать свою помощь Сторожевому холму!" } } } } },
    [6301] = { d = 33.4, v = "tauren-female#71", n = { x = 337 }, c = { x = { { 0.00, "Жадность промышленников и постоянная война опустошили земли Каменного Пика." }, { 6.09, "Только благословение Матери-Земли может исцелить такие раны." }, { 11.17, "Я хочу отправить тебя на поиски особого семени – семени Геи." }, { 15.83, "Его можно найти только здесь, в Каменном Когте, к северу от Приюта у Солнечного Камня, у Мутного Озера, у самого края воды." }, { 25.96, "Как только ты принесёшь мне эти семена, я напитаю их шаманской силой, дабы ускорить их рост." } } }, t = { d = 14.3, v = "tauren-female#71", n = { x = 148 }, c = { x = { { 0.00, "О, так вот они – семена Геи! Смотри и увидишь, как благословение Матери-Земли даст этим крошечным семенам жизни возможность цвести и плодоносить. Таммра начинает читать заклинание." } } } } },
    [6321] = { d = 40.3, v = "scourge-male", n = { x = 416 }, c = { x = { { 0.00, "Исполнитель Хадрик попросил меня заняться нашим арсеналом в Гробнице." }, { 5.22, "По лесу рыщут силы Плети, а то и кое-что похуже, и он хочет, чтобы у наших стражей смерти было достаточно оружия, когда оно понадобится." }, { 15.56, "Я выяснил, что в целом у нас всё в порядке, но нам нужно дополнительное оружие взамен потерянного в боях." }, { 23.72, "Вот заявка на поставку для торговца оружием Гордона Уиндема, находящегося в Подгороде." }, { 30.24, "Отнесите этот заказ нашему дрессировщику летучих мышей, Каросу Раззоку, и поговорите с ним о полёте в Подгород." } } }, t = { d = 11.8, v = "scourge-male", n = { x = 119 }, c = { x = { { 0.00, "А, заказ на поставки. Не сомневаюсь, вам нужно доставить его в Подгород." }, { 5.85, "И как можно скорее, потому что в Гробнице нельзя допустить нехватку оружия." } } } } },
    [6322] = { d = 20.4, v = "scourge-male#145", n = { x = 219 }, c = { x = { { 0.00, "Я сложил припасы для Гробницы в этот ящик." }, { 3.50, "Если вы уже бывали в Гробнице и знакомы с тамошним дрессировщиком летучих мышей, то можете туда лететь." }, { 11.36, "Поговорите с дрессировщиком летучих мышей здесь, в Подгороде – с Майклом Гарреттом. Он поможет вам добраться до Гробницы." } } }, t = { d = 8.0, v = "scourge-male", n = { x = 84 }, c = { x = { { 0.00, "Этот ящик нужно доставить в Гробницу, что в Серебряном бору? Это легко: наши мыши ежедневно туда летают." } } } } },
    [6323] = { d = 19.5, v = "scourge-male", n = { x = 206 }, c = { x = { { 0.00, "Одна из моих летучих мышей может отвезти вас в Подгород, за небольшую плату." }, { 5.73, "Приходите ко мне, когда будете готовы, чтобы мы могли организовать ваш полёт." }, { 11.93, "Гордона Уиндема вы найдёте в Торговом квартале Подгорода. Именно там и приземлится летучая мышь." } } }, t = { d = 6.5, v = "scourge-male#145", n = { x = 67 }, c = { x = { { 0.00, "Заказ из Гробницы? Отлично. Для меня честь – услужить тем, кто служит Тёмной Госпоже." } } } } },
    [6324] = { d = 36.8, v = "scourge-male", n = { x = 394 }, c = { x = { { 0.00, "Дрессировщика летучих мышей в Гробнице зовут Карос Раззок." }, { 4.52, "Если вы уже знакомы с ним, я могу предоставить вам одну из своих летучих мышей, чтобы вы к нему вернулись." }, { 12.73, "Все наши мыши всегда могут долететь до Подгорода, но, чтобы добраться до более отдалённых мест, пассажир должен сначала посетить эти места и познакомиться с тамошними дрессировщиками." }, { 26.53, "С Каросом вы уже встречались в Гробнице, так что теперь можете летать туда на мышах." }, { 32.87, "Вернитесь ко мне, когда будете готовы к полёту." } } }, t = { d = 10.4, v = "scourge-male", n = { x = 102 }, c = { x = { { 0.00, "Хорошая работа. Это оружие позволит не застать врасплох наших стражей смерти." }, { 6.68, "Вы сослужили хорошую службу Тёмной Госпоже." } } } } },
    [6341] = { d = 30.7, v = "nightelf-female#53", n = { x = 353 }, c = { x = { { 0.00, "Рыбаки деревни Рут'теран живут очень хорошо: ведь рыба здесь очень крупная, и её много." }, { 6.00, "Я хотела бы сравнить здешнее изобилие с ситуацией в материковых водах." }, { 11.10, "Я собрала образцы рыбьих костей и чешуи, которые хотела бы отправить своему коллеге на Тёмный Берег." }, { 18.02, "Его зовут Лайрд, он торгует рыбой в Аубердине." }, { 21.94, "Идите с моей коллекцией образцов к нашему дрессировщику гиппогрифов, Веспристу, и поговорите с ним насчёт полёта в Аубердин." } } }, t = { d = 3.9, v = "nightelf-male#54", n = { x = 44 }, c = { x = { { 0.00, "А, вы хотите доставить эту посылку в Аубердин? Отлично..." } } } } },
    [6342] = { d = 36.7, v = "nightelf-male#54", n = { x = 415 }, c = { x = { { 0.00, "Из деревни Рут'теран можно добраться в Аубердин двумя путями: на пароме и на гиппогрифе." }, { 6.09, "Оба способа быстры и надёжны, но если вы ещё никогда не летали в Аубердин на гиппогрифе, я бы порекомендовал вам это сделать." }, { 15.12, "Мой вам добрый совет: говорите с дрессировщикам гиппогрифов в каждом городе, где они есть." }, { 21.30, "Когда вы поговорите с дрессировщиком, то сможете летать в этот город из других мест." }, { 27.41, "Возвращаю вам коллекцию Нессы. Поговорите со мной, когда будете готовы лететь в Аубердин и доставить коллекцию Лайрду." } } }, t = { d = 22.0, v = "nightelf-male#121", n = { x = 250 }, c = { x = { { 0.00, "Посылка от Нессы? Спасибо Она говорила, что собирается прислать мне образцы рыбы, пойманной близ деревни Рут'теран." }, { 7.88, "Она думает, что эта рыба может серьёзно отличаться от той, что ловится здесь..." }, { 13.56, "Ничего себе! Эта челюсть чуть ли не вдвое больше, чем у таких же здешних рыб. А эта чешуя размером с кулак! Невероятно!" } } } } },
    [6343] = { d = 34.3, v = "nightelf-male#121", n = { x = 413 }, c = { x = { { 0.00, "Мне нужно отправить Нессе ответ. Ей будет очень интересно знать, насколько здешняя рыба отличается от той, что водится у берегов Тельдрассила." }, { 9.59, "Мы можем лишь догадываться о причинах, но подозреваю, что так воздействует само Древо Жизни на окружающую его природу!" }, { 17.97, "Пожалуйста, отнесите мой ответ Нессе." }, { 20.53, "Если хотите лететь в Рут'теран на гиппогрифе, поговорите с дрессировщиком гиппогрифов Кайлаис Лунному Перу." }, { 27.90, "А если хотите добраться паромом, то он регулярно отходит от причала к северо-западу отсюда." } } }, t = { d = 22.6, v = "nightelf-female#53", n = { x = 259 }, c = { x = { { 0.00, "Всё это очень интересно. Рыба здесь крупная, но я не думала, что разница между обитающими в материковых и здешних водах столь велика. Для этого должна быть причина..." }, { 11.63, "Что ж, благодарю вас Я обсужу с земляками новости, что вы принесли. Может быть, когда-нибудь мы найдём причину этой странности. А пока будем ею пользоваться!" } } } } },
    [6344] = { d = 20.8, v = "nightelf-male#120", n = { x = 229 }, c = { x = { { 0.00, "Моя подруга, Несса Песня Теней, торгует рыбой в деревне Рут'теран." }, { 4.91, "Ей нужно доставить посылку на Тёмный берег, и она ищет кого-нибудь, кто мог бы ей помочь." }, { 11.49, "Если вы хотите помочь Нессе, то ступайте в деревню Рут'теран через портал в Дарнассе. Портал находится к западу от Храмовых садов." } } }, t = { d = 5.8, v = "nightelf-female#53", n = { x = 65 }, c = { x = { { 0.00, "Да, мне нужен курьер, который доставит посылку на Тёмные берега. Вы мне поможете?" } } } } },
    [6361] = { d = 31.7, v = "tauren-male#132", n = { x = 273 }, c = { x = { { 0.00, "Я хочу переслать в Громовой Утёс связку шкур степных зверей." }, { 5.27, "Мой коллега, Ахану, занимается кожевенным делом и найдёт им достойное применение. Не возьмёшься доставить ему шкуры?" }, { 17.21, "До Громового Утёса проще всего добраться на ветрокрыле." }, { 22.29, "Отнеси шкуры укротителю ветрокрылов Девраку и поговори с ним насчёт доставки в Громовой Утёс." } } }, t = { d = 5.8, g = 1, v = "orc-male#60", n = { m = 58, f = 59 }, c = { m = { { 0.00, "Хочешь отвезти эти шкуры в Громовой Утёс? Тогда ты обратился по адресу!" } }, f = { { 0.00, "Хочешь отвезти эти шкуры в Громовой Утёс? Тогда ты обратилась по адресу!" } } } } },
    [6362] = { d = 23.1, v = "orc-male#60", n = { x = 250 }, c = { x = { { 0.00, "За небольшую плату ты можешь полететь в Громовой Утёс на ветрокрыле. Быстрее не бывает!" }, { 7.11, "Если тебя устраивает цена – обращайся, когда решишь отправиться в путь." }, { 12.26, "Если ты везёшь эти шкуры Ахану, думаю, ты отыщешь его в оружейной Хевы, у основания башни ветрокрылов в Громовом Утёсе. Именно там ты и приземлишься!" } } }, t = { d = 13.5, g = 1, v = "tauren-male#133", n = { m = 131, f = 134 }, c = { m = { { 0.00, "А, новая связка шкур. Я немедленно ими займусь." }, { 4.36, "Спасибо, брат. Ты оказал мне большую услугу. Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время." } }, f = { { 0.00, "А, новая связка шкур. Я немедленно ими займусь." }, { 4.36, "Спасибо, сестра. Ты оказала мне большую услугу. Возьми эти монеты, чтобы покрыть дорожные расходы и потраченное время." } } } } },
    [6363] = { d = 22.7, g = 1, v = "tauren-male#133", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Я приготовил кое-какие кожаные изделия на продажу в Перекрёстке. Не отнесёшь их Джахану?" }, { 7.05, "Если ты уже поговорил с укротителем ветрокрылов в Перекрёстке, можешь полететь туда на виверне." }, { 14.69, "Отнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчёт дороги до Перекрёстка." } }, f = { { 0.00, "Я приготовил кое-какие кожаные изделия на продажу в Перекрёстке. Не отнесёшь их Джахану?" }, { 7.05, "Если ты уже поговорила с укротителем ветрокрылов в Перекрёстке, можешь полететь туда на виверне." }, { 14.74, "Отнеси мои товары здешнему укротителю ветрокрылов Талу и поговори с ним насчёт дороги до Перекрёстка." } } }, t = { d = 11.3, g = 1, v = "tauren-male", n = { m = 105, f = 107 }, c = { m = { { 0.00, "Тебе нужно в Перекрёсток? Нет проблем. Если ты там уже побывал и поговорил с Девраком, можешь лететь на одном из моих ветрокрылов." } }, f = { { 0.00, "Тебе нужно в Перекрёсток? Нет проблем." }, { 2.97, "Если ты там уже побывала и поговорила с Девраком, можешь лететь на одном из моих ветрокрылов." } } } } },
    [6364] = { d = 26.1, g = 1, v = "tauren-male", n = { m = 262, f = 263 }, c = { m = { { 0.00, "Чтобы полететь в какой-нибудь город, следует прежде побывать в нём и поговорить с укротителем ветрокрылов." }, { 8.36, "В Перекрёстке ты уже побывал, поэтому за небольшую плату ветрокрыл может отнести тебя туда." }, { 15.85, "Обращайся, когда решишь отправиться в путь. Оказавшись в Перекрёстке, отнеси кожаные вещи Джахану Соколиному Крылу." } }, f = { { 0.00, "Чтобы полететь в какой-нибудь город, следует прежде побывать в нём и поговорить с укротителем ветрокрылов." }, { 8.36, "В Перекрёстке ты уже побывала, поэтому за небольшую плату ветрокрыл может отнести тебя туда." }, { 16.01, "Обращайся, когда решишь отправиться в путь. Оказавшись в Перекрёстке, отнеси кожаные вещи Джахану Соколиному Крылу." } } }, t = { d = 17.2, v = "tauren-male#132", n = { x = 155 }, c = { x = { { 0.00, "Ахану прислал мне готовые изделия? Очень хорошо." }, { 4.70, "В деревню Кровавого Копыта забредает много охотников и искателей приключений, и дела у меня идут неплохо." }, { 14.50, "Спасибо за помощь. Я у тебя в долгу." } } } } },
    [6365] = { d = 22.6, v = "orc-male", n = { x = 258 }, c = { x = { { 0.00, "Я хочу послать своей подруге несколько видов превосходных мясных продуктов. Её зовут Гришка, она хозяйка таверны в Оргриммаре. Поможешь мне доставить мясо?" }, { 11.19, "До Оргриммара проще всего добраться на ветрокрыле." }, { 15.26, "Отнеси мясные продукты Девраку, укротителю ветрокрылов, и поговори с ним насчёт доставки в Оргриммар." } } }, t = { d = 7.3, v = "orc-male#60", n = { x = 85 }, c = { x = { { 0.00, "Тебе нужно доставить мясо в Оргриммар? Нет проблем. За небольшую плату тебя отнесёт туда мой ветрокрыл." } } } } },
    [6381] = { d = 35.0, g = 1, v = "tauren-female#71", n = { x = 339 }, c = { m = { { 0.00, "Вот видишь, герой, хотя эта земля глубоко изранена, круговорот жизни – великая сила." }, { 6.57, "Теперь мы должны внести свой вклад и помочь этой силе." }, { 10.96, "Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине." }, { 17.80, "Но берегись – там, в полумёртвых землях, ещё встречаются гарпии и злобные элементали огня." }, { 25.10, "Возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!" } }, f = { { 0.00, "Вот видишь, героиня, хотя эта земля глубоко изранена, круговорот жизни – великая сила." }, { 7.30, "Теперь мы должны внести свой вклад и помочь этой силе." }, { 11.69, "Посади эти семена в самой сердцевине разрушения, на западе, в Обугленной долине." }, { 18.53, "Но берегись – там, в полумёртвых землях, ещё встречаются гарпии и злобные элементали огня." }, { 25.83, "Возьми эти зачарованные семена Геи и посади их в кучки плодородной почвы. Круговорот жизни должен продолжаться!" } } }, t = { d = 31.9, g = 1, v = "tauren-female#71", n = { m = 320, f = 321 }, c = { m = { { 0.00, "Это великая победа, свершённая ради здешних земель." }, { 4.11, "Со временем произойдут и другие перемены: Торговая Компания уберётся отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель." }, { 18.77, "Только тогда, в Каменном Когте настанет истинный мир." }, { 23.19, "Ты совершил благое дело, герой; возьми один из этих предметов в награду за вклад в создание новой жизни." } }, f = { { 0.00, "Это великая победа, свершённая ради здешних земель." }, { 4.11, "Со временем произойдут и другие перемены: Торговая Компания уберётся отсюда вместе со своими пилами и топорами, разгневанные духи огня успокоятся, а гарпии будут изгнаны с этих земель." }, { 18.80, "Только тогда, в Каменном Когте настанет истинный мир." }, { 23.22, "Ты совершила благое дело, героиня; возьми один из этих предметов в награду за вклад в создание новой жизни." } } } } },
    [6382] = { d = 42.3, g = 1, v = "tauren-male#67", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Твоя сила производит впечатление, герой, а интерес к охоте даёт надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьёзнее." }, { 13.89, "Орда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса." }, { 24.52, "Если ты готов проявить себя в непознанных ещё землях, обратись к Сенани Громосерд на заставе Расщеплённого Древа." }, { 36.56, "Она находится к северу от тропы из Степей." } }, f = { { 0.00, "Твоя сила производит впечатление, героиня, а интерес к охоте даёт надежды, что вскоре тебе можно будет поручить дичь покрупнее... И посерьёзнее." }, { 14.12, "Орда стремится подчинить себе и в политическом и в духовном смысле бескрайние дикие просторы Ясеневого леса." }, { 24.75, "Если ты готова проявить себя в непознанных ещё землях, обратись к Сенани Громосерд на заставе Расщеплённого Древа." }, { 37.92, "Она находится к северу от тропы из Степей." } } }, t = { d = 34.0, g = 1, v = "tauren-female", n = { x = 307 }, c = { m = { { 0.00, "Добро пожаловать на новое пограничье." }, { 2.96, "Ясеневый лес – край неограниченных возможностей, где юному герою вроде тебя выпадает шанс показать себя." }, { 13.10, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 21.28, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 26.33, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } }, f = { { 0.00, "Добро пожаловать на новое пограничье." }, { 2.96, "Ясеневый лес – край неограниченных возможностей, где юному героине вроде тебя выпадает шанс показать себя." }, { 13.49, "Посмотри на эту заставу и не поленись сходить на Зорамское взморье – у Орды и там форпост есть." }, { 21.66, "Как понимаю, ты здесь для того, чтобы побольше узнать об охоте." }, { 26.72, "Слушай же внимательно, и я с радостью поделюсь с тобой всем, что тебе следует знать." } } } } },
    [6384] = { d = 21.4, v = "orc-male#60", n = { x = 230 }, c = { x = { { 0.00, "Всего лишь за несколько монет ветрокрыл отнесёт тебя в Оргриммар. Оказавшись там, отнеси мясные продукты Зарга Гришке." }, { 9.76, "Её постоялый двор располагается на аллее Силы неподалёку от небесной башни, где тебя высадит мой ветрокрыл." }, { 17.70, "Поговори со мной, когда решишь отправиться в путь." } } }, t = { d = 15.8, v = "orc-female#124", n = { x = 155 }, c = { x = { { 0.00, "О, чудесно! Какое отличное мясо! Оно ведь от Зарга, да? Этот орк знает, как завоевать женское сердце…" }, { 8.22, "Ох, мне не терпится его приготовить. Но не слишком много! Мясо вкуснее, когда его подают редко, верно?" } } } } },
    [6385] = { d = 19.5, g = 1, v = "orc-female#124", n = { m = 219, f = 220 }, c = { m = { { 0.00, "Я написала Заргу письмо благодарности. Поможешь с доставкой?" }, { 4.35, "Если ты уже поговорил с укротителем ветрокрылов в Перекрёстке, то можешь полететь туда." }, { 11.03, "Иди с моим письмом к Дорасу, оргриммарскому укротителю ветрокрылов, и поговори с ним насчёт полёта до Перекрёстка." } }, f = { { 0.00, "Я написала Заргу письмо благодарности. Поможешь с доставкой?" }, { 4.35, "Если ты уже поговорила с укротителем ветрокрылов в Перекрёстке, то можешь полететь туда." }, { 10.99, "Иди с моим письмом к Дорасу, оргриммарскому укротителю ветрокрылов, и поговори с ним насчёт полёта до Перекрёстка." } } }, t = { d = 6.2, v = "orc-male#126", n = { x = 68 }, c = { x = { { 0.00, "Тебе нужно доставить письмо в Перекрёсток? Да, мои виверны могут отнести тебя туда." } } } } },
    [6386] = { d = 24.5, g = 1, v = "orc-male#126", n = { m = 256, f = 260 }, c = { m = { { 0.00, "Мои виверны могут отвезти тебя в самые разные края – при условии, что ты сам там уже был и говорил с местным укротителем ветрокрылов." }, { 10.23, "Тебе уже доводилось бывать в Перекрёстке, да и Деврака ты знаешь, так что, лети прямо к нему." }, { 17.86, "Оказавшись в Перекрёстке, ты сможешь передать Заргху письмо Гришки. Как будешь готов, скажи." } }, f = { { 0.00, "Мои виверны могут отвезти тебя в самые разные края – при условии, что ты сама там уже была и говорила с местным укротителем ветрокрылов." }, { 9.83, "Тебе уже доводилось бывать в Перекрёстке, да и Деврака ты знаешь, так что, лети прямо к нему." }, { 17.46, "Оказавшись в Перекрёстке, ты сможешь передать Заргху письмо Гришки. Как будешь готова, скажи." } } }, t = { d = 17.6, g = 1, v = "orc-male", n = { m = 164, f = 165 }, c = { m = { { 0.00, "Ха! Я так и знал, что ей понравится! Ничто так не нравится женщинам, как хороший сочный стейк!" }, { 9.01, "Спасибо. Ты оказал мне неоценимую услугу. Вот тебе плата за труды – и не удивляйся, если я приглашу тебя на свадьбу!" } }, f = { { 0.00, "Ха! Я так и знал, что ей понравится! Ничто так не нравится женщинам, как хороший сочный стейк!" }, { 9.01, "Спасибо. Ты оказала мне неоценимую услугу. Вот тебе плата за труды – и не удивляйся, если я приглашу тебя на свадьбу!" } } } } },
    [6387] = { d = 33.6, v = "dwarf-male", n = { x = 384 }, c = { x = { { 0.00, "Ко мне приходит немало молодых дворфов, мечтающих научиться горному делу. Что же нужнее всего шахтёру? Кирка!" }, { 7.76, "Я составил список учеников, которые хорошо проявили себя на занятиях и заслужили почётную кирку." }, { 14.48, "Отнеси этот список Голниру Твердопалу в Стальгорн. Он подготовит для меня эти кирки." }, { 20.68, "Проще всего добраться до Стальгорна на грифоне, поэтому ступай с этим списком к нашему укротителю грифонов, Торгруму Боррелсону, и поговори с ним насчёт полёта в Стальгорн." } } }, t = { d = 11.5, v = "dwarf-male", n = { x = 122 }, c = { x = { { 0.00, "Тебе нужно отвезти это в Стальгорн, да?" }, { 2.69, "За небольшую плату я позволю тебе оседлать одного из моих грифонов, и он отнесёт тебя прямо в город. Что скажешь?" } } } } },
    [6388] = { d = 16.4, g = 1, v = "dwarf-male#99", n = { m = 167, f = 168 }, c = { m = { { 0.00, "Вот почётные кирки для учеников Брока. Если ты уже бывал в Телсамаре, можешь полететь обратно на грифоне!" }, { 7.47, "Отнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчёт полёта в Телсамар." } }, f = { { 0.00, "Вот почётные кирки для учеников Брока. Если ты уже бывала в Телсамаре, можешь полететь обратно на грифоне!" }, { 8.27, "Отнеси кирки нашему укротителю грифонов, Гриту Турдену, и поговори с ним насчёт полёта в Телсамар." } } }, t = { d = 10.6, g = 1, v = "dwarf-male", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Значит, тебе нужно в Телсамар? Не вопрос." }, { 3.01, "Если ты там уже бывал и беседовал с Торгрумом Боррелсоном, можешь полететь к нему на грифоне." } }, f = { { 0.00, "Значит, тебе нужно в Телсамар? Не вопрос." }, { 3.01, "Если ты там уже бывала и беседовала с Торгрумом Боррелсоном, можешь полететь к нему на грифоне." } } } } },
    [6391] = { d = 22.4, v = "dwarf-male", n = { x = 262 }, c = { x = { { 0.00, "Всего за несколько монет один из моих грифонов отнесёт тебя в Стальгорн. Там ты сможешь отдать список Брока Голниру Твердопалу." }, { 8.66, "Его можно найти в гильдии горняков Тайной Горы." }, { 12.04, "Она находится неподалёку от Великой Кузни Стальгорна, и именно там тебя высадит мой грифон!" }, { 18.67, "Когда решишь отправиться в путь, обращайся ко мне." } } }, t = { d = 8.1, v = "dwarf-male#99", n = { x = 94 }, c = { x = { { 0.00, "А, последний список лучших учеников Брока. Я уже подготовил почётные кирки, осталось выбить на них имена учеников..." } } } } },
    [6392] = { d = 31.3, g = 1, v = "dwarf-male", n = { m = 349, f = 352 }, c = { m = { { 0.00, "За небольшую плату грифон отнесёт тебя в Телсамар... если ты там уже бывал." }, { 4.95, "Грифоны могут летать только туда, где ты успел побывать." }, { 8.88, "Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность прилететь к ним." }, { 16.16, "Торгрума, дрессировщика грифонов Телсамара, ты уже видел, поэтому можешь вернуться к нему." }, { 22.40, "Оказавшись в Телсамаре, отнеси кирки Броку Камнекопу." }, { 27.48, "Когда решишь тронуться в путь – обращайся ко мне." } }, f = { { 0.00, "За небольшую плату грифон отнесёт тебя в Телсамар... если ты там уже бывала." }, { 5.12, "Грифоны могут летать только туда, где ты успела побывать." }, { 9.10, "Не упускай случая поговорить со всеми укротителями грифонов, и получишь возможность прилететь к ним." }, { 16.38, "Торгрума, дрессировщика грифонов Телсамара, ты уже видела, поэтому можешь вернуться к нему." }, { 22.62, "Оказавшись в Телсамаре, отнеси кирки Броку Камнекопу." }, { 27.70, "Когда решишь тронуться в путь – обращайся ко мне." } } }, t = { d = 15.7, v = "dwarf-male", n = { x = 175 }, c = { x = { { 0.00, "А вот и кирки. Отлично! Я раздам их своим ученикам. Им, конечно, не терпится пустить их в ход в рудниках возле озера Лок Модан." }, { 8.93, "Благодарю за помощь. Я у тебя в долгу. Возьми эти деньги, они должны покрыть стоимость перелёта." } } } } },
    [6393] = { d = 48.0, v = "elemental-water", n = { x = 365 }, c = { x = { { 0.00, "Совет Приливов послал меня объявить войну элементалям огня здесь, в Каменном Когте." }, { 8.92, "Нептулон Приливный Охотник, повелитель всех элементалей воды, лично заинтересован в том, чтобы узреть погибель всех наших огненных сородичей." }, { 24.30, "Ты можешь помочь мне высоко подняться во мнении Совета путём уничтожения элементалей огня в Обугленной долине." }, { 35.99, "После смерти от этих элементалей остаются огненные кристаллы. Отдай их мне, и ты получишь награду." } } }, t = { d = 15.6, g = 1, v = "elemental-water", n = { x = 102 }, c = { m = { { 0.00, "Духи воды внутри меня булькают от восторга." }, { 4.26, "путник, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов." } }, f = { { 0.00, "Духи воды внутри меня булькают от восторга." }, { 4.26, "путница, я высоко ценю твой дар – славную победу, о которой я могу сообщить в Совет Приливов." } } } } },
    [6394] = { d = 33.1, g = 1, v = "orc-male", n = { m = 351, f = 351 }, c = { m = { { 0.00, "Ты добросовестный герой. Можно доверить тебе ещё одно дело?" }, { 5.14, "Не так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку." }, { 11.54, "А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей!" }, { 17.07, "Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку?" }, { 22.47, "Я её оставил в зале с водопадами. Кирка моя заговорённая – она светится в темноте, так что найти её будет нетрудно... только, боюсь, её уже стерегут!" } }, f = { { 0.00, "Ты добросовестная героиня. Можно доверить тебе ещё одно дело?" }, { 4.73, "Не так давно я ходил искать минералы в грот к северу отсюда и забыл там свою любимую кирку." }, { 11.14, "А когда я вернулся за ней, то обнаружил, что там уже полно кровожадных зверей!" }, { 16.66, "Не можешь ли ты сходить в грот Пылающего Клинка и раздобыть мою кирку?" }, { 22.06, "Я её оставил в зале с водопадами. Кирка моя заговорённая – она светится в темноте, так что найти её будет нетрудно... только, боюсь, её уже стерегут!" } } }, t = { d = 11.6, v = "orc-male", n = { x = 121 }, c = { x = { { 0.00, "Она у тебя! Моя любимая кирка! Спасибо большое!" }, { 4.09, "Ну, теперь главное – дождаться, когда мои батраки управятся с рубкой леса, – и можно снова искать минералы!" } } } } },
    [6395] = { d = 46.0, v = "scourge-female#80", n = { x = 402 }, c = { x = { { 0.00, "Моя подруга Марла Фиппс жила до чумы со своим мужем Самуэлем, но когда пришла чума, Самуэль погиб... и вступил в ряды Плети." }, { 13.73, "Марла избежала чумы, но погибла от рук собственного мужа, лишившегося разума." }, { 20.29, "Однако так велика была её любовь, что последним желанием её было, чтобы Самуэль был похоронен рядом с ней." }, { 29.57, "Самуэль Фиппс обитает теперь у разорённого лагеря близ дороги на северо-восток от Могильника." }, { 37.68, "Убей его и выполни желание Марлы: похорони Самуэля в её могиле, в первом ряду нашего кладбища." } } }, t = { d = 12.2, v = "scourge-female#80", n = { x = 114 }, c = { x = { { 0.00, "Ты, совершил сегодня доброе дело. Хотя наша борьба против армии Плети продолжается, будем надеяться, что Марла и Самуэль упокоятся с миром." } } } } },
    [6401] = { d = 21.7, v = "tauren-male", n = { x = 196 }, c = { x = { { 0.00, "Передай Таммре Поле Ветров, тётушке Кайи, живущей в Приюте у Солнечного Камня, добрые новости – Кайя жива!" }, { 10.60, "Мы думали, что она погибла во время того жестокого нападения на нашу деревню." }, { 16.60, "Иди по дороге на запад, и придёшь в Приют у Солнечного Камня." } } }, t = { d = 6.7, v = "tauren-female#71", n = { x = 66 }, c = { x = { { 0.00, "Хвала духам, моя племянница Кайя жива! Это поистине добрая новость. Спасибо тебе!" } } } } },
    [6421] = { d = 44.0, g = 1, v = "tauren-male#67", n = { m = 336, f = 336 }, c = { m = { { 0.00, "Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе?" }, { 8.40, "К юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита." }, { 20.81, "Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере." }, { 29.63, "Помимо того, неплохо бы тебе обследовать глубины этой пещеры." }, { 35.85, "Иди же, юный герой, мне очень важно знать, что за зло таится под этими горами." } }, f = { { 0.00, "Что-то не так здесь, в Каменном Когте. Чувствуешь ли ты непокой, витающий в воздухе?" }, { 8.40, "К юго-востоку отсюда, в ущелье Камнепадов, есть пещера. Там кобольды отчаянно ищут редкие кристаллы резонита." }, { 20.81, "Я прошу тебя принести оттуда образцы руды, чтобы я мог понять, что происходит в этой пещере." }, { 29.63, "Помимо того, неплохо бы тебе обследовать глубины этой пещеры." }, { 35.85, "Иди же, юная героиня, мне очень важно знать, что за зло таится под этими горами." } } }, t = { d = 42.7, v = "tauren-male#67", n = { x = 353 }, c = { x = { { 0.00, "О да! Это оно – кристалл резонита несёт следы земной магии." }, { 5.62, "Должно быть, кобольды, докопавшись до глубин, обнаружили там земельника." }, { 12.93, "Легенда утверждает, что земельники – это существа, созданные титанами." }, { 19.62, "Именно с их помощью создана земная твердь, по которой мы ступаем. Угроза велика, нельзя не обращать на неё внимания. Мор'рогал качает головой." }, { 33.71, "Быть может, я сумею наложить заклинание на эти куски руды, чтобы нарушить затею кобольдов." } } } } },
    [6441] = { d = 33.0, v = "goblin-female#63", n = { x = 376 }, c = { x = { { 0.00, "Привет! Я ехала через Ясеневый лес в Кабестан и решила остановиться здесь, в Расщеплённом Древе." }, { 6.59, "Я никогда не упущу выгодного дельца, а тут оказывается, что рога сатира нынче пользуются в Кабестане большим спросом." }, { 14.95, "Я тут поспрошала, и оказывается, что сатиры с Ночной поляны, Сатирнаара и Ксавиана как раз носят такие рога, что мне надо." }, { 23.32, "Мне эти сатиры не по зубам... но вот вам – наверняка!" }, { 27.21, "Скажите, сколько возьмёте, добудьте мне рога, и я оплачу ваше потраченное время." } } }, t = { d = 4.4, v = "goblin-female#63", n = { x = 46 }, c = { x = { { 0.00, "Изумительные рога! Спасибо за помощь! О, а это вам за труды..." } } } } },
    [6442] = { d = 25.7, g = 1, v = "troll-female", n = { x = 265 }, c = { m = { { 0.00, "Зло рыщет по побережью, герой." }, { 2.52, "Здесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощённый морем. Разрушенный и почти забытый." }, { 11.13, "Теперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись." }, { 20.39, "Принеси мне двадцать их голов! Загони наг назад, в глубины моря!" } }, f = { { 0.00, "Зло рыщет по побережью, героиня." }, { 2.87, "Здесь покоится под волнами проклятый город Зорам, давно разрушенный и поглощённый морем. Разрушенный и почти забытый." }, { 11.49, "Теперь в него непонятно почему вернулись наги. Но причина не так важна – мы должны защитить край, за который так упорно боролись." }, { 20.74, "Принеси мне двадцать их голов! Загони наг назад, в глубины моря!" } } }, t = { d = 3.9, v = "troll-female", n = { x = 38 }, c = { x = { { 0.00, "Побольше бы нам таких, как ты. Спасибо за помощь." } } } } },
    [6461] = { d = 28.8, v = "troll-male#78", n = { x = 330 }, c = { x = { { 0.00, "Мы, тролли, тут, в Малака'джине, живём с земли, да и живём хорошо. В Каменном Когте есть на что поохотиться." }, { 7.36, "Только вот повадились к нам в последнее время незваные гости... по ночам пауки на наши стоянки нападают, хотят украсть нашу добычу." }, { 16.22, "Если поможешь нам поубивать этих злобных тварей, мы, тролли Малака'джина, будем перед тобой в долгу." }, { 23.06, "Тут, в Каменном Когте, пауки повсюду – ступай на север, и увидишь, о чём я толкую." } } }, t = { d = 11.2, v = "troll-male#78", n = { x = 112 }, c = { x = { { 0.00, "О, вот и славненько! Ну хорошо, авось сегодня к нам на ужин меньше незваных гостей налезет." }, { 7.64, "Тысяча благодарностей. Мы у тебя в долгу навечно." } } } } },
    [6462] = { d = 43.1, g = 1, v = "troll-male", n = { m = 409, f = 409 }, c = { m = { { 0.00, "Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам'гара! Эти подлые фурболги!" }, { 14.97, "Я горюю по убитым братьям и сёстрам – но мы ещё встретимся в загробной жизни." }, { 21.24, "Однако, их тролльские обереги в нашем мире весьма ценятся. Меня бесит, что ими завладели фурболги!" }, { 29.76, "Ты должен вернуть эти обереги! Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара." } }, f = { { 0.00, "Мои сородичи шли сюда со священными тролльскими оберегами, но фурболги Колючего Меха напали на них и перебили прежде, чем они успели добраться до Зорам'гара! Эти подлые фурболги!" }, { 14.97, "Я горюю по убитым братьям и сёстрам – но мы ещё встретимся в загробной жизни." }, { 21.24, "Однако, их тролльские обереги в нашем мире весьма ценятся. Меня бесит, что ими завладели фурболги!" }, { 29.76, "Ты должна вернуть эти обереги! Они находятся в сундуках в Крепости Колючего Меха, в пещере на окраине Деревни Колючего Меха, к северу от Астранаара." } } }, t = { d = 15.5, g = 1, v = "troll-male", n = { m = 120, f = 121 }, c = { m = { { 0.00, "Ты их нашёл! О, благодарю тебя! Ты представить себе не можешь, что ты сделал для меня." }, { 9.19, "Тролль без оберега что орк без боевых шрамов... Пустое место, а не тролль." } }, f = { { 0.00, "Ты их нашла! О, благодарю тебя! Ты представить себе не можешь, что ты сделала для меня." }, { 7.37, "Тролль без оберега что орк без боевых шрамов... Пустое место, а не тролль." } } } } },
    [6481] = { d = 37.6, g = 1, v = "tauren-male#67", n = { x = 310 }, c = { m = { { 0.00, "Благодаря тебе, герой, мы узнали, что этой земле грозит великая опасность." }, { 7.19, "Резонитовая ёмкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок." }, { 17.94, "Я изменил своей шаманской силой принесённые тобой кристаллы." }, { 23.77, "Возьми кристалл резинита и разбей резонитовую ёмкость, где спит земельник." }, { 31.52, "Сразу после пробуждения Гоггерок будет ослаблен... Убей его!" } }, f = { { 0.00, "Благодаря тебе, героиня, мы узнали, что этой земле грозит великая опасность." }, { 7.33, "Резонитовая ёмкость, найденная тобою в пещере, служит вместилищем для спящего земельника по имени Гоггерок." }, { 18.08, "Я изменил своей шаманской силой принесённые тобой кристаллы." }, { 23.90, "Возьми кристалл резинита и разбей резонитовую ёмкость, где спит земельник." }, { 31.66, "Сразу после пробуждения Гоггерок будет ослаблен... Убей его!" } } }, t = { d = 31.2, g = 1, v = "tauren-male#67", n = { x = 244 }, c = { m = { { 0.00, "Это хорошие новости, герой! Я опасался того, что земельник может сделать с Калимдором." }, { 8.71, "Уничтожение Гоггерока было задачей, достойной истинного героя." }, { 14.99, "Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный герой." }, { 25.94, "Прими это как заслуженную и достойную награду." } }, f = { { 0.00, "Это хорошие новости, героиня! Я опасался того, что земельник может сделать с Калимдором." }, { 8.77, "Уничтожение Гоггерока было задачей, достойной истинного героя." }, { 15.04, "Но тебе удалось справиться с этим, и теперь и Каменный Коготь, и Калимдор перед тобой в долгу, благородный героиня." }, { 26.36, "Прими это как заслуженную и достойную награду." } } } } },
    [6482] = { d = 27.1, g = 1, v = "tauren-male#67", n = { x = 190 }, c = { m = { { 0.00, "А? Ты кто?" }, { 1.50, "путник? Ты не фурболг. Они прокляты! Они подумали, что я медведь, и схватили меня, а теперь морят голодом! Я погибаю..." }, { 14.17, "Помоги мне сбежать, затем поговори с моей сестрой Ями на Заставе Расщеплённого Дерева к востоку отсюда. путник! Мне надо сбежать!" } }, f = { { 0.00, "А? Ты кто?" }, { 1.50, "путница? Ты не фурболг. Они прокляты! Они подумали, что я медведь, и схватили меня, а теперь морят голодом! Я погибаю..." }, { 13.17, "Помоги мне сбежать, затем поговори с моей сестрой Ями на Заставе Расщеплённого Дерева к востоку отсюда. путница! Мне надо сбежать!" } } }, t = { d = 23.0, g = 1, v = "tauren-female#72", n = { m = 236, f = 236 }, c = { m = { { 0.00, "Ты нашёл моего брата! Его схватили фурболги Колючего Меха? Какая страшная весть!" }, { 6.25, "Хотя многие фурболги существа благородные, эти – извращённые твари." }, { 11.76, "Спасибо за спасение брата. Страшно подумать, как они обходились с бедняжкой Руулом!" }, { 18.34, "Наверняка после таких испытаний он будет долго спать..." } }, f = { { 0.00, "Ты нашла моего брата! Его схватили фурболги Колючего Меха? Какая страшная весть!" }, { 6.42, "Хотя многие фурболги существа благородные, эти – извращённые твари." }, { 11.93, "Спасибо за спасение брата. Страшно подумать, как они обходились с бедняжкой Руулом!" }, { 18.51, "Наверняка после таких испытаний он будет долго спать..." } } } } },
    [6503] = { d = 26.9, v = "troll-male", n = { x = 267 }, c = { x = { { 0.00, "Мы получили донесение, что вестницы Ясеневого леса не так давно покинули Аванпост Среброкрылых и теперь шныряют в лесу у наших границ." }, { 10.89, "Нам не надо, чтобы они разнюхивали что да как с нашей обороной!" }, { 16.34, "Проникни в лес к югу отсюда и к востоку от альянсовского Аванпоста Среброкрылых. Найди и перебей лазутчиц, а потом возвращайся." } } }, t = { d = 14.4, v = "troll-male", n = { x = 129 }, c = { x = { { 0.00, "Очень хорошо. Твоё охотничье мастерство впечатляет..." }, { 4.68, "Потеря лазутчиц малость притупит нюх Альянса, а ежели им разведданных не хватит, то вряд ли они нападут." } } } } },
    [6504] = { d = 28.2, v = "orc-female#58", n = { x = 316 }, c = { x = { { 0.00, "Этот резак я только что получила из Кабестана и как раз возвращалась на лесозаготовки Песни Войны, на своё рабочее место." }, { 8.43, "Мне дали нструкцию к резаку, но по дороге назад у меня её вырвало из рук порывом ветра." }, { 14.60, "Все страницы разлетелись, и осталась у меня одна обложка." }, { 19.01, "Где теперь эти страницы носит, одним предкам ведомо... Но как я резаком-то без них пользоваться буду? Не найдёшь ли их для меня?" } } }, t = { d = 5.2, v = "orc-female#58", n = { x = 52 }, c = { x = { { 0.00, "Не сильна я в чтении... Но теперь я могу вернуться к работе! Спасибо!" } } } } },
    [6523] = { d = 20.4, v = "tauren-female#72", n = { x = 195 }, c = { x = { { 0.00, "Спасибо большое за спасение! Мы должны уходить побыстрее, прежде чем они обнаружат, что я на свободе." }, { 7.98, "Я прошу сопроводить меня до Лагеря Апарахе. Оттуда я уже знаю, куда идти." }, { 14.07, "Мой отец, Макаба Плоское Копыто, наверное, уже отчаялся узнать, где я." } } }, t = { d = 5.6, g = 1, v = "tauren-male", n = { x = 34 }, c = { m = { { 0.00, "Кайя жива! путник, я благодарю тебя за её спасение!" } }, f = { { 0.00, "Кайя жива! путница, я благодарю тебя за её спасение!" } } } } },
    [6541] = { d = 22.1, g = 1, v = "orc-male#60", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Ты когда-нибудь бывал в Ясеневом лесу, на севере?" }, { 3.46, "Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ." }, { 11.68, "Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне." }, { 17.01, "Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." } }, f = { { 0.00, "Ты когда-нибудь бывала в Ясеневом лесу, на севере?" }, { 3.36, "Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ." }, { 11.58, "Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне." }, { 16.90, "Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." } } }, t = { d = 14.7, v = "orc-male", n = { x = 170 }, c = { x = { { 0.00, "Ясеневый лес – разделённый войной край, но наши недавние усилия увенчались успехом." }, { 5.94, "Мы основали заставу не только на Зорамском взморье, но ещё прямо к северу отсюда построили заставу Расщеплённого Дерева." } } } } },
    [6542] = { d = 22.1, g = 1, v = "orc-male#60", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Ты когда-нибудь бывал в Ясеневом лесу, на севере?" }, { 3.46, "Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ." }, { 11.68, "Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне." }, { 17.01, "Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." } }, f = { { 0.00, "Ты когда-нибудь бывала в Ясеневом лесу, на севере?" }, { 3.36, "Орда недавно организовала заставу на Зорамском взморье, и нам всегда нужны новобранцы для обороны новых границ." }, { 11.58, "Если тебе это по сердцу, найди Кадрака в северных Степях, в сторожевой башне." }, { 16.90, "Он руководит кампанией в Ясеневом лесу и может дать тебе поручение." } } }, t = { d = 14.8, v = "orc-male", n = { x = 171 }, c = { x = { { 0.00, "Ясеневый лес – разделённый войной край, но наши недавние усилия увенчались успехом." }, { 5.82, "Мы основали не только заставу на Зорамском взморье, но и ещё прямо к северу отсюда построили заставу Расщеплённого Дерева." } } } } },
    [6543] = { d = 33.7, v = "orc-male", n = { x = 383 }, c = { x = { { 0.00, "Недавно я отправил в Ясеневый лес нескольких разведчиков." }, { 4.23, "Мне нужен гонец, чтобы доставить им приказы и вернуться с отчётом об их наблюдениях." }, { 10.40, "Первый твой пункт – форт Зорам'гар, что на западном побережье на Зорамском взморье. Там ты найдёшь первого гонца." }, { 18.27, "Так же тебе придётся заглянуть на заставу Расщеплённого Древа, что на севере и к востоку по дороге близ Азшары." }, { 25.99, "Там найдёшь разведчика и сопровождающего." }, { 29.35, "Передай каждому указания и забери у них новые донесения." } } }, t = { d = 13.5, v = "orc-male", n = { x = 157 }, c = { x = { { 0.00, "Вижу, на тебя можно положиться. Эти новые сведения чрезвычайно важны для осуществления планов по расширению нашего присутствия в Ясеневом лесу." }, { 10.18, "Теперь мы можем разработать следующий шаг." } } } } },
    [6544] = { d = 32.7, g = 1, v = "orc-male", n = { x = 352 }, c = { m = { { 0.00, "Эй! герой! Иди-ка сюда!" }, { 2.46, "Мы с ребятами хотим напасть на Аванпост Среброкрылых на западе. Наша цель – их командир, Дариэль Лунное Пламя." }, { 10.21, "Разведчики говорят, что форт здорово защищён, там полно часовых и воинов. Славная будет драка!" }, { 17.29, "Хочешь помочь нам, и разделить нашу славу?" }, { 20.38, "Если пойдёшь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку." }, { 27.98, "Ты найдёшь его в Расщеплённом Дереве. Что скажешь? Пойдёшь с нами?" } }, f = { { 0.00, "Эй! героиня! Иди-ка сюда!" }, { 2.39, "Мы с ребятами хотим напасть на Аванпост Среброкрылых на западе. Наша цель – их командир, Дариэль Лунное Пламя." }, { 10.13, "Разведчики говорят, что форт здорово защищён, там полно часовых и воинов. Славная будет драка!" }, { 17.22, "Хочешь помочь нам, и разделить нашу славу?" }, { 20.31, "Если пойдёшь с нами, то когда победим, сможешь доложить о наших успехах моему начальнику, Эртогу Лютоклыку." }, { 27.91, "Ты найдёшь его в Расщеплённом Дереве. Что скажешь? Пойдёшь с нами?" } } }, t = { d = 15.0, g = 1, v = "orc-male#60", n = { m = 163, f = 164 }, c = { m = { { 0.00, "Значит, Тореку дельце удалось! Хорошая работа. Ночные эльфы – достойные враги. Худоваты на вид, но сильные да яростные!" }, { 8.28, "Видать, драка была красивая, посмотреть бы..." }, { 11.70, "Надеюсь, парочку шрамов-то ты заработал?" } }, f = { { 0.00, "Значит, Тореку дельце удалось! Хорошая работа. Ночные эльфы – достойные враги. Худоваты на вид, но сильные да яростные!" }, { 8.28, "Видать, драка была красивая, посмотреть бы..." }, { 11.70, "Надеюсь, парочку шрамов-то ты заработала?" } } } } },
    [6548] = { d = 20.9, v = "tauren-male", n = { x = 194 }, c = { x = { { 0.00, "Клан Зловещего Тотэма напал на мою деревню и убил почти всех жителей." }, { 6.13, "Я сразил столько нападавших, сколько мог, но едва спас собственную жизнь." }, { 12.33, "Всё, чего я желаю – это чтобы как можно больше этих негодяев умерло. Ты найдёшь их к западу отсюда." } } }, t = { d = 8.6, v = "tauren-male", n = { x = 77 }, c = { x = { { 0.00, "Я благодарю тебя... но я никогда не забуду того, что клан Зловещего Тотэма сделал с моей деревней." } } } } },
    [6561] = { d = 33.2, v = "nightelf-male#54", n = { x = 373 }, c = { x = { { 0.00, "Силы оставили меня. Мне необходима твоя помощь!" }, { 3.59, "В давние времена на этом месте был храм Элуны." }, { 6.81, "К несчастью, он был разрушен, когда порча Древнего бога просочилась из-под земли и осквернила священный лунный колодец." }, { 15.39, "Аку'май, слуга Древнего бога, поднялся из глубин." }, { 19.36, "Сектанты Сумеречного Молота объединились с нагами в борьбе за эти земли. Сектанты, ведомые Келрисом, приносят Аку'май невинные жертвы." }, { 28.76, "Убей Келриса и принеси его голову Башане в Громовой Утёс." } } }, t = { d = 35.1, g = 1, v = "tauren-female#71", n = { m = 310, f = 313 }, c = { m = { { 0.00, "Келрису много раз удавалось ускользнуть от Серебряного Рассвета." }, { 5.50, "Его считали мёртвым или пропавшим без вести." }, { 9.35, "Положив конец его власти, ты спас жизнь многих." }, { 13.54, "Слава Матери-Земле! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу!" }, { 20.95, "Ты совершил великий подвиг. Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам. Благодарю тебя." } }, f = { { 0.00, "Келрису много раз удавалось ускользнуть от Серебряного Рассвета." }, { 5.50, "Его считали мёртвым или пропавшим без вести." }, { 9.35, "Положив конец его власти, ты спасла жизнь многих." }, { 13.72, "Слава Матери-Земле! Нет прощенья тем, кто приносит невинные жертвы Древнему Богу!" }, { 21.13, "Ты совершила великий подвиг. Келрис был порождением зла, он стремился повергнуть наш мир в хаос, поклоняясь Старым Богам. Благодарю тебя." } } } } },
    [6562] = { d = 39.4, g = 1, v = "elemental-water", n = { m = 266, f = 266 }, c = { m = { { 0.00, "Дже'неу Санкри нужна помощь. Он в форте Зорам'гар в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор." }, { 13.25, "Ты можешь добраться до него через Утёс Ветрорезов или идя на север через Степи." }, { 21.07, "Зорамское взморье лежит далеко на западе от леса. Будь осторожен. Там обитают такие силы, от которых тёплого приёма не жди." } }, f = { { 0.00, "Дже'неу Санкри нужна помощь. Он в форте Зорам'гар в Ясеневом лесу. Этот лес ночных эльфов находится к северу от Когтистых гор." }, { 17.43, "Ты можешь добраться до него через Утёс Ветрорезов или идя на север через Степи." }, { 25.25, "Зорамское взморье лежит далеко на западе от леса. Будь осторожна. Там обитают такие силы, от которых тёплого приёма не жди." } } }, t = { d = 5.2, v = "troll-male", n = { x = 51 }, c = { x = { { 0.00, "Тебя послал Цунаман? Великолепно. Тогда нам есть что обсудить." } } } } },
    [6563] = { d = 40.3, v = "troll-male", n = { x = 385 }, c = { x = { { 0.00, "В начале туннелей Непроглядной Пучины по стенам пещер можно найти большие сапфировые друзы." }, { 7.59, "Недавно было замечено, что эти кристаллы собирают наги." }, { 12.26, "Пока не станет ясно, зачем им это, сдаётся мне, что надо наг этой возможности лишить." }, { 20.60, "В кристаллах этих содержится великая сила стихий, и если их применить не как должно, то они могут стать мощным чародейским ингредиентом." }, { 31.95, "Ты мне не поможешь? Непроглядная Пучина находится на Зорамском взморье к северу от нашей заставы." } } }, t = { d = 19.2, v = "troll-male", n = { x = 169 }, c = { x = { { 0.00, "Хорошая работа. Это те самые кристаллы, о которых я говорил. Как интригующе..." }, { 6.72, "Я чувствую в них силу. К ним тянутся духи воды. Для чего бы наги ни собирались их использовать..." }, { 15.38, "Ладно, хорошо, что они больше не в их руках." } } } } },
    [6564] = { d = 33.3, v = "human-male#114", n = { x = 346 }, c = { x = { { 0.00, "На смятом обрывке бумаги кое-как нацарапано :" }, { 3.66, "\"Да, вели всем жрицам приносить мне эти кристаллы." }, { 7.52, "В них обитают могучие духи элементалей воды, и они весьма помогут нашим аквамантам в призывании духов." }, { 15.72, "Овладев силой, заключённой в кристаллах, мы сумеем умилостивить Аку'май." }, { 21.31, "И однажды настанет день, когда мы накопим достаточно сил, чтобы вернуть Аку'май к нам, и мир вернётся в величайшую свою эпоху! Эпоху власти Древних богов!\"" } } }, t = { d = 10.7, v = "troll-male", n = { x = 94 }, c = { x = { { 0.00, "Это и правда интересно. Я рад, что ты принёс мне эту записку." }, { 5.46, "Теперь мы знаем, как зовут причину наших бед... Лоргус Джетт!" } } } } },
    [6565] = { d = 34.3, g = 1, v = "troll-male", n = { m = 337, f = 337 }, c = { m = { { 0.00, "Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план." }, { 7.22, "Клан Сумеречного Молота не понимает духов Природы. Они верят в Древних богов – богов хаоса и разрушения, побеждённых давным-давно." }, { 17.61, "Нельзя дать этому Лоргусу добиться своего! Ты должен оставновить его. Мне самому этого не сделать – я слишком слаб." }, { 27.44, "Ступай в Непроглядную Пучину, найди и убей его! А потом возвращайся в Зорам'гар." } }, f = { { 0.00, "Мы не можем допустить, чтобы этот последователь Сумеречного Молота выполнил свой план." }, { 7.22, "Клан Сумеречного Молота не понимает духов Природы. Они верят в Древних богов – богов хаоса и разрушения, побеждённых давным-давно." }, { 17.61, "Нельзя дать этому Лоргусу добиться своего! Ты должна оставновить его. Мне самому этого не сделать – я слишком слаб." }, { 27.23, "Ступай в Непроглядную Пучину, найди и убей его! А потом возвращайся в Зорам'гар." } } }, t = { d = 21.4, v = "troll-male", n = { x = 206 }, c = { x = { { 0.00, "Прекрасно!!! Хвала тебе. Может, мы и не окончательно разобрались с Сумеречным Молотом, но по крайней мере один их план по возвращению в могуществе своём Древних богов мы нарушили." }, { 14.84, "Кто знает, какие ещё замыслы них на уме, но пока мы можем вздохнуть свободно." } } } } },
    [6571] = { d = 33.3, v = "orc-male#60", n = { x = 380 }, c = { x = { { 0.00, "Нам на лесозаготовках Песни Войны страшно не хватает кое-чего!" }, { 4.79, "У Пиксель на заставе Расщеплённого Древа наш груз лезвий для пил." }, { 9.56, "За ящиком топоров от управляющего пристанью Подгребая придётся сгонять в Пиратскую бухту." }, { 16.12, "А получить груз масла и верёвок будет ещё труднее." }, { 19.79, "Верёвку стянули фурболги Колючего Меха и Гиблой Чащи, а сатиры перехватили партию масла, и теперь изводят его на свои гадкие ритуалы на Ночной поляне, Сатирнааре и Ксавиане! Ты мне поможешь?" } } }, t = { d = 6.9, g = 1, v = "orc-male#60", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Замечательно! Ты избавил меня от больших забот!" }, { 3.83, "Но не думай, что я буду неблагодарен!" } }, f = { { 0.00, "Замечательно! Ты избавила меня от больших забот!" }, { 3.88, "Но не думай, что я буду неблагодарен!" } } } } },
    [6621] = { d = 38.4, g = 1, v = "orc-male", n = { x = 422 }, c = { m = { { 0.00, "К юго-востоку от Астранаара живёт ещё одно племя фурболгов, Гиблая Чаща." }, { 5.05, "Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу." }, { 11.57, "Продемонстрировав им силу, мы сможем эту угрозу ликвидировать." }, { 16.36, "Бери этот штандарт, иди в деревлю Гиблой Чащи и поставь его на их тотэмном кургане." }, { 22.36, "Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени." }, { 30.76, "Принеси мне тотэм, что будет на нём." }, { 33.78, "Собирай друзей. С этим делом герой-одиночка не справится." } }, f = { { 0.00, "К юго-востоку от Астранаара живёт ещё одно племя фурболгов, Гиблая Чаща." }, { 5.05, "Они не так многочисленны, как Колючий Мех, но их ярость в будущем может представлять угрозу." }, { 11.57, "Продемонстрировав им силу, мы сможем эту угрозу ликвидировать." }, { 16.36, "Бери этот штандарт, иди в деревлю Гиблой Чащи и поставь его на их тотэмном кургане." }, { 22.36, "Они попытаются уничтожить штандарт, но ты держись, пока не появится их вождь, Мургут. Он захочет отстоять честь племени." }, { 30.76, "Принеси мне тотэм, что будет на нём." }, { 33.78, "Собирай друзей. С этим делом героиня-одиночка не справится." } } }, t = { d = 13.9, g = 1, v = "orc-male", n = { m = 131, f = 132 }, c = { m = { { 0.00, "Хорошая работа. Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбил в их головы: С Ордой шутки плохи." }, { 9.67, "Теперь это племя долго не осмелится досаждать нам." } }, f = { { 0.00, "Хорошая работа. Бросив вызов Гиблой Чаще и победив их вождя, ты крепко вдолбила в их головы: С Ордой шутки плохи." }, { 9.90, "Теперь это племя долго не осмелится досаждать нам." } } } } },
    [6627] = { d = 11.2, g = 1, v = "tauren-male#68", n = { m = 107, f = 110 }, c = { m = { { 0.00, "Ты принёс мне книгу, и я должен задать тебе вопрос. Ты готов?" }, { 5.12, "Спешить нам некуда, так что не торопись. Можешь ответить мне в любое время." } }, f = { { 0.00, "Ты принесла мне книгу, и я должен задать тебе вопрос. Ты готова?" }, { 5.17, "Спешить нам некуда, так что не торопись. Можешь ответить мне в любое время." } } }, t = { d = 8.1, g = 1, v = "tauren-male#68", n = { m = 64, f = 65 }, c = { m = { { 0.00, "Отличная работа, герой. Ты изучил книгу как следует и прошёл ещё одно наше испытание." } }, f = { { 0.00, "Отличная работа, героиня. Ты изучила книгу как следует и прошла ещё одно наше испытание." } } } } },
    [6628] = { d = 21.0, g = 1, v = "scourge-male#83", n = { m = 214, f = 216 }, c = { m = { { 0.00, "Вот мы и встретились снова. Ты проявил недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос." }, { 11.69, "Когда будешь готов, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда." } }, f = { { 0.00, "Вот мы и встретились снова. Ты проявила недюжинные способности при прохождении моих испытаний, и теперь мне осталось только задать тебе последний вопрос." }, { 12.73, "Когда будешь готова, подойди и поговори со мной, но перед этим как следует подготовься. Спешить нам некуда." } } }, t = { d = 7.9, v = "scourge-male#83", n = { x = 81 }, c = { x = { { 0.00, "Отличная работа. Я сомневался, что у тебя хватит терпения изучить этот текст, но ты дал верный ответ." } } } } },
    [6629] = { d = 28.1, v = "tauren-male", n = { x = 273 }, c = { x = { { 0.00, "Что ж, с негодяями из клана Зловещего Тотэма тебе удалось расправиться отлично." }, { 6.23, "Но Грундиг Тёмное Облако и его личная банда громил куда хуже. Именно он возглавлял то жестокое нападение на мою деревню." }, { 17.06, "Если осмелишься, то найдёшь его на Заставе Зловещего Тотэма чуть дальше по дороге на запад." }, { 24.13, "Убей его, и я буду вечно тебе признателен." } } }, t = { d = 8.1, g = 1, v = "tauren-male", n = { x = 60 }, c = { m = { { 0.00, "Грундиг Тёмное Облако мёртв! путник, за это деяние я буду вечно признателен тебе!" } }, f = { { 0.00, "Грундиг Тёмное Облако мёртв! путница, за это деяние я буду вечно признателен тебе!" } } } } },
    [6641] = { d = 34.7, v = "orc-male", n = { x = 365 }, c = { x = { { 0.00, "Ворша Хлестунья... это омерзительная гидра, что рыщет в морях..." }, { 4.74, "Она нападает на нашу заставу почём зря, уничтожая всё на своём пути." }, { 10.01, "Но я готов драться. Я готов уничтожить гидру и положить конец её нападениям на Зорам'гар." }, { 17.35, "Наги почитают эту гадкую тварь и поддерживают в её честь пламя на жаровне, что находится на острове у побережья." }, { 25.36, "Думаю, если мы её загасим, то разъярённая Ворша вылезет из моря." }, { 30.39, "Нам понадобится помощь, так что приведи крепких друзей." } } }, t = { d = 14.6, v = "orc-male", n = { x = 154 }, c = { x = { { 0.00, "С тех пор, как я сюда прибыл, я пережил много нападений наг." }, { 4.90, "Мне прямо легче на душе становится от мысли, что Ворша больше не будет разгуливать где ей вздумается. Мы в большом долгу перед тобой." } } } } },
    [6661] = { d = 24.3, v = "gnome-male", n = { x = 258 }, c = { x = { { 0.00, "Эй ты, стой, да? Ррры!.. Зарррработать хочешь? У нас тут большая проблема с крысами и не хватает умелых рук." }, { 8.32, "Что ты там болтаешь? Всё, что от тебя требуется – взять эту флейту крысолова и сыграть подходящую мелодию." }, { 15.60, "Они пойдут за тобой хоть на край света!" }, { 18.81, "Но это лишнее – ты просто поймай пяток и принеси, они нужны нам живыми. Ррррр..." } } }, t = { d = 8.6, v = "gnome-male", n = { x = 91 }, c = { x = { { 0.00, "Ха, хорошо сделанная работёнка, молодец! Моему братцу они нужны свеженькими, чтобы приготовить из них котлеты." } } } } },
    [6662] = { d = 25.5, v = "gnome-male", n = { x = 294 }, c = { x = { { 0.00, "Мой братишка Нипси занимается производством котлет из подземных крыс на том конце подземки." }, { 6.29, "Надо, чтобы ты доставил этот ящик с крысами к нему, пока они не протухли. Так что давай, двигай!" }, { 13.09, "Ты ведь ездил раньше на поезде, да? Это очень просто. Заходи, когда поезд прибудет – и наслаждайся поездкой." }, { 20.32, "Главное, не высовывай руки-ноги, не то на всю жисть калекой останешься." } } }, t = { d = 16.7, v = "gnome-male", n = { x = 189 }, c = { x = { { 0.00, "Бедняга Монти. После того, что случилось в Гномрегане, он сам на себя не похож." }, { 5.27, "Этот парень океана в жизни не видал, а туда же – в пираты метит." }, { 9.87, "Нипси вздыхает. Ну, по крайней мере, он обеспечивает непрерывные поставки этих дерганых тварей." } } } } },
    [6681] = { d = 28.2, g = 1, v = "human-male", n = { m = 323, f = 327 }, c = { m = { { 0.00, "Чёрный Ворон очень заинтересовался тобой, юный вор. Мы наблюдали. Тебе не хватает ловкости, но это преходяще." }, { 7.88, "Если ты хочешь стать учеником мастера Чёрного Ворона и членом Лиги убийц, стоит только принести печать Чёрного Ворона (приложенную к этому письму) в поместье Чёрный Ворон." }, { 19.94, "Первым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость. С уважением, Фахрад." } }, f = { { 0.00, "Чёрный Ворон очень заинтересовался тобой, юная воришка. Мы наблюдали. Тебе не хватает ловкости, но это преходяще." }, { 8.15, "Если ты хочешь стать ученицей мастера Чёрного Ворона и членом Лиги убийц, стоит только принести печать Чёрного Ворона (приложенную к этому письму) в поместье Чёрный Ворон." }, { 20.18, "Первым заданием будет найти его среди холмов Хилсбрада и тем самым доказать свою ловкость. С уважением, Фахрад." } } }, t = { d = 16.3, g = 1, v = "human-male", n = { m = 178, f = 183 }, c = { m = { { 0.00, "Прекрасно сделано, юный вор." }, { 2.41, "Тебя, знаешь ли, ждёт длинное путешествие. Длинное и выгодное. Готов ли ты принять свою судьбу из рук мастеров Чёрного Ворона?" }, { 11.50, "Поговори со стражниками снаружи. Они подскажут тебе что делать." } }, f = { { 0.00, "Прекрасно сделано, юная воришка." }, { 2.48, "Тебя, знаешь ли, ждёт длинное путешествие. Длинное и выгодное. Готова ли ты принять свою судьбу из рук мастеров Чёрного Ворона?" }, { 11.63, "Поговори со стражниками снаружи. Они подскажут тебе что делать." } } } } },
    [6721] = { d = 16.5, g = 1, v = "dwarf-male", n = { m = 192, f = 193 }, c = { m = { { 0.00, "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга." }, { 8.97, "Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." } }, f = { { 0.00, "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга." }, { 9.00, "Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." } } }, t = { d = 1.2, v = "nightelf-male#54", n = { x = 6 }, c = { x = { { 0.00, "Да, пора." } } } } },
    [6722] = { d = 16.5, g = 1, v = "dwarf-male", n = { m = 192, f = 193 }, c = { m = { { 0.00, "Привет тебе, юный охотник. Ты кажешься мне достаточно опытным, чтобы научиться обращаться с животным и обрести верного друга." }, { 8.93, "Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." } }, f = { { 0.00, "Привет тебе, юная охотница. Ты кажешься мне достаточно опытной, чтобы научиться обращаться с животным и обрести верного друга." }, { 8.87, "Тебе надо повидаться с Дазаларом в Доланааре. Он научит тебя, как обрести собственного питомца и спутника." } } } },
    [6921] = { d = 43.8, v = "troll-male", n = { x = 438 }, c = { x = { { 0.00, "Эти негодяи из Сумеречного Молота пробрались в Руины святилища Луны Непроглядной Пучины." }, { 7.46, "Их присуствие приведёт лишь к тому, что Стихии озлобятся на нас. Если это так и оставить, то они захватят эти места навсегда." }, { 17.85, "Ступай в Непроглядную Пучину и найди в руинах глубинный камень. Он должен быть где-то поблизости в воде." }, { 26.30, "В нём находится глубинный сердечник – устройство, которое при надлежащем считывании излагает историю всей деятельности Стихий." }, { 36.43, "Если я его получу, мы со Служителями Земли, возможно, сумеем как-нибудь остановить их!" } } }, t = { d = 31.3, g = 1, v = "troll-male", n = { m = 301, f = 304 }, c = { m = { { 0.00, "Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь." }, { 10.05, "Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить." }, { 19.73, "Ты сегодня хорошо потрудился, и Служители Земли весьма благодарны тебе за помощь." }, { 26.34, "Ты и всей Орде помог, и имеешь право гордиться собой." } }, f = { { 0.00, "Это именно то, что мне было нужно! Глубинный сердечник – неиссякаемая кладезь информации, которую мы сможем оттуда извлечь." }, { 10.05, "Что бы ни затевал Сумеречный Молот – и уж поверь мне, ничего хорошего – мы с моими товарищами сумеем это выяснить." }, { 19.73, "Ты сегодня хорошо потрудилась, и Служители Земли весьма благодарны тебе за помощь." }, { 26.44, "Ты и всей Орде помогла, и имеешь право гордиться собой." } } } } },
    [6922] = { d = 30.6, v = "human-male#114", n = { x = 321 }, c = { x = { { 0.00, "Сражённый элементаль воды оставил после себя странную сферу." }, { 4.72, "Вы предполагаете, что этот предмет каким-то образо подпитывал тварь энергией. Внутри сферы плещется грязная на вид жидкость." }, { 14.38, "Сама сфера вроде бы не поддаётся никаким физическим воздействиям." }, { 19.61, "Если кто и сможет понять, что это за штука, то это Дже'неу Санкри из Служителей Земли." }, { 26.33, "Он находится в форте Орды Зорам'гар в Ясеневом лесу." } } }, t = { d = 35.2, g = 1, v = "troll-male", n = { m = 336, f = 339 }, c = { m = { { 0.00, "Ого... вот это находка." }, { 2.07, "Говоришь, ты добыл это из барона Акваниса в Непроглядной Пучине?" }, { 7.33, "Барон Акванис давно уже считается осквернённой силой Стихии, а этот шар даст понять, что именно повергло его в скверну." }, { 17.23, "Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать." }, { 26.35, "Хорошо, что ты принёс эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли." } }, f = { { 0.00, "Ого... вот это находка." }, { 2.07, "Говоришь, ты добыла это из барона Акваниса в Непроглядной Пучине?" }, { 7.37, "Барон Акванис давно уже считается осквернённой силой Стихии, а этот шар даст понять, что именно повергло его в скверну." }, { 17.27, "Хотя я не удивлюсь, если это окажется клан Сумеречного Молота, зато мы узнаем, как они сумели это сделать." }, { 26.39, "Хорошо, что ты принесла эту штуку мне. Прошу – прими это вместе с горячей благодарностью Служителей Земли." } } } } },
    [6961] = { d = 31.2, g = 1, v = "goblin-male#110", c = { m = { { 0.00, "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой!" }, { 5.19, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 11.39, "Предупреждать его нужно заранее, иначе подарка не дождёшься." }, { 16.02, "И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус!" }, { 24.15, "\"Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!\"" } }, f = { { 0.00, "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой!" }, { 5.19, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 11.39, "Предупреждать его нужно заранее, иначе подарка не дождёшься." }, { 16.02, "И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус!" }, { 24.00, "\"Свежие фрукты от нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!\"" } } }, t = { d = 28.8, v = "orc-male", n = { x = 296 }, c = { x = { { 0.00, "Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса!" }, { 7.46, "\"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!" }, { 18.92, "Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!" } } } } },
    [6962] = { d = 17.6, g = 1, v = "orc-male", c = { m = { { 0.00, "Эй, мальчуган, не окажешь ли услугу Дедушке Зиме?" }, { 3.96, "Дедушка Зима весь день провёл на ногах и сам не откажется угоститься." }, { 9.00, "Немного пряников и ледяного молока, чтобы запить, будут очень кстати. Ты ведь любишь дедушку? Принесёшь мне угощение?" } }, f = { { 0.00, "Эй, девчушка, не окажешь ли услугу Дедушке Зиме?" }, { 3.86, "Дедушка Зима весь день провёл на ногах и сам не откажется угоститься." }, { 8.90, "Немного пряников и ледяного молока, чтобы запить, будут очень кстати. Ты ведь любишь дедушку? Принесёшь мне угощение?" } } }, t = { d = 9.4, g = 1, v = "orc-male", c = { m = { { 0.00, "Ну, спасибо! Угодил ты Дедушке Зиме! Доброго тебе праздника Зимнего Покрова." }, { 5.81, "А вот тебе кое-что... ну, за труды, понимаешь." } }, f = { { 0.00, "Ну, спасибо! Угодила ты Дедушке Зиме! Доброго тебе праздника Зимнего Покрова." }, { 5.95, "А вот тебе кое-что... ну, за труды, понимаешь." } } } } },
    [6964] = { d = 46.5, v = "tauren-male#67", n = { x = 352 }, c = { x = { { 0.00, "Подарки, гости, угощение... чушь собачья!" }, { 4.17, "Эти гоблины искажают саму суть праздника Зимнего Покрова." }, { 9.67, "Это время возрождения – земля спит под покровом снега, которым её укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!" }, { 28.01, "Ежели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте Сагорна Гривастого Странника." }, { 38.58, "Уверен, он будет очень удивлён, что хоть кому-то история интереснее подарков." } } }, t = { d = 32.6, v = "tauren-male#68", c = { x = { { 0.00, "Праздник Зимнего Покрова, говоришь? Увы, в прежние времена для нас, тауренов, он был куда важнее." }, { 7.54, "А теперь, похоже, другие используют древние легенды, чтобы продать побольше сладостей и подарков." }, { 15.30, "Неудивительно, что Фарманда это так огорчает. Он и остальные таурены держатся за наше прошлое, как за боевое знамя." }, { 24.29, "Я лично считаю, что немного веселья никогда не помешает, но о происхождении праздника забывать нельзя." } } } } },
    [6981] = { d = 24.6, v = "human-male#114", n = { x = 255 }, c = { x = { { 0.00, "Блестящий осколок ярко-зелёный, без примесей, но под поверхностью можно видеть что-то похожее на клубы дыма." }, { 8.43, "Оторвать взгляд от этих узоров в глубине невозможно, но в то же время вы осознаете какое-то беспокойство." }, { 16.90, "Пожалуй, стоит поискать в Кабестане кого-нибудь, кто может знать больше об этом странном осколке." } } }, t = { d = 4.5, v = "tauren-female#71", n = { x = 45 }, c = { x = { { 0.00, "О... мне никогда не приходилось видеть ничего подобного..." } } } } },
    [7021] = { d = 31.7, g = 1, v = "goblin-male#110", c = { m = { { 0.00, "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре!" }, { 6.85, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 13.09, "Предупреждать его нужно заранее, иначе подарка не дождёшься." }, { 17.60, "И сам не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус!" }, { 25.63, "От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" } }, f = { { 0.00, "Весёлого Зимнего Покрова, дружок! Не забудь поздороваться с Дедушкой Зимой – он сейчас в Оргриммаре!" }, { 6.85, "Все, кто хорошо себя вёл в этом году, получат замечательные подарки в день Зимнего Покрова!" }, { 13.09, "Предупреждать его нужно заранее, иначе подарка не дождёшься." }, { 17.60, "И сама не забудь купить подарки для тех, кто хорошо себя вёл весь год. У нас богатейший выбор подарков на любой вкус!" }, { 25.59, "От нашего села да к вашему столу – вкусная и здоровая пища от Пастбищ Дымного Леса!" } } }, t = { d = 28.5, v = "orc-male", n = { x = 296 }, c = { x = { { 0.00, "Хо-хо-хо! Я – Дедушка Зима, явился к вам благодаря добросердечию работников Пастбищ Дымного Леса!" }, { 8.04, "\"Свежие фрукты от нашего села да к вашему столу, вкусная и здоровая пища из Пастбищ Дымного Леса!\" Желаю вам чудесного Зимнего Покрова!" }, { 18.71, "Все, кто хорошо себя вёл в этом году, получат лакомства от Пастбищ Дымного Леса в качестве подарка на праздник Зимнего Покрова. Уррра!" } } } } },
