    [7025] = { d = 20.9, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Эй, не окажешь ли услугу Дедушке Зиме, хм, мальчуган?" }, { 3.90, "Нет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением." }, { 12.37, "Немного пряников и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесёшь мне угощение?" } }, f = { { 0.00, "Эй, не окажешь ли услугу Дедушке Зиме, хм, девчушка?" }, { 4.00, "Нет смысла говорить о себе в третьем лице, но Дедушка Зима весь день был на ногах и хотел бы и сам полакомиться угощением." }, { 12.47, "Немного пряников и ледяного молока, чтобы запить, – и будет довольно. Ты ведь любишь дедушку и принесёшь мне угощение?" } } }, t = { d = 8.8, g = 1, v = "dwarf-male", n = { m = 90, f = 91 }, c = { m = { { 0.00, "Ну, ты и угодил Дедушке Зиме! Доброго тебе праздника Зимнего Покрова." }, { 5.15, "А вот тебе кое-что... ну, за труды, ты понимаешь." } }, f = { { 0.00, "Ну, ты и угодила Дедушке Зиме! Доброго тебе праздника Зимнего Покрова." }, { 5.21, "А вот тебе кое-что... ну, за труды, ты понимаешь." } } } } },
    [7062] = { d = 30.8, v = "dwarf-male", c = { x = { { 0.00, "Подарки, гости, угощение... чушь собачья!" }, { 3.00, "Эти гоблины искажают самую суть праздника Зимнего Покрова." }, { 7.07, "Это время возрождения – земля спит под покровом снега, которым её укутал Дедушка Зима, и это вовсе НЕ ТОТ косноязычный дурак в красном полушубке!" }, { 17.25, "Ежели вам интересно узнать, что такое на самом деле этот праздник, поспрошайте историка Карника из лиги Исследователей." }, { 25.52, "Уверен, он будет очень удивлён, что кому-то история интереснее подарков." } } }, t = { d = 30.7, v = "dwarf-male", c = { x = { { 0.00, "Говорите, праздник Зимнего Покрова? Увы, в прежние времена для нас, дворфов, он имел гораздо более весомое значение." }, { 7.89, "А теперь, похоже, другие используют легенду о Дедушке Зиме, чтобы продать побольше сладостей и подарков." }, { 15.26, "Неудивительно, что Голли так огорчает эта перемена. Он и остальные дворфы держатся за наше прошлое, как за боевое знамя." }, { 23.51, "Я лично считаю, что небольшой праздник никогда не помешает, но о его происхождении забывать нельзя." } } } } },
    [7383] = { d = 33.9, v = "nightelf-male#54", n = { x = 390 }, c = { x = { { 0.00, "Но не всё было ладно с Тельдрассилом." }, { 2.64, "Олений Шлем долго лелеял надежду вырастить новое Древо жизни и даже тщательно спланировал это мероприятие." }, { 10.77, "Но была одна небольшая проблема, с которой можно связать большинство бед Тельдрассила." }, { 17.09, "Однако, пока я об этом говорить не буду. Тебе нужно посетить последний лунный колодец, к северо-западу от Поляны Оракула." }, { 25.36, "Под ветвями Древа-оракула находится первый и самый могучий из наших колодцев. Набери воды из него и возвращайся ко мне." } } }, t = { d = 32.2, v = "nightelf-male#54", n = { x = 389 }, c = { x = { { 0.00, "Находиться в присутствии Древа-оракула... это всё равно что увидеть воплощённую мудрость. Позволь мне продолжить..." }, { 8.10, "Тельдрассил рос, и верховный друид обратился за благословением к драконам, ведь именно они благословили Нордрассил в древние времена." }, { 17.12, "Однако Ноздорму, Повелитель Времени, отказал друиду, упрекнув его в самонадеянности." }, { 22.96, "Алекстраза также отказала Оленьему Шлему, а без её благословения рост Тельдрассила стал непредсказуем, и в нём обнаружились изъяны..." } } } } },
    [7788] = { d = 27.0, g = 1, v = "nightelf-female#51", n = { m = 310, f = 310 }, c = { m = { { 0.00, "Юный герой! Миновав этот проход, ты увидишь поле яростных сражений." }, { 4.76, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 12.70, "Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!" }, { 20.76, "Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" } }, f = { { 0.00, "Юная героиня! Миновав этот проход, ты увидишь поле яростных сражений." }, { 4.84, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 12.77, "Отправляйся в Ущелье Песни Войны, чтобы оборонять Заставу Среброкрылых! Отражай нападения ордынских захватчиков!" }, { 20.84, "Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" } } } },
    [7789] = { d = 33.9, g = 1, v = "orc-male", n = { x = 360 }, c = { m = { { 0.00, "Чащобы Ясеневого леса падут пред мощью Орды, герой! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором." }, { 8.76, "Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?" }, { 16.23, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 23.51, "Разгроми Среброкрылых Часовых и заслужи почётный лощины Песни Войны. Вернись ко мне с этим знаком – и получишь награду!" } }, f = { { 0.00, "Чащобы Ясеневого леса падут пред мощью Орды, героиня! Что бы ни делали Среброкрылые Часовые, им не совладать с нашим напором." }, { 9.71, "Калимдор – это владения Орды! Как смеют они препятствовать нам пользоваться тем, что по праву наше?" }, { 17.18, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 24.46, "Разгроми Среброкрылых Часовых и заслужи почётный лощины Песни Войны. Вернись ко мне с этим знаком – и получишь награду!" } } }, t = { d = 15.3, g = 1, v = "orc-male", n = { x = 127 }, c = { m = { { 0.00, "Капитан Лободроб одобрительно порыкивает." }, { 3.22, "И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать?" }, { 12.13, "Время покажет, путник, время покажет..." } }, f = { { 0.00, "Капитан Лободроб одобрительно порыкивает." }, { 3.22, "И сколько ещё они смогут так продержаться? Сколько ещё солдат Альянса должно погибнуть, чтобы они поняли, что пора отступать?" }, { 12.13, "Время покажет, путница, время покажет..." } } } } },
    [7810] = { d = 10.0, v = "human-male#114", c = { x = { { 0.00, "Должно быть, стать мастером арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чём тут штука!" } } }, t = { d = 10.4, g = 1, v = "goblin-male", c = { m = { { 0.00, "Арр, бей-круши! Чтобы получить право называться мастером Арены, одного значка недостаточно!" }, { 6.42, "Пора тебе показать, на что ты действительно способен." } }, f = { { 0.00, "Арр, бей-круши! Чтобы получить право называться мастером Арены, одного значка недостаточно!" }, { 6.42, "Пора тебе показать, на что ты действительно способна." } } } } },
    [7905] = { d = 25.9, v = "dwarf-male", n = { x = 300 }, c = { x = { { 0.00, "Грядёт Ярмарка Новолуния! Готовься испытать все её чудеса и радости, когда она прибудет в наш город!" }, { 7.27, "Если ты поторопишься, то сможешь обменять этот сертификат на призовой купон!" }, { 12.69, "Надо только передать сертификат Гельвасу Угольному Шлюзу в ярмарочном лагере." }, { 18.40, "Сейчас ярмарка стоит рядом со Златоземьем, в Элвиннском лесу. Не упусти шанса! Отправляйся прямо сегодня!" } } }, t = { d = 18.7, v = "goblin-male", c = { x = { { 0.00, "Добро пожаловать на ярмарку Новолуния! Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов!" }, { 7.78, "Когда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы." }, { 13.54, "Чем больше вы получите купонов, тем больше выиграете призов. Вперёд!" } } } } },
    [7908] = { d = 10.0, v = "human-male#114", c = { x = { { 0.00, "Должно быть, стать мастером арены не так просто! Быть может, пират-распорядитель на Арене Гурубаши, знает, в чём тут штука!" } } } },
    [7926] = { d = 26.8, v = "orc-male", c = { x = { { 0.00, "Грядёт ярмарка Новолуния! Когда она прибудет в город, веселью и чудесам не будет конца!" }, { 6.60, "А если ты поторопишься, то сможешь обменять этот сертификат на бесплатные призовые купоны!" }, { 13.08, "Не забудь передать свой сертификат Гельвасу Угольному Шлюзу в ярмарочном лагере." }, { 19.20, "Сейчас ярмарка стоит рядом с Громовым Утёсом, в Мулгоре. Не упусти свой шанс! Отправляйся прямо сегодня!" } } }, t = { d = 18.7, v = "goblin-male", c = { x = { { 0.00, "Добро пожаловать на ярмарку Новолуния! Этот сертификат на ПЯТЬ, да, целых ПЯТЬ призовых купонов!" }, { 7.78, "Когда у вас будет их побольше, обратитесь ко мне, и я обменяю их на ценные призы." }, { 13.54, "Чем больше вы получите купонов, тем больше выиграете призов. Вперёд!" } } } } },
    [7961] = { d = 7.6, v = "human-male", n = { x = 81 }, c = { x = { { 0.00, "Кролики плодятся с бешеной скоростью! Надо что-то делать!" }, { 4.44, "Помоги нам, ты наша единственная надежда!" } } } },
    [7962] = { d = 5.5, v = "human-male", n = { x = 60 }, c = { x = { { 0.00, "Мне нужны шкурки кроликов Лекрафта. Добудь мне несколько штук. Это важно!" } } } },
    [8155] = { d = 35.3, v = "human-female#47", n = { x = 403 }, c = { x = { { 0.00, "Войну выигрывают солдаты – любой солдат вам это скажет." }, { 3.61, "Скажет он вам и то, что битва, которую ведут с плохим оружием или на пустой желудок, проиграна прежде, чем началась!" }, { 11.69, "Вот почему так важна Низина Арати. В этой низине есть ключевые точки, где сосредоточены важные ресурсы." }, { 18.62, "Металл, оружие, пища, древесина – всё это необходимо и всё это можно добыть там." }, { 24.19, "И вот чего я хочу от вас. Отправляйтесь в Низину Арати, выиграйте битву, удержав больше баз, чем это удастся врагам, и принесите мне ящик с ресурсами." } } }, t = { d = 18.0, g = 1, v = "human-female#47", n = { m = 205, f = 206 }, c = { m = { { 0.00, "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам." }, { 8.51, "Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнил, - вот как действительно выигрывают войны." } }, f = { { 0.00, "У тебя есть ресурсы! Прекрасная работа! Я пошлю их нашим интендантам, которые могут быстро разогнать их по нашим войскам." }, { 8.51, "Спасибо. Действительно, успешное выполнение миссий, подобных той, которую ты выполнила, - вот как действительно выигрывают войны." } } } } },
    [8162] = { d = 47.4, v = "scourge-male", n = { x = 492 }, c = { x = { { 0.00, "Лига Аратора не жалеет средств в попытке вновь захватить контроль над Арати." }, { 7.41, "Они, вместе со всеми расами Альянса, стекаются сейчас в эту отдалённую область, намереваясь распространить свои владения за пределы Опорного пункта." }, { 18.19, "Мы должны остановить их, а наилучшее средство для этого – захватить их припасы." }, { 24.38, "Вы, можете нам помочь. Отправляйтесь в Низину Арати, известную своими богатыми рудниками, плодородными почвами и умелыми ремесленниками." }, { 35.14, "Захватите и удерживайте под своим контролем те базы, которые сможете, выиграйте битву и возвращайтесь ко мне с ресурсами, которые вам удастся добыть." } } } },
    [8168] = { d = 35.2, v = "human-male#50", n = { x = 404 }, c = { x = { { 0.00, "Битва за Низину Арати – это битва за ресурсы и за территорию." }, { 4.02, "Ключевые точки на этой местности нужно удерживать, чтобы обеспечить наши силы поставками сырья и различных припасов." }, { 11.73, "Я отдаю вам приказ атаковать самые дальние от нашей базы в Низине Арати точки." }, { 19.02, "Совершите нападение на ферму, рудник, лесопилку и кузницу, когда они будут находиться под контролем врага." }, { 26.14, "Найдите вражеское знамя и сорвите его с флагштока!" }, { 29.84, "Когда сумеете сделать это в четырёх указанных точках, возвращайтесь ко мне." } } }, t = { d = 12.3, v = "human-male#50", n = { x = 136 }, c = { x = { { 0.00, "Я получил сообщения о ваших подвигах в Низине Арати. Отлично сработано!" }, { 5.40, "С теми, кто, как вы, присоединяется к борьбе здесь, я верю,что однажды мы вернём наши родные земли." } } } } },
    [8171] = { d = 47.1, v = "scourge-female", n = { x = 407 }, c = { x = { { 0.00, "Как вы, конечно, слышали, Лига Аратора посылает огромное количество войск в Низину Арати." }, { 8.04, "Жадные до пищи и припасов, эти идиоты из Альянса намереваются захватить под свой контроль тамошние богатые источники ресурсов." }, { 19.52, "Мы должны показать им, что Арати никогда больше не будет домом для людей!" }, { 26.67, "Отправляйтесь в Низину Арати и нападите на рудник, лесопилку, кузницу и стойла." }, { 35.05, "Сорвите с флагштоков вражеские знамёна, заявив о правах Орды на эти территории." }, { 42.58, "Идите. Доложите мне, когда выполните задание." } } }, t = { d = 22.8, g = 1, v = "scourge-female", n = { m = 203, f = 202 }, c = { m = { { 0.00, "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Молодец." }, { 6.82, "Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса." }, { 18.53, "Сделаем это и наша победа здесь обеспечена." } }, f = { { 0.00, "Разведчик Осквернителя пришёл ко мне с отчётом о твоём успехе. Умница." }, { 6.60, "Как ты знаешь, чтобы выиграть битву за Низину Арати, мы должны быть всегда бдительны и пресекать любые попытки расширения Альянса." }, { 18.22, "Сделаем это и наша победа здесь обеспечена." } } } } },
    [8290] = { d = 26.9, g = 1, v = "nightelf-female#51", n = { m = 310, f = 310 }, c = { m = { { 0.00, "Юный герой! Миновав этот проход, ты увидишь поле яростных сражений." }, { 4.67, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 12.44, "Отправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!" }, { 20.50, "Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" } }, f = { { 0.00, "Юная героиня! Миновав этот проход, ты увидишь поле яростных сражений." }, { 4.94, "Орда продолжает вырубать наши священные леса, уничтожая вечнозелёные кроны, чтобы питать свою военную машину!" }, { 12.71, "Отправляйся в ущелье Песни Войны, чтобы оборонять заставу Среброкрылых! Отражай нападения ордынских захватчиков!" }, { 20.78, "Наградой тебе будет талисман заслуг. Принеси мне такой талисман, и получишь награду!" } } } },
    [8295] = { d = 34.7, g = 1, v = "orc-male", n = { x = 379 }, c = { m = { { 0.00, "Чащобы Ясеневого леса падут перед мощью Орды, герой!" }, { 4.15, "Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды!" }, { 11.85, "Как они смеют препятствовать нам пользоваться тем, что по праву наше?" }, { 17.15, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 24.51, "Разгроми часовых из армии Среброкрылых и заслужи почётный знак ущелья Песни Войны." }, { 30.86, "Вернись ко мне с этим знаком – и получишь награду!" } }, f = { { 0.00, "Чащобы Ясеневого леса падут перед мощью Орды, героиня!" }, { 4.01, "Что бы ни делали часовые из армии Среброкрылых, им не совладать с нашим напором. Калимдор – это владения Орды!" }, { 11.71, "Как они смеют препятствовать нам пользоваться тем, что по праву наше?" }, { 17.01, "Пусть гордость вскипает в твоей груди, когда ты доблестно пресекаешь их жалкие попытки остановить Орду!" }, { 24.37, "Разгроми часовых из армии Среброкрылых и заслужи почётный знак ущелья Песни Войны." }, { 30.72, "Вернись ко мне с этим знаком – и получишь награду!" } } } },
    [8311] = { d = 29.5, v = "child-male", n = { x = 383 }, c = { x = { { 0.00, "Хотел бы я пойти потыквовинничать, но не могу – приболел." }, { 3.41, "Если ты вместо меня сходишь, я обменяю тебе сладости, что ты наберёшь, на те, что у меня уже есть." }, { 9.26, "Думаю, тебе они понравятся – они превратят тебя в разные смешные и страшные штуки!" }, { 14.38, "У каждого из хозяев таверн в больших городах есть сладости, которые они раздают на Тыквовин. Поговори с ними и выполни их задания." }, { 22.19, "А ещё в Стальгорне живёт гном по имени Талваш, и он тоже раздаёт сладости. Когда соберёшь их все, принеси мне сюда!" } } }, t = { d = 12.4, v = "child-male", n = { x = 156 }, c = { x = { { 0.00, "Ух ты, тебе удалось собрать их все! Просто супер!" }, { 3.27, "Спасибо за то, что тыквовинничал вместо меня. Вот, возьми эти тыквовинские конфетки – я уверен, ты будешь от них в восторге! Счастливого Тыквовина!" } } } } },
    [8312] = { d = 39.6, v = "human-female", n = { x = 463 }, c = { x = { { 0.00, "Я так хотела бы пойти просить сладости! Но не могу, потому что болею... Сходи вместо меня, а?" }, { 6.29, "А я с тобой потом поменяюсь: отдам те конфеты, что у меня уже есть, взамен тех, которые дадут тебе!" }, { 13.00, "Вот эта конфетка тебе наверняка понравится: она позволяет превращаться в разных существ, забавных и страшных!" }, { 20.77, "У всех хозяев таверн в больших городах непременно есть конфеты, которые они дарят на Тыквовин – надо только поговорить с ними и сделать то, что они попросят." }, { 31.02, "И троллиха по имени Кали Ремик в деревне Сен'джин тоже раздаёт конфеты. Когда соберёшь все конфеты, принеси их мне, ладно?" } } }, t = { d = 11.1, v = "human-female", n = { x = 124 }, c = { x = { { 0.00, "Ух ты! Тебе удалось собрать их все! Ты настоящий герой!" }, { 4.16, "Спасибо большое. Вот, возьми эти тыквовинские конфеты – они ужасно вкусные! Счастливого Тыквовина!" } } } } },
    [8370] = { d = 23.0, v = "orc-male", n = { x = 246 }, c = { x = { { 0.00, "Наш конфликт с Альянсом дошёл до открытой войны. Никто уже не ищет предлогов, чтобы вступить в бой." }, { 7.37, "В Низине Арати идёт простая и открытая борьба за ресурсы." }, { 12.24, "Или они попадут в руки Альянса и обратятся в оружие против нас, или их захватим мы и вооружим наши войска!" }, { 19.75, "Помоги нам захватить источник ресурсов!" } } } },
    [8374] = { d = 27.4, v = "dwarf-male", n = { x = 314 }, c = { x = { { 0.00, "Чтобы выиграть войну, мало быть умнее и хитрее противника. Зачастую победа достаётся тем, в чьих руках сосредоточены все ресурсы." }, { 9.26, "Ресурсов в Низине Арати – хоть отбавляй. Главное – захватить их первыми." }, { 14.84, "Если победа будет за Альянсом, нашим солдатам достанется больше мечей и копий." }, { 20.09, "Если Орде – те же мечи и копья обратятся против нас! Твой долг помочь Альянсу захватить Низину Арати!" } } } },
    [8399] = { d = 30.6, v = "dwarf-male", n = { x = 351 }, c = { x = { { 0.00, "Среброкрылые Часовые вступили в бой со всадниками из клана Песни Войны, стараясь защитить от них лес." }, { 7.02, "Впрочем, желание сохранить этот лес объсняется не только их любовью к природе." }, { 12.86, "Этот лес представляет собой естественную преграду для наступления сил Орды." }, { 18.16, "Без него Астранаар не продержался бы и дня, и в наши земли давно вторглась бы огромная армия Орды." }, { 25.37, "Внеси свой вклад в борьбу со всадниками из клана Песни Войны! За Альянс!" } } } },
    [8426] = { d = 21.6, v = "orc-male", n = { x = 240 }, c = { x = { { 0.00, "Битва со Среброкрылыми Часовыми за Ущелье Песни Войны имеет огромное значение." }, { 5.58, "Под предлогом охраны леса, который им вовсе не принадлежит, бойцы Альянса пытаются лишить Орду важнейшего источника древесины." }, { 14.89, "Не бывать тому! Возвращайся ко мне и приноси доказательства верной службы Орде!" } } }, t = { d = 11.0, g = 1, v = "orc-male", n = { m = 114, f = 115 }, c = { m = { { 0.00, "Великолепно! Ты показал, чего стоишь, выступив против врага в Ущелье Песни Войны!" }, { 6.23, "Да разнесутся вести о твоих подвигах по всем нашим землям." } }, f = { { 0.00, "Великолепно! Ты показала, чего стоишь, выступив против врага в Ущелье Песни Войны!" }, { 6.45, "Да разнесутся вести о твоих подвигах по всем нашим землям." } } } } },
    [8492] = { d = 18.9, g = 1, v = "dwarf-male", c = { m = { { 0.00, "Здорово, герой! На вид ты вполне пригоден к тому, чтобы принять участие в подготовке к войне!" }, { 6.28, "Нам пригодится любая помощь, так что наступил твой звёздный час." }, { 11.16, "Я собираю медные слитки стопками по двадцать штук. Дело благое, да? Ты как, хочешь оказать помощь Альянсу?" } }, f = { { 0.00, "Здорово, героиня! На вид ты вполне пригодна к тому, чтобы принять участие в подготовке к войне!" }, { 6.44, "Нам пригодится любая помощь, так что наступил твой звёздный час." }, { 11.31, "Я собираю медные слитки стопками по двадцать штук. Дело благое, да? Ты как, хочешь оказать помощь Альянсу?" } } }, t = { d = 13.5, v = "dwarf-male", c = { x = { { 0.00, "Похвально, солдат! Сейчас мы уложим эти слитки в штабель и используем их по назначению. Альянс будет гордиться тобой." }, { 8.40, "Если раздобудешь ещё стопку медных слитков, не раздумывай, неси мне." } } } } },
    [8494] = { d = 26.2, g = 1, v = "human-male#50", n = { m = 303, f = 302 }, c = { m = { { 0.00, "Эгей, мистер.; Красивые Штанишки, ты прямо отрада для моих измученных глаз." }, { 4.98, "Пока ты шатался по городам и весям в поисках приключений, у нас тут произошла прорва всего." }, { 11.05, "К примеру, Альянс вот готовится к войне в Ан'Кираже, и всем резко понадобились железные слитки... чёртова прорва железных слитков." }, { 19.46, "Можешь таскать их мне стопками по двадцать. Ну как, могу я на тебя рассчитывать, герой?" } }, f = { { 0.00, "Эгей, мисс.; Красивые Штанишки, ты прямо отрада для моих измученных глаз." }, { 5.42, "Пока ты шаталась по городам и весям в поисках приключений, у нас тут произошла прорва всего." }, { 11.54, "К примеру, Альянс вот готовится к войне в Ан'Кираже, и всем резко понадобились железные слитки... чёртова прорва железных слитков." }, { 19.96, "Можешь таскать их мне стопками по двадцать. Ну как, могу я на тебя рассчитывать, героиня?" } } }, t = { d = 17.2, v = "human-male#50", c = { x = { { 0.00, "Ну хорошо, на этот раз тебе удалось вывернуться. Пожалуй, на будущее за тобой стоит приглядывать." }, { 6.50, "Как ни тяжело это говорить, но спасибо тебе за помощь. Альянс тебя не забудет, и я тоже." }, { 12.38, "А теперь дуй-ка отсюда и лучше помоги ещё кому-нибудь в заготовках." } } } } },
    [8499] = { d = 29.2, g = 1, v = "dwarf-female#34", c = { m = { { 0.00, "Крайне любезно с твоей стороны, что ты так беспокоишься о нуждах Альянса." }, { 4.70, "Приготовления к войне идут полным ходом, и, помимо всего прочего, нам нужно очень много ториевых слитков." }, { 11.54, "Именно за их сбор я и отвечаю. Торий необходим для изготовления различных военных машин, в основном паровых танков, которые планируется доставлять по воздуху в Силитус сразу же после сборки." }, { 24.12, "За помощь в добыче ториевых слитков я была бы очень признательна, герой." } }, f = { { 0.00, "Крайне любезно с твоей стороны, что ты так беспокоишься о нуждах Альянса." }, { 4.70, "Приготовления к войне идут полным ходом, и, помимо всего прочего, нам нужно очень много ториевых слитков." }, { 11.54, "Именно за их сбор я и отвечаю. Торий необходим для изготовления различных военных машин, в основном паровых танков, которые планируется доставлять по воздуху в Силитус сразу же после сборки." }, { 24.12, "За помощь в добыче ториевых слитков я была бы очень признательна, героиня." } } }, t = { d = 13.3, g = 1, v = "dwarf-female#34", c = { m = { { 0.00, "О, спасибо тебе, герой! Огромное спасибо! Прибавилось ещё двадцать, осталось собрать ещё несчётное количество." }, { 7.26, "Альянс пред тобой в долгу. Если раздобудешь ещё двадцать слитков, обращайся ко мне." } }, f = { { 0.00, "О, спасибо тебе, героиня! Огромное спасибо! Прибавилось ещё двадцать, осталось собрать ещё несчётное количество." }, { 7.45, "Альянс пред тобой в долгу. Если раздобудешь ещё двадцать слитков, обращайся ко мне." } } } } },
    [8503] = { d = 29.7, g = 1, v = "gnome-male", c = { m = { { 0.00, "Знаешь ли ты, герой, насколько широко и разнообразно применение удавника? Как, я тебе уже об этом рассказывал? Правда?.. Ну ладно." }, { 8.67, "В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО!" }, { 15.46, "Не следует ли тебе помочь нам, как ты считаешь?" }, { 18.73, "Я понимаю, это означает, что тебе придётся остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!" } }, f = { { 0.00, "Знаешь ли ты, героиня, насколько широко и разнообразно применение удавника? Как, я тебе уже об этом рассказывал? Правда?.." }, { 8.30, "Ну ладно. В любом случае, нам нужно много этой травы, и когда я говорю так, я имею в виду действительно МНОГО!" }, { 15.77, "Не следует ли тебе помочь нам, как ты считаешь?" }, { 19.04, "Я понимаю, это означает, что тебе придётся остаться без всех этих чудесных штучек, которые можно приготовить из удавника... но ведь это ради благого дела!" } } }, t = { d = 12.2, g = 1, v = "gnome-male", c = { m = { { 0.00, "Урра! Ещё двадцатью меньше собирать. Отлично справляешься с работой! Пойду уберу травы, пока они не засохли." }, { 7.36, "Времени так мало, а удавника так много! Спасибо ещё раз, герой!" } }, f = { { 0.00, "Урра! Ещё двадцатью меньше собирать. Отлично справляешься с работой! Пойду уберу травы, пока они не засохли." }, { 7.36, "Времени так мало, а удавника так много! Спасибо ещё раз, героиня!" } } } } },
    [8505] = { d = 17.2, g = 1, v = "nightelf-male#54", c = { m = { { 0.00, "герой, цветы лилового лотоса где только не применяют." }, { 3.80, "От имени Альянса я отвечаю за заготовку лотоса в количестве, достаточном для удовлетворения всех военных нужд." }, { 11.75, "Но чтобы собирать цветы, мне нужны добровольцы. Справишься с этим заданием?" } }, f = { { 0.00, "героиня, цветы лилового лотоса где только не применяют." }, { 3.90, "От имени Альянса я отвечаю за заготовку лотоса в количестве, достаточном для удовлетворения всех военных нужд." }, { 11.85, "Но чтобы собирать цветы, мне нужны добровольцы. Справишься с этим заданием?" } } }, t = { d = 16.9, g = 1, v = "nightelf-male#54", c = { m = { { 0.00, "Твой вклад очень ценен для всех нас, герой." }, { 2.93, "Только объединив наши усилия, мы сможем отбросить армию безжалостных силитидов и одержать победу." }, { 9.66, "Даже Орда занимается сбором лилового лотоса. Если снова наберёшь этих цветов, возвращайся ко мне." } }, f = { { 0.00, "Твой вклад очень ценен для всех нас, героиня." }, { 3.06, "Только объединив наши усилия, мы сможем отбросить армию безжалостных силитидов и одержать победу." }, { 9.79, "Даже Орда занимается сбором лилового лотоса. Если снова наберёшь этих цветов, возвращайся ко мне." } } } } },
    [8509] = { d = 17.0, g = 1, v = "human-female#47", n = { x = 197 }, c = { m = { { 0.00, "Я предпочитаю говорить быстро и по существу, герой. Альянсу нужно много слёз Артаса для войны в Ан'Кираже." }, { 7.09, "Не спрашивай меня, зачем, я всего лишь выполняю приказ. Собери столько этих цветов, сколько унесёшь, и сдай мне." }, { 14.55, "Ну что, возьмёшься за это задание?" } }, f = { { 0.00, "Я предпочитаю говорить быстро и по существу, героиня. Альянсу нужно много слёз Артаса для войны в Ан'Кираже." }, { 7.05, "Не спрашивай меня, зачем, я всего лишь выполняю приказ. Собери столько этих цветов, сколько унесёшь, и сдай мне." }, { 14.51, "Ну что, возьмёшься за это задание?" } } }, t = { d = 20.5, g = 1, v = "human-female#47", c = { m = { { 0.00, "Неплохо сработано, герой. Должна сказать, я приятно удивлена." }, { 4.18, "Ты никогда бы не поверил, сколько людей приходят, обещают помочь и не возвращаются." }, { 9.83, "Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне ещё эти растения." } }, f = { { 0.00, "Неплохо сработано, героиня. Должна сказать, я приятно удивлена." }, { 4.35, "Ты никогда бы не поверила, сколько людей приходят, обещают помочь и не возвращаются." }, { 9.86, "Одну секунду, сейчас я упакую травы в ящик и прикреплю к нему бирку с твоим именем, а потом сможем поговорить на тему того, нужны ли мне ещё эти растения." } } } } },
    [8511] = { d = 33.4, g = 1, v = "dwarf-female", n = { m = 359, f = 359 }, c = { m = { { 0.00, "Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, герой. Как говорится, и с камня снимем шкуру." }, { 7.54, "Потому-то Альянс и попросил нас взяться за заготовку тонкой кожи для войны в Ан'Кираже." }, { 13.66, "Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится. Но без помощи мне никак не обойтись." }, { 22.42, "Пока я здесь за всем надзираю, тебе придётся прогуляться малость и добыть кож, а потом принести их мне." }, { 29.70, "Ну что, паренёк, возьмёшься за дело?" } }, f = { { 0.00, "Наш клан Обдирщиков Камня испокон века знал толк в снятии шкур, героиня. Как говорится, и с камня снимем шкуру." }, { 8.40, "Потому-то Альянс и попросил нас взяться за заготовку тонкой кожи для войны в Ан'Кираже." }, { 14.52, "Я слежу, чтобы кожа была хорошо выдублена, уж не знаю, для чего она там понадобится. Но без помощи мне никак не обойтись." }, { 23.28, "Пока я здесь за всем надзираю, тебе придётся прогуляться малость и добыть кож, а потом принести их мне." }, { 30.56, "Ну что, девушка, возьмёшься за дело?" } } }, t = { d = 19.1, g = 1, v = "dwarf-female", n = { x = 207 }, c = { m = { { 0.00, "Я прямо скажу, Альянску крупно повезло, что у него есть такие искушённые специалисты по свежеванию, как ты,герой." }, { 7.94, "Уж я прослежу, чтобы ни одну кожу ненароком не попортили." }, { 12.04, "Спасибо тебе – и не забудь, когда я пересчитаю кожу, справиться у меня, не требуется ли нам ещё." } }, f = { { 0.00, "Я прямо скажу, Альянску крупно повезло, что у него есть такие искушённые специалисты по свежеванию, как ты,героиня." }, { 8.08, "Уж я прослежу, чтобы ни одну кожу ненароком не попортили." }, { 12.18, "Спасибо тебе – и не забудь, когда я пересчитаю кожу, справиться у меня, не требуется ли нам ещё." } } } } },
    [8513] = { d = 17.5, g = 1, v = "human-male", c = { m = { { 0.00, "Так точно, сэр, я отвечаю за сбор всей средней кожи, необходимой для подготовки к войне с Ан'Кираем." }, { 6.99, "Если вы можете раздобыть среднюю кожу, неважно где, сдайте её мне, пожалуйста." }, { 12.47, "Я буду благодарен за любую помощь, если у вас найдётся на неё время." } }, f = { { 0.00, "Так точно, мэм, я отвечаю за сбор всей средней кожи, необходимой для подготовки к войне с Ан'Кираем." }, { 6.94, "Если вы можете раздобыть среднюю кожу, неважно где, сдайте её мне, пожалуйста." }, { 12.43, "Я буду благодарен за любую помощь, если у вас найдётся на неё время." } } }, t = { d = 13.3, v = "human-male", c = { x = { { 0.00, "Вау! Похоже, вы и правда решили помочь. Большое спасибо за ваш вклад в общее дело. Пойду-ка я упакую и пересчитаю кожи." }, { 8.42, "Нет, вы действительно знаете, чем скрасить день простого служаки." } } } } },
    [8515] = { d = 25.4, g = 1, v = "gnome-female", n = { x = 274 }, c = { m = { { 0.00, "О, будет так здорово! герой, приготовления к ан'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи." }, { 9.24, "Из неё мы сможем наделать тысячи разных вещей, но сначала надо её достать – тоже тысячами. В буквальном смысле. И тут на сцену выходишь ты." }, { 19.03, "Ты ведь принесёшь мне отличную увесистую кипу плотной кожи? Правда-правда?" } }, f = { { 0.00, "О, будет так здорово! героиня, приготовления к ан'киражской войне идут вовсю, и так получилось, что я отвечаю за заготовку плотной кожи." }, { 10.16, "Из неё мы сможем наделать тысячи разных вещей, но сначала надо её достать – тоже тысячами. В буквальном смысле. И тут на сцену выходишь ты." }, { 19.95, "Ты ведь принесёшь мне отличную увесистую кипу плотной кожи? Правда-правда?" } } }, t = { d = 25.1, g = 1, v = "gnome-female", c = { m = { { 0.00, "О, я знала, что ты справишься, герой, конечно же, я это знала! Я отправлю эту кожу по нужному адресу, как только смогу." }, { 8.02, "Ага, а теперь давай-ка посмотрим. Похоже, в итоге всё получается очень, очень миленько." }, { 13.97, "Загляни ко мне ещё разочек, я сейчас проверю, не нужно ли нам ещё кожи." }, { 18.96, "Если понадобится, то было бы так здорово, если бы ты смог достать для нас ещё!" } }, f = { { 0.00, "О, я знала, что ты справишься, героиня, конечно же, я это знала! Я отправлю эту кожу по нужному адресу, как только смогу." }, { 8.32, "Ага, а теперь давай-ка посмотрим. Похоже, в итоге всё получается очень, очень миленько." }, { 14.26, "Загляни ко мне ещё разочек, я сейчас проверю, не нужно ли нам ещё кожи." }, { 19.25, "Если понадобится, то было бы так здорово, если бы ты смогла достать для нас ещё!" } } } } },
    [8517] = { d = 25.6, g = 1, v = "nightelf-female#52", n = { x = 299 }, c = { m = { { 0.00, "Война в Ан'Кираже будет долгой и кровавой. Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением." }, { 7.85, "Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов." }, { 14.15, "Мне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь." }, { 18.82, "Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить. Что скажешь, герой?" } }, f = { { 0.00, "Война в Ан'Кираже будет долгой и кровавой. Прибегнуть к помощи людей, подобных тебе, было для Альянса мудрым решением." }, { 7.85, "Перед тем как сломя голову ринуться в военный конфликт, надо собрать достаточно припасов." }, { 14.15, "Мне поручили запасать льняные бинты, и я надеюсь, что ты мне поможешь." }, { 18.82, "Это не так-то легко, но по крайней мере льняные бинты проще всего изготовить. Что скажешь, героиня?" } } }, t = { d = 19.6, g = 1, v = "nightelf-female#52", c = { m = { { 0.00, "Многим солдатам ты, считай, сослужил добрую службу, герой. Я лично прослежу, чтобы твои усилия не остались незамеченными." }, { 8.00, "Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, сколько нужно ли мне ещё." }, { 16.07, "Да осенит тебя своим светом Элуна, путник!" } }, f = { { 0.00, "Многим солдатам ты, считай, сослужила добрую службу, героиня. Я лично прослежу, чтобы твои усилия не остались незамеченными." }, { 8.22, "Одну минуту, сейчас я упакую эти бинты, куда надо, и внесу их в реестр, а потом посмотрим, сколько нужно ли мне ещё." }, { 16.29, "Да осенит тебя своим светом Элуна, путница!" } } } } },
    [8520] = { d = 16.8, v = "human-female", n = { x = 194 }, c = { x = { { 0.00, "На горизонте маячит война в Ан'Кираже, так что мы должны приложить все усилия, чтобы на поле боя солдаты ни в чём не нуждались." }, { 8.58, "Именно этим мы и занимаемся. Я вот, например, отвечаю за заготовку шёлковых бинтов. Не хочешь ли мне помочь малость?" } } }, t = { d = 10.4, v = "human-female", c = { x = { { 0.00, "Ты молодчина! Спасибо за бинты. Благодаря тебе мы ещё на шаг приблизились к нашей общей цели." }, { 6.29, "Сейчас пойду уберу бинты, а потом можем ещё поболтать." } } } } },
    [8522] = { d = 25.1, g = 1, v = "nightelf-male#55", n = { x = 278 }, c = { m = { { 0.00, "Считай ведение войны сколь угодно сомнительным занятием, герой, но военная машина уже завертелась." }, { 6.65, "Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадём в горнило битвы, и надо будет как-то выживать." }, { 16.70, "Именно поэтому я запасаюсь бинтами из рунной ткани, кто бы их ни принёс. Не хочешь ли внести посильный вклад в это дело?" } }, f = { { 0.00, "Считай ведение войны сколь угодно сомнительным занятием, героиня, но военная машина уже завертелась." }, { 6.64, "Оглянись на свою семью и друзей и спроси, чем ты можешь помочь им, – ведь все мы попадём в горнило битвы, и надо будет как-то выживать." }, { 16.69, "Именно поэтому я запасаюсь бинтами из рунной ткани, кто бы их ни принёс. Не хочешь ли внести посильный вклад в это дело?" } } }, t = { d = 14.7, g = 1, v = "nightelf-male#55", n = { x = 169 }, c = { m = { { 0.00, "Твоя настойчивость в выполнении этого задания выше всяких похвал, герой. Сейчас я уберу бинты на склад и вернусь." }, { 7.69, "Я бы хотел побеседовать с тобой относительно возможности добыть ещё бинтов из рунической ткани." } }, f = { { 0.00, "Твоя настойчивость в выполнении этого задания выше всяких похвал, героиня. Сейчас я уберу бинты на склад и вернусь." }, { 7.88, "Я бы хотел побеседовать с тобой относительно возможности добыть ещё бинтов из рунической ткани." } } } } },
    [8524] = { d = 24.4, g = 1, v = "gnome-male", c = { m = { { 0.00, "Эй, дружище! Если бы я спросил тебя: \"Нужно ли солдатам на войне хорошо кушать?\" – ты бы, без сомнения, ответил: \"Да, конечно!\"." }, { 8.17, "И я абсолютно с тобой согласен! Рад, что мы сошлись во мнениях." }, { 12.53, "Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне. М-м-м, я уже в предвкушении." } }, f = { { 0.00, "Эй, дружище! Если бы я спросил тебя: \"Нужно ли солдатам на войне хорошо кушать?\" – ты бы, без сомнения, ответила: \"Да, конечно!\"." }, { 8.11, "И я абсолютно с тобой согласен! Рад, что мы сошлись во мнениях." }, { 12.47, "Теперь, я думаю, ты не будешь спорить, что тебе осталось только отправиться на рыбалку, наловить радужного тунца, приготовить всю порцию и принести мне. М-м-м, я уже в предвкушении." } } }, t = { d = 19.6, g = 1, v = "gnome-male", n = { m = 202, f = 204 }, c = { m = { { 0.00, "Два для Альянса, один мне, два для Альянса, один мне... Эгей, отличная работа, рыбак!" }, { 5.66, "Похоже, ты отличное приобретение для нашего клуба. А мне кажется, надо б раздобыть ещё тунца." }, { 12.49, "Почему бы тебе не прогуляться и не принести ещё рыбки? У меня уже в животе урчит..." } }, f = { { 0.00, "Два для Альянса, один мне, два для Альянса, один мне... Эгей, отличная работа, рыбачка!" }, { 6.88, "Похоже, ты отличное приобретение для нашего клуба. А мне кажется, надо б раздобыть ещё тунца." }, { 13.70, "Почему бы тебе не прогуляться и не принести ещё рыбки? У меня уже в животе урчит..." } } } } },
    [8526] = { d = 26.3, g = 1, v = "gnome-female#41", n = { x = 293 }, c = { m = { { 0.00, "Как делишки, герой? Я вижу, ты просто рвёшься принять участие в заготовке провизии для ан'киражской войны." }, { 7.29, "Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит. Как бы не так. Я мясо на дух не выношу." }, { 16.18, "Ладно, если вдруг захочешь помочь, принеси побольше жареных ящеров." }, { 20.92, "Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты." } }, f = { { 0.00, "Как делишки, героиня? Я вижу, ты просто рвёшься принять участие в заготовке провизии для ан'киражской войны." }, { 7.41, "Мой папочка решил, что ответственность за сбор чего-то там чему-то там меня научит. Как бы не так. Я мясо на дух не выношу." }, { 16.30, "Ладно, если вдруг захочешь помочь, принеси побольше жареных ящеров." }, { 21.03, "Несомненно, именно об этом мясе и будут мечтать все наши отважные солдаты." } } }, t = { d = 14.1, g = 1, v = "gnome-female#41", n = { x = 149 }, c = { m = { { 0.00, "Вот это да. Спасибо, что притащил сюда всю эту жженую плоть, герой." }, { 4.64, "Минуточку, сейчас я его покидаю в кучу, – надеюсь, кто-нибудь о нём да позаботится." }, { 10.07, "Если время найдётся, может быть, ещё принесёшь?" } }, f = { { 0.00, "Вот это да. Спасибо, что притащил сюда всю эту жженую плоть, героиня." }, { 5.23, "Минуточку, сейчас я его покидаю в кучу, – надеюсь, кто-нибудь о нём да позаботится." }, { 10.67, "Если время найдётся, может быть, ещё принесёшь?" } } } } },
    [8528] = { d = 34.0, g = 1, v = "nightelf-female#53", n = { x = 394 }, c = { m = { { 0.00, "Возможно, заготовка варёной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, герой.Солдаты – такие же люди, как и все, и они хотят есть." }, { 11.76, "Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан'Кираже." }, { 17.85, "Я получила приказ заготавливать пятнистый желтохвост." }, { 21.52, "Это отличный пищевой ресурс, он хорошо хранится, идёт на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы." }, { 31.03, "Ну что, поможешь мне в его заготовке?" } }, f = { { 0.00, "Возможно, заготовка варёной рыбы выглядит не особенно героически, но не стоит преуменьшать значение нашей работы, героиня.Солдаты – такие же люди, как и все, и они хотят есть." }, { 12.00, "Именно поэтому мы должны обеспечить их провиантом, пока не началась война в Ан'Кираже." }, { 18.09, "Я получила приказ заготавливать пятнистый желтохвост." }, { 21.76, "Это отличный пищевой ресурс, он хорошо хранится, идёт на изготовление различных блюд и совсем не пахнет, в отличие от другой морской рыбы." }, { 31.27, "Ну что, поможешь мне в его заготовке?" } } }, t = { d = 16.2, g = 1, v = "nightelf-female#53", c = { m = { { 0.00, "Спасибо за быструю и своевременную помощь, герой. Теперь наши солдаты не будут испытывать недостатка в провианте." }, { 7.76, "Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку ещё одной порции, если ты не против." } }, f = { { 0.00, "Спасибо за быструю и своевременную помощь, героиня. Теперь наши солдаты не будут испытывать недостатка в провианте." }, { 7.92, "Подожди немного, я позабочусь о размещении рыбы на складе, и мы обсудим доставку ещё одной порции, если ты не против." } } } } },
    [8530] = { d = 28.9, g = 1, v = "dwarf-male", n = { x = 336 }, c = { m = { { 0.00, "герой, мне нужна твоя помощь. Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опалённые вулканические камни." }, { 8.62, "Они нужны нам для подготовки к войне в Ан'Кираже." }, { 12.08, "Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ." }, { 17.98, "Проберись в Огненные Недра и собери столько, сколько сможешь." }, { 22.08, "Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей." } }, f = { { 0.00, "героиня, мне нужна твоя помощь. Есть камни, которые можно достать в Огненных Недрах, – я имею в виду опалённые вулканические камни." }, { 8.73, "Они нужны нам для подготовки к войне в Ан'Кираже." }, { 12.19, "Наши кузнецы и инженеры знают, как их использовать, так что мы получили на них заказ." }, { 18.09, "Проберись в Огненные Недра и собери столько, сколько сможешь." }, { 22.19, "Не сомневаюсь, что тебе удастся уговорить пойти с тобой штук тридцать девять близких приятелей." } } } },
    [8532] = { d = 23.0, g = 1, v = "scourge-male#83", c = { m = { { 0.00, "Я так рад, что ты решил помочь нам. Не всякий бы согласился, так что я лучше ещё раз уточню, правильно ли ты меня понял." }, { 8.90, "Мне нужны медные слитки, а не просто медь." }, { 12.03, "У нас недостаточно ни времени, ни людей, чтобы самим её выплавлять, так что твои усилия не останутся незамеченными. Ну как, герой, справишься?" } }, f = { { 0.00, "Я так рад, что ты решила помочь нам. Не всякий бы согласился, так что я лучше ещё раз уточню, правильно ли ты меня поняла." }, { 9.06, "Мне нужны медные слитки, а не просто медь." }, { 12.20, "У нас недостаточно ни времени, ни людей, чтобы самим её выплавлять, так что твои усилия не останутся незамеченными. Ну как, героиня, справишься?" } } }, t = { d = 19.0, g = 1, v = "scourge-male#83", c = { m = { { 0.00, "Вот они, слитки, хорошо, что ты не стал полировать их. В блеске нет никакого смысла, они всё равно пойдут на военные нужды." }, { 9.03, "Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело. Если добудешь ещё двадцать, обращайся прямо ко мне." } }, f = { { 0.00, "Вот они, слитки, хорошо, что ты не стала полировать их. В блеске нет никакого смысла, они всё равно пойдут на военные нужды." }, { 9.15, "Пойду уложу их в штабели, и нужно позаботиться, чтобы они были пущены в дело. Если добудешь ещё двадцать, обращайся прямо ко мне." } } } } },
    [8542] = { d = 33.2, g = 1, v = "orc-male", n = { x = 328 }, c = { m = { { 0.00, "Лок'тар, герой, я уверен, ты в курсе, что мы собираемся воевать с киражскими тараканами." }, { 6.19, "Вождь сказал, что сначала надо как следует подготовиться." }, { 11.00, "Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков. Для меня это большая честь, да! Но без помощи мне не справиться." }, { 23.61, "Надо, чтобы кто-то добывал эти самые слитки и приносил сюда." }, { 27.90, "Нам нужно так много, что, боюсь, я и считать-то до стольких не умею." } }, f = { { 0.00, "Лок'тар, героиня, я уверен, ты в курсе, что мы собираемся воевать с киражскими тараканами." }, { 6.30, "Вождь сказал, что сначала надо как следует подготовиться." }, { 11.10, "Я б охотней точил мечи или подгонял броню, но мне доверили сбор оловянных слитков. Для меня это большая честь, да! Но без помощи мне не справиться." }, { 23.72, "Надо, чтобы кто-то добывал эти самые слитки и приносил сюда." }, { 28.00, "Нам нужно так много, что, боюсь, я и считать-то до стольких не умею." } } }, t = { d = 15.6, g = 1, v = "orc-male", c = { m = { { 0.00, "Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, герой!" }, { 6.47, "От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси ещё столько же." } }, f = { { 0.00, "Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, героиня!" }, { 6.87, "От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси ещё столько же." } } } } },
    [8545] = { d = 28.0, g = 1, v = "troll-female#73", c = { m = { { 0.00, "Война надвигается неотвратимо, и всё, что нам остаётся, герой, – это как следует подготовиться к ней." }, { 6.75, "В такие времена мы должны сплотиться и помогать друг другу." }, { 10.61, "Как видишь, меня поставили ответственным за сбор мифриловых слитков, которые потом пойдут на нужды армии." }, { 17.82, "Я стараюсь как могу, но этого пока недостаточно." }, { 21.52, "Сумеешь добыть мифрил на рудниках и переплавить его в слитки? Это бы нам очень пригодилось." } }, f = { { 0.00, "Война надвигается неотвратимо, и всё, что нам остаётся, героиня, – это как следует подготовиться к ней." }, { 6.86, "В такие времена мы должны сплотиться и помогать друг другу." }, { 10.72, "Как видишь, меня поставили ответственным за сбор мифриловых слитков, которые потом пойдут на нужды армии." }, { 17.93, "Я стараюсь как могу, но этого пока недостаточно." }, { 21.63, "Сумеешь добыть мифрил на рудниках и переплавить его в слитки? Это бы нам очень пригодилось." } } }, t = { d = 17.6, g = 1, v = "troll-female#73", c = { m = { { 0.00, "Ну вот, очень неплохой зачин в нашей работе, герой." }, { 3.47, "Теперь на складе лежит ещё двадцать новеньких слиточков, сейчас я внесу их в список." }, { 9.07, "Когда на пороге война, на счету каждая крупинка мифрила!" }, { 13.33, "Ты заглядывай, похоже, нам скоро ещё понадобятся слитки." } }, f = { { 0.00, "Ну вот, очень неплохой зачин в нашей работе, героиня." }, { 3.61, "Теперь на складе лежит ещё двадцать новеньких слиточков, сейчас я внесу их в список." }, { 9.21, "Когда на пороге война, на счету каждая крупинка мифрила!" }, { 13.47, "Ты заглядывай, похоже, нам скоро ещё понадобятся слитки." } } } } },
    [8549] = { d = 33.6, g = 1, v = "tauren-female#71", n = { m = 343, f = 343 }, c = { m = { { 0.00, "Говорят, каждое поколение должно пройти испытание огнём. Боюсь, что ан'киражская война станет для нас тем самым горном для закалки." }, { 10.18, "Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста." }, { 16.69, "Нам нужен мироцвет, который пойдёт на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор." }, { 25.96, "Надеюсь, ты пришёл предложить мне свою помощь. Собери побольше мироцвета и принеси его мне." } }, f = { { 0.00, "Говорят, каждое поколение должно пройти испытание огнём. Боюсь, что ан'киражская война станет для нас тем самым горном для закалки." }, { 10.18, "Ничего, подготовимся как следует и покажем всем, из какого мы слеплены теста." }, { 16.69, "Нам нужен мироцвет, который пойдёт на создание лекарственных снадобий, и я вызвалась быть ответственной за его сбор." }, { 25.96, "Надеюсь, ты пришла предложить мне свою помощь. Собери побольше мироцвета и принеси его мне." } } }, t = { d = 20.6, v = "tauren-female#71", c = { x = { { 0.00, "Подготовка близится к концу, и скоро грянет война. Спасибо за помощь." }, { 5.48, "Мироцвет очень нужен нам, и твой вклад в общее дело не останется незамеченным." }, { 11.62, "Если сможешь, возвращайся и помоги мне собрать ещё мироцвета. А пока ступай, и пусть Мать-Земля хранит тебя." } } } } },
    [8580] = { d = 35.8, g = 1, v = "troll-male", n = { x = 326 }, c = { m = { { 0.00, "Даров, герой. Как делишки, дружище? Орде тут для войны в Ан'Кираже понадобилась прорва этого несчастного огнецвета." }, { 10.97, "Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков?" }, { 20.48, "Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага." }, { 25.87, "Но кое-что Пелекейки знает... например, что ты сейчас пойдёшь и принесёшь ему этого несчастного огнецвета, ага, дружище?" } }, f = { { 0.00, "Даров, героиня. Как делишки, дружище? Орде тут для войны в Ан'Кираже понадобилась прорва этого несчастного огнецвета." }, { 9.57, "Даж интересно, они собираются запихнуть его во всякие взрывающиеся штуки или отдать Альянсу на топливо для танков?" }, { 19.08, "Спроси что-нибудь полегче, тут Пелекейки не в курсе, ага." }, { 24.47, "Но кое-что Пелекейки знает... например, что ты сейчас пойдёшь и принесёшь ему этого несчастного огнецвета, ага, дружище?" } } }, t = { d = 25.0, g = 1, v = "troll-male", n = { x = 232 }, c = { m = { { 0.00, "герой! Пеле'кейки просто счастлив. Сейчас он заберёт эти цветочки и сложит их в коробку, чтоб не попортились." }, { 8.88, "Уж Пеле'кейки присмотрит, чтоб их употребили на всякие военные штуки, а не на какую-нибудь дребедень." }, { 17.23, "А если добудешь ещё цветочков, сразу же тащи Пеле'кейки, ему это всяко понадобится." } }, f = { { 0.00, "героиня! Пеле'кейки просто счастлив. Сейчас он заберёт эти цветочки и сложит их в коробку, чтоб не попортились." }, { 8.69, "Уж Пеле'кейки присмотрит, чтоб их употребили на всякие военные штуки, а не на какую-нибудь дребедень." }, { 17.05, "А если добудешь ещё цветочков, сразу же тащи Пеле'кейки, ему это всяко понадобится." } } } } },
    [8582] = { d = 46.6, g = 1, v = "scourge-female#79", n = { x = 397 }, c = { m = { { 0.00, "Лилового лотос, герой, является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан'Кираже." }, { 12.26, "Мы создадим бесчисленное количество самых разных снадобий." }, { 17.95, "Я думаю, придётся даже поэкспериментировать, чтобы исследовать все возможные способы его применения." }, { 27.65, "Но для экспериментов необходимо иметь достаточно цветов в запасе." }, { 34.17, "А вот это уже работа для тебя. Ступай и собери как можно больше цветков лилового лотоса. Возьмёшься ради нас за это задание?" } }, f = { { 0.00, "Лилового лотос, героиня, является основной составляющей множества зелий, эликсиров и масел, которые необходимы для войны в Ан'Кираже." }, { 12.66, "Мы создадим бесчисленное количество самых разных снадобий." }, { 18.36, "Я думаю, придётся даже поэкспериментировать, чтобы исследовать все возможные способы его применения." }, { 28.06, "Но для экспериментов необходимо иметь достаточно цветов в запасе." }, { 34.57, "А вот это уже работа для тебя. Ступай и собери как можно больше цветков лилового лотоса. Возьмёшься ради нас за это задание?" } } }, t = { d = 27.3, g = 1, v = "scourge-female#79", c = { m = { { 0.00, "Твоя работа заслуживает одобрения, герой. Я должна рассортировать образцы и не забыть отметить, что это был твой вклад." }, { 11.38, "Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить." }, { 18.20, "Как ты мог отметить, лотоса нужно гораздо больше, чем мы сейчас имеем. Далеко не уходи." } }, f = { { 0.00, "Твоя работа заслуживает одобрения, героиня. Я должна рассортировать образцы и не забыть отметить, что это был твой вклад." }, { 11.60, "Пока у меня не дойдут руки до этих цветов, нужно их правильно хранить." }, { 18.42, "Как ты могла отметить, лотоса нужно гораздо больше, чем мы сейчас имеем. Далеко не уходи." } } } } },
    [8588] = { d = 28.8, g = 1, v = "troll-female#75", c = { m = { { 0.00, "Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище?" }, { 5.75, "Тяжёлая кожа на войне – продукт первой необходимости." }, { 9.23, "Она идёт на всё – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками." }, { 15.36, "Именно поэтому её надо собрать как можно больше. А вот это уже твоя работа, герой." }, { 20.95, "Наточи поострее нож и добудь кож этак штук десять. Вот принесёшь их, тогда и поговорим." } }, f = { { 0.00, "Если уж мы собрались воевать, сначала надо подготовиться как следует, правда, дружище?" }, { 5.75, "Тяжёлая кожа на войне – продукт первой необходимости." }, { 9.23, "Она идёт на всё – начиная с заплаток на доспехи и заканчивая старыми добрыми ловушками." }, { 15.36, "Именно поэтому её надо собрать как можно больше. А вот это уже твоя работа, героиня." }, { 21.03, "Наточи поострее нож и добудь кож этак штук десять. Вот принесёшь их, тогда и поговорим." } } }, t = { d = 15.2, g = 1, v = "troll-female#75", c = { m = { { 0.00, "О, тебе удалось достать толстую кожу. У тебя острый нож, герой, кожи отлично выделаны! Пойду уберу их на склад." }, { 7.51, "Нужно убедиться, что твой вклад не пропадёт и послужит на благо Орде. Если удастся раздобыть ещё, неси сюда." } }, f = { { 0.00, "О, тебе удалось достать толстую кожу. У тебя острый нож, героиня, кожи отлично выделаны! Пойду уберу их на склад." }, { 7.65, "Нужно убедиться, что твой вклад не пропадёт и послужит на благо Орде. Если удастся раздобыть ещё, неси сюда." } } } } },
    [8590] = { d = 23.5, g = 1, v = "orc-female#58", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Я рада, что ты решил поговорить со мной, герой." }, { 3.33, "Подготовка к войне в Ан'Кираже идёт полным ходом, так что нам с тобой нельзя сбавлять темп работы." }, { 10.50, "Я отвечаю за сбор плотной кожи, и её нужно действительно много, поэтому без твоей помощи никак не справиться." }, { 18.34, "Если ты мне поможешь, в моём лице тебе будет благодарна вся Орда." } }, f = { { 0.00, "Я рада, что ты решила поговорить со мной, героиня." }, { 3.56, "Подготовка к войне в Ан'Кираже идёт полным ходом, так что нам с тобой нельзя сбавлять темп работы." }, { 10.73, "Я отвечаю за сбор плотной кожи, и её нужно действительно много, поэтому без твоей помощи никак не справиться." }, { 18.57, "Если ты мне поможешь, в моём лице тебе будет благодарна вся Орда." } } }, t = { d = 18.5, g = 1, v = "orc-female#58", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Ты хорошо постарался, герой. Эта кожа не будет истрачена зря – она пойдёт на усиление наших дирижаблей и изготовление оружия и брони." }, { 9.27, "Благодарю тебя от лица всей Орды. Если тебе в своих путешествиях удастся добыть ещё плотной кожи, неси её мне. И удачи тебе." } }, f = { { 0.00, "Ты хорошо постаралась, героиня. Эта кожа не будет истрачена зря – она пойдёт на усиление наших дирижаблей и изготовление оружия и брони." }, { 9.54, "Благодарю тебя от лица всей Орды. Если тебе в своих путешествиях удастся добыть ещё плотной кожи, неси её мне. И удачи тебе." } } } } },
    [8600] = { d = 43.1, g = 1, v = "scourge-male#82", n = { x = 339 }, c = { m = { { 0.00, "Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия." }, { 6.69, "И самый тупой клинок способен порезать, если приложить нужное усилие. Правильно, герой?" }, { 14.66, "Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены." }, { 21.81, "Ну, это не важно. У меня для тебя есть дело. Достань мне побольше прочной кожи." }, { 30.42, "Она нужна, чтобы Орда как следует подготовилась к войне в Ан'Кираже. Я не сомневаюсь, что ты отлично справишься, ага?" } }, f = { { 0.00, "Я понял, что подгонка ножа по руке важна даже больше, чем острота лезвия." }, { 6.69, "И самый тупой клинок способен порезать, если приложить нужное усилие. Правильно, героиня?" }, { 14.91, "Думаю, у нас не будет таких проблем, ведь наши ножи всегда хорошо заточены." }, { 22.06, "Ну, это не важно. У меня для тебя есть дело. Достань мне побольше прочной кожи." }, { 30.67, "Она нужна, чтобы Орда как следует подготовилась к войне в Ан'Кираже. Я не сомневаюсь, что ты отлично справишься, ага?" } } }, t = { d = 23.4, g = 1, v = "scourge-male#82", c = { m = { { 0.00, "Прекрасно, прекрасно, ты проделал неплохую работёнку, хотя некоторые из этих кож по краям обрезаны не слишком ровно." }, { 10.60, "Но, без сомнений, задание выполнено, и ты получишь обещанную награду." }, { 17.03, "Если вдруг раздобудешь ещё прочной кожи, то тащи её мне поскорее." } }, f = { { 0.00, "Прекрасно, прекрасно, ты проделала неплохую работёнку, хотя некоторые из этих кож по краям обрезаны не слишком ровно." }, { 10.50, "Но, без сомнений, задание выполнено, и ты получишь обещанную награду." }, { 16.93, "Если вдруг раздобудешь ещё прочной кожи, то тащи её мне поскорее." } } } } },
    [8604] = { d = 40.6, g = 1, v = "tauren-male#67", n = { x = 328 }, c = { m = { { 0.00, "Приветствую, герой. Мне поручено собирать шерстяные бинты для подготовки к войне в Ан'Кираже." }, { 8.91, "К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех." }, { 18.64, "Поэтому мы должны уделить как можно больше внимания оказанию первой помощи." }, { 26.57, "Если у тебя есть время, помоги мне собрать шерстяные бинты." }, { 32.34, "Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение." } }, f = { { 0.00, "Приветствую, героиня. Мне поручено собирать шерстяные бинты для подготовки к войне в Ан'Кираже." }, { 9.19, "К сожалению, на поле боя солдаты не могут рассчитывать, что лекари успеют добраться сразу до всех." }, { 18.91, "Поэтому мы должны уделить как можно больше внимания оказанию первой помощи." }, { 26.85, "Если у тебя есть время, помоги мне собрать шерстяные бинты." }, { 32.62, "Принеси их сюда, а я позабочусь, чтобы тебе выдали положенное вознаграждение." } } }, t = { d = 21.2, g = 1, v = "tauren-male#67", c = { m = { { 0.00, "Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, герой!" }, { 9.13, "От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси ещё столько же." } }, f = { { 0.00, "Хм... Выглядит так, будто слитков столько, сколько нужно... Только не пытайся обмануть меня, героиня!" }, { 9.39, "От этого счета у меня башка раскалывается. Пойду сложу слитки в штабель, а ты пока отправляйся и принеси ещё столько же." } } } } },
    [8607] = { d = 29.2, g = 1, v = "scourge-female#80", c = { m = { { 0.00, "Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю? Отлично!" }, { 7.36, "Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле \"любой ценой\"." }, { 15.50, "Хорошо бы свежие, но это совершенно не обязательно." }, { 19.93, "Когда добудешь их, герой, возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили." } }, f = { { 0.00, "Ты действительно хочешь помочь мне в сборе материалов, за которые я отвечаю? Отлично!" }, { 7.36, "Бинты из магической ткани нужны мне любой ценой, я имею в виду, в буквальном смысле \"любой ценой\"." }, { 15.50, "Хорошо бы свежие, но это совершенно не обязательно." }, { 19.93, "Когда добудешь их, героиня, возвращайся ко мне, я прослежу, чтобы тебя соответственным образом наградили." } } }, t = { d = 24.9, g = 1, v = "scourge-female#80", c = { m = { { 0.00, "Удивительно, но всё в порядке. Возможно, я недооценила твои способности, герой. Всё возможно." }, { 7.88, "К тому же, задание было несложное, а награда гораздо больше, чем следует. Впрочем, не бери в голову." }, { 16.25, "Если хочешь в самом деле доказать, чего стоишь, ступай и принеси ещё бинтов из магической ткани." } }, f = { { 0.00, "Удивительно, но всё в порядке. Возможно, я недооценила твои способности, героиня. Всё возможно." }, { 7.97, "К тому же, задание было несложное, а награда гораздо больше, чем следует. Впрочем, не бери в голову." }, { 16.34, "Если хочешь в самом деле доказать, чего стоишь, ступай и принеси ещё бинтов из магической ткани." } } } } },
    [8609] = { d = 36.6, g = 1, v = "tauren-female", n = { x = 348 }, c = { m = { { 0.00, "Альянс и Орда готовятся к войне в Ан'Кираже, идя встречными курсами." }, { 5.54, "Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними." }, { 14.78, "Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве." }, { 24.12, "Я отвечаю за сбор бинтов из рунной ткани, для оказания первой помощи. Но одна я точно не справлюсь." }, { 32.49, "Помоги мне, герой, я буду очень признательна." } }, f = { { 0.00, "Альянс и Орда готовятся к войне в Ан'Кираже, идя встречными курсами." }, { 5.54, "Просто удивительно, что они собираются воевать не друг с другом, а с силитидами, какая бы сила ни стояла за ними." }, { 14.78, "Не менее удивительно, что обе стороны вносят свой вклад в заготовку военных ресурсов в достаточном количестве." }, { 24.12, "Я отвечаю за сбор бинтов из рунной ткани, для оказания первой помощи. Но одна я точно не справлюсь." }, { 32.49, "Помоги мне, героиня, я буду очень признательна." } } }, t = { d = 23.2, g = 1, v = "tauren-female", n = { x = 226 }, c = { m = { { 0.00, "Орда в долгу перед тобой, герой. Спасибо тебе за то, что ты для нас сделал, мы сохраним твои поступки в своём сердце." }, { 9.65, "Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели." }, { 17.05, "Если получится, добудь ещё бинтов из рунной ткани и возвращайся ко мне." } }, f = { { 0.00, "Орда в долгу перед тобой, героиня. Спасибо тебе за то, что ты для нас сделала, мы сохраним твои поступки в своём сердце." }, { 9.71, "Я должна складировать эти бинты и посчитать, насколько мы приблизились к выполнению цели." }, { 17.11, "Если получится, добудь ещё бинтов из рунной ткани и возвращайся ко мне." } } } } },
    [8611] = { d = 34.8, g = 1, v = "orc-female#58", c = { m = { { 0.00, "Я здесь не просто так загораю, герой. Подготовка к войне – дело нешуточное!" }, { 5.24, "Если мы хотим передавить киражских тараканов, надо приложить массу усилий, в том числе к заготовке провианта." }, { 13.20, "Меня назначили ответственным за засолку постных стейков из волчатины." }, { 18.14, "Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учёт мяса одновременно." }, { 26.48, "Так что это тебе придётся добыть волчатины и приготовить её, как надо, а потом ты принесёшь её мне. Всё понятно?" } }, f = { { 0.00, "Я здесь не просто так загораю, героиня. Подготовка к войне – дело нешуточное!" }, { 5.37, "Если мы хотим передавить киражских тараканов, надо приложить массу усилий, в том числе к заготовке провианта." }, { 13.33, "Меня назначили ответственным за засолку постных стейков из волчатины." }, { 18.27, "Однако не могу же я разорваться на части – бегать за волками по лесам и обеспечивать хранение и учёт мяса одновременно." }, { 26.60, "Так что это тебе придётся добыть волчатины и приготовить её, как надо, а потом ты принесёшь её мне. Всё понятно?" } } }, t = { d = 16.0, g = 1, v = "orc-female#58", c = { m = { { 0.00, "О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживёт свежим." }, { 8.04, "Спасибо за вклад в наше общее дело, герой. А пока – как насчёт того, чтобы принести мне ещё порцию стейков?" } }, f = { { 0.00, "О, это мясо неплохо выглядит. Сейчас я его засолю и уберу на хранение. Надеюсь, до войны оно доживёт свежим." }, { 8.04, "Спасибо за вклад в наше общее дело, героиня. А пока – как насчёт того, чтобы принести мне ещё порцию стейков?" } } } } },
