    [8617] = { d = 37.1, g = 1, v = "orc-male#60", n = { m = 428, f = 429 }, c = { m = { { 0.00, "Пришло время и тебе поучаствовать в нашей подготовке войны в Ан'Кираже, герой." }, { 5.39, "Прошли деньки, когда можно было беззаботно валяться на солнышке. Нынче каждый должен встать под знамёна Орды и Вождя!" }, { 13.36, "А я, в отличие от нашего вождя, добросердечием не страдаю, уж будь спокоен." }, { 18.84, "Ты должен собрать военные силы своей гильдии (если состоишь в таковой) и проникнуть в Огненные Недра." }, { 25.89, "Мне нужны оплавленные вулканические камни, которые можно обнаружить у тамошних обитателей." }, { 32.18, "Собери столько камней, сколько сможешь, и возвращайся обратно." } }, f = { { 0.00, "Пришло время и тебе поучаствовать в нашей подготовке войны в Ан'Кираже, героиня." }, { 5.45, "Прошли деньки, когда можно было беззаботно валяться на солнышке. Нынче каждый должен встать под знамёна Орды и Вождя!" }, { 13.41, "А я, в отличие от нашего вождя, добросердечием не страдаю, уж будь спокойна." }, { 19.12, "Ты должна собрать военные силы своей гильдии (если состоишь в таковой) и проникнуть в Огненные Недра." }, { 26.12, "Мне нужны оплавленные вулканические камни, которые можно обнаружить у тамошних обитателей." }, { 32.41, "Собери столько камней, сколько сможешь, и возвращайся обратно." } } } },
    [8792] = { d = 37.5, g = 1, v = "tauren-female", n = { m = 346, f = 347 }, c = { m = { { 0.00, "Приветствую! Хорошо, что ты решил поговорить со мной." }, { 4.44, "Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может." }, { 12.42, "Вот и тебе не след оставаться в стороне." }, { 15.65, "Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться!" }, { 25.76, "Поговори с тем, кто отвечает за заготовки, – с вождём Горчуком. Ну как, что скажешь, герой?" }, { 32.97, "Примешь участие в этом жизненно важном деле?" } }, f = { { 0.00, "Приветствую! Хорошо, что ты решила поговорить со мной." }, { 4.93, "Если мы хотим достойно подготовиться к ан'киражской войне, то Орде должны помогать все, кто может." }, { 12.91, "Вот и тебе не след оставаться в стороне." }, { 16.15, "Пока мы тут с тобой болтаем, наши интенданты запасают всяческие ресурсы, но без твоей помощи им не справиться!" }, { 26.26, "Поговори с тем, кто отвечает за заготовки, – с вождём Горчуком. Ну как, что скажешь, героиня?" }, { 33.51, "Примешь участие в этом жизненно важном деле?" } } }, t = { d = 19.5, g = 1, v = "orc-male", n = { x = 194 }, c = { m = { { 0.00, "Тромька, герой! Приятно видеть, что так много представителей Орды,как ты, выступают, чтобы оказать свою поддержку в предстоящей Ан'киражской войне." }, { 10.15, "Наши старания гарантируют, что мы победим силитидов и их злых хозяев, скрытых внутри Ан'Киража." } }, f = { { 0.00, "Тромька, героиня! Приятно видеть, что так много представителей Орды,как ты, выступают, чтобы оказать свою поддержку в предстоящей Ан'киражской войне." }, { 12.42, "Наши старания гарантируют, что мы победим силитидов и их злых хозяев, скрытых внутри Ан'Киража." } } } } },
