    [8795] = { d = 33.5, g = 1, v = "gnome-male", n = { m = 386, f = 387 }, c = { m = { { 0.00, "Приветствую. Хорошо, что ты решил поговорить со мной." }, { 3.70, "В подготовке к войне в Ан'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый!" }, { 12.35, "Уже назначены ответственные за сбор разнообразных материалов, но без помощи обычных граждан им не справиться!" }, { 20.29, "Если хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за заготовки. Ну как, что скажешь, герой?" }, { 28.63, "Примешь ли ты участие ли ты в нашем жизненно важном деле?" } }, f = { { 0.00, "Приветствую. Хорошо, что ты решила поговорить со мной." }, { 4.07, "В подготовке к войне в Ан'Кираже Альянс должен использовать все доступные ресурсы, а значит, посильный вклад может внести каждый!" }, { 12.72, "Уже назначены ответственные за сбор разнообразных материалов, но без помощи обычных граждан им не справиться!" }, { 20.66, "Если хочешь поддержать Альянс, обратись к фельдмаршалу Снегопаду, который отвечает за заготовки. Ну как, что скажешь, героиня?" }, { 29.15, "Примешь ли ты участие ли ты в нашем жизненно важном деле?" } } }, t = { d = 26.2, g = 1, v = "dwarf-male", n = { m = 308, f = 310 }, c = { m = { { 0.00, "Приветствую тебя и желаю удачи, юноша! Как хорошо, что в Альянсе есть люди вроде тебя." }, { 5.93, "Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан'Кираже." }, { 11.59, "Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия." }, { 18.50, "Не стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть." } }, f = { { 0.00, "Приветствую тебя и желаю удачи, девушка! Как хорошо, что в Альянсе есть люди вроде тебя." }, { 5.94, "Мы будем рады любой помощи в подготовке надвигающейся грандиозной войны в Ан'Кираже." }, { 11.60, "Если мы объединим наши усилия, то наверняка сможем выковырять мерзких силитидов из их укрытия." }, { 18.51, "Не стесняйся предложить свою помощь лицам, ответственным за сбор материалов, которые тебе легче раздобыть." } } } } },
