    [8827] = { d = 21.9, v = "goblin-male#110", n = { x = 223 }, c = { x = { { 0.00, "Говорят, что Дедушка Зима – не без помощи Пастбищ Дымного Леса – сложил под ёлку в Стальгорне подарки для всех." }, { 7.54, "Я бы с радостью сходил туда, но мне надо присматривать за PX-двести тридцать восемь Чудовольтом Мороза." }, { 15.58, "А ты непременно туда загляни. Не сомневаюсь, Дедушка Зима и для тебя подарочек припас." } } }, t = { d = 23.2, g = 1, v = "dwarf-male", n = { m = 257, f = 257 }, c = { m = { { 0.00, "О-хо! Добро пожаловать! Я знаю, зачем ты пришёл – открыть свой подарочек на Зимний Покров." }, { 6.47, "Не сомневайся, Дедушка Зима не забыл про своего любимого героя. Загляни под ёлочку, подарок тебя ждёт-дожидается." }, { 14.62, "Кстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей чудесными дарами Пастбищ Дымного леса?" } }, f = { { 0.00, "О-хо! Добро пожаловать! Я знаю, зачем ты пришла – открыть свой подарочек на Зимний Покров." }, { 6.51, "Не сомневайся, Дедушка Зима не забыл про своего любимого героиню. Загляни под ёлочку, подарок тебя ждёт-дожидается." }, { 14.80, "Кстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей чудесными дарами Пастбищ Дымного леса?" } } } } },
    [8828] = { d = 21.9, v = "goblin-male#110", n = { x = 223 }, c = { x = { { 0.00, "Говорят, что Дедушка Зима – не без помощи Пастбищ Дымного леса – сложил под ёлку в Оргриммаре подарки для всех." }, { 7.53, "Я бы с радостью сходил туда, но мне надо присматривать за PX-двести тридцать восемь Чудовольтом Мороза." }, { 15.57, "А ты непременно туда загляни. Не сомневаюсь, Дедушка Зима и для тебя подарочек припас." } } }, t = { d = 23.7, g = 1, v = "orc-male", n = { m = 257, f = 257 }, c = { m = { { 0.00, "О-хо! Добро пожаловать! Я знаю, зачем ты пришёл – открыть свой подарочек на Зимний Покров." }, { 6.64, "Не сомневайся, Дедушка Зима не забыл про своего любимого героя. Загляни под ёлочку, подарок тебя ждёт-дожидается." }, { 15.00, "Кстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей чудесными дарами Пастбищ Дымного леса?" } }, f = { { 0.00, "О-хо! Добро пожаловать! Я знаю, зачем ты пришла – открыть свой подарочек на Зимний Покров." }, { 6.60, "Не сомневайся, Дедушка Зима не забыл про своего любимого героиню. Загляни под ёлочку, подарок тебя ждёт-дожидается." }, { 15.01, "Кстати, раз уж все дарят друг другу подарки, не хочешь осчастливить своих друзей чудесными дарами Пастбищ Дымного леса?" } } } } },
    [8860] = { d = 33.8, v = "goblin-male#110", n = { x = 388 }, c = { x = { { 0.00, "Штормград устраивает празднество в честь нового года! Целый день там можно пить задарма, а ночью будет фейерверк!" }, { 8.19, "Это должно быть прекрасно... но в Пиратской бухте сегодня тоже праздник, и держу пари, там будет ещё лучше!" }, { 15.75, "Ну, как бы то ни было, хозяйке таверны Аллисон в Штормграде требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк." }, { 24.89, "Окажи мне услугу, доставь эту партию!" }, { 27.85, "Спасибо! Аллисон держит таверну \"Позолоченная роза\" в Торговом квартале Штормграда." } } }, t = { d = 14.8, v = "human-female#111", n = { x = 166 }, c = { x = { { 0.00, "О, припасы от Пастбища Дымного Леса! Чудесно! Они мне понадобятся, чтобы накормить тех, кто собрался на праздник." }, { 8.13, "Спасибо тебе. Вот, возьми деньги и не забудь как следует выпить и поплясать на праздновании!" } } } } },
    [8861] = { d = 33.5, v = "goblin-male#110", n = { x = 381 }, c = { x = { { 0.00, "Громовой Утёс устраивает празднество в честь нового года! Целый день там можно пить задарма, а ночью будет фейерверк!" }, { 8.45, "Это должно быть прекрасно... но в Пиратской бухте сегодня тоже праздник, и держу пари, там будет ещё лучше!" }, { 16.01, "Ну, как бы то ни было, хозяйке таверны Пале в Громовом Утёсе требуются припасы Пастбищ Дымного Леса, чтобы помочь накормить всех гуляк." }, { 25.18, "Окажи мне услугу, доставь эту партию!" }, { 28.14, "Спасибо! Пала держит таверну возле моста, ведущего на вершину Охотников." } } }, t = { d = 20.6, v = "tauren-female", c = { x = { { 0.00, "О, отлично! Эти припасы помогут накормить всех моих сородичей, собравшихся сюда на праздник!" }, { 8.53, "Спасибо тебе. Я у тебя в долгу. Прошу, возьми эти монеты..." }, { 13.18, "и последуй моему совету – пей сегодня от всей души и присоединяйся к праздничным танцам!" } } } } },
    [8867] = { d = 25.8, v = "tauren-female#72", c = { x = { { 0.00, "Каждый год друиды Лунной поляны празднуют торжество своего города над древним злом." }, { 6.75, "Мы вспоминаем о мудрости старейшин, наслаждаемся пирами и, разумеется, пускаем фейерверки!" }, { 14.12, "За небольшое пожертвование ты можешь приобрести разноцветные фейерверки у наших торговцев." }, { 21.08, "Можешь воспользоваться здешними пусковыми установками." } } }, t = { d = 23.9, v = "tauren-female#72", c = { x = { { 0.00, "Молодец." }, { 1.13, "Раз вы так прониклись духом праздника, почему бы вам не отправиться в Лунную поляну?" }, { 8.06, "Если у вас есть время, там можно неплохо повеселиться. Полно еды, выпивки, баек у костра... И фейерверков!" }, { 16.56, "Откройте приглашение, стоя в большом круге лунного света, и перенесётесь в Лунную поляну." } } } } },
    [8870] = { d = 18.7, v = "nightelf-male#59", c = { x = { { 0.00, "Время веселиться! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 7.43, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 15.29, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 5.1, g = 1, v = "tauren-female#72", c = { m = { { 0.00, "Добро пожаловать. Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать. Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8871] = { d = 18.7, v = "nightelf-male#59", c = { x = { { 0.00, "Время веселиться! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 7.43, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 15.29, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.8, v = "tauren-female#72", c = { x = { { 0.00, "Добро пожаловать. Ты хочешь присоединиться к торжествам?" } } } } },
    [8872] = { d = 18.7, v = "nightelf-male#59", c = { x = { { 0.00, "Время веселиться! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 7.43, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 15.29, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 5.1, g = 1, v = "tauren-female#72", c = { m = { { 0.00, "Добро пожаловать. Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать. Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8873] = { d = 20.7, v = "tauren-male#68", c = { x = { { 0.00, "Время веселиться! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 8.39, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 17.15, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.9, g = 1, v = "tauren-female#72", n = { m = 50, f = 50 }, c = { m = { { 0.00, "Добро пожаловать. Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать. Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8874] = { d = 20.7, v = "tauren-male#68", c = { x = { { 0.00, "Время веселиться! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 8.39, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 17.15, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 4.8, v = "tauren-female#72", c = { x = { { 0.00, "Добро пожаловать. Ты хочешь присоединиться к торжествам?" } } } } },
    [8875] = { d = 20.7, v = "tauren-male#68", c = { x = { { 0.00, "Время веселиться! Круг Кенария приглашает всех обитателей Азерота принять участие в нашем Лунном фестивале." }, { 8.39, "В городе ты найдёшь предвестницу Лунного фестиваля – её расположение отмечено кругом благословенного лунного света." }, { 17.15, "Она расскажет тебе больше об этом празднике." } } }, t = { d = 5.1, g = 1, v = "tauren-female#72", c = { m = { { 0.00, "Добро пожаловать. Ты пришёл, чтобы праздновать вместе с нами?" } }, f = { { 0.00, "Добро пожаловать. Ты пришла, чтобы праздновать вместе с нами?" } } } } },
    [8897] = { d = 35.5, v = "human-male", c = { x = { { 0.00, "Я должен нести стражу здесь, у ворот, но я постоянно беспокоюсь о моей милой Коларе." }, { 5.99, "Даже при самой большой удаче я могу увидеться с нею лишь на несколько часов, да и что я собой представляю?" }, { 13.40, "Я получаю жалованье младшего офицера и в любой день меня могут отозвать на фронт." }, { 19.36, "Не забудет ли она обо мне сразу после расставания? В городе полно мужчин, и многие из них богаты." }, { 26.48, "Но как бы то ни было, я написал тут несколько слов..." }, { 30.00, "ничего особенного, но я буду признателен, если ты доставишь их ей от меня." } } }, t = { d = 11.3, v = "human-female", c = { x = { { 0.00, "Как это мило! Он впервые догадался мне написать. Ты думаешь, он это серьёзно?" }, { 5.64, "Колара Нельдрик? По-моему, звучит неплохо. О, но я забегаю вперёд. Спасибо тебе." } } } } },
    [8898] = { d = 24.2, v = "dwarf-male", c = { x = { { 0.00, "В последний раз, когда я был в Штормграде по делам банка, я встретил там девушку. Она похитила моё сердце." }, { 7.27, "Я не могу не думать о ней! Я хотел бы послать ей это письмо – я переписывал его двенадцать раз." }, { 14.16, "Почта сейчас так загружена, а я хотел бы точно знать, что письмо попадёт к ней." }, { 19.94, "Если ты направляешься туда, то не окажешь ли мне услугу?" } } }, t = { d = 9.8, v = "human-female", c = { x = { { 0.00, "Тормек? О да, я помню его. У него была такая красивая борода, и он всё время в неё улыбался." }, { 6.66, "Ах, поверить не могу, что он меня не забыл!" } } } } },
    [8900] = { d = 33.4, v = "orc-male", c = { x = { { 0.00, "Она была такой грустной. Я понял это, едва узрев, что таится под выражением её лица." }, { 6.06, "Я имею в виду, она казалась грустной – понимаешь?" }, { 9.82, "А после того, как я поговорил с ней, возникла взаимосвязь. Я не думал, что кто-то может понять мои мысли, но она смогла." }, { 18.49, "Когда я сказал остальным, они смеялись надо мной, и потому я больше никогда с ней не заговаривал. Но я скучаю по ней." }, { 26.86, "Ты не можешь отнести ей от меня письмо? Я хочу быть уверен, что оно попадёт к ней в руки." } } }, t = { d = 13.9, v = "scourge-female#80", c = { x = { { 0.00, "Вот не ожидала, что орк окажется таким красноречивым." }, { 4.53, "Конечно же, до нынешних времён у нас не было возможности как следует их узнать. Спасибо за доставку письма!" } } } } },
    [8901] = { d = 37.4, v = "tauren-male", c = { x = { { 0.00, "Известно ли тебе, что такое любовь – в твои-то годы?" }, { 4.10, "До недавнего времени для меня это было нечто чуждое, а затем я встретил в Подгороде ту девушку – Элению." }, { 12.23, "Для моего народа это редкое событие – остановить свой взгляд на ком-то из другой расы, не говоря уж о тех, кто принадлежит к Отрёкшимся." }, { 23.22, "Но ныне мысли о ней занимают мой разум день и ночь." }, { 27.64, "Если будет возможность, не передашь ли ты ей это письмо. Я хочу, чтобы она приехала сюда, в Мулгор. Надеюсь, она скажет \"да\"." } } }, t = { d = 23.1, v = "scourge-female#80", c = { x = { { 0.00, "Какие милые слова написал мне Темма! Но, хотя его слова меня тронули, я не могу всерьёз рассматривать любовь таурена." }, { 10.14, "Мы слишком разные по крови, разуму и духу." }, { 14.24, "Как хорошо, что он не сделал мне это предложение лично. Мне было бы невыносимо разбивать ему сердце." } } } } },
    [8902] = { d = 30.7, v = "scourge-male", c = { x = { { 0.00, "Целую жизнь назад я был помолвлен с девушкой по имени Эления, подругой моего детства." }, { 6.46, "Прошли годы с тех пор, как я в последний раз думал о ней, но в последнее время она постоянно занимает мои мысли." }, { 15.04, "Быть может даже тогда, когда всё ушло, в нашей жизни всё-таки остаётся место для любви." }, { 21.94, "Я уверен, что она тоже изменилась. Ты не передашь ей от меня письмо? Я слишком волнуюсь, чтобы передать его лично." } } }, t = { d = 26.3, v = "scourge-female#80", c = { x = { { 0.00, "Это возвращает воспоминания о прошлой жизни. Эления Тор.Знаешь, это должно было быть моим именем." }, { 8.49, "У нас была бы красивая церемония на берегу озера. Значит, простые мечты." }, { 14.98, "Но если бы он увидел меня сейчас, я сомневаюсь, что он вообще увидел бы во мне Элению." }, { 22.46, "Только холодная плоть и мёртвое сердце..." } } } } },
    [8903] = { d = 27.0, v = "human-male", c = { x = { { 0.00, "Есть что-то неестественное в этой эпидемии любви." }, { 3.53, "Это неправильно, это как заноза в пальце и, если дойдёт до самого худшего, это может стать угрозой безопасности самого Альянса." }, { 12.83, "Только подумай: что, если стражи будут сражены этой странной влюблённостью? Нужно что-то делать." }, { 19.75, "Отправляйся к одному из стражей здесь, в Штормграде, и посмотри, не постигло ли их это помешательство." } } }, t = { d = 9.9, v = "human-male", c = { x = { { 0.00, "Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить." }, { 6.71, "За этим должны крыться какие-то причины." } } } } },
    [8904] = { d = 41.7, v = "scourge-male#82", c = { x = { { 0.00, "Есть что-то неестественное в этой эпидемии любви." }, { 4.63, "Это отвратительно, а поскольку это ослабляет нашу защиту, то может представлять угрозу для всех нас." }, { 14.26, "Достаточно плохо уже то, что многие из нашего народа заразились этим странным поведением." }, { 22.67, "Но мне кажется, что поветрие распространилось даже на стражей, которые должны быть невосприимчивы к таким вещам." }, { 33.27, "Отправляйся к одному из наших стражей и посмотри, не постигло ли их это помешательство." } } }, t = { d = 12.9, v = "scourge-male#82", c = { x = { { 0.00, "Так это правда! Просто не могу поверить. Как это могло случиться? Дай мне немного поразмыслить." }, { 8.78, "За этим должны крыться какие-то причины." } } } } },
    [9065] = { d = 3.4, v = "human-male#114", c = { x = { { 0.00, "Эй, ты! Убей пару кобольдов-вредителей." } } } },
    [9247] = { d = 26.4, v = "human-male#114", c = { x = { { 0.00, "В прошлом тебе иногда приходилось браться за поручения в интересах Серебряного Рассвета, и всегда эти поручения оказывались выполнены в наилучшем виде." }, { 11.31, "Ныне, в час великой нужды, мы вновь посылаем тебе зов." }, { 15.89, "Пожалуйста, если ты желаешь вновь оказать нам помощь, явись к хранителю свитков в Часовню Последней Надежды, что в Восточных Чумных землях." } } }, t = { d = 13.0, v = "human-male", c = { x = { { 0.00, "Ответив на зов, мы будем у тебя в долгу." }, { 2.88, "Серебряный Рассвет уверен, что благодаря твоему яркому примеру другие получат прекрасное представление о том, как отбросить вторжение Плети!" } } } } },
    [9260] = { d = 36.2, v = "human-male#50", n = { x = 438 }, c = { x = { { 0.00, "Плеть стала лагерем у самых наших дверей. Мы не можем оставаться в бездействии!" }, { 5.33, "Встанешь ли ты на защиту Штормграда против этих проклятых захватчиков?" }, { 10.47, "Там, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху." }, { 19.28, "Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно." }, { 25.17, "Пока ты занимаешься этим, уменьши количество этих жутких тварей, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!" } } }, t = { d = 22.5, v = "human-male#50", n = { x = 267 }, c = { x = { { 0.00, "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то." }, { 8.00, "Я содрогаюсь при мысли о том, с каким извращённым разумом осуществляется связь посредством подобной магии." }, { 15.24, "Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу." } } } } },
    [9261] = { d = 38.1, v = "human-male", n = { x = 438 }, c = { x = { { 0.00, "Плеть стала лагерем у самых наших дверей. Мы не можем оставаться в бездействии!" }, { 5.52, "Встанешь ли ты на защиту Стальгорна против этих проклятых захватчиков?" }, { 10.65, "Там, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху." }, { 19.92, "Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно." }, { 25.98, "Пока ты занимаешься этим, уменьши количество этих жутких тварей, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!" } } }, t = { d = 22.8, v = "human-male", n = { x = 267 }, c = { x = { { 0.00, "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то." }, { 8.21, "Я содрогаюсь при мысли о том, с каким извращённым разумом осуществляется связь посредством подобной магии." }, { 15.51, "Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу." } } } } },
    [9263] = { d = 36.9, v = "dwarf-male", n = { x = 438 }, c = { x = { { 0.00, "Плеть стала лагерем у самых наших дверей. Мы не можем оставаться в бездействии!" }, { 5.53, "Встанешь ли ты на защиту Оргриммара против этих проклятых захватчиков?" }, { 10.79, "Там, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху." }, { 19.93, "Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно." }, { 25.90, "Пока ты занимаешься этим, уменьши количество этих жутких тварей, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!" } } }, t = { d = 22.5, v = "dwarf-male", n = { x = 267 }, c = { x = { { 0.00, "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то." }, { 8.09, "Я содрогаюсь при мысли о том, с каким извращённым разумом осуществляется связь посредством подобной магии." }, { 15.29, "Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу." } } } } },
    [9264] = { d = 37.1, v = "human-female#45", n = { x = 442 }, c = { x = { { 0.00, "Плеть стала лагерем у самых наших дверей. Мы не можем оставаться в бездействии!" }, { 5.17, "Встанешь ли ты на защиту Громового Утёса против этих проклятых захватчиков?" }, { 10.65, "Там, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху." }, { 19.89, "Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно." }, { 25.91, "Пока ты занимаешься этим, уменьши количество этих жутких тварей, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!" } } }, t = { d = 22.7, v = "human-female#45", n = { x = 267 }, c = { x = { { 0.00, "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то." }, { 8.16, "Я содрогаюсь при мысли о том, с каким извращённым разумом осуществляется связь посредством подобной магии." }, { 15.47, "Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу." } } } } },
    [9265] = { d = 38.0, v = "orc-male#60", n = { x = 437 }, c = { x = { { 0.00, "Плеть стала лагерем у самых наших дверей. Мы не можем оставаться в бездействии!" }, { 5.60, "Встанешь ли ты на защиту Подгорода против этих проклятых захватчиков?" }, { 10.99, "Там, снаружи, мы видели странные рунические круги, светящиеся той же самой энергией, которая окружает нежить и Некрополь там, наверху." }, { 20.30, "Я знаю, что эти круги имеют какое-то значение, и от тебя требуется узнать, какое именно." }, { 26.45, "Пока ты занимаешься этим, уменьши количество этих жутких тварей, предоставь мне доказательства сего вместе с результатом исследований, и я вознагражу тебя. Иди!" } } }, t = { d = 23.1, v = "orc-male#60", n = { x = 267 }, c = { x = { { 0.00, "Хмм. Судя по твоим словам, эти голоса внутри кругов... должно быть, эти круги используют для общения с кем-то или чем-то." }, { 8.21, "Я содрогаюсь при мысли о том, с каким извращённым разумом осуществляется связь посредством подобной магии." }, { 15.65, "Тем не менее тебе удалось остаться в живых и в здравом рассудке. Серебряный Рассвет ценит твою службу." } } } } },
    [9310] = { d = 7.0, v = "human-male#114", c = { x = { { 0.00, "На трупе павшей твари вы находите кристалл, излучающий тусклую некротическую энергию." } } }, t = { d = 14.1, v = "orc-male#60", c = { x = { { 0.00, "Это было у одной из тварей, напавших на город?" }, { 3.55, "Мы слышали о лагерях-некрополях, призванных Плетью. Я подозреваю, что они хотят создать такой лагерь в Подгороде. Впредь мы должны быть бдительными." } } } } },
    [9322] = { d = 39.3, v = "tauren-female#71", n = { x = 414 }, c = { x = { { 0.00, "Праздник Огненного солнцеворота отмечается повсюду в Азероте, и различные регионы Калимдора – не исключение." }, { 8.45, "Похоже, тебе приходилось много путешествовать, и у тебя есть опыт в странствиях." }, { 15.18, "Праздник Середины лета нельзя оценить должным образом, пока не увидишь горячие огни синего цвета." }, { 22.69, "Зажигаются костры в холодных западных регионах Зимних Ключей, в северо-восточной Азшаре, возле Покоя Доблестных в пустошах Силитуса и у входа в обширный ркатер Ун'Горо." }, { 35.79, "Возвращайся по завершении путешествия." } } }, t = { d = 10.0, v = "tauren-female#71", c = { x = { { 0.00, "Твой дух излучает тепло костров Калимдора. Разве оно не бодрит? Возможно, когда сила покинет тебя, ты ощутишь это чувство." } } } } },
    [9323] = { d = 39.3, g = 1, v = "tauren-female#71", c = { m = { { 0.00, "Огненный праздник распространился по всем землям, герой." }, { 4.44, "Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом. Найди их." }, { 14.47, "Один из них можно обнаружить к северу от Пика Чёрной горы." }, { 19.12, "Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утёсы гористых Внутренних Земель, и на пути к Тёмный портал в Выжженных землях." }, { 34.95, "Возвращайся, когда завершишь своё путешествие." } }, f = { { 0.00, "Огненный праздник распространился по всем землям, героиня." }, { 4.71, "Нет ни единого уголка, куда не проник бы жар этого празднества, а самые сильные огни пылают ярко-синим цветом. Найди их." }, { 14.75, "Один из них можно обнаружить к северу от Пика Чёрной горы." }, { 19.39, "Другие размещаются в глубине территории Восточных Чумных земель возле полуразрушенного города, вдоль дороги, ведущей на утёсы гористых Внутренних Земель, и на пути к Тёмный портал в Выжженных землях." }, { 35.32, "Возвращайся, когда завершишь своё путешествие." } } }, t = { d = 12.7, g = 1, v = "tauren-female#71", c = { m = { { 0.00, "А вот и ты. Немного уставший, пыльный, но просветлённый! Тепло эти костров объединяет нас всех, делая нас мудрее и сильнее." } }, f = { { 0.00, "А вот и ты. Немного уставшая, пыльная, но просветлённая! Тепло эти костров объединяет нас всех, делая нас мудрее и сильнее." } } } } },
    [9367] = { d = 41.0, v = "dwarf-male", c = { x = { { 0.00, "Вновь наступает праздник Огненного солнцеворота!" }, { 3.79, "Каждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажжёнными в наших столичных городах." }, { 14.80, "По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Середине Лета." }, { 24.07, "На самом деле, если ты не против, у меня для тебя есть задание." }, { 28.48, "Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах." }, { 34.71, "Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!" } } }, t = { d = 15.3, v = "dwarf-male", c = { x = { { 0.00, "Отлично! Кажется, мы назначили послушных Хранителей пламени в этом году, если костры так же хорошо хранятся, как вы утверждаете." }, { 8.89, "Спасибо, что осмотрели их для меня. Вот, возьмите это как небольшой знак моего уважения." } } } } },
    [9368] = { d = 55.2, v = "scourge-male#82", c = { x = { { 0.00, "Вновь наступает праздник Огненного солнцеворота!" }, { 4.90, "Каждый год, как диктует традиция, избираются Хранители праздничного костра, обязанные присматривать за этими самыми кострами, зажжёнными в наших столичных городах." }, { 19.61, "По всему Азероту зажигаются огни, но важно, чтобы наши горели жарче и ярче всех, дабы правильно воздать дань уважения Огненному солнцевороту." }, { 32.67, "На самом деле, если ты не против, у меня для тебя есть задание." }, { 38.52, "Мне пока неведомо, должным ли образом горят праздничные костры во всех столичных городах." }, { 46.89, "Отправляйся туда и погрейся у этих костров, чтобы убедиться, что они достаточно горячи!" } } }, t = { d = 13.0, v = "scourge-male#82", c = { x = { { 0.00, "Отличная работа. С тьмой покончено, остался только вопрос времени, когда Король Лич вспомнит о своих некрополях и решит оставить нас в покое." } } } } },
    [9388] = { d = 33.7, v = "dwarf-male", n = { x = 402 }, c = { x = { { 0.00, "Сегодня по всему миру горит множество огней." }, { 3.14, "Сложнее всего присматривать за теми кострами, которые пылают зелёным; без присмотра они не будут гореть долго." }, { 10.85, "Убедись, что изумрудные огни всё ещё горят в Калимдоре – пусть наш Хранитель костров успокоится." }, { 17.64, "Ты найдёшь эти костры вблизи Кабестана в Степях, неподалёку от Меча Властителя на Тёмном Берегу, в Ясеневом лесу у моста около Аванпоста Среброкрылых, и поблизости от дороги на Утёс Ветрорезов вдоль главного тракта в Когтистых горах." } } }, t = { d = 9.3, g = 1, v = "tauren-female#71", n = { m = 88, f = 91 }, c = { m = { { 0.00, "Ах, так значит, они всё ещё горят. Отлично, ты проделал превосходную работу. Вот, возьми это и будь благословен." } }, f = { { 0.00, "Ах, так значит, они всё ещё горят. Отлично, ты проделала превосходную работу. Вот, возьми это и будь благословенна." } } } } },
    [9389] = { d = 38.8, v = "dwarf-male", n = { x = 454 }, c = { x = { { 0.00, "Во время праздника Огненного солнцеворота по всей земле традиционно зажигаются мириады огней." }, { 6.53, "Кое-кто считает, что зелёное пламя является самым изящным, поскольку его труднее всего поддерживать, и оно имеет столь уникальный оттенок." }, { 16.30, "Убедись, что это пламя всё ещё горит в Восточных королевствах, чтобы успокоить нашего хранителя огня." }, { 23.22, "Эти костры размещены около Дун Модра в Болотине, поблизости от деревни Погребальных Костров в Серебряном бору, на утёсах неподалёку от маяка Западного края и возле разрушенной башни в предгорьях Хиллсбрада." } } }, t = { d = 17.1, g = 1, v = "tauren-female#71", n = { m = 158, f = 161 }, c = { m = { { 0.00, "Итак, ты вернулся и видел эти изумрудные огни. Что ты о них думаешь, а? Редкое и удивительное зрелище, не так ли?." }, { 8.93, "Что ж, ты провёл превосходную работу... пожалуйста, возьми это в знак моей благодарности." } }, f = { { 0.00, "Итак, ты вернулась и видела эти изумрудные огни. Что ты о них думаешь, а? Редкое и удивительное зрелище, не так ли?." }, { 10.04, "Что ж, ты провела превосходную работу... пожалуйста, возьми это в знак моей благодарности." } } } } },
    [9415] = { d = 13.6, v = "dwarf-male", n = { x = 147 }, c = { x = { { 0.00, "Ты новобранец маршала Синестена? Ну, конечно." }, { 3.40, "Чего ты ждёшь? Наши солдаты умирают там, в пустыне. Правда, тебе не терпится к ним присоединиться?" }, { 10.35, "Иди, и смотри, не присохни к песку по пути." } } }, t = { d = 14.1, v = "dwarf-male", c = { x = { { 0.00, "Альянсу нужна помощь всех, кто способен держать оружие." }, { 3.77, "Орда регулярно получает подкрепление с северной части континента, и мы изо всех сил стараемся от них не отстать. Позволь, я объясню тебе ситуацию." } } } } },
    [9416] = { d = 23.0, g = 1, v = "orc-male", c = { m = { { 0.00, "Должно быть, ты один из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся." }, { 8.71, "Дворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!" }, { 16.34, "Генерал тебя проинструктирует. Не моё дело – учить тебя. Мне приказали только найти тебя." } }, f = { { 0.00, "Должно быть, ты одна из новобранцев генерала Кирики. Пора тебе браться за дело. В пустыне тела очень быстро портятся." }, { 8.77, "Дворфы ежедневно получают подкрепление, а мы не должны им уступать. Полезные ископаемые Силитуса наши!" }, { 16.40, "Генерал тебя проинструктирует. Не моё дело – учить тебя. Мне приказали только найти тебя." } } }, t = { d = 8.1, v = "orc-female#58", c = { x = { { 0.00, "Хорошо, что ты здесь, но на любезности времени нет. Я проведу инструктаж, и ты сразу отправляйся в бой. Слушай." } } } } },
    [9419] = { d = 23.8, v = "dwarf-male", c = { x = { { 0.00, "Совсем недавно мы выяснили, что Орда добывает в Силитусе полезные ископаемые." }, { 5.19, "Мы думали, что в таком климате не стоит держать много войск." }, { 9.71, "К сожалению, выяснилось, насколько важны эти полезные ископаемые, и теперь мы тщетно пытаемся догнать Орду по масштабам добычи." }, { 18.77, "Если ты хочешь мне помочь, ступай в пустыню и принеси оттуда силитист." } } }, t = { d = 12.7, g = 1, v = "dwarf-male", n = { m = 139, f = 140 }, c = { m = { { 0.00, "Хвала Свету! Ты добился успеха!" }, { 2.80, "Начни мы добычу кристаллов раньше, не оказались бы в таком отчаянном положении." }, { 8.20, "Мы не допустим, чтобы сокровища пустыни попали в руки Орды." } }, f = { { 0.00, "Хвала Свету! Ты добилась успеха!" }, { 2.97, "Начни мы добычу кристаллов раньше, не оказались бы в таком отчаянном положении." }, { 8.36, "Мы не допустим, чтобы сокровища пустыни попали в руки Орды." } } } } },
    [9422] = { d = 23.0, v = "orc-female#58", c = { x = { { 0.00, "Мы давно начали добычу кристаллов пустыни Силитуса." }, { 3.73, "Поначалу мы сталкивались лишь с опасностями, исходящими от местных жителей, песка, пыли и жары." }, { 10.80, "Теперь же Альянс пронюхал, чем мы тут занимаемся, и началась гонка за добычей полезных ископаемых." }, { 18.13, "У меня каждая пара рук на счету, надеюсь, ты мне тоже поможешь." } } }, t = { d = 8.0, v = "orc-female#58", c = { x = { { 0.00, "Ты молодец. Мы отправим добытые ресурсы на склад, а наши приобретения всё равно что потери для наших врагов!" } } } } },
    [65593] = { d = 34.0, v = "scourge-male#83", n = { x = 362 }, c = { x = { { 0.00, "Инкуба привлекают сердца влюблённых, и чем крепче любовь, тем надёжнее приманка." }, { 6.41, "Своим незримым оком я вижу двоих, перед чьей любовью не устоит ни один инкуб." }, { 12.59, "Авелина Лилли из Серебряного бора шьёт одежду для павших чародеев Янтарной мельницы." }, { 18.77, "Исаак Пирсон из Степей надеется заработать состояние в приморском Кабестане." }, { 24.84, "Они трудятся, не зная отдыха, на разных концах света, но их сердца тоскуют лишь друг о друге. Принеси сердца Карендину." } } } },
    [65597] = { d = 33.2, v = "scourge-male#82", c = { x = { { 0.00, "Время наконец пришло. Отнеси сердца в круг призыва внизу. Положи их в центр и позови инкуба." }, { 10.95, "Когда демон поймёт, что его заманили в ловушку, ему это ох как не понравится. Сопротивляйся его попыткам обольстить тебя. Его надо подчинить себе полностью." }, { 25.35, "Только после этого я смогу научить тебя, как заставить демона выполнять твою волю." } } } },
    [65601] = { d = 36.3, g = 1, v = "orc-male", n = { m = 366, f = 367 }, c = { m = { { 0.00, "Мужчин-сайаадов называют инкубами. Эти существа исполнены злобы и изощрённой хитрости." }, { 8.38, "Демона можно привлечь в наш мир особой приманкой – символом великой дружбы и верности." }, { 14.71, "Если ты готов довериться слепому поводырю, то слушай. К востоку от Расселины Теней, у Волока Оргриммара, живёт Магар." }, { 23.81, "Он тоскует по Крилге, своей давно пропавшей подруге." }, { 27.95, "Найди Магара. Он попросит тебя отыскать некую ценность. Это и есть ключ, который надо отнести Ган'рулу." } }, f = { { 0.00, "Мужчин-сайаадов называют инкубами. Эти существа исполнены злобы и изощрённой хитрости." }, { 8.38, "Демона можно привлечь в наш мир особой приманкой – символом великой дружбы и верности." }, { 14.71, "Если ты готова довериться слепому поводырю, то слушай. К востоку от Расселины Теней, у Волока Оргриммара, живёт Магар." }, { 23.12, "Он тоскует по Крилге, своей давно пропавшей подруге." }, { 27.26, "Найди Магара. Он попросит тебя отыскать некую ценность. Это и есть ключ, который надо отнести Ган'рулу." } } } },
    [65602] = { d = 28.0, v = "human-male#50", c = { x = { { 0.00, "Чтобы призвать инкуба, нужен мощный реагент – символ дружбы и верности." }, { 5.02, "Я заглянул в прошлое сквозь туман времени и увидел небольшую статуэтку, которая годится для ритуала." }, { 12.05, "Тысячи лет назад она принадлежала двум друзьям. Они давно мертвы, но их реликвия сохранилась." }, { 18.59, "Иди по дороге в Ясеневый лес, потом сверни на запад и иди дальше мимо заставы Мейстры." }, { 24.42, "Ищи дом между деревьев – статуэтка находится в нём." } } } },
    [65603] = { d = 28.2, g = 1, v = "human-male#50", c = { m = { { 0.00, "Пора. Бери статуэтку и спускайся в гробницу. Круг призыва готов, поставь статуэтку точно в центре." }, { 6.95, "Откроются врата, и инкуб явится в наш мир." }, { 10.17, "Сайаадов нельзя недооценивать. Как только демон поймёт, что его обманули, он сразу атакует." }, { 16.29, "Используй всё, чему ты научился, чтобы победить его." }, { 20.23, "Если всё получится, возвращайся ко мне, и я подчиню демона твоей воле. Но если ты проиграешь, твоя душа обречена." } }, f = { { 0.00, "Пора. Бери статуэтку и спускайся в гробницу. Круг призыва готов, поставь статуэтку точно в центре." }, { 6.95, "Откроются врата, и инкуб явится в наш мир." }, { 10.17, "Сайаадов нельзя недооценивать. Как только демон поймёт, что его обманули, он сразу атакует." }, { 16.29, "Используй всё, чему ты научилась, чтобы победить его." }, { 20.23, "Если всё получится, возвращайся ко мне, и я подчиню демона твоей воле. Но если ты проиграешь, твоя душа обречена." } } } },
    [65604] = { d = 36.6, v = "orc-male", c = { x = { { 0.00, "Да... то, что нужно. Давние чувства переплелись с нитями ткани. Любовь проходит вдоль стежков. Инкуб не сможет устоять." }, { 10.06, "Отнеси это к кругу призыва в шатре Нииру. Вызови гнусного инкуба и покажи ему, кто здесь хозяин. Не жди лёгкой победы." }, { 20.48, "Приготовься пустить в ход всю свою магическую силу. Многие чернокнижники поплатились жизнью, недооценив демона." }, { 30.12, "Когда подчинишь инкуба, верни ткань мне. Нужно будет сообщить Магару о твоей находке." } } } },
    [65610] = { d = 28.0, v = "orc-male", c = { x = { { 0.00, "Я встретил Крилге, когда изготавливал луноткань в Ясеневом лесу." }, { 4.56, "Её отправили туда защищать местных жителей, но однажды она пропала..." }, { 9.81, "Её посчитали дезертиром и прекратили поиски, но я не верю, что она сбежала." }, { 15.58, "Мы часто ходили к Зеркалу Небес, пока озеро не заполонили дикие болотные твари." }, { 21.58, "Я редко прошу других об услуге, но буду рад, если ты поищешь в Ясеневом лесу её следы." } } } },
    [76156] = { d = 23.5, g = 1, v = "tauren-male", n = { x = 230 }, c = { m = { { 0.00, "Я чувствую в тебе талант к искусству скрытности, герой." }, { 4.32, "Возьми эту маску, проберись в ближайшую шахту Торговой Компании и укради их припасы." }, { 10.74, "Да, маски хватит – ловкий разбойник умеет усыпить бдительность одной лишь обаятельной улыбкой и хитроумным трюком. Тебе это тоже вполне под силу." } }, f = { { 0.00, "Я чувствую в тебе талант к искусству скрытности, героиня." }, { 4.50, "Возьми эту маску, проберись в ближайшую шахту Торговой Компании и укради их припасы." }, { 10.92, "Да, маски хватит – ловкий разбойник умеет усыпить бдительность одной лишь обаятельной улыбкой и хитроумным трюком. Тебе это тоже вполне под силу." } } } },
    [76160] = { d = 25.4, v = "tauren-male", n = { x = 253 }, c = { x = { { 0.00, "Быть может, у тебя склонность к ядам, а не к маскировке. К северу отсюда находится логово гарпий." }, { 8.28, "Они гнездятся на деревьях, которые вырабатывают необычайно ядовитую смолу. Собери упавшие шишки и разотри их в кашицу." }, { 17.52, "Если смазать ею клинок, любая рана прожжёт плоть до кости, а кровь посолонеет как морская вода." } } } },
    [76240] = { d = 21.6, v = "tauren-male", n = { x = 195 }, c = { x = { { 0.00, "Не будем терять надежду и попробуем в последний раз. Я всё ещё чувствую в тебе талант, но, как видно, с ходу его не раскрыть." }, { 11.07, "Достань мне сырую блестящую рыбку и разделай её этими кинжалами. Доверься инстинктам – пусть твои руки сами действуют." } } } },
    [78261] = { d = 36.4, v = "human-male#114", n = { x = 326 }, c = { x = { { 0.00, "В сундуке лежит записка. Привет!" }, { 2.93, "Меня интересует сокровище под названием рог Кселтоса, которое хранится где-то в крепости Тёмного Клыка." }, { 12.81, "Туда опасно ходить без боевых товарищей, но сейчас всё нужно сделать как можно тише. Поэтому ты пойдёшь в одиночку." }, { 22.13, "У меня есть агент в Когтистых горах – его зовут Виеникс. Он проведёт тебя за ворота во внутренний двор. Остальное за тобой." }, { 32.10, "Принеси рог сюда, и я сразу вышлю вознаграждение. С" } } } },
    [78270] = { d = 37.8, v = "human-male#114", n = { x = 341 }, c = { x = { { 0.00, "В сундуке лежит записка. Снова привет." }, { 3.36, "Меня интересует сокровище под названием рог Кселтоса, которое хранится где-то в крепости Тёмного Клыка." }, { 13.24, "Туда обычно не ходят без боевых товарищей, но на этот раз всё нужно сделать как можно тише. Поэтому ты пойдёшь в одиночку." }, { 23.01, "У меня есть агент в Когтистых горах – его зовут Виеникс. Он поможет тебе пройти за ворота во внутренний двор. Остальное за тобой." }, { 33.44, "Принеси рог сюда, и вскоре я вышлю вознаграждение. С." } } }, t = { d = 7.9, v = "goblin-male#110", n = { x = 89 }, c = { x = { { 0.00, "Отличная работа. Думаю, для человека твоего ремесла это была лёгкая прогулка. Как и обещано, вот твоя награда." } } } } },
    [79007] = { d = 18.2, v = "human-male#114", n = { x = 64 }, c = { x = { { 0.00, "Вы обнаруживаете пепелище, догорающие угли которого уже почти погасли." }, { 5.78, "Среди разбросанных припасов вам попадается обожжённый клочок бумаги." }, { 11.53, "\"Не всё, что горит, пропадает навечно. Найди земли близнецов, а в них – нужное место\"." } } } },
    [79008] = { d = 18.1, v = "human-male#114", n = { x = 64 }, c = { x = { { 0.00, "Вы обнаруживаете пепелище, догорающие угли которого уже почти погасли." }, { 5.92, "Среди разбросанных припасов вам попадается обожжённый клочок бумаги." }, { 11.37, "\"Не всё, что горит, пропадает навечно. Найди земли близнецов, а в них – нужное место\"." } } }, t = { d = 7.9, v = "human-male#114", n = { x = 82 }, c = { x = { { 0.00, "Наткнувшись на ещё один обугленный труп, вы замечаете послание, прикреплённое к деревянной доске." } } } } },
    [79090] = { d = 6.1, v = "human-male#114", n = { x = 63 }, c = { x = { { 0.00, "Часть всадников клана Песни Войны повержена, но битва всё ещё продолжается..." } } }, t = { d = 19.1, v = "human-male#114", n = { x = 195 }, c = { x = { { 0.00, "Эти захватчики из Орды всё ещё отравляют наши земли своим присутствием и крадут дары священной природы." }, { 8.28, "Продолжай борьбу, пока не прогонишь их!" }, { 11.59, "Этот священный боевой гимн, возможно, вдохновит тебя сражаться с ещё большим пылом. Спасибо." } } } } },
    [79192] = { d = 22.5, v = "human-male#114", n = { x = 239 }, c = { x = { { 0.00, "Записка начинается словами: \"В отчёте о задании сказано, что оба совершали поставки, связанные с новой чумой." }, { 8.34, "Мне кажется, с аптекарями нередко происходят подобные несчастные случаи." }, { 13.95, "Если хочешь поговорить в безопасном месте, найди моё уютное пристанище в горах между Степями и Пустошами\"." } } }, t = { d = 9.2, v = "human-male#114", n = { x = 96 }, c = { x = { { 0.00, "Очевидно, здесь встают лагерем наёмники и искатели приключений. Вы замечаете уголок записки, колышущийся на ветру." } } } } },
    [79362] = { d = 22.1, v = "troll-male#77", n = { x = 259 }, c = { x = { { 0.00, "Это щит, оставленный духом Бранта Вэлора, главы рода Вэлор и героя Вороньего Холма." }, { 6.03, "Дух Бранта всё ещё сражался с нежитью: возможно, его незавершённым делом на этой земле было покончить с воином Плети, который ранил его на кладбище Вороньего Холма." }, { 17.14, "Скорее всего, палица павшего героя так и застряла в теле того чудища." } } } },
    [79363] = { d = 22.8, v = "troll-male#77", n = { x = 271 }, c = { x = { { 0.00, "Это меч, оставленный духом стражницы Вороньего Холма, Сильвии Вэлор, которая провела всю жизнь, защищая горожан и их дома." }, { 8.64, "Дух Сильвии всё ещё скитался от фермы к ферме: возможно, её незавершённым делом на этой земле было изгнать разбойников из Братства Справедливости, которые захватили участок Эддла на юге от Вороньего Холма." } } } },
    [79731] = { d = 12.5, v = "human-male#114", n = { x = 81 }, c = { x = { { 0.00, "Древние знаки прямо у вас на глазах складываются в слова." }, { 4.80, "Когда фонтан Зул'Кунды наполнится водами священного источника, боги даруют своё благословение." } } }, t = { d = 10.5, v = "dwarf-male", n = { x = 116 }, c = { x = { { 0.00, "Волшебный фонтан, спрятанный в джунглях? Вот это история!" }, { 4.29, "Это подсказывает мне идею для новой главы моей книги! Так, куда же я положил рукопись..." } } } } },
    [79974] = { d = 16.8, v = "human-male#114", c = { x = { { 0.00, "\"Всегда стараюсь держать поблизости ещё один тайник на случай, если придётся внезапно бежать." }, { 7.39, "Склоны этой горы так красивы, словно их вырезали из водопадов времени." }, { 13.26, "Ищи гнездо орла. Именно оно тебе нужно\"." } } }, t = { d = 4.2, v = "human-male#114", n = { x = 43 }, c = { x = { { 0.00, "Инженерное мастерство дворфов: как всегда чудесно." } } } } },
    [79975] = { d = 27.4, v = "human-male#114", c = { x = { { 0.00, "В ящике с инструментами вы находите аккуратно сложенное письмо." }, { 5.04, "\"Отныне у тебя есть нужные инструменты, и всё зависит только от тебя. Отличное место для запуска параплана." }, { 13.62, "Моя верность орлу и кулаку предписывает служить им издали." }, { 18.02, "Эта баррикада видала лучшие дни – как и древние королевства, которые она когда-то защищала. Но я никогда её не покину\"." } } }, t = { d = 6.2, v = "human-male#114", n = { x = 63 }, c = { x = { { 0.00, "В костёр недавно положили хворост, но затем это место явно в спешке покинули." } } } } },
    [79976] = { d = 25.7, v = "human-male#114", c = { x = { { 0.00, "\"Придётся взять мои наработки и снова залечь на дно. Чтобы ничего не попало в руки тем, кому не следует\"." }, { 8.41, "Послание едва умещается на клочке бумаги." }, { 11.69, "Кто знает, последняя ли это записка этого автора, которую вы прочтёте, – или подсказка, ведущая к следующему укрытию." }, { 20.62, "У ваших ног разворачивается плохо упакованный спальный мешок..." } } }, t = { d = 6.1, v = "human-male#114", n = { x = 64 }, c = { x = { { 0.00, "Разнообразное снаряжение обмотано тяжёлым холстом. Вы подбираете свёрток." } } } } },
    [79980] = { d = 15.5, v = "human-male#114", n = { x = 157 }, c = { x = { { 0.00, "\"Неплохо, да? Раз ты это читаешь, мой тайник ещё не нашли." }, { 4.46, "Сделай сто шагов на север и не переломай ноги, спускаясь по крутому склону." }, { 10.37, "Содержимое тайника позволит тебе протянуть ещё какое-то время\"." } } }, t = { d = 7.7, v = "human-male#114", n = { x = 80 }, c = { x = { { 0.00, "Вы вытаскиваете из земли сумку посланника. Рядом с припасами в ней лежит испачканный пергамент." } } } } },
    [86574] = { d = 28.6, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "На теле несчастной видны следы многочисленных ударов величавых виверн." }, { 5.90, "Рядом лежит помятый пустой мешок, а курьер сжимает в руке лишь маленькую записку, благодаря которой можно понять, что было потеряно: груз, предназначавшийся для хозяйки таверны Фаралии на пике Каменного Когтя." }, { 22.30, "Виверны, должно быть, унесли связки припасов, чтобы выстелить ими свои гнёзда." } } } },
    [86576] = { d = 38.2, v = "human-male#114", n = { x = 394 }, c = { x = { { 0.00, "Гарпии Кровавой Ярости не только засоряют Обугленную долину, но и тянут все блестящие предметы, какие только подвернутся." }, { 9.60, "Говорят, они собирают самые разные золотисто-жёлтые солнечные камни для украшения гнёзд." }, { 16.60, "Мне такие безделушки не нужны, но Мор'рогал в прошлом упоминал о том, что их можно как-то использовать." }, { 24.98, "Сражаясь с гарпиями в долине, поглядывай по сторонам и собирай сверкающие солнечные камни." }, { 31.96, "Принеси всё, что тебе попадутся, Мор'рогалу – его ты найдёшь выше, на холмах." } } } },
    [86585] = { d = 35.4, v = "human-male#114", n = { x = 356 }, c = { x = { { 0.00, "Погибший горный пехотинец сжимает в руках знамя Стальгорна. Быть может, она проводила разведку или шла в безнадёжную атаку." }, { 9.61, "В любом случае знамя втоптали в грязь. Женщину-пехотинца так сильно ударили по голове, что с неё слетел шлем." }, { 18.06, "Она погибла сразу же – вероятно, от удара шипастой дубины трогга." }, { 23.52, "Убивший её трогг, наверное, всё ещё где-то поблизости и наверняка помнит это знамя." }, { 30.78, "Возможно, вновь поднятое знамя привлечёт его внимание." } } } },
    [86613] = { d = 12.7, v = "human-male#114", n = { x = 137 }, c = { x = { { 0.00, "Инструменты для раскопок, оставленные сбежавшими от троггов дворфами, выглядят почти нетронутыми." }, { 7.54, "Если вернуть их владельцам, тем наверняка будет проще работать." } } } },
    [86614] = { d = 14.0, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Среди рыболовных снастей в обломках лежат ржавые крючки, повреждённые катушки проволоки и слегка окислившаяся, но богато украшенная серебряная заколка для волос с монограммой Х.Р." } } } },
    [86667] = { d = 35.9, g = 1, v = "dwarf-female", n = { m = 411, f = 413 }, c = { m = { { 0.00, "Норрик, мой старый наставник, прислал мелкого элементаля со странной просьбой." }, { 5.42, "Ему нужен кувшин снега для каких-то шаманских обрядов!" }, { 9.28, "Не знаю, что он будет с ним делать, но я уже давно усвоила, что в его магических талантах сомневаться не стоит." }, { 17.24, "Я пока только устраиваюсь и занята изучением местных элементалей, поэтому не могу сейчас ему помочь. Не мог бы ты этим заняться?" }, { 26.03, "Отправляйся к Южным вратам – там снег лежит круглый год." }, { 29.89, "Набери немного в этот керамический кувшин и отнеси ему, пока снег не растаял." } }, f = { { 0.00, "Норрик, мой старый наставник, прислал мелкого элементаля со странной просьбой." }, { 5.42, "Ему нужен кувшин снега для каких-то шаманских обрядов!" }, { 9.28, "Не знаю, что он будет с ним делать, но я уже давно усвоила, что в его магических талантах сомневаться не стоит." }, { 17.24, "Я пока только устраиваюсь и занята изучением местных элементалей, поэтому не могу сейчас ему помочь." }, { 24.20, "Не могла бы ты этим заняться? Отправляйся к Южным вратам – там снег лежит круглый год." }, { 30.15, "Набери немного в этот керамический кувшин и отнеси ему, пока снег не растаял." } } } },
    [86758] = { d = 34.0, v = "dwarf-male", n = { x = 385 }, c = { x = { { 0.00, "Я когда-нибудь рассказывал тебе, как кроколиск чуть не отгрыз мне руку? Мне удалось вонзить ему в пасть нож и унести ноги." }, { 8.26, "Я думал, что нож остался у меня, но никак не могу его найти." }, { 12.77, "В любом случае этот кроколиск, вероятно, всё ещё выискивает добычу где-то на берегу озера." }, { 18.99, "Эту мерзкую зверюгу надо убить – хотя бы ради безопасности других охотников." }, { 24.63, "Я его прозвал Ножезубом. Если он тебе попадётся, передавай от меня привет!" }, { 29.64, "И под \"передавай привет\" я имею в виду \"поруби его в капусту\"." } } } },
    [86776] = { d = 22.9, v = "dwarf-male", n = { x = 268 }, c = { x = { { 0.00, "Телсамар – прекрасное место для жизни, но всех удобств Стальгорна тут нет. У меня постоянно заканчивается бронза!" }, { 7.77, "Мне нужно больше бронзы для изготовления инструментов, котелков и чайников!" }, { 13.27, "Я вижу, что у тебя есть опыт работы в кузнице. Как думаешь, сможешь выплавить для меня несколько бронзовых слитков? Я тебе хорошо заплачу!" } } } },
    [86784] = { d = 33.6, v = "dwarf-male", n = { x = 397 }, c = { x = { { 0.00, "Моя соратница Элеанор Шеклтон гордится тем, что путешествует по диким местам, выживая в схватке с непогодой и чудовищами." }, { 8.29, "Она разбила лагерь довольно близко, в холмах к западу." }, { 11.97, "Я помню совет, который она мне однажды дала: \"Когда тебе кажется, что дров уже достаточно, собери в пять раз больше\"." }, { 20.08, "Если у тебя найдётся свободное время, можешь собрать дров в эту корзину и отнести в её лагерь." }, { 26.40, "Уверен, она могла бы поделиться с тобой советами, полезными для странствующего искателя приключений." } } } },
    [87288] = { d = 33.8, g = 1, v = "nightelf-female#119", n = { m = 396, f = 397 }, c = { m = { { 0.00, "Привет, странник! Как тебе наша деревенька? Мне очень нравится в Доланааре – жизнь здесь простая, а жители дружелюбные." }, { 8.40, "Я местная торговка. У меня можно приобрести всевозможные инструменты и прочие вещи, которые могут пригодиться в путешествиях." }, { 17.15, "Кстати, мне сейчас нужны шкуры саблезубов и я готова за них заплатить." }, { 22.01, "Эти величественные звери, безусловно, прекрасны, но местные саблезубы очень агрессивные, так что не расстраивайся, если придётся убить кого-то из них для самозащиты." } }, f = { { 0.00, "Привет, странница! Как тебе наша деревенька? Мне очень нравится в Доланааре – жизнь здесь простая, а жители дружелюбные." }, { 8.52, "Я местная торговка. У меня можно приобрести всевозможные инструменты и прочие вещи, которые могут пригодиться в путешествиях." }, { 17.27, "Кстати, мне сейчас нужны шкуры саблезубов и я готова за них заплатить." }, { 22.13, "Эти величественные звери, безусловно, прекрасны, но местные саблезубы очень агрессивные, так что не расстраивайся, если придётся убить кого-то из них для самозащиты." } } } },
    [87760] = { d = 35.9, v = "nightelf-female", n = { x = 379 }, c = { x = { { 0.00, "Пришли вести из Дарнаса!" }, { 2.22, "Изучив образцы животных, мы узнали, что наги подчинили этих морских существ своей воле и заставляют их перевозить всадников и тяжёлые грузы." }, { 12.13, "А самых непокорных, старых и тяжело раненых они просто изгнали. Это чудовищно!" }, { 18.03, "Наш священный долг – остановить это!" }, { 20.89, "Силы наг обосновались возле руин Матистры. Должно быть, они охотятся на крепкозубов с ближайшего побережья." }, { 30.64, "Найди их укротительницу, убей её и принеси мне её жестокие инструменты!" } } } },
    [90902] = { d = 44.2, g = 1, v = "scourge-male#83", n = { m = 488, f = 486 }, c = { m = { { 0.00, "Я рад приветствовать в наших рядах ещё одного паладина, вернувшегося к жизни после смерти." }, { 6.53, "По мере того, как твоя связь со Светом восстанавливается, ты заметишь, что некоторые способности, в прошлом казавшиеся столь естественными, теперь могут причинять тебе сильную боль." }, { 19.56, "Особенно это касается тех, что позволяют тебе исцелять самого себя или кого-то ещё силой Света." }, { 27.06, "Как это ни печально, единственный способ справиться с этими трудностями – набраться терпения." }, { 34.51, "Как и при восстановлении атрофировавшихся мышц, тебе нужно превозмогать боль и закалять плоть, чтобы вернуть утраченные силы." } }, f = { { 0.00, "Я рад приветствовать в наших рядах ещё одного паладина, вернувшегося к жизни после смерти." }, { 6.53, "По мере того, как твоя связь со Светом восстанавливается, ты заметишь, что некоторые способности, в прошлом казавшиеся столь естественными, теперь могут причинять тебе сильную боль." }, { 19.58, "Особенно это касается тех, что позволяют тебе исцелять саму себя или кого-то ещё силой Света." }, { 26.95, "Как это ни печально, единственный способ справиться с этими трудностями – набраться терпения." }, { 34.41, "Как и при восстановлении атрофировавшихся мышц, тебе нужно превозмогать боль и закалять плоть, чтобы вернуть утраченные силы." } } }, t = { d = 21.8, g = 1, v = "scourge-male#83", n = { m = 213, f = 222 }, c = { m = { { 0.00, "Боль не в новинку тем, кто прошёл через смерть, и потому Отрёкшиеся особенно стойки к ней." }, { 6.60, "К тому же боль очищает – прими её как знак чести и доказательство того, что ты по-прежнему слуга Света, несмотря на всё, что с тобой случилось." }, { 17.40, "Будь здоров и вновь иди путём Света, герой." } }, f = { { 0.00, "Боль не в новинку тем, кто прошёл через смерть, и потому Отрёкшиеся особенно стойки к ней." }, { 6.60, "К тому же боль очищает – прими её как знак чести и доказательство того, что ты по-прежнему служительница Света, несмотря на всё, что с тобой случилось." }, { 17.96, "Будь здорова и вновь иди путём Света, героиня." } } } } },
    [91208] = { d = 33.9, v = "scourge-male#83", n = { x = 373 }, c = { x = { { 0.00, "Не всем нашим братьям-паладинам, вернувшимся к жизни, удаётся быстро приспособиться к новым условиям." }, { 7.49, "Некоторым трудно смириться с тем, что теперь они в некотором смысле стали тем, с чем боролись всю свою жизнь." }, { 15.86, "В таких случаях достаточно просто проявить к ним доброту и сочувствие. К сожалению, многие поддаются гневу." }, { 23.63, "Найди испуганных паладинов, сбежавших в холмы к западу от этой часовни." }, { 28.84, "Протяни им руку дружбы и помоги вернуться к Свету, если сможешь." } } }, t = { d = 22.4, g = 1, v = "scourge-male#83", n = { m = 233, f = 234 }, c = { m = { { 0.00, "Увы, немало наших братьев и сестёр после воскрешения впадают в такое же безумие." }, { 6.03, "Как ни дорога каждая душа Отрёкшегося, порой лучшее, что мы можем сделать для тех, кто не в силах смириться, – это даровать им лёгкий конец." }, { 16.65, "Я помолюсь Свету за неё. Спасибо, что сделал то, что должно быть сделано." } }, f = { { 0.00, "Увы, немало наших братьев и сестёр после воскрешения впадают в такое же безумие." }, { 6.03, "Как ни дорога каждая душа Отрёкшегося, порой лучшее, что мы можем сделать для тех, кто не в силах смириться, – это даровать им лёгкий конец." }, { 16.65, "Я помолюсь Свету за неё. Спасибо, что сделала то, что должно быть сделано." } } } } },
    [91209] = { d = 30.4, v = "scourge-male#83", n = { x = 331 }, c = { x = { { 0.00, "Лордерон уже не тот, что прежде, но наш дом по-прежнему нужно защищать от всевозможных угроз." }, { 6.89, "Пришло время тебе отправиться дальше и исследовать мир." }, { 11.14, "Отправляйся в город Брилл в центре Тирисфальских лесов и поговори с Шари Стилвелл. Она продолжит твоё обучение." }, { 19.68, "Дам тебе ещё последний совет: паладинам опасно в землях Отрёкшихся." }, { 24.69, "Многие слуги Тёмной Госпожи не доверяют нам из-за нашей близости к Свету." } } }, t = { d = 30.8, g = 1, v = "scourge-female#80", n = { x = 277 }, c = { m = { { 0.00, "Добро пожаловать, герой. Всегда отрадно видеть, что в этих землях становится больше наших." }, { 7.55, "Здесь, в Брилле, многим нужна помощь искателей приключений вроде тебя. Берись за работу и крепни в Свете." }, { 16.47, "А когда понадобится обучение – возвращайся ко мне." }, { 21.06, "Когда докажешь себя мне и жителям Брилла, я подскажу, куда двигаться дальше. Да пребудет с тобой Свет, герой." } }, f = { { 0.00, "Добро пожаловать, героиня. Всегда отрадно видеть, что в этих землях становится больше наших." }, { 7.94, "Здесь, в Брилле, многим нужна помощь искателей приключений вроде тебя. Берись за работу и крепни в Свете." }, { 16.85, "А когда понадобится обучение – возвращайся ко мне." }, { 21.44, "Когда докажешь себя мне и жителям Брилла, я подскажу, куда двигаться дальше. Да пребудет с тобой Свет, героиня." } } } } },
    [91282] = { d = 39.2, v = "scourge-female#80", n = { x = 372 }, c = { x = { { 0.00, "На душе всегда радостно, когда вернувшиеся к жизни братья и сёстры добиваются таких успехов, как ты." }, { 8.59, "Только благодаря единству и общей вере мы можем по-настоящему раскрыть свой потенциал." }, { 15.75, "С этой целью мы организуем новый орден паладинов прямо здесь, в Тирисфале." }, { 22.54, "Если хочешь узнать больше, то загляни в наш монастырь на Северной скале." }, { 28.73, "Он называется крепость Бандариона и находится на утёсах к северо-западу от усадьбы Соллиден – его трудно не заметить." } } }, t = { d = 5.0, g = 1, v = "scourge-male#83", n = { m = 46, f = 48 }, c = { m = { { 0.00, "Ещё один новобранец? Добро пожаловать в Дозор Тира, брат." } }, f = { { 0.00, "Ещё одна новобранка? Добро пожаловать в Дозор Тира, сестра." } } } } },
    [91285] = { d = 34.8, g = 1, v = "scourge-male#83", n = { m = 376, f = 377 }, c = { m = { { 0.00, "Обычно мы радушнее приветствуем новичков, но сейчас нам портят жизнь мурлоки." }, { 6.19, "В крепости раньше располагалось нерестилище их племени." }, { 10.29, "С тех пор, как мы сюда переехали и изгнали их, они попили немало нашей крови, но теперь ситуация действительно начинает выходить из-под контроля." }, { 21.14, "Судя по виду, ты уже очень многое повидал. Ты поможешь нам отвадить этих вредителей?" }, { 27.44, "Они прячутся на утёсах вдоль дороги на восток, а ещё несколько разбойничают в озере на западе." } }, f = { { 0.00, "Обычно мы радушнее приветствуем новичков, но сейчас нам портят жизнь мурлоки." }, { 6.19, "В крепости раньше располагалось нерестилище их племени." }, { 10.29, "С тех пор, как мы сюда переехали и изгнали их, они попили немало нашей крови, но теперь ситуация действительно начинает выходить из-под контроля." }, { 21.14, "Судя по виду, ты уже очень многое повидала. Ты поможешь нам отвадить этих вредителей?" }, { 27.49, "Они прячутся на утёсах вдоль дороги на восток, а ещё несколько разбойничают в озере на западе." } } }, t = { d = 14.5, v = "scourge-male#83", n = { x = 148 }, c = { x = { { 0.00, "Спасибо за помощь. Нападения это, конечно, не прекратит, но, надеюсь, хоть немного их поубавит." }, { 6.96, "Восстанавливать крепость и так нелегко, а тут ещё мурлоки норовят всадить копьё в спину." } } } } },
    [91294] = { d = 23.3, v = "scourge-male#83", n = { x = 229 }, c = { x = { { 0.00, "Теперь, когда угроза нападения мурлоков устранена, советую тебе осмотреть нашу крепость." }, { 6.55, "Выглядит не очень впечатляюще, но это наш дом." }, { 10.43, "Как обойдёшь её, найди Даниту Морр, нашего лидера. Она поможет тебе обустроиться." }, { 18.11, "Я очень рад, что мы с тобой познакомились. Да направит тебя Свет." } } }, t = { d = 31.2, v = "scourge-female", n = { x = 259 }, c = { x = { { 0.00, "Тебя прислал Бретон? Отлично." }, { 3.29, "Меня зовут Данита Морр, и здесь, в крепости, я ближе всех к тому, что можно назвать командиром." }, { 12.67, "Если ты ищешь братства среди тех, кто по-прежнему верен Свету, – ты по адресу." }, { 19.96, "Прежде чем мы прочно здесь обоснуемся, предстоит немало работы, и мы будем очень признательны, если ты согласишься помочь." } } } } },
    [91316] = { d = 40.0, v = "scourge-male#83", n = { x = 424 }, c = { x = { { 0.00, "На таком расстоянии от Подгорода логистика становится сущим кошмаром, и сейчас мы испытываем огромную нехватку стройматериалов, необходимых для восстановления крепости." }, { 12.23, "Твоя помощь в этом деле пришлась бы очень кстати." }, { 16.38, "В Шепчущем лесу к юго-западу отсюда совсем неподалёку ты найдёшь разрушенную деревню Тенедол." }, { 25.17, "В одном из строений должен быть старый погребок в корнях , где хранилась всякая всячина. Наверняка там отыщется что-нибудь полезное." }, { 34.95, "Забери оттуда всё, что может пригодиться, и возвращайся к нам." } } }, t = { d = 13.9, v = "scourge-male#83", n = { x = 150 }, c = { x = { { 0.00, "Рад, что твоя вылазка в Тенистый Дол оказалась не напрасной." }, { 4.51, "Позже отправлю туда Бретона с парой новобранцев – пусть разберут остатки погреба и вытащат всё, что ещё лежит там в темноте." } } } } },
    [91317] = { d = 49.2, g = 1, v = "scourge-female", n = { m = 447, f = 448 }, c = { m = { { 0.00, "Как ты, возможно, уже обратил внимание, не все восставшие из мёртвых паладины смирились со своей новой формой бытия." }, { 10.41, "Некоторые из них до сих пор одержимы предрассудками из прошлой жизни, и потому проявляют агрессию к своим новым братьям-Отрёкшимся." }, { 22.59, "К нам с недоверием относятся наши же собратья, которые пока ещё слишком хорошо помнят притеснения, творимые живыми во имя Света, и подобные неприятности нам совершенно ни к чему." }, { 38.30, "Группа таких \"Порочных\" обосновалась в Тенедоле, что к юго-западу отсюда. Перебей всех и принеси мне голову их лидера." } }, f = { { 0.00, "Как ты, возможно, уже обратила внимание, не все восставшие из мёртвых паладины смирились со своей новой формой бытия." }, { 10.52, "Некоторые из них до сих пор одержимы предрассудками из прошлой жизни, и потому проявляют агрессию к своим новым братьям-Отрёкшимся." }, { 22.70, "К нам с недоверием относятся наши же собратья, которые пока ещё слишком хорошо помнят притеснения, творимые живыми во имя Света, и подобные неприятности нам совершенно ни к чему." }, { 38.61, "Группа таких \"Порочных\" обосновалась в Тенедоле, что к юго-западу отсюда. Перебей всех и принеси мне голову их лидера." } } }, t = { d = 45.4, v = "scourge-female", n = { x = 354 }, c = { x = { { 0.00, "Отличная работа. Всякий раз, когда кто-то из омрачённых нападает и убивает Отрёкшегося, нашим недоброжелателям становится всё проще разжигать недоверие к паладинам." }, { 17.62, "Избавившись от них, мы продвинем наше дело и укрепим своё положение здесь, в Тирисфале." }, { 25.88, "Подозреваю, пройдёт немало времени, прежде чем Отрёкшиеся и Орда примут нас полностью. Годы... а может, и десятилетия." }, { 39.19, "Но всё, что нам остаётся, – раз за разом доказывать, чего мы стоим." } } } } },
    [91723] = { d = 20.2, v = "human-male", n = { x = 237 }, c = { x = { { 0.00, "Проклятие! Каждый раз, когда я пытаюсь настроить эту чувствительную магическую аппаратуру, всё идёт прахом из-за всплесков энергии." }, { 9.53, "Их источники, кажется, находятся на севере, где кобольды-недоумки занимаются своей грубой магией." }, { 16.02, "Можешь избавиться от них, чтобы я мог продолжить работу?" } } }, t = { d = 3.9, v = "human-male", n = { x = 40 }, c = { x = { { 0.00, "Прекрасно! Дай-ка ещё раз попробую всё настроить..." } } } } },
    [91724] = { d = 22.1, v = "human-male", n = { x = 251 }, c = { x = { { 0.00, "Почти готово... Ну-ка, ну-ка... Да чтоб вас Пустота поглотила! Что-то всё ещё мешает аппаратуре работать." }, { 7.35, "Как же это всё утомительно. Говорят, местные бандиты практикуются в магии рядом с озером Каменных Столбов." }, { 14.65, "Может, если остановишь их, всё наконец заработает как надо, и я смогу получить хоть какие-то результаты?" } } }, t = { d = 3.7, v = "human-male", n = { x = 41 }, c = { x = { { 0.00, "Кажется, всё наконец работает нормально. Спасибо." } } } } },
    [91725] = { d = 24.1, v = "gnome-female", n = { x = 278 }, c = { x = { { 0.00, "Наставник Теокрит велел мне забрать кое-какие припасы для наложения чар в торговой лавке, но на обратном пути на меня напала шайка гноллов!" }, { 10.05, "Мне удалось спастись, но припасы пришлось бросить." }, { 13.65, "Если я вернусь без них, то в наказание буду ещё много недель прибираться после экспериментов по превращению!" }, { 21.21, "Может, поможешь мне и найдёшь пропажу?" } } }, t = { d = 4.4, v = "gnome-female", n = { x = 44 }, c = { x = { { 0.00, "Ох, прямо гора с плеч! Кажется, всё на месте. Спасибо тебе!" } } } } },
    [91732] = { d = 20.2, v = "human-male", n = { x = 231 }, c = { x = { { 0.00, "После войны хорошей стали не хватает, и из-за этого инструменты наши не те, что прежде." }, { 6.11, "Шахтёры в Яшмовой шахте работали отличными стальными кирками, и некоторые из них наверняка ещё лежат где-то в глубине." }, { 14.32, "Можешь достать мне хоть немного? А я попробую что-нибудь сделать из этой стали." } } }, t = { d = 4.4, v = "human-male", n = { x = 43 }, c = { x = { { 0.00, "О, неплохо. Видишь, как блестит? Да, умели раньше делать." } } } } },
    [91733] = { d = 20.0, v = "human-male", n = { x = 221 }, c = { x = { { 0.00, "Я вёз припасы из торговой лавки, но моя повозка перевернулась, и груз оказался в реке!" }, { 5.99, "Я даже выловить его не успел – так быстро его унесло вниз по течению." }, { 11.20, "Там полно мурлоков и волков, так что самому мне припасы никак не вернуть. Ты, вроде бы, не робкого десятка. Сможешь их найти?" } } }, t = { d = 5.2, g = 1, v = "human-male", n = { m = 53, f = 54 }, c = { m = { { 0.00, "Вижу, ты порядком промок. Уж извини. Но спасибо, что вернул припасы." } }, f = { { 0.00, "Вижу, ты порядком промок. Уж извини. Но спасибо, что вернула припасы." } } } } },
    [91740] = { d = 10.6, v = "human-male#114", n = { x = 110 }, c = { x = { { 0.00, "Этот мурлок наверняка уже какое-то время держал в страхе окрестные дороги." }, { 5.68, "Вы полагаете, что местной страже стоит узнать о его гибели." } } }, t = { d = 9.9, g = 1, v = "human-female#45", n = { x = 107 }, c = { m = { { 0.00, "На той неделе от лап мурлоков погибли двое наших, герой." }, { 3.87, "Надеюсь, после смерти их вожака мы наконец сможем изгнать их из Элвиннского леса." } }, f = { { 0.00, "На той неделе от лап мурлоков погибли двое наших, героиня." }, { 4.03, "Надеюсь, после смерти их вожака мы наконец сможем изгнать их из Элвиннского леса." } } } } },
    [91741] = { d = 12.2, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Один из кобольдов уронил эту книгу. Похоже, он пытался её съесть." }, { 5.36, "У брата Пакстона в аббатстве есть небольшая библиотека. Вероятно, эта книга оттуда." } } }, t = { d = 15.6, g = 1, v = "human-male", n = { m = 171, f = 172 }, c = { m = { { 0.00, "Эй, откуда у тебя это? Она должна стоять на полке! О нет, кобольды опять принялись воровать мои книги. Наверняка пытаются их съесть!" }, { 9.59, "Спасибо, что вернул эту книгу, но как же мне быть с остатками пропавшей коллекции?" } }, f = { { 0.00, "Эй, откуда у тебя это? Она должна стоять на полке! О нет, кобольды опять принялись воровать мои книги. Наверняка пытаются их съесть!" }, { 9.59, "Спасибо, что вернула эту книгу, но как же мне быть с остатками пропавшей коллекции?" } } } } },
    [91743] = { d = 6.4, v = "human-male", n = { x = 69 }, c = { x = { { 0.00, "Эти ужасные кобольды поедают мои книги! Верни их, пока всю мою библиотеку не сожрали!" } } }, t = { d = 13.4, v = "human-male", n = { x = 141 }, c = { x = { { 0.00, "Огромное тебе спасибо! Вот, возьми одно из этих руководств – они мне не нужны." }, { 5.85, "Но сколько же ещё книг не найдено. Похоже, кобольды их всё-таки не едят. Что же они с ними тогда делают?" } } } } },
    [91745] = { d = 13.1, v = "human-male", n = { x = 153 }, c = { x = { { 0.00, "Поговори с новой ученицей горного дела, Келси Фарго." }, { 3.59, "Она работает прямо рядом с рудником и наверняка видела, чем занимаются кобольды." }, { 9.12, "Заодно можешь научиться у неё основам горного дела." } } }, t = { d = 9.7, v = "human-female#112", n = { x = 109 }, c = { x = { { 0.00, "Кобольды с книгами? Да, я видела кобольдов, которые бегали тут с книгами и орали друг на друга." }, { 6.65, "Видимо, украли из библиотеки в аббатстве." } } } } },
    [91746] = { d = 13.2, v = "human-male#114", n = { x = 139 }, c = { x = { { 0.00, "Этот трофей служит впечатляющим напоминанием о вашей победе над Вязолапом." }, { 5.76, "Возможно, местный охотник или специалист по снятию шкур захочет услышать рассказ об этом." } } }, t = { d = 12.8, g = 1, v = "human-female#47", n = { m = 151, f = 152 }, c = { m = { { 0.00, "Так ты одолел Вязолапа? Впечатляет!" }, { 2.75, "Позволь отблагодарить тебя за трофей – я знаю пару коллекционеров, которые щедро заплатят, чтобы повесить такое над камином, когда я его подготовлю." } }, f = { { 0.00, "Так ты одолела Вязолапа? Впечатляет!" }, { 2.77, "Позволь отблагодарить тебя за трофей – я знаю пару коллекционеров, которые щедро заплатят, чтобы повесить такое над камином, когда я его подготовлю." } } } } },
    [91751] = { d = 13.9, v = "human-female#47", n = { x = 172 }, c = { x = { { 0.00, "Хочешь попрактиковаться в снятии шкур? Обычно мой муж занимается охотой на волков, но он сейчас занят в аббатстве." }, { 7.52, "Мне бы как раз пригодилась помощь с добыванием шкур, чтобы я могла выполнить имеющиеся заказы." } } }, t = { d = 4.4, g = 1, v = "human-female#47", n = { x = 42 }, c = { m = { { 0.00, "Отличные шкуры, герой. У тебя настоящий охотничий талант." } }, f = { { 0.00, "Отличные шкуры, героиня. У тебя настоящий охотничий талант." } } } } },
    [91752] = { d = 23.8, v = "human-female#112", n = { x = 281 }, c = { x = { { 0.00, "Время от времени тут пробегают кобольды и орут что-то типа \"Картинки для Нарфа!\" Не знаю, кто такой этот Нарф." }, { 7.40, "Может быть, важный кобольд, живущий в глубине рудника? У него наверняка уже целый мешок этих книг." }, { 14.13, "Добудь их и принеси нашему местному стражу закона, маршалу Макбрайду. Только без друзей не ходи." }, { 20.55, "Кобольды в глубине рудника гораздо опаснее." } } }, t = { d = 10.2, g = 1, v = "human-male", n = { m = 108, f = 110 }, c = { m = { { 0.00, "Спасибо, что вернул украденные книги. Я немедленно доставлю их брату Пакстону." }, { 5.79, "Ты уже так много для всех нас сделал. Отличная работа!" } }, f = { { 0.00, "Спасибо, что вернула украденные книги. Я немедленно доставлю их брату Пакстону." }, { 5.89, "Ты уже так много для всех нас сделала. Отличная работа!" } } } } },
    [91753] = { d = 30.1, v = "human-female#45", n = { x = 366 }, c = { x = { { 0.00, "Академическая строгость, безусловно, необходима для ремесла зачаровывателя, но полученные на практике навыки тоже оказываются полезны." }, { 9.17, "Возьмём, к примеру, скромных кобольдов." }, { 11.72, "Не имея формального образования, они, тем не менее, демонстрируют определённые врождённые способности к использованию несложных заклинаний и чар." }, { 22.13, "Добудь несколько их восковых статуэток и разбери заключённые в них чары. Так ты вполне можешь многому научиться." } } }, t = { d = 4.3, v = "human-female#45", n = { x = 46 }, c = { x = { { 0.00, "Теория и практика – две стороны одной монеты. Запомни это." } } } } },
    [91758] = { d = 27.8, g = 1, v = "human-male", n = { m = 322, f = 323 }, c = { m = { { 0.00, "С кобольдами ты пока не закончил. Только что пришла весточка от Келси, что из рудника вышел кобольд, который нёс большой мешок книг." }, { 9.01, "Разыщи этого кобольда, чтобы мы могли вернуть книги брату Пакстону." }, { 14.11, "Ступай и поговори с Тордрином Мракорубом. Он новый наставник охотников, который недавно прибыл из Стальгорна." }, { 21.74, "Найдёшь его за аббатством, у конюшни. Он поможет тебе выследить воришку-кобольда." } }, f = { { 0.00, "С кобольдами ты пока не закончила. Только что пришла весточка от Келси, что из рудника вышел кобольд, который нёс большой мешок книг." }, { 9.06, "Разыщи этого кобольда, чтобы мы могли вернуть книги брату Пакстону." }, { 14.15, "Ступай и поговори с Тордрином Мракорубом. Он новый наставник охотников, который недавно прибыл из Стальгорна." }, { 21.79, "Найдёшь его за аббатством, у конюшни. Он поможет тебе выследить воришку-кобольда." } } }, t = { d = 6.1, v = "dwarf-male", n = { x = 62 }, c = { x = { { 0.00, "Я помогу тебе выследить этого вредителя. Дай-ка кое-что для тебя приготовлю." } } } } },
    [91772] = { d = 21.4, v = "dwarf-male", n = { x = 248 }, c = { x = { { 0.00, "Что ж. Возьми набор для выслеживания кобольдов. Он позволит тебе отыскать кобольда, который интересует маршала Макбрайда." }, { 8.64, "Иди по следам и принеси то, что найдёшь, маршалу Дугхану в Златоземье." }, { 13.83, "Нутром чую, эти вредители что-то затевают за пределами Североземья, так что тебе понадобится помощь Дугхана." } } }, t = { d = 14.9, v = "human-male", n = { x = 163 }, c = { x = { { 0.00, "Что это? Выслеживаешь кобольдов?" }, { 2.62, "Ну конечно же, они направляются на рудник Подземных Глубин! Там кобольдов не счесть." }, { 8.87, "Ладно, молодцом. Надо будет найти кого-нибудь, чтобы разобрались с этой проблемой." } } } } },
    [91775] = { d = 28.5, g = 1, v = "human-male", n = { m = 333, f = 333 }, c = { m = { { 0.00, "Когда будешь исследовать рудник Подземных Глубин, постарайся найти там книги брата Пакстона." }, { 6.43, "Его особенно беспокоит судьба работы под названием \"Элементали – это весело\"." }, { 11.67, "Он полагает, что с её помощью даже кобольды смогут призвать себе слугу-элементаля." }, { 17.40, "Будь осторожен – нижние ярусы рудника довольно опасны. Лучше захвати с собой друзей." }, { 23.45, "И возьми вот эту сумку! В ней найденные книги будут в безопасности." } }, f = { { 0.00, "Когда будешь исследовать рудник Подземных Глубин, постарайся найти там книги брата Пакстона." }, { 6.43, "Его особенно беспокоит судьба работы под названием \"Элементали – это весело\"." }, { 11.67, "Он полагает, что с её помощью даже кобольды смогут призвать себе слугу-элементаля." }, { 17.40, "Будь осторожна – нижние ярусы рудника довольно опасны. Лучше захвати с собой друзей." }, { 23.59, "И возьми вот эту сумку! В ней найденные книги будут в безопасности." } } }, t = { d = 14.4, g = 1, v = "human-male", n = { m = 164, f = 165 }, c = { m = { { 0.00, "Ты проявил замечательную внимательность. Брат Пакстон прислал список книг, и тебе удалось найти почти все пропавшие." }, { 8.04, "Остальные, вероятно, унесли в Яшмовую шахту." }, { 11.49, "Сумку для книг можешь оставить себе." } }, f = { { 0.00, "Ты проявила замечательную внимательность. Брат Пакстон прислал список книг, и тебе удалось найти почти все пропавшие." }, { 8.17, "Остальные, вероятно, унесли в Яшмовую шахту." }, { 11.63, "Сумку для книг можешь оставить себе." } } } } },
    [91777] = { d = 31.4, v = "human-male", n = { x = 363 }, c = { x = { { 0.00, "В списке брата Пакстона осталось всего две пропавшие книги: \"Геомантия для юных волшебников\" и \"Чародейский справочник: магические термины простыми словами\"." }, { 10.80, "Вероятно, кобольды унесли их в Яшмовую шахту. Прошу, разыщи эти книги и верни их брату Пакстону." }, { 17.83, "Только, боюсь, это будет весьма опасно." }, { 20.46, "Если кобольд-ученик сумел призвать элементаля, то можно лишь догадываться, на что будет способен его \"наставник\"." }, { 28.31, "Я бы на твоём месте взял с собой друзей." } } }, t = { d = 12.9, g = 1, v = "human-male", n = { m = 143, f = 146 }, c = { m = { { 0.00, "О! Спасибо тебе огромное! Ты спас мою библиотеку и оказал мне огромную услугу. Вот, выбирай любое оружие." }, { 7.41, "Оно было предназначено для ополченцев, но тебе явно больше пригодится." } }, f = { { 0.00, "О! Спасибо тебе огромное! Ты спасла мою библиотеку и оказала мне огромную услугу. Вот, выбирай любое оружие." }, { 7.62, "Оно было предназначено для ополченцев, но тебе явно больше пригодится." } } } } },
    [91858] = { d = 45.1, v = "scourge-female", n = { x = 410 }, c = { x = { { 0.00, "Крайне прискорбное стечение обстоятельств в Серебряном бору дало нам уникальную возможность выслужиться перед Ордой." }, { 10.94, "Два высокопоставленных лица из числа Служителей Земли пропали без вести в Серебряном бору по пути к Мельнице Таррен." }, { 21.28, "Нам об этом мало что известно, но ходят слухи, что дело попахивает настоящим дипломатическим скандалом." }, { 30.62, "Если мы найдём пропавших, это придаст нам веса и упрочит наш статус." }, { 37.24, "У нас есть в Гробнице надёжный контакт, Треван Рол. Отправляйся туда и поговори с ним." } } }, t = { d = 8.5, g = 1, v = "scourge-male", n = { m = 66, f = 67 }, c = { m = { { 0.00, "Тебя прислала Данита? Тогда я уже знаю, зачем ты здесь. Ну и в заварушку же ты угодил, герой." } }, f = { { 0.00, "Тебя прислала Данита? Тогда я уже знаю, зачем ты здесь. Ну и в заварушку же ты угодила, героиня." } } } } },
    [91859] = { d = 42.5, v = "scourge-male", n = { x = 418 }, c = { x = { { 0.00, "Перейдём сразу к делу: эти \"высокопоставленные лица\" – не простые дипломаты. Один таурен – это для Служителей Земли обычное дело." }, { 10.87, "А вот другая – хоть в такое и непросто поверить – эльфийка. Высшая эльфийка." }, { 16.38, "Оба были в плащах, но мне доводилось видеть кель'дорай, и я готов дать мизинец на отсечение, что она как раз из них." }, { 26.20, "Зачем эльфийке сопровождать таурена на территории Орды? Что ж, тут нам с тобой обоим остаётся лишь гадать." }, { 34.94, "Больше я ничего не знаю, поэтому советую поговорить со стражем смерти Балдреном у входа в город." } } }, t = { d = 10.5, g = 1, v = "scourge-male", n = { m = 98, f = 99 }, c = { m = { { 0.00, "Может, я и недолюбливаю вас, паладинов, но признаю: ты появился как нельзя вовремя. Лучше быть везучим, чем умелым, так ведь?" } }, f = { { 0.00, "Может, я и недолюбливаю вас, паладинов, но признаю: ты появилась как нельзя вовремя. Лучше быть везучим, чем умелым, так ведь?" } } } } },
    [91860] = { d = 44.1, v = "scourge-male", n = { x = 469 }, c = { x = { { 0.00, "Вчера во время патрулирования я заметил нескольких гноллов, взваливающих чьё-то массивное тело на костёр на берегу острова Фенриса." }, { 9.84, "Ни эльфийки, ни каких-либо трупов помельче я не видел, но, думаю, это всё равно ничего доброго не сулит." }, { 17.96, "Если у тебя хватит храбрости или глупости, можешь отправиться на остров Фенриса и разузнать побольше." }, { 25.64, "На мой взгляд, это слишком уж накладно – искать какую-то высокомерную эльфийку, которая к тому же наверняка давно мертва." }, { 34.91, "Я знаю, что вы, паладины, любите приносить клятвы и браться за безнадёжные дела, но оно того не стоит, можешь поверить." } } }, t = { d = 22.2, v = "scourge-male", n = { x = 0 }, c = { x = { { 0.00, "Перед вами, несомненно, труп таурена, и видно, что его сильно обглодали, прежде чем бросить на костёр." }, { 7.60, "Однако никаких следов эльфийки, о которой вам рассказывали, нет. Может, она ещё жива где-то в глубине крепости неподалёку?" }, { 17.03, "Это будет опасно, но узнать наверняка можно лишь одним способом." } } } } },
    [91861] = { d = 13.7, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Вы нашли только одно тело, и это обнадёживает." }, { 3.65, "Возможно, высшая эльфийка, о которой говорили Треван и Хадрик, всё ещё жива и находится где-то в глубине крепости неподалёку?" } } }, t = { d = 7.8, v = "skyborne-female", n = { x = 77 }, c = { x = { { 0.00, "Ты из Отрёкшихся, верно? Ты можешь меня освободить?" }, { 4.04, "Боюсь, времени у меня мало. Прошу, поторопись!" } } } } },
    [91862] = { d = 34.0, v = "skyborne-female", n = { x = 391 }, c = { x = { { 0.00, "Кель'дорай? Нет, я не из кель'дорай. Меня зовут Люмина Песнь Ветра, и я шен'дорай – одна из небеснорождённых Ваятелей Ветра." }, { 9.21, "Я пришла в эти края как гостья земельников." }, { 12.13, "Мы с моим спутником Баноном шли через Серебряный бор в нагорья Арати, чтобы исследовать там конвергенции стихий." }, { 19.42, "Увы, мы так и не смогли туда добраться." }, { 22.32, "Но сейчас не до того. Перебей гноллов, что бродят поблизости, найди у них ключ от этой клетки и выпусти меня." }, { 29.59, "Когда мы окажемся в безопасности, я расскажу тебе остальное." } } }, t = { d = 4.5, g = 1, v = "skyborne-female", n = { x = 39 }, c = { m = { { 0.00, "Спасибо, герой. К сожалению, опасность ещё не миновала." } }, f = { { 0.00, "Спасибо, героиня. К сожалению, опасность ещё не миновала." } } } } },
    [91920] = { d = 43.2, v = "scourge-male", n = { x = 462 }, c = { x = { { 0.00, "Я бы не осмелился усомниться в эффективности формул аптекаря Ренферрела, однако покривил бы душой, если бы сказал, что зелье заметно мне помогло." }, { 11.94, "На берегу озера Лордамер живёт стая мурлоков, и, что немаловажно, у них есть глаза." }, { 18.25, "Подозреваю, что готовность аптекаря пробовать что-то новое подавляется его нынешней одержимостью сердцами." }, { 26.34, "Принеси ему несколько глаз этих мурлоков." }, { 29.88, "Если мне приходится выбирать между неизбежной второй смертью и перспективой пасть от руки Ренферрела за то, что я ставлю под сомнение его профессионализм, то я выбираю последнее." } } }, t = { d = 35.6, g = 1, v = "scourge-male#82", n = { m = 280, f = 283 }, c = { m = { { 0.00, "Зелье не сработало? Ну конечно же не сработало. Всё потому, что ты мне принёс слишком мало сердец. В рецепте явно указано шесть. А ты добыл три." }, { 13.34, "Но должен признаться, что до сих пор не задумывался об использовании органов мурлоков... Ренферрел забирает у вас глаза." }, { 24.47, "Я могу себе позволить пожертвовать несколькими сердцами из моих запасов, чтобы вернуть тебе силу ловчего смерти." } }, f = { { 0.00, "Зелье не сработало? Ну конечно же не сработало. Всё потому, что ты мне принесла слишком мало сердец." }, { 9.22, "В рецепте явно указано шесть. А ты добыла три." }, { 13.91, "Но должен признаться, что до сих пор не задумывался об использовании органов мурлоков... Ренферрел забирает у вас глаза." }, { 24.87, "Я могу себе позволить пожертвовать несколькими сердцами из моих запасов, чтобы вернуть тебе силу ловчего смерти." } } } } },
    [91921] = { d = 16.6, v = "scourge-male#82", n = { x = 141 }, c = { x = { { 0.00, "Вот новое зелье, которое должно помочь Квинну выздороветь. Сделано с любовью, извлечённой из шести сердец." }, { 10.13, "А теперь прощай, а то из-за тебя у меня прибавится бумажной работы." } } }, t = { d = 10.2, g = 1, v = "scourge-male", n = { m = 76, f = 77 }, c = { m = { { 0.00, "Квинн выпивает зелье." }, { 2.33, "Да, я чувствую его действие. Вскоре я снова смогу передвигаться. Ты оказал мне большую услугу." } }, f = { { 0.00, "Квинн выпивает зелье." }, { 2.33, "Да, я чувствую его действие. Вскоре я снова смогу передвигаться. Ты оказала мне большую услугу." } } } } },
    [92109] = { d = 23.6, g = 1, v = "child-female", n = { m = 306, f = 306 }, c = { m = { { 0.00, "Э-э... привет, дяденька. Мне вообще-то нельзя разговаривать с незнакомцами, но..." }, { 4.56, "ой, а что это за блестящие бутылочки торчат у тебя из сумки? Ты что, алхимик? Как здорово!" }, { 10.24, "Когда я вырасту, я тоже буду алхимиком. Папа не разрешает мне играть с его травами. Он говорит, это слишком опасно." }, { 17.40, "Но я хочу учиться уже сейчас. Принесёшь мне немного алхимических припасов? Пожалуйста-препожалуйста!" } }, f = { { 0.00, "Э-э... привет, тётенька. Мне вообще-то нельзя разговаривать с незнакомцами, но..." }, { 4.52, "ой, а что это за блестящие бутылочки торчат у тебя из сумки? Ты что, алхимик? Как здорово!" }, { 10.20, "Когда я вырасту, я тоже буду алхимиком. Папа не разрешает мне играть с его травами. Он говорит, это слишком опасно." }, { 17.37, "Но я хочу учиться уже сейчас. Принесёшь мне немного алхимических припасов? Пожалуйста-препожалуйста!" } } }, t = { d = 10.1, g = 1, v = "child-female", n = { m = 105, f = 107 }, c = { m = { { 0.00, "Ух ты! Вот это да! Травы ты сам собрал?" }, { 3.22, "Спасибо, дяденька! Пойду прямо сейчас посмотрю, что из этого можно сделать! Хочешь посмотреть?" } }, f = { { 0.00, "Ух ты! Вот это да! Травы ты сама собрала?" }, { 2.97, "Спасибо, тётенька! Пойду прямо сейчас посмотрю, что из этого можно сделать! Хочешь посмотреть?" } } } } },
    [92110] = { d = 29.8, g = 1, v = "child-female", n = { m = 366, f = 368 }, c = { m = { { 0.00, "Ну и ну, моё первое зелье! А когда ты только начинал заниматься алхимией, ты знал, что смесь этих двух трав окрашивает зелье в ярко-красный цвет?" }, { 9.00, "Это было интересно, но мой папа не просто смешивает цветочки, а я хочу заниматься алхимией, как он! У него есть и другие ингредиенты." }, { 17.22, "Но я не знаю, что ещё нужно использовать, так что давай возьмём то, что первое придёт в голову! Хм... может, глаза мурлоков?" }, { 25.77, "Звучит мерзко, но они ведь наверняка дают какой-нибудь эффект." } }, f = { { 0.00, "Ну и ну, моё первое зелье! А когда ты только начинала заниматься алхимией, ты знала, что смесь этих двух трав окрашивает зелье в ярко-красный цвет?" }, { 8.94, "Это было интересно, но мой папа не просто смешивает цветочки, а я хочу заниматься алхимией, как он! У него есть и другие ингредиенты." }, { 17.17, "Но я не знаю, что ещё нужно использовать, так что давай возьмём то, что первое придёт в голову! Хм... может, глаза мурлоков?" }, { 25.72, "Звучит мерзко, но они ведь наверняка дают какой-нибудь эффект." } } }, t = { d = 35.1, g = 1, v = "child-female", n = { m = 281, f = 283 }, c = { m = { { 0.00, "Ты принёс мне глаза мурлоков! Я так рада, что сейчас будет моё первое НАСТОЯЩЕЕ зелье, что даже дышать не могу!" }, { 6.92, "Пока тебя не было, я тайком выбралась и нарвала ещё немного трав, а внизу нашла пустые склянки. Э-э... смешивать в этот раз будешь ты." }, { 15.85, "Девочка с восторгом наблюдает, как вы смешиваете ингредиенты, но морщит нос, когда вы добавляете глаза." }, { 21.90, "За считанные секунды варево приобретает болезненно-оранжевый цвет." }, { 26.24, "Ух ты! Видишь, я была права. Пить бы я такое не стала, но вот мой рецепт, если захочешь сделать ещё. Заходи как-нибудь!" } }, f = { { 0.00, "Ты принесла мне глаза мурлоков! Я так рада, что сейчас будет моё первое НАСТОЯЩЕЕ зелье, что даже дышать не могу!" }, { 7.77, "Пока тебя не было, я тайком выбралась и нарвала ещё немного трав, а внизу нашла пустые склянки. Э-э... смешивать в этот раз будешь ты." }, { 16.70, "Девочка с восторгом наблюдает, как вы смешиваете ингредиенты, но морщит нос, когда вы добавляете глаза." }, { 22.75, "За считанные секунды варево приобретает болезненно-оранжевый цвет." }, { 27.09, "Ух ты! Видишь, я была права. Пить бы я такое не стала, но вот мой рецепт, если захочешь сделать ещё. Заходи как-нибудь!" } } } } },
    [92124] = { d = 29.5, v = "human-male", n = { x = 339 }, c = { x = { { 0.00, "Нужно выяснить, сколько книг пропало!" }, { 3.10, "Ступай поговори с моим никчёмным помощником Даниэлем. Пусть осмотрит библиотеку и выяснит, насколько серьёзна проблема." }, { 11.78, "Он просто помешан на всяких ремёслах в Элвиннском лесу и постоянно тратит время на них вместо того, чтобы заниматься своими прямыми обязанностями, – помогать мне." }, { 23.10, "Не дай ему заболтать тебя рассказами о ремёслах и выясни, что случилось с моими книгами!" } } }, t = { d = 26.8, v = "human-male", n = { x = 297 }, c = { x = { { 0.00, "Да, я уже в курсе. Сто раз предупреждал брата Пакстона, что кобольды роют туннели под аббатством." }, { 7.12, "Похоже, они забрали много книг. Некоторые полки опустошены полностью." }, { 11.98, "Узнай у брата Пакстона, что он хочет сделать по этому поводу." }, { 16.97, "Кстати, пока ты ещё здесь, не хочешь поговорить о ремёслах?" }, { 20.98, "Я с радостью отвечу на любые вопросы и расскажу, где найти местных наставников." } } } } },
    [92401] = { d = 45.0, g = 1, v = "scourge-female", n = { m = 385, f = 385 }, c = { m = { { 0.00, "Мой муж Эдвард..." }, { 1.84, "Он каждую неделю ходит на кладбище в руинах Лордерона, но в это раз он не вернулся." }, { 9.41, "Наш сын погиб, когда Артас сравнял город с землёй, и мой милый Эдвард до сих пор винит себя и убивается из-за того, что мы так и не нашли его тело." }, { 22.53, "Я пыталась отговорить его от поисков в опасных руинах, но он отказывается сдаваться." }, { 30.21, "Я стараюсь не переживать, но прошло уже несколько дней." }, { 35.65, "Мне в руинах не уцелеть, но если ты согласен помочь, то мне просто необходимо узнать о судьбе мужа." } }, f = { { 0.00, "Мой муж Эдвард..." }, { 1.84, "Он каждую неделю ходит на кладбище в руинах Лордерона, но в это раз он не вернулся." }, { 9.41, "Наш сын погиб, когда Артас сравнял город с землёй, и мой милый Эдвард до сих пор винит себя и убивается из-за того, что мы так и не нашли его тело." }, { 22.62, "Я пыталась отговорить его от поисков в опасных руинах, но он отказывается сдаваться." }, { 30.30, "Я стараюсь не переживать, но прошло уже несколько дней." }, { 35.74, "Мне в руинах не уцелеть, но если ты согласна помочь, то мне просто необходимо узнать о судьбе мужа." } } }, t = { d = 22.5, g = 1, v = "scourge-female", n = { m = 189, f = 189 }, c = { m = { { 0.00, "Я просила о слишком многом, и никто не осудил бы тебя, если бы ты просто ушёл. Спасибо тебе, незнакомец." }, { 9.43, "Мне нечем отплатить тебе сполна, но, надеюсь, что-нибудь из этого подойдёт." }, { 16.62, "Надеюсь, наши пути ещё пересекутся – но уже без такой печали." } }, f = { { 0.00, "Я просила о слишком многом, и никто не осудил бы тебя, если бы ты просто ушла. Спасибо тебе, незнакомка." }, { 9.38, "Мне нечем отплатить тебе сполна, но, надеюсь, что-нибудь из этого подойдёт." }, { 16.57, "Надеюсь, наши пути ещё пересекутся – но уже без такой печали." } } } } },
    [92415] = { d = 18.3, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Рваный и запачканный пергамент, долгое время пролежавший на кишащем нежитью кладбище, сильно повредился." }, { 8.24, "В нём говорится о пропавшем ребёнке из семейства Хартвивер. Возможно, попечительница сирот из Штормграда что-то знает об этом." } } }, t = { d = 17.3, v = "human-female", n = { x = 194 }, c = { x = { { 0.00, "Хартвивер? Что-то знакомое..." }, { 2.30, "А! Был малютка Джереми Хартвивер. Он попал к нам несколько лет назад после нападения на Лордерон." }, { 9.07, "Бедняжка тогда потерял обоих родителей." }, { 12.24, "К слову, его недавно усыновила очень милая женщина из Сумеречного леса." } } } } },
    [92421] = { d = 40.2, v = "scourge-male", n = { x = 408 }, c = { x = { { 0.00, "Мой долг как паладина-Отрёкшегося – исполнять волю Тёмной Госпожи и заботиться о нашем народе." }, { 7.07, "Нам повезло, ведь у нас есть возможность исполнить обе задачи разом." }, { 12.62, "Над Подгородом до сих пор в огромных количествах бродят воины Плети." }, { 17.72, "Мы пытаемся отвоевать наши земли, но постоянно теряем солдат, а разлагающуюся плоть нельзя просто зашить. Но можно заменить." }, { 27.26, "Жаль, что наш славный капитан Гарек Бандарион больше не с нами, но я знаю, чего бы он хотел – завершить начатое и исцелить наш народ. За Лордерон!" } } }, t = { d = 16.9, v = "scourge-male", n = { x = 161 }, c = { x = { { 0.00, "Пусть те, кто лишился милости Королевы-банши, встретят наше правосудие!" }, { 5.70, "Благодаря этим частям тел у наших братьев и сестёр есть надежда прожить ещё один день. Капитан Бандарион гордился бы тобой." } } } } },
    [92422] = { d = 30.4, v = "scourge-male", n = { x = 332 }, c = { x = { { 0.00, "Пришли вести с обзорной площадки озера Лордамер, расположенной глубоко в руинах Лордерона." }, { 6.72, "Улицы и кладбище окутаны зловещим туманом, что позволяет тамошней Плети действовать скрытно." }, { 13.99, "Разведчики докладывают, что армию нежити постоянно пополняет некромант по имени Рат'маэль. Промедление смерти подобно." }, { 23.17, "Зови всех своих союзников и иди на помощь к Отрёкшимся. Изгони это существо из наших земель." } } }, t = { d = 9.7, v = "scourge-male", n = { x = 98 }, c = { x = { { 0.00, "Не сомневаюсь, что на его место придёт кто-то ещё из его породы, но будем надеяться, что до тех пор их ряды поредеют. Спасибо." } } } } },
    [92454] = { d = 29.0, v = "human-male#114", n = { x = 319 }, c = { x = { { 0.00, "Добро пожаловать в мир World of Warcraft!" }, { 3.07, "В знак особой благодарности за приобретение коллекционного издания вы получаете подарок!" }, { 9.80, "Передайте этот подарочный сертификат Далии Свежий Ветер в Тендалской роще." }, { 15.61, "Взамен вы получите маленького спутника, который будет сопровождать вас на пути к славе." }, { 22.77, "Ещё раз благодарим вас и желаем приятного времяпровождения в мире World of Warcraft!" } } } },
    [92460] = { d = 28.2, g = 1, v = "skyborne-female#3773", n = { m = 316, f = 315 }, c = { m = { { 0.00, "А вот и ты! Без сомнения, полон энтузиазма и готов к приключениям!" }, { 4.62, "Мы ждали твоего прибытия в деревню Тендал и надеемся на твою помощь. Наверняка ты весь дрожишь от предвкушения." }, { 11.87, "В конце концов, совершеннолетие бывает лишь раз в жизни. Айлия по-доброму улыбается." }, { 17.76, "Ступай, найди предводителя нашей деревни Рориана Искателя Утра на пути к старому дереву. Это к западу отсюда." }, { 25.57, "Он поможет тебе начать путешествие." } }, f = { { 0.00, "А вот и ты! Без сомнения, полна энтузиазма и готова к приключениям!" }, { 4.74, "Мы ждали твоего прибытия в деревню Тендал и надеемся на твою помощь. Наверняка ты вся дрожишь от предвкушения." }, { 11.93, "В конце концов, совершеннолетие бывает лишь раз в жизни. Айлия по-доброму улыбается." }, { 17.82, "Ступай, найди предводителя нашей деревни Рориана Искателя Утра на пути к старому дереву. Это к западу отсюда." }, { 25.63, "Он поможет тебе начать путешествие." } } }, t = { d = 33.5, g = 1, v = "skyborne-male", n = { m = 382, f = 383 }, c = { m = { { 0.00, "Приветствую! Для меня честь вручить тебе эту реликвию к совершеннолетию. В тебе скрыт огромный потенциал, который послужит шен'дорай." }, { 9.78, "У нашего народа сложная история, и мы пережили много горя и гонений." }, { 14.84, "Сегодня в твои руки переходит одна из реликвий, когда-то принадлежавших твоим предшественникам." }, { 21.24, "Однажды, когда твой прах будет развеян, её получит кто-то ещё, и традиция будет продолжена." }, { 27.84, "Держи её и помни: ветер из дома всегда будет с тобой, где бы ты ни странствовал." } }, f = { { 0.00, "Приветствую! Для меня честь вручить тебе эту реликвию к совершеннолетию. В тебе скрыт огромный потенциал, который послужит шен'дорай." }, { 9.78, "У нашего народа сложная история, и мы пережили много горя и гонений." }, { 14.84, "Сегодня в твои руки переходит одна из реликвий, когда-то принадлежавших твоим предшественникам." }, { 21.24, "Однажды, когда твой прах будет развеян, её получит кто-то ещё, и традиция будет продолжена." }, { 27.84, "Держи её и помни: ветер из дома всегда будет с тобой, где бы ты ни странствовала." } } } } },
    [92461] = { d = 23.9, v = "skyborne-male", n = { x = 284 }, c = { x = { { 0.00, "Мы живём во времена великой неопределённости, часто требующей от нас смелых решений. Но бывают и повседневные проблемы." }, { 8.07, "Вот, к примеру, популяция лисвенов слишком разрослась." }, { 12.04, "Они неотъемлемая часть нашей экосистемы. Но когда лисвены угрожают хрупкому равновесию в Тендалской роще, мы должны вмешаться." }, { 20.85, "Ступай на восток и убей часть лисвенов." } } }, t = { d = 16.0, g = 1, v = "skyborne-male", n = { x = 168 }, c = { m = { { 0.00, "Спасибо за помощь Зефрису, герой." }, { 2.69, "Обычно лисвены смирные, но все звери на Зефрисе чуют, когда магия ветров выходит из равновесия." }, { 9.23, "И если ничего с этим не делать, они могут начать вести себя опасно и непредсказуемо." } }, f = { { 0.00, "Спасибо за помощь Зефрису, героиня." }, { 3.00, "Обычно лисвены смирные, но все звери на Зефрисе чуют, когда магия ветров выходит из равновесия." }, { 9.53, "И если ничего с этим не делать, они могут начать вести себя опасно и непредсказуемо." } } } } },
    [92462] = { d = 17.2, v = "skyborne-male", n = { x = 202 }, c = { x = { { 0.00, "Один из наших следопытов недавно сообщил, что в Тендалской роще развелось много щетинистых ос." }, { 6.77, "Если дать рою слишком разрастись, он может стать опасным, так что, пожалуйста, ступай в восточную часть рощи и уничтожь как можно больше щетинистых ос." } } }, t = { d = 6.2, g = 1, v = "skyborne-male", n = { m = 68, f = 69 }, c = { m = { { 0.00, "Судя по тому, что ты с ног до головы покрыт кусками насекомых, ос и правда было немало." } }, f = { { 0.00, "Судя по тому, что ты с ног до головы покрыта кусками насекомых, ос и правда было немало." } } } } },
    [92463] = { d = 21.0, g = 1, v = "skyborne-male", n = { m = 239, f = 239 }, c = { m = { { 0.00, "Если этих насекомых в лесу и правда так много, то убить рабочих недостаточно." }, { 5.58, "Зайди глубже в лес и отыщи матку. Она должна быть недалеко от улья и в окружении крупных и агрессивных защитников, так что будь осторожен." }, { 15.30, "Избавься от матки и возвращайся сюда. Так у нас станет на одну проблему меньше." } }, f = { { 0.00, "Если этих насекомых в лесу и правда так много, то убить рабочих недостаточно." }, { 5.58, "Зайди глубже в лес и отыщи матку. Она должна быть недалеко от улья и в окружении крупных и агрессивных защитников, так что будь осторожна." }, { 15.29, "Избавься от матки и возвращайся сюда. Так у нас станет на одну проблему меньше." } } }, t = { d = 6.7, v = "skyborne-male", n = { x = 79 }, c = { x = { { 0.00, "Чудесно. Если с искательством приключений дело не выгорит, из тебя выйдет прекрасный следопыт." } } } } },
    [92464] = { d = 28.4, v = "skyborne-male", n = { x = 321 }, c = { x = { { 0.00, "С тех пор как наши благодетели из мира стихий оставили нас, мы не знаем покоя." }, { 5.24, "Вот и теперь – разбушевались порождения ветра, что обитают у камней к северо-востоку." }, { 11.27, "Они не обладают истинным разумом, как духи ветра, жившие здесь прежде, но реагируют на эмоции и намерения существ вокруг." }, { 19.91, "Моя ученица Яла Загонщица Ветров отправилась понаблюдать за ними. Отыщи её и выясни, что ей удалось разузнать." } } }, t = { d = 4.7, v = "skyborne-female", n = { x = 50 }, c = { x = { { 0.00, "Тебя прислал Рориан? Прекрасно. Мне понадобится твоя помощь." } } } } },
    [92465] = { d = 19.7, g = 1, v = "skyborne-female", n = { x = 216 }, c = { m = { { 0.00, "Секта Ал'акет – настоящее проклятие этого острова. Наверняка именно сектанты разозлили духов ветра, живущих здесь." }, { 8.73, "К сожалению, нам придётся угомонить ревущие ветра, пока кто-нибудь не пострадал." }, { 14.01, "А ещё надо дать сектантам ясно понять: в роще им не рады. Поможешь нам, герой?" } }, f = { { 0.00, "Секта Ал'акет – настоящее проклятие этого острова. Наверняка именно сектанты разозлили духов ветра, живущих здесь." }, { 8.73, "К сожалению, нам придётся угомонить ревущие ветра, пока кто-нибудь не пострадал." }, { 14.01, "А ещё надо дать сектантам ясно понять: в роще им не рады. Поможешь нам, героиня?" } } }, t = { d = 5.9, v = "skyborne-female", n = { x = 67 }, c = { x = { { 0.00, "Мне больно проливать в роще кровь шен'дорай, но мы должны делать то, что необходимо." } } } } },
    [92466] = { d = 27.6, v = "skyborne-male", n = { x = 330 }, c = { x = { { 0.00, "Хотя мы во многом процветаем благодаря стихии ветра, наш путь требует, чтобы мы слушали зов всех четырёх стихий и проходили испытания каждой." }, { 9.55, "Но прежде чем ты по-настоящему приступишь к первому испытанию, надо проверить твою решимость." }, { 16.13, "Ступай к стоячим камням на востоке. Там обнаружили ал'акетских новообращённых, и с ними надо разобраться." }, { 23.26, "Вступи в бой с сектантами и принеси мне один из их перстней." } } }, t = { d = 9.4, g = 1, v = "skyborne-male", n = { m = 106, f = 110 }, c = { m = { { 0.00, "Ты вернулся и принёс то, что я просил, а значит, в твоей стойкости и решимости сомневаться не приходится. Ты готов к следующему шагу." } }, f = { { 0.00, "Ты вернулась и принесла то, что я просил, а значит, в твоей стойкости и решимости сомневаться не приходится. Ты готова к следующему шагу." } } } } },
    [92467] = { d = 26.4, g = 1, v = "skyborne-male", n = { m = 307, f = 307 }, c = { m = { { 0.00, "Сапта – это напиток, который связывает душу со стихией. Насыщенное магией зелье позволяет тем, кто силён духом, видеть незримое." }, { 8.52, "Твой дух будет связан с той стихией, для которой сварили сапту. Лишь немногие шаманы знают её рецепт." }, { 15.59, "И запомни: сапту можно пить лишь в священном месте и нигде более!" }, { 20.28, "Отыщи Вершину Духов к северо-востоку отсюда. Выпей там сапту и увидишь то, что должен!" } }, f = { { 0.00, "Сапта – это напиток, который связывает душу со стихией. Насыщенное магией зелье позволяет тем, кто силён духом, видеть незримое." }, { 8.52, "Твой дух будет связан с той стихией, для которой сварили сапту. Лишь немногие шаманы знают её рецепт." }, { 15.59, "И запомни: сапту можно пить лишь в священном месте и нигде более!" }, { 20.28, "Отыщи Вершину Духов к северо-востоку отсюда. Выпей там сапту и увидишь то, что должна!" } } }, t = { d = 52.5, g = 1, v = "elemental-earth", n = { x = 342 }, c = { m = { { 0.00, "А... путник... дитя четырёх ветров... Ты ищешь понимания. Ищешь ответов. Почему ветра покинули тебя? Как вернуть их?" }, { 14.48, "Этих ответов я дать не могу, ибо мне неведомы ни помыслы, ни пути ветров." }, { 23.64, "Но я могу многое поведать тебе о земле. О её силе, о её стойкости." }, { 31.43, "Даже здесь, высоко над бескрайним морем облаков, ты остаёшься созданием земли." }, { 39.58, "Если хочешь обрести силу, чтобы вновь говорить с духами четырёх ветров, – вот путь, которым тебе надлежит идти." } }, f = { { 0.00, "А... путница... дитя четырёх ветров... Ты ищешь понимания. Ищешь ответов. Почему ветра покинули тебя? Как вернуть их?" }, { 13.26, "Этих ответов я дать не могу, ибо мне неведомы ни помыслы, ни пути ветров." }, { 22.42, "Но я могу многое поведать тебе о земле. О её силе, о её стойкости." }, { 30.22, "Даже здесь, высоко над бескрайним морем облаков, ты остаёшься созданием земли." }, { 38.36, "Если хочешь обрести силу, чтобы вновь говорить с духами четырёх ветров, – вот путь, которым тебе надлежит идти." } } } } },
    [92468] = { d = 60.9, g = 1, v = "elemental-earth", n = { m = 384, f = 385 }, c = { m = { { 0.00, "Возьми этот необработанный кварц и отнеси его тому, кого зовёшь Ваятель ветра Боро, в доказательство того, что мы с тобой встречались." }, { 17.42, "Он изготовит для тебя тотэм, и этот фрагмент будет его сердцем." }, { 24.58, "Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого." }, { 37.98, "Будь терпелив. Оставайся сильным. И ищи мудрости. Этого от тебя требуют стихии." }, { 47.50, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } }, f = { { 0.00, "Возьми этот необработанный кварц и отнеси его тому, кого зовёшь Ваятель ветра Боро, в доказательство того, что мы с тобой встречались." }, { 20.50, "Он изготовит для тебя тотэм, и этот фрагмент будет его сердцем." }, { 27.67, "Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого." }, { 41.06, "Будь терпелива. Оставайся сильной. И ищи мудрости. Этого от тебя требуют стихии." }, { 50.70, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } } }, t = { d = 25.9, g = 1, v = "skyborne-male", n = { m = 300, f = 301 }, c = { m = { { 0.00, "Хорошо!" }, { 0.98, "Тотэм, который я для тебя изготовлю, – не просто знак твоего положения среди шаманов, у него есть и другие свойства." }, { 8.58, "Например, он служит средоточием для заклинаний." }, { 11.79, "Эти заклинания связаны с землёй, и чем больше мудрости ты обретёшь, тем больше сил земли станет тебе доступно." }, { 19.54, "Наставники поймут, когда ты будешь готов к новым знаниям. А пока возьми этот тотэм земли..." } }, f = { { 0.00, "Хорошо!" }, { 0.98, "Тотэм, который я для тебя изготовлю, – не просто знак твоего положения среди шаманов, у него есть и другие свойства." }, { 8.58, "Например, он служит средоточием для заклинаний." }, { 11.79, "Эти заклинания связаны с землёй, и чем больше мудрости ты обретёшь, тем больше сил земли станет тебе доступно." }, { 19.54, "Наставники поймут, когда ты будешь готова к новым знаниям. А пока возьми этот тотэм земли..." } } } } },
    [92469] = { d = 12.1, g = 1, v = "skyborne-female", n = { m = 129, f = 130 }, c = { m = { { 0.00, "На сегодня ты сделал достаточно, герой. Я останусь здесь и добью остальных." }, { 5.50, "Иди в деревню и расскажи Рориану о том, что тут появились сектанты. Он точно не обрадуется." } }, f = { { 0.00, "На сегодня ты сделала достаточно, героиня. Я останусь здесь и добью остальных." }, { 5.61, "Иди в деревню и расскажи Рориану о том, что тут появились сектанты. Он точно не обрадуется." } } }, t = { d = 18.0, g = 1, v = "skyborne-male", n = { m = 207, f = 208 }, c = { m = { { 0.00, "Вести мрачные, но, увы, ожидаемые. Мы уже давно знали о действиях сектантов, но лишь наблюдали за ними издалека." }, { 7.57, "Однако то, что они разгневали духов ветра у стоячих камней, – это уже слишком." }, { 13.01, "Ты оказал Тендалской роще тяжёлую, но необходимую услугу. Благодарю." } }, f = { { 0.00, "Вести мрачные, но, увы, ожидаемые. Мы уже давно знали о действиях сектантов, но лишь наблюдали за ними издалека." }, { 7.57, "Однако то, что они разгневали духов ветра у стоячих камней, – это уже слишком." }, { 13.01, "Ты оказала Тендалской роще тяжёлую, но необходимую услугу. Благодарю." } } } } },
    [92470] = { d = 21.5, v = "skyborne-female#3773", n = { x = 255 }, c = { x = { { 0.00, "Рориан наверняка сказал, что я за тобой наблюдаю. Теперь же я предлагаю тебе проверку на твёрдость." }, { 6.42, "Только имей в виду, дело предстоит опасное." }, { 9.44, "Прореди стаю медвер и отыщи их матриарха. Следопыты зовут её Урс'ана." }, { 14.48, "Расправься с ней и принеси мне доказательство того, что она мертва. Это будет важный шаг на твоём пути." } } }, t = { d = 11.7, g = 1, v = "skyborne-female#3773", n = { m = 134, f = 135 }, c = { m = { { 0.00, "Замечательно. Ты одолел диких зверей и бесчестных сектантов." }, { 4.63, "Что-то в тебе определённо есть, но скоро путь уведёт тебя из относительно безопасной деревни Тендал." } }, f = { { 0.00, "Замечательно. Ты одолела диких зверей и бесчестных сектантов." }, { 4.35, "Что-то в тебе определённо есть, но скоро путь уведёт тебя из относительно безопасной деревни Тендал." } } } } },
    [92471] = { d = 28.2, g = 1, v = "skyborne-male", n = { m = 330, f = 332 }, c = { m = { { 0.00, "Возможно, ты не догадывался, но всё, что ты делал, было своего рода испытанием, чтобы подготовить тебя к тому, что грядёт." }, { 8.13, "Зефрис – большой остров, и чтобы наш народ пережил все невзгоды, нужны отважные молодые искатели приключений. Такие, как ты." }, { 16.69, "Одна из наших предводительниц на острове Зефрис – Эфин Штормовая, и она внимательно следила за тобой." }, { 23.45, "У неё есть для тебя задание. Поговори с ней, чтобы узнать больше." } }, f = { { 0.00, "Возможно, ты не догадывалась, но всё, что ты делала, было своего рода испытанием, чтобы подготовить тебя к тому, что грядёт." }, { 8.27, "Зефрис – большой остров, и чтобы наш народ пережил все невзгоды, нужны отважные молодые искатели приключений. Такие, как ты." }, { 16.83, "Одна из наших предводительниц на острове Зефрис – Эфин Штормовая, и она внимательно следила за тобой." }, { 23.58, "У неё есть для тебя задание. Поговори с ней, чтобы узнать больше." } } }, t = { d = 20.1, g = 1, v = "skyborne-female#3773", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Рориан много рассказывал о тебе. Ты, скорее всего, меня не знаешь, но я принадлежу к Совету старейшин острова Зефрис." }, { 7.55, "Я читаю потоки ветра в Тендалской роще, а ещё оцениваю молодых шен'дорай вроде тебя, готовых стать взрослыми." }, { 15.15, "Скажи, готов ли ты сделать следующий шаг и послужить острову Зефрис?" } }, f = { { 0.00, "Рориан много рассказывал о тебе. Ты, скорее всего, меня не знаешь, но я принадлежу к Совету старейшин острова Зефрис." }, { 7.61, "Я читаю потоки ветра в Тендалской роще, а ещё оцениваю молодых шен'дорай вроде тебя, готовых стать взрослыми." }, { 15.12, "Скажи, готова ли ты сделать следующий шаг и послужить острову Зефрис?" } } } } },
    [92472] = { d = 29.3, v = "skyborne-female#3773", n = { x = 342 }, c = { x = { { 0.00, "Одна из самых давних угроз острову Зефрис – секта Ал'акет." }, { 3.85, "Это религиозные фанатики, преданные Ал'акиру Владыке Ветра, который якобы должен править Небесной высью." }, { 10.74, "Они жестоки и упрямы, а их сила и амбиции становятся всё опаснее с каждым днём." }, { 16.21, "Скоро ты отправишься в деревню Шен'дар к югу отсюда. Поговори с констеблем Аондой, когда прибудешь туда." }, { 22.88, "Секта угрожает Шен'дару, и деревне нужна помощь. Скажи Аонде, что ты от меня." } } } },
    [92473] = { d = 31.0, v = "skyborne-female#3773", n = { x = 377 }, c = { x = { { 0.00, "От логова медвер на юго-западе всё больше проблем." }, { 3.74, "Буквально на той неделе следопытам пришлось прикончить молодую медверу, которая подошла слишком близко к деревне и напала на мальчишку, игравшего под старым деревом в центре поселения." }, { 16.09, "Нам повезло, что ему удалось сбежать целым и невредимым. Эти звери от голода и отчаяния становятся слишком опасными." }, { 23.79, "Ступай на юг и убей самых слабых медвер. Принеси мне их когти как доказательство того, что дело сделано." } } }, t = { d = 4.0, g = 1, v = "skyborne-female#3773", n = { x = 32 }, c = { m = { { 0.00, "Молодцом, герой. Следопыты Рощи у тебя в долгу." } }, f = { { 0.00, "Молодцом, героиня. Следопыты Рощи у тебя в долгу." } } } } },
    [92474] = { d = 28.0, v = "skyborne-female#3773", n = { x = 325 }, c = { x = { { 0.00, "Ну привет! Хочешь сыграть в одну игру?" }, { 3.38, "Тебе всего-то надо подойти вон к тому краю... и спрыгнуть. Используй свою способность к левитации и посмотри, как далеко улетишь." }, { 11.99, "Правила выдуманы только что, награды никакой нет, но ты получишь дополнительные очки, если приземлишься прямо перед Рорианом Искателем Утра и напугаешь его!" }, { 22.38, "Ему это, конечно, не понравится, но я посмеюсь от души, если он разорётся! Ха-ха!" } } }, t = { d = 25.1, v = "skyborne-male", n = { x = 304 }, c = { x = { { 0.00, "Да сколько раз мне говорить Мириаал, чтобы не подбивала других применять наши врождённые способности для всякой ерунды?" }, { 8.40, "Впрочем, небольшая тренировка в относительно безопасной деревне может быть... полезной." }, { 14.43, "Но в будущем советую применять способности осмотрительно." }, { 18.37, "Израсходуешь магию, а потом не сможешь воспользоваться ей, когда она будет действительно нужна." } } } } },
    [92479] = { d = 17.4, v = "human-male", n = { x = 205 }, c = { x = { { 0.00, "Меня попросили передать тебе это письмо, как только ты вернёшься из лагеря кобольдов." }, { 5.97, "Похоже, на нём стоит печать Тордрина Кряжеруб, местного наставника охотников." }, { 11.35, "Прочти, прежде чем заниматься какими бы то ни было другими делами здесь в аббатстве." } } } },
    [92481] = { d = 16.0, g = 1, v = "skyborne-male", n = { m = 196, f = 197 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наша наставница магов Дорийя Громкий Шёпот оставила тебе этот кристалл возвращения." }, { 7.65, "На нём записано какое-то послание, так что обязательно взгляни. А потом сможешь найти Дорийю в строении у меня за спиной." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наша наставница магов Дорийя Громкий Шёпот оставила тебе этот кристалл возвращения." }, { 7.67, "На нём записано какое-то послание, так что обязательно взгляни. А потом сможешь найти Дорийю в строении у меня за спиной." } } }, t = { d = 28.2, g = 1, v = "skyborne-female#3773", n = { m = 334, f = 334 }, c = { m = { { 0.00, "Дай-ка взглянуть на тебя. Да, думаю, из тебя получится отличный герой." }, { 4.95, "Сила тайной магии среди нашего народа угасла, но есть те, кто стремится заново открыть многое из утраченного за тысячелетия, что мы провели здесь, среди облаков." }, { 15.49, "Уверена, ты будешь в первых рядах в этом нескончаемом поиске тайных знаний и в конце концов заставишь нас гордиться тобой." }, { 23.88, "Поговори со мной снова, когда захочешь сделать следующий шаг." } }, f = { { 0.00, "Дай-ка взглянуть на тебя. Да, думаю, из тебя получится отличная героиня." }, { 5.10, "Сила тайной магии среди нашего народа угасла, но есть те, кто стремится заново открыть многое из утраченного за тысячелетия, что мы провели здесь, среди облаков." }, { 15.64, "Уверена, ты будешь в первых рядах в этом нескончаемом поиске тайных знаний и в конце концов заставишь нас гордиться тобой." }, { 24.03, "Поговори со мной снова, когда захочешь сделать следующий шаг." } } } } },
    [92482] = { d = 12.1, g = 1, v = "skyborne-male", n = { m = 142, f = 143 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наша наставница охотников Тай'ри Дальний Взор оставила тебе записку. Она сейчас в центре деревни." }, { 8.66, "Прочитай её послание, а затем найди её саму." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наша наставница охотников Тай'ри Дальний Взор оставила тебе записку. Она сейчас в центре деревни." }, { 8.76, "Прочитай её послание, а затем найди её саму." } } }, t = { d = 23.6, g = 1, v = "skyborne-female#3773", n = { x = 277 }, c = { m = { { 0.00, "Твой путь, герой, полон опасностей, и выжить в дикой глуши могут лишь те, у кого самые острые чувства и самая быстрая реакция." }, { 8.33, "Гляжу на тебя и вспоминаю себя, когда много лет назад стояла перед своей наставницей." }, { 13.87, "Думаю, у тебя есть всё, что нужно, но в конечном счёте это зависит лишь от тебя." }, { 19.53, "Поговори со мной снова, когда захочешь сделать следующий шаг." } }, f = { { 0.00, "Твой путь, героиня, полон опасностей, и выжить в дикой глуши могут лишь те, у кого самые острые чувства и самая быстрая реакция." }, { 8.29, "Гляжу на тебя и вспоминаю себя, когда много лет назад стояла перед своей наставницей." }, { 13.83, "Думаю, у тебя есть всё, что нужно, но в конечном счёте это зависит лишь от тебя." }, { 19.49, "Поговори со мной снова, когда захочешь сделать следующий шаг." } } } } },
    [92483] = { d = 20.5, g = 1, v = "skyborne-male", n = { m = 240, f = 241 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, тебя разыскивал наш наставник разбойников Акери Клинок Сумерек." }, { 6.47, "Он оставил эту записку, так что сначала прочитай её, а потом найди его в сторожевой башне – здесь, в деревне." }, { 13.99, "Подозрительный малый, правда, о тебе можно сказать то же самое. Думаю, вы найдёте общий язык." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, тебя разыскивал наш наставник разбойников Акери Клинок Сумерек." }, { 6.35, "Он оставил эту записку, так что сначала прочитай её, а потом найди его в сторожевой башне – здесь, в деревне." }, { 13.87, "Подозрительный малый, правда, о тебе можно сказать то же самое. Думаю, вы найдёте общий язык." } } }, t = { d = 29.4, g = 1, v = "skyborne-male", n = { m = 332, f = 332 }, c = { m = { { 0.00, "Я почти не услышал, как ты подошёл, юный герой. Почти." }, { 4.12, "За пределами Тендалской рощи «почти» тебя не спасёт. Ты должен быть как тонкий клинок – бесшумный и твёрдый." }, { 11.23, "Всегда начеку, всегда помня о том, что вокруг. Может, у тебя хватит сил выжить среди опасностей Зефриса." }, { 18.23, "А может, тебя найдут в канаве с перерезанным горлом. В конечном счёте всё зависит лишь от тебя." }, { 24.82, "Поговори со мной снова, когда захочешь сделать следующий шаг." } }, f = { { 0.00, "Я почти не услышал, как ты подошла, юная героиня. Почти." }, { 4.19, "За пределами Тендалской рощи «почти» тебя не спасёт. Ты должна быть как тонкий клинок – бесшумный и твёрдый." }, { 11.39, "Всегда начеку, всегда помня о том, что вокруг. Может, у тебя хватит сил выжить среди опасностей Зефриса." }, { 18.39, "А может, тебя найдут в канаве с перерезанным горлом. В конечном счёте всё зависит лишь от тебя." }, { 24.97, "Поговори со мной снова, когда захочешь сделать следующий шаг." } } } } },
    [92484] = { d = 12.7, g = 1, v = "skyborne-male", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наш наставник шаманов Ваятель ветра Боро оставил тебе этот кристалл возвращения." }, { 8.30, "Прошу, осмотри его, а затем поговори с Боро в центре деревни." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наш наставник шаманов Ваятель ветра Боро оставил тебе этот кристалл возвращения." }, { 7.58, "Прошу, осмотри его, а затем поговори с Боро в центре деревни." } } }, t = { d = 27.5, v = "skyborne-male", n = { x = 321 }, c = { x = { { 0.00, "Слышишь? Шёпот ветров? Вряд ли – ведь духи перестали говорить с нами, когда покинули нас много лет назад." }, { 7.41, "Те из нас, кто хочет вновь удостоиться беседы с духами четырёх ветров, оттачивают понимание стихий и природы в надежде восстановить так внезапно оборвавшийся диалог." }, { 18.73, "Хочешь пойти этим путём и овладеть стихиями?" }, { 22.15, "Поговори со мной снова, когда захочешь сделать следующий шаг, и я обучу тебя." } } } } },
    [92485] = { d = 17.5, g = 1, v = "skyborne-male", n = { m = 208, f = 209 }, c = { m = { { 0.00, "Пока ты разбирался с лисвенами, наш наставник друидов Зитон Среброветрый оставил тебе записку." }, { 6.28, "Прочитай её поскорее, а затем найди Среброветрого на нижнем ярусе большого дерева у меня за спиной." }, { 13.42, "Прислушайся к его словам – он может многому тебя научить." } }, f = { { 0.00, "Пока ты разбиралась с лисвенами, наш наставник друидов Зитон Среброветрый оставил тебе записку." }, { 6.36, "Прочитай её поскорее, а затем найди Среброветрого на нижнем ярусе большого дерева у меня за спиной." }, { 13.50, "Прислушайся к его словам – он может многому тебя научить." } } }, t = { d = 27.0, g = 1, v = "skyborne-male", n = { m = 320, f = 323 }, c = { m = { { 0.00, "Флора и фауна острова Зефрис – это целая палитра яркой, безудержной жизни." }, { 4.92, "Чтобы в природе была гармония, требуется постоянно поддерживать всё в равновесии, и храним это равновесие мы, друиды." }, { 12.66, "Я вижу в тебе отличные задатки, но этот путь труден, и тебе понадобится наставник, чтобы ты смог познать тайны клыка, когтя, пера и ветви." }, { 22.28, "Поговори со мной вновь, когда будешь готов сделать следующий шаг." } }, f = { { 0.00, "Флора и фауна острова Зефрис – это целая палитра яркой, безудержной жизни." }, { 4.94, "Чтобы в природе была гармония, требуется постоянно поддерживать всё в равновесии, и храним это равновесие мы, друиды." }, { 12.67, "Я вижу в тебе отличные задатки, но этот путь труден, и тебе понадобится наставник, чтобы ты смогла познать тайны клыка, когтя, пера и ветви." }, { 22.34, "Поговори со мной вновь, когда будешь готова сделать следующий шаг." } } } } },
    [92514] = { d = 31.2, v = "skyborne-female", n = { x = 353 }, c = { x = { { 0.00, "На вид ты будто бы из числа Ваятелей ветра." }, { 3.00, "Рядом с ними я всегда чувствую, как по коже пробегает статический разряд, – это и выдаёт благословлённых духами." }, { 10.29, "Прежде чем я загружу тебя работой, тебе стоит поговорить со старейшиной Ваятелей ветра, живущей здесь, – Иллайей Янтарный Ветер." }, { 18.69, "Ты найдёшь её на улице, недалеко от центра." }, { 22.09, "Ах да, к Кориэлле Спокойный Бриз тоже загляни – это хозяйка местной таверны, где можно получить кров и припасы." } } }, t = { d = 25.2, g = 1, v = "skyborne-female", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Значит, с Иллайей ты уже поговорил? Отлично." }, { 3.78, "Между Высшим орденом и Ваятелями ветра сейчас большое напряжение, но здесь, в Шен'даре, они ведут себя прилично." }, { 11.35, "Все понимают, что у нас есть заботы посерьёзнее их склок." }, { 15.67, "Ну а теперь... Ты, похоже, из тех, кому не терпится найти работу для рук, а у меня как раз беда с бандитами. Надеюсь, ты поможешь." } }, f = { { 0.00, "Значит, с Иллайей ты уже поговорила? Отлично." }, { 3.04, "Между Высшим орденом и Ваятелями ветра сейчас большое напряжение, но здесь, в Шен'даре, они ведут себя прилично." }, { 10.60, "Все понимают, что у нас есть заботы посерьёзнее их склок." }, { 14.93, "Ну а теперь... Ты, похоже, из тех, кому не терпится найти работу для рук, а у меня как раз беда с бандитами. Надеюсь, ты поможешь." } } } } },
    [92515] = { d = 25.1, v = "skyborne-male", n = { x = 298 }, c = { x = { { 0.00, "Мало нам было бандитов и безумных сектантов, так теперь холмы ещё и кишат когтями прайда." }, { 6.04, "Они уже начали подбираться к границам деревни и становятся всё смелее. Ещё немного, и у жителей начнут пропадать дети и питомцы." }, { 14.53, "Нам лучше проредить ряды этих хищников сейчас, не дожидаясь трагедии." }, { 19.60, "Принеси мне с десяток их шкур. Сделаю из них что-нибудь полезное для деревни." } } }, t = { d = 4.1, v = "skyborne-male", n = { x = 45 }, c = { x = { { 0.00, "Никто ведь не обещал, что работа не будет грязной, верно?" } } } } },
    [92516] = { d = 12.5, v = "skyborne-female", n = { x = 154 }, c = { x = { { 0.00, "К юго-востоку от деревни Шен'дар устроила гнездовье стая гиппогрифов, и теперь они нападают на путешественников на дороге." }, { 8.03, "Мне нужно, чтобы кто-нибудь сократил численность этих существ." } } }, t = { d = 3.7, v = "skyborne-female", n = { x = 36 }, c = { x = { { 0.00, "Отличная работа – и быстрая. Неплохо, неплохо." } } } } },
    [92517] = { d = 32.3, g = 1, v = "skyborne-female", n = { m = 367, f = 367 }, c = { m = { { 0.00, "Недалеко отсюда, к северу, есть пещера, скрытая водопадом. Мне известно, что там устроила себе логово группа бандитов." }, { 7.94, "Они доставляли нам неприятности ещё до появления здесь культа, но теперь это настоящая беда." }, { 14.24, "Боюсь, у нас не хватает рук, и мы не можем пойти и истребить их сами." }, { 20.49, "Отправляйся туда и займись этим. Убей как можно больше бандитов и, если получится, их предводителя, которого называют Бенник-Баламут." }, { 29.33, "В пещере опасно, так что будь осторожен." } }, f = { { 0.00, "Недалеко отсюда, к северу, есть пещера, скрытая водопадом. Мне известно, что там устроила себе логово группа бандитов." }, { 7.94, "Они доставляли нам неприятности ещё до появления здесь культа, но теперь это настоящая беда." }, { 14.24, "Боюсь, у нас не хватает рук, и мы не можем пойти и истребить их сами." }, { 20.49, "Отправляйся туда и займись этим. Убей как можно больше бандитов и, если получится, их предводителя, которого называют Бенник-Баламут." }, { 29.33, "В пещере опасно, так что будь осторожна." } } }, t = { d = 15.8, v = "skyborne-female", n = { x = 189 }, c = { x = { { 0.00, "С бандитами покончено, и у нас стало одной проблемой меньше." }, { 4.17, "Но, признаться, теперь меня беспокоит, что выжившие бандиты присоединятся к культу, который и без того разрастается тревожными темпами. Впрочем, нам важна каждая победа." } } } } },
    [92528] = { d = 28.8, v = "skyborne-male", n = { x = 343 }, c = { x = { { 0.00, "Паства Ал'акира крепнет с каждым новым воодушевлённым последователем вроде тебя. Как видишь, наша сила способна вызвать бурю!" }, { 8.75, "Я бы отправил тебя прямиком к небесному жрецу Аандерсу, чтобы он тебя оценил, но он сейчас занят – принимает гостя в таверне на северной стороне города." }, { 18.88, "Прошу тебя пока не ходить туда. Новичку не подобает показываться на глаза столь важному гостю." }, { 25.64, "Пока что просто постарайся никому не мешать." } } }, t = { d = 28.8, v = "skyborne-female", n = { x = 331 }, c = { x = { { 0.00, "Сама Лортуна была там? Она же лидер этой проклятой секты!" }, { 4.22, "Если они собираются наступать на деревню Шен'дар и западную сторожевую башню, мы должны подготовиться. Но вот что странно... Зачем им сторожевая башня?" }, { 14.71, "С деревней-то всё ясно, но башня... Да, это пост наблюдения, но не самый стратегически важный." }, { 21.04, "В любом случае мы будем готовы. Пусть узнают, что жителей нагорья не так легко застать врасплох, как они думают." } } } } },
    [92529] = { d = 33.5, v = "skyborne-female", n = { x = 402 }, c = { x = { { 0.00, "Твоё желание служить Ал'акиру греет мне душу. Наш народ переживает тяжёлые времена – и всё из-за нашего самодовольства." }, { 7.75, "Мы возгордились и начали принимать милость ветров как должное. Это привело к застою, и духи ветра покинули нас." }, { 15.64, "Лишь покаявшись, мы сможем вновь ощутить ласковое прикосновение ветра." }, { 20.36, "Если хочешь быть в кругу единомышленников, отправляйся в деревню Фалаат и найди там миссионера Джасаана." }, { 27.98, "Я поставлю на тебя метку, чтобы верующие приняли тебя как нового последователя." } } }, t = { d = 14.3, v = "skyborne-male", n = { x = 151 }, c = { x = { { 0.00, "Кто тут у нас? Новый последователь, желающий служить Владыке Ветра? Значит, тебя прислала Сания?" }, { 7.03, "Воистину четыре ветра ныне благоволят нам!" }, { 10.34, "Мы рады всем, кто ищет благословения Ал'акира." } } } } },
    [92532] = { d = 17.3, v = "skyborne-male", n = { x = 183 }, c = { x = { { 0.00, "Пока тебя не было, наша наставница воинов мастер клинка Рен попросила, чтобы тебя отправили к ней, когда вернёшься." }, { 8.36, "А ещё она оставила тебе эту записку." }, { 11.17, "Прочитай её, а затем отыщи мастера клинка Рен в местной сторожевой башне." } } } },
    [92544] = { d = 32.4, v = "bloodelf-female", n = { x = 374 }, c = { x = { { 0.00, "Шайка ал'акетских негодяев расположилась у развалин храма к юго-западу отсюда." }, { 5.48, "Ими верховодит настоящее чудовище по имени Малдуко Упавшее Облако." }, { 10.59, "Нет сомнений, что этот сброд явился сюда из святилища Акира по приказу верховной жрицы Лортуны, чтобы нападать на путников и заманивать в секту всех, кого можно." }, { 22.15, "Мне нужно оставаться здесь, чтобы предупреждать путников об опасности, но я скажу спасибо, если ты что-нибудь сделаешь с сектантами и их лидером." } } }, t = { d = 14.4, g = 1, v = "bloodelf-female", n = { x = 144 }, c = { m = { { 0.00, "Как же мне хотелось бросить дежурство и присоединиться к тебе. Надеюсь, эти негодяи всё поняли и скоро уберутся восвояси." }, { 9.54, "Спасибо, герой. Следопыты Тендалской рощи благодарны тебе." } }, f = { { 0.00, "Как же мне хотелось бросить дежурство и присоединиться к тебе. Надеюсь, эти негодяи всё поняли и скоро уберутся восвояси." }, { 9.54, "Спасибо, героиня. Следопыты Тендалской рощи благодарны тебе." } } } } },
    [92550] = { d = 35.2, g = 1, v = "skyborne-female", n = { m = 397, f = 398 }, c = { m = { { 0.00, "Пожалуй, лучшей защитой для нас будет уверенное нападение. У нас есть преимущество, так как мы знаем о планах врага." }, { 7.74, "Он точно не ждёт, что мы нападём первыми." }, { 11.15, "Ты уже много сделал для меня, но, прошу, отправляйся в деревню Фалаат." }, { 15.87, "Убей как можно больше сектантов, а если сможешь подобраться достаточно близко, то и их командира. Его голову принеси мне." }, { 25.39, "Я останусь здесь и прослежу, чтобы мирные жители и наши немногочисленные миротворцы подготовились к обороне... на случай, если ты не вернёшься." } }, f = { { 0.00, "Пожалуй, лучшей защитой для нас будет уверенное нападение. У нас есть преимущество, так как мы знаем о планах врага." }, { 7.74, "Он точно не ждёт, что мы нападём первыми." }, { 11.15, "Ты уже много сделала для меня, но, прошу, отправляйся в деревню Фалаат." }, { 15.78, "Убей как можно больше сектантов, а если сможешь подобраться достаточно близко, то и их командира. Его голову принеси мне." }, { 25.30, "Я останусь здесь и прослежу, чтобы мирные жители и наши немногочисленные миротворцы подготовились к обороне... на случай, если ты не вернёшься." } } }, t = { d = 23.7, g = 1, v = "skyborne-female", n = { m = 266, f = 268 }, c = { m = { { 0.00, "Слава ветрам, ты вернулся!" }, { 2.52, "Сания Серебряный Поток буквально только что ускользнула из деревни – наверняка испугалась того, что жители готовят оружие." }, { 11.01, "Ты оказал неоценимую помощь деревне Шен'дар. Мы все перед тобой в долгу." }, { 16.24, "Если сектанты вернутся на нагорье, они поймут, что мы не такая уж и лёгкая мишень. Да направят тебя ветра." } }, f = { { 0.00, "Слава ветрам, ты вернулась!" }, { 2.65, "Сания Серебряный Поток буквально только что ускользнула из деревни – наверняка испугалась того, что жители готовят оружие." }, { 11.15, "Ты оказала неоценимую помощь деревне Шен'дар. Мы все перед тобой в долгу." }, { 15.97, "Если сектанты вернутся на нагорье, они поймут, что мы не такая уж и лёгкая мишень. Да направят тебя ветра." } } } } },
    [92551] = { d = 28.3, v = "skyborne-male", n = { x = 323 }, c = { x = { { 0.00, "Я слышал, ты собираешься в деревню Фалаат. Когда будешь там, поищи наши украденные припасы." }, { 6.46, "Ал'акетские сектанты уже не первый месяц нападают на наши караваны, везущие еду и ветрокамни в низины и из них." }, { 14.74, "А вину всегда сваливают на бандитов. Но мы-то знаем, что всё украденное в итоге оказывается в одном и том же месте." }, { 22.35, "Если в Фалаате ещё что-нибудь осталось, ты здорово поможешь, если принесёшь это нам." } } }, t = { d = 10.4, v = "skyborne-male", n = { x = 127 }, c = { x = { { 0.00, "Замечательно! Без регулярных поставок припасов нам приходилось несладко." }, { 5.02, "Мы с констеблем позаботимся о том, чтобы это досталось наиболее нуждающимся." } } } } },
    [92553] = { d = 22.2, g = 1, v = "skyborne-male", n = { m = 258, f = 259 }, c = { m = { { 0.00, "Хочешь немного поработать? Такой сильный помощник мне не помешает." }, { 4.51, "Забот у нас сейчас столько, что ни у кого нет времени на охоту и сбор растений." }, { 9.81, "Мне нужен кто-то, кто добудет свежие яйца и мясо долгоногов, чтобы накормить деревню." }, { 15.83, "Если поможешь, буду рад научить тебя готовить одно из моих фирменных блюд. Что скажешь?" } }, f = { { 0.00, "Хочешь немного поработать? Такая сильная помощница мне не помешает." }, { 4.66, "Забот у нас сейчас столько, что ни у кого нет времени на охоту и сбор растений." }, { 9.96, "Мне нужен кто-то, кто добудет свежие яйца и мясо долгоногов, чтобы накормить деревню." }, { 15.98, "Если поможешь, буду рад научить тебя готовить одно из моих фирменных блюд. Что скажешь?" } } }, t = { d = 15.9, v = "skyborne-male", n = { x = 179 }, c = { x = { { 0.00, "Эти яйца непросто раздобыть, но, о ветер, какие же они вкусные, если пожарить их в сале медверы!" }, { 6.87, "Если у тебя есть время и ты любишь готовить, могу дать тебе несколько советов." }, { 12.20, "Я готов начать обучение хоть сейчас – только скажи." } } } } },
    [92579] = { d = 36.4, v = "skyborne-female", n = { x = 386 }, c = { x = { { 0.00, "Пока похоже, что столп и деревня в безопасности, и я хочу попросить тебя доставить этот доклад Валеннии Штормовой Кулак в Валанаар, на юго-восточный край острова." }, { 13.59, "Валенния – лидер миротворцев на острове, и она должна узнать, что здесь произошло." }, { 19.43, "Культ быстро разрастается, и миротворцы до сих пор избегали открытого столкновения, но дальше так продолжаться не может. Валанаар должен быть готов к бою." }, { 31.08, "Как бы то ни было, спасибо тебе. В Шен'даре ты всегда найдёшь верных друзей." } } }, t = { d = 33.2, v = "skyborne-female", n = { x = 357 }, c = { x = { { 0.00, "Читая письмо, Валенния мрачнеет." }, { 2.76, "Аонда доверила тебе доставку послания и хорошо о тебе отзывается в нём. Я тоже постараюсь тебе доверять." }, { 9.83, "Прежде чем продолжить разговор, мне нужно посоветоваться с теми немногими миротворцами, что ещё остались со мной, и разработать план на случай нападения культа. Отдохни пока в Валанааре." }, { 23.45, "Если будешь искать себе занятие, многим горожанам, скорее всего, не помешает помощь такого молодого и сильного искателя приключений, как ты." } } } } },
    [92595] = { d = 25.0, g = 1, v = "skyborne-female", n = { m = 259, f = 259 }, c = { m = { { 0.00, "Иллайя тепло улыбается вам." }, { 2.18, "Я рада, что ты пришёл поговорить со мной, дитя ветров. Едва увидев тебя, я поняла, что ты владеешь небесным взором." }, { 9.84, "Тебя это удивляет? Даже те, кто не учился ремеслу шамана, могут обладать этим даром." }, { 16.39, "Идём. Нам нужно поговорить о предназначении Ваятелей ветра, сути выпавших нам на Зефрисе испытаний и судьбе нашего народа." } }, f = { { 0.00, "Иллайя тепло улыбается вам." }, { 2.18, "Я рада, что ты пришла поговорить со мной, дитя ветров. Едва увидев тебя, я поняла, что ты владеешь небесным взором." }, { 9.95, "Тебя это удивляет? Даже те, кто не учился ремеслу шамана, могут обладать этим даром." }, { 16.50, "Идём. Нам нужно поговорить о предназначении Ваятелей ветра, сути выпавших нам на Зефрисе испытаний и судьбе нашего народа." } } }, t = { d = 26.0, v = "skyborne-female", n = { x = 303 }, c = { x = { { 0.00, "Думаю, теперь ты понимаешь, как важна миссия Ваятелей ветра." }, { 4.12, "Каждый, кто владеет небесным взором, бесценен, если мы надеемся вновь наладить диалог с духами ветров." }, { 11.17, "Внутренние угрозы вроде Ал'акета, шаткое положение нашего дома здесь, в Небесной выси..." }, { 16.92, "Наш долг как Ваятелей ветра – использовать свой дар, чтобы спасти родину и помочь шен'дорай пережить эти тяжёлые времена." } } } } },
    [92596] = { d = 23.1, g = 1, v = "skyborne-male", n = { m = 275, f = 276 }, c = { m = { { 0.00, "Тебя окружает мощная аура чародейской энергии, хотя ты не проходил посвящение в маги." }, { 5.74, "Не сомневаюсь, тебя ждёт успех в странствиях, а связь с нашей древней магией станет для тебя великим даром, даже если за всю жизнь ты не произнесёшь ни единого слова силы." }, { 17.42, "Давай побеседуем о моём ордене, природе магии на Зефрисе и судьбе нашего народа." } }, f = { { 0.00, "Тебя окружает мощная аура чародейской энергии, хотя ты не проходила посвящение в маги." }, { 5.76, "Не сомневаюсь, тебя ждёт успех в странствиях, а связь с нашей древней магией станет для тебя великим даром, даже если за всю жизнь ты не произнесёшь ни единого слова силы." }, { 17.43, "Давай побеседуем о моём ордене, природе магии на Зефрисе и судьбе нашего народа." } } }, t = { d = 29.2, v = "skyborne-male", n = { x = 351 }, c = { x = { { 0.00, "Высший орден заботится о выживании нашего народа." }, { 3.40, "Мы чтим своих стихийных покровителей, но должны принимать реальность такой, какая она есть." }, { 9.47, "Их больше нет с нами – мы предоставлены сами себе." }, { 13.12, "Ал'акет угрожает нам изнутри, а на уязвимое состояние нашего дома нельзя закрывать глаза, но мы потомки высокорождённых Эльдре'Таласа: мы должны позаботиться о том, чтобы шен'дорай вновь твёрдо стояли на ногах. В этом нам поможет наш дар." } } } } },
    [92597] = { d = 23.5, v = "skyborne-male", n = { x = 281 }, c = { x = { { 0.00, "Здесь, в обители стихий, значительная часть нашей магической силы исходит от силовых линий, пролегающих под землёй." }, { 7.82, "В последнее время они начали выступать на поверхность, и у нас появился прямой доступ к их дремлющей магической энергии." }, { 16.12, "Ступай к валунам на северо-востоке. Там есть силовая линия. Вспомни своё наследие и напитайся энергией." } } }, t = { d = 27.3, g = 1, v = "skyborne-male", n = { m = 311, f = 312 }, c = { m = { { 0.00, "Чувствуешь? Да? Прекрасно! Ты сделал первые шаги. С твоими способностями ты сможешь использовать магическую энергию многих мест." }, { 8.63, "Так можно получить разные преимущества – иногда явные, иногда незаметные. Точно не узнаешь, пока не попробуешь." }, { 16.05, "Но это лучшая часть твоего дара... узнавать непознанное." }, { 20.09, "Чтобы выжить в эти тяжёлые времена, нам надо неустанно стремиться к знаниям... и силе." } }, f = { { 0.00, "Чувствуешь? Да? Прекрасно! Ты сделала первые шаги. С твоими способностями ты сможешь использовать магическую энергию многих мест." }, { 9.47, "Так можно получить разные преимущества – иногда явные, иногда незаметные. Точно не узнаешь, пока не попробуешь." }, { 16.89, "Но это лучшая часть твоего дара... узнавать непознанное." }, { 20.93, "Чтобы выжить в эти тяжёлые времена, нам надо неустанно стремиться к знаниям... и силе." } } } } },
    [92598] = { d = 25.7, v = "skyborne-female#3773", n = { x = 313 }, c = { x = { { 0.00, "Как и все Ваятели ветра, ты обладаешь даром небесного взора, которым нас наделили духи стихий." }, { 6.11, "Ступай к стоячим камням к северо-востоку от деревни. Найди там слияние стихий и примени свой дар." }, { 12.98, "Использовать небесный взор можно где угодно, но он наиболее силён в присутствии слияния стихий." }, { 19.35, "Также у духов, которых привлекают такие места, подчас можно получить новые крупицы мудрости." } } }, t = { d = 21.4, g = 1, v = "skyborne-female#3773", n = { m = 263, f = 264 }, c = { m = { { 0.00, "Небесный взор – как ещё одна мышца, которую нужно развивать, если хочешь усилить свой дар." }, { 5.85, "В твоих приключениях наверняка пригодится способность стирать грань между мирами смертных и духов." }, { 12.64, "Советую запомнить то, чему ты научился сегодня. Способность слышать то, о чём говорят духи, может стать ключом к нашему выживанию" } }, f = { { 0.00, "Небесный взор – как ещё одна мышца, которую нужно развивать, если хочешь усилить свой дар." }, { 5.85, "В твоих приключениях наверняка пригодится способность стирать грань между мирами смертных и духов." }, { 12.64, "Советую запомнить то, чему ты научилась сегодня. Способность слышать то, о чём говорят духи, может стать ключом к нашему выживанию" } } } } },
    [92640] = { d = 30.2, v = "skyborne-male", n = { x = 340 }, c = { x = { { 0.00, "Раз мы не можем открыто напасть на культ, остаётся воспользоваться шансом и атаковать само святилище." }, { 6.86, "Выведем Лортуну из игры, пока она не завершила свою часть плана." }, { 11.55, "Момент как нельзя более благоприятный: Валенния уже некоторое время готовит стратегию нападения на святилище." }, { 20.96, "Единственная загвоздка в том, что её не выполнить без дополнительной помощи." }, { 26.46, "Поговори с Валеннией, она расскажет тебе подробности." } } }, t = { d = 8.1, v = "skyborne-female", n = { x = 98 }, c = { x = { { 0.00, "Отношения между Ваятелями ветра и Высшим орденом сейчас напряжённые, но план не удастся без содействия обеих сторон." } } } } },
    [92642] = { d = 37.2, v = "skyborne-female", n = { x = 434 }, c = { x = { { 0.00, "Валенния прислала одного бойца, когда у нас тут полномасштабное нападение... Ветра милостивые..." }, { 7.76, "Ты выглядишь не очень многообещающе, но я не стану отказываться от помощи." }, { 12.83, "Надо причинить врагу как можно больше урона, чтобы быстро его остановить. Мои бойцы долго не продержатся." }, { 20.18, "Спустись с холма и нарушь их организацию." }, { 22.93, "Вражеские целители постоянно поддерживают наступление – если мы их уничтожим, то сможем собрать силы для ответного удара и отбросить противника." }, { 32.54, "А если убьёшь пару сектантов по пути, то тоже очень нам поможешь." } } }, t = { d = 5.2, g = 1, v = "skyborne-female", n = { m = 43, f = 44 }, c = { m = { { 0.00, "Ты ещё жив? Что ж... Спасибо ветрам за это маленькое чудо." } }, f = { { 0.00, "Ты ещё жива? Что ж... Спасибо ветрам за это маленькое чудо." } } } } },
    [92643] = { d = 30.7, v = "skyborne-male", n = { x = 366 }, c = { x = { { 0.00, "Мы вышли на связь с отступником из Ал'акета." }, { 2.96, "Он утверждает, что знает истинные планы культа в отношении острова, и хочет встретиться с нами, но только если мы предоставим ему защиту." }, { 12.55, "Этот перебежчик скрывается в уединённом жилище к северо-западу от Валанаара, на нагорье." }, { 18.39, "Нужно, чтобы кто-то незаметно добрался туда, отыскал предателя и привёл его к нам." }, { 23.80, "Это может быть ловушка, но если у отступника и правда есть важная информация, нам стоит рискнуть." } } }, t = { d = 11.1, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "Сектант явно мёртв – его убили ассасины, с которыми вы сразились у входа в дом." }, { 5.20, "Вы наклоняетесь, чтобы осмотреть тело, и замечаете, как что-то поблёскивает на свету..." } } } } },
    [92644] = { d = 15.2, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "Вы запускаете руку под ещё тёплое тело сектанта-перебежчика и достаёте небольшой светящийся синий кристалл." }, { 7.21, "Похоже, он повреждён, но всё ещё может быть полезен. Верховный старейшина Песня Теней наверняка им заинтересуется." } } }, t = { d = 9.1, v = "skyborne-male", n = { x = 51 }, c = { x = { { 0.00, "Значит, перебежчик был уже мёртв? Печально..." }, { 3.18, "Вы отдаёте кристалл, который нашли на теле мёртвого сектанта. А это уже интересно..." } } } } },
    [92645] = { d = 30.7, g = 1, v = "skyborne-female", n = { x = 350 }, c = { m = { { 0.00, "Отразить это нападение будет непросто, если мы не устраним командира. Её зовут Бельгилос Сокрушительница, и это настоящая гроза." }, { 8.54, "Она была миротворицей, пока культ не разбушевался, как сейчас, но даже тогда в ней было что-то... жуткое." }, { 15.96, "Могу только представить, насколько страшнее она сейчас." }, { 19.91, "Быть может, я отправляю тебя на верную смерть, но если кто-то не устранит Бельгилос, погибнем мы все." }, { 26.52, "Найдёшь её на вилле у подножия холма. Удачи, герой." } }, f = { { 0.00, "Отразить это нападение будет непросто, если мы не устраним командира. Её зовут Бельгилос Сокрушительница, и это настоящая гроза." }, { 8.54, "Она была миротворицей, пока культ не разбушевался, как сейчас, но даже тогда в ней было что-то... жуткое." }, { 15.96, "Могу только представить, насколько страшнее она сейчас." }, { 19.91, "Быть может, я отправляю тебя на верную смерть, но если кто-то не устранит Бельгилос, погибнем мы все." }, { 26.52, "Найдёшь её на вилле у подножия холма. Удачи, героиня." } } }, t = { d = 7.3, g = 1, v = "skyborne-female", n = { x = 65 }, c = { m = { { 0.00, "Бельгилос мертва? Да хранят тебя четыре ветра, герой." }, { 4.27, "Похоже, мы ещё переживём этот бой." } }, f = { { 0.00, "Бельгилос мертва? Да хранят тебя четыре ветра, героиня." }, { 4.56, "Похоже, мы ещё переживём этот бой." } } } } },
    [92646] = { d = 23.3, g = 1, v = "skyborne-female", n = { x = 263 }, c = { m = { { 0.00, "Лортуна бежала на вершины через какой-то портал. Айесса и Элаадрин последовали за ней. Это было буквально пару мгновений назад." }, { 8.96, "Боюсь, мне слишком досталось, чтобы продолжать. Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 16.74, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть. Удачи, герой." } }, f = { { 0.00, "Лортуна бежала на вершины через какой-то портал. Айесса и Элаадрин последовали за ней. Это было буквально пару мгновений назад." }, { 8.96, "Боюсь, мне слишком досталось, чтобы продолжать. Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 16.74, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть. Удачи, героиня." } } }, t = { d = 23.9, v = "skyborne-female", n = { x = 279 }, c = { x = { { 0.00, "Я отправила нескольких целителей, чтобы помочь Валеннии и её оставшимся бойцам. Сейчас она отдыхает в доме верховного старейшины." }, { 9.04, "Мулн уже отбыл обратно, но мы успели обсудить будущее Ваятелей ветра и наши дальнейшие действия на Азероте." }, { 16.72, "Боюсь, остров уязвим как никогда, и нам надо решить, как мы будем защищать Зефрис от того, что нас ждёт." } } } } },
    [92679] = { d = 25.2, g = 1, v = "skyborne-male", n = { m = 231, f = 235 }, c = { m = { { 0.00, "З... здравствуй. Кажется, ты опытный искатель приключений. Я..." }, { 4.75, "Небеснорождённый морщится – он явно испытывает сильную боль." }, { 9.11, "Я хотел спросить, не ищешь ли ты какую-нибудь работу... Хочу нанять в Валанааре бойцов, чтобы спасти мою ферму." }, { 16.41, "Если такая задача по тебе, отыщи мою жену, Аамелию Поле Ветров, в нашем саду. Он находится в низине, на западе от Валанаара." } }, f = { { 0.00, "З... здравствуй. Кажется, ты опытная искательница приключений. Я..." }, { 4.96, "Небеснорождённый морщится – он явно испытывает сильную боль." }, { 9.32, "Я хотел спросить, не ищешь ли ты какую-нибудь работу... Хочу нанять в Валанааре бойцов, чтобы спасти мою ферму." }, { 16.62, "Если такая задача по тебе, отыщи мою жену, Аамелию Поле Ветров, в нашем саду. Он находится в низине, на западе от Валанаара." } } }, t = { d = 23.0, g = 1, v = "skyborne-female", n = { m = 199, f = 199 }, c = { m = { { 0.00, "Вы рассказываете Аамелии, что случилось с Альварионом." }, { 3.99, "Что ж, зато теперь я знаю, что он в Валанааре и в безопасности." }, { 9.58, "Послушай, незнакомец... Мне очень жаль, но мой дуралей зря послал тебя сюда – только погибнешь напрасно." }, { 16.94, "Если в тебе есть хоть капля благоразумия, уходи подобру-поздорову. Это не твоя битва." } }, f = { { 0.00, "Вы рассказываете Аамелии, что случилось с Альварионом." }, { 3.99, "Что ж, зато теперь я знаю, что он в Валанааре и в безопасности." }, { 9.58, "Послушай, незнакомка... Мне очень жаль, но мой дуралей зря послал тебя сюда – только погибнешь напрасно." }, { 16.23, "Если в тебе есть хоть капля благоразумия, уходи подобру-поздорову. Это не твоя битва." } } } } },
    [92682] = { d = 27.9, v = "skyborne-female", n = { x = 312 }, c = { x = { { 0.00, "Значит, ты скорее из отважных, чем из разумных? Ладно, не буду тебя отговаривать." }, { 5.62, "Ферау и его бандиты ещё не скоро придут за своей долей урожая, так что пока выполни пару поручений и отработай свой хлеб." }, { 14.11, "Сначала сходи собери сегодняшнюю партию буреяблок. А, и имей в виду: среди буреяблонь прячутся разбойники..." }, { 21.30, "Думают, я их не вижу – как бы не так. Убей их." }, { 24.74, "Как раз и посмотрим, что ты умеешь в бою." } } }, t = { d = 4.5, g = 1, v = "skyborne-female", n = { m = 49, f = 50 }, c = { m = { { 0.00, "Я всё видела в окно: а ты неплохо справился с этими бандитами." } }, f = { { 0.00, "Я всё видела в окно: а ты неплохо справилась с этими бандитами." } } } } },
    [92683] = { d = 30.9, g = 1, v = "skyborne-female", n = { m = 359, f = 360 }, c = { m = { { 0.00, "Уверена, ты уже заметил огромных порхательниц на полях за садом? Они не только радуют глаз – их пыльца бывает весьма полезна." }, { 8.37, "С ней много хлопот, но если собрать её побольше, эта пыльца очень помогает в быту." }, { 14.70, "Возьми эту хлопушку от бабочек-порхательниц и хорошенько похлопай этих букашек." }, { 20.59, "Чаще всего они просто пугаются и улетают, но иной раз могут рассвирепеть." }, { 25.58, "При любом раскладе они встряхнутся достаточно, чтобы просыпать кучку пыльцы." } }, f = { { 0.00, "Уверена, ты уже заметила огромных порхательниц на полях за садом? Они не только радуют глаз – их пыльца бывает весьма полезна." }, { 8.33, "С ней много хлопот, но если собрать её побольше, эта пыльца очень помогает в быту." }, { 14.66, "Возьми эту хлопушку от бабочек-порхательниц и хорошенько похлопай этих букашек." }, { 20.56, "Чаще всего они просто пугаются и улетают, но иной раз могут рассвирепеть." }, { 25.55, "При любом раскладе они встряхнутся достаточно, чтобы просыпать кучку пыльцы." } } }, t = { d = 26.1, g = 1, v = "skyborne-female", n = { m = 286, f = 288 }, c = { m = { { 0.00, "Обращаться с этой пыльцой не очень приятно: она везде забивается. Боюсь, ты ещё долго будешь вытряхивать её из штанов." }, { 7.84, "Зато ты очень мне помог. Я уже несколько недель собиралась этим заняться, но боялась отойти от дома, пока я тут совсем одна, а вокруг поджидают бандиты." }, { 19.45, "Только не спрашивай, для чего я использую пыльцу. Нужно для всякого... Не бери в голову." } }, f = { { 0.00, "Обращаться с этой пыльцой не очень приятно: она везде забивается. Боюсь, ты ещё долго будешь вытряхивать её из штанов." }, { 7.84, "Зато ты очень мне помогла. Я уже несколько недель собиралась этим заняться, но боялась отойти от дома, пока я тут совсем одна, а вокруг поджидают бандиты." }, { 18.42, "Только не спрашивай, для чего я использую пыльцу. Нужно для всякого... Не бери в голову." } } } } },
    [92684] = { d = 25.8, g = 1, v = "skyborne-female", n = { m = 295, f = 295 }, c = { m = { { 0.00, "Мало нам было бедного урожая, так ещё местные буреноги повадились забредать в сад и воровать буреяблоки." }, { 6.93, "Можешь сходить в поля и сократить их число?" }, { 10.18, "Но будь осторожен: буреноги из низин крупнее и злее, чем те, что пасутся на нагорье." }, { 16.27, "Если зазеваешься, они отправят тебя на тот свет одним ударом ногой." }, { 21.18, "Принеси немного их мяса, и я заодно приготовлю нам горячий обед." } }, f = { { 0.00, "Мало нам было бедного урожая, так ещё местные буреноги повадились забредать в сад и воровать буреяблоки." }, { 6.93, "Можешь сходить в поля и сократить их число?" }, { 10.18, "Но будь осторожна: буреноги из низин крупнее и злее, чем те, что пасутся на нагорье." }, { 15.78, "Если зазеваешься, они отправят тебя на тот свет одним ударом ногой." }, { 20.69, "Принеси немного их мяса, и я заодно приготовлю нам горячий обед." } } }, t = { d = 4.4, g = 1, v = "skyborne-female", n = { m = 47, f = 48 }, c = { m = { { 0.00, "Вот это крупные вырезки! Каких же монстров ты там завалил?" } }, f = { { 0.00, "Вот это крупные вырезки! Каких же монстров ты там завалила?" } } } } },
    [92685] = { d = 21.5, v = "skyborne-female", n = { x = 250 }, c = { x = { { 0.00, "У бандитов тут повсюду лагеря, но один небольшой находится совсем близко: на холмах к северу отсюда." }, { 6.70, "Поднимись туда и задай им жару. Если застанем бандитов врасплох и перебьём их до того, как они доберутся сюда, то достаточно сравняем шансы." }, { 16.46, "Принеси мне их маски. Чем больше они пропитаются кровью, тем лучше." } } }, t = { d = 26.2, g = 1, v = "skyborne-female", n = { m = 299, f = 301 }, c = { m = { { 0.00, "А ты меня послушал: маски и правда пропитаны кровью. И славно. Так я точно знаю, что мерзавцам было больно." }, { 7.57, "А если серьёзно, огромное спасибо за всё, что ты сделал. Я неделями бесцельно скиталась по ферме, будто ожидая приговора." }, { 15.65, "Теперь ко мне возвращается надежда." }, { 18.42, "Ферау и его негодяи вот-вот будут здесь. Нужно только их встретить. Что скажешь? Останешься со мной до конца?" } }, f = { { 0.00, "А ты меня послушала: маски и правда пропитаны кровью. И славно. Так я точно знаю, что мерзавцам было больно." }, { 7.70, "А если серьёзно, огромное спасибо за всё, что ты сделала. Я неделями бесцельно скиталась по ферме, будто ожидая приговора." }, { 15.73, "Теперь ко мне возвращается надежда." }, { 18.50, "Ферау и его негодяи вот-вот будут здесь. Нужно только их встретить. Что скажешь? Останешься со мной до конца?" } } } } },
    [92693] = { d = 27.4, g = 1, v = "skyborne-female", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Благодаря тебе у нас появился шанс. Даже если мы погибнем, то сделаем это, зная, что сражались до последнего." }, { 7.77, "А для тебя, незнакомец, это последняя возможность отступить: если предпочтёшь вернуться в Валанаар и сберечь свою жизнь, я не осужу." }, { 16.89, "Но если ты так любишь выручать пропащих и отчаявшихся, скажи, когда будешь готов." }, { 22.14, "Мы выйдем навстречу врагу с высоко поднятой головой – и будь что будет." } }, f = { { 0.00, "Благодаря тебе у нас появился шанс. Даже если мы погибнем, то сделаем это, зная, что сражались до последнего." }, { 7.77, "А для тебя, незнакомка, это последняя возможность отступить: если предпочтёшь вернуться в Валанаар и сберечь свою жизнь, я не осужу." }, { 16.92, "Но если ты так любишь выручать пропащих и отчаявшихся, скажи, когда будешь готова." }, { 22.34, "Мы выйдем навстречу врагу с высоко поднятой головой – и будь что будет." } } }, t = { d = 7.1, v = "skyborne-female", n = { x = 69 }, c = { x = { { 0.00, "Не могу поверить... всё кончено. Мне надо успокоиться. Иначе сердце выпрыгнет из груди." } } } } },
    [92698] = { d = 22.8, v = "elemental-golem", n = { x = 36 }, c = { x = { { 1.66, "Вы наклоняетесь поближе, чтобы расслышать слова, раздающиеся под пластинами огромного голема. Ошибка назначения... Вопрос... В чём.... Назначение..." }, { 12.65, "Похоже, эти обрывки фраз повторяются по кругу. Может быть, кто-то поблизости знает об этой странной машине?" } } }, t = { d = 31.8, v = "skyborne-female", n = { x = 370 }, c = { x = { { 0.00, "Голем? Он уже несколько десятков лет бродит по этим полям. Кажется, с тех пор как ушли элементали воздуха." }, { 7.76, "Альварион предположил, что он перевозил урожай на рынок или помогал ухаживать за скотом, когда здесь был большой сад." }, { 15.60, "Но с тех пор прошла уже тысяча лет." }, { 18.48, "В древние времена таких големов поддерживали Ваятели ветра." }, { 22.37, "Мы хотели подать запрос, чтобы те пришли и осмотрели его, но так и не собрались." }, { 27.73, "В последнее время мы просто не обращаем на него внимания." } } } } },
    [92699] = { d = 30.4, g = 1, v = "skyborne-female", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Ты только что прибыл в Валанаар и, наверное, хочешь встретиться с другими представителями Высшего ордена." }, { 7.62, "Нынешний верховный магистр Элаадрин Вечерняя Буря и его приближённые обосновались в юго-восточной части Валанаара." }, { 15.61, "Будь настороже: Высший орден и Ваятели ветра друг с другом не ладят. Вторых лучше обходить стороной." }, { 23.59, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потреплю." } }, f = { { 0.00, "Ты только что прибыла в Валанаар и, наверное, хочешь встретиться с другими представителями Высшего ордена." }, { 6.96, "Нынешний верховный магистр Элаадрин Вечерняя Буря и его приближённые обосновались в юго-восточной части Валанаара." }, { 14.95, "Будь настороже: Высший орден и Ваятели ветра друг с другом не ладят. Вторых лучше обходить стороной." }, { 22.93, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потреплю." } } }, t = { d = 31.3, v = "skyborne-male", n = { x = 369 }, c = { x = { { 0.00, "Добро пожаловать. Ратирил отправил мне магическое послание – сообщил о тебе и о том, что у тебя есть потенциал." }, { 7.75, "Теперь, когда я вижу тебя своими глазами, мне ясно, почему он предложил тебе встретиться со мной." }, { 14.13, "У тебя ярко выраженная чародейская аура." }, { 16.99, "Среди нас осталось мало тех, кому хватает способностей, не говоря уже о воле, делать то, что должно, ради спасения нашего дома." }, { 25.44, "Достанет ли тебе смелости и силы, чтобы помочь Высшему ордену? Скоро мы это узнаем." } } } } },
    [92700] = { d = 25.7, g = 1, v = "skyborne-female", n = { m = 307, f = 308 }, c = { m = { { 0.00, "Ты только что прибыл в Валанаар и, наверное, хочешь встретиться с другими Ваятелями ветра." }, { 6.01, "Нынешняя великая небовидица и её приближённые обосновались недалеко от центра Валанаара." }, { 12.29, "Будь настороже: Ваятели ветра и Высший орден друг с другом не ладят. Вторых лучше обходи стороной." }, { 18.85, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потреплю." } }, f = { { 0.00, "Ты только что прибыла в Валанаар и, наверное, хочешь встретиться с другими Ваятелями ветра." }, { 5.88, "Нынешняя великая небовидица и её приближённые обосновались недалеко от центра Валанаара." }, { 12.16, "Будь настороже: Ваятели ветра и Высший орден друг с другом не ладят. Вторых лучше обходи стороной." }, { 18.72, "У нас и так хватает хлопот из-за культа – стычки между фракциями на улицах города я не потреплю." } } }, t = { d = 26.5, g = 1, v = "skyborne-female", n = { m = 304, f = 307 }, c = { m = { { 0.00, "Старейшина Янтарный Ветер прислала мне весточку о тебе и твоих подвигах в деревне Шен'дар. Тебе здесь очень рады, друг." }, { 8.37, "У тебя сильная аура, и ты явно на одной волне с духами." }, { 12.06, "В последнее время небесным взором владеют всё меньше наших, а Зефрису нужны те, у кого есть этот дар, если мы хотим пережить тяжёлые времена." }, { 21.43, "Я рада, что ты нашёл дорогу ко мне. Буду рада узнать тебя поближе." } }, f = { { 0.00, "Старейшина Янтарный Ветер прислала мне весточку о тебе и твоих подвигах в деревне Шен'дар. Тебе здесь очень рады, подруга." }, { 8.52, "У тебя сильная аура, и ты явно на одной волне с духами." }, { 12.21, "В последнее время небесным взором владеют всё меньше наших, а Зефрису нужны те, у кого есть этот дар, если мы хотим пережить тяжёлые времена." }, { 21.58, "Я рада, что ты нашла дорогу ко мне. Буду рада узнать тебя поближе." } } } } },
    [92701] = { d = 36.4, v = "skyborne-female", n = { x = 386 }, c = { x = { { 0.00, "Пока похоже, что столп и деревня в безопасности, и я хочу попросить тебя доставить этот доклад Валеннии Штормовой Кулак в Валанаар, на юго-восточный край острова." }, { 13.59, "Валенния – лидер миротворцев на острове, и она должна узнать, что здесь произошло." }, { 19.43, "Культ быстро разрастается, и миротворцы до сих пор избегали открытого столкновения, но дальше так продолжаться не может. Валанаар должен быть готов к бою." }, { 31.08, "Как бы то ни было, спасибо тебе. В Шен'даре ты всегда найдёшь верных друзей." } } }, t = { d = 33.4, v = "skyborne-female", n = { x = 357 }, c = { x = { { 0.00, "Читая письмо, Валенния мрачнеет." }, { 2.76, "Аонда доверила тебе доставку послания и хорошо о тебе отзывается в нём. Я тоже постараюсь тебе доверять." }, { 9.83, "Прежде чем продолжить разговор, мне нужно посоветоваться с теми немногими миротворцами, что ещё остались со мной, и разработать план на случай нападения культа. Отдохни пока в Валанааре." }, { 23.65, "Если будешь искать себе занятие, многим горожанам, скорее всего, не помешает помощь такого молодого и сильного искателя приключений, как ты." } } } } },
    [92703] = { d = 30.1, g = 1, v = "skyborne-female", n = { m = 318, f = 318 }, c = { m = { { 0.00, "Не дело и дальше называть тебя незнакомцем... Спасибо тебе." }, { 4.23, "Если ты всё равно собираешься возвращаться, может, расскажешь Альвариону, что здесь случилось?" }, { 10.47, "И ещё передай, что когда встанет на ноги, пусть приведёт на ферму Ваятеля ветра: пусть взглянет на того голема и убедится, что он не будет опасен для нашего... для нашей семьи." }, { 22.13, "Аамелия с нежностью прикасается к животу." }, { 25.28, "Он ещё не знает об этом. Пусть эта деталь пока останется между нами." } }, f = { { 0.00, "Не дело и дальше называть тебя незнакомкой... Спасибо тебе." }, { 4.21, "Если ты всё равно собираешься возвращаться, может, расскажешь Альвариону, что здесь случилось?" }, { 10.44, "И ещё передай, что когда встанет на ноги, пусть приведёт на ферму Ваятеля ветра: пусть взглянет на того голема и убедится, что он не будет опасен для нашего... для нашей семьи." }, { 22.11, "Аамелия с нежностью прикасается к животу." }, { 25.26, "Он ещё не знает об этом. Пусть эта деталь пока останется между нами." } } }, t = { d = 27.9, g = 1, v = "skyborne-male", n = { m = 230, f = 231 }, c = { m = { { 0.00, "Вы рассказываете Альвариону, что произошло в саду. Он слушает со слезами на глазах." }, { 6.00, "Даже не знаю, как тебя отблагодарить, друг мой. Я пришёл в Валанаар в поисках надежды и был почти уверен, что моё желание тщетно." }, { 15.59, "Но я нашёл героя. Настоящего, как в старых легендах до нашего исхода в Небесную высь." }, { 22.19, "Я не забуду, что ты для нас сделал. Тебе всегда будут рады в доме Поля Ветров." } }, f = { { 0.00, "Вы рассказываете Альвариону, что произошло в саду. Он слушает со слезами на глазах." }, { 6.00, "Даже не знаю, как тебя отблагодарить, друг мой. Я пришёл в Валанаар в поисках надежды и был почти уверен, что моё желание тщетно." }, { 15.59, "Но я нашёл героя. Настоящего, как в старых легендах до нашего исхода в Небесную высь." }, { 22.19, "Я не забуду, что ты для нас сделала. Тебе всегда будут рады в доме Поля Ветров." } } } } },
    [92706] = { d = 18.6, v = "human-male#114", n = { x = 190 }, c = { x = { { 0.00, "Внимание всем рыболовам!" }, { 2.48, "В водах около пристани завелась огромная акула, которая нападает на матросов и небольшие суда." }, { 9.85, "Работники пристани дали ей прозвище \"Брууз\". Тот, кто принесёт мне её плавник, будет щедро вознаграждён! – Газлоу" } } }, t = { d = 16.2, v = "named/3391", n = { x = 185 }, c = { x = { { 0.00, "Наконец-то кто-то прикончил эту тварь! Знаешь, как трудно загнать команду в воду, когда весь город без конца вопит «Акула!»?" }, { 8.80, "Пожалуй, сварю сегодня на ужин суп из плавника этого чудища – просто чтобы последнее слово осталось за мной." } } } } },
    [92708] = { d = 23.9, g = 1, v = "skyborne-female", n = { m = 283, f = 287 }, c = { m = { { 0.00, "Ваятели ветра работают не покладая рук, чтобы отвратить беду, грозящую острову Зефрис." }, { 5.76, "В поисках пропавших духов ветра мы сделали несколько неожиданных открытий и составляем план, как спасти остров." }, { 13.55, "Правда, нам понадобятся молодые и крепкие искатели приключений вроде тебя." }, { 19.32, "Прошу, если у тебя есть свободная минутка, давай поговорим об этом." } }, f = { { 0.00, "Ваятели ветра работают не покладая рук, чтобы отвратить беду, грозящую острову Зефрис." }, { 5.76, "В поисках пропавших духов ветра мы сделали несколько неожиданных открытий и составляем план, как спасти остров." }, { 13.55, "Правда, нам понадобятся молодые и крепкие искательницы приключений вроде тебя." }, { 18.72, "Прошу, если у тебя есть свободная минутка, давай поговорим об этом." } } }, t = { d = 25.0, v = "skyborne-female", n = { x = 291 }, c = { x = { { 0.00, "Теперь понимаешь? За пределами Небесной выси – целый мир знаний и нераскрытых возможностей." }, { 6.65, "Она навсегда останется нашим домом, но я всё больше убеждаюсь, что путь к спасению лежит внизу." }, { 13.06, "Мы должны отправиться на Азерот и обрести силу и средства, чтобы спасти остров Зефрис. Таков наш путь." }, { 20.21, "Хватит ли у тебя смелости присоединиться к нам, когда придёт время?" } } } } },
    [92709] = { d = 17.5, g = 1, v = "skyborne-male", n = { m = 202, f = 202 }, c = { m = { { 0.00, "Твоё благородное происхождение неоспоримо. Я вижу его в твоих глазах, как ясное небо." }, { 5.78, "Ты один из нас, и именно такие молодые эльфы, как ты, помогут спасти наш дом." }, { 11.01, "Но сначала позволь рассказать о наших планах и целях – здесь, на Зефрисе, и за его пределами." } }, f = { { 0.00, "Твоё благородное происхождение неоспоримо. Я вижу его в твоих глазах, как ясное небо." }, { 5.78, "Ты одна из нас, и именно такие молодые эльфы, как ты, помогут спасти наш дом." }, { 11.01, "Но сначала позволь рассказать о наших планах и целях – здесь, на Зефрисе, и за его пределами." } } }, t = { d = 32.1, v = "skyborne-male", n = { x = 369 }, c = { x = { { 0.00, "Теперь ты понимаешь? Возрождение древней магии наших предшественников – ключ к разгадке тайн острова Зефрис и к нашему светлому будущему." }, { 10.13, "Чтобы спасти наш дом, мы должны заново открыть то, что утратили за прошедшие тысячелетия." }, { 16.51, "Ответ кроется на Азероте, и маги Кирин-Тора готовы указать нам путь." }, { 21.51, "Пока мы готовимся к отбытию, поговори с другими членами Высшего ордена в Валанааре." }, { 26.92, "У многих из них есть важные дела, с которыми не помешала бы твоя помощь." } } } } },
    [92727] = { d = 32.8, v = "skyborne-male", n = { x = 382 }, c = { x = { { 0.00, "Поиск новых знаний – ключевая цель Высшего ордена, но из-за ситуации на Зефрисе этот труд стал как никогда опасен." }, { 8.05, "Один из наших учёных, Филлион Огненная Дымка, направился в Шен'дарское нагорье, чтобы изучить магию ветра, которая собирается там в некоторых местах." }, { 18.02, "Увы, он до сих пор не вернулся, и мы опасаемся, что с ним могло что-то случиться по пути." }, { 24.22, "Прошу, постарайся его отыскать. В последний раз его видели на дороге, ведущей от Валанаара на запад, к Шен'дарскому нагорью." } } }, t = { d = 12.6, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "Вы видите на клапане брошенной сумки вкрапления чего-то, похожего на засохшую кровь." }, { 5.66, "Разглядывая пятна, вы также замечаете на клапане вышивку с именем: \"Филлион Огненная Дымка\"." } } } } },
    [92741] = { d = 29.6, v = "skyborne-female", n = { x = 366 }, c = { x = { { 0.00, "Теневейный лес очень опасен, и простые искатели приключений туда обычно не ходят." }, { 5.39, "Однако недавно популяция визгунов возросла настолько, что эти звери начали покидать лес в поиске новых территорий." }, { 13.03, "Я хочу изучить алхимические свойства их когтей, так что, сократив численность этих особей, мы можем заодно почерпнуть полезные научные знания." }, { 22.76, "Отправляйся в Теневейный лес и поохоться на визгунов. Добудь как можно больше когтей и принеси мне." } } }, t = { d = 8.5, g = 1, v = "skyborne-female", n = { m = 83, f = 85 }, c = { m = { { 0.00, "Ну и гору когтей ты мне принёс! Не терпится приступить к изучению!" }, { 4.83, "Благодарю за службу Высшему ордену, герой." } }, f = { { 0.00, "Ну и гору когтей ты мне принесла! Не терпится приступить к изучению!" }, { 4.87, "Благодарю за службу Высшему ордену, героиня." } } } } },
    [92742] = { d = 14.0, v = "nightelf-female#52", n = { x = 169 }, c = { x = { { 0.00, "Нужно отыскать источник яда, поразившего эти земли, и понять его природу. Начнём с исследования подземных вод под местными фермами." }, { 8.80, "Ступай во владение Янсена и на ферму Мольсена и возьми пробы из колодцев." } } }, t = { d = 2.5, v = "nightelf-female#52", n = { x = 25 }, c = { x = { { 0.00, "Благодарю. Дай-как посмотреть..." } } } } },
    [92744] = { d = 24.5, v = "nightelf-female#52", n = { x = 293 }, c = { x = { { 0.00, "Порча, которая одолевает посевы в Западном крае, просочилась и в океан." }, { 4.61, "Если она заразит местную рыбу, это может привести к голоду в Штормграде." }, { 9.73, "Собери жабры мурлоков на побережье и принеси мне." }, { 13.08, "Мурлоки крайне живучие существа, но их физиология такова, что они чутко реагируют на любые загрязнения." }, { 20.04, "Если в морской воде есть яд, он обязательно будет в их жабрах." } } }, t = { d = 4.7, v = "nightelf-female#52", n = { x = 52 }, c = { x = { { 0.00, "Понятно... жабры, похоже, пока чистые. Но расслабляться нам нельзя." } } } } },
    [92745] = { d = 26.2, g = 1, v = "nightelf-female#52", n = { m = 320, f = 321 }, c = { m = { { 0.00, "В образцах колодезной воды, которые ты собрал, содержатся ядовитые металлы!" }, { 5.00, "Если сейчас же не положить конец этой порче, на здешних полях не будет урожаев ещё несколько десятилетий." }, { 12.46, "Братство Справедливости захватило рудники Западного края и заставляет местных обитателей добывать ресурсы." }, { 19.65, "Сорви их планы, убив шахтёров на руднике Янго на севере и прииске на Золотом Берегу на западе." } }, f = { { 0.00, "В образцах колодезной воды, которые ты собрала, содержатся ядовитые металлы!" }, { 4.95, "Если сейчас же не положить конец этой порче, на здешних полях не будет урожаев ещё несколько десятилетий." }, { 12.41, "Братство Справедливости захватило рудники Западного края и заставляет местных обитателей добывать ресурсы." }, { 19.60, "Сорви их планы, убив шахтёров на руднике Янго на севере и прииске на Золотом Берегу на западе." } } }, t = { d = 4.7, v = "nightelf-female#52", n = { x = 51 }, c = { x = { { 0.00, "Отлично. Но, боюсь, источник яда находится где-то в другом месте..." } } } } },
    [92747] = { d = 25.2, g = 1, v = "nightelf-female#52", n = { m = 294, f = 295 }, c = { m = { { 0.00, "Странно. Судя по всему, яд появился не на том руднике, который ты обследовал." }, { 5.42, "Говорят, Мёртвые копи под городом Луноречье – самые глубокие и обширные шахты в Западном Крае, но их забросили ещё во времена Первой войны." }, { 14.59, "Неужели там снова что-то происходит?" }, { 17.39, "Прошу, отправляйся в Луноречье, и отыщи свидетельства любой активности в шахтах. Это наша последняя зацепка!" } }, f = { { 0.00, "Странно. Судя по всему, яд появился не на том руднике, который ты обследовала." }, { 5.65, "Говорят, Мёртвые копи под городом Луноречье – самые глубокие и обширные шахты в Западном Крае, но их забросили ещё во времена Первой войны." }, { 14.81, "Неужели там снова что-то происходит?" }, { 17.61, "Прошу, отправляйся в Луноречье, и отыщи свидетельства любой активности в шахтах. Это наша последняя зацепка!" } } }, t = { d = 1.5, v = "nightelf-female#52", n = { x = 11 }, c = { x = { { 0.00, "Что это такое?" } } } } },
    [92748] = { d = 26.0, g = 1, v = "nightelf-female#52", n = { m = 316, f = 317 }, c = { m = { { 0.00, "Припасы, которые ты обнаружил, указывают, что кто-то развил в Мёртвых копях бурную деятельность." }, { 6.29, "Без сомнения, именно это и есть источник токсина, который отравляет поля Западного Края." }, { 12.03, "Нужно как можно скорее положить этому конец." }, { 15.36, "Что бы ни ждало нас внизу, уничтожить это будет непросто." }, { 19.28, "Ступай в Квартал Дворфов в Штормграде и отыщи инженера, который сможет снабдить нас взрывчаткой." } }, f = { { 0.00, "Припасы, которые ты обнаружила, указывают, что кто-то развил в Мёртвых копях бурную деятельность." }, { 6.38, "Без сомнения, именно это и есть источник токсина, который отравляет поля Западного Края." }, { 12.12, "Нужно как можно скорее положить этому конец." }, { 15.45, "Что бы ни ждало нас внизу, уничтожить это будет непросто." }, { 19.37, "Ступай в Квартал Дворфов в Штормграде и отыщи инженера, который сможет снабдить нас взрывчаткой." } } }, t = { d = 2.3, v = "gnome-female", n = { x = 23 }, c = { x = { { 0.00, "Хочешь что-нибудь взорвать?" } } } } },
    [92749] = { d = 4.2, v = "gnome-female", n = { x = 46 }, c = { x = { { 0.00, "Промышленный саботаж? Я вся внимание! Начнём с динамита..." } } }, t = { d = 5.8, v = "gnome-female", n = { x = 58 }, c = { x = { { 0.00, "Отличное начало! Теперь всё это соединить... и добавить немного огонька..." } } } } },
    [92750] = { d = 16.4, v = "gnome-female", n = { x = 187 }, c = { x = { { 0.00, "Полагаю, тебе нужен \"управляемый\" взрыв? Это не так весело, но если не хочешь потерять пару конечностей, то сойдёт." }, { 8.11, "Боюсь, у меня нет дистанционного детонатора. Сходи к ребятам из разведки Штормграда – у них должно что-нибудь найтись." } } }, t = { d = 2.6, v = "human-male#116", n = { x = 23 }, c = { x = { { 0.00, "Хм-м... ищешь что-то конкретное?" } } } } },
    [92751] = { d = 31.8, v = "human-male#116", n = { x = 374 }, c = { x = { { 0.00, "Хочешь что-то уничтожить? Это имеет какое-то отношение к тому, чем ты занимаешься в Луноречье?" }, { 6.31, "Не удивляйся – ШРУ в курсе всего, что происходит в землях Штормграда." }, { 11.13, "Если собираешься устроить взрыв в пещерах под Западным краем, обязательно сперва выберись на поверхность." }, { 18.31, "Вот, возьми этот дистанционный детонатор. Это новая разработка наших инженеров." }, { 24.19, "Ах да, и будет лучше, если ты не станешь рассказывать о моём участии в этой затее своей эльфийской подруге." } } }, t = { d = 3.6, v = "gnome-female", n = { x = 38 }, c = { x = { { 0.00, "Прекрасно! Как раз такой детонатор нам и нужен!" } } } } },
    [92752] = { d = 4.1, v = "gnome-female", n = { x = 46 }, c = { x = { { 0.00, "Ну вот, бомба готова! Только поаккуратнее с детонатором." } } } },
    [92753] = { d = 20.7, v = "nightelf-female#52", n = { x = 249 }, c = { x = { { 0.00, "Скорее всего, источником яда является какой-то крупный металлургический горн." }, { 5.21, "Проберись в Мёртвые копи и найти этот горн, а затем заложи взрывчатку." }, { 10.14, "Я буду ждать тебя в холмах за Луноречьем. Мы детонируем взрывчатку, когда ты вернёшься." }, { 16.09, "Надеюсь, когда этот горн будет уничтожен, земля сможет исцелиться." } } }, t = { d = 4.6, g = 1, v = "nightelf-female#52", n = { m = 51, f = 52 }, c = { m = { { 0.00, "Значит, ты нашёл горн и заложил взрывчатку... Осталось лишь одно." } }, f = { { 0.00, "Значит, ты нашла горн и заложила взрывчатку... Осталось лишь одно." } } } } },
    [92819] = { d = 4.3, v = "nightelf-female#52", n = { x = 49 }, c = { x = { { 0.00, "Мы почти закончили. Используй детонатор и заверши начатое." } } }, t = { d = 8.4, v = "nightelf-female#52", n = { x = 101 }, c = { x = { { 0.00, "Даже не знаю, что сказать. Подумать только: Штормград ставит свои военные амбиции выше благополучия собственного народа..." } } } } },
    [92834] = { d = 34.2, v = "skyborne-male", n = { x = 414 }, c = { x = { { 0.00, "Когда культ начал свою кампанию насилия, миротворцы и Ваятели ветра ответили показной бравадой." }, { 6.43, "Я посчитал, что глупо ещё больше разжигать конфликт, и выступил за мирный диалог." }, { 11.88, "Вчера я отправил своего друга Белатаана Яркая Мечта к святилищу Акира, надеясь наладить этот диалог." }, { 18.94, "Только что прибыла шкатулка с языком Белатаана, обмакнутым в серебряный пигмент." }, { 24.74, "Теперь я вижу, что договариваться с культом бесполезно." }, { 28.34, "Убей всех сектантов, которых повстречаешь, и принеси мне их молитвенные талисманы." } } }, t = { d = 24.6, v = "skyborne-male", n = { x = 246 }, c = { x = { { 0.00, "Высший орден гордится своим прагматизмом и логикой, а логика показывает, что избежание конфликта и напрасных потерь – наиболее разумное решение в большинстве ситуаций." }, { 11.31, "Глаза Элаадрина загораются и искрятся от чародейской энергии." }, { 15.87, "Однако сектанты приняли нашу осмотрительность за слабость, и они даже не представляют, как серьёзно поплатятся за эту ошибку." } } } } },
    [92840] = { d = 33.3, v = "skyborne-male", n = { x = 405 }, c = { x = { { 0.00, "Магию, которая поддерживает этот остров, также можно найти вокруг каменных монолитов на Шен'дарском нагорье." }, { 7.39, "Увы, это место считается священным и находится под непосредственной защитой Ваятелей ветра, что затрудняет изучение присутствующей там магии." }, { 17.20, "Пока Ваятели ветра заняты другими вопросами, у нас появилась возможность изучить природу этих стихийных чар." }, { 24.82, "Отнеси это устройство к монолитам и защити его, пока оно собирает важные данные. Постарайся не привлекать к себе внимание." } } }, t = { d = 31.4, g = 1, v = "skyborne-male", n = { m = 366, f = 368 }, c = { m = { { 0.00, "Я надеялся, что нам не придётся проливать кровь Ваятелей ветра, но вина за этот конфликт целиком и полностью лежит на них." }, { 8.33, "Ты был там исключительно с мирной целью – это они решили прибегнуть к насилию." }, { 13.79, "Вести о том, что случилось у каменных монолитов, уже дошли до других Ваятелей." }, { 19.12, "Они не посмеют мстить нам в Валанааре, но ни за что не забудут этой обиды." }, { 24.43, "Ты оказал неоценимую помощь Высшему ордену. Неудивительно, что Ратирил разглядел в тебе потенциал." } }, f = { { 0.00, "Я надеялся, что нам не придётся проливать кровь Ваятелей ветра, но вина за этот конфликт целиком и полностью лежит на них." }, { 8.33, "Ты была там исключительно с мирной целью – это они решили прибегнуть к насилию." }, { 13.76, "Вести о том, что случилось у каменных монолитов, уже дошли до других Ваятелей." }, { 19.08, "Они не посмеют мстить нам в Валанааре, но ни за что не забудут этой обиды." }, { 24.39, "Ты оказала неоценимую помощь Высшему ордену. Неудивительно, что Ратирил разглядел в тебе потенциал." } } } } },
    [92849] = { d = 14.6, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Судя по вашей находке, Филлиона постигла какая-то беда. Быть может, он ещё рядом и нуждается в помощи." }, { 7.93, "Вы замечаете пещеру с северной стороны от вас. Пожалуй, стоит продолжить поиски там." } } }, t = { d = 23.3, g = 1, v = "skyborne-male", n = { m = 263, f = 263 }, c = { m = { { 0.00, "С... спасибо, незнакомец. Я уже возвращался в Валанаар, когда надо мной вдруг возникла большая тень." }, { 6.48, "Я обернулся и увидел, как с неба на меня мчится огромный и ужасный зверь." }, { 11.79, "Я побежал, но что-то тут же ударило меня, и всё потемнело." }, { 16.00, "Скажу без преувеличения: если бы ты сейчас не подошёл, я бы сгинул в пасти этого зверя и его детёнышей." } }, f = { { 0.00, "С... спасибо, незнакомка. Я уже возвращался в Валанаар, когда надо мной вдруг возникла большая тень." }, { 6.46, "Я обернулся и увидел, как с неба на меня мчится огромный и ужасный зверь." }, { 11.77, "Я побежал, но что-то тут же ударило меня, и всё потемнело." }, { 15.98, "Скажу без преувеличения: если бы ты сейчас не подошла, я бы сгинул в пасти этого зверя и его детёнышей." } } } } },
    [92850] = { d = 31.1, v = "skyborne-male", n = { x = 369 }, c = { x = { { 0.00, "Мне уже гораздо лучше. Я неплохо владею тайной магией, и до Валанаара совсем недалеко. Я доберусь до него сам." }, { 7.48, "Сейчас моя безопасность – не самое важное: подумай, как близко к Валанаару обосновались эти визгуны и какую опасность они представляют." }, { 16.52, "Прошу, сделай одолжение: вернись в пещеру и отруби голову этой зверюге!" }, { 21.65, "А после отыщи нас с Дондаллионом в Валанааре. Постараюсь вернуться к нему как можно скорее." }, { 27.83, "Он, наверное, уже измучился от беспокойства." } } }, t = { d = 12.5, g = 1, v = "skyborne-male", n = { x = 132 }, c = { m = { { 0.00, "Признаю, я страшно рад, что Филлион к нам вернулся. Он частенько не замечает, что творится вокруг." }, { 6.59, "То слишком глубоко задумается, то увлечётся книгой... Спасибо тебе, герой." } }, f = { { 0.00, "Признаю, я страшно рад, что Филлион к нам вернулся. Он частенько не замечает, что творится вокруг." }, { 6.59, "То слишком глубоко задумается, то увлечётся книгой... Спасибо тебе, героиня." } } } } },
    [92860] = { d = 30.9, v = "skyborne-male", n = { x = 376 }, c = { x = { { 0.00, "Верховный орден всячески старался избегать прямого конфликта с культом, но теперь это не представляется возможным." }, { 7.78, "Они проявили открытую враждебность, а теперь до нас доходят слухи о более масштабных движениях сектантов по всему острову." }, { 16.11, "Они явно что-то замышляют, и вряд ли это пойдёт на благо жителям Зефриса." }, { 21.43, "Отправляйся к Валеннии Штормовой Кулак и сообщи, что Верховный орден предлагает свою полную поддержку в борьбе Валанаара против ал'акетов." } } }, t = { d = 17.1, g = 1, v = "skyborne-female", n = { m = 195, f = 197 }, c = { m = { { 0.00, "Жаль, что так вышло с Белатааном. Ты, наверное, не знал, но я его двоюродная сестра." }, { 5.46, "Он был хорошим магом и верой и правдой служил нашему острову. Мы за него отомстим." }, { 11.45, "Вижу, ты уже готов оказать поддержку. Идём. Надо обсудить сложившуюся ситуацию." } }, f = { { 0.00, "Жаль, что так вышло с Белатааном. Ты, наверное, не знала, но я его двоюродная сестра." }, { 5.40, "Он был хорошим магом и верой и правдой служил нашему острову. Мы за него отомстим." }, { 11.39, "Вижу, ты уже готова оказать поддержку. Идём. Надо обсудить сложившуюся ситуацию." } } } } },
    [92871] = { d = 23.3, v = "skyborne-female", n = { x = 277 }, c = { x = { { 0.00, "Валенния Штормовой Кулак и её миротворцы всегда были защитниками Зефриса, и мы стараемся помогать им как можем." }, { 7.49, "Ходят слухи, что по всему острову пришли в движение силы сектантов, они явно что-то замышляют." }, { 14.19, "Отправляйся к Валеннии и скажи, что Ваятели ветра готовы всеми силами поддержать её в битве за Валаннар, если это будет необходимо." } } }, t = { d = 5.7, v = "skyborne-female", n = { x = 67 }, c = { x = { { 0.00, "Ты как будто хочешь немедленно начать действовать. Идём, давай обсудим ситуацию." } } } } },
    [92880] = { d = 28.6, g = 1, v = "skyborne-female", n = { x = 319 }, c = { m = { { 0.00, "Думаю, нам потребуется некоторое время, чтобы добить остатки нападавших, но сейчас наши шансы намного выше." }, { 7.10, "Возвращайся в Валанаар и скажи, что теперь ситуация под контролем." }, { 11.90, "Не могу выразить словами, как я тебе благодарна. Без тебя нас ждала бы ужасная участь." }, { 18.77, "Похоже, вместо отряда подкрепления мне прислали начинающего героя. Что ж, меня это устраивает." }, { 25.46, "Да благословят тебя четыре ветра, герой." } }, f = { { 0.00, "Думаю, нам потребуется некоторое время, чтобы добить остатки нападавших, но сейчас наши шансы намного выше." }, { 7.10, "Возвращайся в Валанаар и скажи, что теперь ситуация под контролем." }, { 11.90, "Не могу выразить словами, как я тебе благодарна. Без тебя нас ждала бы ужасная участь." }, { 18.77, "Похоже, вместо отряда подкрепления мне прислали начинающего героя. Что ж, меня это устраивает." }, { 25.46, "Да благословят тебя четыре ветра, героиня." } } }, t = { d = 7.8, v = "skyborne-female", n = { x = 11 }, c = { x = { { 0.00, "Валенния с видимым облегчением выслушивает ваш отчёт о ситуации у восточной башни. Хвала ветрам..." } } } } },
    [92881] = { d = 20.5, v = "skyborne-female", n = { x = 231 }, c = { x = { { 0.00, "То, что враг напал на западную и восточную сторожевые башни, – не совпадение." }, { 5.96, "Судя по твоему рассказу о западной башне и жреце небес, культ хочет что-то сделать с опорными столпами." }, { 13.30, "Поговори с верховным старейшиной Песня Теней. Он расскажет тебе о зацепке, которую нам стоит проверить." } } }, t = { d = 7.3, v = "skyborne-male", n = { x = 86 }, c = { x = { { 0.00, "Есть одно маленькое дело, для решения которого как раз нужна помощь такого искателя приключений, как ты." } } } } },
    [92909] = { d = 28.7, v = "gnome-male", n = { x = 330 }, c = { x = { { 0.00, "О нет... вот это я попал!" }, { 2.16, "Мне рассказали, что в Западном крае на полях бесчинствуют големы, так что я прибыл сюда аж из самого Стальгорна, чтобы попробовать их перенастроить." }, { 12.21, "Но они оказались куда агрессивнее, чем предсказывали мои расчёты. Даже загнали меня вот в эту конюшню!" }, { 19.57, "Будь у меня изопружины и гиростабилизаторы големов, я бы собрал устройство, которое поможет скрыться. Соберёшь для меня запчасти?" } } }, t = { d = 4.9, v = "gnome-male", n = { x = 45 }, c = { x = { { 0.00, "Вот спасибо! Я займусь планированием побега. А это тебе!" } } } } },
    [92910] = { d = 10.8, v = "human-male#114", n = { x = 111 }, c = { x = { { 0.00, "Деталь, которую вам удалось добыть у голема, на вид почти целая." }, { 4.89, "Возможно, на неё захочет взглянуть кто-нибудь, интересующийся големами." } } }, t = { d = 1.3, v = "gnome-male", n = { x = 7 }, c = { x = { { 0.00, "Это чего?" } } } } },
    [92911] = { d = 17.3, g = 1, v = "gnome-male", n = { m = 189, f = 193 }, c = { m = { { 0.00, "Понятно... Теперь я чуть лучше понимаю, как эти чудища работают." }, { 4.34, "У меня есть идея, как можно обойти их системы – по крайней мере, временно." }, { 9.66, "Я продолжу ковыряться в том, что ты принёс, а пока не мог бы ты собрать кое-какие детали для устройства?" } }, f = { { 0.00, "Понятно... Теперь я чуть лучше понимаю, как эти чудища работают." }, { 4.34, "У меня есть идея, как можно обойти их системы – по крайней мере, временно." }, { 9.66, "Я продолжу ковыряться в том, что ты принесла, а пока не могла бы ты собрать кое-какие детали для устройства?" } } }, t = { d = 8.4, v = "gnome-male", n = { x = 80 }, c = { x = { { 0.00, "Вот, держи! Должно отлично сработать. Иди испытай!" }, { 4.25, "...Я? Нет, я останусь здесь. Тут уже как-то по-домашнему." } } } } },
    [92947] = { d = 35.6, g = 1, v = "skyborne-female", n = { x = 394 }, c = { m = { { 0.00, "Всё на месте. Хорошо. Я отправила несколько моих лучших бойцов на передовую, чтобы они устроили немного шума и отвлекли врага." }, { 10.12, "Тем временем я заведу отряд Ваятелей ветра и Высшего ордена с тыла." }, { 15.00, "Если всё пройдёт гладко, мы быстро пробьёмся к святилищу и устраним верховную жрицу." }, { 21.21, "Теперь твоя часть плана: ворвись туда и начинай убивать врагов." }, { 25.51, "Когда посеешь достаточно хаоса, найди мою первую помощницу Хюсаа Быстрый Бриз. Она будет ждать у ступеней святилища. Да хранят тебя ветра, герой." } }, f = { { 0.00, "Всё на месте. Хорошо. Я отправила несколько моих лучших бойцов на передовую, чтобы они устроили немного шума и отвлекли врага." }, { 10.12, "Тем временем я заведу отряд Ваятелей ветра и Высшего ордена с тыла." }, { 15.00, "Если всё пройдёт гладко, мы быстро пробьёмся к святилищу и устраним верховную жрицу." }, { 21.21, "Теперь твоя часть плана: ворвись туда и начинай убивать врагов." }, { 25.51, "Когда посеешь достаточно хаоса, найди мою первую помощницу Хюсаа Быстрый Бриз. Она будет ждать у ступеней святилища. Да хранят тебя ветра, героиня." } } }, t = { d = 3.5, v = "skyborne-female", n = { x = 37 }, c = { x = { { 0.00, "Мы с боем прошли так далеко, но это ещё не конец." } } } } },
    [93036] = { d = 31.2, v = "skyborne-female", n = { x = 377 }, c = { x = { { 0.00, "Может, ты не знаешь: это Сания Серебряный Поток, миссионер культа Ал'акет." }, { 4.91, "Они любят прикидываться обычной религией и отправлять мирных посланников, чтобы пополнять свои ряды." }, { 11.52, "Пока что мы терпели присутствие Сании, чтобы избежать прямого конфликта с сектантами, но, очевидно, иллюзия мира продержится недолго." }, { 20.80, "Ты здесь недавно, и многие тебя ещё не знают. Может, у тебя получится подобраться к культу через их миссионера?" }, { 28.12, "Нам бы узнать, каковы их планы в деревне." } } }, t = { d = 14.8, v = "skyborne-female", n = { x = 158 }, c = { x = { { 0.00, "Приветствую, дитя. Я Сания Серебряный Поток, жрица ордена Ал'акет. Хочешь узнать больше о нашем повелителе Ал'акире Владыке Ветра?" }, { 10.32, "За его столом всегда найдётся место для праведных и покаянных." } } } } },
    [93065] = { d = 14.1, v = "skyborne-female", n = { x = 170 }, c = { x = { { 0.00, "Миротворцы уже мобилизуются, а мы снаряжаемся к бою." }, { 3.82, "Сделай все необходимые приготовления и выходи на восточную дорогу, ведущую из города на север." }, { 10.02, "Там мы проведём последнюю перекличку и двинемся на врага." } } }, t = { d = 1.8, v = "skyborne-female", n = { x = 17 }, c = { x = { { 0.00, "Мы готовы выступать." } } } } },
    [93089] = { d = 29.5, v = "skyborne-male", n = { x = 347 }, c = { x = { { 0.00, "Передай мою благодарность Элаадрину за всё, что Высший орден и твои новые друзья из Кирин-Тора сделали ради Зефриса." }, { 7.91, "Я знаю, что Высший орден собирается покинуть остров, и я благословляю вашу экспедицию. Желаю удачи." }, { 15.01, "Надеюсь, благодаря своей магии орден найдёт ответы и вернёт нам покой, которого мы были лишены в последние годы." }, { 22.54, "Если ты собираешься отправиться с ним... что ж, вместе вы будете сильнее. Да пребудет с тобой ветер." } } }, t = { d = 22.5, v = "skyborne-male", n = { x = 257 }, c = { x = { { 0.00, "Меня радует, что верховный старейшина Песня Теней благословил нашу экспедицию." }, { 5.40, "Мы разгромили секту и подготовили всё необходимое, – думаю, пора в путь." }, { 10.43, "Трудяга Ансирем подготовил работающий неборез, который доставит нас с Зефриса в город Даларан." }, { 16.68, "Мы всё проверили как только могли – пора авангарду отправляться." } } } } },
    [93090] = { d = 26.5, v = "skyborne-male", n = { x = 313 }, c = { x = { { 0.00, "Передай мою благодарность Айессе за всё, что Ваятели ветра и твои новые друзья из круга Служителей Земли сделали ради Зефриса." }, { 8.58, "Я знаю о планах собрать Ваятелей ветра и покинуть остров и благословляю экспедицию. Желаю твоему ордену удачи." }, { 16.44, "Надеюсь, что Ваятели ветра найдут ответы на все вопросы и вернут нам покой, которого мы были лишены в последние годы. Да пребудет с тобой ветер." } } } },
    [93159] = { d = 15.8, v = "gnome-male", n = { x = 111 }, c = { x = { { 0.00, "Э-э... здрасьте. То есть привет! Или как там, приветствую! Извиняюсь, я... очень давно ни с кем не разговаривал. Боюсь, что отвык." }, { 8.74, "Странная фигура в капюшоне неловко мнётся перед вами. Так, э-э... как твои дела?" } } }, t = { d = 30.3, v = "gnome-male", n = { x = 331 }, c = { x = { { 0.00, "...Вот и всё, что я могу об этом рассказать. Я был... гм... где-то ещё, а потом оказался тут." }, { 6.37, "И теперь я тут со своими друзьями и своими вещами. Вещами... которые сделал сам. Это всё, что мне нужно." }, { 13.35, "Ну, я так думаю, во всяком случае." }, { 16.09, "Но вот что хочу сказать, это здорово – говорить с кем-то, кто может тебе ответить." }, { 21.44, "Лесные духи стараются отвечать, но они умеют только петь. Это тоже по-своему мило, но интеллектуальная беседа не получается." } } } } },
    [93160] = { d = 23.6, g = 1, v = "gnome-male", n = { m = 257, f = 259 }, c = { m = { { 0.00, "Спасибо, что остановился и поболтал со мной! Я... если хочешь помочь, пожалуйста, собери опавшие жёлуди." }, { 6.89, "Тут я их уже собрал, но дальше в лесу водится куча этих не то птиц, не то ящеров." }, { 12.93, "Там опасно, а я не хочу стать обедом для огромной птицы!" }, { 17.25, "Так что если хочешь, может, соберёшь желудей? А я приготовлю для нас что-нибудь вкусное!" } }, f = { { 0.00, "Спасибо, что остановилась и поболтала со мной! Я... если хочешь помочь, пожалуйста, собери опавшие жёлуди." }, { 7.07, "Тут я их уже собрал, но дальше в лесу водится куча этих не то птиц, не то ящеров." }, { 13.11, "Там опасно, а я не хочу стать обедом для огромной птицы!" }, { 17.43, "Так что если хочешь, может, соберёшь желудей? А я приготовлю для нас что-нибудь вкусное!" } } }, t = { d = 6.9, g = 1, v = "gnome-male", n = { m = 72, f = 72 }, c = { m = { { 0.00, "Спасибо, незнакомец! Я их поджарю, будет пальчики оближешь. Один момент, сейчас всё будет." } }, f = { { 0.00, "Спасибо, незнакомка! Я их поджарю, будет пальчики оближешь. Один момент, сейчас всё будет." } } } } },
    [93165] = { d = 21.2, g = 1, v = "skyborne-male", n = { m = 232, f = 232 }, c = { m = { { 0.00, "Ал'акетские сектанты принесли нам страшное горе, и кровь можно смыть только кровью." }, { 5.89, "У меня есть предложение, незнакомец. Если встретишь этих проклятых фанатиков, убей их и принеси мне уши." }, { 12.98, "Я заплачу за них монетой и – когда ты докажешь, что ты настоящий друг – тайными знаниями Когтя Ночи." } }, f = { { 0.00, "Ал'акетские сектанты принесли нам страшное горе, и кровь можно смыть только кровью." }, { 5.89, "У меня есть предложение, незнакомка. Если встретишь этих проклятых фанатиков, убей их и принеси мне уши." }, { 12.79, "Я заплачу за них монетой и – когда ты докажешь, что ты настоящий друг – тайными знаниями Когтя Ночи." } } }, t = { d = 19.9, v = "skyborne-male", n = { x = 214 }, c = { x = { { 0.00, "Превосходно. Уничтожение этих сектантов – безусловное благо." }, { 4.46, "Надеюсь, теперь-то они поймут, что с Когтем Ночи лучше не связываться и память у нас долгая." }, { 11.03, "Полагаю, что у тебя свои счёты с этой сектой, и ты ещё не раз с ними столкнёшься. Если добудешь ещё их уши, неси сюда." } } } } },
    [93172] = { d = 32.5, g = 1, v = "gnome-male", n = { m = 350, f = 350 }, c = { m = { { 0.00, "Большая часть эльфов на острове думает, что в лесу живут призраки – и они не так уж и неправы." }, { 7.37, "В старых руинах на северо-востоке собираются странные духи, похожие на души мертвецов. Иногда по ночам можно услышать их... пение." }, { 16.02, "Это не похоже на наши песни, но это точно пение, и оно... оно такое грустное." }, { 22.05, "Не знаю почему, но думаю, что когда-то там произошло нечто ужасное, и духи томятся в заключении." }, { 28.59, "Если ты смелый, может, попробуешь их освободить?" } }, f = { { 0.00, "Большая часть эльфов на острове думает, что в лесу живут призраки – и они не так уж и неправы." }, { 7.37, "В старых руинах на северо-востоке собираются странные духи, похожие на души мертвецов. Иногда по ночам можно услышать их... пение." }, { 16.02, "Это не похоже на наши песни, но это точно пение, и оно... оно такое грустное." }, { 22.05, "Не знаю почему, но думаю, что когда-то там произошло нечто ужасное, и духи томятся в заключении." }, { 28.59, "Если ты смелая, может, попробуешь их освободить?" } } }, t = { d = 1.9, g = 1, v = "gnome-male", n = { m = 17, f = 17 }, c = { m = { { 0.00, "Спасибо, незнакомец." } }, f = { { 0.00, "Спасибо, незнакомка." } } } } },
    [93317] = { d = 29.2, g = 1, v = "skyborne-female", n = { m = 341, f = 341 }, c = { m = { { 0.00, "Что тебе известно о ветроозёрных крабах?" }, { 2.58, "Они обитают только на озере Песни Ветра, а добывать их можно только раз в год, в течение нескольких недель." }, { 10.06, "Из-за бесчинств культа нам до сих пор не удалось сходить к озеру, а благоприятное время почти на исходе." }, { 17.13, "Я буду тебе очень благодарна, если отловишь немного. Обычно их можно найти на берегу озера или в ближайших реках." }, { 25.08, "Только будь осторожен: эти крабы куда злее, чем кажутся." } }, f = { { 0.00, "Что тебе известно о ветроозёрных крабах?" }, { 2.58, "Они обитают только на озере Песни Ветра, а добывать их можно только раз в год, в течение нескольких недель." }, { 10.06, "Из-за бесчинств культа нам до сих пор не удалось сходить к озеру, а благоприятное время почти на исходе." }, { 17.13, "Я буду тебе очень благодарна, если отловишь немного. Обычно их можно найти на берегу озера или в ближайших реках." }, { 25.08, "Только будь осторожна: эти крабы куда злее, чем кажутся." } } }, t = { d = 5.3, g = 1, v = "skyborne-female", n = { x = 46 }, c = { m = { { 0.00, "Клянусь ветром, до чего чудесное мясо! Огромное спасибо, герой." } }, f = { { 0.00, "Клянусь ветром, до чего чудесное мясо! Огромное спасибо, героиня." } } } } },
    [93318] = { d = 26.4, v = "human-male#114", n = { x = 281 }, c = { x = { { 0.00, "По распоряжению Аонды, констебля миротворцев, назначается награда за голову Вулгары Ненасытного, терроризирующего нагорье." }, { 9.42, "В последний раз его видели на вершине холма к юго-западу от деревни Шен'дар." }, { 15.44, "Эта крылатая бестия чрезвычайно опасна – соблюдайте осторожность." }, { 20.73, "Чтобы получить награду, принесите голову зверя Данарию Воющая Вуаль." } } }, t = { d = 12.3, g = 1, v = "skyborne-male", n = { m = 151, f = 152 }, c = { m = { { 0.00, "Нам хватает хлопот с сектантами и бандитами нагорья – гигантский лисвен, терроризирующий мирных жителей, нам точно не нужен." }, { 8.20, "Ты совершил благородный поступок. Вот обещанная награда." } }, f = { { 0.00, "Нам хватает хлопот с сектантами и бандитами нагорья – гигантский лисвен, терроризирующий мирных жителей, нам точно не нужен." }, { 8.20, "Ты совершила благородный поступок. Вот обещанная награда." } } } } },
    [93319] = { d = 27.6, v = "skyborne-female", n = { x = 317 }, c = { x = { { 0.00, "Ветрокамни – важный ресурс здесь, на Зефрисе, так что мы всегда держим у себя запасы для экстренных случаев." }, { 7.20, "Не так давно я заметила, что некоторая часть наших запасов пропала." }, { 12.00, "Мы нашли ветрокамни у бандитов, которых недавно поймали, – подозреваю, что они-то и стоят за кражей." }, { 19.50, "Если будешь идти мимо пещеры бандитов к северу отсюда, может, расшибешь пару лбов и заберёшь украденные ветрокамни?" } } }, t = { d = 10.8, g = 1, v = "skyborne-female", n = { x = 121 }, c = { m = { { 0.00, "Спасибо, герой. Этого нам пока должно хватить." }, { 3.54, "Но если мы не наладим снабжение в ближайшем будущем, украденные ветрокамни будут меньшей из наших проблем." } }, f = { { 0.00, "Спасибо, героиня. Этого нам пока должно хватить." }, { 3.39, "Но если мы не наладим снабжение в ближайшем будущем, украденные ветрокамни будут меньшей из наших проблем." } } } } },
    [93320] = { d = 33.0, v = "skyborne-female", n = { x = 402 }, c = { x = { { 0.00, "Мне только что сообщили, что сектанты напали на сторожевую башню за городом. К счастью, у нас была пара свободных миротворцев." }, { 8.35, "Я поручила им прорваться через тыл врага и поддержать защитников башни, но любая дополнительная помощь может означать разницу между жизнью и смертью наших бойцов." }, { 19.53, "Прошу, немедленно отправляйся к восточной сторожевой башне и окажи любую возможную помощь." }, { 25.85, "Подкрепление возглавляет Йорана Ветреный Тростник. Если она ещё жива, то подскажет, что нужно сделать." } } }, t = { d = 9.5, v = "skyborne-female", n = { x = 112 }, c = { x = { { 0.00, "Пока что нам удаётся сдерживать врагов, но их больше, чем нас, а наши бойцы начинают уставать." }, { 6.23, "Мы должны пересилить противника, и поскорее." } } } } },
    [93459] = { d = 29.8, v = "skyborne-male", n = { x = 352 }, c = { x = { { 0.00, "Обычно ал'акетские сектанты обходят этот лес за километр – боятся призраков, которые якобы тут живут." }, { 6.68, "Ну, а мы с радостью поддерживаем эти слухи." }, { 9.52, "Друиды моего ордена хотят спокойно жить в Теневейном лесу, и сектанты нам тут не нужны. Многие из нас напуганы." }, { 17.34, "У меня есть предложение. Сразись с сектантами ради нас и принеси их уши." }, { 22.23, "Мы заплатим за каждое ухо деньгами, а когда ты покажешь себя настоящим другом, ещё и тайнами нашего ордена." } } }, t = { d = 2.4, v = "skyborne-male", n = { x = 23 }, c = { x = { { 0.00, "Вот твоя обещанная награда." } } } } },
    [93461] = { d = 32.5, v = "human-male#114", n = { x = 332 }, c = { x = { { 0.00, "На вид ты будто бы из Высшего ордена. Тех, чьи предки были высокорождёнными, всегда выдаёт едва уловимый блеск в глазах." }, { 9.34, "Прежде чем я загружу тебя работой, тебе стоит поговорить со старейшиной Высшего ордена, живущим здесь, – Ратирилом Солнечное Копьё." }, { 19.44, "Ты найдёшь его в главном здании, прямо за углом." }, { 23.47, "Ах да, к Кориэлле Спокойный Бриз тоже загляни – это хозяйка местной таверны, где можно получить кров и припасы." } } }, t = { d = 27.1, g = 1, v = "skyborne-female", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Значит, ты поговорил с Ратирилом? Отлично." }, { 2.81, "Отношения у Высшего ордена и Ваятелей ветра сейчас напряжённые, но здесь, в Шен'даре, они сдерживают свой конфликт в определённых рамках." }, { 11.89, "По крайней мере в деревне. О том, что происходит в степях, знают только ветры." }, { 17.40, "Так, с этим мы закончили... Похоже, ты ищешь себе занятие. У меня есть пара предложений, если ты не прочь немного потрудиться." } }, f = { { 0.00, "Значит, ты поговорила с Ратирилом? Отлично." }, { 3.37, "Отношения у Высшего ордена и Ваятелей ветра сейчас напряжённые, но здесь, в Шен'даре, они сдерживают свой конфликт в определённых рамках." }, { 12.46, "По крайней мере в деревне. О том, что происходит в степях, знают только ветры." }, { 17.96, "Так, с этим мы закончили... Похоже, ты ищешь себе занятие. У меня есть пара предложений, если ты не прочь немного потрудиться." } } } } },
    [93552] = { d = 26.3, v = "skyborne-female#3773", n = { x = 320 }, c = { x = { { 0.00, "Ветрокамень – важнейший ресурс на острове Зефрис, так как он содержит концентрированную энергию ветров." }, { 6.59, "Духи ветра, когда-то жившие здесь с нами, исчезли несколько веков назад, и с тех пор магия, поддерживавшая жизнь на острове, медленно угасает." }, { 15.97, "Ветрокамень – не идеальный, но надёжный источник энергии, так что мы его очень ценим." }, { 21.88, "Куски ветрокамня разбросаны по роще. Поможешь мне собрать их?" } } }, t = { d = 18.2, v = "skyborne-female#3773", n = { x = 222 }, c = { x = { { 0.00, "Спасибо тебе большое. Мы, эльфы, тесно связаны с магией, и эти ветрокамни становятся всё ценнее по мере того как магия, наполняющая наши земли благодаря опорным столпам, продолжает рассеиваться." }, { 12.83, "Но земля богата не только ветрокамнями. Вот, возьми одно из этих руководств." } } } } },
    [93735] = { d = 29.0, v = "skyborne-female", n = { x = 349 }, c = { x = { { 0.00, "Ваятели ветра издавна ухаживали за магическими инструментами и устройствами, подаренными нам духами воздуха." }, { 7.23, "В том числе за множеством магических големов на острове – увы, с тех пор как духи нас покинули, почти все они перестали работать." }, { 16.16, "Один из немногих действующих големов в Валанааре был повреждён. Мы отправили на помощь мастера, но ему может понадобиться помощник." }, { 24.90, "Иди в западную часть города и предложи свои услуги." } } }, t = { d = 17.5, v = "skyborne-female", n = { x = 108 }, c = { x = { { 0.00, "Лицо Рииани скрыто под тяжёлыми пластинами голема – мастер пытается что-то делать с механизмом внутри. Он не замечает вас." }, { 8.35, "Проклятие бури, где ядро? Кто такой умный догадался вытащить ещё и гирозефир?" }, { 13.50, "Чудо, что ветра голема ещё не рассеялись окончательно!" } } } } },
    [93736] = { d = 29.0, g = 1, v = "skyborne-female", n = { m = 339, f = 341 }, c = { m = { { 0.00, "Главный вопрос, который занимает Ваятелей ветра: почему духи нас покинули и что мы можем сделать, чтобы их вернуть." }, { 7.62, "Одной характерной особенностью Теневейного леса стало появление необычных духов, которых прозвали мертвенями." }, { 15.65, "Мы мало что о них знаем, кто они и откуда взялись, но они начали появляться после ухода духов ветра." }, { 22.74, "Я хочу, чтобы ты отправился туда и рассеял этих духов. Собери их останки и принеси сюда." } }, f = { { 0.00, "Главный вопрос, который занимает Ваятелей ветра: почему духи нас покинули и что мы можем сделать, чтобы их вернуть." }, { 7.62, "Одной характерной особенностью Теневейного леса стало появление необычных духов, которых прозвали мертвенями." }, { 15.65, "Мы мало что о них знаем, кто они и откуда взялись, но они начали появляться после ухода духов ветра." }, { 22.74, "Я хочу, чтобы ты отправилась туда и рассеяла этих духов. Собери их останки и принеси сюда." } } }, t = { d = 16.0, v = "skyborne-female", n = { x = 170 }, c = { x = { { 0.00, "Эти сущности переполняют меня чувством... глубокой тревоги. Я почти физически ощущаю их ауру, смесь злости и сожаления." }, { 7.88, "Иногда кажется, что я начинаю терять сознание. Эндария содрогается." }, { 12.74, "Надеюсь, мне не придётся больше их изучать." } } } } },
    [93737] = { d = 14.5, v = "skyborne-male", n = { x = 155 }, c = { x = { { 0.00, "О, привет. Айесса прислала тебя помочь мне? Ну, хорошо." }, { 4.45, "Не знаю, что тут может сделать новичок вроде тебя, но дай я вытащу голову из нутра голема – у меня есть пара мыслей, что ещё тебе можно поручить." } } }, t = { d = 15.6, g = 1, v = "skyborne-male", n = { m = 175, f = 177 }, c = { m = { { 0.00, "Спасибо, что принёс материалы. Догадываюсь, что кое-что было не так-то просто достать." }, { 6.15, "С этими деталями я могу снова запустить голема." }, { 9.40, "Будем надеяться, что его память не пострадала, и он скажет нам, кто забрал его части." } }, f = { { 0.00, "Спасибо, что принесла материалы. Догадываюсь, что кое-что было не так-то просто достать." }, { 6.34, "С этими деталями я могу снова запустить голема." }, { 9.59, "Будем надеяться, что его память не пострадала, и он скажет нам, кто забрал его части." } } } } },
    [93738] = { d = 31.3, v = "skyborne-male", n = { x = 350 }, c = { x = { { 0.00, "Яркая Мечта? Значит, Высший орден решил изъять эти компоненты. Но для чего, с какой целью?" }, { 6.95, "Орден всегда лез в наши дела, им было интересно поэкспериментировать с магией духов ветра." }, { 12.94, "Смелость на грани глупости, мы категорически запретили им посягать на тайны Ваятелей ветра, – но в последнее время они снова начали испытывать наше терпение." }, { 23.70, "Думаю, тебе стоит рассказать об этом Айессе Певице Рассвета. Она скажет, что делать дальше." } } }, t = { d = 21.5, v = "skyborne-female", n = { x = 214 }, c = { x = { { 0.00, "Очень интересно. Значит, это Высший орден виноват в том, что голем вышел из строя?" }, { 7.49, "Я знаю Белатаана. Он двоюродный брат Валеннии Штормовой Кулак, а его мать, между прочим, была из Ваятелей ветра." }, { 16.39, "Печально, что он оказался в этом замешан. Мне нужно немного это обдумать." } } } } },
    [93739] = { d = 22.9, g = 1, v = "orc-male", n = { m = 256, f = 257 }, c = { m = { { 0.00, "Азерот – огромный мир, и владения Орды обширны." }, { 3.40, "В каждом из наших городов – Подгороде, Оргриммаре и Громовом Утёсе – обитают разные народы с уникальной культурой." }, { 11.65, "Если ты хочешь быть гостем Орды здесь, на Азероте, тебе будет полезно по очереди посетить каждую из наших столиц." }, { 19.74, "Мой советник Назгрел укажет тебе дорогу." } }, f = { { 0.00, "Азерот – огромный мир, и владения Орды обширны." }, { 3.40, "В каждом из наших городов – Подгороде, Оргриммаре и Громовом Утёсе – обитают разные народы с уникальной культурой." }, { 11.65, "Если ты хочешь быть гостьей Орды здесь, на Азероте, тебе будет полезно по очереди посетить каждую из наших столиц." }, { 19.68, "Мой советник Назгрел укажет тебе дорогу." } } } },
    [93740] = { d = 24.3, v = "skyborne-female", n = { x = 286 }, c = { x = { { 0.00, "Этим утром на нагорье нашли несколько тел молодых Ваятелей ветра." }, { 4.43, "Мы не знаем точно, но с большой вероятностью за этим стоят ал'акетские сектанты." }, { 9.67, "Ваятели ветра всегда готовы пролить кровь за кровь." }, { 13.51, "Иди на север и убей всех ал'акетов, которых увидишь. Принеси мне их ветрокаменные молитвенные талисманы в знак победы." }, { 21.35, "Мы не прощаем и не забываем обид." } } }, t = { d = 15.1, v = "skyborne-female", n = { x = 90 }, c = { x = { { 0.00, "Айесса выглядит потрясённой и без всякого выражения смотрит на протянутые ей ветрокаменные талисманы." }, { 7.23, "Не обращай на меня внимания. Просто сегодня был... тяжёлый день. Спасибо за всё, что ты делаешь для Ваятелей ветра." } } } } },
    [93746] = { d = 27.4, v = "skyborne-female", n = { x = 327 }, c = { x = { { 0.00, "Высший орден предупреждали о том, что будет, если лезть в дела Ваятелей ветра." }, { 5.12, "Думаю, надо показательно наказать Белатаана и вернуть в орден – понаставив синяков и научив уважать наши правила." }, { 12.80, "Его видели, когда он выходил из города и направлялся на север в святилище Акира." }, { 18.06, "Не знаю, что ему там нужно, но безопаснее всего будет перехватить его по пути, когда он будет один. Отыщи его и припугни как следует." } } }, t = { d = 28.0, g = 1, v = "skyborne-female", n = { m = 275, f = 277 }, c = { m = { { 0.00, "Что-что? Белатаан... мёртв?" }, { 1.92, "Айесса слушает ваш рассказ о произошедшем." }, { 5.46, "Высший орден вёл мирные переговоры с сектой Ал'акета? С ними невозможно договориться, это фанатичные убийцы." }, { 12.63, "О чём Элаадрин только думал, посылая к ним Белатаана одного?" }, { 18.04, "Не принимай близко к сердцу. Ты не виноват, это всё из-за высокомерия ордена... опять." }, { 23.47, "А ты просто оказался в правильном месте в неправильное время." } }, f = { { 0.00, "Что-что? Белатаан... мёртв?" }, { 1.92, "Айесса слушает ваш рассказ о произошедшем." }, { 5.46, "Высший орден вёл мирные переговоры с сектой Ал'акета? С ними невозможно договориться, это фанатичные убийцы." }, { 12.63, "О чём Элаадрин только думал, посылая к ним Белатаана одного?" }, { 18.04, "Не принимай близко к сердцу. Ты не виновата, это всё из-за высокомерия ордена... опять." }, { 23.57, "А ты просто оказалась в правильном месте в неправильное время." } } } } },
    [93791] = { d = 23.1, g = 1, v = "skyborne-male", n = { m = 279, f = 280 }, c = { m = { { 0.00, "Ты определённо поднаторел в магии, и пришло время последовать одной из старейших традиций Высшего ордена для молодых и начинающих магов." }, { 9.16, "Пора тебе изготовить собственное средоточие заклинаний." }, { 13.16, "Найди Беланна Древо Ветров в Валанааре." }, { 15.85, "Он уже больше века изготавливает посохи и жезлы для Высшего ордена – лучшего наставника и не сыщешь." } }, f = { { 0.00, "Ты определённо поднаторела в магии, и пришло время последовать одной из старейших традиций Высшего ордена для молодых и начинающих магов." }, { 9.23, "Пора тебе изготовить собственное средоточие заклинаний." }, { 13.23, "Найди Беланна Древо Ветров в Валанааре." }, { 15.93, "Он уже больше века изготавливает посохи и жезлы для Высшего ордена – лучшего наставника и не сыщешь." } } }, t = { d = 11.3, v = "skyborne-male", n = { x = 128 }, c = { x = { { 0.00, "А ты, должно быть? Отрадно видеть молодых магов, неравнодушных к нашей истории и обычаям." }, { 6.35, "Идём, я тебе объясню, что надо делать, чтобы создать фокус заклинания." } } } } },
    [93797] = { d = 33.0, v = "skyborne-male", n = { x = 398 }, c = { x = { { 0.00, "У нас есть давняя традиция: когда молодые маги достигают определённого уровня мастерства, они создают собственный фокус заклинаний." }, { 8.97, "Обычно мы берём для этого упавшую ветвь одного из старейших деревьев, поскольку в них ещё осталась энергия стихии ветра." }, { 17.41, "Я обнаружил, что лучшие образцы можно найти у святилища ветра, что к югу от деревни Фалаат." }, { 23.52, "Отправляйся туда и принеси мне большую ветвь, а пока будем создавать твой фокус заклинаний, я расскажу тебе ещё больше о наших традициях." } } }, t = { d = 17.5, g = 1, v = "skyborne-male", n = { x = 193 }, c = { m = { { 0.00, "Спасибо. Я и правда чувствую в этой ветви энергии стихии, которые ждут, чтобы их обуздал тот, кто наделён даром." }, { 7.51, "Из неё получится превосходный фокус заклинаний." }, { 10.98, "Скажи, эта ветвь, случаем, не пела тебе? Часто бывает, что выбор делает ветвь, а не герой." } }, f = { { 0.00, "Спасибо. Я и правда чувствую в этой ветви энергии стихии, которые ждут, чтобы их обуздал тот, кто наделён даром." }, { 7.51, "Из неё получится превосходный фокус заклинаний." }, { 10.98, "Скажи, эта ветвь, случаем, не пела тебе? Часто бывает, что выбор делает ветвь, а не героиня." } } } } },
    [93835] = { d = 25.6, g = 1, v = "skyborne-female", n = { x = 264 }, c = { m = { { 0.00, "Лортуна сбежала к вершинам через какой-то портал. Айесса и Элаадрин последовали за ней. Всё произошло пару мгновений назад." }, { 10.17, "Боюсь, мне слишком досталось, чтобы продолжать. Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 17.96, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть. Удачи тебе, герой." } }, f = { { 0.00, "Лортуна сбежала к вершинам через какой-то портал. Айесса и Элаадрин последовали за ней. Всё произошло пару мгновений назад." }, { 10.17, "Боюсь, мне слишком досталось, чтобы продолжать. Пройди через портал, найди Элаадрина и помоги остановить Лортуну." }, { 17.96, "Элаадрин и Айесса послали за подкреплением, но оно может к вам не успеть. Удачи тебе, героиня." } } }, t = { d = 25.8, v = "skyborne-male", n = { x = 302 }, c = { x = { { 0.00, "Я отправил нескольких оставшихся у нас магов, чтобы Валенния и её бойцы тоже смогли выбраться." }, { 7.01, "Сейчас она должна отдыхать в доме верховного старейшины Песня Теней." }, { 11.97, "Ансирему пришлось вернуться на Азерот, но перед отбытием мы с ним обсудили дальнейшие шаги Высшего ордена." }, { 18.93, "Этот день мы пережили, но теперь Зефрис опасно уязвим, и нам нужно готовиться к тому, что грядёт." } } } } },
    [93836] = { d = 27.7, v = "skyborne-female", n = { x = 328 }, c = { x = { { 0.00, "Мулн рассказал мне про повелителей элементалей, и я боюсь, что у нас есть все основания бояться Ал'акира." }, { 6.77, "Без оберегов, которые скрывали Зефрис от его взора, мы совершенно беззащитны." }, { 11.97, "И если он нападёт на нас здесь, в его владениях, мы обречены." }, { 16.44, "Надо сообщить верховному старейшине Песня Теней об этой угрозе и, что ещё важнее, о нашем плане отправиться на Азерот." }, { 24.42, "Клянусь, мы придумаем, как защитить наш дом!" } } }, t = { d = 30.3, v = "skyborne-male", n = { x = 246 }, c = { x = { { 0.00, "Талаанис Песня Теней внимательно слушает ваш рассказ о том, что произошло над святилищем Акира, и план Айессы покинуть остров Зефрис." }, { 9.33, "Мне надо обдумать это всё. Что хорошо – мы избавились от Лортуны и обезглавили секту." }, { 14.97, "В наш дом ещё никто не вторгся, и, зная повелителей элементалей, могут пройти ещё многие годы и даже десятилетия, прежде чем Ал'акир наконец обратит на нас внимание." }, { 26.19, "Нам есть чего бояться, но также есть и повод для радости." } } } } },
    [93926] = { d = 25.9, v = "skyborne-female", n = { x = 306 }, c = { x = { { 0.00, "Какой бы ни была причина нападения на башню, она не стоит жизней наших бойцов." }, { 5.64, "Отправляйся на юго-запад и найди её. Скажи размещённым там миротворцам, чтобы возвращались в деревню." }, { 12.34, "Эта башня не стоит того, чтобы за неё умирать, – лучше собрать всех бойцов здесь для защиты мирных жителей." }, { 19.72, "Там командует миротворец Вааниэл; пусть направляется сюда как можно скорее. Поторопись!" } } }, t = { d = 9.1, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "Труп достаточно свежий – смерть настигла несчастного недавно." }, { 3.94, "Судя по ожогам на коже, это дело рук сектантов, владеющих магией бури." } } } } },
    [93927] = { d = 9.3, v = "skyborne-male", n = { x = 0 }, c = { x = { { 0.00, "Когда вы осматриваете тело миротворца, из его рук выпадает окровавленная записка." }, { 5.55, "Возможно, прочитав её, вы поймёте, что делать дальше." } } }, t = { d = 28.4, v = "skyborne-female", n = { x = 323 }, c = { x = { { 0.00, "Значит, все они мертвы. Да разразит буря этих проклятых сектантов!" }, { 4.85, "Хотя тебе удалось избавиться от жреца и остановить их в башне, должна признать, что теперь меня ещё сильнее беспокоят твои слова об их махинациях со столпом." }, { 15.24, "У них был огромный запас ветрокамней, а значит, им требовалось колоссальное количество энергии." }, { 21.88, "Какова же их цель? Ритуал со столпом, нападение на деревню... Для чего всё это?" } } } } },
    [93928] = { d = 3.2, v = "human-male#114", n = { x = 27 }, c = { x = { { 0.00, "Мне нужно печенье, смекаешь? Хи-хи!" } } }, t = { d = 1.2, v = "dwarf-male", n = { x = 9 }, c = { x = { { 0.00, "(PH) Спасибо!" } } } } },
    [93948] = { d = 29.9, v = "skyborne-female", n = { x = 339 }, c = { x = { { 0.00, "Раз ты всё равно собираешься в Валанаар, доставь перстень, найденный в башне, Талаанису Песня Теней." }, { 8.23, "Он наверняка пожелает сохранить эту вещь у себя, и уж точно ему стоит узнать о судьбе племянника." }, { 15.37, "Талаанис – верховный старейшина на острове Зефрис. Он справедливый лидер, любимый своим народом даже в эти трудные времена." }, { 23.54, "Мне больно думать о том, как старейшина воспримет эту весть. Передай ему мои соболезнования." } } }, t = { d = 20.3, g = 1, v = "skyborne-male", n = { m = 235, f = 237 }, c = { m = { { 0.00, "Какая ужасная новость... Мой племянник мёртв. Спасибо, что принёс этот перстень." }, { 5.61, "Нечасто такие молодые и способные шен'дорай заглядывают к нам с нагорий." }, { 10.87, "Если тебе нужна работа, поговори с Валеннией Штормовой Кулак, капитаном миротворцев в Валанааре. Нам сейчас пригодится любая помощь." } }, f = { { 0.00, "Какая ужасная новость... Мой племянник мёртв. Спасибо, что принесла этот перстень." }, { 5.82, "Нечасто такие молодые и способные шен'дорай заглядывают к нам с нагорий." }, { 11.09, "Если тебе нужна работа, поговори с Валеннией Штормовой Кулак, капитаном миротворцев в Валанааре. Нам сейчас пригодится любая помощь." } } } } },
    [93949] = { d = 30.1, v = "skyborne-female", n = { x = 346 }, c = { x = { { 0.00, "Кругом эти насекомые." }, { 2.02, "В низинах сезон небопрыгов, и эти назойливые существа повсюду." }, { 6.19, "Один из магов Высшего ордена доложил, что на одном из убитых ими небопрыгов были некие чары." }, { 13.54, "Изучив их, мы обнаружили, что это какое-то подслушивающее заклинание." }, { 18.45, "Мы полагаем, что секта использует зачарованных насекомых для разведки. Истреби их." }, { 23.81, "На вид зачарованные насекомые не отличаются от обычных, поэтому тебе придётся убить всех." } } }, t = { d = 10.2, v = "skyborne-female", n = { x = 122 }, c = { x = { { 0.00, "Я не сомневаюсь, что в Валанааре их ещё много, но с каждым зачарованным небопрыгом, которого мы растоптали, наш город становится немного безопаснее." } } } } },
    [93951] = { d = 28.6, v = "skyborne-female", n = { x = 326 }, c = { x = { { 0.00, "Гиппогрифы, поселившиеся на юго-западе деревни, иногда нам досаждают, но зато теперь мы можем легко добывать их перья." }, { 7.85, "Многие небеснорождённые любят украшать волосы яркими перьями, а у гиппогрифов пуховые перья очень яркие и, что ещё важнее, мягкие как шёлк." }, { 19.15, "Если будешь там, собери как можно больше выпавших перьев в гнездовье гиппогрифов и рядом." }, { 25.07, "Но осторожнее: дикие гиппогрифы не любят гостей." } } }, t = { d = 19.7, g = 1, v = "skyborne-female", n = { m = 232, f = 234 }, c = { m = { { 0.00, "Украшения для волос могут показаться показным излишеством. Однако даже в такие времена нужно позволять себе маленькие радости." }, { 8.94, "Если моё творение принесёт кому-то радость, то день пройдёт не зря." }, { 13.46, "Спасибо, что принёс мне эти перья – с твоей помощью я смогу порадовать жителей Зефриса." } }, f = { { 0.00, "Украшения для волос могут показаться показным излишеством. Однако даже в такие времена нужно позволять себе маленькие радости." }, { 8.94, "Если моё творение принесёт кому-то радость, то день пройдёт не зря." }, { 13.46, "Спасибо, что принесла мне эти перья – с твоей помощью я смогу порадовать жителей Зефриса." } } } } },
    [93958] = { d = 14.8, v = "skyborne-female", n = { x = 174 }, c = { x = { { 0.00, "Войска Валеннии прорвались в святая святых врага. Поначалу там шла ожесточённая борьба, но теперь стало... неожиданно тихо." }, { 8.15, "Пробейся к Валеннии и её бойцам... если там ещё кто-то остался. А я буду прикрывать тебя здесь." } } }, t = { d = 2.2, v = "skyborne-female", n = { x = 0 }, c = { x = { { 0.00, "Валенния серьёзно ранена." } } } } },
    [93963] = { d = 21.8, v = "human-male", n = { x = 251 }, c = { x = { { 0.00, "В каждом из наших городов – Штормграде, Стальгорне и Дарнасе – обитают разные народы с уникальной культурой." }, { 7.34, "Раз уж ты в гостях у Альянса здесь, на Азероте, выдели время для того, чтобы по очереди посетить каждую из наших столиц." }, { 15.88, "Для начала поговори с Рандалом Эмерсоном в южном вестибюле – он укажет тебе дорогу." } } }, t = { d = 32.2, g = 1, v = "human-male", n = { m = 366, f = 367 }, c = { m = { { 0.00, "А, ты вернулся!" }, { 1.54, "Надеюсь, странствия дали тебе представление о том, как велик и удивителен наш мир." }, { 7.27, "Понимаю, от всего этого голова идёт кругом, но если ты хочешь помочь своему народу, нужно быть готовым ко всему, что может ждать тебя на Азероте." }, { 17.71, "Пока твой орден обустраивается в Даларане, советую обратить внимание на земли вокруг Штормграда." }, { 24.29, "Западному краю, к примеру, всегда пригодятся сильные искатели приключений – если ты, конечно, не против помочь." } }, f = { { 0.00, "А, ты вернулась!" }, { 1.64, "Надеюсь, странствия дали тебе представление о том, как велик и удивителен наш мир." }, { 7.38, "Понимаю, от всего этого голова идёт кругом, но если ты хочешь помочь своему народу, нужно быть готовой ко всему, что может ждать тебя на Азероте." }, { 17.83, "Пока твой орден обустраивается в Даларане, советую обратить внимание на земли вокруг Штормграда." }, { 24.42, "Западному краю, к примеру, всегда пригодятся сильные искатели приключений – если ты, конечно, не против помочь." } } } } },
    [94003] = { d = 33.5, v = "skyborne-female#3773", n = { x = 365 }, c = { x = { { 0.00, "Я последняя из Небовержцев острова Зефрис. Всех остальных убили ал'акетские фанатики." }, { 6.10, "И единственное, что давит на меня тяжелее, чем чувство вины, это стыд: реликвия моей семьи, щит Бастион Небовержца, попал в руки сектанта по имени Заал Щит Бури." }, { 17.59, "Наше семейное предание гласит, что достойный обладатель этого щита непобедим." }, { 23.33, "Заал недостоин, я в этом уверена. Найди его в святилище Акира и отбери мой щит. Сделай это, и я обучу тебя защите Небовержцев." } } }, t = { d = 25.1, g = 1, v = "skyborne-female#3773", n = { m = 278, f = 280 }, c = { m = { { 0.00, "Ты сделал то, чего не смогла я, и вернул честь моей семье." }, { 3.83, "За это я одарю тебя тем, чего на Зефрисе удостаиваются немногие: я открою тебе секреты защиты Небовержца." }, { 11.84, "Кроме того, чтобы применить на деле то, чему я тебя научу, тебе понадобится щит. Прошу, возьми этот." }, { 18.97, "Теперь, когда бастион Небовержца вернулся ко мне, он мне ни к чему. Бану'Адораа, друг мой." } }, f = { { 0.00, "Ты сделала то, чего не смогла я, и вернула честь моей семье." }, { 3.87, "За это я одарю тебя тем, чего на Зефрисе удостаиваются немногие: я открою тебе секреты защиты Небовержца." }, { 11.87, "Кроме того, чтобы применить на деле то, чему я тебя научу, тебе понадобится щит. Прошу, возьми этот." }, { 19.01, "Теперь, когда бастион Небовержца вернулся ко мне, он мне ни к чему. Бану'Адораа, друг мой." } } } } },
    [94004] = { d = 16.8, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций эликсира силы огра, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.24, "Снизу указано, что этот заказ можно передавать другим." } } } },
    [94006] = { d = 28.3, g = 1, v = "skyborne-male", n = { m = 337, f = 338 }, c = { m = { { 0.00, "Привет. Ты достаточно продвинулся по пути друида, и я думаю, что тебе пора встретиться с одним из великих духов Зефриса." }, { 8.11, "Урс'ендрис – благородный мудрый дух, научивший много поколений друидов принимать облик медверы." }, { 14.45, "К несчастью, его владения начали рассыпаться и рушиться в небо, как и многие другие области Зефриса." }, { 21.39, "Ищи его на северо-востоке отсюда у водопада, в тени святилища Акира. Он скажет, что делать дальше." } }, f = { { 0.00, "Привет. Ты достаточно продвинулась по пути друида, и я думаю, что тебе пора встретиться с одним из великих духов Зефриса." }, { 8.06, "Урс'ендрис – благородный мудрый дух, научивший много поколений друидов принимать облик медверы." }, { 14.40, "К несчастью, его владения начали рассыпаться и рушиться в небо, как и многие другие области Зефриса." }, { 21.34, "Ищи его на северо-востоке отсюда у водопада, в тени святилища Акира. Он скажет, что делать дальше." } } }, t = { d = 5.1, v = "tauren-female", n = { x = 46 }, c = { x = { { 0.00, "Итак, ты хочешь пойти по пути когтя, дитя? Давай поговорим." } } } } },
    [94007] = { d = 17.8, g = 1, v = "skyborne-female", n = { m = 205, f = 206 }, c = { m = { { 0.00, "Теперь, когда ты достаточно освоился на нагорьях, думаю, самое время тебе обзавестись своим собственным питомцем." }, { 7.78, "Ступай в порт Валанаар, что к юго-востоку отсюда, и там поговори с Кве'ланой Быстрым Порывом." }, { 14.61, "Он обучит тебя искусству укрощения зверей." } }, f = { { 0.00, "Теперь, когда ты достаточно освоилась на нагорьях, думаю, самое время тебе обзавестись своим собственным питомцем." }, { 7.93, "Ступай в порт Валанаар, что к юго-востоку отсюда, и там поговори с Кве'ланой Быстрым Порывом." }, { 14.76, "Он обучит тебя искусству укрощения зверей." } } }, t = { d = 3.3, g = 1, v = "skyborne-male", n = { m = 33, f = 33 }, c = { m = { { 0.00, "Я очень рад, что ты пришёл. Идём, приступим." } }, f = { { 0.00, "Я очень рад, что ты пришла. Идём, приступим." } } } } },
    [94013] = { d = 23.0, g = 1, v = "skyborne-male", n = { m = 261, f = 264 }, c = { m = { { 0.00, "Ты вернулся с победой, приручив двух зверей, и готов к последнему шагу. Ветра Зефриса шепчут о новых сложных испытаниях." }, { 8.33, "Возьми хлыст приручения и отправляйся на Шен'дарское нагорье. Там покажи своё мастерство, приручив лисвена-вожака." }, { 17.13, "После этого урока ты будешь готов изучать самые сокровенные секреты охотников." } }, f = { { 0.00, "Ты вернулась с победой, приручив двух зверей, и готова к последнему шагу. Ветра Зефриса шепчут о новых сложных испытаниях." }, { 8.47, "Возьми хлыст приручения и отправляйся на Шен'дарское нагорье. Там покажи своё мастерство, приручив лисвена-вожака." }, { 17.26, "После этого урока ты будешь готова изучать самые сокровенные секреты охотников." } } }, t = { d = 15.5, g = 1, v = "skyborne-male", n = { m = 167, f = 167 }, c = { m = { { 0.00, "Превосходно! Ты схватываешь на лёту." }, { 2.81, "Теперь, когда ты знаешь основы, я могу научить тебя, как создать прочную связь со своим зверем." }, { 9.51, "Ступай с этим знанием и процветай. Стань тем, в ком нуждается остров Зефрис, герой." } }, f = { { 0.00, "Превосходно! Ты схватываешь на лёту." }, { 2.81, "Теперь, когда ты знаешь основы, я могу научить тебя, как создать прочную связь со своим зверем." }, { 9.51, "Ступай с этим знанием и процветай. Стань той, в ком нуждается остров Зефрис, героиня." } } } } },
    [94050] = { d = 13.2, g = 1, v = "skyborne-male", n = { m = 151, f = 151 }, c = { m = { { 0.00, "У тебя достаточно сил, чтобы приручить зверя, теперь надо научиться его дрессировать." }, { 5.72, "Поговори с моей сестрой Кель'дорой – она расскажет тебе, как обучать питомцев. Ступай с ветром, юный герой." } }, f = { { 0.00, "У тебя достаточно сил, чтобы приручить зверя, теперь надо научиться его дрессировать." }, { 5.72, "Поговори с моей сестрой Кель'дорой – она расскажет тебе, как обучать питомцев. Ступай с ветром, юная героиня." } } }, t = { d = 24.9, g = 1, v = "skyborne-female", n = { m = 270, f = 270 }, c = { m = { { 0.00, "Вижу, начинающий герой. Да, я могу обучить тебя навыкам, которые нужны, чтобы дрессировать и направлять питомца." }, { 7.23, "Ты сможешь не только обучать его новым способностям, но и кормить, а также воскрешать, если он падёт в бою." }, { 16.11, "Помни: всегда чти равновесие и с благоговением относись к природе вокруг тебя. А теперь ступай. Мы ещё поговорим, но позже." } }, f = { { 0.00, "Вижу, начинающая героиня. Да, я могу обучить тебя навыкам, которые нужны, чтобы дрессировать и направлять питомца." }, { 7.59, "Ты сможешь не только обучать его новым способностям, но и кормить, а также воскрешать, если он падёт в бою." }, { 16.47, "Помни: всегда чти равновесие и с благоговением относись к природе вокруг тебя. А теперь ступай. Мы ещё поговорим, но позже." } } } } },
    [94212] = { d = 16.8, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций эликсира мудрости, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.20, "Снизу указано, что этот заказ можно передавать другим." } } }, t = { d = 23.8, g = 1, v = "skyborne-male", n = { x = 270 }, c = { m = { { 0.00, "Признаюсь, я ожидал, что коварные ветра нагорья разорвут это письмо в клочья." }, { 5.03, "И представить не мог, что кто-то увидит мою скромную просьбу, а тем более доставит заказ прямо мне в руки." }, { 12.48, "Твоё усердие достойно похвалы, путник. Этот эликсир поможет мне в медитации." }, { 18.01, "Можешь остаться и поделиться парой историй о своих странствиях. Я рад компании." } }, f = { { 0.00, "Признаюсь, я ожидал, что коварные ветра нагорья разорвут это письмо в клочья." }, { 5.03, "И представить не мог, что кто-то увидит мою скромную просьбу, а тем более доставит заказ прямо мне в руки." }, { 12.48, "Твоё усердие достойно похвалы, путница. Этот эликсир поможет мне в медитации." }, { 18.13, "Можешь остаться и поделиться парой историй о своих странствиях. Я рад компании." } } } } },
    [94213] = { d = 16.8, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций малого зелья маны, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.26, "Снизу указано, что этот заказ можно передавать другим." } } }, t = { d = 17.1, v = "skyborne-female", n = { x = 152 }, c = { x = { { 0.00, "А, это зелье, которое я заказывала?" }, { 2.82, "Эльфийка почтительно берёт у вас флакон." }, { 6.02, "Ты как раз вовремя, и твою щедрость я глубоко ценю. Принимаю это и предлагаю взамен небольшой знак благодарности." }, { 13.91, "Спасибо, и, быть может, мы ещё встретимся." } } } } },
    [94214] = { d = 17.8, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций зелья защиты от тёмной магии, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 13.22, "Снизу указано, что этот заказ можно передавать другим." } } } },
    [94215] = { d = 17.1, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций зелья свободы действий, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.50, "Снизу указано, что этот заказ можно передавать другим." } } }, t = { d = 22.7, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Вы не мешкая предлагаете извивающейся массе заказанное зелье свободы действий." }, { 6.15, "Она, похоже, либо не замечает вас, либо не может забрать предмет." }, { 11.54, "Рядом с коконом рассыпана горстка монет. Вы можете оставить зелье здесь и забрать монеты себе." }, { 18.86, "Природа, надо думать, сама во всём разберётся." } } } } },
    [94216] = { d = 17.1, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций малого эликсира ловкости, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.54, "Снизу указано, что этот заказ можно передавать другим." } } }, t = { d = 29.8, v = "goblin-male", n = { x = 292 }, c = { x = { { 0.00, "Зиз продолжает говорить приглушённым голосом." }, { 3.59, "Я не собираюсь рассказывать тебе всю историю о том, как оказался на этом месте, но вот тебе совет." }, { 10.80, "Иногда, чтобы произвести впечатление на нового начальника, достаточно присвоить чужую работу." }, { 17.34, "Так что ты отдаёшь мне эликсир, а я расскажу, сколько крови, пота и слёз пролил, пока его варил." }, { 24.36, "Это новая работа, ясно? Мне нужно произвести хорошее первое впечатление!" } } } } },
    [94217] = { d = 17.6, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций малого эликсира тролльей крови, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 13.05, "Снизу указано, что этот заказ можно передавать другим." } } }, t = { d = 15.7, v = "human-male#114", n = { x = 157 }, c = { x = { { 0.00, "Именно то, что заказывал Коротышка Джон Мифрил!" }, { 4.10, "Вот твои монеты. На твоём месте я бы прижимал их к груди покрепче, пока будешь выбираться отсюда, – бойцы арены жаждут богатств не меньше, чем крови!" } } } } },
    [94218] = { d = 16.7, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на порции:порций эликсира защиты, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.09, "Снизу указано, что этот заказ можно передавать другим." } } } },
