    [94359] = { d = 16.9, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на жилета:жилетов из призрачной ткани, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 12.33, "Снизу указано, что этот заказ можно передавать другим." } } } },
    [94360] = { d = 15.5, v = "human-male#114", c = { x = { { 0.00, "В записке, написанной выцветшими чернилами, содержится заказ на сумы:сум души, а также сведения о том, куда всё нужно доставить, и об оплате." }, { 10.94, "Снизу указано, что этот заказ можно передавать другим." } } } },
    [94369] = { d = 29.0, v = "skyborne-male", n = { x = 337 }, c = { x = { { 0.00, "Ансирем рассказал мне про повелителей элементалей, и я боюсь, что у нас есть все основания бояться Ал'акира, раз обереги, которые скрывали Зефрис, больше не действуют." }, { 11.96, "И если Владыка Ветра нападёт на нас, в его владениях мы будем совершенно беззащитны." }, { 17.90, "Надо сообщить верховному старейшине Песня Теней об этой угрозе и, что ещё важнее, о нашем плане отправиться на Азерот." }, { 25.72, "Клянусь, мы придумаем, как защитить наш дом!" } } }, t = { d = 32.9, v = "skyborne-male", n = { x = 246 }, c = { x = { { 0.00, "Талаанис Песня Теней внимательно слушает ваш рассказ о том, что произошло над святилищем Акира, и план Элаадрина покинуть остров Зефрис." }, { 11.96, "Мне надо обдумать это всё. Что хорошо – мы избавились от Лортуны и обезглавили секту." }, { 17.60, "В наш дом ещё никто не вторгся, и, зная повелителей элементалей, могут пройти ещё многие годы и даже десятилетия, прежде чем Ал'акир наконец обратит на нас внимание." }, { 28.82, "Нам есть чего бояться, но также есть и повод для радости." } } } } },
    [94373] = { d = 37.5, g = 1, v = "dwarf-male", n = { m = 427, f = 430 }, c = { m = { { 0.00, "Время пришло, юный шаман. Ты стал крепким и твёрдым, как камень у нас под ногами." }, { 5.63, "То, что ты выбрал путь шамана, показывает, что в тебе есть мудрость гор, хотя ты ещё и не доказал свою силу." }, { 12.87, "Я чувствую в тебе непоколебимость камня, которая позволит идти путём Земли." }, { 18.38, "Но чтобы заслужить её благосклонность, нужно сперва встретиться к ней лицом к лицу." }, { 24.14, "В пещере к югу отсюда живут тролли из племени Мерзлогривов." }, { 28.61, "Принеси мне две подвески, сделанные из когтей медведей-ледокогтей, которые они носят. Тогда мы поговорим о твоём будущем." } }, f = { { 0.00, "Время пришло, юный шаман. Ты стала крепкой и твёрдой, как камень у нас под ногами." }, { 5.65, "То, что ты выбрала путь шамана, показывает, что в тебе есть мудрость гор, хотя ты ещё и не доказала свою силу." }, { 13.22, "Я чувствую в тебе непоколебимость камня, которая позволит идти путём Земли." }, { 18.73, "Но чтобы заслужить её благосклонность, нужно сперва встретиться к ней лицом к лицу." }, { 24.49, "В пещере к югу отсюда живут тролли из племени Мерзлогривов." }, { 28.96, "Принеси мне две подвески, сделанные из когтей медведей-ледокогтей, которые они носят. Тогда мы поговорим о твоём будущем." } } }, t = { d = 27.6, g = 1, v = "dwarf-male", n = { m = 306, f = 310 }, c = { m = { { 0.00, "Прекрасно, друг мой. Ты отлично себя показал. Земля – фундамент всего. Это сила, выносливость, терпение." }, { 7.67, "Она защитит тебя, но только если ты будешь относиться к ней с уважением." }, { 12.73, "Даже камень может сдвинуться, если обращаться с ним неосторожно. Изучи её путь, и ты станешь мудрее большинства. Никогда не забывай её секретов." }, { 22.83, "Я приготовлю тебе сапту. Прими её и встань на истинный путь." } }, f = { { 0.00, "Прекрасно, подруга моя. Ты отлично себя показала. Земля – фундамент всего. Это сила, выносливость, терпение." }, { 7.21, "Она защитит тебя, но только если ты будешь относиться к ней с уважением." }, { 12.27, "Даже камень может сдвинуться, если обращаться с ним неосторожно. Изучи её путь, и ты станешь мудрее большинства. Никогда не забывай её секретов." }, { 22.37, "Я приготовлю тебе сапту. Прими её и встань на истинный путь." } } } } },
    [94374] = { d = 27.9, v = "dwarf-male", n = { x = 306 }, c = { x = { { 0.00, "Сапта – магический отвар, который связывает наши души со стихиями." }, { 4.61, "Мало кому из шаманов известен рецепт, и эта штука точно не для слабых духом." }, { 9.94, "Выпьешь её – и сможешь узреть то, что от других сокрыто. И знай, что пить её можно только в священном месте." }, { 18.26, "Ступай на север к камню духов, что притулился в конце тайной тропы в горах." }, { 23.37, "Там выпей зелье – и увидишь то, что земля решит тебе показать." } } }, t = { d = 42.3, g = 1, v = "elemental-earth", n = { m = 280, f = 280 }, c = { m = { { 0.00, "А... путник... Земля приветствует тебя, даже в этом промёрзшем краю." }, { 7.20, "Связанный с ней телом и духом, ты пойдёшь вперёд, зная, что горы – твоя сила, равнины – твоё терпение, а мир – твоя суть." }, { 21.08, "Чтобы пройти этот обряд, смиренно предстань перед Землёй. Другие стихии не так спокойны – они сталкиваются и ревут." }, { 34.67, "Познай их двойственную природу даже здесь, среди снега и камня." } }, f = { { 0.00, "А... путница... Земля приветствует тебя, даже в этом промёрзшем краю." }, { 7.58, "Связанная с ней телом и духом, ты пойдёшь вперёд, зная, что горы – твоя сила, равнины – твоё терпение, а мир – твоя суть." }, { 21.28, "Чтобы пройти этот обряд, смиренно предстань перед Землёй. Другие стихии не так спокойны – они сталкиваются и ревут." }, { 34.87, "Познай их двойственную природу даже здесь, среди снега и камня." } } } } },
    [94375] = { d = 52.8, g = 1, v = "elemental-earth", n = { m = 345, f = 346 }, c = { m = { { 0.00, "Возьми этот необработанный кварц и отнеси его Тео Молотошторму в доказательство того, что мы с тобой встречались." }, { 15.40, "Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма." }, { 22.94, "Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого." }, { 36.33, "Будь терпелив. Оставайся сильным. И ищи мудрости." }, { 42.26, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } }, f = { { 0.00, "Возьми этот необработанный кварц и отнеси его Тео Молотошторму в доказательство того, что мы с тобой встречались." }, { 15.65, "Он создаст тотэм для тебя, и этот камушек будет сердцем тотэма." }, { 23.19, "Он невелик, но со временем ты поймёшь, что размер не имеет значения. Иногда малое оказывается долговечнее большого." }, { 36.59, "Будь терпелива. Оставайся сильной. И ищи мудрости." }, { 42.55, "В конце концов ты станешь единым целым с Землёй – чти же её, и она будет чтить тебя." } } }, t = { d = 23.8, g = 1, v = "dwarf-male", n = { m = 281, f = 282 }, c = { m = { { 0.00, "Молодец! И знай: тотэмы – не просто знак твоего места среди шаманов." }, { 4.63, "Это инструменты, средоточие для заклинаний, связанных с камнем, землёй и другими стихиями." }, { 10.73, "Чем мудрее будешь становиться, тем больше силы горы тебе откроется. Наставники сами поймут, когда ты будешь готов к большему." }, { 19.27, "А пока возьми этот тотэм и позволь земле говорить через тебя." } }, f = { { 0.00, "Молодец! И знай: тотэмы – не просто знак твоего места среди шаманов." }, { 4.63, "Это инструменты, средоточие для заклинаний, связанных с камнем, землёй и другими стихиями." }, { 10.73, "Чем мудрее будешь становиться, тем больше силы горы тебе откроется. Наставники сами поймут, когда ты будешь готова к большему." }, { 19.28, "А пока возьми этот тотэм и позволь земле говорить через тебя." } } } } },
    [94411] = { d = 27.0, v = "skyborne-female", n = { x = 327 }, c = { x = { { 0.00, "Хочу тебя предупредить: у каменных монолитов на севере деревни были замечены представители Высшего ордена." }, { 7.15, "Мы не раз говорили им держаться подальше от наших священных мест, но их дерзость не знает границ." }, { 13.76, "Докажи свою решимость: отправляйся к монолитам и разгони незваных гостей." }, { 19.05, "Очень не хотелось бы доводить до кровопролития, но если придётся, сделай, что должно. После этого возвращайся ко мне." } } }, t = { d = 22.3, v = "skyborne-female", n = { x = 260 }, c = { x = { { 0.00, "Столкновения между братьями и сёстрами лишь ослабляют шен'дорай, но иногда нужно действовать решительно, чтобы предотвратить ещё большую беду." }, { 10.73, "Магов Высшего ордена совсем не волнуют последствия их вмешательства." }, { 15.29, "Силы, хранящие наш остров, хрупки и уязвимы – один необдуманный поступок, и наш дом будет уничтожен." } } } } },
    [94413] = { d = 30.6, v = "skyborne-male", n = { x = 359 }, c = { x = { { 0.00, "Появление силовых линий на поверхности Зефриса имело большое значение для нашего ордена." }, { 6.05, "Энергии, пронизывающие это место, стали для нас более осязаемыми, что значительно углубило наши знания о магии." }, { 13.90, "Ваятели ветра, однако, считают силовые линии шрамами на земле, которые нужно залечить." }, { 19.64, "Для нашего ордена это оскорбление, и мы не намерены такое терпеть." }, { 24.42, "Отправляйся к силовой линии в лесу к юго-западу и выдвори оттуда Ваятелей ветра." } } }, t = { d = 16.9, v = "skyborne-male", n = { x = 194 }, c = { x = { { 0.00, "Иногда сложно разграничить слепой фанатизм культа Ал'акет и упрямство Ваятелей ветра, отвергающих перемены." }, { 7.62, "Если бы они и правда верили, что ветра направят нас, то чувствовали бы, куда дуют эти ветра, и следовали бы за ними, а не против них." } } } } },
    [94414] = { d = 24.1, g = 1, v = "skyborne-male", n = { m = 280, f = 281 }, c = { m = { { 0.00, "Приветствую. Я частенько прихожу сюда, чтобы посмотреть на древний опорный столп." }, { 5.49, "Это дар от духов ветра, который питает наш остров. Но в последнее время их магия стала нестабильной и непредсказуемой." }, { 13.86, "Хотя повреждений на столпах нет, и они всё так же великолепны." }, { 18.35, "Если хочешь, могу поделиться с тобой даром, чтобы ты полюбовался вместе со мной." } }, f = { { 0.00, "Приветствую. Я частенько прихожу сюда, чтобы посмотреть на древний опорный столп." }, { 5.49, "Это дар от духов ветра, который питает наш остров. Но в последнее время их магия стала нестабильной и непредсказуемой." }, { 13.86, "Хотя повреждений на столпах нет, и они всё так же великолепны." }, { 18.35, "Если хочешь, могу поделиться с тобой даром, чтобы ты полюбовалась вместе со мной." } } }, t = { d = 8.6, g = 1, v = "skyborne-male", n = { m = 98, f = 99 }, c = { m = { { 0.00, "Благодарю, что разделил со мной этот момент. Я продолжу наблюдать за рощей и размышлять о том, что стало с нашими землями." } }, f = { { 0.00, "Благодарю, что разделила со мной этот момент. Я продолжу наблюдать за рощей и размышлять о том, что стало с нашими землями." } } } } },
    [94427] = { d = 32.2, g = 1, v = "scourge-female", n = { m = 286, f = 286 }, c = { m = { { 0.00, "Одно из главных качеств паладина – благочестие. Это значит, что ты должен творить добро, не думая о собственной выгоде." }, { 10.52, "Каждый из нас, оказавшихся здесь, перенёс тяготы, после которых легко забыть, что при жизни мы служили Свету." }, { 20.77, "Отправляйся в Подгород и найди Танис Элдервуд в Торговом квартале. Ей нужна помощь тех, кто ещё помнит, что такое милосердие." } }, f = { { 0.00, "Одно из главных качеств паладина – благочестие. Это значит, что ты должна творить добро, не думая о собственной выгоде." }, { 10.55, "Каждый из нас, оказавшихся здесь, перенёс тяготы, после которых легко забыть, что при жизни мы служили Свету." }, { 20.80, "Отправляйся в Подгород и найди Танис Элдервуд в Торговом квартале. Ей нужна помощь тех, кто ещё помнит, что такое милосердие." } } }, t = { d = 13.5, g = 1, v = "scourge-male#83", n = { x = 101 }, c = { m = { { 0.00, "Ты... ты герой? Прошу, не трогай меня. Я-я знаю, что попрошайничать нельзя. Я ни с тобой, ни с твоим орденом не ссорилась. Оставь меня, умоляю!" } }, f = { { 0.00, "Ты... ты героиня? Прошу, не трогай меня. Я-я знаю, что попрошайничать нельзя. Я ни с тобой, ни с твоим орденом не ссорилась. Оставь меня, умоляю!" } } } } },
    [94434] = { d = 39.3, g = 1, v = "scourge-male#83", n = { m = 393, f = 395 }, c = { m = { { 0.00, "Подожди, ты хочешь... помочь? С чего бы паладину помогать какой-то попрошайке?" }, { 6.06, "Ну, кое-что ты можешь для меня сделать." }, { 9.36, "Моя подруга... как бы сказать... еле держится. В том смысле, что она буквально разваливается на части." }, { 17.98, "Аптекари могли бы подшить её так, что она будет как новенькая, но все они заняты поручениями Тёмной Госпожи, и ни у кого нет свободного времени." }, { 28.78, "Не мог бы ты принести мне немного чистой ткани?" }, { 32.38, "Тогда я смогу хотя бы обмотать её, чтобы не развалилась совсем, пока мы ждём аптекарей." } }, f = { { 0.00, "Подожди, ты хочешь... помочь? С чего бы паладину помогать какой-то попрошайке?" }, { 6.06, "Ну, кое-что ты можешь для меня сделать." }, { 9.36, "Моя подруга... как бы сказать... еле держится. В том смысле, что она буквально разваливается на части." }, { 17.98, "Аптекари могли бы подшить её так, что она будет как новенькая, но все они заняты поручениями Тёмной Госпожи, и ни у кого нет свободного времени." }, { 28.78, "Не могла бы ты принести мне немного чистой ткани?" }, { 32.53, "Тогда я смогу хотя бы обмотать её, чтобы не развалилась совсем, пока мы ждём аптекарей." } } }, t = { d = 4.4, g = 1, v = "scourge-male#83", n = { x = 37 }, c = { m = { { 0.00, "Это очень великодушно с твоей стороны, герой. Очень." } }, f = { { 0.00, "Это очень великодушно с твоей стороны, героиня. Очень." } } } } },
    [94435] = { d = 14.8, g = 1, v = "scourge-male#83", n = { m = 149, f = 150 }, c = { m = { { 0.00, "Не знаю, почему ты решил потратить своё время на помощь мне, но я тебе благодарна." }, { 6.19, "Если кто-то тебя ко мне отправил, ему тоже передай спасибо. Танис Элдервуд всегда будет твоей подругой, герой." } }, f = { { 0.00, "Не знаю, почему ты решила потратить своё время на помощь мне, но я тебе благодарна." }, { 6.19, "Если кто-то тебя ко мне отправил, ему тоже передай спасибо. Танис Элдервуд всегда будет твоей подругой, героиня." } } }, t = { d = 46.1, g = 1, v = "scourge-female", n = { m = 382, f = 383 }, c = { m = { { 0.00, "Ты хорошо поработал. Дело было небольшое, но даже такие малые деяния во имя служения могут укрепить нашу связь со Светом." }, { 12.32, "Тёмная Госпожа и многие из тех, кто ей служит, не доверяют нам." }, { 18.22, "Некоторые даже плетут против нас заговоры, но мы ответим на их страх и недоверие отвагой и праведностью." }, { 27.74, "Мы покажем им, что мы – Отрёкшиеся и готовы внести свой вклад, большой или малый, чтобы наш народ снова процветал." }, { 39.16, "Возьми этот символ – он понадобится тебе для того, что предстоит дальше." } }, f = { { 0.00, "Ты хорошо поработала. Дело было небольшое, но даже такие малые деяния во имя служения могут укрепить нашу связь со Светом." }, { 12.40, "Тёмная Госпожа и многие из тех, кто ей служит, не доверяют нам." }, { 18.30, "Некоторые даже плетут против нас заговоры, но мы ответим на их страх и недоверие отвагой и праведностью." }, { 27.82, "Мы покажем им, что мы – Отрёкшиеся и готовы внести свой вклад, большой или малый, чтобы наш народ снова процветал." }, { 39.24, "Возьми этот символ – он понадобится тебе для того, что предстоит дальше." } } } } },
    [94436] = { d = 49.9, v = "scourge-female", n = { x = 441 }, c = { x = { { 0.00, "Пришла пора показать, как ты умеешь обращаться с одним из величайших даров Света." }, { 7.78, "Предмет, который я сейчас тебе дала, называется знаком Жизни." }, { 13.30, "Обращайся с ним осторожно: тебе может быть неприятно держать в руках талисман, наполненный силой Света." }, { 22.56, "Он враждебен той магии, что создала нас, но мы всё ещё можем следовать пути Света и использовать его силу. Боль лишь напоминает нам об этом." }, { 35.44, "Спускайся вниз и найти стража смерти Билмута. Он недавно пришёл к нам с просьбой о помощи." }, { 43.55, "Покажи ему и всем Отрёкшимся, на что способен настоящий паладин." } } }, t = { d = 18.8, v = "scourge-male", n = { x = 175 }, c = { x = { { 0.00, "Так ты мне поможешь? Хорошо, хорошо. Признаюсь, я не горжусь тем, что пришлось... что ж, что пришлось просить о помощи паладинов." }, { 10.80, "Жрецы от меня отмахнулись, и ты, возможно, единственная надежда моего друга. Прошу, помоги мне." } } } } },
    [94438] = { d = 40.3, v = "scourge-male", n = { x = 405 }, c = { x = { { 0.00, "Нас с Фалганом отправили следить за Алым орденом в Долину ядовитых пауков." }, { 5.68, "Подкравшись к одному из их лагерей, мы подслушали, что орден готовится напасть на Брилл, но пока мы думали, что делать дальше, я случайно наступил на сухую ветку. Треск был на всю округу." }, { 21.03, "Фалган закричал мне \"Беги!\", и я побежал. Пролетел полпути до Брилла, прежде чем понял, что я один." }, { 28.67, "Должно быть, этот отважный балбес остался позади, чтобы задержать врагов и дать мне шанс." }, { 35.80, "Пожалуйста, найди моего друга и помоги ему, если сможешь." } } }, t = { d = 30.8, g = 1, v = "scourge-male", n = { x = 301 }, c = { m = { { 0.00, "Я... вернулся? И спас меня не кто-нибудь, а герой? Вижу, у тебя Символ жизни. Я не видел таких с..." }, { 8.40, "что ж, с довоенных времён, когда Лордерон был совсем другим. Могу лишь предположить, что ты здесь, чтобы помочь." }, { 16.61, "Нас с Билмутом послали сюда разведать, что затевает Алый орден, и мы выяснили, что они готовят какое-то нападение." }, { 25.38, "Если захочешь помочь ещё, для Отрёкшихся можно сделать куда больше." } }, f = { { 0.00, "Я... вернулся? И спас меня не кто-нибудь, а героиня? Вижу, у тебя Символ жизни. Я не видел таких с..." }, { 8.39, "что ж, с довоенных времён, когда Лордерон был совсем другим. Могу лишь предположить, что ты здесь, чтобы помочь." }, { 16.61, "Нас с Билмутом послали сюда разведать, что затевает Алый орден, и мы выяснили, что они готовят какое-то нападение." }, { 25.37, "Если захочешь помочь ещё, для Отрёкшихся можно сделать куда больше." } } } } },
    [94440] = { d = 27.2, v = "scourge-male", n = { x = 270 }, c = { x = { { 0.00, "Рыцари Алого ордена часто носят с собой сумки с приказами." }, { 4.50, "Мы знаем, что они собираются напасть, но получив их приказы, мы сможем предупредить остальных стражей смерти и подготовить засаду." }, { 14.55, "Ты не робкого десятка, паладин. Убей этих алых извергов и добудь приказы, а затем отнеси их стражу смерти Билмуту. Он знает, что делать дальше." } } }, t = { d = 25.7, g = 1, v = "scourge-male", n = { m = 263, f = 266 }, c = { m = { { 0.00, "Спасибо, что спас моего друга. Я отнесу эти планы командиру, и мы устроим этим крестоносцам такой приём, что они его не забудут." }, { 9.83, "Знаю, многие из нашего народа не доверяют вам, паладинам, но мне ясно, что ты настоящий Отрёкшийся до мозга костей." }, { 18.39, "Я этого не забуду и позабочусь, чтобы другие узнали о том, что ты сегодня здесь сделал." } }, f = { { 0.00, "Спасибо, что спасла моего друга. Я отнесу эти планы командиру, и мы устроим этим крестоносцам такой приём, что они его не забудут." }, { 10.07, "Знаю, многие из нашего народа не доверяют вам, паладинам, но мне ясно, что ты настоящая Отрёкшаяся до мозга костей." }, { 18.69, "Я этого не забуду и позабочусь, чтобы другие узнали о том, что ты сегодня здесь сделала." } } } } },
    [94441] = { d = 20.8, v = "scourge-male", n = { x = 210 }, c = { x = { { 0.00, "Пожалуйста, передай мою благодарность Даните Морр и скажи ей, что все стражи смерти узнают о том, как нам помогли паладины из Дозора Тира." }, { 10.54, "Я вижу в тебе задатки великого паладина и горжусь, что среди Отрёкшихся есть такие, как ты. Да хранит тебя Тёмная Госпожа." } } }, t = { d = 38.4, g = 1, v = "scourge-female", n = { m = 339, f = 340 }, c = { m = { { 0.00, "Символом жизни может пользоваться только герой, готовый воспользоваться одним из величайших благословений Света." }, { 10.33, "Я горжусь, что ты среди нас, и теперь дарую тебе дар искупления. С ним ты сможешь воскрешать павших товарищей. Используй этот дар с умом." }, { 22.78, "Ты хорошо послужил и Отрёкшимся, и паладинам Дозора Тира." }, { 28.15, "Любой шаг, который поможет завоевать сердца и умы наших собратьев-Отрёкшихся, стоит усилий. Ступай со Светом." } }, f = { { 0.00, "Символом жизни может пользоваться только героиня, готовая воспользоваться одним из величайших благословений Света." }, { 10.33, "Я горжусь, что ты среди нас, и теперь дарую тебе дар искупления. С ним ты сможешь воскрешать павших товарищей. Используй этот дар с умом." }, { 22.78, "Ты хорошо послужила и Отрёкшимся, и паладинам Дозора Тира." }, { 28.17, "Любой шаг, который поможет завоевать сердца и умы наших собратьев-Отрёкшихся, стоит усилий. Ступай со Светом." } } } } },
    [94449] = { d = 25.3, g = 1, v = "dwarf-male", n = { m = 287, f = 288 }, c = { m = { { 0.00, "Прошло немало времени после твоего прошлого испытания." }, { 3.73, "Терпения тебе не занимать, это да, но теперь пришёл черёд обучиться сеять хаос... и разрушения." }, { 10.28, "Зов огня громогласен и он обращается к тем, кто готов заплатить нужную цену." }, { 15.86, "Найди Брюкса Дитя Искр в горах далеко на востоке. Он живёт в пещере над фортом у Южных врат." }, { 22.15, "Он поймёт, действительно ли ты готов." } }, f = { { 0.00, "Прошло немало времени после твоего прошлого испытания." }, { 3.73, "Терпения тебе не занимать, это да, но теперь пришёл черёд обучиться сеять хаос... и разрушения." }, { 10.28, "Зов огня громогласен и он обращается к тем, кто готов заплатить нужную цену." }, { 15.86, "Найди Брюкса Дитя Искр в горах далеко на востоке. Он живёт в пещере над фортом у Южных врат." }, { 22.15, "Он поймёт, действительно ли ты готова." } } }, t = { d = 27.4, g = 1, v = "dwarf-male", n = { m = 283, f = 285 }, c = { m = { { 0.00, "Хм... Значит, ты от той старейшины? Что ж, слово шамана кремень, так что не буду спорить. Выходит, ты готов испить новую сапту." }, { 8.29, "Сапту огня. Да, я уже вижу в твоих глазах пылающую жажду познания! Ты вкусил власти и теперь хочешь ещё. Но не торопись." }, { 16.50, "Помни, чему тебя научил камень. Огнём легко овладеть, но его трудно унять. Важно знать, когда вовремя остановиться." } }, f = { { 0.00, "Хм... Значит, ты от той старейшины? Что ж, слово шамана кремень, так что не буду спорить. Выходит, ты готова испить новую сапту." }, { 10.14, "Сапту огня. Да, я уже вижу в твоих глазах пылающую жажду познания! Ты вкусила власти и теперь хочешь ещё. Но не торопись." }, { 19.18, "Помни, чему тебя научил камень. Огнём легко овладеть, но его трудно унять. Важно знать, когда вовремя остановиться." } } } } },
    [94465] = { d = 31.1, g = 1, v = "dwarf-male", n = { m = 324, f = 325 }, c = { m = { { 0.00, "Да уж, у тебя есть сила носить тотэм огня – но это ещё не значит, что ты готов." }, { 6.33, "За долиной Королей, среди утёсов Лок Модана лежит тайная тропа к одной из наших священных вершин." }, { 14.87, "Там Бралдир Пеплоплащ стережёт святилище Дремлющего Пламени." }, { 19.37, "Отнеси ему этот факел, и он поймёт, зачем ты пришёл." }, { 23.00, "Если вернёшься с факелом, зажжённым от жаровни святилища, я обучу тебя всему, что нужно для владения тотэмом огня." } }, f = { { 0.00, "Да уж, у тебя есть сила носить тотэм огня – но это ещё не значит, что ты готова." }, { 5.90, "За долиной Королей, среди утёсов Лок Модана лежит тайная тропа к одной из наших священных вершин." }, { 14.44, "Там Бралдир Пеплоплащ стережёт святилище Дремлющего Пламени." }, { 18.94, "Отнеси ему этот факел, и он поймёт, зачем ты пришла." }, { 22.50, "Если вернёшься с факелом, зажжённым от жаровни святилища, я обучу тебя всему, что нужно для владения тотэмом огня." } } }, t = { d = 26.3, v = "dwarf-male", n = { x = 296 }, c = { x = { { 0.00, "А, прости. Не заметил у тебя факел. Рад, что мы с тобой наконец-то встретились." }, { 5.72, "Многие странники забираются сюда, наслушавшись историй о богатствах и чудовищах, а находят только безмолвный камень." }, { 13.77, "Но нас с тобой не обманешь, так ведь?" }, { 16.73, "Это святилище скрывает истины, о которых Альянс и не догадывается." }, { 21.39, "Для нас это священное пламя, которое так и ждёт, чтобы пробудиться." } } } } },
    [94466] = { d = 29.0, g = 1, v = "dwarf-male", n = { m = 337, f = 337 }, c = { m = { { 0.00, "Но ты ведь столько шёл не ради моих рассказов, так ведь? Тебе нужно вечное пламя и тотэм огня." }, { 6.90, "Сначала нам понадобится сапта, которая свяжет твой дух со стихией огня." }, { 12.14, "Я её приготовлю, только добудь для меня две вещи: огненную смолу геомантов-туннельщиков из кобольдских пещер на севере и мешочек с реагентами ясновидца из племени Камнедробов, таящегося среди южных холмов." }, { 25.85, "Опасная задача, зато под стать пламени." } }, f = { { 0.00, "Но ты ведь столько шла не ради моих рассказов, так ведь? Тебе нужно вечное пламя и тотэм огня." }, { 6.83, "Сначала нам понадобится сапта, которая свяжет твой дух со стихией огня." }, { 12.06, "Я её приготовлю, только добудь для меня две вещи: огненную смолу геомантов-туннельщиков из кобольдских пещер на севере и мешочек с реагентами ясновидца из племени Камнедробов, таящегося среди южных холмов." }, { 25.62, "Опасная задача, зато под стать пламени." } } }, t = { d = 30.4, v = "dwarf-male", n = { x = 333 }, c = { x = { { 0.00, "Да, это то, что нужно." }, { 2.09, "Запомни, что я скажу: огонь – это не только ярость и разрушения. Это жизнь, это жар горна, это дыхание творения." }, { 10.42, "Все вещи связаны в равновесии. Одна сила укрощает другую, даёт ей смысл к существованию. Без тени свет был бы слепящей вспышкой." }, { 19.08, "Без огня камень был бы слишком холоден." }, { 22.24, "Истинное мастерство магии огня – умение сочетать его с другими силами, а не только всё сжигать. Вот истинная мудрость." } } } } },
    [94467] = { d = 26.1, v = "dwarf-male", n = { x = 297 }, c = { x = { { 0.00, "Сапта огня готова. Пришло время встретиться с пламенем. Вкуси её у святилища, а затем заберись до самой вершины." }, { 7.61, "Там ты найдёшь духа: он не нанесёт удар раньше тебя, но сразу поймёт, что ты его видишь." }, { 14.03, "Бей не мешкая. Чем больше будешь ждать, тем сильнее он разгорится. Когда дух падёт, забери его искры и положи в жаровню." }, { 22.27, "Подожги от неё факел, и получишь благословение огня." } } }, t = { d = 19.2, v = "dwarf-male", n = { x = 221 }, c = { x = { { 0.00, "Когда вы бросаете уголёк в жаровню, в чаше вспыхивает жаркое белое пламя." }, { 5.04, "Вы ощущаете, как по телу разливается огонь сапты, перед глазами ритмично бьётся пламя." }, { 11.27, "Вы опускаете факел в чашу, и он мгновенно вспыхивает. Вам кажется, что дым факела тянется в сторону Чёрной горы." } } } } },
    [94468] = { d = 21.8, v = "human-male#114", n = { x = 217 }, c = { x = { { 0.00, "Крепко сжимая факел, вы отступаете от жаровни, оборачиваетесь и окидываете взглядом весь Лок Модан. Вас охватывает восторг." }, { 10.41, "Пламя факела рвётся и трепещет на ветру." }, { 13.76, "И вот вы начинаете спускаться обратно по тропе, ведущей в Дун Морог, возвращаясь к Брюксу Дитя Искр." } } }, t = { d = 23.7, g = 1, v = "dwarf-male", n = { m = 272, f = 273 }, c = { m = { { 0.00, "Клянусь бородой Мадорана, твой дух горит ярче любого факела, что я видел, – и этим можно гордиться." }, { 7.05, "Продолжай идти этим путём, и стихии склонятся перед твоей волей. Наши сородичи будут приходить к тебе за мудростью и советом." }, { 15.64, "Так позволь мне первым от души поздравить тебя – и вручить твой новый тотэм. Ты его заслужил, рождённый в пламени." } }, f = { { 0.00, "Клянусь бородой Мадорана, твой дух горит ярче любого факела, что я видел, – и этим можно гордиться." }, { 7.05, "Продолжай идти этим путём, и стихии склонятся перед твоей волей. Наши сородичи будут приходить к тебе за мудростью и советом." }, { 15.64, "Так позволь мне первым от души поздравить тебя – и вручить твой новый тотэм. Ты его заслужила, рождённая в пламени." } } } } },
    [94484] = { d = 23.4, v = "skyborne-male", n = { x = 276 }, c = { x = { { 0.00, "Найдётся минутка? Ты направляешься в Теневейный лес? Там, в пещере к северо-востоку, действует конклав друидов." }, { 7.46, "Я жду от них вестей, которых нет уже очень давно." }, { 11.21, "После разрушения Бан'этала и недавних тревожных событий я боюсь, что случилась беда." }, { 16.90, "Прошу, если можешь туда отправиться, разыщи Элегаэль Колючую Лапу – тогда я смогу успокоиться." } } }, t = { d = 21.9, g = 1, v = "skyborne-female", n = { m = 191, f = 189 }, c = { m = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума. Погоди, а где остальные бойцы? Тебя же не отправили одного?" }, { 7.80, "Элегаэль бледнеет, когда вы пересказываете ей разговор с Лотелумом." }, { 12.94, "Значит, послание не дошло. Тогда мы и вправду в тяжёлом положении." }, { 17.73, "Похоже, придётся справляться своими силами. Время дорого." } }, f = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума. Погоди, а где остальные бойцы? Тебя же не отправили одну?" }, { 7.70, "Элегаэль бледнеет, когда вы пересказываете ей разговор с Лотелумом." }, { 12.84, "Значит, послание не дошло. Тогда мы и вправду в тяжёлом положении." }, { 17.63, "Похоже, придётся справляться своими силами. Время дорого." } } } } },
    [94485] = { d = 30.8, v = "skyborne-female", n = { x = 368 }, c = { x = { { 0.00, "Чтобы спасти моих товарищей в логове Когтя Ночи, мне понадобятся ингредиенты для припарки." }, { 5.97, "Первый и самый важный – мох \"Девичьи слёзы\". Обычно он растёт у корней деревьев Теневейного леса." }, { 12.73, "Этот мох выделяет липкое вещество, которое действует как антисептик и нужно для перевязки открытых ран." }, { 19.68, "Я собрала немного поблизости, но в лесу наверняка есть ещё." }, { 24.06, "Поспеши. Нам понадобится много мха – если, конечно, раненые, которых мне пришлось оставить, ещё живы." } } }, t = { d = 8.5, g = 1, v = "skyborne-female", n = { m = 47, f = 48 }, c = { m = { { 0.00, "Элегаэль берёт у вас липкий мох, устало улыбаясь." }, { 3.94, "Спасибо, ты славно потрудился. Это как раз то, что нам нужно." } }, f = { { 0.00, "Элегаэль берёт у вас липкий мох, устало улыбаясь." }, { 3.94, "Спасибо, ты славно потрудилась. Это как раз то, что нам нужно." } } } } },
    [94486] = { d = 34.1, g = 1, v = "skyborne-female", n = { m = 418, f = 418 }, c = { m = { { 0.00, "Мне нужен ещё один ингредиент для припарки – перья теневейных визгунов, которые бродят в этом лесу." }, { 6.38, "У молодых особей перья обладают изолирующими свойствами – они отлично подойдут, чтобы наложить поверх мха." }, { 13.49, "Перья не дадут засохнуть антисептическому соку и хоть немного защитят раны от воздействия окружающей среды." }, { 21.12, "Должна предупредить: хотя обычно визгуны – мирные создания, в последнее время они ведут себя на удивление агрессивно." }, { 28.86, "Их большие когти запросто вспорют тебе живот, если не будешь осторожен." } }, f = { { 0.00, "Мне нужен ещё один ингредиент для припарки – перья теневейных визгунов, которые бродят в этом лесу." }, { 6.38, "У молодых особей перья обладают изолирующими свойствами – они отлично подойдут, чтобы наложить поверх мха." }, { 13.49, "Перья не дадут засохнуть антисептическому соку и хоть немного защитят раны от воздействия окружающей среды." }, { 21.12, "Должна предупредить: хотя обычно визгуны – мирные создания, в последнее время они ведут себя на удивление агрессивно." }, { 28.86, "Их большие когти запросто вспорют тебе живот, если не будешь осторожна." } } }, t = { d = 5.4, v = "skyborne-female", n = { x = 57 }, c = { x = { { 0.00, "Благодарю. Я использую каждое перо, чтобы их жертва не была напрасной." } } } } },
    [94487] = { d = 31.9, v = "skyborne-female", n = { x = 363 }, c = { x = { { 0.00, "Культ Ал'акет напал на нас без предупреждения, и их мотивы остаются для меня загадкой." }, { 5.77, "Я всегда знала, что у них облака вместо мозгов, но не думала, что они нарушат равновесие на Зефрисе, совершив подобную жестокость." }, { 14.52, "Убей как можно больше сектантов и забери фамильные реликвии, у кого найдёшь. Элегаэль сплёвывает." }, { 21.38, "Эти проклятые сектанты не заслуживают зваться шен'дорай." }, { 25.02, "Как не заслуживают и того, чтобы их прах был развеян по ветру – пусть их тела съедят лесные звери." } } }, t = { d = 22.5, g = 1, v = "skyborne-female", n = { m = 208, f = 210 }, c = { m = { { 0.00, "Элегаэль тревожно смотрит на окровавленные трофеи." }, { 4.44, "Столько жизней потеряно, столько потенциала было у этих молодых шен'дорай. Спасибо, что принёс эти реликвии, герой." }, { 12.23, "Я сохраню их, а потом отнесу верховному старейшине." }, { 15.77, "Он позаботится о том, чтобы они дождались следующего и, возможно, более достойного поколения." } }, f = { { 0.00, "Элегаэль тревожно смотрит на окровавленные трофеи." }, { 4.44, "Столько жизней потеряно, столько потенциала было у этих молодых шен'дорай. Спасибо, что принесла эти реликвии, героиня." }, { 12.51, "Я сохраню их, а потом отнесу верховному старейшине." }, { 16.05, "Он позаботится о том, чтобы они дождались следующего и, возможно, более достойного поколения." } } } } },
    [94488] = { d = 23.3, v = "skyborne-female", n = { x = 272 }, c = { x = { { 0.00, "Я по-прежнему не понимаю, что понадобилось здесь сектантам, но я чую знакомый запах, пробивающийся через смрад пролитой крови." }, { 8.84, "Один из друидов нашего круга – Хаалиен – исчез несколько месяцев назад. Похоже, он продал свою жалкую шкуру сектантам." }, { 16.91, "Покажи ему, что бывает, когда проливаешь кровь своих же собратьев! Принеси мне его голову." } } }, t = { d = 17.5, v = "skyborne-female", n = { x = 136 }, c = { x = { { 0.00, "Элегаэль морщится, увидев отрубленную голову, но потом кивает." }, { 4.38, "Спасибо. Как бы ни бушевала во мне ярость, мне было бы сложно убить собрата." }, { 10.42, "Не стоит о нём скорбеть. Его невежество и злоба погубили сегодня множество невинных жизней." } } } } },
    [94489] = { d = 29.1, v = "skyborne-female", n = { x = 328 }, c = { x = { { 0.00, "Я приготовила припарки. Скорее отнеси их друидам в пещере – иди к северу через поляну." }, { 6.18, "Моим братьям досталось куда сильнее, чем мне. Наверняка они даже не в состоянии исцелить свои раны." }, { 12.80, "Друидов среди шен'дорай осталось так мало, что дорога каждая жизнь." }, { 18.04, "Пока ты здесь, у меня есть личная просьба. Мой супруг, Йорел Песнь Ветра, был в тяжёлом состоянии, когда я уходила." }, { 25.63, "Прошу, обработай его раны, если он ещё жив." } } }, t = { d = 20.2, v = "skyborne-female", n = { x = 95 }, c = { x = { { 0.00, "Элегаэль бледнеет, когда вы рассказываете о судьбе Йорела и состоянии остальных друидов." }, { 6.67, "Нет... Нет! Всё куда хуже, чем я..." }, { 9.21, "Элегаэль сдерживает слёзы и сжимает зубы, натужно рыча." }, { 13.73, "Они заплатят. Они все заплатят! Все, кто якшается с культом Ал'акет, познают мой гнев! Клянусь..." } } } } },
    [94490] = { d = 17.6, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "В наруче Хаалиена спрятана записка – немного порванная и запятнанная кровью во время сражения." }, { 7.36, "Похоже, она содержит полезные сведения о мотивах нападения культа на логово друидов. Элегаэль наверняка заинтересуется." } } }, t = { d = 28.9, v = "skyborne-female", n = { x = 281 }, c = { x = { { 0.00, "Им был нужен столп? Но зачем? Мы даже не были их целью?" }, { 4.86, "Элегаэль продолжает читать, дрожа от гнева." }, { 8.92, "Они убили моих товарищей, потому что мы оказались на пути! Я разорву каждого сектанта собственными клыками! Никто не уйдёт отсюда живым." }, { 18.36, "Поспеши! Если приказ и правда поступил из Валанаара, вероятно, там прячется предатель." }, { 24.03, "Передай послание Лотелуму в Валанааре и расскажи ему, что произошло." } } } } },
    [94491] = { d = 30.6, v = "skyborne-female", n = { x = 331 }, c = { x = { { 0.00, "Похоже, в Валанааре прячется шпион, передающий сведения культу." }, { 4.92, "Ясно, что мне на долгое путешествие не хватит сил, но Лотелум должен узнать, что здесь произошло." }, { 11.85, "Ещё ему следует знать, какая судьба постигла тех, кого больше нет с нами." }, { 16.65, "Благодаря твоей помощи, думаю, мы теперь справимся здесь сами, несмотря на все потери." }, { 22.66, "Прошу, поторопись. Надеюсь, наши пути пересекутся вновь. А пока... пойду убивать сектантов." } } }, t = { d = 32.0, v = "skyborne-male", n = { x = 295 }, c = { x = { { 0.00, "Лотелум смотрит на вас с неподдельным ужасом, когда вы рассказываете, что произошло в логове друидов." }, { 7.07, "Я... прошу меня извинить. Дай мне минуту. У меня нет слов, чтобы выразить, что я сейчас чувствую." }, { 13.90, "Поистине удручающая новость. Если послание не поддельное, то здесь, в Валанааре, прячется в лучшем случае сообщник сектантов, а в худшем – предатель." }, { 23.70, "Немедленно поставлю в известность верховного старейшину! Я не допущу, чтобы жертва моих товарищей оказалась напрасной." } } } } },
    [94493] = { d = 26.5, g = 1, v = "skyborne-female", n = { m = 201, f = 199 }, c = { m = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума. Погоди, а где остальные бойцы? Тебя же не отправили одного?" }, { 8.57, "Элегаэль бледнеет, когда вы всё объясняете." }, { 11.91, "Значит, послание не дошло до Валанаара. Тогда мы и вправду в тяжёлом положении." }, { 17.55, "Элегаэль глубоко вздыхает, в её взгляде появляется решимость." }, { 21.92, "Тогда придётся справляться своими силами. Время дорого." } }, f = { { 0.00, "Как хорошо, что наше послание добралось до Лотелума. Погоди, а где остальные бойцы? Тебя же не отправили одну?" }, { 7.71, "Элегаэль бледнеет, когда вы всё объясняете." }, { 11.05, "Значит, послание не дошло до Валанаара. Тогда мы и вправду в тяжёлом положении." }, { 16.68, "Элегаэль глубоко вздыхает, в её взгляде появляется решимость." }, { 21.05, "Тогда придётся справляться своими силами. Время дорого." } } }, t = { d = 20.0, v = "skyborne-female", n = { x = 228 }, c = { x = { { 0.00, "Сектанты Ал'акета напали на нас почти без предупреждения. Многие в моём логове ранены или умирают." }, { 6.57, "Я пыталась отправить весть в Валанаар, но, похоже, мои усилия были напрасны." }, { 12.49, "Прошу, раз уж ты здесь, – умоляю, помоги нам. Не знаю, сколько ещё мои собратья смогут выдерживать этот натиск." } } } } },
    [94494] = { d = 20.7, g = 1, v = "dwarf-male", n = { m = 218, f = 219 }, c = { m = { { 0.00, "Много воды утекло со времени последнего испытания." }, { 3.56, "Ты проявил немало упорства в учении, но теперь тебе пришло время узнать о чистоте воды." }, { 9.88, "Отыщи Норрика Тана Лока. Он живёт у северо-западного края озера, к югу от Каменной Плотины. Там и найдёшь его землянку. Удачи тебе." } }, f = { { 0.00, "Много воды утекло со времени последнего испытания." }, { 3.56, "Ты проявила немало упорства в учении, но теперь тебе пришло время узнать о чистоте воды." }, { 10.07, "Отыщи Норрика Тана Лока. Он живёт у северо-западного края озера, к югу от Каменной Плотины. Там и найдёшь его землянку. Удачи тебе." } } }, t = { d = 16.6, v = "dwarf-male", n = { x = 189 }, c = { x = { { 0.00, "Ветер дует тебе в спину, камень твёрд под ногами, а огонь в твоей груди горит ярко. Да, пора тебе познать истину о чистоте воды." }, { 8.55, "Твой путь был долгим, но именно дух понесёт тебя дальше. А теперь ступай, сделай первый шаг. Гора никого не ждёт." } } } } },
    [94495] = { d = 27.4, v = "dwarf-male", n = { x = 293 }, c = { x = { { 0.00, "Первым делом пойми такую истину: вода – это перерождение." }, { 3.80, "Вода точит камень, очищает от грязи и исцеляет утомлённых – но только если она чистая." }, { 9.71, "Оскверни воду, и она разнесёт эту скверну повсюду." }, { 13.59, "Если хочешь получить сапту воды, отыщи Гервдану Саэгрунд в Болотине. Она проживает вместе с семьёй в пещере под южными водопадами." }, { 24.38, "Ну же, иди, пока река тебя не обогнала." } } }, t = { d = 24.3, g = 1, v = "dwarf-male", n = { m = 232, f = 232 }, c = { m = { { 0.00, "Да, вижу это в твоих глазах, путник." }, { 2.46, "Ты гадаешь, что за душа решила поселиться здесь, в глубине Болотины, где рыщет отребье из клана Чёрного Железа, а стражи и не видать." }, { 14.05, "Что ж, у всех свои причины, дорогой." }, { 16.92, "Но главный вопрос: что привело тебя в наш дом? Здесь, у самого водопада, мы с тобой и так знаем ответ." } }, f = { { 0.00, "Да, вижу это в твоих глазах, путница." }, { 2.56, "Ты гадаешь, что за душа решила поселиться здесь, в глубине Болотины, где рыщет отребье из клана Чёрного Железа, а стражи и не видать." }, { 14.14, "Что ж, у всех свои причины, дорогая." }, { 16.99, "Но главный вопрос: что привело тебя в наш дом? Здесь, у самого водопада, мы с тобой и так знаем ответ." } } } } },
    [94497] = { d = 37.4, g = 1, v = "human-male#114", n = { m = 361, f = 361 }, c = { m = { { 0.00, "А-а, значит, ты и правда пришёл за саптой? Тогда слушай внимательно, дорогуша." }, { 7.91, "Чтобы обрести понимание и заслужить сапту, ты должен найти воду в самых разных её проявлениях." }, { 15.40, "Когда будешь собирать образцы, наблюдай за всем." }, { 19.29, "Смотри, какие звери охраняют воду, какую землю она питает и как она влияет на жизнь вокруг." }, { 26.75, "Начнём с простого: наполни этот бурдюк у подножия водопада, где свежая вода встречается с солёной." }, { 34.45, "Ступай, но будь осторожен в болоте." } }, f = { { 0.00, "А-а, значит, ты и правда пришла за саптой? Тогда слушай внимательно, дорогуша." }, { 6.00, "Чтобы обрести понимание и заслужить сапту, ты должна найти воду в самых разных её проявлениях." }, { 13.31, "Когда будешь собирать образцы, наблюдай за всем." }, { 17.20, "Смотри, какие звери охраняют воду, какую землю она питает и как она влияет на жизнь вокруг." }, { 24.66, "Начнём с простого: наполни этот бурдюк у подножия водопада, где свежая вода встречается с солёной." }, { 32.36, "Ступай, но будь осторожна в болоте." } } }, t = { d = 34.9, v = "human-male#114", n = { x = 352 }, c = { x = { { 0.00, "Рада, что тебе удалось обойти Чёрное Железо стороной." }, { 4.05, "Жаль, что они пробрались так далеко на север, – невольно задумаешься, на что были бы способны дворфы, если бы кланы перестали грызться и действовали заодно." }, { 16.10, "И всё же, когда луны сильны, прилив поднимается высоко, и морская вода заливает болото. Здесь мы и изучаем воду устья." }, { 26.43, "Благодарю за это священное подношение – оно знаменует начало твоего пути как сосуда, ищущего мудрости вод." } } } } },
    [94499] = { d = 34.3, v = "human-male#114", n = { x = 337 }, c = { x = { { 0.00, "Озеро Безмолвия поит всё Красногорье, но к тому времени как его воды обрушиваются в водопаде Каменной Стражи, к ним что-то примешивается." }, { 10.41, "Местные мурлоки – здоровенные и странные твари, совсем не такие, как те, которых можно найти здесь или у озера Лок." }, { 19.38, "К счастью для горожан, они почти не отходят от подножия водопада." }, { 24.74, "Принеси мне образец вод у того старого форта. Хочу разобраться, что их загрязняет, – яд или что-то ещё." } } }, t = { d = 24.0, g = 1, v = "human-male#114", n = { m = 243, f = 244 }, c = { m = { { 0.00, "Да, это хорошая вода. Должно быть, магия провидцев тени в тех краях меняет мурлоков. А это – чистейшая вода." }, { 8.13, "Твоя преданность делу и умение находить то, что нужно, доказывают: ты готов к следующему этапу пути." }, { 16.20, "Мне нужен всего один образец, чтобы создать реагент для твоей сапты. Норрик тоже будет доволен." } }, f = { { 0.00, "Да, это хорошая вода. Должно быть, магия провидцев тени в тех краях меняет мурлоков. А это – чистейшая вода." }, { 8.13, "Твоя преданность делу и умение находить то, что нужно, доказывают: ты готова к следующему этапу пути." }, { 16.31, "Мне нужен всего один образец, чтобы создать реагент для твоей сапты. Норрик тоже будет доволен." } } } } },
    [94500] = { d = 37.2, v = "dwarf-female#34", n = { x = 429 }, c = { x = { { 0.00, "Возьми этот бурдюк и отправляйся прямиком в изумрудные чащи Ясеневого леса." }, { 5.13, "Среди вод, не затронутых порчей, ты найдёшь деревушку Астранаар." }, { 9.43, "Дно местного озера усеяно обломками строений, существовавших в давно минувшие времена. Принеси мне образец из него." }, { 17.16, "То будет чистая, древняя и, возможно, зачарованная вода." }, { 21.85, "Это последнее, что мне нужно, прежде чем я отправлю тебя к Норрику." }, { 26.77, "Сядь на корабль в Гавани Менетилов, идущий в Аубердин. Он останавливается в Южнобережье." }, { 32.93, "И имей в виду... у леса есть глаза, и они никогда не моргают." } } }, t = { d = 19.7, g = 1, v = "dwarf-female#34", n = { x = 209 }, c = { m = { { 0.00, "Молодец! Все три образца у нас, и теперь я сварю тебе флакон воды такой чистой, что горы прослезятся." }, { 7.40, "Это последняя часть твоего обряда посвящения. Горжусь, что могу звать тебя своей роднёй." }, { 13.80, "Тобой гордился бы любой герой, и я с нетерпением жду твоих будущих историй." } }, f = { { 0.00, "Молодец! Все три образца у нас, и теперь я сварю тебе флакон воды такой чистой, что горы прослезятся." }, { 7.40, "Это последняя часть твоего обряда посвящения. Горжусь, что могу звать тебя своей роднёй." }, { 13.80, "Тобой гордился бы любой героиня, и я с нетерпением жду твоих будущих историй." } } } } },
    [94501] = { d = 11.9, v = "dwarf-female#34", n = { x = 144 }, c = { x = { { 0.00, "Прежде чем провести обряды с тотэмом воды, Норрик поручит тебе ещё одно задание." }, { 5.22, "Для этого понадобится фиал с водой, который я тебя дала. Ступай, поговори с ним. Мы ещё встретимся." } } }, t = { d = 21.7, v = "dwarf-male", n = { x = 255 }, c = { x = { { 0.00, "А-а, вода, благословлённая самой Хервданой и собранная твоими собственными руками? Воистину дар." }, { 6.74, "Из этих флаконов родится твоя сапта, и ты сможешь узреть духов воды у пруда Стенделя, что близ Луноречья." }, { 13.95, "У последних капель воды не менее важное предназначение... не трать зря даже пробку, смоченную священной водой." } } } } },
    [94502] = { d = 33.1, v = "dwarf-male", n = { x = 379 }, c = { x = { { 0.00, "В Западном Крае, недалеко от Луноречья, находится пруд Стенделя." }, { 4.47, "Когда-то в нём бил чистый источник, но теперь он омрачён тёмными силами, а обитающие в том месте духи совсем умолкли." }, { 12.91, "Тебе придётся сразиться с порчей, оскверняющей воду." }, { 16.55, "Возьми её браслеты и последние капли зелья Гервданы и возложи их на алтарь святилища." }, { 22.48, "На этот жест откликнется дух, верный и чистый. Поговори с ним и наберись у него мудрости." }, { 28.84, "Принеси мне доказательство успеха, и я дарую тебе тотэм." } } }, t = { d = 14.4, v = "dwarf-male", n = { x = 173 }, c = { x = { { 0.00, "Вы кладёте наручи на святилище и выливаете оставшиеся капли зелья Норрика на сухой камень." }, { 6.26, "Вы начинаете произносить простые слова, которым научил вас Норрик, и капли испаряются на камне внутри переплетения..." } } } } },
    [94503] = { d = 17.4, v = "human-male#114", n = { x = 188 }, c = { x = { { 0.00, "Как только вы договариваете последнее слово, святилище вспыхивает ярким светом." }, { 6.15, "Шипение испаряющейся воды сменяется тишиной, и вы в смятении наблюдаете за тем, как осквернённые духи вокруг распадаются, словно пепел на ветру." } } }, t = { d = 10.8, v = "elemental-water", n = { x = 80 }, c = { x = { { 0.00, "Благодарю тебя. Благодарю шаманов." }, { 3.94, "Порча отступает, но жизнь всё угасает. Шаманам защищать жизнь." } } } } },
    [94505] = { d = 16.0, v = "elemental-water", n = { x = 113 }, c = { x = { { 0.00, "Возьми осколок. Возьми его и даруй жизнь." }, { 4.73, "Даруй жизнь и пойми. Пойми, что вода – это жизнь... А порча – конец жизни." }, { 12.56, "Оберегай и даруй жизнь силой воды." } } }, t = { d = 23.4, g = 1, v = "dwarf-male", n = { m = 264, f = 265 }, c = { m = { { 0.00, "Да, это то доказательство, о котором я просил, и ты хорошо потрудился." }, { 4.63, "Горжусь, что первым могу тебя поздравить – и вручить тотэм воды. Используй его с умом, и пусть удача идёт с тобой рядом." }, { 13.07, "Следующее испытание будет нескоро, так что потрать это время на учёбу." }, { 18.00, "Чистая вода исцеляет, да, но её дары – это куда больше, чем заживление ран." } }, f = { { 0.00, "Да, это то доказательство, о котором я просил, и ты хорошо потрудилась." }, { 4.77, "Горжусь, что первым могу тебя поздравить – и вручить тотэм воды. Используй его с умом, и пусть удача идёт с тобой рядом." }, { 13.21, "Следующее испытание будет нескоро, так что потрать это время на учёбу." }, { 18.14, "Чистая вода исцеляет, да, но её дары – это куда больше, чем заживление ран." } } } } },
    [94568] = { d = 15.5, v = "skyborne-male", n = { x = 177 }, c = { x = { { 0.00, "Перебежчик явно пришёл в ужас от того, что замыслили сектанты – настолько, что отступился от их учений и обратился к нам." }, { 7.92, "Очень жаль, что он погиб и унёс эти тайны в могилу." }, { 11.81, "Нам надо всё обдумать и обсудить дальнейшие шаги." } } }, t = { d = 8.2, v = "skyborne-male", n = { x = 95 }, c = { x = { { 0.00, "Можно было бы отправить миротворцев на бой с культом, но мы вряд ли одолеем их в открытом бою. Нам нужен другой подход." } } } } },
    [94638] = { d = 37.9, g = 1, v = "tauren-female", n = { m = 341, f = 341 }, c = { m = { { 0.00, "Ты пришёл, чтобы обрести силу. У меня есть для тебя поручение, хотя мне и нелегко об этом просить." }, { 9.33, "Моя подруга Ур'эндра потеряла рассудок и начала нападать на близких." }, { 15.03, "Когда ветра нас покинули, многие на острове обезумели, а Ур'эндра сильна и угрожает хрупкому равновесию." }, { 24.45, "Она бродит по Шен'дарскому нагорью к северо-западу отсюда." }, { 29.44, "Покажи, что у тебя довольно сил, чтобы прервать её страдания, и я дарую тебе благословение." } }, f = { { 0.00, "Ты пришла, чтобы обрести силу. У меня есть для тебя поручение, хотя мне и нелегко об этом просить." }, { 8.36, "Моя подруга Ур'эндра потеряла рассудок и начала нападать на близких." }, { 14.06, "Когда ветра нас покинули, многие на острове обезумели, а Ур'эндра сильна и угрожает хрупкому равновесию." }, { 23.47, "Она бродит по Шен'дарскому нагорью к северо-западу отсюда." }, { 28.46, "Покажи, что у тебя довольно сил, чтобы прервать её страдания, и я дарую тебе благословение." } } }, t = { d = 28.9, g = 1, v = "tauren-female", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Моя боль от утраты огромна, но это было нужно, чтобы сохранить равновесие." }, { 6.13, "Ты доказал, что у тебя есть решимость выживать и делать то, что должно, даже если цена ужасна." }, { 14.07, "Ты молодец, герой. Благословляю тебя принимать наш облик. Будь лучом надежды для слабых и защитником для нуждающихся. Иди и познавай путь когтя, дитя." } }, f = { { 0.00, "Моя боль от утраты огромна, но это было нужно, чтобы сохранить равновесие." }, { 6.13, "Ты доказала, что у тебя есть решимость выживать и делать то, что должно, даже если цена ужасна." }, { 14.29, "Ты молодец, героиня. Благословляю тебя принимать наш облик. Будь лучом надежды для слабых и защитницей для нуждающихся. Иди и познавай путь когтя, дитя." } } } } },
    [94774] = { d = 23.2, g = 1, v = "human-female#45", n = { m = 271, f = 275 }, c = { m = { { 0.00, "Ты привлёк внимание нашего начальства. Тебя просят как можно скорее отправиться в Собор Света в Штормграде." }, { 7.38, "Как я понимаю, вышестоящие считают, что ты уже достаточно показал себя и готов к дальнейшему обучению." }, { 14.19, "Когда доберёшься туда, отыщи верховную жрицу Лорену. Она расскажет, что делать дальше. Удачи и да пребудет с тобой Свет." } }, f = { { 0.00, "Ты привлекла внимание нашего начальства. Тебя просят как можно скорее отправиться в Собор Света в Штормграде." }, { 7.50, "Как я понимаю, вышестоящие считают, что ты уже достаточно показала себя и готова к дальнейшему обучению." }, { 14.69, "Когда доберёшься туда, отыщи верховную жрицу Лорену. Она расскажет, что делать дальше. Удачи и да пребудет с тобой Свет." } } }, t = { d = 15.3, g = 1, v = "human-female#45", n = { m = 171, f = 173 }, c = { m = { { 0.00, "Рада, что ты прибыл. Нам многое предстоит обсудить, но важнее всего – твоё обучение путям Света." }, { 6.86, "Есть уроки, которые должен усвоить каждый служитель Света. Если ты готов, приступим к некоторым из них прямо сейчас." } }, f = { { 0.00, "Рада, что ты прибыла. Нам многое предстоит обсудить, но важнее всего – твоё обучение путям Света." }, { 7.05, "Есть уроки, которые должен усвоить каждый служитель Света. Если ты готова, приступим к некоторым из них прямо сейчас." } } } } },
    [94775] = { d = 26.9, g = 1, v = "human-male#114", n = { m = 261, f = 264 }, c = { m = { { 0.00, "Да благословит тебя Элуна, герой. Надеюсь, Свет остаётся с тобой и защищает тебя." }, { 6.63, "Недавно тебя искал один из ваших жрецов." }, { 9.90, "Он сказал, что тебе нужно как можно скорее вернуться в Собор Света и поговорить с верховной жрицей Лореной." }, { 18.31, "Похоже, ты отлично себя показал, раз привлёк такое внимание. Не задерживайся здесь, ты нужен своим." } }, f = { { 0.00, "Да благословит тебя Элуна, героиня. Надеюсь, Свет остаётся с тобой и защищает тебя." }, { 6.97, "Недавно тебя искал один из ваших жрецов." }, { 10.23, "Он сказал, что тебе нужно как можно скорее вернуться в Собор Света и поговорить с верховной жрицей Лореной." }, { 18.65, "Похоже, ты отлично себя показала, раз привлекла такое внимание. Не задерживайся здесь, ты нужна своим." } } } },
    [94776] = { d = 25.2, g = 1, v = "human-male", n = { m = 284, f = 285 }, c = { m = { { 0.00, "Пора тебе отправиться в Штормград. С тобой хочет поговорить верховная жрица Лорена из Собора Света." }, { 6.93, "Либо дела очень хороши, либо очень плохи, раз она решила встретиться с тобой лично." }, { 12.67, "Но я подозреваю, что ты отлично себя показал, и то, что она хочет тебя видеть, это добрый знак." }, { 19.54, "Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь." } }, f = { { 0.00, "Пора тебе отправиться в Штормград. С тобой хочет поговорить верховная жрица Лорена из Собора Света." }, { 6.93, "Либо дела очень хороши, либо очень плохи, раз она решила встретиться с тобой лично." }, { 12.67, "Но я подозреваю, что ты отлично себя показала, и то, что она хочет тебя видеть, это добрый знак." }, { 19.67, "Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь." } } } },
    [94777] = { d = 22.3, g = 1, v = "human-male#114", n = { x = 210 }, c = { m = { { 0.00, "Недавно приходил один ваших жрецов и искал тебя, герой. Он попросил передать, что тебя ждут в Соборе Света." }, { 8.30, "По его словам, дело очень важное, но ты не беспокойся. Выглядел он так, будто нёс добрые вести." }, { 15.60, "Я бы на твоём месте скорее поспешила туда. Да пребудет с тобой Элуна, герой." } }, f = { { 0.00, "Недавно приходил один ваших жрецов и искал тебя, героиня. Он попросил передать, что тебя ждут в Соборе Света." }, { 8.45, "По его словам, дело очень важное, но ты не беспокойся. Выглядел он так, будто нёс добрые вести." }, { 15.76, "Я бы на твоём месте скорее поспешила туда." }, { 19.45, "Да пребудет с тобой Элуна, героиня." } } } },
    [94778] = { d = 21.0, g = 1, v = "human-male#114", n = { m = 221, f = 222 }, c = { m = { { 0.00, "Тебя вызывают в Штормград. Верховная жрица Лорена считает, что пора тебе доказать свою готовность к продолжению обучения." }, { 9.32, "Поспеши туда. Ты найдёшь её в Соборе Света в центре города. Передай ей от меня привет и докажи, что достоин этого призвания. Да пребудет с тобой Свет." } }, f = { { 0.00, "Тебя вызывают в Штормград. Верховная жрица Лорена считает, что пора тебе доказать свою готовность к продолжению обучения." }, { 9.32, "Поспеши туда. Ты найдёшь её в Соборе Света в центре города. Передай ей от меня привет и докажи, что достойна этого призвания. Да пребудет с тобой Свет." } } } },
    [94779] = { d = 22.2, v = "human-male#114", n = { x = 216 }, c = { x = { { 0.00, "Слава Элуне и твоему Свету." }, { 2.55, "Примерно в это время многие из нашего ордена обучаются способностям, отражающим их веру в Элуну." }, { 10.00, "Если не ошибаюсь, у вас принято делать так же." }, { 13.99, "Когда закончишь дела в Дарнасе, отыщи одну их своих верховных жриц, чтобы продолжить обучение." } } } },
    [94792] = { d = 29.5, v = "human-female", n = { x = 359 }, c = { x = { { 0.00, "Многие охотники предпочитают заводить животных-компаньонов. Когда рядом с тобой зверь, легче выжить даже в самой тяжёлой ситуации." }, { 8.79, "Оно и понятно – вдвоём с другом всегда всё даётся проще. Но чтобы завести такого компаньона, нужна осторожность." }, { 16.21, "Природа живёт в хрупком равновесии, которое следует уважать." }, { 20.66, "Возьми этот хлыст приручения. С его помощью ты сможешь приручить твердошкурого вепря и попрактиковаться в охотничьих навыках." } } }, t = { d = 2.9, v = "human-female", n = { x = 30 }, c = { x = { { 0.00, "Превосходно! Ты схватываешь на лёту." } } } } },
    [94793] = { d = 14.1, g = 1, v = "human-female", n = { m = 154, f = 154 }, c = { m = { { 0.00, "Теперь ты умеешь приручать зверей – осталось научиться их дрессировать. Поговори с Исааком Чаном." }, { 6.64, "Он всю жизнь посвятил лесу и расскажет, как обучать питомцев. Ступай с ветром, начинающий героя." } }, f = { { 0.00, "Теперь ты умеешь приручать зверей – осталось научиться их дрессировать. Поговори с Исааком Чаном." }, { 6.64, "Он всю жизнь посвятил лесу и расскажет, как обучать питомцев." }, { 11.24, "Ступай с ветром, начинающая героиню." } } }, t = { d = 24.2, g = 1, v = "human-male", n = { m = 270, f = 270 }, c = { m = { { 0.00, "Вижу, начинающий герой. Да, я могу обучить тебя навыкам, которые нужны, чтобы дрессировать и направлять питомца." }, { 7.77, "Ты сможешь не только обучать его новым способностям, но и кормить, а также воскрешать, если он падёт в бою." }, { 15.43, "Помни: всегда чти равновесие и с благоговением относись к природе вокруг тебя. А теперь ступай. Мы ещё поговорим, но позже." } }, f = { { 0.00, "Вижу, начинающая героиня. Да, я могу обучить тебя навыкам, которые нужны, чтобы дрессировать и направлять питомца." }, { 7.84, "Ты сможешь не только обучать его новым способностям, но и кормить, а также воскрешать, если он падёт в бою." }, { 15.50, "Помни: всегда чти равновесие и с благоговением относись к природе вокруг тебя. А теперь ступай. Мы ещё поговорим, но позже." } } } } },
    [94817] = { d = 19.6, g = 1, v = "gnome-female#41", n = { x = 224 }, c = { m = { { 0.00, "путник! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки." }, { 9.54, "Не мешкай. Ты найдёшь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!" } }, f = { { 0.00, "путница! Тебя ждут в Штормграде! Верховная жрица Лорена говорит, что тебе пора доказать свою способность перейти на новый уровень подготовки." }, { 9.63, "Не мешкай. Ты найдёшь Лорену в Соборе Света в центре города. Передай ей от меня привет и постарайся не завалить экзамен. Да хранит тебя Свет!" } } } },
    [94819] = { d = 23.8, g = 1, v = "human-male", n = { m = 277, f = 280 }, c = { m = { { 0.00, "Твоя верховная жрица Мимс хочет встретиться с тобой в Стальгорне." }, { 4.49, "Поспеши, мой находчивый друг, близится время твоего следующего испытания." }, { 9.62, "Мне хотелось бы своими глазами увидеть обряды твоего народа, но моё место здесь. Пусть Свет направит тебя в твоих странствиях." }, { 18.33, "Ищи Мимс в Палатах Магии, когда доберёшься до города. Она будет ждать." } }, f = { { 0.00, "Твоя верховная жрица Мимс хочет встретиться с тобой в Стальгорне." }, { 4.49, "Поспеши, моя находчивая подруга, близится время твоего следующего испытания." }, { 9.85, "Мне хотелось бы своими глазами увидеть обряды твоего народа, но моё место здесь. Пусть Свет направит тебя в твоих странствиях." }, { 18.56, "Ищи Мимс в Палатах Магии, когда доберёшься до города. Она будет ждать." } } } },
    [94820] = { d = 30.6, v = "nightelf-female", n = { x = 352 }, c = { x = { { 0.00, "Твой народ очень умён. Мы горды зваться вашими союзниками." }, { 4.02, "С каждым закатом ты и твои сородичи всё ближе к тому, чтобы вернуть свой город, но вместе с тем вам нужно заботиться о безопасности родных в изгнании." }, { 14.44, "Эта тоска по дому, верно, тяготит ваши сердца." }, { 18.09, "Недавно мы получили весточку из Стальгорна. Тебя просят вернуться туда и поговорить с верховной жрицей Мимс в Палатах Магии." }, { 26.60, "Не стоит заставлять её ждать. Да направит тебя Элуна." } } } },
    [94821] = { d = 19.6, g = 1, v = "human-male#114", n = { m = 193, f = 194 }, c = { m = { { 0.00, "Недавно к нам заглянул жрец, которому был нужен ты, герой." }, { 4.46, "Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне." }, { 11.75, "Когда прибудешь туда, отыщи верховную жрицу Мимс – она всё объяснит. Да пребудет с тобой Свет." } }, f = { { 0.00, "Недавно к нам заглянул жрец, которому была нужна ты, героиня." }, { 4.73, "Он сказал, что ему поручили отыскать тебя и как можно скорее отправить в Зал Тайн в Стальгорне." }, { 12.03, "Когда прибудешь туда, отыщи верховную жрицу Мимс – она всё объяснит. Да пребудет с тобой Свет." } } } },
