    [94824] = { d = 24.5, g = 1, v = "dwarf-male", n = { m = 278, f = 279 }, c = { m = { { 0.00, "Пора тебе отправиться в Стальгорн. Верховная жрица Мимс из Зала Тайн повелевает явиться ней." }, { 6.36, "Либо дела очень хороши, либо очень плохи, раз она решила встретиться с тобой лично." }, { 12.02, "Но я подозреваю, что ты отлично себя показал, и то, что она хочет тебя видеть, это добрый знак." }, { 18.79, "Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь." } }, f = { { 0.00, "Пора тебе отправиться в Стальгорн. Верховная жрица Мимс из Зала Тайн повелевает явиться ней." }, { 6.36, "Либо дела очень хороши, либо очень плохи, раз она решила встретиться с тобой лично." }, { 12.02, "Но я подозреваю, что ты отлично себя показала, и то, что она хочет тебя видеть, это добрый знак." }, { 18.98, "Я на твоём месте не задерживался бы здесь. Поспеши туда, как только сможешь." } } } },
    [94825] = { d = 22.1, g = 1, v = "human-male#114", n = { x = 207 }, c = { m = { { 0.00, "Недавно приходил один ваших жрецов и искал тебя, герой. Он попросил передать, что тебя ждут в Зале Тайн." }, { 8.03, "По его словам, дело очень важное, но ты не беспокойся. Выглядел он так, будто нёс добрые вести." }, { 15.39, "Я бы на твоём месте скорее поспешила туда. Да пребудет с тобой Элуна, герой." } }, f = { { 0.00, "Недавно приходил один ваших жрецов и искал тебя, героиня. Он попросил передать, что тебя ждут в Зале Тайн." }, { 8.15, "По его словам, дело очень важное, но ты не беспокойся. Выглядел он так, будто нёс добрые вести." }, { 15.51, "Я бы на твоём месте скорее поспешила туда." }, { 19.08, "Да пребудет с тобой Элуна, героиня." } } } },
    [94826] = { d = 21.0, v = "human-male#114", n = { x = 210 }, c = { x = { { 0.00, "Слава Элуне и твоему Свету." }, { 2.55, "Примерно в это время многие из нашего ордена обучаются способностям, отражающим их веру в Элуну." }, { 10.00, "Если не ошибаюсь, у вас принято делать так же." }, { 13.99, "Когда закончишь дела в Дарнасе, отыщи свою верховную жрицу, чтобы продолжить обучение." } } } },
    [94863] = { d = 23.4, v = "human-female", n = { x = 277 }, c = { x = { { 0.00, "Ты уже знаешь всё, что нужно, о приручении вепрей, и пришло время следующего урока." }, { 5.58, "В лесу водятся куда более опасные компаньоны, и при должной осторожности ты сможешь заслужить их доверие." }, { 13.14, "Возьми хлыст приручения и разыщи серого лесного волка. Помни: природное равновесие следует уважать." }, { 19.97, "Продемонстрируй своё умение охотника ещё раз." } } } },
    [94864] = { d = 24.6, g = 1, v = "human-female", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Ты показал себя, приручив вепря и волка, теперь же пробил час последнего испытания." }, { 5.70, "Равновесие в Элвиннском лесу зиждется на уважении и мастерстве. Возьми хлыст приручения и найди молодого лесного медведя." }, { 13.99, "Покажи, что можешь заслужить доверие даже самого могучего компаньона." }, { 19.01, "Этот урок поможет тебе почувствовать более глубокую связь с животными." } }, f = { { 0.00, "Ты показала себя, приручив вепря и волка, теперь же пробил час последнего испытания." }, { 5.68, "Равновесие в Элвиннском лесу зиждется на уважении и мастерстве. Возьми хлыст приручения и найди молодого лесного медведя." }, { 13.96, "Покажи, что можешь заслужить доверие даже самого могучего компаньона." }, { 18.98, "Этот урок поможет тебе почувствовать более глубокую связь с животными." } } }, t = { d = 2.5, v = "human-female", n = { x = 24 }, c = { x = { { 0.00, "Сама мощь леса. Смелая работа!" } } } } },
    [94896] = { d = 29.3, g = 1, v = "skyborne-female", n = { m = 309, f = 313 }, c = { m = { { 0.00, "Похоже, ты способный искатель приключений. Случайно не в Теневейный лес направляешься?" }, { 5.75, "Глубоко в лесу находится Бан'этал, и мы все его бывшие жители." }, { 10.31, "Эалана указывает на других беженцев." }, { 13.37, "Нам пришлось покинуть Бан'этал, потому что он начал обрушиваться в небо. Это случилось внезапно и посреди ночи." }, { 20.81, "Если ты направляешься туда, может, поищешь брошенные пожитки? Мы не можем вернуться – в лесу и в деревне слишком опасно." } }, f = { { 0.00, "Похоже, ты способная искательница приключений. Случайно не в Теневейный лес направляешься?" }, { 5.98, "Глубоко в лесу находится Бан'этал, и мы все его бывшие жители." }, { 10.53, "Эалана указывает на других беженцев." }, { 13.59, "Нам пришлось покинуть Бан'этал, потому что он начал обрушиваться в небо. Это случилось внезапно и посреди ночи." }, { 21.03, "Если ты направляешься туда, может, поищешь брошенные пожитки? Мы не можем вернуться – в лесу и в деревне слишком опасно." } } }, t = { d = 11.0, g = 1, v = "skyborne-female", n = { x = 120 }, c = { m = { { 0.00, "Спасибо, герой. Мы, беженцы, не забудем твоей доброты. Я прослежу, чтобы эти вещи вернулись к владельцам." }, { 6.87, "Теперь у нас хотя бы будет с чего начать новую жизнь." } }, f = { { 0.00, "Спасибо, героиня. Мы, беженцы, не забудем твоей доброты. Я прослежу, чтобы эти вещи вернулись к владельцам." }, { 7.12, "Теперь у нас хотя бы будет с чего начать новую жизнь." } } } } },
    [94897] = { d = 24.1, v = "skyborne-female", n = { x = 278 }, c = { x = { { 0.00, "Если ты направляешься в Бан'этал, у меня есть личная просьба. Мой любимый, Ресаан... я думаю, он навсегда меня покинул." }, { 7.84, "Он хотел вернуться за припасами, хотя я умоляла его не делать этого, и уже неделю не возвращается. Боюсь, случилось худшее." }, { 16.38, "Прошу, если найдёшь его, приведи ко мне. Если же он погиб, то, пожалуйста, принеси мне что-нибудь на память о нём." } } }, t = { d = 22.9, g = 1, v = "skyborne-female", n = { x = 183 }, c = { m = { { 0.00, "Глаза Эаланы наполняются слезами." }, { 3.07, "О, Ресаан, любовь моя... Что же теперь с нами станет? Столько воспоминаний... Кажется, будто наша жизнь вдвоём только начиналась." }, { 14.17, "Спасибо, герой. Как же жестока судьба – я лишилась и дома, и любимого. Но теперь я хотя бы знаю, что с ним произошло." } }, f = { { 0.00, "Глаза Эаланы наполняются слезами." }, { 3.07, "О, Ресаан, любовь моя... Что же теперь с нами станет? Столько воспоминаний... Кажется, будто наша жизнь вдвоём только начиналась." }, { 14.17, "Спасибо, героиня. Как же жестока судьба – я лишилась и дома, и любимого. Но теперь я хотя бы знаю, что с ним произошло." } } } } },
    [94898] = { d = 28.3, v = "skyborne-male", n = { x = 331 }, c = { x = { { 0.00, "Когда наш дом начал обрушиваться в небо той роковой ночью, было похоже, что сами стихии хотят нас поглотить." }, { 7.21, "Духи ветра являлись перед нами, пока мы уносили ноги, и нападали, сея среди беженцев ужас." }, { 13.56, "Катастрофа унесла жизни многих жителей, но ещё больше погибло из-за неудержимой ярости духов ветра." }, { 20.30, "Может, их спровоцировало обрушение, но они всё равно очень опасны." }, { 25.17, "Если сможешь, пожалуйста, подари им покой." } } } },
    [94911] = { d = 30.4, g = 1, v = "human-male#114", n = { m = 308, f = 308 }, c = { m = { { 0.00, "Привет, юный герой. Вижу, ты подаёшь большие надежды как друид." }, { 4.84, "В Громовом Утёсе живёт таурен по имени Тюрак Рунический Тотэм, вам стоит поговорить." }, { 11.25, "Он покажет тебе, как попасть в святилище Круга Кенария на Калимдоре, на Лунную поляну." }, { 18.33, "Друиды Круга будут рады поделиться с тобой знаниями." }, { 22.53, "Как говорят на вашем острове, ступай с благословением ветра, мой юный друг. Удачи в приключениях." } }, f = { { 0.00, "Привет, юная героиня. Вижу, ты подаёшь большие надежды как друид." }, { 4.94, "В Громовом Утёсе живёт таурен по имени Тюрак Рунический Тотэм, вам стоит поговорить." }, { 11.35, "Он покажет тебе, как попасть в святилище Круга Кенария на Калимдоре, на Лунную поляну." }, { 18.43, "Друиды Круга будут рады поделиться с тобой знаниями." }, { 22.63, "Как говорят на вашем острове, ступай с благословением ветра, мой юный друг. Удачи в приключениях." } } }, t = { d = 27.8, g = 1, v = "tauren-male#67", n = { m = 218, f = 222 }, c = { m = { { 0.00, "Высший эльф говорит со мной... в Громовом Утёсе. Чудесам нет конца, да?" }, { 7.16, "Что ж, ваятель ветра, позволь мне вместе с братьями и сёстрами из Служителей Земли поприветствовать тебя на Азероте." }, { 19.49, "Моим собратьям-друидам из Круга Кенария есть чем поделиться с тобой, дитя природы." } }, f = { { 0.00, "Высший эльф говорит со мной... в Громовом Утёсе. Чудесам нет конца, да?" }, { 7.16, "Что ж, ваятельница ветра, позволь мне вместе с братьями и сёстрами из Служителей Земли поприветствовать тебя на Азероте." }, { 18.70, "Моим собратьям-друидам из Круга Кенария есть чем поделиться с тобой, дитя природы." } } } } },
    [94912] = { d = 30.5, g = 1, v = "human-male#114", n = { m = 282, f = 283 }, c = { m = { { 0.00, "Привет, молодой герой." }, { 2.05, "Ты слышал про Круг Кенария? Вряд ли. Это древний орден служителей природы, практикующих искусство друидов, как и ты." }, { 12.58, "в Штормграде живёт ночной эльф по имени Шельдрас Лунное Древо." }, { 17.43, "Он расскажет тебе, как попасть на Лунную поляну – святилище Круга Кенария на Калимдоре." }, { 25.11, "Иди. Если ты хочешь спасти свой дом, тебе надо многому научиться." } }, f = { { 0.00, "Привет, молодая героиня." }, { 2.23, "Ты слышала про Круг Кенария? Вряд ли. Это древний орден служителей природы, практикующих искусство друидов, как и ты." }, { 11.40, "в Штормграде живёт ночной эльф по имени Шельдрас Лунное Древо." }, { 16.25, "Он расскажет тебе, как попасть на Лунную поляну – святилище Круга Кенария на Калимдоре." }, { 23.93, "Иди. Если ты хочешь спасти свой дом, тебе надо многому научиться." } } }, t = { d = 22.1, g = 1, v = "human-male#114", n = { x = 199 }, c = { m = { { 0.00, "Приветствую, герой. Мне приятно встретить собрата по ремеслу из числа небеснорождённых и одним из первых поприветствовать тебя на Азероте." }, { 11.11, "Думаю, ты убедишься, что моим собратьям-друидам из Круга Кенария есть чем поделиться с тобой, дитя природы." } }, f = { { 0.00, "Приветствую, героиня. Мне приятно встретить собрата по ремеслу из числа небеснорождённых и одним из первых поприветствовать тебя на Азероте." }, { 13.47, "Думаю, ты убедишься, что моим собратьям-друидам из Круга Кенария есть чем поделиться с тобой, дитя природы." } } } } },
    [94913] = { d = 47.9, v = "tauren-male#67", n = { x = 402 }, c = { x = { { 0.00, "На священной земле Лунной поляны рады всем друидам." }, { 5.15, "Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами." }, { 15.15, "Я научу тебя заклинанию, которое позволит тебе переноситься на Лунную поляну." }, { 22.59, "Пользуйся им, когда захочешь приобщиться знаниям или насладиться покоем." }, { 30.09, "Вот первый урок здесь, на Азероте, – отправляйся на Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид." } } }, t = { d = 8.6, g = 1, v = "tauren-male#67", n = { m = 58, f = 59 }, c = { m = { { 0.00, "А, вижу, ты уже освоил облик медведя. Хорошо, хорошо. Ты на верном пути, юный герой." } }, f = { { 0.00, "А, вижу, ты уже освоила облик медведя. Хорошо, хорошо. Ты на верном пути, юная героиня." } } } } },
    [94914] = { d = 35.0, v = "nightelf-male", n = { x = 402 }, c = { x = { { 0.00, "На священной земле Лунной поляны рады всем друидам." }, { 3.51, "Хранитель Ремул – страж Лунной поляны – присматривает за всеми здешними погружёнными в спячку друидами." }, { 10.54, "Я научу тебя заклинанию, которое позволит тебе переноситься на Лунную поляну." }, { 15.82, "Пользуйся им, когда захочешь приобщиться знаниям или насладиться покоем." }, { 21.24, "Вот первый урок здесь, на Азероте, – отправляйся на Лунную поляну и поговори с Дендритом Блеском Звёзд в Ночной гавани о том пути, которым ты ныне следуешь. Удачи тебе, мой юный друид." } } }, t = { d = 6.2, g = 1, v = "nightelf-male", n = { m = 58, f = 59 }, c = { m = { { 0.00, "А, вижу, ты уже освоил облик медведя. Хорошо, хорошо. Ты на верном пути, юный герой." } }, f = { { 0.00, "А, вижу, ты уже освоила облик медведя. Хорошо, хорошо. Ты на верном пути, юная героиня." } } } } },
    [94946] = { d = 27.2, g = 1, v = "skyborne-male", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Я намеревался первым ступить на земли Азерота, но недавние события, связанные с культом, всё меняют." }, { 6.76, "Пока мне придётся остаться в Валанааре. Но не беспокойся: один из наших магов встретит тебя в Даларане." }, { 13.70, "Советую начать исследовать Азерот, пока мы улаживаем дела на острове. Тебя призовут, когда понадобится помощь." }, { 21.44, "Как будешь готов отправляться, иди на ближний причал и садись на неборез." } }, f = { { 0.00, "Я намеревался первым ступить на земли Азерота, но недавние события, связанные с культом, всё меняют." }, { 6.76, "Пока мне придётся остаться в Валанааре. Но не беспокойся: один из наших магов встретит тебя в Даларане." }, { 13.70, "Советую начать исследовать Азерот, пока мы улаживаем дела на острове. Тебя призовут, когда понадобится помощь." }, { 21.44, "Как будешь готова отправляться, иди на ближний причал и садись на неборез." } } }, t = { d = 17.6, v = "skyborne-male", n = { x = 206 }, c = { x = { { 0.00, "А, вот и ты. Чудесно. Нам ещё нужно тут обустроиться, так что у тебя есть время всё здесь осмотреть." }, { 6.60, "Но постарайся не отходить от города." }, { 9.47, "Эти новые земли кажутся безмятежными, но выходить за пределы Даларана без должной подготовки может быть очень опасно." } } } } },
    [94947] = { d = 38.7, g = 1, v = "skyborne-male", n = { m = 444, f = 445 }, c = { m = { { 0.00, "Мир под облаками очень велик, и наш народ должен исследовать его просторы. Этим ты и займёшься." }, { 6.88, "Орден Кирин-Тор входит в так называемый Альянс народов-единомышленников." }, { 11.67, "Фактическим сердцем этого союза является город Штормград на юге отсюда." }, { 16.46, "Элаадрин попросил меня подыскать представителя нашего народа, который смог бы отправиться в этот город и встретиться с его лордом-регентом, человеком по имени Болвар Фордрагон." }, { 28.50, "Когда будешь готов, воспользуйся порталом в Штормград. Маги Кирин-Тора создали его специально для Высшего ордена." } }, f = { { 0.00, "Мир под облаками очень велик, и наш народ должен исследовать его просторы. Этим ты и займёшься." }, { 6.88, "Орден Кирин-Тор входит в так называемый Альянс народов-единомышленников." }, { 11.67, "Фактическим сердцем этого союза является город Штормград на юге отсюда." }, { 16.46, "Элаадрин попросил меня подыскать представителя нашего народа, который смог бы отправиться в этот город и встретиться с его лордом-регентом, человеком по имени Болвар Фордрагон." }, { 28.50, "Когда будешь готова, воспользуйся порталом в Штормград. Маги Кирин-Тора создали его специально для Высшего ордена." } } }, t = { d = 31.1, g = 1, v = "human-male", n = { m = 352, f = 352 }, c = { m = { { 0.00, "Приветствую тебя, герой. Я Болвар Фордрагон, регент королевства Штормград." }, { 5.50, "Посланник Кирин-Тора предупредил, что скоро прибудет эмиссар Высшего ордена, и вот ты здесь." }, { 11.83, "В этот тронный зал давно не ступала нога высшего эльфа, но я с радостью приму тебя как гостя." }, { 18.50, "От имени нашего короля сердечно приветствую тебя в Штормграде. Отныне тебе разрешено свободно перемещаться по землям Альянса." }, { 27.24, "Добро пожаловать в Азерот, небеснорождённый." } }, f = { { 0.00, "Приветствую тебя, героиня. Я Болвар Фордрагон, регент королевства Штормград." }, { 6.03, "Посланник Кирин-Тора предупредил, что скоро прибудет эмиссар Высшего ордена, и вот ты здесь." }, { 12.36, "В этот тронный зал давно не ступала нога высшего эльфа, но я с радостью приму тебя как гостя." }, { 19.03, "От имени нашего короля сердечно приветствую тебя в Штормграде. Отныне тебе разрешено свободно перемещаться по землям Альянса." }, { 27.77, "Добро пожаловать в Азерот, небеснорождённая." } } } } },
    [94978] = { d = 25.0, v = "skyborne-male", n = { x = 280 }, c = { x = { { 0.00, "Каждому охотнику нужен верный питомец, любящий своего хозяина. Это будет твоё первое испытание." }, { 7.09, "Когда-нибудь ты станешь приручать зверей со всех концов света, но пока начни на реках и озёрах Зефриса." }, { 14.50, "Возьми этот хлыст приручения и найди ползуна Песни Ветра." }, { 19.18, "Покажи, что умеешь дрессировать зверей, и начни свой путь к настоящему мастерству." } } }, t = { d = 3.4, g = 1, v = "skyborne-male", n = { m = 33, f = 34 }, c = { m = { { 0.00, "Отлично приручил! Ты уже делаешь успехи." } }, f = { { 0.00, "Отлично приручила! Ты уже делаешь успехи." } } } } },
    [94979] = { d = 22.7, g = 1, v = "skyborne-male", n = { m = 266, f = 268 }, c = { m = { { 0.00, "Ты показал, что способен, приручить речного ползуна, теперь испытаем твои умения на равнине." }, { 6.14, "Поля Зефриса оглашают крики буреногов – гордых крылатых охотников, бегущих со скоростью ветра." }, { 12.67, "Возьми хлыст приручения, ступай в низину и отыщи буренога. Заслужи его доверие и приручи." }, { 19.08, "Докажи, что ты готов к предстоящим испытаниям." } }, f = { { 0.00, "Ты показала, что способна, приручить речного ползуна, теперь испытаем твои умения на равнине." }, { 6.21, "Поля Зефриса оглашают крики буреногов – гордых крылатых охотников, бегущих со скоростью ветра." }, { 12.74, "Возьми хлыст приручения, ступай в низину и отыщи буренога. Заслужи его доверие и приручи." }, { 19.15, "Докажи, что ты готова к предстоящим испытаниям." } } }, t = { d = 3.3, g = 1, v = "skyborne-male", n = { m = 31, f = 32 }, c = { m = { { 0.00, "Уже вернулся! Впечатляющая скорость!" } }, f = { { 0.00, "Уже вернулась! Впечатляющая скорость!" } } } } },
    [95034] = { d = 32.3, v = "skyborne-female", n = { x = 366 }, c = { x = { { 0.00, "Тебе стоит знать, что на самом деле мы столкнулись не с гноллами." }, { 4.70, "На нас напало огромное волкоподобное существо – теперь я знаю, что их называют воргенами." }, { 10.55, "Оно перебило стражу и переключилось на нас, но Банон заслонил меня собой." }, { 15.82, "Я кое-как сотворила заклинание, отчего тварь испугалась и сбежала. Но Банон уже получил серьёзные укусы." }, { 22.85, "Он уговаривал его бросить. Я не согласилась." }, { 27.04, "Мы ковыляли обратно, когда нас нашли гноллы. А потом случилось страшное..." } } }, t = { d = 32.2, v = "skyborne-female", n = { x = 369 }, c = { x = { { 0.00, "Теперь ты понимаешь. На последнем издыхании, пронзённый дюжиной гнолльих клинков, он поднялся, чтобы напасть на меня." }, { 8.61, "В тот последний миг наши взгляды встретились, и я поняла: он всё ещё знал, кто он, и узнал меня." }, { 14.95, "Он понимал, что происходит, но не мог себя контролировать. Это было хуже всего." }, { 20.57, "Если такое вообще возможно, я добьюсь, чтобы тварь, погубившая его, умерла и больше никогда не принесла этот ужас ни одному живому существу. Клянусь небом над головой." } } } } },
    [95036] = { d = 29.2, v = "skyborne-female", n = { x = 348 }, c = { x = { { 0.00, "Треван рассказал мне, что воргены терроризируют жителей Серебряного бора. Несмотря на силу и живучесть, их можно убить." }, { 7.89, "Но есть один, которого постоянно воскрешает неизвестная магия." }, { 12.49, "Как раз он на нас и напал – самый крупный и злобный в племени. Его называют Старый Огнеглаз." }, { 18.61, "Чтобы с ним расправиться, нам нужно совершенно особенное оружие." }, { 23.30, "Поговори с Треваном: он даст тебе список материалов для изготовления такого оружия." } } }, t = { d = 7.9, v = "scourge-male", n = { x = 82 }, c = { x = { { 0.00, "Теперь, когда материалы у нас, нужен лишь кузнец, который выкует для нас клинок. Кажется, я знаю такого." } } } } },
    [95041] = { d = 31.9, v = "gnome-female#39", n = { x = 369 }, c = { x = { { 0.00, "Перед тем как покинуть Гномреган, я сделала копию всех своих семейных архивов." }, { 5.20, "Чаротехнические полевые подсчёты, чертежи подлодок времён Второй войны, рецепт чили бабули Быстросмен..." }, { 12.07, "там собраны все наши величайшие достижения." }, { 15.46, "И только прибыв в Стальгорн, я поняла, что у меня в сумке дырка! Пропало несколько перфокарт, а без них данные не восстановить." }, { 24.32, "Должно быть, они упали в снег где-то в предместьях Гномрегана. Не поищешь их? Знаю, надежды мало, но..." } } }, t = { d = 4.9, v = "gnome-female#39", n = { x = 54 }, c = { x = { { 0.00, "Эти карты, кажется, немного отсырели... но я с этим справлюсь! Спасибо!" } } } } },
    [95042] = { d = 37.3, g = 1, v = "scourge-male", n = { x = 370 }, c = { m = { { 0.00, "Паладин из Отрёкшихся... здесь, в Ясеневом лесу? Забавно." }, { 5.69, "Значит, ты ищешь самоцвет Кор? Неудивительно: паладины Альянса иногда используют такие камни, чтобы усилить магическое оружие и снаряжение." }, { 16.86, "С чего бы падшему паладину вроде тебя от них отличаться?" }, { 21.50, "Если тебе и правда нужен такой самоцвет, отправляйся на север, к руинам под названием Непроглядная Пучина." }, { 29.42, "Наги, которые до сих пор пользуются этими камнями, обитают в глубине. Не ходи туда в одиночку, герой." } }, f = { { 0.00, "Паладин из Отрёкшихся... здесь, в Ясеневом лесу? Забавно." }, { 5.69, "Значит, ты ищешь самоцвет Кор? Неудивительно: паладины Альянса иногда используют такие камни, чтобы усилить магическое оружие и снаряжение." }, { 16.87, "С чего бы падшему паладину вроде тебя от них отличаться?" }, { 21.51, "Если тебе и правда нужен такой самоцвет, отправляйся на север, к руинам под названием Непроглядная Пучина." }, { 29.42, "Наги, которые до сих пор пользуются этими камнями, обитают в глубине. Не ходи туда в одиночку, героиня." } } }, t = { d = 28.7, g = 1, v = "scourge-male", n = { m = 300, f = 301 }, c = { m = { { 0.00, "Ты наверняка заметишь порчу, пропитавшую этот самоцвет." }, { 4.23, "Для твоих целей магия, нужная, чтобы изгнать зло, которым его наполнили ведьмы наг, довольно проста." }, { 11.64, "Жаль, на самом деле: такая сила могла бы многому научить." }, { 16.35, "Полагаю, ты не согласишься бросить то дело, ради которого искал этот камень, и продать его мне?" }, { 23.52, "Он мог бы оказаться весьма ценным для моих... научных изысканий." } }, f = { { 0.00, "Ты наверняка заметишь порчу, пропитавшую этот самоцвет." }, { 4.23, "Для твоих целей магия, нужная, чтобы изгнать зло, которым его наполнили ведьмы наг, довольно проста." }, { 11.64, "Жаль, на самом деле: такая сила могла бы многому научить." }, { 16.35, "Полагаю, ты не согласишься бросить то дело, ради которого искала этот камень, и продать его мне?" }, { 23.59, "Он мог бы оказаться весьма ценным для моих... научных изысканий." } } } } },
    [95065] = { d = 37.4, v = "human-male", n = { x = 419 }, c = { x = { { 0.00, "Какой прекрасный вид... настоящая услада для старческих глаз." }, { 4.78, "Рыба клюёт просто отлично, но у меня совсем закончилась наживка. У тебя нет при себе наживки или рыболовных снастей?" }, { 12.96, "Ну да, глупый вопрос. Я слишком увлечён рыбалкой, и мне как-то не пришло в голову, что я, наверное, единственный, кто всегда носит всё своё с собой." }, { 23.49, "Может, поможешь мне пополнить запасы?" }, { 26.17, "К западу от торгового квартала у каналов ты найдёшь Катрин Лиланд – у неё должно найтись всё необходимое для рыбной ловли." }, { 34.64, "Скажи, что тебя старина Грей послал." } } }, t = { d = 14.9, g = 1, v = "human-male", n = { m = 165, f = 167 }, c = { m = { { 0.00, "Ты как раз вовремя! Я только что поймал крупную рыбу на последнюю наживу. Сегодня хороший день, клюёт просто отлично!" }, { 8.48, "Спасибо, помог старику не потерять работу. Может, возьмёшь в дорогу часть моего улова?" } }, f = { { 0.00, "Ты как раз вовремя! Я только что поймал крупную рыбу на последнюю наживу. Сегодня хороший день, клюёт просто отлично!" }, { 8.48, "Спасибо, помогла старику не потерять работу. Может, возьмёшь в дорогу часть моего улова?" } } } } },
    [95111] = { d = 33.4, v = "scourge-male", n = { x = 339 }, c = { x = { { 0.00, "На Мельнице Таррен живёт оружейник по имени Отт. Ничем не примечательный кузнец, продаёт простые клинки путешественникам." }, { 9.87, "Я сам купил у него меч, а когда через какое-то время отдал его в Подгороде на ремонт, кузнецов удивило его качество." }, { 18.49, "Они подумали на известного мастера, но нет, то был всего лишь Отт." }, { 23.80, "Я хочу дать орку шанс выковать что-нибудь достойное. Отнеси материалы Отту на Мельницу Таррен и предложи заказ." } } }, t = { d = 23.0, v = "orc-male", n = { x = 254 }, c = { x = { { 0.00, "Интересно. По-моему, ещё никто не просил меня выполнить заказ на особую работу." }, { 5.57, "В основном я делаю простое, добротное оружие в своём стиле. Немного, зато честный труд, а славы и почестей я не ищу." }, { 14.19, "Я с радостью попробую, но почему ты обращаешься с этим ко мне? В Подгороде полно кузнецов, которые берутся за такие заказы." } } } } },
    [95125] = { d = 13.4, g = 1, v = "orc-male", n = { x = 136 }, c = { m = { { 0.00, "Это материалы наилучшего качества, герой. Ты оказываешь мне честь, заказав у меня такой клинок. Постараюсь оправдать твои ожидания." }, { 9.59, "Пожалуйста, отойди. Я приступлю к ковке." } }, f = { { 0.00, "Это материалы наилучшего качества, героиня. Ты оказываешь мне честь, заказав у меня такой клинок. Постараюсь оправдать твои ожидания." }, { 9.68, "Пожалуйста, отойди. Я приступлю к ковке." } } }, t = { d = 10.3, v = "orc-male", n = { x = 113 }, c = { x = { { 0.00, "Этот клинок – моя лучшая работа, и я надеюсь, что он хорошо послужит тебе в странствиях. Ещё раз спасибо за эту возможность. Ака'Магош, друг мой." } } } } },
    [95126] = { d = 9.8, v = "orc-male", n = { x = 109 }, c = { x = { { 0.00, "Вот готовый клинок. Говоришь, тебя послал паладин Треван? Передай благодарность и ему. Нечасто выпадает такой шанс. Иди с честью, друг." } } }, t = { d = 16.9, g = 1, v = "scourge-male", n = { m = 118, f = 119 }, c = { m = { { 0.00, "Треван берёт клинок и внимательно его осматривает." }, { 4.32, "Отлично подойдёт. Я знал, что Отт способен создать нечто поистине великое." }, { 11.24, "Осталось лишь убить эту тварь. Поговори с Люминой, когда будешь готов." } }, f = { { 0.00, "Треван берёт клинок и внимательно его осматривает." }, { 4.32, "Отлично подойдёт. Я знал, что Отт способен создать нечто поистине великое." }, { 11.24, "Осталось лишь убить эту тварь. Поговори с Люминой, когда будешь готова." } } } } },
    [95140] = { d = 22.6, g = 1, v = "skyborne-female", n = { x = 242 }, c = { m = { { 0.00, "Вижу, оружие у тебя, герой. Я буду молиться, чтобы оно тебя не подвело." }, { 5.01, "Местные жители говорят, что Старый Огнеглаз охотится на большой территории к югу и часто пробегает мимо ворот Гилнеаса." }, { 13.00, "Найди его и пусти в ход свой клинок. Когда прикончишь Огнеглаза, возвращайся ко мне за наградой от Ваятелей Ветра." } }, f = { { 0.00, "Вижу, оружие у тебя, героиня. Я буду молиться, чтобы оно тебя не подвело." }, { 5.21, "Местные жители говорят, что Старый Огнеглаз охотится на большой территории к югу и часто пробегает мимо ворот Гилнеаса." }, { 13.20, "Найди его и пусти в ход свой клинок. Когда прикончишь Огнеглаза, возвращайся ко мне за наградой от Ваятелей Ветра." } } }, t = { d = 30.1, g = 1, v = "skyborne-female", n = { x = 233 }, c = { m = { { 0.00, "Спасибо. Теперь Банон может покоиться с миром." }, { 3.46, "Если позволишь, думаю, я смогу наложить на твой только что обагрённый кровью клинок немного магии моего народа." }, { 12.06, "Глаза Люмины Песнь Ветра начинают светиться ярко-синим, когда она касается окровавленного клинка в вашей руке." }, { 20.39, "Готово. Это мелочь – такой великолепный клинок я едва ли могла улучшить." }, { 25.18, "И всё же я буду молить ветра, чтобы он хорошо служил тебе, герой." } }, f = { { 0.00, "Спасибо. Теперь Банон может покоиться с миром." }, { 3.46, "Если позволишь, думаю, я смогу наложить на твой только что обагрённый кровью клинок немного магии моего народа." }, { 12.06, "Глаза Люмины Песнь Ветра начинают светиться ярко-синим, когда она касается окровавленного клинка в вашей руке." }, { 20.39, "Готово. Это мелочь – такой великолепный клинок я едва ли могла улучшить." }, { 25.18, "И всё же я буду молить ветра, чтобы он хорошо служил тебе, героиня." } } } } },
    [95161] = { d = 23.1, v = "human-female", n = { x = 262 }, c = { x = { { 0.00, "Если ты ищешь Джереми Хартвивера, то обратись к его новоиспечённой приёмной матери." }, { 5.70, "Её зовут Аветта Хвористинка, и живёт она в Сумеречном лесу. Добрейшая женщина." }, { 11.63, "Ей, должно быть, понадобился помощник по хозяйству, но это лучше, чем жить в приюте." }, { 17.58, "Если увидишься с Джереми, передай ему, что мы все про него вспоминаем, хорошо?" } } }, t = { d = 32.3, g = 1, v = "human-female#113", n = { m = 366, f = 368 }, c = { m = { { 0.00, "О нет..." }, { 0.99, "Спасибо, что принёс это письмо, но мне кажется, Джереми ещё не готов его увидеть." }, { 6.38, "Попечительница Найтингейл сказала, что мой Джереми не разговаривает с тех пор, как на Лордерон напали, и я не хочу на него давить." }, { 15.08, "Это письмо принесёт ему только боль." }, { 17.81, "Не смотри на меня так. Я не собираюсь скрывать от мальчика его прошлое, но ему нужно время, чтобы прийти в себя." }, { 25.45, "Отдам ему письмо, когда он будет постарше. Спасибо, что зашёл к нам, но, думаю, тебе пора уходить." } }, f = { { 0.00, "О нет..." }, { 0.99, "Спасибо, что принесла это письмо, но мне кажется, Джереми ещё не готов его увидеть." }, { 6.53, "Попечительница Найтингейл сказала, что мой Джереми не разговаривает с тех пор, как на Лордерон напали, и я не хочу на него давить." }, { 15.23, "Это письмо принесёт ему только боль." }, { 17.96, "Не смотри на меня так. Я не собираюсь скрывать от мальчика его прошлое, но ему нужно время, чтобы прийти в себя." }, { 25.60, "Отдам ему письмо, когда он будет постарше. Спасибо, что зашла к нам, но, думаю, тебе пора уходить." } } } } },
    [95189] = { d = 12.5, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Истёртый герб с символом Лордерона. После падения королевства уцелело так мало реликвий, что кто-нибудь в Штормграде наверняка заинтересуется этим предметом." } } }, t = { d = 16.8, g = 1, v = "human-female#45", n = { m = 186, f = 187 }, c = { m = { { 0.00, "Как тебе удалось раздобыть эту вещицу? Учитывая, через что она прошла, состояние у неё просто отличное." }, { 7.37, "Спасибо, что вернул нам эту частицу истории Альянса, герой. Я немедленно поручу моим лучшим экспертам восстановить эту реликвию." } }, f = { { 0.00, "Как тебе удалось раздобыть эту вещицу? Учитывая, через что она прошла, состояние у неё просто отличное." }, { 7.37, "Спасибо, что вернула нам эту частицу истории Альянса, героиня. Я немедленно поручу моим лучшим экспертам восстановить эту реликвию." } } } } },
    [95195] = { d = 13.9, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Похоже, этот старый знак отличия Альянса принадлежал солдату Лордерона. В этих руинах наверняка полно таких медалей." }, { 9.02, "Выжившие родственники солдат будут благодарны их получить." } } }, t = { d = 20.6, g = 1, v = "human-male", n = { m = 236, f = 239 }, c = { m = { { 0.00, "Ты правильно сделал, что принёс мне эти знаки отличия. Когда Плеть захватила Лордерон, многие его жители бежали сюда, в Штормград." }, { 8.85, "А из хозяев этих знаков едва ли кто-то остался в живых." }, { 12.95, "Твоя преданность Штормграду достойна похвалы. Я немедленно передам эти знаки выжившим родственникам." } }, f = { { 0.00, "Ты правильно сделала, что принесла мне эти знаки отличия." }, { 3.95, "Когда Плеть захватила Лордерон, многие его жители бежали сюда, в Штормград." }, { 9.12, "А из хозяев этих знаков едва ли кто-то остался в живых." }, { 13.23, "Твоя преданность Штормграду достойна похвалы. Я немедленно передам эти знаки выжившим родственникам." } } } } },
    [95204] = { d = 12.2, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Истёртый герб с символом Лордерона. После падения королевства уцелело так мало реликвий, что кто-нибудь в Подгороде наверняка заинтересуется этим предметом." } } }, t = { d = 26.4, g = 1, v = "scourge-female#79", n = { x = 161 }, c = { m = { { 0.00, "Оран пробует герб на зуб, чтобы убедиться в его подлинности." }, { 6.26, "Надо же. Настоящая реликвия нашей родины. И почти целая. С ней нужно обращаться особенно бережно." }, { 15.72, "Спасибо, что помогаешь восстановить нашу историю, герой. Я прослежу, чтобы о ней как следует позаботились." } }, f = { { 0.00, "Оран пробует герб на зуб, чтобы убедиться в его подлинности." }, { 6.26, "Надо же. Настоящая реликвия нашей родины. И почти целая. С ней нужно обращаться особенно бережно." }, { 15.72, "Спасибо, что помогаешь восстановить нашу историю, героиня. Я прослежу, чтобы о ней как следует позаботились." } } } } },
    [95212] = { d = 18.7, v = "dwarf-female#34", n = { x = 225 }, c = { x = { { 0.00, "Мы готовимся отправить подмогу альтеракской экспедиции, но у нас не хватает материалов, чтобы изготовить сёдла для баранов." }, { 8.56, "Поохоться на самых крупных и свирепых леопардов на юге и принеси их шкуры." }, { 13.65, "В Альтераке лютый мороз, а наши всадники заслуживают самые тёплые сёдла!" } } }, t = { d = 5.4, g = 1, v = "dwarf-female#34", n = { x = 54 }, c = { m = { { 0.00, "Из этих шкур выйдут отличные сёдла. Альянс может гордиться тобой, герой!" } }, f = { { 0.00, "Из этих шкур выйдут отличные сёдла. Альянс может гордиться тобой, героиня!" } } } } },
    [95213] = { d = 22.5, v = "human-male#114", n = { x = 198 }, c = { x = { { 0.00, "На бочонке отпечатана надпись:" }, { 2.65, "ПОРОХ – ОПАСНО – НЕ ТРОГАТЬ – ОПАСНО – ТРЕБУЕТСЯ РАЗРЕШЕНИЕ НАЧАЛЬНИКА КАРЬЕРА – ОПАСНО" }, { 11.42, "У вас возникает тревожное чувство, что у троггов этого бочонка быть не должно. Лучше сообщить об этом в карьер как можно скорее." } } }, t = { d = 5.3, g = 1, v = "dwarf-male", n = { m = 13, f = 13 }, c = { m = { { 0.00, "Дворф замечает опустевший бочонок и заметно бледнеет. Ты... где это нашёл?" } }, f = { { 0.00, "Дворф замечает опустевший бочонок и заметно бледнеет. Ты... где это нашла?" } } } } },
    [95214] = { d = 11.5, v = "dwarf-male", n = { x = 134 }, c = { x = { { 0.00, "Да в этом бочонке было достаточно пороха, чтобы превратить тронный зал короля Магни в открытый двор." }, { 6.83, "Надо забрать его у троггов, пока они не додумались его поджечь." } } }, t = { d = 11.4, g = 1, v = "dwarf-male", n = { x = 120 }, c = { m = { { 0.00, "Кажется, это весь украденный порох. Спасибо, герой." }, { 3.91, "Прими эту награду и... буду ещё более признателен, если ты никому не расскажешь об этом маленьком казусе." } }, f = { { 0.00, "Кажется, это весь украденный порох. Спасибо, героиня." }, { 4.08, "Прими эту награду и... буду ещё более признателен, если ты никому не расскажешь об этом маленьком казусе." } } } } },
    [95216] = { d = 41.2, g = 1, v = "scourge-male", n = { m = 455, f = 456 }, c = { m = { { 0.00, "Добро пожаловать в самый главный орган Подгорода: Район Фармацевтов!" }, { 5.11, "Здесь мы экспериментируем с самыми заразными и экзотическими веществами на всём Азероте." }, { 12.09, "Ты застал меня в хорошем настроении, так что я позволю тебе поучаствовать в моём новом расследовании." }, { 19.57, "Похоже, в руинах над нашим прекрасным городом завёлся крайне ядовитый членистоног. Говорят, его токсин разъедает даже плоть нежити. Разве не восхитительно?" }, { 31.06, "Нужно убедиться в достоверности этих слухов. Если эта тварь заразит тебя своим смертельным ядом, приходи ко мне – я возьму образец." } }, f = { { 0.00, "Добро пожаловать в самый главный орган Подгорода: Район Фармацевтов!" }, { 5.11, "Здесь мы экспериментируем с самыми заразными и экзотическими веществами на всём Азероте." }, { 12.09, "Ты застала меня в хорошем настроении, так что я позволю тебе поучаствовать в моём новом расследовании." }, { 19.72, "Похоже, в руинах над нашим прекрасным городом завёлся крайне ядовитый членистоног. Говорят, его токсин разъедает даже плоть нежити. Разве не восхитительно?" }, { 31.21, "Нужно убедиться в достоверности этих слухов. Если эта тварь заразит тебя своим смертельным ядом, приходи ко мне – я возьму образец." } } }, t = { d = 16.5, g = 1, v = "scourge-male", n = { m = 166, f = 167 }, c = { m = { { 0.00, "Ты его убил??" }, { 1.52, "Хм-м. Твоё счастье, что этого ихора должно хватить, чтобы разобраться в свойствах яда." }, { 8.46, "Поверь, не стоит становиться врагом Королевского фармацевтического общества. А теперь прочь с глаз моих!" } }, f = { { 0.00, "Ты его убила??" }, { 1.50, "Хм-м. Твоё счастье, что этого ихора должно хватить, чтобы разобраться в свойствах яда." }, { 8.44, "Поверь, не стоит становиться врагом Королевского фармацевтического общества. А теперь прочь с глаз моих!" } } } } },
    [95217] = { d = 16.6, v = "dwarf-male#99", n = { x = 191 }, c = { x = { { 0.00, "Значит, хочешь обучиться кузнечному делу? Думаю, мы можем помочь друг другу." }, { 5.47, "Груз с припасами запаздывает, а мне нужны материалы, чтобы починить кое-что для лагеря." }, { 11.39, "Если достанешь то, что мне нужно, обучу тебя паре приёмов. Договорились?" } } }, t = { d = 5.2, g = 1, v = "dwarf-male#99", n = { m = 51, f = 51 }, c = { m = { { 0.00, "А ты находчивый." }, { 1.55, "Теперь слушай внимательно – повторять не буду!" } }, f = { { 0.00, "А ты находчивая." }, { 1.80, "Теперь слушай внимательно – повторять не буду!" } } } } },
    [95250] = { d = 29.0, g = 1, v = "human-male", n = { x = 317 }, c = { m = { { 0.00, "Что тебе нужно, герой? Не видишь, у нас тут война?" }, { 3.73, "Мой господин уже бросился в бой, а мне велел оставаться здесь. Но прошло уже довольно много времени." }, { 11.08, "Ты небось и десяти минут в бою не продержишься, но если тебе не хватает ума придумать себе занятие, то поищи моего господина, главнокомандующего." }, { 21.16, "Он самый высокий и статный герой, какого тебе когда-либо доводилось видеть, так что ты его сразу узнаешь." } }, f = { { 0.00, "Что тебе нужно, героиня? Не видишь, у нас тут война?" }, { 4.03, "Мой господин уже бросился в бой, а мне велел оставаться здесь. Но прошло уже довольно много времени." }, { 11.38, "Ты небось и десяти минут в бою не продержишься, но если тебе не хватает ума придумать себе занятие, то поищи моего господина, главнокомандующего." }, { 21.46, "Он самый высокий и статный герой, какого тебе когда-либо доводилось видеть, так что ты его сразу узнаешь." } } } },
    [95314] = { d = 48.9, v = "scourge-female#141", n = { x = 408 }, c = { x = { { 0.00, "До нашествия Плети уединённая деревушка Тенедол славилась своим шепчущим эликсиром." }, { 8.04, "Его изготавливали из трав, растущих только в Гибели Тира, и даже после того как его запретили продавать в городе, эликсир пользовался большим спросом среди аптекарей, мистиков и ценителей ядов." }, { 28.56, "Уже не один заинтересованный покупатель просил меня его раздобыть." }, { 34.77, "Отправляйся вглубь Шепчущего леса и на восток – там найдёшь руины Тенедола." }, { 41.86, "Если добудешь мне несколько бутылок, я хорошо заплачу тебе за труды." } } }, t = { d = 30.0, v = "scourge-female#141", n = { x = 236 }, c = { x = { { 0.00, "Говоришь, в Тенедоле поселилось зло? Признаюсь, я не удивлён. Лесной народ всегда был странным и не жаловал гостей." }, { 11.94, "Некоторые верят, что сам Шепчущий лес проклят, и эликсир, выгнанный из его корней, несёт то же проклятие..." }, { 22.36, "...но хватит суеверий и слухов. Спасибо за эликсиры. Вот, возьми это в уплату." } } } } },
    [95328] = { d = 8.8, v = "human-male#114", n = { x = 96 }, c = { x = { { 0.00, "Вопреки здравому смыслу, вы собираете извивающиеся останки чудища. Они могут пригодиться кому-нибудь в Подгороде." } } }, t = { d = 16.8, g = 1, v = "scourge-male#83", n = { x = 162 }, c = { m = { { 0.00, "Какой любопытный образец. Говоришь, из-под Шепчущего леса? Ни для кого не секрет, что это гиблое место отмечено Бездной." }, { 10.01, "Я рад любой возможности изучить тайны тьмы, герой. Позволь заплатить тебе за находку." } }, f = { { 0.00, "Какой любопытный образец. Говоришь, из-под Шепчущего леса? Ни для кого не секрет, что это гиблое место отмечено Бездной." }, { 10.01, "Я рад любой возможности изучить тайны тьмы, героиня. Позволь заплатить тебе за находку." } } } } },
    [95349] = { d = 30.7, g = 1, v = "skyborne-female", n = { m = 352, f = 353 }, c = { m = { { 0.00, "Из-за недавних событий, связанных с культом, мне придётся отложить путешествие по Азероту и на время остаться в Валанааре." }, { 8.08, "Вместо меня мы отправим отряд Ваятелей ветра – ты будешь в числе этих первопроходцев." }, { 13.79, "Алаана Штормовой Полёт встретит тебя в Мулгоре. Пока мы занимаемся делами здесь, советую тебе начать исследовать Азерот. Скоро мы тоже туда прибудем." }, { 24.09, "Когда будешь готов, иди на ближний причал и садись на неборез. Бану-ала." } }, f = { { 0.00, "Из-за недавних событий, связанных с культом, мне придётся отложить путешествие по Азероту и на время остаться в Валанааре." }, { 8.08, "Вместо меня мы отправим отряд Ваятелей ветра – ты будешь в числе этих первопроходцев." }, { 13.79, "Алаана Штормовой Полёт встретит тебя в Мулгоре. Пока мы занимаемся делами здесь, советую тебе начать исследовать Азерот. Скоро мы тоже туда прибудем." }, { 24.09, "Когда будешь готова, иди на ближний причал и садись на неборез. Бану-ала." } } }, t = { d = 21.8, g = 1, v = "skyborne-female", n = { m = 250, f = 254 }, c = { m = { { 0.00, "Ещё один искатель приключений с Зефриса? Чудесно. Ветра благоволят нам!" }, { 5.72, "Мы пока только обустраиваемся, поэтому у тебя есть время, чтобы исследовать эту новую землю." }, { 12.19, "Азерот – новое для нас, удивительное и опасное место." }, { 15.70, "Советую тебе подготовиться к дальнейшим приключениям, изучив для начала земли вокруг." } }, f = { { 0.00, "Ещё одна искательница приключений с Зефриса? Чудесно. Ветра благоволят нам!" }, { 5.55, "Мы пока только обустраиваемся, поэтому у тебя есть время, чтобы исследовать эту новую землю." }, { 12.02, "Азерот – новое для нас, удивительное и опасное место." }, { 15.53, "Советую тебе подготовиться к дальнейшим приключениям, изучив для начала земли вокруг." } } } } },
    [95350] = { d = 29.7, v = "skyborne-female", n = { x = 344 }, c = { x = { { 0.00, "Здесь, внизу, раскинулся большой мир, и новые союзники – ключ к нашему выживанию." }, { 5.69, "Служители Земли – часть Орды, объединяющей много гордых единомышленников." }, { 10.56, "Город Громовой Утёс – одно из поселений Орды, а к востоку находится её столица Оргриммар." }, { 16.86, "Обратись к распорядителю полётов в центре Громового Утёса, чтобы полететь в Оргриммар, и переговори с вождём Орды Траллом от имени Ваятелей ветра. Пусть ветра направляют тебя." } } }, t = { d = 24.6, g = 1, v = "orc-male", n = { m = 250, f = 254 }, c = { m = { { 0.00, "Лок-тар, герой. Я Тралл, вождь Орды." }, { 3.66, "Посланник Служителей Земли сказал, что со мной хочет поговорить представитель Ваятелей ветра, и вот ты здесь." }, { 12.11, "Не думал, что увижу высшего эльфа здесь, в Оргриммаре, однако добро пожаловать, гость Орды." }, { 18.82, "Можешь свободно путешествовать в наших землях. Ступай с честью, Ваятель ветра." } }, f = { { 0.00, "Лок-тар, героиня. Я Тралл, вождь Орды." }, { 3.25, "Посланник Служителей Земли сказал, что со мной хочет поговорить представитель Ваятелей ветра, и вот ты здесь." }, { 11.69, "Не думал, что увижу высшего эльфа здесь, в Оргриммаре, однако добро пожаловать, гость Орды." }, { 18.40, "Можешь свободно путешествовать в наших землях. Ступай с честью, Ваятельница ветра." } } } } },
    [95494] = { d = 22.3, v = "orc-male#126", n = { x = 251 }, c = { x = { { 0.00, "Мне нужен кто-нибудь с прямыми руками и свободным временем, чтобы раздобыть несколько львиных шкур." }, { 6.98, "Стыдно просить об этом постороннего, но меня ранили в ногу совсем недавно." }, { 12.28, "Пока что я не в состоянии идти на охоту, но обязанности никуда не денутся." }, { 17.89, "Лучшие шкуры бывают у зверей покрупнее, так что начни с них." } } }, t = { d = 19.7, v = "orc-male#126", n = { x = 199 }, c = { x = { { 0.00, "Да, эти вполне подойдут. У меня договор с местным дубильщиком: я поставляю ему сырые шкуры, а он взамен даёт мне готовые кожаные изделия, которые нужны мне в работе." }, { 12.95, "Я ещё ни разу не нарушал своей части уговора и, даже раненый, не собираюсь начинать." } } } } },
    [95495] = { d = 22.8, v = "orc-male#126", n = { x = 254 }, c = { x = { { 0.00, "Эти шкуры предназначены для дубильщика, с которым я часто веду торговлю." }, { 5.10, "Он что-то вроде отшельника и живёт один на гряде позади меня." }, { 9.50, "Сейчас мне будет трудновато туда подняться, так что буду признателен, если доставишь товар." }, { 16.37, "Ах да, и насчёт его... внешности. Не беспокойся, он совершенно безобиден. Клянусь, это так." } } }, t = { d = 11.1, g = 1, v = "orc-male#126", n = { m = 117, f = 118 }, c = { m = { { 0.00, "Значит, тебя прислал Вранг? Что ж, хорошо. Спасибо, что доставил мне эти шкуры. Жаль, что Вранг не смог прийти сам." }, { 8.04, "Мне нужно кое о чём с ним поговорить." } }, f = { { 0.00, "Значит, тебя прислал Вранг? Что ж, хорошо. Спасибо, что доставила мне эти шкуры. Жаль, что Вранг не смог прийти сам." }, { 8.09, "Мне нужно кое о чём с ним поговорить." } } } } },
    [95507] = { d = 16.8, v = "orc-male#126", n = { x = 180 }, c = { x = { { 0.00, "А ещё ты мне очень поможешь, если проверишь мои ловушки. Она расставлены по всей долине." }, { 7.02, "Принеси любую мелкую дичь, которая в них попалась. Только смотри, чтобы какой зверь не напал на тебя. В этих краях лучше не отвлекаться." } } }, t = { d = 8.7, g = 1, v = "orc-male#126", n = { x = 89 }, c = { m = { { 0.00, "Спасибо за помощь, герой. Я уже начал думать, что из-за этой проклятой раны на ноге придётся ложиться спать голодным." } }, f = { { 0.00, "Спасибо за помощь, героиня. Я уже начал думать, что из-за этой проклятой раны на ноге придётся ложиться спать голодным." } } } } },
    [95508] = { d = 21.5, v = "human-male", n = { x = 242 }, c = { x = { { 0.00, "Да, раньше я состоял в култирасском флоте." }, { 3.02, "После того как лорд-адмирал занял Терамор и начал свою кампанию в Дуротаре, у меня появились... \"возражения\" насчёт его действий." }, { 11.74, "Особенно всего, что касалось убийства мирного населения." }, { 16.07, "Всё не совсем так просто, но... Постой... Что это? На гряду поднимается отряд!" } } }, t = { d = 14.6, g = 1, v = "human-male", n = { x = 151 }, c = { m = { { 0.00, "Что ж, похоже, все живы. Я... знал, что однажды прошлое меня настигнет. Я у тебя в долгу за сегодняшнюю помощь." }, { 7.77, "Прошу, возьми это. Немного, но это самое меньшее, что я могу сделать. Счастливого пути, герой." } }, f = { { 0.00, "Что ж, похоже, все живы. Я... знал, что однажды прошлое меня настигнет. Я у тебя в долгу за сегодняшнюю помощь." }, { 7.77, "Прошу, возьми это. Немного, но это самое меньшее, что я могу сделать. Счастливого пути, героиня." } } } } },
    [95621] = { d = 22.3, v = "human-male", n = { x = 249 }, c = { x = { { 0.00, "Сегодня утром я заметил группу людей, ищущих что-то в долине под нами." }, { 4.84, "Я неплохо разглядел их через прицел ружья: это явно были солдаты в форме Кул-Тираса." }, { 11.15, "Если ты не против выполнить моё поручение, отправляйся к лагерю этих людей у разорённого каравана на юге." }, { 18.46, "Убей всех, кого увидишь, и узнай, что им тут нужно." } } }, t = { d = 5.3, v = "human-male", n = { x = 57 }, c = { x = { { 0.00, "Значит, они ищут дезертира... Что ж, похоже, прошлое наконец меня нагнало." } } } } },
    [95771] = { d = 22.6, v = "human-male", n = { x = 261 }, c = { x = { { 0.00, "Рудник в Североземье – не единственная головная боль." }, { 3.70, "До меня дошли известия о том, что и на элвиннском руднике Подземных глубин поселились кобольды." }, { 10.70, "Нужно исследовать рудник и подтвердить эти известия или опровергнуть их. Я буду ждать отчёта." }, { 17.28, "Рудник расположен к югу от Златоземья, между фермами Стоунфилд и Маклур." } } } },
    [95774] = { d = 24.6, v = "orc-male#60", n = { x = 267 }, c = { x = { { 0.00, "Лекарю удалось спасти меня, но не её. Она погибла в бою. Её имя – Ольгра, и я никогда её не забуду." }, { 7.15, "На ней не было украшений? Она носила много вещей из полированной кости." }, { 12.48, "Убей налётчиков из племени Иглогривых возле того места, где она погибла, и найди её драгоценные украшения!" }, { 20.10, "Я размещу их на памятнике, который воздвигну в память о ней." } } }, t = { d = 11.7, g = 1, v = "orc-male#60", n = { m = 120, f = 121 }, c = { m = { { 0.00, "Я помещу эти украшения на памятник моей жене, чтобы никогда её не забыть. Жажда мести всегда будет жечь мою кровь!" }, { 8.37, "Ты оказал мне... нам... огромную услугу." } }, f = { { 0.00, "Я помещу эти украшения на памятник моей жене, чтобы никогда её не забыть. Жажда мести всегда будет жечь мою кровь!" }, { 8.37, "Ты оказала мне... нам... огромную услугу." } } } } },
    [95803] = { d = 24.8, g = 1, v = "scourge-female", n = { m = 215, f = 217 }, c = { m = { { 0.00, "Теперь, когда голова командира омрачённых у нас, я хочу, чтобы ты отнёс её в Подгород." }, { 7.71, "Сильвана Ветрокрылая не доверяет нам и почти открыто презирает." }, { 13.84, "Отнеси голову Рудольфа Гельхардта Тёмной Госпоже. Покажи ей, что мы заботимся о своих и преданы делу Отрёкшихся." } }, f = { { 0.00, "Теперь, когда голова командира омрачённых у нас, я хочу, чтобы ты отнесла её в Подгород." }, { 8.00, "Сильвана Ветрокрылая не доверяет нам и почти открыто презирает." }, { 14.14, "Отнеси голову Рудольфа Гельхардта Тёмной Госпоже. Покажи ей, что мы заботимся о своих и преданы делу Отрёкшихся." } } }, t = { d = 28.8, v = "skyborne-female", n = { x = 337 }, c = { x = { { 0.00, "Я не сомневаюсь в искренности Даниты и в её желании добиться для вашего рода места среди Отрёкшихся." }, { 6.70, "Однако подозреваю, что мы ещё не раз увидим, как кто-то из ваших братьев и сестёр сходит с ума и обращает Свет против собственного народа." }, { 16.35, "Может настать день, когда я решу, что терпеть ваш злосчастный орден больше не в интересах Отрёкшихся." }, { 23.01, "Советую тебе и дальше усердно служить своему народу. Мы будем наблюдать." } } } } },
    [95805] = { d = 44.7, v = "tauren-male#68", n = { x = 406 }, c = { x = { { 0.00, "Солнце и луна, Ан'ше и Му'ша, не являются такой же частью нашего мира, как стихии, но их свет указывает нам путь, даёт жизнь и надежду." }, { 13.53, "Мы почитаем духов мира, и потому также отдаём дань уважения близнецам." }, { 19.38, "Если тоже хочешь выказать уважение, возьми эти тлеющие благовония и отнеси к святилищу в холмах к юго-востоку отсюда, что возвышаются над плато." }, { 32.57, "Если увидишь свинобразов – значит, тебе южнее. Поторопись, чтобы добраться до святилища до того, как они полностью истлеют. И не дай благовониям намокнуть!" } } }, t = { d = 10.7, v = "tauren-male#68", n = { x = 0 }, c = { x = { { 0.00, "Когда вы высыпаете благовония в огонь, их аромат окутывает вас, и вам остаётся лишь пустой мешочек и едва уловимое чувство удовлетворения." } } } } },
    [95816] = { d = 26.9, v = "human-male#114", c = { x = { { 0.00, "Приветствуем, уважаемый мастер!" }, { 2.82, "Заполнение этой анкеты даст вам неэксклюзивное, отчуждаемое и юридически неоднозначное право демонстрировать вывеску вашего ремесла или ремёсел по всему Азероту!" }, { 15.90, "После заполнения, пожалуйста, передайте анкету координатору контрактов в местном отделении Азеротского торгового управления. Успехов в труде!" } } } },
    [95819] = { d = 27.0, v = "human-male#114", c = { x = { { 0.00, "Приветствуем, уважаемый мастер!" }, { 2.82, "Заполнение этой анкеты даст вам неэксклюзивное, отчуждаемое и юридически неоднозначное право демонстрировать вывеску вашего ремесла или ремёсел по всему Азероту!" }, { 15.90, "После заполнения, пожалуйста, передайте анкету координатору контрактов в местном отделении Дуротарского снабжения и логистики. Успехов в труде!" } } } },
    [95883] = { d = 20.7, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Орудия для ритуала наскоро и небрежно побросали на алтарь. Если верить обрывку записки, все материалы на месте." }, { 8.72, "Не хватает только крови и истерзанной души." }, { 12.49, "Нежить вокруг вас вполне подходит под определение истерзанной. Нужный ингредиент надо искать у них." } } }, t = { d = 9.5, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Истерзанная душа источает зловещую энергию рядом с жертвенным камнем." }, { 5.71, "Похоже, вы на шаг ближе к завершению ритуала." } } } } },
    [95884] = { d = 16.5, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "На обрывке записки почти ничего нельзя прочесть. Однако записи о подготовке к жертвоприношению сохранились лучше." }, { 9.05, "В них упоминается жертвенный камень и некий ритуал." }, { 13.37, "Может, этот камень где-нибудь рядом." } } }, t = { d = 11.4, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Грубая поверхность камня усеяна странными орудиями и предметами." }, { 5.37, "Это наверняка тот самый жертвенный камень, о котором говорится в записке." } } } } },
    [95885] = { d = 12.2, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Осталось только кровавое подношение." }, { 3.24, "В обрывке записки упоминалась небольшая добровольная жертва." }, { 8.17, "На вас волной накатывает зловещее предчувствие." } } }, t = { d = 18.0, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Жертвенный камень теперь безжизнен. Похоже, ваш ритуал вытянул из него всю силу. Зачем – вам неведомо, но всё кончено." }, { 9.59, "Грубый камень трескается и рассыпается, лишившись своего предназначения. Среди обломков что-то блестит..." } } } } },
    [95981] = { d = 28.8, v = "scourge-male", n = { x = 304 }, c = { x = { { 0.00, "Отобрать подвески – лишь первый шаг." }, { 2.73, "Если Кирин-Тор действительно организовал постоянные поставки реликвий из Даларана, необходимо устранить их источник." }, { 12.75, "Осмотри дороги у Янтарной мельницы и отыщи там даларанских волшебников и дозорных." }, { 19.06, "Слишком долго мы разрешали им пересекать наши границы. Если избавиться от них, то подвесок в Серебряном бору больше не станет." } } }, t = { d = 13.4, v = "scourge-male", n = { x = 124 }, c = { x = { { 0.00, "С тех пор как вокруг Даларана пал барьер, Кирин-Тор мёртвой хваткой держится за дороги. Они чего-то боятся, это уж точно." }, { 10.31, "Впрочем, пока что причина не важна." } } } } },
    [95998] = { d = 29.3, g = 1, v = "human-male", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Приветствую, герой. Ты, похоже, один из нас, искателей приключений. Славно, славно." }, { 5.70, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.34, "Мир вокруг очень велик, и нужно учиться быть в диких краях как дома, чтобы преуспеть в нашем деле." }, { 18.09, "Не знаю, насколько ты уже в этом подкован, но если хочешь, могу научить тебя паре трюков." }, { 24.55, "Сядь у костра, устраивайся поудобнее, и я тебе всё расскажу." } }, f = { { 0.00, "Приветствую, героиня. Ты, похоже, одна из нас, искателей приключений. Славно, славно." }, { 5.82, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.46, "Мир вокруг очень велик, и нужно учиться быть в диких краях как дома, чтобы преуспеть в нашем деле." }, { 18.21, "Не знаю, насколько ты уже в этом подкована, но если хочешь, могу научить тебя паре трюков." }, { 24.76, "Сядь у костра, устраивайся поудобнее, и я тебе всё расскажу." } } }, t = { d = 10.1, v = "human-male", n = { x = 118 }, c = { x = { { 0.00, "Мы изучили основы, а теперь иди поучись ремеслу." }, { 3.45, "Тебе даже могут показать, как лучше обустроить лагерь в соответствии с твоей новой профессией." } } } } },
    [95999] = { d = 26.7, v = "human-male#114", n = { x = 288 }, c = { x = { { 0.00, "Разыскивается: Испепелитель Гар'им, предводитель армии орков в долине Ренда." }, { 5.84, "Предположительно работает с кланом Чёрной Горы в крепости Каменной Стражи." }, { 11.85, "Берегитесь Испепелителя Гар'има: он и его тёмные чародеи крайне опасны." }, { 17.15, "Смельчак, что предоставит доказательство гибели Испепелителя Гар'има мировому судье Соломону, получит щедрую награду." } } }, t = { d = 10.5, v = "human-male", n = { x = 125 }, c = { x = { { 0.00, "Отличная работа! Испепелитель Гар'им готовился укрепить оборону крепости Каменной Стражи." }, { 6.20, "После этой победы у нас появился шанс отвоевать крепость!" } } } } },
    [96031] = { d = 19.4, g = 1, v = "dwarf-male", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Ты стал кожевником. Отличное решение, герой." }, { 3.08, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать палатку, которая поможет охладиться в жаркий день и не промокнуть под дождём." }, { 13.05, "С ней ты сможешь хорошо отдыхать, чтобы всегда быть начеку во время странствий." } }, f = { { 0.00, "Ты стала кожевником. Отличное решение, героиня." }, { 3.65, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать палатку, которая поможет охладиться в жаркий день и не промокнуть под дождём." }, { 13.63, "С ней ты сможешь хорошо отдыхать, чтобы всегда быть начеку во время странствий." } } }, t = { d = 28.3, g = 1, v = "gnome-female#41", n = { m = 330, f = 331 }, c = { m = { { 0.00, "Вот, держи – теперь у тебя есть собственная походная палатка." }, { 4.21, "В городах не любят, когда палатки ставят посреди площади, так что, если хочешь её опробовать, придётся отправиться на природу." }, { 13.13, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 19.83, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, держи – теперь у тебя есть собственная походная палатка." }, { 4.21, "В городах не любят, когда палатки ставят посреди площади, так что, если хочешь её опробовать, придётся отправиться на природу." }, { 13.13, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 19.83, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
    [96044] = { d = 20.7, g = 1, v = "dwarf-male", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Так ты решил стать кузнецом? Отличный выбор, если хочешь, чтобы твои клинки никогда не затупились." }, { 6.98, "Сдаётся мне, я знаю кое-кого, кто может тебе помочь и научить создавать круг для заточки." }, { 13.19, "Установишь такой у себя в лагере – отбоя не будет от воинов и разбойников, которым надо заточить оружие." } }, f = { { 0.00, "Так ты решила стать кузнецом? Отличный выбор, если хочешь, чтобы твои клинки никогда не затупились." }, { 7.00, "Сдаётся мне, я знаю кое-кого, кто может тебе помочь и научить создавать круг для заточки." }, { 13.22, "Установишь такой у себя в лагере – отбоя не будет от воинов и разбойников, которым надо заточить оружие." } } }, t = { d = 26.7, g = 1, v = "dwarf-male", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственный круг для заточки." }, { 4.15, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.32, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 18.07, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственный круг для заточки." }, { 4.15, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.32, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 18.07, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
    [96045] = { d = 15.4, g = 1, v = "dwarf-male", n = { m = 180, f = 181 }, c = { m = { { 0.00, "Раз ты занялся алхимией, я также смогу обучить тебя создавать в лагере колодец маны, когда ты немножко наберёшься опыта в этом ремесле." }, { 9.27, "К тебе сразу выстроится очередь из целителей и колдунов, желающих из него напиться." } }, f = { { 0.00, "Раз ты занялась алхимией, я также смогу обучить тебя создавать в лагере колодец маны, когда ты немножко наберёшься опыта в этом ремесле." }, { 9.31, "К тебе сразу выстроится очередь из целителей и колдунов, желающих из него напиться." } } } },
    [96046] = { d = 24.2, v = "dwarf-male", n = { x = 269 }, c = { x = { { 0.00, "Горное дело не для белоручек, но это честная работа и отличный выбор профессии." }, { 5.83, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать магнетит для лагеря." }, { 11.62, "С ним все, кто привык размахивать мечом, соберутся у твоего костра, чтобы проникнуться силой минерала и почувствовать себя готовыми ко всему. Суеверие, но помогает же!" } } } },
    [96047] = { d = 23.6, g = 1, v = "dwarf-male", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Ты решил стать специалистом по первой помощи? Для героя это ответственный и... прагматичный выбор." }, { 7.10, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для лагеря." }, { 13.50, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } }, f = { { 0.00, "Ты решила стать специалистом по первой помощи? Для героини это ответственный и... прагматичный выбор." }, { 7.13, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для лагеря." }, { 13.53, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } } } },
    [96050] = { d = 22.7, g = 1, v = "dwarf-male", n = { m = 252, f = 254 }, c = { m = { { 0.00, "Ты, может, об этом не задумывался, но навыки рыбной ловли могут очень пригодиться в лагере." }, { 6.45, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать аквариум для лагеря." }, { 12.25, "Он порадует тебя и других искателей приключений, ведь даже простые радости могут сделать нас сильнее." }, { 19.26, "Уверена, ты и сам в этом убедишься." } }, f = { { 0.00, "Ты, может, об этом не задумывалась, но навыки рыбной ловли могут очень пригодиться в лагере." }, { 6.57, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать аквариум для лагеря." }, { 12.37, "Он порадует тебя и других искателей приключений, ведь даже простые радости могут сделать нас сильнее." }, { 19.38, "Уверена, ты и сама в этом убедишься." } } } },
    [96055] = { d = 29.3, v = "dwarf-male", n = { x = 346 }, c = { x = { { 0.00, "Ты, похоже, уже многое знаешь о травничестве. Собирать цветы – не просто развлечение. Это занятие может быть полезным... и весьма прибыльным." }, { 9.73, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать ароматную свечу для лагеря." }, { 15.93, "Чтобы целители и заклинатели достойно показывали себя в бою, им нужно правильное состояние духа, и ароматические свечи в этом здорово помогают." }, { 25.77, "Все знакомые заклинатели будут тебе благодарны." } } }, t = { d = 27.0, g = 1, v = "dwarf-female", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственную ароматную свечу. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.09, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 17.96, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственную ароматную свечу. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.37, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 18.24, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
    [96056] = { d = 28.6, v = "dwarf-male", n = { x = 335 }, c = { x = { { 0.00, "Умение быстро снимать с убитых зверей кожи и шкуры – один из наиболее полезных навыков для любого искателя приключений." }, { 8.50, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать удобный стул для лагеря." }, { 14.50, "Иногда очень важно, чтобы было где расслабиться, – а из шкур, которые ты добываешь, можно скроить очень удобное сиденье." }, { 22.62, "Благодаря этому ты точно будешь в форме, когда придёт время для следующей потасовки." } } }, t = { d = 26.3, g = 1, v = "dwarf-male", n = { m = 304, f = 305 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственный походный стул. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 10.79, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 17.54, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственный походный стул. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 10.87, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 17.62, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
