    [96059] = { d = 19.7, g = 1, v = "dwarf-male", n = { m = 232, f = 233 }, c = { m = { { 0.00, "Раз ты решил стать зачаровывателем, я, пожалуй, смогу научить тебя создавать зачарованную лютню для лагеря, когда ты немножко наберёшься опыта в этом ремесле." }, { 10.98, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы в пути." } }, f = { { 0.00, "Раз ты решила стать зачаровывателем, я, пожалуй, смогу научить тебя создавать зачарованную лютню для лагеря, когда ты немножко наберёшься опыта в этом ремесле." }, { 11.13, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы в пути." } } }, t = { d = 26.9, g = 1, v = "dwarf-male", n = { m = 309, f = 310 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственную зачарованную лютню." }, { 4.33, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.50, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 18.25, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственную зачарованную лютню." }, { 4.33, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.50, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 18.25, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
    [96101] = { d = 27.3, g = 1, v = "skyborne-male", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Приветствую, герой. Ты, похоже, один из нас, искателей приключений. Это хорошо." }, { 5.73, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.11, "Чтобы преуспевать в этом деле, тебе нужно быть в диких краях как дома." }, { 15.77, "Не знаю, насколько ты уже в этом подкован, но, возможно, смогу научить тебя паре трюков, если хочешь." }, { 23.52, "Сядь у костра поудобнее. Я тебе всё расскажу." } }, f = { { 0.00, "Приветствую, героиня. Ты, похоже, одна из нас, искателей приключений. Это хорошо." }, { 5.89, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.27, "Чтобы преуспевать в этом деле, тебе нужно быть в диких краях как дома." }, { 15.93, "Не знаю, насколько ты уже в этом подкована, но, возможно, смогу научить тебя паре трюков, если хочешь." }, { 22.96, "Сядь у костра поудобнее. Я тебе всё расскажу." } } }, t = { d = 11.7, v = "skyborne-male", n = { x = 142 }, c = { x = { { 0.00, "Мы изучили основы, а теперь иди поучись ремеслу у наставников в деревне поблизости." }, { 5.56, "Они даже могут показать, как обустроить лагерь в соответствии с твоей новой профессией." } } } } },
    [96102] = { d = 21.7, g = 1, v = "orc-male", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 7.22, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умел для этого." }, { 15.76, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } }, f = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 7.22, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умела для этого." }, { 15.70, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } } }, t = { d = 27.2, g = 1, v = "orc-male", n = { m = 304, f = 305 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственное знамя фракции. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.24, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 18.25, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственное знамя фракции. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 11.24, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 18.25, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
    [96130] = { d = 42.4, v = "tauren-male", n = { x = 397 }, c = { x = { { 0.00, "Среди степных волков, охотящихся в окрестных холмах, есть одна особенно агрессивная волчица. Мы её прозвали Чакуак." }, { 11.46, "Она стала настоящей угрозой для странников, прибывающих издалека." }, { 17.06, "Её охотничьи угодья – леса к западу от озера Каменного Быка, где она кочует от лабаза к лабазу." }, { 24.79, "Разделайся с опасной волчицей и принеси мне её шкуру, а я замолвлю за тебя словечко вождю." }, { 31.79, "Сохраняй бдительность – она крайне опасна! Может, ты встретишь там других охотников, ищущих её, и объединишь с ними силы." } } }, t = { d = 14.1, v = "tauren-male", n = { x = 137 }, c = { x = { { 0.00, "Смерть такого прекрасного существа – печальное событие, но это необходимо для безопасности нашего народа." }, { 8.98, "Я позабочусь о том, чтобы шкура не пропала зря. Спасибо тебе." } } } } },
    [96137] = { d = 26.3, v = "human-male#114", n = { x = 277 }, c = { x = { { 0.00, "Небольшой кинжал, принадлежавший самопровозглашённому следопыту Ире, которая следила за тем, чтобы обитающие в лесах звери не представляли угрозы для путешественников." }, { 13.21, "Судя по тому, что дух Иры всё ещё бродит среди деревьев, можно предположить, что у неё есть незавершённое дело – уничтожить воргов, нападающих на людей по всему лесу." } } } },
    [96138] = { d = 26.6, v = "human-male#114", n = { x = 274 }, c = { x = { { 0.00, "Лук, оставленный духом Меррика Вэлора – знаменитого дозорного, гордо защищавшего дороги от подступающих врагов." }, { 9.05, "Судя по тому, что дух Меррика всё ещё бродит по дороге, можно предположить, что у него есть незавершённое дело – уничтожить захватчиков возле его дома на Вороньем Холме." }, { 22.08, "Вероятно, огры к югу от города не дают ему упокоиться." } } } },
    [96139] = { d = 37.4, g = 1, v = "human-male", n = { m = 410, f = 411 }, c = { m = { { 0.00, "В эти тёмные времена мы должны помнить наших героев не хуже, чем наших врагов." }, { 5.34, "Темнолесья бы не было, если бы не подвиги отважной леди Алтеи и тех смельчаков, что сложили головы на Вороньем Холме." }, { 13.65, "Читал ли ты о Вороньем Холме? Нет? Я так и думал. История этого места была забыта, стёрта с лица земли вместе с его обитателями." }, { 23.36, "Даже в моей огромной библиотеке почти нет записей о нём." }, { 28.05, "Если найдёшь что-нибудь, что касается Вороньего Холма, принеси это мне, пожалуйста. Его жители заслуживают того, чтобы их помнили." } }, f = { { 0.00, "В эти тёмные времена мы должны помнить наших героев не хуже, чем наших врагов." }, { 5.34, "Темнолесья бы не было, если бы не подвиги отважной леди Алтеи и тех смельчаков, что сложили головы на Вороньем Холме." }, { 13.65, "Читала ли ты о Вороньем Холме? Нет? Я так и думал." }, { 17.30, "История этого места была забыта, стёрта с лица земли вместе с его обитателями." }, { 22.83, "Даже в моей огромной библиотеке почти нет записей о нём." }, { 27.52, "Если найдёшь что-нибудь, что касается Вороньего Холма, принеси это мне, пожалуйста. Его жители заслуживают того, чтобы их помнили." } } } },
    [96204] = { d = 7.9, g = 1, v = "skyborne-female", n = { x = 85 }, c = { m = { { 0.00, "Раз я на свободе, эти поганые твари пожалеют, что посмели хоть взглянуть на Ваятеля Ветра. Уходим отсюда, герой." } }, f = { { 0.00, "Раз я на свободе, эти поганые твари пожалеют, что посмели хоть взглянуть на Ваятеля Ветра. Уходим отсюда, героиня." } } }, t = { d = 28.2, v = "skyborne-female", n = { x = 329 }, c = { x = { { 0.00, "Ещё раз спасибо. Мне довелось познакомиться с Треваном – как выяснилось, именно он отправил тебя по моему следу." }, { 7.77, "До сих пор в своих странствиях я слышала о паладинах... не самые лестные вещи." }, { 12.95, "Но шен'дорай, отмеченным небом, нелегко странствовать по землям Орды, так что я прекрасно понимаю, как легко пускают корни нетерпимость и предрассудки." }, { 23.28, "У тебя и твоих собратьев теперь есть друг среди Ваятелей ветра." } } } } },
    [96243] = { d = 26.1, g = 1, v = "human-male#114", n = { m = 270, f = 272 }, c = { m = { { 0.00, "Тебе давно пора прислушаться к земле, храбрый шаман." }, { 3.87, "Стихии уже пронизывают тебя, но когда начнёшь говорить со скалами, сама земля создаст крепкий фундамент у тебя под ногами и укрепит твою душу." }, { 15.27, "Отправляйся к Тео Молотошторму в Холодную долину. Найдёшь его в Старой Наковальне, укреплении, созданном молотом, огнём и силой воли." } }, f = { { 0.00, "Тебе давно пора прислушаться к земле, храбрая шаманка." }, { 4.07, "Стихии уже пронизывают тебя, но когда начнёшь говорить со скалами, сама земля создаст крепкий фундамент у тебя под ногами и укрепит твою душу." }, { 15.47, "Отправляйся к Тео Молотошторму в Холодную долину. Найдёшь его в Старой Наковальне, укреплении, созданном молотом, огнём и силой воли." } } } },
    [96390] = { d = 18.4, v = "dwarf-male", n = { x = 213 }, c = { x = { { 0.00, "В Дун Морог проникли шпионы из клана Чёрного Железа." }, { 3.65, "Что они замышляют, я пока не знаю, но проблемы такого рода нужно решать незамедлительно." }, { 10.12, "Отправляйся на восток в мастерскую Сталекрута и убей всех шпионов из клана Чёрного Железа, которых там повстречаешь." } } }, t = { d = 20.2, v = "dwarf-male", n = { x = 231 }, c = { x = { { 0.00, "Дворфы Чёрного Железа – наши дальние родственники, но уж точно не члены семьи." }, { 5.33, "Если тех из них, кто забрёл слишком далеко от этой их проклятой горы, постигнут какие-нибудь несчастья, то слёз я проливать не стану." }, { 14.82, "Надеюсь, так у них пропадёт желание и дальше совершать набеги на эти земли." } } } } },
    [96391] = { d = 36.6, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "На карте в ваших руках изображена сложная сеть подземных туннелей и проходов, кажется, сходящихся в одной точке прямо под Стальгорном." }, { 10.22, "Что именно означают начертанные здесь руны, вы сказать не можете, так как всё написано на уродливом языке дворфов Чёрного Железа, но у вас есть определённые догадки о том, зачем всё это нужно." }, { 25.27, "Рассматривая карту, вы вдруг чувствуете порыв ветра, который доносит до вас тихий дворфийский голос." }, { 33.19, "Надо показать карту Землевидцу Фарсену." } } }, t = { d = 19.4, g = 1, v = "dwarf-male", n = { m = 225, f = 226 }, c = { m = { { 0.00, "Судя по этой карте, дворфы Чёрного Железа, похоже, планируют вторжение в склепы под Стальгорном." }, { 6.67, "Отряд, который ты разгромил на востоке, должно быть, проводил разведку." }, { 11.95, "Спасибо тебе за сведения. Если поторопимся, мы, возможно, достигнем их цели в подземелье раньше противника." } }, f = { { 0.00, "Судя по этой карте, дворфы Чёрного Железа, похоже, планируют вторжение в склепы под Стальгорном." }, { 6.67, "Отряд, который ты разгромила на востоке, должно быть, проводил разведку." }, { 11.92, "Спасибо тебе за сведения. Если поторопимся, мы, возможно, достигнем их цели в подземелье раньше противника." } } } } },
    [96392] = { d = 21.4, v = "dwarf-male", n = { x = 235 }, c = { x = { { 0.00, "Приветствую тебя! Моё имя Землевидец Фарсен, я прибыл в Дун Морог с Заоблачного пика." }, { 6.42, "В дороге я никак не мог избавиться от ощущения, что у нас... эгм... есть некоторые проблемы с дворфами из клана Чёрного Железа." }, { 14.97, "Если у тебя найдётся минутка, я разъясню, о чём толкую. Немного магии, и ты всё увидишь." } } }, t = { d = 10.8, g = 1, v = "dwarf-male", n = { m = 109, f = 110 }, c = { m = { { 0.00, "Ну что, видишь, герой? Снуют, как тараканы, и это только те, которых нам видно на поверхности." }, { 6.75, "Ты парень крепкий. Не желаешь немного посражаться?" } }, f = { { 0.00, "Ну что, видишь, героиня? Снуют, как тараканы, и это только те, которых нам видно на поверхности." }, { 6.85, "Ты девушка крепкая. Не желаешь немного посражаться?" } } } } },
    [96393] = { d = 28.4, v = "dwarf-male", n = { x = 319 }, c = { x = { { 0.00, "Собери союзников и вместе спуститесь в пещеры под Старым Стальгорном. Там войдите в Чертоги танов и пробивайтесь к нижним склепам." }, { 9.33, "Память у меня уже не та, что прежде, но вроде одно имя я ещё не забыл – Дарген Сокрушающий Молот." }, { 15.77, "Скорее всего, там он за главного. Сними его голову с плеч и принеси королю Магни Бронзобороду." }, { 22.61, "А, и передай заодно, что его старый друг Фарсен желает ему доброго здравия!" } } }, t = { d = 32.7, g = 1, v = "dwarf-male#177", n = { x = 381 }, c = { m = { { 0.00, "Вторжение Чёрного Железа – прямо у нас под ногами? Что ж, рад слышать, что с их командиром покончено." }, { 6.87, "Стража спустится вниз и разберётся с остальным сбродом." }, { 10.69, "Мы позаботимся о том, чтобы проломы заделали, а нижние ярусы укрепили, – больше никаких вторжений." }, { 17.49, "Благодарю за службу Стальгорну, герой. Прими это как скромный знак моей признательности." }, { 23.45, "Да, и если снова увидишь этого старого камнелюба Фарсена из клана Громового Молота, передай, чтобы заглянул ко мне как полагается." } }, f = { { 0.00, "Вторжение Чёрного Железа – прямо у нас под ногами? Что ж, рад слышать, что с их командиром покончено." }, { 6.87, "Стража спустится вниз и разберётся с остальным сбродом." }, { 10.69, "Мы позаботимся о том, чтобы проломы заделали, а нижние ярусы укрепили, – больше никаких вторжений." }, { 17.49, "Благодарю за службу Стальгорну, героиня. Прими это как скромный знак моей признательности." }, { 23.66, "Да, и если снова увидишь этого старого камнелюба Фарсена из клана Громового Молота, передай, чтобы заглянул ко мне как полагается." } } } } },
    [96394] = { d = 22.1, v = "dwarf-female", n = { x = 252 }, c = { x = { { 0.00, "Могилы в Чертогах танов чем-то потревожены... какие-то странные звуки доносятся из самых глубин склепов." }, { 7.00, "Духи мёртвых спят чутко, и, вероятно, там произошло нечто, что испугало их." }, { 12.55, "Отправляйся туда и посмотри, что можно сделать." }, { 15.89, "Если какие-то мертвецы и вправду пробудились – что ж, придётся тебе упокоить их снова!" } } }, t = { d = 14.0, v = "dwarf-female", n = { x = 156 }, c = { x = { { 0.00, "А, дело уже сделано? Вот и славно." }, { 2.54, "Нельзя же допустить, чтобы хранители отказывались входить в зал и выполнять свои обязанности из-за каких-то там \"призраков\" и \"разгневанных мертвецов\", не так ли?" } } } } },
    [96395] = { d = 10.1, v = "human-male#114", n = { x = 77 }, c = { x = { { 0.00, "Тан... Великий... Тан... хочет... покоя." }, { 3.28, "Молю... помоги ему... обрести... покой..." }, { 6.74, "Его гложет... древняя... злоба... Нет... покоя..." } } } },
    [96403] = { d = 26.9, g = 1, v = "gnome-male", n = { m = 303, f = 307 }, c = { m = { { 0.00, "Эй, искатель приключений!.. Мне очень нужна твоя помощь." }, { 4.16, "Едва я успел сюда проникну... то есть начать патрулирование, как на буровых машинах приехали дворфы Чёрного Железа!" }, { 11.83, "Не знаю, зачем они тут, но на кону бесценная добыча... вернее, \"важные культурные ценности\"!" }, { 17.82, "Прошу, принеси мне все реликвии, которые тебе попадутся." }, { 22.04, "Уверяю, мы всё внесём в каталог и поместим на почётное место." } }, f = { { 0.00, "Эй, искательница приключений!.. Мне очень нужна твоя помощь." }, { 4.58, "Едва я успел сюда проникну... то есть начать патрулирование, как на буровых машинах приехали дворфы Чёрного Железа!" }, { 12.25, "Не знаю, зачем они тут, но на кону бесценная добыча... вернее, \"важные культурные ценности\"!" }, { 18.24, "Прошу, принеси мне все реликвии, которые тебе попадутся." }, { 22.46, "Уверяю, мы всё внесём в каталог и поместим на почётное место." } } }, t = { d = 20.0, v = "gnome-male", n = { x = 229 }, c = { x = { { 0.00, "Ну надо же – и храбрость, и предприимчивость! Я гном слова, и награда тобой честно заработана!" }, { 6.71, "А теперь дай-ка взглянуть на добы... э-э, то есть на найденные реликвии. Нужно поскорее приступить к оценке..." }, { 13.76, "прошу прощения, к \"каталогизации\", чтобы как можно быстрее вернуть их на законные места." } } } } },
    [96408] = { d = 23.3, g = 1, v = "dwarf-male", n = { m = 269, f = 270 }, c = { m = { { 0.00, "Вчера вечером один из наших горных пехотинцев заметил костёр на восточном склоне холма." }, { 6.03, "Кажется, довольно высоко – оттуда видно всю каменоломню Гол'Болар." }, { 10.82, "Вероятно, сильно переживать не стоит, но мне хотелось бы, чтобы ты разведал тот лагерь." }, { 16.69, "Если его обитатели дружелюбны, то ничего страшного. Если же нет... Ну, ты знаешь, что делать." } }, f = { { 0.00, "Вчера вечером один из наших горных пехотинцев заметил костёр на восточном склоне холма." }, { 6.03, "Кажется, довольно высоко – оттуда видно всю каменоломню Гол'Болар." }, { 10.82, "Вероятно, сильно переживать не стоит, но мне хотелось бы, чтобы ты разведала тот лагерь." }, { 16.90, "Если его обитатели дружелюбны, то ничего страшного. Если же нет... Ну, ты знаешь, что делать." } } }, t = { d = 2.4, v = "dwarf-male", n = { x = 23 }, c = { x = { { 0.00, "Приветствую тебя! Как жизнь?" } } } } },
    [96604] = { d = 27.9, g = 1, v = "orc-male", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Приветствую, герой. Ты, похоже, один из нас, искателей приключений. Это хорошо." }, { 6.06, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.89, "Чтобы преуспевать в этом деле, тебе нужно быть в диких краях как дома." }, { 16.91, "Не знаю, насколько ты уже в этом подкован, но, возможно, смогу научить тебя паре трюков, если хочешь." }, { 24.29, "Сядь у костра поудобнее. Я тебе всё расскажу." } }, f = { { 0.00, "Приветствую, героиня. Ты, похоже, одна из нас, искателей приключений. Это хорошо." }, { 5.48, "Миру нужно больше таких неугомонных, как мы, – вечно ищущих богатство и славу." }, { 11.31, "Чтобы преуспевать в этом деле, тебе нужно быть в диких краях как дома." }, { 16.32, "Не знаю, насколько ты уже в этом подкована, но, возможно, смогу научить тебя паре трюков, если хочешь." }, { 23.71, "Сядь у костра поудобнее. Я тебе всё расскажу." } } }, t = { d = 12.3, v = "orc-male", n = { x = 142 }, c = { x = { { 0.00, "Мы изучили основы, а теперь иди поучись ремеслу у наставников в деревне поблизости." }, { 5.98, "Они даже могут показать, как обустроить лагерь в соответствии с твоей новой профессией." } } } } },
