    [96659] = { d = 29.1, g = 1, v = "tauren-male#67", n = { m = 232, f = 234 }, c = { m = { { 0.00, "Подожди. У меня есть ещё одна просьба, прежде чем ты нас покинешь." }, { 7.33, "Рядом с деревней Кровавого Копыта разбила лагерь искательница приключений по имени Кага Дикое Копыто." }, { 17.35, "Она сильно мне помогла в прошлом, и теперь у меня есть возможность отплатить ей. Не мог бы ты отнести ей эти припасы?" } }, f = { { 0.00, "Подожди. У меня есть ещё одна просьба, прежде чем ты нас покинешь." }, { 7.33, "Рядом с деревней Кровавого Копыта разбила лагерь искательница приключений по имени Кага Дикое Копыто." }, { 17.35, "Она сильно мне помогла в прошлом, и теперь у меня есть возможность отплатить ей. Не могла бы ты отнести ей эти припасы?" } } }, t = { d = 23.5, g = 1, v = "tauren-female", n = { m = 186, f = 190 }, c = { m = { { 0.00, "Тебя послал вождь Соколиный Ветер? Я ещё тогда сказала ему, что мне не нужна никакая плата, но он, похоже, не послушал. Спасибо, герой." }, { 13.24, "Слушай, а ты на вид такой же искатель приключений, как я. Не хочешь поучиться премудростям походной жизни?" } }, f = { { 0.00, "Тебя послал вождь Соколиный Ветер? Я ещё тогда сказала ему, что мне не нужна никакая плата, но он, похоже, не послушал. Спасибо, героиня." }, { 13.46, "Слушай, а ты на вид такая же искательница приключений, как я. Не хочешь поучиться премудростям походной жизни?" } } } } },
