    [96821] = { d = 22.3, v = "troll-male#78", n = { x = 262 }, c = { x = { { 0.00, "Со стороны Колючего Холма приходит всё меньше и меньше путников." }, { 4.36, "Дорога и так была не самая приятная из-за скорпидов, так теперь ходят слухи, что вдоль неё появились гнёзда пауков." }, { 12.55, "Если отправишься куда-нибудь на север, убей хоть сколько-то пауков по пути." }, { 17.55, "И сообщи Колючему Холму, что теперь сюда будет безопасней ходить." } } }, t = { d = 8.1, g = 1, v = "orc-male#60", n = { m = 89, f = 90 }, c = { m = { { 0.00, "Батраки уже давно боятся ходить на юг. Теперь, когда ты немного расчистил путь, мы можем снова занять их делом." } }, f = { { 0.00, "Батраки уже давно боятся ходить на юг. Теперь, когда ты немного расчистила путь, мы можем снова занять их делом." } } } } },
    [96822] = { d = 22.3, v = "orc-male#60", n = { x = 259 }, c = { x = { { 0.00, "Мы потеряли много отважных воинов, когда разоряли крепость Тирагард." }, { 4.70, "Теперь люди возвели в руинах новые укрепления, и мы не можем собрать останки, чтобы почтить память погибших." }, { 12.48, "Ступай в руины, окружающие крепость, и разыщи оружие, оставленное нашими павшими братьями и сёстрами." }, { 19.43, "Мы выставим его на почётном месте." } } }, t = { d = 4.1, v = "orc-male#60", n = { x = 43 }, c = { x = { { 0.00, "Этих воинов никогда не забудут. И всё благодаря тебе." } } } } },
    [96825] = { d = 28.0, v = "orc-male", n = { x = 312 }, c = { x = { { 0.00, "Охотники и рыбаки приносят нашим бойцам достаточно мяса – а вот шанса поесть чего-то сладкого у них давно не было." }, { 8.46, "Я знаю кактус, на котором вырастают колючие, но вкусные плоды." }, { 12.92, "Вот только растут эти кактусы среди холмов на западе, совсем рядом с лагерями мерзких свинобразов." }, { 19.95, "Ты уж постарайся их обойти и добудь мне те фрукты. Только осторожно: фрукты такие же колючие, как свинобразы!" } } }, t = { d = 10.2, v = "orc-male", n = { x = 113 }, c = { x = { { 0.00, "Я приготовлю из этих фруктов кое-что вкусное, а семена оставлю – потом посадим." }, { 5.53, "Когда-нибудь колючие груши будут расти по всему Оргриммару!" } } } } },
    [96873] = { d = 26.7, v = "troll-female#75", n = { x = 327 }, c = { x = { { 0.00, "Тролли на востоке отсюда потеряли волю и полностью подчинились знахарю Залазану." }, { 5.46, "Он сохраняет контроль над жертвами с помощью разных жестоких чар, но его излюбленный приём – заставлять их носить подвески, зачарованные злыми связывающими заклинаниями." }, { 16.96, "Потренируйся в зачаровывании, рассеяв магию этих подвесок, а после принеси мне результат." }, { 22.81, "И если тебе дорога свобода, ни за что их не надевай!" } } }, t = { d = 8.7, v = "troll-female#75", n = { x = 86 }, c = { x = { { 0.00, "Отличная работа. Жаль убитых троллей, но теперь, когда подчиняющие чары сняты, их духи смогут упокоиться." } } } } },
    [96874] = { d = 26.3, g = 1, v = "orc-male", n = { m = 260, f = 261 }, c = { m = { { 0.00, "Ты видел, какие здоровенные звери бродят по Громовому хребту?" }, { 4.36, "Думаю, из гребней у них на спине получилось бы славное лезвие топора. Сару поднял меня на смех, когда я ему это сказал... Но что он вообще знает?!" }, { 15.55, "Помоги-ка мне – в рамках обучения кузнечному делу! Принеси несколько гребней и шлифовальных камней, чтобы их заточить." } }, f = { { 0.00, "Ты видела, какие здоровенные звери бродят по Громовому хребту?" }, { 4.41, "Думаю, из гребней у них на спине получилось бы славное лезвие топора. Сару поднял меня на смех, когда я ему это сказал... Но что он вообще знает?!" }, { 15.60, "Помоги-ка мне – в рамках обучения кузнечному делу! Принеси несколько гребней и шлифовальных камней, чтобы их заточить." } } }, t = { d = 7.7, v = "orc-male", n = { x = 82 }, c = { x = { { 0.00, "Эти шипы оказались прочнее, чем я ожидал! Работать с ними будет не так просто, как я думал... но я не сдамся!" } } } } },
    [96875] = { d = 25.4, g = 1, v = "orc-female#57", n = { x = 280 }, c = { m = { { 0.00, "Оргриммар постоянно растёт, герой. И когда батракам нужны шкуры, чтобы обить стены и крыши новых домов, они приходят ко мне!" }, { 9.25, "Шкуры ящеров с Громового хребта обычно слишком толстые для брони, зато из них получается отличный стройматериал." }, { 17.36, "Принеси мне эти шкуры, а также несколько обработанных шкур полегче. Посмотрим, как ты умеешь работать с кожей!" } }, f = { { 0.00, "Оргриммар постоянно растёт, героиня. И когда батракам нужны шкуры, чтобы обить стены и крыши новых домов, они приходят ко мне!" }, { 9.28, "Шкуры ящеров с Громового хребта обычно слишком толстые для брони, зато из них получается отличный стройматериал." }, { 17.38, "Принеси мне эти шкуры, а также несколько обработанных шкур полегче. Посмотрим, как ты умеешь работать с кожей!" } } }, t = { d = 6.0, v = "orc-female#57", n = { x = 63 }, c = { x = { { 0.00, "Твоя работа помогает Оргриммару расти. Помни об этом, шагая по улицам города." } } } } },
    [96876] = { d = 4.1, v = "human-male#114", n = { x = 39 }, c = { x = { { 0.00, "Вдоль клапана сумки грубовато вышито имя \"Укор\"." } } }, t = { d = 9.8, g = 1, v = "orc-male", n = { m = 93, f = 95 }, c = { m = { { 0.00, "Моя сума! Когда я бросил её, удирая от того огромного паука, думал, что больше никогда её не увижу. Ты настоящий герой!" } }, f = { { 0.00, "Моя сума! Когда я бросил её, удирая от того огромного паука, думал, что больше никогда её не увижу. Ты настоящая героиня!" } } } } },
    [96877] = { d = 5.7, v = "human-male#114", n = { x = 58 }, c = { x = { { 0.00, "Это огромное копыто – доказательство вашей победы над могучим ящером." } } }, t = { d = 4.1, g = 1, v = "orc-female#57", n = { x = 34 }, c = { m = { { 0.00, "Вот это трофей, герой! Наверняка бой был что надо!" } }, f = { { 0.00, "Вот это трофей, героиня! Наверняка бой был что надо!" } } } } },
    [96895] = { d = 34.4, g = 1, v = "scourge-male", n = { m = 368, f = 369 }, c = { m = { { 0.00, "Не знаю, слышал ты или нет, но недавно здесь проходили два посланника Серебряного Рассвета." }, { 6.82, "У меня нет проблем с этим орденом, но это не значит, что его агентам можно хозяйничать в Тирисфале без присмотра." }, { 15.21, "Они оба были Отрёкшимися... но мне всё равно это не нравится." }, { 20.05, "Один из них только что отправился отсюда на юго-восток. Там на окраинах города действует группа сектантов Плети." }, { 28.51, "Если посланники узнали про сектантов, то наверняка заинтересовались ими." } }, f = { { 0.00, "Не знаю, слышала ты или нет, но недавно здесь проходили два посланника Серебряного Рассвета." }, { 6.98, "У меня нет проблем с этим орденом, но это не значит, что его агентам можно хозяйничать в Тирисфале без присмотра." }, { 15.37, "Они оба были Отрёкшимися... но мне всё равно это не нравится." }, { 20.21, "Один из них только что отправился отсюда на юго-восток. Там на окраинах города действует группа сектантов Плети." }, { 28.67, "Если посланники узнали про сектантов, то наверняка заинтересовались ими." } } }, t = { d = 6.2, g = 1, v = "scourge-male", n = { x = 59 }, c = { m = { { 0.00, "Пригнись и постарайся не высовываться, герой. С этими сектантами шутки плохи." } }, f = { { 0.00, "Пригнись и постарайся не высовываться, героиня. С этими сектантами шутки плохи." } } } } },
    [96896] = { d = 35.1, v = "scourge-male", n = { x = 374 }, c = { x = { { 0.00, "Мы с Данитой вместе защищали Подгород, когда напали твари из Наксрамаса." }, { 5.50, "В тот день мы потеряли многих добрых друзей, среди которых был герой, в честь которого эта крепость и получила своё имя – Гарека Бандариона." }, { 16.16, "Возможно, он оказался первым Отрёкшимся, заново научившимся использовать силы Света как паладин." }, { 23.30, "Здорово было бы, если бы его наследие передалось здесь Даните и её подчинённым." }, { 30.16, "Если бы только остальные Отрёкшиеся разделяли мои устремления..." } } }, t = { d = 19.9, v = "scourge-male", n = { x = 222 }, c = { x = { { 0.00, "Я собираюсь задержаться здесь ненадолго и поговорить ещё кое с кем из друзей, но скоро вернусь в часовню Последней Надежды в Восточных Чумных землях." }, { 10.85, "Если вдруг окажешься в тех краях, обязательно загляни. Помощь крепких искателей приключений нам никогда не помешает." } } } } },
    [96897] = { d = 18.5, v = "scourge-male", n = { x = 189 }, c = { x = { { 0.00, "Плеть – чума на теле нашей земли, а её живые слуги – худшие из всех." }, { 5.05, "Жители Тирисфаля выбиваются из сил, разрываясь между безмозглыми мертвецами и Алым орденом." }, { 12.72, "Если хочешь сделать доброе дело, помоги мне разделаться с этой мерзостью." } } }, t = { d = 12.9, g = 1, v = "scourge-male", n = { x = 112 }, c = { m = { { 0.00, "Спасибо за помощь, герой. Если мы не хотим, чтобы история Лордерона повторилась, нужно быть начеку всякий раз, когда возникает подобная угроза." } }, f = { { 0.00, "Спасибо за помощь, героиня. Если мы не хотим, чтобы история Лордерона повторилась, нужно быть начеку всякий раз, когда возникает подобная угроза." } } } } },
    [96898] = { d = 34.6, v = "scourge-male", n = { x = 365 }, c = { x = { { 0.00, "Ещё не так давно этому городу угрожала цитадель Наксрамас, стремившаяся стереть Отрёкшихся с лица земли." }, { 7.74, "И Отрёкшиеся, и Серебряный Рассвет тогда принесли огромные жертвы, чтобы обеспечить Отрёкшимся будущее." }, { 16.52, "В той битве фокусирующий кристалл некротической энергии, подвешенный под Наксрамасом, был разбит, а его осколки разбросаны по округе." }, { 27.00, "Полагаю, они-то и были нужны сектантам. Помоги мне вернуть эти фрагменты, вырвав их из рук Плети." } } }, t = { d = 14.6, v = "scourge-male", n = { x = 157 }, c = { x = { { 0.00, "Спасибо. Это должно замедлить Плеть в здешних краях." }, { 3.97, "Подозреваю, жители Тирисфаля будут выкапывать эти кристаллы из земли ещё долгие годы, но убрать хотя бы самые заметные из них уже неплохо." } } } } },
    [96899] = { d = 38.0, g = 1, v = "scourge-male", n = { m = 398, f = 399 }, c = { m = { { 0.00, "Сегодня ты оказал Серебряному Рассвету огромную услугу, и я очень благодарен за это." }, { 6.28, "Уж не знаю, многое ли тебе известно о крепости Бандариона, но мы с командиром как раз направлялись туда на встречу с тамошним командованием." }, { 16.48, "Это было ещё до того, как нам стало известно о присутствии культа Проклятых." }, { 23.06, "Если ты хочешь узнать больше о Серебряном Рассвете и нашей миссии, разыщи моего командира в крепости Бандариона – это к северо-западу отсюда." }, { 34.37, "Я же пока останусь здесь наводить порядок." } }, f = { { 0.00, "Сегодня ты оказала Серебряному Рассвету огромную услугу, и я очень благодарен за это." }, { 6.44, "Уж не знаю, многое ли тебе известно о крепости Бандариона, но мы с командиром как раз направлялись туда на встречу с тамошним командованием." }, { 16.65, "Это было ещё до того, как нам стало известно о присутствии культа Проклятых." }, { 23.23, "Если ты хочешь узнать больше о Серебряном Рассвете и нашей миссии, разыщи моего командира в крепости Бандариона – это к северо-западу отсюда." }, { 34.29, "Я же пока останусь здесь наводить порядок." } } }, t = { d = 31.6, v = "scourge-male", n = { x = 334 }, c = { x = { { 0.00, "Это место полно воспоминаний для меня. Когда-то здесь стоял Серебряный Рассвет." }, { 5.97, "Отсюда мы готовились ко многим битвам и стычкам с Плетью во время её последнего наступления на Тирисфальские леса." }, { 14.82, "Когда мы отступили в Чумные земли, я боялся, что крепость придёт в запустение." }, { 20.70, "Опасения оправдались, но я рад, что теперь о ней заботятся Данита и её паладины." }, { 27.10, "Она даже назвала крепость в честь... нашего общего друга." } } } } },
    [97003] = { d = 38.0, g = 1, v = "orc-male", n = { m = 358, f = 358 }, c = { m = { { 0.00, "Эй, герой. Нужна твоя помощь. До нас дошли слухи о чудище, поселившемся в пещере на Тернистом холме, к северо-востоку отсюда." }, { 10.58, "Свинобразы из племени Иглогривых зовут его Чол'арук или \"Стервятник\"." }, { 15.31, "Говорят, он в пять раз больше обычного свинобраза и особенно кровожаден." }, { 20.66, "Многие не верят этим историям. А вот я верю: потому что уже сражался с такими." }, { 26.41, "Найди логово Чол'арука и убей его. Принеси мне его голову. Но не ходи один и хорошо подготовься. Кровь и гром, герой." } }, f = { { 0.00, "Эй, героиня. Нужна твоя помощь. До нас дошли слухи о чудище, поселившемся в пещере на Тернистом холме, к северо-востоку отсюда." }, { 11.30, "Свинобразы из племени Иглогривых зовут его Чол'арук или \"Стервятник\"." }, { 16.03, "Говорят, он в пять раз больше обычного свинобраза и особенно кровожаден." }, { 21.39, "Многие не верят этим историям. А вот я верю: потому что уже сражался с такими." }, { 27.14, "Найди логово Чол'арука и убей его. Принеси мне его голову. Но не ходи одна и хорошо подготовься. Кровь и гром, героиня." } } }, t = { d = 17.7, g = 1, v = "orc-male", n = { m = 196, f = 197 }, c = { m = { { 0.00, "Впечатляет, герой. Теперь, когда я вернусь в Оргриммар с этим мрачным доказательством существования таких чудовищ, никто не усомнится в моих рассказах." }, { 10.31, "Но будь уверен: эта слава принадлежит тебе, и я буду громко говорить о твоих подвигах. Лок-тар!" } }, f = { { 0.00, "Впечатляет, героиня. Теперь, когда я вернусь в Оргриммар с этим мрачным доказательством существования таких чудовищ, никто не усомнится в моих рассказах." }, { 10.60, "Но будь уверена: эта слава принадлежит тебе, и я буду громко говорить о твоих подвигах. Лок-тар!" } } } } },
    [97005] = { d = 35.7, v = "human-male", n = { x = 402 }, c = { x = { { 0.00, "Ходят слухи, что в пещере на северо-западе отсюда, на Тернистом холме, поселилось страшное чудище." }, { 6.83, "Свинобразы из племени Иглогривых зовут его Чол'арук или \"Стервятник\". Говорят, он такой огромный, что может целиком проглотить орка." }, { 16.25, "Мало кто верит в такие россказни, зато верю я... потому что и сам сражался с подобным чудовищем." }, { 22.72, "Эта тварь должна умереть – ради чести товарищей, которых я тогда потерял." }, { 27.97, "Собери могучих союзников и отыщи логово Чол'арука. Убей эту мерзкую тварь и принеси мне её голову." } } }, t = { d = 12.6, g = 1, v = "human-male", n = { m = 143, f = 145 }, c = { m = { { 0.00, "Моим павшим воинам будет спокойнее от того, что в мире стало на одно такое чудовище меньше." }, { 6.26, "Ты отлично справился – истинный и стойкий защитник Альянса. Спасибо. Ступай с честью." } }, f = { { 0.00, "Моим павшим воинам будет спокойнее от того, что в мире стало на одно такое чудовище меньше." }, { 6.26, "Ты отлично справилась – истинная и стойкая защитница Альянса. Спасибо. Ступай с честью." } } } } },
    [97220] = { d = 25.2, v = "human-male#114", n = { x = 255 }, c = { x = { { 0.00, "На этой неделе у нас постоянно не хватает грузчиков." }, { 4.51, "Не хочешь помочь нам справиться с нагрузкой?" }, { 8.26, "Отнеси это к входу в хранилище вестибюля. Это в магазине \"Сыры Триаса\", на втором этаже. Хозяйка, Илана, привыкла к таким доставкам." }, { 18.37, "В вестибюль часто тайно доставляют грузы, – эдакий ритуальный сюрприз от руководства." } } }, t = { d = 8.2, g = 1, v = "human-female#112", n = { m = 93, f = 94 }, c = { m = { { 0.00, "Ох, батюшки. Думаешь, мы сами потащим это вверх по лестнице? Пока ты не передал груз, за его сохранность отвечаешь ты." } }, f = { { 0.00, "Ох, батюшки. Думаешь, мы сами потащим это вверх по лестнице? Пока ты не передала груз, за его сохранность отвечаешь ты." } } } } },
    [97222] = { d = 25.6, g = 1, v = "human-female#112", n = { m = 291, f = 292 }, c = { m = { { 0.00, "Да, да, нужно всего лишь подняться по лестнице. Но раз уж это так просто, то можешь сделать это и сам!" }, { 7.21, "\"Сыры Триаса\" не считаются частью вестибюля, и у нас с ними раздельный инвентарь. Мы лишь находимся в одном здании." }, { 15.08, "Поставь ящик рядом со входом в хранилище, его, как обычно, заберёт стражник." }, { 20.24, "Он увидит доставку и занесёт её внутрь, когда будет возвращаться на пост." } }, f = { { 0.00, "Да, да, нужно всего лишь подняться по лестнице. Но раз уж это так просто, то можешь сделать это и сама!" }, { 7.34, "\"Сыры Триаса\" не считаются частью вестибюля, и у нас с ними раздельный инвентарь. Мы лишь находимся в одном здании." }, { 15.20, "Поставь ящик рядом со входом в хранилище, его, как обычно, заберёт стражник." }, { 20.37, "Он увидит доставку и занесёт её внутрь, когда будет возвращаться на пост." } } } },
    [97223] = { d = 30.1, v = "troll-female#75", n = { x = 350 }, c = { x = { { 0.00, "Всех ящеров, которых ты тут видишь, я объезжала лично." }, { 3.65, "Их собрали со всего Калимдора, но зачастую лучшие ящеры – это кровопалые с островов, что недалеко от наших берегов." }, { 11.69, "Матриарх кровопалых отличается особой свирепостью." }, { 15.04, "Она лишила жизни многих из нашей деревни и стала слишком опасной, чтобы оставлять её у нас на границе." }, { 21.95, "Если сможешь убить её, то принеси мне её яйца – так мы сможем вырастить вылупившихся ящеров как союзников." } } }, t = { d = 10.7, g = 1, v = "troll-female#75", n = { m = 116, f = 117 }, c = { m = { { 0.00, "Спасибо. Я рада, что мы сможем сохранить породу и вырастить этих ящеров, сделав их нашими союзниками." }, { 7.51, "Ты оказал нашему племени большую услугу." } }, f = { { 0.00, "Спасибо. Я рада, что мы сможем сохранить породу и вырастить этих ящеров, сделав их нашими союзниками." }, { 7.51, "Ты оказала нашему племени большую услугу." } } } } },
    [97225] = { d = 38.7, v = "troll-male", n = { x = 359 }, c = { x = { { 0.00, "Когда мы бежали с островов, которые захватил Залазан и ему подобные, нам пришлось бросить много драгоценных идолов." }, { 9.51, "Они помогали нам общаться с духами, которым мы поклоняемся, – нашими лоа. Для нашего племени они невероятно ценны." }, { 19.94, "Последователи Залазана не почитают наших лоа и разбросали идолов по самому крупному из островов." }, { 28.25, "Если мы не соберём их, жди беды – оскорблять лоа нельзя." }, { 33.14, "Иди и собери как можно больше идолов лоа и принеси их мне." } } }, t = { d = 17.5, g = 1, v = "troll-male#77", n = { m = 186, f = 187 }, c = { m = { { 0.00, "Ты сегодня сделал для нашего племени подвиг." }, { 3.74, "В отличие от некоторых других племён, наша связь с лоа основывается на почитании и уважении, и мы им многим обязаны." }, { 12.66, "Не хотелось бы, чтоб племя Чёрного Копья утратило их расположение." } }, f = { { 0.00, "Ты сегодня сделала для нашего племени подвиг." }, { 3.48, "В отличие от некоторых других племён, наша связь с лоа основывается на почитании и уважении, и мы им многим обязаны." }, { 12.40, "Не хотелось бы, чтоб племя Чёрного Копья утратило их расположение." } } } } },
    [97234] = { d = 22.9, v = "human-male", n = { x = 265 }, c = { x = { { 0.00, "Ты здесь, чтобы обсудить тайный смысл наших легенд? Нет?" }, { 4.22, "Что ж, когда закончишь осматриваться, можешь отнести вот это в библиотеку?" }, { 9.33, "Мы обмениваем некоторые менее популярные работы на более современные книги." }, { 14.49, "У меня есть список фолиантов, которые можно достать в библиотеке." }, { 19.25, "Если поможешь, угостим тебя напитком бесплатно." } } }, t = { d = 21.4, v = "human-male", n = { x = 246 }, c = { x = { { 0.00, "Так, посмотрим. Книжный клуб Роя, верно? Узнаю эту манеру заворачивать." }, { 5.36, "Что ж, если он говорит, что именно об этом люди хотят беседовать, я не против." }, { 10.56, "Книги к нам всегда возвращаются в том же состоянии, в каком мы их выдали, – значит, там с ними обращаются бережно, какими бы провокационными ни были слова внутри." } } } } },
    [97236] = { d = 11.8, v = "human-male#114", n = { x = 125 }, c = { x = { { 0.00, "Свежий образец от паука таких размеров – настоящая находка." }, { 4.56, "Возможно, этим клыком заинтересуется кто-то, занимающийся изучением пауков в Альдрассиле." } } }, t = { d = 7.9, v = "human-male#114", n = { x = 79 }, c = { x = { { 0.00, "Надо же! Обожаю сюрпризы." }, { 2.36, "Вне всяких сомнений, этот экземпляр пригодится для моих исследований." } } } } },
    [97237] = { d = 31.3, v = "human-male", n = { x = 356 }, c = { x = { { 0.00, "Я проверил записи, и все книги, которые попросил господин Льюэлс, сейчас доступны." }, { 6.12, "Тебе, правда, придётся самостоятельно взять их с полок. Работа библиотекаря – следить за библиотекой, и я не могу отвлекаться." }, { 15.08, "Также уведомляю, что ты не будешь отвечать за возврат книг, которые доставишь Рою." }, { 20.85, "В записке говорится, что ты сейчас официально являешься курьером книжного клуба, а значит, вся ответственность будет лежать на нём. Хорошего дня." } } }, t = { d = 17.9, g = 1, v = "human-male", n = { m = 198, f = 199 }, c = { m = { { 0.00, "Это они! Некоторые даже пахнут экзотикой! Великолепно, жду не дождусь оживлённых бесед об этих сочинениях." }, { 7.69, "В погребе, после закрытия, разумеется." }, { 10.67, "Спасибо, что так быстро обернулся. Как и обещали, угощение за счёт заведения. Мы своё слово держим." } }, f = { { 0.00, "Это они! Некоторые даже пахнут экзотикой! Великолепно, жду не дождусь оживлённых бесед об этих сочинениях." }, { 7.69, "В погребе, после закрытия, разумеется." }, { 10.67, "Спасибо, что так быстро обернулась. Как и обещали, угощение за счёт заведения. Мы своё слово держим." } } } } },
    [97242] = { d = 26.1, v = "orc-male#127", n = { x = 290 }, c = { x = { { 0.00, "Йелмак хочет, чтобы его ученик наконец-то перестал всё портить." }, { 4.70, "Он сказал, что его подмастерье слишком горд, чтобы попросить о помощи, даже когда она ему необходима." }, { 11.57, "И хочет дать ему попробовать кое-какое наше зелье." }, { 15.15, "Срежь камыш и копьё-траву, растущие у воды на Аллее Чести." }, { 19.66, "Я бы и сам мог это сделать, но если я уйду из магазина, Вуут наверняка что-то заподозрит." } } }, t = { d = 24.3, v = "orc-male#127", n = { x = 233 }, c = { x = { { 0.00, "Такие камыш и копьё-трава растут только в Оргриммаре." }, { 4.66, "Они пьют родниковую воду с гор Азшары и питаются минеральной пылью нашей каменистой земли, пропитанной потом и кровью, – в этих травах скрыта немалая сила." }, { 18.72, "Я отдам их Йелмаку – может, наглядный урок поможет ему вернуть доверие Вуута." } } } } },
    [97243] = { d = 24.4, v = "skyborne-female#3773", n = { x = 286 }, c = { x = { { 0.00, "Хотя мы в Небесной выси, это всё ещё обитель стихий. Духи всех четырёх стихий говорят с нами, если мы готовы слушать." }, { 7.75, "Один из нас, Ваятелей ветра, находится в особенно крепкой связи со стихией огня – шен'дорай по имени Олариан Быстрая Вспышка." }, { 16.88, "Отнеси это ему в святилище пламени в Ветроягодных низинах. Оно находится на краю острова, к западу от Валанаара." } } }, t = { d = 10.4, g = 1, v = "skyborne-male", n = { m = 105, f = 107 }, c = { m = { { 0.00, "Значит, ты принёс факел. Да, юный герой, я могу научить тебя внимать зову огня." }, { 5.90, "Это будет нелегко, но в обители стихий ничто не даётся легко." } }, f = { { 0.00, "Значит, ты принесла факел. Да, юная героиня, я могу научить тебя внимать зову огня." }, { 5.64, "Это будет нелегко, но в обители стихий ничто не даётся легко." } } } } },
    [97244] = { d = 32.0, v = "skyborne-male", n = { x = 367 }, c = { x = { { 0.00, "Среди ал'акетов есть жрец небес по имени Фаладиэль." }, { 3.80, "Когда-то он был призывателем пламени и верным Ваятелем ветра, но, как и многие ал'акеты, променял верность на могущество." }, { 11.83, "Теперь его руки запятнаны кровью бывших братьев и сестёр." }, { 16.09, "Ты найдёшь жреца небес Фаладиэля на ферме к северо-востоку, за Валанааром, чуть к югу от святилища Акира. Убей этого предателя." }, { 25.38, "Принеси мне его сердце. Дело грязное, но необходимое для ритуала, который мы должны провести." } } }, t = { d = 18.5, v = "skyborne-male", n = { x = 217 }, c = { x = { { 0.00, "Ваятели ветра ничего не забывают, и за кровь всегда платят кровью." }, { 4.52, "Я рад, что тебе удалось преподнести этому предателю последнее, мучительное напоминание о нашем кредо." }, { 11.75, "Но не только это сердце будет питать пламя сегодня. Есть ещё одно дело, которое нужно завершить." } } } } },
    [97245] = { d = 28.3, v = "skyborne-male", n = { x = 330 }, c = { x = { { 0.00, "Обитатели Шен'дарского нагорья рассказывают о древнем лесном духе по имени Курамаа." }, { 5.67, "Говорят, он живёт в пне на вершине холма, рядом с опорным столпом." }, { 10.40, "Отправляйся на нагорье и отыщи этот пень. Постучи по нему кулаком, и Курамаа явится." }, { 16.14, "Одолей духа в бою и принеси мне его деревянную маску." }, { 20.11, "Но имей в виду: это существо будет невосприимчиво к большей части твоей магии. Лишь прикосновение огня упокоит духа." } } }, t = { d = 5.8, v = "skyborne-male", n = { x = 66 }, c = { x = { { 0.00, "Теперь у нас есть всё необходимое. Мы зажжём Вечное пламя и воззовём к духам огня." } } } } },
    [97246] = { d = 39.2, v = "orc-male#60", n = { x = 414 }, c = { x = { { 0.00, "Мой сын Миги целыми днями играет со своими друзьями." }, { 3.82, "Постоянно говорю ему, чтобы не забыл забрать у Борстана свой обед, но знаю наверняка, что он этого почти никогда не делает, потому что приходит домой голодным." }, { 16.97, "Вот ведь дети пошли – думают, будто игры важнее, чем здоровое питание!" }, { 22.22, "Прошу, зайди в \"Жаровню Борстана\" и скажи, что доставишь обед Миги." }, { 26.68, "Самого Миги ты почти наверняка найдёшь за крепостью Громмаш, как и всех его друзей." }, { 32.95, "У меня здесь много работы, поэтому я не могу каждый раз следить, пообедал он или нет." } } }, t = { d = 20.9, v = "orc-male", n = { x = 228 }, c = { x = { { 0.00, "Всё верно, мы с родителями Миги договорились, что я буду каждый день передавать ему готовый обед." }, { 6.98, "Но не могу же я сделать так, чтобы мальчишка получил свою еду, если он за ней не приходит." }, { 13.71, "Иногда он по несколько дней в неделю тут не появляется. Откуда у него только берутся силы на игры?" } } } } },
    [97249] = { d = 38.2, v = "orc-male", n = { x = 425 }, c = { x = { { 0.00, "Теперь, когда я узнал, что родители Миги беспокоятся о его питании, у меня появилась идея." }, { 6.71, "Мы с ними договорились, что я не буду готовить для него одно и то же каждый день, чтобы он привыкал к разнообразной пище." }, { 15.19, "Но он всегда приходит в одно и то же время: когда коптильня полна мяса и мы делаем бутерброды со свиной грудинкой в сладкой глазури." }, { 24.56, "Мы начали крошить остатки мяса в хрустящей глазури – этим можно посыпать другие блюда хоть каждый день." }, { 32.13, "Отнеси ему. Может быть, тогда он будет приходить пораньше и звать с собой друзей!" } } }, t = { d = 28.8, g = 1, v = "child-male", n = { m = 349, f = 353 }, c = { m = { { 0.00, "Мясо от Борстана? Ты принёс это кому-то из нас? О!" }, { 3.52, "Ого... как здорово пахнет! Вкуснятина." }, { 6.37, "Спасибо, что принёс мой обед. Я могу по запаху определить, что Борстан будет готовить сегодня, когда мы с друзьями идём мимо по пути к крепости Громмаш." }, { 15.63, "Это похоже на мою любимую сладкую глазурь! Но... как-то по-другому. Мне очень нравятся эти кусочки." }, { 22.00, "Если он будет каждый день делать такую вкуснятину, нам придётся прерывать игру, чтобы вместе обедать!" } }, f = { { 0.00, "Мясо от Борстана? Ты принесла это кому-то из нас? О!" }, { 3.87, "Ого... как здорово пахнет! Вкуснятина." }, { 6.72, "Спасибо, что принесла мой обед. Я могу по запаху определить, что Борстан будет готовить сегодня, когда мы с друзьями идём мимо по пути к крепости Громмаш." }, { 15.95, "Это похоже на мою любимую сладкую глазурь! Но... как-то по-другому. Мне очень нравятся эти кусочки." }, { 22.32, "Если он будет каждый день делать такую вкуснятину, нам придётся прерывать игру, чтобы вместе обедать!" } } } } },
    [97250] = { d = 27.9, v = "orc-male#60", n = { x = 315 }, c = { x = { { 0.00, "Ты случайно не путешествуешь к Пылевым топям?" }, { 3.28, "До меня дошли слухи, что несколько солдат-людей заняли позицию на их границе и громят памятные места, которые остались со времён тауренов-первопроходцев." }, { 14.36, "Говорят, они сожгли дотла знаменитую таверну. А потом по-альянсовски свалили вину на Орду!" }, { 20.77, "Не знаю, сколько тут правды, но я не потерплю вторжения на НАШИ земли. Сначала казнь, потом суд!" } } } },
    [97253] = { d = 38.6, v = "goblin-male", n = { x = 407 }, c = { x = { { 0.00, "Эй, на минутку." }, { 1.54, "Короче говоря, у нас проблема с пиратами. Кого я только ни посылал с ними разобраться – никто не вернулся назад." }, { 9.18, "Тогда я подумал: а если послать машину? Оказалось, ятаганы раскручивают запчасти не сильно хуже отвёрток." }, { 17.21, "Не успел я направить машину домой, как она превратилась в кучу железок и разлетелась по всему их лагерю!" }, { 24.79, "Мне нужно вернуть детали. Причём это всего лишь коротенькая вылазка за трофеями, так что твои шансы на выживание наверняка НАМНОГО выше, чем в предыдущие разы. Ну чё?" } } } },
    [97257] = { d = 24.6, v = "skyborne-male", n = { x = 289 }, c = { x = { { 0.00, "Теперь мы проведём ритуал." }, { 2.07, "Я помещу всё необходимое на алтарь и воззову к духам огня. Если они примут наше подношение, то явятся и зажгут Вечное пламя." }, { 10.49, "Тогда тебе нужно будет поднести к нему свой факел." }, { 14.17, "Отнеси зажжённый факел в Валанаар и помести его в жаровню Вечного пламени." }, { 19.14, "Но поторопись – пламя Огненных Просторов быстро гаснет здесь, в Небесной выси." } } }, t = { d = 18.9, v = "skyborne-female#3773", n = { x = 221 }, c = { x = { { 0.00, "Готово. Вечное пламя полыхает вновь." }, { 2.69, "Твоё испытание окончено, и я с радостью передаю тебе твой тотэм огня. Используй его с умом в своих странствиях." }, { 10.29, "И помни: огонь обители стихий служит тем, кто обращается с ним уважительно, и пожирает тех, кто этого не делает. Таков наш путь." } } } } },
    [97263] = { d = 17.3, v = "gnome-male", n = { x = 0 }, c = { x = { { 0.00, "У почтового ящика лежит несколько потерянных посылок." }, { 3.79, "Вы замечаете, что одна из них помечена как предназначенная для доставки из Заоблачного пика в Стальгорн и адресована Элдруну Тучегону. На посылке стоит штамп \"срочно\"." } } }, t = { d = 28.7, g = 1, v = "dwarf-male", n = { m = 312, f = 314 }, c = { m = { { 0.00, "Что?! Я каждый день ходил к почтовому ящику у банка за этой посылкой! Пора бы этому городу разобраться со своей планировкой." }, { 8.43, "Тут тебе не Заоблачный пик – поди разберись!" }, { 11.81, "Посмотрим, что тут у нас... инструменты для резьбы тотэмов... запасной топор... какое-то гоблинское устройство?" }, { 18.98, "Я такого не заказывал! Ладно, отправлю обратно." }, { 22.73, "Э-э... то есть... спасибо, что принёс мне всё это. Вот тебе кое-что за труды." } }, f = { { 0.00, "Что?! Я каждый день ходил к почтовому ящику у банка за этой посылкой! Пора бы этому городу разобраться со своей планировкой." }, { 8.43, "Тут тебе не Заоблачный пик – поди разберись!" }, { 11.81, "Посмотрим, что тут у нас... инструменты для резьбы тотэмов... запасной топор... какое-то гоблинское устройство?" }, { 18.98, "Я такого не заказывал! Ладно, отправлю обратно." }, { 22.73, "Э-э... то есть... спасибо, что принесла мне всё это. Вот тебе кое-что за труды." } } } } },
    [97275] = { d = 37.2, v = "orc-male", n = { x = 386 }, c = { x = { { 0.00, "У Вуута есть талант, это бесспорно. Но ему не хватает опыта, мудрости и практики в работе у котла." }, { 8.99, "Он думает, что может делать всё по-своему." }, { 12.42, "Вуут расходует все редкие и экзотические ингредиенты, которые у нас есть, вместо того чтобы тренироваться и оттачивать базовые навыки." }, { 22.39, "Я тут по-быстрому приготовил одно снадобье. Пожалуйста, отнеси его Вууту." }, { 28.08, "Он задумается, всё ли делает правильно, когда поймёт, что первейший ключ к мастерству – это знание местных трав и осторожность." } } }, t = { d = 29.3, g = 1, v = "orc-male", n = { m = 312, f = 313 }, c = { m = { { 0.00, "Грорру... чего?" }, { 1.43, "Говоришь, Йелмак сварил это зелье из копьё-травы и камыша, без всяких других реагентов?" }, { 7.56, "Я и не думал, что химикам могут по-настоящему пригодиться эти обычные травы, которые мы видим каждый день." }, { 15.47, "Может, он и прав. Наверное, я многое упускаю, сразу берясь за самые редкие и малоизученные растения." }, { 22.97, "Выбери себе одно из зелий, что я сварил раньше. Спасибо, что заглянул в нашу лавку." } }, f = { { 0.00, "Грорру... чего?" }, { 1.43, "Говоришь, Йелмак сварил это зелье из копьё-травы и камыша, без всяких других реагентов?" }, { 7.56, "Я и не думал, что химикам могут по-настоящему пригодиться эти обычные травы, которые мы видим каждый день." }, { 15.47, "Может, он и прав. Наверное, я многое упускаю, сразу берясь за самые редкие и малоизученные растения." }, { 22.97, "Выбери себе одно из зелий, что я сварил раньше. Спасибо, что заглянула в нашу лавку." } } } } },
    [97277] = { d = 37.5, v = "dwarf-male", n = { x = 428 }, c = { x = { { 0.00, "Я отвернулся проследить за тем, как дожаривается вепрь, и тут мой приятель Гозвин завопил как резаный!" }, { 7.45, "А когда развернулся, успел разглядеть только расплывчатое пятно и жуткие клыки. А ещё лапищи – здоровенные такие!" }, { 15.21, "Это снежный леопард утаскивал моего друга. Я тут же схватил дробовик и выстрелил над головой у зверя. Тот выпустил Гозвина и убежал." }, { 24.62, "К счастью, бедняга отделался лишь парой глубоких порезов." }, { 28.97, "Сходи-ка в наш лагерь на северо-западных холмах и принеси его журнал механика. А если попадётся тот леопард, убей его!" } } }, t = { d = 21.4, v = "dwarf-male", n = { x = 243 }, c = { x = { { 0.00, "Так и знал, что леопард захочет полакомиться нашим жареным вепрем!" }, { 4.86, "Теперь, когда журнал у него, Гозвин будет поменьше волноваться. Надеюсь, эта малая радость поможет ему встать на ноги." }, { 13.29, "Спасибо. Прими этот пустяк в знак моей благодарности – за то, что сходил за журналом и сделал эти холмы безопаснее." } } } } },
    [97279] = { d = 38.1, v = "orc-male#60", n = { x = 440 }, c = { x = { { 0.00, "С наплывом новобранцев вроде тебя нам стало трудно обеспечивать всех оружием." }, { 5.39, "У нашего оружейника, Кзана, заканчивается запас учебного оружия, и я хочу узнать, какие у тебя есть навыки, чтобы понять, с кем приходится иметь дело." }, { 15.81, "К счастью для тебя, я знаю, как разом решить оба этих вопроса." }, { 20.54, "Пока набиваешь кулаки на кабанах, найди шесть образцов брошенного тренировочного оружия." }, { 26.60, "Они так и остались валяться на земле, брошенные бестолковыми новобранцами." }, { 31.87, "Как только сделаешь это, верни их нашему оружейнику Кзану – он в Логове позади меня." } } }, t = { d = 6.8, g = 1, v = "orc-male", n = { m = 70, f = 71 }, c = { m = { { 0.00, "Спасибо, что вернул оружие. Я займусь его починкой для следующей группы новобранцев." } }, f = { { 0.00, "Спасибо, что вернула оружие. Я займусь его починкой для следующей группы новобранцев." } } } } },
    [97281] = { d = 26.6, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Перед вами странная сфера с тусклой поверхностью. Приподняв её, вы чувствуете ритмичные электрические импульсы." }, { 8.56, "При ближайшем рассмотрении кажется, что внутри клубится тёмный туман и время от времени мелькают маленькие искры." }, { 17.72, "Совершенно ясно, что гарпия использовала эту сферу для какой-то цели. Возможно, эта вещь заинтересует Резлака." } } }, t = { d = 9.2, g = 1, v = "goblin-male", n = { m = 94, f = 94 }, c = { m = { { 0.00, "Ого, где ты нашёл такую занятную штуку? Знаешь, она напоминает мне ещё кое-что, что мне вечно повторял мой босс Газлоу..." } }, f = { { 0.00, "Ого, где ты нашла такую занятную штуку? Знаешь, она напоминает мне ещё кое-что, что мне вечно повторял мой босс Газлоу..." } } } } },
    [97282] = { d = 31.3, v = "goblin-male", n = { x = 351 }, c = { x = { { 0.00, "\"Резлак, никогда не упускай подвернувшейся возможности\". Этой мудрости меня научил Газлоу, и я собираюсь воспользоваться его советом." }, { 9.51, "Похоже, эта сфера цела – просто разрядилась. Но у меня есть мыслишка, как восстановить её мощь!" }, { 16.40, "В ущелье к западу отсюда водится много рокочущих ящериц." }, { 20.42, "У них есть органы, удерживающие сильный электрический заряд, и они идеально подходят для наших целей." }, { 27.94, "Сходи собери органы ящериц и принеси мне!" } } }, t = { d = 22.4, g = 1, v = "goblin-male", n = { m = 242, f = 245 }, c = { m = { { 0.00, "Эй, спасибо, дружище! Ты мне здорово помог, и я это ценю." }, { 4.24, "Будем надеяться, что с помощью этих органов я смогу зарядить её." }, { 8.73, "Спорим, эти никчёмные гарпии дважды подумают, прежде чем снова нападать на мой караван. Очень надеюсь, что сработает." }, { 17.18, "В любом случае свою часть сделки ты выполнил. Вот, держи за труды." } }, f = { { 0.00, "Эй, спасибо, дружище! Ты мне здорово помогла, и я это ценю." }, { 4.50, "Будем надеяться, что с помощью этих органов я смогу зарядить её." }, { 8.99, "Спорим, эти никчёмные гарпии дважды подумают, прежде чем снова нападать на мой караван. Очень надеюсь, что сработает." }, { 17.44, "В любом случае свою часть сделки ты выполнила. Вот, держи за труды." } } } } },
    [97288] = { d = 18.0, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Когда существо обрушивается на землю, его голова отделяется от тела." }, { 5.16, "Похоже, её присоединяли уже несколько раз, и с каждым разом связь становилась слабее." }, { 12.02, "Кто-нибудь в Подгороде наверняка знает что-то об этом необычном поганище." } } }, t = { d = 10.4, v = "scourge-male", n = { x = 100 }, c = { x = { { 0.00, "Ого! Кажется, я знаю эту голову. Жестокая шутка нашей Тёмной Госпожи. И при этом восхитительная. Думаю, я найду ей применение." } } } } },
    [97289] = { d = 33.1, v = "scourge-male", n = { x = 349 }, c = { x = { { 0.00, "Мы регулярно изготавливаем головы поганищ, но эта – особенная." }, { 5.02, "Когда-то она принадлежала особенно мерзкому главнокомандующему из Альянса. Тёмная Госпожа лично его прикончила." }, { 13.81, "Если бы эта голова могла говорить, она бы поведала нам так много интересных тайн! И мы дадим ей эту возможность." }, { 22.10, "Нужно лишь присоединить её к подходящему телу." }, { 25.98, "Положи голову рядом со свободным телом в соседней комнате. Но не присоединяй её. Пока что." } } }, t = { d = 6.9, v = "scourge-male", n = { x = 2 }, c = { x = { { 0.00, "Тело дёргается и оживает, в панике переживая заново свои последние мгновения. Ты..." } } } } },
    [97290] = { d = 4.2, v = "named/271613", n = { x = 34 }, c = { x = { { 0.00, "Ты... чудовище... С чего бы... помогать тебе... Прочь..." } } }, t = { d = 5.2, v = "named/271613", n = { x = 47 }, c = { x = { { 0.00, "Не желаешь сотрудничать, да? Прекрасно. Обожаю трудности." } } } } },
    [97291] = { d = 38.8, v = "scourge-male", n = { x = 419 }, c = { x = { { 0.00, "Теперь, когда мы вернули чудищу голову, осталось лишь подчинить его воле Тёмной Госпожи. Это будет просто." }, { 7.92, "Оно и так уже почти ничего не соображает после стольких трепок. Нужно лишь дать ему мотивацию." }, { 15.40, "Принеси мне ядовитую черепоганку от госпожи Гризетт из Торгового квартала." }, { 21.04, "Ещё жгуч-траву от Альестаров, местных учителей травничества. У них передо мной должок, так что они отдадут тебе траву бесплатно." }, { 30.64, "Ну и наконец, нужно немного субстанции агонии. Её можно найти у любого торговца ядами. Будем варить зелье!" } } }, t = { d = 11.1, v = "scourge-male", n = { x = 103 }, c = { x = { { 0.00, "Это отлично подойдёт. Посмотрим, сколько бравады останется у нашего почётного гостя после того, как он испробует мой шедевр." } } } } },
    [97292] = { d = 23.9, v = "scourge-male", n = { x = 247 }, c = { x = { { 0.00, "Я приготовил замечательную сыворотку, которая непременно подарит нашему гостю... острые ощущения." }, { 7.46, "Держи. Подлей это в механизм у него над головой. Попробуем продемонстрировать, почему в его интересах – верно служить нам." }, { 17.63, "И постарайся не пролить. Поиски нового помощника обойдутся мне слишком дорого." } } }, t = { d = 17.5, v = "scourge-male", n = { x = 168 }, c = { x = { { 0.00, "Превосходно. Пусть его плоть немного потомится. Дадим ему время привыкнуть к новому дому." }, { 8.39, "Пока что этот жалкий тип мне больше не нужен, но мы будем за ним приглядывать. У меня большие планы на будущее Отмара." } } } } },
    [97326] = { d = 27.2, g = 1, v = "child-female", n = { m = 334, f = 336 }, c = { m = { { 0.00, "Эй! У тебя есть время нам помочь! Я знаю, что есть. Я видела, как ты улыбался, когда смотрел на нашу игру." }, { 7.19, "Нам нравится этот участок за крепостью Громмаш, потому что тут есть место, где расставить фигурки." }, { 13.04, "Одна беда – нам не хватает камней, на которые можно было бы сесть или поставить что-нибудь." }, { 18.72, "Ты большой и сильный... можешь, пожалуйста, принести нам камней? Больших и гладких, чтобы на них можно было присесть и отдохнуть." } }, f = { { 0.00, "Эй! У тебя есть время нам помочь! Я знаю, что есть. Я видела, как ты улыбалась, когда смотрела на нашу игру." }, { 7.87, "Нам нравится этот участок за крепостью Громмаш, потому что тут есть место, где расставить фигурки." }, { 13.72, "Одна беда – нам не хватает камней, на которые можно было бы сесть или поставить что-нибудь." }, { 19.40, "Ты большая и сильная... можешь, пожалуйста, принести нам камней? Больших и гладких, чтобы на них можно было присесть и отдохнуть." } } } },
    [97485] = { d = 41.3, v = "tauren-male", n = { x = 364 }, c = { x = { { 0.00, "Да благословит тебя Ан'ше." }, { 2.74, "У нас, тауренов, есть традиция развеивать благовония по ветру. Я надеюсь, ты тоже захочешь почтить её." }, { 13.22, "Тебе нужно будет смешать благовония, купив травы у Ниды, кедр у Наты, нить из жил у Маху на центральном холме." }, { 22.85, "А Наал на верхнем холме продаст тебе огниво и кремень." }, { 27.24, "Когда соберёшь эти предметы, совмести их и развей на Вершине охотников, над утёсом, что смотрит на юг." }, { 36.45, "На месте проведения церемонии будет коврик и благовония." } } } },
    [97538] = { d = 40.8, v = "tauren-male#67", n = { x = 343 }, c = { x = { { 0.00, "Приветствую! Можно попросить тебя об одолжении?" }, { 4.66, "У меня закончился красный пигмент для красок, и мне нужна помощь кого-то помоложе, кто отправился бы в далёкие Когтистые горы вместо меня." }, { 18.38, "На горном перевале есть большое круглое озеро, которое называют Мутным, и в его водах растёт уникальное растение – лихолист." }, { 30.30, "Высушенные стручки лихолиста приобретают ярко-красный цвет. Собери их для меня, и я щедро тебя вознагражу." } } } },
    [97558] = { d = 49.4, v = "scourge-female#80", n = { x = 451 }, c = { x = { { 0.00, "Одна из особенностей жизни после смерти, о которой никто не упоминает, – это то, что происходит, когда мы получаем ранения. Как заживает кожа у нежити? Да никак." }, { 15.08, "Вся наша жизнь – проклятие. Мы продлеваем своё существование, отнимая у живых." }, { 22.12, "Когда мы получаем ранение, кожу приходится заменять, для чего обычно используются шкуры животных." }, { 30.54, "Поскольку шкуры разной толщины лучше подходят для определённых участков на теле, ключ к успеху – разнообразие!" }, { 40.10, "Принеси мне перепонки крыльев сумеречницы, шкуры псов тьмы и кожу мурлока из племени Злобного Плавника." } } }, t = { d = 8.6, g = 1, v = "scourge-female#80", n = { m = 72, f = 74 }, c = { m = { { 0.00, "Превосходно! Спасибо, что принёс мне эти материалы. Обещаю найти им хорошее применение." } }, f = { { 0.00, "Превосходно! Спасибо, что принесла мне эти материалы. Обещаю найти им хорошее применение." } } } } },
    [97583] = { d = 27.4, v = "human-male#114", n = { x = 0 }, c = { x = { { 0.00, "Маленькая слизь, похоже, в восторге и пытается повторять ваши движения, пока вы танцуете." }, { 6.90, "Однако вскоре она начинает выглядеть утомлённой." }, { 10.89, "Маленькая слизь зависает над лужицей ила и впитывает её, немного приободрившись." }, { 17.56, "Кажется, все эти танцы её совсем вымотали. Может быть, кто-нибудь в каналах Подгорода продаёт ещё такого питательного ила?" } } } },
    [97891] = { d = 32.9, g = 1, v = "scourge-male", n = { m = 289, f = 290 }, c = { m = { { 0.00, "Эй, ты! Мне нужно, чтобы ты поскорее доставил это зелье доктору Мартину Фелбену в Район Фармацевтов, по ту сторону потока слизи!" }, { 10.54, "У зелья очень ограниченный срок годности, и нет, я сам не смогу – у меня кости гремят и ноги сразу ломаются, стоит мне только побежать." }, { 20.89, "Такой вот \"приятный\" побочный эффект жизни после смерти." }, { 25.48, "Но мы теряем время! Вот, бери зелье – и вперёд! Алессандро отгоняет вас жестом." } }, f = { { 0.00, "Эй, ты! Мне нужно, чтобы ты поскорее доставила это зелье доктору Мартину Фелбену в Район Фармацевтов, по ту сторону потока слизи!" }, { 10.65, "У зелья очень ограниченный срок годности, и нет, я сам не смогу – у меня кости гремят и ноги сразу ломаются, стоит мне только побежать." }, { 21.00, "Такой вот \"приятный\" побочный эффект жизни после смерти." }, { 25.59, "Но мы теряем время! Вот, бери зелье – и вперёд! Алессандро отгоняет вас жестом." } } }, t = { d = 21.9, g = 1, v = "scourge-male", n = { m = 205, f = 206 }, c = { m = { { 0.00, "А, чудесно! Я как раз ждал зелье Алессандро." }, { 4.34, "Последние шесть, что он посылал, разложились по дороге, но ты успел как раз вовремя!" }, { 11.01, "Вот, возьми за труды. На этом всё, если у тебя нет ко мне других дел." }, { 16.54, "А если нет – ступай, чтобы я мог спокойно продолжить эксперименты." } }, f = { { 0.00, "А, чудесно! Я как раз ждал зелье Алессандро." }, { 4.34, "Последние шесть, что он посылал, разложились по дороге, но ты успела как раз вовремя!" }, { 11.09, "Вот, возьми за труды. На этом всё, если у тебя нет ко мне других дел." }, { 16.62, "А если нет – ступай, чтобы я мог спокойно продолжить эксперименты." } } } } },
    [97894] = { d = 42.2, v = "dwarf-male#98", n = { x = 465 }, c = { x = { { 0.00, "Душевно рад познакомиться! Звать меня Боргус, я из единственной и неповторимой семьи Сталеруков." }, { 7.29, "Со Сталеруками ты всегда можешь рассчитывать на выгодную и честную сделку!" }, { 14.09, "Несколько недель назад мой брат Горбольд открыл торговую лавку в Аубердине." }, { 19.39, "На снабжении тамошних кораблей можно целое состояние сколотить, уж поверь мне! Вот уж повезло так повезло." }, { 26.89, "С тех пор я не получал от него весточки – может, заглянешь его проведать, если тебе будет по пути?" }, { 33.83, "Тут в порту новый корабль стоит, который идёт как раз туда. Ступай на самый южный причал, ты его точно не пропустишь!" } } }, t = { d = 15.2, v = "dwarf-male#99", n = { x = 171 }, c = { x = { { 0.00, "Тебя старина Борги послал? Он всегда за меня переживает." }, { 4.42, "Лишняя пара рук здесь нам точно не помешает." }, { 7.53, "Из-за недавней трагедии дела почти совсем встали, но, мне кажется, ты сможешь помочь нам исправить положение." } } } } },
    [97899] = { d = 21.2, g = 1, v = "orc-male", n = { m = 229, f = 230 }, c = { m = { { 0.00, "Значит, ты решил готовить отвары и зелья, став алхимиком. Не сомневаюсь, что это будет полезно в твоих странствиях." }, { 8.42, "И думаю, что я знаю кое-кого, кто может научить тебя создавать в лагере колодец маны." }, { 14.42, "К тебе сразу выстроится очередь из целителей и колдунов, желающих из него напиться." } }, f = { { 0.00, "Значит, ты решила готовить отвары и зелья, став алхимиком. Не сомневаюсь, что это будет полезно в твоих странствиях." }, { 8.45, "И думаю, что я знаю кое-кого, кто может научить тебя создавать в лагере колодец маны." }, { 14.45, "К тебе сразу выстроится очередь из целителей и колдунов, желающих из него напиться." } } }, t = { d = 24.4, g = 1, v = "orc-male", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Вот, держи – теперь ты знаешь, как создать собственный колодец маны." }, { 4.70, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 12.10, "Без костра никакого лагеря не получится – с него всё и начинается. Этому тебя может научить почти любой повар." }, { 19.95, "Если ещё не освоил азы, обратись к наставнику кулинарии." } }, f = { { 0.00, "Вот, держи – теперь ты знаешь, как создать собственный колодец маны." }, { 4.70, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 12.10, "Без костра никакого лагеря не получится – с него всё и начинается. Этому тебя может научить почти любой повар." }, { 19.95, "Если ещё не освоила азы, обратись к наставнику кулинарии." } } } } },
