    [97914] = { d = 39.6, g = 1, v = "nightelf-male#54", n = { x = 443 }, c = { m = { { 0.00, "Аубердин – непримечательное место, герой. Под дарнасскими ветвями никому до него нет дела." }, { 6.18, "Большинство обсуждает лишь руины некогда процветавших городов, разрушенных Расколом – Амет'Аран, Башал'Аран и... Латар'Лазал." }, { 14.57, "Но Аубердин продолжает существовать в их тени." }, { 18.16, "Я хочу, чтобы о нашей работе узнали." }, { 20.82, "Недавно к нам начал ходить корабль из королевства Штормград, приносящий к нашим берегам путешественников и припасы." }, { 28.78, "Прошу, отправляйся на этом корабле в Штормград и отнеси это письмо человеку по имени Барос Алекстон. Пусть мир узнает о нашем доме." } }, f = { { 0.00, "Аубердин – непримечательное место, героиня. Под дарнасскими ветвями никому до него нет дела." }, { 6.95, "Большинство обсуждает лишь руины некогда процветавших городов, разрушенных Расколом – Амет'Аран, Башал'Аран и... Латар'Лазал." }, { 15.33, "Но Аубердин продолжает существовать в их тени." }, { 18.93, "Я хочу, чтобы о нашей работе узнали." }, { 21.58, "Недавно к нам начал ходить корабль из королевства Штормград, приносящий к нашим берегам путешественников и припасы." }, { 29.54, "Прошу, отправляйся на этом корабле в Штормград и отнеси это письмо человеку по имени Барос Алекстон. Пусть мир узнает о нашем доме." } } }, t = { d = 5.7, v = "human-male", n = { x = 0 }, c = { x = { { 0.00, "Барос открывает письмо и начинает читать. Улыбка постепенно сходит с его лица." } } } } },
