    [97926] = { d = 25.7, g = 1, v = "human-male", n = { x = 277 }, c = { m = { { 0.00, "Честное слово, герой, я был бы рад помочь, но это не так просто." }, { 4.89, "Если ты проведёшь немного времени в наших землях, ты увидишь, что многие живут в бедности." }, { 11.08, "Штормградская казна почти опустела, и остатков ресурсов едва хватает нам самим." }, { 17.02, "Передай мой ответ старейшине, когда увидишь его в следующий раз. Это не те вести, которых он ждёт, но других у меня нет." } }, f = { { 0.00, "Честное слово, героиня, я был бы рад помочь, но это не так просто." }, { 4.94, "Если ты проведёшь немного времени в наших землях, ты увидишь, что многие живут в бедности." }, { 11.13, "Штормградская казна почти опустела, и остатков ресурсов едва хватает нам самим." }, { 17.07, "Передай мой ответ старейшине, когда увидишь его в следующий раз. Это не те вести, которых он ждёт, но других у меня нет." } } }, t = { d = 12.3, g = 1, v = "nightelf-male#54", n = { m = 131, f = 132 }, c = { m = { { 0.00, "Печальные вести. И всё же спасибо, что проделал этот путь." }, { 4.81, "Раз ни Штормград, ни Дарнас не придут нам на помощь, похоже, судьбу Аубердина нам предстоит решать самим." } }, f = { { 0.00, "Печальные вести. И всё же спасибо, что проделала этот путь." }, { 4.83, "Раз ни Штормград, ни Дарнас не придут нам на помощь, похоже, судьбу Аубердина нам предстоит решать самим." } } } } },
