    [97928] = { d = 24.5, g = 1, v = "tauren-female", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Так ты решил стать кузнецом? Отличный выбор, если хочешь, чтобы твои клинки никогда не затупились." }, { 8.08, "Сдаётся мне, я знаю кое-кого, кто может тебе помочь и научить создавать круг для заточки." }, { 15.39, "Установишь такой у себя в лагере – отбоя не будет от воинов и разбойников, которым надо заточить оружие." } }, f = { { 0.00, "Так ты решила стать кузнецом? Отличный выбор, если хочешь, чтобы твои клинки никогда не затупились." }, { 8.44, "Сдаётся мне, я знаю кое-кого, кто может тебе помочь и научить создавать круг для заточки." }, { 15.75, "Установишь такой у себя в лагере – отбоя не будет от воинов и разбойников, которым надо заточить оружие." } } }, t = { d = 32.1, g = 1, v = "tauren-male", n = { m = 306, f = 307 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственный круг для заточки." }, { 4.75, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 12.86, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 22.13, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственный круг для заточки." }, { 4.75, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 12.79, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 21.31, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
    [97929] = { d = 27.8, v = "tauren-female", n = { x = 277 }, c = { x = { { 0.00, "Зачаровыватели делают всё лучше, и их привечают в любом походном лагере." }, { 6.36, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать зачарованную лютню для своего лагеря." }, { 14.51, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы, какие только могут встретиться в странствиях." } } } },
    [97930] = { d = 28.2, v = "tauren-female", n = { x = 281 }, c = { x = { { 0.00, "Инженеры вроде тебя могут конструировать всяческие приблуды, прибамбасы и бомбы, чтобы развлекаться и зарабатывать." }, { 9.80, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать реагентобота для лагеря." }, { 17.07, "Этот славный автоматон помогает с припасами, чтобы у тебя и твоих союзников всегда были материалы, необходимые для ваших заклинаний." } } } },
    [97931] = { d = 27.9, g = 1, v = "tauren-female", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Ты решил стать специалистом по первой помощи? Для героя это ответственный и... прагматичный выбор." }, { 8.33, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для лагеря." }, { 16.02, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } }, f = { { 0.00, "Ты решила стать специалистом по первой помощи? Для героини это ответственный и... прагматичный выбор." }, { 8.49, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для лагеря." }, { 16.19, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } } }, t = { d = 30.8, g = 1, v = "tauren-female#71", n = { m = 309, f = 310 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственный набор первой помощи." }, { 4.85, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 13.05, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 20.83, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботился этим, обратись к кому-нибудь из них." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственный набор первой помощи." }, { 4.85, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Это лучше делать на природе." }, { 12.97, "Да, и помни, что без костра никакого лагеря не получится. Так что сначала придётся разжечь костёр." }, { 20.70, "Этому тебя может научить почти любой специалист по кулинарии. Если ещё не озаботилась этим, обратись к кому-нибудь из них." } } } } },
