    [97933] = { d = 34.4, v = "tauren-female", n = { x = 346 }, c = { x = { { 0.00, "Ты, похоже, уже многое знаешь о травничестве. Собирать цветы – не просто развлечение. Это занятие может быть полезным... и весьма прибыльным." }, { 11.36, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать ароматную свечу для лагеря." }, { 18.71, "Чтобы целители и заклинатели достойно показывали себя в бою, им нужно правильное состояние духа, и ароматические свечи в этом здорово помогают." }, { 30.15, "Все знакомые заклинатели будут тебе благодарны." } } }, t = { d = 31.1, g = 1, v = "tauren-male#133", n = { m = 319, f = 320 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственную ароматную свечу." }, { 4.91, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 14.41, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 23.73, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственную ароматную свечу." }, { 4.91, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 14.41, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 23.73, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
    [97934] = { d = 22.9, g = 1, v = "tauren-female", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Ты стал кожевником. Отличное решение, герой." }, { 4.04, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать палатку, которая поможет охладиться в жаркий день и не промокнуть под дождём." }, { 15.62, "С ней ты сможешь хорошо отдыхать, чтобы всегда быть начеку во время странствий." } }, f = { { 0.00, "Ты стала кожевником. Отличное решение, героиня." }, { 4.33, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать палатку, которая поможет охладиться в жаркий день и не промокнуть под дождём." }, { 16.11, "С ней ты сможешь хорошо отдыхать, чтобы всегда быть начеку во время странствий." } } }, t = { d = 39.1, g = 1, v = "tauren-male#67", n = { m = 313, f = 314 }, c = { m = { { 0.00, "Вот и всё – теперь у тебя есть собственная лагерная палатка." }, { 5.81, "В городах палатки лучше не ставить, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 17.91, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 29.57, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь у тебя есть собственная лагерная палатка." }, { 5.81, "В городах палатки лучше не ставить, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 17.94, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 29.59, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
    [97935] = { d = 27.4, v = "tauren-female", n = { x = 269 }, c = { x = { { 0.00, "Горное дело не для белоручек, но это честная работа и отличный выбор профессии." }, { 6.76, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать магнетит для лагеря." }, { 13.65, "С ним все, кто привык размахивать мечом, соберутся у твоего костра, чтобы проникнуться силой минерала и почувствовать себя готовыми ко всему. Суеверие, но помогает же!" } } } },
    [97936] = { d = 33.4, v = "tauren-female", n = { x = 335 }, c = { x = { { 0.00, "Умение быстро снимать с убитых зверей кожи и шкуры – один из наиболее полезных навыков для любого искателя приключений." }, { 9.96, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать удобный стул для лагеря." }, { 16.97, "Иногда очень важно, чтобы было где расслабиться, – а из шкур, которые ты добываешь, можно скроить очень удобное сиденье." }, { 26.54, "Благодаря этому ты точно будешь в форме, когда придёт время для следующей потасовки." } } } },
    [97937] = { d = 24.7, g = 1, v = "tauren-female", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 8.06, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умел для этого." }, { 17.92, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } }, f = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 8.06, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умела для этого." }, { 17.97, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } } } },
    [97938] = { d = 20.1, g = 1, v = "nightelf-female#53", n = { m = 229, f = 230 }, c = { m = { { 0.00, "Значит, ты решил готовить отвары и зелья, став алхимиком. Не сомневаюсь, что это будет полезно в твоих странствиях." }, { 8.11, "И думаю, что я знаю кое-кого, кто может научить тебя создавать в лагере колодец маны." }, { 13.99, "К тебе сразу выстроится очередь из целителей и колдунов, желающих из него напиться." } }, f = { { 0.00, "Значит, ты решила готовить отвары и зелья, став алхимиком. Не сомневаюсь, что это будет полезно в твоих странствиях." }, { 8.32, "И думаю, что я знаю кое-кого, кто может научить тебя создавать в лагере колодец маны." }, { 14.20, "К тебе сразу выстроится очередь из целителей и колдунов, желающих из него напиться." } } } },
    [97939] = { d = 20.1, g = 1, v = "nightelf-female#53", n = { m = 235, f = 236 }, c = { m = { { 0.00, "Так ты решил стать кузнецом? Отличный выбор, если хочешь, чтобы твои клинки никогда не затупились." }, { 6.97, "Сдаётся мне, я знаю кое-кого, кто может тебе помочь и научить создавать круг для заточки." }, { 13.01, "Установишь такой у себя в лагере – отбоя не будет от воинов и разбойников, которым надо заточить оружие." } }, f = { { 0.00, "Так ты решила стать кузнецом? Отличный выбор, если хочешь, чтобы твои клинки никогда не затупились." }, { 6.79, "Сдаётся мне, я знаю кое-кого, кто может тебе помочь и научить создавать круг для заточки." }, { 12.83, "Установишь такой у себя в лагере – отбоя не будет от воинов и разбойников, которым надо заточить оружие." } } } },
    [97940] = { d = 20.8, v = "nightelf-female#53", n = { x = 243 }, c = { x = { { 0.00, "Зачаровыватели делают всё лучше, и их привечают в любом походном лагере." }, { 5.39, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать зачарованную лютню для своего лагеря." }, { 12.18, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы в пути." } } } },
    [97941] = { d = 23.6, v = "nightelf-female#53", n = { x = 281 }, c = { x = { { 0.00, "Инженеры вроде тебя могут конструировать всяческие приблуды, прибамбасы и бомбы, чтобы развлекаться и зарабатывать." }, { 8.18, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать реагентобота для лагеря." }, { 14.19, "Этот славный автоматон помогает с припасами, чтобы у тебя и твоих союзников всегда были материалы, необходимые для ваших заклинаний." } } } },
    [97942] = { d = 24.5, g = 1, v = "nightelf-female#53", n = { m = 268, f = 269 }, c = { m = { { 0.00, "Ты решил стать специалистом по первой помощи? Для героя это ответственный и... прагматичный выбор." }, { 6.91, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для лагеря." }, { 13.41, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } }, f = { { 0.00, "Ты решила стать специалистом по первой помощи? Для героини это ответственный и... прагматичный выбор." }, { 7.80, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для лагеря." }, { 14.31, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } } } },
    [97943] = { d = 22.0, g = 1, v = "nightelf-female#53", n = { m = 252, f = 254 }, c = { m = { { 0.00, "Ты, может, об этом не задумывался, но навыки рыбной ловли могут очень пригодиться в лагере." }, { 6.31, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать аквариум для лагеря." }, { 12.02, "Он порадует тебя и других искателей приключений, ведь даже простые радости могут сделать нас сильнее." }, { 18.99, "Уверена, ты и сам в этом убедишься." } }, f = { { 0.00, "Ты, может, об этом не задумывалась, но навыки рыбной ловли могут очень пригодиться в лагере." }, { 6.53, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать аквариум для лагеря." }, { 12.24, "Он порадует тебя и других искателей приключений, ведь даже простые радости могут сделать нас сильнее." }, { 19.22, "Уверена, ты и сама в этом убедишься." } } } },
    [97944] = { d = 29.2, v = "nightelf-female#53", n = { x = 346 }, c = { x = { { 0.00, "Ты, похоже, уже многое знаешь о травничестве. Собирать цветы – не просто развлечение. Это занятие может быть полезным... и весьма прибыльным." }, { 9.71, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать ароматную свечу для лагеря." }, { 15.84, "Чтобы целители и заклинатели достойно показывали себя в бою, им нужно правильное состояние духа, и ароматические свечи в этом здорово помогают." }, { 25.62, "Все знакомые заклинатели будут тебе благодарны." } } } },
    [97946] = { d = 19.0, g = 1, v = "nightelf-female#53", n = { m = 210, f = 211 }, c = { m = { { 0.00, "Ты стал кожевником. Отличное решение, герой." }, { 3.10, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать палатку, которая поможет охладиться в жаркий день и не промокнуть под дождём." }, { 13.08, "С ней ты сможешь хорошо отдыхать, чтобы всегда быть начеку во время странствий." } }, f = { { 0.00, "Ты стала кожевником. Отличное решение, героиня." }, { 3.59, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать палатку, которая поможет охладиться в жаркий день и не промокнуть под дождём." }, { 13.57, "С ней ты сможешь хорошо отдыхать, чтобы всегда быть начеку во время странствий." } } } },
    [97948] = { d = 23.3, v = "nightelf-female#53", n = { x = 269 }, c = { x = { { 0.00, "Горное дело не для белоручек, но это честная работа и отличный выбор профессии." }, { 5.84, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать магнетит для лагеря." }, { 11.62, "С ним все, кто привык размахивать мечом, соберутся у твоего костра, чтобы проникнуться силой минерала и почувствовать себя готовыми ко всему. Суеверие, но помогает же!" } } } },
    [97949] = { d = 28.5, v = "nightelf-female#53", n = { x = 335 }, c = { x = { { 0.00, "Умение быстро снимать с убитых зверей кожи и шкуры – один из наиболее полезных навыков для любого искателя приключений." }, { 8.54, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать удобный стул для лагеря." }, { 14.45, "Иногда очень важно, чтобы было где расслабиться, – а из шкур, которые ты добываешь, можно скроить очень удобное сиденье." }, { 22.46, "Благодаря этому ты точно будешь в форме, когда придёт время для следующей потасовки." } } }, t = { d = 27.2, g = 1, v = "nightelf-male#55", n = { m = 318, f = 319 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственный лагерный стул." }, { 4.17, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 12.72, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.00, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственный лагерный стул." }, { 4.17, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 12.72, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.00, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
    [97950] = { d = 20.8, g = 1, v = "nightelf-female#53", n = { m = 239, f = 240 }, c = { m = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 6.84, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умел для этого." }, { 15.02, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } }, f = { { 0.00, "Портняжное дело – на удивление полезный навык, который, не сомневаюсь, будет часто тебя выручать." }, { 6.84, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умела для этого." }, { 15.17, "В любой битве боевой дух очень важен, и вдохновляющее знамя может его поднять." } } }, t = { d = 27.2, g = 1, v = "nightelf-female#52", n = { m = 324, f = 325 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственное развевающееся знамя." }, { 4.44, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 12.95, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.10, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственное развевающееся знамя." }, { 4.44, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 12.95, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.10, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
