    [97965] = { d = 23.6, g = 1, v = "skyborne-male", n = { m = 274, f = 275 }, c = { m = { { 0.00, "Ты решил стать специалистом по первой помощи? Для героя это ответственный и... прагматичный выбор." }, { 6.80, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для твоего лагеря." }, { 13.64, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } }, f = { { 0.00, "Ты решила стать специалистом по первой помощи? Для героини это ответственный и... прагматичный выбор." }, { 6.99, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать набор первой помощи для твоего лагеря." }, { 13.82, "Для искателей приключений травмы неизбежны, и если у тебя в лагере будет всё необходимое для лечения, это может даже спасти кому-нибудь жизнь." } } }, t = { d = 29.7, g = 1, v = "skyborne-female", n = { m = 355, f = 356 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственный набор первой помощи." }, { 4.19, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Лучше отправляйся куда-нибудь в дикие места." }, { 12.18, "А, и помни, что никакого лагеря без костра не получится. Так что сначала придётся разжечь костёр." }, { 18.51, "Этому тебя может научить почти любой специалист по кулинарии." }, { 22.66, "Если ещё не озаботился этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственный набор первой помощи." }, { 4.19, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Лучше отправляйся куда-нибудь в дикие места." }, { 12.18, "А, и помни, что никакого лагеря без костра не получится. Так что сначала придётся разжечь костёр." }, { 18.51, "Этому тебя может научить почти любой специалист по кулинарии." }, { 22.70, "Если ещё не озаботилась этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } } } } },
