    [97971] = { d = 29.6, v = "skyborne-male", n = { x = 355 }, c = { x = { { 0.00, "Способность умело снимать с убитых зверей кожи и шкуры – один из наиболее полезных навыков для любого искателя приключений." }, { 8.65, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать лагерный стул для твоего лагеря." }, { 15.14, "Иногда очень важно, чтобы было где расслабиться, а из шкур, которые ты собираешь, можно изладить очень удобное место для сидения." }, { 23.74, "Благодаря этому ты точно будешь в форме, когда придёт время для следующей потасовки." } } }, t = { d = 31.0, g = 1, v = "skyborne-male", n = { m = 350, f = 351 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственный лагерный стул. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 8.60, "Лучше отправляйся куда-нибудь в дикие места." }, { 11.98, "А, и помни, что никакого лагеря без костра не получится. Так что сначала придётся разжечь костёр." }, { 19.21, "Этому тебя может научить почти любой специалист по кулинарии." }, { 23.31, "Если ещё не озаботился этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственный лагерный стул. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 8.60, "Лучше отправляйся куда-нибудь в дикие места." }, { 11.98, "А, и помни, что никакого лагеря без костра не получится. Так что сначала придётся разжечь костёр." }, { 19.21, "Этому тебя может научить почти любой специалист по кулинарии." }, { 23.42, "Если ещё не озаботилась этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } } } } },
    [97972] = { d = 21.6, g = 1, v = "skyborne-male", n = { m = 251, f = 252 }, c = { m = { { 0.00, "Портняжное дело – неожиданно полезный навык, и я уверен, что он тебе очень пригодится." }, { 6.15, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умел для этого." }, { 14.18, "В любой битве боевой дух очень важен, а вдохновляющее знамя может здорово помочь, когда надо его поднять." } }, f = { { 0.00, "Портняжное дело – неожиданно полезный навык, и я уверен, что он тебе очень пригодится." }, { 6.15, "Я знаю кое-кого, кто может научить тебя создавать знамя фракции для лагеря. Если, конечно, ты достаточно умела для этого." }, { 14.16, "В любой битве боевой дух очень важен, а вдохновляющее знамя может здорово помочь, когда надо его поднять." } } }, t = { d = 27.9, g = 1, v = "skyborne-female", n = { m = 324, f = 325 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственное развевающееся знамя." }, { 4.57, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 13.03, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.25, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственное развевающееся знамя." }, { 4.57, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать его придётся где-нибудь на природе." }, { 13.03, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.25, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
