    [97977] = { d = 28.4, v = "human-female", n = { x = 336 }, c = { x = { { 0.00, "Фурболги из племени Кривой Сосны не стали бы так легко предавать своих давних союзников." }, { 6.01, "Мы должны разузнать побольше об их неурядицах." }, { 9.47, "Поищи тотэмы в их заброшенных домах." }, { 11.95, "Если какие-то сохранились после их спешного исхода, вырезанные на них изображения могут пролить свет на то, что здесь произошло." }, { 20.87, "Их стоянки расположены вдоль западного края долины, хотя грелли и греллиды уже могли оттуда всё вынести." } } }, t = { d = 32.3, v = "human-female", n = { x = 378 }, c = { x = { { 0.00, "Всё даже хуже, чем я думала." }, { 2.41, "Эти выгравированные изображения повествуют о том, что фурболгам из племени Кривой Сосны начали сниться кошмары о том, как им приносит погибель какая-то огромная тень." }, { 13.58, "Вскоре этот страх превратился в ярость – а тень приняла облик их бывших друзей-эльфов." }, { 19.41, "Как же жутко постепенно лишаться рассудка, осознавая это..." }, { 23.73, "Надеяться теперь приходится только на то, что нам удастся лучше понять ситуацию на Тельдрассиле. Спасибо тебе за помощь." } } } } },
    [97979] = { d = 34.6, g = 1, v = "nightelf-female#51", n = { m = 394, f = 396 }, c = { m = { { 0.00, "Ты – один из калдорай, детей звёзд, и по праву рождения унаследовал благодать богини, недоступную больше никому в этом мире." }, { 9.12, "Элуна может благословлять нас своим светом, помогая метко бить врага, или скрывать нас, как луна затмевает солнце." }, { 17.39, "Наше долгое бдение после обороны горы Хиджал подошло к концу, и мы примкнули к Альянсу других народов – с ними ты встретишься в своё время." }, { 26.86, "Сейчас же ты укрыт в ветвях Тельдрассила." }, { 30.14, "Продемонстрируй дары Матери-Луны и озарись её благословениями." } }, f = { { 0.00, "Ты – одна из калдорай, детей звёзд, и по праву рождения унаследовала благодать богини, недоступную больше никому в этом мире." }, { 8.40, "Элуна может благословлять нас своим светом, помогая метко бить врага, или скрывать нас, как луна затмевает солнце." }, { 16.68, "Наше долгое бдение после обороны горы Хиджал подошло к концу, и мы примкнули к Альянсу других народов – с ними ты встретишься в своё время." }, { 26.15, "Сейчас же ты укрыта в ветвях Тельдрассила." }, { 29.47, "Продемонстрируй дары Матери-Луны и озарись её благословениями." } } }, t = { d = 5.4, g = 1, v = "nightelf-female#51", n = { m = 58, f = 59 }, c = { m = { { 0.00, "Ты видел дары богини. Пользуйся ими с умом – и она никогда тебя не оставит." } }, f = { { 0.00, "Ты видела дары богини. Пользуйся ими с умом – и она никогда тебя не оставит." } } } } },
    [98013] = { d = 35.4, g = 1, v = "human-male#114", n = { x = 354 }, c = { m = { { 0.00, "Соберись с мужеством прежде, чем отправишься в руины, дитя... враги непременно преградят тебе путь." }, { 7.71, "Полчища проклятых высокорожденных, теперь известных как наги, бродят по некогда великому городу." }, { 15.09, "Отправляйся на северо-восток и изгони их из этих земель." }, { 19.99, "Они утратили всё величие, которым когда-то обладали." }, { 24.04, "Если они в сговоре с Сумеречным Молотом, то могут лишь навредить лесу, что когда-то был их домом." }, { 31.72, "Они хотят войны, герой... и они её получат." } }, f = { { 0.00, "Соберись с мужеством прежде, чем отправишься в руины, дитя... враги непременно преградят тебе путь." }, { 7.71, "Полчища проклятых высокорожденных, теперь известных как наги, бродят по некогда великому городу." }, { 15.09, "Отправляйся на северо-восток и изгони их из этих земель." }, { 19.99, "Они утратили всё величие, которым когда-то обладали." }, { 24.04, "Если они в сговоре с Сумеречным Молотом, то могут лишь навредить лесу, что когда-то был их домом." }, { 31.72, "Они хотят войны, героиня... и они её получат." } } }, t = { d = 8.1, v = "human-male#114", n = { x = 82 }, c = { x = { { 0.00, "Не тревожься, дитя. Разорять собственный дом ради какого-то тёмного повелителя... Этому нет прощения." } } } } },
    [98021] = { d = 34.8, g = 1, v = "human-male", n = { m = 411, f = 416 }, c = { m = { { 0.00, "Если хочешь сделать доброе дело, советую обратиться к Гриану Камнегриву в Западном крае на юге, в поселении под названием Сторожевой холм. Его людям нужна помощь." }, { 11.24, "Конечно, после путешествия из другой части реальности проблемы, с которыми столкнулись наши земли, могут показаться незначительными, но я уверяю: помощь, которую ты предоставишь тем, на кого эти проблемы обрушились, будет значить для них очень много." }, { 28.24, "И ты сам станешь в результате сильнее после всех трудов. Удачи, искатель приключений!" } }, f = { { 0.00, "Если хочешь сделать доброе дело, советую обратиться к Гриану Камнегриву в Западном крае на юге, в поселении под названием Сторожевой холм. Его людям нужна помощь." }, { 11.28, "Конечно, после путешествия из другой части реальности проблемы, с которыми столкнулись наши земли, могут показаться незначительными, но я уверяю: помощь, которую ты предоставишь тем, на кого эти проблемы обрушились, будет значить для них очень много." }, { 28.28, "И ты сама станешь в результате сильнее после всех трудов. Удачи, искательница приключений!" } } }, t = { d = 14.6, g = 1, v = "human-male", n = { x = 147 }, c = { m = { { 0.00, "Я месяцами умолял Штормград о помощи, а он прислал мне тощего эльфа? Что ж, дарёному коню в зубы не смотрят." }, { 7.76, "Добро пожаловать в Западный край, герой. Посмотрим, к какому делу тебя приставить." } }, f = { { 0.00, "Я месяцами умолял Штормград о помощи, а он прислал мне тощего эльфа? Что ж, дарёному коню в зубы не смотрят." }, { 7.76, "Добро пожаловать в Западный край, героиня. Посмотрим, к какому делу тебя приставить." } } } } },
    [98024] = { d = 33.5, g = 1, v = "orc-male", n = { m = 376, f = 380 }, c = { m = { { 0.00, "После путешествия из обители стихий проблемы, с которыми столкнулись наши земли, могут показаться незначительными." }, { 8.12, "Но я уверяю: Орде грозят серьёзные опасности, и ты станешь гораздо сильнее, если уцелеешь в своём служении ей." }, { 16.25, "Если захочешь сделать доброе дело, отправляйся на юго-восток, в обширные земли, известные как Степи." }, { 23.41, "Там есть поселение под названием Перекрёсток. Его гордым обитателям всегда нужна помощь." }, { 30.14, "Ступай с честью, искатель приключений!" } }, f = { { 0.00, "После путешествия из обители стихий проблемы, с которыми столкнулись наши земли, могут показаться незначительными." }, { 8.12, "Но я уверяю: Орде грозят серьёзные опасности, и ты станешь гораздо сильнее, если уцелеешь в своём служении ей." }, { 16.25, "Если захочешь сделать доброе дело, отправляйся на юго-восток, в обширные земли, известные как Степи." }, { 23.41, "Там есть поселение под названием Перекрёсток. Его гордым обитателям всегда нужна помощь." }, { 30.14, "Ступай с честью, искательница приключений!" } } }, t = { d = 19.3, g = 1, v = "orc-male#60", n = { m = 143, f = 144 }, c = { m = { { 0.00, "Это что ещё такое? Эльф? И ты говоришь, тебя прислал вождь?" }, { 4.60, "Торк резко хмыкает, оглядывая вас с ног до головы." }, { 8.64, "На мой взгляд, ты тощеват, но это неважно. Здесь ты либо выживешь и окрепнешь, либо погибнешь. Так уж заведено в этих землях." } }, f = { { 0.00, "Это что ещё такое? Эльф? И ты говоришь, тебя прислал вождь?" }, { 4.60, "Торк резко хмыкает, оглядывая вас с ног до головы." }, { 8.64, "На мой взгляд, ты тощевата, но это неважно. Здесь ты либо выживешь и окрепнешь, либо погибнешь. Так уж заведено в этих землях." } } } } },
    [98025] = { d = 34.4, v = "human-male#114", n = { x = 345 }, c = { x = { { 0.00, "Внимание!" }, { 1.28, "Объявляется награда за убийство совы Джай'ванель, также известной по прозвищу \"Мечеперая\"." }, { 8.43, "К сожалению, сова обезумела и начала нападать на путешественников, проходящих по дороге близ Аубердина." }, { 16.70, "В последний раз её заметили к северу от руин Амет'Арана у подножия горы." }, { 22.13, "Принесите одно из её чёрных перьев как доказательство смерти." }, { 27.17, "За наградой обращаться к часовому Глинде Нал'Шии в Аубердине. Совет Аубердина" } } }, t = { d = 21.0, g = 1, v = "nightelf-female#52", n = { x = 230 }, c = { m = { { 0.00, "Хорошо, что проблема решена, хотя мне очень жаль, что нам не удалось найти другой выход." }, { 5.76, "Джай'ванель давно была своего рода хранительницей этих земель, и я не уверена, что могло подтолкнуть её к безумию." }, { 13.71, "В любом случае, спасибо тебе за услугу, герой. Теперь дороги к Аубердину снова безопасны." } }, f = { { 0.00, "Хорошо, что проблема решена, хотя мне очень жаль, что нам не удалось найти другой выход." }, { 5.76, "Джай'ванель давно была своего рода хранительницей этих земель, и я не уверена, что могло подтолкнуть её к безумию." }, { 13.71, "В любом случае, спасибо тебе за услугу, героиня. Теперь дороги к Аубердину снова безопасны." } } } } },
    [98028] = { d = 36.0, v = "human-male#114", n = { x = 370 }, c = { x = { { 0.00, "Всё, что осталось от могучего элементаля, – сфера чистой воды, замутнённой неизвестной субстанцией." }, { 7.57, "По краям сфера выглядит чистой, но когда вы поворачиваете её, субстанция перемещается, словно специально не позволяя вам заглянуть вглубь." }, { 18.49, "Что бы ни случилось с элементалем и руинами, которые он охранял, воздействовавшая на него магия всё ещё действует." }, { 27.47, "Если кто и сможет разобраться в этом, то только древо мудрости Ону из Рощи Древних далеко на юге." } } }, t = { d = 28.9, g = 1, v = "tauren-male", n = { m = 192, f = 193 }, c = { m = { { 0.00, "Ону выглядит удивлённым – насколько вообще может выглядеть удивлённым древний." }, { 6.58, "Лестница, ведущая вниз, в Матистре? Неужели? Ону качает головой." }, { 11.97, "Мне нужно обсудить это с остальными. Пока же знай: хорошо, что ты обнаружил это раньше наг... и их союзников из культа." }, { 22.45, "Прими это в благодарность за труды. Одолеть элементаля-стража – немалый подвиг." } }, f = { { 0.00, "Ону выглядит удивлённым – насколько вообще может выглядеть удивлённым древний." }, { 6.58, "Лестница, ведущая вниз, в Матистре? Неужели? Ону качает головой." }, { 11.97, "Мне нужно обсудить это с остальными. Пока же знай: хорошо, что ты обнаружила это раньше наг... и их союзников из культа." }, { 22.35, "Прими это в благодарность за труды. Одолеть элементаля-стража – немалый подвиг." } } } } },
    [98042] = { d = 13.3, g = 1, v = "human-male#114", n = { m = 55, f = 56 }, c = { m = { { 0.00, "Когда вы вырываете страницу из Сумеречного фолианта, в ваш разум вторгается зловещий голос. Они не справились. Ты будешь забыт." }, { 10.14, "Они потеряют то око, что получили." } }, f = { { 0.00, "Когда вы вырываете страницу из Сумеречного фолианта, в ваш разум вторгается зловещий голос. Они не справились. Ты будешь забыта." }, { 10.29, "Они потеряют то око, что получили." } } }, t = { d = 11.5, g = 1, v = "nightelf-male#54", n = { x = 82 }, c = { m = { { 0.00, "Тандрис долго раздумывает." }, { 2.15, "Я чувствую здесь след древнего зла, герой. Я немедленно отправлю это на изучение в Дарнас. Анде'торас-этиль." } }, f = { { 0.00, "Тандрис долго раздумывает." }, { 2.15, "Я чувствую здесь след древнего зла, героиня. Я немедленно отправлю это на изучение в Дарнас. Анде'торас-этиль." } } } } },
    [98046] = { d = 26.7, g = 1, v = "named/3516", n = { x = 182 }, c = { m = { { 0.00, "Верховный друид Фэндрал Олений Шлем прищуривается. Ты ещё здесь?" }, { 5.22, "Возьми этот флакон и уходи с глаз долой, герой. Мне ясно, что вода не даст мне ответов на вопросы, как не давала их раньше." }, { 13.98, "Думаю, какая-нибудь жрица из храма Луны на юге, придумает, что с этим делать." }, { 19.68, "Фэндрал отводит взгляд. Его дальнейшие слова адресованы уже не вам. Нужно найти другой способ..." } }, f = { { 0.00, "Верховный друид Фэндрал Олений Шлем прищуривается. Ты ещё здесь?" }, { 5.22, "Возьми этот флакон и уходи с глаз долой, героиня. Мне ясно, что вода не даст мне ответов на вопросы, как не давала их раньше." }, { 14.12, "Думаю, какая-нибудь жрица из храма Луны на юге, придумает, что с этим делать." }, { 19.82, "Фэндрал отводит взгляд. Его дальнейшие слова адресованы уже не вам. Нужно найти другой способ..." } } }, t = { d = 13.8, v = "nightelf-female#51", n = { x = 151 }, c = { x = { { 0.00, "Не обижайся на верховного друида. В отсутствие Малфуриона на его плечах лежит тяжёлое бремя." }, { 6.71, "Постой! В фиале ещё осталось несколько капель! Может, потому его заклинание и не сработало?" } } } } },
    [98065] = { d = 22.0, v = "nightelf-female#51", n = { x = 244 }, c = { x = { { 0.00, "Немедленно покажи это Тиранде! Сейчас я перемещу это в более подобающий сосуд." }, { 5.73, "Не бойся. Верховная жрица Элуны строгая, но у неё доброе сердце." }, { 10.27, "Она защищает всех жителей и гостей Дарнасса и несёт нам свет нашей богини." }, { 15.82, "Она с радостью примет у тебя священную воду. Её можно найти на верхнем этаже храма." } } }, t = { d = 41.9, g = 1, v = "nightelf-female#173", n = { m = 385, f = 387 }, c = { m = { { 0.00, "Ярохрип многое сделал в отсутствие моего возлюбленного, но он не Малфурион." }, { 5.74, "И не он управляет делами Дарнаса – это бремя лежит на мне одной. Лицо Тиранды становится спокойным." }, { 13.72, "Прости. Как ты, вероятно, уже видел, нам предстоит преодолеть немало трудностей." }, { 20.23, "Сейчас Фэндрал – верховный друид, и я прошу тебя уважать его положение." }, { 26.01, "Но его забота – друидизм, моя же – не только служение Элуне, но и то, чтобы вести наш народ по её воле." }, { 34.08, "Каждая капля этой воды благословлена нашей богиней. Благодарю тебя за то, что сохранил её." } }, f = { { 0.00, "Ярохрип многое сделал в отсутствие моего возлюбленного, но он не Малфурион." }, { 5.74, "И не он управляет делами Дарнаса – это бремя лежит на мне одной. Лицо Тиранды становится спокойным." }, { 13.72, "Прости. Как ты, вероятно, уже видела, нам предстоит преодолеть немало трудностей." }, { 20.15, "Сейчас Фэндрал – верховный друид, и я прошу тебя уважать его положение." }, { 25.92, "Но его забота – друидизм, моя же – не только служение Элуне, но и то, чтобы вести наш народ по её воле." }, { 34.00, "Каждая капля этой воды благословлена нашей богиней. Благодарю тебя за то, что сохранила её." } } } } },
    [98067] = { d = 35.2, v = "nightelf-female#52", n = { x = 414 }, c = { x = { { 0.00, "Генерал Лунное Перо следит за тем, чтобы у всех часовых было время на молитву Элуне." }, { 6.56, "Чтобы одолеть врагов, настоящая охотница использует не только свой клинок, но и дары богини." }, { 13.03, "Помоги мне в моих ежедневных обязанностях и расставь часовых по городу." }, { 17.62, "Начни с туннелей, ведущих под крепость Кенария на севере, а затем иди к банку в центре города, таверне на Террасе Ремесленников на северо-востоке и городским воротам. Стражники могут тебе помочь." }, { 30.95, "В Тельдрассиле не всё спокойно. Мы должны оставаться начеку." } } }, t = { d = 8.1, v = "nightelf-female#52", n = { x = 97 }, c = { x = { { 0.00, "Благодарю за помощь. Хотя ежедневные ритуалы и дарят мне покой, приятно вместо них выкроить минутку для размышлений." } } } } },
    [98072] = { d = 39.9, g = 1, v = "human-male", n = { m = 427, f = 428 }, c = { m = { { 0.00, "Да ты настоящий труженик! У меня есть ещё одна просьба, если ты не прочь взяться за работу поопаснее." }, { 9.42, "Торговля кроколисками приносит стабильный доход, но это мелочь по сравнению с тем, что можно выручить за драконью чешую." }, { 17.76, "За мешок чешуи дракончиков заплатят солидные деньги." }, { 21.86, "Я их называю небесными кроколисками!" }, { 24.56, "Моему ученику ни за что к ним не подобраться, зато эта работа, похоже, как раз по твоей части!" }, { 31.33, "Дракончиков можно найти далеко на востоке, вдоль Зелёного Пояса. Но будь настороже – в тех холмах рыскают злобные орки!" } }, f = { { 0.00, "Да ты настоящая труженица! У меня есть ещё одна просьба, если ты не прочь взяться за работу поопаснее." }, { 7.54, "Торговля кроколисками приносит стабильный доход, но это мелочь по сравнению с тем, что можно выручить за драконью чешую." }, { 15.88, "За мешок чешуи дракончиков заплатят солидные деньги." }, { 19.99, "Я их называю небесными кроколисками!" }, { 22.68, "Моему ученику ни за что к ним не подобраться, зато эта работа, похоже, как раз по твоей части!" }, { 29.45, "Дракончиков можно найти далеко на востоке, вдоль Зелёного Пояса. Но будь настороже – в тех холмах рыскают злобные орки!" } } } },
    [98093] = { d = 33.6, g = 1, v = "tauren-female#71", n = { m = 332, f = 333 }, c = { m = { { 0.00, "Как хорошо, что ты меня заметил!" }, { 3.05, "Сегодня утром была чудесная погода, и я решила пройтись от лагеря Таурахо по золотой тропе." }, { 10.36, "А когда собралась возвращаться, не смогла – вокруг начали кружить гиены, а обходной путь преградили грозовые ящеры." }, { 19.66, "Пришлось забраться на дерево, а теперь вокруг столько опасных зверей, что я ни за что не добегу домой." }, { 28.05, "Может быть, зачистишь поля от грозовых ящеров и многозубых ловцов?" } }, f = { { 0.00, "Как хорошо, что ты меня заметила!" }, { 2.95, "Сегодня утром была чудесная погода, и я решила пройтись от лагеря Таурахо по золотой тропе." }, { 10.26, "А когда собралась возвращаться, не смогла – вокруг начали кружить гиены, а обходной путь преградили грозовые ящеры." }, { 19.56, "Пришлось забраться на дерево, а теперь вокруг столько опасных зверей, что я ни за что не добегу домой." }, { 27.95, "Может быть, зачистишь поля от грозовых ящеров и многозубых ловцов?" } } }, t = { d = 21.1, g = 1, v = "tauren-female#71", n = { m = 197, f = 201 }, c = { m = { { 0.00, "Спасибо, что выручил меня. Я сообщу в лагерь Таурахо, что ты меня спас." }, { 5.56, "Как же мне повезло, что ты оказался рядом, – иначе я бы просидела там весь день!" }, { 12.15, "Больше у меня ничего нет, но надеюсь, тебе это пригодится." }, { 17.05, "А я потихоньку слезу с дерева и пойду домой." } }, f = { { 0.00, "Спасибо, что выручила меня. Я сообщу в лагерь Таурахо, что ты меня спасла." }, { 5.66, "Как же мне повезло, что ты оказалась рядом, – иначе я бы просидела там весь день!" }, { 12.39, "Больше у меня ничего нет, но надеюсь, тебе это пригодится." }, { 17.30, "А я потихоньку слезу с дерева и пойду домой." } } } } },
    [98094] = { d = 36.5, v = "scourge-female", n = { x = 323 }, c = { x = { { 0.00, "Теперь, когда мы знаем, что можем доверить тебе доставку важных сведений нашим шпионам, для тебя есть ещё одно задание." }, { 10.90, "Отнеси это стражу смерти Масоджу. Ты найдёшь его почти точно к югу от нас. Когда передашь это ему, он даст тебе новое задание." }, { 22.12, "Ищи его на возвышенности к северу от сгнившего виноградника, который зовут Владением Нетандера." }, { 31.06, "Наши планы по захвату этих земель воплощаются в жизнь." } } } },
    [98095] = { d = 36.5, v = "human-male#114", n = { x = 384 }, c = { x = { { 0.00, "Высшее командование использует летучих всадников для перевозки войск. В ключевых точках предгорий нужно обновить сигнальные приманки." }, { 10.50, "Возьми эти флаконы. Открой их в трёх местах: на холмах рядом с Дун Гароком, на плато, откуда открывается вид на крепость Дарнхольд, и на Высоком отроге над городом Хилсбрадом." }, { 23.88, "Сделав это, ты распылишь пары, которые снова привлекут наших летучих мышей к нужным точкам высадки." }, { 32.07, "Найди разбитые пустые флаконы и обнови наши приманки." } } } },
    [98189] = { d = 22.3, v = "human-male", n = { x = 253 }, c = { x = { { 0.00, "Невероятно... Какая красота!" }, { 2.36, "\"Слепая принцесса\" должна была доставить это в Гавань Менетилов, прежде чем произошла трагедия. Мы были так близки!" }, { 10.61, "Полагаю, капитан Крепкий Кулак должен был подписать нужные документы в крепости Менетилов позади нас." }, { 17.68, "Почему бы тебе не оказать нам всем честь и не закончить работу?" } } } },
    [98190] = { d = 42.8, g = 1, v = "human-male#114", n = { m = 460, f = 459 }, c = { m = { { 0.00, "Тебе следует немедленно отправиться с этим в Штормград." }, { 4.17, "Как бы я ни гордился тем, что крепость и гавань носят имя короля Теренаса Менетила II, это место – лишь небольшой тихий уголок посреди настоящей бури врагов. Здесь просто-напросто небезопасно." }, { 19.23, "В частности, клан Драконьей Пасти многим бы пожертвовал, чтобы завладеть чем-то подобным..." }, { 25.83, "Боюсь даже представить, что бы они сделали с такой ценностью." }, { 30.44, "Правилами субординации можешь в этот раз пренебречь, парень. Отправляйся прямиком к верховному лорду Фордрагону." }, { 39.15, "Он знает, где следует хранить такой предмет." } }, f = { { 0.00, "Тебе следует немедленно отправиться с этим в Штормград." }, { 4.17, "Как бы я ни гордился тем, что крепость и гавань носят имя короля Теренаса Менетила II, это место – лишь небольшой тихий уголок посреди настоящей бури врагов. Здесь просто-напросто небезопасно." }, { 19.23, "В частности, клан Драконьей Пасти многим бы пожертвовал, чтобы завладеть чем-то подобным..." }, { 25.83, "Боюсь даже представить, что бы они сделали с такой ценностью." }, { 30.44, "Правилами субординации можешь в этот раз пренебречь, милая. Отправляйся прямиком к верховному лорду Фордрагону." }, { 39.07, "Он знает, где следует хранить такой предмет." } } } },
    [98191] = { d = 36.6, v = "human-male#114", n = { x = 371 }, c = { x = { { 0.00, "Король Теренас был хорошим человеком. Набожным. Народ любил его, и именно ему наш Альянс обязан своим существованием." }, { 9.54, "Ирония состоит в том, что он был очень скромным и терпеть не мог подобные памятные предметы. Поэтому их так мало." }, { 18.37, "И лишь малая их часть уцелела после падения Лордерона." }, { 23.39, "Похоже, в этой статуэтке собралась сила Света." }, { 26.86, "Лучше всего будет хранить её в Соборе Света на Соборной площади, в самом центре города. Отнеси её лорду Грейсону Тенелому." } } } },
    [98197] = { d = 35.1, v = "dwarf-male", n = { x = 391 }, c = { x = { { 0.00, "Эту гавань Старая Орда построила как плацдарм для морского вторжения в Хилсбрад. Так она смогла полностью обойти оборону Лордерона! Сколько же жизней унесла война..." }, { 13.61, "Что ещё хуже, тот флот был построен из материалов, украденных из Каз Модана!" }, { 19.12, "Много чего осталось в гавани после того, как адмирал Праудмур разгромил захватчиков и отстроил это место для Альянса." }, { 27.15, "Нам понадобятся эти материалы, чтобы укрепить оборону города, когда клан Драконьей Пасти перейдёт в наступление." } } }, t = { d = 12.0, g = 1, v = "dwarf-male", n = { x = 117 }, c = { m = { { 0.00, "Ага! Немного отсырело, но пара дней на солнце всё исправит." }, { 4.73, "Спасибо, герой. Приятно хоть раз не зависеть целиком от поставок из Терамора или Аубердина!" } }, f = { { 0.00, "Ага! Немного отсырело, но пара дней на солнце всё исправит." }, { 4.73, "Спасибо, героиня. Приятно хоть раз не зависеть целиком от поставок из Терамора или Аубердина!" } } } } },
    [98208] = { d = 35.0, v = "nightelf-female#53", n = { x = 399 }, c = { x = { { 0.00, "Я прибыла в Гавань Менетилов из Аубердина, от великого древа Тельдрассил, чтобы вернуть цветок, очень важный для моего народа." }, { 9.65, "Корабль моего народа, «Летящая скопа», много лун назад потерпел здесь крушение вместе с Третьей флотилией Кул-Тираса." }, { 17.52, "Среди его груза был цветок Норд'эль – на вашем языке «Цветок Небес»." }, { 22.12, "Он распустился под полной луной на вершине горы Хиджал, нашего прежнего дома." }, { 27.63, "Прошу, помоги мне вернуть его! Обломки лежат к югу от города, но там засели свирепые мурлоки-налётчики!" } } } },
    [98219] = { d = 31.4, v = "human-male", n = { x = 351 }, c = { x = { { 0.00, "Ещё раз спасибо за безопасную доставку статуэтки." }, { 3.94, "Мне нужна твоя помощь ещё кое в чём. Есть один городской стражник, которого перевели на службу в Южнобережье, в предгорья Хилсбрада." }, { 13.32, "Его отец был моим другом, и хотя я не спорю, что его стоит научить уму-разуму... мне всё же хочется, чтобы он добился успеха." }, { 21.91, "Помощь кого-то вроде тебя была бы ему очень полезна." }, { 25.84, "Если отправишься в ту сторону, то можешь сесть на корабль из Гавани Менетилов." } } } },
    [98240] = { d = 30.3, v = "human-male", n = { x = 339 }, c = { x = { { 0.00, "Вести о дракончиках быстро разлетелись. У нас уже есть один заказ!" }, { 4.99, "Я красиво его упакую, а ты отнесёшь клиенту. Я всё прекрасно понимаю, так что об услуге прошу в последний раз, обещаю!" }, { 13.64, "Этот заказ сделал некий Ховин Мягкое Перо. К слову, для этого он отправил в город своего грифона с письмом!" }, { 21.05, "Пишет, что он находится чуть в стороне от восточной дороги, немного дальше области раскопок Вельгара, если тебе знакомы те места." } } } },
    [98245] = { d = 34.0, v = "dwarf-male", n = { x = 376 }, c = { x = { { 0.00, "Уж не знаю, кого я ненавижу больше: проклятых Чёрных Железных дворфов, клан Драконьей Пасти или драконов, на которых они летали. Ховин сплёвывает." }, { 10.30, "Я хочу всё исправить. Но нам понадобятся кое-какие припасы." }, { 14.76, "Чешуя дракончиков неплохо защищает от драконьего огня, но сплетать её вместе – сущее мучение." }, { 21.47, "Ящеры-острозубы на Гряде Ящеров к северо-востоку и в Долине Солевого Тумана к северо-западу получили своё имя за острые клыки – уж они-то чешую пробьют. Принеси мне горсть их резцов." } } } },
    [98246] = { d = 28.2, v = "dwarf-male", n = { x = 312 }, c = { x = { { 0.00, "Чтобы мой план сработал, мне понадобятся яйца." }, { 3.33, "Басоклюв должен быть сыт по горло – я не собираюсь садиться на спину злющему грифону." }, { 9.52, "Яйца должны быть целыми – ни трещинки, ничего такого." }, { 13.57, "Добудь их у ящеров-острозубов – у них, говорят, желтки размером с гномью голову." }, { 18.98, "Найдёшь их на Гряде Ящеров к северо-востоку и в Долине Солевого Тумана к северо-западу." }, { 25.40, "Давай ровно дюжину, для надёжности." } } } },
    [98247] = { d = 34.2, v = "human-male#114", c = { x = { { 0.00, "На боку заполненного ящика наклеена порванная этикетка." }, { 4.33, "Хотя имя адресата не сохранилось, на ней можно разобрать сведения о том, откуда был отправлен груз." }, { 12.51, "\"Собственность \"Азеротского торгового управления\"." }, { 15.88, "Пустые ящики и недоставленные грузы просим возвращать в наш торговый пункт у Трёх Углов в Красногорье." }, { 23.91, "Курьеров вознаградят за потраченное время и проделанный путь\"." }, { 28.91, "Рядом с текстом есть грубый набросок карты упомянутой местности." } } }, t = { d = 36.3, g = 1, v = "human-female#47", n = { m = 444, f = 445 }, c = { m = { { 0.00, "Ты пришёл именно туда, куда надо. Я с радостью запишу тебя в перечень наших подрядчиков." }, { 5.75, "Никаких контрактов подписывать не надо, да и особых обязанностей у тебя не будет." }, { 11.08, "Мы лишь просим, чтобы ты доставлял по адресу или возвращал нам принадлежащие управлению грузы, которые попадутся тебе в странствиях." }, { 20.39, "За каждую такую доставку ты получишь торговые обязательства. С их помощью ты сможешь платить нам за товары и услуги." }, { 28.17, "Кстати, вот тебе сразу кое-что для начала." }, { 31.37, "Теперь скажи, у тебя есть ящик, на который была наклеена эта этикетка?" } }, f = { { 0.00, "Ты пришла именно туда, куда надо. Я с радостью запишу тебя в перечень наших подрядчиков." }, { 5.86, "Никаких контрактов подписывать не надо, да и особых обязанностей у тебя не будет." }, { 11.19, "Мы лишь просим, чтобы ты доставляла по адресу или возвращала нам принадлежащие управлению грузы, которые попадутся тебе в странствиях." }, { 20.11, "За каждую такую доставку ты получишь торговые обязательства. С их помощью ты сможешь платить нам за товары и услуги." }, { 27.89, "Кстати, вот тебе сразу кое-что для начала." }, { 31.10, "Теперь скажи, у тебя есть ящик, на который была наклеена эта этикетка?" } } } } },
    [98248] = { d = 34.5, v = "human-male#114", c = { x = { { 0.00, "На боку заполненного ящика наклеена порванная этикетка." }, { 4.33, "Хотя имя адресата не сохранилось, на ней можно разобрать сведения о том, откуда был отправлен груз." }, { 12.51, "\"Просим возвращать повреждённые грузы и пустые ящики на торговый пост \"Дуротарского снабжения и логистики\", теперь удобно расположенный к западу от Перекрёстка в Степях." }, { 25.33, "Мы ценим ваше время и вознаградим за усилия!\"" }, { 29.21, "Рядом с текстом есть грубый набросок карты упомянутой местности." } } }, t = { d = 37.2, g = 1, v = "orc-female", n = { m = 419, f = 419 }, c = { m = { { 0.00, "Ты нашёл нужное место и разговариваешь именно с той, с кем надо! Я запишу тебя в перечень наших подрядчиков." }, { 7.56, "Тебе о бумажной волоките беспокоиться не надо, я сама уже от неё устала." }, { 13.04, "Мы просим лишь помогать нам в доставке и возвращении утерянных грузов, которые попадутся в твоих странствиях." }, { 20.64, "За это ты получишь торговые обязательства, которые позволят платить нам за различные товары и услуги." }, { 27.80, "Вот тебе сразу кое-что, чтобы поднять настроение!" }, { 31.81, "У тебя, случайно, нет ещё и ящика, на который была наклеена эта этикетка?" } }, f = { { 0.00, "Ты нашла нужное место и разговариваешь именно с той, с кем надо! Я запишу тебя в перечень наших подрядчиков." }, { 7.44, "Тебе о бумажной волоките беспокоиться не надо, я сама уже от неё устала." }, { 12.93, "Мы просим лишь помогать нам в доставке и возвращении утерянных грузов, которые попадутся в твоих странствиях." }, { 20.52, "За это ты получишь торговые обязательства, которые позволят платить нам за различные товары и услуги." }, { 27.68, "Вот тебе сразу кое-что, чтобы поднять настроение!" }, { 31.70, "У тебя, случайно, нет ещё и ящика, на который была наклеена эта этикетка?" } } } } },
    [98251] = { d = 34.6, g = 1, v = "troll-female#73", n = { m = 390, f = 392 }, c = { m = { { 0.00, "А-а-а!" }, { 0.94, "Просто зло берёт. Говорили, в Ясеневом лесу легко ориентироваться. Кому легко? Зверью? Птицам?" }, { 7.64, "Собираешь себе травы, как вдруг оказываешься в каком-то овраге." }, { 12.00, "Неужели тут действительно нужно обойти половину леса, чтобы вернуться туда, где был лишь мгновение назад?" }, { 19.51, "Когда я в таком настроении, мои заклинания становятся непредсказуемыми и действуют... иначе." }, { 26.08, "Не мог бы ты проредить местную живность? Даже топот их негодных копыт сводит меня с ума. Ненавижу этот проклятый лес." } }, f = { { 0.00, "А-а-а!" }, { 0.94, "Просто зло берёт. Говорили, в Ясеневом лесу легко ориентироваться. Кому легко? Зверью? Птицам?" }, { 7.64, "Собираешь себе травы, как вдруг оказываешься в каком-то овраге." }, { 12.00, "Неужели тут действительно нужно обойти половину леса, чтобы вернуться туда, где был лишь мгновение назад?" }, { 19.51, "Когда я в таком настроении, мои заклинания становятся непредсказуемыми и действуют... иначе." }, { 26.08, "Не могла бы ты проредить местную живность? Даже топот их негодных копыт сводит меня с ума. Ненавижу этот проклятый лес." } } } },
    [98252] = { d = 35.7, v = "troll-female#73", n = { x = 393 }, c = { x = { { 0.00, "Выведи моё око Килрогга из этого оврага и покажи путь к дороге. Я последую за вами, когда увижу расчищенный путь." }, { 8.12, "Пока же останусь здесь – кому-то из нас нужно следить, чтобы мы не потерялись." }, { 13.18, "Если собьёшься с пути, я смогу привести тебя назад с помощью ока." }, { 17.63, "Не хочу, чтобы мы вместе вслепую шатались по этому жуткому лесу." }, { 22.27, "Моей силы хватит, чтобы поддерживать связь четыре минуты – ни мгновением дольше." }, { 29.19, "Доберись до дороги, прежде чем связь прервётся, или вернись ко мне, и мы попробуем снова." } } } },
    [98282] = { d = 41.1, v = "human-female", n = { x = 490 }, c = { x = { { 0.00, "Некоторые алхимические рецепты требуют ингредиентов, которые собирают, скажем так, в крайне небезопасных местах." }, { 7.58, "И зачастую это всего лишь базовые травы! А есть такие ингредиенты, которые вообще добыть практически невозможно!" }, { 15.66, "Прежде чем я снова смогу отправиться в путь, мне нужно изготовить побольше противоядия. Честное слово, в этом болоте всё ядовито." }, { 24.22, "Как будто отрава пропитала саму землю!" }, { 27.12, "Ты поможешь мне? Мне нужна ядовитая железа пауков из пещеры Тельгена далеко на юго-востоке." }, { 33.43, "Но она должна быть неповреждённой, иначе по дороге обратно из неё выльется слишком много яда. Ты уж извини!" } } } },
    [98284] = { d = 23.2, v = "skyborne-male", n = { x = 277 }, c = { x = { { 0.00, "Зачаровыватели делают всё лучше, и их привечают в любом походном лагере." }, { 5.24, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать зачарованную лютню для своего лагеря." }, { 12.10, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы, какие только могут встретиться в странствиях." } } }, t = { d = 27.4, g = 1, v = "skyborne-female#3773", n = { m = 322, f = 323 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственную зачарованную лютню." }, { 4.26, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 12.53, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.39, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственную зачарованную лютню." }, { 4.26, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 12.53, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.39, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
    [98285] = { d = 21.7, v = "gnome-male", n = { x = 257 }, c = { x = { { 0.00, "Главное для инженера – изобретательность, и если вдруг ты окажешься в одиночку в какой-нибудь глуши, всегда можно найти приложение своему ремеслу." }, { 9.83, "Ни один лагерь не будет полноценным без пары полезных механизмов!" }, { 14.75, "Когда наберёшься опыта в инженерном деле, приходи ко мне – я научу тебя создавать кое-что особенное!" } } }, t = { d = 30.8, g = 1, v = "gnome-male", n = { m = 351, f = 352 }, c = { m = { { 0.00, "Вот, теперь ты можешь создать собственного реагентобота. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 8.71, "Лучше отправляйся куда-нибудь в дикие места." }, { 12.12, "А, и помни, что никакого лагеря без костра не получится. Так что сначала придётся разжечь костёр." }, { 19.39, "Этому тебя может научить почти любой специалист по кулинарии." }, { 23.71, "Если ещё не озаботился этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } }, f = { { 0.00, "Вот, теперь ты можешь создать собственного реагентобота. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо." }, { 8.71, "Лучше отправляйся куда-нибудь в дикие места." }, { 12.12, "А, и помни, что никакого лагеря без костра не получится. Так что сначала придётся разжечь костёр." }, { 19.39, "Этому тебя может научить почти любой специалист по кулинарии." }, { 23.64, "Если ещё не озаботилась этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы." } } } } },
    [98286] = { d = 23.2, v = "skyborne-male", n = { x = 277 }, c = { x = { { 0.00, "Зачаровыватели делают всё лучше, и их привечают в любом походном лагере." }, { 5.24, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать зачарованную лютню для своего лагеря." }, { 12.10, "Развлечения – очень важная штука на отдыхе, а эта магическая вещица поможет тебе достойно встречать любые проблемы, какие только могут встретиться в странствиях." } } }, t = { d = 27.4, g = 1, v = "skyborne-female#3773", n = { m = 322, f = 323 }, c = { m = { { 0.00, "Вот и всё – теперь ты можешь создать собственную зачарованную лютню." }, { 4.26, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 12.53, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.39, "Если ещё не озаботился этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } }, f = { { 0.00, "Вот и всё – теперь ты можешь создать собственную зачарованную лютню." }, { 4.26, "В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо, так что испытать её придётся где-нибудь на природе." }, { 12.53, "Да, и помни: без костра никакого лагеря не получится. Сначала придётся его разжечь. Этому может научить почти любой повар." }, { 21.39, "Если ещё не озаботилась этим, загляни к кому-нибудь из учителей кулинарии и освой азы." } } } } },
    [98287] = { d = 24.7, v = "human-male", n = { x = 287 }, c = { x = { { 0.00, "Инженеры вроде тебя могут конструировать всяческие приблуды, прибамбасы и бомбы, чтобы развлекаться и зарабатывать." }, { 8.33, "Сдаётся мне, я знаю кое-кого, кто может научить тебя создавать реагентобота для твоего лагеря." }, { 15.48, "Этот славный автоматон помогает с припасами, чтобы у тебя и твоих союзников всегда были материалы, необходимые для ваших заклинаний." } } } },
    [98293] = { d = 15.7, v = "human-male#114", n = { x = 163 }, c = { x = { { 0.00, "Клан Драконьей Пасти запасает самое разное оружие. Разумно было бы избавить их от него, пока они не вооружили новых солдат." }, { 9.95, "Капитан Крепкий Кулак в крепости Менетилов наверняка им заинтересуется." } } } },
    [98298] = { d = 50.1, v = "scourge-male#82", n = { x = 407 }, c = { x = { { 0.00, "А, теперь всё до смешного ясно! Аругал едва владел магией – о силе, необходимой для сотворения воргенов, не идёт и речи." }, { 13.76, "Проклятие Аругала... Пф! Да оно такое слабое, что и минуты не держится." }, { 20.40, "Эти оковы доказывают, что он может подчинять этих чудовищ, а не создавать их." }, { 27.65, "Проклятие воргенов явно распространяется иначе – и я даже знаю, как именно." }, { 34.81, "Отправляйся на юг, к Стене Седогрива. Похоже, воргены заражают обитающих там людей. Истреби чудовищ и принеси всё, что найдёшь." }, { 46.12, "Пришло время для более прямого подхода." } } }, t = { d = 33.2, v = "scourge-male#82", n = { x = 291 }, c = { x = { { 0.00, "Похоже, последним смеюсь всё-таки я, ха-ха! Аругал и впрямь был глупцом. А я, Далар Ткач Рассвета, разоблачил его как мошенника." }, { 11.68, "Эти останки – всё доказательство, какое мне нужно: проклятие не имеет к этому пустоголовому болвану никакого отношения." }, { 22.61, "Увы, это значит, что и его средство ничего не стоит. Похоже, поиски лекарства от проклятия воргенов продолжаются." } } } } },
    [98299] = { d = 49.1, g = 1, v = "scourge-male#82", n = { x = 410 }, c = { m = { { 0.00, "Нам точно известно, что за появлением воргенов в Серебряном бору стоит Аругал." }, { 7.31, "Возможно, он опять что-то задумал, а может, дело в чём-то ещё. Чего мы не знаем, так это того, как распространяется проклятие." }, { 18.81, "Пока я ищу способ остановить его, нам срочно нужно предотвратить новое заражение." }, { 26.50, "Похоже, Отрёкшиеся неспособны подхватить эту хворь, но у Стены Седогрива собралась большая группа людей." }, { 36.54, "Ступай туда и избавься от этих беженцев, пока они не стали прислужниками Аругала. И смотри, чтобы тебя не укусили, герой." } }, f = { { 0.00, "Нам точно известно, что за появлением воргенов в Серебряном бору стоит Аругал." }, { 7.31, "Возможно, он опять что-то задумал, а может, дело в чём-то ещё. Чего мы не знаем, так это того, как распространяется проклятие." }, { 18.81, "Пока я ищу способ остановить его, нам срочно нужно предотвратить новое заражение." }, { 26.50, "Похоже, Отрёкшиеся неспособны подхватить эту хворь, но у Стены Седогрива собралась большая группа людей." }, { 36.54, "Ступай туда и избавься от этих беженцев, пока они не стали прислужниками Аругала. И смотри, чтобы тебя не укусили, героиня." } } }, t = { d = 24.0, v = "scourge-male#82", n = { x = 187 }, c = { x = { { 0.00, "Похоже, гилнеасцы не слишком-то рады пускать кого-либо за свою стену. Пожалуй, это к лучшему." }, { 10.54, "Значит, проклятие воргенов вряд ли доберётся до их города." }, { 16.36, "Можешь представить, какой был бы кошмар, если бы заразилось целое королевство?" } } } } },
    [98319] = { d = 31.6, v = "dwarf-female#33", n = { x = 362 }, c = { x = { { 0.00, "С троллями и так проблем не оберёшься, а тут ещё и горы кишат вендиго!" }, { 4.82, "Обычно они не покидают свои пещеры, но в последнее время, видно, расплодились как кролики и заполонили Серую берлогу к северу отсюда." }, { 14.35, "Если хотим предоставить Белобороду отчёт, то придётся нам разыскать моего напарника Корнелия." }, { 20.81, "Этот болван переволновался и сломя голову ринулся в бой. Храбро, но глупо." }, { 26.32, "Иди в пещеру и поищи его. А заодно можешь уничтожить несколько чудовищ." } } } },
    [98321] = { d = 28.3, g = 1, v = "dwarf-male", n = { m = 316, f = 318 }, c = { m = { { 0.00, "Ага! Приятно встретить героя, который не боится замарать руки." }, { 4.85, "Если ищешь работу, боюсь, у меня сейчас туго с материалами." }, { 8.90, "На наш самый надёжный источник руды напали вендиго, и теперь пещера заброшена." }, { 14.37, "Рудокопам пришлось всё побросать и спасаться бегством." }, { 18.55, "Скажи-ка, не мог бы ты заглянуть в Серую берлогу к западу отсюда и поискать там предназначенные для нас припасы? Нам бы это очень помогло." } }, f = { { 0.00, "Ага! Приятно встретить героиню, которая не боится замарать руки." }, { 4.71, "Если ищешь работу, боюсь, у меня сейчас туго с материалами." }, { 8.76, "На наш самый надёжный источник руды напали вендиго, и теперь пещера заброшена." }, { 14.23, "Рудокопам пришлось всё побросать и спасаться бегством." }, { 18.41, "Скажи-ка, не могла бы ты заглянуть в Серую берлогу к западу отсюда и поискать там предназначенные для нас припасы? Нам бы это очень помогло." } } } },
    [98322] = { d = 34.6, v = "dwarf-male", n = { x = 372 }, c = { x = { { 0.00, "Шастать по тёмным пещерам – это дело искателей приключений, а моя работа – просто составлять отчёты и отправлять их в Стальгорн." }, { 8.84, "Дело в том, что один из моих отчётов пока…" }, { 11.91, "ну, не подоспел. Я попросил нескольких горных пехотинцев разузнать побольше о трудностях с местными вендиго, но от них до сих пор нет вестей." }, { 23.46, "Если ты уже собираешься куда-нибудь прогуляться, почему бы тебе не встретиться с пехотинцем Гретхен к западу от города? У меня время уже поджимает!" } } } },
    [98323] = { d = 25.8, g = 1, v = "dwarf-female#33", n = { m = 290, f = 291 }, c = { m = { { 0.00, "Надеюсь, ты там много монстров поубивал. Жаль Корнелия, конечно." }, { 4.86, "С твоих слов, нам и докладывать-то не о чем, кроме того, что от пещеры теперь лучше держаться подальше." }, { 11.84, "Белобороду это не понравится, но в эту смертельную ловушку я никого отправлять больше не решусь." }, { 18.86, "Доложи о ситуации. Я отсюда никуда не уйду, пока обстановка на горе не станет снова безопасной." } }, f = { { 0.00, "Надеюсь, ты там много монстров поубивала. Жаль Корнелия, конечно." }, { 4.87, "С твоих слов, нам и докладывать-то не о чем, кроме того, что от пещеры теперь лучше держаться подальше." }, { 11.85, "Белобороду это не понравится, но в эту смертельную ловушку я никого отправлять больше не решусь." }, { 18.87, "Доложи о ситуации. Я отсюда никуда не уйду, пока обстановка на горе не станет снова безопасной." } } } },
    [98326] = { d = 34.1, v = "dwarf-female", n = { x = 381 }, c = { x = { { 0.00, "Ты хоть знаешь, как трудно рыбачить на замёрзшем озере?" }, { 3.80, "Мой бедный муж Пакстон уже несколько дней там торчит, а улова едва наберётся на один мешок." }, { 10.60, "Вернее, мешок у нас был, пока распроклятый вендиго не напал на меня и не стащил нашу рыбу." }, { 16.86, "У нас недели уйдут на то, чтобы снова наловить рыбы! Если, конечно, этот горлопан Ледяной Вой не испортил весь клёв." }, { 25.29, "Сделай одолжение и верни наш улов, ладно? Этот слюнявый громила скрывается где-то в глубине Серой берлоги на юго-востоке." } } } },
    [98340] = { d = 34.5, g = 1, v = "tauren-male#67", n = { m = 284, f = 287 }, c = { m = { { 0.00, "Думаю, ты готов сделать следующий шаг на пути друида, ученик." }, { 5.99, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретился с ним на Лунной поляне." }, { 16.05, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 26.21, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } }, f = { { 0.00, "Думаю, ты готова сделать следующий шаг на пути друида, ученица." }, { 6.28, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретилась с ним на Лунной поляне." }, { 16.07, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 26.23, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } } } },
    [98341] = { d = 33.4, g = 1, v = "nightelf-male#54", n = { m = 387, f = 388 }, c = { m = { { 0.00, "Недавно здесь явился дух твоих родных земель и попросил меня направить тебя к нему." }, { 5.73, "Дух рождённой ветром кошки хочет обучить и направить тебя, чтобы ты получил возможность принимать кошачью форму на Зефрисе." }, { 14.47, "Все друиды ищут этих знаний, хотя похоже, что в твоих землях дух принимает форму, отличную от той, к которой привыкли мы." }, { 22.62, "Если хочешь научиться превращению в кошку, тебе нужно будет пройти наше испытание." }, { 28.73, "Разыщи духа в южной части Лунной поляны, к югу от двух мостов." } }, f = { { 0.00, "Недавно здесь явился дух твоих родных земель и попросил меня направить тебя к нему." }, { 5.73, "Дух рождённой ветром кошки хочет обучить и направить тебя, чтобы ты получила возможность принимать кошачью форму на Зефрисе." }, { 14.59, "Все друиды ищут этих знаний, хотя похоже, что в твоих землях дух принимает форму, отличную от той, к которой привыкли мы." }, { 22.75, "Если хочешь научиться превращению в кошку, тебе нужно будет пройти наше испытание." }, { 28.85, "Разыщи духа в южной части Лунной поляны, к югу от двух мостов." } } } },
    [98342] = { d = 47.9, g = 1, v = "tauren-female", n = { m = 472, f = 475 }, c = { m = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.16, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способен воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 18.57, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 26.98, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 33.39, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смог пробраться мимо них." }, { 41.22, "Принеси мне эти реликвии. Тогда мы узнаем, готов ли ты принимать мой облик." } }, f = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.16, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способна воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 18.65, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 27.05, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 33.47, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смогла пробраться мимо них." }, { 41.59, "Принеси мне эти реликвии. Тогда мы узнаем, готова ли ты принимать мой облик." } } }, t = { d = 20.0, g = 1, v = "tauren-female", n = { m = 180, f = 181 }, c = { m = { { 0.00, "Превосходно. Ты доказал, что понимаешь истинную природу кошки и способен воплотить хитрость, скрытность и свирепость, необходимые, чтобы принимать мой облик." }, { 12.93, "Теперь я считаю тебя достойным моего благословения, юный герой." } }, f = { { 0.00, "Превосходно. Ты доказала, что понимаешь истинную природу кошки и способна воплотить хитрость, скрытность и свирепость, необходимые, чтобы принимать мой облик." }, { 14.45, "Теперь я считаю тебя достойной моего благословения, юная героиня." } } } } },
    [98362] = { d = 29.5, g = 1, v = "nightelf-male#54", n = { m = 341, f = 340 }, c = { m = { { 0.00, "Пришло время нам снова расстаться, дитя." }, { 2.70, "Чтобы испытать полученные знания на практике, тебе нужно вернуться к тому, кто отправил тебя сюда." }, { 9.42, "Похоже, что твой наставник Тюрак Рунический Тотэм нашёл себе достойного ученика. Я тоже вижу в тебе большой потенциал." }, { 17.60, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать его обличье." }, { 24.73, "Возвращайся домой. Мы снова встретимся, когда придёт время." } }, f = { { 0.00, "Пришло время нам снова расстаться, дитя." }, { 2.70, "Чтобы испытать полученные знания на практике, тебе нужно вернуться к тому, кто отправил тебя сюда." }, { 9.42, "Похоже, что твой наставник Тюрак Рунический Тотэм нашёл себе достойную ученицу. Я тоже вижу в тебе большой потенциал." }, { 17.61, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать его обличье." }, { 24.74, "Возвращайся домой. Мы снова встретимся, когда придёт время." } } }, t = { d = 36.4, g = 1, v = "tauren-male#67", n = { m = 281, f = 286 }, c = { m = { { 0.00, "С возвращением. Я чувствую, что ты встретился с духом Великой Кошки и прошёл испытание." }, { 10.29, "Его проходят все друиды, но у каждого поколения оно своё. Я горжусь тем, что ты выдержал проверку и внял мудрости Великой Кошки." }, { 22.73, "Этот древний дух столь же смертоносен, сколь и игрив, хотя, чувствую, ты и сам уже это понял." }, { 32.07, "Теперь я научу тебя принимать облик кошки." } }, f = { { 0.00, "С возвращением. Я чувствую, что ты встретилась с духом Великой Кошки и прошла испытание." }, { 8.33, "Его проходят все друиды, но у каждого поколения оно своё." }, { 13.91, "Я горжусь тем, что ты выдержала проверку и вняла мудрости Великой Кошки." }, { 20.98, "Этот древний дух столь же смертоносен, сколь и игрив, хотя, чувствую, ты и сама уже это поняла." }, { 30.52, "Теперь я научу тебя принимать облик кошки." } } } } },
    [98386] = { d = 31.5, v = "human-male", n = { x = 357 }, c = { x = { { 0.00, "Орки, гноллы, мурлоки... Кажется, все только и делают, что пытаются помешать мне достроить мост к сроку." }, { 7.02, "А теперь ещё говорят, что на нашей лесопилке завелись тарантулы!" }, { 11.88, "Если хочешь немного подзаработать, сходи на лесопилку Альтера и изничтожь тамошних пауков." }, { 18.16, "Она для меня совершенно бесполезна, если нельзя отправлять туда работников за грузами без риска для жизни." }, { 25.98, "И ещё: если увидишь старика Альтера, скажи ему, что за ним теперь должок." } } }, t = { d = 10.5, v = "human-male", n = { x = 110 }, c = { x = { { 0.00, "На лесопилке всё так плохо? Хуже, чем я думал." }, { 3.50, "Я не из брезгливых, но работы и без пауков, хватающих моих рабочих, хватает. Спасибо за помощь!" } } } } },
    [98387] = { d = 32.8, v = "human-male", n = { x = 376 }, c = { x = { { 0.00, "Орки из клана Чёрной Горы этого не понимают, но идёт война на истощение." }, { 5.10, "Начав дерзкое наступление на территорию Альянса, они стали уязвимыми и лишились припасов, из-за чего им приходится рыскать по горам в поисках ресурсов." }, { 16.03, "Никакая армия не может воевать на пустой желудок." }, { 19.63, "Наведайся в их лагеря к югу от крепости Каменной Стражи на востоке и забери оттуда еду и оружие." }, { 26.39, "Посмотрим, как оркам удастся сохранить боевой дух, когда они будут голодны и беззащитны." } } }, t = { d = 9.0, v = "human-male", n = { x = 103 }, c = { x = { { 0.00, "Отличная работа. Теперь, когда орки Чёрной Горы отрезаны от союзников в Пылающих степях, без припасов им здесь не удержаться." } } } } },
    [98389] = { d = 41.9, g = 1, v = "scourge-male#83", n = { x = 437 }, c = { m = { { 0.00, "Приветствую, герой. Да, я паладин. Даже смерть не остановит Свет." }, { 5.13, "В этом мы едины со всеми Отрёкшимися – нам удалось преодолеть то, что живые считают окончанием своей истории." }, { 13.23, "Однако даже многие наши соплеменники страшатся нас. Они думают, будто мы уничтожим их как каких-то чудовищ." }, { 21.58, "На самом же деле наши отношения с посмертием весьма сложны, но причинять вред своим я не собираюсь." }, { 29.02, "Помоги мне доказать это остальным. Оправляйся в низину Ночных Пут к северо-востоку и освободи тех недавно поднявшихся дурней, что оказались там в плену у пауков." } }, f = { { 0.00, "Приветствую, героиня. Да, я паладин. Даже смерть не остановит Свет." }, { 5.81, "В этом мы едины со всеми Отрёкшимися – нам удалось преодолеть то, что живые считают окончанием своей истории." }, { 13.91, "Однако даже многие наши соплеменники страшатся нас. Они думают, будто мы уничтожим их как каких-то чудовищ." }, { 22.26, "На самом же деле наши отношения с посмертием весьма сложны, но причинять вред своим я не собираюсь." }, { 29.71, "Помоги мне доказать это остальным. Оправляйся в низину Ночных Пут к северо-востоку и освободи тех недавно поднявшихся дурней, что оказались там в плену у пауков." } } }, t = { d = 25.2, v = "scourge-male#83", n = { x = 269 }, c = { x = { { 0.00, "Надеюсь, это поможет палачу Аррену и многим другим понять нашу истинную сущность." }, { 6.14, "Как и в прошлой жизни, мы существуем для того, чтобы служить нашему народу и защищать его с помощью сил, дарованных нам Светом." }, { 15.85, "Со временем они поймут, что мы так же важны для планов Тёмной Госпожи, как и остальные Отрёкшиеся. Да пребудет с тобой Свет." } } } } },
    [98391] = { d = 24.2, g = 1, v = "nightelf-female#51", n = { m = 266, f = 267 }, c = { m = { { 0.00, "Да будешь ты благословлён, герой. Сестринство Элуны было столпом калдорай тысячи лет." }, { 6.27, "До Великого Раскола, до Войны древних, на протяжении всего Долгого бдения мы исцеляли наш народ и направляли его во тьме." }, { 14.67, "Таков наш долг и наказ Матери-Луны." }, { 17.43, "Теперь же нам нужна твоя помощь в крайне важном деле. Сестра Аквинна ждёт тебя в Дарнассе." } }, f = { { 0.00, "Да будешь ты благословлена, героиня. Сестринство Элуны было столпом калдорай тысячи лет." }, { 6.44, "До Великого Раскола, до Войны древних, на протяжении всего Долгого бдения мы исцеляли наш народ и направляли его во тьме." }, { 14.84, "Таков наш долг и наказ Матери-Луны." }, { 17.60, "Теперь же нам нужна твоя помощь в крайне важном деле. Сестра Аквинна ждёт тебя в Дарнассе." } } }, t = { d = 4.8, g = 1, v = "nightelf-female#53", n = { m = 51, f = 52 }, c = { m = { { 0.00, "Я рада, что ты так быстро прибыл. Сестринству нужна твоя помощь." } }, f = { { 0.00, "Я рада, что ты так быстро прибыла. Сестринству нужна твоя помощь." } } } } },
    [98392] = { d = 20.6, v = "nightelf-female#52", n = { x = 238 }, c = { x = { { 0.00, "Эти пояса... присмотрись к этой коже. Видишь порчу, пронизывающую волокна?" }, { 5.15, "У меня есть догадка, откуда она взялась, но нам нужны доказательства." }, { 10.05, "Вернись к гнёздам гарпий на западе и уничтожь их предводительниц." }, { 14.40, "Если в их ожерельях обитает та же тьма, что и в этих поясах, мы узнаем всё, что нам нужно." } } }, t = { d = 19.0, v = "nightelf-female#52", n = { x = 191 }, c = { x = { { 0.00, "Ариния рассматривает амулеты." }, { 2.37, "Видишь эти зловещие зелёные разводы внутри камней? Это и впрямь порча мха Скверны." }, { 8.26, "Я слышала похожие донесения из Тенистой долины и других уголков кроны: эта дрянь обращает сам наш мир против нас." }, { 16.27, "Я немедленно доложу об этом старшим." } } } } },
    [98393] = { d = 24.7, g = 1, v = "nightelf-male#59", n = { m = 284, f = 287 }, c = { m = { { 0.00, "Думаю, ты готов сделать следующий шаг на пути друида, ученик." }, { 4.13, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретился с ним на Лунной поляне." }, { 11.18, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 18.41, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } }, f = { { 0.00, "Думаю, ты готова сделать следующий шаг на пути друида, ученица." }, { 4.45, "Дендрит Блеск Звёзд прислал весточку: он хочет, чтобы ты снова встретилась с ним на Лунной поляне." }, { 11.56, "Ты уже умеешь использовать магию, которая перенесёт тебя туда, так что можешь отправляться прямо сейчас." }, { 18.79, "Я советую не откладывать это путешествие, если хочешь продолжать обучение друида." } } }, t = { d = 27.6, v = "nightelf-male#54", n = { x = 225 }, c = { x = { { 0.00, "События идут своим чередом, отец Кенарий." }, { 3.33, "Дендрит делает быстрый незаметный жест в воздухе у себя над головой, и его окутывает лёгкая аура силы." }, { 10.82, "И снова здравствуй. Пришла пора тебе изучить следующее обличье – обличье кошки." }, { 16.72, "Я наставлю тебя на путь понимания этого аспекта нашего бытия, но как и в случае с обликом медведя, усвоить знания и совершенствоваться далее – твоя забота." } } } } },
    [98394] = { d = 33.0, v = "nightelf-male#54", n = { x = 379 }, c = { x = { { 0.00, "На юге Лунной поляны, на возвышающемся над мостом холме, обитает мудрое и хитрое существо, которое мы называем духом Великой Кошки." }, { 9.43, "Подобно духу Великого Медведя, этот дух был учителем и наставником для друидов, желающих принимать кошачий облик." }, { 17.38, "Все друиды рано или поздно обращаются к нему за наставлениями." }, { 21.82, "То же предстоит и тебе, если ты захочешь научиться придавать себе облик кошки." }, { 27.65, "Встреться с духом Великой Кошки и узнай, чему он согласится тебя научить." } } }, t = { d = 8.4, g = 1, v = "tauren-female", n = { m = 77, f = 78 }, c = { m = { { 0.00, "Вижу, ты пришёл научиться взывать к моему духу. Хорошо. Посмотрим, готов ли ты принять мой облик." } }, f = { { 0.00, "Вижу, ты пришла научиться взывать к моему духу. Хорошо. Посмотрим, готова ли ты принять мой облик." } } } } },
    [98396] = { d = 48.9, g = 1, v = "tauren-female", n = { m = 472, f = 475 }, c = { m = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.16, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способен воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 19.78, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 28.19, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 34.60, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смог пробраться мимо них." }, { 42.42, "Принеси мне эти реликвии. Тогда мы узнаем, готов ли ты принимать мой облик." } }, f = { { 0.00, "Чтобы взывать к моему духу, мало нескольких слов." }, { 4.16, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способна воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 18.45, "В кельях к востоку отсюда скрыты три реликвии, символы моего покровительства, которые тебе нужно добыть." }, { 26.86, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 33.27, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смогла пробраться мимо них." }, { 41.39, "Принеси мне эти реликвии. Тогда мы узнаем, готова ли ты принимать мой облик." } } }, t = { d = 20.0, g = 1, v = "tauren-female", n = { m = 180, f = 181 }, c = { m = { { 0.00, "Превосходно. Ты доказал, что понимаешь истинную природу кошки и способен воплотить хитрость, скрытность и свирепость, необходимые, чтобы принимать мой облик." }, { 12.93, "Теперь я считаю тебя достойным моего благословения, юный герой." } }, f = { { 0.00, "Превосходно. Ты доказала, что понимаешь истинную природу кошки и способна воплотить хитрость, скрытность и свирепость, необходимые, чтобы принимать мой облик." }, { 14.45, "Теперь я считаю тебя достойной моего благословения, юная героиня." } } } } },
    [98397] = { d = 28.3, g = 1, v = "nightelf-male#54", n = { m = 331, f = 331 }, c = { m = { { 0.00, "Пришло время нам снова расстаться, дитя. Чтобы применить уроки на практике, тебе нужно вернуться к тому, кто послал тебя сюда." }, { 8.57, "Похоже, что твой наставник Матренгил Медвежья Лапа нашёл себе достойного ученика. Я тоже вижу в тебе большой потенциал." }, { 16.85, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать её обличье." }, { 23.80, "Возвращайся домой. Когда ты будешь готов, мы снова встретимся." } }, f = { { 0.00, "Пришло время нам снова расстаться, дитя. Чтобы применить уроки на практике, тебе нужно вернуться к тому, кто послал тебя сюда." }, { 8.57, "Похоже, что твой наставник Матренгил Медвежья Лапа нашёл себе достойную ученицу. Я тоже вижу в тебе большой потенциал." }, { 16.60, "Слушай своего учителя, и скоро ты научишься взывать к духу Великой Кошки и принимать её обличье." }, { 23.55, "Возвращайся домой. Когда ты будешь готова, мы снова встретимся." } } }, t = { d = 24.7, g = 1, v = "nightelf-male#59", n = { m = 270, f = 274 }, c = { m = { { 0.00, "С возвращением. Я чувствую, что ты встретился с духом Великой Кошки и прошёл испытание – его проходят все друиды, но у каждого поколения оно своё." }, { 9.86, "Ты выдержал проверку и внял мудрости Великой Кошки, и я горжусь тобой." }, { 14.62, "Этот древний дух в равной мере игрив и опасен, в чём ты, кажется, уже убедился." }, { 21.40, "Теперь я научу тебя принимать новый облик." } }, f = { { 0.00, "С возвращением. Я чувствую, что ты встретилась с духом Великой Кошки и прошла испытание – его проходят все друиды, но у каждого поколения оно своё." }, { 10.12, "Ты выдержала проверку и вняла мудрости Великой Кошки, и я горжусь тобой." }, { 14.94, "Этот древний дух в равной мере игрив и опасен, в чём ты, кажется, уже убедилась." }, { 21.10, "Теперь я научу тебя принимать новый облик." } } } } },
    [98398] = { d = 22.1, g = 1, v = "nightelf-female#52", n = { m = 262, f = 265 }, c = { m = { { 0.00, "Ты столько достиг за такое короткое время! Это очень впечатляет." }, { 4.32, "Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела." }, { 12.20, "Я заметила, что Древо-оракул только что сбросило кусок коры." }, { 16.17, "Несомненно, оно хочет, чтобы ты выполнил какое-то поручение для него. Поговори с ним." } }, f = { { 0.00, "Ты столько достигла за такое короткое время! Это очень впечатляет." }, { 4.24, "Хотелось бы мне попросить тебя задержаться здесь и помочь мне по службе... но я понимаю, что тебя ждут великие дела." }, { 12.12, "Я заметила, что Древо-оракул только что сбросило кусок коры." }, { 16.09, "Несомненно, оно хочет, чтобы ты выполнила какое-то поручение для него. Поговори с ним." } } }, t = { d = 10.5, v = "nightelf-female#52", n = { x = 127 }, c = { x = { { 0.00, "Когда вы осматриваете упавшую кору, в ваш разум проникает голос." }, { 4.38, "Он спокоен и умиротворяющ и накатывает на вас, словно лёгкий ветерок, шелестящий в листве." } } } } },
    [98403] = { d = 33.4, g = 1, v = "nightelf-male#54", n = { m = 381, f = 381 }, c = { m = { { 0.00, "Лорд Меленас действовал не один – он исполнял приказы. Того, кто их отдал, зовут Зеторр Злобный." }, { 7.04, "Похоже, он осквернил пауков, что обитают в Тельдрассиле, и замышляет использовать их яд для своих гнусных планов." }, { 15.12, "Он поселился глубоко в лесу, в месте на северо-западе отсюда, которое называют Расселиной." }, { 21.29, "Будь осторожен и возьми с собой союзников. Зеторр – очень опасный противник." }, { 26.77, "Уничтожь его стаю и принеси мне что-нибудь, что поможет нам узнать больше о действиях сатира." } }, f = { { 0.00, "Лорд Меленас действовал не один – он исполнял приказы. Того, кто их отдал, зовут Зеторр Злобный." }, { 7.04, "Похоже, он осквернил пауков, что обитают в Тельдрассиле, и замышляет использовать их яд для своих гнусных планов." }, { 15.12, "Он поселился глубоко в лесу, в месте на северо-западе отсюда, которое называют Расселиной." }, { 21.29, "Будь осторожна и возьми с собой союзников. Зеторр – очень опасный противник." }, { 26.93, "Уничтожь его стаю и принеси мне что-нибудь, что поможет нам узнать больше о действиях сатира." } } }, t = { d = 31.6, v = "nightelf-male#54", n = { x = 359 }, c = { x = { { 0.00, "Мне следовало догадаться, что именно этим отравляют пауков наших земель." }, { 5.31, "Я слышал, будто эта субстанция – источник большей части порчи, что терзает нас." }, { 10.61, "Это не первоисточник, но образец старый и может рассказать больше, чем всё, что мы добыли до сих пор." }, { 17.97, "Обычно я попросил бы тебя отправить это в Дарнас на изучение." }, { 22.15, "Но сейчас лучше не поднимать шума, иначе Доланаар никогда не восстановит свою репутацию." }, { 28.74, "Надеюсь, ты тоже сохранишь это в тайне." } } } } },
    [98404] = { d = 47.4, g = 1, v = "tauren-female", n = { m = 455, f = 457 }, c = { m = { { 0.00, "Чтобы взывать к моему духу, тебе придётся пройти испытание." }, { 4.86, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способен воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 19.45, "В кельях к востоку отсюда скрыты три реликвии, которые тебе нужно добыть." }, { 25.49, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 31.86, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смог пробраться мимо них." }, { 39.83, "Принеси мне эти реликвии, чтобы завершить испытание друидов этих земель." } }, f = { { 0.00, "Чтобы взывать к моему духу, тебе придётся пройти испытание." }, { 4.86, "Получить полное понимание моей формы и истинное уважение к ней можно, доказав, что ты способна воплощать её хитрость, незаметность и, если тебя загнали в угол, неукротимость." }, { 20.66, "В кельях к востоку отсюда скрыты три реликвии, которые тебе нужно добыть." }, { 26.70, "Их охраняют могущественные яростные духи, которые нападут, если заметят тебя." }, { 33.07, "Статуя у входа благословит тебя временной незаметностью, чтобы ты смогла пробраться мимо них." }, { 41.14, "Принеси мне эти реликвии, чтобы завершить испытание друидов этих земель." } } }, t = { d = 16.9, g = 1, v = "tauren-female", n = { m = 156, f = 158 }, c = { m = { { 0.00, "Превосходно. Ты доказал, что понимаешь истинную природу кошки и способен на хитрость, скрытность и безжалостность, необходимые, чтобы принимать мою форму. Ты достоин моего благословения." } }, f = { { 0.00, "Превосходно. Ты доказала, что понимаешь истинную природу кошки и способна на хитрость, скрытность и безжалостность, необходимые, чтобы принимать мою форму. Ты достойна моего благословения." } } } } },
    [98405] = { d = 36.8, v = "human-male#114", n = { x = 379 }, c = { x = { { 0.00, "На юге Лунной поляны, на возвышающемся над мостом холме, обитает мудрое и хитрое существо, которое мы называем духом Великой Кошки." }, { 10.67, "Подобно духу Великого Медведя, этот дух был учителем и наставником для друидов, желающих принимать кошачий облик." }, { 19.43, "Все друиды рано или поздно обращаются к нему за наставлениями." }, { 24.40, "То же предстоит и тебе, если ты захочешь научиться придавать себе облик кошки." }, { 30.83, "Встреться с духом Великой Кошки и узнай, чему он согласится тебя научить." } } }, t = { d = 7.9, g = 1, v = "human-male#114", n = { m = 77, f = 78 }, c = { m = { { 0.00, "Вижу, ты пришёл научиться взывать к моему духу. Хорошо. Посмотрим, готов ли ты принять мой облик." } }, f = { { 0.00, "Вижу, ты пришла научиться взывать к моему духу. Хорошо. Посмотрим, готова ли ты принять мой облик." } } } } },
    [98407] = { d = 34.4, v = "human-male", n = { x = 389 }, c = { x = { { 0.00, "Раз уж гноллы так осмелели, что разбивают лагерь столь близко к людям, то неизвестно, на что ещё они готовы пойти. Нам нужно их отпугнуть." }, { 9.86, "Этим тварям не хватает организованности, а больше всего они, похоже, ценят силу." }, { 15.37, "Если убьём их вожаков и заберём какие-нибудь трофеи, то напомним этим гноллам, почему им следует сидеть на их холмах и не высовывать оттуда нос." }, { 25.77, "Если ты повстречаешь их твердозубов, принеси мне их ошейники. Так мы заставим их дрожать в страхе перед мощью Альянса." } } }, t = { d = 10.5, g = 1, v = "human-male", n = { m = 110, f = 112 }, c = { m = { { 0.00, "Ну и охапку ты принёс." }, { 1.82, "Это не решает наших проблем, но теперь я могу быть спокоен: мы отбили у гноллов охоту лезть дальше. Отличная работа." } }, f = { { 0.00, "Ну и охапку ты принесла." }, { 2.11, "Это не решает наших проблем, но теперь я могу быть спокоен: мы отбили у гноллов охоту лезть дальше. Отличная работа." } } } } },
    [98423] = { d = 24.8, v = "human-male#114", n = { x = 267 }, c = { x = { { 0.00, "В хранилище ты найдёшь табличку с подробным описанием условий мирного договора между кланом Громового Молота и Бронзобородами." }, { 9.89, "По всей видимости, он относится к периоду сразу после Войны Трёх Кланов и, вероятно, является важным историческим документом." }, { 19.64, "Король Стальгорна, несомненно, заинтересуется этим артефактом." } } }, t = { d = 30.3, g = 1, v = "dwarf-male#177", n = { m = 339, f = 342 }, c = { m = { { 0.00, "Ах да, мой предок Мадоран был первым королём Стальгорна из Бронзобородов после великой гражданской войны между кланами Громового Молота, Бронзобородов и Чёрного Железа." }, { 12.25, "Этот договор составили, чтобы закрепить прекращение вражды и условия мира после того, как Бронзобороды отстояли гору." }, { 21.20, "Как видишь, Громовой Молот и Бронзобороды его подписали... а клан Чёрного Железа – нет." }, { 27.03, "Спасибо, что вернул его и принёс мне, герой." } }, f = { { 0.00, "Ах да, мой предок Мадоран был первым королём Стальгорна из Бронзобородов после великой гражданской войны между кланами Громового Молота, Бронзобородов и Чёрного Железа." }, { 12.00, "Этот договор составили, чтобы закрепить прекращение вражды и условия мира после того, как Бронзобороды отстояли гору." }, { 20.95, "Как видишь, Громовой Молот и Бронзобороды его подписали... а клан Чёрного Железа – нет." }, { 26.78, "Спасибо, что вернула его и принесла мне, героиня." } } } } },
    [98424] = { d = 25.5, v = "human-male#114", n = { x = 277 }, c = { x = { { 0.00, "Несколько особенно потрёпанных бумаг нашлось отдельно, сложенными во внутреннем нагрудном кармане Шумовика." }, { 8.71, "Кажется, в них содержится важная информация, которую можно использовать против Торговой Компании и её предприятий в регионе." }, { 18.12, "Было бы разумно собрать побольше информации, прежде чем возвращаться к Морину Ловцу Облаков." } } }, t = { d = 9.5, v = "human-male#114", n = { x = 68 }, c = { x = { { 0.00, "О, это очень ценные сведения. Благодарю за труды. Морин просматривает заметки." }, { 6.41, "Похоже, наш следующий шаг очевиден." } } } } },
    [98427] = { d = 41.4, v = "tauren-male", n = { x = 404 }, c = { x = { { 0.00, "Я уже видел крошшеры вроде того, о котором говорится на одной из страниц, в ходе моих путешествий." }, { 7.66, "Они могут вырубать лес во много раз быстрее, чем обычные дровосеки." }, { 13.39, "Рощи, тысячелетиями служившие домом детям Матери-Земли, исчезают навсегда за считанные дни." }, { 21.10, "Мы не позволим этому случиться у нас дома, вблизи того места, где наш молодняк делает свои первые шаги." }, { 29.66, "Я должен попросить тебя собрать отряд, вернуться в шахту на северо-востоке и убедиться, что крошшер не срубит больше ни одного дерева." } } }, t = { d = 8.9, v = "tauren-male", n = { x = 82 }, c = { x = { { 0.00, "Вся деревня Кровавого Копыта сегодня в долгу перед тобой. Да пребудет с тобой милость Матери-Земли." } } } } },
    [98430] = { d = 42.5, g = 1, v = "tauren-male#68", n = { x = 396 }, c = { m = { { 0.00, "Приветствую, герой. Что привело тебя в такое мрачное и суровое место?" }, { 5.77, "Меня послал сюда верховный вождь Кэрн Кровавое Копыто, чтобы попытаться наладить контакт с поселившимися тут гноллами." }, { 15.02, "Другая часть моего задания должна оставаться в тайне, как и всё, что касается дальноходов, доверенных разведчиков нашего вождя." }, { 25.15, "Знай, что ответом на нашу дипломатию стало насилие, и я боюсь, что сегодня вечером стану главным блюдом на пиру у гноллов, если ты меня отсюда не вызволишь. Ты поможешь мне?" } }, f = { { 0.00, "Приветствую, героиня. Что привело тебя в такое мрачное и суровое место?" }, { 5.75, "Меня послал сюда верховный вождь Кэрн Кровавое Копыто, чтобы попытаться наладить контакт с поселившимися тут гноллами." }, { 15.00, "Другая часть моего задания должна оставаться в тайне, как и всё, что касается дальноходов, доверенных разведчиков нашего вождя." }, { 25.14, "Знай, что ответом на нашу дипломатию стало насилие, и я боюсь, что сегодня вечером стану главным блюдом на пиру у гноллов, если ты меня отсюда не вызволишь. Ты поможешь мне?" } } }, t = { d = 27.7, g = 1, v = "named/3057", n = { m = 315, f = 317 }, c = { m = { { 0.00, "Я рад, что дальноход Грозовое Копыто цел. Он мой самый доверенный разведчик, а его задание крайне важно." }, { 7.40, "Прими мою благодарность и гостеприимство за то, что рисковал жизнью ради его спасения." }, { 13.23, "Ты оказал нашему народу большую услугу, чем думаешь." }, { 17.22, "Пока ты здесь, осмотри наш великий город." }, { 20.07, "Здесь безопасно, и на его утёсах ты найдёшь многих, кто поможет тебе в твоих странствиях. Иш-не-ало пор-а." } }, f = { { 0.00, "Я рад, что дальноход Грозовое Копыто цел. Он мой самый доверенный разведчик, а его задание крайне важно." }, { 7.40, "Прими мою благодарность и гостеприимство за то, что рисковала жизнью ради его спасения." }, { 13.35, "Ты оказала нашему народу большую услугу, чем думаешь." }, { 17.40, "Пока ты здесь, осмотри наш великий город." }, { 20.25, "Здесь безопасно, и на его утёсах ты найдёшь многих, кто поможет тебе в твоих странствиях. Иш-не-ало пор-а." } } } } },
    [98435] = { d = 25.5, v = "human-male#114", n = { x = 270 }, c = { x = { { 0.00, "Необходимо оповестить старейшин в Громовом Утёсе о прогрессе, которого мы достигли благодаря твоей помощи." }, { 8.53, "Пожалуйста, отнеси это верховному друиду Хамуулу Руническому Тотэму в Громовой Утёс." }, { 15.24, "Ты найдёшь его на Вершине Старейшин в восточной части города." }, { 19.70, "Для этого поднимись на лифте к центу города, а затем пройди по мостам." } } }, t = { d = 26.2, g = 1, v = "tauren-male", n = { m = 230, f = 231 }, c = { m = { { 0.00, "Ах, неудивительно, что по ручьям Мулгора струится такая радость. Сегодня ты оказал нам великую услугу." }, { 8.85, "Колодцы дают многое не только нашему народу, но и зверям, от которых зависят наша пища, одежда и дружба." }, { 18.16, "Для меня честь исполнить просьбу Мулла. Прими этот знак моей благодарности." } }, f = { { 0.00, "Ах, неудивительно, что по ручьям Мулгора струится такая радость. Сегодня ты оказала нам великую услугу." }, { 10.46, "Колодцы дают многое не только нашему народу, но и зверям, от которых зависят наша пища, одежда и дружба." }, { 19.78, "Для меня честь исполнить просьбу Мулла. Прими этот знак моей благодарности." } } } } },
    [98447] = { d = 34.2, g = 1, v = "human-male", n = { m = 372, f = 373 }, c = { m = { { 0.00, "Хоть ты и упокоил призраков семьи Валор, сообщения о нападениях не прекращаются." }, { 6.17, "Попытка была хорошая, но, похоже, их незавершённые дела мы так и не уладили." }, { 11.77, "Судя по тому, что мне удалось выяснить, вся эта семья пропала в одно и то же время." }, { 17.54, "Что бы ни приковало их души к этому миру, это случилось со всеми сразу." }, { 23.29, "Наша единственная зацепка – место, где ты нашёл книгу. Возвращайся на Вороний холм и посмотри, что удастся найти." }, { 31.09, "Может быть, их оружие что-нибудь пробудит." } }, f = { { 0.00, "Хоть ты и упокоила призраков семьи Валор, сообщения о нападениях не прекращаются." }, { 6.11, "Попытка была хорошая, но, похоже, их незавершённые дела мы так и не уладили." }, { 11.71, "Судя по тому, что мне удалось выяснить, вся эта семья пропала в одно и то же время." }, { 17.48, "Что бы ни приковало их души к этому миру, это случилось со всеми сразу." }, { 23.24, "Наша единственная зацепка – место, где ты нашла книгу. Возвращайся на Вороний холм и посмотри, что удастся найти." }, { 31.02, "Может быть, их оружие что-нибудь пробудит." } } } },
    [98459] = { d = 36.1, v = "human-male#114", n = { x = 360 }, c = { x = { { 0.00, "Барт Приливень – никудышный скряга, уж поверь!" }, { 3.83, "Зовёт себя капитаном \"Девичьей Чести\". Да этот корабль проплыл в Танарисе не дальше брошенного камня!" }, { 11.65, "Он не капитан, а притворщик, который просто выиграл денег в покер и купил \"Честь\"!" }, { 18.16, "Если ты когда-нибудь окажешься в Гавани Менетилов в Болотине, передай ему это и скажи, что это от старины \"Полурыба\"." }, { 27.31, "Кстати, отсюда прямо в гавань ходит корабль. Вторая остановка – твоя!" }, { 32.99, "И помни, что в покере он жульничает!" } } }, t = { d = 31.9, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "Барт разворачивает подарок. Ах ты ж никчёмный сукин..." }, { 3.98, "Он хоть сказал тебе, что это ОН жульничает в покере?!" }, { 7.74, "Я выиграл денег на \"Девичью Честь\" только после того, как мы вышвырнули его из нашего покерного кружка!" }, { 16.40, "Клянусь, когда я в следующий раз увижу эту бесполезную морскую водицу..." }, { 21.64, "Прости, прости. Нечего срываться на гонце." }, { 24.67, "От имени команды \"Девичьей Чести\" – лучшего корабля Великого моря – добро пожаловать в Гавань Менетилов!" } } } } },
    [98461] = { d = 38.2, v = "dwarf-female#33", n = { x = 398 }, c = { x = { { 0.00, "Если ты собираешься покинуть Аубердин, мне бы пригодилась твоя помощь!" }, { 5.28, "Мы с моим дорогим другом Таррелом были одноклассниками. О, во всём, что касалось раскопок, он был таким сообразительным!" }, { 13.47, "После окончания школы жизнь разбросала нас по миру: он отправился в Болотину, а я сюда, на Тёмные берега." }, { 21.07, "Холли вздыхает, затем слегка хмурится. Извини. Его жена... Меррин..." }, { 25.90, "Впрочем, неважно. Если окажешься в Болотине, можешь узнать, как у него дела? И, может, передашь ему это?" }, { 32.89, "Он, вероятно, где-то неподалёку от Гавани Менетилов. Туда ходит корабль." } } }, t = { d = 21.8, v = "dwarf-male", n = { x = 220 }, c = { x = { { 0.00, "Таррел читает записку. Ох... ох, надо же. Бедная Холли." }, { 4.05, "Она всегда была ко мне неравнодушна. И, по правде говоря, было время, когда я ответил бы ей взаимностью. Но я женат. Счастливо женат!" }, { 13.33, "Думаю, лучше всего будет не отвечать. Не знаю, как мягко ей отказать, да и здесь у меня заботы поважнее! Моя жена пропала!" } } } } },
    [98512] = { d = 20.2, g = 1, v = "bloodelf-male", n = { m = 215, f = 215 }, c = { m = { { 0.00, "Эй, незнакомец. Пригнись и не шуми. Мы не одни здесь." }, { 4.00, "Я патрулировал границу и заметил группу ал'акетов возле дома на холме, что к северу отсюда." }, { 10.29, "Не знаю, что они там делают, но явно ничего хорошего." }, { 14.39, "Если хочешь помочь, пойди и устрани их. Я подожду здесь – прикрою тебе спину." } }, f = { { 0.00, "Эй, незнакомка. Пригнись и не шуми. Мы не одни здесь." }, { 4.15, "Я патрулировал границу и заметил группу ал'акетов возле дома на холме, что к северу отсюда." }, { 10.44, "Не знаю, что они там делают, но явно ничего хорошего." }, { 14.54, "Если хочешь помочь, пойди и устрани их. Я подожду здесь – прикрою тебе спину." } } }, t = { d = 11.3, g = 1, v = "bloodelf-male", n = { m = 124, f = 125 }, c = { m = { { 0.00, "Хорошо, что ты вернулся в целости. Те ал'акеты выглядели как безжалостные головорезы." }, { 6.14, "Спасибо за помощь. Я упомяну это в отчёте, когда вернусь в Валанаар." } }, f = { { 0.00, "Хорошо, что ты вернулась в целости. Те ал'акеты выглядели как безжалостные головорезы." }, { 6.21, "Спасибо за помощь. Я упомяну это в отчёте, когда вернусь в Валанаар." } } } } },
    [98517] = { d = 19.7, g = 1, v = "human-male#114", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Приветствую, юный небеснорождённый. Духи говорили о тебе, и они сказали, что ты готов ответить на зов огня." }, { 8.31, "Но наставлять тебя на этом пути предстоит не мне. Возвращайся домой в мир стихий и разыщи там своих наставников. Они скажут, что нужно сделать." } }, f = { { 0.00, "Приветствую, юная небеснорождённая. Духи говорили о тебе, и они сказали, что ты готова ответить на зов огня." }, { 8.36, "Но наставлять тебя на этом пути предстоит не мне. Возвращайся домой в мир стихий и разыщи там своих наставников. Они скажут, что нужно сделать." } } } },
    [98545] = { d = 30.0, g = 1, v = "scourge-male", n = { m = 272, f = 274 }, c = { m = { { 0.00, "Раз уж ты тут, я хочу, чтобы ты отнёс это письмо моему старому другу в Подгород." }, { 5.94, "Я мог бы и сам это сделать, но у нас с Тёмной Госпожой ранее возникали некоторые разногласия, поэтому лучше, если письмо доставит кто-то сторонний." }, { 17.01, "Найди гоблина по имени Гликс Ксиззикс в Торговом квартале Подгорода. Думаю, он с радостью оплатит твою услугу." }, { 25.56, "Леонид издаёт негромкий смешок, протягивая вам письмо." } }, f = { { 0.00, "Раз уж ты тут, я хочу, чтобы ты отнесла это письмо моему старому другу в Подгород." }, { 6.03, "Я мог бы и сам это сделать, но у нас с Тёмной Госпожой ранее возникали некоторые разногласия, поэтому лучше, если письмо доставит кто-то сторонний." }, { 17.10, "Найди гоблина по имени Гликс Ксиззикс в Торговом квартале Подгорода. Думаю, он с радостью оплатит твою услугу." }, { 25.65, "Леонид издаёт негромкий смешок, протягивая вам письмо." } } }, t = { d = 23.1, g = 1, v = "goblin-male#110", n = { m = 257, f = 256 }, c = { m = { { 0.00, "Спасибо за доставку, приятель." }, { 2.53, "Постой... он сказал, что я тебе заплачу? Я на такое не подписывался!" }, { 7.50, "Ладно. Выбирай, что хочешь, из этого хлама в бюро находок. Ты не поверишь, сколько Отрёкшихся забывают свои вещи после стрижки." }, { 16.27, "Тут напрашивается шутка про безмозглых, но подозреваю, что во многих случаях это чистая правда." } }, f = { { 0.00, "Спасибо за доставку, подруга." }, { 2.41, "Постой... он сказал, что я тебе заплачу? Я на такое не подписывался!" }, { 7.38, "Ладно. Выбирай, что хочешь, из этого хлама в бюро находок. Ты не поверишь, сколько Отрёкшихся забывают свои вещи после стрижки." }, { 16.15, "Тут напрашивается шутка про безмозглых, но подозреваю, что во многих случаях это чистая правда." } } } } },
    [98574] = { d = 13.7, g = 1, v = "dwarf-male", n = { m = 158, f = 159 }, c = { m = { { 0.00, "Пока ты мне помогал, меня попросили передать тебе этот меморандум. Почитай его на досуге." }, { 6.16, "Думаю, его прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне." } }, f = { { 0.00, "Пока ты мне помогала, меня попросили передать тебе этот меморандум. Почитай его на досуге." }, { 6.24, "Думаю, его прислал Брансток, наставник жрецов. Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 24.3, g = 1, v = "dwarf-male", n = { m = 281, f = 282 }, c = { m = { { 0.00, "Со временем и практикой ты откроешь новые грани Света." }, { 3.88, "В некотором роде это поиск единства между тем, что ты думаешь, и тем, что ты чувствуешь." }, { 9.85, "Когда твоя связь со Светом окрепнет, возвращайся ко мне и расскажи, что узнал." }, { 15.30, "Я с радостью покажу, как обратиться к этой силе, чтобы исцелять или карать нечестивых. За небольшое пожертвование, разумеется!" } }, f = { { 0.00, "Со временем и практикой ты откроешь новые грани Света." }, { 3.88, "В некотором роде это поиск единства между тем, что ты думаешь, и тем, что ты чувствуешь." }, { 9.85, "Когда твоя связь со Светом окрепнет, возвращайся ко мне и расскажи, что узнала." }, { 15.37, "Я с радостью покажу, как обратиться к этой силе, чтобы исцелять или карать нечестивых. За небольшое пожертвование, разумеется!" } } } } },
    [98575] = { d = 17.0, v = "orc-male#60", n = { x = 183 }, c = { x = { { 0.00, "А! Тебе тут скрижаль прислали, пока тебя не было." }, { 4.08, "Я лично стараюсь не иметь дела с чернокнижниками, однако ты её всё-таки прочитай, когда время будет." }, { 11.16, "Это, кажется, от твоего нового наставника, Нартока. Он хочет с тобой поговорить." } } }, t = { d = 21.9, g = 1, v = "orc-male", n = { m = 237, f = 238 }, c = { m = { { 0.00, "Ты лишь мельком увидел силу, что может стать твоей." }, { 3.63, "Слабые и глупые боятся пути, которым мы идём, но смелость и хитрость позволяют нам самим решать свою судьбу." }, { 11.77, "Береги свои силы. Трусы нападают на то, чего не понимают." }, { 16.17, "Теперь ты один из нас. Понадобится обучение заклинаниям – возвращайся ко мне." } }, f = { { 0.00, "Ты лишь мельком увидела силу, что может стать твоей." }, { 3.69, "Слабые и глупые боятся пути, которым мы идём, но смелость и хитрость позволяют нам самим решать свою судьбу." }, { 11.83, "Береги свои силы. Трусы нападают на то, чего не понимают." }, { 16.23, "Теперь ты одна из нас. Понадобится обучение заклинаниям – возвращайся ко мне." } } } } },
    [98576] = { d = 13.1, v = "orc-male#60", n = { x = 142 }, c = { x = { { 0.00, "О, пока тебя не было, тут прислали пергамент." }, { 3.66, "Прочти на досуге. Если не ошибаюсь, он от наставницы магов Май'ах." }, { 8.12, "Она хочет перемолвиться с тобой словечком, когда ты найдёшь время." } } }, t = { d = 21.7, g = 1, v = "troll-female#73", n = { m = 245, f = 247 }, c = { m = { { 0.00, "Магия, что течёт сквозь тебя, – величайшая сила во вселенной, но тут нужно терпение. Жди идеального момента для удара." }, { 7.79, "Выбирай верный ответ на любую задачу. Будь умнее, смотри в оба – и тебе всё будет по плечу." }, { 14.24, "Когда решишь, что готов учиться, возвращайся к Май'а. Она научит тебя тому, к чему ты готов, без проблем." } }, f = { { 0.00, "Магия, что течёт сквозь тебя, – величайшая сила во вселенной, но тут нужно терпение. Жди идеального момента для удара." }, { 7.79, "Выбирай верный ответ на любую задачу. Будь умнее, смотри в оба – и тебе всё будет по плечу." }, { 14.24, "Когда решишь, что готова учиться, возвращайся к Май'а. Она научит тебя тому, к чему ты готова, без проблем." } } } } },
    [98581] = { d = 17.7, v = "dwarf-male", n = { x = 201 }, c = { x = { { 0.00, "Меня тут попросили передать тебе благодарность за помощь и вот эту руну. Изучи её, когда будет время." }, { 6.95, "Это руна Громового Молота – скорее всего, её прислал Тео Молотошторм, наставник шаманов." }, { 13.54, "Если представится случай, отыщи его в Старой Наковальне." } } }, t = { d = 20.2, v = "dwarf-male", n = { x = 241 }, c = { x = { { 0.00, "Шаманское искусство долгие годы хранил клан Громового Молота, а теперь эти знания перешли и к дворфам Бронзобородам." }, { 8.01, "Я здесь, чтобы распространять это учение и наставлять новых шаманов, познающих пути стихий." }, { 14.32, "Приходи ко мне, если понадобится обучение заклинаниям земли, воздуха, огня и воды." } } } } },
    [98601] = { d = 26.8, g = 1, v = "scourge-male#82", n = { m = 231, f = 232 }, c = { m = { { 0.00, "Пока ты разбирался с безмозглыми тварями Плети, тебе тут свиток прислали." }, { 6.78, "От него так и несёт магией Света, так что, полагаю, для паладина типа тебя он должен быть важен." }, { 15.96, "Прочитай его, прежде чем отправляться дальше в путь. Только сперва отойди подальше – мне рядом с паладином не по себе." } }, f = { { 0.00, "Пока ты разбиралась с безмозглыми тварями Плети, тебе тут свиток прислали." }, { 6.82, "От него так и несёт магией Света, так что, полагаю, для паладина типа тебя он должен быть важен." }, { 16.00, "Прочитай его, прежде чем отправляться дальше в путь. Только сперва отойди подальше – мне рядом с паладином не по себе." } } }, t = { d = 19.8, g = 1, v = "scourge-male#83", n = { m = 202, f = 203 }, c = { m = { { 0.00, "Теперь твоё обучение начнётся по-настоящему, герой." }, { 3.87, "Я вижу в тебе большие задатки, но смотри не отворачивайся от Света, даже на мгновение. Прими боль, которую он тебе причинит." }, { 13.11, "Эта боль – горнило, и из него ты выйдешь сильнее, чем был когда-либо в прошлой жизни." } }, f = { { 0.00, "Теперь твоё обучение начнётся по-настоящему, героиня." }, { 3.99, "Я вижу в тебе большие задатки, но смотри не отворачивайся от Света, даже на мгновение. Прими боль, которую он тебе причинит." }, { 13.23, "Эта боль – горнило, и из него ты выйдешь сильнее, чем была когда-либо в прошлой жизни." } } } } },
    [98731] = { d = 21.2, v = "tauren-female", n = { x = 170 }, c = { x = { { 0.00, "Теперь, получив моё благословение, возвращайся к Дендриту. Он расскажет, что делать дальше. Надеюсь, однажды мы встретимся снова." }, { 13.58, "Пусть тени всегда скрывают тебя, а твои враги оказываются у тебя в когтях, дитя." } } } },
    [98738] = { d = 30.7, g = 1, v = "tauren-female", n = { m = 288, f = 288 }, c = { m = { { 0.00, "Теперь, получив моё благословение, возвращайся к Дендриту. Он расскажет, что делать дальше." }, { 8.34, "К сожалению, сейчас мне больше нечему тебя научить. Надеюсь, ты ещё придёшь повидаться со мной на Зефрисе." }, { 16.90, "Я чувствую, что тебя ждут великие дела, юный шен'дорай." }, { 21.63, "Пусть тени всегда скрывают тебя, твои враги оказываются у тебя в когтях, а ветра направляют тебя в пути." } }, f = { { 0.00, "Теперь, получив моё благословение, возвращайся к Дендриту. Он расскажет, что делать дальше." }, { 8.34, "К сожалению, сейчас мне больше нечему тебя научить. Надеюсь, ты ещё придёшь повидаться со мной на Зефрисе." }, { 16.90, "Я чувствую, что тебя ждут великие дела, юная шен'дорай." }, { 21.76, "Пусть тени всегда скрывают тебя, твои враги оказываются у тебя в когтях, а ветра направляют тебя в пути." } } }, t = { d = 33.1, v = "nightelf-male#54", n = { x = 252 }, c = { x = { { 0.00, "Когда вы приближаетесь, Дендрит делает едва заметный жест у себя над головой." }, { 5.34, "Его окутывает новая аура могущества, а на губах появляется лёгкая улыбка." }, { 10.88, "Я чувствую в тебе кошачью хитрость и неукротимость, которых не было, когда я отправил тебя на встречу с духом Великой Кошки." }, { 19.46, "По твоим глазам я вижу, что теперь ты обладаешь хитростью и скоростью, которые нужны, чтобы постичь кошачью природу." }, { 27.89, "Используй этот урок, чтобы призывать дух кошки и принимать её облик." } } } } },
    [98739] = { d = 19.9, v = "tauren-female", n = { x = 170 }, c = { x = { { 0.00, "Теперь, получив моё благословение, возвращайся к Дендриту. Он расскажет, что делать дальше. Надеюсь, однажды мы встретимся снова." }, { 12.22, "Пусть тени всегда скрывают тебя, а твои враги оказываются у тебя в когтях, дитя." } } }, t = { d = 35.7, v = "nightelf-male#54", n = { x = 272 }, c = { x = { { 0.00, "Когда вы приближаетесь, Дендрит делает ещё один незаметный жест в воздухе у себя над головой." }, { 6.41, "Его окутывает новая аура силы, и он едва заметно улыбается." }, { 10.86, "Я чувствую в тебе кошачью хитрость и свирепость, которых не было, когда я отправил тебя к духу Великой Кошки." }, { 18.31, "По твоим глазам я вижу, что теперь ты понимаешь, какие скрытность и быстрота нужны, чтобы перенять эту природу." }, { 27.70, "Теперь ты можешь научиться сосредотачивать свою хитрость, принимать истинную природу кошки и взывать к её духу." } } } } },
    [99046] = { d = 32.7, v = "nightelf-female#52", n = { x = 397 }, c = { x = { { 0.00, "Некоторое время назад Совет Леса отправил к Древу-оракулу небольшой отряд часовых." }, { 5.50, "Древо передаёт послания нашим старейшинам, и мы должны в целости доставлять их в Дарнасс." }, { 11.68, "До меня дошли вести, что наша последняя бегунья так и не вернулась." }, { 15.88, "Послания Оракула приходят когда чаще, когда реже, но на этот раз прошло слишком много времени." }, { 22.50, "Прошу, отправляйся на запад по дороге к Поляне Оракула и узнай, что с ней." }, { 27.19, "Была очередь Эралии Листотень, а она ещё только учится. Да направит тебя Элуна." } } }, t = { d = 3.1, v = "nightelf-female#52", n = { x = 31 }, c = { x = { { 0.00, "Милость Элуны... Я не умру... в одиночестве..." } } } } },
    [99047] = { d = 14.1, v = "nightelf-female#52", n = { x = 112 }, c = { x = { { 0.00, "Меня с сёстрами... отправили... Древо-оракул..." }, { 3.17, "Древо... послание. Я... гарпии... повсюду..." }, { 6.34, "Эралия кашляет кровью, морщась от боли." }, { 9.36, "Мне недолго осталось... никто не придёт. Прошу... Бьянси... в Доланааре..." } } }, t = { d = 11.5, v = "nightelf-female#53", n = { x = 128 }, c = { x = { { 0.00, "Гарпии поражены той же скверной, что проявляется по всему лесу. Уверена, именно она терзает и часового Эралию." }, { 7.90, "Нужно спешить. Скоро она не выдержит своих ран." } } } } },
    [99048] = { d = 24.0, v = "orc-male", n = { x = 270 }, c = { x = { { 0.00, "Одна воительница из Изувеченной Длани – клана, известного своей... изощрённой тактикой, – наблюдала за крепостью Тирагард издалека." }, { 9.03, "Внезапно мы перестали получать от неё донесения." }, { 12.93, "Вряд ли её могли схватить люди – боюсь, как бы тут не было замешано что-то более серьёзное. Постарайся её найти." }, { 20.81, "Надеюсь, её доклад просто задерживается." } } }, t = { d = 9.9, v = "orc-female", n = { x = 108 }, c = { x = { { 0.00, "Окоченевшее тело Хеглан лежит среди обломков хижины." }, { 4.16, "Непохоже, что её убил человек. Возможно, рядом найдётся какая-нибудь зацепка." } } } } },
    [99049] = { d = 15.2, v = "orc-female", n = { x = 0 }, c = { x = { { 0.00, "Всё вокруг было разрушено в бою. Существам, напавшим на Хеглан, тоже крепко досталось." }, { 6.13, "Рядом наверняка найдутся следы, которые укажут, что произошло." }, { 10.90, "Лучше собрать для Оргнила зацепки, оставленные атакующими." } } }, t = { d = 14.0, v = "orc-male", n = { x = 143 }, c = { x = { { 0.00, "Это же знамя наг. И осколок клинка тоже их! Должно быть, они пришли с северного берега." }, { 7.21, "Нельзя позволить им здесь закрепиться. Колючий Холм не сможет воевать на два фронта сразу." } } } } },
    [99050] = { d = 35.6, v = "nightelf-female#53", n = { x = 402 }, c = { x = { { 0.00, "Мне нужна твоя помощь, чтобы раздобыть ингредиенты." }, { 3.37, "С ними я смогу сдержать болезнь достаточно долго, чтобы Эралию успели доставить сюда для дальнейшего лечения." }, { 11.21, "К счастью, наш живой дом всё ещё щедр и не оставит нас в час нужды." }, { 16.02, "Главный ингредиент – листья росистого хлестуна." }, { 19.23, "Ты найдёшь их у озера Аль'Амет прямо к югу отсюда или у Родникового озера и его реки к северо-западу." }, { 27.09, "Ещё мне понадобятся пустой флакон и немного родниковой воды. И то и другое можно купить здесь, в деревне, или выменять." } } }, t = { d = 9.4, v = "nightelf-female#53", n = { x = 101 }, c = { x = { { 0.00, "Спасибо за помощь. Прошу, прими это, чтобы покрыть расходы на флакон и воду." }, { 5.58, "А теперь приготовлю мазь. Это займёт всего минуту." } } } } },
    [99051] = { d = 17.5, v = "orc-male", n = { x = 191 }, c = { x = { { 0.00, "Эти ползучие твари уже не в первый раз к нам лезут. Надо втолковать им, что мы не потерпим их присутствие." }, { 7.92, "Найди, где закрепились их разведчики, и убей всех. В доказательство принеси их плавники. Надо действовать быстро, чтобы нас поняли." } } }, t = { d = 9.8, v = "orc-male", n = { x = 111 }, c = { x = { { 0.00, "Надеюсь, это заставит их убраться обратно на север." }, { 3.61, "Велю паре бойцов присматривать, не объявятся ли отставшие или какие-нибудь фокусы." } } } } },
    [99052] = { d = 21.7, v = "orc-male", n = { x = 242 }, c = { x = { { 0.00, "Один из наших разведчиков сообщил, что за теми нагами сюда пришёл морской великан." }, { 5.94, "Не знаю, специально они его привели или нет, но он очень опасен." }, { 10.95, "Великан ещё молодой, но даже такой запросто порвёт зазевавшегося орка пополам. Надо от него избавиться." }, { 18.32, "Только советую позвать для этого пару друзей." } } }, t = { d = 11.2, v = "orc-male", n = { x = 117 }, c = { x = { { 0.00, "Ха! Я отсюда слышал, как рухнула его туша!" }, { 3.76, "Гордись сегодняшней победой – немногие могут похвастаться, что пережили схватку с морским великаном." } } } } },
    [99053] = { d = 25.1, g = 1, v = "nightelf-female#52", n = { m = 289, f = 290 }, c = { m = { { 0.00, "Мои молитвы услышаны! Какое счастье, что ты сюда пробился." }, { 4.29, "Древо-оракул отправило меня сюда, чтобы передать послание спящим друидам, но когда я пришла, оказалось, что тут повсюду фурболги!" }, { 12.88, "Они набросились на меня прежде, чем я успела уйти, и утащили вниз – боюсь, припасли на ужин." }, { 19.26, "Не знаю как ты, но я не хочу здесь больше оставаться. Калдорай не место под землёй." } }, f = { { 0.00, "Мои молитвы услышаны! Какое счастье, что ты сюда пробилась." }, { 4.23, "Древо-оракул отправило меня сюда, чтобы передать послание спящим друидам, но когда я пришла, оказалось, что тут повсюду фурболги!" }, { 12.83, "Они набросились на меня прежде, чем я успела уйти, и утащили вниз – боюсь, припасли на ужин." }, { 19.20, "Не знаю как ты, но я не хочу здесь больше оставаться. Калдорай не место под землёй." } } }, t = { d = 14.4, g = 1, v = "nightelf-female#52", n = { m = 167, f = 170 }, c = { m = { { 0.00, "Хвала Элуне, что ты оказался рядом и спас Линессу от страшной участи в лапах Кривой Сосны." }, { 5.91, "Она одна из наших лучших и мой близкий друг." }, { 9.26, "Прими это в знак благодарности. Пусть послужит тебе на страже калдорай." } }, f = { { 0.00, "Хвала Элуне, что ты оказалась рядом и спасла Линессу от страшной участи в лапах Кривой Сосны." }, { 5.99, "Она одна из наших лучших и мой близкий друг." }, { 9.34, "Прими это в знак благодарности. Пусть послужит тебе на страже калдорай." } } } } },
    [99073] = { d = 16.2, v = "nightelf-female#53", n = { x = 174 }, c = { x = { { 0.00, "Мазь готова. Скорее отнеси её Эралии." }, { 3.28, "Не знаю, исцелит ли она её по-настоящему. Гниль разъедает быстро и набирает силу по мере распространения." }, { 10.81, "Но она хотя бы облегчит её страдания. А ради этого тоже стоит поспешить." } } }, t = { d = 9.7, v = "nightelf-female#53", n = { x = 0 }, c = { x = { { 0.00, "Когда вы помогаете Эралии принять мазь, её дыхание быстро успокаивается." }, { 5.07, "Возможно, она не выживет, но сейчас ей относительно спокойно." } } } } },
    [99079] = { d = 40.7, v = "tauren-male", n = { x = 413 }, c = { x = { { 0.00, "Дальноходы – самые надёжные разведчики нашего народа." }, { 4.18, "Они верны верховному вождю и только ему, но порой юный Бейн тоже прибегает к их помощи." }, { 11.48, "Это как раз такой случай. Дальноход Мала отправилась к нашим восточным границам." }, { 17.69, "Она так и не вернулась прошлой ночью, а прошло уже три дня." }, { 22.24, "Когда такое случается, мы должны сделать всё, чтобы помочь разведчику." }, { 28.14, "Нельзя, чтобы наша деревня подверглась угрозе. Покажи себя и найди Малу." }, { 33.90, "Ты узнаешь её по повязке на голове и посоху с перьями – такие есть у всех дальноходов." } } }, t = { d = 8.6, v = "tauren-female", n = { x = 82 }, c = { x = { { 0.00, "Совершенно очевидно, что смерть Малы была насильственной: из её спины и земли вокруг торчат стрелы." } } } } },
    [99081] = { d = 27.2, v = "tauren-female", n = { x = 260 }, c = { x = { { 0.00, "Вы ищете взглядом место, откуда могли прилететь стрелы: кентавры разбили новый лагерь." }, { 7.86, "В нём кипит бурная деятельность – похоже, в Мулгор проник небольшой отряд налётчиков." }, { 15.05, "Убитый дальноход всё ещё сжимает в руке отчёт о происходящем." }, { 19.95, "Храбрец Вольный Охотник должен узнать, что случилось с Малой – и кто именно её убил." } } }, t = { d = 4.6, v = "tauren-male", n = { x = 45 }, c = { x = { { 0.00, "Ужасные новости. Надо немедленно предупредить Бейна!" } } } } },
    [99082] = { d = 50.6, v = "tauren-male#67", n = { x = 426 }, c = { x = { { 0.00, "Твоя отвага и готовность защищать свой народ достойны похвалы." }, { 6.13, "Отправляйся на северо-запад в Громовой Утёс, могучий город тауренов, укрывающий нас тенью в жаркие дни. Попроси аудиенции у моего отца." }, { 19.47, "Это он объединился с новоиспечённым вождём Траллом и отвоевал эти равнины, навсегда изгнав кентавров." }, { 29.35, "Благодаря твоим действиям сегодня его подвиг не оказался напрасным. Как верховный вождь, он щедро наградит тебя за труды." }, { 41.60, "Чтобы попасть к верховному вождю, поднимись на подъёмнике и пройди к центральному уступу." } } }, t = { d = 22.0, g = 1, v = "named/3057", n = { m = 248, f = 250 }, c = { m = { { 0.00, "Кентавры Галак посмели показаться в Мулгоре?!" }, { 3.80, "Изгнав их, ты принёс гордость своим предкам. Быть может, это напомнит им о боли, что ждёт их, если они осмелятся вернуться!" }, { 12.39, "Прими этот дар в честь твоего подвига." }, { 15.01, "Пусть послужит тебе, когда ты отправишься в царство Матери-Земли, в самые дальние уголки этого мира." } }, f = { { 0.00, "Кентавры Галак посмели показаться в Мулгоре?!" }, { 3.80, "Изгнав их, ты принесла гордость своим предкам. Быть может, это напомнит им о боли, что ждёт их, если они осмелятся вернуться!" }, { 12.50, "Прими этот дар в честь твоего подвига." }, { 15.12, "Пусть послужит тебе, когда ты отправишься в царство Матери-Земли, в самые дальние уголки этого мира." } } } } },
    [99101] = { d = 17.9, v = "tauren-male", n = { x = 152 }, c = { x = { { 0.00, "Бейн Кровавое Копыто – предводитель нашей деревни. Он должен узнать о вторжении как можно скорее." }, { 9.33, "Отыщи его в центре и передай отчёт дальнохода Малы." }, { 13.66, "И не медли. Нам нельзя терять времени!" } } }, t = { d = 11.6, g = 1, v = "tauren-male#67", n = { m = 48, f = 49 }, c = { m = { { 0.00, "Бейн листает отчёт, мрачнея с каждой секундой." }, { 4.97, "Мы этого так не оставим. Спасибо, что передал это мне, Пророк." } }, f = { { 0.00, "Бейн листает отчёт, мрачнея с каждой секундой." }, { 4.97, "Мы этого так не оставим. Спасибо, что передала это мне, Пророк." } } } } },
    [99108] = { d = 40.7, g = 1, v = "tauren-male", n = { x = 345 }, c = { m = { { 0.00, "Приветствую, юный герой. Ты не воин, и я не могу научить тебя этому пути, но это не значит, что мои уроки тебе не пригодятся." }, { 11.87, "Перед тобой арена. Здесь неважно, кого ты зовёшь матерью и чем сражаешься – мечом или луком." }, { 20.51, "Здесь все равны, и все учатся точить рога в открытом бою." }, { 26.20, "Войдёшь ли ты в наш круг, чтобы познать наши обычаи на себе?" }, { 30.96, "Можешь сразиться с любым из этих новичков или с любым другим противником, кто согласится. Мне всё равно, с кем." } }, f = { { 0.00, "Приветствую, юный героиня. Ты не воин, и я не могу научить тебя этому пути, но это не значит, что мои уроки тебе не пригодятся." }, { 11.22, "Перед тобой арена. Здесь неважно, кого ты зовёшь матерью и чем сражаешься – мечом или луком." }, { 19.86, "Здесь все равны, и все учатся точить рога в открытом бою." }, { 25.55, "Войдёшь ли ты в наш круг, чтобы познать наши обычаи на себе?" }, { 30.31, "Можешь сразиться с любым из этих новичков или с любым другим противником, кто согласится. Мне всё равно, с кем." } } }, t = { d = 14.0, g = 1, v = "tauren-male", n = { x = 129 }, c = { m = { { 0.00, "Твоё умение делает мне честь, герой. Быть может, у нового поколения ещё есть надежда." }, { 7.09, "Возьми это, чтобы залечить раны, ведь в этом суровом мире тебя ждёт ещё много битв." } }, f = { { 0.00, "Твоё умение делает мне честь, героиня. Быть может, у нового поколения ещё есть надежда." }, { 6.98, "Возьми это, чтобы залечить раны, ведь в этом суровом мире тебя ждёт ещё много битв." } } } } },
    [99123] = { d = 13.2, v = "troll-female#75", n = { x = 155 }, c = { x = { { 0.00, "Я решила сама немного разведать утёс." }, { 2.60, "К несчастью, магия иссякла в самый неподходящий момент, и с тех пор мне приходится здесь прятаться." }, { 9.45, "Если поможешь мне выбраться, буду очень благодарна." } } }, t = { d = 17.4, g = 1, v = "troll-male", n = { m = 157, f = 159 }, c = { m = { { 0.00, "А, Пал'джу снова попала в беду, да?" }, { 3.26, "Надеюсь, на этот раз она усвоит урок и не будет ходить в одиночку. Спасибо, что помог ей." }, { 10.44, "Она многообещающая охотница, просто ведёт себя скорее как ящер, чем как тигр." } }, f = { { 0.00, "А, Пал'джу снова попала в беду, да?" }, { 3.26, "Надеюсь, на этот раз она усвоит урок и не будет ходить в одиночку. Спасибо, что помогла ей." }, { 10.73, "Она многообещающая охотница, просто ведёт себя скорее как ящер, чем как тигр." } } } } },
    [99127] = { d = 19.5, v = "human-male", n = { x = 215 }, c = { x = { { 0.00, "Рыба сегодня не клюёт, и вообще с ней творится что-то неладное." }, { 4.44, "Дело не только в пустых крючках – я вообще ни одной рыбёшки в воде не видел." }, { 9.90, "Ли оставил на ночь ловушки, пойди, что ли, посмотри, попалось хоть что-то или нет." }, { 15.58, "А если заметишь нечто странное, принеси посмотреть." } } }, t = { d = 10.6, v = "human-male", n = { x = 118 }, c = { x = { { 0.00, "И что, все сети в таком состоянии? Похоже, наши новые соседи-вредители натворили больше бед, чем мы думали." }, { 7.27, "Если с этим ничего не сделать, я разорюсь." } } } } },
    [99128] = { d = 16.2, v = "human-male", n = { x = 179 }, c = { x = { { 0.00, "Это наверняка дело рук тех мурлоков с другого берега озера. Мерзкие мелкие твари – нрав злобный, зубы острющие." }, { 7.97, "Если так пойдёт и дальше, во всём озере рыбы не останется. Сократи слегка их поголовье, а? Ты мне очень поможешь." } } }, t = { d = 12.0, v = "human-male", n = { x = 135 }, c = { x = { { 0.00, "Я их бульканье отсюда слышу, оно мне теперь в кошмарах являться будет. В любом случае, это должно поумерить их пыл..." }, { 7.95, "хотя не сомневаюсь, что они быстро восполнят потери." } } } } },
    [99129] = { d = 15.1, v = "human-male", n = { x = 164 }, c = { x = { { 0.00, "Реми на днях что-то говорил о мурлоках... Уверен, он ненавидит этих мелких паразитов не меньше моего." }, { 7.30, "Может, у него есть идеи, как отвадить их от моей рыбы. Сходи, поговори с ним и узнай, что он может предложить." } } }, t = { d = 13.4, v = "human-male", n = { x = 149 }, c = { x = { { 0.00, "А я говорил стражникам об этих мурлоках, да разве кто послушал?" }, { 4.73, "У меня есть пара идей, как поквитаться с этими тварями. Но тут понадобится твоя помощь, чтобы раздобыть всё необходимое." } } } } },
    [99130] = { d = 28.1, v = "human-male", n = { x = 319 }, c = { x = { { 0.00, "У меня есть пара идей, как разобраться с мурлоками. И одна из них заодно поможет ещё кое-кому." }, { 6.93, "В здешних усадьбах часто растёт сорняк под названием закатнолист; в больших количествах его лепестки ядовиты для большинства животных." }, { 16.23, "Если сделать из него приманку для мурлоков, глядишь, эти твари наконец научатся держаться подальше." }, { 23.62, "Заодно и поля фермерам расчистишь. Одни плюсы... одни плюсы." } } }, t = { d = 10.3, v = "human-male", n = { x = 111 }, c = { x = { { 0.00, "Дай мне минутку..." }, { 1.60, "Приманка простенькая, но если ничей питомец до неё не доберётся, она безопасна. Только скажи Джейсону, чтобы сам её не ел." } } } } },
    [99131] = { d = 14.3, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Передай Матерсу, что приманку можно будет забрать уже сегодня. Я расскажу ему, как её применять." }, { 7.02, "Надеюсь, скоро он снова сможет начать торговать рыбой. А поголовье мурлоков в этом мире сократится." } } }, t = { d = 8.2, v = "human-male", n = { x = 91 }, c = { x = { { 0.00, "Отравленная приманка? Главное, чтобы рыба на неё не позарилась, а так должно сработать. Заберу её у Реми попозже." } } } } },
    [99134] = { d = 24.3, g = 1, v = "scourge-male", n = { m = 228, f = 229 }, c = { m = { { 0.00, "Ты не из стражей смерти, а значит, ещё не успел меня разочаровать." }, { 5.27, "В награду за отсутствие некомпетентности тебе выпадает честь наказать тех, кто проявил этот талант сверх всякой меры." }, { 14.43, "Живее – путник, кажется? – иначе я впишу твоё имя в свой список, и наградой будешь уже ты – для кого-то другого." } }, f = { { 0.00, "Ты не из стражей смерти, а значит, ещё не успела меня разочаровать." }, { 5.35, "В награду за отсутствие некомпетентности тебе выпадает честь наказать тех, кто проявил этот талант сверх всякой меры." }, { 14.50, "Живее – путница, кажется? – иначе я впишу твоё имя в свой список, и наградой будешь уже ты – для кого-то другого." } } }, t = { d = 15.6, g = 1, v = "scourge-male", n = { m = 160, f = 162 }, c = { m = { { 0.00, "В смерти нам доступно не так уж много радостей. К счастью, боль – главная из них." }, { 6.22, "Сегодня ты доставил мне удовольствие, а значит, порадовал и Тёмную Госпожу. Возможно, от тебя будет и дальнейшая польза." } }, f = { { 0.00, "В смерти нам доступно не так уж много радостей. К счастью, боль – главная из них." }, { 6.22, "Сегодня ты доставила мне удовольствие, а значит, порадовала и Тёмную Госпожу. Возможно, от тебя будет и дальнейшая польза." } } } } },
    [99141] = { d = 37.2, g = 1, v = "scourge-male", n = { x = 366 }, c = { m = { { 0.00, "Не заблуждайся, герой: Тёмная Госпожа требует безупречного исполнения своей воли. Как палач, я обязан за этим следить." }, { 10.01, "Несколько моих стражей смерти задерживают донесения. Стоит ли говорить, что моё терпение иссякло." }, { 17.27, "Добудь их донесения и принеси мне во имя Тёмной Госпожи." }, { 21.88, "Страж смерти Диллинджер стоит к западу отсюда, у кладбища. Страж смерти Кристоф несёт службу на заставе к востоку." }, { 31.87, "И проверь поганище Толстяка – он бродит на западе, у Тихого Омута." } }, f = { { 0.00, "Не заблуждайся, героиня: Тёмная Госпожа требует безупречного исполнения своей воли. Как палач, я обязан за этим следить." }, { 10.11, "Несколько моих стражей смерти задерживают донесения. Стоит ли говорить, что моё терпение иссякло." }, { 17.36, "Добудь их донесения и принеси мне во имя Тёмной Госпожи." }, { 21.98, "Страж смерти Диллинджер стоит к западу отсюда, у кладбища. Страж смерти Кристоф несёт службу на заставе к востоку." }, { 31.97, "И проверь поганище Толстяка – он бродит на западе, у Тихого Омута." } } }, t = { d = 15.9, g = 1, v = "scourge-male", n = { m = 165, f = 167 }, c = { m = { { 0.00, "Следовало догадаться, что поганище не способно написать ничего толкового. Пусть этот мой промах останется между нами." }, { 9.06, "Ты угодил мне, а значит, угодил и Тёмной Госпоже. Возможно, на тебя ещё есть надежда." } }, f = { { 0.00, "Следовало догадаться, что поганище не способно написать ничего толкового. Пусть этот мой промах останется между нами." }, { 9.06, "Ты угодила мне, а значит, угодила и Тёмной Госпоже. Возможно, на тебя ещё есть надежда." } } } } },
    [99142] = { d = 33.1, v = "named/10665", n = { x = 391 }, c = { x = { { 0.00, "Если направляешься на восток, к ферме Балнира, у меня найдётся для тебя ещё работа." }, { 5.63, "Хорошего помощника в наши дни так трудно найти – твоя встреча с Толстяком это прекрасно показала." }, { 12.31, "Добывая погибельник, я слегка изменяю его алхимическими средствами и снова высаживаю на той ферме, чтобы вырастить своё высшее творение." }, { 21.67, "Я называю его гробовником, и он станет предвестником моей великой судьбы." }, { 26.93, "Пока будешь там, приглядывай за Плетью. Похоже, их... тянет... к этому растению. Любопытно." } } }, t = { d = 18.0, g = 1, v = "named/10665", n = { m = 158, f = 159 }, c = { m = { { 0.00, "Поистине великолепно!" }, { 1.97, "Младший аптекарь Холланд осматривает растения." }, { 5.59, "Хм, я надеялся, что они созреют... поагрессивнее. И всё же прогресс есть прогресс!" }, { 11.22, "Из-за того, что ты сегодня сделал, погибнет великое множество народу. Можешь гордиться собой." } }, f = { { 0.00, "Поистине великолепно!" }, { 1.97, "Младший аптекарь Холланд осматривает растения." }, { 5.59, "Хм, я надеялся, что они созреют... поагрессивнее. И всё же прогресс есть прогресс!" }, { 11.22, "Из-за того, что ты сегодня сделала, погибнет великое множество народу. Можешь гордиться собой." } } } } },
    [99143] = { d = 14.3, v = "human-male", n = { x = 154 }, c = { x = { { 0.00, "Эти рыболюди ведь наверняка мыслят как настоящие рыбы, да? А значит, всё, что нравится им, понравится и рыбе!" }, { 7.94, "Порыскай в их хламе и принеси мне всё, что сгодится на наживку, а я в долгу не останусь." } } }, t = { d = 9.7, v = "human-male", n = { x = 104 }, c = { x = { { 0.00, "Занятная коллекция. Думаю, сойдёт!" }, { 2.90, "Вот кое-что из моих старых припасов. Пригодится любому, кто делает первые шаги в рыбной ловле." } } } } },
    [99144] = { d = 41.9, g = 1, v = "scourge-male", n = { m = 390, f = 390 }, c = { m = { { 0.00, "Да благословит тебя Свет за то, что ты меня нашёл." }, { 4.21, "Я шёл из крепости Бандариона, чтобы передать послание Шари Стилвелл в Брилле, когда меня схватили эти чудовища." }, { 12.47, "Они обращаются к Свету с такой ненавистью в сердце, что остатки моей крови вскипают." }, { 18.69, "Это противно всему, о чём я размышляю в медитациях... всему, что я стремлюсь защищать!" }, { 25.89, "Барет Камень Зари собирается с силами." }, { 29.17, "Я знаю, что многие до сих пор не доверяют таким, как я, но уверяю тебя, наши намерения чисты." }, { 36.79, "Если поможешь мне сбежать отсюда, я буду вечно тебе благодарен." } }, f = { { 0.00, "Да благословит тебя Свет за то, что ты меня нашла." }, { 3.93, "Я шёл из крепости Бандариона, чтобы передать послание Шари Стилвелл в Брилле, когда меня схватили эти чудовища." }, { 12.19, "Они обращаются к Свету с такой ненавистью в сердце, что остатки моей крови вскипают." }, { 18.40, "Это противно всему, о чём я размышляю в медитациях... всему, что я стремлюсь защищать!" }, { 25.61, "Барет Камень Зари собирается с силами." }, { 28.89, "Я знаю, что многие до сих пор не доверяют таким, как я, но уверяю тебя, наши намерения чисты." }, { 36.51, "Если поможешь мне сбежать отсюда, я буду вечно тебе благодарен." } } }, t = { d = 35.6, v = "scourge-female#80", n = { x = 318 }, c = { x = { { 0.00, "Благослови тебя Свет за помощь Камню Зари." }, { 3.78, "Наш орден ещё только пускает здесь корни, и потерять столь многообещающего брата раньше срока было бы страшным ударом." }, { 16.27, "Прошу, прими это в знак нашей благодарности." }, { 20.06, "Если когда-нибудь заинтересуешься нашим учением – наш монастырь, крепость Бандариона, стоит на утёсах к северо-западу от фермы Соллидена." }, { 31.66, "Мы рады всем, кто ищет наставления в Свете." } } } } },
    [99152] = { d = 46.3, v = "scourge-female#80", n = { x = 397 }, c = { x = { { 0.00, "Запятнанные в Тенедоле к юго-западу – та ещё проблема, но нельзя допустить, чтобы подвалы под городом загнили и превратились в полноценный плацдарм Плети против крепости Бандариона." }, { 18.75, "Мне нужно подтянуть этих новобранцев на случай, если такое случится. А вот тебя ждёт то, что я называю ускоренным курсом." }, { 29.65, "Спустись под Тенедол и добудь немного их мерзких костей, чтобы мы могли изучить их получше." }, { 37.67, "Мне нужны те, в которых ещё осталась магия изначального воскрешения, – то есть светящиеся." } } }, t = { d = 13.1, v = "scourge-female#80", n = { x = 116 }, c = { x = { { 0.00, "Молодец, новобранец. Глядишь, из тебя ещё выйдет толк." }, { 5.20, "С этими костями мы, возможно, поймём, как такая угроза так долго оставалась незамеченной." } } } } },
    [99153] = { d = 32.8, g = 1, v = "scourge-male#83", n = { m = 331, f = 332 }, c = { m = { { 0.00, "Эй, ты! Слухи в наших рядах разлетаются быстро. Я слышал, как ты разобрался с культистами у останков поля битвы с Наксрамасом." }, { 9.62, "Беда в том, что один из этих культистов удрал с куском фокусирующего кристалла. В нём, похоже, ещё осталась сила." }, { 17.88, "Скорее всего, он где-то под Тенедолом. Он либо поднимает мертвецов, либо делает их сильнее, и ни то ни другое нам не нужно." }, { 27.47, "Найди этот кристалл, пока всё не вышло из-под контроля." } }, f = { { 0.00, "Эй, ты! Слухи в наших рядах разлетаются быстро. Я слышал, как ты разобралась с культистами у останков поля битвы с Наксрамасом." }, { 10.40, "Беда в том, что один из этих культистов удрал с куском фокусирующего кристалла. В нём, похоже, ещё осталась сила." }, { 18.66, "Скорее всего, он где-то под Тенедолом. Он либо поднимает мертвецов, либо делает их сильнее, и ни то ни другое нам не нужно." }, { 28.24, "Найди этот кристалл, пока всё не вышло из-под контроля." } } }, t = { d = 4.5, v = "scourge-male#83", n = { x = 43 }, c = { x = { { 0.00, "Отлично – и быстро к тому же! А теперь моя любимая часть..." } } } } },
    [99156] = { d = 42.8, g = 1, v = "scourge-female", n = { m = 372, f = 374 }, c = { m = { { 0.00, "Проклятье! Пока ты был в патруле, пришло новое донесение." }, { 5.68, "В восточной части Тирисфальских лесов, у Долины ядовитых пауков, видели бродячее поганище." }, { 14.32, "Что-то тут не так. Поганища не проскальзывают через Бастион незамеченными." }, { 21.43, "Держи это дело в строжайшей тайне. При этом такая тварь легко не падёт – тебе понадобятся союзники, если не хочешь стать её следующим обедом." }, { 34.35, "Доведи дело до конца, и будешь щедро вознаграждён. В доказательство принеси мне её сердце." } }, f = { { 0.00, "Проклятье! Пока ты была в патруле, пришло новое донесение." }, { 5.26, "В восточной части Тирисфальских лесов, у Долины ядовитых пауков, видели бродячее поганище." }, { 13.90, "Что-то тут не так. Поганища не проскальзывают через Бастион незамеченными." }, { 21.01, "Держи это дело в строжайшей тайне. При этом такая тварь легко не падёт – тебе понадобятся союзники, если не хочешь стать её следующим обедом." }, { 33.90, "Доведи дело до конца, и будешь щедро вознаграждена. В доказательство принеси мне её сердце." } } }, t = { d = 17.5, v = "scourge-female", n = { x = 153 }, c = { x = { { 0.00, "Ты – живое свидетельство хитрости и слаженности, которыми обладают все Отрёкшиеся и которых никогда не будет у безмозглой Плети." }, { 11.74, "Прошу, прими это в благодарность за труды, как я и обещала." } } } } },
    [99158] = { d = 29.8, v = "dwarf-male", n = { x = 347 }, c = { x = { { 0.00, "В горах живёт один священник из организации под названием Серебряный Рассвет." }, { 5.26, "Это святой орден, который ищет и уничтожает всё нечестивое и противоестественное." }, { 11.37, "Но отец Гавин – он скорее из тех, кто стремится всем помочь и всех исцелить, а не хвататься за оружие." }, { 18.26, "Он привёл в порядок старое здание, чтобы путники могли там отдохнуть. У меня есть для него партия освящённых свечей." }, { 26.29, "Не отнесёшь их ему, если будешь проходить мимо?" } } }, t = { d = 11.6, v = "human-male", n = { x = 126 }, c = { x = { { 0.00, "А, свечи из Стальгорна." }, { 2.07, "Хотя в своей обители я почти ни в чём не нуждаюсь, есть несколько важных вещей, за которые я благодарен городу и благочестивым людям." } } } } },
    [99159] = { d = 14.5, v = "human-male", n = { x = 160 }, c = { x = { { 0.00, "Мой очаг открыт, чтобы согреть любую душу, но я хотел бы попросить тебя о помощи, если сможешь." }, { 6.89, "Мне просто нужно больше дров. Обычно я занимаюсь этим сам, но в последнее время был занят другими делами." } } }, t = { d = 11.6, v = "human-male", n = { x = 120 }, c = { x = { { 0.00, "А, отлично. Эти подойдут – те, что пока слишком сырые, я оставлю сохнуть." }, { 5.41, "А теперь, если хочешь, у меня есть и другие дела, с которыми мне пригодится помощь." } } } } },
    [99160] = { d = 24.4, g = 1, v = "human-male", n = { m = 272, f = 273 }, c = { m = { { 0.00, "Ты, наверное, заметил элементалей поблизости." }, { 3.16, "Несколько дней назад с горных вершин обрушился пласт камня и льда, и это их взбудоражило." }, { 10.26, "Эти промёрзшие горы и без того опасны для обычного дворфа или человека, даже когда стихии не обретают плоть." }, { 17.84, "Я уже не гожусь для сражений, так что каждый убитый тобой дух сделает дорогу безопаснее." } }, f = { { 0.00, "Ты, наверное, заметила элементалей поблизости." }, { 3.09, "Несколько дней назад с горных вершин обрушился пласт камня и льда, и это их взбудоражило." }, { 10.18, "Эти промёрзшие горы и без того опасны для обычного дворфа или человека, даже когда стихии не обретают плоть." }, { 17.76, "Я уже не гожусь для сражений, так что каждый убитый тобой дух сделает дорогу безопаснее." } } }, t = { d = 9.3, v = "human-male", n = { x = 107 }, c = { x = { { 0.00, "Жаль, что их нельзя было просто усмирить." }, { 2.87, "К несчастью, это было выше моих познаний, а оставлять их без присмотра было слишком опасно." } } } } },
    [99161] = { d = 19.3, v = "human-male", n = { x = 215 }, c = { x = { { 0.00, "Я заметил, что первый элементаль, появившийся после обвала, был крупнее остальных." }, { 5.84, "И насколько я могу судить, именно он время от времени меняет погоду и вызывает небольшие обвалы." }, { 12.95, "Я зову его Авалой. Если убьёшь его и принесёшь ядро в доказательство, я тебя награжу." } } }, t = { d = 9.6, g = 1, v = "human-male", n = { x = 103 }, c = { m = { { 0.00, "Да благословит тебя Свет, герой. Благодаря тебе здесь стало намного безопаснее, и, надеюсь, это убережёт кого-то от напрасной смерти." } }, f = { { 0.00, "Да благословит тебя Свет, героиня. Благодаря тебе здесь стало намного безопаснее, и, надеюсь, это убережёт кого-то от напрасной смерти." } } } } },
    [99162] = { d = 28.7, v = "human-male", n = { x = 335 }, c = { x = { { 0.00, "Даже горным пехотинцам из Стальгорна приходится быть начеку, пробираясь через вершины Дун Морога." }, { 6.68, "Снегопады и обвалы нередко обрывают жизни менее опытных." }, { 11.11, "После обвала я обычно пытаюсь найти следы выживших или погибших – и молю Свет, чтобы ничего не нашлось." }, { 18.11, "Но раз стихии разбушевались, я не решаюсь уходить далеко." }, { 22.00, "Если поищешь пропавших горных пехотинцев и принесёшь мне их ружья, я верну их в Стальгорн." } } }, t = { d = 11.0, v = "human-male", n = { x = 127 }, c = { x = { { 0.00, "Горные пехотинцы вырезают свои имена на прикладах ружей. Так их можно опознать, если что-то случится." }, { 7.07, "Я отправлю ружья в Стальгорн – там их передадут родным." } } } } },
}
